-- VowLMS migration 038: 37 SAVVA career courses
-- Admin preview only. Courses remain draft until an administrator explicitly publishes them.
-- Requires migrations 001 and 018. Re-running is idempotent.
SET NAMES utf8mb4;
SET @academy_id := (SELECT id FROM academies WHERE slug = 'upskilling-academy' LIMIT 1);
START TRANSACTION;

-- Adobe After Effects
SELECT '548316f2bc2d7ea184c46fc23dac5160','adobe-after-effects',@academy_id,NULL,'Adobe After Effects','Create professional motion graphics, visual effects, compositing, and publication-ready media using Adobe After Effects.','Advanced','9 weeks',999.00,0,'draft'
WHERE @academy_id IS NOT NULL
ON DUPLICATE KEY UPDATE title=VALUES(title),description=VALUES(description),level=VALUES(level),duration=VALUES(duration),price=VALUES(price),is_free=0,status=IF(status='published','published','draft');

