INSERT INTO modules (id,slug,course_id,title,position) VALUES ('cc3fb9193f16749482307c8782e1f5f1','adobe-after-effects-module-0','548316f2bc2d7ea184c46fc23dac5160','Module 0: Introduction, Purpose, Objectives, Summary',0) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('83543f70cd902784b264297db5b0edd7','adobe-after-effects-m0-l1-module-0-intro','cc3fb9193f16749482307c8782e1f5f1','Module 0 Intro','text',12,'<h2>Module 0 Intro</h2><section><h3>Video Transcript</h3><p>The world of animation, visual effects, and motion graphics have grown tremendously over the last decade. Whether you are watching a superhero movie, an advertisement on TV, or even just a YouTube video, it is highly likely that you are looking at videos created and enhanced using Adobe After Effects—one of the most powerful and comprehensive creative video enhancement tools available today.</p><p>With After Effects, the only limit is your imagination: from creating fantastic animations, to applying cinematic transitions and effects, all the way to 3D design. Whether you are just a student who is interested in animation and visual effects, or if you want to pursue a career in motion graphics and videography, you can do it all using Adobe After Effects. This course prepares students for the Adobe After Effects Associate certification exam. Students can start with zero experience and learn how to navigate and work in After Effects. It will help them lay a strong foundation for pursuing a career in the world of visual effects and motion graphics.</p></section><section><h3>Adobe Effects Course Layout</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>Course Navigation</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>Course Objectives</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>Pligiarism Be Original</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>Syllabus</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>Syllabus Quiz</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('6684ef6c67ce0433775f6eac6e5da42c','adobe-after-effects-module-1','548316f2bc2d7ea184c46fc23dac5160','Module 1: Visual Effects and Motion Graphics 1',1) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1efb12921159d4a1acd6e54934b1c46e','adobe-after-effects-m1-l1-introduction-purpose-and-objectives','6684ef6c67ce0433775f6eac6e5da42c','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Video Transcript</h3><p>Hi, I’m Mr. Southwick and I’ll be one of your instructors for this course on Adobe After Effects. This is the intro video for Working in the Visual Effects and Motion Graphics Industry Part 1. You’ll see me introducing each module in this course, providing an overview of the topics you’ll cover in each one. Throughout the course, you’ll have a variety of ways to learn the material. There will be readings, videos, screenshot tutorials, images, gifs, and much more. But our ultimate goals are two-fold. First, so that you learn how to use After Effects. And second, so that you are best prepared to take (and pass!) the Adobe Certification exam on After Effects.</p><p>As with most things in life, we learn best by doing, and something like After Effects is no exception. So, as you are going through the course, I’d encourage you to have After Effects up and running on your computer. Follow along, try things for yourself, and experiment! It’s ok and even encouraged to make mistakes. One because that’s how we learn, and two, there’s always the ability to undo an action!</p><p>After Effects is a complex program and can be overwhelming for someone who is brand new to it. But we’ll be walking through it slowly, step by step, to get you comfortable with all the key features of this software. And occasionally in the course, I’ll take you through some screenshot tutorials of After Effects.</p><p>After Effects is an industry-standard software, used by everyone from beginners to professionals to create, enhance, and design high-quality animations and videos. Don’t let the fact that After Effects is used by professional designers and animators intimidate you! It is incredibly user-friendly, and with our detailed tutorials, you will be able to do everything from creating both simple 2D animations and 3D animations, applying various graphic and text effects into your videos, and creating cool motion graphics and cinematically composited videos!</p><p>In this module, you’ll get an insight into the visual effects and motion graphics industry and how After Effects fits into it. You’ll get an understanding of the real-world processes that take place in the design process, and the standards you need to have in place before you start using After Effects.</p><p>Legal and ethical considerations also come into the picture when you need to ask yourself questions like, “Is it okay for me to record in public?” or “Can I reuse sketches or animations from other sources like someone else’s videos or movies?” You’ll learn about all this and more in this introduction to the motion graphics industry!</p></section><section><h3>Module 1 Description</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>Module 1 Objectives</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>Module 1 Polling Questions</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
