INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('57a888f6aaa778db603843e106b02f61','adobe-after-effects-m3-l1-introduction-purpose-and-objectives','07c156736d41c60638ffa0f0b20f34a0','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Video Transcript</h3><p>Introduction Video Transcript</p><p>Hi, welcome back! After looking at some of the foundational elements of design, it’s finally time to open up After Effects! Let’s dive into this module on Project Setup and Interface.</p><p>In this module, you will get comfortable with some very important basics. You will learn how to set up a new project in After Effects and the various program settings available. Before you can actually use After Effects, you need to get familiar with all of the elements of the interface. It can be intimidating at first! In the interface, there are a half dozen different boxes or spaces where work takes place, top bars, dialogue boxes, and much more.</p><p>So, we’ll slowly introduce and walk through all the fantastic tools in the After Effects interface that you can use to transform your videos. And, as with any project, it is always important to stay organized, so we’ll show you how you can completely organize and customize your After Effects workspace. You can import and manage all of your assets, create sequences, and use various design tools that will help you manage your project workflow. Let’s take a look!</p></section><section><h3>Module 3 Description</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>Module 3 Objectives</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>Module 3 Polling Question</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('23ce91d5f0ecbdb5e65c81f61248c392','adobe-after-effects-m3-l2-lesson-1','07c156736d41c60638ffa0f0b20f34a0','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>New Projects in After Effects</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>Rendering and Effects</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>Lesson 1 Concept Check</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2b076da5c47897b26803d8dfb775bde3','adobe-after-effects-m3-l3-lesson-2','07c156736d41c60638ffa0f0b20f34a0','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Understanding Compositions</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>CompositionTranscript and Video Transcript</h3><p>Composition Flashcard Transcript</p><p>Frame rate:&#160;This refers to the number of frames per second in your composition. The standard frame rate for videos is 30 frames per second (fps), but you can choose a different frame rate depending on your needs.</p><p>Naming compositions:&#160;It&#39;s important to give your compositions descriptive names so that you can easily identify them later. You can rename a composition by double-clicking on its name in the Project panel.</p><p>Composition from footage:&#160;This is a quick way to create a new composition from a video or image file. Simply drag and drop the file onto the New Composition button in the Project panel.</p><p>Resolution:&#160;This refers to the number of pixels in your composition. The resolution is usually defined by the number of horizontal and vertical pixels, such as 1920x1080 pixels for full HD video. So, think about what type of video output you need - do you require a 4K video, a full HD video, or an SD video?</p><p>Duration:&#160;This refers to the length of your composition in seconds or frames. Always keep the duration of the video in mind when you edit. Many platforms may have set durations you need to meet. Also remember that the larger the duration of your video, the bigger your file size.</p><p>Dimensions:&#160;This refers to the physical size of your composition. It&#39;s usually defined by the width and height of your composition in pixels. This factor also comes to play when you are deciding where your video will be shared. For example, the dimensions of a video for a movie will be different from one that you will upload on YouTube, or even on other social media sites or apps.</p><p>Aspect ratio:&#160;This refers to the proportional relationship between the width and height of your composition. The most common aspect ratios are 16:9 and 4:3. You will see different aspect ratios being used depending on which medium the video will be shown. The videos you see on Instagram or TikTok are usually in a 16:9 aspect ratio as they are vertical videos, or 1:1 in the square videos. Most old TV shows used a 4:3 aspect ratio. And movies that you watch on the big screen usually use a much wider aspect ratio of 21:9 to create a cinematic experience.</p><p>Presets:&#160;These are pre-defined settings for creating compositions in After Effects. They can be useful for quickly creating a new composition with specific settings. We’ll learn more about these in the upcoming modules.</p><p>Background color:&#160;This is the color that appears behind your composition. The background color can affect the entire mood and feel of your video. You can change the background color by going to the Composition menu and selecting Background Color.</p><p>Creating Composition After Effect Video Transcript</p><p>Welcome to this video on Creating Compositions!</p><p>In this video, we&#39;ll talk about compositions in After Effects. Put simply, compositions are the documents that are created within the After Effects project. You can have multiple compositions in a single After Effects file or have multiple child compositions under a single parent composition. We&#39;ll cover the concepts of parent and child compositions later in this course.</p><p>Here, we have a blank project in After Effects. Let&#39;s create a composition by clicking the New Composition button here. Alternatively, you can create a composition from the main menu by clicking Composition and New Composition, or you can also press control + N to create a new composition. You will see the Composition Settings window. Here you can enter the specifications for your composition.</p><p>You can name your composition here - this name will be displayed in the project panel. There are a number of presets that you can use to choose the size of a composition. You can choose any of these presets based on your requirements. Just make sure that you use a size and frame rate according to the footage that you want to import here.</p><p>You also have the option of editing these presets. For example, let&#39;s choose HDTV at 25 FPS. If we want to use portrait mode instead of landscape mode, then we just need to turn off the lock aspect ratio here, and change these values here to make a portrait composition.</p><p>You can also customize the other settings based on what you need. For example, you can change the frame rate for your videos, based on what the project requires. You can also change the playback resolution based on what your computer can handle.</p><p>You can set the duration of the composition as well. You can see that this timecode has 4 components - the hour, minutes, seconds, and frames. You can also specify the background color of the composition based on your requirements. There are also other advance settings available, which we will revisit later. Once you are done with all the settings, click the OK button to create a composition.</p><p>You will see a new composition is created, and is also listed in the Project panel. Since we have not added any media or objects to the composition, it appears blank. You can edit your composition settings at any time from the Project panel as well. Just right-click the composition and choose composition settings to edit them.</p><p>Let&#39;s say I change the background color of my composition. You can easily duplicate your compositions in After Effects. Just choose the composition in the Project panel and press Ctrl + D or Cmd + D. You will see two compositions have been created. You can now customize each composition separately. You will see both the compositions are listed in the panels below.</p><p>So this is how you can create, edit, and use compositions in After Effects.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c92259fb3929672e0d950ba90a3e6c9f','adobe-after-effects-m3-l4-lesson-2-activity','07c156736d41c60638ffa0f0b20f34a0','Lesson 2 Activity','text',12,'<h2>Lesson 2 Activity</h2><section><h3>Lesson 2 Match Activity</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c59359b047f4e654786da1e34e1c5049','adobe-after-effects-m3-l5-lesson-3','07c156736d41c60638ffa0f0b20f34a0','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>After Effect Interface</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>After Effect Interface Image and Video Transcript</h3><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Screenshot of the After Effects workspace</p><p>The hotspot points on the image are as follows:</p><p>Application window and menu bar</p><p>This entire window is called the application window. It contains multiple&#160;panels&#160;that are arranged into spaces called&#160;workspaces. Panels can be grouped or standalone. You can easily customize the panels that appear in your workspace, and you can also save these configurations to create custom workspaces that you can use for different tasks. Across the top, you can access all the menus of your project from the&#160;Menu&#160;bar.</p><p>Toolbar or Tools panel</p><p>This panel contains various tools that you can use to work with layers, masks, shapes, and much more.</p><p>Composition panel</p><p>This displays the active composition and allows you to preview your work.</p><p>Project panel</p><p>This is where you will import and organize your files and compositions.</p><p>Effects &amp; Presets panel</p><p>This panel contains many different nested panels, including the Effects &amp; Presets panel, Preview panel, etc. You can use these panels for a variety of functions, such as adding effects and presets to your composition, previewing the composition, viewing information about the selected layer, etc. We&#39;ll go over each of these in detail in the coming lessons.</p><p>Timeline panel</p><p>This is where you&#39;ll arrange and animate your layers over time.</p><p>Layers panel</p><p>This displays the layers in your composition and allows you to adjust their properties.</p><p>After Effect Interface Video Transcript</p><p>Welcome to this video on the After Effects Interface!</p><p>In this video, I will give you a quick tour of the After Effects interface. This is the screen that you will see when you open the program - it is called the Home screen. From here, you can create a new project or open existing projects.</p><p>You can use this Home tab to access the most recently opened files. You will also see a Learn tab here if you are connected to the internet, that you can use to watch tutorials on the Adobe website. And if you are working with a team, you may have a Team project here that will allow you to invite others to the project, so you can work collaboratively with your team.</p><p>You can revisit the Start screen at any time by clicking this Home icon on the workspace Toolbar.</p><p>Let&#39;s first go over the interface. Here, you can see the main menu, from where you can access all the basic functions like creating a new project, open an existing project, saving a project, importing media or exporting media, and more.</p><p>Just below the main menu, you can see a toolbar that has many different tools like the selection tool, hand tool, zoom tool, etc. that you can use while working on your project.</p><p>On the left panel, you can see the Project panel where you will see all the project files. You can use this area to organize all your project files. It contains the compositions, Illustrator files, Photoshop files, etc. that you can import into your project.</p><p>In the middle, you can see the Composition panel where the video will be displayed.</p><p>On the right-hand side, you can see all the different panels that are nested here. You can expand or collapse any of these panels by just clicking the tab.</p><p>You can also see the Layers and Timeline panels at the bottom of this window. You can adjust the configuration of this workspace to suit your preferences by just clicking the different workspaces listed at the top here. For example, you can switch to the Small Screen workspace which gives you a large composition panel or you may choose the Library workspace that shows you the Library panel that you can use to access all of the different assets from the Adobe website.</p><p>You can use the Window menu to add many different panels to your workspace and customize it. For example, if you select the Align panel, this will add the Align panel to your current workspace.</p><p>You can also easily remove panels if you aren&#39;t using them. Just right-click the panel and choose Close Panel. You can also rearrange your panels on the workspace however you want them. Just drag a panel out to undock it and you can drop it onto any of the blue areas on the workspace to dock the panel again.</p><p>You can also undock the panel by right-clicking on the header and choosing to undock the panel. This will give you a floating panel that you can move anywhere on the workspace.</p><p>If you have made customizations like removing or moving panels, but now want to go back to the default interface, you can easily do that by resetting the workspace. Just click Window, Workspace, and click Reset Default to Saved Layout. This will reset the selected workspace to the default settings.</p><p>So, this was all about how you can navigate the interface of Adobe After Effects.</p></section><section><h3>Using Workspace Panel</h3><p>11101</p><p>Adobe After Effects</p><p>Project Setup and Interface - Lesson 3</p><p>Using Workspace Panels</p><p>Project Panel</p><p>The&#160;Project&#160;panel in Adobe After Effects is where you will manage and organize all of the assets that you will be using in your composition.&#160;This includes footage, images, audio, and other media files that you will be using in your project.</p><p>Here are some key features and functions of the Project panel:</p><p>Next Tab</p><p>Importing files</p><p>You can import files into the Project panel by selecting&#160;File &gt; Import&#160;from the Menu bar or using the shortcut Cmd+I (Mac) or Ctrl+I (Windows).</p><p>Viewing files</p><p>The Project panel displays a list of all the files that you have imported, along with basic information such as the file name, duration, and size.</p><p>Creating folders</p><p>You can organize your files into folders to keep your project organized and easy to navigate. To create a new folder, right-click on the Project panel and select&#160;New Folder.</p><p>Previewing files</p><p>You can preview files in the Project panel by selecting th<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0454a1ea853b21e39c0b7c4e172ac502','adobe-after-effects-m3-l6-lesson-3-activity','07c156736d41c60638ffa0f0b20f34a0','Lesson 3 Activity','text',12,'<h2>Lesson 3 Activity</h2><section><h3>Lesson 3 Activity</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('19401235dbf2c306799e3dee370e267c','adobe-after-effects-m3-l7-lesson-4','07c156736d41c60638ffa0f0b20f34a0','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Importing Assets</h3><p>Project Setup and Interface - Lesson 4</p><p>Importing Assets</p><p>In After Effects, you can import media from a variety of sources, including:</p><p>Flashcard Transcript</p><p>File import:&#160;You can import media files from your computer by selecting File &gt; Import &gt; File. This allows you to import a wide range of file types, including video, audio, images, and more.</p><p>Importing images as a sequence:&#160;If you have a sequence of images that you want to import as a video clip, you can select File &gt; Import &gt; File and select the first image in the sequence. Make sure that the Import As option is set to Footage and the Image Sequence box is checked.</p><p>Camera and microphone:&#160;If you have a camera and microphone connected to your computer, you can use After Effects to capture video and audio directly from your devices. To do this, select File &gt; New &gt; New Project and select the Camera and Microphone option.</p><p>Adobe Stock:&#160;After Effects also allows you to access Adobe Stock, a library of stock footage, images, and graphics. To access Adobe Stock, select File &gt; Adobe Stock.</p><p>Dynamic Link:&#160;If you arere working with other Adobe applications like Premiere Pro, you can use Dynamic Link to import media directly from those applications into After Effects. This allows you to easily switch between applications and make changes to your project in real time.</p><p>Welcome to this video on Importing Assets.</p><p>In this video, we&#39;ll see how you can import files in After Effects to create a composition. There are many ways in which you can import a file into After Effects. You can open the File menu, select Import and choose the file you want to import. You can also use the keyboard shortcut Ctrl+I or Cmd + I.</p><p>Alternatively, you can also double-click in the Project panel and choose the file that you want to import.</p><p>When you import a video, you have the option to either import it as footage or to create a composition. For now, let&#39;s import this video as footage.</p><p>You can see the imported video in the Project panel. Remember to keep your project panel organized. As you add more elements to your video, you will see many different types of files here, which can become complex in larger projects.</p><p>So to organize your projects, you can create a new folder to sort and manage your files. I&#39;m naming this folder Footage and dragging the video into this folder.</p><p>As you learned earlier, your composition should be created based on the settings of the footage you are using. For example, if you select this video, you can see the resolution and frame rate of this video. So, you can just right-click the video and click New Composition (or Comp) From Selection. This will create a composition with the exact settings as the video. You can also click and drag the video onto this icon in the Project panel. You can scroll the timeline to view your video. And you can also see that a composition file has been created in the Project panel. Let&#39;s organize the project and create a Comps folder to hold all the compositions. Just drag and drop your composition into this folder.</p><p>And this is how you can import videos and create a composition in After Effects.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f2ae14ec372e8fee6ab12a801df9d459','adobe-after-effects-m3-l8-lesson-5','07c156736d41c60638ffa0f0b20f34a0','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Managing Assets and Footage</h3><p>Managing Assets and Footage</p><p>Managing assets and footage in an After Effects project is important to keep your project organized and make it easier to work on.&#160;Here are some tips for managing assets and footage in an After Effects project:</p><p>Organize your files</p><p>Before you start working on your project, organize your files in a folder structure that makes sense to you. This can include subfolders for different types of files, such as footage, images, and audio files.</p><p>Import your assets</p><p>To bring assets into After Effects, go to the&#160;File&#160;menu and select&#160;Import. Select the file or folder that contains your assets and click&#160;Open. After Effects will import the files and create a new folder in the Project panel.</p><p>Rename and organize your assets in the Project panel</p><p>Once your assets are imported, you can rename them and organize them in the Project panel. You can create folders and subfolders to group related assets together, and you can rename files to make them easier to identify.</p><p>Use the Search bar</p><p>If you have a large number of assets in your project, you can use the search bar in the Project panel to quickly find what you&#39;re looking for. Simply type in a keyword or part of a filename to narrow down the results.</p><p>Use markers</p><p>Markers can be used to indicate important points or sections within a composition. You can use markers to mark specific points in time within a composition, to organize your composition, to collaborate with others on a project, and to help you when exporting your composition.</p><p>Finding and replacing media files</p><p>You can easily replace a media file by selecting it in the Project panel and choosing&#160;File&#160;&gt;&#160;Replace Footage. This is useful if you need to update a file that has been modified outside of After Effects.</p><p>Reloading linked media files</p><p>If a media file becomes disconnected or missing, you can use the Replace Footage command to locate the file and reconnect it to the project.</p><p>Interpreting footage</p><p>You can interpret footage to change its frame rate, pixel aspect ratio, and more. To do this, select the footage in the Project panel and choose&#160;Interpret Footage&#160;&gt;&#160;Main.</p><p>Organizing assets using folders and placeholders</p><p>You can organize assets in the Project panel by creating folders and subfolders to group related files together. You can also create placeholders for media that hasn&#39;t been added yet to help organize your project.</p><p>Adding metadata to assets</p><p>You can add metadata to assets in the Project panel to help you keep track of important information about each file. To do this, right-click on an asset and choose&#160;Edit Original&#160;to access the file&#39;s metadata.</p><p>By using these techniques, you can manage and organize your media files and assets in After Effects, making it easier to find, replace, and work with them in your projects.</p><p>UsefukKeytboard Shortcuts</p><p>As you get used to working on After Effects, keyboard shortcuts will become very useful when you want to quickly perform tasks.&#160;Here are some of the main keyboard shortcuts in After Effects:</p><p>Click each term to learn more.</p><p>Next Tab</p><p>General shortcuts</p><p>Ctrl + N&#160;(Windows) /&#160;Command + N&#160;(Mac) - Create new composition</p><p>Ctrl + Alt + N&#160;(Windows) /&#160;Command + Option + N&#160;(Mac) - Create new project</p><p>Ctrl + O&#160;(Windows) /&#160;Command + O&#160;(Mac) - Open project</p><p>Timeline shortcuts</p><p>Spacebar&#160;- Play / Pause</p><p>Ctrl + Home&#160;(Windows) /&#160;Command + Home&#160;(Mac) - Move playhead to the beginning of the composition</p><p>Ctrl + End&#160;(Windows) /&#160;Command + End&#160;(Mac) - Move playhead to the end of the composition</p><p>K&#160;- Move playhead to the next key in the timeline</p><p>J&#160;- Move playhead to the previous key in the timeline</p><p>Alt + Left Arrow&#160;(Windows) /&#160;Option + Left Arrow&#160;(Mac) - Move layer in timeline to the left</p><p>Alt + Right Arrow&#160;(Windows) /&#160;Option + Right Arrow&#160;(Mac) - Move layer in timeline to the right</p><p>View shortcuts</p><p>Z&#160;- Zoom tool</p><p>H&#160;- Hand tool</p><p>Ctrl + Alt + Left Arrow&#160;(Windows) /&#160;Command + Option + Left Arrow&#160;(Mac) - Zoom in</p><p>Ctrl + Alt + Right Arrow&#160;(Windows) /&#160;Command + Option + Right Arrow&#160;(Mac) - Zoom out</p><p>Layer shortcuts</p><p>Ctrl + D&#160;(Windows) /&#160;Command + D&#160;(Mac) - Duplicate selected layer(s)</p><p>Ctrl + Shift + D&#160;(Windows) /&#160;Command + Shift + D&#160;(Mac) - Split layer at the&#160;current time</p><p>Ctrl + Shift + C&#160;(Windows) /&#160;Command + Shift + C&#160;(Mac) - Pre-compose selected layers</p><p>These are just a few of the many keyboard shortcuts available in After Effects.&#160;You can view a complete list of keyboard shortcuts by going to the Help menu and selecting Keyboard Shortcuts.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7847e7ed5d96ad0c383f81ed19124262','adobe-after-effects-m3-l9-summary','07c156736d41c60638ffa0f0b20f34a0','Summary','text',12,'<h2>Summary</h2><section><h3>Module 3 Summary</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('668ea105aef1ab948dbb4d2b2f020eab','adobe-after-effects-m3-l10-quiz','07c156736d41c60638ffa0f0b20f34a0','Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Project Setup and Interface. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('12ab87906466240efc1eb45eebf1ca11','adobe-after-effects-module-4','548316f2bc2d7ea184c46fc23dac5160','Module 4: Organizing Projects',4) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('346db409e3d7b5dc21972d67eee2a92a','adobe-after-effects-m4-l1-introduction-purpose-and-objectives','12ab87906466240efc1eb45eebf1ca11','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Organizing Projects</h3><p>Organizing Projects - Introduction</p><p>Welcome back to this module on Organizing Projects! By now, you should have a good understanding of the basic design principles and project setup and interface options in After Effects. You should now be ready to dive deeper into organizing a project and learning how to start editing your videos. One of the most essential elements you will use for this is compositions! As you go through this module, we’ll give you some great tips and tricks on how to add different types of media files to your project to create compositions, manage the timelines of your compositions, manage multiple layers, and much more!</p><p>The best part is that you can explore how to use layers to add so many different elements to your video! You can create complex compositions and use masks and track mattes to create awesome effects. Don’t worry about getting everything perfect just yet, as editing is a process. (And learning about editing is a process too!) After Effects is highly flexible and forgiving software. It allows you to make mistakes and correct them as you go. You can lay out your videos and audio in different ways, cut and crop them, layer them, undo actions, and finally, preview them to see what works best.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('53680c6f8bd32cba008287fe7a5171a4','adobe-after-effects-m4-l2-lesson-1','12ab87906466240efc1eb45eebf1ca11','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Types of Layers</h3><p>Organizing Projects - Lesson 1</p><p>Types of Layers</p><p>In After Effects, you can add and arrange different elements to your compositions in different layers.&#160;Layering is a way of arranging different types of elements either one on top of the other or next to each other in a way that you can modify and manipulate each of these elements either separately or together with other elements.&#160;There are many different types of layers that can be added to a composition in the Timeline panel:</p><p>Video Layers:</p><p>These are layers that contain video footage or animations or image sequences, these are the raster elements of your composition as they are made up of pixels and their quality is dependent on the source files.</p><p>Audio Layers:</p><p>No video is quite complete without audio, is it?&#160;These are layers that contain audio files or sound effects.&#160;You can choose to layer these over your video layers, sync them, or fade them in or out.&#160;You can add as many audio layers as required for your project.</p><p>Text Layers:</p><p>These are layers that contain text, which can be customized using various text tools and effects.&#160;You can add multiple different types of fonts, and also add text in different languages.&#160;These layers are vector elements and can therefore be scaled easily without compromising the quality.</p><p>Adjustment Layers:</p><p>These are layers that do not contain any content themselves, but instead apply effects or adjustments to other layers in the composition.&#160;Adjustment layers are very useful when you want to apply effects to multiple layers at once.</p><p>Solid Layers:</p><p>These are layers that contain a solid color or pattern, which can be used as a background or for creating shapes and masks.&#160;These layers are vector elements and can be scaled easily without compromising the quality of your output.</p><p>Let’s say you are creating a video for an advertising campaign.&#160;You wish to add an animated title sequence for a video.&#160;You can add a Solid Layer which will serve as the backdrop for the text and other elements in the video.</p><p>Shape Layers:</p><p>These are layers that contain vector-based shapes that can be customized using various tools and effects.&#160;Shape layers can be used to create complex animations and motion graphics.</p><p>Null Layers:</p><p>These are layers that do not contain any content themselves, but instead act as a reference point or control layer for other layers in the composition.&#160;Null layers are useful for creating complex animations and rigging setups.</p><p>By recognizing the different types of layers in the Timeline panel, you can choose the right type of layer for your needs and effectively organize and manage your compositions.</p><p>Video Transcript: Lesson 1 Video 1</p><p>Welcome to this video on Layer Types Part 1!</p><p>In this video, we will look at the different types of layers in After Effects. As you know, there are many different types of layers in After Effects. In this project, I have many different types of layers, but all of them have some things in common.</p><p>For example, all layers have a duration that you can adjust. You will see each of these layers appears in the Timeline panel. You can adjust the “in” and “out” points for each layer in the timeline to adjust when it appears and when it finishes. If any footage is too long, you can crop it from either end by just dragging the in or out point on the timeline. However, if any footage is too short, you cannot make it longer without applying certain effects like Time Stretch or other effects.</p><p>Another thing all layers have in common are properties to transform them, such as their position and rotation. Most layers also have anchor point, scale, and opacity properties that can be adjusted.</p><p>Certain layers like the Camera and Spot Light will have special transform properties that are specific to the functions of that layer. For example, the Camera layer has zoom, depth of field, and other special properties.</p><p>You can apply effects to most layers, except for Camera and Light layers. If I open the Effects &amp; Presets panel and drag any effect onto these layers, you can see that it cannot be applied to the camera and light layers.</p><p>To see all the types of layers that are available in After Effects, just click the Layer menu button and select New. As you can see, the different layer types are text, solid, light, camera, null shapes, adjustment, as well as some advanced layers that we will not discuss right now.</p><p>Let&#39;s open a new composition and go over each of the different types of layers. Let&#39;s go to the Layer menu and select New and add a Text layer.</p><p>A text layer is exactly what it sounds like, it&#39;s a layer that controls and displays text. Once you add the text you want to add to your videos, you can manage the text, edit all the different fonts, colors, and orientation of the text, apply effects to the text, or animate it based on your requirements. Another way you can create text is to use the Text tool from the toolbar. Just select this tool and click anywhere to add text, and you will see that a new text layer is created.</p><p>You can then select the text layer and edit it using the Character panel and the Paragraph panel. Most of the settings in these panels should be familiar to you if you have used any other design software or even Word or PowerPoint.</p><p>In addition to the regular transform properties, the text layer has special text properties including Source text which can be keyframed. You can view the Animate menu to see the other text properties that you can add and modify.</p><p>Next, let&#39;s add a Solid layer. This is a simple color layer that you can use creatively in your projects. When you add a Solid layer, you can adjust many of these properties, including its size, aspect ratio, color, etc. This will basically generate a rectangular swatch of the color you select. You can modify this color and other settings at any time by opening the Solid settings window.</p><p>You can also add multiple Solid layers in a single composition and use them creatively. They are lightweight layers and are a great way to apply effects to your video. For example, you can use multiple solid layers like this and animate them or apply effects to create a cool transition. Solids layers do not have any special properties other t<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e85d5d5dc5e98f3e06aaffd1bdc32a08','adobe-after-effects-m4-l3-lesson-2','12ab87906466240efc1eb45eebf1ca11','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Working with Layers</h3><p>Working with Layers</p><p>The Timeline panel in After Effects is where you can manage the layers in your composition.&#160;It provides a visual representation of the layers in your project and allows you to control their timing, animation, and visibility.</p><p>Here are some ways you can use the Timeline panel to manage layers in After Effects:</p><p>Click each term to learn more.</p><p>Adjusting layer duration</p><p>Animating layers</p><p>Managing layer order</p><p>Controlling layer visibility</p><p>Locking and unlocking layers</p><p>Pre-composing layers</p><p>Flashcard TranscriptAdjusting layer duration:&#160;You can drag the layer&#39;s in-point and out-point markers in the Timeline panel to adjust its duration. This allows you to control when a layer appears and disappears in your composition.</p><p>Animating layers:&#160;You can create animations by adding keyframes to layer properties, such as position, scale, rotation, and opacity. Keyframes can be added and edited in the Timeline panel, allowing you to create complex animations over time.</p><p>Managing layer order:&#160;You can drag and drop layers in the Timeline panel to change their order. This can affect how layers are layered on top of each other and how they appear in the composition.</p><p>Controlling layer visibility:&#160;You can use the eye icon next to a layer in the Timeline panel to toggle its visibility on and off. This allows you to control which layers are visible at any given time</p><p>Locking and unlocking layers:&#160;You can use the lock icon next to a layer in the Timeline panel to lock or unlock its properties. This can be useful if you want to prevent accidental changes to a layer&#39;s properties.</p><p>Pre-composing layers:&#160;You can select one or more layers and pre-compose them into a new composition. This allows you to group layers together and apply effects to them as a single unit.</p><p>For instance, you are working on an animation movie.&#160;You can use After Effects to visually enhance the movie.&#160;After Effects allows you to create separate layers for each body part of the character.&#160;Using this, you can depict the character&#39;s movements and expressions.</p><p>Overall, the Timeline panel is an essential tool for managing layers in After Effects.&#160;By using it effectively, you can create complex animations and compositions with ease.</p><p>Welcome to this video on Working with Layers!</p><p>In this lesson, you will learn all about working with layers in After Effects. This concept should be familiar to you if you have used any other design software like Photoshop. All the elements that you add to your After Effects project appear on top of each other in layers. The layer that is at the top in the layers panel will appear on top of all the objects in the composition panel.</p><p>Let&#39;s take a closer look. Here, you can see that the Jack of hearts is above all the other elements in this layer. And if you check the 10 of hearts, it is placed below many other objects in the layers panel, and you can see this in the Composition panel as well.</p><p>If we move any of the objects in the layers panel to the top of the list, like the Ace of hearts for example, you will see that it appears on top of all the objects. As you can see, stacking the order of layers is essential to understand how you can make a complex and creative composition in after effects.</p><p>Now, let&#39;s look at layer durations. You can also customize for how long each composition appears on the screen. Currently, all of these layers will appear on the screen for the entirety of the composition. If you see the composition settings, you can see that this entire composition is 3 seconds long, during which all these objects are visible.</p><p>To change this, just select a point on the timeline where you want the object to start. Then, just drag the object on the timeline towards the playhead. It will snap to this position. If you drag the playhead, you will see that this object is only visible after this point.</p><p>Let&#39;s try this for another object as well. You can also do this using keyboard shortcuts. Just place the playhead where you want to start and press Alt + open bracket key ([). This will snap the layer to the playhead. You can also end layers at different points in the timeline. So to place the endpoint for this layer, just place the playhead where you want it to end on the timeline and then press the Alt + Close Bracket key (]). You can also use the drag option that we used. These shortcuts are very useful when you want to trim layers in After Effects.</p><p>Another set of useful shortcuts are the Undo and Redo shortcuts. Just press Ctrl + z on your keyboard to undo any changes, and press Shift + Ctrl + z to redo any changes.</p><p>Let&#39;s take a closer look at the Layers panel. You can see many different buttons here. Let&#39;s first look at the Lock layer option. You can lock layers so that they cannot be edited or moved by selecting this icon. This is useful when you are working with multiple layers and want to ensure you don’t accidentally move elements that you have placed in your composition. You can even click and drag down to lock multiple layers at once.</p><p>You also have the option to mute layers that contain audio using the audio key. Sometimes when you work with many layers, it is difficult to focus on a single layer with many other layers overlapping it. In this case, you can hide layers using this eye icon. If you want to hide all layers except a single selected layer, use the Solo key instead.</p><p>Another function you can use is Shy layers. After Effects projects can become very complex when you work on large videos, and the Layers panel can become very confusing because you have a lot of different layers in it. To make the workflow easier, you can use Shy layers. This setting is used when you want to hide certain layers from the layer stack. Just click the Shy icons next to these layers. Then, if you click the Shy icon at the top, these layers are automatically hidden. This is a really good technique to hide all the background elements that more or less remain constant while you work on the more active elements in the foreground of your video.</p><p>So this was an introduction to layers!</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('093a8209a5eecc434c6853c2b145ee41','adobe-after-effects-m4-l4-lesson-3','12ab87906466240efc1eb45eebf1ca11','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Pre-Composing in After Effects</h3><p>Pre-Composing in After Effects</p><p>Pre-composing in After Effects refers to the process of combining multiple layers into a single layer or composition.&#160;This can be useful for organizing and managing complex projects, as well as for applying effects and animations to multiple layers at once.</p><p>Here is how you can pre-compose layers in After Effects:</p><p>Select the layers you want to pre-compose in the timeline or composition panel.</p><p>Right-click on the selected layers and choose&#160;Pre-compose&#160;from the context menu.</p><p>In the&#160;Pre-compose&#160;dialog box, give the new composition a name and choose the settings you want to use, such as the composition size and duration.</p><p>Click&#160;OK&#160;to create the new composition.</p><p>After pre-composing layers, you can edit them as a single unit in the new composition.&#160;This can be useful for applying effects, animations, or adjustments to multiple layers at once.</p><p>To access the pre-composed composition, double-click on it in the timeline or composition panel.&#160;This will open the composition in a new tab, where you can make changes to its properties or add new layers.</p><p>Pre-composing can also be used to simplify the timeline and reduce the number of layers, making it easier to manage complex projects.&#160;It&#39;s important to note that pre-composing can affect the layer hierarchy and timing, so be sure to adjust the pre-compose composition&#39;s properties as needed to achieve the desired result.</p><p>&#187;</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6c80fa1a8c0988d95f874d076e2e3aee','adobe-after-effects-m4-l5-lesson-4','12ab87906466240efc1eb45eebf1ca11','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Adjusting Layer Visibility</h3><p>Adjusting Layer Visibility</p><p>In After Effects, you can adjust a layer&#39;s visibility to make it visible or invisible in the composition.&#160;This can be useful for organizing your project or for creating visual effects where layers need to appear or disappear at certain times.</p><p>Here&#39;s how to adjust a layer&#39;s visibility in After Effects:</p><p>Select the layer you want to adjust in the timeline panel.</p><p>Click on the&#160;Eye&#160;icon to the left of the layer name to toggle its visibility on or off.&#160;When the Eye icon is visible, the layer is visible in the composition.&#160;When the Eye icon is not visible, the layer is hidden from view.</p><p>If you want to adjust the visibility of multiple layers at once, select the layers you want to adjust by holding down the Shift key while clicking on each layer, and then click on the&#160;Eye&#160;icon for any of the selected layers.</p><p>You can also use the&#160;Toggle Switches/Modes&#160;button at the bottom of the timeline panel to quickly show or hide the visibility controls for all layers in the composition.</p><p>Adjusting a layer&#39;s visibility can be especially useful when working with complex compositions or animations, where you need to toggle the visibility of certain layers to preview the animation or to make adjustments to the composition.</p><p>In After Effects, the&#160;Solo, Shy,&#160;and&#160;Mute&#160;layer options can be used to control the visibility and audio of layers in your composition.</p><p>Click each term to learn more.</p><p>Next Tab</p><p>Solo</p><p>The Solo option allows you to isolate a single layer in the composition so that only that layer is visible.&#160;To enable Solo mode for a layer, click on the Solo button (represented by a small S) next to the layer name in the timeline panel.&#160;When a layer is in Solo mode, all other layers are hidden.</p><p>Shy</p><p>The Shy option allows you to hide layers that you don&#39;t need to see or work with. To enable Shy mode for a layer, click on the Shy button (represented by an eye icon with a line through it) next to the layer name in the timeline panel. When a layer is in Shy mode, it is hidden from view in the timeline panel and the composition panel.</p><p>Mute</p><p>The Mute option allows you to turn off the audio for a layer. To enable Mute mode for a layer, click on the Mute button (represented by a small speaker icon) next to the layer name in the timeline panel. When a layer is muted, its audio will not be played back in the composition.</p><p>These layer options can be especially useful when working with complex compositions that contain many layers.&#160;By using Solo mode, you can quickly isolate a single layer to focus on, without distractions from other layers.&#160;Shy mode can help you hide layers that you don&#39;t need to see or work with, making it easier to navigate your composition.&#160;And Mute mode can help you turn off audio for specific layers, which can be useful when working with sound effects or music tracks.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9312425091bb86ecd2ff98ae6f3e2326','adobe-after-effects-m4-l6-lesson-4-activity','12ab87906466240efc1eb45eebf1ca11','Lesson 4 Activity','text',12,'<h2>Lesson 4 Activity</h2><section><h3>Lesson 4 Activity</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4ce5c4a25b42654abf48820c0f040216','adobe-after-effects-m4-l7-lesson-5','12ab87906466240efc1eb45eebf1ca11','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Lesson 5</h3><p>Masking</p><p>In After Effects, masking is the process of using a layer mask to hide or reveal specific parts of a layer.&#160;Here are the steps to mask elements in After Effects:</p><p>Import your footage or image sequence into After Effects and create a new composition.</p><p>Create a new layer and place it above the layer you want to mask.</p><p>Add a layer mask to the new layer by selecting the layer and going to Layer &gt; Mask &gt; New Mask.</p><p>Use the Pen tool to draw a custom shape on the mask layer.&#160;The areas inside the shape will be visible, while the areas outside the shape will be hidden.</p><p>Adjust the mask properties in the timeline panel to refine the shape and position of the mask.</p><p>You can also use the Mask Feather property to soften the edges of the mask.</p><p>Once you&#39;ve created your mask, you can use it to selectively hide or reveal parts of the layer below it.&#160;For example, you can use a mask to isolate a person or object in a video clip and add special effects to just that element.&#160;You can also use multiple masks on a single layer to create more complex effects.&#160;By animating the mask properties over time, you can create custom transitions and visual effects.</p><p>In After Effects, the Masking property is a set of controls that allow you to adjust the settings of a layer mask.&#160;Here are some of the properties you can adjust:</p><p>Click each term to learn more.</p><p>Next Tab</p><p>Mask Path</p><p>This property controls the shape of the mask.&#160;You can use the Pen tool to draw a custom shape or use one of the built-in shapes like a rectangle or ellipse.</p><p>Mask Feather</p><p>This property controls the softness of the edges of the mask. A higher value will result in a softer edge, while a lower value will result in a sharper edge.</p><p>Mask Opacity</p><p>This property controls the transparency of the mask. A lower value will make the mask more transparent, while a higher value will make it more opaque.</p><p>Mask Expansion</p><p>This property controls the size of the mask. You can use it to expand or contract the mask shape.</p><p>Mask Offset</p><p>This property controls the position of the mask. You can use it to move the mask around within the layer.</p><p>By adjusting these properties, you can create complex mask shapes and control the way they interact with your footage.&#160;You can also animate these properties over time to create custom transitions and visual effects.&#160;The Masking property is an essential tool for compositing in After Effects, allowing you to isolate specific parts of your footage and apply effects to them selectively.</p><p>Let’s assume you are working on visually enhancing a short movie.&#160;In one of the scenes, there is a video of a woman standing on a busy street.&#160;You want to make it look like she is standing in front of the Statue of Liberty.&#160;You can easily do that using the masking feature in After Effects.&#160;First you will have to import the video clip of a woman standing on a busy street and the video clip of the Statue of Liberty into After Effects.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ddab65b44b6bc2a26d47e24b17b81477','adobe-after-effects-m4-l8-summary','12ab87906466240efc1eb45eebf1ca11','Summary','text',12,'<h2>Summary</h2><section><h3>Module 4 Summary</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('dc532cc551472151833b331ea6313b33','adobe-after-effects-m4-l9-quiz','12ab87906466240efc1eb45eebf1ca11','Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Organizing Projects. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('a42f30aa52d702d59218ab00a9d0fb52','adobe-after-effects-module-5','548316f2bc2d7ea184c46fc23dac5160','Module 5: Visual Elements Part 1',5) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('84f3b72d3a2538d3cccab7c0d55dba2a','adobe-after-effects-m5-l1-introduction-purpose-and-objectives','a42f30aa52d702d59218ab00a9d0fb52','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction</h3><p>Introduction</p><p>Hey there! Welcome back to this module on Creating and Modifying Visual Elements Part I. You’ve covered a lot of ground in your After Effects journey so far. You’ve learned some essential basics about the visual design industry, you’ve learned to navigate around the After Effects interface and set up a project, and you’ve also learned how to organize your assets and manage multiple layers in your composition.</p><p>In this module, we’ll look at another critical visual element in your videos – titles and text! Typography is a key aspect of your designs. You can use the comprehensive tools in After Effects to add and animate titles, text, and basic shapes to your video. Adobe gives you free access to thousands of beautiful fonts to choose from. And After Effects is packed with loads of preset text layouts, fun effects, and different text treatments and animations that you can apply to your projects. So let’s get started!</p><p>Module Description</p><p>In this module, students will learn how to add and animate titles, text and shapes in a video.&#160;They will learn how to use the various tools available in After Effects to transform various visual elements of their video compositions.&#160;Students will also learn how to animate text and adjust the layers in their composition using a variety of tools.</p><p>Objectives</p><p>In this module, students will:</p><p>Create visual elements using a variety of tools.</p><p>Place assets into a composition.</p><p>Create text in a composition.</p><p>Adjust paragraph settings.</p><p>Animate text.</p><p>Adjust layers using a variety of tools.</p><p>Transform visual elements in the composition.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('cc5594a0029866a5f878c35c4e4db48c','adobe-after-effects-m5-l2-lesson-1','a42f30aa52d702d59218ab00a9d0fb52','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Using the Pen tool to Add Shapes</h3><p>Using the Pen tool to Add Shapes</p><p>The Pen tool in After Effects is a powerful tool that allows you to perform a variety of tasks.&#160;You can create vector paths and use them for a variety of purposes, including creating masks, shape layers, and motion paths for animations.</p><p>To use the Pen tool, simply select it from the toolbar or press the G key on your keyboard.&#160;Once you have the Pen tool selected, you can click anywhere on the composition to create an anchor point.&#160;If you click and drag, you can create a curved path, which can be adjusted using the handles that appear on the anchor points.</p><p>To complete a path, you can either click on the starting anchor point or press the Command/Ctrl key to close the path.&#160;You can also use the Selection tool to move and adjust the position of anchor points and handles.</p><p>The Pen tool has several different modes that allow you to create and adjust paths in different ways.&#160;For example, the&#160;Add Vertex&#160;tool allows you to add new anchor points to an existing path, while the&#160;Delete Anchor Point&#160;tool allows you to remove existing anchor points.</p><p>In addition to creating masks and shapes, the Pen tool can also be used to create motion paths for animations.&#160;You can create a path using the Pen tool, then apply a motion path animation to a layer to make it follow the path.&#160;This can be useful for creating complex motion graphics and visual effects.</p><p>In After Effects, you can use the Pen tool to create and manipulate vector paths using several methods.&#160;To access these methods, click and hold down the Pen tool in the toolbar.&#160;This will show you a menu of different Pen tool options.</p><p>Here are some of the different Pen tool methods in After Effects:</p><p>Click each term to learn more.</p><p>Pen Tool</p><p>This is the standard Pen tool that allows you to create and modify paths using anchor points and handles.</p><p>Add Vertex Tool</p><p>This tool allows you to add new vertex points to an existing path. To use it, click on an existing path to add a new anchor point.</p><p>Delete Vertex Point Tool</p><p>This tool allows you to remove vertex points from a path. To use it, click on an anchor point to delete it.</p><p>Convert Vertex Tool</p><p>This tool allows you to convert a corner point into a smooth point or vice versa. To use it, select a vertex point and then click on the Convert Vertex tool.</p><p>Mask Feather Tool</p><p>This tool allows you to feather your vertex point, by using it you can make mask sharper or smoother.</p><p>Each of these Pen tool methods can be used to create and modify vector paths in different ways, making them useful for a variety of tasks in After Effects.</p><p>There are many creative ways in which you can incorporate text into your videos.&#160;Here are some examples:</p><p>Contrast:&#160;Always be mindful of the font color of the text you are using in relation to the colors in the video in the background.&#160;For example, if you are working on a video that was shot at night and you use black text, it will not be visible.&#160;Also, think of the duration for which the text is going to be visible on the screen and what changes are going on during that time in the video in the background.&#160;You can also use solid-colored shapes behind your text to make it stand out more.</p><p>Text Placement:&#160;Location is everything!&#160;Think of where you are placing the text - will you choose to center the text or put it in the lower third?&#160;Remember that anything that you display front and center in your video will indicate that it is important, so ideally, you should only center-align things like title text.&#160;Use safe margins to ensure that you are placing text within the safe bounds of the video.</p><p>Fonts and Typography:&#160;There is a whole world of fonts that you can choose from.&#160;Adobe has a large library of fonts that are available for use, and you can also choose to download customized fonts from various online sources.&#160;You can combine different types of fonts for a more stylish approach.&#160;However, as a rule, avoid using more than three different types of fonts at a time.&#160;You can experiment with different font colors, styles, opacity, and other characteristics like spacing and boldness.&#160;Whichever approach you choose, it is important to keep your fonts consistent throughout your video as well.</p><p>Be Mindful of Tone:&#160;If you are creating a video of a birthday celebration, you wouldn’t use sad background music, right?&#160;Similarly, the type of font you use should also match the tone of the video.&#160;For example, if you see Comic Sans font being used in news reporting, you wouldn’t be able to take them seriously!&#160;Adjust the type of font you use based on the tone you are going for in your video.&#160;For example, Sans Serif fonts usually look more modern than Serif fonts and can have different applications.</p><p>Creativity:&#160;Finally, don’t be afraid to explore various creative ways to use fonts in your videos.&#160;For example, you can use masking to incorporate text into your video by making it look like the video is playing in the letters of the font over a solid background.&#160;You can animate your font and synchronize it with the audio or movements in the video.</p></section><section><h3>Shape Layers</h3><p>Shape Layers</p><p>Watch the following video, which goes through the importance and use of Shape Layers.</p><p>Welcome to this video on Shape layers!</p><p>In this video, we will talk about shape layers in After Effects. Shape layers are the backbone of motion graphics and 2D animation in After Effects. I will be walking you through some major features of shape layers that will help you when you work with motion graphics.</p><p>First, shape layers are vector graphics. This means that these layers are made with mathematical calculations; they are not raster graphics. In a practical sense, this means that you can infinitely scale shape layers up or down without losing any details or clarity in your media file.</p><p>Next, let&#39;s talk about the three basic components of shape layers. The path, fill, and stroke. These attributes are organized into groups in a shape layer. A shape layer can contain one or more shape groups in the Contents section of the layer. This means that a single shape layer in the timeline can represent <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('da20518cdb5a3649f9ccef1db22f2055','adobe-after-effects-m5-l3-lesson-2','a42f30aa52d702d59218ab00a9d0fb52','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Placing Assets into a Composition</h3><p>Placing Assets into a Composition</p><p>Once you place assets into your composition in After Effects, you can make modifications to its position on the timeline as well as its coordinates.</p><p>Temporal Position</p><p>In After Effects, the temporal position of a layer refers to its position on the timeline, which determines when it appears in the composition.&#160;You can adjust the temporal position of a layer by moving its keyframes or by dragging the layer in the timeline.</p><p>To move keyframes, select the layer and then select the keyframe(s) you want to move on the timeline.&#160;You can then drag the selected keyframes to a new position in time to change the layer&#39;s temporal position.</p><p>Alternatively, you can drag the layer itself in the timeline to change its position.&#160;This will move all of the keyframes associated with the layer to the new position in time.&#160;You can also use the keyboard shortcut Option/Alt and the left or right arrow keys to move the selected layer by one frame in either direction.</p><p>The temporal position of a layer can also be adjusted by changing the duration of the layer.&#160;This can be done by trimming the in or out points of the layer, or by stretching or compressing the layer in time.&#160;These adjustments can be made using the tools in the timeline, or by using keyboard shortcuts.</p><p>Spatial Position</p><p>In After Effects, the spatial position of a layer refers to its location in the composition window.&#160;The position is defined by X, Y, and Z coordinates that determine where the layer is placed on the screen.</p><p>To view and edit the spatial position of a layer, select the layer in the timeline and look for the &quot;Position&quot; property under the &quot;Transform&quot; category.&#160;The X and Y values determine the horizontal and vertical position of the layer, respectively, and the Z value determines its depth in 3D space.</p><p>You can adjust the spatial position of a layer by either entering the values manually in the &quot;Position&quot; property or by using the selection tool to drag the layer to the desired location in the composition window.&#160;Additionally, you can use the arrow keys on your keyboard to move the selected layer in small increments or hold down the Shift key while dragging the layer to constrain its movement to a straight line or to move it in larger increments.</p><p>Stacking Order of Layers</p><p>In After Effects, the stacking order of layers determines which layers appear in front of or behind other layers in the composition.&#160;This order is controlled by the layer panel, where the topmost layer appears in front of all the other layers, and the bottom most layer appears behind all the other layers.</p><p>You can change the stacking order of layers by simply dragging and dropping them in the layer panel.&#160;When you move a layer up or down in the panel, you are changing its position in the stacking order.&#160;The layers that are higher in the panel will appear in front of the layers that are lower.</p><p>You can also use the keyboard shortcuts Command/Ctrl + [ to move a layer down in the stacking order and Command/Ctrl +] to move a layer up.</p><p>In addition to the layer panel, you can also control the stacking order of layers using blend modes and track mattes.&#160;Blend modes allow you to control how the layers blend together and can affect the layer&#39;s appearance and position in the stacking order.&#160;Track mattes allow you to use the transparency of one layer to determine the visibility of another layer, which can also affect the stacking order.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4d9b346052c1ec790f1097457e302ada','adobe-after-effects-m5-l4-lesson-3','a42f30aa52d702d59218ab00a9d0fb52','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Create and Manipulate Text in a Composition</h3><p>Create and Manipulate Text in a Composition</p><p>The Text Layer in After Effects is a type of layer that allows you to create and animate text.&#160;You can use the Text Layer to add titles, captions, credits, and other types of text to your compositions.</p><p>To create a Text Layer, follow these steps:</p><p>Select the&#160;Layer&#160;menu in the top menu bar and choose&#160;New&#160;&gt;&#160;Text.</p><p>In the&#160;Composition&#160;panel, click and drag to create a rectangular area for your text.</p><p>Type your text in the box that appears and use the&#160;Character&#160;and&#160;Paragraph&#160;panels to customize the font, size, color, alignment, and other properties.</p><p>To animate your text, you can use keyframes to change its position, scale, opacity, rotation, and other attributes over time.&#160;You can also add effects, such as shadows, glows, bevels, and gradients, to enhance the appearance of your text.</p><p>To render your composition, select&#160;Composition&#160;&gt;&#160;Add to Render Queue, and choose your output settings.</p><p>The Text Layer in After Effects is a powerful tool for creating dynamic and engaging motion graphics.&#160;By experimenting with different fonts, colors, and animations, you can create a wide range of visual styles and effects.</p><p>Point Text</p><p>In After Effects, &quot;point text&quot; refers to a type of text layer where the text is anchored to a specific point in the composition.&#160;This is in contrast to &quot;paragraph text&quot;, where the text is contained within a bounding box and can be wrapped to multiple lines.</p><p>To create point text in After Effects, follow these steps:</p><p>Select the Text tool from the toolbar or use the shortcut key Ctrl/Cmd + T.</p><p>Click on the composition where you want the text to appear.</p><p>Type in your text.</p><p>To adjust the position of the text, use the Selection tool to click and drag the text to the desired location.</p><p>Use the Character and Paragraph panels to adjust the font, size, color, and other properties of the text.</p><p>Once you have created your point text layer, you can animate it by setting keyframes for its position, scale, rotation, and other properties.&#160;You can also apply effects and expressions to the text to create more complex animations and interactions.</p><p>Point text is useful for creating simple titles and captions, as well as for adding text overlays to video footage.&#160;Its simplicity and flexibility make it a popular choice for many types of motion graphics projects.</p><p>Paragraph Text</p><p>In After Effects, &quot;paragraph text&quot; refers to a type of text layer where the text is contained within a bounding box and can wrap to multiple lines.&#160;This allows you to create more complex text layouts and formatting options.</p><p>To create paragraph text in After Effects, follow these steps:</p><p>Select the&#160;Text&#160;tool from the toolbar or use the shortcut key&#160;Ctrl/Cmd + T.</p><p>Click and drag to create a rectangular bounding box where you want the text to appear.</p><p>Type in your text.&#160;The text will be wrapped in multiple lines if it exceeds the width of the bounding box.</p><p>Use the Selection tool to adjust the position and size of the bounding box.</p><p>Use the Character and Paragraph panels to adjust the font, size, color, alignment, spacing, and other properties of the text.</p><p>Once you have created your paragraph text layer, you can animate it by setting keyframes for its position, scale, rotation, and other properties.&#160;You can also apply effects and expressions to the text to create more complex animations and interactions.</p><p>Paragraph text is useful for creating longer blocks of text, such as subtitles, captions, and body copy.&#160;Its ability to wrap text to multiple lines allows you to create more readable and aesthetically pleasing text layouts.</p><p>Welcome to this video on the Text Tool.</p><p>In this video, we&#39;ll explore the text layer in After Effects. Let&#39;s start by creating a new composition. Before we begin, make sure you have the character and paragraph panels in your workspace.</p><p>Select the Text tool from the Tools menu. You can click and hold the cursor to choose between horizontal and vertical text. There are two ways in which you can enter text in After Effects. You can just click in the Composition panel and then type an infinite line of text. In this method, the text does not wrap to the next line and will just continue on the same line. To delete this active text layer, just press the Escape key.</p><p>Another way of entering text is to click and drag to create a text frame. Now, any text you add over here will be added as paragraph text that will be wrapped within this shape. You can change the size and orientation of this text frame if you want. Let&#39;s delete this text. I am going to click and add the text &#39;After Effects&#39;. To format this text, select the text layer, click the text, make sure the Text tool is the active tool, and then press control + A to select the text. You can then open the Character panel to edit the text settings.</p><p>This panel contains many of the same options that you might know from Adobe Photoshop, Illustrator, or any other design software. The first option here is to choose the font. Adobe has a huge selection of fonts you can choose from. You can also install additional fonts. To search for a font, just type the name in this field. I am choosing Myanmar Text Bold here.</p><p>To change the color of the text, click the color swatch option and choose the color setting that you want. You can also apply an outline or stroke to the text. Let&#39;s first zoom in to see it better. The Stroke settings are nested with the color settings. Just click it to activate it, and then click it again to change the color of the stroke. To turn off the stroke, just click the Stroke button again.</p><p>Next, you can use the Scale option to increase or decrease the size of the text frame. There are many other modifications you can make to text as well. Let&#39;s move the word &#39;Effects&#39; into another line by clicking here and pressing Enter. Next, just select the layer and adjust the Line Height value by clicking and dragging the value left or right. This adjusts the spacing between the two lines. You can also enter any custom value you want by entering it manually.</p><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f886ba1f110cb7b607da50cdb8481c33','adobe-after-effects-m5-l5-lesson-4','a42f30aa52d702d59218ab00a9d0fb52','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Adjusting Layers</h3><p>Adjusting Layers</p><p>You can adjust the layers in your composition in many ways.&#160;Let&#39;s look at a few of them.</p><p>Moving Layers</p><p>To move a layer in After Effects, you can either click and drag the layer to a new position in the Composition panel or use the arrow keys on your keyboard to move it in increments.</p><p>Sequencing Layers</p><p>To sequence layers in After Effects, you can drag and drop them into the desired order in the timeline panel.&#160;Layers at the top of the layer stack will be visible in front of layers beneath them.</p><p>Trimming Layers</p><p>To trim the beginning or end of a layer in After Effects, you can select the layer in the timeline panel and drag the handles at the beginning or end of the layer to the desired position.</p><p>Splitting Layers</p><p>To split a layer in After Effects, you can place your playhead where you want to split your layer and go to layer from the main menu and choose split layer.&#160;This will create a cut in the layer at that point.</p><p>Setting In and Out Points in the Footage Panel</p><p>To set in and out points for a video clip in the Footage panel in After Effects, you can use the keyboard shortcuts &quot;I&quot; and &quot;O&quot; to set the in and out points, respectively.&#160;Alternatively, you can drag the handles at the beginning and end of the clip to the desired positions.&#160;Once you have set the in and out points, you can use the clip in your composition by dragging it from the project panel to the timeline panel.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('dce573a940af4c77f064599e5ee9d844','adobe-after-effects-m5-l6-lesson-4-activity','a42f30aa52d702d59218ab00a9d0fb52','Lesson 4 Activity','text',12,'<h2>Lesson 4 Activity</h2><section><h3>Lesson 4 Activity</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9158148d31a8e9763a8b90e1bb72b329','adobe-after-effects-m5-l7-lesson-5','a42f30aa52d702d59218ab00a9d0fb52','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Transforming Visual Elements in the Composition</h3><p>Transforming Visual Elements in the Composition</p><p>After Effects provides a wide range of layer properties that you can use to customize and animate your compositions.&#160;Transform properties&#160;are a set of layer properties in After Effects that allow you to move, rotate, scale, and adjust the opacity of a layer.&#160;Here&#39;s an overview of the transform properties in After Effects:</p><p>Click each term to learn more.</p><p>Next Tab</p><p>Position</p><p>This property controls the position of the layer in the composition.&#160;You can adjust the position by changing the&#160;X and Y values&#160;in the&#160;Effect Controls&#160;panel or by dragging the layer in the&#160;Composition&#160;panel.</p><p>Scale</p><p>This property controls the size of the layer in the composition. You can adjust the scale by changing the percentage value in the&#160;Effect Controls&#160;panel, or by dragging the layer handles in the&#160;Composition&#160;panel.</p><p>Rotation</p><p>This property controls the rotation of the layer in the composition. You can adjust the rotation by changing the degree value in the&#160;Effect Controls&#160;panel or by rotating the layer in the&#160;Composition&#160;panel.</p><p>Opacity</p><p>This property controls the transparency of the layer in the composition. You can adjust the opacity by changing the percentage value in the&#160;Effect Controls&#160;panel or by using the opacity slider in the&#160;Layer&#160;panel.</p><p>Anchor Point</p><p>This property controls the point in the layer around which transformations such as rotation and scaling occur. You can adjust the anchor point by clicking on the layer and moving the anchor point in the&#160;Composition&#160;panel.</p></section><section><h3>Adjusting Layer Properties</h3><p>Adjusting Layer Properties</p><p>There are some additional properties that you can adjust in After Effects based on the nature of the layer.</p><p>Mask Properties</p><p>These include mask shape, feather, and expansion, which allow you to create and adjust masks for a layer.</p><p>Effects</p><p>These include a wide range of visual and audio effects you can apply to a layer, such as color correction, blur, and distortion.</p><p>Text Properties</p><p>Text properties include text content, font, size, and color, as well as text animation properties such as tracking, leading, and baseline shift.</p><p>Shape Properties</p><p>You can also adjust many different properties of shapes, including shape layer contents such as fill, stroke, and gradient, as well as shape layer properties such as path operations and trim paths.</p><p>3D Properties</p><p>These include position, rotation, and scale in 3D space, as well as camera and light properties.</p><p>For example, let’s assume a sports bike manufacturer has approached you to create a promotional video to showcase their latest sports bike model.&#160;First, you will import the 3D model of the bike into After Effects as a 3D layer.&#160;You can then use the 3D camera to showcase the bike from different angles.&#160;This will help you create a visually appealing promotional video for the client.</p><p>Time Properties</p><p>These include time remapping, which allows you to adjust the timing and speed of a layer over time.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c67e435369bcbe55ae2264b4a539bcfb','adobe-after-effects-m5-l8-summary','a42f30aa52d702d59218ab00a9d0fb52','Summary','text',12,'<h2>Summary</h2><section><h3>Summary</h3><p>Summary</p><p>Select a Student</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module&#160;on&#160;Creating and Modifying Visual Elements Part I!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Create visual elements using a variety of tools.</p><p>Place assets into a composition.</p><p>Create text in a composition.</p><p>Adjust paragraph settings.</p><p>Animate text.</p><p>Adjust layers using a variety of tools.</p><p>Transform visual elements in the composition.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('fe61302d36bbedec0f5aab94003c85fa','adobe-after-effects-m5-l9-quiz','a42f30aa52d702d59218ab00a9d0fb52','Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Visual Elements Part 1. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('fee599c54899849ea7485007ee465f8e','adobe-after-effects-module-6','548316f2bc2d7ea184c46fc23dac5160','Module 6: Visual Elements Part 2',6) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2acb7064114c03fd81f04fa1b2fecfae','adobe-after-effects-m6-l1-introduction-purpose-and-objectives','fee599c54899849ea7485007ee465f8e','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction</h3><p>Introduction</p><p>Hi again and welcome to this module on Creating and Modifying Visual Elements Part II. Let’s quickly recap what we’ve learned so far (or what you should know before tackling this module). You’ve learned some essential video basics, you’ve learned to navigate around the After Effects interface and set up a project, and you’ve also learned how to organize your files using layers in your composition.</p><p>This module will give you an insight into the power of effects, transformations, and motion effects in After Effects. If you can dream it, you can create it! After Effects has a large bank of effects and animations that you can use to enhance your videos, create smooth transitions, and add stylistic features to all of your clips.</p><p>We’ll learn how to fine-tune your video effects to give them a clean, professional look and feel. You can even create your own custom preset effects and transitions that you can use and reuse for multiple projects.</p><p>With that, let’s get going!</p><p>Module Description</p><p>License:&#160;All Rights Reserved</p><p>After Effects is a haven for the creative mind, and it contains a multitude of effects, animations, and other motion effects to explore.&#160;In this module, students will learn about some basic editing techniques to manipulate video clips.&#160;They will also learn how to use Effect controls and adjust different animation and effect settings.&#160;Students will learn about adjustment layers and how they can be used.</p><p>Objectives</p><p>In this module, students will:</p><p>Change the speed of a video clip.</p><p>Use basic auto-correction methods and tools.</p><p>Apply and adjust a video effect or preset to a layer.</p><p>Use 3D space to modify composition elements.</p><p>Create composites.</p><p>Apply and modify effects and presets on multiple layers.</p><p>Apply and adjust transformations using keyframes.</p><p>Animate effects using keyframes.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e54bdf41572f9c134e161b779e1b7565','adobe-after-effects-m6-l2-lesson-1','fee599c54899849ea7485007ee465f8e','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Changing Speed of Video Clip</h3><p>Changing Speed of Video Clip</p><p>Time remapping, time stretching, creating freeze frames, changing speed, and time reversal are all techniques you can use to manipulate time in After Effects.&#160;Here&#39;s an overview of each technique:</p><p>Time Remapping</p><p>This technique allows you to adjust the timing and speed of a layer over time.&#160;To use time remapping, you can enable it on the layer by right-clicking on it and selecting&#160;Time&#160;&gt;&#160;Enable Time Remapping.&#160;This will create a time-remap property in the timeline panel, which you can</p><p>Time Stretching</p><p>This technique allows you to adjust the duration of a layer without changing its speed. To use time stretching, you can select the layer in the timeline panel and go to&#160;Layer&#160;&gt;&#160;Time Stretch. This will bring up a dialog box where you can enter a new duration for the layer. It will adjust the timing and placement of your other animation keyframes according to the new time.</p><p>Creating Freeze Frames</p><p>This technique allows you to create a still image from a video clip. To create a freeze frame, you can set the current time indicator to the frame you want to freeze, then right-click on the layer and select&#160;Time&#160;&gt;&#160;Freeze Frame. This will create a new still image of the frame you selected.</p><p>Time Reversal</p><p>This technique allows you to play a layer in reverse. To play a layer in reverse, you can select the layer in the timeline panel and go to&#160;Layer&#160;&gt;&#160;Time&#160;&gt;&#160;Time Reverse Layer. This will reverse the layer, so it plays backward from its end to its beginning.</p><p>By using these time manipulation techniques in After Effects, you can create interesting and dynamic visual effects and animations.</p><p>Let’s assume you are editing the video of a football game that took place last night.&#160;The game was intense and full of exciting moments.&#160;You want to highlight a few of the exciting moments to make it more engaging for viewers.&#160;You can use the time remapping, time stretching, creating freeze frames, changing speed of the video to draw the viewers’ attention to show the skills of the player.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('dd46fbcac136bfda53f85530645882b0','adobe-after-effects-m6-l3-lesson-1-activity','fee599c54899849ea7485007ee465f8e','Lesson 1 Activity','text',12,'<h2>Lesson 1 Activity</h2><section><h3>Lesson 1 Activity</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f8b37c13b3c9ff2bd75ca5eba96a9622','adobe-after-effects-m6-l4-lesson-2','fee599c54899849ea7485007ee465f8e','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Using Basic Auto-Correction Methods&amp;Tools</h3><p>Using Basic Auto-Correction Methods and Tools</p><p>After Effects has several color correction tools that you can use to adjust the colors in your footage.&#160;Here are some of the basic color correction tools in After Effects:</p><p>LumetriColor Effect</p><p>The LumetriColor effect is a powerful tool that allows you to adjust the color and exposure of your footage.&#160;You can use this effect to adjust the brightness, contrast, saturation, and hue of your footage.</p><p>Let’s say you are working on editing a short film.&#160;The scenes in that film are shot at different locations and light conditions.&#160;To maintain consistency throughout the video, you can use LumetriColor Effect feature for color correction and grading and easily make changes in the video.</p><p>Levels Effect</p><p>The Levels effect allows you to adjust the black, white, and gray levels in your footage.&#160;You can use this effect to improve the contrast and color balance of your footage.</p><p>Curves Effect</p><p>The Curves effect is a versatile tool that allows you to adjust the brightness and contrast of your footage.&#160;You can use this effect to create custom color grades for your footage.</p><p>Color Balance Effect</p><p>The Color Balance effect allows you to adjust the shadows, midtones, and highlights of your footage.&#160;You can use this effect to adjust the color temperature of your footage.</p><p>Tint Effect</p><p>The Tint effect allows you to add a color tint to your footage.&#160;You can use this effect to create a specific mood or atmosphere for your footage.</p><p>Hue/Saturation Effect</p><p>The Hue/Saturation effect allows you to adjust the hue, saturation, and lightness of your footage.&#160;You can use this effect to create specific color effects or to correct color imbalances in your footage.</p><p>By using these basic color correction tools in After Effects, you can achieve a more professional and polished look for your video projects.</p></section><section><h3>Stabilization</h3><p>Stabilization</p><p>Stabilization refers to the process of reducing unwanted motion or shaking in video footage.&#160;The process involves analyzing the motion of the camera and applying corrections to reduce or eliminate unwanted movement.</p><p>Unwanted motion can be caused by several factors, such as camera shake, movement of the subject, or vibrations from the environment.&#160;Stabilization can help make the footage appear smoother and more professional.</p><p>Stabilization can be achieved through various methods, including using a tripod or other stable support for the camera during filming, using electronic or optical image stabilization systems built into the camera or lens, or applying software-based stabilization in post-production using specialized software or plugins.</p><p>Overall, stabilization is an essential technique for achieving high-quality, professional-looking video footage.&#160;You can stabilize footage in After Effects using the Warp Stabilizer effect.&#160;Here&#39;s how:</p><p>Select the footage you want to stabilize in the timeline.</p><p>Go to the&#160;Effects&#160;panel and search for&#160;Warp Stabilizer</p><p>Drag the Warp Stabilizer effect onto the footage in the timeline.</p><p>In the&#160;Effect Controls&#160;panel, you can choose a stabilization preset from the drop-down menu or adjust the settings manually.</p><p>By default, the&#160;Smoothness&#160;option is set to 50%, which determines how much of the original camera motion is retained in the stabilized footage.&#160;You can increase or decrease this value to adjust the amount of smoothing.</p><p>The&#160;Result&#160;option allows you to choose how much of the stabilized footage is cropped to remove any unwanted borders that may appear after stabilization.&#160;You can choose to stabilize and crop the footage to a specific resolution or leave it uncropped.</p><p>You can also adjust other settings, such as the&#160;Method&#160;option, which determines the type of stabilization used, and the&#160;Detailed Analysis&#160;option, which analyzes the footage more thoroughly for better stabilization.</p><p>Once you have adjusted the settings, click on the&#160;Analyze&#160;button to start analyzing the footage for stabilization.</p><p>After the analysis is complete, the footage will be automatically stabilized.&#160;You can preview the stabilized footage in the timeline or in the&#160;Effects&#160;panel.</p><p>Overall, the Warp Stabilizer effect in After Effects is a powerful tool for stabilizing footage and can help you achieve smooth and professional-looking video footage.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1c27f9c7c5ddc28a06b15a36d87f5a7f','adobe-after-effects-m6-l5-lesson-3','fee599c54899849ea7485007ee465f8e','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Adding and Modifying Effects</h3><p>Adding and Modifying Effects</p><p>After Effects is a powerful visual effects and motion graphics software that comes with a wide range of built-in effects that you can use to enhance your compositions.&#160;Here is a list of some of the most commonly used effects in After Effects and their explanation:</p><p>Click each term to learn more.</p><p>Blur &amp; Sharpen</p><p>This effect allows you to blur or sharpen your footage to create a soft or sharp look.</p><p>Color Correction</p><p>This effect allows you to adjust the color and contrast of your footage and apply various color grading techniques.</p><p>Distort</p><p>This effect allows you to warp and bend your footage, create wave-like effects, and more.</p><p>Generate</p><p>This effect allows you to create various shapes and patterns, such as fractals, grids, and noise.</p><p>Keying</p><p>This effect allows you to remove a specific color or key out a green screen background.</p><p>Matte</p><p>This effect allows you to create a mask or matte around your footage, allowing you to isolate specific areas for manipulation.</p><p>Noise &amp; Grain</p><p>This effect allows you to add or remove noise and grain from your footage, which can create a vintage or film-like look.</p><p>Particles</p><p>This effect allows you to create various particle effects, such as fire, smoke, and dust.</p><p>Time</p><p>This effect allows you to manipulate the speed and timing of your footage, such as slowing down or speeding up the motion.</p><p>Transition</p><p>This effect allows you to create various transitions between two clips, such as fades and wipes.</p><p>Warp Stabilizer</p><p>This effect allows you to stabilize shaky footage and remove unwanted camera movement.</p><p>3D</p><p>This effect allows you to create and manipulate 3D layers and objects, giving your compositions depth and dimension.</p><p>These are just a few of the many effects available in After Effects.&#160;Each effect has its own set of parameters and settings, allowing you to customize and create unique effects for your projects.&#160;You can modify these effects and presets to suit your needs and create custom effects and settings.&#160;Here&#39;s how to modify effects and presets in After Effects:</p><p>Apply the effect or preset to the layer you want to modify by dragging and dropping it from the&#160;Effects &amp; Presets&#160;panel onto the layer in the timeline.</p><p>In the&#160;Effect Controls&#160;panel, you can modify the properties of the effect or preset.</p><p>To modify a property, simply click on it to select it, then adjust the value by dragging the slider or entering a new value in the text box.</p><p>You can also animate the properties by setting keyframes.&#160;To do this, click on the stopwatch icon next to the property you want to animate, then adjust the value at different points in time by setting keyframes.</p><p>To save your modified effect or preset, go to the&#160;Animation&#160;menu and select&#160;Save Animation Preset.</p><p>In the&#160;Save Animation Preset&#160;dialog box, you can name your preset and select which properties to include.</p><p>Click&#160;OK&#160;to save the preset.</p><p>You can now find your custom preset in the&#160;Effects &amp; Presets&#160;panel, where you can apply it to other layers in your composition.</p><p>By modifying effects and presets in After Effects, you can create custom settings and animations that are tailored to your specific needs.&#160;This can save you time and make your workflow more efficient while also allowing you to create unique and creative effects for your projects.</p></section><section><h3>Using 3D Space to Modify Composition Elements</h3><p>Using 3D Space to Modify Composition Elements</p><p>After Effects allows you to work with 3D space, which means you can modify composition elements in three dimensions, giving you more control over the position, rotation, and scale of the layers.&#160;Here&#39;s how to use 3D space to modify composition elements in After Effects:</p><p>Create a new composition by going to&#160;Composition&#160;&gt;&#160;New Composition&#160;in the menu bar.</p><p>Import the footage or elements you want to use in your composition by going to&#160;File&#160;&gt;&#160;Import&#160;in the menu bar or dragging and dropping them into the Project panel.</p><p>Select the layer you want to modify in the timeline.</p><p>In the&#160;Layer&#160;panel, click on the cube icon to activate 3D space for the layer.</p><p>You can now modify the position, rotation, and scale of the layer in three dimensions using the&#160;X,&#160;Y,&#160;and&#160;Z&#160;properties in the&#160;Transform&#160;section of the&#160;Layer&#160;panel.</p><p>To move the layer in 3D space, adjust the&#160;Position&#160;property.&#160;You can also use the&#160;Pan Behind&#160;tool to adjust the anchor point of the layer, which affects how the layer rotates and scales in 3D space.</p><p>To rotate the layer in 3D space, adjust the&#160;Rotation&#160;property.&#160;You can also use the&#160;Orientation&#160;property to change the direction the layer is facing.</p><p>To scale the layer in 3D space, adjust the&#160;Scale&#160;property.</p><p>You can also use the&#160;Camera&#160;tool to create a camera and adjust its position and settings to change the perspective and depth of the 3D space.</p><p>In After Effects, you can use a 3D camera to create dynamic and immersive compositions by adding depth and perspective to your layers.&#160;Here&#39;s how to use a 3D camera in After Effects:</p><p>Select the composition to which you want to add a 3D camera in the timeline.</p><p>In the&#160;Layer&#160;panel, click on the cube icon to activate 3D space for the layer.</p><p>Go to&#160;Layer&#160;&gt;&#160;New&#160;&gt;&#160;Camera&#160;in the menu bar to create a new camera.</p><p>In the&#160;New Camera&#160;dialog box, you can set the camera type, angle of view, and other settings.</p><p>Click&#160;OK&#160;to create the camera.</p><p>In the&#160;Layer&#160;panel, select the camera layer.&#160;And change its properties.</p><p>You can use the&#160;Camera&#160;tool to adjust the camera position and settings in the&#160;Composition&#160;panel.</p><p>You can also adjust the camera settings in the&#160;Camera Options&#160;section of the&#160;Effect Controls&#160;panel.</p><p>To animate the camera, you can use keyframes to set the camera position, rotation, and other properties over time.</p><p>You c<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7fb4bccdc4a8d74b0e4d1ec503c958c9','adobe-after-effects-m6-l6-lesson-4','fee599c54899849ea7485007ee465f8e','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Keying and Masking</h3><p>Keying and Masking</p><p>Keying</p><p>In Adobe After Effects, keying is the process of removing a specific color or range of colors from an image or video footage.&#160;This is often used in post-production to separate the subject from the background or to create special effects.</p><p>To key a layer in After Effects, follow these steps:</p><p>Import the footage or image into After Effects.</p><p>Create a new composition by clicking on&#160;Composition&#160;&gt;&#160;New Composition&#160;in the menu bar.</p><p>Drag and drop the footage or image into the new composition.</p><p>Select the layer that you want to key by clicking on it in the timeline.</p><p>Click on&#160;Effect&#160;&gt;&#160;Keying&#160;in the menu bar and select the keying effect that you want to use, such as&#160;Keylight&#160;or&#160;Ultra Key.</p><p>Adjust the settings of the keying effect to remove the unwanted color or range of colors from the layer.&#160;This usually involves selecting a color or range of colors using the eyedropper tool and adjusting the settings, such as the tolerance, edge feathering, and alpha channel output.</p><p>Preview the keying effect by pressing the spacebar to play the timeline or using the RAM preview function to play a section of the composition in real time.</p><p>Note that keying can be a complex and time-consuming process, especially if the footage has uneven lighting, shadows, or motion blur.&#160;To achieve a seamless result, it may require additional steps, such as rotoscoping or color correction.</p><p>Masking</p><p>Masking is a fundamental technique in Adobe After Effects that allows you to selectively show or hide parts of a layer, create shapes, or reveal layers beneath it.&#160;You can use masks to create visual effects, and composites, or to isolate areas for color correction or other adjustments.</p><p>To create a mask in After Effects, follow these steps:</p><p>Select the layer that you want to mask in the timeline.</p><p>Click on the&#160;Pen Tool&#160;in the toolbar to create a new mask shape.</p><p>Click and drag the pen tool to draw the mask shape on the layer.</p><p>You can adjust the shape by dragging the anchor points, Bezier handles or by using the various mask tools in the toolbar.</p><p>To adjust the mask&#39;s properties, such as its size, feathering, opacity, or mode, select the mask in the timeline and open the mask properties panel by clicking on the&#160;Mask&#160;button in the layer controls.</p><p>To animate the mask over time, you can use keyframes to change the mask&#39;s properties or use the&#160;Mask Path&#160;property to animate the mask shape.</p><p>To create a mask from an existing layer or shape, you can use the&#160;Auto-trace&#160;function or use the&#160;Set Matte&#160;effect.</p><p>You can use many advanced techniques with masks in After Effects, such as using multiple masks on a single layer, combining masks with effects, or using masks to create 3D effects.</p><p>Keying in Adobe After Effects can be used to replace a background with a different scene.&#160;It is a green screen.&#160;Let’s assume you are working on a short movie.&#160;The client has given you the video of an actor standing in front of a green screen.&#160;The location is shot separately.&#160;You can use the keying feature to get rid of the green background behind the actor.</p><p>Welcome to this video on Masking!</p><p>In this video, you will learn about how to use masking in your After Effects projects. Let&#39;s import a video into After Effects. And let&#39;s create a composition using this video by dragging the video down to the New Composition icon. You can see that this video shows a chair in a room with windows. Let&#39;s say that for this demo, we want to change the background environment shown through the window. First thing I’ll do is zoom into the video so we can take a closer look at the window. You can rename the video in the Layers panel. Select the layer and then choose the Pen tool from the Tools menu. You can also use keyboard shortcuts and just press G to select the Pen tool.</p><p>Since we want to change what we see through this window, let&#39;s start cutting. Using the Pen tool, click points on the window to mark the area you want to cut out. Once you click back on the starting point to close the mask, you will see that the video is masked out. Here, the select area is isolated and then the rest of the video is hidden. But we want to mask out what is inside the window and keep the rest of the video the same. So now, we need to invert the mask. I am zooming out again so we can see the full video.</p><p>Click the arrow next to the video in the Layers panel. You will see the Masks properties of this layer. Click the arrow to view the mask settings that you can edit. You can see that this drop-down shows that the Add mask has been selected. Let&#39;s change this to None. This setting will remove the mask and show you the original video. Let&#39;s select Add again and then let&#39;s select the Inverted checkbox.&#160; This masks out the window area.</p><p>Now, to change this to a different background, we first need to make this transparent. Click the Toggle Transparency Grid icon in the Composition panel. You will see the window area has changed into a checkered pattern, which indicates that this area is transparent.</p><p>Let&#39;s create a solid red layer to see which parts of this video are transparent and which are not. Right-click in the Layers panel, select New and click Solid. Now change the color to red. Now, let&#39;s move this layer so that it is below the video layer.</p><p>Now, let&#39;s zoom in and take a look at the transparent parts to make sure we have masked it correctly.</p><p>Here, we have successfully masked out one window. We do not want to mask this window, as it is completely covered by the wall, and you cannot see any of the outside environment. But the lower window still does show the outside environment, so let&#39;s mask this one out as well. Select the layer, choose the Pen tool, and mark out the area you want to mask.</p><p>Select the layer again and choose the pen tool and select the desired region which you want to mask out. As you see, the mask is not working. Let&#39;s change the setting of both these masks to Subtract filters. Now, you can see that both windows are masked. Ok we are in good shape now!</p><p>Now let&#39;s import the footage we want to show here. Drag and drop th<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3b681a38f10bd5f5bb5d6141092dc5b3','adobe-after-effects-m6-l7-lesson-5','fee599c54899849ea7485007ee465f8e','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Applying and Adjusting Transformations using Keyfram</h3><p>Applying and Adjusting Transformations using Keyframes</p><p>Keyframing</p><p>In Adobe After Effects, keyframing the transform properties of a layer is a powerful technique for creating dynamic animations.&#160;The transform properties include position, scale, rotation, and opacity.&#160;By setting keyframes at different points in time and adjusting the values of the transform properties, you can create smooth animations that bring your project to life.</p><p>Here&#39;s how to keyframe the transform properties in After Effects:</p><p>Select the layer you want to animate in the composition panel.</p><p>Expand the layer in the timeline panel by clicking the triangle next to the layer name.</p><p>Click the stopwatch icon next to the transform property you want to animate.&#160;This will add a keyframe at the current time.</p><p>Move the current time indicator to a different point in time in the timeline.</p><p>Adjust the value of the transform property by dragging the slider or typing in a new value.</p><p>A new keyframe will automatically be added at the current time with the updated value.</p><p>Repeat steps 4-6 to add more keyframes and create a smooth animation.</p><p>You can adjust the timing of the keyframes by dragging them in the timeline panel or by selecting them and using the keyframe interpolation options.</p><p>Preview your animation by pressing the spacebar to play back the composition.</p><p>By using keyframes to animate the transform properties of a layer, you can create a wide range of animations, including movement, scaling, rotation, and fades.&#160;You can also use keyframes to create more complex animations by animating multiple properties at once or by using expressions to control the animation.&#160;With practice, keyframing in After Effects can become a quick and intuitive process that allows you to bring your creative ideas to life.</p><p>Graph Editor</p><p>The Graph Editor in Adobe After Effects is a powerful tool that allows you to fine-tune the animation curves of your keyframes.&#160;By using Graph Editor, you can create smooth and natural-looking animations that bring your project to life.</p><p>There are different components of graph editor that are listed below:</p><p>Click each term to learn more.</p><p>Graph</p><p>The Graph itself is the main area where you will see the animation curves and keyframes.</p><p>Time Ruler</p><p>The Time Ruler is located at the bottom of the Graph Editor and displays the timeline of your composition.</p><p>Keyframes</p><p>Keyframes are markers that represent changes in animation properties over time. You can add, move, and delete keyframes in the Graph Editor.</p><p>Curves</p><p>Curves are lines that connect the keyframes and represent the animation values between them. You can adjust the curves to change the animation speed, smoothness, or amplitude.</p><p>Value and Speed Graph</p><p>The Value Graph displays the animation values of the selected property, while the Speed Graph displays the animation speed. You can use these graphs to fine-tune the animation timing and easing.</p><p>Handles</p><p>Handles are control points on the curves that allow you to adjust the curve shape and direction.</p><p>Grid</p><p>The Grid provides a visual reference for the graph coordinates and can be customized to match your preferences.</p><p>Here&#39;s how to use the Graph Editor in After Effects:</p><p>Select the layer with keyframes that you want to edit in the timeline panel.</p><p>Click the Graph Editor button in the timeline panel to open the Graph Editor.</p><p>The Graph Editor displays the animation curves for the selected keyframes.&#160;You can adjust the curves by clicking and dragging the control points on the curves.</p><p>The X-axis of the Graph Editor represents time, while the Y-axis represents the value of the property being animated.</p><p>You can adjust the timing of the animation by dragging the keyframes along the X-axis in the Graph Editor.</p><p>You can adjust the shape of the animation curve by dragging the control points on the curve.</p><p>You can also use the different tools in the Graph Editor to adjust the animation curve, including the Pen tool, the Selection tool, and the Hand tool.</p><p>Preview your animation by pressing the spacebar to play back the composition.</p><p>By using the Graph Editor in After Effects, you can create custom animation curves that add depth and character to your animations.&#160;You can use the Graph Editor to adjust the timing and values of keyframes, as well as the shape of the animation curve.&#160;With practice, the Graph Editor can become a powerful tool that allows you to create dynamic and engaging animations.</p><p>Interpolation</p><p>Interpolation is the process of filling in the gaps between two known values with unknown data.&#160;You can use keyframes to specify a property&#39;s values at crucial moments.&#160;This is why interpolation is also commonly referred to as tweening.&#160;For every interval between keyframes, After Effects interpolates values for the property.</p><p>Movement, effects, audio levels, image alterations, transparency, color changes, and many other visual and audio aspects can all be animated via interpolating between keyframes.&#160;Some common interpolation methods are:</p><p>Click each term to learn more.</p><p>Linear Keyframes</p><p>Linear keyframes create a constant motion between keyframes, with no easing or acceleration.</p><p>Hold Keyframes</p><p>Hold keyframes create a step-like effect, where the animation value stays constant until the next keyframe.</p><p>Easy Ease Keyframes</p><p>Easy Ease keyframes create a smooth easing effect, slowing down the animation as it approaches a keyframe and accelerating as it moves away.</p><p>Easy Ease In Keyframes</p><p>Easy Ease In keyframes create a gradual easing effect as the animation approaches a keyframe.</p><p>Easy Ease Out Keyframes</p><p>Easy Ease Out keyframes create a gradual easing effect as the animation moves away from a keyframe.</p><p>Bezier Keyframes</p><p>Bezier keyframes allow for more control over the easing and acceleration of animation curves, with handles that can be adjusted to change the shape and direction of the curve.</p><p>Auto Bezier Keyframes</p><p>Auto Bezier keyframes create a smooth, automatically adjusted curve between keyframes.</p><p>Continuous Bezier Keyframes</p><p>Continuous Bezier keyframes <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b19f8b7cac595cd058aa27543016f7cf','adobe-after-effects-m6-l8-summary','fee599c54899849ea7485007ee465f8e','Summary','text',12,'<h2>Summary</h2><section><h3>Summary</h3><p>Summary</p><p>Great Work!&#160;You have successfully completed this module on&#160;Creating and Modifying Visual Elements Part II!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Changed the speed of a video clip.</p><p>Used basic auto-correction methods and tools.</p><p>Applied and adjusted a video effect or preset to a layer.</p><p>Used 3D space to modify composition elements.</p><p>Created composites.</p><p>Applied and modified effects and presets on multiple layers.</p><p>Applied and adjusted transformations using keyframes.</p><p>Animated effects using keyframes.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4a4ca818fd6b6f2e85b2053d4ad9f3b4','adobe-after-effects-m6-l9-quiz','fee599c54899849ea7485007ee465f8e','Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Visual Elements Part 2. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('6a5bbe1c87dd51cd447a2a58eb13c407','adobe-after-effects-module-7','548316f2bc2d7ea184c46fc23dac5160','Module 7: Publishing Digital Media',7) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('02abb9ac75092787684bf5585f781616','adobe-after-effects-m7-l1-introduction-purpose-and-objectives','6a5bbe1c87dd51cd447a2a58eb13c407','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction</h3><p>Introduction</p><p>Hi everyone, and welcome to this module on Publishing Digital Media. It’s been an exciting journey diving into all of the fantastic features that After Effects has to offer.By now, you should have an idea of just how many things you can do with After Effects. Just like any other tool, you’ll keep getting better at it the more you use it! So make sure you continue to explore After Effects and experiment to design creative, impactful videos!</p><p>In this module, we’ll cover an important last step in this After Effects journey—publishing and exporting your digital media. Because After Effects allows you to work with so many different types of media files, it also gives you multiple options to prepare and export your data in various formats and for various purposes.</p><p>Hopefully by the end here, you have been able to capture the vision of what is possible with After Effects! There are so many things out there to image, create, edit, and publish. You are well on your way to seeing that vision and those ideas become reality.</p><p>Module Description</p><p>After Effects gives you multiple ways and formats in which you can export your video compositions for digital or web use, screen use, or for use on other devices or programs.&#160;In this module, students will learn how to check their project for errors and ensure all the correct project specifications are set.&#160;Students will also learn about exporting and archiving project elements in various formats.&#160;Finally, we’ll go over the structure and test prep students will need for the ACA After Effects Certification Exam.</p><p>Objectives</p><p>In this module, students will:</p><p>Check a composition for errors and verify specifications.</p><p>Archive a project.</p><p>Export frames.</p><p>Export a composition.</p><p>Prepare for the Adobe Certified Professional Exam.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4eec68add1118eac7b2790925fca41e6','adobe-after-effects-m7-l2-lesson-1','6a5bbe1c87dd51cd447a2a58eb13c407','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Checking for Errors</h3><p>Checking for Errors</p><p>In After Effects,&#160;rendering&#160;refers to the process of building movie frames from your compositions.&#160;When you render a frame of your video, After Effects essentially combines all the layers, animations, effects, options, and other details in the composition together.&#160;Each frame of your video is a combination of all these elements put together into a two-dimensional composite image.&#160;All of these individual frames are stitched together frame by frame to render a complete movie.</p><p>Once you render a composition to create the final output, it undergoes processing using one or more output modules designed to encode the rendered frames into your output files.&#160;This is basically the process of&#160;exporting&#160;your video.</p><p>The great thing about After Effects is that you can output your video into a single file that will play as a video, or you could also export it as a series of frames or still photos.</p><p>Before you can render your video in After Effects, you must always check all of the settings of your project to make sure there are no errors and that you have chosen all the correct quality settings for your requirements.</p><p>Here are some specific things to check before rendering:</p><p>Click each term to learn more.</p><p>Check for Typos</p><p>Make sure that you check all of the text components of your video to ensure that there are no typos or spelling mistakes.</p><p>Hidden Layers</p><p>This is one of the most common errors you may need to correct. While creating and editing your composition, you may hide or turn off specific layers to work on other portions of the video. Always ensure that any layers that should be visible in the final output are not hidden or turned off. You can use the&#160;Toggle Switches / Modes&#160;button at the bottom of the timeline panel to show or hide layers.</p><p>Animation Timing</p><p>Preview the animation and check the timing of each layer and effect to make sure that it lines up with the other elements of the video and appears at the right time. You can use the RAM preview feature to preview the animation in real-time and adjust the timings as needed.</p><p>Audio Levels</p><p>Check your composition&#39;s audio levels to ensure they are consistent and appropriate for your project. You can adjust audio levels in the timeline panel or the audio effects section of the effects panel.</p><p>Resolution</p><p>Make sure that the resolution of your composition matches the desired output resolution. You can check this by going to&#160;Composition&#160;in the menu bar and selecting&#160;Composition Settings.</p><p>Title Safe Area</p><p>We discussed this at the beginning of this course. The title safe area is a rectangular area used to define the area visible on the screen. Depending on where you will be viewing your videos, make sure you take the title safe area into consideration while making your edits to ensure you haven&#39;t framed your subjects in a way that they get cropped or are out of the frame.</p><p>Frame Rate</p><p>Make sure that the frame rate of your composition matches the desired output frame rate. You can check this by going to&#160;Composition&#160;in the menu bar and selecting&#160;Composition Settings. Make sure that you select the proper frame rate for your video. Frame rate isn&#39;t just a consideration in terms of the quality of the video output but also in terms of the bandwidth and playback ability. If you are working with heavy files that have a high frame rate, reducing the frame rate can help improve playback when you have limited bandwidth. However, most videos look better when they use their original frame rates. So, you can vary this value based on the type of output you are exporting and where you will be using those videos. The same goes for frame size. If you increase the frame size, your video quality gets affected.</p><p>Work Area</p><p>Check that the work area of your composition covers the entire duration of your animation or video. You can adjust the work area by dragging the handles in the timeline panel.</p><p>By checking these elements before rendering, you can ensure that your output is high quality and meets your project&#39;s requirements.&#160;This can save time and prevent issues during the rendering and exporting process.</p><p>Imagine you are a video editor working on an advertising video for a client.&#160;You&#39;ve spent a lot of time editing the video, adding special effects and transitions to make it appealing to the audience.&#160;You have also adjusted the color grading to make it look perfect.&#160;Before you export the final version of the video, you want to ensure that there are no errors in the video that could negatively impact the quality of the video.&#160;You will check that there are no typos or spelling mistakes.&#160;You will go through the entire timeline of the video.&#160;You will glance through for any unintended gaps or overlaps between clips.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b5515a52f6c3964d58824762398a2ab3','adobe-after-effects-m7-l3-lesson-2','6a5bbe1c87dd51cd447a2a58eb13c407','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Archiving a Project</h3><p>Archiving a Project</p><p>After Effects helps you manage all of the files associated with your projects in an efficient manner, this is especially useful when you work with large projects with multiple clips and media formats.&#160;Sometimes, you need to transfer your project files to another device or share it with a team member when working together.&#160;In these instances, always&#160;archive&#160;your project first so that all the files and assets associated with your project are saved in a single location.</p><p>When you archive a project in After Effects, a copy of the project file and its associated assets are saved to an external location.&#160;This can be useful for backup or for sharing the project with others.</p><p>Here are the steps to archive a project in After Effects:</p><p>Save your project file:&#160;Start by saving your project file.&#160;Go to the&#160;File&#160;menu and select&#160;Save&#160;to save your project file.</p><p>Collect the assets:&#160;Next, you must collect all your project assets.&#160;Open the&#160;File&#160;menu, and select&#160;Dependencies&#160;&gt;&#160;Collect Files.</p><p>In the&#160;Collect Files&#160;dialog box, select the options you want, such as which assets to include and where to save the collected files.&#160;Click&#160;Collect&#160;to save the assets to the chosen location.</p><p>Compress the files:&#160;After collecting the files, you can compress them into a single archive file to save space and make sharing easier.&#160;You can use software like WinZip or WinRAR to compress the files.</p><p>Save the archive:&#160;Save the compressed archive to a secure external location, such as an external hard drive or cloud storage service.</p><p>Once you have archived your After Effects project and its associated assets, you can easily share or create a backup of your work.</p><p>Welcome to this video on Packaging Files!</p><p>In this video, you will learn how to package all the files related to your After Effects project. This helps you collect all the source files in one location, making it easy to backup your files or share it with other members of your team.</p><p>I have my After Effects project open here. To package all the files together, first open the File menu, select Dependencies, and click Collect Files. You will see the Collect Files popup. You can select which files you want to collect. For instance, you may only want to collect files for a specific composition, or only the project files that will exclude any external files in your project. For now, let&#39;s select All and click Collect.</p><p>You now need to select a location where the package will be created. Let&#39;s click Save. All the files of your project will be collected, and saved in the folder.</p><p>You will see a report of the package that is generated as a text file. This file shows you all the components of this package, if they have any errors, and other details.</p><p>Here are all the project files, which includes the After Effects project, and a Footage folder that contains all of the footage I used in this project. I can now ZIP and backup or share this file as required.</p><p>Again, this is a very useful method of archiving or backing up projects in After Effects.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3434acb81eff6ab351c345adce677d0e','adobe-after-effects-m7-l4-lesson-3','6a5bbe1c87dd51cd447a2a58eb13c407','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Exporting Frames</h3><p>Exporting Frames</p><p>When you export a file from After Effects, there are several vital things to remember to ensure you get a high-quality output that meets your project&#39;s requirements.&#160;Here are some essential things to consider:</p><p>Click each term to learn more.</p><p>Output Format</p><p>Select the appropriate output format for your project. Consider the intended use of the final file, such as web or broadcast, and choose a format that is compatible with that use.</p><p>Resolution</p><p>Choose the appropriate resolution for your project. This should match the resolution of your composition and the desired output size.</p><p>Bitrate</p><p>Choose the appropriate bitrate for your project. This determines the quality and size of the output file. Higher bitrates will result in larger files but also higher quality.</p><p>Compression</p><p>Use compression if necessary to reduce the size of the output file. This is particularly important for video files, where large file sizes can cause problems with playback and streaming.</p><p>Audio Settings</p><p>Adjust the audio settings, such as selecting the appropriate sample rate and bit depth.</p><p>Color Space</p><p>Choose the appropriate color space for your project. This should match the color space of your composition and the intended output.</p><p>Render Settings</p><p>Set the appropriate render settings, such as motion blur and depth of field. These can affect the quality and appearance of the final output.</p><p>Output Module</p><p>Select the appropriate output module for your project. This determines the settings for the final output file.</p><p>Considering these key points when exporting a file from After Effects, you can ensure that the output is high quality and meets your project&#39;s requirements.&#160;This can save time and prevent problems during the rendering and exporting process.</p><p>To export a single frame in After Effects, follow these steps:</p><p>In the&#160;Composition&#160;panel, navigate to the frame you want to export.</p><p>Click on the Composition panel menu button (the three lines on the top-right corner of the panel).</p><p>From the menu, select&#160;Save Frame As&#160;&gt;&#160;File.</p><p>In the&#160;Save Frame As&#160;dialog box, select the location where you want to save the file and enter a name for the file.</p><p>Choose the file format you want to use from the&#160;Format&#160;drop-down list.</p><p>Click the&#160;Render Settings&#160;button to adjust the settings for the file format you&#39;ve chosen.</p><p>Click the&#160;Render&#160;button to export the single frame.</p><p>After the frame is rendered, you can find the exported single frame in your specified location.</p><p>Suppose you are working on an animated logo for a company and want to export the logo animation.&#160;After Effects allows you to extract specific frames from your video and gives you flexibility to animate the different sections of the video.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c33af4beae3aeea48d40b6f96c0e9a96','adobe-after-effects-m7-l5-lesson-4','6a5bbe1c87dd51cd447a2a58eb13c407','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Exporting a Composition</h3><p>Exporting a Composition</p><p>There are two ways in which you can render your compositions in After Effects.&#160;You can either use the render queue in After Effects, or you can use the Adobe Media Encoder using the render options you selected in the Render Queue panel.</p><p>Using the Render Queue</p><p>Adobe After Effects enables you to easily render and export your projects using the render queue.&#160;To export your compositions, follow these steps:</p><p>Click each step to learn more.</p><p>Next Tab</p><p>Step 1</p><p>Open your composition in After Effects.&#160;Open the&#160;Composition&#160;menu and select&#160;Add to Render Queue.</p><p>Step 2</p><p>Next, you can select the output module and format you want to export in the Render Queue panel. For example, you can select H.264 or ProRes.</p><p>Step 3</p><p>You also have the option to adjust settings such as resolution, frame rate, and bit rate to optimize the output file.</p><p>Step 4</p><p>Once you have made all your selections, select the&#160;Output To&#160;option and choose where you want to save the output file.</p><p>Step 5</p><p>Once you have set your export settings, click the&#160;Render&#160;button to begin the export process. You can monitor the progress of the export in the render queue panel. Once the file has been rendered, it will be saved in your selected location.</p><p>One advantage of using the render queue to export your compositions is that it gives you precise control over the export settings.&#160;This lets you optimize the output file for your specific needs.&#160;You can also export multiple versions of the same composition with different settings for different uses.&#160;You can compare the different versions and choose the best one, or you may want to use them for different purposes.&#160;It is important to note that the render queue can tie up your computer&#39;s resources while exporting, so be mindful of your workflow and prioritize your tasks accordingly.</p><p>Welcome to this video on the Render Queue!</p><p>In this video, you will learn how to render your After Effects videos using the Render Queue. During this process, After Effects will create the final output video within the program using an internal render queue. Note that using this method, you will only have a limited set of file types that you can choose from to render your video. Additionally, these video files are usually very large files.</p><p>Let&#39;s render this project using the Render Queue. Open the File menu, select Export, and select Add to Render Queue. This will load the render queue at the bottom of your workspace. There are some settings here that you can modify.</p><p>Click Best Settings to load the Render Settings popup window. Here, you can modify various settings to set the quality of the output video. Ideally, you should leave the Quality setting at Best. You can change this to Draft if you are sharing an interim version of your project for internal review or review with a client. Similarly, it is ideal to choose full resolution, but you can change this to whatever resolution you require for your video. Once you are done, click OK.</p><p>Now that you have set the basic settings, it’s time to choose the format of the output video. Click this link next to Output Module. You can now choose all the specific settings for your video. First, choose from many available format options for your video. You can see that there are formats for exporting videos, audio files, image sequences, and more. For videos, you can choose between AVI and QuickTime formats, which can generate very large files. In comparison, the Adobe Media encoder gives you many more format options.</p><p>You can also modify many other settings. For now, let’s leave those settings as they are and click OK.</p><p>Next, you need to choose the location where your output file will be stored by clicking the Output To link. Choose a location on your computer, and then click the Render button here to start rendering the video. You can track the status of the rendering using this progress bar.</p><p>Once the video is rendered, you can check the output file. Here, I rendered a 10-20 second video and it created a file of more than 300 MB which is quite large. So, this rendering process is not useful if you want to upload your videos anywhere like on social media sites. It’s more suited for rendering for draft purposes.</p><p>Using Adobe Media Encoder</p><p>Rendering and exporting your movies using the Adobe Media Encoder is a simple and efficient way to export your compositions.&#160;Here are the steps:</p><p>With your composition open, click the&#160;Composition&#160;menu and select&#160;Add to Adobe Media Encoder Queue.</p><p>The Adobe Media Encoder appears and will show your composition loaded into the queue.</p><p>You can now select the format you want to export to, for example, H.264 or ProRes.</p><p>Make any other changes you want to the resolution, frame rate, and bit rate to optimize the output file.</p><p>Once you are done, click&#160;Output Name&#160;and rename the file, and then choose a location to save it.</p><p>After choosing your export settings, click the&#160;Start Queue&#160;button to begin the export process.&#160;You can monitor the progress of the export in the queue window, and once it&#39;s complete, the output file will be saved in the location you selected.</p><p>A major advantage of using the Media Encoder to export your compositions is that it allows you to continue working while the export continues in the background.&#160;This means you can save time and increase your productivity by queuing up multiple exports at once.&#160;You can also choose from a wide range of presets in the Media Encoder and choose different output formats and devices, making it easy to optimize your exports for different platforms and purposes.</p><p>Welcome to this video on the Media Encoder Queue!</p><p>In this video, you will learn to use the Adobe Media Encoder to render your video files in After Effects. You can render your files in many different formats.</p><p>First, open the File menu and select Export, and click Add to Adobe Media Encoder Queue. This may take a little while to open, so we’ll skip ahead. You can see the file has been added to the queue. Let&#39;s set the export settings by clicking this link. First, choose the file format from this drop-down list. As you can see, there is an extensive list <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('866af043d7792b5cb71912116a22bdde','adobe-after-effects-m7-l6-lesson-5','6a5bbe1c87dd51cd447a2a58eb13c407','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Certification</h3><p>Certification</p><p>License:&#160;All Rights Reserved</p><p>We’ve reached the end of this course on After Effects.&#160;By now, you should have a good grasp on all of the fantastic features available in After Effects and how you can use them to do everything from combining multiple video clips to adding effects, animations, text animations, and much more to create original, innovative videos.</p><p>All of this training has been put in place to enable you to enhance your skills and get certified as an Adobe Certified Professional.&#160;The certification is a globally recognized stamp on your profile that demonstrates your proficiency and understanding of digital skills.</p><p>In order to earn this certification, you will need to pass a rigorous examination administered through a Certified Authorized Testing Center (CATC).&#160;In this final lesson, we’ll give you an idea of what the structure of the examination will be like, what to expect, and how you can prepare yourself to ace the exam!</p></section><section><h3>Exam Structure and Walk through</h3><p>Exam Structure &amp; Walk-through</p><p>The After Effects exam is a timed examination comprised of two sections.&#160;You will have 50 minutes to complete both these sections.</p><p>Note:&#160;All exams undergo continuing psychometric analysis and the number of questions are subject to change.</p><p>These exams evaluate both your knowledge and skills using two types of questions:</p><p>Linear questions:&#160;These are the standard multiple-choice, true/false or matching type questions that assess your knowledge and understanding of basic concepts.</p><p>Performance-based questions:&#160;These questions will have you perform steps in a simulated After Effects application so you can demonstrate your skills in the actual work environment.</p><p>Let’s look at how these two sections will be structured.</p><p>Tutorial:&#160;You will start off with a tutorial introducing you to the exam, how to navigate it, and how to answer questions.&#160; This is not a timed task, so take your time to read through and understand the rules.</p><p>Questions:&#160;This is the first section that contains linear questions.&#160;The timer starts as soon as you begin this section.</p><p>Section Summary:&#160;Once you complete a section and submit the questions, you will see a summary that allows you to review only the questions.&#160;You cannot revisit questions once submitted, so make sure they are final.</p><p>Tutorial:&#160;The timer is paused for a tutorial on how to proceed with the next section of the exam.&#160;Again, take your time to understand the rules.</p><p>Tasks:&#160;This second section contains performance-based questions or tasks that you will need to perform in a virtual After Effects environment.&#160;The timer will resume where you left off as soon as you begin this section.</p><p>Section Summary:&#160;Once you complete the second section, you can review the tasks you just completed in the Section Summary page.</p><p>Leave Feedback:&#160;After you have submitted both sections, you can leave feedback on the exam, tasks or questions.</p><p>License:&#160;All Rights Reserved</p><p>Note that during the performance-based section of your exam, a few features in your simulated After Effects application will be disabled, including:</p><p>Open</p><p>Help</p><p>Adobe Bridge</p><p>Adobe Stock</p><p>CC Library</p><p>Only use the Certification Test workspace to perform your tasks (unless specified otherwise).</p><p>The best way to prepare yourself for the After Effects examination is to practice, practice, practice!&#160;The projects you’ve completed throughout this course are a great way for your to do this.&#160;Re-do the projects with different video and audio clips and use different tools to perform the tasks.&#160;Try out different types of edits, transitions, and effects.&#160;Explore After Effects and practice using all of the different tools.</p><p>The internet is also a great source of inspiration and a well of information from other video developers who have applied their After Effects skills.&#160;Explore these resources to see examples of how others have edited their videos, take a look at sample projects, or just try to identify how you can replicate different effects and animations that you have seen applied in the videos you watch.&#160;Finally, share and discuss your work and creative ideas with your classmates and friends.&#160;Working collaboratively is a great way to discover new creative directions and explore all that After Effects has to offer.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('59b17da71fac445fc0a391cd5e4dceb0','adobe-after-effects-m7-l7-summary','6a5bbe1c87dd51cd447a2a58eb13c407','Summary','text',12,'<h2>Summary</h2><section><h3>Summary</h3><p>Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Publishing Digital Media.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Check ed a composition for errors and verified specifications.</p><p>Archived a project.</p><p>Exported frames.</p><p>Exported a composition.</p><p>Prepared for the Adobe Certified Professional Exam.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4efa15e30b56eb0f9c0a869ceba13f48','adobe-after-effects-m7-l8-module-7-quiz','6a5bbe1c87dd51cd447a2a58eb13c407','Module 7 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Publishing Digital Media. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,7,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('945d4117e57cb1051e0a9d368bc2b66b','adobe-after-effects-module-8','548316f2bc2d7ea184c46fc23dac5160','Module 8: Course Project Empty',8) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('20152a6f06b3a5a2603571d27ba99794','adobe-after-effects-m8-guided-learning','945d4117e57cb1051e0a9d368bc2b66b','Guided Learning','text',15,'<h2>Course Project Empty</h2><p>Build and apply the essential concepts in this module through guided explanation, practical examples, and reflective activities.</p>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('e577ce19e2a5242b130616ec686f8fee','adobe-after-effects-module-9','548316f2bc2d7ea184c46fc23dac5160','Module 9: Course Wrap Up Summary',9) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3e70bd62f79077bf9c4fbdfb13e57d99','adobe-after-effects-m9-l1-course-wrap-up-summary','e577ce19e2a5242b130616ec686f8fee','Course Wrap Up Summary','text',12,'<h2>Course Wrap Up Summary</h2><section><h3>Course Summary</h3><p>Course Wrap Up</p><p>We&#39;re at the last leg of our exciting After Effects journey!&#160;We hope this course has equipped you with the knowledge needed for you to master the learning objectives of this course.&#160;After Effects is a tool that is best learned by doing, which is why we gave you a ton of videos and activities to practice your skills.&#160;You should now be ready for the final exam.</p><p>Our main objective on this journey has been to push away the veil of mystery from After Effects and enable you to discover all of the creative possibilities it has.&#160;Keep exploring After Effects and use the resources to discover more interesting, creative ways to use After Effects.&#160;Whether you choose to pursue a career in video development and editing or not, this course has given you some fantastic skills that you can still apply in other fields or even as a hobby.</p><p>Complete the final exam on the next page and submit it to complete this activity.</p></section><section><h3>Final Exam</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe After Effects lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe After Effects interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9298a67933550b661468172d4c278373','adobe-after-effects-course-mastery-assessment','e577ce19e2a5242b130616ec686f8fee','Course Mastery Assessment','assessment',30,'<h2>Course mastery assessment</h2><p>Bring together knowledge and application from the complete course. Achieve at least 80% to satisfy the assessment requirement for certification.</p>',NULL,1,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO assessments (id,slug,course_id,title,pass_mark,questions) VALUES ('d2ac2ae7fa19fbbbed03e55b276b0df0','adobe-after-effects-course-mastery-assessment','548316f2bc2d7ea184c46fc23dac5160','Adobe After Effects Course Mastery Assessment',80,CAST('[{"id":"adobe-after-effects-course-mastery-assessment-q1","type":"multiple-choice","prompt":"Before starting a practical task in Visual Effects and Motion Graphics 1, which action best demonstrates professional judgement?","options":["Clarify the intended outcome, constraints, and success criteria before choosing tools.","Choose the fastest tool and define the goal afterward.","Copy the first available example without checking its fit.","Begin production immediately and leave requirements for final review."],"answer":"Clarify the intended outcome, constraints, and success criteria before choosing tools.","explanation":"Strong practice begins with a clear outcome, constraints, and measurable success criteria.","clue":"Think about what must be understood before execution begins."},{"id":"adobe-after-effects-course-mastery-assessment-q2","type":"multiple-choice","prompt":"A first attempt in Visual Effects and Motion Graphics 2 does not meet the requirement. What is the strongest next step?","options":["Compare the result with the criteria, identify the cause, revise, and test again.","Submit the attempt unchanged because the task is complete.","Replace the criteria with measures the attempt already meets.","Discard all evidence and restart without diagnosing the issue."],"answer":"Compare the result with the criteria, identify the cause, revise, and test again.","explanation":"An evidence-led improvement cycle diagnoses the gap before a focused revision and retest.","clue":"Use feedback and evidence to improve the next attempt."},{"id":"adobe-after-effects-course-mastery-assessment-q3","type":"multiple-choice","prompt":"Which evidence most credibly demonstrates applied competence in Project Setup and Interface?","options":["A completed work sample with decisions, checks, feedback, and reflection documented.","A claim that the topic was understood without a work sample.","A list of tools with no explanation of how they were used.","An unfinished draft that has not been checked against requirements."],"answer":"A completed work sample with decisions, checks, feedback, and reflection documented.","explanation":"Competence is best demonstrated through completed, reviewed evidence and reflective reasoning.","clue":"Choose evidence that shows both the result and how quality was established."},{"id":"adobe-after-effects-course-mastery-assessment-q4","type":"multiple-choice","prompt":"When work in Organizing Projects could affect people, data, safety, or the environment, what should the learner do?","options":["Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","Proceed without checks when the intended outcome is positive.","Treat ethical and safety considerations as optional after delivery.","Hide known limitations so stakeholders remain confident."],"answer":"Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","explanation":"Responsible practice makes risk, consent, standards, and safeguards part of the work itself.","clue":"Professional quality includes the impact of the work, not only the output."},{"id":"adobe-after-effects-course-mastery-assessment-q5","type":"multiple-choice","prompt":"How should a learner transfer skills from Visual Elements Part 1 to a new workplace or project context?","options":["Analyse the new context, adapt the method, test assumptions, and evaluate the result.","Repeat the original steps unchanged regardless of context.","Use only familiar methods and ignore new constraints.","Wait for a complete example to copy before making any decision."],"answer":"Analyse the new context, adapt the method, test assumptions, and evaluate the result.","explanation":"Transfer requires adapting core principles to new constraints and validating the result.","clue":"Core principles remain useful, but their application must fit the new context."}]' AS JSON)) ON DUPLICATE KEY UPDATE title=VALUES(title),pass_mark=VALUES(pass_mark),questions=VALUES(questions);
