INSERT INTO modules (id,slug,course_id,title,position) VALUES ('5248db68db770e53348e239d45581d05','adobe-animate-module-0','abaa7c52a53a919b464dd650652e62ff','Module 0: Introduction, Purpose, Objectives, Summary',0) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('68cfbbd006832cd73944b0131ee8e58d','adobe-animate-m0-l1-teacher-course-resource','5248db68db770e53348e239d45581d05','Teacher Course Resource','text',12,'<h2>Teacher Course Resource</h2><section><h3>Adobe Animate Pacing Guide</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>Adobe Animate Blended Learning Guide 1</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>Adobe Animate Answer Key</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>Translating the Language in a Course Page</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>How to View Students Quiz and Concept Check Answers 2</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>How to Recalculate and Sync Student</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>How to View Students Participation</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Animate lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Animate interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('ab8a9f1e8e5e90cd35d5413ec7a27629','adobe-animate-module-1','abaa7c52a53a919b464dd650652e62ff','Module 1: Course Modules',1) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('190aaaecda7f0ca4d3997ab55e4082e0','adobe-animate-m1-l1-module-0','ab8a9f1e8e5e90cd35d5413ec7a27629','Module 0','text',12,'<h2>Module 0</h2><section><h3>Course Introduction and Overview</h3><p>Course Intro Video</p><p>Do you remember that feeling of joy and wonder, watching cartoons as a child, or even now playing vidoe games with your friends? Animations transport you to magical worlds from &#160;your wildest imagination, and they&#39;re all around us in movies, TV shows, ads, games, and media. Whether you&#39;re an artist wanting to explore a new creative medium, or you&#39;re interested in pursuing a career in digital media, this course will unlock a whole new world for you.</p><p>Adobe Animate is a powerful, comprehensive tool that can create all sorts of animated content. And in this course, you&#39;ll learn everything you need to know to start animating with this industry standard software. You&#39;ll learn the core principles of animation, illustration, and design using various tools available in the Adobe Animate workspace. You&#39;ll learn how to transform simple shapes into characters and bring them to life.</p><p>This course also prepares you for professional certification in multi-platform animation. Using Adobe Animate, real world examples, video tutorials, and practice questions will help you build a solid foundation for a career in animation.</p><p>Course Navigation</p><p>In this Course Navigation, we’ll go over the overall course structure and what you can expect in each of the modules in this course.</p><p>Before You Begin</p><p>Before we go over the navigation and structure of the course, here are a few important things you should do:</p><p>When you start the course, make sure you have Adobe Animate open on your computer.&#160;You can follow along with the reading material and instructional videos and explore Adobe Animate as you learn about it.</p><p>Make sure you have Office suite programs or basic word processing programs installed on your computer, as you will require them for your project work.</p><p>Navigating the Course</p><p>Within each section, you can easily navigate between the pages either with the menu on the left or with the left/right arrows on the bottom.&#160;This allows you to move between PAGES within each section.&#160;Once you are done with all the pages in a section, you can either click at the top on the title of the course, or you can click at the very bottom of the page to the next section.&#160;It’s very important to make sure you finish every page in a section BEFORE moving to the next section.</p><p>(opens in a new tab)</p><p>This image shows a typical course page with navigation bars on the left side as well as the bottom.&#160;The course number, title, and content will vary from course to course.</p><p>License:&#160;All Rights Reserved</p><p>Course &amp; Module Structure</p><p>The course is divided into 8 modules, with an initial introductory module that you are now taking.&#160;This introductory module is intended to familiarize you with the course structure and explain some basic but important concepts about sources, plagiarism, and the syllabus.</p><p>Each module of the course will be structured as shown in the diagram here.</p><p>Each module has an introduction, 4-5 lessons, and a summary and quiz at the end.&#160;We begin each module with an introductory video into the topics that will be covered in that module.&#160;You can use the video controls to adjust the volume, captions, and speed of the video based on your preferences.</p><p>Each module lesson covers a different topic.&#160;Lessons contain multiple pages of instructional content and instructional videos.&#160;Follow along and explore Adobe Animate yourself as you learn about its features and tools in each lesson.</p><p>As you will learn in the syllabus, the introduction, video, and reading pages are graded on participation, meaning you get credit for going through every page and activity in the module.</p><p>After each lesson is a concept check or reflection where you&#39;ll either input an answer or work with flashcards or maybe a sorting exercise to review and firm up the concepts that were taught in that section.&#160;The reflections are either journal entries or discussion prompts.&#160;To participate in a class-wide discussion, you’ll click on a link to read the questions or prompts and then participate in the discussion by adding a new discussion topic and eventually commenting on posts from other students.&#160;You&#39;ll see this repeat itself throughout all the sections.</p><p>Every module ends with a module summary.&#160;Once you are finished with each lesson, you will need to complete a project and a quiz.</p><p>The project gives you a chance to practice what you learned in that module in Adobe Animate.&#160;Every module will have a different project and will give you a chance to be creative, explore all the tools yourself, and learn by doing.</p><p>Finally, the module quiz is pretty straightforward as they are mostly multiple-choice and true/false questions.</p><p>Many aspects of grading or other features of the course may be changed by your individual schools and instructors.&#160;So please refer to the updated instructions or grading procedures that they provide.</p><p>For additional help, you can reach out to your instructor or contact the help desk of your LMS.</p><p>Course Objectives</p><p>In this course, students will:</p><p>Determine whether content is relevant to the purpose, the audience,&#160;and their needs.</p><p>Identify requirements based on how the animations or interactive&#160;content will be delivered, distributed, and/or consumed.</p><p>Demonstrate knowledge of techniques for communicating ideas about&#160;design plans with peers and clients.</p><p>Demonstrate knowledge of basic project management concepts.</p><p>Identify legal and ethical considerations for using third-party content and obtain permission to use images.</p><p>Demonstrate knowledge of animation terminology and interactive&#160;media.</p><p>Define key terms related to multiplatform animation.</p><p>Explain the elements and principles of design and common design&#160;techniques.</p><p>Identify and use common typographic adjustments to create contrast,&#160;hierarchy, and enhanced readability/legibility.</p><p>Create a new document with appropriate settings for a new project and&#160;manage settings for specific project needs.</p><p>Identify and customize elements on the Animate workspace and&#160;configure application preferences.</p><p>Navigate a document.</p><p>Customize toolbar and timeline tools.&#160;Use <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Animate lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Animate interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('60f622b88c073db5ea1b13dd5e978587','adobe-animate-m1-l2-4-midterm-exam','ab8a9f1e8e5e90cd35d5413ec7a27629','4 Midterm Exam','text',12,'<h2>4 Midterm Exam</h2><section><h3>Midterm Exam Activity</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>Midterm Exam Activity.pdf</h3><p>Midterm Exam</p><p>Answer Key:Off</p><p>ABCABC</p><p>Directions:&#160;Read each question carefully and then choose the correct answer.</p><p>To legally use an image protected by copyright in your animation, what would you need to do?</p><p>Obtain permission and pay a licensing fee to use the asset under specific conditions</p><p>Use it without telling the artist</p><p>You cannot use any copyright-protected images in your animations</p><p>True or false?&#160;The triangle at the corner of some tools in the Tools panel indicates that these tools can only be used in ActionScript documents.</p><p>True</p><p>False</p><p>What is the Rotation tool used for?</p><p>To quickly move around the stage without changing magnification</p><p>To temporarily rotate the stage</p><p>To quickly scrub through the animation</p><p>What does the View area of the Tools panel contain?</p><p>Tools that allow you to zoom and pan in the application window.</p><p>All the selection, drawing, and painting tools.</p><p>Modifiers for whichever tool you have selected.</p><p>You are designing an animated virtual guided tour of a city.&#160;What platform would be best suited for your project and why?</p><p>WebGL because it allows you to create more complex animations.</p><p>VR because you can create a virtual world.</p><p>Adobe AIR as it is best suited for this type of project.</p><p>What are display fonts?</p><p>Formal, traditional fonts used mostly in print media.</p><p>Modern, cleaner font used on computers.</p><p>Stylistic fonts used for decorative purposes.</p><p>In an animated movie, when a running character suddenly stops running, its clothes keep moving for a while before stopping.&#160;Explain which principle of animation is used here.</p><p>The principle of exaggeration is used to emphasize or make an action more exciting.</p><p>Anticipation is used to prepare the viewer for a major action.</p><p>Follow-through and overlapping action to give a sense of movement and inertia.</p><p>What can you achieve with a VFX presentation?</p><p>Give clients an idea of what they can expect</p><p>Pitch new projects to clients</p><p>Ensure clients make payments on time</p><p>__________ is a transition method used to slowly transition in or out of motion in animations.</p><p>Tweening</p><p>Keyframing</p><p>Easing</p><p>___________ are rough animations that are created based on the storyboard.</p><p>Thumbnails</p><p>Wireframes</p><p>Animatics</p><p>What types of paint brushes can you create in Animate?</p><p>Art brushes or pattern brushes</p><p>Paint brushes or fill brushes</p><p>Texture brushes or pattern brushes</p><p>What is the purpose of guides in a document?</p><p>They can be used to view dimensions or spacing between objects on the stage</p><p>They can be used to align or arrange objects on the stage</p><p>They can be used to scale objects</p><p>True or false?&#160;Understanding factors related to the target audience helps determine the design approach for animation projects.</p><p>True</p><p>False</p><p>What is the unity/harmony principle of visual design?</p><p>How well the elements of design work together based on the connection between the elements</p><p>Theory of how we perceive things and subconsciously group things together</p><p>Placing emphasis or importance on specific items in a design</p><p>In this method, the video is kept external, and the video plays in real time from the server to the client.</p><p>Progressive download from a web server</p><p>Stream video using Adobe Media Server</p><p>Embed video</p><p>Match the element of design with its definition.ShapesForms</p><p>What is meant by user interaction?</p><p>How a user feels when they use interactive media</p><p>What the user sees when they use interactive media</p><p>Actions the user makes like clicking, scrolling, or entering text</p><p>What are grouped panels?</p><p>Panels that appear in tabs</p><p>Undocked panels that can be moved freely</p><p>Panels that are nested within other panels</p><p>This tab shows the properties of the current tool that is selected.</p><p>Tool tab in the Properties panel</p><p>Object tab in the Properties panel</p><p>Frame tab in the Properties panel</p><p>Which of these can help you understand your audience better?</p><p>Researching the target audience</p><p>Paying the audience to watch the animation</p><p>Conducting surveys</p><p>Identifying audience goals and needs</p><p>How can you add guides to your document?</p><p>Drag in from the ruler in the edges of the stage area</p><p>Click File and select Guides</p><p>Open the Properties panel and select Add Guide</p><p>What is the purpose of conducting surveys before beginning an animation project?</p><p>To understand the preferences of the audience</p><p>To determine if the project will be financially viable</p><p>To collect contact information from the audience</p><p>In this phase of the project, a timeline is created that details when each task will be completed.</p><p>Scheduling</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Animate lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Animate interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('33b6beab37b235618b22d932aa7a3fdf','adobe-animate-m1-l3-course-wrap-summary-and-final-exam','ab8a9f1e8e5e90cd35d5413ec7a27629','Course Wrap Summary and Final Exam','text',12,'<h2>Course Wrap Summary and Final Exam</h2><section><h3>Course Wrap Up Summary</h3><p>Course Wrap Up_Summary</p><p>We&#39;re at the last leg of our exciting Animate journey!&#160;We hope this course has equipped you with the knowledge needed for you to master the learning objectives of this course.&#160;Animate is a tool that is best learned by doing, which is why we gave you a ton of videos and activities to practice your skills.&#160;You should now be ready for the final exam.</p><p>Our main objective on this journey has been to push away the veil of mystery from Animate and enable you to discover all of the creative possibilities it has.&#160;Keep exploring Animate and use the resources to discover more interesting, creative ways to use Animate.&#160;Whether you choose to pursue a career in animation or not, this course has given you some fantastic skills that you can still apply in other fields or even as a hobby.</p><p>Complete the final exam on the next page and submit it to complete this activity.</p></section><section><h3>Final Exam Part 1</h3><p>Final Exam - Part 1</p><p>Answer Key:Off</p><p>ABCABC</p><p>Directions:&#160;Read each question carefully and then choose the correct answer.</p><p>What is meant by user interaction?</p><p>How a user feels when they use interactive media</p><p>What the user sees when they use interactive media</p><p>Actions the user makes like clicking, scrolling, or entering text</p><p>You want to draw multiple clouds in the sky that are of the same shape but different sizes.&#160;How can you do this efficiently in Animate?</p><p>Draw a cloud, copy and paste it, and scale it, and repeat this as many times as necessary</p><p>Select ‘Scale proportionately’ when you convert the cloud to an art brush</p><p>Draw each cloud in the size required</p><p>True or false?&#160;Understanding factors related to the target audience such as their age group is an important pre-requisite to working on an animation project.</p><p>True</p><p>False</p><p>How can you add guides to your document?</p><p>Drag in from the ruler in the edges of the stage area</p><p>Click File and select Guides</p><p>Open the Properties panel and select Add Guide</p><p>You are designing animated banner ads for a company.&#160;What platform would be best suited for your project and why?</p><p>WebGL because it allows you to create more complex animations.</p><p>ActionScript as it allows you to create dynamic links.</p><p>HTML5 Canvas as it is best suited to create interactive web content.</p><p>What does it mean when an asset is protected by copyright?</p><p>It has been locked in a secure location</p><p>Its rights have been purchased by a person already</p><p>It is legally protected from being modified, copied, shared, or used without explicit permission</p><p>What does the Main tools area of the Tools panel contain?</p><p>Tools that allow you to zoom and pan in the application window.</p><p>All the selection, drawing, and painting tools.</p><p>Modifiers for whichever tool you have selected.</p><p>True or false?&#160;In Animate, you cannot expand or collapse panels.</p><p>True</p><p>False</p><p>What are grouped panels?</p><p>Panels that appear in tabs</p><p>Undocked panels that can be moved freely</p><p>Panels that are nested within other panels</p><p>What is the purpose of conducting surveys before beginning an animation project?</p><p>To understand the preferences of the audience</p><p>To determine if the project will be financially viable</p><p>To collect contact information from the audience</p><p>This Fluid Brush setting will help you avoid minor variations or fluctuations that may occur when you draw lines or strokes.</p><p>Stabilizer</p><p>Curve smoothing</p><p>Velocity</p><p>In this method, the video is kept external, and the video plays in real time from the server to the client.</p><p>Progressive download from a web server</p><p>Stream video using Adobe Media Server</p><p>Embed video</p><p>What are sans serif fonts?</p><p>Formal, traditional fonts used mostly in print media.</p><p>Modern, cleaner font used on computers.</p><p>Stylistic fonts used for decorative purposes.</p><p>The frames between ____________ are known as in-betweens.</p><p>Guides</p><p>Symbols</p><p>Keyframes</p><p>Which of these may a VFX presentation include?</p><p>Breakdown reels</p><p>Concept art</p><p>3D animation</p><p>In this phase of the project, a timeline is created that details when each task will be completed.</p><p>Scheduling</p><p>Budgeting</p><p>Risk management</p><p>What is tracking in typography?</p><p>The spacing between all the characters in a word</p><p>The spacing between two lines of text in a paragraph</p><p>The positioning of text with respect to the margins</p><p>True or false?&#160;You can add, remove, rearrange, or combine the tools in the Tools panel however you want in Animate.</p><p>True</p><p>False</p><p>What is the Time Scrub tool used for?</p><p>To quickly move around the stage without changing magnification</p><p>To temporarily rotate the stage</p><p>To quickly scrub through the animation</p><p>What is the purpose of grids in a document?</p><p>They can be used to view dimensions or spacing between objects on the stage</p><p>They can be used to scale objects</p><p>They can be used to position or align elements in your composition</p><p>___________ are a series of images or illustrations that depict key moments and actions in a story.</p><p>Storyboards</p><p>Scripts</p><p>Mood boards</p><p>True or false?&#160;You can use text to create masking effects in Animate.</p><p>True</p><p>False</p><p>Which of these statements is true for pattern brushes?</p><p>Objects you draw will be stretched along the path you draw</p></section><section><h3>Final Exam Part 1</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>Final Exam Part 2</h3><p>Final Exam - Part 2</p><p>Answer Key:Off</p><p>ABCABC</p><p>Directions:&#160;Read each question carefully and then choose the correct answer.</p><p>What does it mean if a frame has a hollow circle on it?</p><p>It is a property keyframe</p><p>It is a blank keyframe</p><p>It is a motion tween</p><p>What is the advantage of embedding fonts in your Animate file?</p><p>The font will always display on any location the animation is played.</p><p>The file size will remain small.</p><p>The animation will load faster.</p><p>Which of the following Al<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Animate lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Animate interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('41943556b3d65903747c784b9440333c','adobe-animate-course-mastery-assessment','ab8a9f1e8e5e90cd35d5413ec7a27629','Course Mastery Assessment','assessment',30,'<h2>Course mastery assessment</h2><p>Bring together knowledge and application from the complete course. Achieve at least 80% to satisfy the assessment requirement for certification.</p>',NULL,3,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO assessments (id,slug,course_id,title,pass_mark,questions) VALUES ('46f6b922318860a1f109e7de03a4074b','adobe-animate-course-mastery-assessment','abaa7c52a53a919b464dd650652e62ff','Adobe Animate Course Mastery Assessment',80,CAST('[{"id":"adobe-animate-course-mastery-assessment-q1","type":"multiple-choice","prompt":"Before starting a practical task in Introduction, Purpose, Objectives, Summary, which action best demonstrates professional judgement?","options":["Clarify the intended outcome, constraints, and success criteria before choosing tools.","Choose the fastest tool and define the goal afterward.","Copy the first available example without checking its fit.","Begin production immediately and leave requirements for final review."],"answer":"Clarify the intended outcome, constraints, and success criteria before choosing tools.","explanation":"Strong practice begins with a clear outcome, constraints, and measurable success criteria.","clue":"Think about what must be understood before execution begins."},{"id":"adobe-animate-course-mastery-assessment-q2","type":"multiple-choice","prompt":"A first attempt in Course Modules does not meet the requirement. What is the strongest next step?","options":["Compare the result with the criteria, identify the cause, revise, and test again.","Submit the attempt unchanged because the task is complete.","Replace the criteria with measures the attempt already meets.","Discard all evidence and restart without diagnosing the issue."],"answer":"Compare the result with the criteria, identify the cause, revise, and test again.","explanation":"An evidence-led improvement cycle diagnoses the gap before a focused revision and retest.","clue":"Use feedback and evidence to improve the next attempt."},{"id":"adobe-animate-course-mastery-assessment-q3","type":"multiple-choice","prompt":"Which evidence most credibly demonstrates applied competence in Introduction, Purpose, Objectives, Summary?","options":["A completed work sample with decisions, checks, feedback, and reflection documented.","A claim that the topic was understood without a work sample.","A list of tools with no explanation of how they were used.","An unfinished draft that has not been checked against requirements."],"answer":"A completed work sample with decisions, checks, feedback, and reflection documented.","explanation":"Competence is best demonstrated through completed, reviewed evidence and reflective reasoning.","clue":"Choose evidence that shows both the result and how quality was established."},{"id":"adobe-animate-course-mastery-assessment-q4","type":"multiple-choice","prompt":"When work in Course Modules could affect people, data, safety, or the environment, what should the learner do?","options":["Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","Proceed without checks when the intended outcome is positive.","Treat ethical and safety considerations as optional after delivery.","Hide known limitations so stakeholders remain confident."],"answer":"Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","explanation":"Responsible practice makes risk, consent, standards, and safeguards part of the work itself.","clue":"Professional quality includes the impact of the work, not only the output."},{"id":"adobe-animate-course-mastery-assessment-q5","type":"multiple-choice","prompt":"How should a learner transfer skills from Introduction, Purpose, Objectives, Summary to a new workplace or project context?","options":["Analyse the new context, adapt the method, test assumptions, and evaluate the result.","Repeat the original steps unchanged regardless of context.","Use only familiar methods and ignore new constraints.","Wait for a complete example to copy before making any decision."],"answer":"Analyse the new context, adapt the method, test assumptions, and evaluate the result.","explanation":"Transfer requires adapting core principles to new constraints and validating the result.","clue":"Core principles remain useful, but their application must fit the new context."}]' AS JSON)) ON DUPLICATE KEY UPDATE title=VALUES(title),pass_mark=VALUES(pass_mark),questions=VALUES(questions);
INSERT INTO courses (id,slug,academy_id,moodle_id,title,description,level,duration,price,is_free,status)
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('a5e7c36d04172b53446f18d9d19730ef','adobe-illustrator-module-0','2eeac88d9b6058d9d55e1dcf25daf550','Module 0: Introduction, Purpose, Objectives, Summary',0) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4bc92f04d7806e1961007b0d6d008fb3','adobe-illustrator-m0-l1-module-0-intro','a5e7c36d04172b53446f18d9d19730ef','Module 0 Intro','text',12,'<h2>Module 0 Intro</h2><section><h3>Course Introduction</h3><p>Course Intro Video</p><p>Over the past decade, graphic design has evolved tremendously. Adobe Illustrator is a highly powerful tool that has been at the forefront of this journey. Whether it’s a company logo, infographic, or business cards, having stunning visuals is essential for any brand. And because of Illustrator’s intelligent design and high-precision tools, anyone can learn to create beautiful designs. If you’re interested in pursuing a career in graphic design, or if you’re simply curious about what working in the design industry is like, then this course is for you! This course will give you the skills to think and execute like a designer, creating your own path of opportunities for your career.</p><p>Course Navigation</p><p>Welcome to this course on Adobe Illustrator!&#160;To get you started in Module 0, we have included the video below, which provides some navigation help and other details about the course.</p><p>Other sections of this Module 0 include the Course Syllabus and a Syllabus Quiz, so read&#160;through the syllabus carefully and thoroughly!</p><p>Hi and welcome to this orientation video for this course. As we go through this video, some details may differ depending on which course you are taking and the learning management system, or LMS, that your school uses, but the overall structure generally stays the same for each course.</p><p>After you complete this navigation tutorial video for module zero you should read through the course objectives, a section on sources and plagiarism, the syllabus, and finally take the syllabus quiz. Now, a few things on navigation. Within each section, you can navigate between pages either with the menu here on the left, or with the left/right arrows near the bottom. Again, that will allow you to move between PAGES within each section. Once you are done with all the pages in a section, you can either select home at the top of the course. Or you can select “Next” at the very bottom of the page to the next section. It’s very important to make sure you finish every page within a section BEFORE moving to the next section.</p><p>Ok, once you are done with Module 0, you&#39;ll move on to start your first module. Within each module there is an introduction, somewhere between 4 and 6 lessons, and then a summary and assessments at the end. First, within the introduction, if you select it, it should look something like this. Each module will start at this page which contains a 30 to 60 second introductory video that will introduce and discuss some of the concepts that you&#39;ll learn and review during this module. Let’s talk about the videos. You can also turn closed captioning on or off by clicking the CC button. Next is the setting button, where you can adjust the speed that the videos will play. Maybe you like to hear things a little faster at 1.25x. Or maybe there is a concept that is difficult, and you would like to slow down. These next two icons allow the video window to pop out, or for the video window to go full-screen. For many videos, there will also be a transcript of the video below.</p><p>The next page is a description of the module. Then we move on to objectives which explains what the student will learn during this module. Next there is typically is a polling question. Sometimes this appears at the beginning of a module and sometimes it appears at the end. But it&#39;s just a way to take a guess or to voice your opinion on a certain issue and you can click on whichever you&#39;d like and see how your answer compares to your classmates.</p><p>You will next come to a vocabulary activity. Most of these will also be at the beginning as a formative assessment, meaning that you aren&#39;t expected to know the answers but take your best guess as this is an ungraded quiz. For instance, you can pick a word drag it over and then check your answer to see that it was incorrect you keep trying again and see if you can get them all lined up. Again, this allows you to just familiarize yourself with the various vocabulary words that will be introduced in this module. Alternatively you can select on the alternative activity and it&#39;s more of a multiple choice format. So again this is an ungraded quiz. You can close it out right there. Next, we move to the lessons. As said before, there are 4 to 6 lessons within each module. So you&#39;ll see each lesson represents more or less a day&#39;s worth of work and contains a video, a reading, and then either a concept check or reflection. As you will learn in the syllabus, the introduction, video, and reading pages are graded on participation, meaning you get credit for going through every page and activity in the module. Your school may or may not be using participation, so please check with your instructor on whether or not you will be receiving participation credit in your course.</p><p>The videos and their functionality we have already talked about. Next we go into the readings which obviously will have additional content and details to read. It will also frequently contain images as well as embedded videos. These are videos that add a lot of visual detail to the materials and again just hitting play there. Some videos are longer, so we try to limit video clips to 2 to 5 minutes, so in some cases you will only see a small clip of a larger video.</p><p>After the video and reading is a concept check or reflection where you&#39;ll either input an answer or work with flashcards or maybe a sorting exercise to review and firm up the concepts that were taught in that section. The reflections are either journal entry or discussion prompts. To participate in class-wide discussion, you’ll select this link to read the questions or prompts, and then participate in the discussion by adding a new discussion topic and eventually commenting on posts from other students.&#160;You&#39;ll see this repeat itself through the rest of the sections. After which you&#39;ll find a quick summary. Once you are finished with each lesson, you see three more assignments here: the short answer assignment, the project and the quiz. The short answer assignment is generally a one to two-page paper, written after every module, that will allow you to explore and apply the principles learned. Here we can select the link to read through the prompt and also see the rubric by which you will be graded. Then you can use an external word processing program like Word to complete the assignme<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('a8cdafcbb66c78c54e6be46cd0538d97','adobe-illustrator-module-1','2eeac88d9b6058d9d55e1dcf25daf550','Module 1: Design Industry',1) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1e906b502d0210d1f94e69050bec762e','adobe-illustrator-m1-l1-introduction-purpose-and-objectives','a8cdafcbb66c78c54e6be46cd0538d97','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Intro Description Objectives</h3><p>Introduction</p><p>Hi, I’m Ms. Jacobs and I’ll be one of your instructors for this course on Adobe Illustrator. This is the intro video for Working in the Design Industry. If you are interested in learning graphic design, chances are you’ve heard of the “Big Three” Adobe software applications – Photoshop, InDesign, and Illustrator. In this course, we’ll be diving into what is possible with Adobe Illustrator.</p><p>Throughout the course, you’ll have a variety of ways to learn the material. There will be readings, videos, screenshot tutorials, images, and much more. But we really have two ultimate goals. First, that you learn how to use Illustrator. And second, that you are best prepared to take (and pass!) the Adobe Certified Expert or ACE Certification exam on Illustrator.</p><p>As with most things in life, we learn best by doing, and something like Illustrator is no exception. So as you are going through the course, I’d encourage you to have the Illustrator program up and running on your computer. Follow along, trying things for yourself, and experiment! It’s ok and even encouraged to make mistakes. Because that’s how we learn. And there’s always the ability to undo an action!</p><p>Illustrator is a complex program, and can be overwhelming for someone who is brand new to it. But we’ll be walking through it slowly, step-by-step to get you comfortable with all the key features of this software. You’ll see me introducing each module in this course, providing an overview of the topics you’ll cover in each one. My colleague for this course, John, will be the one walking you through the screenshot tutorials of Illustrator. As you’ll come to find out, he is a top-notch expert when it comes to Illustrator.</p><p>In this module, we’re going to explore how to set up project requirements. We’ll do this by following a case study of a professional designer named Lucy who’s got a new project brief on her desk. Her job will be to create the graphics to promote a music festival. You’ll get to find out about the different ways that she sets up her project up for success.</p><p>We’ll introduce you to the Adobe Creative Suite, a suite of apps that professional graphic designers use. As we learn about Illustrator, we’ll find out about creating vector graphics like logos, icons and illustrations. You’ll learn about why your audience matters on a graphic design project, and how to tailor your designs for them. You’ll also find out how to navigate issues of copyright and licensing when you’re using material created by others in your projects. We’ll talk a little bit about project management and, finally, we’ll discuss an important but often overlooked part of being a designer – communication. I hope you enjoy the module and this course. Good luck!</p><p>Module Description</p><p>by Adobe</p><p>License:&#160;All Rights Reserved</p><p>Have you heard about the Adobe Creative Cloud, and its design tool, Adobe Illustrator?&#160;In this module, students will explore how to set up design projects using Adobe Illustrator, the industry-standard software tool for graphic design and illustration.&#160;Students will learn about how the applications in Creative Cloud can be used together on successful projects and think about the purpose and audience for their graphics work so that they can design for the needs of their audience.&#160;They will also begin to make decisions like a designer about what should be included in a project, build on their awareness of copyright and licensing, recognize the responsibilities involved in managing a design project, and find out how to communicate well with other people about their design plans.</p><p>Objectives</p><p>In this module, students will</p><p>Understand the Adobe Creative Suite and the role of the various applications.</p><p>Identify the purpose, audience, and audience needs for preparing graphics and illustrations.</p><p>Determine the type of copyright, project fit, permissions, and licensing to use specific content.</p><p>Demonstrate knowledge of project management tasks and responsibilities.</p><p>Communicate with colleagues and clients about design plans.</p><p>Polling Question</p><p>Prior to beginning this module, how familiar are you with the Adobe Creative Cloud, and, in particular, Adobe Illustrator?</p><p>I&#39;ve never heard of it before&#160;I&#39;ve heard about it but haven&#39;t used it&#160;I&#39;ve tried it a few times&#160;I use it often</p><p>Results:</p><p>I use it often&#160;50%</p><p>I&#39;ve tried it a few times&#160;25%</p><p>I&#39;ve heard about it but haven&#39;t used it&#160;25%</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Tab through this activity to read the feedback for your answers</p><p>Feedback</p><p>This is the first step in the design process.&#160;It includes a client profile and a written plan that identifies the purpose, target audience, outputs, content, technical requirements and constraints of a project.</p><p>Design brief</p><p>Correct!</p><p>What a client wants accomplished which provides direction to the project plan.</p><p>Project goals</p><p>Correct!</p><p>A specific group of people for which a message is intended.&#160;Demographic characteristics such as age, sex, income, location, education, and religion of an audience.</p><p>Target audience</p><p>Correct!</p><p>May be a brochure, a website, a poster, an advertising campaign, etc. Content may include items such as copy, photographs, graphics etc.</p><p>Outputs</p><p>Correct!</p><p>A sum of money available for a particular project.</p><p>Budget</p><p>Correct!</p><p>A date when a project or part of a project is due.</p><p>Deadline</p><p>Correct!</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('46b1d5719a6b34c8408d24dfc12f0de5','adobe-illustrator-m1-l2-lesson-1','a8cdafcbb66c78c54e6be46cd0538d97','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Creative Cloud Video</h3><p>Creative Cloud Video</p><p>If you want to get into graphic design, you’ll find that you need the industry standard go-to tools like Adobe Photoshop, Illustrator and InDesign. These are part of Adobe’s Creative Cloud.</p><p>Adobe’s Creative Cloud makes it easy to access your files from anywhere, keep your software up-to-date and collaborate with other people to get your designs just right.</p><p>There are many different kinds of design projects you could be working on, from brochures to invitations, infographics, logos, posters, and many more.</p><p>If you want to create products like these, you’ll need to get familiar with Creative Cloud and learn how to choose the best app for the project you have in mind.</p><p>The Creative Cloud contains lots of apps to help you with your design work.</p><p>The ones you should know about for now are Photoshop, best for photo editing and compositing, InDesign, best for print layouts like books, magazines, and brochures, and Illustrator, best for vector graphics like logos, icons, and illustrations.</p><p>Depending on the type of work you do, you might like to use Adobe Premiere Pro and After Effects to create videos and special effects, Adobe XD and Dreamweaver to design and code websites, Audition to work with audio files or Photoshop and Spark to create quick graphics for social media and the web.</p><p>Once you get familiar with these tools, you can create all kinds of dynamic images and media for the web, print, and screen.</p><p>In this course, we’ll be focusing on Illustrator.</p><p>Illustrator is used for creating vector graphics like logos, icons, infographics, and illustrations.</p><p>You can also use Illustrator to create layouts for websites, brochures, and other printed documents, if you want to.</p><p>Illustrator is ideal when you want to create a graphic and scale it to any size. Design your logo in Illustrator and you could print it on a stamp or on a billboard with no loss of quality. We’ll look at the many things that Illustrator can do during the course.</p></section><section><h3>Creative Cloud Overview</h3><p>Reading 1</p><p>by Adobe</p><p>License:&#160;All Rights Reserved</p><p>The Adobe Creative Suite and its Applications</p><p>As you learned in the video, the Adobe Creative Cloud is a collection of software tools that designers use to create content for the web and print, from video to infographics, logos, posters, animations and graphics for social media.</p><p>What’s a Cloud?</p><p>But wait, just what is the cloud, exactly, and why do you want your software in it?</p><p>In essence, the word “cloud” is used when a service is made available via the internet.&#160;The Adobe Creative Cloud contains all of the applications available in its service, and you can access those apps from anywhere that you have an internet connection.</p><p>This promotional video from Adobe explains the benefits of using their cloud-based software.</p><p>Video title:&#160;Adobe Creative Cloud Overview&#160;Video publisher:&#160;Adobe Creative Cloud(opens in a new tab)</p><p>The cloud gives you easy access to your files, wherever you are, ways to share what you’re working on with colleagues and software that’s always up-to-date so that you don&#39;t have to wait for installation.&#160;You’ve got the newest tools at your fingertips anytime.</p><p>What’s included in the Creative Cloud?</p><p>There are lots (and lots!) of apps in the Creative Cloud, and Adobe adds new ones (and sometimes retires old ones) quite frequently.</p><p>by Adobe</p><p>License:&#160;All Rights Reserved</p><p>The “big three” that you should know about are:</p><p>Adobe Photoshop - used for editing photographs; some designers also use it for website and app layouts</p><p>Adobe InDesign - used to lay out (usually) printed documents like books, newsletters and reportsAdobe Illustrator - the focus of this course, used to create vector graphics like illustrations, logos, icons and infographics</p><p>You’ll also hear about apps like:</p><p>Spark - great for quick promotional graphics for social media</p><p>Adobe XD - useful if you are working on website or user experience design</p><p>Dreamweaver - where you’d code those websites</p><p>Premiere Pro - &#160;used for video post-production</p><p>Audition - used to record and mix audio</p><p>After Effects - for special effects and animation</p><p>Lightroom - used for advanced photo editing</p><p>It might seem like a lot just now, but don’t worry –&#160;all of the Creative Cloud apps have similar tools and interfaces, so once you get to know a few, you’ll feel more confident in others, even if it is your first time using them.</p><p>Choosing the right app for the job</p><p>Many of the apps overlap in some way with their functionality, so there isn’t always just one way to do things, but you’ll find that some tools are better suited to certain outputs than others are.</p><p>Can you guess which app is the best one for the job by matching the projects with the Adobe Creative Cloud applications below?</p><p>Tab through this activity to read the feedback for your answers</p><p>Project</p><p>Application</p><p>Feedback</p><p>Editing photos taken with a digital camera.</p><p>Photoshop</p><p>Correct!</p><p>Creating a logo.</p><p>Illustrator</p><p>Correct!</p><p>Creating graphics with filters and text effects for a social media marketing campaign.</p><p>Spark</p><p>Correct!</p><p>Layout for a 50-page booklet.</p><p>InDesign</p><p>Correct!</p><p>Creating a video clip for YouTube.</p><p>Premiere</p><p>Correct!</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Editing photos taken with a digital camera.</p><p>InDesign</p><p>Illustrator</p><p>Photoshop</p><p>Spark</p><p>Premiere</p><p>Correct!</p><p>2.</p><p>Creating a logo.</p><p>Premiere</p><p>Spark</p><p>InDesign</p><p>Illustrator</p><p>Photoshop</p><p>Correct!</p><p>3.</p><p>Creating graphics with filters and text effects for a social media marketing campaign.</p><p>Photoshop</p><p>InDesign</p><p>Spark</p><p>Premiere</p><p>Illustrator</p><p>Correct!</p><p>4.</p><p>Layout for a 50-page booklet.</p><p>InDesign</p><p>Premiere</p><p>Spark</p><p>Photoshop</p><p>Illustrator</p><p>Correct!</p><p>5.</p><p>Creating a video clip for YouTube.</p><p>Spark</p><p>Illustrator</p><p>Premiere</p><p>InDesign</p><p>Photoshop</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('dfff7cb38ff48f069dc35dd643a9039c','adobe-illustrator-m1-l3-lesson-2','a8cdafcbb66c78c54e6be46cd0538d97','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Case Study Part 1</h3><p>Case Study: Part 1</p><p>To start this lesson, watch the following video, which is part 1 of a case study on Lucy, a graphic designer.&#160;We&#39;ll then follow her story throughout the rest of this module.</p><p>Lucy works as a graphic designer and her new brief is to create the promotional material for a music and arts festival coming to town next summer. Her boss has explained that Lucy’s job will be to lead on the art direction for the campaign, and they need to start promoting – like yesterday!</p><p>Lucy has a copywriter and a videographer to work with. She also has access to the agency’s IT team and a social media team who can help with web development and digital marketing. Lucy will be designing the graphics herself and will be the main point of contact for the festival promoter, Eric.</p><p>Lucy has two key audiences to think about as she creates her campaign. First, the client, Eric –&#160;she’s got to keep the client happy! – and second, the audience for the campaign – the people who will buy tickets to the festival. She needs her design to appeal to them and make them want to buy tickets.</p><p>To keep the client happy, she has to deliver on time and within budget. The festival will be in town next summer so she’s got 12 months before the gates open, but that deadline isn’t very far away. Tickets will start selling three months before the July 1st festival date. Eric wants the festival to appeal to an audience of people between the ages of 18-30, so he’s looking for eye-catching, vibrant design. 10,000 tickets will be available and ticket holders will have access to three stages of music and entertainment featuring different genres of music for the one-day festival.</p><p>Lucy’s boss has hinted she could get a promotion (and a bigger salary!) if this campaign goes well, so she’s got to make a big impression.</p><p>Target Audience</p><p>People racing smartphones on concert(opens in a new tab)&#160;by Ezra Comeau-Jeffrey</p><p>License:&#160;No known copyright restrictions</p><p>As you learned in the video, knowing who your audience is and what they need, is a huge part of a graphic designer’s job.&#160;Like Lucy in the case study video, you might be working on a project where you have a clearly defined audience.&#160;In Lucy’s case, the audience is young people between 18-30 living in a specific geographic area who are music fans, but you could be creating designs to advertise a brand, like food or drink, for example, that aims to appeal to different age groups and needs to tailor its ads to many different audiences.&#160;Or, you might be promoting a company that advertises around the world, so you will have to think about audiences who have differences in language and culture and change your designs accordingly.&#160;You’ll often find out about your target audience for the first time when you receive design brief and discuss the project goals with your client.</p><p>You might have a few different audiences to think about, depending on the project you are working on.&#160;You’ve also got to keep the client in mind as another audience to impress!</p><p>Why audience matters</p><p>Many people think that designing for everybody is the best approach.&#160;Anyone could see the posters and website that Lucy will be developing as part of her campaign, so shouldn’t she try to make a design with the broadest appeal?</p><p>Well, she could, but remember, her client has quite a specific audience in mind –&#160;young people between 18-30 in the local area who are likely to buy tickets to a music festival.&#160;So, since this is her target audience, she should be marketing her event directly to them.&#160;People outside of this demographic might buy tickets too, and that’s a bonus, but she’ll sell tickets more easily if she focuses on a primary audience.</p><p>It’s like this with any product or service.&#160;Remember that design is part of marketing!&#160;Most brands or companies will have different groups of people who will be interested in their products and services.&#160;There is usually a primary audience –&#160;the largest group&#160;–&#160;and then some other secondary audiences that are likely to buy the product or service.&#160;Advertising campaigns can then be designed for specific demographic groups.&#160;When we look at an audience’s demographics, we’re looking for shared traits, including age, race, gender, marital status, income, education, and occupation.</p><p>A marketing campaign for a travel company targeting married couples in their 50s, for example, would look very different than a campaign targeting University students who want to book a spring break holiday, so the target audience makes a big difference to a designer’s approach.</p><p>Researching your target audience</p><p>How do you know who your target audience and what will appeal to them?&#160;That all comes down to research.&#160;You’ll want to gather as much information about them as you can.&#160;For example:</p><p>How old are they?</p><p>Where do they live?</p><p>Is one gender found in much higher numbers?</p><p>What jobs do they do?</p><p>How much do they earn?</p><p>What do they spend their money on?</p><p>How do they spend their leisure time?</p><p>What other products and services do they buy?</p><p>What’s important to them?</p><p>The answers to questions like these will help you better understand the people you are designing for.&#160;The more you know about these individuals, the better you can target your work to them, and the more likely they are to engage with your designs.&#160;There are many ways to find out about your target audience, from asking them directly, to conducting a survey or looking at marketing designs for similar products that they buy.</p><p>Designing for your target audience</p><p>In the case study, Lucy’s campaign is targeting young people, and her client has asked for a vibrant, eye-catching design, so she’ll likely use bright colors and expressive fonts.&#160;Since she’s promoting a music event, she’s likely to use images or footage of the performers, but she might also use a modern graphic illustration style to appeal to a youthful audience.</p><p>Here are some of the different considerations you might make, depending on who your target audience is:</p><p>Color&#160;- You might use bold, bright color when designing for children, but more muted colors if designing for older people, for example.&#160;You may also need to consider cultu<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('02f69dc64b1dc84a35a417e1b16f8a5a','adobe-illustrator-m1-l4-lesson-3','a8cdafcbb66c78c54e6be46cd0538d97','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Case Study Part 2</h3><p>Case Study Part 2 and Reading</p><p>On the music and arts festival project, Lucy will be working on graphics to be used across different marketing channels. She’ll need branding elements like a logo, colors, fonts, and promotional photos, and since she’ll be promoting via the internet, TV, and print, she’ll need a video ad (for TV and social media), a poster and graphics for the website and social media marketing campaign that the IT and marketing teams are working on.</p><p>Because this is a new festival, she’s run into a challenge already. There’s no footage from a previous festival that she can use in her video ad, so she has applied for permission from the bands who will perform to use previous concert footage and soundbites in her promotional material.&#160; She’s also asking for permission to use the musicians’ promotional photos on her posters and ads. She can’t just take anything she wants from the internet or she could get into trouble with copyright laws.</p><p>She is also getting model releases ready for the photographer to use on event day so that she will have permission to use the photos and videos captured when she promotes next year’s festival. She will also be posting signs at the entrance to the festival to let the public know that recording equipment (video and photo) will be used on the day, and that they might appear in promotions later.</p><p>Reading 3</p><p>License:&#160;No known copyright restrictions</p><p>Making decisions about content:&#160;copyright, project fit, permissions, and licensing</p><p>As you learned in the video, designers have to think about copyright, permissions and licensing when they are choosing content for design projects.&#160;Designers make decisions every day about which fonts, colors, photos and illustrations and even media like video and audio clips to use.&#160;Not only do they have to think about whether their choices fit the project and will appeal to their target audience, they also need to know that they are allowed to use that material in their work, and that they are not running into legal, privacy or copyright issues.</p><p>First, think about the composition of your design, and what content would be a good fit for it.&#160;Think back on what you know about your audience and what will appeal to them, as well as the channels where your work will be used to promote the product, service or event.</p><p>If you are working on a poster, booklet or other printed output, you might look online for photos or graphics to use, or you might create your own.&#160;You might choose fonts, icons, photos or other graphic elements that were created by other designers and made available on the internet, but if you do, remember the intellectual property is owned by the person who created the content, so you will need to check the licensing.&#160;If the content is offered for free, you will likely need to include a credit somewhere on your work.&#160;If you pay for these design assets, you may only be able to use them in certain ways.</p><p>If you are working on videos or digital ads, you might need photos and graphics, but your team might also want to include audio or video clips, so you may need to source those, too.</p><p>In our case study, Lucy is curating some content that belongs to other people by asking for photos and video of the musicians, and she is creating some of her own content by working with a photographer to get photos and video.&#160;She’ll produce graphics and illustrations herself, but she will likely use some content like icons, fonts and other design elements that were created by other designers, so she’ll need to use and credit these correctly.</p><p>This video explains some essentials about copyright for designers.</p><p>Video title:&#160;Design &amp; Copyright - Making sure your work is legal</p><p>Video publisher:&#160;CharliMarieTV(opens in a new tab)</p><p>Kinds of copyright</p><p>5</p><p>Image Hotspots Transcript</p><p>Fair use</p><p>Fair use is not a copyright status, but it may mean that you can make use of copyrighted work without permission.&#160;This depends on:</p><p>What kind of work you are using</p><p>How you are using it</p><p>How much of the work you have used</p><p>How your use might impact the market for the work</p><p>The rules of this are complex, and cover situations like:</p><p>When you are reviewing or critiquing a work (for example, you quote a line from a book in a book review)</p><p>When you are parodying a work</p><p>When you are using a work in an educational context (for example, your teacher shows you a clip from a movie in your film studies class)</p><p>Because of the complexity and context-specific rules about fair use, it is better to ask for permission to reuse and adapt a work rather than hoping that Fair Use will protect you.</p><p>Privacy</p><p>Another issue that Lucy had to deal with in the case study was the issue of privacy.&#160;She wants to take photos and videos in a public place to later use in promotional material.</p><p>There are some precautions to take when you do this.&#160;For example, Lucy is providing model releases to her photographer so that, if the photographer takes a photo of a specific person where they are clearly identifiable, the photographer can provide the person with information about how the photo would be used and get their written permission to use it in promotional content or on social media.</p><p>Generally, it is permissible to take photos and video in public places with the assumption that people passing in the crowd won’t be easily identified or the focus of the work.&#160;If you are doing this at an event, you should be upfront about this and let people know by posting signs or making announcements.&#160;This way, if people are in any way concerned they can request that images of them are not used, or they can choose not to enter the location where filming and photography are taking place.</p><p>Getting permission</p><p>Just like Lucy did in our case study, you might need to get permission to use some material in your work.&#160;Often, this can be obtained by paying a licensing fee, but this can be expensive –&#160;get in touch with the copyright holder to find out if an arrangement can be made.&#160;Make sure you get any permissions or licensing agreements in writing so that you have proof of the agreement and a record of any fees paid.</p><p>Sourcing content that you can use</p><p>There are many places onli<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b58fd4c31dd24e53e74fe1d1719a9f3e','adobe-illustrator-m1-l5-lesson-4','a8cdafcbb66c78c54e6be46cd0538d97','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Case Study Part 3</h3><p>Case Study Part 3</p><p>Lucy’s boss has asked her to map out what the next 12 months might look like on the project, to make sure she has the team, funds and other resources that she needs to successfully promote the festival, so it’s time to get organized.</p><p>She needs to include time for printing. The local printer she is working with has told her that he’ll need about 6 weeks’ lead time to get her posters printed. The agency’s marketing team will start promoting the festival 6 months before event day, and they will ramp up their advertising 3 months before the event when tickets go on sale. So she needs to start brainstorming with the team soon to get ads ready.</p><p>Lucy has permission to use the band’s video footage and promo photos. The copywriter is working on the TV ad, posters and advertising for social media. The photographer will be attending the event so that the team will have video and photos to use when they promote the festival next year. Some of this might also be used by the marketing team on event day. She is working on the poster graphics using some of the photographs her client provided.</p><p>She has created a chart for her boss that maps out how much time it will take for each stage of the project, like design, proofing, printing, and marketing, and now it’s time to check in with the IT and marketing teams to make sure they have what they need to create the website and social media ads.</p><p>Reading 4</p><p>Project management tasks and responsibilities</p><p>As you learned in the video, project management can be a big part of a designer’s job, depending on where they work and what their role in the project is.&#160;It’s helpful to have some idea about how to run a successful project in case you need to take on the role of a project lead as Lucy has in our case study.</p><p>Here’s a primer on why project management matters for designers:</p><p>Video title:&#160;Project Management for Designers</p><p>Video publisher:&#160;Kadenze(opens in a new tab)</p><p>The design process</p><p>Here’s the basic process you’ll go through on most projects.</p><p>(opens in a new tab)</p><p>A successful planning phase</p><p>So much of your project’s success depends on what you do during the planning phase.&#160;It is helpful to create a project strategy document at this point, working out some of the finer points so that you can refer to it throughout the project and make sure things are on track.&#160;Try to record things like:</p><p>What problem are you trying to solve?</p><p>What are you proposing to do to solve this problem, and what have you agreed with the client to deliver?</p><p>What are the project’s goals?</p><p>Who is on the project team?</p><p>What is the timeframe and how does this break down?&#160;What fixed dates are there?</p><p>What could go wrong, and what contingencies do you have in place, just in case?</p><p>What budget do you have to work with, and what are the estimated costs for large expenses?</p><p>Tips for running a successful project</p><p>Like Lucy, you might decide to create a chart or timeline to share with your team so that everyone knows what should happen and when and what they are depending on each other for.</p><p>Here are some of our top tips for running a successful design project:</p><p>Make communication easy and don’t overload people with too many requests.</p><p>Get to know your team and each person’s strengths</p><p>Provide clear direction and a schedule that is easy to access</p><p>Keep your project files organized and easily accessible in one place</p><p>Keep the client in the loop with regular check-in meetings or progress reports</p><p>Know the project scope (and avoid “scope creep” –&#160;when a project expands to include items that weren’t originally in the specification which take more time and resource).</p><p>Initiate</p><p>You might hear some of the stages referred to by different names, but you’ll usually start with initiation –&#160;where you’ll review the project brief, the project team will be put together, and you’ll all likely have a kick-off meeting with the client where you’ll find out about their needs and goals.</p><p>Plan</p><p>Based on what you found out, you can then move on to the planning stage of the project.&#160;You and the rest of the team will need to create a strategy for the product or campaign you are working on based on what you already know about the audience, and what you can find out through your research.&#160;At this point, you’ll be thinking about what channels will be used, if you are working on a campaign, and you will likely also work out the finer points of the project, like a timeframe and budget, how often you will meet as a team, the resources and people you need to succeed, and so on.</p><p>Design</p><p>From there, you’ll move on to the design stage.&#160;You’ll likely be working in the Adobe Creative Suite and other tools by this time as you create your initial mock-ups (sketches or very early drafts of designs).&#160;Like Lucy, you might be working with a copyeditor, photographer, illustrator or other professionals at this stage who will contribute to the outputs you are working on.</p><p>You’ll then create more polished versions of your design and give the client some options, and, based on their feedback, you’ll revise your designs.&#160;Other members of the team might be working on other parts of campaign development at this point.&#160;In Lucy’s case, here’s where the IT and marketing teams will be working on the website and social media campaign, for example, while she puts the finishing touches on her design work.</p><p>Approve</p><p>Once you are finished with your design work, you will hopefully test it in some way to get some feedback and inform any final revisions.&#160;You’ll do final quality checks and, once your work has been approved by the client, you’ll get your files ready to go over to a printer, web developer or other professional who’ll take your design from here into its final form.</p><p>Launch</p><p>Finally, once your outputs are ready, the campaign or product goes public and is promoted.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6ee341cfb2689e70b11544c47107007a','adobe-illustrator-m1-l6-lesson-5','a8cdafcbb66c78c54e6be46cd0538d97','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Case Study Part 4</h3><p>Case Study Part 4</p><p>Communication is a bigger part of this job than Lucy thought it would be, because she’s got to keep the client, her boss, and her team happy and informed, while keeping in mind that it’s all about what the audience needs - and focusing on them when the team makes decisions.</p><p>During the onboarding process with the client, Lucy asked for the content she needed, like musician bios, photos, footage, logos, and colors, fonts, any style guidelines she had to stick to, and other details that would help her create a successful campaign. She also found out about the budget and timeframe, and has kept the client aware of those throughout the project.</p><p>Every day, Lucy communicates with her team using a project management app that’s “in the cloud” so that each person can clearly see what tasks they have to do and by when, collaborate on files and check-in with each other. This helps to prevent email overload. Using the app, they share a calendar and post short updates regularly to update each other on their part of the project. Lucy meets with the copywriter, videographer and marketing team often for a quick catch-up.</p><p>She has been hard at work on web graphics and ads. The IT team have launched the website and public interest in the festival is starting to pick up. The TV ad is also being released soon, so she’s putting the finishing touches on graphics for the video. She loves using the team’s shared document storage space because she can get feedback from her team quickly and get sign-off from Eric quickly, too. Since project files are shared in the cloud, everyone can view, edit and make suggestions in real-time.</p><p>She meets with the client once every two weeks to clear any roadblocks in the project. He has asked her for an update on the poster, so she’s got to check in with the copyeditor in a hurry. Luckily, she’s got their shared project management app on her phone and can request an update while she is on-the-go.</p><p>Reading</p><p>Man in gray shirt facing sticky notes(opens in a new tab)&#160;by BonnevalSebastien</p><p>License:&#160;No known copyright restrictions</p><p>Communicating with others about design plans</p><p>As you learned in the video, communication is a big part of design, especially if you are working on a team.&#160;On smaller projects, you might just need to report to the client, but on other projects, like in our case study, you might need to communicate regularly with superiors and colleagues who have different roles on the project, from writers to other designers, developers, photographers and videographers, marketing and IT professionals, administration staff and others.&#160;This can be a tricky balance, made much easier when you use technology to help you.</p><p>In this video, a graphic designer explains how he looks after communication with clients, using technology to streamline the process.</p><p>Video title:&#160;How to Handle the Client Workflow Process for Graphic DesignersVideo publisher:&#160;Ben G. Kaiser</p><p>Enabling team collaboration</p><p>Right from the beginning of a project, make sure that everyone on your team is clear about what the project will deliver and who is responsible for what aspects of it.&#160;Set expectations early about how you will communicate with each other, how often you will meet, and what pace of work is expected.&#160;Sharing a Gantt chart or timeline with your team, or using a cloud-based project management app like Lucy does can be a big help in terms of making sure everyone knows what is expected of them.&#160;If you do this from the start, you can cut down on a lot of unnecessary email communication and meetings.</p><p>Communication strategy</p><p>One of the most important things you can do early on your project is make sure everyone is clear on what the strategy is.&#160;Everyone on the project team should know the important details like the project scope, deliverables and deadlines.</p><p>You might ask teammates to provide a weekly update by email, using a project management tool, or in a meeting.&#160;Try to encourage openness on your team and let people know that they can ask for help if they need someone to bounce ideas off or if they are struggling with their workload.</p><p>Keep your client in the loop by providing regular status updates or holding short meetings.&#160;Ask for the things you need, like branding (colors, fonts, logo), photos or video and other content that you will use in your design early in the process, remembering to also ask the client for examples of other designs that they like, and to explain what they like about these, so that you have a good idea of what they are looking for and what style suits their brand.</p><p>Presenting your ideas</p><p>It can be helpful to pitch some of the ideas or design options you have come up with to the client and other decision-makers using a mood board to show the colors, fonts, illustration or photography style and other elements of your design, or even to present more developed mock-ups and layout options.</p><p>Here’s an example of a mood board –&#160;a collection of design elements that helps to communicate the “feel” of the design you are considering.&#160;This one is for an outdoors brand.&#160;Notice that this isn’t a finished piece of design, so it doesn’t take a lot of time to put together, but it does give us a sense of what our designs might look like at the end of the project.&#160;Your goal with a mood board is to communicate the design direction you are proposing to others, including your team and your client.</p><p>Mood board - Element&#160;by Photos - Unsplash, Icons - Noun Project</p><p>License:&#160;All Rights Reserved</p><p>Mood boards can be created digitally, using a tool like Pinterest.&#160;You can design them in Illustrator, or you can even create a physical mood board by cutting and pasting images onto a sheet of paper.&#160;They can be quite organised and clean, or they can be displayed in a more experimental way.&#160;Whichever method you choose, it’s a good idea to give the client a few distinct choices to consider, but don’t give them too many options –&#160;this can actually make it more difficult to reach a decision.</p><p>Communication tools</p><p>Here are some common tools used by designers to help streamline the process of communicating with clients and other people on the team.</p><p>Project management apps - there are many apps like this w<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('487720dc5128cd64112237f75faf9191','adobe-illustrator-m1-l7-summary','a8cdafcbb66c78c54e6be46cd0538d97','Summary','text',12,'<h2>Summary</h2><section><h3>Module 1 Summary</h3><p>Summary</p><p>Great work!&#160;You have successfully completed this module on Setting Project Requirements!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Understood the Adobe Creative Suite and the role of the various applications.</p><p>Identified the purpose, audience, and audience needs for preparing graphics and illustrations.</p><p>Determined the type of copyright, project fit, permissions, and licensing to use specific content.</p><p>Demonstrated knowledge of project management tasks and responsibilities.</p><p>Communicated with colleagues and clients about design plans.</p><p>Additional Resources</p><p>The following books, articles,&#160;and websites are additional resources to learn more about this topic.&#160;(Not required reading)</p><p>Adobe.com.&#160;(2019).&#160;Adobe Creative Cloud | Software and services for creative professionals(opens in a new tab)</p><p>Creativesuitepodcast.com.&#160;(2019).&#160;Adobe Creative Suite Video Podcast.(opens in a new tab)</p><p>Ben G Kaiser.com (2019).&#160;BenGKaiser.(opens in a new tab)</p><p>Creative Bloq.&#160;(2019).(opens in a new tab)</p><p>Designcrowd.com.&#160;(2019).&#160;Design Inspiration, Crowdsourcing, Small Business Tips and News.(opens in a new tab)</p><p>99designs.&#160;(2019).&#160;The Creative Edge, a design blog by 99designs.(opens in a new tab)</p><p>Webdesigner Depot.&#160;(2019).&#160;Webdesigner Depot.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('cb696c921a202f334bed853843289a98','adobe-illustrator-m1-l8-module-1-project-empty','a8cdafcbb66c78c54e6be46cd0538d97','Module 1 Project Empty','text',12,'<h2>Module 1 Project Empty</h2><section><h3>Module 1 Project</h3><p>2200</p><p>Adobe Illustrator</p><p>Working in the Design Industry - Project</p><p>Setting Project Requirements - Project</p><p>For this assignment, you will be creating a mood board for the project described in the case study. As a reminder, the project is as follows:</p><p>Promotion for a one-day music festival</p><p>Target audience: Music fans between 18-30 who live in your city (you may focus on any type of music or a variety of styles)</p><p>Vibrant, youthful style</p><p>You can use the mood board from Lesson 5 as a guideline, but use your creativity to lay out the mood board! You may want to do some research online to see mood boards that other designers have created to get some inspiration.</p><p>Give the festival a name and choose a font style for its logoChoose some photos and/or illustrations that are examples of the style you would use. Make sure to check permissions and use Creative Commons, CC0 or public domain images, or your own.</p><p>Showcase any patterns, colors, fonts, icons and other design elements that you would use in your promotional graphics for the festival</p><p>You can create your mood board using any app or tool that you are comfortable with. You can even create it by cutting and pasting by hand, if you prefer. Whichever method you choose, scan, photograph or save your mood board in PDF format to share it with your instructor.</p><p>Review the rubric below to see how you will be graded.</p><p>Working in the Design Industry - Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Design</p><p>8 points Mood board is well designed for the target audience described. Student has made careful decisions about what to include and the design is visually appealing.</p><p>7-6 points 8 points Mood board is adequate for the target audience described. Student has made some decisions about what to include but student could improve on the appeal for this audience. The design has some visual appeal.</p><p>5-0 points Mood board is poorly designed and will not appeal to the target audience described. Student has not been selective about what to include. The mood board lacks visual appeal.</p><p>8</p><p>Copyright considerations</p><p>8 points Student has carefully considered issues of copyright and licensing and has provided credit in an appropriate way.</p><p>7-6 points Student has made some consideration of issues of copyright and licensing but lacks credit or has missed some critical issues.</p><p>5-0 points Student has not considered issues of copyright and licensing and has not provided credit in an appropriate way.</p><p>8</p><p>Communication</p><p>2 points The mood board effectively communicates the design plan to a viewer in an appealing way.</p><p>1 point The mood board needs a more cohesive approach to communicating the design plan to a viewer.</p><p>0 points The mood board fails to communicate a clear design plan to a viewer</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ec2baf8c55b3e3588271b5bc10fb91dd','adobe-illustrator-m1-l9-module-1-quiz','a8cdafcbb66c78c54e6be46cd0538d97','Module 1 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Design Industry. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('5018a75ca7eb978ab6c162f5b71a6845','adobe-illustrator-module-2','2eeac88d9b6058d9d55e1dcf25daf550','Module 2: Ditital Graphics & Illustrations',2) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9e3946f331b5df5355833ab59b8b3166','adobe-illustrator-m2-l1-introduction-purpose-and-objectives','5018a75ca7eb978ab6c162f5b71a6845','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>PIPEnter fullscreen</p><p>Hi everyone, and welcome back! This is the intro video for Understanding Digital Graphics and Illustrations. If you want to be a graphic designer, then you’ve got to know the fundamentals of design so that you can talk to other designers and get things done in your day-to-day life!</p><p>Just like many other industries, design has its own language, and for new designers, this new lingo can be a source of confusion. But don’t worry – that won’t happen to you because, in this module, you’re going to learn about some of the terminology you’ll hear and, more importantly, what to do with it!</p><p>First, we’ll work through part of the graphic design process with a case study of a young design intern who is learning new terms at every step. Then, you’ll find out what makes a design work, like how to use typography to get your message across with impact, and how to use color, which has symbolic meanings to us that can be very different depending on where you are in the world. You’ll also find out how to work with images, like how to get them in the right format for the web and for print, and how to share them with other people like designers and your print shop.</p><p>Module Description</p><p>by iStockphoto</p><p>License:&#160;All Rights Reserved</p><p>Find out about the fundamentals of graphic design!&#160;In this module, students will begin to think like designers, learning some of the terminology used in the design industry and exploring the elements and principles of good design.&#160;Next, they&#39;ll learn about how designers make decisions about their work, including the essentials of color theory and typography.&#160;Finally, they&#39;ll find out how to choose the best file type for the job by examining some of the benefits and drawbacks of the file types used on the web and in print.</p><p>Objectives</p><p>In this module, students will:</p><p>Understand key terminology related to digital graphics and illustrations.</p><p>Demonstrate knowledge of basic design principles and best practices employed in the digital graphics and illustration industry.</p><p>Demonstrate knowledge of typography and its use in digital graphics and illustrations.</p><p>Demonstrate knowledge of color and its use in digital graphics and illustration.</p><p>Demonstrate knowledge of image resolution, image size, and image file format for web, video, and print.</p><p>Polling Question</p><p>How much do you think graphic design choices like fonts and colors affect you when you see advertising on TV, online and in print ?</p><p>It makes no difference to me.&#160;I&#39;m either going to buy the product or I&#39;m not.</p><p>I don&#39;t really notice it but I think it has some impact.</p><p>I can think of some situations where design has influenced my decision to buy.</p><p>I pay a lot of attention to design and am more likely to buy products when design appeals to me.</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Placing elements in a design in positions where the eye is naturally drawn, using principles such as contrast, repetition, or movement.</p><p>Font</p><p>This happens when two design elements are in opposition to each other, like black and white, thick and thin or modern and traditional.</p><p>Contrast</p><p>Often used interchangeably with ‘typeface’; a particular design of type.</p><p>Hue</p><p>The primary value of a color.</p><p>Emphasis</p><p>Colors that are opposite each other on the color wheel</p><p>Complementary colors</p><p>The proportional relationship of width to height in an image.</p><p>Aspect ratio</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Placing elements in a design in positions where the eye is naturally drawn, using principles such as contrast, repetition, or movement.</p><p>Emphasis</p><p>Aspect ratio</p><p>Complementary colors</p><p>Font</p><p>Contrast</p><p>Hue</p><p>2.</p><p>This happens when two design elements are in opposition to each other, like black and white, thick and thin or modern and traditional.</p><p>Complementary colors</p><p>Emphasis</p><p>Font</p><p>Aspect ratio</p><p>Contrast</p><p>Hue</p><p>3.</p><p>Often used interchangeably with ‘typeface’; a particular design of type.</p><p>Contrast</p><p>Aspect ratio</p><p>Emphasis</p><p>Hue</p><p>Font</p><p>Complementary colors</p><p>4.</p><p>The primary value of a color.</p><p>Aspect ratio</p><p>Contrast</p><p>Complementary colors</p><p>Hue</p><p>Font</p><p>Emphasis</p><p>5.</p><p>Colors that are opposite each other on the color wheel</p><p>Hue</p><p>Aspect ratio</p><p>Complementary colors</p><p>Emphasis</p><p>Font</p><p>Contrast</p><p>6.</p><p>The proportional relationship of width to height in an image.</p><p>Contrast</p><p>Aspect ratio</p><p>Emphasis</p><p>Font</p><p>Complementary colors</p><p>Hue</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('dfa83485ef711fb77a3d227e729f2dfd','adobe-illustrator-m2-l2-lesson-1','5018a75ca7eb978ab6c162f5b71a6845','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Terms to Know</h3><p>Terms to Know</p><p>This is Charlie. He’s doing an internship at a design agency and so far, he loves his new job.</p><p>He’s working with Lucy, a senior designer, on a new project.</p><p>He’s got a lot to learn about the graphic design process and the words that designers use.</p><p>Charlie’s first task is to review the design brief that a client has provided.</p><p>Then, he’ll do some research and discovery about the brand and its competitors, to get some ideas about how to approach the campaign.</p><p>The client has given Charlie a style guide so he can get to know the brand identity and see the logo, colors, typography and other design elements that the company uses.</p><p>Next, Charlie and Lucy will do some brainstorming together, and Charlie can get to work on some early sketches.</p><p>Once Charlie has a clearer idea of what his designs will look like, he’ll create some design comps to share with the client.</p><p>These look more like the finished product. He’ll create three different concepts so that the team can talk about their options and decide which one they like most.</p><p>He might be using some placeholders and dummy text, at this point.</p><p>Charlie will create his designs in Illustrator, Photoshop or another design tool, and he’ll choose fonts, graphics, stock photos, icons and patterns for his designs.</p><p>Once the team have chosen a concept to use, Charlie will revise the design based on feedback and change requests.</p><p>He will replace the dummy text with the correct body copy provided by a copywriter.</p><p>He’ll also do final checks and get his files ready to hand over to the client and the printer.</p><p>He’ll need to make sure the images are high-resolution and that his files are ready for printing so that he can get a proof to show his client.</p><p>Reading 1</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>The language of graphic design</p><p>In the video, you learned about the process that designers go through when they are working on a new project, and some key terms came up that you should try to remember.&#160;Let’s review them.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>&#171; Back</p><p>Brand identity</p><p>Brand identityThe visualization of a brand that represents the values of the company.&#160;Identity can include things like a logo, business cards, letterheads, uniforms and packaging design.</p><p>Logo</p><p>LogoA company name designed in a visual way using text and/or symbols.</p><p>Style guide</p><p>Style guideA document consisting of fonts, colors, images and other design settings that gives a standardized look to all parts of a project.</p><p>Font</p><p>FontOften used interchangeably with ‘typeface’; a particular design style of type.</p><p>Stock photo</p><p>Stock photoA professionally shot photograph available online for licensing, usually used in place of hiring a photographer, or if a designer cannot access the images they need from their own inventory of photos.</p><p>Copy</p><p>CopyThe text in your design.</p><p>Comp</p><p>CompThe layout of a proposed design as initially presented by the designer to a client.</p><p>Proofs</p><p>ProofsA ‘soft’ one of these is one you can see on your screen, usually in PDF format.&#160;A ‘hard’ one of these is provided on paper to show you how your job will look when printed.</p><p>⟳ Flip Card</p><p>Next &#187;</p><p>Flashcard&#160;1&#160;of&#160;8</p><p>Flashcard Transcript</p><p>Printing terms</p><p>Here are some of the printing styles you can use in your designs.&#160;It&#39;s helpful to know a little bit about how they work so that you can communicate with your print shop.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Die cut - The process of cutting areas of your printed design in various shapes to create unique effects.&#160;Die cuts are created after printing and are classed as a finishing process.</p><p>Screen printing - Also known as silkscreening. In this technique, ink is pushed through mesh onto fabric or paper, with non-printing areas blocked using a stencil. Each colour is applied separately. Great for blocks of color, but not for fine details.</p><p>Offset printing is used for big jobs. An inked image is transferred to a plate for each color (Cyan, Magenta, Yellow, Black) then to the printing surface. Digital printing uses Red, Green and Blue and is like printing at home but better quality.</p><p>Foil stamping - Foil is heat-pressed to certain parts of a design to give a shiny, metallic finish.</p><p>Letterpress - many copies of letters or symbols can be produced by making repeated direct impressions of an inked, raised surface against paper.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('968aa6fa0a1d892ba7a8ae6412d7e4cd','adobe-illustrator-m2-l3-lesson-2','5018a75ca7eb978ab6c162f5b71a6845','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Elements &amp; Principles</h3><p>Elements&amp;Principles of Design</p><p>Let&#39;s review some of the basic elements of design. Lines are everywhere, in graphic design.</p><p>They can be curved, angled or straight. They can give us impressions. For example, a straight line feels orderly and neat, but a wavy line gives a sense of movement while an angled line has a sense of energy and intensity.</p><p>An area contained within an implied line, or shown by color or value changes. Shapes can be geometric or organic.</p><p>Colour creates mood and emotion. Each colour makes us feel a different way. Some colors can make us feel calm and others can make us feel energetic, for example.</p><p>Value is the relative lightness or darkness of parts of a design.</p><p>Space is a volume that can be empty or filled with objects. It can create a sense of depth in a design.</p><p>Negative space is the space in between elements which forms its own shape.</p><p>Principles of Design</p><p>When all parts of a design belong together, they are unified. This makes a design feel complete. Each part of a design has visual weight.</p><p>A design is balanced when equal visual weight is given to the parts of a composition. You can use size, shape and colour to balance your design.</p><p>Alignment, when elements are lined up equally, gives balance to a design. Symmetry is often used to create balance.</p><p>You use emphasis when you accentuate part of a design by giving it extra weight.</p><p>Create contrast by accentuating differences in a design, like using light and dark, large and small or thick and thin.</p><p>Good contrast also makes your design easier to read. At the top of a hierarchy are the most important parts which command the most attention.</p><p>You might use size, weight or position to make parts of your design stand out over other parts.</p><p>Objects are in proportion when they are scaled in relation to each other. This is one way to show hierarchy in a design.</p><p>Repetition helps to tie your design together. Patterns are an orderly form of repetition.</p><p>A sense of direction or flow in a design helps to move the eye from one part to another.</p><p>Lines or blurring can make objects in a composition appear as though they are in motion.</p><p>Reading 2</p><p>License:&#160;No known copyright restrictions</p><p>Design elements and principles</p><p>In the video, we explored some of the elements of design, which are the visual tools that designers use to create their designs, and some of the principles, which represent how a designer uses the elements of design to create an effect.&#160;Along the way, you learned some more new design terms.&#160;Well done!</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>&#171; Back</p><p>ProportionThe size of one element in relation to the other elements in a design.</p><p>UnityThis is what makes the parts of a composition look like they belong together.&#160;When each element relates to the other elements, your composition has unity.</p><p>EmphasisDrawing the eye towards specific elements or areas of a design.</p><p>BalanceWhen your design has form and stability and the elements are distributed evenly, it has balance.&#160;This can be achieved in many ways, for example by aligning elements, or by using symmetry.</p><p>AlignmentArrangement of elements in a straight line, or in appropriate relative positions.</p><p>ProportionThe size of one element in relation to the other elements in a design.</p><p>UnityThis is what makes the parts of a composition look like they belong together.&#160;When each element relates to the other elements, your composition has unity.</p><p>⟳ Flip Card</p><p>Next &#187;</p><p>Flashcard&#160;1&#160;of&#160;5</p><p>Flashcard Transcript</p><p>Unity:&#160;This is what makes the parts of a composition look like they belong together. When each element relates to the other elements, your composition has unity.</p><p>Emphasis:&#160;Drawing the eye towards specific elements or areas of a design.</p><p>Balance:&#160;When your design has form and stability and the elements are distributed evenly, it has balance. This can be achieved in many ways, for example by aligning elements, or by using symmetry.</p><p>Alignment:&#160;Arrangement of elements in a straight line, or in appropriate relative positions.</p><p>Proportion:&#160;The size of one element in relation to the other elements in a design.</p><p>Design elements and principles in action</p><p>Let’s look at how some of these elements and principles influence the graphic design that you see every day in branding, advertising, packaging, page layouts, websites, videos and more.</p><p>Which of the design elements and principles do you recognize in this logo design?</p><p>by Lamborghini</p><p>License:&#160;All Rights Reserved</p><p>The designer has achieved balance by using the shield shape which is symmetrical.&#160;We have contrast between two bold colors.&#160;Color plays a strong role, here.&#160;The use of gold and black together makes this looks expensive or luxurious, doesn’t it?&#160;A good choice for a luxury vehicle brand!</p><p>The parts of the logo feel unified because two colors have been used throughout, and there is a suggestion of movement here, too, in the bull’s pose –&#160;notice his tail looks like it is in motion.</p><p>Here’s Twitter’s website homepage.</p><p>by Twitter</p><p>License:&#160;All Rights Reserved</p><p>Notice how the bird symbol is repeated (small on the right and large on the left).&#160;This makes the page feel unified.&#160;The designer has split the screen in the center, giving us a contrasting bold color on one side and space on the other.&#160;This creates balance and the bold blue on the right side creates emphasis where we need it –&#160;on the sign up button.</p><p>Here’s the packaging design for Froot Loops cereal.</p><p>by Kellogg&#39;s</p><p>License:&#160;All Rights Reserved</p><p>This one uses bold, bright colors to stand out on the store shelf.&#160;There is a sense of movement and energy created by the cereals in the air.&#160;Notice that Froot Loops is written in a large, all caps font and is framed by other elements, which creates a hierarchy and draws your eye to the brand name.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3b0c36d394a01deb94bc538745d963c3','adobe-illustrator-m2-l4-lesson-3','5018a75ca7eb978ab6c162f5b71a6845','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Typography</h3><p>Typography</p><p>Let’s take a look at some of the basic elements of typography. First, there are some terms to learn about letter forms.</p><p>An ascender is the part of some letters that extends above the midline. A descender is the part of some letters that extends below the baseline.X-height is the space between the baseline and midline.</p><p>An arm is the part of some letters that extends from the stem of the letter. The stroke is the part of some letters which connects two stems. A counter is the negative space inside some letters.</p><p>There are four main classifications of font or typeface. These are serif, sans-serif, script and display. Serif fonts have a line or stroke attached to the end of letters. Sans-serif fonts have no serifs. Script fonts look more like hand lettering and the letters are usually joined. Just about anything goes with display fonts.</p><p>Reading 3</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Reviewing typography terms</p><p>Typography is the style, arrangement, or appearance of text elements in a design.&#160;In the video, you learned about the parts of letters and some of the different types of fonts that designers can choose from.&#160;Do you remember which one is which?</p><p>Choices:</p><p>Move image &quot;Letters meri&quot;</p><p>Move image &quot;Letters Fair&quot;</p><p>Move image &quot;Letters vetic&quot;</p><p>Move image &quot;Letters ebur&quot;</p><p>Your Answer</p><p>Serif</p><p>Sans-serif</p><p>Display</p><p>Script</p><p>Alternative Activity</p><p>Script&#160;Display&#160;Sans-serif&#160;Serif</p><p>Sans-serif&#160;Serif&#160;Display&#160;Script</p><p>Sans-serif&#160;Script&#160;Serif&#160;Display</p><p>Serif&#160;Display&#160;Script&#160;Sans-serif</p><p>We also looked at some of the properties of type.&#160;Can you identify them?</p><p>stroke</p><p>ascender</p><p>descender</p><p>counter</p><p>arm</p><p>_</p><p>5</p><p>Displaying type</p><p>When you are working with type in your design, you will need to make some choices about how it is displayed.&#160;For example, you will need to choose a:</p><p>Font&#160;- the style of font you choose will need to fit with your design.&#160;You might choose a fun display font for a poster, or a serif font for typesetting in a book, for example.</p><p>Size&#160;- you’ll need to make sure your font size is big enough that it can be read.&#160;You might use big, bold type for emphasis or a small size for the fine print.</p><p>Weight&#160;- you might also need to vary the font weight in your layout.&#160;For example, if you are working on a report, you might choose a bold weight for headings and a thin version of the same font for the body text.</p><p>You could also use a pull quote –&#160;a stylized way to display a quotation, or add a drop-cap –&#160;an oversized letter that’s sometimes used at the beginning of a paragraph or book chapter – to your design.</p><p>You will often need to make adjustments to your type so that it is easier to read or fits better in the layout you have designed.&#160;Here are some of the adjustments you can make:</p><p>Kerning&#160;- Kerning is the process of adjusting the space between characters so that they fit together.&#160;Some letters, like V and A in our example above, can look like they don’t belong together without this.</p><p>Here’s a little game you can play to&#160;see how good you are at kerning(opens in a new tab).</p><p>Leading&#160;- Leading is the vertical space between each line of type.&#160;To make your body text comfortable to read, your leading should be 1.25 and 1.5 times greater than the font size.</p><p>Tracking&#160;- Tracking is the process of adjusting the spacing of all characters in a word, and is applied evenly.</p><p>Measure&#160;- the width of a text block.&#160;If your lines are too long, your reader can easily get lost, while a too-short measure breaks up the reading experience unnecessarily.</p><p>Alignment&#160;- Your text can be aligned to the left or right, it can be centered, or it can be justified.&#160;In a paragraph of justified text, the words are spaced so there is no white space at the end of a line – each begins flush left and finishes flush right.&#160;This means the spacing between words will vary depending on how many are in that line.</p><p>Have you ever heard of an orphan and a widow, in the context of type?</p><p>An&#160;orphan&#160;is the first line of a new paragraph when it is stranded at the bottom of a page.&#160;A&#160;widow&#160;is a word or fragment that sits alone at the end of a paragraph of type.&#160;Isn’t that sad!&#160;It is good practice to adjust your type –&#160;either by adjusting the spacing or slightly re-wording the content – if your copywriter agrees –&#160;to avoid having orphans or widows.</p><p>Choosing a typeface</p><p>Choosing the right typefaces for your design is a decision you’ll have to make carefully because typography can have a dramatic effect on the mood of your design.&#160;Take a look at the logos below, for example.</p><p>Which typeface do you think is best suited to a dentist’s practice?&#160;Option 2 gives the impression of a child’s handwriting, which might appeal to the kids in the dentist’s target audience, but perhaps not so much to the parents.&#160;Option 3, with its jagged edges, is not the best impression to give for a dentist’s office where people want perfectly straight teeth!&#160;Option 4 might work, but feels a bit too feminine and detailed for a logo in this context.&#160;Options 1 and 5 are the simplest, and perhaps the safest choices in this case, as a dentist will want to project a professional, trustworthy image which is easy to read and appeals to a range of people.</p><p>Many fonts come with various weights and styles (like italic or condensed, for example) to form a font family or typeface, but display fonts will tend not to have so many options.</p><p>When you choose a font, check that it has the features you need.&#160;Does it support multiple languages?&#160;This is important if your design will be in a language other than English and you need non-standard characters.&#160;&#160;If you are using it for a web project, is it a system font, that comes pre-installed on most computers so that you can expect most people who view your design will see it in the font you chose?</p><p>There are thousands of free fonts available online.&#160;Try&#160;Google Fonts(opens in a new tab), for example, a huge collectio<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('fcf84175dfb826a93a7af98726facfbd','adobe-illustrator-m2-l5-lesson-4','5018a75ca7eb978ab6c162f5b71a6845','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Colour Theory</h3><p>Colour Theory</p><p>Colors have different meanings to us, and they can even influence our mood.</p><p>Red is an extreme color. It symbolises danger and is the color of blood. But also a symbol of love. It is the most common color on flags. It symbolises luck in Asia and is popular there for weddings. It is common in fast food branding and might even make us hungry.</p><p>Orange is energetic and vibrant. It is the color of juicy, healthy fruits. It is a symbol of autumn. It stands out, so it is used for safety items like traffic cones and life rafts.</p><p>Yellow catches our attention more than any other color. You’ll see it on traffic lights and caution signs. It is a happy color that makes us think of sunshine and summertime, but it also symbolises cowardice and treason.</p><p>Blue is a common favourite color. It is the color of water and sky. It is cool, clean and calm. Blue feels trustworthy. You’ll see it often in corporate branding. But you can also be ‘feeling blue’ which indicates sadness.</p><p>Maybe you are ‘going green’ for the environment. You can also feel ‘green around the gills’ when you are sick and you can be ‘green with envy’, too. Green symbolizes growth, fertility and luck. Green means GO, If you are using green in your design, remember that colorblind people can’t distinguish between green and red.</p><p>Purple is rare and expensive. It is associated with power, royalty and the supernatural. A Purple Heart is given for bravery. In ancient Rome, only the Emperor could wear purple.</p><p>Black is powerful and strong. It symbolizes villainy, sophistication, mystery and mourning.</p><p>White is fresh, pure and peaceful. It is often used in contrast with black – yin and yang.</p><p>Reading 4</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Color Theory</p><p>In the video, we explored color theory.&#160;This tells us about how people perceive color and the subliminal messages that colors communicate.</p><p>The color wheel</p><p>Let’s take a look at the color wheel.</p><p>Video Title:&#160;How to use colour:&#160;The colour wheel</p><p>Video Publisher:&#160;Ideal Home</p><p>Note:&#160;there are no closed captions for this video.</p><p>The color wheel has three primary colors (red, yellow, blue), three secondary colors (colors created when primary colors are mixed:&#160;green, orange, purple) and six tertiary colors (colors made from primary and secondary colors, such as blue-green or red-violet).</p><p>If you draw a line through the center of the wheel, you’ll separate the warm colors (reds, oranges, yellows) from cool colors (blues, greens, purples).&#160;Warm colors are usually full of energy, brightness, and action.&#160;Cool colors feel calm and peaceful.</p><p>Color terminology</p><p>Here are some color terms to know.&#160;Can you work out which is which?</p><p>The primary value of a color.</p><p>Saturation</p><p>The overall intensity or brightness of the color.&#160;If a color is dull, it is desaturated.</p><p>Gradient</p><p>A mixture of a color with white.</p><p>Shade</p><p>A mixture of a color with black.</p><p>Tint</p><p>A mixture of a color with grey.</p><p>Tone</p><p>A spectrum of color that gradually changes from one to another.</p><p>Hue</p><p>_</p><p>6</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>The primary value of a color.</p><p>Gradient</p><p>Tone</p><p>Hue</p><p>Saturation</p><p>Shade</p><p>Tint</p><p>2.</p><p>The overall intensity or brightness of the color. If a color is dull, it is desaturated.</p><p>Saturation</p><p>Tint</p><p>Tone</p><p>Gradient</p><p>Hue</p><p>Shade</p><p>3.</p><p>A mixture of a color with white.</p><p>Tone</p><p>Saturation</p><p>Tint</p><p>Shade</p><p>Hue</p><p>Gradient</p><p>4.</p><p>A mixture of a color with black.</p><p>Gradient</p><p>Saturation</p><p>Hue</p><p>Tone</p><p>Shade</p><p>Tint</p><p>5.</p><p>A mixture of a color with grey.</p><p>Saturation</p><p>Gradient</p><p>Tone</p><p>Tint</p><p>Hue</p><p>Shade</p><p>6.</p><p>A spectrum of color that gradually changes from one to another.</p><p>Gradient</p><p>Tint</p><p>Shade</p><p>Tone</p><p>Saturation</p><p>Hue</p><p>Color schemes</p><p>The color wheel can help you choose a color palette for your design.&#160;You can use it to see the relationship between colors.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a048f36e2a7eb7103d051ad1af7ba8e9','adobe-illustrator-m2-l6-lesson-5','5018a75ca7eb978ab6c162f5b71a6845','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>File Formats</h3><p>File Formats</p><p>Let’s take a look at some of the common file formats you’ll use as a designer.</p><p>An AI file is a vector file created by Adobe that can only be created or edited with Adobe Illustrator. It is used for creating logos, graphics, and illustrations. You can open these files back up in Illustrator and edit the text or other elements.</p><p>JPEGs –&#160;joint photographic experts group files –&#160;are often used for photographs on the web. You can balance file size and image quality to get a small file to use on the web. These will always be in the shape of a rectangle or square with a solid background.</p><p>PNGs – portable network graphics – are raster images which can have a transparent background. They are useful for logos, icons and other graphics where you want a transparent background.</p><p>A GIF – graphic interchange format – is a raster image that can support up to 256 colors These are useful for simple web graphics like buttons, charts and icons. GIFs can support basic animation.</p><p>A TIFF – tagged image file format – is a raster file with a large file size and high quality. These are usually too big to use on the web but are ideal for high-quality printing.</p><p>An EPS – encapsulated postscript file – is a vector that you can resize without losing any quality. This file format is useful when you want to provide an editable file for graphics and illustrations.</p><p>An SVG – scaleable vector graphic – is a vector format that’s great for the web because it can be scaled to any size without loss of quality. These files are often used on responsive websites and in apps.</p><p>A PDF – portable document format – can be vector or raster depending on how it is created. It is useful for sharing files but isn’t a good option for files that need to be edited because it isn’t straightforward to do so. You’ll send your printer a PDF, but you might also use these on the web to share documents.</p><p>Reading 5</p><p>Answer Key:Off</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>File formats</p><p>In the video, you learned about some of the common file types that designers use and you found out about their strengths and limitations.</p><p>Based on what you learned in the video, fill in the blanks below with the name of the best file format for each situation.&#160;Here are the file formats to choose from – but you won&#39;t need all of these.</p><p>SVG</p><p>PNG</p><p>AI</p><p>GIF</p><p>EPS</p><p>PDF</p><p>TIFF</p><p>JPG</p><p>An animation for the web in a small file sizeShow Hint</p><p>A graphic with a transparent backgroundShow Hint</p><p>A photo in a small file size for the webShow Hint</p><p>A logo that someone else can reopen and edit, when you are uncertain which software they are usingShow Hint</p><p>A photo for high-quality printShow Hint</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Resolution</p><p>Units of measurement such as dots per inch (DPI) or pixels per inch (PPI) refer to the number of pixels in one inch of an image.&#160;The more dots or pixels you have, the more detail you have in your image –&#160;your image has a high resolution.</p><p>On the web, your images will often display at 72dpi (72 dots or pixels per inch) – a low pixel density, but you wouldn’t want this same low quality if you were printing your image.</p><p>For print, your image should be at least 300 dpi, a much higher pixel density than the web displays.</p><p>You can’t add pixels to an image, so if you try to resize a 72 DPI image for print, your pixels will get bigger and become distorted.&#160;It is always better to start your designs larger than you need them and size down.</p><p>Size and aspect ratio</p><p>You will need to set up your designs to fit commonly used paper sizes.&#160;The United States and Canada use slightly different sizes than most of the rest of the world.&#160;You probably have Letter size paper in your printer at home, which is 8.5 by 11 inches.&#160;You might also use Legal paper, which is 8.5 by 14 inches.&#160;If you are printing business cards, these are typically 3.5 by 2 inches.&#160;In much of the rest of the world, the International Standard (ISO-216) paper sizes are used.&#160;The most common of these is A4 (8.25 by 11.25 inches) and these range from A0 (largest) to A10 (smallest).</p><p>You should also be aware of some standard aspect ratios for images.&#160;&#160;Aspect ratio is the proportional relationship of width to height.&#160;A 6 x 4 inch image has an aspect ratio of 3:2, for example.&#160;Common aspect ratios are:</p><p>1:1 Ratio - square, widely used on social media.</p><p>3:2 Ratio - widely used for print.&#160;Images framed at 1080 x 720 pixels or 6 x 4 inches are set within this aspect ratio.</p><p>4:3 Ratio - often used for video and the web.&#160;&#160;An image sized at 1024 x 768 pixels or 8 x 6 inches fits this ratio.</p><p>16:9 Ratio - often used in presentation slides and for widescreen video.&#160;&#160;Images sized at 1920 x 1080 pixels and 1280 x 720 pixels fit this ratio.</p><p>Preparing your design files for print</p><p>When you are sending a file to a printer, you will need to save your text as outlines.&#160;When you send a file to someone else, you are relying on the idea that they will have the font you have used installed in their computer.&#160;If they don’t have that font, this may mean defaulting to a different font so your design doesn’t look as you intended.&#160;You can save your text as outlines –&#160;converting it to a shape rather than editable text –&#160;to prevent any problems, but you can’t edit the text anymore, so make sure you save a copy of your design in an AI file and then send an EPS with outlines to the print shop.</p><p>Guidelines for working with files</p><p>If your image will be used on the web or mobile, use JPEG, PNG, GIF or SVG.</p><p>If your images will be printed, use TIFF.</p><p>If you want your printer or designer friend to be able to edit the file but you&#39;re not sure what software they use, choose EPS.</p><p>If you want to keep a version that remains editable for yourself, choose your software&#39;s native file format such as AI for Illustrator.</p><p>Find a balance between image quality and file size, if you are saving files for the web.</p><p>Send the best quality images you can, if sending files to print.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5bcb50ad56898c9a605e168ac090010e','adobe-illustrator-m2-l7-summary','5018a75ca7eb978ab6c162f5b71a6845','Summary','text',12,'<h2>Summary</h2><section><h3>Module 2 Summary</h3><p>Summary</p><p>Great work!&#160;You have successfully completed this module on Understanding Digital Graphics and Illustrations!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Understood key terminology related to digital graphics and illustrations.</p><p>Demonstrated knowledge of basic design principles and best practices employed in the digital graphics and illustration industry.</p><p>Demonstrated knowledge of typography and its use in digital graphics and illustrations.</p><p>Demonstrated knowledge of color and its use in digital graphics and illustration.</p><p>Demonstrated knowledge of image resolution, image size, and image file format for web, video, and print.</p><p>Additional Resources</p><p>The following books, articles,&#160;and websites are additional resources to learn more about this topic.&#160;(Not required reading)</p><p>Adobe Blog.&#160;(2016).&#160;8 Basic Design Principles to Help You Create Better Graphics.(opens in a new tab)</p><p>Hubspot Blog.&#160;(2018).&#160;10 Types of Image File Extensions and When to Use Them.(opens in a new tab)</p><p>JotForm Blog.&#160;(n.d.) A Crash Course in Typography:&#160;The Basics of Type.(opens in a new tab)</p><p>Rasmussen College.&#160;(2017).&#160;Talk the Talk:&#160;25 Graphic Design Terms Every Serious Designer Should Know(opens in a new tab).</p><p>Smashing Magazine (2010).&#160;Color Theory for Designers, Part 1:&#160;The Meaning of Color.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1c230bc6e49e64a871360d31c838712b','adobe-illustrator-m2-l8-module-2-project-empty','5018a75ca7eb978ab6c162f5b71a6845','Module 2 Project Empty','text',12,'<h2>Module 2 Project Empty</h2><section><h3>Module 2 Project</h3><p>2200</p><p>Adobe Illustrator</p><p>Understanding Digital Graphics and Illustrations - Project</p><p>For this assignment, you will be creating your first design composition. Imagine that you are at the early stages of the project and are trying to work out the best concept for your design. Before you get on the computer, it is a good idea to play with ideas either by sketching/drawing, or using collage, so that&#39;s what you&#39;ll be doing here. Your goal is to come up with the best design concept that you can, by hand. Please choose one of the following projects to work on:</p><p>A poster for a new skateboarding and BMX park opening up in your town.</p><p>Social media graphics (profile banner &amp; ad) for a coffee bar opening soon.</p><p>A magazine ad for a new electric sports car model.</p><p>Packaging design for a luxury line of watches.</p><p>Let your creativity loose on this task! You may want to do some research online to see the kinds of designs that have been created for related products and services.&#160;Behance(opens in a new tab)&#160;is a great place to get design inspiration.</p><p>Give the product or service a name.</p><p>Choose or create images and graphics. Make sure to check permissions and use Creative Commons, CC0 or public domain images, or your own.</p><p>Pay special attention to your use of design elements and principles, and your use of color</p><p>Add typographic elements, manipulating the type you choose to suit the design</p><p>Scan or photograph your work and upload it as a JPG with appropriate size and dimensions.</p><p>Review the rubric below to see how you will be graded.</p><p>Understanding Digital Graphics and Illustrations - Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Design</p><p>16 points Composition is well designed for the product or service chosen. Student has made careful decisions about typography, color and the design elements and principles discussed, and the design is visually appealing.</p><p>9-15 points Composition is adequate for the product or service chosen. Student has madesome decisions about typography, color and the design elements and principles discussed, but could improve on the visual appeal.</p><p>8-0 points Composition is poorly designed and not a good fit for the project chosen. Student has not been selective about what to include in terms of typography and color, and has not considered the design elements and principles discussed. The composition lacks visual appeal.</p><p>16</p><p>File sharing</p><p>2 points The student has shared the file using the requested file type and has worked at an appropriate size and dimension for the project selected.</p><p>1 point The student has shared the file using the requested file type but has not worked at an appropriate size and dimension for the project selected.</p><p>0 points The student has not shared the file using the requested file type and/or has not worked at an appropriate size and dimension for the project selected.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5ab55c245dc7dee805857ffdef551bfc','adobe-illustrator-m2-l9-module-2-quiz','5018a75ca7eb978ab6c162f5b71a6845','Module 2 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Ditital Graphics & Illustrations. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('73ecf22e91fc43e117ac5d1669a5fab1','adobe-illustrator-module-3','2eeac88d9b6058d9d55e1dcf25daf550','Module 3: Understanding Illustrator Part 1',3) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c045e619edfdf9c132087194fa99e41e','adobe-illustrator-m3-l1-introduction-purpose-and-objectives','73ecf22e91fc43e117ac5d1669a5fab1','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Welcome back to the Illustrator course. This is the intro video for the module on Understanding Adobe Illustrator Part I. In this module, we’re going to explore the interface of Adobe Illustrator CC, getting to know the basic tools that you’ll use in your day-to-day life as a designer.</p><p>You’ll soon discover that creating graphics (or creating any type of art) is about seeing shapes and lines everywhere! As long as you can recognize and create basic shapes like lines, triangles, and circles, you have promise as a graphic artist! So, over the next few lessons, we’ll find out how Adobe Illustrator can help you to create and manipulate shapes and lines.</p><p>You’ll find your way around the interface and start creating with the many tools. You’ll experiment with transforming shapes. You’ll also set up your workspace for the way that you want to work. Finally, you’ll use the many helpful elements of the interface like artboards, grids, and rulers. Put this all together and your designs will turn out pixel perfect!</p><p>Module Description</p><p>by Adobe</p><p>License:&#160;All Rights Reserved</p><p>In this module, students will take a first look at the Adobe Illustrator CC user interface and begin to find their way around the software.&#160;They will explore how the fundamental tools work, finding out how to select objects, move them, draw lines and shapes and make transformations.&#160;Next, they will set up their workspace, and finally, they will discover ways to use tools like rulers and guides to facilitate the design process.</p><p>Objectives</p><p>In this module, students will:</p><p>Navigate Adobe Illustrator</p><p>Identify elements of the Illustrator CC user interface and demonstrate knowledge of their functions</p><p>Define the functions of commonly used tools, including selection tools, the Pen tool, and other drawing tools, shape tools, and transformation tools.</p><p>Navigate, organize, and customize the workspace</p><p>Use non-printing, design tools in the interface, such as rulers, guides, bleeds, and artboards.</p><p>Polling Question</p><p>Which type of graphic design project are you most looking forward to using Adobe Illustrator for?</p><p>Branding &amp; logos</p><p>Printed material like infographics and posters</p><p>Graphics for the web</p><p>Graphics for motion and video</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Printable portion of the work area.</p><p>Bounding Box</p><p>The inner area of an object.</p><p>Fill</p><p>A single level in the stacking order that can hold any number of objects.</p><p>Layer</p><p>The line that forms the shape of an object.</p><p>Path</p><p>A temporary frame around a selected object that shows the object&#39;s outer dimensions.</p><p>Guides</p><p>Nonprinting lines that can be used to creat boundaries or guidelines in a drawing.</p><p>Artboard</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Printable portion of the work area.</p><p>Fill</p><p>Artboard</p><p>Guides</p><p>Bounding Box</p><p>Path</p><p>Layer</p><p>2.</p><p>The inner area of an object.</p><p>Fill</p><p>Guides</p><p>Artboard</p><p>Bounding Box</p><p>Path</p><p>Layer</p><p>3.</p><p>A single level in the stacking order that can hold any number of objects.</p><p>Bounding Box</p><p>Guides</p><p>Layer</p><p>Fill</p><p>Artboard</p><p>Path</p><p>4.</p><p>The line that forms the shape of an object.</p><p>Fill</p><p>Layer</p><p>Bounding Box</p><p>Path</p><p>Guides</p><p>Artboard</p><p>5.</p><p>A temporary frame around a selected object that shows the object&#39;s outer dimensions.</p><p>Fill</p><p>Artboard</p><p>Guides</p><p>Bounding Box</p><p>Path</p><p>Layer</p><p>6.</p><p>Nonprinting lines that can be used to creat boundaries or guidelines in a drawing.</p><p>Layer</p><p>Path</p><p>Fill</p><p>Artboard</p><p>Guides</p><p>Bounding Box</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c6c09b5df7b06ec5754651ff6d6227b2','adobe-illustrator-m3-l2-lesson-1','73ecf22e91fc43e117ac5d1669a5fab1','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Getting Started</h3><p>Getting Started</p><p>Let&#39;s take a first look at Adobe Illustrator CC. I&#39;m creating this recording on a Mac, so if you&#39;re using Windows your screen might look slightly different. You may want to follow along with me. You can pause the video at any time.</p><p>The home screen appears when there are no documents open in Illustrator and this lists your recent files and presets. From here, you can create a new file, access tutorials, choose from popular presets and see your recent documents. The contents of your home screen might look a little different from mine, depending on your Creative Cloud membership. You can also get back and forth from the home screen by clicking on the AI symbol or the house.</p><p>From the home screen, click on Create New. Start by choosing a preset. For example, the Print preset shows various sizes and document options you can set for a new document. Name - this is what your file name will be. It automatically sets to Untitled. You don&#39;t need to name it right now, you can always save this as your file name later. Number of artboards - an artboard is like the digital version of the canvas an artist might use. Sometimes, you&#39;ll need just one artboard, but for other projects it might be helpful to have two or three artboards in the same file. These can be different sizes. If you were creating graphics for social media and you need three variations: one for Facebook, one for Twitter and one for Instagram, for example, you could create these in one file with three artboards. You can also add artboards once you are working in your file, so don&#39;t worry if you&#39;re not sure how many are going to use right away. Orientation - this is a quick way to change your artboards from portrait to landscape. Color mode - you can change your color mode automatically here by changing the profile. If you want to design something for print, you will use CMYK and if you are designing for the web set this to RGB.</p><p>Once you have made your selections, click Create. This will set up a new file with the number of artboards you have chosen. First, let&#39;s make sure you can see everything in your document. You may want to use View &gt; Fit in window if you can&#39;t.</p><p>The workspaces of the different applications in Creative Cloud look similar so that you can move between the applications easily. If you are already familiar with Photoshop or InDesign, for example, this should feel familiar to you. There are various ways of organizing your workspace and we&#39;ll dig into that later. For now just to make sure we&#39;re all seeing the same thing, please go to Window &gt; Workspace. If you see a Reset essentials option near the bottom, choose that option. If the reset command has any other workspace name, choose Essentials near the top of the list then choose Window &gt; Workspace &gt; Reset Essentials. This will make sure you&#39;re seeing Illustrator as it should be out of the box, without any presets or workspace customizations from you or another user.</p><p>There are three useful navigation tools to know that can help you find your way around Illustrator. These are the Zoom tool, the Hand tool and the Artboard tool. First the Zoom tool. Located in the Toolbar, this can be used to show you more detail of a document. To change from zoom in to zoom out, press ALT on Windows or Option on a Mac and plus or minus. You can also access zoom controls from the View menu. You&#39;ll use this to zoom in when you are working on the fine details of a design and zoom out when you are working on a composition.</p><p>The Hand tool, found by clicking and holding the Zoom tool in the Toolbar, allows you to pan across a document. As we discussed, an artboard is like a canvas. You can have many artboards in one Illustrator file in case you want different versions or sizes of a graphic, for example. To create a new Artboard, select the Artboard tool in the Tools panel and drag to create an artboard. Choose an artboardpreset from the Properties panel to resize the new artboard and drag the artboard to position it.</p><p>In this video, you had a first look at the Adobe Illustrator CC interface.</p><p>You can pause these videos any time you need to, and it&#39;s a good idea to follow along if you can.&#160;Illustrator is a powerful tool, and there are often multiple ways to do what you want to do, so there is a lot of functionality to learn.&#160;But don&#39;t worry, you&#39;ll pick it up as you try working with the different tools and panels.</p><p>Your turn!</p><p>Take a few moments now to try this out for yourself.&#160;Open up Illustrator, set up a new file and choose one of the available presets.&#160;Make sure your Workspace is set to Essentials.&#160;Try out the Zoom too, Hand tool and create a new Artboard with the Artboard tool.</p><p>You can also try out some of the keyboard shortcuts below, which will make your life easier as you find your way around</p><p>Keyboard shortcuts</p><p>Here are some of the commonly used Keyboard shortcuts for Adobe Illustrator.&#160;You can&#160;export a full list of keyboard shortcuts from Illustrator as a text document by doing the following:</p><p>Choose Edit &gt; Keyboard Shortcuts</p><p>Click Export Text on the lower-left corner of the Keyboard Shortcuts dialog box</p><p>Navigate to the desired location to save the text file</p><p>Click Save</p><p>Function</p><p>Windows</p><p>Mac</p><p>Undo</p><p>Ctrl + Z</p><p>Command + Z</p><p>Redo</p><p>Shift + Ctrl + Z</p><p>Shift + Command + Z</p><p>Cut</p><p>Ctrl + X</p><p>Command + X</p><p>Copy</p><p>Ctrl + C</p><p>Command + C</p><p>Paste</p><p>Ctrl + V</p><p>Command + V</p><p>Paste in front</p><p>Ctrl + F</p><p>Command + F</p><p>Paste at back</p><p>Ctrl + B</p><p>Command + B</p><p>Paste in place</p><p>Shift + Ctrl + B</p><p>Shift + Command + B</p><p>Selection tool</p><p>V</p><p>Type tool</p><p>T</p><p>Line Segment tool</p><p>\ (backslash)</p><p>Rotate tool</p><p>R</p><p>Free Transform tool</p><p>E</p><p>Switch to Hand tool (when not in text-edit mode)</p><p>Spacebar</p><p>Zoom in</p><p>Ctrl + =</p><p>Command + =</p><p>Zoom out</p><p>Ctrl + -</p><p>Command + -</p><p>Hide guides</p><p>Ctrl + ;</p><p>Command + ;</p><p>Show grid</p><p>Ctrl + &#39;</p><p>Command + &#39;</p><p>Select all</p><p>Ctrl + A</p><p>Command + A</p><p>Deselect</p><p>Shift + Ctrl + A</p><p>Shift + Command + A</p><p>Next, we&#39;ll take a look at the workspace where you&#39;ll create<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c7b3a246403970b97dff7341be149fd1','adobe-illustrator-m3-l3-lesson-2','73ecf22e91fc43e117ac5d1669a5fab1','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Exporing the Workspace</h3><p>Exporing the Workspace</p><p>Let&#39;s take a look at some parts of the workspace. The Application frame is where all parts of the workspace fit together in one single window and respond to each other so that nothing overlaps. If I click and drag my window around it all moves as one. Then, my panels won&#39;t disappear if I switch or click outside of the application. You can switch the Application frame on and off on a Mac using Window &gt; Application frame depending on whether you prefer a single window or if you&#39;d like to move your panels around.</p><p>The Application bar across the top has your workspace switcher and other application controls. If you are working on Windows, your menus will be here as well. On a Mac, you&#39;ll only see this when the Application frame is off.</p><p>In the Menu bar you&#39;ll find lists with lots of menu items in them. If you see an arrow to the right, new options will pop up when you move your cursor. You should take some time to have a look at the menu bar items to get familiar with them. You can pause a video for a few minutes if you need to.</p><p>The Document window displays the file you&#39;re working on. If you have more than one document open in Illustrator at one time, these will be tabbed and you can easily switch between them. On the left side of the workspace we have the Toolbar. If you don&#39;t see all of the options here, double click on the Toolbar title. You can view this in one or two columns depending on works best for the size of your screen. Double click the title to switch between the two modes. You can also move the Toolbar by dragging it around from from the title or hide it by clicking the X. Open it again from Window &gt; Tools.</p><p>In the Toolbar, you have selection tools, drawing and typing, modification, information and color, and other functional tools. You also have quick controls for color, and at the bottom of that panel, you can change your drawing and screen modes. Hover over anything to find out what it&#39;s called. The panels on the right help you to change the fine details of your work. You can group them and move them around. The default panels include color, brushes, libraries and more. You can select which panels to display or hide by going to Window and checking the panels you want to display.</p><p>In the video, we explored the elements of the Illustrator CC user interface.&#160;We found out about:</p><p>The Application frame</p><p>The Menu bar</p><p>The Document window</p><p>The Toolbar</p><p>The Properties panel</p><p>The Control panel</p><p>The Status bar</p><p>Let’s see if you remember some of the parts of the interface.</p><p>5</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Illustrator workspace</p><p>The hotspot points on the image are as follows:</p><p>Options panel</p><p>This panel shows you contextual options for the tool you have currently selected.</p><p>Toolbar</p><p>On the left, the Toolbar contains tools for creating and editing artwork. Similar tools are grouped together. You can access them by clicking and holding a tool in the Toolbar</p><p>Document window</p><p>The Document window displays the file you’re currently working on. Multiple open documents appear as tabs in the Document window.</p><p>Panels</p><p>On the right, the Panels include Properties, Layers, and other panels that contain a variety of controls for working with artwork. You can find a full list of panels under the Window menu.</p><p>Artboard</p><p>The artboard is the canvas where you create your art.</p><p>Status bar</p><p>The Status bar shows the zoom level, artboards and active tool.</p></section><section><h3>Panels</h3><p>Panels</p><p>Let&#39;s take a look at some of the panels in more detail. The Properties panel on the right shows you can contextual settings and controls. For any selection the Properties panel displays two sets of controls. First transformation and appearance controls like width, height, fill, stroke, opacity and so on. And second dynamic controls which depend on the contents of your selection. For example, you can adjust the character and paragraph attributes of text objects. For image objects the properties panel displays crop, mask, embed or unembed and image trace controls. If you select a text box, the controls related to text modification are displayed in the Properties panel.</p><p>You&#39;ll get similar information in the Control panel above the document window. You can switch this on from the Windows menu if you don&#39;t see it. Options displayed in the control panel vary depending on the type of object or tool you select. For example, if I create a text box and select it, I can see formatting options for my text up here like color, font, and alignment. When nothing is selected in the file, the Control panel options open up the Document set up dialog box and the Preferences dialog box. Other options set the default stroke and fill attributes for the next object you create.</p><p>The status bar appears at the lower left edge of the illustration window. It displays the current zoom level. The active artboard and number of artboards as well as artboard navigation tools and the tool you are currently using.</p><p>In the video, we had a look at two of the most useful panels in Illustrator – the Control panel and the Properties panel.&#160;Using these panels, you can control the fine details of the tools you are using.</p><p>Your turn!</p><p>Please open up Illustrator and have a look around to get familiar with the interface.&#160;Explore:</p><p>What’s in the menus?</p><p>What happens when you hover over a menu item that has an arrow on the right?</p><p>Where is the toolbar and how can you access hidden tols?</p><p>What&#39;s in the properties panel?</p><p>What’s in the status bar?</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('df0f57992a5aa818d7c8d8dde804a845','adobe-illustrator-m3-l4-lesson-3','73ecf22e91fc43e117ac5d1669a5fab1','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Section Tools</h3><p>Section Tools</p><p>In this lesson&#39;s video series, we&#39;ll be having a look at each of the categories of tools that you have access to in Illustrator.&#160;Broadly, the tools are organized as follows:</p><p>Select</p><p>Draw (and under this, some sub-sections)</p><p>Paint</p><p>Reshape</p><p>Symbol</p><p>Graph</p><p>Type</p><p>Paint</p><p>Navigate</p><p>In Illustrator, the tools are broadly organized in the following categories: select, draw (and under this some subsections: paint, reshape, symbol graph). There is also type tools, paint tools and navigate tools.</p><p>We&#39;re going to have a look at these different tool sets and find out what you can do with them. Over here on the left is the Toolbar, as you know. Some tools have properties that will appear in the Properties panel, so make sure you can see that too.</p><p>To select a tool, you can either click on it in the Toolbar or use a keyboard shortcut. The keyboard shortcut is displayed in its tooltip. For example, you can choose the Selection tool by pressing the V key. If there is a small triangle in a tool&#39;s lower right corner, click and hold to view the hidden tools, then click on the tool you want to select. You can also hold down ALT on Windows or Option on a Mac, then click the tool to cycle through and select hidden tools.</p><p>The pointer for most tools is the same as the icon in the Toolbar. If you are working with precise artwork you can change the pointer for the tool to crosshairs to get more accuracy when you were working with details. For example, if I click on the Pen tool and then push the Caps Lock on my keyboard, I can switch to crosshairs. Just hit Caps Lock again to switch back to regular pointers. There are different ways of selecting objects in Illustrator, some with tools and some with other functions. There are five selection tools. They are: Selection, Direct selection, Group selection, Magic wand and Lasso. You&#39;ll use the Selection and Direct selection tools a lot, so let&#39;s have a look at those.</p><p>The black arrow is the Selection tool and it&#39;s keyboard shortcut is V. This is the default tool and you can use it to select entire objects and move them around. Either click on an object or drag an area around the objects you want to select. To add or remove objects from your selection, hold down Shift and click or drag around the objects you want. It will pick up objects or groups of objects. When you are using this tool with a group of objects, you can go into Isolation mode by double clicking on a group. So if I do that here I&#39;ll be in Isolation mode and you can tell because you get these breadcrumbs up here with a blue line underneath. If you wanted to keep digging deeper you could keep double clicking, if there are groups within the group. These are all grouped together, so if I double click I&#39;m going to go inside of this group. See how it shows you it with a different opacity. It will print just fine, This is just focusing you in. It is very helpful if you&#39;re dealing with graphics that have lots of parts and some of them are grouped together and you only want to focus on certain sections. If you want to exit out of this you can hit the Escape or double click outside your selection.</p><p>Here, we have the Direct selection tool. With this, you can select individual objects or anchor points and it ignores your group settings. So if I click on one of these it won&#39;t get the full group. See how it works? I can click and drag over anchor points or click on them and if I try to move this it will only move that anchor point but everything in my group stays as it is.</p><p>This lets you make selections in more fine detail than the regular Selection tool.</p><p>In this clip, we had a first look at the Selection tools.</p><p>There are a lot of tools to be aware of, but depending on the type of work you do, you&#39;re likely to work with the same ones repeatedly and use others much less often.&#160;Don&#39;t worry if you can&#39;t remember them all right away!&#160;The purpose of these videos is to help you get to know what&#39;s possible and introduce you to some of the tools.&#160;We&#39;ll dig deeper into their usage later in the course.</p><p>In Illustrator, like in the other Adobe Creative Cloud applications, there is usually more than one way to do whatever it is you are trying to do, so over time you will develop processes that you like and you&#39;ll get faster at it, too.</p><p>In the video, we also had a first look at the tool categories that you’ll see in Adobe Illustrator CC, and we found out how to access hidden tools and how to change the pointer for your tool.</p><p>Your turn!</p><p>Open up Illustrator now to make sure that you can:</p><p>Access hidden tools</p><p>Change your pointer to crosshairs and back again</p><p>Try out the difference between the Selection and Direct Selection tools</p><p>Next, we&#39;ll take a look at some of the Drawing tools.</p></section><section><h3>Drawing Tools</h3><p>Drawing Tools</p><p>There are lots of drawing tools in illustrator. The ones you will probably use the most are the Pen and the Add or Delete anchor point tools that go along with this, the Line segment and Shapes. So let&#39;s take a look at some of these.</p><p>The Pen is one of the tools you&#39;ll use the most, but it can be a little tricky to master it, so don&#39;t worry if you can&#39;t get it to do what you want on the first try. The simplest path you can draw with the Pen tool is a straight line, made by clicking the Pen tool to create two anchor points. Each time you click, you create a path made of straight line segments connected by corner points. Choose the tool. Position your cursor where you want the line to start and click to define the first anchor point –&#160;don&#39;t drag. You won&#39;t see your first segment until you click your second anchor point, so click where you want the segment to end. Shift-click if you want your angle to be a multiple of 45. Click each time you want a new anchor point. The last anchor point is a solid square and the others are hollow so that you know where you are. Complete your path by closing it or leaving it open. Put your Pen over the first anchor point you created and a small circle will appear next to your pointer. Click to close the path. You can leave your path open by Control or Command-clicking away from it, or clicking enter on your keyboard.</p><p>You can also us<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('fb63645d153534295d5a8f04b26b202d','adobe-illustrator-m3-l5-lesson-4','73ecf22e91fc43e117ac5d1669a5fab1','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>The User Interface</h3><p>The User Interface</p><p>Choose Illustrator, preferences, user interface. On Windows, preferences is in the Edit menu. Here you can customize the interface to show one of the following available color options. Dark, medium dark, medium light and light. You can also set the color of the canvas from this menu. You can create your own custom workspace by moving around the panels. When you have a setup that you like you can save it by going to window, workspace, new workspace. Choose the name. Select OK and then it will then show up in your workspace menu.</p><p>In this video, we looked at workspace options and Panels, including the Control Panel.</p><p>Your turn</p><p>Take a moment to have a look in Illustrator yourself and make sure you know how to:</p><p>How to switch workspaces</p><p>How to dock, minimize, remove and group panels</p><p>What is contained in the Control Panel</p><p>How to change where the Control Panel is displayed</p><p>Next, we&#39;ll have a look at the Toolbar.</p></section><section><h3>Customize the Workspace</h3><p>Customize the Workspace</p><p>In Illustrator, you will use various elements of the interface such as panels, bars and windows to work on your designs. An arrangement of these elements is called a workspace. You&#39;ll find that the workspaces and Illustrator looks similar to other creative cloud applications like photoshop or InDesign. So over time as you get more comfortable with the apps, you&#39;ll be able to switch between them easily.</p><p>You can adapt Illustrator to your own workflow by selecting from several preset workspaces or by creating one of your own. There are different workspaces available in Illustrator and you might change the workspace depending on the type of work you were doing. This sets you up for different types of work by displaying different panels by default.</p><p>Watch how different panels show if I switch to printing and proofing or painting for example. Before you start working with workspaces it&#39;s a good idea to reset things to their original location. So let&#39;s go to essentials reset essentials to do this so that we are all looking at the same thing.</p><p>If you have more than one document open in Illustrator you&#39;ll see that your document windows are tabbed here at the top. You can rearrange these tabs or undock them if you&#39;d like. If you undock them you can put them back together again like this.</p><p>A dock is a collection of panels or group of panels displayed together. You can dock and undock panels by moving them into and out of a dock. To remove a panel from a group drag it out of its dock by its tab or title bar. You can drag it into another dock or leave it free floating. To dock a panel, drag it by its tab back into the dock. You&#39;ll see a blue outline appear and you can drop it. You can remove any panels that you don&#39;t want to see by closing them using the x. To get them back select the panel you want from the windows menu, use the arrows in the top right of the title bar or any panel to collapse or expand it. This can help you to clean up the interface if you are working with a lot of panels.</p><p>You can minimize a panel by double clicking on its tab. You might prefer to group certain panels together. You can do that by dragging panels around and docking them together to make panel groups. When you drag a panel out of its dock but not into a drop zone, the panels float freely. You can position a floating panel anywhere in the workspace or stack floating panels so that you can move them as a group by dragging the top title bar. Most panels have menus of their own that you can access by clicking the menu icon in the upper right corner of the panel.</p><p>Go to window &gt; control. The contents of the control panel change depending on what tool you were using. But you can also choose to show and hide certain controls here by switching them on and off in the control panel menu. I&#39;ve got the selection tool selected. Watch what happens if I switch off fill and stroke for example. See how it disappears from the control panel.</p><p>When a word is underlined in the control panel you can click on it to get a new panel or dialog box. For example, if I click on stroke, the stroke panel appears for me and I can change those settings. You can also change where the control panel is displayed. I can move it to the bottom of my workspace by choosing dock to bottom in the menu on the right end of the control panel. You can also have the control panel float if you click and drag it here on the left.</p><p>In this video, we looked at the toolbar and keyboard shortcuts in Illustrator.</p><p>Your turn</p><p>Open up Illustrator for yourself and make sure you know how to:</p><p>Add and remove tools from the toolbar</p><p>Customize keyboard shortcuts</p><p>Next, we&#39;ll find out how you can make the user interface just the way you like.</p></section><section><h3>Customize the Toolbar</h3><p>Customize the Toolbar</p><p>The Toolbar can be either basic or advanced.</p><p>The basic Toolbar is displayed by default and that&#39;s what we&#39;ll see because we&#39;ve reset our Essentials workspace. This gives us a selection of commonly used tools. But you might prefer to see the advanced Toolbar which shows all the tools available. To switch between these, you can go to Window &gt; Toolbars &gt; Advanced. You can customize a Toolbar by moving tools between the Toolbar and the drawer.</p><p>Open the drawer by clicking the ellipse &gt; Edit Toolbar at the bottom. You can add tools from the drawer to the Toolbar or remove tools from the Toolbar by dragging them to the drawer where they will automatically go into the section where they belong.</p><p>To remove a tool from the Toolbar, drag the tool from the Toolbar and drop anywhere in the drawer. The tool is automatically added to the category to which it belongs. To go back to the original setting, click Reset in the flyout menu of the drawer. You can also use the Toolbar to change your screen mode, to go from normal to full screen, for example, and to change your drawing mode from normal to draw behind.</p><p>You can also create your own custom Toolbar by choosing New Toolbar from the flyout menu or going to Windows &gt; Tools &gt; New toolbar. Choose a name and click ok, and you will see a blank Toolbar where you can add tools to the Toolbar from the drawer.</p><p>Choosing Edit &gt; Keyboard shortcuts opens up a di<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('720d7ac6d6ed75b11fa1b125455bf062','adobe-illustrator-m3-l6-lesson-5','73ecf22e91fc43e117ac5d1669a5fab1','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Rulers</h3><p>Rulers</p><p>There are lots of design tools in the Adobe Illustrator interface that you won&#39;t see when you print your file.</p><p>But these are just as important for helping you get your design right as the objects you put on your artboard. We&#39;re going to explore some of these design tools and find out how they fit into your workflow. It&#39;s tempting to just eyeball things as you&#39;re working, but to make sure your designs look polished, you&#39;ll need to use rulers and guides to make sure your spacing is right.</p><p>To show or hide rulers, choose View &gt; Rulers &gt; Show rulers, or View &gt; Rulers &gt; Hide rulers, or on Windows you can use Control R and on a Mac, Command R. See how they appear across the top and left? The point where zero appears on each ruler is called the ruler origin. The default origin point for rulers is the upper left corner. You can change the origin by clicking on the point where the rulers intersect up here and dragging to where you want the new origin. See how my cursor changes to a crosshair? Rulers can measure in relation to your document (global) or your artboard. You can switch between these modes and you might find this helpful if you are trying to take measurements in a document with many artboards.</p><p>The default unit of measurement in Illustrator is Picas, but you can change this by right-clicking on the top left corner where your rulers meet. You&#39;ll see a drop-down menu with other options.</p><p>You can display a grid to help you line up objects more easily while you were working. Don&#39;t worry it won&#39;t print. It&#39;s just here for your reference. To show or hide the grid, choose View &gt; Show grid or View &gt; Hide grid. You can turn on a setting to snap your objects to the grid which works if you are within two pixels. Choose View &gt; Snap to grid, then select the object you want to move and drag it where you want it to go and it will snap to your grid.</p><p>You can also snap to the individual pixels from View &gt; Snap to pixel.</p><p>You can change the settings for your grid, including changing it from lines to dots and what color it is under the Preferences menu. Illustrator &gt; Preferences &gt; Guides and grid on a Mac, or Edit &gt; Preferences &gt; Guides and grid on Windows.</p><p>You can create ruler guides – straight vertical or horizontal lines – and guide objects, vector objects that you convert to guides. Click in the ruler area and drag down to place a guide on your artboard. You can also lock and unlock these guides so that you won&#39;t accidentally move them. View &gt; Guides &gt; Lock or unlock guides.</p><p>To move a guide, drag it or copy it. To delete a guide, select it and press backspace (or delete), or choose Edit &gt; Cut or Edit &gt; Clear. To delete all guides at once, Choose View &gt; Guides &gt; Clear guides. You can also use a shape or line as a guide. For example, I can draw a line and convert it to a guide. First, I select my line and then go View &gt; Guides &gt; Make guides. Or I can use the faster right-click &gt; Make guides option. This will turn my line into a custom guide that I can lock and use to align other objects.</p><p>Smart guides are temporary snap-to guides that appear when you create or manipulate objects or artboards. They help you align, edit and transform objects or artboards relative to other objects or artboards and by displaying position values. These are helpful when you create an object with a Pen or Shape tool. You can position your new object relative to an existing one. You can also use smart guides to position anchor points that present angles like 45 or 90 degrees when you are using the Pen, Dhape or Transform tools. They automatically appear when you are transforming an object. Choose Illustrator &gt; Preferences &gt; Smart guides or Edit &gt; Preferences &gt; Smart guides on Windows to set preferences for smart guides including color, labels and snapping tolerance.</p><p>In this video, we explored rulers, grids and guides in Adobe Illustrator CC.&#160;You’ll use these all the time when you are creating your designs.</p><p>Your turn!</p><p>Please try these out on your own by opening up Illustrator to make sure you know how to:</p><p>Show and hide rulers</p><p>Show and hide grids</p><p>Create guides</p><p>Align objects using grids and Smart Guides</p></section><section><h3>The Measure Tool</h3><p>The Measure Tool</p><p>It is useful to know how to measure the distance between objects to make sure your design is evenly spaced. You can use the Measure tool to do this. Choose the Measure tool under the Eyedropper (if you can&#39;t see it, make sure you have the advanced Toolbar open) and then click two points. You will see x and y coordinates and size details in the Info panel.</p><p>Artboards represent the print area. Think of them like pages in a Word document, for example. You can have up to a thousand artboards on one canvas depending on the size of the ones you draw. To create multiple artboards, you can either set this up when you create the document, or you can click the artboard tool and drag the document in the shape, size and location where you want your new artboard. You can choose from artboardpresets if you double click on the Artboard tool. You will get a dialog box. Click ok and drag the artboard out on your canvas. You can also duplicate an existing artboard by selecting it with the Artboard tool and clicking the New Artboard button in either the Control or Properties panel.</p><p>In the Artboards panel: Window &gt; Artboards, you can add, rearrange, delete, reorder and re-number your artboards. Only one artboard can be active at any time. Select the Artboard tool and the artboard, and you can see details about the artboard like its name and preset. You can also change from portrait to landscape orientation. If you want to edit an artboard, click on it and you can resize it by dragging from the corner, or you can choose new width and height values in the Properties or Control panel. Move an artboard by selecting it and select the Move artwork with art board settings in the Properties panel, or don&#39;t, if you want to leave the contents of the artboard behind. Position your pointer in the artboard and drag. In the Artboards panel, Windows &gt; Artboards, use the up and down arrows to reorder your artboards.</p><p>Bleed is the amount of artwork that falls outside of the printed area. You can use this as a m<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4ede9b4dd4d50d5ad01de2ad54f54a9a','adobe-illustrator-m3-l7-module-3-summary','73ecf22e91fc43e117ac5d1669a5fab1','Module 3 Summary','text',12,'<h2>Module 3 Summary</h2><section><h3>Module 3 Summary</h3><p>Summary</p><p>Great work!&#160;You have successfully completed this module on Understanding Adobe Illustrator Part 1!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Navigated Adobe Illustrator</p><p>Identified elements of the Illustrator CC user interface and demonstrate knowledge of their functions</p><p>Defined the functions of commonly used tools, including selection tools, the Pen tool, and other drawing tools, shape tools, and transformation tools.</p><p>Navigated, organize, and customize the workspace</p><p>Used non-printing, design tools in the interface, such as rulers, guides, bleeds, and artboards.</p><p>Additional Resources</p><p>The following books, articles,&#160;and websites are additional resources to learn more about this topic.&#160;(Not required reading)</p><p>Adobe (n.d.) Customize the workspace(opens in a new tab)</p><p>Adobe (n.d.).&#160;Illustrator Tool galleries(opens in a new tab)</p><p>Adobe (n.d.) Printer’s marks and bleeds</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0fabce2eec0f3124da40dfe5d0786ce7','adobe-illustrator-m3-l8-project-empty','73ecf22e91fc43e117ac5d1669a5fab1','Project Empty','text',12,'<h2>Project Empty</h2><section><h3>Module 3 Illustrator</h3><p>2200</p><p>Adobe Illustrator</p><p>Understanding Adobe Illustrator Part I - Project</p><p>Now it’s time to get into Illustrator and try out some of the commonly used tools by creating a simple landscape scene. You might include objects like trees, mountains or hills, birds, sun or clouds –&#160;or any other elements of nature. Make these out of very basic shapes.</p><p>Remember –&#160;it doesn’t have to be perfect or highly detailed. Right now, you are just experimenting, so have fun with it! The image above is an example of what you might aspire to.</p><p>Your task is to:</p><p>Create a scene using the shapes and other drawing tools</p><p>Use rules, guides and grids to help you place objects in your scene</p><p>Experiment with some of the Drawing, Painting and Reshaping tools to see what kind of creative designs you can make</p><p>Move and scale objects as needed using the Selection tools and the Free Transform tool</p><p>Choose fill and stroke colors for your design</p><p>Add some text to your image, choosing a font, size and weight</p><p>Save your file</p><p>Have fun with this! The exercise will get your creative juices flowing and help you to find out what Illustrator can do. You can even post your creation on your fridge when you’re done, if you want to!&#160;Review the rubric below to see how you will be graded.</p><p>Understanding Adobe Illustrator Part I - Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Composition</p><p>7-8 points The composition is well balanced. The student has made careful decisions about layout, color, size and shape.</p><p>4-6 points The composition is adequate. The student has made some decisions about layout, color, size and shape, but could improve on visual appeal.</p><p>1-3 points The composition is poorly designed. The student has not made informed decisions about layout, color, size and shape. The composition lacks visual appeal.</p><p>8</p><p>Use of Illustrator tools</p><p>7-8 points The work demonstrates that the student has used multiple design, painting and reshaping tools to create the scene.</p><p>4-6 point The student has used a limited selection of design, painting and reshaping tools to create the scene.</p><p>1-3 points The student has not used a variety of tools to create the scene.</p><p>8</p><p>Typography</p><p>4 points The student has selected typographic elements including font, size, weight and color that are pleasing within the composition.</p><p>2-3 point The student has selected basic typography but the composition would benefit from more careful selection of elements including font, size, weight and color.</p><p>0-1 point The student has not chosen typographic elements or has chosen font, size, weight and/or colors that do not align within the composition.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('dbd5a067bed8ae136ba31f42d18352d7','adobe-illustrator-m3-l9-module-3-quiz','73ecf22e91fc43e117ac5d1669a5fab1','Module 3 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Understanding Illustrator Part 1. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('3d7d27fb1daa2fdeeddf1353e498a3bc','adobe-illustrator-module-4','2eeac88d9b6058d9d55e1dcf25daf550','Module 4: Understanding Illustrator Part 2',4) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8a4f44e202a6ba790d2169c90716ded4','adobe-illustrator-m4-l1-introduction-purpose-and-objectives','3d7d27fb1daa2fdeeddf1353e498a3bc','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi everyone! Welcome back to the Illustrator course! This is the intro video for the module on Understanding Adobe Illustrator Part II. In this module, we’re going to get to know some of the fun things that you can do in Adobe Illustrator to create your designs. First, we’ll get to know layers – a very useful tool that helps you to organize your work.</p><p>Then, we’ll get our artistic hats on and play with color, brushes, symbols and patterns. You’ll even create your own pattern and graphic style. You can create these to make your workflow easier if you want to reuse similar styles in branded graphics, for example. We’ll have a look at the different views and modes that you can use in Illustrator to make your illustrations and designs, and try them out. We’ll also get some more practice with the vector drawing tools.</p><p>Module Description</p><p>by Adobe</p><p>License:&#160;All Rights Reserved</p><p>In this module, students will take a deeper dive into the functionality of Adobe Illustrator CC.&#160;They will try out using layers, managing colours and brushes, and explore how the various modes and views can be used while working on a graphic design or illustration project.&#160;Finally, they will get some practice with the vector drawing tools that Illustrator provides.</p><p>Objectives</p><p>In this module, students will:</p><p>Use layers to manage design elements.</p><p>Manage colors, swatches, and gradients.</p><p>Manage brushes, symbols, graphic styles, and patterns.</p><p>Demonstrate knowledge of how and why illustrators employ different views and modes throughout the course of a project including vector/outline vs.&#160;display/appearance, isolation mode, and various Draw modes.</p><p>Demonstrate and understanding of vector drawing tools.</p><p>Polling Question</p><p>What do you think is the most important skill for a commercial graphic designer?</p><p>Artistic ability</p><p>Technical and software skills</p><p>Understanding of branding and marketing</p><p>Creativity</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>An arrangement of lines or shapes, especially a design in which the same shape is repeated.</p><p>Symbol</p><p>A line of color that precisely follows a path, sometimes with applied visual effects.</p><p>Pattern</p><p>The visual representation of a concept idea, often using an icon or graphic signifier.</p><p>Graphic Style</p><p>A set of reusable appearance attributes that allow you to quickly change the look of an object.</p><p>Stroke</p><p>A method of converting text to a graphic to avoid issues with fonts once a design is complete.</p><p>Outlines</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>An arrangement of lines or shapes, especially a design in which the same shape is repeated.</p><p>Symbol</p><p>Stroke</p><p>Outlines</p><p>Pattern</p><p>Graphic Style</p><p>2.</p><p>A line of color that precisely follows a path, sometimes with applied visual effects.</p><p>Stroke</p><p>Graphic Style</p><p>Pattern</p><p>Symbol</p><p>Outlines</p><p>3.</p><p>The visual representation of a concept idea, often using an icon or graphic signifier.</p><p>Symbol</p><p>Pattern</p><p>Stroke</p><p>Graphic Style</p><p>Outlines</p><p>4.</p><p>A set of reusable appearance attributes that allow you to quickly change the look of an object.</p><p>Symbol</p><p>Graphic Style</p><p>Outlines</p><p>Stroke</p><p>Pattern</p><p>5.</p><p>A method of converting text to a graphic to avoid issues with fonts once a design is complete.</p><p>Pattern</p><p>Graphic Style</p><p>Symbol</p><p>Outlines</p><p>Stroke</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('daaac4f0925f68487e2a97011c2b2545','adobe-illustrator-m4-l2-lesson-1','3d7d27fb1daa2fdeeddf1353e498a3bc','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Layers</h3><p>Layers</p><p>Layers can give you a lot of flexibility with your designs in Illustrator, and you’ll find them especially helpful if you’re working on a complex design.&#160;Sometimes, you have so many objects on your artboard that it’s hard to find what you are looking for, so layers can help to keep you organized.</p><p>Some designers aren’t in the habit of using them, so if you download an AI file from the web, you might find that all objects are contained in one layer, but it is good practice to use them.&#160;You’ll find that it makes your life easier if you do.</p><p>Layers are like a stack of folders which contain your artwork.&#160;&#160;Sometimes, when you have lots of objects on your artboard, smaller objects become hidden behind larger objects, or the object you want is many layers deep and hard to select.</p><p>If you have ever created a collage, you have some idea of how layers work.&#160;You had a background or bottom layer and then various other layers of paper on top of this, all the way to the layer at the top – the one you most recently glued onto your collage.&#160;This is the way it works in Illustrator, too.&#160;You can move items between layers, create sub-layers and contain many items on one layer.</p><p>What you’ll find useful about layers is that you can move, edit, hide, lock, and work with content on one layer without affecting content on the other layers.</p><p>Select window layers to open the layers panel. By default, in Illustrator, all of your items are contained in one layer. But if you want to you can create new layers and move parts of your design into them or you can move items in and out of layers. You&#39;ll do this using the Layers panel where you can select hide and lock your layers. First thing to know is that you can rename a layer just by double clicking on its name. Try to keep up with naming your layers. It will get really confusing fast if you got layer one to layer 40 in your layers panel and aren&#39;t quite sure what is where. Double click anywhere else on the layer to get the layer options panel.</p><p>Here, you can change the identifying color of the layer. Notice that when I&#39;ve got a layer selected, its bounding box is the color noted on the layers panel. This helps you to find the right layer when you&#39;ve got a lot of objects on your artboard. You&#39;ll see the same color in the bounding box on paths and anchor points and displaying the center point of any object on that layer. You can make a layer a template layer and this is helpful. If you&#39;ve scanned a sketch and want to use it as the base of your artwork. If you make it a template it will be locked and it won&#39;t print. You can trace over the top of the layer because it will be dimmed and easy to see the lines you were drawing.</p><p>You can control layer visibility, choose whether to print or lock the layer and choose to dim the layer. You can also show all the artwork inside the layer or print the layer, preview in color, if the layer is in outline mode.</p><p>In the Layers panel, I can click on the new layer button on the bottom to create a new layer. If I want to delete it all I have to do is select it and then click on the trash can. I can also select multiple layers by holding Command, or I can select adjacent layers with Shift.</p><p>The column on the left controls visibility. So if my layer is visible, it will have an eye here in this column. If it is hidden this space is blank. You can control visibility here as well as in the layer options. In the next column we can see whether our layer is locked, where it will show a lock icon. Or unlocked where it will show a blank space. You can&#39;t edit a locked layer.</p><p>So this feature is useful when you&#39;re trying to move specific objects around without accidentally moving other objects. Notice that I get a double circle in my target column and you can see the bounding box light up on my artboard if I click on the layer. The column furthest to the right is the selection column. From here we can tell whether the item is selected. A colored box shows here when the item is selected.</p><p>To move content from one layer to another. You can drag the selected art indicator to the layer you want. When an item in your Layers panel contains other items you&#39;ll see a triangle to the left of the name. Click on the triangle to show or hide the contents of that sub layer. Drag a layer up or down in the Layers panel to change the order. As you can see here, I&#39;ve got some different layers. If I rearrange the order of my layers that rearranges things on my artboard so that certain objects are behind or in front of others. You can send all the items in one layer to individual layers. So if I draw a couple of quick shapes here on this layer I can then go to the layers panel and making sure my layer is selected choose Release to layers sequence from the menu and you see I get some new sub layers.</p><p>You can turn layers into a single layer by using the Merge or Flatten commands. Use Merge when you want to choose items to consolidate into their own layer and use Flatten when you want to put all visible items into one layer. Merge all items into a single layer or group hold down Control on Windows or Command on Mac and click the names of the layers or groups that you want to merge. You can hold down Shift and select all listings in between the layer or group names you click. Then choose the Merge Selected option from the Layers panel menu. Your items will be merged into the last layer or group that you selected. To flatten your layers, click on the name of the layers where you want the other layers to go and then choose Flatten Artwork from the Layers panel menu. When your layers are collapsed like this it can be hard to find your items.</p><p>So you can use the Locate Object command to find the item you want. Click on the object you want to find. Then click locate object at the bottom of the layers panel and the layer you need will be highlighted.</p><p>You can change the display of the layers panel if you want to. Select Panel Options from the Layers panel menu. From here you can show layers only, which will hide paths and groups. You can also choose the height of the rows and choose which type of layers to show thumbnails for.</p><p>In the video, we found out how layers work in Illustrator.&#160;You’ll find that these are a bit like folders which contain your artwork.&#160;You can re<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e638efe8a7d86fcdc639f035b9b5c561','adobe-illustrator-m4-l3-lesson-2','3d7d27fb1daa2fdeeddf1353e498a3bc','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Colors</h3><p>Colors</p><p>In Illustrator, you’ll be working with colors all the time.&#160; When you’re applying color to your designs, consider how your work will be published –&#160;for the screen or in print –&#160;so that you use the correct color mode.</p><p>To switch between color modes you can use File &gt; Document &gt; Color mode and choose CMYK color or RGB color. Remember CMYK for print and RGB for the screen. First let&#39;s review how to work with Fill and Stroke. A Fill is a color, pattern or gradient inside an object and a stroke is the visible outline of an object, a path, or the edge of a live paint group. Over here in the Toolbar I&#39;ve got two colors. You can also see these in the Control and Properties panel. These are my current fill and color strokes. I can switch off the stroke or fill by selecting one and clicking the none button. To change these colors all I need to do is double click on each and I can use the Color Picker to choose a new color. I can click and drag around inside the color spectrum, or I can enter the hex code of a web color, or add HSB Hugh, Saturation, Brightness values or RGB or CMYK values.</p><p>If I create a new shape it will have those colors. When you draw an object you can assign a Fill, Stroke or both to it. At first. The shape will be created with whatever color settings you have in the Toolbar for Fill and Stroke.</p><p>You can also see these in the Options panel across the top. I can click on Fill and Stroke in the Options panel and change these colors. You can apply a brush stroke using the drop down menu that shows basic. If you open the stroke panel, Window &gt; Stroke and Show options from the menu you have some more options.</p><p>For example you can change to a dashed line or add arrowheads to a line. You can copy the stroke and fill from one shape to another using the Eyedropper Tool. If I click on this shape with the Eyedropper while my other shape is selected you&#39;ll see that the colors of my stroke and fill change. You can also invert the color of your objects to get an interesting negative effect or just to have a look at some alternative options. Here are some circles to show you what I mean. Go to Edit &gt; Edit colors &gt; Invert. This swaps the color of my graphics to the colors opposite them on the color wheel. If you&#39;re not yet sure about your color scheme, Illustrator has some panels that can help you narrow down your options. Let&#39;s take a look at the Color Guide panel first. Window &gt; Color Guide.</p><p>It will suggest colors that work together in a scheme based on your active fill color in the toolbar. It shows you shades with black added, and tints with white added. And you can select colors based on its recommendations. You&#39;ll see my fill color here on the top left. If I want to base my color recommendations on a different color, I could instead select a different color from the swatches panel.</p><p>Or I could double click on my fill swatch here in the Toolbar to use the Color Picker and select something I like better. I can then change the color rule it is using to choose my colors or change the variation from warm to cool colors in the right corner menu. All of this is based on the color wheel.</p><p>If you want to. You can set some options for your color guide panel. Use the menu in the top right to choose color guide options. From here you can decide how many color steps you want in your recommended pallets, and you can say how much variation you want between your colors. When you have a color or group of colors that you want to save and use in your design you can save them as swatches. if I do this with my Swatches panel open you&#39;ll see the color I choose is stored there.</p><p>There is another panel which can help you choose a color scheme called Color Themes.&#160; Window &gt; Color Themes. With this one, you can use the color wheel to select your color scheme from the Create tab. If you click and drag around the Color Wheel you&#39;ll see that the selectors automatically adjust for you. You can also explore color schemes. This is collected to Adobe&#39;s Web site of color schemes, Adobe color, which allows people to create and share their own color schemes. So there is plenty of inspiration there. And now you can get access to this without leaving Illustrator.</p><p>In this video, we took a look at how to manage your colors in Illustrator.&#160;You&#39;ll always have a color set for your stroke and fill (unless you select &#39;None&#39; for one of those options).&#160;When you create a shape or line, you&#39;ll see that it appears first with the colors you have set in your Toolbar.&#160;You can then go on to change these options in a few different ways:&#160;in the Toolbar, in the Options panel and in the Properties panel.</p><p>Your turn!</p><p>Try selecting a color scheme using either the Color Guide or the Color Themes panel and see which one you prefer to use.</p><p>Next, we&#39;ll try out using Gradients.</p></section><section><h3>Swatches</h3><p>Swatches</p><p>Swatches can be colors, tint, gradients and patterns and these appear in the Swatches panel. Window &gt; Swatches. You can store these individually or in groups. Swatches are a useful way of storing and accessing design elements that you want to use repeatedly like brand colors for example or a gradient you are using across a series of graphics. You can create a color swatch by selecting the color you want for your artboard, using the eyedropper, or by selecting an object that has the color you want. Once you&#39;ve done that, use the menu in the Swatches panel to choose New Swatch.</p><p>You can also select a color for a fill or stroke using the color picker from the Toolbar and then dragging the color over the Swatches panel. Do you see that green plus sign appeared? Just drop the color into Swatches. You can also add all the colors in your document by choosing add used colors from the Swatches panel menu. You can come back here and edit your colors swatch anytime by double clicking on the Swatch. In the Swatches panel you can give your swatches names if you want to. And you&#39;ll notice that when your objects fill or stroke is applied from the Swatches panel the swatch is highlighted. If you have lots of swatches stored here you can click on the Show Swatch Kinds button and choose to show all swatches, just colors gradients or patterns or show color group.</p><p>Swatch Libraries or a collect<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4d8b6408ce0c35a18d3f8731004fe8da','adobe-illustrator-m4-l4-lesson-3','3d7d27fb1daa2fdeeddf1353e498a3bc','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Brushes</h3><p>Brushes</p><p>Brushes are used to style paths. You can add a brush stroke to an existing path that you&#39;ve created with the Pencil or Pen tool or you can use the Paint Brush to draw a path and apply a brush stroke at the same time.</p><p>Let&#39;s take a look at the Brushes panel. Here are the basic brushes and my most recently used brushes. If I select my path and then choose one of these brushes you&#39;ll see that it applies to the brush stroke in my path. There are presets in here. You can open Brush Libraries from this menu on the right and choose to show or hide certain brush types. If I choose one of the brushes from a library and I can use it. I can also delete brushes from the panel by selecting them and clicking on the trash can. The types of brushes available in Illustrator are Telegraphic brushes, Scatter brushes, Art brushes, Bristle brushes and Pattern brushes.</p><p>Let&#39;s try out a Telegraphic brush using the Paint brush. And then something similar with the Blob brush. If I click here you can see that the one created with the Paint brush is made up of lots of different lines but the one created with the Blob brush is one shape. I could even put some more paint in here and this would merge with my shape. With the paint brush, I&#39;d have to merge all those paths together to get a single shape. Next we have Scatter brushes. These can place copies of an object along a path. So if I open a set of Scatter brushes and select one you can see how painting with the Paint brush makes my objects appear along the path I&#39;m drawing.</p><p>There are also Art brushes styled like charcoal or watercolor paints. There are also brushes that look more like natural paint brushes. These are called Bristle brushes. There is a preset library here. Finally you can use Pattern brushes. These are made of tiles that repeat on a path. There are many of these and other brush types available online and you can download them for free or for a small fee.</p><p>If you want to edit individual parts of your path, select your path and choose Object &gt; Expand Appearance. Now all of the parts of my path are in a group and I can work with these parts individually in isolation mode. You can also create brushes of your own. You&#39;ll need to create the artwork first for Scatter, Art and Pattern brushes. Let&#39;s try creating a simple brush. I have some simple shapes here. Select the shapes you want as part of your brush and then click on New Brush in the Brush panel menu. I&#39;ll choose Art brush. You can also play with how the stroke stretches and flip the brush stroke i f you want to. Make sure you choose tints for the colorization method so that you can change the color of your brush as if it was a stroke color. Without this your brush will always be the same color it is now. Click OK and your new brush is now in the brushes panel and you can start applying it.</p><p>Illustrator gives you access to libraries of presets for brushes, symbols and patterns.</p><p>In this video, we found out how to style a path using brushes.&#160;The main types of brushes available in Illustrator are calligraphic brushes, scatter brushes, art brushes, bristle brushes and pattern brushes.&#160;We used the Paintbrush and the Blob brush to apply brushes to strokes.&#160;You also saw how you can create custom brushes of your own.</p><p>Your turn!</p><p>Create a simple brush using shapes, strokes or any other artwork of your choice and test it out by painting a path.</p></section><section><h3>Symbols</h3><p>Symbols</p><p>Just like with brushes there are preset libraries for other things in Illustrator like symbols and patterns. Let&#39;s take a look at Symbols. Symbols are objects that you can reuse easily in your art many times to keep your file size small. You can also have Dynamic Symbols which have the same master shape but instances of the symbol can have a different appearance. There are presets in Illustrator which we can open by looking at these symbols in the libraries here. Just like with brushes and patterns you can download symbols online to expand what&#39;s built in here. Let&#39;s try creating a symbol of our own.</p><p>I&#39;ve got a shape here that I want to make into a symbol. So I&#39;ll select it and drag it into the Symbols panel. Here, I can give it a name and choose the Dynamic Symbol type. My new symbol has a plus sign next to it in the panel which indicates that it is dynamic. I can now create more instances of my symbol by dragging it to my artboard. Dynamic Symbols are different from Static Symbols because we can select the individual element of our symbol with its selection tool and change the stroke or fill. So we can change individual instances of the symbol. We can also edit our master symbol and our change will be reflected in all instances of it.</p><p>In this video, we looked at the Symbol preset libraries that Ilustrator provides, and found out how to use symbols.&#160;They&#39;re very useful when you are creating a background or texture, for example, where you need lots of instances of the same shape.&#160;You also found out how you can create a custom symbol of your own that you can reuse.</p><p>Your turn!</p><p>Open up Illustrator and go through the process of creating a simple symbol using shapes or line illustration.</p></section><section><h3>Patterns</h3><p>Patterns</p><p>Now let&#39;s see how Patterns work in Illustrator. First I&#39;ll open the Swatches panel so I can access Patterns. Let&#39;s create a shape here on the artboard. I can filll my shape with a preset pattern by choosing from one of the libraries here. The pattern acts like a fill for my object. I can put a stroke around it or I can switch the stroke and fill so that my stroke is a pattern. You can create patterns of your own. Let&#39;s try creating a seamless pattern. I have some shapes here. Now I&#39;ll select the objects I want to include using my selection tool. And go to Object &gt; Pattern &gt; Make. You will see the Pattern Options window and the Workspace will show you what the pattern looks like when tiled. From here you can add and delete elements and change their color, size and position. You might also need to adjust the shape so that your patterns look even. Now I can access my pattern anytime from the Swatches panel. You can apply your pattern to objects. Just like with brushes and symbols, you can find free or lowcost patterns to download online that you can use<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8e3ef6d6d04061b22bc4a06c6f82a3e8','adobe-illustrator-m4-l5-lesson-4','3d7d27fb1daa2fdeeddf1353e498a3bc','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Effects</h3><p>Effects</p><p>Let&#39;s have a look at effects. You can apply these to objects, groups or layers in your design. Under the Effect menu you can see the different effects available. You can create some interesting shapes using the Warp effects or the Distortion effects, for example. The top half of the menu contains Vector effects which you can only apply to vector objects. The effects in the bottom half of the menu are Raster effects which might be familiar to you if you&#39;ve worked in Photoshop. You can apply these either to vector or bitmap objects. Apply an effect by clicking on one in the Effects menu or by clicking Choose an Effect in the Properties panel.</p><p>To edit an effect, click the name of the effect in the Properties panel and the effect options will become available. You can see the effects applied to objects in your document in the Appearance panel or under more options in the Appearance section of the Properties panel. When you are working with effects and graphic styles, you&#39;ll use the Appearance panel a lot. Appearance attributes are properties that affect the way an object looks but don&#39;t actually change the way it&#39;s made up. So, appearance attributes are things like transparency, effect and stroke. You can apply these and then later remove them without altering the object itself. Effects are listed in the order they were applied to the art. You can switch an attribute on and off by clicking on the eye next to it. Click any attributes row to edit it to delete an attribute temporarily click the eye and then simply click it again to reactivate.</p><p>You can delete a specific attribute by clicking on it and then by clicking on the delete icon. Before you can add an appearance attribute to something you need to target it in the Layers panel. To target an object select it on the artboard with the selection tools. At the moment my object is not targeted and doesn&#39;t have appearance attributes other than a default fill and stroke.</p><p>If I click on it with my selection tool the icon changes to have a larger circle around it. If I come up here to the Effects menu and add an effect you can see that my object changes but also the icon in the layers panel changes to have a filled inner circle and an outer circle which tells me that the object is targeted and that it has its appearance attributes applied to it. If I deselect the object my icon changes again to have an inner filled circle only. This icon can be a helpful visual reminder of where you applied visual effects and styles particularly when you have many layers in your file. There are many different types of effects. Let&#39;s take a look at what a few of these can do. For example. The Zigzag effect is a quick way to get a zigzag or wave from a straight line. Let&#39;s try the Scribble effect on this object. See how the style changes? You could then use what your effect is created and build upon it in your artwork.</p><p>When you use an effect, you&#39;ll need to expand the object before you can access the new anchor point.</p><p>in this video, we explored how to use some of the preset Effects that Ilustrator provides.&#160;You can apply these to vector objects and you can also access Photoshop effects in case you have any raster or bitmap graphics in your file.</p><p>Your turn!</p><p>Have a look in Ilustrator, bring in a couple of photos or create a few objects, and try out some of the Effects.&#160;What can you find out about how they work, and what design options do they give you?</p></section><section><h3>Graphic Styles</h3><p>Graphic Styles</p><p>Graphic styles in Illustrator are similar to Layer Style in Photoshop, if you&#39;re familiar with those. With Graphic Styles you can save all of the attributes you have apply to an object. For example, say you have applied ingredients fill and stroke color altered the object&#39;s transparency and apply a drop shadow effect. Now all you have to do is drag this object to the Graphic Styles panel and a new style will be created that you can then apply to other objects. You can save a group of Graphic Styles for use in other documents just as you would a group of Swatches from the Swatches panel. With Graphic Styles you can quickly change how an object looks. If you have a preset graphic style you could change the fill color, transparency and effects of an object in one step.</p><p>Graphic Styles don&#39;t interfere with the object structure so you can apply and remove them without changing the object underneath. Use the Appearance panel to adjust your attributes if you want to. We have a list of default styles in here. You can add a Graphic Style to an object group or layer. When you have your style the way you like it click on the New Graphic Style button. If I want to apply my style to another object, all I need to do is select my object and click on the style in the Graphic Styles panel or the Control panel.</p><p>In this video, we tried out some of the built-in Graphic Styles that Illustrator provides, and you found out how to set your own Graphic Style to make it quick and easy to reuse a set of appearance attributes with objects or with text.</p><p>Your turn!</p><p>Now it’s time to go into Illustrator and make sure you know how to access and use graphic styles.&#160;Can you create one of your own and apply it to an object or some lettering?</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5ed767bff0113cdcf42349d2d04411b0','adobe-illustrator-m4-l6-lesson-5','3d7d27fb1daa2fdeeddf1353e498a3bc','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Views</h3><p>Views</p><p>In Illustrator there are different views and modes that you can use to view your artwork and you&#39;ll want to use these for a number of different reasons as you work. You can view your work in Preview Mode which is what I have here in my artboard. In this view you can see all your strokes fills and effects just as the graphic will actually appear when printed or you can view your work in Outline Mode where you will see only vector paths. Using this mode, you can see the structure of the image at its most basic form without color and effects distracting you. So, it&#39;s a good place to do the basic structure of your design. You can use a keyboard shortcut to switch between these; Control/Command &gt; y or View &gt; Outlines. You can open a new window and put one of you in Preview and one in Outline Mode and then move your windows around to see the two views side by side. Alternatively, in your navigator panel your art will always be shown in Preview Mode so you can arrange this side by side with your document in Outline Mode to see the two together. This can be really useful when you are trying to edit the finer details of an illustration.</p><p>If your graphic has lots of gradients or effects in it your file can take some time to render when you make a change so it can be easier to make simple changes in these files in Outline Mode. It&#39;s also a useful way to see where you might need to tidy up. If you have extra bits of path or anchor points hanging around that you don&#39;t want.</p><p>You can also use illustrators different view options to see what your work will look like in different mediums. Notice at the top of the screen beside your file name it says RGB Preview. This tells us the color mode and preview mode.</p><p>This is Over Print Preview Mode. You might not realize that some colors come out a little different when printed or viewed on the screen. You can make sure colors will display as you want them when you print using this mode. This will also simulate how things like blending transparency and over printing will appear when your images printed.</p><p>Pixel Preview Mode simulates how your art will look when it is rasterized and viewed on a web browser. You will see that pixels form the illustration when you zoom in even if you are creating a vector image. You might be planning to use this in raster format. You might be creating an icon for a Web site for example and want to know how it will be broken up into pixels so that you can clean up your design.</p><p>Trim view mode trims the view to the boundaries of your artboard so that non-printing objects like grids, guides and artwork that extend beyond the edge are clipped. This is a useful way of previewing your graphics when you have some other design elements showing in your workspace.</p><p>Illustrators Isolation Mode is used to edit objects or paths within a sub layer, compound path, group or symbol. When you are in Isolation Mode anything not within the isolated object will be dimmed. There will also be a gray isolation bar here at the top of the document window. There are two ways to enter Isolation Mode. One is to simply double click the object you want to edit. The other way is through the layers panel select the object or group, then click the Layers panel menu and choose Enter Isolation Mode. Once you are in Isolation Mode any new objects you create will become part of the isolated layer and you won&#39;t be able to select anything outside that layer. This helps you to work on the fine details even when you have lots of layers and objects on your artboard. When you are finished editing the isolated object click the arrow in the gray isolation bar across the top until the isolation bar disappears. As you edit, you&#39;re going into deeper levels of isolation so you may have to click the arrow a few times to exit. You can also exit Isolation Mode by pressing the escape key on your keyboard.</p><p>In Illustrator, you can specify how and where you want to draw an object. You can draw on top of an object, behind an object or inside an object using different drawing modes. You can select a drawing mode at the bottom of the toolbar or use the Shift &gt; D keyboard shortcut to cycle through each one.</p><p>Draw Normal mode is the default drawing mode that you&#39;ll be using if you haven&#39;t changed it. Draw Behind mode allows you to draw behind all objects on a selected layer. If an object is selected the new object is drawn directly behind it. This is helpful when you are creating new layers, placing symbols, placing files from the File menu, duplicating objects or using paste in place. I can only select the drawer inside mode if I have an object like a shape selected. These drawing modes are useful when you are working on complex graphics or illustrations with lots of objects and layers and when the order of your objects on the screen is important. Think about working with transparencies for example.</p><p>There are a number of different views and modes that you can use in Ilustrator to view, edit and check your work before you print or export it.&#160;In this video, we had a look at some of these modes and found out how to use them.</p><p>Your turn!</p><p>Try these out yourself by opening a file in Ilustrator and making sure that you know how to access the following modes, and that you understand when to use them:</p><p>Preview</p><p>Outline</p><p>Pixel Preview</p><p>Trim</p><p>Isolation</p><p>Draw Normal, Behind and Inside</p></section><section><h3>Paths</h3><p>Paths</p><p>When you are drawing in Illustrator you create a line called a path. A path is made up of one or more straight or curved segments. At the beginning and end of each segment are anchor points; the small squares you see, which work a bit like pins holding a wire in place. A path could be closed like a circle or open with end points like a line. To create precise artwork in Illustrator, you need to get the hang of working with paths and anchor points. When you select paths for editing with a selection tool in the toolbar a bounding box appears around the entire path. Notice that when I hover there is some text that indicates it is a path. Notice what happens when I drag this handle on a perfect circle. You changed the shape of the path by dragging its anchor points, the direction points at the end of direction lines that appear at anchor points or the path segment itself. Path&#39;s can have two kin<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e53ff405a115c9a176c6b7c890efba5a','adobe-illustrator-m4-l7-summary','3d7d27fb1daa2fdeeddf1353e498a3bc','Summary','text',12,'<h2>Summary</h2><section><h3>Summary</h3><p>Summary</p><p>Great work!&#160;You have successfully completed this module on Understanding Adobe Illustrator Part II!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Used layers to manage design elements.</p><p>Managed colors, swatches, and gradients.</p><p>Managed brushes, symbols, graphic styles, and patterns.</p><p>Demonstrated knowledge of how and why illustrators employ different views and modes throughout the course of a project including vector/outline vs.&#160;display/appearance, isolation mode, and various Draw modes.</p><p>Demonstrated and understanding of vector drawing tools.</p><p>Additional Resources</p><p>The following books, articles,&#160;and websites are additional resources to learn more about this topic.&#160;(Not required reading)</p><p>AGI Training (n.d.) Creating new layers and moving items between layers in Illustrator(opens in a new tab)</p><p>Adobe (n.d.) Importing artwork files(opens in a new tab)</p><p>TutsPlus (2011) Illustrator’ Type Tool:&#160;A Comprehensive Introduction(opens in a new tab)</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8e160f5cb8d72dde0da039fcd898dfde','adobe-illustrator-m4-l8-project-empty','3d7d27fb1daa2fdeeddf1353e498a3bc','Project Empty','text',12,'<h2>Project Empty</h2><section><h3>Module 4 Illustrator 2</h3><p>2200</p><p>Adobe Illustrator</p><p>Understanding Adobe Illustrator Part II - Project</p><p>by Vecteezy</p><p>Create a poster for the event of your choice. Here is an example of what you might aspire to.</p><p>You might be promoting a fashion show, a concert, a comic book convention, a theatre production, or another event that you would like to attend.</p><p>Create shapes using the drawing tools, and add some text to show the details of your event. Use gradients and/or patterns in your design. You might like to look online for free patterns,&#160;brushes(opens in a new tab)&#160;and other&#160;design resources(opens in a new tab).</p><p>Your task is to:</p><p>Use layers to organise your work, and make sure each object or group is tidily organised.</p><p>Use gradients, patterns, symbols, brushes and/or color swatches in your work</p><p>Choose colors using the Color Guide panel</p><p>Try out some Effects and Graphic Styles</p><p>Add some text to your image</p><p>Save your file, making sure to save your text as outlines</p><p>Use some of the drawing and transformation tools to create your graphics and illustrations</p><p>When you have finished, please save your AI file and compress it into a ZIP file.</p><p>On Mac, right-click the file and choose Compress. On Windows, right-click the file, select Send to, and then select Compressed (zipped) folder.</p><p>Review the rubric below to see how you will be graded.</p><p>Understanding Adobe Illustrator Part II - Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Composition</p><p>5-6 points The composition is well balanced. The student has made careful decisions about layout, color, size and shape.</p><p>3-4 points The composition is adequate. The student has made some decisions about layout, color, size and shape, but could improve on visual appeal.</p><p>1-2 points The composition is poorly designed. The student has not made informed decisions about layout, color, size and shape. The composition lacks visual appeal.</p><p>6</p><p>Use of Illustrator tools</p><p>5-6 points The work demonstrates that the student has used multiple design, painting and reshaping tools to create the scene.</p><p>3-4 point The student has used a limited selection of design, painting and reshaping tools to create the scene.</p><p>1-2 points The student has not used a variety of tools to create the scene.</p><p>6</p><p>Use of design elements</p><p>5-6 points The work demonstrates that the student has used multiple design elements such as effects, graphic styles, gradients, patterns and symbols, to create the poster.</p><p>3-4 points The student has used some design elements such as effects, graphic styles, gradients, patterns and symbols, to create the poster, however the design choices could be improved.</p><p>1-2 points The student has only minimally used (or not at all used) design elements such as effects, graphic styles, gradients, patterns and symbols, to create the poster.</p><p>6</p><p>Organization</p><p>2 points The student has used Layers to carefully organize their work.</p><p>1 point The student has used Layers but some are used improperly or lack organization.</p><p>0 points The student has not used layers.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5412c7d78dded5a30acd55579c808f7d','adobe-illustrator-m4-l9-module-4-quiz','3d7d27fb1daa2fdeeddf1353e498a3bc','Module 4 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Understanding Illustrator Part 2. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('c780dbf7a334e720c1545b95396578df','adobe-illustrator-module-5','2eeac88d9b6058d9d55e1dcf25daf550','Module 5: Graphics and Illustrations Part 1',5) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('33774b5a209194e25d006bfd48ecfadb','adobe-illustrator-m5-l1-introduction-purpose-and-objectives','c780dbf7a334e720c1545b95396578df','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Welcome back! This is the intro video for the module on Creating Digital Graphics and Illustrations Using Adobe Illustrator Part I. In this module, we’re going to get into the details of setting up for a web, print or video project, and we’ll find out how to handle the differences between these formats. We’ll experiment some more with the vector drawing tools and shape tools, to give you options for creating more complex graphics and illustrations. You’ll also put your creative hat on and try the transform tools to see what kind of dynamic shapes you can create.</p><p>Next, we’ll try out some editing techniques. We’ll even find out how to live trace an image to create vector art. You can do this from just about any image or photo you like, making your design options virtually endless!</p><p>Module Description</p><p>by Adobe</p><p>License:&#160;All Rights Reserved</p><p>In this module, students will find out how to set up a document for web, print and video.&#160;They will further explore the range of drawing tools that Illustrator offers, creating more complex shapes and transforming graphics and illustrations to suit their design.&#160;As they work, they will develop more experience with the software and gain confidence when working with the interface.</p><p>Objectives</p><p>In this module, students will:</p><p>Create a new project</p><p>Use vector drawing tools</p><p>Use shape tools</p><p>Transform graphics and illustrations</p><p>Use basic reconstructing and editing techniques to manipulate digital graphics and media</p><p>Polling Question</p><p>What type of design do you see yourself doing most often with your new Illustrator skills?</p><p>Branding&#160;Illustration/digital art&#160;Graphic design&#160;Digital media (video, interactive)</p><p>Results:</p><p>Graphic design&#160;100%</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Tab through this activity to read the feedback for your answers</p><p>Feedback</p><p>Settings dictating whether a file is using RGB or CMYK.</p><p>Color mode</p><p>Correct!</p><p>These can be corner or smooth and are found on and at the ends of paths.</p><p>Anchor point</p><p>Correct!</p><p>A tool that allows you to combine, edit and fill objects on your artboard.</p><p>Shape Builder</p><p>Correct!</p><p>A shape with any number of straight sides.</p><p>Polygon</p><p>Correct!</p><p>To slant, or skew an object along the horizontal or vertical axis.</p><p>Shear</p><p>Correct!</p><p>To resize an object proportionately.</p><p>Scale</p><p>Correct!</p><p>6</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Settings dictating whether a file is using RGB or CMYK.</p><p>Anchor point</p><p>Shear</p><p>Shape Builder</p><p>Color mode</p><p>Scale</p><p>Polygon</p><p>Correct!</p><p>2.</p><p>These can be corner or smooth and are found on and at the ends of paths.</p><p>Anchor point</p><p>Color mode</p><p>Shear</p><p>Scale</p><p>Shape Builder</p><p>Polygon</p><p>Correct!</p><p>3.</p><p>A tool that allows you to combine, edit and fill objects on your artboard.</p><p>Scale</p><p>Anchor point</p><p>Shape Builder</p><p>Polygon</p><p>Color mode</p><p>Shear</p><p>Correct!</p><p>4.</p><p>A shape with any number of straight sides.</p><p>Shape Builder</p><p>Anchor point</p><p>Scale</p><p>Polygon</p><p>Shear</p><p>Color mode</p><p>Correct!</p><p>5.</p><p>To slant, or skew an object along the horizontal or vertical axis.</p><p>Polygon</p><p>Scale</p><p>Shear</p><p>Anchor point</p><p>Shape Builder</p><p>Color mode</p><p>Correct!</p><p>6.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('36b13d4f7c71bb738afc832e13008b8f','adobe-illustrator-m5-l2-lesson-1','c780dbf7a334e720c1545b95396578df','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Document Set Up</h3><p>Document Set Up</p><p>Let&#39;s take a look at the New Document window and see what our options are. Click New or press control N on Windows or command N on Mac OS. You can choose File &gt; New as well. You&#39;ve probably already seen this a few times by now but let&#39;s take a look at the finer details. Click a category tab such as mobile, web or print. You&#39;ll see that there are a lot of presets shown below for standard document sizes. US letter for example which is your typical eight and a half by 11 inch sheet in your printer at home.</p><p>When you start with one of these presets, you&#39;re using the best settings for your project. It will be in the correct dimensions, color mode, RGB or CMYK, and resolution. It is easy to customize these though. You can use the preset details on the right to change any of the default settings. For example, you can change measurement units from millimeters or pixels to inches if you prefer to work that way, or you can change your artboard orientation from portrait to landscape. Let&#39;s try setting up three different documents: one for print one for the web and one for video graphics. You can see here that under the print presets I&#39;ve got the various essential paper sizes. In the US, we&#39;d use letter for a flyer or something like that. If you were in Europe, the standard paper sizes are slightly different. So an A4 sheet is your closest size. Since it is a print preset it is already set me to CMYK color mode, so no need to change that. Down here I&#39;ve got more settings and I can change the PPI or add a bleed if I want my image to go all the way to the edge of the paper. If you don&#39;t want a white edge around your poster or flyer, you will need to set a bleed. Ask your printer what their requirements are. It is a good idea to set this at a minimum for 0.125 inches (or three millimeters) outside of your documents final size, ideally. You will probably want to set your bleed to 0.25 inches (or six millimeters) to allow a little bit of room for error.</p><p>When we click Create, our artboard is all ready for us and we can start working on our design. I&#39;ll use command N to set up another one. This time, let&#39;s see what we have under web presets. These are more for designing website layouts. You&#39;ll also see some standard web image sizes here, useful if you are creating graphics for social media. As you can see, we also have access to templates from Adobe Stock here. So, if you are trying to create a design quickly and you need some inspiration to get you started, you can often find one here. I can tweak my preset over here on the right, and you can see that it has set us up automatically with an RGB color space. Click Create, and we have an artboard to work with.</p><p>Finally, let&#39;s take a look at our options for video. We&#39;ve got options for the different video resolutions. So if you were planning to show your movie on an HDTV or you need 4K video, there are settings here for you. This sets me up in RGB for the screen with 72 pixels per inch. If I click Create with this one, my artboard looks a little bit different, because you will be often creating graphics to overlay onto video, so you&#39;ll want to see how things will be positioned on the screen. You might have also noticed that there are presets for mobile and for art and illustration here as well. So have a look around yourself and see what your options are. Depending on the type of design you do you will use some presets more than others, and you might even set up your own using File &gt; Save As Template, if you have certain settings that you use all the time.</p><p>In the video, we learned about how to set up documents for print, web and video in Illustrator.&#160;You also saw how to tweak Illustrator’s presets to get what you need.&#160;You can even create your own Template if there are document settings that you use all the time.</p><p>Tips for success</p><p>Here are some tips to help you set up your documents in Illustrator.</p><p>When you are setting up your document, remember what you are trying to create in the end.&#160;You’ll need to think about how your design will be used.</p><p>When you set up your document you will need to specify:</p><p>Name</p><p>Size</p><p>Number of artboards</p><p>Bleed</p><p>Color mode</p><p>Units</p><p>Pixels per inch (PPI)</p><p>It is easier to think about print dimensions in terms of inches and web dimensions in terms of pixels, for example, so it’s nice to have this set up correctly when you start.</p><p>Remember that if you are designing for print, you’ll probably need a bleed, but if you are designing for web you won’t need this.</p><p>Color mode is very important.&#160;For print, you want CMYK as you know, and for web, RGB.&#160;If you are doing branding work, like a logo which will be used both in print and on the web, you can start with RGB, but you’ll also need to establish CMYK and Pantone spot color values for a logo.</p><p>Raster effects is the resolution that Illustrator will use to render effects like drop shadows.&#160;For the eb, 72 dpi is fine, but just in case you might want to blow up a part of your design or use it in print later, it’s a good idea to set this to 300 dpi to give yourself the option.</p><p>The Preview mode will usually be in the default Illustrator view, but if you are designing for the web and you want to see how your images will look when you rasterize, you might prefer Pixel Preview mode.</p><p>Your turn!</p><p>Now is a good time for you to have a look at the New Document dialog box yourself and make sure you know how to:</p><p>Set up a document for print</p><p>Set up a document for web</p><p>Set up a document for video</p><p>Change your settings for size, number of artboards, bleed, color mode, units of measurement and resolution</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('17db38a12cc2ee835a5723d09b8577e9','adobe-illustrator-m5-l3-lesson-2','c780dbf7a334e720c1545b95396578df','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Vector Drawing Tools</h3><p>Vector Drawing Tools</p><p>You have experimented a little with some of the vector drawing tools in Illustrator like the Pen, Pencil and Shape tools, but since you are going to use these so often, you’ll need to get some more practice with them.</p><p>The Pen tool is probably one of the most-used tools in Illustrator, but also one of the trickiest to master, so now is a good time to get some more practice with this very useful tool.&#160;With it, you can create complex shapes and illustrations.</p><p>Using the Pen tool and mastering line construction is all about understanding the nature of anchor points and how to create and work with them.</p><p>Let’s take a look at it.</p><p>Choose the Pen tool from the toolbar. If I click on the artboard with this, you&#39;ll see that this creates a point. So very simply, I can click again to create another point and another in any shape that I want. And each time I add to my path, a new anchor point is created, and these are connected together. To close my path, all I need to do is click back on the starting point. Notice that a small circle appears when I hover, so I know that clicking here on my first anchor point is going to close my shape.</p><p>To draw a curved line, I click and drag to pull out the handles and create a smooth anchor point. I can also change the direction of my path when I&#39;m creating a smooth anchor point. Without releasing my mouse, I can hold the ALT or option key and drag the handle up, which changes the direction of my path. With my Pen tool selected, I go near the path and a plus sign appears. If I click on my path now, I&#39;ll get a new anchor point which lets me further manipulate my path. To remove an anchor point, I&#39;ll move my Pen close to an anchor and a minus sign will appear. I&#39;ll click on an anchor point and that will delete it for me.</p><p>With the Pen tool, you can quickly change the anchor directions. Hold the Control or Command key to quickly change the Pen tool to the Direct Selection tool. Select the anchor point you want to edit. The anchor handle will appear. Now release the Control or Command key and hold the ALT or Option key to change it to the Convert anchor tool. Click and drag the handles to change the direction.</p><p>We can have smooth anchor points and sharp anchor points, and these behave in different ways. To convert a smooth anchor point to a sharp anchor point, move your Pen tool near the anchor and hold the ALT or option key and your Pen tool will change to an arrow shape. Click on the smooth anchor to convert it to an anchor point. Click and drag on the anchor point again to change it back to a smooth anchor point. We can also move anchor points using the Direct Selection tool. All we need to do is click on the anchor we want to move and drag it to change its position.</p><p>If you find that your lines are a little bumpy at first, don&#39;t worry you can smooth out the lines you&#39;ve drawn with the Pen tool using the Smooth tool. Notice that this smooths out my line. I can keep going over my line to improve the shape of it if I need to.</p><p>There is also an easier way to draw a curve. Choose the Curvature tool from the toolbar. Click on where you want to begin and anywhere else that you want to set an anchor point. The anchor points create curved paths by default. If you want a straight path, double click to set an anchor point or double click an existing anchor point to make the path straight.</p><p>In this video, we tried out working with the Pen tool and the Curvature tool.&#160;Once you get the hang of these tools, you&#39;ll find that the Pencil tool and the Paintbrush tool work similarly, so you should also try experimenting with these tools.&#160;Over time, you&#39;ll get better at handling them and will be able to create more complex work.</p><p>Use the fewest anchor points as you need to create your shape</p><p>Add anchor points where your line or curve changes direction</p><p>Use shortcuts like Alt/Option or Ctrl/Command to quickly swap to other tools to edit your path</p><p>Hold shift to lock your path while adding new anchor point to get a 45-degree angle</p><p>Your turn!</p><p>Now is a good time for you to try out the Pen, Pencil, Anchor point and Smooth tools.&#160;Make sure you know how to:</p><p>Create straight and curved paths</p><p>Close a shape</p><p>Add and remove anchor points</p><p>Convert anchor points from smooth to sharp (also called corner)</p><p>Smooth your path</p></section><section><h3>Pen Tool</h3><p>Pen Tool</p><p>Save this image and open it up in Illustrator using File &gt; Place.&#160;Then, use your pen tool to trace the shapes.&#160;Don’t worry if you don’t get it on the first try, this tool takes designers quite a while to master, but you’ll get it if you keep practicing!</p><p>Learning more</p><p>Learning how to work with lines and shapes in Illustrator to create drawings takes some time, so try out some tutorials to practice.&#160;Here is one where a designer shows you how he turns a portrait photo into a line drawing.&#160;It’s a little more complex than the tracing you have been doing so far, but a useful way to see the potential of this tool.&#160;Have a look at the video to understand the basics and then try this with a photo of your own.&#160;You don’t have to add a lot of detail, but try to get the basic shapes in.</p><p>Video Title:&#160;Adobe Illustrator CC - Line Art Tutorial 2016 - Tips, Tricks &amp; Shortcuts</p><p>Video Publisher:&#160;Michael Tierney(opens in a new tab)</p><p>Note:&#160;there are no closed captions for this video.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ca731580b843875bce095b92773672f4','adobe-illustrator-m5-l4-lesson-3','c780dbf7a334e720c1545b95396578df','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Shape Tools</h3><p>Shape Tools</p><p>You&#39;ve seen these briefly before, so let&#39;s quickly review them. Your Shape tools are here in the toolbar. The default is the Rectangle tool. And if you click and hold on that you can also access the Rounded Rectangle tool the Ellipse tool the Polygon tool and the Star tool. The flare tool is also here and although it&#39;s not a basic shape we&#39;ll have to look at it too just so that you know it&#39;s there. I&#39;ll select the Rectangle tool here. All you need to do is click and drag diagonally. If you want to make a square, use the rectangle and hold the Shift key while you drag. This also works with the Ellipse tool to create a perfect circle. After you create the shape you can adjust its size and position by using the Selection tool. Reposition the shape by clicking the selected object and dragging. Resize the object by grabbing a handle and adjusting in or out. To adjust two sides together grab a corner handle. To resize the shape proportionally Shift and drag a corner handle.</p><p>Next, let&#39;s try out the Rounded Rectangle tool. There are two ways to create one of these. Your first option is to do the same thing we just did with a Rectangle tool, click and drag to create the rounded rectangle shape, or you can click anywhere on the artboard once with the Rounded Rectangle tool selected and you&#39;ll see this dialog box. Here, you can enter width height and corner radius values if you want something very specific. I&#39;ll enter quite a high value here for a corner radius, so you can see what that does.</p><p>You can create polygons and stars in a similar way. First let&#39;s try a polygon. This is a shape with a number of sides you indicate. Click once on the artboard to change the options for radius and a number of sides. You can have up to 1000 sides but it really starts to look like a circle quite quickly unless you blow it up very large and can see the detail. So, if you want a triangle you&#39;ll need a polygon with three sides or if you want a pentagon, five sides, and so on.</p><p>To create a star shape, select the Star tool. If you click the artboard once to open the dialog box, you&#39;ll have some options to customize your star. Radius 1 is the distance from the outer points to the center of the star. Radius 2 is the distance from the inner points to the center of the star. Points is the number of points that make up your star. The closer the Radius 1 and Radius 2 values are to each other, the shorter the points on your star.</p><p>Let&#39;s take a quick look at the Flare tool. First, you&#39;ll define where the highlight will go and then you&#39;ll define the angle of the light. Choose the Flare tool in the Shape tool stack in the toolbar. Click and drag from the point where you want the center of the highlight to be, but don&#39;t release the mouse yet. Press the up and down arrows to add and remove the number of rays in the lens flare, then release. Click and drag to define the direction of the light, but don&#39;t release it yet. Press the up and down arrows to add and remove the number of rings of the lens flare. Then release the mouse to complete the lens flare.</p><p>Let&#39;s take a look at how you can combine and arrange the basic shapes you&#39;ve learned about to create more complex shapes and layouts. I&#39;ll show you the Align panel, as you&#39;ll find this quite helpful. With this panel, you can make sure your spacing between shapes and alignment of shapes is correct and even. You can hover over each of the buttons in this panel to see what they do.</p><p>I&#39;m going to draw a tree, so here are my shapes. These are just basic shapes created with the Ellipse, Rectangle and Polygon tools. I&#39;ll move them into place. Now, I&#39;ll open my Pathfinder panel and I can unite these green circles so that they become one shape. Now if I click on it, you&#39;ll see it behaves as one shape. I&#39;ll do the same with the trunk. You&#39;ll find some options in the Pathfinder panel that can combine or cut out shapes. So I&#39;ll show you quickly a couple of them on this trunk. Just as an example we want the trunk to show behind the leaves so I can move the trunk by right clicking it and choosing Arrange &gt; Send to back. You could also do this by reordering layers in the layers panel. Just to keep my work tidy, now I&#39;ll group these objects and I can move my tree as one shape. Let&#39;s try a slightly more complex shape. This time we&#39;ll use Illustrator&#39;s Shape Builder tool. I&#39;ve got some shapes here and we&#39;re going to assemble a bee. So let&#39;s put our base layer into position right now. These are separate shapes. Now we&#39;ll select my paths and then click on the Shape Builder tool here. Notice if I hover over the shapes that the Shape Builder treats each overlapping part as an object. There are three modes to this tool. The default is merge and that&#39;s what we need for our body. So I&#39;ll click on one of the yellow shapes and drag to the other and you&#39;ll see that we&#39;ve got a new merged shape. I will do the same thing with the antenna and we can merge those as well. Next I&#39;ll put my black stripes in place. Now we want the erase mode here. So that will let us completely remove the parts we don&#39;t want. So I&#39;ll highlight everything and then get my shape builder. Now I&#39;ll hold alt and click on these parts here that we don&#39;t need and you&#39;ll see that they disappear. Finally just to separate these wings a little bit. I&#39;m going to use the last mode extract to pull out this part here in the middle. All I need to do is hold ALT and click on this piece where the wings overlap. We&#39;ll put our wings in place and there we have our bee, made up of basic shapes.</p><p>In this video, we tried out the shape tools, including Rectangle, Ellipse, Polygon and Star.&#160;As a bonus, we also experimented with the Flare tool which can create some interesting light effects.</p><p>Next, we tried out some of the Pathfinder commands, which is one way to combine and delete parts of shapes to make new shapes.&#160;We also looked at Illustrator&#39;s Shape Builder tool, which helps you build more complex shapes.</p><p>Your turn!</p><p>You&#39;ll need lots of practice with these features.&#160;Once you master them, you can create all sorts of graphics and illustrations with them.&#160;Try them out to make sure that you know:</p><p>How to find and use the shap<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c1f1ecba827e405b62ede39986b12214','adobe-illustrator-m5-l5-lesson-4','c780dbf7a334e720c1545b95396578df','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Transform Graphics</h3><p>Transform Graphics&amp;Illustrations</p><p>Using the Transform panel</p><p>Besides the transform tools and menu items, there is another way of transforming objects in Illustrator.&#160;The entire panel is dedicated to it.&#160;Let’s take a look at the Transform panel.&#160;It works with entire objects or groups of objects.&#160;There is a small diagram here in the panel that indicates&#160; your transformation point.&#160;There are nine possible positions - center, four corners, and the middle point of each side.&#160;You can choose any of these points for reference, but you can&#39;t fix another random transformation point with the Transform panel.&#160;The position chosen will indicate the starting point when you use the panel.</p><p>Position</p><p>You can change the position of an object (or move) with the Transform panel. Just insert the needed values in X and Y fields. You can see the numbers in these fields - they show the coordinates of the object&#39;s reference point. X indicates the horizontal coordinates while Y shows vertical coordinates. Simply enter new numbers in the appropriate units. In Illustrator the origin of coordinates by default is positioned in the bottom-left corner of the document.</p><p>Size</p><p>You can change the size of an object (or its scale) with the Transform panel. Enter the values you want in the W and H fields. W means width of object, and H is its height. The values in these fields indicate the initial width and height of your object in chosen units. Enter new numbers to scale the object, or click the chain icon to constrain proportions and enter only one value. The other one will change proportionally.</p><p>Angle</p><p>To change the angle of an object (or rotate) with the Transform panel, insert the angle you want to use in the Rotation field, or select the angle from the drop down menu. The object will be rotated around the point.</p><p>Slant</p><p>To skew an object (or shear) with the Transform panel, choose the angle in the Shear field, or insert the value you need manually. The object will be sheared around the point. You will have more flexibility if you use the Shear tool, though.</p><p>Reflect</p><p>You can mirror an object (or reflect it) with the Transform panel, go to the panel flyout menu and choose Flip horizontal or Flip vertical. The selected object will be reflected along the axis that you chose.</p><p>In the flyout menu of the Transform panel you can choose Scale Strokes and Effects if you want all the strokes and effects applied to a selected object to be transformed along with the object itself. You can also choose to either transform objects or patterns applied to it as a fill, or both.</p><p>Please make sure you have the advanced toolbar open using Window &gt; Toolbars. &gt; Advanced. I&#39;ll create a shape for us to transform. A transformation could be changing the position, size, angle or other aspect of your design asset. You might change multiple properties at once.</p><p>In Illustrator, every element of your design has its own bounding box. This is the square border around your asset with four corner points and four sides. The bounding box has a central point and by default. This is your reference point when you transform. The transformations you&#39;ll do most often in Illustrator are moving, scaling, rotating, reflecting and shearing. You can also free transform an object in Illustrator, which gives you the option of changing multiple parameters at the same time. There are three main ways of doing transformation. You can use the Edit &gt; Transform menu where you can access dialog boxes, you can use the Free transform tool or you can use the Selection tool. Your choice depends on how you like to work and how precise you need to be.</p><p>Moving an object can be as simple as dragging it with a Selection tool. But sometimes you need to be more precise. So, to do this, double click on the Selection tool in the toolbar and you will see a dialog box where you can enter a new position which then tells you the total distance and angle of movement.</p><p>Scaling just means changing the size of an object. Usually you&#39;ll scale an object on both the horizontal and vertical axis at the same time, so that it scales proportionately. But you can also scale an object only horizontally or vertically so that the shape and proportions will change. Scaling is measured as a percentage with 100% being the object&#39;s initial size. To scale an object, I&#39;ll open this scale dialog box from the Transform menu. It is helpful to switch on Preview so that you can see what happens. Now if I scale by 50 percent, this will simply make my shape half the size of the original. I can also scale up. So let&#39;s try 150 percent. Let&#39;s see what happens if I scale horizontally and vertically with different measures. See how this gives my object a whole new shape? You can also scale an object using the Selection tool and dragging from the edges or corners. Make sure to hold Shift to maintain the object&#39;s proportions. You can also use the Free transform tool which you will find under the Puppet warp tool in the toolbar. There is also a Scale tool that you can use to do this. Select the tool, and then your object. Drag the bounding box handles to scale. You can drag horizontally or vertically, if you only want to scale in a certain direction. And to maintain proportions, hold Shift. You will transform around the center point. If you need very precise scaling options double click on the tool in the toolbar and enter your values. You can enter separate numbers for horizontal and vertical scaling or add a percentage for proportional scaling. With this tool, like the other transform tools, you can choose copy from the dialog box to duplicate the object.</p><p>Next, let&#39;s try rotation. You do a rotation when you change an object&#39;s angle. Rotation is measured in degrees from negative 360 to 360 – counterclockwise and clockwise in a full circle. If you leave the transformation point on the center of the object&#39;s bounding box, the object will rotate around itself. I can rotate my object using Object &gt; Transform &gt; Rotate. From the dialog box enter an angle. You can use Preview here to see what will happen. You can also use the Free transform tool. The cursor changes when you are close to the corner point, so you can just click and drag to rotate. You will also get a rotation arrow if you<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('358d6cfcb6aa5ed02afca40cb02f0077','adobe-illustrator-m5-l6-lesson-5','c780dbf7a334e720c1545b95396578df','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Editing Tools</h3><p>Editing Tools</p><p>You can make basic corrections to an image or object in Illustrator using the cutting tools. I&#39;ll show you the Eraser tool first. The Eraser is a free drawing tool that gives you manual control over what you erase and move. Double click on the Eraser tool to get a dialog box where you can change options like angle and size of the eraser. Click and drag to erase. Notice that a white area starts to show when you are erasing. Release the mouse button to apply your changes. Press and hold the ALT key while you are dragging to create a rectangular shape that cuts with straight edges. Repeat this until you have erased the parts of your object that you want to get rid of.</p><p>The Scissors tools splits a path, graphics frame or empty text frame at an anchor point or along a segment. You will find it under the Eraser in the toolbar. All I need to do is click on my path or shape where I want to split it, and this will create two endpoints with one selected by default. You can then use the Direct selection tool to modify your object. The Knife tool, also found under the Eraser tool, divides an object into parts. Drag the pointer where you want to cut. You can do this with curves or lines. If you want to cut in a straight line hold the ALT or Option key as you click and then drag. The cuts you have made will appear in your object. You can then deselect the object and use the Direct selection tool to work with the new objects you have created.</p><p>Let&#39;s briefly revisit the Appearance panel, as you can do a lot of editing and manipulations with it. You can open an appearance attribute such as an effect and change the settings at any time. I&#39;ll create a shape with a fill and stroke and apply an effect to it so that you can see what happens in the Appearance panel. Now, if I want to edit any of these attributes I can see them in the Appearance panel to edit any of them, I can click on the underlined name of the attribute and make changes in the dialog boxes. I can also change my colors or add new effects to my object using the Add New Effect. See how this gives me a new row in the Attributes panel? And I can edit the effect in the same way. If I want to delete any of my effects, all I have to do is click on the row and then click on the trash can.</p><p>Another feature of Illustrator that is very helpful when you have existing artwork that you want to change is the Image Trace feature. You can take a raster artwork and automatically trace it to convert it into vector artwork. This means you can take scans of sketches, illustrations and even photographs, and convert them into vector artwork that can be edited in Illustrator. So let&#39;s say we want the shape of the Eiffel Tower for a graphics project. I can bring this image in and then I can use the Image Trace function. I will open the panel to give myself some options and use Preview so that I know what I will get. I&#39;ll choose a preset and then give it a try to see what happens. I can then tweak the settings using my dialog box. Now I have vector shapes and paths rather than a raster image. I could go in with my Direct selection tool and edit the fine points of this, or use the various tools and effects that Illustrator provides to manipulate it for the type of design or illustration I want. I&#39;m just looking for a silhouette of the shape, so from here I can choose a new color for my tower, and there we are.</p><p>In this video, we tried out some of the editing tools that Illustrator provides.&#160;We also took a look at the appearance panel to get some options for manipulating images with attributes and effects.</p><p>Your turn!</p><p>Have a look in Illustrator and make sure you can:</p><p>Use and change brush sizes on the Eraser tool</p><p>Use the Scissors tool</p><p>Use the Knife tool to cut a freeform and straight line</p><p>Use the Appearance panel to add and change effects and attributes</p><p>Trace an image using image trace and experiment with the presets</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('84264b7307ad1f8ce63f8acb6e8ecea7','adobe-illustrator-m5-l7-summary','c780dbf7a334e720c1545b95396578df','Summary','text',12,'<h2>Summary</h2><section><h3>Module 5 Summary</h3><p>Summary</p><p>Great work!&#160;You have successfully completed this module on Creating Digital Graphics and Illustrations Using Adobe Illustrator Part I!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Created a new project</p><p>Used vector drawing tools</p><p>Used shape tools</p><p>Transformed graphics and illustrations</p><p>Used basic reconstructing and editing techniques to manipulate digital graphics and media</p><p>Additional Resources</p><p>The following books, articles,&#160;and websites are additional resources to learn more about this topic.&#160;(Not required reading)</p><p>Adobe (n.d.) How to Draw Basic Shapes(opens in a new tab)</p><p>Adobe (n.d.) Transform and edit artwork(opens in a new tab)</p><p>Adobe (n.d.) Warp, pose and sculpt your artwork easily</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('13414582fa0a0b203ca2017a7fda0f12','adobe-illustrator-m5-l8-module-project-empty','c780dbf7a334e720c1545b95396578df','Module Project Empty','text',12,'<h2>Module Project Empty</h2><section><h3>Module 4 Project</h3><p>2200</p><p>Adobe Illustrator</p><p>Understanding Adobe Illustrator Part I - Project</p><p>Now it’s time to get into Illustrator and try out some of the commonly used tools by creating a simple landscape scene. You might include objects like trees, mountains or hills, birds, sun or clouds –&#160;or any other elements of nature. Make these out of very basic shapes.</p><p>Remember –&#160;it doesn’t have to be perfect or highly detailed. Right now, you are just experimenting, so have fun with it! The image above is an example of what you might aspire to.</p><p>Your task is to:</p><p>Create a scene using the shapes and other drawing tools</p><p>Use rules, guides and grids to help you place objects in your scene</p><p>Experiment with some of the Drawing, Painting and Reshaping tools to see what kind of creative designs you can make</p><p>Move and scale objects as needed using the Selection tools and the Free Transform tool</p><p>Choose fill and stroke colors for your design</p><p>Add some text to your image, choosing a font, size and weight</p><p>Save your file</p><p>Have fun with this! The exercise will get your creative juices flowing and help you to find out what Illustrator can do. You can even post your creation on your fridge when you’re done, if you want to!&#160;Review the rubric below to see how you will be graded.</p><p>Understanding Adobe Illustrator Part I - Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Composition</p><p>7-8 points The composition is well balanced. The student has made careful decisions about layout, color, size and shape.</p><p>4-6 points The composition is adequate. The student has made some decisions about layout, color, size and shape, but could improve on visual appeal.</p><p>1-3 points The composition is poorly designed. The student has not made informed decisions about layout, color, size and shape. The composition lacks visual appeal.</p><p>8</p><p>Use of Illustrator tools</p><p>7-8 points The work demonstrates that the student has used multiple design, painting and reshaping tools to create the scene.</p><p>4-6 point The student has used a limited selection of design, painting and reshaping tools to create the scene.</p><p>1-3 points The student has not used a variety of tools to create the scene.</p><p>8</p><p>Typography</p><p>4 points The student has selected typographic elements including font, size, weight and color that are pleasing within the composition.</p><p>2-3 point The student has selected basic typography but the composition would benefit from more careful selection of elements including font, size, weight and color.</p><p>0-1 point The student has not chosen typographic elements or has chosen font, size, weight and/or colors that do not align within the composition.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a262d0c688264956d68bf5d441d7fdc5','adobe-illustrator-m5-l9-module-5-quiz','c780dbf7a334e720c1545b95396578df','Module 5 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Graphics and Illustrations Part 1. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('b60cf7bdaa4272640109ec80646fbc47','adobe-illustrator-module-6','2eeac88d9b6058d9d55e1dcf25daf550','Module 6: Graphics and Illustrations Part 2',6) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1dba8025144ca4a1ea44003117017750','adobe-illustrator-m6-l1-introduction-purpose-and-objectives','b60cf7bdaa4272640109ec80646fbc47','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objective</h3><p>Introduction</p><p>Hi and welcome back to another module. This is the intro video for the module on Creating Digital Graphics and Illustrations Using Adobe Illustrator Part II. In this module, we’re going to take a look at layers and masks, which can help you to create more complex designs by covering or revealing certain areas or elements of your composition. You can fill text with an image, for example, using a mask.</p><p>We’ll look at different ways to bring images into your project. You can do this whether you’ve sourced icons or templates from another designer online, or are using your own photographs as the basis for your work. It even works if you are sketching by hand and building your design digitally from there.</p><p>We’ll have some fun with type, looking for creative ways of displaying text in your designs. Finally, we’ll take a look at the 3D and perspective tools that let you add extra dimension to your work.</p><p>Module Description</p><p>by Adobe</p><p>License:&#160;All Rights Reserved</p><p>In this module, students will find out how to modify the visibility of layers using opacity and masks to create depth in their work.&#160;They will learn how timport various different asset types, manipulate typography and create 3D effects using the perspective tools.&#160;In the process, they will gain familiarity with some of the more complex tools that Illustrator offers.</p><p>Objectives</p><p>In this module, students will:</p><p>Demonstrate knowledge of layers and masks.</p><p>Import assets into a project.</p><p>Add and manipulate type using Type tools.</p><p>Create digital graphics and illustrations using 3D and perspective tools in Illustrator.</p><p>Polling Question</p><p>There are many ways that you can bring in your designs to Illustrator and develop them further.&#160;Which option would you most like to try?</p><p>Hand-drawing and then scanning your artwork</p><p>Creating a design with a graphics tablet or iPad and penci</p><p>l&#160;Importing a photo and tracing it</p><p>Results:</p><p>Importing a photo and tracing it&#160;100%</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Tab through this activity to read the feedback for your answers</p><p>Feedback</p><p>Drawing objects on a two-dimensional surface so that their height, width, depth and position are correctly in relation to each other when viewed from a particular point.</p><p>Import</p><p>Incorrect</p><p>Where text flows around an image.</p><p>Linked file</p><p>Incorrect</p><p>A file which is referenced but not actually embedded in your Illustrator document.</p><p>Clipping mask</p><p>Incorrect</p><p>To place an external file into your document.</p><p>Opacity</p><p>Incorrect</p><p>A group of layers to which a mask is applied.&#160;The base layer defines the boundaries of the group.</p><p>Text wrap</p><p>Incorrect</p><p>Defines how transparent an image is.&#160;A lower value means that the image is more transparent.</p><p>Perspective</p><p>Incorrect</p><p>0</p><p>6</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Drawing objects on a two-dimensional surface so that their height, width, depth and position are correctly in relation to each other when viewed from a particular point.</p><p>Text wrap</p><p>Opacity</p><p>Clipping mask</p><p>Perspective</p><p>Linked file</p><p>Import</p><p>Incorrect</p><p>2.</p><p>Where text flows around an image.</p><p>Import</p><p>Opacity</p><p>Linked file</p><p>Perspective</p><p>Clipping mask</p><p>Text wrap</p><p>Incorrect</p><p>3.</p><p>A file which is referenced but not actually embedded in your Illustrator document.</p><p>Perspective</p><p>Text wrap</p><p>Linked file</p><p>Import</p><p>Opacity</p><p>Clipping mask</p><p>Incorrect</p><p>4.</p><p>To place an external file into your document.</p><p>Import</p><p>Clipping mask</p><p>Perspective</p><p>Linked file</p><p>Text wrap</p><p>Opacity</p><p>Incorrect</p><p>5.</p><p>A group of layers to which a mask is applied. The base layer defines the boundaries of the group.</p><p>Perspective</p><p>Clipping mask</p><p>Opacity</p><p>Linked file</p><p>Import</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7a61fd72263697654ebfbb133cc4a5d3','adobe-illustrator-m6-l2-lesson-1','b60cf7bdaa4272640109ec80646fbc47','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Opacity and Masks</h3><p>Opacity and Masks</p><p>You&#39;ve worked with the layers before and by now you should know how the Layers panel works and how you can reorder layers, show and hide layers, lock layers and move objects to different layers. We&#39;re going to look now at some more advanced effects that you can get using layers when you introduce opacity and masks. A clipping mask is a very useful element that you can use in Illustrator. A clipping mask creates a mask for other objects so that only the artwork within your mask shape will be visible. This is helpful if you are trying to fill text with a photograph, or you want to show your design in a circle cut out.</p><p>Have a look at my Layers panel.</p><p>I&#39;ve got a photograph of New York City on one layer and my text here on another layer. So what I want to do is fill my text with this photograph. So this is just regular text at the moment. First I need to convert my text into an object so that I can use it as part of my artwork.</p><p>So I&#39;ll go to Object &gt; Expand. Then I need to make it into a compound path. So I go to Object &gt; Compound path &gt; Make. Now my text is ready to be used because it works like a shape. Now I&#39;ll move my text into position. It can be helpful to adjust your opacity temporarily in the Properties panel just to get an idea of what will show through your mask. So highlight everything and then choose Object &gt; Clipping Mask &gt; Make. There we go. Our letters are now filled with the photograph and we can&#39;t see any of the photo that was outside of our border.</p><p>You can also do this with a shape. For example, let&#39;s say we wanted to make our photograph into a circle shape to fit our design. All I have to do is create a circle on its own layer, position it where I want over the top of my photo, select them both and use Object &gt; Clipping mask &gt; Make.</p><p>I have now got a whole new shape. When you do this, just make sure the object you are using as your mask is at the top of the layer order. If I double click on the object I can move it around and change it as in isolation mode. I can also undo my clipping mask if I select the group of content and then choose Object &gt; Clipping mask &gt; Release.</p><p>You can also apply layer effects and change the appearance of your content while it&#39;s inside the mask. For example, if I look at my Appearance panel, I can change the opacity of the masked images or I can add an effect to it from here by using the effects button to choose one.</p><p>In this video, we explored how to use clipping masks in your artwork to create shapes and filled text.</p><p>Your turn!</p><p>Now is a good time for you to have a look around the workspace for yourself.&#160;Make sure that you can:</p><p>Organize your layers to create a clipping mask</p><p>Create a clipping mask using a shape</p><p>Create a clipping mask using text</p><p>Apply effects, gradients and transparency changes to a masked image or text</p><p>Learning more</p><p>You can also try out this tutorial to explore how to get more advanced text effects using transparency with your clipping masks.</p><p>Video Title:&#160;How to Use Transparency Masks in Illustrator</p><p>Video Publisher:&#160;Design Cuts(opens in a new tab)</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3939baede606486060c336b60732ca90','adobe-illustrator-m6-l3-lesson-2','b60cf7bdaa4272640109ec80646fbc47','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Importing Assets</h3><p>Importing Assets</p><p>Select a Student</p><p>When you are working on design projects, you may be creating artwork from scratch like we&#39;ve talked about with the drawing, shape and other tools, but that is not your only option. You can import vector drawings and raster images if you have created them in another application, or if someone has shared them with you. You can use importing and exporting or copying and pasting to work with your files across the Adobe Creative Cloud applications and many others. There are three basic ways to import files.</p><p>First, you can drag and drop files from your desktop or anywhere else on your computer. I have a photo here on my desktop and all I need to do is drag and drop the file onto my window and I can work with it. You can see here in the Links panel that this makes my image a linked file. My Layers panel also indicates this. This means that the file itself isn&#39;t stored in Illustrator, it&#39;s kept elsewhere and Illustrator shows me a rendering of the file while I work. If you choose this option, you&#39;ll be able to modify the artwork with transformations and effects but you can&#39;t edit the individual parts. This is a good option which you&#39;re working with a very big file with large images because as the Illustrator tries to show you many highly detailed images while you work, it will slow down. By storing your files elsewhere. It means your software needs less working memory as you work. When you Export or Print, Illustrator puts the original graphic in your file so that it will appear as you intended.</p><p>You can also use File &gt; Open to open a file or import some artwork or photos. When I do this, my image is embedded into the document. This means that my file will be brought into the Illustrator document so it will be easy to share the file with another person, but my file could become quite large over time and so Illustrator could slow down. If you don&#39;t want that and would prefer a linked file, you can use the unembed button in the Control panel.</p><p>Finally, you can also use the Place command. I&#39;ve got a blank document open and I&#39;ll use File &gt; Place to import an image. When I click Place, here, you&#39;ll see the image appears on my artboard. This will also embed my image. But, again, I could unembed it and make it a linked file if I wanted to, using the unembed button.</p><p>Illustrator also has a useful option that lets you paste text into an object, like a shape, or onto a path. I&#39;ll create a rectangle here and then use File &gt; Place to choose a text file where my text is stored and you&#39;ll see it placed onto the shape.</p><p>There are a few file types that behave in a special way when you place them. For example if you place a PDF file that has many pages, you&#39;ll be able to choose which page you want to place and how you want to crop the artwork. You can also bring in artwork that you&#39;ve started in Photoshop using these same three options. Your layers, editable text and paths will transfer over so that you can edit your work between the two. Or, you can copy your artwork from a Photoshop file and paste straight into Illustrator.</p><p>You can also manage your project assets using a Creative Cloud Library. This is another useful way of sharing your assets like colors, styles, graphics and text across your files if you are working in Photoshop, Illustrator, InDesign and other Adobe applications. A Creative Cloud Library gives you a way to organize and access your assets. For example, you could create a library with the assets you&#39;d need for a specific project. If you organize things this way, you&#39;ll always be using the latest version of your linked assets. You can even share assets from your libraries with your colleagues so that things are consistent across all aspects of a project.</p><p>Here is a library that I&#39;ve created. You can see that it contains colors, images, graphics and so on that align with one theme. If you want to create a library of your own, click on this dropdown here and choose Create New Library. You can share your libraries with other users. From the flyout menu, choose Collaborate and then you can enter your colleague&#39;s email address and decide whether you want them to be able to edit or just view your library. This is helpful when you are working with other designers.</p><p>If you want to add assets to your library, you can drag an image and objects from your artboard or click the plus sign at the bottom of the panel. From here, you can choose from your fill or stroke color. You can then use these in your document. If you want to use a color, right click and choose Set Color when you have an object selected.</p><p>For images, right click and Place Copy. I&#39;ve also got some text in my library which has a Character Style applied to it. So in this case I&#39;ve chosen a specific font, weight and color. You can also change things like kerning and tracking in your typography and save a Character Style with those details. Once you have the text styled in the way you want, to simply use Window &gt; Character Styles to save that setting and then drag the text into your library so that it can be used on any project from any computer. If you want to delete anything from your library just click on it, and the trash can here.</p><p>In this video, we found some different ways of bringing assets into your Ilustrator file.&#160;Now, you know how to use the Open and Place commands, and you know that you can drag-and-drop files in.&#160;You also know how to store files and use them on different computers and projects using a Creative Cloud library.</p><p>Tip:&#160;Watch your linked files!</p><p>If you ever open Illustrator and see an Exclamation mark next to your images in the Links panel, this indicates that your files are missing.&#160;It is probably because you’ve done some tidying up on your computer and have moved the files, so Illustrator doesn’t know how to find them.&#160;If this happens to you, don’t worry, all you need to do is relink the files.&#160;Illustrator will show you an alert.&#160;Choose Yes and navigate to where the file is on your computer to tell Ilustrator where to find it.</p><p>Your turn!</p><p>Now is a good time for you to have a look around the workspace for yourself.&#160;Make sure that you can:</p><p>Open, place and drag-and-drop assets into your file</p><p>Create and edit a Creati<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0836c540e125332e537355e1e2b982a5','adobe-illustrator-m6-l4-lesson-3','b60cf7bdaa4272640109ec80646fbc47','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Types of Tools</h3><p>Type of Tools</p><p>Select a Student</p><p>In this video, we took a look at the Type tools in Illustrator.</p><p>Remember, if you are sharing a file with another designer or the print shop, you’ll need to double-check that they’ve got the font you are using, or convert your text to outlines (Type &gt; Create Outlines) so that there are no problems displaying your design.</p><p>PIPEnter fullscreen</p><p>When you are working in graphic design or illustration, you will find that you work with text similarly to other design elements. You&#39;ll use typography to influence the mood or to fit the style of your designs. To do this, you&#39;ll need to be able to manipulate the text you are using. Let&#39;s take a closer look at how the Type tools work in Illustrator, and find out how we can manipulate text in our designs.</p><p>To work with text, first, you will need to add some to your layout, so you&#39;ll find the Type tools here in your toolbar. The basic Type tool is here, and if you click and hold you can see the other type tools. These are Area type, Type on a path, Vertical type, Vertical area, Vertical type on a path and the Touch type tool. Let&#39;s take a look at some of these.</p><p>To add basic text to my layout, I&#39;ll use the Type tool. I can click anywhere on my artboard and start to type or I can click and drag to define a text box. I can select this text and use my Properties panel to change formatting like font and size. I can also change the color of my text by changing the fill color here.</p><p>You can create rows and columns of text using the Area type tool. In Area type options you can set some options for your rows and columns including number height and width. I can also use the Area type tool if I want to put my type in a particular shape. So I can draw a shape here and then if I click on the edge of my shape, it will fill with dummy text. If you want a little bit of a margin between the type and the edge of the shape, you can add inset spacing. Select the area type object and go to Type &gt; Area type options and give a value for inset spacing. I&#39;ll use Preview here so that you can see what that will do.</p><p>If you want your text to fit along a path, all you need to do is create your path then your text will flow along it, if you use the Type on a path tool. I&#39;ll create an arc. Now, if I use my Type on a path tool to click on the arc path, I&#39;ll get dummy text all the way along. Now, I can do this with any kind of path. If I want to create a freehand line with the Pen tool for example, I can take this in any direction that I want and then grab the Type on a path tool, and there you go. My type flows along this organic path I&#39;ve created.</p><p>There are these same tools for vertical type as well. They work the same way, except that your text flows vertically rather than horizontally. I&#39;ll create another shape here and use the Vertical area type tool to show you what I mean. Notice that my text is now running in the other direction. This can give you some really interesting design effects. You probably wouldn&#39;t want to use vertical type when you have lots of text because it isn&#39;t easy to read, but you might try it with a heading or just a few words if it suits your design.</p><p>When you are using type, you will probably want to have some type panels open the Character panel is the one you&#39;ll use a lot. Here, you can change the font size and weight. You can also change the leading, kerning and tracking from here. The other panel you&#39;ll use a lot is the Paragraph panel which lets you set options for your text alignment and indentation.</p><p>If you&#39;ve added paragraphs of text, sometimes you might want your text to flow across text boxes. I&#39;ll create a couple of text placeholders. I could then use File &gt; Place to place my text from a text document, or I could copy and paste it in. I&#39;ll do that then I can scale the text object by dragging its corners. If I pasted too much text in there and it doesn&#39;t all fit, you&#39;ll see I&#39;ve got a small red plus sign here on the right edge of my text box that indicates there is overset text. If I use my Selection tool and click on that plus sign I can place another text box that contains my overset text. If there&#39;s more, I&#39;ll see another red plus sign until I&#39;ve made a place for it all. I can place these anywhere I want and I can move my text boxes around just like any other object on the artboard. I can break the link between these text threads just by double clicking on one of these ports.</p><p>If you want to work with your text as though it was a shape so that you can manipulate each letter, you&#39;ll need to convert your text to a graphic. Now, make sure you&#39;re happy with what you have typed before you do this, because you won&#39;t be able to go back and edit this text again. So check for spelling errors and that the font is the one you want and that sort of thing to avoid any problems. To convert my text to a graphic, I will select it and go to Object &gt; Expand. If I want to, I can use my Direct selection tool to manipulate the anchor points of each letter shape individually. This is really useful when the text is a central part of the design you&#39;re creating and you want something very specific. As you can see. I can customize all of these letters any way I want.</p><p>Adding new fonts</p><p>Sometimes, you might want a particular style of font but not have a font installed that suits your design.&#160;Don&#39;t worry, it&#39;s easy to add new fonts.&#160;Using the Character Panel (or from the Properties Panel when you have a type tool selected), click on the font drop-down menu.&#160;You will see an option &#39;Find more&#39;.&#160;Click on this, and the list of fonts will update to show you all of the available Adobe Fonts.&#160;Scroll through the list and find a font you like.&#160;From there, click on the cloud icon on the right and you can instantly activate any new font you like.</p><p>Your turn!</p><p>Now is a good time for you to have a look around the workspace for yourself.&#160;Make sure that you know how to:</p><p>Add text to your artboard</p><p>Change type options like font and size using the Character and Paragraph panels</p><p>Use the Area Type tool</p><p>Create a path and flow type along it</p><p>Flow text across multiple text areas</p><p>Manipulate text as though it were a shape</p><p<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2eddbe7a9150171ae2808f34fad5fb20','adobe-illustrator-m6-l5-lesson-4','b60cf7bdaa4272640109ec80646fbc47','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Perspective Tools</h3><p>Perspective Tools</p><p>You can draw objects in perspective in Illustrator using the Perspective grid.&#160;The perspective grid allows you to represent a 3 dimensional scene on a flat surface (our screen or a printout for example).&#160;For example, you might want to show a road disappearing off into the distance.&#160;The point where the receding parallel lines appear to converge in the distance is called your vanishing point.</p><p>Click on the Perspective grid tool in the toolbar to switch on the grid. To switch off the grid, simply select the Perspective grid tool and hit the Escape key.</p><p>This defaults to the two point grid. You can switch between one point, two point and three point perspective using View &gt; Perspective grid and choosing the one you want. You can only have one grid per Illustrator document. You can also set some options for the grid under View &gt; Perspective grid &gt; Define grid. Here, you can save a preset, choose units to measure your grid in, choose a scale, choose a size for the cells, choose a view angle in distance, the horizon height and set a Vanishing Point. You can also change the colors of your grid and change the opacity of the grid. You can hover over these handles to adjust the grid at different points.</p><p>To get started drawing on the grid, I&#39;ll grab my rectangle tool and start to draw some shapes. You can switch the perspective plane by clicking on the cube icon in the top left. Smart guides help you out by aligning your object to the grid. Sometimes it&#39;s easier to draw your graphics off the grid and then apply them later to your grid. Choose the plane you want to add the graphic to and then use the Perspective selection to drag it onto your grid. You can adjust the size and position. You can also release your object from the Perspective grid by selecting it and choosing Object &gt; Perspective &gt; Release with perspective. The object then becomes normal artwork.</p><p>You can bring text and symbols into your scene but you&#39;ll need to create those in normal mode first. I&#39;ve created some simple text and chosen a symbol from the Symbols panel. They show up normally, but if I turn on the grid again and select them with the Perspective selection tool, notice how their perspective changes when I move them onto the plane. You can edit the text from the Control panel under Object &gt; Perspective. You can also edit the text in Isolation mode by double-clicking the text object.</p><p>In this video, we looked at the Perspective Grid and Perspective Selection Tool in Illustrator and found out how to add dimension to your images.</p><p>Your turn!</p><p>Now is a good time to try out Illustrator for yourself.&#160;Make sure that you can:</p><p>Set preferences, switch on and change planes on the Perspective Grid</p><p>Create shapes on the Perspective Grid</p><p>Add text and symbols to a Perspective Grid drawing</p></section><section><h3>3D Tools</h3><p>3D Tools</p><p>PIPEnter fullscreen</p><p>Illustrator has some 3D options that allow you to give dimension to your work. With 3D effects, you can create three dimensional objects on a two-dimensional artboard. You can control the way your 3D objects appear by adjusting the lighting, shading, rotation and other properties. There are two main ways to do this: by extruding (or extending) and by revolving.</p><p>When you are working in 3D, it is helpful to think about the three different axis or dimensions. I&#39;ve marked these out here using dashed lines so that you have a reference. Extrude extends a two-dimensional object along Z axis or adds depth. So, with this, you can turn a circle into a cylinder, for example. I&#39;ll use the Extrude and Bevel 3D effect on this circle. It helps if you use Preview when you are doing this. Let&#39;s set some options. Position sets how the object is rotated and the perspective from which you view it. I can also adjust these angles individually. You can change the depth and choose whether the end is open or closed. You can change the bevel (or cut) on the outside of the shape. You can also choose More Options to set some options for lighting.</p><p>Let&#39;s try revolving. Revolving sweeps a path in a circular direction around the Y axis to create a 3D object. Because of how this works, you&#39;ll usually need to start with half of the profile you want your 3D object to have and then you can rotate to fill it in. I&#39;ve got a bottle shape here and I&#39;ll use the Pathfinder to quickly split it in half. Now, I&#39;ll select this half and go through Effects &gt; 3D &gt; Revolve and then set some options here. I&#39;ll use Preview so that you can see what will happen. I&#39;ll change the surface to give us a nice lighting effect. So there we go, we have a 3D shape.</p><p>You can also rotate an object in 3D space. Let&#39;s try with a basic shape. I&#39;ll draw a star, then I&#39;ll go to Effect &gt; 3D &gt; Rotate. I&#39;ll use Preview to see what will happen. I can also change the position and surface. Watch what happens to my shape when I do this.</p><p>In this video, we found out how to create 3D shapes in Illustrator using the 3D effects – Extrude and Revolve.&#160;We also looked at the Rotate effect which allows you to move an object around in 3D space.</p><p>Your turn!</p><p>Now is a good time for you to experiment with the 3D effects yourself.&#160;Try them out in Illustrator and make sure that you can:</p><p>Create 3D objects using the Extrude effect</p><p>Use the Revolve effect to convert a 2D shape into a 3D one</p><p>Position objects using the Rotate effect</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('04e4c1b6a3117ab8ff9fd3fbac1ec58b','adobe-illustrator-m6-l6-module-6-summary','b60cf7bdaa4272640109ec80646fbc47','Module 6 Summary','text',12,'<h2>Module 6 Summary</h2><section><h3>Module 6 Summary</h3><p>Summary</p><p>Great work!&#160;You have successfully completed this module on Creating Digital Graphics and Illustrations Using Adobe Illustrator Part II!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Demonstrated knowledge of layers and masks.</p><p>Imported assets into a project.</p><p>Added and manipulated type using Type tools.</p><p>Created digital graphics and illustrations using 3D and perspective tools in Illustrator.</p><p>Additional Resources</p><p>The following books, articles,&#160;and websites are additional resources to learn more about this topic.&#160;(Not required reading)</p><p>Adobe (n.d.) How to Draw Basic Shapes(opens in a new tab)</p><p>Adobe (n.d.) Transform and edit artwork(opens in a new tab)</p><p>Adobe (n.d.) Warp, pose and sculpt your artwork easily</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('41d2c591e0a7a42cb9e047cfa5115547','adobe-illustrator-m6-l7-module-6-project-empty','b60cf7bdaa4272640109ec80646fbc47','Module 6 Project Empty','text',12,'<h2>Module 6 Project Empty</h2><section><h3>Module 6 Project</h3><p>2200</p><p>Adobe Illustrator</p><p>Understanding Adobe Illustrator Part II - Project</p><p>by Vecteezy</p><p>Create a poster for the event of your choice. Here is an example of what you might aspire to.</p><p>You might be promoting a fashion show, a concert, a comic book convention, a theatre production, or another event that you would like to attend.</p><p>Create shapes using the drawing tools, and add some text to show the details of your event. Use gradients and/or patterns in your design. You might like to look online for free patterns,&#160;brushes(opens in a new tab)&#160;and other&#160;design resources(opens in a new tab).</p><p>Your task is to:</p><p>Use layers to organise your work, and make sure each object or group is tidily organised.</p><p>Use gradients, patterns, symbols, brushes and/or color swatches in your work</p><p>Choose colors using the Color Guide panel</p><p>Try out some Effects and Graphic Styles</p><p>Add some text to your image</p><p>Save your file, making sure to save your text as outlines</p><p>Use some of the drawing and transformation tools to create your graphics and illustrations</p><p>When you have finished, please save your AI file and compress it into a ZIP file.</p><p>On Mac, right-click the file and choose Compress. On Windows, right-click the file, select Send to, and then select Compressed (zipped) folder.</p><p>Review the rubric below to see how you will be graded.</p><p>Understanding Adobe Illustrator Part II - Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Composition</p><p>5-6 points The composition is well balanced. The student has made careful decisions about layout, color, size and shape.</p><p>3-4 points The composition is adequate. The student has made some decisions about layout, color, size and shape, but could improve on visual appeal.</p><p>1-2 points The composition is poorly designed. The student has not made informed decisions about layout, color, size and shape. The composition lacks visual appeal.</p><p>6</p><p>Use of Illustrator tools</p><p>5-6 points The work demonstrates that the student has used multiple design, painting and reshaping tools to create the scene.</p><p>3-4 point The student has used a limited selection of design, painting and reshaping tools to create the scene.</p><p>1-2 points The student has not used a variety of tools to create the scene.</p><p>6</p><p>Use of design elements</p><p>5-6 points The work demonstrates that the student has used multiple design elements such as effects, graphic styles, gradients, patterns and symbols, to create the poster.</p><p>3-4 points The student has used some design elements such as effects, graphic styles, gradients, patterns and symbols, to create the poster, however the design choices could be improved.</p><p>1-2 points The student has only minimally used (or not at all used) design elements such as effects, graphic styles, gradients, patterns and symbols, to create the poster.</p><p>6</p><p>Organization</p><p>2 points The student has used Layers to carefully organize their work.</p><p>1 point The student has used Layers but some are used improperly or lack organization.</p><p>0 points The student has not used layers.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('829b9c5a2d1a9a28638b27510d7d0ad2','adobe-illustrator-m6-l8-module-6-quiz','b60cf7bdaa4272640109ec80646fbc47','Module 6 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Graphics and Illustrations Part 2. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,7,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('f7419d155213b4343aad10dbf56043c8','adobe-illustrator-module-7','2eeac88d9b6058d9d55e1dcf25daf550','Module 7: Archive Export Publish Graphics',7) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1987ab077194759f23a9e4d13b9254bd','adobe-illustrator-m7-l1-introduction-purpose-and-objectives','f7419d155213b4343aad10dbf56043c8','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Intro Description Objectives</h3><p>Introduction</p><p>Hi and welcome back! This is the intro video for the module on how to Archive, Export, and Publish Graphics Using Adobe Illustrator. In this final module, you’ll find out how to prepare your graphics for print or export on a web, print or video project. We’ll look at the different file formats you might use, and get your work ready to publish and show off to the world!</p><p>We’ll also get to know the Adobe Certified Expert (A.C.E.) exam like structure, contents, and types of questions so that you can be prepared. Thanks for sticking with it to the end of this course and best of luck on the final exam, as well as the ACE exam. In the meantime, though, never stop designing and creating!</p><p>Module Description</p><p>by Adobe</p><p>License:&#160;All Rights Reserved</p><p>In this module, students will find out how to get their files ready for exporting to the web, printing or using in video production and then export their graphics and illustrations to various file formats.&#160;From there, they will review the structure of the ACA Illustrator Certification Exam, reviewing the preparation they’ll need to do to gain a passing grade.</p><p>Objectives</p><p>In this module, students will:</p><p>Prepare images for web, print, and video.</p><p>Export digital graphics and illustration to various file formats.</p><p>Understand the structure and test prep necessary for the Adobe Certified Professional credential.</p><p>Polling Question</p><p>How soon do you plan to take your Adobe Certified Associate exam for Adobe Illustrator?</p><p>Within 1 month&#160;1-3 months&#160;3-6 months&#160;I&#39;m not sure</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>To convert a file into a new format such as for print, web or video use, for example.</p><p>PPI</p><p>Approximating unavailable colors in an image.</p><p>Pixel preview</p><p>Lines printed in the corners of your sheet to show the printer where to cut the paper.</p><p>Trim marks</p><p>A view that shows how an image will look when rasterised.</p><p>Dithering</p><p>Pixels per inch; the density of pixels in an image.</p><p>Export</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>To convert a file into a new format such as for print, web or video use, for example.</p><p>Export</p><p>Pixel preview</p><p>PPI</p><p>Dithering</p><p>Trim marks</p><p>2.</p><p>Approximating unavailable colors in an image.</p><p>Export</p><p>Dithering</p><p>Trim marks</p><p>Pixel preview</p><p>PPI</p><p>3.</p><p>Lines printed in the corners of your sheet to show the printer where to cut the paper.</p><p>PPI</p><p>Export</p><p>Pixel preview</p><p>Trim marks</p><p>Dithering</p><p>4.</p><p>A view that shows how an image will look when rasterised.</p><p>Pixel preview</p><p>Dithering</p><p>Trim marks</p><p>Export</p><p>PPI</p><p>5.</p><p>Pixels per inch; the density of pixels in an image.</p><p>Dithering</p><p>Export</p><p>PPI</p><p>Trim marks</p><p>Pixel preview</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('d0467adc00021f94adf8c5afc9249777','adobe-illustrator-m7-l2-lesson-1','f7419d155213b4343aad10dbf56043c8','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Prepare for Export</h3><p>Prepare for Export</p><p>Select a Student</p><p>PIPEnter fullscreen</p><p>When you have finished your design and you are ready to Print or Export to use it, there are some final checks to do to make sure everything is as expected, depending on the type of project you are working on.</p><p>One of the first things to check is that your image is the right size and resolution for the job. Usually, your print projects will be measured in inches and your web projects will be measured in pixels. You can see your artboard&#39;s dimensions by selecting the Artboard tool and clicking on the artboard&#39;s corners. Some text will pop up showing the width and height. Remember, a pixel is a single square in a raster image. A display or video screen is made up of millions of pixels, like in a grid, so the more pixels you have in your image, the more detail you have.</p><p>When we talk about the resolution of a screen or of an image, we&#39;re talking about how many pixels it has. More pixels equals a higher resolution and a higher quality. Remember that if you are sharing a file with someone else and it contains text, you&#39;ll need to convert your text to outlines. Before you do this, make sure you save your native AI file first and keep a copy of it just in case you need to edit your text later. To convert to outlines, all you need to do is use your Selection tool to select the text boxes and go to Type &gt; Create outlines. Notice what happens when I do this. I can no longer edit the text because my letters now behave like shapes.</p><p>It is a good idea to switch to Outline view so that you can tidy up any stray parts or elements that you don&#39;t want to print. You can also print a composite of your artwork so that you can proof the overall design just using the printer you have at home. To do this, choose File &gt; Print and select a printer from the printer menu. If you want to print to a file instead of a printer, you can print to an Adobe Postscript file from here. Choose an artboard option. To print everything on one page, select ignore artboards. To print each artboard separately, deselect Ignore artboards and specify if you want to print all artboards or a specific range, like from 1 to 3. Select output on the left side of the print dialog box, check that mode is also set to composite and click Print.</p><p>If you are printing artwork from a single artboard that can&#39;t fit on a single page, you can tile the artwork onto multiple pages. To set this up, choose File &gt; Print and select a tile option. Full pages divide the artboard into full media sized pages for output and imageable areas divide the artboard into pages based on what the selected device can handle. For example, your printer at home can work with Letter and Legal sized pages most likely, as well as some smaller paper sizes.</p><p>The imageable areas option is useful for outputting artwork that is larger than your device can handle because it allows you to reassemble tiled pieces onto the original larger artwork. If you selected full pages, set the overlap option to specify the amount of overlap between the pages.</p><p>When you prepare artwork for printing, some marks are needed for the printer to register the artwork precisely and check that the color is correct. Some different types of Printers&#39; marks to know about include Trim marks that show where the page should be trimmed, Registration marks that help to align the color separations, Color bars that are used to adjust the density of ink and Page information like the time and date, artboard name and number. To add printers marks, all you need to do is choose File &gt; Print. Select Marks and Bleeds on the left in the print dialog box. Then, choose the kind of Printer&#39;s marks that you want to include. If you&#39;ve chosen Trim marks, specify the width of the lines and the distance between the Trim marks and the artwork here. To keep your Printer&#39;s marks away from your bleed, set an offset value that is larger than the bleed value.</p><p>Now, I&#39;ll switch over to a file set up for the web. Before you save a file for the web, it&#39;s a good idea to make sure your objects are aligned to the Pixel Grid, which makes your lines look crisp when the image is saved in a raster format. When you transform an object and you have the setting switched on in the Properties panel, new objects are aligned to the Pixel grid. This is on by default, I f you use any of the web presets. You can preview what your objects will look like when rasterized using the Pixel Preview (View &gt; Pixel preview) which lets you control placement, size and anti-aliasing in your graphic. Pixels are square, so it is helpful sometimes to use anti-aliasing which smooths out any jagged edges on curves and diagonal lines. When using Pixel Preview, you&#39;ll want to magnify your art so that you can see the pixels. Your artboard has been divided into a Pixel grid with 72 pixels per inch. Zoom in so you can see how things look.</p><p>I&#39;ll switch over to a file set up for a video. If you are going to work with your graphics in a video editing or motion graphics program like Adobe Premiere Pro or After Effects, make sure you have been working in a preset designed for video so that you can see your safe areas and get the position of your elements on the screen right. Double check that you are working in our RGB color. You can see this up top next to the file name in the tab you are working in. For video graphics, lines should be at least two pixels thick so that you can avoid any flickering that will happen when using thinner lines with motion.</p><p>Make sure that your objects are each on their own layers as After Effects will recognize everything in a single layer as one piece. You can use the Release to Layers (Sequence) option from the Layers panel menu to do this, and be sure to give your layers descriptive names so that they are easier to work with when you import them into a video project.</p><p>In this video, we found out how to check your work before you send it off to be printed, use it on the web or add it to a video project.</p><p>Remember to always keep an Ilustrator native (AI) file of your work before you convert text to outlines, in case you need to go back and make changes later.</p><p>When you are sending a file to print, always check with your print shop to find out their preferences in terms of file type and which printers mark<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('25c4736e99e48f3e4c0a3759cbee5bcd','adobe-illustrator-m7-l3-lesson-2','f7419d155213b4343aad10dbf56043c8','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Export to Various File Formats</h3><p>Export to Various File Formats</p><p>When you have created a design in Illustrator, you&#39;ll need to export it for the medium that you are designing for (usually, web, print or video) so that you can share and use it. When you&#39;re exporting your artwork, make sure you update your export settings to suit the project you are working on. You can export your project assets in different sizes and formats depending on what you need to do with them. Let&#39;s have a quick review of the most common file formats that you will use.</p><p>For print, you will choose between an AI native file an EPS and a PDF. An AI file can be read by Illustrator only, and saving this way gives you the option to go back and edit your file. It also keeps your transparency settings. This is the best option for you if you are going to keep working with the file or if you are going to take it into InDesign or Photoshop, for example. An EPS file can be opened with other standard graphics software but does not support transparency. A PDF can be opened by any PDF reader. As long as you leave the Preserve Illustrator editing capabilities box checked, you will be able to edit later in Illustrator as a copy of the AI is saved inside the file, but you will have a larger file size this way.</p><p>For web, you will likely choose a JPEG for the smallest file size, or a PNG if your file has transparency. These will both rasterize your graphic, converting it from a vector graphic that can be infinitely scaled to a graphic based on pixels which will lose quality if you try to blow it up. If your graphics will be used on a responsive Web site or in an app you might choose an SVG (scalable vector graphic) which preserves your graphic in a vector format so that it can be scaled. Depending on your printer&#39;s preferences, you may want to provide a native AI file, an EPS or a PDF.</p><p>From File &gt; Package, you can package your file. Here, you can copy your links and fonts as well as generate a report. This way, you can give your print shop one packaged file with everything included.</p><p>There is a balance to be made between file size and quality of your graphics when you are saving for the web. Online, you&#39;ll want the smallest file size you can get because large image sizes make a website slow to load, but you&#39;ll need to balance your need for a small file with quality because, generally, to make your file smaller you have to sacrifice some quality.</p><p>Use Export &gt; Save for web (Legacy) to view the size and estimated download time for your web graphic in different format. If my file has a transparent background, I&#39;ll need a PNG. If not, JPEG is standard for the web. In the lower left corner. I can see the file format and size of my graphic. If I switch from PNG-24 to PNG-8, for example, I can cut my file size in half without losing much quality because PNG-24 has many more colors. But, if there is a limited range of colors in my image it&#39;s not a problem. PNG-8 only supports 256 colors but PNG-24 supports many more. This wouldn&#39;t work well for a photograph, but for a graphic without gradients or many color variations, it is fine. Notice what happens to my file size if I switch to JPG and adjust the quality. We can have quite a range of file sizes this way.</p><p>I can view this in 2-Up mode where my original and optimized images show side by side so that I can get an idea of whether or not the quality is being noticeably lost as I change my settings. We can also adjust the image size here and optimize either for artwork or for type. Also notice what happens when I click the Browser dither checkbox. I can see what may happen if a browser has to replace unavailable colors. So, my colors are changed slightly. This is probably ok for a graphic like this one, but you would want to be careful if you were working with company branding or something like that, where matching specific color is very important.</p><p>If your artwork will be used in a video, you may want to provide your video producer with a native AI file so that they have the best possible quality to work with. Or, you may want to export to PNG or SVG. Ask the person who you will be working with for their preferences.</p><p>You may want to export assets individually if they are going to be animated. So, let&#39;s take a look at how to do this. Sometimes you might need to Save or Export only selected objects from a larger piece of art. For example, if you have designed a logo you may want to save the text or the symbol in its own individual file. You can do this by turning the objects into assets. Go to Window &gt; Asset export. Choose this Selection tool and drag the objects that you want to save onto the Asset export panel. Select the asset (hold the Control or Command key to select more than one). Under Export settings, choose a format. You can select PNG, JPEG, SVG or PDF. If you&#39;re saving as a PNG or JPG, you can export at multiple sizes. So, set the scale to two times if you want to enlarge the image. Click Export and choose the location to save your new files.</p><p>In this video, we reviewed the most common file formats that you will Save or Export to from Illustrator.&#160;Match the formats below with their most likely use cases.</p><p>Print</p><p>Web</p><p>Video</p><p>EPS</p><p>SVG</p><p>AI</p><p>SVG</p><p>PNG</p><p>AI</p><p>PDF</p><p>JPG</p><p>PNG</p><p>Alternative Activity</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('aa0e3f421da7660943c093d5f4652059','adobe-illustrator-m7-l4-lesson-3','f7419d155213b4343aad10dbf56043c8','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Exam Preparation Revision 1</h3><p>Exam Preparation Revision 1</p><p>by Shutterstock</p><p>License:&#160;All Rights Reserved</p><p>You’ll soon be taking the exam associated with the Adobe Certified Professional Certification.&#160;In this lesson, we’ll review the requirements and make sure you are prepared.</p><p>This lesson is intended to help you familiarise yourself with the areas of the exam, but is not a standalone study guide.&#160;You will need to have completed this course, used the provided resources, done your own research and practice, and looked for additional tutorials to brush up in the areas where you are not yet confident before you take your exam.</p><p>About the Adobe Certified Professional credential</p><p>An Adobe Certified Professional credential certifies that you have the entry-level skills to work within Adobe Illustrator.</p><p>Exam topics</p><p>The topic areas for the exam follow the basic structure of this course as follows:</p><p>Setting project requirements</p><p>Understanding Digital Graphics and Illustrations</p><p>Understanding Adobe Illustrator</p><p>Creating Digital Graphics and Illustrations Using Adobe Illustrator</p><p>Archive, Export, and Publish Graphics Using Adobe Illustrator</p><p>How to prepare</p><p>Preparation includes practicing with Illustrator as well as learning some skills related to graphic design.&#160;Adobe recommends that you spend about 100 hours preparing before you take the exam.</p><p>Exam format</p><p>The exam has 40 questions, and you will have 50 minutes to complete them</p><p>On the exam, you will have three types of questions:</p><p>Multiple choice</p><p>Simulation</p><p>Scenario-based</p><p>The multiple-choice questions will be much like the questions you have been completing in the quizzes in this course.</p><p>You will also have simulation questions which you complete with your mouse in a simulated software environment.&#160;These questions will be things like:</p><p>Create a new web document named Exact Bookkeeping that uses two artboards with the size 1024x768.</p><p>In the Pathfinder panel, remove the diamond shape by combining the selected shapes using the Minus Front method.</p><p>Make the grid visible.</p><p>The scenario-based questions will frame questions in the context of a project that a designer might do.&#160;For example, You have been hired to create banners for a company’s social media campaign.&#160;List the steps you would take to set the tracking of their name to -50.</p><p>The exam sections are as follows:</p><p>Section 1</p><p>Tutorial - Explanation of how to complete the section (not timed)</p><p>Questions (timed)</p><p>Section Summary - review the questions from that section.</p><p>Section 2</p><p>Tutorial</p><p>Tasks - Simulation tasks that you will perform in Illustrator.</p><p>Section Summary</p><p>Leave Feedback</p></section><section><h3>Exam Preparation Revision 2</h3><p>Exam Preparation Revision 2</p><p>by Shutterstock</p><p>License:&#160;All Rights Reserved</p><p>Navigating the exam</p><p>Before you click on Submit Section on each of the two Section Summaries, make sure you are happy with your answers.&#160;You will not be able to go back and change your answers after you do this.</p><p>While you are working through the exam, your screen will have indicators that show you which question you are working on (out of the total number of questions in the section), and how much time you have remaining.&#160;You will also be able to go back, reset the question, display Help text or go to the next question.&#160;You can also mark a question for review if you want to remember to come back to the question.</p><p>When you reach the Section Summaries, you will be able to see which questions you marked for review, and you will see each question in a list.&#160;You can click on the question number to go back and revisit it before you click ‘Submit Section’.</p><p>When you reach the second section, you will complete a series of tasks using Illustrator.&#160;Your tasks will be displayed in a special panel within the Illustrator interface.&#160;For most tasks, you will be provided with a starter document to work with.&#160;Your work will be saved when you click Back or Next.&#160;Like the previous section, here you will see the task number (out of the total number of tasks), and your remaining time.&#160;You will be able to Reset the task if you need to, or view Help text.</p><p>The Certification Test panel</p><p>In this special version of Illustrator that you will be using, you will have most of the functionality available in the version of the software that you have been using to practice, however Adobe Bridge and Adobe Stock, as well as the Open and Help menu items are disabled – you will not need these to complete your tasks.</p><p>Your Exam is controlled from within a new Panel – the Certification Test panel, contained within its own workspace.&#160;Here, you have the controls you need to navigate your exam &#160;(Back, Next and Help buttons) and manage your time (task or question number, remaining time).</p><p>You’ll open other workspaces and panels as needed from the Window menu.&#160;The Certification Test panel behaves like other panels in that you can float, resize and move it.&#160;If you close this panel, your navigation buttons will disappear, so you will need to reset the Certification Test workspace (Window &gt; Workspaces &#160;&gt; Reset Certification Test)</p><p>NOTE:&#160;Be sure not to reset any of the default workspaces as this will remove the Certification Test panel from that workspace.</p><p>In the Certification Test panel, you will find a description of the task that you need to perform.</p><p>If an instruction is in Italics, this indicates part of your document or a file that you need to import.&#160;If an instruction is in bold and italicised, it indicates text that you will need to type.</p><p>Do’s and Don’ts</p><p>Change only the settings noted in the task.&#160;If a value is not specified, keep the default.</p><p>Do not make other changes to the starter document (i.e. don’t change layer names unless you are told to do so).</p><p>If you need to save or export a file, save it to the default location or a location specified in the task.&#160;Do not go to other folders.</p><p>Leaving Feedback</p><p>As you work through the exam, you can mark questions and tasks to remind yourself to leave feedback for them.&#160;At the end of the exam, you’ll be invited to give ope<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('bba228fb589efdb943937f0d5848560f','adobe-illustrator-m7-l5-module-7-summary','f7419d155213b4343aad10dbf56043c8','Module 7 Summary','text',12,'<h2>Module 7 Summary</h2><section><h3>Module 7 Summary</h3><p>Summary</p><p>Great work!&#160;You have successfully completed this module on Archive, Export, and Publish Graphics Using Adobe Illustrator!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Prepared images for web, print, and video.</p><p>Exported digital graphics and illustration to various file formats.</p><p>Understood the structure and test prep necessary for the ACA Illustrator Certification Exam.</p><p>Additional Resources</p><p>The following books, articles,&#160;and websites are additional resources to learn more about this topic.&#160;(Not required reading)</p><p>Adobe (n.d.) Best Practices for Creating Web Graphics(opens in a new tab)</p><p>Maria Halthoff (n.d.) How to Set-Up and Prepare your Design Files for Print(opens in a new tab)</p><p>Graphic Mac (n.d.) Adobe Illustrator file formats explained(opens in a new tab)</p><p>Adobe (n.d.) Import artwork files&#160;(opens in a new tab)</p><p>Adobe (2017)&#160;ACA Exam Study Guide:&#160;Graphic Design &amp; Illustration Using Adobe Illustrator CC</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c3bdffc8d498b916f905fbb0171ed6ea','adobe-illustrator-m7-l6-module-7-project-empty','f7419d155213b4343aad10dbf56043c8','Module 7 Project Empty','text',12,'<h2>Module 7 Project Empty</h2><section><h3>Module 5 Project</h3><p>2200</p><p>Adobe Illustrator</p><p>Archive, Export, and Publish Graphics Using Adobe Illustrator - Project</p><p>by Vecteezy</p><p>Design a T-shirt graphic for your favorite sports team or a team you imagine, including creating your own version of the mascot. &#160;If you&#39;re not into sports, you can instead create a T-shirt for your favourite band.</p><p>Here is an example of what you might aspire to.</p><p>Be sure to include both graphics/illustrations and typography in your design.</p><p>Your task is to:</p><p>Set up your file for print using US Letter size</p><p>Create two artboards and include both a graphic for the front and a graphic/text for the back of your T-shirt design</p><p>Use any of the Illustrator tools and assets that you have learned about to create your design</p><p>Choose typographic elements, convert to shapes and manipulate them into a pleasing design.</p><p>Choose a pleasing color palette for your design</p><p>When you have finished, please save your AI file and compress it into a ZIP file.</p><p>On Mac, right-click the file and choose Compress. On Windows, right-click the file, select Send to, and then select Compressed (zipped) folder.</p><p>Review the rubric below to see how you will be graded.</p><p>Archive, Export, and Publish Graphics Using Adobe Illustrator - Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Composition</p><p>5-6 points The composition is well balanced. The student has made careful decisions about layout, color, size and shape.</p><p>3-4 points The composition is adequate. The student has made some decisions about layout, color, size and shape, but could improve on visual appeal.</p><p>1-2 points The composition is poorly designed. The student has not made informed decisions about layout, color, size and shape. The composition lacks visual appeal.</p><p>6</p><p>Use of Illustrator tools</p><p>5-6 points The work demonstrates that the student has used multiple drawing, shape and transform tools to create their design.</p><p>3-4 point The student has used a limited selection of drawing, shape and transform tools to create their design.</p><p>1-2 points The student has not used a variety of drawing, shape and transform tools to create their design.</p><p>6</p><p>Use of design elements</p><p>5-6 points The work demonstrates that the student has used multiple design elements such as effects, brushes, gradients, patterns and symbols, to create the graphic.</p><p>3-4 points The student has used some design effects, brushes, gradients, patterns and symbols, to create the graphic. however the design choices could be improved.</p><p>1-2 points The student has only minimally used (or not at all used) design elements such as effects, brushes, gradients, patterns and symbols, to create the graphic.</p><p>6</p><p>Organization</p><p>2 points The student has used Layers to carefully organize their work.</p><p>1 point The student has used Layers but some are used improperly or lack organization.</p><p>0 points The student has not used layers.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f2edfbe34bde2e30167e68cd3443b31e','adobe-illustrator-m7-l7-module-7-quiz','f7419d155213b4343aad10dbf56043c8','Module 7 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Archive Export Publish Graphics. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,6,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('18e3a4ca63e7f10d529dd5ba4d229331','adobe-illustrator-module-8','2eeac88d9b6058d9d55e1dcf25daf550','Module 8: Course Project Empty',8) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('fd08b6eca57606c7b0cd11f06a91240c','adobe-illustrator-m8-guided-learning','18e3a4ca63e7f10d529dd5ba4d229331','Guided Learning','text',15,'<h2>Course Project Empty</h2><p>Build and apply the essential concepts in this module through guided explanation, practical examples, and reflective activities.</p>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('7fd87e4033e3bba77334f64ab4523f8d','adobe-illustrator-module-9','2eeac88d9b6058d9d55e1dcf25daf550','Module 9: Course Wrap Summary and Exam',9) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f9a170ffa6146bd62ed4785e20266496','adobe-illustrator-m9-l1-course-wrap-summary-and-exam','7fd87e4033e3bba77334f64ab4523f8d','Course Wrap Summary and Exam','text',12,'<h2>Course Wrap Summary and Exam</h2><section><h3>Course Summary</h3><p>Course Summary</p><p>Select a StudentCTEdemo_artsavCTEdemo_illustratorMatthew Barber</p><p>We&#39;re at the last leg of our exciting Illustrator journey!&#160;We hope this course has equipped you with the knowledge needed for you to master the learning objectives of this course.&#160;Illustrator is a tool that is best learned by doing, which is why we gave you a ton of videos and activities to practice your skills.&#160;You should now be ready for the final exam.</p><p>Our main objective on this journey has been to push away the veil of mystery and complexity from Illustrator and enable you to discover all of the creative possibilities it has.&#160;Keep exploring Illustrator and use the resources to discover more interesting, creative ways of expressing yourself in your designs and layouts.&#160;Whether you choose to pursue a career in graphic design or not, this course has given you some fantastic skills that you can still apply in other fields or even as a hobby.</p><p>This final exam has two parts.&#160; Be sure to complete and submit both parts on the next two pages to finish this activity.</p></section><section><h3>Final Exam 1</h3><p>Final Exam - Part 1</p><p>Select a StudentCTEdemo_artsavCTEdemo_illustratorMatthew Barber</p><p>Analytics:Off</p><p>Answer Key:Off</p><p>ABCABC</p><p>Directions:&#160;Read each question carefully and then choose the correct answer.</p><p>Which type of graphic should you use for the company name and logo to allow the company to print banners in a variety of sizes?</p><p>Bitmap</p><p>Raster</p><p>Vector</p><p>Outline</p><p>Which of the following would be a reason to add a bleed to your document?</p><p>To add needed margins or padding to your document</p><p>To compensate for printing in both the RGB and CMYK color spaces</p><p>To allow for accurate color printing on various printer types</p><p>To ensure that your artwork is still printed to the edge of the page after the page is trimmed</p><p>You want to limit the number of color variations displayed by the Color Guide panel.&#160;What should you do?</p><p>Use a harmony rule with fewer swatches.</p><p>Select Color Guide Options from the Color Guide panel menu, and enter a smaller number in the Steps field.</p><p>Use a color group with fewer swatches.</p><p>Choose a library with fewer colors from the Limits the color group pop-up menu in the Color Guide panel.</p><p>A graduated blend between colors is called a:</p><p>Gradient</p><p>Tint</p><p>Stroke</p><p>Graphic Style</p><p>True or false, you can change the width and length of an artboard after you create it?</p><p>True</p><p>False</p><p>Which type of curve will you be able to scale and edit easily because it has been created with a mathematical formula?</p><p>Raster curve</p><p>Vector curve</p><p>Isolated curve</p><p>Rendered curve</p><p>You want to add some guides that will be visible only inside a particular artboard.&#160;What should you do?</p><p>Select the artboard name in the Artboard panel, and then drag a guide out from the horizontal or vertical document ruler.</p><p>Select the Artboard tool from the Tools panel, click on the artboard, and then drag guides out from the horizontal or vertical document ruler.</p><p>Click on the artboard with the Selection tool, and then Option+double-click (Mac OS) or Alt+double-click (Windows) on the horizontal or vertical ruler.</p><p>Drag a guide from the horizontal or vertical document ruler, and hold down the Option (Mac OS) or Alt (Windows) key before letting go of the mouse button.</p><p>Which color scheme is made of tints and shades of just one color?</p><p>Warm</p><p>Complementary</p><p>Monochromatic</p><p>Cool</p><p>Which other tool is hidden under the Eraser tool in the toolbar?</p><p>Free Transform</p><p>Knife</p><p>Rectangle</p><p>Line segment</p><p>The Illustrator interface is contained in the:</p><p>Dock</p><p>Control Panel</p><p>Workspace</p><p>Application frame</p><p>How can you change the units of measurement in a document that is currently open?</p><p>View &gt; Rulers &gt; Units</p><p>Edit &gt; Document properties (choose the correct unit)</p><p>File &gt; New Document (set units)</p><p>View &gt; Show rulers (right-click on the ruler)</p><p>In which panel can you customise the tint of a swatch you have selected?</p><p>Appearance panel</p><p>Swatches panel</p><p>Color Guide panel</p><p>Align panel</p><p>RGB stands for:</p><p>Red, Gray, Blue</p><p>Red, Gray, Black</p><p>Red, Green, Blue</p><p>Red, Green, Black</p><p>Which two of the following describes the characteristics of typing on a path?</p><p>The text flows along the edge of a closed path only</p><p>The text flows in the direction in which points were added to the path</p><p>The text flows along the edge of an open or closed path</p><p>Text cannot be edited once it’s been added to a path</p><p>You can view the keyboard shortcut for a tool by:</p><p>Looking in the Control Panel</p><p>Hovering over the tool in the Toolbar</p><p>Using View &gt; Keyboard shortcuts</p><p>Right-clicking on the tool</p><p>Which of these is a vector image format?&#160;Select all that apply.</p><p>SVG</p><p>PNG</p><p>GIF</p><p>AI</p><p>Which tool is a vector drawing tool?</p><p>Paintbrush</p><p>Slice</p><p>Width</p><p>Gradient</p><p>When you add white to a color, you create a:</p></section><section><h3>Final Exam 1</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>Final Exam - Part 2</h3><p>Final Exam - Part 2</p><p>Select a StudentCTEdemo_artsavCTEdemo_illustratorMatthew Barber</p><p>Analytics:Off</p><p>Answer Key:Off</p><p>ABCABC</p><p>Directions:&#160;Read each question carefully and then choose the correct answer.</p><p>Which option is used to reposition an Artboard?</p><p>Click on the Artboard with the Direct Selection Tool</p><p>Click on the Artboard in the artboard panel and Choose Move from the flyout menu</p><p>Select the Artboard tool, click on the artboard and drag</p><p>Quit Illustrator without saving and relaunch</p><p>You can have up to how many vanishing points on a Perspective Grid?</p><p>Two</p><p>Three</p><p>Four</p><p>Five</p><p>The bar which appears in the lower left edge of Adobe Illustrator window is called the:</p><p>Toolbar</p><p>Control bar</p><p>Status bar</p><p>Properties bar</p><p>You are creating a JPG banner ad for display on a we<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Illustrator lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Illustrator interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7b36cfc1736214196a8920436d36d724','adobe-illustrator-course-mastery-assessment','7fd87e4033e3bba77334f64ab4523f8d','Course Mastery Assessment','assessment',30,'<h2>Course mastery assessment</h2><p>Bring together knowledge and application from the complete course. Achieve at least 80% to satisfy the assessment requirement for certification.</p>',NULL,1,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO assessments (id,slug,course_id,title,pass_mark,questions) VALUES ('0b6e7c8b8327c9934fefe908b803adca','adobe-illustrator-course-mastery-assessment','2eeac88d9b6058d9d55e1dcf25daf550','Adobe Illustrator Course Mastery Assessment',80,CAST('[{"id":"adobe-illustrator-course-mastery-assessment-q1","type":"multiple-choice","prompt":"Before starting a practical task in Design Industry, which action best demonstrates professional judgement?","options":["Clarify the intended outcome, constraints, and success criteria before choosing tools.","Choose the fastest tool and define the goal afterward.","Copy the first available example without checking its fit.","Begin production immediately and leave requirements for final review."],"answer":"Clarify the intended outcome, constraints, and success criteria before choosing tools.","explanation":"Strong practice begins with a clear outcome, constraints, and measurable success criteria.","clue":"Think about what must be understood before execution begins."},{"id":"adobe-illustrator-course-mastery-assessment-q2","type":"multiple-choice","prompt":"A first attempt in Ditital Graphics & Illustrations does not meet the requirement. What is the strongest next step?","options":["Compare the result with the criteria, identify the cause, revise, and test again.","Submit the attempt unchanged because the task is complete.","Replace the criteria with measures the attempt already meets.","Discard all evidence and restart without diagnosing the issue."],"answer":"Compare the result with the criteria, identify the cause, revise, and test again.","explanation":"An evidence-led improvement cycle diagnoses the gap before a focused revision and retest.","clue":"Use feedback and evidence to improve the next attempt."},{"id":"adobe-illustrator-course-mastery-assessment-q3","type":"multiple-choice","prompt":"Which evidence most credibly demonstrates applied competence in Understanding Illustrator Part 1?","options":["A completed work sample with decisions, checks, feedback, and reflection documented.","A claim that the topic was understood without a work sample.","A list of tools with no explanation of how they were used.","An unfinished draft that has not been checked against requirements."],"answer":"A completed work sample with decisions, checks, feedback, and reflection documented.","explanation":"Competence is best demonstrated through completed, reviewed evidence and reflective reasoning.","clue":"Choose evidence that shows both the result and how quality was established."},{"id":"adobe-illustrator-course-mastery-assessment-q4","type":"multiple-choice","prompt":"When work in Understanding Illustrator Part 2 could affect people, data, safety, or the environment, what should the learner do?","options":["Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","Proceed without checks when the intended outcome is positive.","Treat ethical and safety considerations as optional after delivery.","Hide known limitations so stakeholders remain confident."],"answer":"Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","explanation":"Responsible practice makes risk, consent, standards, and safeguards part of the work itself.","clue":"Professional quality includes the impact of the work, not only the output."},{"id":"adobe-illustrator-course-mastery-assessment-q5","type":"multiple-choice","prompt":"How should a learner transfer skills from Graphics and Illustrations Part 1 to a new workplace or project context?","options":["Analyse the new context, adapt the method, test assumptions, and evaluate the result.","Repeat the original steps unchanged regardless of context.","Use only familiar methods and ignore new constraints.","Wait for a complete example to copy before making any decision."],"answer":"Analyse the new context, adapt the method, test assumptions, and evaluate the result.","explanation":"Transfer requires adapting core principles to new constraints and validating the result.","clue":"Core principles remain useful, but their application must fit the new context."}]' AS JSON)) ON DUPLICATE KEY UPDATE title=VALUES(title),pass_mark=VALUES(pass_mark),questions=VALUES(questions);
INSERT INTO courses (id,slug,academy_id,moodle_id,title,description,level,duration,price,is_free,status)
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('d3fed255f1ea1f42bc101e567fbfd33b','adobe-indesign-module-0','06e4e2edaf3c4cc38b4d0a152e3ee09a','Module 0: Introduction, Purpose, Objectives, Summary',0) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4f2702edde4c2675e86474471f3c852d','adobe-indesign-m0-l1-introduction-purpose-and-objectives','d3fed255f1ea1f42bc101e567fbfd33b','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Nav Objectives</h3><p>Course Intro Video</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>&#171; Back</p><p>wordsdefinition</p><p>⟳ Flip Card</p><p>Next &#187;</p><p>Flashcard&#160;1&#160;of&#160;3</p><p>Flashcard Transcript</p><p>close</p><p>Flashcard Transcript</p><p>words:&#160;definition</p><p>Communicating with words and text is important, but in today’s short-attention-span world, sometimes words need…well, a little help. The written word is eternal, so we might as well make it look good!</p><p>Adobe’s InDesign is one of the world’s best programs for creating text-based documents like e-books, brochures, magazines, business plans, and much more. It is an incredibly versatile tool that can create both printed pages, as well as fully interactive digital publications.</p><p>In this course, students can start with no experience and learn how to create in InDesign, preparing them for the ACE Certification exam. This course will give students a foundation of knowledge to start using InDesign and will prepare them for a rich set of opportunities in the world of digital publishing.</p><p>Course Navigation</p><p>In this Course Navigation, we’ll go over the overall course structure and what you can expect in each of the modules in this course.</p><p>Before You Begin</p><p>Before we go over the navigation and structure of the course, here are a few important things you should do:</p><p>Make sure you have Adobe InDesign open on your computer when you start the course.&#160;You can follow along with the reading material and instructional videos and explore InDesign as you learn about it.</p><p>Make sure you have Office suite programs or basic word processing programs installed on your computer, as you will require them for your project work.</p><p>Navigating the Course</p><p>Within each section, you can easily navigate between the pages either with the menu on the left, or with the left/right arrows on the bottom.&#160;This allows you to move between PAGES within each section.&#160;Once you are done with all the pages in a section, you can either click at the top on the title of the course, or you can click at the very bottom of the page to the next section.&#160;It’s very important to make sure you finish every page in a section BEFORE moving to the next section.</p><p>(opens in a new tab)</p><p>This image shows a typical course page with navigation bars on the left side as well as the bottom.&#160;The course number, title, and content will vary from course to course.</p><p>License:&#160;All Rights Reserved</p><p>Course &amp; Module Structure</p><p>The course is divided into 10 modules, with an initial introductory module that you are now taking.&#160;This introductory module is intended to make you familiar with the course structure and explain some basic but important concepts about sources, plagiarism as well as the syllabus of this course.</p><p>Each module of the course will be structured as shown in the diagram here.</p><p>Each module has an introduction, 4-5 lessons, and a summary and quiz at the end of the module.&#160;We begin each module with an introductory video into the topics that will be covered in that module.&#160;You can use the video controls to adjust the volume, captions, and speed of the video based on your preferences.</p><p>Each lesson of the module will cover a different topic for that module.&#160;Lessons contain multiple pages of content that comprise of instructional content as well as instructional videos.&#160;Follow along and explore InDesign yourself as you learn about its features and tools in each lesson.</p><p>As you will learn in the syllabus, the introduction, video, and reading pages are graded on participation, meaning you get credit for going through every page and activity in the module.</p><p>After each lesson is a concept check or reflection where you&#39;ll either input an answer or work with flashcards or maybe a sorting exercise to review and firm up the concepts that were taught in that section.&#160;The reflections are either journal entry or discussion prompts.&#160;To participate in a class-wide discussion, you’ll click on a link to read the questions or prompts, and then participate in the discussion by adding a new discussion topic and eventually commenting on posts from other students.&#160;You&#39;ll see this repeat itself through all the sections.</p><p>Every module ends with a module summary and additional resource links that you can check out.&#160;Once you are finished with each lesson, you will need to complete a project and a quiz.</p><p>The project gives you a chance to practice what you learned in that module in InDesign.&#160;Every module will have a different project and will give you a chance to be creative, explore all the tools yourself, and learn by doing.</p><p>Finally, the module quiz is pretty straight forward as they are mostly multiple choice and true/false questions.&#160;Unless you are told otherwise by your instructor, there are no retakes for quizzes, so give it your best shot on your first and only time.</p><p>Many aspects of grading or other features of the course may be changed by your individual schools and instructors.&#160;So please refer to updated instructions or grading procedures that they provide.</p><p>For additional help, you can reach out to your instructor or contact the help desk of your LMS.</p><p>Course Objectives</p><p>In this course, students will:</p><p>Understand the critical concepts related to working with colleagues and clients as well as crucial legal, technical, and design-related knowledge.</p><p>Navigate the interface setup and program settings that assist in an efficient and effective workflow.</p><p>Identify the process as well as demonstrate the ability to ingest digital assets for a project.</p><p>Organize document structure such as layers and tracks.</p><p>Manage document structure for efficient workflows.</p><p>Use core tools and features of the application to create visual elements and manipulate text and selections.</p><p>Save and export documents or assets within individual layers or selections.</p><p>Sources and Plagiarism</p><p>Sources and Bias</p><p>Throughout this course, you will be asked to write reports or complete assignments.&#160;You may also be asked to research content from external sources, such as news articles and videos.</p><p>Image <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('cb2355171c283acde81827c1d8dbe7e4','adobe-indesign-module-1','06e4e2edaf3c4cc38b4d0a152e3ee09a','Module 1: Working InDesign Industry Part 1',1) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('90ce332f56d1e4840258790b812dc580','adobe-indesign-m1-l1-introduction-purpose-and-objectives','cb2355171c283acde81827c1d8dbe7e4','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi, I’m Mr. Southwick and I’ll be one of your instructors for this course on Adobe InDesign. This is the intro video for Working in the Design Industry Part 1. If you are interested in learning graphic design, chances are you’ve heard of the “Big Three” Adobe software applications – Photoshop, InDesign, and Illustrator. In this course, we’ll be diving into the world of digital publishing with Adobe InDesign.</p><p>Throughout the course, you’ll have a variety of ways to learn the material. There will be readings, videos, screenshot tutorials, images, and much more. But we really have two ultimate goals. First, so that you learn how to use InDesign. And second, so that you are best prepared to take (and pass!) the Adobe Certified Expert or ACE Certification exam on InDesign.</p><p>As with most things in life, we learn best by doing, and something like InDesign is no exception. So as you are going through the course, I’d encourage you to have the InDesign program up and running on your computer. Follow along, trying things for yourself, and experiment! It’s ok and even encouraged to make mistakes. One because that’s how we learn, and two, there’s always the ability to undo an action!</p><p>InDesign is a complex program, and can be overwhelming for someone who is brand new to it. But we’ll be walking through it slowly, step-by-step to get you comfortable with all the key features of this software. You’ll see me introducing each module in this course, providing an overview of the topics you’ll cover in each one. My colleague for this course, Preeti, will be the one walking you through the screenshot tutorials of InDesign. I think you’ll agree, she has a much more pleasant voice than mine, and she is a top-notch expert when it comes to InDesign.</p><p>So what exactly does InDesign help you do? You can use InDesign to create and design everything from flyers, stationery, and posters to brochures, magazine and book layouts. InDesign gives you all the tools you need to create complex layouts, add stylish typography, eye-catching graphics, and even make your documents interactive. The thought of using professional typesetting and layout tools may sound complicated, but InDesign puts all of these tools together in a user-friendly, intuitive interface that is versatile and easy to use!</p><p>In this module, we’ll focus on the core aspects of working in the design industry with peers and clients. Take a peek into the life of a designer and understand real-world processes like client management, understanding your audience, project management, copyright and other standards.</p><p>Module Description</p><p>License:&#160;Public Domain</p><p>Working in the design industry is more than just knowing how to use graphic design tools.&#160;There are crucial design, legal, and technical aspects that you must take into consideration when you work on any design project.&#160;Another key factor is working with colleagues and clients, and how well you are able to communicate your ideas and design visions.</p><p>In this module, students will learn critical skills to recognize what their audience needs, and how to communicate with colleagues and clients about design plans.&#160;They will also learn the legal ramifications of copyright, permissions, and licensing when using digital&#160;content.</p><p>Objectives</p><p>By the end of this module, you will be able to:</p><p>Understand the Adobe Creative Suite and the role of the various applications.</p><p>Determine whether the content is relevant to the purpose, audience, and audience needs.</p><p>Demonstrate knowledge of techniques for communicating about design plans with peers and clients.</p><p>Demonstrate knowledge of project management tasks and responsibilities.</p><p>Determine the type of copyright permissions and licensing required to use specific content.</p><p>Polling Question</p><p>What is your level of familiarity with InDesign?</p><p>I&#39;ve heard about it but never used it</p><p>I&#39;ve played around on InDesign for fun</p><p>I&#39;ve created projects using InDesign</p><p>I’ve never heard about InDesign before</p><p>Make a selection to see the results so far.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('dc8f589ed8166a89b8ed8fd400bc1716','adobe-indesign-m1-l2-lesson-1','cb2355171c283acde81827c1d8dbe7e4','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>What is Adobe Creative Suite</h3><p>What is Adobe Creative Suite?</p><p>Creative Commons&#160;Adobe Creative Suite Logo(opens in a new tab)&#160;by Saingfx&#160;is licensed under&#160;CC BY 4.0(opens in a new tab).</p><p>Adobe Creative Suite is&#160;a set of software applications that enable you to create design-heavy media.&#160;It’s great for people who are involved in&#160;video editing, graphic design, photography, and even web development!&#160;It offers a wide degree of features that let you&#160;collaborate with other professionals across all mobile and desktop devices, which is why it is an optimal choice for many businesses.&#160;You can grant editing rights to team members near and far and any updates will be automatically reflected in real-time for all your collaborators!</p><p>What apps are there in Adobe Creative Cloud?</p><p>There are more than 20 different apps includes in Adobe Creative Cloud, which you can purchase as a package or as individual subscriptions.</p><p>Here are just a few of them:</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Adobe Video Tools</p><p>Adobe has a suite of video and audio editing tools that are used by professionals around the world to create everything from YouTube videos to Hollywood movies.&#160;Apps include:</p><p>Premiere Pro</p><p>Premiere Rush</p><p>After Effects</p><p>Character Animator</p><p>Adobe Audition</p><p>Adobe Spark</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Adobe Graphic and Visual Design Tools</p><p>These apps allow you to explore your creativity and bring your designs to life.&#160;Create logos, advertisements, posters, website designs, and even 3D designs.&#160;Use apps to paint, draw and sketch your artwork.&#160;Apps include:</p><p>Photoshop</p><p>InDesign</p><p>Illustrator</p><p>Adobe Spark</p><p>Photoshop Sketch</p><p>Capture</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Adobe Photography Tools</p><p>Transform your photographs with professional photography editing and enhancement tools.&#160;You can edit, organize, and share your photographs easily using apps like:</p><p>Lightroom</p><p>Photoshop</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Adobe Web Design Tools</p><p>The world lives on the web, and you can use Adobe tools to create visually stunning web and UX designs.&#160;Apps include:</p><p>Adobe XD</p><p>Dreamweaver</p><p>Adobe Spark</p><p>These software applications are quite popular, so I wouldn’t be surprised if you’ve heard of many of them before.&#160;Let’s look at them in a little more detail.</p><p>Click each tab to learn more about some of the core and most popular Adobe Creative Suite tools.</p><p>Next Tab</p><p>InDesign</p><p>Adobe InDesign gives you a wide degree of functionality for&#160;designing print media such as magazines, posters, newspapers, and basically any typographic marketing materials.</p><p>Illustrator</p><p>Adobe Illustrator gives you a wide degree of functionality for&#160;designing vector art or images. These images&#160; use mathematical lines and curves, rather than pixels, for ultimate scalability.</p><p>Photoshop</p><p>Unlike Illustrator, Adobe Photoshop gives you a wide degree of functionality for&#160;editing or manipulating&#160;highly-detailed, high-quality raster (pixel) images.</p><p>After Effects</p><p>Adobe After Effects gives you a wide degree of functionality for&#160;adding visual effects or animations to videos.&#160;It also allows you to easily animate text or characters, as well as add clips or green screens.</p><p>Acrobat</p><p>Adobe Acrobat gives you a wide degree of functionality for&#160;creating robust PDF files containing visual effects&#160;such as backgrounds, foregrounds, individually-resized pages, etc. You can even embed multimedia!</p><p>Flash</p><p>Adobe Flash gives you a wide degree of functionality for many purposes, including&#160;creating animations, cloud-based, desktop, and mobile software, as well as interactive online games. It is also used to embed online videos.</p><p>Dreamweaver</p><p>Adobe Dreamweaver gives you a wide degree of functionality for&#160;coding websites. In essence, it is an HTML editor, but unlike many editors, you can render in real-time the visual side of the website, or automatically generate code by working on the visual side.</p><p>Fireworks</p><p>Adobe Fireworks gives you a wide degree of functionality when&#160;developing web and mobile applications. It can infuse graphics with interactivity as well as create wireframes (skeletal 3D models of the apps) and object behaviors.</p><p>In this course, we’re going to be focusing&#160;on InDesign – a software program for creating beautiful print media and layouts&#160;such as magazines, posters, newspapers, and more!</p></section><section><h3>Introduction to Adobe InDesign</h3><p>Introduction to Adobe InDesign</p><p>This video will give you an overview of InDesign and its key features.</p><p>Video Title:&#160;Adobe Creative Cloud 2019 - Software and services for creative professionals</p><p>Video Publisher:&#160;Adobe(opens in a new tab)</p><p>&#171;What is Adobe Creative Suite?</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('97f47a2930edbfca31ad16d434bbec30','adobe-indesign-m1-l3-lesson-2','cb2355171c283acde81827c1d8dbe7e4','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Beginning a New Project</h3><p>Beginning a New Project</p><p>Unlike many other fields where client requirements are clear and measurable directives, working in the design industry can be much more challenging.&#160;It is essential for you to have a clear understanding of the purpose of the design, the intended audience, and their needs.</p><p>There are a number of key factors you need to keep in mind to ensure a smooth, productive and long-lasting business relationship with your clients.</p><p>Click each tab to learn more.</p><p>Ask the Right Questions</p><p>Any new project starts with understanding what the client wants. Most creative projects run into roadblocks because of a lack of basic understanding of what the client wants.</p><p>Make it a point to&#160;understand the client’s goals&#160;and what they hope to achieve. It is a good idea to research and gather information about the client before you speak to them. This will give you an idea of their company or product and what their past work has been like.</p><p>Listen&#160;to what your client has to say, and ask questions to refine the information they are giving you. Make sure you take notes while in discussion with the client so you can also note down any follow-up questions that you may have. Make a note of examples or recommendations made by the client.</p><p>There are many situations when the client doesn&#39;t really know what they want. In these cases, make sure you&#160;ask the right questions&#160;that lead to a clear, specific design direction.</p><p>Focus on the Purpose</p><p>As designers, your work speaks for you, your expertise, and your skill. Before you begin your project, ask yourself, “What do I want to accomplish with this publication?” Sometimes your purpose might be to inform or educate, other times it might be to persuade or inspire. Once you’ve figured out your ultimate aim, make sure that everyone on your design team is on board!</p><p>Understand the Audience</p><p>Once you’ve determined your purpose, then an idea of your audience will naturally begin taking shape. The success of your project will depend on your audience’s reaction to your publication. Therefore, once you’ve narrowed down who your audience is, you can begin “assuming character”. You can predict which type of language or terminology to use, what is beyond their scope and needs further clarification, what type of content they’ll find valuable, and what you can leave out. Consider factors like:</p><p>Age group</p><p>Educational background</p><p>Geographical location</p><p>Cultural aspects</p><p>Technical expertise</p><p>Accessibility</p><p>Finalize the Format</p><p>Your purpose will lead you to your audience, and your audience will help you narrow down considerations such as the general format or structure of your publication. How would you like your audience to interact with your publication? Will it be for an online or print medium? If you’re targeting the older baby boomer demographic, print might be more preferable. If you’re targeting millennials, then you might consider digital mediums.</p><p>Create the Design Approach</p><p>Once you’ve got the format, or general structure down, you can start making design considerations such as the layout and ratio of text to images in the publication. Am I working with a creative audience that’s apt to be more visually inclined, or with an academic audience that might prefer words? You’ll also need to consider the typeface, color, and imagery you intend to use. Ultimately, these design considerations need to fall within the constraints of your or your company’s budget.</p><p>At the end of the day,&#160;your overarching goal is to make sure that the final product delivers value.&#160;Allowing your purpose and audience to determine your format and design will help you ensure that the final product is marketable and well-received.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c398b01547246cf0cb2845c4f4647610','adobe-indesign-m1-l4-lesson-3','cb2355171c283acde81827c1d8dbe7e4','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Effectively Communicating with Clients and Peers</h3><p>Effectively Communicating with Clients and Peers</p><p>License:&#160;Public Domain</p><p>Design is such a subjective process, that&#160;communication&#160;is wholly integral to a project&#39;s success.&#160;On the one hand, you need to communicate effectively with your client to make sure that you&#39;re on the same page.&#160;Even with all the planning in the world, if there is a miscommunication error, then you dismantle a lot of your hard work and waste time and resources.</p><p>Whether you&#39;re a solopreneur or work as an agency or employee, large projects require you to work on teams.&#160;You might be clear on the client&#39;s expectations, but what if the rest of your team isn&#39;t?&#160;In this lesson, we&#39;re going to cover how you can&#160;communicate your design plans clearly, effectively, politely, and ensure that everyone is aligned with the same vision.</p><p>A key step in the design process is to share iterative versions of your work with both your team and clients to get feedback.&#160;This helps in many ways.&#160;Your peers can provide constructive feedback and suggestions based on their understanding of the client needs.&#160;And your clients can give you perspective on if your designs are in line with their expectations.</p><p>There are many techniques to share your design ideas and plans with clients and peers, depending on what tool and medium you are using.</p><p>Click each term to learn more.</p><p>Sketches</p><p>Rough outlines of your design which give clients a visual guideline of what to expect. This is a great first step to get feedback.</p><p>Specifications</p><p>Put down more technical specifications like color palettes, font, size and resolution, complexity, navigation choices, etc. This is helpful in filtering and honing in on what works for the client.</p><p>Wireframes</p><p>These are mainly used in web design and are used to establish the basic structure of a page before the graphics, design, and content are added. This is a fantastic way to give clients a big picture outline of the product. It is also more efficient for you to make any changes to the core structure at this stage, rather than after the entire web page is built.</p><p>Prototypes</p><p>While a wireframe is a skeleton of your design, a prototype is a short, full-featured working sample of your final product. Think of a prototype like a trailer to a movie. It shows you exactly what to expect and gives you as close an idea of the final product as possible without actually showing you the entire movie.</p><p>Here are a few videos that will walk you through the sketching to prototyping process that designers at Google use for their projects.</p><p>Video Title:&#160;Rapid Prototyping 1 of 3:&#160;Sketching &amp; Paper Prototyping</p><p>Video Publisher:&#160;Google for Startups</p><p>Video Title:&#160;Rapid Prototyping 2 of 3:&#160;Digital Prototyping</p><p>Video Publisher:&#160;Google for Startups</p><p>Video Title:&#160;Rapid Prototyping 3 of 3:&#160;Native Prototyping</p><p>Video Publisher:&#160;Google for Startups</p><p>Throughout all these stages, it is essential to keep track of client feedback and map it to their initial requirements.&#160;Are you still in line with what the client wants?&#160;Has the client strayed from what they wanted and are going in a different direction?&#160;What impact does that have on the effort or complexity of the project?&#160;These are all essential questions you need to ask at every stage.</p><p>As always, keep an open channel of communication with your team and clients about all of these factors.</p></section><section><h3>Addressing Communication Problems with Team</h3><p>Addressing Communication Problems with Your Design Team</p><p>(opens in a new tab)by Shutterstock</p><p>License:&#160;All Rights Reserved</p><p>Usually, when working on a design team, each member has a specific role based on his/her experiences and credentials.&#160;However, the differences that strengthen the group can also lead to conflict.&#160;Conflict is inevitable, but what dictates whether it can be overcome is how cohesive the group is.&#160;Communication&#160;is a core aspect of teamwork cohesion and alignment.&#160;With poor communication, teammates might feel devalued, misunderstood, confused, or hostile.&#160;These issues can be grave for successful project completion, especially in the face of deadlines.&#160;But there are many ways to not only address, but prevent these issues from occurring.&#160;Let&#39;s take a look!</p><p>Flip each card to learn more.</p><p>Designate a team leader</p><p>Clearly communicate your goals and expectations</p><p>Stay in touch with regular meetings</p><p>Stay on the same page as everyone</p><p>Keep discussions to a limit</p><p>Develop conventions and remain organized</p><p>Flashcard Transcript</p><p>Designate a team leader:&#160;In team settings, every member has their specific backgrounds and roles, so there&#39;s bound to be conflicting ideas. To keep things on a forward directory, designate a team leader to facilitate discussions and have the final say if need be. The team leader should remove his/her ego from the equation and stay focused on the vision/end result.</p><p>Clearly communicate your goals and expectations:&#160;Keep everyone updated on their roles, tasks, and responsibilities with periodic reminders about their task deadlines and the overall project timeline. Teammates should also be aware of what everyone else is responsible for. When delegating responsibilities, minimize gaps by balancing the skills sets.</p><p>Stay in touch with regular meetings:&#160;Whether you&#39;re working in-house or with a remote team, have regular - if possible, daily meetings - where teammates can feel open to voice any questions or concerns. Receive feedback from each other and hold regular design reviews. Exploit software like Trello, Slack, and Asana to easily share documents and update team members on each other&#39;s progress and deadlines.</p><p>Stay on the same page as everyone:&#160;Software programs like Slack, Trello, and Asana are great regardless if your teammates are near or far. It&#39;s an efficient way to stay on the same page. Staying aligned involves knowing who&#39;s doing what and why, and what&#39;s been completed or in-progress to smoothen the workflow and make it more efficient.</p><p>Keep discussions to a limit:&#160;Just like analysis paralysis<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('023932ebc0cd1889b8e09b22f61462ba','adobe-indesign-m1-l5-lesson-4','cb2355171c283acde81827c1d8dbe7e4','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Managing Your InDesign Projects</h3><p>Managing Your InDesign Projects</p><p>License:&#160;Public Domain</p><p>Project management is an essential part of working in the design industry.&#160;You may have the most creative and innovative ideas, but if you are unable to meet deadlines, manage your clients, or communicate effectively with your team, you will not be successful.&#160;The main goal of project management is to be organized at every stage of the project.&#160;You need to &quot;lay out&quot; a&#160;fundamental process, or&#160;&quot;steps&quot;&#160;for how to efficiently proceed with your project.&#160;Then, you simply fill it in with more specific details and tasks by&#160;breaking down the steps into smaller pieces.</p><p>The idea of an effective project management process is that once you&#39;ve established a methodology that works for you, you can apply it to virtually any project you embark on within or even outside of the design realm!</p><p>Some of the key components of project management are planning, time management, clear and open communication, and maintaining a professional attitude.</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Planning:</p><p>Start off your design process by charting out a project plan.&#160;You’ve already learned how to understand your client requirements in the last few lessons.&#160;Your project plan should take into account&#160;what&#160;needs to be done,&#160;how&#160;it needs to be done,&#160;by&#160;when&#160;it needs to be done, and&#160;who&#160;you will be working with.</p><p>Within your project plan, create timelines and milestones for specific tasks along with due dates.&#160;You should also be aware of what the review process will be with the client.</p><p>If you are working with a team on a project, make sure everyone has individually assigned tasks and that they follow up on their own responsibilities.</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Time management:</p><p>This is an essential step no matter what you do, whether you are in school or a working professional.&#160;As you gain experience in the design industry, you will be able to gauge how much time different tasks take.&#160;Allocate time for each task in your project plan and stick to a schedule.&#160;Make a note of all deadlines that have been met, and also those that haven’t been met, so that you can plan for unforeseen delays.</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Communication:</p><p>Another essential part of project management is to always have open, clear communication with your team and clients.&#160;When working with a team, make it a practice to give each other constructive feedback.&#160;Instead of “I don’t like it,” say something like “Have you considered using a more colorful background?”</p><p>Along with giving feedback, it is also essential that you be open to feedback from others.&#160;Your listening skills play a big role in having good communication skills.</p><p>When communicating with clients, it is important to remember that the client is not always right.&#160;Just because they said so is not always a reason to change the design.&#160;You are the design expert in this situation, so make sure that you consider the requirements of the project, client, and audience and decide if the client’s feedback improves the design of the project.&#160;If a client makes a suggestion that seems to be going away from the direction of the project, bring that to light in a professional manner.&#160;For example, “That’s a great idea, but I think our audience may not relate to it.&#160;I think it would have more of an impact if we…”</p><p>Once you begin to incorporate these basic project management principles into your work process, you will find that rather than it being another thing added to your plate, it will greatly ease and enhance your creative process.</p></section><section><h3>Project Management Tips</h3><p>Project Management Tips</p><p>While watching this video, think about the project management tasks we just covered and try to draw parallels with the methods presented in the video.&#160;They wholly complement each other!</p><p>Video Title:&#160;The Secret to More Freelance Work:&#160;Project Management?</p><p>Video Publisher:&#160;Brad Colbow</p><p>&#171;Managing Your InDesign Projects</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1f502174478e00b68a938a78626bd6c1','adobe-indesign-m1-l6-lesson-5','cb2355171c283acde81827c1d8dbe7e4','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Copyright Considerations</h3><p>Copyright Considerations</p><p>License:&#160;Public Domain</p><p>Every creative’s worst nightmare is seeing his/her original work redistributed under somebody else’s name or without the appropriate attributions.&#160;So, while you will need to implement appropriate&#160;copyright protections&#160;for your work, you’ll also need to be careful when sourcing images, content, and/or media!</p><p>As designers, you should be the first to understand the importance of giving credit where credit is due.&#160;It is your responsibility as creatives to ensure that you are aware of where the content you are using is sourced from, whether it is a quote, an article, photos, artwork, music, or even icons and logos.&#160;There are serious legal and ethical considerations and ramifications of using content created by someone else.&#160;This video gives you an overview of what copyright is.</p><p>Video Title:&#160;Copyright and Fair Use</p><p>Video Publisher:&#160;Common Sense Education(opens in a new tab)</p><p>What Is Copyright?</p><p>Copyright is a form of&#160;legal protection for original works of authorship, whether unpublished or published, that is&#160;tangible and/or perceptible.&#160;These works include but are not limited to:</p><p>Images</p><p>Movies</p><p>Novels</p><p>Poetry</p><p>Songs</p><p>Computer software</p><p>Architecture</p><p>The moment you create something, it is&#160;automatically protected under copyright law.&#160;You don’t need to necessarily register with the copyright office unless you’re filing a lawsuit.</p><p>Bear in mind that because only tangible forms of expression fall under the purview of copyright laws, abstractions such as facts, ideas, systems, or methods of operation are not protected.</p><p>Key Terms You Should Know</p><p>Copyright</p><p>Copyright&#160;is protection for intellectual property.</p><p>Creative Commons</p><p>A&#160;Creative Commons&#160;license is one of many public copyright licenses that allow the free distribution of “work” that is otherwise copyrighted. Creators use CC licenses when they want to give other people the right to freely share, use, modify, and build upon a work that they have created, in a bid to expand the range of creative works available to the public.</p><p>Patents</p><p>Unlike copyright law, patents don’t pertain to the realm of expression. Patents protect inventions and/or discoveries.</p><p>For example, Alexander Graham Bell patented the telephone.</p><p>Intellectual property</p><p>Intellectual property&#160;is anything that a person has written or created. This can include artwork, text, photos, music, sounds, and so on.</p><p>Fair use doctrine</p><p>Fair use doctrine&#160;is part of the copyright laws and states that small portions of materials can be used without explicit written permission of the creator for certain purposes, like news reporting or school work. This doctrine doesn’t clearly define what “limited” means, so be careful of overusing material. This doctrine also requires that you must give credit to the creator of the material that you are using.</p><p>Derivative works</p><p>Derivative works&#160;are copyrighted materials that have been altered or changed. These materials are also protected by copyright laws. Let’s say you use Photoshop to make changes to a copyrighted photo. That photo is still protected by copyright laws and you may not use it without written permission.</p><p>Academic standards</p><p>Academic standards&#160;for copyrighted material are higher than others. Researchers and scholars are considered experts in their fields and have a greater responsibility for sharing their opinions and ideas with the world. Because of this, they are held to higher standards of honesty and must give credit for all their research, including when they quote someone else’s words or even if they paraphrase those quotes in their own words. As a researcher, even if you paraphrase what someone else says, you still need to give them credit for it.</p><p>Trademarks</p><p>Trademarks protect logos, slogans, and words/phrases that uniquely identify a specific company or organization.</p><p>For example, McDonald&#39;s “I’m Lovin’ It” tagline and Nike’s swoosh logo are trademarked.</p><p>Avoiding Copyright Infringement</p><p>When creating an InDesign project, unless you plan to create everything completely fresh with in-house photography and illustrations, you’re most likely going to be sourcing a lot of materials, especially images!&#160;In this case, you’re going to need to:</p><p>License:&#160;Public Domain</p><p>1.&#160;Ask for permission.</p><p>It’s a huge no-no to simply grab photos off of other people’s websites, Google images, or to even assume that a photo of yourself/business is naturally yours to use if somebody else took the photo (the photographer owns the image not the subject in it!).</p><p>When seeking permission, let the owner know how you plan to use it (e.g., commercially vs recreationally) and how/where you’re going to display it .</p><p>The original author of the photo or media materials might allow you to use the photo under certain conditions, such as only using it once, paying a fee, or only if you assign the appropriate attributions as specified, etc.</p><p>Asking for permissions can take time.&#160;You need to track down and be absolutely sure of the owner/licensor and await their reply.&#160;Because you’ll be working with strict deadlines, always allow yourself sufficient time to obtain permissions.</p><p>2.&#160;Fair Use Copyright</p><p>There are certain conditions where you don’t need to ask for permission to use a photo or source materials.&#160;These conditions fall within the purview of “Fair Use” legislation.&#160;However, this too can be a slippery slope.&#160;Be mindful of the following Fair Use conditions:</p><p>The nature of use</p><p>Is it for commercial or non-profit/educational purposes? You’re more likely to fall under the Fair Use clause when your purpose is for non-commercial use.</p><p>The nature of the copywritten work</p><p>Has the work been published? Is it creative or factual? How easy is it to access? You’re more likely to fall under the Fair Use clause when the copywritten work is published, creative, and easy to access.</p><p>How much of the work are you using?</p><p>Are you using the whole photo or just a small part of it? Is the part that you’re using a significant detail? You’re more likely to fall under the Fair Use clau<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4a23f9174faaaca7df8808e6f07819f3','adobe-indesign-m1-l7-lesson-6','cb2355171c283acde81827c1d8dbe7e4','Lesson 6','text',12,'<h2>Lesson 6</h2><section><h3>Release Forms</h3><p>Release Forms</p><p>Just as you have copyright laws for using content created by other individuals, there are also rules in place that determine what you can and cannot take photos of and use commercially.</p><p>Legally, it is completely fine for you to videotape or photograph anything and everyone on public property within reasonable community standards.&#160;You do not need permissions to take photographs in these situations.&#160;You can even sell these pictures, as many photographers do to stock websites, product or media companies, etc.</p><p>Permissions come into the picture when you, or the buyer, choose to publish the photograph.</p><p>Model Release</p><p>A model release is a legal release signed by the subject of a photograph or video giving you permission to publish the photo or video in one form or another.</p><p>Location Release</p><p>A location release is a legal release signed by the owner or owners of a private property where you took photographs or videos giving you permission to publish the photo or video in one form or another.</p><p>As a photographer, it is not essential for you to get the model or location release for photographs you take unless you plan on publishing them yourself.&#160;But most professional photographers get the release forms signed because or the convenience and because it gives them better chances of selling the photograph to a buyer who wants to publish the photo without the hassle of having to find the people in or locations in the photo and get releases signed.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9ebab7516aef5841a3b2ec0869757ecf','adobe-indesign-m1-l8-module-1-summary','cb2355171c283acde81827c1d8dbe7e4','Module 1 Summary','text',12,'<h2>Module 1 Summary</h2><section><h3>Module 1 Summary</h3><p>Working in the Design Industry Part I - Summary</p><p>Summary</p><p>Great Work!&#160;You have successfully completed this module on Working in the Design Industry Part I!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>By now, you should be able to:</p><p>Understood the Adobe Creative Cloud and the role of the various applications.</p><p>Determined whether the content is relevant to the purpose, audience, and audience needs.</p><p>Demonstrated knowledge of techniques for communicating about design plans with peers and clients.</p><p>Demonstrated knowledge of basic project management concepts.</p><p>Identified legal and ethical considerations for using third-party content, such as copyright, permissions, and licensing.</p><p>Identified when and how to obtain permission to use images of people and locations.</p><p>Additional Resources</p><p>The following books, articles,&#160;and websites are additional resources to learn more about this topic.&#160;(Not required reading)</p><p>Photography and the Law(opens in a new tab)</p><p>Creative Commons(opens in a new tab)</p><p>Model Release(opens in a new tab)</p><p>Working Together:&#160;How Designers And Developers Can Communicate To Create Better Projects(opens in a new tab)</p><p>What Do All of the Adobe Programs Do?(opens in a new tab)</p><p>7 Steps to Profitable Print Advertising(opens in a new tab)</p><p>Professional Team Management Tips For Creative Folks(opens in a new tab)</p><p>3Doodler Start:&#160;Safe and Affordable 3D Printing Pen for Kids(opens in a new tab)</p><p>Factors to Consider When Designing Your Publications(opens in a new tab)</p><p>Your One-Stop Shop for Communicating with Design Clients(opens in a new tab)</p><p>10 Creative Graphic Design Tips for Social Media(opens in a new tab)</p><p>Design Process:&#160;Tips from an Expert Graphic Designer(opens in a new tab)</p><p>Graphic Design Tips #4 – Consider Your Audience</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7eea92eaff179ad322fa39940901c42c','adobe-indesign-m1-l9-module-1-project-empty','cb2355171c283acde81827c1d8dbe7e4','Module 1 Project Empty','text',12,'<h2>Module 1 Project Empty</h2><section><h3>Module 1 Project</h3><p>4100</p><p>Adobe InDesign</p><p>Working in the Design Industry Part I - Project</p><p>Project</p><p>For this assignment, you will interview a member of the graphic design or publishing community to gain their perspective on working in the Publishing and Design industry.</p><p>Find an interviewee who is working as a graphic designer or in the publishing industry, and who agrees to participate in the assignment.</p><p>The interview can be conducted in person, on the phone, virtually, or via email.</p><p>Prepare at least eight questions that cover topics from this module, such as:</p><p>Client communication and understanding your audience</p><p>Working with teams</p><p>Project management</p><p>Copyright and permissions</p><p>Be ready to ask follow-up questions, as needed, to prompt more in-depth discussion by the interviewee.</p><p>Your paper should be double-spaced and include:</p><p>Name of the person interviewed, and date and style of the interview (virtual, face to face, etc.)</p><p>Each question asked, followed by the interviewee’s answers.</p><p>A conclusion section (2 – 3 paragraphs in length) comparing what you learned from the interview and the concepts explored in this module.</p><p>Review the rubric below to see how you will be graded.</p><p>Working in the Design Industry Part I Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Interview Questions</p><p>8 points Interview questions are well designed to gain insight and perspective from the interviewee. Follow-up questions are used to effectively explore a topic further.</p><p>7-6 points Interview questions are adequately designed to gain some insight and perspective from the interviewee. Follow-up questions are used somewhat effectively to explore a topic further.</p><p>5-0 points Interview questions are poorly designed and unable to gain much insight and perspective from the interviewee. Follow-up questions are not used where needed.</p><p>8</p><p>Conclusion Paragraphs</p><p>8 points Includes in depth comparisons between the interview and course content, references specific details as evidence to support the comparisons made, and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete comparisons between the interview and course content, references some details as evidence to support the comparisons made, and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no relevant comparisons between the interview and course content, references no details as evidence to support the comparisons made, or does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Includes the required content and is formatted neatly.</p><p>1 point Does not include all required content or is not formatted neatly.</p><p>0 points Does not include all required content and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p><p>&#169; 2025. All Rights Reserved.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('73cb9788b601b9b1160aad7e611e72dd','adobe-indesign-m1-l10-module-1-quiz','cb2355171c283acde81827c1d8dbe7e4','Module 1 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Working InDesign Industry Part 1. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('27f220ee5f88fb596e0293a730e90ca2','adobe-indesign-module-2','06e4e2edaf3c4cc38b4d0a152e3ee09a','Module 2: Working InDesign Industry Part 2',2) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('97e641ed48fc53585a0ee6c140a0081c','adobe-indesign-m2-l1-introduction-purpose-and-objectives','27f220ee5f88fb596e0293a730e90ca2','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi everyone, and welcome back! This is the intro video for Working in the Design Industry, Part II for InDesign. The first module gave you a birds-eye view of working in the design industry. You learned about working with clients and peers collaboratively to bring a design idea to life. You learned what questions to ask to get to know what your client wants and understand what the audience needs. You also learned about the importance of project management and the role it plays in your creative process. Finally, you learned about the importance of copyright permissions and licensing both as a designer and as a user of other creative material.</p><p>In this module, we’ll be going into some of the more basic technical aspects of design as they relate to InDesign. Before we dive in, you need to have an understanding of key publishing terminology. You will gain some insight into some of the best practices employed in the publishing industry, and the different color and typography considerations you need to keep in mind. Let’s get started!</p><p>Module Description</p><p>A strong foundation of design principles and concepts is essential before you start to learn about any design program.&#160;In this module, students will learn about key terms related to publications and multi-page layouts.&#160;They will learn all about the basic building blocks of design, that is color, typography, layouts, templates, and more.&#160;Students will also gain an insight into some of the principles of design and common design and composition techniques.</p><p>Objectives</p><p>In this module, students will:</p><p>Demonstrate knowledge and understanding of key terms related to publication and multi-page layouts.</p><p>Demonstrate knowledge of how color is created in publications.</p><p>Demonstrate knowledge of elements and principles of design and common design techniques.</p><p>Identify and use common typographic adjustments to create contrast, hierarchy, and enhanced readability.</p><p>Define common photographic/cinematic composition terms and principles.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('d1919ac59ffa2e8d21b879abce6e7add','adobe-indesign-m2-l2-lesson-1','27f220ee5f88fb596e0293a730e90ca2','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Image Size and Resolution</h3><p>Image Size and Resolution</p><p>Pixels&#160;are the most basic building blocks of digital images.&#160;Just like paintings or drawings are made up of brush or pen strokes, images are made up of hundreds or thousands of pixels.&#160;Each pixel is just a block of color and a digital image is like a grid of pixels.</p><p>One important thing to remember is that unlike other units of measurement that you may use for printed photos, like centimeters or inches, a single pixel doesn’t have a fixed size.&#160;The size of a pixel depends completely on the resolution of an image.&#160;Confused?&#160;Don’t worry, we’ll explain this in detail very soon.</p><p>The size of a document is defined in terms of the&#160;pixel dimensions.&#160;This is basically a count of the total number of pixels in an image.&#160;In a digital format, images are measured in terms of their pixel dimension.&#160;If you look at the specifications on your camera or phone camera, you will see that it may be a 5MP or 8MP camera.&#160;“MP” here refers to “megapixels”, which is basically “a million pixels”.&#160;So a 5MP camera will take pictures that contain 5 million pixels in the image (approximately).</p><p>Talking about taking pictures, you know that the standard size in which images are printed is usually 4 inches by 6 inches, but you can print images in many different sizes.&#160;The size in which the picture is printed is called the&#160;print dimensions&#160;or&#160;print size&#160;of the image.</p><p>Now, this may sound like it is the same as the pixel dimension, but it isn’t, and there’s a straightforward explanation.</p><p>Let’s talk about&#160;image resolution.&#160;The resolution of an image is a measurement of the number of pixels per inch of a printed image.&#160;Now, here is what makes the distinction between pixel dimensions and print dimensions clear.&#160;Do you remember how we said earlier that pixels don’t have a fixed size?&#160;This means that you can have as many or as few pixels in an image as you want.&#160;All you need to do is change the image resolution.</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>For example, in the above picture, the face on the left has a very few pixels and you can just about make out the face and features.&#160;This is because it has a low number of pixels per inch of the face, i.e., a low resolution.&#160;On the other hand, the face on the right has a high number of pixels and therefore all the facial features are clearly defined.&#160;This part of the image has a high resolution.</p><p>Increasing the resolution of an image usually increases the quality and size of the image.</p></section><section><h3>Key Publishing Terminology</h3><p>Key Publishing Terminology</p><p>Here is some of the common publishing terminology that you will come across frequently throughout this course.</p><p>Click each term to learn more.</p><p>Orientation</p><p>The&#160;orientation&#160;of a page is basically the direction in which it is displayed or printed. The two basic types of orientations are landscape and portrait. You will use both of these for different types of documents. Based on the orientation of your pages, the images, text, graphics and other elements will be arranged differently on your document.</p><p>Layout</p><p>In publishing, the&#160;layout&#160;is the way in which the graphics and text are arranged on a page. In the older days of publishing, layout artists would physically arrange page layouts using printed pictures and cutouts to visualize how the page would look, before it was finalized for printing.</p><p>Nowadays, tools like InDesign are highly intuitive and can make it much easier for you to lay out documents that look professional, neat, and visually pleasing.</p><p>Facing Pages</p><p>Facing pages&#160;are the two pages that face each other in a book or publication. A set of facing pages is called a&#160;spread&#160;in InDesign. If you look at any of your textbooks, workbooks, or even magazines, you may notice that the book cover itself actually has three pages; the front cover, back cover, and the spine of the book. InDesign allows you to create 3-page spreads as well.</p><p>Pasteboard</p><p>When you work on a document in InDesign, you will see that there is a blank area around your document. This area is called the&#160;pasteboard. You can use this area to place objects that you may need during the design but will not be printed.</p><p>Bleed, Trim, and Slugs</p><p>A&#160;bleed&#160;is when an object or image you place on the corner or edge of a document touches or exceeds the edge of the document. This is used to ensure that the image that you placed on the document appears to start from the very edge of the page when printed, and no border or white margin appears around it.</p><p>Trim&#160;is the edge of the document where the bleed gets cut off when printed.</p><p>The&#160;slug area&#160;of a document is usually found at the bottom of a document and is an area used to enter non-printing information like the title or date. It is just data that is used for you to identify the document.</p><p>Master Page</p><p>Master Page&#160;in InDesign is the same as master pages that you will find in Microsoft PowerPoint and Word. This is a non-printing page that you can use to define a template for the rest of the pages. You can add text and graphic elements that you know will be repeated across all the pages, like the header, footer, page number, etc. This way, you do not need to add it over and over on each page.</p><p>Margins, Columns, and Gutters</p><p>Margins, as you may already know, are vertical and horizontal blank spaces that you can define for your document.</p><p>Columns&#160;are vertical sections that you can define in your document. These help you layout text and graphics neatly on your document.</p><p>Column gutters&#160;are the spaces left in between columns.&#160;Margin gutters&#160;are the spaces left in the inside margins of two facing pages in a document.</p></section><section><h3>Bitmap and Vector Graphics</h3><p>Bitmap and Vector Graphics</p><p>Next, let’s discuss&#160;bitmap or raster graphics&#160;and&#160;vector graphics.</p><p>Bitmap graphics&#160;are technically called raster graphics and are made up of pixels.&#160;Vector graphics, on the other hand, are made up of lines and curves defined by mathematical objects called vectors.</p><p>Take a look at this video to understand the diffe<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4a6591154db5729f0ce2c3b7849ec61a','adobe-indesign-m2-l3-lesson-2','27f220ee5f88fb596e0293a730e90ca2','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Color in Digital Images</h3><p>Color in Digital Images</p><p>We’ve all learned the basics of how colors are created from a very young age.&#160;You know that there are three primary colors, red, blue, and yellow.</p><p>In digital images, colors are stored in&#160;channels&#160;of color.&#160;Channels are basically Greyscale images that store information about the color elements in an image.&#160;The color channels in an image are dependant on the color mode.&#160;You must have already heard of some of the more common color modes like RGB, CMYK, or Greyscale.&#160;The&#160;color mode&#160;of an image determines how colors combine in an image based on the number of channels in a color model.</p><p>For example, the RGB model is made up of red, blue and green color channels.&#160;So an RGB image will contain colors that are made by combining the primary colors together.&#160;These are known as&#160;additive primaries.&#160;Most computer monitors use the RGB mode to create colors.</p><p>On the other hand, the CMYK model is made up of cyan, magenta, yellow and black color channels.&#160;These are known as&#160;subtractive primaries.&#160;This model is used for printing by most commercial and home-use printers, as well as to print full-color magazines, books, and brochures.</p><p>Take a look at this video to understand the differences between RGB and CMYK color modes.</p><p>Design in 60 Seconds:&#160;RGB and CMYK Color Modes Explained</p><p>Video Title:&#160;Design in 60 Seconds:&#160;RGB and CMYK Color Modes Explained</p><p>Video Publisher:&#160;EnvatoTuts+</p><p>Here are some of the key things you should keep in mind when you use colors in your digital images and designs.</p><p>Beginning Graphic Design:&#160;Color</p><p>Video Title:&#160;Beginning Graphic Design:&#160;Color</p><p>Video Publisher:&#160;GCFLearnFree.org(opens in a new tab)</p><p>To read more about color channels, check out the links in the&#160;Additional Resources&#160;page at the end of this module.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('fb9959f32b715d315ad1b4a30ed3e78c','adobe-indesign-m2-l4-lesson-3','27f220ee5f88fb596e0293a730e90ca2','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Design Considerations</h3><p>Design Considerations</p><p>Once you&#39;ve decided on what the purpose, audience, and general format of your InDesign project will be, then it&#39;s time to zoom into the particulars of the&#160;design considerations.&#160;With all the ideas, trends, and options at your disposal, the possibilities are endless and you might find the decision-making process overwhelming.</p><p>Which colors do you use?</p><p>What font or typeface should you use?</p><p>What is an appropriate ratio of text to images?</p><p>What images should I include and how do I legally source them?</p><p>These lessons will help you navigate all of these questions so that your selections will be appropriate and appealing!</p><p>Selecting the Right Color</p><p>Now that you have a solid footing in design layouts and composition, we&#39;re going to learn more about selecting appropriate and appealing colors.&#160;Color&#160;is important in design because:</p><p>They can be eye-grabbing and direct your attention.</p><p>They are emotionally evocative.</p><p>They have symbolic significance.</p><p>Therefore,&#160;when you&#39;re selecting a color scheme, keep your audience in mind!&#160;Think about what emotion or symbolic messages you&#39;re trying to evoke and how much they align with your brand, your purpose, and your audience.</p><p>Color Combinations</p><p>Things become slightly more complicated when you&#39;re combining colors because they work collectively to convey a coherent message.&#160;For example, the symbolism and emotions that &quot;red&quot; evokes changes when paired with different colors.</p><p>Let&#39;s look at some of the&#160;Dos and Don&#39;ts&#160;of color use and color combinations!</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Don&#39;tallowcolors to bleed into each other.&#160;This creates a visual vibration that’s hard on the eyes.</p><p>Doensure that there is enough contrast between colors to make it easy on the eyes.</p><p>Don&#39;toverdo it with color.&#160;Not every detail needs to be colorful.</p><p>Dobalance the colors with more neutral colors like white, black, and gray so that it’s even and balanced.</p><p>Don&#39;tusecolors whose tones are inappropriate for your audience and message.&#160;For example, don’t use bright colors for serious/professional publications.</p><p>Douse colors whose tones align with your audience and message.&#160;For example, use bright colors for more fun or modern publications.</p><p>Next &#187;</p><p>Flashcard&#160;1&#160;of&#160;6</p><p>Flashcard Transcript</p><p>Don&#39;t:&#160;allow colors to bleed into each other. This creates a visual vibration that’s hard on the eyes.</p><p>Do:&#160;ensure that there is enough contrast between colors to make it easy on the eyes.</p><p>Don&#39;t:&#160;overdo it with color. Not every detail needs to be colorful.</p><p>Do:&#160;balance the colors with more neutral colors like white, black, and gray so that it’s even and balanced.</p><p>Don&#39;t:&#160;use colors whose tones are inappropriate for your audience and message. For example, don’t use bright colors for serious/professional publications.</p><p>Do:&#160;use colors whose tones align with your audience and message. For example, use bright colors for more fun or modern publications.</p></section><section><h3>Fundamentals of Designs</h3><p>Fundamentals of Designs</p><p>If you break down any design to its most fundamental components, you will see that it is made up of a few common components—space,&#160;line,&#160;shape,&#160;form,&#160;color&#160;or&#160;texture, and&#160;balance.</p><p>All of these terms are self-explanatory.&#160;But how do they come together to form a design?&#160;Take a look at this video that explains some of the fundamentals of design.</p><p>Beginning Graphic Design:&#160;Fundamentals</p><p>Video Title:&#160;Beginning Graphic Design:&#160;Fundamentals</p><p>Video Publisher:&#160;GCFLearnFree.org</p></section><section><h3>Principles of Graphic Design</h3><p>Principles of Graphic Design</p><p>What truly makes a design effective?&#160;Is it all subjective or are there basic principles that guide the way designs are structured and created?&#160;The Gestalt Principles&#160;can help you understand design better.</p><p>The word ‘gestalt’ is a psychology term that refers to a whole that is greater than the sum of its parts.&#160;When you look at a painting, the entire painting first makes an impact on you before you are able to notice the individual parts of the painting.</p><p>Let’s say that I tell your entire class to paint a bowl of fruit from memory in your own style or composition.&#160;The painting should include, at the very least, a bowl and fruit.&#160;You can choose to include other elements as you please.&#160;Now, all of these components of the painting can be arranged in an infinite number of ways, and every person in your class will have a different interpretation.</p><p>Let’s take a look at the Gestalt Principles that help define approaches you can take to create a coherent, connected design.</p><p>Gestalt Psychology and Why It&#39;s Essential for Good Design</p><p>Video Title:&#160;Gestalt Psychology and Why It&#39;s Essential for Good Design</p><p>Video Publisher:&#160;HubSpot</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2504930c1d2ec5475c683b3b0ec422c8','adobe-indesign-m2-l5-lesson-4','27f220ee5f88fb596e0293a730e90ca2','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Typography</h3><p>Typography</p><p>Text and typography is an often undermined but essential part of a design.&#160;It&#39;s everywhere you look if you think about it.&#160;From your computer or phone screens to any of the products you use, to signs and signals on the roads and shop fronts, typography is a key part of how we communicate.&#160;A font can make or break your design.&#160;Just think of the Coca Cola logo in a different font, would you even recognize it?</p><p>This video gives you a great explanation of the importance of typography, as well as different ways in which you can use typography to enhance and boost your designs.</p><p>Beginning Graphic Design:&#160;Typography</p><p>Video Title:&#160;Beginning Graphic Design:&#160;Typography</p><p>Video Publisher:&#160;GCFLearnFree.org</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('78ca7497b534642c73470046d270a3d0','adobe-indesign-m2-l6-lesson-5','27f220ee5f88fb596e0293a730e90ca2','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Design and Composition</h3><p>Design and Composition</p><p>You have the fundamentals in place, but what really makes a good design?&#160;Let’s say you’ve taken a beautiful picture, created fantastic graphical elements, chosen a great color palette and fonts.&#160;You have all the ingredients for brilliant design, but unless you put them together in the right way, you’ll be left with a bad taste in your mouth.</p><p>There are some basic tenets of design that must be applied for a design to be truly considered good or appealing.&#160;One key factor is the layout and composition of your designs.&#160;Take a look at this video to learn more.</p><p>Beginning Graphic Design:&#160;Layout &amp; Composition</p><p>Video Title:&#160;Beginning Graphic Design:&#160;Layout &amp; Composition</p><p>Video Publisher:&#160;GCFLearnFree.org(opens in a new tab)</p><p>Here are some tips and techniques that you can use to ensure your designs are composed and arranged in a way that makes them stand out.</p><p>Strong Focal Point</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>This is an important factor when you create designs as well as when you take photographs.&#160;Choose a focal point that helps you get your message across in the best possible way.&#160;Think about your design approach, what is the key focus of the image?&#160;Where do you want viewers to look as soon as they look at their image?&#160;These questions will help you frame your designs and photos better.</p><p>Contrast</p><p>Contrast is a very powerful tool that you can use to highlight and hide elements of your design.&#160;Use a feature color in an otherwise simplistic design to make the design pop.&#160;Use more neutral elements to balance out the design.</p><p>White Space</p><p>Mathematicians will tell you that the zero is possibly the most important number of all.&#160;Similarly, in design, you cannot forget the importance of ‘empty space’ or white space.&#160;You can use white space to create contrast, create focus, boost and enhance the design, all while keeping the design simplistic and clean.</p><p>(opens in a new tab)</p><p>License:&#160;No known copyright restrictions</p><p>Compositional Flow</p><p>When you take a photograph, do you find yourself adjusting your position, angle, and light because it doesn&#39;t quite look &quot;right&quot;?&#160;You can take ten pictures of a boat out at sea that all have the same elements in them, but you pick the best one because of its composition.</p><p>Composition refers to how the different elements of a design are arranged.&#160;Compositional flow&#160;is what determines how your eye is led through this design.&#160;Where do your eyes go the first second you look at an image or design?&#160;Where does it go next?&#160;What catches your eye?</p><p>Until now, you would have unconsciously used this to judge what designs look good to you.&#160;If you think about this consciously when creating a design, you can use this to determine where to place the most important information first.&#160;For example, if you are creating an advertisement flyer and want people to take advantage of a sale, make your flyer is designed such that your eyes are drawn first to the &quot;SALE&quot; or &quot;BUY NOW&quot; sections of your design.</p><p>Rule of Thirds</p><p>The rule of thirds is a very basic but highly effective technique that artists and designers have been using for decades.&#160;Divide your page into three columns and three rows.&#160;The rule of thirds states that the main focal points of your image should be at the points where the lines intersect.</p><p>You can test this out by picking a design that you like from a magazine or printing out a design and drawing the lines over it to see where they intersect.</p><p>Use the links in&#160;the Additional Resources&#160;section at the end of this module to learn more.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ed75e6973d8adc66f31184d2550c3ecb','adobe-indesign-m2-l7-summary','27f220ee5f88fb596e0293a730e90ca2','Summary','text',12,'<h2>Summary</h2><section><h3>Summary</h3><p>Summary</p><p>Great Work!&#160;You have successfully completed this module on Working in the Design Industry Part II!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this session, you:</p><p>Demonstrated knowledge and understanding of key terms related to publication and multi-page layouts.</p><p>Demonstrated knowledge of how color is created in publications.</p><p>Demonstrated knowledge of elements and principles of design and common design techniques.</p><p>Identified and use common typographic adjustments to create contrast, hierarchy, and enhanced readability.</p><p>Defined common photographic/cinematic composition terms and principles.</p><p>Additional Resources</p><p>The following websites are additional resources to learn more about this topic.&#160;(Not required reading)</p><p>RGB and Color Channels in Photoshop Explained(opens in a new tab)</p><p>Essential Photoshop Color Settings</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b9cc324d1c0bc81cab6841f2408f2194','adobe-indesign-m2-l8-module-2-project-empty','27f220ee5f88fb596e0293a730e90ca2','Module 2 Project Empty','text',12,'<h2>Module 2 Project Empty</h2><section><h3>Module 2 Project</h3><p>4100</p><p>Adobe InDesign</p><p>Working in the Design Industry Part II - Project</p><p>Project</p><p>In this assignment, you will use what you’ve learned about basic design principles and publication terminology to write an essay.</p><p>Pick an example of what you consider good print design to base your essay on. This can be a print advertisement, a magazine cover, a book cover, or a brochure that you found visually appealing.</p><p>Write a two-page essay on your assessment of the artwork based on the following factors:</p><p>The visual appeal of the document, why you think it is appealing, and how that ties into the basic principles of design.</p><p>The use of color and/or typography in the document and an evaluation of how they have been used to create contrast, visual impact, etc.</p><p>The impact of the layout and composition of the document.</p><p>Review the rubric below to see how you will be graded.</p><p>Working in the Design Industry Part II Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Understand basic principles of design</p><p>8 points The student demonstrates an understanding of the basic principles of design and common design techniques.</p><p>7-6 points The student demonstrates an adequate understanding of the basic principles of design and common design techniques. The essay contains some accurate details and concepts.</p><p>5-0 points The student demonstrates little to no understanding of the basic principles of design and common design techniques, and the essay contains inaccurate details or little to no explanation of concepts.</p><p>8</p><p>Understand use of color and typography</p><p>6 points The student demonstrates an understanding of the use of color and typography in designs.</p><p>5-4 points The student demonstrates an adequate understanding of the use of color and typography in designs. The essay contains some accurate details and concepts.</p><p>3-0 points The student demonstrates little to no understanding of the use of color and typography in designs. The essay contains inaccurate details or little to no explanation of concepts.</p><p>6</p><p>Understand image layouts and composition</p><p>6 points The student demonstrates an understanding of image layouts and composition.</p><p>5-4 points The student demonstrates an adequate understanding of image layouts and composition. The essay contains some accurate details and concepts.</p><p>3-0 points The student demonstrates little to no understanding of image layouts and composition. The essay contains inaccurate details or little to no explanation of concepts.</p><p>6</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('62ee0efeed24d383168a34c3901c67ca','adobe-indesign-m2-l9-module-2-quiz','27f220ee5f88fb596e0293a730e90ca2','Module 2 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Working InDesign Industry Part 2. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('932115f8ee8bd0b7433c46fe570d5f7e','adobe-indesign-module-3','06e4e2edaf3c4cc38b4d0a152e3ee09a','Module 3: Project Setup and Interface Part 1',3) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('37f24667fccb8af941ba53dd6e60a7f5','adobe-indesign-m3-l1-introduction-purpose-and-objectives','932115f8ee8bd0b7433c46fe570d5f7e','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Welcome back to the InDesign course. This is the intro video for the module on Project Setup and Interface Part I. So far in this course, you have had an introduction to some of the fundamental concepts of working in the design industry. You also learned about crucial design principles and techniques, as well as common graphic design terms and their definitions.</p><p>In this module, you will take your first look at InDesign and learn how to navigate the InDesign interface. We’ll explore the InDesign interface and learn about all the different tools and features available to you. Let’s kickstart your InDesign journey by learning how to create a new document in InDesign, how to use and set up the workspace using rulers, grids, guides, and much more. So let’s get started!</p><p>Module Description</p><p>The InDesign Interface is a treasure trove of useful tools and settings.&#160;As beginners, students will first need to get acclimatized with the interface so they can begin to identify the different sections and tools available.&#160;Students will learn how to get started with InDesign by creating a new document.&#160;They will also get an overview of all the elements of the InDesign interface and their functions.&#160;Finally, students will learn how to customize the InDesign workspace and preferences in a way that is both convenient and efficient.</p><p>Objectives</p><p>In this module, students will:</p><p>Create a document with appropriate settings for web, print, and mobile.</p><p>Identify and manipulate elements of the InDesign interface.</p><p>Navigate, organize, and customize the application workspace.</p><p>Navigate a document.</p><p>Use rulers, grids, guides, views, and modes to work efficiently.</p><p>Polling Question</p><p>What are some of the things you are excited to learn to create using InDesign?</p><p>Posters</p><p>E-books</p><p>Magazines</p><p>Interactive PDFs</p><p>Multiple of the above</p><p>Others</p><p>Results:</p><p>Multiple of the above&#160;100%</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9c578361f4976ac1ec6045b47cb7858c','adobe-indesign-m3-l2-lesson-1','932115f8ee8bd0b7433c46fe570d5f7e','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Creating a New Document</h3><p>Creating a New Document</p><p>When you open InDesign, the first thing you need to do is to create a new document.&#160;There are a few different ways in which you can do this.&#160;You can start with a blank document, open an existing document, or you can use one of the many available presets and templates to create a new document in InDesign.</p><p>Note:&#160;The screenshots and videos shown in this course may look a little different to you depending on the version of InDesign you are using, but the basic functions will remain the same.</p><p>This&#160;Start&#160;screen of InDesign gives you all the options you need to create a new document.&#160;You can click the&#160;Create New&#160;button to create a new document, or you can click the&#160;Open&#160;button to open an existing document.</p><p>Even if you don’t see the Start screen, you can always use these options by clicking the&#160;File&#160;menu.</p><p>To create a new document in InDesign, click the&#160;Create New&#160;button or use the&#160;File&#160;menu, select&#160;New&#160;and click&#160;Document.&#160;You can also use the keyboard shortcut&#160;Ctrl + N&#160;(Windows) or&#160;Command + N&#160;(Mac) to open a new document.</p><p>The&#160;New Document&#160;dialog box appears.&#160;Let’s explore all the elements you see here in the New Document window.</p><p>Along the top of the window, you can see several categories;&#160;Recent,&#160;Saved,&#160;Print,&#160;Web, and&#160;Mobile.</p><p>By default, when you create a blank document, the&#160;New Document&#160;window always opens on the&#160;Recent&#160;tab.&#160;If you have recently been working on any documents, you will see those in the area below.&#160;The&#160;Saved&#160;tab will contain custom presets that you have created and saved.&#160;You’ll learn more about what presets are in just a little while.</p><p>Let’s say you want to create a document that you will later print.&#160;Let’s select&#160;Print.&#160;As soon as you do this, you will see three sections,&#160;Blank Document Presets,&#160;Templates, and a sidebar called&#160;Preset Details.</p><p>Blank Document Presets&#160;are basically blank documents that have pre-defined settings like the size and orientation of the document.&#160;There are many different presets that you can choose from, based on your requirements, and the settings of each preset will be shown in the&#160;Preset Details&#160;column.&#160;You can click the&#160;View All Presets&#160;link to view all the available presets.</p><p>You also have the option to choose from a number of&#160;templates&#160;from Adobe Stock that already come with reusable elements, graphics, layouts and illustrations that you can use for your documents.&#160;This feature is very useful when you are creating a new project for a client.</p></section><section><h3>Creating a New Document Using Presets</h3><p>Creating a New Document Using Presets</p><p>When you select a preset from any of the categories, that is,&#160;Print,&#160;Web&#160;or&#160;Mobile, you will see the corresponding settings of each preset in the&#160;Preset Details&#160;column on the right.&#160;You can use this section to modify the settings of any preset.&#160;This includes settings like:</p><p>Click each hotspot on the screenshot to learn more.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>InDesign Preset Details panel</p><p>The hotspot points on the image are as follows:</p><p>Width and Height</p><p>These denote the size of the document. You can also specify the unit of measurement to use form the drop-down menu.</p><p>Orientation</p><p>You can choose if your document should be in Landscape or Portrait orientation.</p><p>Pages</p><p>This denotes the number of pages in your document. You can leave this as the default and add more pages later from your document.</p><p>Facing Pages</p><p>You can use this setting to make the left and right pages face each other when you create books, PDFs or other multi-page documents.</p><p>Start#</p><p>Here, you specify which page number the document starts on.</p><p>Primary Text Frame</p><p>Select this option to add a primary text frame on the master page.</p><p>Columns</p><p>You can add multiple columns to your document using this field.</p><p>Column Gutter</p><p>Here you can specify the amount of space in between two columns.</p><p>Margins</p><p>You can set the margins for the document in this section.</p><p>Bleed and Slug</p><p>You can set the bleed and slug position for your document. You will learn more about this later in the course.</p><p>The easiest way to create a new document in InDesign is to see if there is already a preset you can use.</p><p>Let’s first see how you can create a new document using one of the InDesign presets. The first step is to select a category from the tabs on the top of the&#160;New Document&#160;window. For this example, let’s select&#160;Print. You can see that many preset document sizes are available for you to choose from. You can also click the&#160;View All Presets&#160;link here to view all of the available presets. Let’s select&#160;Tabloid. You will see that as soon as I selected this preset, the details in the&#160;Preset Details&#160;panel have changed. You can see the dimensions, the orientation, and the other details of this preset. You can change the units here to see the dimensions in&#160;Inches. Now, click the&#160;Create&#160;button at the bottom of the window.</p><p>This is how you can create a new document in InDesign using presets.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e43bddbec2a4cce30f4b576da0457c9f','adobe-indesign-m3-l3-lesson-2','932115f8ee8bd0b7433c46fe570d5f7e','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>InDesign Interface</h3><p>InDesign Interface</p><p>Now that you’ve learned how to create a new document in InDesign, let’s explore the InDesign interface.&#160;InDesign is packed with a large number of features and tools that are categorized into different sections.&#160;The best part about InDesign is that you can modify and customize all these sections to suit your needs and create your own personal workspace.</p><p>When you open a document in InDesign, this is what the InDesign interface looks like.</p><p>Document Window</p><p>This is one of the biggest sections of the InDesign interface and is where your document will be displayed.&#160;This is where you will create and edit your document.&#160;You can also have multiple documents open.&#160;They will appear as different document tabs at the top of the document window.</p><p>The tab shows you the name of the document, the type of file it is, and the zoom level it is at.&#160;You will learn more about working with multiple documents later in this course.</p><p>Toolbox</p><p>The left panel of the interface has the toolbox which contains all the tools you will need to create and edit your artwork and documents.&#160;You can find tools for everything from selecting and cropping images to painting, drawing, and adding various shapes to your image.</p><p>Tools with arrows in the corner indicate that there are multiple tools nested within a tool.&#160;You can click and hold down the tool to view the nested tools.</p><p>In the default view, the toolbox appears as a single, long column of tools.&#160;You can easily expand the toolbox by clicking the double-arrows at the top of the toolbox—this view displays the same tools, just in two shorter rows.</p><p>Most of these tools are grouped into categories based on their functions.&#160;We’ll go into the details of how to use these tools later in the course, but for now, here’s an overview of the different categories of tools you will find.&#160;The screenshot here shows the different categories separated by color:</p><p>A:&#160;Selection Tools:&#160;Use these to select and move objects, points, lines, or sections on your document in different ways.</p><p>B:&#160;Drawing and Type Tools:&#160;Use these tools to create and format text, as well as to draw and style simple and complex objects and shapes like rectangles, polygons, freeform shapes, and more.</p><p>C:&#160;Transformation Tools:&#160;Use these to reshape, reorient or resize objects on your document.</p><p>D:&#160;Modification and Navigation Tools:&#160;Use these tools to move around in, control the view of, and measure distances in a document.</p><p>You’ll learn more about using all of the tools in the Toolbox in later modules.</p><p>Application Bar</p><p>The Application bar runs along the top of the InDesign window.&#160;This contains the workspace switcher, menus (on Windows only), and other application controls.&#160;If you are using a Mac, you will only see the application bar when the Application frame is off.&#160;You can toggle it on or off using the&#160;Window&#160;menu.</p><p>Menu Bar</p><p>This is a standard element of most applications.&#160;The Menu bar runs across the top of the InDesign window and has all the main program-level functions and commands grouped into various categories like the&#160;File, Edit, Layout,&#160;and&#160;Window&#160;menus.&#160;You can use these different menus to set preferences and make other changes in InDesign.</p><p>Panels</p><p>On the right side of your InDesign window, you will see different docked panels that contain various document controls.&#160;Panels are where you will work with and apply different settings, properties, and formatting to your documents.&#160;By default, you will see three panels here, the&#160;Properties,&#160;Pages&#160;and&#160;CC Library&#160;panels.</p><p>If you select an item on your document, you will see that that the fields in the&#160;Properties&#160;panel also change.&#160;The&#160;Properties&#160;panel will show you different options depending on the object that you have selected.</p><p>If you select the&#160;Pages&#160;panel, you will see a list of the pages in your document.</p><p>There are many more panels available to you as well.&#160;To view a list of all the panels, click the&#160;Window&#160;menu.&#160;From here, you can select any panel that you want to add to your workspace and arrange it as convenient.</p><p>You can stack, group or dock panels in various configurations to make your workspace more usable.&#160;Because there are so many different types of panels available, InDesign groups similar panels together into Panel Groups.&#160;You will learn more about working with the different panels in the coming modules.</p><p>Workspaces</p><p>Workspaces in InDesign are basically a preset arrangement of the various interface elements.&#160;They determine which panels are displayed, how they are arranged, what tools are shown, etc.</p><p>Why do we have Workspaces?&#160;Because InDesign is such a versatile tool, there are so many different types of people that can use it for different things.&#160;For example, creating a book and creating digital publications may require a different set of tools, panels, and settings.</p><p>This is why InDesign gives you a variety of workspaces specific to different tasks to choose from.&#160;The default workspace is the&#160;Essentials&#160;workspace which is an all-purpose workspace that is suitable for many tasks.</p><p>Note:&#160;If you are using a touch-device like an iPad or a laptop with a touch-screen to open InDesign for the first time, it may detect this and open in the&#160;Touch&#160;workspace which allows you to use gestures to navigate through InDesign.</p><p>You can easily switch between workspaces by clicking the&#160;Workspaces&#160;option in the top-right corner of the InDesign window.&#160;This will show you a list of other preset workspaces to choose from.</p></section><section><h3>Vocabulary</h3><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definitions.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this lesson.</p><p>Shows the workspace switcher, menus, and other application controls.</p><p>Application bar</p><p>Shows program-level functions and commands grouped into various categories.</p><p>Menu bar</p><p>Help you monitor and modify your work.&#160;There are different types of panels for differen<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('21429e7d3383656ad96b42a952c7a64f','adobe-indesign-m3-l4-lesson-3','932115f8ee8bd0b7433c46fe570d5f7e','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Manage Documents</h3><p>Manage Documents</p><p>In this lesson, we’ll go into all the ways in which you can customize your InDesign workspace.&#160;InDesign is very versatile and allows you to move, group, and manipulate your Document windows and panels.&#160;Let’s first see how you can manage multiple documents in InDesign.</p><p>You can open multiple documents in InDesign. Multiple documents, as I have opened here, appear as&#160;tabbed document windows. You can easily change the order of the documents by clicking and dragging the tabs left or right and positioning the tabs where you want.</p><p>If you want to view your documents as a&#160;Floating Document Windows, just click and hold the tab and drag it away from the other tabs. It will undock and separate from the group and appear as a “floating” window. You can do this to the other tabs as well.</p><p>To dock the document again, simply click the header and drag it back to the tabs. You&#39;ll see a blue highlighted area indicating the drop zone. If you want to change the layout of the document windows and see multiple windows open together, you can use the options in the&#160;Application&#160;bar. Click the&#160;Arrange Documents&#160;icon. Here you can see multiple different layouts that you can choose from depending on the number of documents you have open, and how you want to view them. Let’s select this side-by-side view. Arranging documents in this way is helpful for when you want to copy or move items from one document to another. All you need to do is click and drag the object or selection out from one window and drag it over the document’s tab for a moment.</p><p>So this is how you can organize your documents in InDesign.</p></section><section><h3>Manage Panels</h3><p>Manage Panels</p><p>Panels are a large part of the InDesign interface, and you will use them extensively when you work in InDesign.&#160;There are many ways in which you can modify, manipulate and customize panels.</p><p>As you know, InDesign panels appear in a column on the right side of the InDesign interface. They are usually grouped in 2-3 tabs based on their functions. You can rearrange these tabs in many different ways. Let’s start off by seeing how to&#160;dock and undock panels. A dock is basically a collection of panels or panel groups that are displayed together. You can dock and undock panels by moving them. To move a single panel, just click and hold the panel and drag it away from its dock. Now, as you are moving this panel, you can see&#160;blue highlighted areas. These are drop zones. If you drop the panel in a drop zone, it will get re-docked. If you move this panel to an area that is not in the drop zone, it floats freely and is basically a&#160;floating panel. To redock this, just drag it over back to the tabs and drop it.</p><p>You can also move entire panel groups. Just select and hold the title bar and drag it out of the dock. You can move and re-dock this in the same way as you did with the panels. Drag it till you see a drop zone and drop the panels. To collapse a dock, just click the double arrows that you see at the top of the panels here. This gives you a wider document window to work in.</p><p>Now let’s see how you can&#160;add and remove panels. Let&#39;s open this up again. To remove a panel, just right-click the panel and select&#160;Close. If you want to remove the entire panel group, select the&#160;Close Tab Group&#160;option.</p><p>InDesign has a ton of panels that you can add to your workspace as well. Click the&#160;Window&#160;button. Here, you can see a full list of all the panels available in InDesign. Just select the panel that you want to add, and it will be added to your workspace. This vertical dock is known as the secondary panel. When you add a new panel to your workspace, it is always added to the vertical dock. You can then move and reposition it wherever you want.</p><p>You can also easily resize any panel. Just drag any side of the panel to resize it. Now you know that when you drag a panel out of the dock and not into another drop zone, it remains as a floating panel. Let&#39;s say you have multiple floating panels. You can stack these floating panels together so that they move as a single unit. To stack a floating panel, just drag a panel onto the bottom of another panel. And as you can see, you can move both these panels together.</p><p>As you can see, there are a ton of ways in which you can move the panels around and arrange them based on your requirements. Now, let’s say you moved some panels around but now you want to reset it to how it was originally. All you need to do is to select the&#160;Workspace&#160;drop-down and select&#160;Reset Essential&#160;from the drop-down menu. All your panels will be rest to the default Essentials layout.</p></section><section><h3>Managing Workspaces</h3><p>Managing Workspaces</p><p>You have learned about all the elements of the InDesign interface, and you’ve also learned about different ways in which you can organize and customize these elements.&#160;Now, let’s see how you can save your workspace so that you can use the same settings the next time you use InDesign, and how you can delete or reset the workspace.</p><p>By default, InDesign gives you the Essentials workspace, as you can see up here. Now once you rearrange the panels or toolbox to suit your preferences, you need to have a way of saving this workspace so you can use it again. To save your custom workspace layout, all you need to do is click&#160;Window, select&#160;Workspace&#160;and click&#160;New Workspace.&#160;Enter a name for your new workspace. I’ll name this “Demo. As you can see here, your panel locations and your menu customizations will also be saved. Click&#160;OK. And here you can see that the workspace name has been changed to demo.</p><p>Now let’s say that after a while of working on the project using this workspace, you want to make a few more modifications. So let’s add another panel, and I&#39;ll dock that here. If you want to update your workspace to include these changes, click this drop-down list. Now you’ll see that there isn’t an “Update” button or link here. So how do you save the changes? Just follow the same steps you did when you created the workspace. Click&#160;New Workspace, enter the same name “Demo” and click&#160;OK. InDesign will ask you if you want to replace the existing workspace. So since we want to update the existing workspace, let&#39;s click&#16<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('aa8828c18359a1ac709aa3e3c5c0582e','adobe-indesign-m3-l5-lesson-4','932115f8ee8bd0b7433c46fe570d5f7e','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Zooming In and Out of Documents</h3><p>Zooming In and Out of Documents</p><p>In this lesson, you’ll learn how to navigate a document by zooming, panning, and scrolling.&#160;This will make working in InDesign much easier.&#160;Let’s start by looking at how you can zoom in and out of documents in InDesign.</p><p>When you open a document in InDesign, you will start off by seeing one or more pages in the document window.&#160;If you look at the&#160;Document tab, you can see the current or default zoom level of the document.&#160;It is also displayed in the&#160;Application bar.</p><p>There are many ways in which you can zoom in and out of the document.&#160;Let’s first see how you can zoom using the&#160;Zoom&#160;tool.</p><p>Zoom Tool:</p><p>The Zoom tool is a very useful tool in InDesign, and once you learn how to use it, you will find yourself needing to use it in most of your projects.&#160;First, let’s select the&#160;Zoom&#160;tool from the&#160;Toolbox; it is the tool shaped like a magnifying glass.</p><p>As soon as you roll over the document, you will see the cursor has changed to a magnifying glass with a plus sign in the middle, which means that it will zoom in to the document.&#160;To zoom in, just click the area that you want to magnify.&#160;With each click, the tool will magnify the document to the next preset percentage.</p><p>To zoom out of the document again, just press and hold the&#160;Alt&#160;key (if you’re using Windows) or the&#160;Option&#160;key (on a Mac) and you’ll see that the plus sign on the cursor changes to a minus sign.&#160;With the key pressed down, click on the area that you want to zoom out of.&#160;As with zooming in, each click will keep reducing the view and zooming out.</p><p>You can also zoom in or out of a document using the zoom level drop-down list in the&#160;Application&#160;bar.&#160;Just select the zoom level from the list and you can zoom in to or out of a document.</p><p>View Commands:</p><p>You can also use the&#160;View&#160;commands to move around in InDesign.&#160;Click the&#160;View&#160;menu from the menu bar.</p><p>You can click either&#160;Zoom In&#160;or&#160;Zoom Out&#160;from the list to zoom in or out of the document.&#160;Each time you click this, there is an incremental increase or decrease in the zoom level of the document.</p><p>You can also use the keyboard shortcuts shown here, that is&#160;Ctrl + +&#160;to zoom in or&#160;Ctrl + -&#160;to zoom out.&#160; On a Mac, you need to use the&#160;Command&#160;button instead of the Ctrl button.</p><p>There are a few more options here that you can use.&#160;If you click the&#160;Fit Page in Window&#160;option, you can fit the full page within the document window.&#160;This is helpful if you are zoomed in all the way and want to look at the full document.</p><p>You can click the&#160;Fit Spread in Window&#160;option to fit the full spread within the document window.&#160;A spread is a set of pages viewed together, just as you would see in a book.</p><p>To view the page in its actual or full size, just click the&#160;Actual Size&#160;option.&#160;Viewing the document in this mode will show you all the details and will give you an idea of the quality of the image as well.</p><p>Finally, if you have added objects to your pasteboard and want to see the entire pasteboard at once, then select the&#160;Entire Pasteboard&#160;option.</p><p>For all of these options, you can also use the keyboard shortcuts shown in the menu to access them faster.</p></section><section><h3>anning and Scrolling Documents</h3><p>Panning and Scrolling Documents</p><p>There may be times when you have zoomed into a document and now need to move to another area in the document.&#160;You can do this by panning in the document using the&#160;Hand&#160;tool from the&#160;Toolbox.&#160;This is the hand-shaped tool you see here.</p><p>Once you select the tool, the cursor will change to a hand icon.&#160;You can now click and drag the document anywhere to pan across it.&#160;You can also use the scroll bars to scroll the document.</p><p>If you continue to drag down in a multi-page document, you will see the next page as well.&#160;You can then continue panning and scrolling or you can use the View menu to adjust the view of the pages.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5974122f5d3409e1783a753d7d5b850a','adobe-indesign-m3-l6-lesson-5','932115f8ee8bd0b7433c46fe570d5f7e','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Showing and Hiding Rulers</h3><p>Showing and Hiding Rulers</p><p>Rulers help you position or place elements on the screen.&#160;You’ll find rulers in most commonly used writing and editing software and applications, many of which you must be familiar with, like Microsoft Word and PowerPoint.</p><p>By default, when you open a document in InDesign, you will see the rulers on the top and left sides of the document area.&#160;You can use the menu bar to show or hide rulers in InDesign.&#160;Just click the&#160;View&#160;menu and select&#160;Hide&#160;Rulers&#160;to hide the rulers.&#160;You can also use the keyboard shortcut&#160;Ctrl + R&#160;(on Windows) or&#160;Command + R&#160;(on Mac) to display or hide the ruler.</p><p>Rulers appear along the top and left sides of the document window.&#160;The default measurements are in millimeters.</p><p>Changing the Measurement Unit</p><p>Depending on the type of document you are working on, you may want your ruler to show you a different unit of measurement.&#160;You can easily change this by simply right-clicking on the ruler and selecting one of the other options available in the drop-down list.</p><p>You can also change this from the&#160;Preferences&#160;window.&#160;In the&#160;Menu&#160;bar, click&#160;Edit, select&#160;Preferences&#160;and click&#160;Units &amp;&#160;Increments.&#160;You can change the unit of measurement of the ruler from the&#160;Preferences&#160;window that pops up.</p><p>Zero Origin</p><p>If you look closely at the rulers, you will see that the “0” on both the left and top rulers are aligned with the top-left corner of the document.&#160;This point is called the ruler’s&#160;zero origin.&#160;This makes it easier for you to place objects on your document.&#160;For example, let’s say you need to place an image exactly 4 inches from the top edge of the page.&#160;You can use the ruler to measure where you place your image and make sure it is aligned correctly.</p><p>You can also change the default position of the zero origin to any position on your document.&#160;Just position your pointer over the intersection of the two rulers and click and drag down over the document.&#160;Release your mouse button at the position you want the origin to be.</p><p>You’ll see that the zeroes on the ruler have now moved.&#160;You can now use this new origin to align objects, grids, and guides.&#160;To restore the zero origin to the default position, just double-click at the point of intersection of the two rulers.</p></section><section><h3>Adding Guides</h3><p>Adding Guides</p><p>Guides are lines that you can place anywhere on your document, either vertically or horizontally, to help you arrange objects on your document.&#160;They are floating lines, which means that they always appear over any objects or text you have on your document, and they are only visible in InDesign while you are editing your document; they will not be printed or saved in your final output file.</p><p>You can add multiple guides to your document.&#160;There are two types of guides that you can create:</p><p>Page Guides:&#160;These guides appear only on the page that you add them to.</p><p>Spread Guides:&#160;These guides span across all the pages of a multi-page document.</p><p>One important thing to remember is that in InDesign, guides are tied to layers.&#160;This means that if you add a guide on a particular layer and then hide the layer, the guide will also be hidden.&#160;So, if you need the guide to be visible at all times, add it to a master page.</p><p>Another important thing to remember is that when you add a new guide to a document, the ruler will only appear on the target spread or page, that is, the active or selected page or spread.</p><p>Let’s take a look at a video to see how you can easily add guides to your document.</p><p>Adding a guide to your document in InDesign is very easy. Just click anywhere on the ruler and drag out from it. As you drag it over the document, you will see a vertical or horizontal line appearing on the document; this is the guide.</p><p>Now there are a few things you should keep in mind when you are creating guides. First, make sure that you have the correct spread or page selected where you want to add the guide. If the document has multiple layers and you want to add the guide to a specific layer, make sure you select the layer where you want to add the guide.</p><p>As you know, there are two types of guides that you can add. To add a guide just to this page, just click on the ruler and drag onto the page itself. You’ll see that the line stays within the boundaries of the page. If you want to add a spread guide, drag out a guide in the same way, but this time, keep the pointer in the pasteboard area and position the guide where you want on the spread. This guide line will spread across the pasteboard, and in case of a spread, will appear across both pages of the spread.</p><p>If you are zoomed in and want to add a spread guide, instead of zooming out till the pasteboard is visible, just press and hold down the Ctrl key in Windows or the Command key in Mac as you drag out the guide.</p><p>You can also create evenly spaced guide lines on your document. Click&#160;Layout&#160;and click&#160;Create Guides. Here, specify the number of rows and columns you want to add. You know that gutter indicates the space between two columns, so you can define this as well for both rows and columns. Once you have added all the settings, click&#160;OK&#160;and your new guides will be added to the page.</p><p>You can also make other adjustments to the guides. Click&#160;View&#160;and select&#160;Grids &amp; Guides. From here, you can show, hide, lock, or delete all the guides.</p><p>Smart Guides</p><p>These are similar to guides, but they are much more useful when you want to align multiple images, shapes or selections.&#160;Objects snap to guides, making it easier for you to control the spacing and alignment of objects on your document.&#160;By default, the Smart Guides feature is selected in InDesign.</p></section><section><h3>Adding Grids</h3><p>Adding Grids</p><p>A grid is a non-printing checkerboard grid that appears over your document.&#160;It helps you lay items on your document symmetrically.&#160;You can completely customize the grid in InDesign.&#160;There are two types of grids that you can create:</p><p>Baseline Grid:&#160;This is used to align columns of text on the document.&#160;This grid looks like a rule<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6102c4ce434a5bcfa71e9f531cd9e5d1','adobe-indesign-m3-l7-summary','932115f8ee8bd0b7433c46fe570d5f7e','Summary','text',12,'<h2>Summary</h2><section><h3>Summary</h3><p>Summary</p><p>Great Work!&#160;You have successfully completed this module on Project Setup and Interface Part I!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this session, you:</p><p>Created a document with appropriate settings for web, print, and mobile.</p><p>Identified and manipulated elements of the InDesign interface.</p><p>Navigated, organized, and customized the application workspace.</p><p>Navigated a document.</p><p>Used rulers, grids, guides, views, and modes to work efficiently.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c67cdcf809b70a96ed4a8a25f9c10883','adobe-indesign-m3-l8-project-empty','932115f8ee8bd0b7433c46fe570d5f7e','Project Empty','text',12,'<h2>Project Empty</h2><section><h3>Module 3 Project</h3><p>4100</p><p>Adobe InDesign</p><p>Project Setup and Interface Part I - Project</p><p>Project</p><p>In this assignment, you will apply all that you have learned about the project setup and the InDesign interface to perform the following tasks. You will need to use InDesign to perform these tasks. In some of these tasks, you may need to take screenshots to label them as well.</p><p>The first task is to create two documents in InDesign. One document should use one of the Document Presets provided, and the other should use one of the free Templates provided. (Take screenshots once the tasks are completed.)</p><p>Take a screenshot of the InDesign interface, paste it onto a Word or PPT document, and label the various components of the interface. You must label the following areas:</p><p>Toolbox</p><p>Panels and panel groups</p><p>Document window</p><p>Document tabs</p><p>Menu bar</p><p>Application bar</p><p>Change the document view to show both the documents that you created side by side. Also, undock the panels and make them all floating panels. (Take screenshots once the tasks are completed.)</p><p>Use the Zoom tool to zoom into your document in InDesign and take a screenshot showing the zoom level.</p><p>Add a vertical and horizontal Page Guide, as well as a Baseline Grid to your document. Both the guides and grids should have different colors. (Take screenshots once the tasks are completed.)</p><p>Project Setup and Interface Part I Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Create a document</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Identify interface elements</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Customize the workspace</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Navigate a document</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Use rulers, grids, and guides</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('278ad89a6d2230d2bfd1a3480b7d305a','adobe-indesign-m3-l9-module-3-quiz','932115f8ee8bd0b7433c46fe570d5f7e','Module 3 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Project Setup and Interface Part 1. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('834a4f1ef987ccc861b4ea7fbad2f5c2','adobe-indesign-module-4','06e4e2edaf3c4cc38b4d0a152e3ee09a','Module 4: Project Setup and Interface Part 2',4) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('72962d11fec4758112d733d11b16656e','adobe-indesign-m4-l1-introduction-purpose-and-objectives','834a4f1ef987ccc861b4ea7fbad2f5c2','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi everyone! Welcome back to the InDesign course! This is the intro video for the module on Project Setup and Interface Part II. So far, you’ve become familiar with working in the design industry. You should also be familiar with the InDesign interface, the different sections and elements, and how to organize your workspace using rulers, grids, guides, and more.</p><p>To work in InDesign, you first need to know how to import different assets into your InDesign documents. Next, color is a key component of your design and layout. You’ll learn how to use the tools available in InDesign to add and customize colors, gradients, swatches, and more! You will also learn how to apply styles to all of these components in your design.</p><p>Module Description</p><p>InDesign is a pioneer in the digital publishing world and allows you to create beautiful designs and layouts using rich and vibrant colors and text.&#160;This module will introduce students to different ways in which they can import assets into InDesign.&#160;They will learn about various ways in which they can select, use, and modify background colors, gradients, and swatches in InDesign.&#160;They will also learn how to manage paragraph, character, and object styles in InDesign.</p><p>Objectives</p><p>In this module, students will:</p><p>Import assets into a project.</p><p>Manage colors, swatches, and swatch libraries.</p><p>Create and customize gradients.</p><p>Manage paragraph, character, and object styles.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9e071aed1185676bf5ba4e1d922897e4','adobe-indesign-m4-l2-lesson-1','834a4f1ef987ccc861b4ea7fbad2f5c2','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Using Templates</h3><p>Using Templates</p><p>In the last module, you learned how to create new documents in InDesign using presets.&#160;In addition to the presets, InDesign also gives you a whole host of different templates that you can choose from.&#160;Templates are basically like sample designs and layouts with reusable content, placeholders for images, text, and much more.&#160;There is a multitude of templates you can choose from based on what you want to create, like menus, brochures, business cards, and even book layouts.</p><p>Let’s see how you can easily create a new document in InDesign using templates.</p><p>When you open InDesign and click&#160;Create New, the&#160;New&#160;Document&#160;window is displayed. There are different templates available for each of the three categories listed on top,&#160;Print,&#160;Web, and&#160;Mobile. Let’s select the&#160;Print&#160;tab.</p><p>If you scroll down, you can see all the different templates that are available for you to choose from. You can select a template and click the&#160;See Preview&#160;button to see what it looks like. To go back and browse through the other templates, just click the&#160;Back&#160;button.</p><p>Let’s preview this template. If you like what you see, you can click the&#160;Download&#160;button to download the template.&#160;Once the template has downloaded, you can click the&#160;Open&#160;button to launch a new document using this template. If the template is using fonts that you don’t already have installed, you may see a prompt like this asking you to download them. Just click Find Fonts and click Done to replace them with the suggested fonts.</p><p>And that’s how you can open a new document using Templates.</p></section><section><h3>Placing Assets in InDesign</h3><p>Placing Assets in InDesign</p><p>You’ve learned how to create a new document.&#160;The next step is to add assets to your document in InDesign.&#160;The best part of working in Adobe Creative Cloud is that you can easily import files from one program into another.&#160;So, you can easily import your Adobe Photoshop or Illustrator files in InDesign to work on them, and vice versa.</p><p>The&#160;Place&#160;command in InDesign helps you place assets into InDesign.&#160;This includes assets like images, text files, PDFs, Illustrator files, Photoshop files, or even assets from other InDesign files.</p><p>If you are familiar with using Adobe Photoshop and Adobe Illustrator, take a look at the links shared in the&#160;Additional Resources&#160;section at the end of this module to learn how to import .psd and .ai files into InDesign.</p><p>Let’s see how you can add graphics to your InDesign document.&#160;When you add graphics to InDesign, they need to be placed in a frame.&#160;This allows you to build a layout on your document.&#160;You can either create placeholder frames when you create your document, or you can just import or place graphics and InDesign will create the frame for you.</p><p>You’ll learn how to create a frame later in this course.&#160;For now, let’s see how you can directly use the&#160;Place&#160;command to add images to a document.&#160;To add an image to InDesign, click the&#160;File&#160;menu and select&#160;Place.</p><p>You can also click the&#160;Import File&#160;button in the&#160;Properties&#160;panel.</p><p>Navigate to the folder where you have the images and select the image you want to add.&#160;You can also choose multiple images to add at once using the&#160;Shift&#160;key and click the&#160;Open&#160;button.</p><p>Since you are not adding the images into a frame, you will see a preview of the loaded images on your cursor.&#160;You will also see a number in brackets here when you select multiple images – this just indicates the number of images you have selected.&#160;The image shown in the preview is the one that will be added first.&#160;If you want to switch to a different image, just use the arrow keys on your keyboard.</p><p>To place an image, drag a placeholder on the document.&#160;As you drag you will see that the dimensions of the shape you are dragging out are fixed to the dimensions of the image.</p><p>You can repeat this for all the remaining images you selected and place them on your document.</p></section><section><h3>Linked and Embedded Images</h3><p>Linked and Embedded Images</p><p>When you add images to InDesign, they can either be&#160;linked&#160;or&#160;embedded&#160;images.&#160;The main difference between linked and embedded images are the location where they are stored.</p><p>Linked images&#160;are not stored in your InDesign file, they are just lower resolution versions of the original image shown on your InDesign document, and they remain independent of the document.&#160;You can link images from multiple different sources, from Photoshop files, Illustrator files, PDFs, and more.</p><p>Linked objects are a very useful feature.&#160;Let’s say you are creating 3-4 different brochure designs.&#160;While they all have different designs, they can have the same images, address, title, etc. &#160;If you need to make any global changes like changing the image, you’ll need to go into each brochure’s InDesign file and update the dates.&#160;But with linked objects, you only need to make the changes to the main source image file, and the changes will be reflected in all the instances.</p><p>On the other hand,&#160;embedded images&#160;are directly copied into the document at full resolution.&#160;You can still replace an embedded image in InDesign, as well as maintain the version history.&#160;When you embed images, your InDesign document is self-sufficient.</p><p>Is the Image Linked or Embedded?</p><p>So, when you add an image to your InDesign document, how do you tell if it is linked or embedded?</p><p>When you use the&#160;Place&#160;command, in most cases the image is added to your document as a linked image.&#160;The exception is when you place an image from an Adobe Illustrator file, it is embedded into the document.</p><p>The first indicator that an image is a linked image is in the image itself.&#160;You will see a link icon on the image itself.&#160;This indicates that the image is linked.</p><p>Another indicator is in the&#160;Properties&#160;panel.&#160;Select the image in your document.&#160;At the top of the&#160;Properties&#160;panel, you will see&#160;Linked&#160;File&#160;or&#160;Embedded File&#160;depending on if the image is linked or embedded.</p><p>If you hav<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('771ab278457887e5253b479dd449ef93','adobe-indesign-m4-l3-lesson-2','834a4f1ef987ccc861b4ea7fbad2f5c2','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Working with Colors in InDesign</h3><p>Working with Colors in InDesign</p><p>InDesign has a number of tools you can use to add color to your images and documents.&#160;This includes the&#160;Toolbox, the&#160;Swatch&#160;panel, the&#160;Color panel, the&#160;Color Picker, and the&#160;Properties panel.</p><p>Before we go into how to apply color to your document, let’s go over some key terms.</p><p>Stroke:&#160;This is the border of an object such as shape, image, frame, or text.</p><p>Fill:&#160;This is the color filled into the background of an object such as shape, image, frame, or text.</p><p>In InDesign, you can store colors in the&#160;Fill&#160;and&#160;Stroke&#160;color boxes.&#160;These boxes are found at the bottom of the Toolbox.</p><p>In this screenshot:</p><p>‘A’ shows you the default fill and stroke colors.&#160;You can click this icon to return to the default colors.</p><p>‘B’ shows you the current fill color.&#160;You can double-click it to change the fill color using the Color Picker.</p><p>‘C’ is the current stroke color.&#160;You can double-click it to change the stroke color using the Color Picker.</p><p>You can click the ‘D’ icon to easily switch the fill and stroke colors.</p><p>The ‘E’ icons are the&#160;Formatting Affects Container&#160;and&#160;Formatting Affects Text&#160;icons.&#160;You can click these to indicate if the colors you select are applied to text frames or text in your document.</p><p>There are many ways in which you can apply colors in InDesign.&#160;In the screenshot above, you can see that the default fill box has a red line across it, which indicates that there is no fill.&#160;The default stroke box has a standard black stroke as the default setting.&#160;You can choose to set an active fill and stroke color for text frames or text beforehand.&#160;Alternatively, you can create your shapes, frames or text and then apply color and stroke to them.</p><p>Color Picker</p><p>The Color Picker is the most full-featured way to pick a color in InDesign.&#160;The Adobe Color Picker allows you to input specific values and choose colors using different color models; RGB, Lab, CMYK, and even the hexadecimal value of the color.</p><p>The big square box you see is called the&#160;color field.&#160;This shows you the full range of colors and you can click in the field to select a shade.&#160;The rectangle next to it is the&#160;color spectrum, which allows you to refine the shade you select using the color slider triangles.</p><p>On the right, you can see the different color models.&#160;To give you an overview of each of these color models:</p><p>RGB:&#160;Uses the Red, Green and Blue values to define a color.&#160;The values for these colors range from 0 to 255, where 0 indicates no color and 255 is the pure color.</p><p>Lab:&#160;In this model, L specifies the luminance of a color, the A value denotes how red or green a color is, and the B value denotes how Blue or Yellow the color is.&#160;L values range from 0 to 100, and the A &amp; B values range from -128 to 127.</p><p>CMYK:&#160;Uses the Cyan, Magenta, Yellow, and Black color values to define a color.&#160;These are all denoted as percentage values.&#160;These are the values you will most commonly use as they are best suited for printing and publishing.</p><p>Hexadecimal value:&#160;The hexadecimal value or Hex code of color is based on the syntax #RRGGBB, where every two characters represent red, green, and blue colors.&#160;The values of these colors are integers in the range of 00 to FF, where FF is the pure color.</p><p>To learn more about the different color models and about how and where they are used, check the&#160;Additional Resources&#160;page at the end of this course.</p><p>The color picker shows you the exact numerical values of the colors you choose.&#160;You can save the values to be used later for another document, or if you have the values of a color you want to use, you can directly enter them here as well.</p><p>Color Panel</p><p>The Color panel and the Swatches panel are two panels that you can use to work with colors in InDesign.&#160;You can add both of these panels to your workspace by clicking the&#160;Window&#160;menu and selecting the&#160;Color&#160;option.</p><p>You will see the familiar Fill and Stroke boxes on the left of the panel.&#160;You can use these to select which color you want to set.&#160;By default, the color panel will show you CMYK colors.&#160;You can easily change this to RGB or Lab colors by clicking the Menu button at the top-right corner of the panel.</p><p>You can use the tint slider at the bottom of the panel to choose the color you want.&#160;You can then use the CMYK sliders or fields to refine the values to the color you want to choose.</p><p>You will also see a box at the bottom left which shows you the last selected color.&#160;You can change the color of an object to the last color that was set by clicking this icon.</p><p>Swatches Panel</p><p>Next, let’s look at the Swatches panel.&#160;The Swatches panel is the recommended panel to work with colors in InDesign because you can easily create and name colors and quickly apply them to your documents.&#160;A great advantage of using the Swatches panel is that you can easily make global changes to colors using this panel.&#160;Let’s say you have used a particular shade of green to create a multi-page document that contains stationery items like business card, letterhead, envelope designs, etc. If you want to change the shade of green to any other color, you can easily just change the color in the Swatches panel and it will be updated everywhere that color is used in the document.&#160;Every document can have a different set of swatches stored in its Swatches panel.</p><p>In the&#160;Swatches&#160;panel, you will see some familiar icons again.&#160;You will see the Fill and Stroke color boxes at the top, with six CMYK-defined colors.</p><p>Properties panel</p><p>You can also easily use the Properties panel to set the fill and stroke color for objects in your document.&#160;When you select an object on your document, you will see the&#160;Appearance&#160;section in the&#160;Properties&#160;panel.</p><p>Here, you can adjust the Fill, Stroke and other settings of the selected object.&#160;All you need to do is click the color tile to view the options.&#160;This is what appears when you click the&#160;Fill&#160;color tile.</p><p>At the top, you can see the current Fill color and thre<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3abcb2b38f5025e32155685bf103ef32','adobe-indesign-m4-l4-lesson-3','834a4f1ef987ccc861b4ea7fbad2f5c2','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Working with Gradients</h3><p>Working with Gradients</p><p>Gradients are a gradual change of color that sweeps over an image or shape.&#160;You can use them to blend colors and show subtle color changes to indicate shapes, shadows, and create interesting effects.</p><p>There are many ways in which you can add gradients to your documents in InDesign.&#160;First, let’s see how you can create a new Gradient Swatch in InDesign.</p><p>Creating a Gradient Swatch</p><p>You can create and save gradients using the Swatches panel in InDesign.&#160;Open the&#160;Swatches&#160;panel, click the&#160;Menu&#160;and select&#160;New Gradient Swatch.</p><p>You will see the&#160;New Gradient Swatch&#160;popup.&#160;There are a lot of settings that you can control here.&#160;At the top are the Swatch Name and Type.&#160;You can enter a custom name for the new swatch you are creating.&#160;There are two types of swatches you can choose from,&#160;Linear&#160;and&#160;Radial.</p><p>At the bottom, you will see a Gradient Ramp which shows a white to black gradient which are the default colors that you will see.&#160;You can also see two small boxes at the bottom, and a small diamond at the top of the gradient bar.&#160;The boxes at the bottom are&#160;color stops&#160;and they indicate the starting and ending colors of the gradient.&#160;The diamond at the top indicates the&#160;midpoint&#160;of the gradient.&#160;We’ll see how to use this later.&#160;To set the colors for the gradient, click the first color stop.</p><p>You will see that the&#160;Stop Color&#160;field becomes active.&#160;The default selection is CMYK and you can move the sliders to select a color.&#160;If you want to choose a color from the Swatches panel, select&#160;Swatches&#160;from the drop-down list.</p><p>Here, you can see all the swatches in your document.&#160;Select a swatch color from the list.&#160;In the same way, select the last color stop and select another color from the swatches list.</p><p>Now, you can adjust the midpoint between the two gradients by dragging the diamond in either direction.&#160;You can also move the color stops to decrease the distance between the two colors and make it a sharper gradient.</p><p>Once you are happy with the gradient, you can select Linear or Radial, name the swatch, and click&#160;OK&#160;or&#160;Add&#160;to save it.&#160;The new gradient will be saved in the Swatches panel with the new name.</p></section><section><h3>Modifying Gradients</h3><p>Modifying Gradients</p><p>You can also edit gradients to add additional stops, change the color stops, adjust the midpoints, and more.&#160;A good tip is to create a shape or object on your document and fill it with the gradient first before you make changes to the gradient.&#160;This way, you will be able to preview the changes as you are making them.</p><p>First, open the&#160;Swatches&#160;panel and double-click the gradient swatch to open it up.&#160;Select the&#160;Preview&#160;checkbox so you can preview the changes as you make them.</p><p>To add another color stop, click anywhere below the gradient bar.&#160;A new color stop is added, and the color values are defined by the position you clicked on.&#160;You can now adjust the color stop’s position by clicking and dragging it.&#160;You can also change the position of the other color stops in the same way.</p><p>To change the color of the new color stop, select the color stop and adjust the CMYK sliders till you get the color you want.&#160;You can also choose Swatches or another color set to choose colors from.</p><p>You should be able to see the new gradient applied to the shape in the document.&#160;Once you are happy with the changes, click&#160;OK.&#160;The gradient will be updated.</p><p>Gradient Tool</p><p>You can use the&#160;Gradient&#160;tool from the InDesign Toolbox to apply gradients to one or more objects on your document.&#160;For example, let’s say you have these four objects shaped like petals.&#160;They all have the same gradient applied to them.&#160;To give them a gradient effect from the center out, first select all the objects.&#160;Then, select the Gradient tool and position it where you want to begin the gradient.&#160;Click and drag across the objects in the direction where you want the gradient to flow.&#160;Once you release your mouse button, you will see that the gradient has been applied in the direction you indicated.</p><p>In the same way, you can also apply gradients to text as well.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('47b6b5e93ee416d49fdb191b6f01d178','adobe-indesign-m4-l5-lesson-4','834a4f1ef987ccc861b4ea7fbad2f5c2','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Character and Paragraph Styles</h3><p>Character and Paragraph Styles</p><p>What are Styles?</p><p>In InDesign, styles are formatting attributes that you can apply to different elements of your document.&#160;In this lesson, you’ll learn about&#160;character styles,&#160;paragraph styles, and&#160;object styles, and the types of styles you can apply to your documents.&#160;Since we haven’t yet covered how to add text or objects to documents, we’ll go into how to create, edit, and apply styles in the upcoming modules.</p><p>Character and Paragraph Styles</p><p>If you’ve worked in text editing tools like Microsoft Word and PowerPoint, you’ve definitely seen the Styles panel that gives you different formatting options for different sections of your text, like heading styles, paragraph styles, etc. For example, here is how the Styles panel looks in Microsoft Word.</p><p>You can apply different styles to both the characters and paragraphs that you create in InDesign.&#160;A&#160;character style&#160;is basically a set of character formatting attributes that are applied to text.&#160;Paragraph styles&#160;combine both the character attributes as well as the paragraph attributes.&#160;You can apply paragraph styles to one or multiple paragraphs in your document.</p><p>The best part about styles is that you can easily create, edit, and save styles to your document or even your CC Library.&#160;If you make a change to the formatting of a style, it is automatically updated to all the text in your document that has that style applied.</p><p>When you add text in InDesign, it is created with a default [Basic Paragraph] Style.&#160;You can edit this style based on your requirements and save it as a different style.</p><p>You also have the option to import styles from other documents.&#160;So let’s say you have a Word document that has custom styles applied to it, and you want to replicate it in InDesign.&#160;You can easily import your Word document into InDesign, and all the styles in the document will be imported as well!</p></section><section><h3>Object Styles</h3><p>Object Styles</p><p>Just as you can apply character and paragraph styles to text and paragraphs in InDesign, you can also apply styles to objects like shapes and frames using&#160;object styles.&#160;You can add formatting for everything from stroke, fill, transparency, shadows, text wrapping, and much more!&#160;You’ll learn more about applying object styles in a later module.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a9b3432c5a9e9165261016d006549c81','adobe-indesign-m4-l6-summary','834a4f1ef987ccc861b4ea7fbad2f5c2','Summary','text',12,'<h2>Summary</h2><section><h3>Summary</h3><p>Summary</p><p>Great Work!&#160;You have successfully completed this module on the Project Setup and Interface Part II!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Imported assets into a project.</p><p>Managed colors, swatches, and swatch libraries.</p><p>Created and customized gradients.</p><p>Managed paragraph, character, and object styles.</p></section><section><h3>Additional Resources</h3><p>Additional Resources</p><p>The following books, articles,&#160;and websites are additional resources to learn more about this topic.&#160;(Not required reading).</p><p>Import files from other applications(opens in a new tab)</p><p>When to link graphics(opens in a new tab)</p><p>Manage color</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ab5cdc6a94b8acc77ef00be384969d31','adobe-indesign-m4-l7-project-empty','834a4f1ef987ccc861b4ea7fbad2f5c2','Project Empty','text',12,'<h2>Project Empty</h2><section><h3>Module 4 Project</h3><p>4100</p><p>Adobe InDesign</p><p>Project Setup and Interface Part II - Project</p><p>Project</p><p>In this assignment, you will apply all that you have learned about project setup in InDesign to perform the following tasks. You will need to use InDesign to perform these tasks. In some of these tasks, you may need to take screenshots and label them as well. You can save the screenshots as images or add them all to a Word/PPT document.</p><p>Create a new document in InDesign and use the Place command to add an image to the document as a linked image.</p><p>Open the attached InDesign practice file&#160;InDesign ColorsPractice.indd(opens in a new tab)&#160;in InDesign. Create a new swatch color using the Eyedropper tool and selecting a color from the image.&#160;(Take a screenshot of your saved custom swatch.)</p><p>Create a gradient using your new swatch color as one of the colors, and another color from the Swatches list. Make sure you save the new gradient.&#160;(Take a screenshot once this task is complete.)</p><p>Define what Character, Paragraph and Object styles are in InDesign.</p><p>Once you are done with all the tasks, save your InDesign documents for review.</p><p>Project Setup and Interface Part II Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Import assets into a project.</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Manage colors, swatches, and swatch libraries.</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately with attention to detail and meeting all requirements.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well or as instructed.</p><p>5</p><p>Create and customize gradients.</p><p>5 points Demonstrated a strong understanding of the objective. The task was completed correctly.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. Almost all the instructions to perform the task were followed correctly, with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. Little to none of the instructions were followed correctly.</p><p>5</p><p>Manage paragraph, character, and object styles.</p><p>5 points Demonstrated a strong understanding of the objectives. The tasks were performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objectives. The tasks were performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objectives. The tasks were not performed well.</p><p>5</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('226aaf794074bb78b3d9ed633a6eeaed','adobe-indesign-m4-l8-module-4-quiz','834a4f1ef987ccc861b4ea7fbad2f5c2','MOdule 4 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Project Setup and Interface Part 2. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,7,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('81e9a6a504e6664e0f4d80e1f980cc1e','adobe-indesign-module-5','06e4e2edaf3c4cc38b4d0a152e3ee09a','Module 5: Organizing Documents',5) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('71e7c9f6a77e0a684bb37ad7042d5bbd','adobe-indesign-m5-l1-introduction-purpose-and-objectives','81e9a6a504e6664e0f4d80e1f980cc1e','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Welcome back! This is the intro video for the module on Organizing Documents. How’s your InDesign journey been so far? By now, you should have a good understanding of the basics of publication design and you should also be familiar with the interface options and basic project setup in InDesign. In this module, you’ll learn all about a very useful feature in InDesign, that is, Layers!</p><p>So, what exactly are layers? Layers are basically like a stack of acetate or transparent sheets. They look like they’re one single document, but they are actually made up of multiple elements drawn on separate sheets. This means that you can add, delete, or modify elements on these sheets without making any changes to any of the other layers. You can even hide layers to see how your document looks with or without some elements. You can create different page layouts, some of which use common elements, and you can hide the different elements to compare various page layouts. With InDesign layers, you can easily manage and modify your documents in a fraction of the time.</p><p>Module Description</p><p>Layers can help you manage all of the design elements of your document.&#160;They give you the flexibility to work on individual elements and adjust them as required.&#160;In this module, you will learn all about the Layers panel and how you can use it to create and modify layers.&#160;You’ll learn the mechanics of working with multiple layers on complex projects.&#160;You will also learn how to modify layer visibility and printability.&#160;Finally, we’ll go over how you can create, edit and customize pages in InDesign.</p><p>Objectives</p><p>In this module, students will:</p><p>Use the Layers panel to modify layers.</p><p>Employ best practices to effectively manage multiple layers and complex projects.</p><p>Modify layer visibility and printability.</p><p>Create pages in a document.</p><p>Edit and customize pages.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8d1c8494fcbe73b5006ec1ab092ff1c0','adobe-indesign-m5-l2-lesson-1','81e9a6a504e6664e0f4d80e1f980cc1e','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Layers Panel</h3><p>Layers Panel</p><p>Let’s kick off this module by exploring the Layers panel.&#160;Layers are a great way to manage content in your InDesign documents.&#160;You can open the Layers panel by clicking&#160;Window&#160;and selecting&#160;Layers.</p><p>The&#160;Layers&#160;panel is added to the vertical panel column.&#160;This panel will show you all of the layers in the document.&#160;You can use this panel to add, edit, delete, show, hide, and group layers.&#160;You can also arrange layers in a way that some content appears above or below other content in the document.</p><p>Let’s take a look at the different elements of the Layers panel.</p><p>Click each hotspot to learn more.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Layers panel in InDesign</p><p>The hotspot points on the image are as follows:</p><p>Layers panel menu</p><p>This menu contains actions you can perform like hiding, locking or deleting layers, or adjusting how layers are displayed.</p><p>Layer</p><p>This is the default layer that is created when you create a new document. Any new layers you create will be added above this layer.</p><p>Visibility</p><p>This eye icon controls the visibility of a layer. You can use it to hide and show layers to work on them separately.</p><p>Layer Lock</p><p>This lock icon allows you to lock or unlock layers. If you lock layers, none of the elements on that layer can be moved or selected.</p><p>Layer Select</p><p>This box here indicates if a layer or an object on a layer is selected.</p><p>Layer Color</p><p>You can assign different colors to layers to categorize them and easily identify them on your document.</p><p>New Layer</p><p>You can use this icon to create a new layer.</p><p>Delete</p><p>You can use this icon to delete a selected layer.</p><p>Adding &amp; Duplicating Layers</p><p>When you create a blank document in InDesign, it opens with a default layer named&#160;Layer 1.&#160;To add a new layer to your document, click the&#160;New Layer&#160;icon at the bottom of the&#160;Layers&#160;panel.&#160;You can also open the&#160;Layer menu&#160;and click&#160;New Layer.</p><p>A new layer is added.&#160;Always keep an eye on which layer is selected when you create a new layer.&#160;Your new layer will be added right above that layer.&#160;So, if you have multiple layers in a document and want to create a new layer above a certain layer, just select it and then create a new layer.</p><p>You can also duplicate layers in InDesign.&#160;Just select the layer you want to duplicate.&#160;Drag the layer to the&#160;New Layer&#160;icon and drop it.&#160;A duplicate layer will be created.&#160;You can also select the layer and then click&#160;Duplicate Layer&#160;from the&#160;Layer&#160;panel menu.</p></section><section><h3>Working with Layers</h3><p>Working with Layers</p><p>Renaming Layers</p><p>New layers in InDesign have generic names like “Layer 1”.&#160;You can rename this so that it is easier to find elements in your Layers panel.&#160;To rename a layer, just double-click on the layer name.&#160;You will see a popup where you can rename the layer and click&#160;OK.</p><p>Moving Objects and Layers</p><p>In InDesign, a layer can contain multiple objects.&#160;The way that objects and layers are displayed in the Layers panel is how they are layered on your document.&#160;So, any object that is at the top of the list will appear above the objects below.&#160;The same goes for layers.&#160;All the objects in one layer will appear on top of the objects on a layer below it.</p><p>For example, in the screenshot below, all objects are on the same layer.&#160;If you look at the Layers panel, the rectangle shape is listed on top of the text boxes, which is why it appears over the two elements in the image.</p><p>You can easily move it by selecting and dragging it up or down.&#160;So, if you move the rectangle shape down below the two text boxes, you will see that it appears behind the text but still above the background image in the document.</p><p>Locking &amp; Unlocking Layers</p><p>Let’s say you have a layer that is finalized, and you want to make sure that none of the objects on that layer are moved.&#160;To do this, you can lock the layer by clicking the space next to the eye icon in the Layers panel.&#160;A lock icon will appear, indicating that the layer is locked, and none of the items on the layer can be selected or moved.</p><p>If you only want to lock a few objects on a layer, then expand the layer by clicking the arrow next to the layer name and lock the specific objects only.&#160;This way, you can still edit the other objects on the layer.</p><p>If you want to easily lock multiple layers at once, just click in the space next to the eye icon of the first layer and drag down through all the layers you want to lock.&#160;You can unlock the layers by clicking or by clicking and dragging in the same way.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('fdd8aa744f732139b53e98fd99dceae8','adobe-indesign-m5-l3-lesson-2','81e9a6a504e6664e0f4d80e1f980cc1e','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Managing Layers in Complex Projects</h3><p>Managing Layers in Complex Projects</p><p>In most simple projects, you can manage all your objects easily on a single layer.&#160;But when you start working on more complex projects with multiple objects and pages, you will find that you have a large number of objects piling up, which can be difficult to track and manage.</p><p>There are a few things you can do to organize and sort objects in your document.&#160;If your computer desktop was filled with files and applications, what would be the first thing you would do to organize them?&#160;Categorize them into folders and subfolders!&#160;Similarly, in InDesign, you can group different objects on your document into different layers.&#160;You can also assign different colors to these layers so you can easily identify them with visual indicators.</p><p>Because layers work like stacked transparent sheets, objects on the lowermost layer will appear at the background of the image, and any object on the next layer will appear on top of it.&#160;So, make sure that you also take this into consideration when you group elements into a layer.</p><p>For example, if your document has four background images, a logo, and multiple text boxes, then the background images would all be in the lowermost layer, as they need to appear behind all the other elements.&#160;All the remaining objects and text would appear on one or more layers on top of the background image.</p><p>In this document, all the elements are on a single layer. Let’s take a closer look at all the objects here, we have background images, a shape, and some text boxes. To manage these items easily, let’s categorize them into three layers, one&#160;Background&#160;layer, one&#160;Text&#160;layer, and one&#160;Graphics&#160;layer. Let’s rename this existing layer as &#39;Background&#39;, let’s add a new layer and rename it as &#39;Text&#39;, and I&#39;ll add one more layer and name this &#39;Graphics&#39;.</p><p>Now the first thing that you will notice is that all three of these layers have different colored bars next to the name. These are the layer colors that you can use to visually categorize items on the layer. Right now, because all of the objects are on the Background layer, which is blue, you will see a blue border around all of the objects on the document. Now let’s see what happens when we move these objects into other layers.</p><p>To move an object, just select it and drag it into another layer. So since the next layer is text, I&#39;ll select this text and move it into the text layer. If you click this arrow and open the text layer, you&#39;ll see that the text layer has been added here. Let&#39;s also move this text box, and let&#39;s do this for the circle as well. Now because the graphics layer is on top of the text layer, you&#39;ll see that the circle is covering the text. So to move this, just click and drag the graphics layer below the text layer.</p><p>Now, do you notice any difference in the outline colors of the objects? You&#39;ll see that the circle has a faint green outline because the layer color is green, and the text boxes have a red outline because the layer color is red.</p><p>InDesign automatically assigns a new color to each new layer you create, but if you want to change this, just double-click the layer and that will open the&#160;Layer Options&#160;window. Here, you can choose from a huge list of colors, and if you scroll down, you&#39;ll see that you also have the option to create your own custom color. You can also adjust any of these other layer settings here. Let&#39;s leave this color as it is.</p><p>Another thing that can happen when you work on large documents is that you can end up with many empty layers after moving objects around on the document and in between layers. Instead of scrolling through all the layers looking for the empty ones, you can easily clean up your document by clicking the menu and selecting&#160;Delete Unused Layers.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('216db84a762d3567f39d7220af634fcc','adobe-indesign-m5-l4-lesson-3','81e9a6a504e6664e0f4d80e1f980cc1e','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Visibility and Printability</h3><p>Visibility and Printability</p><p>If you look at the Layers panel, you will see an Eye icon at the beginning of each layer and object on your document.&#160;This icon indicates the&#160;visibility.&#160;While working on documents with multiple objects or layers, you may want to hide one or more objects or layers so that you can work directly on other items on your document.&#160;Hiding layers also helps you visualize how your document may look with or without one or more elements.&#160;This doesn’t delete the layer; it simply hides it.</p><p>To hide a layer or object, just click the&#160;Eye&#160;icon.&#160;Hiding a layer hides all the objects on that layer, so if you want to hide only a few objects on a layer you can do that as well.&#160;You can hide as many layers as you want.&#160;To show hidden layers, simply click the&#160;Eye&#160;icon again.</p><p>Modifying visibility is also helpful when you create multiple layouts and want to compare different layouts to each other.</p><p>Another great way you can use layers is by adjusting the&#160;printability.&#160;When you work on documents like brochures or PDFs that need to go through reviews, it may take a long time to print them because of the number of graphics in them.&#160;If you only need to review the text, InDesign allows you to easily adjust the printability of certain layers to prevent them from being printed.&#160;This way, only the text layers will be printed quickly so you can easily review them and make any changes.</p><p>You can adjust the printability of a layer by double-clicking the layer to open the&#160;Layer Options&#160;popup.&#160;Here, you can deselect the&#160;Print Layer&#160;checkbox.&#160;This layer will not be printed until you change this setting back.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('431d39bb5ff6063ea9afd05ae78dc9f5','adobe-indesign-m5-l5-lesson-4','81e9a6a504e6664e0f4d80e1f980cc1e','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Creating Pages in a New Document</h3><p>Creating Pages in a New Document</p><p>At the beginning of this course, you learned how to create a new document.&#160;By default, InDesign creates documents with a single page, unless you are using a multi-page template to create a new document.&#160;There are a few different ways in which you can control the number of pages in your documents.</p><p>First, let’s consider a situation where you already know how many pages you want to create when you start creating a new file in InDesign.&#160;For example, if you know that you are creating a postcard or business card layout, you know that you will need two pages, one for the front of the card and one for the back.&#160;In these cases, you can specify the number of pages in your document right at the outset while you are creating a new file.</p><p>When you open InDesign and click&#160;Create New, you will see the&#160;New Document&#160;window.&#160;Here, you can select a preset to use for your new document.&#160;For example, in this example, we’ve selected a&#160;Letter&#160;preset.</p><p>If you look closely at the&#160;Preset Details&#160;column, you’ll see a field where you can enter the number of pages.&#160;The default number is&#160;1.&#160;You can change this to as many pages as you need.&#160;Don’t worry about entering the wrong number here, as you can always add or delete pages after the document is created as well.&#160;If you are creating a document that will eventually be a book or magazine, then you can keep the&#160;Facing Pages&#160;setting selected.&#160;If not, make sure you deselect this option before clicking&#160;Create.</p><p>Your new document will be displayed.&#160;This may look like a regular single-page document, as you see only one page.&#160;To view the pages in the document, you need to open the&#160;Pages&#160;panel.&#160;Usually, this will be open by default along with the Properties panel.&#160;If you don’t see it, you can open it using the&#160;Window&#160;menu.</p><p>The&#160;Page&#160;panel will be displayed.&#160;As you can see below, this document has four pages.&#160;You can move to any page by just double-clicking the page thumbnail.</p></section><section><h3>Adding Pages to an Existing File</h3><p>Adding Pages to an Existing File</p><p>Once you have started working on a file, you may realize that you need to add more pages to your document.&#160;In this case, you can easily add more pages to your InDesign document at any time.</p><p>Click the&#160;Layout&#160;menu, select&#160;Pages, and click&#160;Insert Pages.</p><p>In the&#160;Insert Pages&#160;popup, you can specify the number of pages you want to add, and you can also specify where you want to add the new pages.&#160;Once you are done, click&#160;OK.</p><p>The new pages will be added to your document, and you can see this in the&#160;Pages&#160;panel.</p><p>Another great option you have when you need to add new pages to an existing document is that you have the option to duplicate an existing page as well.&#160;This is useful if you know that the new page you are creating will have a similar layout to the page you have already created.&#160;To duplicate an existing page, just drag the thumbnail of the page that you want to duplicate down to the&#160;New Page&#160;icon at the bottom of the&#160;Page&#160;panel.</p><p>Similarly, if you want to delete a page, just select it and click the&#160;Delete&#160;icon at the bottom of the&#160;Pages&#160;panel.&#160;You can also drag the page and drop it on the&#160;Delete&#160;icon.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9d18104ecae3642a8cac40904f56f110','adobe-indesign-m5-l6-lesson-5','81e9a6a504e6664e0f4d80e1f980cc1e','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Using a Master Page</h3><p>Using a Master Page</p><p>If you have used programs like Microsoft PowerPoint or Microsoft Word, you may have used a master template or&#160;master page.&#160;A master page is basically like a document template.&#160;For example, when you buy notebooks or journals, you can choose a completely blank one or you can choose one that already comes with some designs around the page margins or that include page numbers, etc. The latter is an example of a document template.</p><p>When you create a new document in InDesign, it comes with a blank master page.&#160;If you are creating a document that will have elements that will be repeated on all the pages, like a logo or page numbers or even other design elements, master pages are very useful.&#160;You can also create multiple master pages in your document if you want two or more different templates to choose from.&#160;Any object that you place on a master template will appear on a page that uses that template.</p></section><section><h3>Creating a Master Page</h3><p>Creating a Master Page</p><p>Let’s see how you can easily create a custom master page in InDesign.</p><p>Let’s see how you can easily create a custom master page in InDesign. The first thing you need to do is to open the master page in your document. There are a few ways you can do this. You can open the Pages panel, and right at the top, you will see A-Master, which is the default master page in this document. You can double-click this thumbnail to open the master page. Another way that you can open the master page is from the Properties panel. In the Page section, just select A-Master from this drop-down list.</p><p>Now, let’s add a few things to this master page. Let’s add a footnote at the bottom of the flier that needs to appear on all the different layouts. First, let’s zoom in to this page so we can see it a little clearly. Just click View and click Zoom In. Okay, now select the line tool from the Toolbox. Now let&#39;s draw a line at the bottom of the page. You can use the Properties panel to change the color and thickness of this line. Next, I’ll select the Type tool from the toolbox and I&#39;ll draw a text box right above the line. I’ll then type in some text like this “Conditions apply”. And again, you can use the Properties panel to adjust the font size, the orientation of the text, the font color, etc.</p><p>Now, just to make it easier to manage these items, we&#39;ll switch to the Selection tool and select these two objects. We can move them to align them correctly on the page and let&#39;s scroll down in the Properties menu and click Group to group them together. This way, they will stay together on the page.</p><p>Now, let’s go back to the View menu and click Fit Page In Window to see the full page. This is how the master page looks. Now let&#39;s see how the flyer looks with this content added. Choose 1 from the Page list. And here, you can see that I added appears at the bottom of the flyer. You’ll notice that you cannot select or edit this content here because it is on the master page. Now, even if you add a new page to this document, the content on the master page appears here by default.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1f9e9e339df6834146d7f0c7a17a7333','adobe-indesign-m5-l7-summary','81e9a6a504e6664e0f4d80e1f980cc1e','Summary','text',12,'<h2>Summary</h2><section><h3>Summary</h3><p>Summary</p><p>Great Work!&#160;You have successfully completed this module on Organizing Documents!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Used the Layers panel to modify layers.</p><p>Employed best practices to effectively manage multiple layers and complex projects.</p><p>Modified layer visibility and printability.</p><p>Created pages in a document.</p><p>Edited and customized pages.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0839e108fdd46b36f06846f8b564f2b4','adobe-indesign-m5-l8-project','81e9a6a504e6664e0f4d80e1f980cc1e','Project','text',12,'<h2>Project</h2><section><h3>Module 5 Project</h3><p>4100</p><p>Adobe InDesign</p><p>Organizing Documents - Project</p><p>Project</p><p>In this assignment, you will apply all that you have learned about using layers and creating pages to manage the design elements of a document. You will need to use InDesign to perform these tasks. Download the&#160;Layers.indd(opens in a new tab)&#160;practice file and use it to perform these tasks. Take screenshots after completing each step and save them as image files or add them to a Word/PPT document.</p><p>Open the InDesign document and open the Layers panel. Rename the layer and add a new blank layer.&#160;(Take a screenshot once the task is complete.)</p><p>Next, create different layers and rename them. Sort the objects in the document logically into the different layers so that they are organized and appear correctly on the document.&#160;(Take a screenshot once the task is complete.)</p><p>Adjust the printability of the background images so that they will not be printed if you print this document.&#160;(Take a screenshot once the task is complete.)</p><p>Add a new page to the document.&#160;(Take a screenshot once the task is complete.)</p><p>Edit the master page by adding graphics and text objects to it. Take a screenshot of page 1 of the document once you are done.</p><p>Review the rubric below to see how you will be graded.</p><p>Organizing Documents Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Use the Layers panel to modify layers</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Manage layers in a complex project</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately with attention to detail and meeting all requirements.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Modify layer visibility and printability</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Create pages in a document</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Edit and customize pages</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9ab5077044fffaf017e4ca1e1d58e566','adobe-indesign-m5-l9-module-5-quiz','81e9a6a504e6664e0f4d80e1f980cc1e','Module 5 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Organizing Documents. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('8875d1b5f1089338ab8077acace2940b','adobe-indesign-module-6','06e4e2edaf3c4cc38b4d0a152e3ee09a','Module 6: Visual Elements Part 1',6) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('cb39680e7a857f5dfc3215b2de5bb284','adobe-indesign-m6-l1-introduction-purpose-and-objectives','8875d1b5f1089338ab8077acace2940b','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi and welcome back to another module. This is the intro video for the module on Creating and Modifying Visual Elements Part I.&#160; You’ve covered a lot of ground in your InDesign journey so far. You’ve learned a lot of the basics, but there is so much more to explore!</p><p>Because it is a tool specifically geared towards the web and print publication industry, InDesign gives you many different tools and features that help you lay out the visual elements of your documents.</p><p>Typography is another key aspect of your designs. Use the comprehensive type tools in InDesign to add text to your documents in creative ways. Adobe gives you free access to thousands of beautiful fonts to choose from, and InDesign allows you to create fun and exciting text effects, apply different text treatments, add text in different shapes and paths, and so much more. Let’s get started!</p><p>Module Description</p><p>InDesign is a haven for the creative mind.&#160;In this module, you will explore various tools and features that will allow you to place and layout visual elements of your document.&#160;Students will also learn how to add and manipulate text using various typographic settings in InDesign.</p><p>Objectives</p><p>In this module, students will:</p><p>Use core tools and features to lay out visual elements.</p><p>Use a variety of type tools to add typography to a design.</p><p>Use appropriate character and paragraph settings in a design.</p><p>Convert text to graphics and manage text flow across multiple text areas.</p><p>Use tools to add special characters or content.</p><p>Polling Question</p><p>So far, you’ve learned about many different features and tools in InDesign.&#160;Which of these did you find the most interesting?</p><p>Managing colors and swatches</p><p>Customizing the workspace</p><p>Using layers to manage objects</p><p>Principles of design</p><p>Make a selection to see the results so far.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7c925edab4f6a0a69390bc6bd1dc075a','adobe-indesign-m6-l2-lesson-1','8875d1b5f1089338ab8077acace2940b','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Creating Frames</h3><p>Creating Frames</p><p>Frames are an essential part of InDesign and they are what you will use to add all the elements onto your documents.&#160;Frames are basically containers for images, graphics, or text.&#160;You can also use frames as placeholders – which are basically empty containers.&#160;You can use frames and placeholders to build your page layouts very easily.</p><p>There are many tools in InDesign that you can use to create frames.</p><p>Frame tool:&#160;The Frame tool is used to draw placeholder or empty frames for graphics.&#160;Depending on the type of graphic you want to add, you can choose from the Rectangle Frame Tool, Ellipse Frame Tool, or the Polygon Frame Tool.</p><p>Shape tool:&#160;You can use the shape tool to draw unassigned frames, which are basically frames that are also graphic elements.&#160;One way you can use this is as a color box behind the text to improve readability.&#160;You can select either the Rectangle Tool, Ellipse Tool, or the Polygon Tool to draw different shapes.&#160;Shape tools are versatile because you can also add images and text to the shape.</p><p>Type tool:&#160;The Type tool is used to add text to your document.&#160;You can use the text tool to directly add text to the document, or you can create placeholder text frames to build a layout and then add content later.</p><p>Let’s start by using the Frame tool to create a frame in InDesign. First, select the Frame tool from the Toolbox. If you click and hold down the Frame Tool icon, you can see the different types of frames that you can create. For now, let’s just select the Rectangle Frame tool. All you have to do is click and drag to define the frame. That’s it! Let’s say that you know the size of the image that you are going to use or want to use in your document. You can also define the dimensions of the frame. With the Frame tool selected, just click anywhere in the document. You will see a popup where you can define the dimensions of the frame. Here, you can see that the default unit is millimeters, but if you want to set your dimensions using another unit, you can do that as well. Just enter the unit after you enter the number. For example, if you want to add an image that is 1.5 inches by 1.5 inches, just type 1.5in in both these fields. You’ll see that InDesign automatically converts the measurements into millimeters. Now click&#160;OK. Here’s the new frame. To move the frame, switch to the Selection tool and drag the frame to where you want to place it on the document.</p><p>Now, if you’re not sure if you want to add text or a graphic or even just a shape with color fill and stroke, you can create unassigned frames using the shape tools. Let’s select the Rectangle tool from the Toolbox. If you click and hold this icon, you can see the other shape options as well. Click and drag to draw a shape. You’ll see that the rectangle shape looks different from the frame because it doesn’t have the X mark inside. Also, if you switch to the Preview mode, you can see that the Frames that we added don’t show up because they were just placeholders, but the rectangle shape appears here with a black border. This is because when you draw a shape, it takes the default color fill and stroke settings. You can easily change this from the Properties panel. To remove the stroke, just change the stroke value to 0. Let’s add a fill color to this box. Click the Fill tile in the Properties panel and select a swatch.</p><p>Next, let’s add a text frame. Select the Type tool. Same as before, click and drag to draw a text frame. Switch to the Selection tool. You can tell this is a text frame by this icon on the frame. If you are creating a layout and don’t want to add text immediately, you can also add placeholder text to this text frame. Just click&#160;Type&#160;and select&#160;Fill with Placeholder Text.</p><p>This is how you can create different types of frames using the various tools in InDesign.</p></section><section><h3>Placing Images in Frames</h3><p>Placing Images in Frames</p><p>You have already learned how to add images to your document in an earlier module.&#160;Another way of adding images to your document is by placing them into frames.</p><p>In InDesign, you can create different page layouts using placeholder frames for graphics and text, and then add your images and content to it later. This is very useful when you need to visualize where different elements can be placed in your document. In this document, I have already created a few text and graphic frames as placeholders. Let’s see how you can place images into these frames.</p><p>First, use the selection tool to select the frame. Then, click the&#160;File&#160;menu and click&#160;Place. Select the image that you want to add to the document and click&#160;Open. The image will be placed in the frame at its full size. This means that if the size of your image and frame are not the same, parts of your image may be hidden. &#160;In the same way, if the image is smaller than the frame, it won’t fill the frame completely. You’ll learn more about this later in the course.</p><p>To add an image to another frame in the document, make sure you select that frame first, or else you will be replacing the image in the frame that is currently selected. If you have multiple images to add to a document, you can also select multiple images to place at once. Let’s see how you do this.</p><p>This time let’s use another way to place images, that is by clicking the&#160;Import File&#160;button in the Properties panel. Here, press and hold down the&#160;Shift&#160;key and select all the images you want to add, and then click&#160;Open. You will see that multiple images are loaded and available to be placed. The image that you see in this preview here is the one that will be placed first. Click in the frame and the image will be placed into it. Do this for the remaining image as well.</p><p>This is how you can place images into frames in your InDesign documents.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('172fd27c0fcedf5f43850753a8c7518e','adobe-indesign-m6-l3-lesson-2','8875d1b5f1089338ab8077acace2940b','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Adding Text</h3><p>Adding Text</p><p>There are a variety of ways in which you can add text to your InDesign documents.&#160;You can use the Type tool to create text frames and type your text directly in your document.&#160;You can then use the Properties panel to customize the appearance of the text by adjusting the font type, font size, color, and other settings.</p><p>There are other ways in which you can add text to your documents.&#160;You can easily copy and paste text from other word-processing programs as well as from other InDesign documents.&#160;You can also drag and drop text from these sources.</p><p>If you are working with large amounts of content, you can use the Place command to easily import text from other documents into your InDesign document.&#160;Depending on which application you are importing the text from, you may also be able to maintain the styles and formatting from the source document, which is very convenient.&#160;So, for example, if you have a well-formatted Word document with styles, colors and fonts applied, you can import the Word document into InDesign and all the styles will also be copied.</p><p>Let’s see how you can use all of these type tools to add text to your documents.</p><p>Adding Text Using Type Tool</p><p>First, let’s zoom in so you can see the document clearly. Select the&#160;Type&#160;tool and click and drag to create a text frame. You can now enter text in this frame. Once you have entered the text, you can position this text correctly on your document by switching to the Selection Tool and dragging the text frame to the right location.</p><p>InDesign has Smart Guides enabled by default, so you should see guides that will help you align the text box to other elements on your document. You can resize the text box using the handles that you can see all around the edge of the frame.</p><p>If you see a plus sign at the corner of the frame, it means that the frame is too small and that there is some text that doesn’t fit and is hidden. This is called&#160;Overset text. Drag the corner to make the frame larger so it shows all the text.</p><p>Now, you can use the Properties panel to format the text. To do this, you first need to select the text. Double-click the text box to select it and then select all the text. To change the font size, click the Font Size drop-down and select a size. You can also directly enter the point value in this field. You can change the color of this text by clicking the Fill icon and selecting a color. You can also choose to add a stroke around the text.</p><p>Next, you can choose one of many available fonts here. You can see a preview of each of the fonts, which makes choosing a font very easy. You can also roll your cursor over each of the fonts to see a quick preview of the font in your document.</p><p>So, this is how you can easily add text to your document using the Type tool.</p><p>Importing Text</p><p>Let’s see how you can paste, copy or import text into your InDesign document from external sources like Microsoft Office, a plain text file, or other InDesign documents. You can use the Place command to import content from an external document. If you already have a text frame defined, you can select it. If not, you can also directly click the File menu and select Place. Navigate to the document that you want to import and select it. Before you click Open, on a Mac, click the&#160;Options&#160;button and select&#160;Show Import Options. On Windows, this should be directly visible. Then, click the&#160;Open&#160;button. You will see a popup that allows you to specify what elements of the document you want to import, for example, do you want to include the table of contents, footnotes, etc. You can also specify if you want to keep the formatting of the document or clear it all and copy the content as plain text. For now, let’s leave all of this at their default settings and click&#160;OK.</p><p>If you started off by selecting a text frame, all the text would have been added to the frame. Since we didn’t do that, you can see that the text is loaded onto the cursor. You can either just click anywhere in the document and InDesign will create a frame automatically, or you can click and drag to define a text frame. All of the text will be placed in the frame.</p><p>Another easy way to import text is to simply drag and drop or copy and paste the text into the InDesign document. Now let’s say you want to copy text from another InDesign document into this document. Let’s change the view to see both documents side by side. Click the Arrange Documents icon at the top and select this view. Now, you can select the text from one document, and just drag it into the other document.</p><p>These are all the different ways in which you can import text into an InDesign document.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('96053072bbecd13a363837b4f1f25e4f','adobe-indesign-m6-l4-lesson-3','8875d1b5f1089338ab8077acace2940b','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Adjust Character Settings</h3><p>Adjust Character Settings</p><p>Character and Paragraph Formatting</p><p>There are two different types of text formatting that you can apply; character formatting and paragraph formatting.&#160;If you’ve used any other word-processing application, chances are that you have used this formatting on your content.</p><p>Character formatting&#160;is applied to specific characters or text that you select.&#160;This includes changes to font and font size, etc.</p><p>Paragraph formatting&#160;is applied to entire paragraphs or blocks of text and involves changes to the alignment of the text, indentation, etc.</p><p>You can apply both character and paragraph formatting from the Properties panel.</p><p>Character Settings</p><p>You can access the&#160;Character&#160;settings in the Properties panel.&#160;You can also select the&#160;Type&#160;menu and select&#160;Character&#160;to open the&#160;Character panel&#160;that you can then dock onto your workspace.</p><p>You already know how to adjust the font size and select a font from the&#160;Fonts&#160;drop-down list.&#160;Apart from the list of fonts you see, you also have the option to explore the huge library of Adobe Fonts and instantly download them.&#160;You can find this by clicking the&#160;Find More&#160;tab at the top, searching for a font you like, and clicking the cloud icon at the right to download the font.</p><p>Let’s take a look at the other advanced settings you see here, starting with&#160;Leading.</p><p>This option controls the spacing between the lines of type.&#160;The default selection here is&#160;Auto.&#160;This is usually fine, but depending on the font you are using, you may need to adjust this value.&#160;When you adjust this value, think about if your text looks natural and easily readable, and always consider the size of your document.&#160;For example, is it going to be printed as a large poster or banner, or a smaller card or postcard?&#160;Visualize what the final product will look like when you adjust these values.</p><p>Next, let’s move on to&#160;Kerning.&#160;Kerning adjusts the spacing between any&#160;two characters.&#160;To set a kerning value, you need to click between the two characters where you want to adjust the spacing, or else the option will be greyed out.</p><p>Right next to Kerning, you will see an option to adjust the&#160;Tracking.&#160;Tracking also controls the spacing between the characters.&#160;Don’t confuse tracking with kerning.&#160;While kerning controls the spacing between just two characters, you can use tracking to control the spacing between a whole range of characters.&#160;You can either select from one of the preset values available in the drop-down list or you can enter your own custom value directly into the field.</p><p>There are many ways you can modify the tracking value to create a bigger visual impact.&#160;For example, you can select a specific word and adjust the tracking value for just that word.</p><p>Next, you can scale the type either vertically or horizontally using the&#160;Vertical and Horizontal Scale&#160;options.</p><p>You can select specific characters that you want to scale, or you can scale the entire text as well.&#160;This is usually not recommended as it distorts the font and can look odd.</p><p>Next comes the&#160;Baseline Shift&#160;option.&#160;This option allows you to stylize the text by selecting and moving specific characters above or below the baseline of the font.&#160;Some places this setting can be useful is if you want to type fractions, subscripts, or superscripts.</p><p>Next, let’s talk about the&#160;Skew&#160;setting.&#160;You can adjust this angle to add a slant to the text.&#160;Positive values will slant the text to the right, and negative values will slant text to the left.&#160;It is useful to note that if you want to italicize your text, it is better to choose that from the font settings rather than adjusting the skew, as it doesn’t produce true italic characters.</p><p>Finally, at the bottom, you can see a row of settings that you can use to capitalize text, change text to superscript or subscript text, underline or cross out text.&#160;And finally, you can also choose a different language from this panel as well.</p></section><section><h3>Adjust Paragraph Settings</h3><p>Adjust Paragraph Settings</p><p>Just as you can adjust advanced character settings, you can also adjust the paragraph settings from the&#160;Properties&#160;panel.&#160;You can also open the&#160;Paragraph&#160;panel from the&#160;Type&#160;menu.&#160;Let’s see how you can use these settings.</p><p>Click each hotspot on the Paragraph section to learn more.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>InDesign Paragraph settings</p><p>The hotspot points on the image are as follows:</p><p>Alignment and justification options</p><p>These work like the options you would see in Word or other similar tools. You can select how you want your text to be aligned, and you can select how you want the spacing between the words of a paragraph.</p><p>Indent options</p><p>These options allow you to add space on the left or right side of the entire paragraph, or just before the first line or after the last line of the paragraph.</p><p>Spacing around and between paragraphs</p><p>And next is another commonly used setting, which is adding a space before or after a paragraph, or between two paragraphs. To use either of these tools, just select the paragraphs where you want to add the spacing and adjust the values.</p><p>Drop cap</p><p>In a lot of published work like books, you will notice that a large capital letter is used at the beginning of a paragraph as a decorative element. This is a drop cap. To set the drop cap, just click on the paragraph you want to add the drop cap. In the Drop Cap Number of Lines field, you can specify the number of lines that you want the drop cap to span over. If instead of just the first letter, you want to drop cap more characters, you can set that number in the Drop Cap One or More Characters field.</p><p>Borders and shading</p><p>Next, you’ll see options that allow you to add a border around one or more paragraphs, as well as fill in color into the background of the text box. You can use this option to highlight text or make certain paragraphs more prominent.</p><p>Hyphenate checkbox</p><p>This is used to break longer words i<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8793211314e926604a83f9cfecd9cc91','adobe-indesign-m6-l5-lesson-4','8875d1b5f1089338ab8077acace2940b','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Convert Text to Graphics</h3><p>Convert Text to Graphics</p><p>InDesign gives you the ability to convert your text into paths or outlines that are shapes with points that you can manipulate.&#160;You can also place images into these outlines to convert your text into stylized graphics.</p><p>For example, let’s say you type out some text onto your document like this.</p><p>All you need to do is select the text frame, click the&#160;Type&#160;menu and select&#160;Create Outlines.</p><p>The selected text will be converted into a path outline with the default black fill.&#160;You can change this to transparent.</p><p>Now, you can easily manipulate the points to transform your text.&#160;You can also use the&#160;File &gt; Place&#160;command to place an image into the outline like this.</p></section><section><h3>Threading Text</h3><p>Threading Text</p><p>When you work in InDesign, you may need to import large sections or even multiple pages of text.&#160;Sometimes, you need this text to go from one page to the next.&#160;In other cases, the text may not fit in one text frame and you may need to move it to another area.&#160;Instead of having to cut and paste the content into multiple text boxes, InDesign allows you to flow text between frames using a feature called&#160;Threading.</p><p>You learned earlier that text that doesn’t fit in a frame is indicated by the plus sign and is called the&#160;Overset text.&#160;You can connect two text frames by taking the overset text that doesn’t fit and flowing it into the next frame.</p><p>Select the&#160;Selection&#160;tool and click the text frame in this document. The red plus sign here indicates that all the text doesn’t fit in this frame. If you look closely, you will see another box in the top left corner of the frame. This is called the&#160;Inport&#160;of the frame, and the plus sign is called the&#160;Outport&#160;of the frame. You can thread different text frames together by connecting the outport of one frame to the inport of the next one.</p><p>To do this, click the red plus. When you move the pointer away, you will see that the overset text is now loaded on to the cursor, and the red plus is no longer present. You can now click anywhere on the document and InDesign will automatically create a text frame with the overset text. Alternatively, you can click and drag out a frame as well. Let’s do that. Now, the overset text has been added to the new frame.</p><p>Here, you can see that the inport of this new frame has an arrow in it, which indicates that text is coming into this frame from somewhere else. If you go back and select the first text frame, you will see a similar arrow in the outport of this frame, which means that text is flowing out from this frame into the next one.</p><p>When you have multiple text boxes on a page or in a document, it can be difficult to track where the text is coming from. You can see this by clicking the&#160;View&#160;menu, selecting&#160;Extras, and clicking&#160;Show Text Threads. You should now be able to see how the text flows by these connecting lines. This threaded text is called a&#160;story&#160;in InDesign.</p><p>If you resize any of the text frames, the text gets rearranged as well. A great part of this feature is that because all the frames are threaded, even if you delete one of these text frames, the text isn’t deleted. Instead, it is pulled into the remaining text frames and shown as overset text.</p><p>As you can see, threading is a great way to manage the text in your documents.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a4ee41b02e9dae442ffeee6a19b2db44','adobe-indesign-m6-l6-lesson-5','8875d1b5f1089338ab8077acace2940b','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Adding Special Characters</h3><p>Adding Special Characters</p><p>In InDesign, you can easily add accented characters, symbols, and glyphs to your documents.&#160;You can use these special characters in many places, like if you are writing text in Spanish or French, or if you are writing academic content and need to use scientific symbols.</p><p>You can add special characters using the Glyphs panel in InDesign.&#160;To open this panel, just click the&#160;Window&#160;menu, select&#160;Type &amp; Tables, and click&#160;Glyphs.</p><p>You can also open it from the Type menu by clicking&#160;Type&#160;and selecting&#160;Glyph.</p><p>The panel will show you the different glyphs that are available for the font you are using.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>InDesign Glyphs panel</p><p>The hotspot points on the image are as follows:</p><p>Recently Used</p><p>Any glyphs that you used recently will appear in this section.</p><p>Search bar</p><p>You can use this box to search for glyphs by name or Unicode value.</p><p>Subset Filter</p><p>Use the&#160;Show&#160;drop-down list to filter glyphs by different subsets, like Math Symbols or Currency.</p><p>Glyphs</p><p>This section shows you all the glyphs for the selected font. You can scroll down to select the glyph you want to use.</p><p>Font</p><p>Use these drop-down lists to change the font type and style. Different fonts can have different sets of glyphs.</p><p>Zoom icons</p><p>Use the&#160;Zoom In&#160;and&#160;Zoom Out&#160;icons at the bottom of the Glyphs panel to take a closer look at the glyphs and characters.</p><p>You can roll over each of the characters listed here to see its details like the name, glyph ID, etc. The forward arrow next to some characters indicates that it has more than 5 alternates.&#160;You can see these by clicking and holding the mouse button down.&#160;You can then roll over the alternates and release the mouse button to choose them.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ec09da6322397dcd7a769024e58830be','adobe-indesign-m6-l7-summary','8875d1b5f1089338ab8077acace2940b','Summary','text',12,'<h2>Summary</h2><section><h3>Summary</h3><p>Summary</p><p>Great Work!&#160;You have successfully completed this module&#160;on Creating and Modifying Visual Elements Part I!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Used core tools and features to lay out visual elements.</p><p>Used a variety of type tools to add typography to a design.</p><p>Used appropriate character and paragraph settings in a design.</p><p>Converted text to graphics and managed text flow across multiple text areas.</p><p>Used tools to add special characters or content.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8650e4272346fb41b234f07557aca2d9','adobe-indesign-m6-l8-project','8875d1b5f1089338ab8077acace2940b','Project','text',12,'<h2>Project</h2><section><h3>Module 6 Project</h3><p>Project</p><p>In this assignment, you will apply all that you have learned about creating frames and text using various tools to lay out the visual elements of a document. You will need to use InDesign to perform these tasks. Take screenshots after completing each step and save them as image files or add them to a Word/PPT document.</p><p>Create a new InDesign document and create three different types of frames; a graphics frame, an unassigned frame, and a text frame. Add an image to the graphics frame.&#160;(Take a screenshot once the task is complete.)</p><p>Next, use the Type tool to add text to the text frame that you created. Create a Word document with some text and import it into your InDesign document.&#160;(Take a screenshot once the task is complete.)</p><p>Change the character and paragraph settings to format the text in your InDesign document.&#160;(Take a screenshot once the task is complete.)</p><p>Import a large piece of content into an InDesign document in a way that you have overset text in your text frame. Now, apply what you learned about threading text to spread the text across multiple threaded text frames.&#160;(Take a screenshot showing the text threads once the task is complete.)</p><p>Add a few special characters to your content using the Glyphs panel.&#160;(Take a screenshot once the task is complete.)</p><p>Review the rubric below to see how you will be graded.</p><p>Creating and Modifying Visual Elements Part I</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Creating frames</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Using Type tools to add typography</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately with attention to detail and meeting all requirements.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Use appropriate character and paragraph settings</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Manage text flow</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Add special characters</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8b5ab289725018f8655bf083b002bb11','adobe-indesign-m6-l9-module-6-quiz','8875d1b5f1089338ab8077acace2940b','Module 6 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Visual Elements Part 1. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('c10ec528dd2a54e974ad6745b46df7f6','adobe-indesign-module-7','06e4e2edaf3c4cc38b4d0a152e3ee09a','Module 7: Visual Elements Part 2',7) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1dec0ceb70b1766a7b79c7fed0bbc6d5','adobe-indesign-m7-l1-into','c10ec528dd2a54e974ad6745b46df7f6','Into','text',12,'<h2>Into</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hey there! This is the intro video for the module on Creating and Modifying Visual Elements Part II. In the last module, you learned how to create different types of frames in InDesign. You also learned all about adding and editing the text in InDesign. Let’s keep the creativity ball rolling in this module as well! In this module, you will learn all about making and modifying selections, as well as how you can modify frames and transform them in InDesign.</p><p>When you are working with so many different elements on a document, tools that allow you to select these objects and modify them are essential. You’ve already learned all about using frames to add all types of objects to your document. We’ll now look deeper into how you can transform individual frames and the content within frames to enhance your designs.</p><p>Module Description</p><p>When you are designing documents for digital or print publication, just inserting objects onto your document is not enough.&#160;You need a way to select different objects, modify, refine, and transform them in different ways to make your designs creative and unique.&#160;In this module, students will learn how to make and refine selections using various tools and methods.&#160;They will also learn how to rotate, flip and transform different elements of their documents.</p><p>Objectives</p><p>In this module, students will:</p><p>Make selections using a variety of tools.</p><p>Modify and refine selections using various methods.</p><p>Modify frames and frame content.</p><p>Rotate, flip, and transform individual frames or content.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6b7115baa211530c4daeffea84d77daf','adobe-indesign-m7-l2-lesson-1','c10ec528dd2a54e974ad6745b46df7f6','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Making Selections in InDesign</h3><p>Making Selections in InDesign</p><p>InDesign gives you a few different tools that you can use to make selections in your document.&#160;But first, let’s understand the need for making selections.&#160;Here are a few basic definitions:</p><p>Object:&#160;In InDesign, an object is any element on your document that can be printed.&#160;So, this can be a graphic, a shape, an image, text, etc.</p><p>Frame or path:&#160;A frame or a path is a container or shape that holds text, graphics, or images.&#160;When you insert a graphic into a frame, it doesn’t merge into the frame; the graphic just sits inside the frame.</p><p>Bounding box:&#160;The vertical and horizontal edges of an object is called a bounding box.&#160;It is basically a rectangle with eight handles all around the edge that can be used to transform the object.</p><p>In order to transform an object, you need to first&#160;select&#160;it.&#160;There are two selection tools available in InDesign.&#160;You can find them right at the top of the Toolbox – the&#160;Selection tool&#160;and the&#160;Direct Selection tool.</p><p>The names may sound similar, but they both work differently.&#160;Let’s see what each tool does.</p><p>Selection tool:&#160;You can use this tool to select text and graphics frames.&#160;If you use the Selection tool and click an object, it will first select the frame of the object.</p><p>If you click and hold an object using this tool, you can move the object.</p><p>To work with the bounding box of the object or the text, you need to double click on the object or use the content grabber.&#160;You’ll learn about this a little later.</p><p>Direct Selection tool:&#160;This tool allows you to directly select the contents of a frame like an image or graphic that you placed inside a frame.</p><p>You can also use this tool to work with objects like paths or outlines that you may have created.&#160;This tool allows you to change the shape of graphics and text boxes as well.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c9b3fab8f042106af03368fa357e867a','adobe-indesign-m7-l3-lesson-2','c10ec528dd2a54e974ad6745b46df7f6','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Refining Selections</h3><p>Refining Selections</p><p>Once you select objects on your document, there are many different ways in which you can modify and refine your selections.</p><p>If you need to select multiple objects on your document, just select the first object, press and hold down the&#160;Shift&#160;key on your keyboard, and click on all the other objects you need to select.&#160;You can then release the&#160;Shift&#160;key and move all the objects, apply effects or any other formatting changes that you want to apply globally.</p><p>If you want to select or deselect all the objects on your document, you can use the&#160;Edit&#160;menu to easily do this.</p><p>Just click&#160;Select All&#160;to select all the objects on the document.&#160;To deselect all the objects, click&#160;Deselect All.</p><p>Another alternative is to use the&#160;Select&#160;sub-menu in the&#160;Object&#160;menu.&#160;This gives you an array of options to select different elements on your document.</p><p>All of these options may not be active, depending on the type of object you’re working with and also depends on the position of your pointer or on how the items are listed in your Layers panel.&#160;Why is this useful?&#160;If you are working on a large document with multiple objects, chances are that you will be zoomed in while working on your document.&#160;In such cases, it is tedious to zoom out and individually select each item.&#160;Instead, you can use the following options:</p><p>First Object Above:&#160;Use this to select the object at the top of the stack.</p><p>Next Object Above:&#160;This selects the object that is just above the current object.</p><p>Next Object Below:&#160;Use this to select the object just below the current object.</p><p>Last Object Below:&#160;This option selects the object at the bottom of the stack.</p><p>Content:&#160;You can use this to select the content a frame.&#160;For example, if you have a graphics frame to which you have added text, you can use this option to just select the text.&#160;Or, if you have grouped different objects together and only want to select the content from the group, you can use this option.</p><p>Container:&#160;This option will select the frame enclosing the selected object.&#160;If you have selected an object that is in a group, using this option will select the group that contains the object.</p><p>Previous Object/Next Object:&#160;These options are used with grouped objects.&#160;You can use them to select the next or previous object in the group.&#160;If you are using this with ungrouped objects, it will select the next or previous object on the spread.</p><p>When you have a large number of objects grouped together, you can&#160;Shift-click&#160;to skip them by five.&#160;You can also use the shortcuts&#160;Ctrl-click (Windows)&#160;or&#160;Command-click (Mac OS)&#160;to select the first or last object in a group.</p><p>Note:&#160;Practice using the keyboards shortcuts that you see in the&#160;Select&#160;sub-menu.&#160;Once you commit them to memory, they make selecting objects quick and easy.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('36c4423ec31b9ee6111ca1b2a2634d92','adobe-indesign-m7-l4-lesson-3','c10ec528dd2a54e974ad6745b46df7f6','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Modifying Frames and Frame Content</h3><p>Modifying Frames and Frame Content</p><p>There are many ways in which you can modify frames and the content within frames.&#160;Earlier in this course, you learned how to place images into frames.&#160;When you place images into frames, they are always added at 100% of their size by default.&#160;Many times, you may want to resize or reposition the image inside the frame.&#160;You can easily do this using the selection tools in InDesign.</p><p>There are some simple ways in which you can modify frames in InDesign.&#160;When you use the&#160;Selection&#160;tool and click any frame on the document, you will see the handles around the frame, and you will also see a yellow box on the left of the frame.&#160;You can use this box to adjust the corners of the frame.</p><p>To adjust the corners of the frame, click the yellow box once.&#160;It will move to the corner of the frame.&#160;You can now drag it along the edge of the shape to create a curved corner.</p><p>If you want only one corner to be curved, you can do that as well.&#160;When you select the image, you will see the&#160;Appearance&#160;section in the&#160;Properties&#160;panel.&#160;Here, you can click the&#160;Corner&#160;link.&#160;The&#160;Corner Options&#160;popup appears.</p><p>In this popup, you can adjust the values of all four corners proportionally or individually by either selecting or deselecting the link icon in the center.&#160;Select the&#160;Preview&#160;checkbox so you can see a preview of the changes you are making.&#160;You can use the&#160;Corner Shape&#160;drop-down to select a shape, and you can adjust the values in the&#160;Corner Size&#160;box to change the size of the corner.</p><p>When you use the&#160;Selection&#160;tool and just roll the cursor over an image in the document, you will see a donut-shaped icon at the center of the image.&#160;This is the&#160;Content Grabber.</p><p>You know that when you use the&#160;Selection&#160;tool and click and drag the image, the entire frame is moved.&#160;You can use the Content Grabber to move and edit just the image inside the frame.</p><p>First, let’s click the&#160;Selection&#160;tool, and click this image. Usually, you will see a donut-shaped circle in the center where you can see this hand icon. This is called the&#160;Content Grabber. Right now, the frame of the object is selected. So, if I click anywhere except on the content grabber and drag this image, both the image and the frame are moving.</p><p>In InDesign, you can resize just the frame, just the image inside the frame, or both the image and the frame. Let’s go over each one by one.</p><p>To resize just the frame, just use the Selection tool and click and drag any of the handles that you see around the frame. Only the frame is resized, and the image remains in its original position and size.</p><p>To resize or move only the image and keep the frame the same size, let’s use the Content Grabber. Click it and you will see a dark orange outline appearing here. These are the actual edges of the image. You can click the content grabber and drag the image around the frame to reposition it. Once you see this outline, you can also click and drag any of the handles to resize and then reposition the image inside the frame as well. If you want to resize the image proportionally inside the frame, just press and hold the Shift key and then drag out the image using the handles.</p><p>If you want to resize both the image and the frame proportionally, you can use the Auto-Fit option. With the frame selected, let’s go over to the Properties panel and scroll down to the Frame Fitting section. Here, you will see an Auto-Fit checkbox. Let’s select this. Now, if you try to resize the frame, you will see that both the image and the frame are resized. If you want to resize both image and frame proportionally, just click Shift and drag the handles.</p><p>There are a few other options you can use to determine how images fit inside frames. In the Frame Fitting section, you can see a number of icons. You can find these same functions from the&#160;Object&#160;menu by selecting&#160;Fitting. The first icon you see here is&#160;Fill Frame Proportionally. This means that the image will fill the frame as much as it has to so that you don’t see any gaps where the frame is empty, even if that means parts of the image get cropped out. So, if I select this icon, this is what the image looks like.</p><p>The next option is to&#160;Fit Content Proportionally. This option ensures that the entire image fits inside the frame proportionally, even if that means that some parts of the frame are left blank. First, make sure you have the frame selected, and click the icon. As you can see, there are a few gaps in the frame, but the image completely fits inside the frame.</p><p>The next icon is used to&#160;Fit Content to Frame. This option resizes the dimensions of the image to make all edges of the image align to the edges of the frame. Normally you would only use this option if you were certain that your image and frame had the same proportions, otherwise your image would get distorted, like this.</p><p>The next icon is similar to the previous, except that it will resize the frame to fit the graphic. This is used a lot when you work with text frames and want to resize the frame so that it wraps exactly to the amount of text in the frame.</p><p>Next comes the&#160;Center Content&#160;option. You can use this option to center the image in the frame. And finally, the last option is the latest addition to InDesign, the&#160;Content-Aware Fit&#160;option. This option enables InDesign to automatically reposition your image in the frame based on the context and focal point.</p><p>So, these are the different ways in which you can modify your frames and frame content.</p></section><section><h3>Wrapping Text around Objects</h3><p>Wrapping Text around Objects</p><p>When you leaf through magazines and really look at the layout of the different elements on the pages, you will notice how text is placed very creatively in conjunction with images.&#160;Sometimes, images are cropped in creative shapes with text neatly aligned along all the edges.&#160;In other instances, you will see quotes and text boxes in the middle of other text columns.</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>InDesign can help you wrap text around simple objects and shapes on your document to customize h<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8be76643d8f443577a148cd82095ae09','adobe-indesign-m7-l5-lesson-4','c10ec528dd2a54e974ad6745b46df7f6','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Transforming Objects</h3><p>Transforming Objects</p><p>InDesign gives you many ways to modify an object’s shape, size, orientation and angle in the document.&#160;You can scale, rotate, shear, and flip frames.&#160;Let’s go over the different ways in which you can do this.</p><p>You can find these all of the transformation settings in the&#160;Transform&#160;panel.&#160;To open this panel, click the&#160;Window&#160;menu, select&#160;Object &amp; Layout&#160;and click&#160;Transform.</p><p>You can find the same settings in the&#160;Properties&#160;panel when you select an image.</p><p>A third way of accessing these functions is using the Toolbox.&#160;You will see four different functions nested together in the Toolbox; the&#160;Rotate Tool, the&#160;Scale Tool, the&#160;Shear Tool, and the tool that can do all these functions, the&#160;Free Transform Tool.</p><p>You can use any of the above methods to transform the frames, depending on what you are more comfortable with.</p><p>Let’s quickly go over the different settings in the&#160;Transform&#160;section in the&#160;Properties&#160;panel.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>InDesign Properties panel, Transform section</p><p>The hotspot points on the image are as follows:</p><p>Reference Point</p><p>This box represents the image, and each point is a point on the image. This grid is used to set a focal or central point for any of the transformations you may apply to the image. So, if the central point is selected and you rotate the image, it will be rotated around the center of the image.</p><p>W &amp; H</p><p>These denote the width and height of the image. You can use the link icon to constrain the proportions while you resize the image.</p><p>X &amp; Y</p><p>These denote the position of the image on the document.</p><p>Rotation Angle</p><p>This is the angle by which you want to rotate the image. The image will rotate around the point selected in the Reference Point grid.</p><p>Scale X &amp; Y Percentage</p><p>Here, you can enter values by which you want to scale an image vertically or horizontally. You can also use the link icon here to constrain the proportions while scaling the image.</p><p>Shear X Angle</p><p>This feature skews or slants the object horizontally to the left or right by an angle. This gives the object an appearance of having depth or perspective.</p><p>Flip Horizontally &amp; Vertically</p><p>You can use these icons to flip the image horizontally or vertically. The image will flip along the horizontal or vertical axis of the point selected in the Reference Point grid.</p><p>Rotate 90&#176; Clockwise &amp; Anticlockwise</p><p>You can use these icons to rotate the image by 90&#176; clockwise or anticlockwise. The image will rotate around the point selected in the Reference Point grid.</p></section><section><h3>How to Transform Objects</h3><p>How to Transform Objects</p><p>Let’s see how you can apply transformations to the different objects in this document. For this example, we’ll be using the&#160;Transform&#160;section in the&#160;Properties&#160;panel, but you can also use the tools from the Toolbox or the Transform panel to achieve the same results.</p><p>First, let’s use the Selection tool and select this image. Let’s select the center of this image as the reference point so that any transformations we apply will be around the center of the image. Let’s flip this image vertically by clicking this icon. If you had selected another point here and flipped the image, this is how it would have flipped. That’s why it is always important to first select a reference point before you apply transformations.</p><p>Next, let’s rotate this frame. Now, you can rotate frames in many ways. When you click a frame using the Selection tool, and then roll over the corner of the image, you will see the cursor changing to this bent double arrow. You can now click to select this corner of the frame and rotate it in any direction you want. You will see a helpful tooltip showing you the rotation angle as you turn the object. When you are dragging the object, if you press and hold down the Shift key, the object will rotate by an angle of 45&#176;. Alternatively, you can also select an angle from this drop-down list or enter an angle directly into the text box. To rotate by an angle of 90&#176;, you can use these icons.</p><p>Now, let’s look at another document. I have an image of a screen here, and I have another image that I want to place over this to look like this image is appearing on the screen. Here, I can use the Shear angle setting to slant the image and give it depth perception.</p><p>When you are working with multiple objects on a document and applying transformations, it is easy to click on the wrong object by mistake and move something unintentionally. To avoid this, you lock the position of objects in the document. Just select one or more objects that you want to lock, click the&#160;Object&#160;menu, and select&#160;Lock. Locked objects will have this lock icon on the frame, and you will no longer be able to select those objects. To unlock the objects, just click the&#160;Object&#160;menu and click&#160;Unlock All on Spread. This will unlock all the objects. If you only want to unlock one object, just click the lock icon on its frame and it will be unlocked.</p><p>This is how you can apply different transformations to objects in InDesign.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4ffda20b55e8d6a7d1a0e63b1fbe70f7','adobe-indesign-m7-l6-module-7-summary','c10ec528dd2a54e974ad6745b46df7f6','Module 7 Summary','text',12,'<h2>Module 7 Summary</h2><section><h3>Summary</h3><p>Summary</p><p>Great Work!&#160;You have successfully completed this module on Creating and Modifying Visual Elements Part II!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Made selections using a variety of tools.</p><p>Modified and refined selections using various methods.</p><p>Modified frames and frame content.</p><p>Rotated, flipped, and transformed individual frames or content.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0739cc006629880db74e6d1e21db7e3c','adobe-indesign-m7-l7-project','c10ec528dd2a54e974ad6745b46df7f6','Project','text',12,'<h2>Project</h2><section><h3>Module 7 Project</h3><p>4100</p><p>Adobe InDesign</p><p>Creating and Modifying Visual Elements Part II - Project</p><p>Project</p><p>In this assignment, you will apply all that you have learned about using selection tools, modifying and transforming frames to manage the design elements of a document. You will need to use InDesign to perform these tasks. Take screenshots after completing each step and save them as image files or add them to a Word/PPT document.</p><p>Open an InDesign document and place an image in the document. Now, use the Selection tool and the Direct Selection tool to select the objects on the document. Take screenshots and provide a short explanation of how the two tools are different.</p><p>Add multiple objects to your document and use the keyboard shortcuts to select all the objects on the document.&#160;(Take a screenshot once the task is complete.)</p><p>Make modifications to the corners of an image in your document by giving all four corners a different shape and size. Create a large text frame with placeholder text and wrap the text around the image on your document.&#160;(Take a screenshot once the task is complete.)</p><p>Apply three different transformations to objects on your document.&#160;(Take a screenshot once the task is complete and label them to indicate what transformations were applied. You can take before and after screenshots to show what you changed.)</p><p>Review the rubric below to see how you will be graded.</p><p>Creating and Modifying Visual Elements Part II</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Make selections</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Modify and refine selections</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately with attention to detail and meeting all requirements.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Modify frames and frame content</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Apply transformations</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('47352bc3719030ff8daf0e08d272e9e2','adobe-indesign-m7-l8-module-7-quiz','c10ec528dd2a54e974ad6745b46df7f6','Module 7 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Visual Elements Part 2. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,7,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('b24eaacdeb0176e406ee5c7c6a4386c0','adobe-indesign-module-8','06e4e2edaf3c4cc38b4d0a152e3ee09a','Module 8: Visual Elements Part 3',8) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('01e1f82b5582b6ffae48a273ca87207f','adobe-indesign-m8-l1-introduction-purpose-and-objectives','b24eaacdeb0176e406ee5c7c6a4386c0','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi and welcome to another module. This is the intro video on Creating and Modifying Visual Elements Part III. In the last few modules, you’ve been learning about different ways in which you can enhance the visual elements of your document. You’ve learned about using frames and text in creative ways. You’ve also learned how to manage selections and transform graphics in your documents. In this module, we’ll dive a little deeper into creative ways in which you can manipulate your document content; from repairing and auto-correction to applying effects and styles to change the appearance of elements on your document.</p><p>Module Description</p><p>InDesign is not just a layout program, it gives you many tools and features to manipulate, enhance, and modify the appearance of all of the elements on your documents.&#160;In this module, students will learn how to use different tools to repair project content.&#160;They will also learn how to adjust the appearance of objects and use the Story Editor to edit the text in a project.&#160;Finally, students will learn to modify the appearance of design elements using effects and styles.</p><p>Objectives</p><p>In this module, students will:</p><p>Use various tools and auto-correction methods to repair project content.</p><p>Use the Story Editor to edit the text within a project.</p><p>Use effects to modify images or frames.</p><p>Create, edit, and save object styles.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9ed68bf4619e84a631758478868e3b6e','adobe-indesign-m8-l2-lesson-1','b24eaacdeb0176e406ee5c7c6a4386c0','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Using Auto Correction and Rapair Methods</h3><p>Using Auto-Correction and Repair Methods</p><p>Working in InDesign is a creative and often lengthy process.&#160;There may be times when you complete a whole set of changes but are not happy with the results and want to revert to an earlier version.&#160;InDesign allows you to revert to up to several hundred of the most recent actions (depending on the RAM of your computer and the types of actions you performed).</p><p>This set of actions is discarded each time you save the document, close the document or exit from InDesign.</p><p>To undo the most recent changes that you made, just click the&#160;Edit&#160;menu and click&#160;Undo.&#160;If you want to redo an action, just click the&#160;Edit&#160;menu and click&#160;Redo.</p><p>You can also undo all the changes you made in a session since the last time that you saved the file.&#160;Just click the&#160;File&#160;menu and click&#160;Revert.</p><p>Spell Check &amp; Autocorrect Settings</p><p>Typos can be the bane of your existing, and it is an issue that is easily solved by making sure that your language and spell check settings are set correctly.&#160;In InDesign, you can start off by setting the global dictionary language that you want to use for all of your documents.&#160;This way, any spell checks that you will do will be in that language.&#160;You can always change this to other languages for specific documents if needed.</p><p>To set the dictionary for all your InDesign documents, first make sure you don’t have any documents open.&#160;If you do, the dictionary language will only be changed for that document.&#160;You need to open the Preferences window.&#160;On a Windows computer, click the&#160;Edit&#160;menu, select&#160;Preferences&#160;and click&#160;Dictionary.&#160;On a Mac, click&#160;InDesign, select&#160;Preferences&#160;and click&#160;Dictionary.&#160;You will see the Preference window with a list of different preferences that you can edit along the left of the window.</p><p>Here, you can choose the language you want from the&#160;Language&#160;drop-down.&#160;By default, InDesign uses the Hunspell dictionary for most languages to verify spellings.&#160;You can always add words to the dictionary so that it is customized for your needs.&#160;You can also create your own new dictionary, but we won’t go into those details in this module.</p><p>Next, select&#160;Spelling&#160;from the left menu.&#160;Here, you can see all the spelling settings.&#160;InDesign will indicate when it finds these errors in your document.</p><p>You can select&#160;Enable Dynamic Spelling&#160;as well.&#160;This setting enables InDesign to check your spelling as you type and indicates potentially misspelled words immediately.&#160;You can customize the colors for different types of spelling mistakes as well if that helps you easily identify them.</p><p>Now let’s explore the&#160;Autocorrect&#160;section.&#160;If you enable this option, InDesign will automatically correct common spelling mistakes.&#160;You can also select the&#160;Autocorrect Capitalization Errors&#160;checkbox to automatically fix capitalization errors.&#160;For example, if you type ‘united states’ instead of ‘United States’, InDesign will automatically capitalize this.</p><p>As you can see, there is already a default list of commonly misspelled words.&#160;You can also add other words that you may misspell that are not on the list.&#160;Just click the&#160;Add&#160;button and add the misspelled word and its correct spelling.</p><p>Running a Spell Check</p><p>When you are done working on your document, it is always a good idea to run a spell check to make sure all the content is spelled correctly.&#160;You can do a spell check for a specific range of text or for your whole document.&#160;To do this, just click the&#160;Edit&#160;menu, select&#160;Spelling&#160;and click&#160;Check Spelling.</p><p>The spell check begins, and you will see a&#160;Check Spelling&#160;popup with any spelling errors, suggestions for corrections that you can choose from, and an option to select a dictionary.&#160;In this example, we’ve added placeholder text, which is why it is showing up as an error.</p><p>Here, you can choose to correct the spelling, skip the word, or choose to ignore all instances of the word in the document.&#160;You can also add the word to your dictionary.&#160;You can click the&#160;Search&#160;drop down to list to specify where you want to run the spell check.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4de85f07cd4c31c754a93eeeef6b4570','adobe-indesign-m8-l3-lesson-2','b24eaacdeb0176e406ee5c7c6a4386c0','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Using the Story Editor</h3><p>Using the Story Editor</p><p>You learned earlier in the course that an individual text frame or a set of threaded text frames is called a&#160;story&#160;in InDesign.&#160;So far, you have only learned how to work with and edit the text in the layout view.&#160;If you are creating a one-page flyer or a document with less text on it, the layout view is just fine.&#160;But if you are working with multi-page documents, it can become tedious to keep scrolling through pages and dealing with text that may be wrapped around images or graphics.</p><p>There is another, easier way of editing text in InDesign, and that is using the&#160;Story Editor.&#160;The Story Editor will display all the text of a story in your document, including overset text.&#160;The Story Editor gives you a clean, basic window in which you can edit the text in your document without any distractions.&#160;It will also display the character and paragraph formatting, indicate where the overset text is present and will show track changes that have been made to the text.</p><p>If you have multiple different stories in a document, they will appear in separate Story Editor windows.&#160;You can also run spell checks, add special characters, and find and replace text using the editor.&#160;As you can see, it is very versatile!&#160;Let’s see how you can launch the Story Editor.</p><p>First, select the text frame or select multiple text frames if they are from different stories. Then, click the&#160;Edit&#160;menu and select&#160;Edit in Story Editor. The Story Editor is displayed. You can resize the window to see all the text clearly. You can also drag and dock the Story Editor onto your workspace. It will appear as a document tab. You can change the view to see both the document and Story Editor side by side, like this.</p><p>Here, you can see the styles applied to each paragraph of the text. The vertical ruler you see here is an indication of how much text is filling the frame. If you look down here, this red line indicates where the text is overset. You can make any edits you want here. You learned how to use the spell checker in the last lesson. You can apply that here to check the spelling and make edits simultaneously. You’ll see that as you make changes, they are immediately reflected in the layout as well.</p><p>You can customize some elements of how the Story Editor looks as well. With the Story Editor open, click the&#160;View&#160;menu and select&#160;Story Editor. You can show or hide the style name column, the depth ruler, expand or collapse footnotes, and show or hide paragraph break marks to indicate the start of new paragraphs. Once you are done, just close the Story Editor.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a62f0e31ebdf342c338d69d8882ed6c6','adobe-indesign-m8-l4-lesson-3','b24eaacdeb0176e406ee5c7c6a4386c0','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Using Effects to Modify Objects</h3><p>Using Effects to Modify Objects</p><p>InDesign allows you to add a myriad of&#160;effects and styles&#160;to the objects on your designs.&#160;Before we get into them, let’s understand what effects and styles are, and how they are related.</p><p>You can add drop shadows, bevels, gradients, patterns, glows, and many more such effects to individual or multiple objects on your documents.&#160;You can apply effects to an&#160;object&#160;(that is, a frame or shape), the&#160;stroke&#160;or outline of an object, the&#160;fill&#160;of an object, or directly to&#160;text.&#160;You can apply many different effects to objects.&#160;For example, effects are like different pieces of your outfit, a shirt, sunglasses, a watch, socks, etc.</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Now, let’s talk about styles.&#160;Styles are basically a saved set of effects that you can reuse in your documents.&#160;You can use styles to quickly format text, shapes, and objects.&#160;So, in our example, a style would be like an outfit.&#160;It is a specific combination of the different pieces of your wardrobe, and once you put it together, you can reuse it or you can choose to edit some parts, like switching to a different pair of pants and make it a different outfit.</p><p>Let’s see how you can use effects to modify images or frames in your documents.&#160;First, how do you access the effects?&#160;There are multiple ways to do this.&#160;When you select a frame or image on your document, you will see the&#160;Appearance&#160;section it the&#160;Properties&#160;panel.&#160;Here, you can see two small icons at the bottom.</p><p>The first icon lets you choose which object you want to apply the effect to.&#160;You can choose from Object,&#160;Stroke,&#160;Fill&#160;or&#160;Text.&#160;If you select a text frame, this will show&#160;Text&#160;selected by default, or in this case, if you have a regular object frame selected, it will show you&#160;Object&#160;selected.</p><p>If you click the&#160;fx&#160;icon here, you will see all the effects that you can apply to the selected object.</p><p>You can access these settings from the&#160;Effects&#160;panel.&#160;Click the&#160;Window&#160;menu and select&#160;Effects.</p><p>The&#160;Effects&#160;panel will be added to your workspace.&#160;Here, you can click the&#160;fx&#160;icon at the bottom of the panel to see the same list of effects.</p><p>The first drop-down list you see in this panel is the&#160;Blending Modes&#160;list.&#160;You can choose how you want the effects that you apply to blend with the other objects on your document.</p><p>You can also adjust the Opacity of your object from here.&#160;You can select the item to which you want to apply the effects.&#160;So, if you select the stroke and change the opacity to 50%, only the stroke of the selected object will become 50% transparent.</p></section><section><h3>Applying Effects</h3><p>Applying Effects</p><p>Now, let’s see how you can apply different effects to objects on your document.</p><p>Let’s apply some effects to this image on the document. Using the&#160;Selection&#160;tool, select this frame and then click the&#160;fx&#160;icon either in the&#160;Properties&#160;panel or in the&#160;Effects&#160;panel. Select one of the effects; let’s select&#160;Transparency. The&#160;Effects&#160;window is displayed.</p><p>On the left here, you can see all the different effects that you can apply. Right at the top, you can choose if you want to apply these effects to the Object, Stroke or Fill of the selected frame. Because the frame we selected was a graphics frame, the text option here is disabled. Now, at the bottom of this left panel, you can see the current status of the&#160;Object, Stroke&#160;and&#160;Fill&#160;for this object. There is no blending mode applied, it is at 100% transparency, and there are no effects applied either.</p><p>Before adding any effects, select this&#160;Preview&#160;checkbox so that you can see what the image looks like as you apply the effects.</p><p>Let’s select the&#160;Drop Shadow&#160;effect. As soon as you do this, you can see a shadow on the image here. On the right side of the window, you can see all the settings for the drop shadow that you can adjust. You can change the color of the shadow, adjust the position of the shadow from the image, you can increase or decrease its size, and adjust its angle. Click&#160;OK&#160;once you are done.</p><p>Now, if you want to apply these same effects to other objects on the document, just open the&#160;Effects&#160;panel. The fx here indicates that some effects have been applied to this object. You can roll over the icon to see what has been applied. To apply the same effect to other objects on the document, just click and drag it onto them.</p><p>Similarly, you can also apply effects to text frames. Let’s select this text frame, select&#160;Text, and open the&#160;Effects&#160;window. Let’s add a Bevel and Emboss effect to this text. You can change the angle of the shading by dragging this point. Click&#160;OK&#160;to save these settings.</p><p>So, this is how you can apply effects to different elements of your documents.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4ec2dea1958bbcb9ea6f8394d34736ea','adobe-indesign-m8-l5-lessson-4','b24eaacdeb0176e406ee5c7c6a4386c0','Lessson 4','text',12,'<h2>Lessson 4</h2><section><h3>Creating and Editing Object Styles</h3><p>Creating and Editing Object Styles</p><p>Select a Student</p><p>You just learned how to use the Effects panel to add effects to various objects on your document.&#160;Now, let’s talk about&#160;object styles.</p><p>Object styles are very helpful when you are trying to achieve a global, uniform style for the element of your document.&#160;Now, you have seen how you can apply effects to multiple objects by just dragging and dropping them onto other objects.&#160;So why do you need to define styles?&#160;Apart from effects, styles also include other settings, like fill and stroke, corners, opacity, etc.</p><p>To create an object style, you will need to use the&#160;Object Styles&#160;panel.&#160;Click&#160;Window&#160;and select&#160;Styles.&#160;Here, there are many different styles you can create here.</p><p>You already learned about character and paragraph styles earlier in the course.&#160;For now, let’s select&#160;Object Styles.&#160;This is what the&#160;Object Styles&#160;panel looks like.</p><p>The styles you see listed here are the default styles applied when you create new objects or frames.&#160;At the bottom, you will see links to create a new style or create a new style group as well.</p><p>Let’s see an example of how you can create and apply an object style to multiple objects on your document.</p><p>This document has four images. Let’s select the first image and open the&#160;Effects&#160;window. We’ll add a drop-shadow to this image and make some modifications to it. Let’s change the color of the drop-shadow. That looks fine, now let’s click&#160;OK. Now, let’s apply a stroke to this image as well. Click the&#160;Stroke&#160;box in the&#160;Properties&#160;panel. Now, let’s select a color from the image itself. Click and drag the eyedropper onto the image and release the mouse button when you see a color you like. Click&#160;OK&#160;to select this color. Let’s also change the corners of this image. Click the&#160;Corner&#160;link and let’s unlink these corners. Change this corner to this shape, and let’s also change this one. I’ll change the size in both places as well. Click&#160;OK.</p><p>Now, we’ve applied many different characteristics to this image. If I want to apply all these settings to other elements on the document, I may not always remember all of the exact settings. So, let’s create a new style. Open the&#160;Object Styles&#160;panel and click the&#160;Create New Style&#160;icon. Double-click the new style. The&#160;Object Style Options&#160;window is displayed. Here, you can change the name of the style. You can also make any other customizations you want here. Let’s rename this and click&#160;OK.</p><p>You can now apply this new style to other objects in your document. To select more than one object, press and hold down the&#160;Shift&#160;key and click all the objects. Now, open the&#160;Object Styles&#160;panel. Click the name of the new style to apply it to all the selected objects. Now, all the frames will look the same. And the best part is that if you ever want to go in and change any of the settings in the style, it will be applied to all the objects that the style is applied to.</p><p>For example, let’s go in and change the stroke color to something else. Open the&#160;Object Styles&#160;panel and double-click the style we just created. Select&#160;Stroke&#160;from the&#160;Basic Attributes&#160;list. Choose another color and click&#160;OK. As you can see, the changes are immediately applied to all the objects that we applied this style to.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f7a786742147e24536f48196bd2ad4ca','adobe-indesign-m8-l6-module-8-summary','b24eaacdeb0176e406ee5c7c6a4386c0','Module 8 Summary','text',12,'<h2>Module 8 Summary</h2><section><h3>Summary</h3><p>Summary</p><p>Select a Student</p><p>Great Work!&#160;You have successfully completed this module on Creating and Modifying Visual Elements Part III!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Used various tools and auto-correction methods to repair project content.</p><p>Used the Story Editor to edit the text within a project.</p><p>Used effects to modify images or frames.</p><p>Created, edited, and saved object styles.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('336d2b57c43b051d3f40b1f59ac3e142','adobe-indesign-m8-l7-project-empty','b24eaacdeb0176e406ee5c7c6a4386c0','Project Empty','text',12,'<h2>Project Empty</h2><section><h3>Module 8 Project</h3><p>4100</p><p>Adobe InDesign</p><p>Creating and Modifying Visual Elements Part III - Project</p><p>Project</p><p>In this assignment, you will apply all that you have learned about modifying and manipulating the appearance of your documents. You will need to use InDesign to perform these tasks. Take screenshots after completing each step and save them as image files or add them to a Word/PPT document.</p><p>Open InDesign and set up your Dictionary, Spelling, and Autocorrect settings. Run a spell check on one of the InDesign project documents that you created in the earlier modules.&#160;(Take a screenshot once the task is complete.)</p><p>Open the same document. It should have a large amount of text added to it. If not, import text from a Word document into your InDesign document. Open the text story in the Story Editor and place it side-by-side with your document in the document window.&#160;(Take a screenshot once the task is complete.)</p><p>Apply effects one of the image and text frames in your document.&#160;(Take a screenshot once the task is complete.)</p><p>Apply some more visual modifications to the image that you applied effects to, save them as a style, and apply the new style to the other images in your document.&#160;(Take a screenshot once the task is complete.)</p><p>Review the rubric below to see how you will be graded.</p><p>Creating and Modifying Visual Elements Part III</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Use auto-correction methods to repair content</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Use the Story Editor to edit text</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately with attention to detail and meeting all requirements.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Use effects to modify images or frames</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Create, edit, and save object styles</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('459e852f7b56e9ab4d74890fd58d1c3e','adobe-indesign-m8-l8-module-8-quiz','b24eaacdeb0176e406ee5c7c6a4386c0','Module 8 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Visual Elements Part 3. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,7,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('ab2978262cfe203a8eac7df5cba5b75e','adobe-indesign-module-9','06e4e2edaf3c4cc38b4d0a152e3ee09a','Module 9: Visual Elements Part 4',9) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('530712f10d9b85eb54cdea96ec8a7daa','adobe-indesign-m9-l1-introduction-purpose-and-objectives','ab2978262cfe203a8eac7df5cba5b75e','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Select a Student</p><p>Welcome back, everyone! This is the intro video on Creating and Modifying Visual Elements Part IV. We’re almost at the last leg of our exciting InDesign journey! By now, you should have a good idea of how to use the various tools and functions in InDesign. But we have more in store for you. When used as a digital publication tool, InDesign has fantastic tools that allow you to add interactive, dynamic content and media to your projects. From embedding rich-media objects to making your documents interactive, you can design content that is completely immersive and engaging! You’ll also learn how to create and design tables to display your content in creative ways as well. Let’s get designing!</p><p>Module Description</p><p>Select a Student</p><p>InDesign is a powerhouse tool that allows you to add fun interactive elements to your documents.&#160;In this module, students will learn how to add interactive buttons and other objects to their documents.&#160;They will learn how to embed rich-media and multimedia assets.&#160;Students will also learn how they can easily add and edit tables in InDesign.</p><p>Objectives</p><p>Select a Student</p><p>In this module, students will:</p><p>Add interactive elements and behaviors.</p><p>Demonstrate knowledge of how to embed rich-media objects.</p><p>Identify and assign triggers for multimedia assets.</p><p>Create a table to display data.</p><p>Edit tables and cells.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1ad268ac35548a6132e74c6403d2bf52','adobe-indesign-m9-l2-lesson-1','ab2978262cfe203a8eac7df5cba5b75e','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Interactive Elements &amp; Behaviour</h3><p>Interactive Elements &amp; Behaviors</p><p>Select a Student</p><p>InDesign allows you to create content that has interactive elements like hyperlinks, animations, videos, and much more.&#160;These features are usually used for digital publication and distribution.</p><p>There are many different panels available to add and manage different interactive elements to your document.&#160;Click&#160;Window&#160;and select&#160;Interactive.</p><p>Here, you can add panels for everything from animation, bookmarks, and buttons to media, object states and timing.</p><p>Because there are so many different panels for adding interactive elements, you can choose to just change the workspace.&#160;As you learned earlier, InDesign has many different preset workspaces that are customized with panels and other tools specific to different uses.&#160;Throughout this course, we’ve used the Essentials workspace, but for this module, you can choose to switch to&#160;the Digital Publishing workspace&#160;as well.</p><p>Once you switch to the Digital Publishing workspace, you will see many key panels added to the workspace.</p><p>Let’s go over what each of these panels can do.</p><p>Animation:&#160;You can choose from multiple preset motions and apply them to any object on your document.&#160;You can also completely customize the motion paths, duration, and other effects.</p><p>Timing:&#160;Use this panel to determine the order in which elements on the document are animated.</p><p>Media:&#160;You can add videos and audio clips to your documents and preview and manage them using this panel.</p><p>Object States:&#160;You can use this panel to create multiple states for an object.&#160;States are basically different versions of the same object that can be programmed to change based on certain factors changing, like when you click a button.</p><p>Buttons and Forms:&#160;You can use the Buttons panel to create buttons that trigger an action.&#160;For example, you can have a button that links to a page or section.&#160;You can also use this section to create simple forms.</p><p>Hyperlinks:&#160;You can use this panel to create hyperlinks, which are links you can use to jump to other locations in the same document, other documents, websites, or email.</p><p>Liquid Layout:&#160;You can use this panel to create different page layout options for various orientations or devices.</p></section><section><h3>Adding Interactive Elements</h3><p>Adding Interactive Elements</p><p>Select a Student</p><p>Let’s see how you can add some of these interactive elements and behaviors to your documents.</p><p>You can add many different interactive elements to your InDesign documents. Let’s explore a few of these options. I have switched to the Digital Publishing workspace, so all the interactive panels are already added to the workspace.</p><p>First, let’s add a hyperlink to this text. Let’s double-click and select this text. Now, open the&#160;Hyperlinks&#160;panel. If you export this document as a PDF or an online document, you can use hyperlinks to link to other parts in the document or to external links. Click the&#160;Create new hyperlink&#160;icon at the bottom of the panel. The&#160;New Hyperlink&#160;window is displayed. You can use the&#160;Link To&#160;drop-down to choose what type of link you want to create. Let’s choose&#160;URL. Now, enter the URL that you want to link to. I’ll just enter&#160;www.google.com. If you have defined some character styles for hyperlinks, you can apply those styles from this drop-down list. And you can also customize the appearance of the link using these settings. Once you are done, click&#160;OK. You will see the new hyperlink listed in the panel here.</p><p>Next, let’s add some animation to this text. Use the&#160;Selection&#160;tool to select this text frame. Now, open the&#160;Animation&#160;panel. If you open the Preset drop-down list, you can see a huge list of presets available for you to choose from. If you click a preset, you can see a quick preview of the animation. If you want to see how it looks on the text you selected, click this icon to see an&#160;EPUB Interactivity Preview. You can explore all of the available presets. For now, let’s choose&#160;Fly in from Right. You can also modify these settings to customize the animation further.</p><p>Similarly, you can also add buttons, forms, and other interactive elements to your document. Make sure you explore and practice these tasks on your own too.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7ab81a2378e89a2b37a32770962e01e4','adobe-indesign-m9-l3-lesson-2','ab2978262cfe203a8eac7df5cba5b75e','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Embedding Media Files</h3><p>Embedding Media Files</p><p>Select a Student</p><p>InDesign also allows you to add rich-media objects like movies and sound clips to your documents.&#160;You can then export your document to a PDF or SWF and have the audio and video clips play.</p><p>Adding video and audio files to your document is very easy; you just need to use the&#160;Place&#160;command.&#160;Click the&#160;File&#160;menu and select&#160;Place.</p><p>Navigate to the movie or audio file you want to add and select it.&#160;Then, just click where you want to add it to the document.&#160;Don’t drag out a frame as you would do when placing an image, because the video can look skewed.&#160;If needed, use the&#160;Properties&#160;panel to first lock the aspect ratio and then resize the video to fit on the page.</p><p>When you place a movie or audio file on your document, it always appears in a frame.&#160;You can resize and move the frame to where you want it on the document.</p><p>You can then use the&#160;Media&#160;panel to preview the file and adjust its settings.</p><p>For example, you can determine when the video should play and if it should be looped.&#160;A Poster is like a cover for your media file and is what you will see when you open the document.&#160;You can choose a clip from the media file or you can import another image to use.</p><p>This is how you can easily add rich-media objects into your InDesign objects.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8e3aa0c92dc7662c8525262aad13eab5','adobe-indesign-m9-l4-lesson-3','ab2978262cfe203a8eac7df5cba5b75e','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Events or Triggers for Multimedia Assets</h3><p>Events or Triggers for Multimedia Assets</p><p>Select a Student</p><p>A fun part of adding interactive objects to your InDesign documents is that you can also set triggers for when different elements should become active or when media should be played.&#160;These triggers are called&#160;Events.</p><p>Events help InDesign determine how specific actions are activated, like animations or buttons.&#160;There are many different types of events or triggers that you can set.</p><p>Let’s see an example of this by adding a button to a document.&#160;You can always create a button by drawing a shape using one of the drawing tools in InDesign.&#160;Instead of spending a lot of time creating a custom button, you can also choose from one of the many preset buttons that InDesign provides.</p><p>To view all the sample buttons, open the&#160;Buttons and Forms&#160;panel and click the panel menu.</p><p>Select&#160;Sample Buttons and Forms.&#160;The popup with a list of 70+ sample buttons is displayed.</p><p>You can scroll through this list and select which one you want to add.&#160;Another reason why using preset buttons is a great choice is that they come with a lot of features already defined, like actions and states.</p><p>Here, you can see the&#160;Event&#160;drop-down list.&#160;These are the different triggers that you can specify for this button.&#160;If the event you choose happens, the action listed in the&#160;Action&#160;section will happen.</p><p>Here is what each of these events is:</p><p>On Release or Tap</p><p>This means when the mouse button is released after a click. This is usually the most commonly used event. If you drag the cursor off the button after the click, the action won’t be activated.</p><p>On Click</p><p>This means when the mouse button is clicked (without being released). This is only used if you have a specific reason to do so.</p><p>On Roll Over</p><p>This means whenever the mouse cursor enters the button area or the button’s bounding box.</p><p>On Roll Off</p><p>This means when the mouse cursor exits the button area.</p><p>On Focus (PDF)</p><p>This is when the button in a PDF file receives focus. This can be through a mouse action or when the user presses the Tab key.</p><p>On Blur (PDF)</p><p>This is when the focus moves to a different button or form field in the PDF file.</p><p>After you select an event, you can choose from a whole list of actions that should happen after the event occurs by clicking the plus sign.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('246a070fe9822a5e8f6a8c816cea90b3','adobe-indesign-m9-l5-lesson-4','ab2978262cfe203a8eac7df5cba5b75e','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Creating Tables</h3><p>Create Tables</p><p>Select a Student</p><p>When you are working in InDesign, you may need to add content to your document in a tabular format.&#160;You can create and customize tables in InDesign.&#160;As with all other elements added to InDesign documents, tables are also added into frames, specifically into text frames.&#160;You can either draw a text frame and then insert a table into it, or you can create a table and InDesign will draw a frame around it.</p><p>A table is basically a combination of cells arranged in rows and columns.&#160;The individual cells in a table also act as individual text frames.&#160;You can add text or even graphics into these frames or cells.</p><p>Just like text frames, you can thread tables together by cutting the overset from one table and moving it to a new table.</p><p>You can either create a table from scratch and then add text to it, or you can also add text to a text frame and then convert the text into a table.</p><p>There are many ways in which you can create tables.&#160;You can add the&#160;Tables&#160;panel from the&#160;Window&#160;menu.</p><p>The easiest way to create a table is to first draw a text frame.&#160;Then, click in the text frame, click the&#160;Table&#160;menu and select&#160;Insert Table.&#160;You can also do this without creating the text frame, InDesign will automatically create one.&#160;In the&#160;Create Table&#160;popup, you can add the specifications of the table you want to create.</p><p>Don’t worry about this being too accurate, as you can always come back and add or remove rows and columns.&#160;Enter the number of rows and columns you want to add.&#160;You can also specify if you want header and footer rows here.&#160;Once you are done, click&#160;OK.</p><p>The table is added to the document.&#160;If you take a look at the&#160;Table&#160;panel, you can see the same details you just added.&#160;You can also control other settings here like the spacing in each cell, position, and angle of the text, etc. Just as you have&#160;Character&#160;and&#160;Paragraph Styles, InDesign allows you to create and save&#160;Cell Styles&#160;and&#160;Table Styles.&#160;Those are the two additional panels that are added along with the Tables panel.&#160;You can create and save your own cell and table styles.</p><p>Next, you need to add text or images to this table.&#160;To do this, just double-click in a cell and then type the text you want.&#160;You can select and format this text using the&#160;Properties&#160;panel.&#160;If you want to add graphics to the cell, just select the cell and use the Place command to add an image.&#160;Note that in InDesign tables, the images are added at full size, so the table will be resized to fit the image.&#160;If you need the image to be smaller, then it is best to first place the image outside the table, resize it and then copy and place it into the table.</p><p>Another way to create tables in InDesign is by converting text to tables.&#160;Let’s say I have a list of keywords that I want to put into a table.&#160;Use the&#160;Selection&#160;tool and select all the text.&#160;Then, click the&#160;Table&#160;menu and select&#160;Convert Text to Table.</p><p>The&#160;Convert Text to Table&#160;popup appears.&#160;When you convert plain-text to a table, you need to have a way to denote which text falls in which row and column.&#160;To achieve this, InDesign gives you the chance to enter text using&#160;Column Separators.&#160;These are commands that will indicate where text should be divided into the next column.&#160;For example, here you can separate text for different columns using&#160;Tabs,&#160;Commas, or&#160;Paragraphs.</p><p>Click&#160;OK&#160;and the table is displayed.</p><p>Table Setup</p><p>The table that you just added is a very basic table.&#160;You can customize this table using the Table Setup window.&#160;Select the table and click the&#160;Table&#160;menu, select&#160;Table Options&#160;and click&#160;Table Setup.</p><p>The&#160;Table Options&#160;window is displayed.&#160;Here, you can completely customize your tables.</p><p>As you can see, you can specify the table settings, row &amp; column strokes, fill colors, and add headers and footers.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6c14d8de274cf608664e3b826821cacf','adobe-indesign-m9-l6-lesson-5','ab2978262cfe203a8eac7df5cba5b75e','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Editing Tables</h3><p>Editing Tables</p><p>Select a StudentCTEdemo_indesign</p><p>You just learned how you can easily create tables in InDesign.&#160;Now, let’s look at how you can edit tables and cells.&#160;All editing begins with first selecting the table and cell.</p><p>If you double-click in a cell till you see the cursor in the cell, and then select the text of that cell, then only the text is selected.</p><p>If, however, you select the entire row, both the cells and text of that row will be selected.</p><p>To select a row, just roll your cursor above a row or column till you see it changing to an arrow pointing right or down, respectively.&#160;If you click, the row or column will be selected.&#160;If you roll over your mouse over the corner of the table, you will see a diagonal arrow.&#160;Clicking this will select the entire table.</p><p>Adding Rows and Columns</p><p>To add a row or column, place the insertion point either in the last row or column.&#160;Then, click the Table menu, select Insert and then click Row or Column.&#160;You can also open the&#160;Table&#160;panel and increase the number of rows or columns.</p><p>Another way you can do this is by using keyboard shortcuts.&#160;Pressing the&#160;Tab&#160;key will take you to the next cell.&#160;If you press&#160;Tab&#160;when in the last cell, a new row is added.</p><p>If you need to delete a table, row or column, you can again use the&#160;Table&#160;menu and select&#160;Delete.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6fe321b38365fa146158f225cbe522b1','adobe-indesign-m9-l7-module-9-summary','ab2978262cfe203a8eac7df5cba5b75e','Module 9 Summary','text',12,'<h2>Module 9 Summary</h2><section><h3>Summary</h3><p>Summary</p><p>Select a StudentCTEdemo_indesign</p><p>Great Work!&#160;You have successfully completed this module on Creating and Modifying Visual Elements Part III!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Applied basic auto-correction methods and tools.</p><p>Used various tools to repair and reconstruct project content.</p><p>Evaluated or adjusted the appearance of objects, frames, or layers using various tools.</p><p>Used the Story Editor to edit the text within a project.</p><p>Used effects to modify images or frames.</p><p>Created, edited, and saved object styles.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('46132098a842836fb5bc065a9445ca1d','adobe-indesign-m9-l8-module-9-project','ab2978262cfe203a8eac7df5cba5b75e','Module 9 Project','text',12,'<h2>Module 9 Project</h2><section><h3>Module 9 Project</h3><p>4100</p><p>Adobe InDesign</p><p>Creating and Modifying Visual Elements Part IV - Project</p><p>Project</p><p>In this assignment, you will apply all that you have learned about adding interactive elements to your document You will need to use InDesign to perform these tasks. Take screenshots after completing each step and save them as image files or add them to a Word/PPT document.</p><p>Open an InDesign document that you created for one of the previous modules. The document should have both images and text. Apply an animation to some text and add a hyperlink to the text.&#160;(Take a screenshot once the task is complete.)</p><p>Import and place an audio or video file onto the document.&#160;(Take a screenshot once the task is complete.)</p><p>Define events to determine when the audio or video file is played. You need to add a button as a trigger.&#160;(Take a screenshot once the task is complete.)</p><p>Create a new table with 14 rows and 7 columns.&#160;(Take a screenshot once the task is complete.)</p><p>Delete 5 rows and add three more columns to the table you just created. Modify the cell colors and stroke.&#160;(Take a screenshot once the task is complete.)</p><p>Review the rubric below to see how you will be graded.</p><p>Creating and Modifying Visual Elements Part IV</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Add interactive elements and behaviors.</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Embed rich-media objects.</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately with attention to detail and meeting all requirements.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Identify and assign triggers.</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Create a table to display data.</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Edit tables and cells.</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('84cb2422c3520561cb69e7ed7581d5ab','adobe-indesign-m9-l9-module-9-quiz','ab2978262cfe203a8eac7df5cba5b75e','Module 9 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Visual Elements Part 4. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('7ea28868584e5600cef9675c5dad8664','adobe-indesign-module-10','06e4e2edaf3c4cc38b4d0a152e3ee09a','Module 10: Publishing Digital Media',10) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('34bda16803f1d73b22967281d855e76b','adobe-indesign-m10-l1-introduction-purpose-and-objectives','7ea28868584e5600cef9675c5dad8664','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Select a Student</p><p>Hi everyone! This is the intro video on Publishing Digital Media. Welcome to this last and final module of the InDesign course. It’s been an exciting journey diving into all of the fantastic features that InDesign has to offer. You’ve learned about basic but critical aspects of working in the publishing industry, both with teams and clients. You explored the InDesign interface and the various tools and commands available. You learned how to create documents and organize them using the various tools and panels in InDesign. Next, you handled more complex topics by creating and modifying visual elements of images and documents using various functions. By now, you should have an idea of just how many things you can do with InDesign. Just like any other tool, you’ll keep getting better at it the more you use it, so make sure you explore InDesign and experiment to build beautiful designs!</p><p>In this module, we’ll cover an important last step in this InDesign journey—publishing and exporting your digital media. Because InDesign allows you to work with so many different types of documents, it also gives you multiple options to prepare and export your data in various formats and for various purposes.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('124c8b8dc37e16733782cd2f3cf88b81','adobe-indesign-m10-l2-lesson-1','7ea28868584e5600cef9675c5dad8664','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Checking for Errors and Project Specifications</h3><p>Checking for Errors and Project Specifications</p><p>Select a Student</p><p>Once you are done working on your document in InDesign, the most important thing you need to do is to check the document for any errors.&#160;You also need to make sure that your document meets any and all project specifications that may have been defined at the outset.</p><p>There are a few quick and easy checks that you can perform to make sure your document is ready for publishing, whether you are sending it to a printer or preparing it to be published online.</p><p>First, take a look at your document window itself.&#160;If you look at the bottom, you should be able to see a clear indication of any errors in your document.&#160;If there are errors, you will see a red dot like this.</p><p>If you double-click this error, the&#160;Preflight&#160;panel is opened.&#160;The Preflight panel is an essential part of the publishing process and is an industry-standard process for quality checks.&#160;You can set preflight settings specific to your projects so that it will check for those errors while you are working on your documents.</p><p>For example, if you look at the error listed here, you can see that it indicates there is Overset text in this document.</p><p>Overset text is shown as an error because it is hidden text and will not be printed.&#160;This is easily fixed by resizing the text box or moving the overset text to a new text box.</p><p>Another way to open the Preflight panel is from the Window menu.&#160;Click&#160;Window, select&#160;Output&#160;and click&#160;Preflight.</p><p>By default, InDesign applies a basic profile to all new documents.&#160;This profile flags missing or modified links, overset text, and missing fonts.&#160;You can also create your own preflight profiles if you need it to check for specific errors related to links, color, images and objects, text and the document itself.</p><p>Here are some important issues to look out for when you check for preflight errors:</p><p>In some cases, if design elements like swatches are causing an error, it is not listed directly as the cause of the problem.&#160;Instead, you will just see the page item that it is applied to listed in the panel.&#160;Make sure you check for the design elements when you see such errors.</p><p>If there are errors in the overset text or any hidden notes, they are not listed in the Preflight panel.</p><p>If you create multiple master pages but haven’t used a few of them, and if one of the unused master pages has an error, it won’t be caught by the Preflight panel.</p><p>Similarly, any errors on non-printing areas like things placed on the pasteboard or any non-printing layers that you may have defined, will not be checked unless you create a specific profile that checks for them.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2a0bef61b1a7b12271225a8159da67a6','adobe-indesign-m10-l3-lesson-2','7ea28868584e5600cef9675c5dad8664','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Saving Files</h3><p>Saving Files</p><p>Once you have finished working on your file and you have prepared your document, the next step is to save your document.&#160;As a best practice, it is always recommended to save your file in the native InDesign file format, that is, in .indd format.&#160;This allows you to preserve a master copy of your file in case you need to go back in and extract specific objects or layers, make edits to the file, or if your exported file is lost or corrupted.</p><p>Saving your file as a .indd document is easy.&#160;Just click the&#160;File&#160;menu and click&#160;Save As.</p><p>Choose the location where you want to save the file.&#160;Enter a name for the file and choose&#160;.indd&#160;as the file type.&#160;Click&#160;Save.</p><p>Your file will be saved in its native .indd format.&#160;You can now always open this file and export it or package it for print or publishing.</p><p>100% Completed</p><p>Score1/1</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('eedd7ff071050e6b3305c83fc09871dd','adobe-indesign-m10-l4-lesson-3','7ea28868584e5600cef9675c5dad8664','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Document Formats</h3><p>Document Formats</p><p>InDesign allows you to export your files in many formats and for different uses.&#160;You’ve learned how to save your file as a master file.&#160;Now, let’s see how you can choose to save your document in formats for print or screen use.&#160;Let’s go over a few different file formats and how you can use them.</p><p>Publish Online</p><p>This is a format you would use when you want to publish your interactive documents for web viewing.&#160;Once you publish your document, you can share the link with anyone.&#160;This online document is versatile because you don’t need a plugin to view it, it can be shared across platforms, and can even be embedded into websites.</p><p>PDF</p><p>This is one of the common formats that you will use to export your files.&#160;PDFs are very versatile and widely used document formats.&#160;They are very customizable in many ways.&#160;You can control the quality of all of the elements of your PDF, you can compress heavy files to control the file size, and you can even add security for PDF files to restrict access to them.</p><p>HTML</p><p>Exporting to HTML is another easy way to prepare InDesign documents for web use.&#160;Exporting in HTML gives you flexibility in choosing how the various graphic and visual elements are exported.</p><p>JPEG</p><p>You can also export your documents as JPEG files.&#160;JPEG uses a standardized image compression mechanism to compress full-color or grayscale images for onscreen display.&#160;Use the Export command to export a page, spread, or selected object in JPEG format.</p><p>Check out the&#160;Additional Resources&#160;section at the end of this module for a comprehensive list of supported formats in Photoshop.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('210bfbaa60398a9723da0504213199ed','adobe-indesign-m10-l5-lesson-4','7ea28868584e5600cef9675c5dad8664','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Printing Proofs</h3><p>Printing Proofs</p><p>Select a Student</p><p>A proof copy is a printed simulation of what your document will look like when it is published or printed.&#160;InDesign does this by simulating the printing process of different devices.&#160;This is a cheap way to run a final check on your document before you send it off to be published.</p><p>To set this up, click the&#160;View&#160;menu, select&#160;Proof Setup, and click&#160;Custom.</p><p>You can select the device that you want this proof to simulate.&#160;Make sure that the&#160;Preserve CMYK Numbers&#160;or&#160;Preserve RGB Numbers&#160;checkbox is selected because this ensures that the color profiles of the document are handled correctly.</p><p>Then, print your document.&#160;Click&#160;File&#160;and click&#160;Print.&#160;You can check all the print settings to make sure that they are correct.</p><p>Select&#160;Color Management&#160;from the left panel.&#160;Here, choose&#160;Proof&#160;from the&#160;Print&#160;section to proof the document.&#160;You can leave the other settings as they are and then click&#160;Setup&#160;or&#160;Print&#160;to access the&#160;Print&#160;dialog box.&#160;Print your document.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('100795c9266c2ef74743cd38aaf12205','adobe-indesign-m10-l6-lesson-5','7ea28868584e5600cef9675c5dad8664','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Packaging InDesign Files</h3><p>Packaging InDesign Files</p><p>Your InDesign document is made up of a lot of components, images, fonts, hyperlinks, and much more.&#160;Before you send your document to someone for review, further work, or for printing, you need to make sure that they have all the resources they need to do their tasks.</p><p>Instead of having to put together the files yourself, the Package command in InDesign makes this task much easier.&#160;Just click the&#160;File&#160;menu and click&#160;Package.&#160;The&#160;Package&#160;window is displayed.</p><p>The Package window runs a quick preflight of your document to make sure everything looks fine.&#160;Here, you can see a summary of all the checks.&#160;You can also go into each of the tabs on the left to see what was found in each category.&#160;For example, if you click&#160;Fonts, you will see all the fonts you have used in your document also listed here.&#160;InDesign will package the fonts as well.&#160;This is because if the person you are sending the package to doesn’t have the correct fonts installed, they will not be able to view the document correctly.</p><p>If you’re working with larger documents, you can click the&#160;Show Problems Only&#160;checkbox to only see the issues in the document, if any.&#160;Once you have gone through all the tabs and everything looks okay, click the&#160;Package&#160;button.</p><p>You can name your package here.&#160;There are a few options shown down here, you can see that InDesign will copy all of your fonts into the package by default, along with the linked graphics and any other graphic links.&#160;Click the&#160;Package&#160;button to create the package.</p><p>You will see a quick warning that is just informing you that you are sharing fonts which are software and that you need to follow copyright laws.&#160;Click&#160;OK.&#160;Your package will be created.&#160;You can navigate to the location on your computer to check the package.</p><p>As you can see, the package includes the fonts, links and a PDF version of my document.&#160;You can now zip this folder and share it with the intended recipients.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1b75420bff66eb9f020dc650a2ee35a0','adobe-indesign-m10-l7-summary','7ea28868584e5600cef9675c5dad8664','Summary','text',12,'<h2>Summary</h2><section><h3>Summary</h3><p>Summary</p><p>Select a Student</p><p>Great Work!&#160;You have successfully completed this module on Working in the Design Industry Part II!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this session, you:</p><p>Demonstrated knowledge and understanding of key terms related to publication and multi-page layouts.</p><p>Demonstrated knowledge of how color is created in publications.</p><p>Demonstrated knowledge of elements and principles of design and common design techniques.</p><p>Identified and use common typographic adjustments to create contrast, hierarchy, and enhanced readability.</p><p>Defined common photographic/cinematic composition terms and principles.</p><p>Additional Resources</p><p>Select a Student</p><p>The following websites are additional resources to learn more about this topic.&#160;(Not required reading)</p><p>RGB and Color Channels in Photoshop Explained(opens in a new tab)</p><p>Essential Photoshop Color Settings</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e20d8763c63f5fa1d777f91218992a6d','adobe-indesign-m10-l8-module-10-project','7ea28868584e5600cef9675c5dad8664','Module 10 Project','text',12,'<h2>Module 10 Project</h2><section><h3>Module 10 Project</h3><p>4100</p><p>Adobe InDesign</p><p>Publishing Digital Media - Project</p><p>Project</p><p>In this assignment, you will use what you have learned to check your document and export it in various formats.</p><p>Create an InDesign document with multiple elements. You can choose from one of these types of documents:</p><p>An interactive document with animations and buttons</p><p>A flyer or brochure layout</p><p>A multi-page report with images and text</p><p>Check the settings of the document to ensure there are no errors and they fit the description provided above. Save the file as a .indd file. Save a version of the file as a PDF. Then, create a package to share with others for review and printing.</p><p>Review the rubric below to see how you will be graded.</p><p>Publishing Digital Media Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Check document and project specifications</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Save in native file format</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Save in appropriate format for print or screen</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Export project elements</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Total Points:&#160;20</p><p>&#169; 2025. All Rights Reserved.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('53daa0fdb384161ef91543fc23ab8b82','adobe-indesign-m10-l9-module-10-quiz','7ea28868584e5600cef9675c5dad8664','Module 10 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Publishing Digital Media. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('edcb5de6ece7cfceba6c7e9363a0e7b1','adobe-indesign-module-11','06e4e2edaf3c4cc38b4d0a152e3ee09a','Module 11: Final Exam',11) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2235fbbf8fde651d77853e816023a709','adobe-indesign-m11-l1-final-exam','edcb5de6ece7cfceba6c7e9363a0e7b1','Final Exam','text',12,'<h2>Final Exam</h2><section><h3>Course Wrapup and Summary</h3><p>Course Wrap Up/Summary</p><p>Select a StudentCTEdemo_indesign</p><p>We&#39;re at the last leg of our exciting InDesign journey!&#160;We hope this course has equipped you with the knowledge needed for you to master the learning objectives of this course.&#160;InDesign is a tool that is best learned by doing, which is why we gave you a ton of videos and activities to practice your skills.&#160;You should now be ready for the final exam.</p><p>Our main objective on this journey has been to push away the veil of mystery and complexity from InDesign and enable you to discover all of the creative possibilities it has.&#160;Keep exploring InDesign and use the resources to discover more interesting, creative ways of expressing yourself in your designs and layouts.&#160;Whether you choose to pursue a career in digital media and publishing or not, this course has given you some fantastic skills that you can still apply in other fields or even as a hobby.</p><p>Complete the final exam on the next page and submit it to complete this activity.</p></section><section><h3>Final Exam</h3><p>Final Exam</p><p>Select a StudentCTEdemo_indesign</p><p>Analytics:Off</p><p>Answer Key:Off</p><p>ABCABC</p><p>Directions:&#160;Read each question carefully and then choose the correct answer.</p><p>What is the Content Grabber used for?</p><p>Used to only select and move the object placed inside the frame.</p><p>Used to select text</p><p>Used to copy content</p><p>The way that objects and layers are displayed in the Layers panel is how they are layered on your document.</p><p>True</p><p>False</p><p>What is the difference between the Selection tool and Direct Selection tool?</p><p>They are the same</p><p>With Selection tool you need to click to select, with Direct Selection tool, you only need to rollover the object.</p><p>Selection tool selects the frame, Direct Selection tool selects the content of the frame</p><p>There is only a Selection tool in InDesign</p><p>What are the different ways in which you can organize objects in InDesign?&#160;(select all that apply)</p><p>Group them</p><p>Assign colors to categorize layers</p><p>Organize into layers based on type of object</p><p>Organize into layers based on position or section on the document</p><p>What types of interactions can you add to InDesign documents?&#160;(Select all that apply.)</p><p>Animation</p><p>Videos</p><p>Buttons</p><p>Hyperlinks</p><p>Where are Serif fonts commonly used?</p><p>Magazines and newspapers</p><p>Articles and website text</p><p>Titles, headers, and graphic-heavy designs</p><p>How can you tell if an image is linked or embedded?&#160;(Select all that apply)</p><p>It will be list at the top of the Properties panel</p><p>It will be indicated on the image</p><p>Linked objects will be listed in the Links panel</p><p>The word Linked or Embedded will appear over the image</p><p>What is white space in a design?</p><p>It is the negative space or space left unmarked in a design</p><p>It is the background layer of an image</p><p>It is the spacing between characters</p><p>It is the amount of white in the colors used in the design</p><p>If you need to apply the same gradient across different objects, what tool would you use?</p><p>Gradient tool</p><p>Color Picker</p><p>Selection tool</p><p>Paint tool</p><p>True or false?&#160;You can add videos and determine when the video should play and if it should be looped.</p><p>True</p><p>False</p><p>It is best to save files in the native format.</p><p>True</p><p>False</p><p>Why is it beneficial to create object styles?</p><p>You can easily apply them to multiple objects</p><p>They look cool</p><p>They are the same as effects</p><p>There are no benefits</p><p>True or false?&#160;When you change the view to &quot;Fit Spread in Window&quot; you can see the entire pasteboard.</p><p>True</p><p>False</p><p>If your document has overset text, what does it mean?</p><p>It means two text boxes are overlapping</p><p>It means there is too much content to fit inside a text box</p><p>It means that the text is not formatted correctly</p><p>It means that the text much less than the size of the text frame</p><p>How many effects can you add to an object?</p><p>It depends on the object</p><p>Upto 5</p><p>Upto 10</p><p>As many as you want</p><p>True or false?&#160;Paragraph styles are a combination of character styles and other paragraph attributes.</p><p>True</p><p>False</p><p>Which of these tools can you use to lay out visual elements on your InDesign document?&#160;(Select all that apply)</p><p>Frame tool</p><p>Shape tool</p><p>Text tool</p><p>Selection tool</p><p>What are the ways to create tables in InDesign?&#160;(Select all that apply)</p><p>Using Tables menu</p><p>Using Tables panel</p><p>Using Convert Text to Table command</p><p>Using File menu</p><p>The Jump object wrap option makes the text skip over the object and starts back up below the object.</p><p>True</p><p>False</p><p>What are the different categories of tools you can find in InDesign?&#160;(Select all that apply)</p><p>Selection tools</p><p>Drawing and Type tools</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe InDesign lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe InDesign interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b97707d6e74067abdf17ee5fa6cf1b1a','adobe-indesign-course-mastery-assessment','edcb5de6ece7cfceba6c7e9363a0e7b1','Course Mastery Assessment','assessment',30,'<h2>Course mastery assessment</h2><p>Bring together knowledge and application from the complete course. Achieve at least 80% to satisfy the assessment requirement for certification.</p>',NULL,1,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO assessments (id,slug,course_id,title,pass_mark,questions) VALUES ('62c5878e0538f64505d2d7562971acd8','adobe-indesign-course-mastery-assessment','06e4e2edaf3c4cc38b4d0a152e3ee09a','Adobe InDesign Course Mastery Assessment',80,CAST('[{"id":"adobe-indesign-course-mastery-assessment-q1","type":"multiple-choice","prompt":"Before starting a practical task in Working InDesign Industry Part 1, which action best demonstrates professional judgement?","options":["Clarify the intended outcome, constraints, and success criteria before choosing tools.","Choose the fastest tool and define the goal afterward.","Copy the first available example without checking its fit.","Begin production immediately and leave requirements for final review."],"answer":"Clarify the intended outcome, constraints, and success criteria before choosing tools.","explanation":"Strong practice begins with a clear outcome, constraints, and measurable success criteria.","clue":"Think about what must be understood before execution begins."},{"id":"adobe-indesign-course-mastery-assessment-q2","type":"multiple-choice","prompt":"A first attempt in Working InDesign Industry Part 2 does not meet the requirement. What is the strongest next step?","options":["Compare the result with the criteria, identify the cause, revise, and test again.","Submit the attempt unchanged because the task is complete.","Replace the criteria with measures the attempt already meets.","Discard all evidence and restart without diagnosing the issue."],"answer":"Compare the result with the criteria, identify the cause, revise, and test again.","explanation":"An evidence-led improvement cycle diagnoses the gap before a focused revision and retest.","clue":"Use feedback and evidence to improve the next attempt."},{"id":"adobe-indesign-course-mastery-assessment-q3","type":"multiple-choice","prompt":"Which evidence most credibly demonstrates applied competence in Project Setup and Interface Part 1?","options":["A completed work sample with decisions, checks, feedback, and reflection documented.","A claim that the topic was understood without a work sample.","A list of tools with no explanation of how they were used.","An unfinished draft that has not been checked against requirements."],"answer":"A completed work sample with decisions, checks, feedback, and reflection documented.","explanation":"Competence is best demonstrated through completed, reviewed evidence and reflective reasoning.","clue":"Choose evidence that shows both the result and how quality was established."},{"id":"adobe-indesign-course-mastery-assessment-q4","type":"multiple-choice","prompt":"When work in Project Setup and Interface Part 2 could affect people, data, safety, or the environment, what should the learner do?","options":["Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","Proceed without checks when the intended outcome is positive.","Treat ethical and safety considerations as optional after delivery.","Hide known limitations so stakeholders remain confident."],"answer":"Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","explanation":"Responsible practice makes risk, consent, standards, and safeguards part of the work itself.","clue":"Professional quality includes the impact of the work, not only the output."},{"id":"adobe-indesign-course-mastery-assessment-q5","type":"multiple-choice","prompt":"How should a learner transfer skills from Organizing Documents to a new workplace or project context?","options":["Analyse the new context, adapt the method, test assumptions, and evaluate the result.","Repeat the original steps unchanged regardless of context.","Use only familiar methods and ignore new constraints.","Wait for a complete example to copy before making any decision."],"answer":"Analyse the new context, adapt the method, test assumptions, and evaluate the result.","explanation":"Transfer requires adapting core principles to new constraints and validating the result.","clue":"Core principles remain useful, but their application must fit the new context."}]' AS JSON)) ON DUPLICATE KEY UPDATE title=VALUES(title),pass_mark=VALUES(pass_mark),questions=VALUES(questions);
INSERT INTO courses (id,slug,academy_id,moodle_id,title,description,level,duration,price,is_free,status)
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('7f810662eb6a789fad50017ca45c6f8a','adobe-photoshop-module-0','ee9c9635d1344f63172dfbcc5883d9ea','Module 0: Introduction, Purpose, Objectives, Summary',0) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('de30af61545cec84a93cb30351f60e1d','adobe-photoshop-m0-l1-introduction-purpose-and-objectives','7f810662eb6a789fad50017ca45c6f8a','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Course Intro Video</h3><p>Course Intro Video</p><p>Let’s be honest, the perfect picture doesn’t take itself! Even the best-shot photos still need work done to fix mistakes, enhance lighting, and make the picture ready for a billboard in times square, or a holiday card to send to loved ones.</p><p>Adobe’s Photoshop is one of the most widely known and used programs, with over 90% of the world’s creative professionals using Photoshop. Not only can you edit and enhance your photographs, but you can also create illustrations and paintings, 3D graphics and animations! This course will prepare students for Adobe’s Photoshop certification exam. Students who pass the exam will be accredited as an Adobe Certified Expert in Photoshop, which can open doors and opportunities in the world of photography and design.</p><p>In this course, students can start with zero experience and learn how to navigate and work in Photoshop. They’ll learn about project setup, organizing documents, creating visual elements, and publishing digital media. This course will give students the foundation they need to start using Photoshop and all of the fantastic tools and features that it offers.</p><p>Course Navigation</p><p>In this Course Navigation, we’ll go over the overall course structure and what you can expect in each of the modules in this course.</p><p>Before You Begin</p><p>Before we go over the navigation and structure of the course, here are a few important things you should do:</p><p>Make sure you have Adobe Photoshop open on your computer when you start the course.&#160;You can follow along with the reading material and instructional videos and explore Photoshop as you learn about it.</p><p>Make sure you have Office suite programs or basic word processing programs installed on your computer, as you will require them for your project work.</p><p>Navigating the Course</p><p>Within each section, you can easily navigate between the pages either with the menu on the left, or with the left/right arrows on the bottom.&#160;This allows you to move between PAGES within each section.&#160;Once you are done with all the pages in a section, you can either click at the top on the title of the course, or you can click at the very bottom of the page to the next section.&#160;It’s very important to make sure you finish every page in a section BEFORE moving to the next section.</p><p>(opens in a new tab)</p><p>This image shows a typical course page with navigation bars on the left side as well as the bottom.&#160;The course number, title, and content will vary from course to course.</p><p>License:&#160;All Rights Reserved</p><p>Course &amp; Module Structure</p><p>The course is divided into 11 modules, with an initial introductory module that you are now taking.&#160;This introductory module is intended to make you familiar with the course structure and explain some basic but important concepts about sources, plagiarism as well as the syllabus of this course.</p><p>Each module of the course will be structured as shown in the diagram here.</p><p>Each module has an introduction, 4-5 lessons, and a summary and quiz at the end of the module.&#160;We begin each module with an introductory video into the topics that will be covered in that module.&#160;You can use the video controls to adjust the volume, captions, and speed of the video based on your preferences.</p><p>Each lesson of the module will cover a different topic for that module.&#160;Lessons contain multiple pages of content that comprise of instructional content as well as instructional videos.&#160;Follow along and explore Photoshop yourself as you learn about its features and tools in each lesson.</p><p>As you will learn in the syllabus, the introduction, video, and reading pages are graded on participation, meaning you get credit for going through every page and activity in the module.</p><p>After each lesson is a concept check or reflection where you&#39;ll either input an answer or work with flashcards or maybe a sorting exercise to review and firm up the concepts that were taught in that section.&#160;The reflections are either journal entry or discussion prompts.&#160;To participate in a class-wide discussion, you’ll click on a link to read the questions or prompts, and then participate in the discussion by adding a new discussion topic and eventually commenting on posts from other students.&#160;You&#39;ll see this repeat itself through all the sections.</p><p>Every module ends with a module summary and additional resource links that you can check out.&#160;Once you are finished with each lesson, you will need to complete a project and a quiz.</p><p>The project gives you a chance to practice what you learned in that module in Photoshop.&#160;Every module will have a different project and will give you a chance to be creative, explore all the tools yourself, and learn by doing.</p><p>Finally, the module quiz is pretty straight forward as they are mostly multiple choice and true/false questions.&#160;Unless you are told otherwise by your instructor, there are no retakes for quizzes, so give it your best shot on your first and only time.</p><p>Many aspects of grading or other features of the course may be changed by your individual schools and instructors.&#160;So please refer to updated instructions or grading procedures that they provide.</p><p>For additional help, you can reach out to your instructor or contact the help desk of your LMS.</p><p>Course Objectives</p><p>In this course, students will</p><p>Understand the critical concepts related to working with colleagues and clients as well as crucial legal, technical, and design-related knowledge.</p><p>Navigate the interface setup and program settings that assist in an efficient and effective workflow.</p><p>Identify the process as well as demonstrate the ability to ingest digital assets for a project.</p><p>Organize document structure such as layers and tracks.</p><p>Manage document Structure for efficient workflows.</p><p>Use core tools and features of the application to create visual elements and manipulate text and selections.</p><p>Transform digital graphics and media using basic reconstructing and retouching techniques to manipulate digital graphics and media as well as modify the appearance of elements using filters and styles.</p><p>Save and export documents or assets within individual layers or selections.</p><p>Sources and Plagiarism</p><p>Sources and Bias</p><p>Throughout this cou<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('80d0e1d511f54a6fe80c0f32e5bdcdaf','adobe-photoshop-module-1','ee9c9635d1344f63172dfbcc5883d9ea','Module 1: Design Industry Part 1',1) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0953dba64f8ca86b85947cda775b8b36','adobe-photoshop-m1-l1-introduction-purpose-and-objectives','80d0e1d511f54a6fe80c0f32e5bdcdaf','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi, I’m Mr. Southwick and I’ll be one of your instructors for this course on Adobe Photoshop. This is the intro video for Working in the Design Industry Part 1. You’ll see me introducing each module in this course, providing an overview of the topics you’ll cover in each one. Throughout the course, you’ll have a variety of ways to learn the material. There will be readings, videos, screenshot tutorials, images, and much more. But our ultimate goals are two-fold. First, so that you learn how to use photoshop. And second, so that you are best prepared to take (and pass!) the Adobe Certification exam on Photoshop.</p><p>As with most things in life, we learn best by doing, and something like Photoshop is no exception. So as you are going through the course, I’d encourage you to have the photoshop program up and running on your computer. Follow along, trying things for yourself, and experiment! It’s ok and even encouraged to make mistakes. One because that’s how we learn, and two, there’s always the ability to undo an action!</p><p>Photoshop is a complex program, and can be overwhelming for someone who is brand new to it. But we’ll be walking through it slowly, step-by-step to get you comfortable with all the key features of this software. My colleague for this course, Preeti, will be the one walking you through the screenshot tutorials of Photoshop. I think you’ll agree, she has a much more pleasant voice than mine, and she is a top-notch expert when it comes to Photoshop.</p><p>Now, I’m sure you’ve heard of Photoshop before, but what can it really do? Is it just a tool to remove red-eye from your photos? Or is it just used by photographers to airbrush their photos? Well, Photoshop can do both those things, but they are minuscule compared to the full scope of what you can do with Photoshop. In this module, you’ll get an insight into the design industry and how Photoshop fits into it. You’ll get an understanding of the real-world processes that take place in graphic design, and the processes and standards you need to have in place before you start using Photoshop.</p><p>Legal and ethical considerations also come into the picture when you need to ask yourself questions like, “Is it okay for me to edit or modify this famous photographer’s photo?” or “Can I use this picture I copied from a website and edit it for my own use?” You’ll learn about all this and more in this introduction into the design industry.</p><p>Module Description</p><p>License:&#160;All Rights Reserved</p><p>Working in the design industry is more than just knowing how to use graphic design tools.&#160;There are crucial design, legal, and technical aspects that you must take into consideration when you work on any design project.&#160;Another key factor is how you work with colleagues and clients, and how well you are able to communicate your ideas and design visions.&#160;In this module, students will learn critical skills to recognize what their audience needs, and how to communicate with colleagues and clients about design plans.&#160;They will also learn the legal ramifications of copyright, permissions, and licensing when using digital&#160;content.</p><p>Objectives</p><p>In this module, students will:</p><p>Understand the Adobe Creative Cloud and the role of the various applications</p><p>Determine whether the content is relevant to the purpose, audience, and audience needs</p><p>Demonstrate knowledge of techniques for communicating about design plans with peers and clients</p><p>Demonstrate knowledge of basic project management concepts</p><p>Identify legal and ethical considerations for using third-party content, such as copyright, permissions, and licensing</p><p>Identify when and how to obtain permission to use images of people and locations</p><p>Polling Question</p><p>Which of these aspects of working in the design industry are you most intimidated about?</p><p>Working with clients</p><p>Working with colleagues</p><p>Coming up with design ideas</p><p>Managing projects and time</p><p>Obtaining permissions to use copyright and licensed content</p><p>Results:</p><p>Coming up with design ideas&#160;25%</p><p>Working with clients&#160;25%</p><p>Working with colleagues&#160;25%</p><p>Managing projects and time&#160;25%</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('bed796fbe168c250eccf6728ffb9ee48','adobe-photoshop-m1-l2-lesson-1','80d0e1d511f54a6fe80c0f32e5bdcdaf','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Introduction to Adobe Creative Cloud</h3><p>Introduction to Adobe Creative Cloud</p><p>Let&#39;s kick this module off with an introduction to Adobe Creative Cloud.</p><p>Video Title:&#160;Adobe Creative Cloud 2019 - Software and services for creative professionals</p><p>Video Publisher:&#160;Adobe</p></section><section><h3>What is Adobe Creative Cloud</h3><p>What is Adobe Creative Cloud?</p><p>Adobe Creative Cloud is a suite of Adobe apps for everything from graphic design and video editing to photography and web development.&#160;Adobe Creative Cloud, or as it is more commonly known, Adobe CC applications are widely used among professionals in all of these fields.&#160;The apps are designed to help you push the boundaries of your creativity.&#160;It also allows you to work collaboratively with teams and clients, and share assets between Adobe apps for a seamless design workflow.</p><p>You can use Creative Cloud applications for a myriad of things including:</p><p>Editing videos and movies,</p><p>Creating animations and special effects,</p><p>Designing mobile apps and websites,</p><p>Advertising, print and magazine designs,</p><p>And much more.</p><p>What apps are there in Adobe Creative Cloud?</p><p>There are more than 20 different apps includes in Adobe Creative Cloud, which you can purchase as a package or as individual subscriptions.</p><p>Here are just a few of them:</p><p>License:&#160;All Rights Reserved</p><p>Adobe Video Tools</p><p>Adobe has a suite of video and audio editing tools that are used by professionals around the world to create everything from YouTube videos to Hollywood movies.&#160;Apps include:</p><p>Premiere Pro</p><p>Premiere Rush</p><p>After Effects</p><p>Character Animator</p><p>Adobe Audition</p><p>Adobe Spark</p><p>License:&#160;All Rights Reserved</p><p>Adobe Graphic and Visual Design Tools</p><p>These apps allow you to explore your creativity and bring your designs to life.&#160;Create logos, advertisements, posters, website designs, and even 3D designs.&#160;Use apps to paint, draw and sketch your artwork.&#160;Apps include:</p><p>Photoshop</p><p>InDesign</p><p>Illustrator</p><p>Adobe Spark</p><p>Photoshop Sketch</p><p>Capture</p><p>License:&#160;All Rights Reserved</p><p>Adobe Photography Tools</p><p>Transform your photographs with professional photography editing and enhancement tools.&#160;You can edit, organize, and share your photographs easily using apps like:</p><p>Lightroom</p><p>Photoshop</p><p>License:&#160;All Rights Reserved</p><p>Adobe Web Design Tools</p><p>The world lives on the web, and you can use Adobe tools to create visually stunning web and UX designs.&#160;Apps include:</p><p>Adobe XD</p><p>Dreamweaver</p><p>Adobe Spark</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('68e59e726d55c02cd4c8d426361c1799','adobe-photoshop-m1-l3-lesson-2','80d0e1d511f54a6fe80c0f32e5bdcdaf','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Gathering Information</h3><p>Gathering Information</p><p>Unlike many other fields where client requirements are clear and measurable directives, working in the design industry can be much more challenging.&#160;It is essential for you to have a clear understanding of the purpose of the design, the intended audience, and their needs.</p><p>There are a number of key factors you need to keep in mind to ensure a smooth, productive and long-lasting business relationship with your clients.</p><p>Take a look at this video about understanding customer needs.&#160;While it caters to the sales industry, it covers points of view that are relevant for any client-vendor relationship.</p><p>Video Title:&#160;Understanding Customer Needs</p><p>Video Publisher:&#160;InfoteamConsulting(opens in a new tab)</p><p>Asking the Right Questions:</p><p>Any new project starts with understanding what the client wants.&#160;Make it a point to understand what the client’s goals are and what they hope to achieve with the product you are designing.</p><p>It is a good idea to research and gather information about the client before you speak to them.&#160;This will give you an idea of their company or product and what their past work has been like.</p><p>Listen to what your client has to say, and ask questions to refine the information they are giving you.&#160;Make sure you take notes while in discussion with the client so you can also note down any follow-up questions that you may have.&#160;Make a note of examples or recommendations made by the client.</p><p>byPressmaster</p><p>License:&#160;All Rights Reserved</p><p>Understanding the Audience:</p><p>When you work on a project, your client isn’t only the person who gave you the project, your client is also the end-user of your designs, the audience!&#160;Any designs that you create must take your target audience into consideration.&#160;For example, let’s say you are creating an advertising design for a product whose target audience is in China.&#160;If you use American pop culture or music references in your design, the objective of your advertisement could be lost on the intended audience because they may not be familiar with the elements of your design approach.</p><p>Consider the target audience factors like:</p><p>Age group</p><p>Educational background</p><p>Geographical location</p><p>Cultural aspects</p><p>Technical expertise</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1402d805cce1c44a3439f4f954b18e87','adobe-photoshop-m1-l4-lesson-3','80d0e1d511f54a6fe80c0f32e5bdcdaf','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Communication with Clients and Peers</h3><p>Communication with Clients and Peers</p><p>byChaosamran_Studio</p><p>License:&#160;All Rights Reserved</p><p>A key step in the design process is to share iterative versions of your work with both your team and clients to get feedback.&#160;This helps in many ways.&#160;Your peers can provide constructive feedback and suggestions based on their understanding of the client needs, and your clients can tell you if your designs are in-line with their expectations.</p><p>There are many techniques to share your design ideas and plans with clients and peers, depending on what tool and medium you are using.</p><p>Click each term to learn more.</p><p>Sketches</p><p>Rough outlines of your design which give clients a visual guideline of what to expect. This is a great first step to get feedback.</p><p>Specifications</p><p>Put down more technical specifications like color palettes, font, size and resolution, complexity, navigation choices, etc. This is helpful in filtering and honing in on what works for the client.</p><p>Wireframes</p><p>These are mainly used in web design and are used to establish the basic structure of a page before the graphics, design, and content are added. This is a fantastic way to give clients a big picture outline of the product. It is also more efficient for you to make any changes to the core structure at this stage, rather than after the entire web page is built.</p><p>Prototypes</p><p>While a wireframe is a skeleton of your design, a prototype is a short, full-featured working sample of your final product. Think of a prototype like a trailer to a movie. It shows you exactly what to expect and gives you as close an idea of the final product as possible without actually showing you the entire movie.</p><p>Here are a few videos that will walk you through the sketching to prototyping process that designers at Google use for their projects.</p><p>Video Title:&#160;Rapid Prototyping 1 of 3:&#160;Sketching &amp; Paper Prototyping</p><p>Video Publisher:&#160;Google for Startups</p><p>Video Title:&#160;Rapid Prototyping 2 of 3:&#160;Digital Prototyping</p><p>Video Publisher:&#160;Google for Startups</p><p>Video Title:&#160;Rapid Prototyping 3 of 3:&#160;Native Prototyping</p><p>Video Publisher:&#160;Google for Startups</p><p>Throughout all these stages, it is essential to keep track of client feedback and map it to their initial requirements.&#160;Are you still in line with what the client wants?&#160;Has the client strayed from what they wanted and are going in a different direction?&#160;What impact does that have on the effort or complexity of the project?&#160;These are all essential questions you need to ask at every stage.</p><p>As always, keep an open channel of communication with your team and clients about all of these factors.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1d5f6312dfc091d1aa0e4cc0b4582c91','adobe-photoshop-m1-l5-lesson-4','80d0e1d511f54a6fe80c0f32e5bdcdaf','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Project Management</h3><p>Project Management</p><p>Let&#39;s start off by saying what everyone is thinking, “Project management?&#160;What does that have to do with visual design?” The truth is, project management is going to be an essential part of working in the design industry.&#160;You may be the best designer with the most creative ideas, but if you are unable to meet deadlines, manage your clients, or communicate effectively with your team, you will not be successful.&#160;The main goal of project management is to be organized at every stage of the project.&#160;Here&#39;s a video that gives you an idea of the project management aspects that graphic designers need to consider.</p><p>Video Title:&#160;The Secret to More Freelance Work:&#160;Project Management?</p><p>Video Publisher:&#160;Brad Colbow(opens in a new tab)</p><p>Some of the key components of project management are planning, time management, clear and open communication, and maintaining a professional attitude.</p><p>License:&#160;All Rights Reserved</p><p>Planning:</p><p>Start off your design process by charting out a project plan.&#160;You’ve already learned how to understand your client requirements in the last few lessons.&#160;Your project plan should take into account&#160;what&#160;needs to be done,&#160;how&#160;it needs to be done,&#160;by&#160;when&#160;it needs to be done, and&#160;who&#160;you will be working with.</p><p>Within your project plan, create timelines and milestones for specific tasks along with due dates.&#160;You should also be aware of what the review process will be with the client.</p><p>If you are working with a team on a project, make sure everyone has individually assigned tasks and that they follow up on their own responsibilities.</p><p>License:&#160;All Rights Reserved</p><p>Time management:</p><p>This is an essential step no matter what you do, whether you are in school or a working professional.&#160;As you gain experience in the design industry, you will be able to gauge how much time different tasks take.&#160;Allocate time for each task in your project plan and stick to a schedule.&#160;Make a note of all deadlines that have been met, and also those that haven’t been met, so that you can plan for unforeseen delays.</p><p>License:&#160;All Rights Reserved</p><p>Communication:</p><p>Another essential part of project management is to always have open, clear communication with your team and clients.&#160;When working with a team, make it a practice to give each other constructive feedback.&#160;Instead of “I don’t like it,” say something like “Have you considered using a more colorful background?”</p><p>Along with giving feedback, it is also essential that you be open to feedback from others.&#160;Your listening skills play a big role in having good communication skills.</p><p>When communicating with clients, it is important to remember that the client is not always right.&#160;Just because they said so is not always a reason to change the design.&#160;You are the design expert in this situation, so make sure that you consider the requirements of the project, client, and audience and decide if the client’s feedback improves the design of the project.&#160;If a client makes a suggestion that seems to be going away from the direction of the project, bring that to light in a professional manner.&#160;For example, “That’s a great idea, but I think our audience may not relate to it.&#160;I think it would have more of an impact if we…”</p><p>Once you begin to incorporate these basic project management principles into your work process, you will find that rather than it being another thing added to your plate, it will greatly ease and enhance your creative process.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('16ed6a4a389fdd5c284e47775b24d066','adobe-photoshop-m1-l6-lesson-5','80d0e1d511f54a6fe80c0f32e5bdcdaf','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Copyright and Licensing</h3><p>Copyright and Licensing</p><p>License:&#160;All Rights Reserved</p><p>When you work in a creative industry, it&#39;s easy for the line between ‘inspiration’ and ‘copying’ to get blurred.&#160;As designers, you should be the first to understand the importance of giving credit where credit is due.&#160;It is your responsibility as creatives to ensure that you are aware of where the content you are using is sourced from, whether it is a quote, an article, photos, artwork, music, or even icons and logos.&#160;There are serious legal and ethical considerations and ramifications of using content created by someone else.&#160;This video gives you an overview of what copyright is.</p><p>Video Title:&#160;Copyright and Fair Use</p><p>Video Publisher:&#160;Common Sense Education(opens in a new tab)</p><p>There are many different types of copyright, permissions and licensing options available, and you need to be aware of what can be used where.&#160;Here are some of the principle rules of copyright you should be aware of:</p><p>Click each term to learn more.</p><p>Academic standards</p><p>Academic standards&#160;for copyrighted material are higher than others. Researchers and scholars are considered experts in their fields and have a greater responsibility for sharing their opinions and ideas with the world. Because of this, they are held to higher standards of honesty and must give credit for all their research, including when they quote someone else’s words or even if they paraphrase those quotes in their own words. As a researcher, even if you paraphrase what someone else says, you still need to give them credit for it.</p><p>Copyright</p><p>Copyright is a form of&#160;legal protection for original works of authorship, whether unpublished or published, that is&#160;tangible and/or perceptible.</p><p>You can pay a &quot;licensing fee&quot; to use these assets under certain specified conditions, including but not limited to, number of uses, method of use, permission to edit or modify the asset, etc.</p><p>Creative Commons</p><p>A&#160;Creative Commons&#160;license is one of many public copyright licenses that allow the free distribution of “work” that is otherwise copyrighted. Creators use CC licenses when they want to give other people the right to freely share, use, modify, and build upon a work that they have created, in a bid to expand the range of creative works available to the public.</p><p>Derivative works</p><p>Derivative works&#160;are copyrighted materials that have been altered or changed. These materials are also protected by copyright laws. Let’s say you use Photoshop to make changes to a copyrighted photo. That photo is still protected by copyright laws and you may not use it without written permission.</p><p>Fair use doctrine</p><p>Fair use doctrine&#160;is part of the copyright laws and states that small portions of materials can be used without explicit written permission of the creator for certain purposes, like news reporting or school work. This doctrine doesn’t clearly define what “limited” means, so be careful of overusing material. This doctrine also requires that you must give credit to the creator of the material that you are using.</p><p>Intellectual property</p><p>Intellectual property&#160;is anything that a person has written or created. This can include artwork, text, photos, music, sounds, and so on.</p><p>Royalty Free</p><p>Royalty free&#160;assets are not &#39;free&#39; assets. They are copyrighted assets that you can purchase once and then use as many times as you want without the need to pay royalties or license fees for each “use”.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0e255909326cb133249c5bb6507a4b7d','adobe-photoshop-m1-l7-lesson-6','80d0e1d511f54a6fe80c0f32e5bdcdaf','Lesson 6','text',12,'<h2>Lesson 6</h2><section><h3>Release Forms</h3><p>Release Forms</p><p>License:&#160;All Rights Reserved</p><p>Just as you have copyright laws for using content created by other individuals, there are also rules in place that determine what you can and cannot take photos of and use commercially.</p><p>Legally, it is completely fine for you to videotape or photograph anything and everyone on public property within reasonable community standards.&#160;You do not need permissions to take photographs in these situations.&#160;You can even sell these pictures, as many photographers do to stock websites, product or media companies, etc.</p><p>Permissions come into the picture when you, or the buyer, choose to publish the photograph.</p><p>Model Release</p><p>A model release is a legal release signed by the subject of a photograph or video giving you permission to publish the photo or video in one form or another.</p><p>Location Release</p><p>A location release is a legal release signed by the owner or owners of a private property where you took photographs or videos giving you permission to publish the photo or video in one form or another.</p><p>As a photographer, it is not essential for you to get the model or location release for photographs you take unless you plan on publishing them yourself.&#160;But most professional photographers get the release forms signed because of the convenience.&#160;It gives them better chances of selling the photograph to a buyer who wants to publish the photo, without the hassle of having to find the people or locations in the photo and get releases signed after the fact.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c50e9f532cfb0f0c451bc1b843bf98e2','adobe-photoshop-m1-l8-module-1-summary','80d0e1d511f54a6fe80c0f32e5bdcdaf','Module 1 Summary','text',12,'<h2>Module 1 Summary</h2><section><h3>Summary</h3><p>Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on&#160;Working in the Design Industry Part I!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Understood the Adobe Creative Cloud and the role of the various applications.</p><p>Determined whether the content is relevant to the purpose, audience, and audience needs.</p><p>Demonstrated knowledge of techniques for communicating about design plans with peers and clients.</p><p>Demonstrated knowledge of basic project management concepts.</p><p>Identified legal and ethical considerations for using third-party content, such as copyright, permissions, and licensing.</p><p>Identified when and how to obtain permission to use images of people and locations.</p><p>Additional Resources</p><p>The following articles, videos, and websites are additional resources to learn more about this topic.&#160;(Not required reading)</p><p>Photography and the law(opens in a new tab)</p><p>Creative Commons(opens in a new tab)</p><p>Model release</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5b3506ae4edc8c58f67f0939e020a558','adobe-photoshop-m1-l9-module-1-project','80d0e1d511f54a6fe80c0f32e5bdcdaf','Module 1 Project','text',12,'<h2>Module 1 Project</h2><section><h3>Module 1 Project</h3><p>2400</p><p>Adobe Photoshop</p><p>Working in the Design Industry Part I - Project</p><p>Project</p><p>For this assignment, you will interview a member of the design or graphic design community to gain their perspective on working in the Design industry.</p><p>Find an interviewee who is working as a graphic designer or in the design industry, and who agrees to participate in the assignment.</p><p>The interview can be conducted in person, on the phone, virtually, or via email.</p><p>Prepare at least eight questions that cover topics from this module, such as:</p><p>Client communication and understanding your audience</p><p>Working with teams</p><p>Project management</p><p>Copyright and permissions</p><p>Be ready to ask follow-up questions, as needed, to prompt more in-depth discussion by the interviewee.</p><p>Your paper should be double-spaced and include:</p><p>Name of the person interviewed, and date and style of the interview (virtual, face to face, etc.)</p><p>Each question asked, followed by the interviewee’s answers.</p><p>A conclusion section (2 – 3 paragraphs in length) comparing what you learned from the interview and the concepts explored in this module.</p><p>Review the rubric below to see how you will be graded.</p><p>Working in the Design Industry Part I</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Interview Questions</p><p>8 points Interview questions are well designed to gain insight and perspective from the interviewee. Follow-up questions are used to effectively explore a topic further.</p><p>7-6 points Interview questions are adequately designed to gain some insight and perspective from the interviewee. Follow-up questions are used somewhat effectively to explore a topic further.</p><p>5-0 points Interview questions are poorly designed and unable to gain much insight and perspective from the interviewee. Follow-up questions are not used where needed.</p><p>8</p><p>Conclusion Paragraphs</p><p>8 points Includes in depth comparisons between the interview and course content, references specific details as evidence to support the comparisons made, and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete comparisons between the interview and course content, references some details as evidence to support the comparisons made, and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no relevant comparisons between the interview and course content, references no details as evidence to support the comparisons made, or does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Includes the required content and is formatted neatly.</p><p>1 point Does not include all required content or is not formatted neatly.</p><p>0 points Does not include all required content and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6aa261595c9a526c9db46a6ea2bc96cb','adobe-photoshop-m1-l10-module-1-quiz','80d0e1d511f54a6fe80c0f32e5bdcdaf','Module 1 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Design Industry Part 1. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('9c7468f447af0a19cfaa4ac78392f6ab','adobe-photoshop-module-2','ee9c9635d1344f63172dfbcc5883d9ea','Module 2: Design Industry Part 2',2) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5d6d1b2feb4b3ba207271b6cedba4db6','adobe-photoshop-m2-l1-introduction-purpose-and-objectives','9c7468f447af0a19cfaa4ac78392f6ab','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi everyone, and welcome back! This is the intro video for Working in the Design Industry, Part 2. In the last module, you took a step into the world of visual design and Adobe Photoshop. You learned about some critical aspects of working in the design world, both with teams and with clients. We also covered some important information about copyright permissions and licensing that you should always keep in mind.</p><p>Before you can learn about using Photoshop, you’ll need to be familiar with some of the common terminology used in the design industry. We’ll give you an introduction to basic design principles and best practices used in the design industry. To get the most out of Photoshop, you need to start thinking like a designer. How is color created in images? What are the key principles of design? How can you use typography to improve and enhance your design, while still being readable? What are the best ways to approach cinematic or photographic composition? What really makes a design ‘good’?</p><p>These are all questions that we’ll explore together in this module. Let’s get started!</p><p>Before you dive into Photoshop, you need to have a strong base knowledge of design principles and sensibilities.&#160;In this module, students will be introduced to digital image terminology.&#160;They will learn about the basic building blocks of design like color, typography, layout, and composition.&#160;They will also be introduced to fundamental design principles and techniques that will be very valuable as they progress in this course.</p><p>Objectives</p><p>In this module, students will:</p><p>Demonstrate knowledge of digital image terminology</p><p>Demonstrate knowledge of how color is created in digital images</p><p>Communicate visually using the elements and principles of design and common design techniques</p><p>Identify and use common typographic adjustments to create contrast, hierarchy, and enhanced readability/legibility</p><p>Demonstrate knowledge of common photographic/cinematic composition terms and principles</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8b0e1bdfc4a7c05dd80356abf8ff28b6','adobe-photoshop-m2-l2-lesson-1','9c7468f447af0a19cfaa4ac78392f6ab','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Key Terminology</h3><p>Key Terminology</p><p>The first thing you need to get familiar with is some of the common digital image terminologies that you will come across frequently throughout this course.</p><p>Image Size and Resolution</p><p>Pixels&#160;are the most basic building blocks of digital images.&#160;Just like paintings or drawings are made up of brush or pen strokes, images are made up of hundreds or thousands of pixels.&#160;Each pixel is just a block of color and a digital image is like a grid of pixels.</p><p>One important thing to remember is that unlike other units of measurement that you may use for printed photos, like centimeters or inches, a single pixel doesn’t have a fixed size.&#160;The size of a pixel depends completely on the resolution of an image.&#160;Confused?&#160;Don’t worry, we’ll explain this in detail very soon.</p><p>The size of a document is defined in terms of the&#160;pixel dimensions.&#160;This is basically a count of the total number of pixels in an image.&#160;In a digital format, images are measured in terms of their pixel dimension.&#160;If you look at the specifications on your camera or phone camera, you will see that it may be a 5MP or 8MP camera.&#160;“MP” here refers to “megapixels”, which is basically “a million pixels”.&#160;So a 5MP camera will take pictures that contain 5 million pixels in the image (approximately).</p><p>Talking about taking pictures, you know that the standard size in which images are printed is usually 4 inches by 6 inches, but you can print images in many different sizes.&#160;The size in which the picture is printed is called the&#160;print dimensions&#160;or&#160;print size&#160;of the image.</p><p>Now, this may sound like it is the same as the pixel dimension, but it isn’t, and there’s a straightforward explanation.</p><p>Let’s talk about&#160;image resolution.&#160;The resolution of an image is a measurement of the number of pixels per inch of a printed image.&#160;Now, here is what makes the distinction between pixel dimensions and print dimensions clear.&#160;Do you remember how we said earlier that pixels don’t have a fixed size?&#160;This means that you can have as many or as few pixels in an image as you want.&#160;All you need to do is change the image resolution.</p><p>For example, in the picture below, the face on the left has a very few pixels and you can just about make out the face and features.&#160;This is because it has a low number of pixels per inch of the face, i.e., a low resolution.&#160;On the other hand, the face on the right has a high number of pixels and therefore all the facial features are clearly defined.&#160;This part of the image has a high resolution.</p><p>Increasing the resolution of an image usually increases the quality and size of the image.</p><p>When you&#160;resize&#160;an image in Photoshop, you can either resize it or resample it.&#160;Resizing an image will keep the same number of pixels, but change the way the pixels are distributed within that document size.</p><p>Resampling&#160;refers to changing the amount of data in the image, that is the number of pixels in the image, by changing either the pixel dimensions or the resolution of the image.</p><p>You will learn more about how you can adjust all of these in your images further on in this course.</p><p>License:&#160;All Rights Reserved</p></section><section><h3>Bitmap and Vector Graphics</h3><p>Bitmap and Vector Graphics</p><p>Next, let’s discuss&#160;bitmap or raster graphics&#160;and&#160;vector graphics.</p><p>Bitmap graphics&#160;are technically called raster graphics and are made up of pixels.&#160;Vector graphics, on the other hand, are made up of lines and curves defined by mathematical objects called vectors.</p><p>Take a look at this video to understand the differences between the two, and in what situations you would use them.</p><p>Vector vs Raster Graphics</p><p>Video Title:&#160;Vector vs Raster Graphics</p><p>Video Publisher:&#160;Buddy Media</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6d71e776dfe5825b8ecfd2d5cc2274d9','adobe-photoshop-m2-l3-lesson-2','9c7468f447af0a19cfaa4ac78392f6ab','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Color in Digital Images</h3><p>Color in Digital Images</p><p>We’ve all learned the basics of how colors are created from a very young age.&#160;You know that there are three primary colors, red, blue, and yellow.</p><p>In digital images, colors are stored in&#160;channels&#160;of color.&#160;Channels are basically Greyscale images that store information about the color elements in an image.&#160;The color channels in an image are dependant on the color mode.&#160;You must have already heard of some of the more common color modes like RGB, CMYK, or Greyscale.&#160;The&#160;color mode&#160;of an image determines how colors combine in an image based on the number of channels in a color model.</p><p>For example, the RGB model is made up of red, blue and green color channels.&#160;So an RGB image will contain colors that are made by combining the primary colors together.&#160;These are known as&#160;additive primaries.&#160;Most computer monitors use the RGB mode to create colors.</p><p>Take a look at this video to understand the differences between RGB and CMYK color modes.</p><p>Design in 60 Seconds:&#160;RGB and CMYK Color Modes Explained</p><p>Video Title:&#160;Design in 60 Seconds:&#160;RGB and CMYK Color Modes Explained</p><p>Video Publisher:&#160;EnvatoTuts+</p><p>Here are some of the key things you should keep in mind when you use colors in your digital images and designs.</p><p>Beginning Graphic Design:&#160;Color</p><p>Video Title:&#160;Beginning Graphic Design:&#160;Color</p><p>Video Publisher:&#160;GCFLearnFree.org(opens in a new tab)</p><p>To read more about color channels, check out the links in the&#160;Additional Resources&#160;page at the end of this module.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('d930df3da0cdea9b4bda64e2e3a1a671','adobe-photoshop-m2-l4-lesson-3','9c7468f447af0a19cfaa4ac78392f6ab','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Fundamentals of Designs</h3><p>Fundamentals of Designs</p><p>If you break down any design to its most fundamental components, you will see that it is made up of a few common components—space,&#160;line,&#160;shape,&#160;form,&#160;color&#160;or&#160;texture, and&#160;balance.</p><p>All of these terms are self-explanatory.&#160;But how do they come together to form a design?&#160;Take a look at this video that explains some of the fundamentals of design.</p><p>Beginning Graphic Design:&#160;Fundamentals</p><p>Video Title:&#160;Beginning Graphic Design:&#160;Fundamentals</p><p>Video Publisher:&#160;GCFLearnFree.org</p></section><section><h3>Principles of Graphic Design</h3><p>Principles of Graphic Design</p><p>What truly makes a design effective?&#160;Is it all subjective or are there basic principles that guide the way designs are structured and created?&#160;The Gestalt Principles&#160;can help you understand design better.</p><p>The word ‘gestalt’ is a psychology term that refers to a whole that is greater than the sum of its parts.&#160;When you look at a painting, the entire painting first makes an impact on you before you are able to notice the individual parts of the painting.</p><p>Let’s say that I tell your entire class to paint a bowl of fruit from memory in your own style or composition.&#160;The painting should include, at the very least, a bowl and fruit.&#160;You can choose to include other elements as you please.&#160;Now, all of these components of the painting can be arranged in an infinite number of ways, and every person in your class will have a different interpretation.</p><p>Let’s take a look at the Gestalt Principles that help define approaches you can take to create a coherent, connected design.</p><p>This video explains some key principles of graphic design as they would be applicable to you working in digital programs like Photoshop.</p><p>Gestalt Psychology and Why It&#39;s Essential for Good Design</p><p>Video Title:&#160;Gestalt Psychology and Why It&#39;s Essential for Good Design</p><p>Video Publisher:&#160;HubSpot</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4192681682a183b7343924402a46c8eb','adobe-photoshop-m2-l5-lesson-4','9c7468f447af0a19cfaa4ac78392f6ab','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Typography</h3><p>Typography</p><p>Text and typography is an often undermined but essential part of a design.&#160;It&#39;s everywhere you look if you think about it.&#160;From your computer or phone screens to any of the products you use, to signs and signals on the roads and shop fronts, typography is a key part of how we communicate.&#160;A font can make or break your design.&#160;Just think of the Coca Cola logo in a different font, would you even recognize it?</p><p>This video gives you a great explanation of the importance of typography, as well as different ways in which you can use typography to enhance and boost your designs.</p><p>Beginning Graphic Design:&#160;Typography</p><p>Video Title:&#160;Beginning Graphic Design:&#160;Typography</p><p>Video Publisher:&#160;GCFLearnFree.org</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b8b5f6f3e273c4798e2594280b487d5c','adobe-photoshop-m2-l6-lesson-5','9c7468f447af0a19cfaa4ac78392f6ab','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Design and Composition</h3><p>Design and Composition</p><p>You have the fundamentals in place, but what really makes a good design?&#160;Let’s say you’ve taken a beautiful picture, created fantastic graphical elements, chosen a great color palette and fonts.&#160;You have all the ingredients for brilliant design, but unless you put them together in the right way, you’ll be left with a bad taste in your mouth.</p><p>There are some basic tenets of design that must be applied for a design to be truly considered good or appealing.&#160;One key factor is the layout and composition of your designs.&#160;Take a look at this video to learn more.</p><p>Beginning Graphic Design:&#160;Layout &amp; Composition</p><p>Video Title:&#160;Beginning Graphic Design:&#160;Layout &amp; Composition</p><p>Video Publisher:&#160;GCFLearnFree.org(opens in a new tab)</p><p>Here are some tips and techniques that you can use to ensure your designs are composed and arranged in a way that makes them stand out.</p><p>Strong Focal Point</p><p>License:&#160;All Rights Reserved</p><p>This is an important factor when you create designs as well as when you take photographs.&#160;Choose a focal point that helps you get your message across in the best possible way.&#160;Think about your design approach, what is the key focus of the image?&#160;Where do you want viewers to look as soon as they look at their image?&#160;These questions will help you frame your designs and photos better.</p><p>Contrast</p><p>Contrast is a very powerful tool that you can use to highlight and hide elements of your design.&#160;Use a feature color in an otherwise simplistic design to make the design pop.&#160;Use more neutral elements to balance out the design.</p><p>White Space</p><p>Mathematicians will tell you that the zero is possibly the most important number of all.&#160;Similarly, in design, you cannot forget the importance of ‘empty space’ or white space.&#160;You can use white space to create contrast, create focus, boost and enhance the design, all while keeping the design simplistic and clean.</p><p>License:&#160;All Rights Reserved</p><p>Compositional Flow</p><p>When you take a photograph, do you find yourself adjusting your position, angle, and light because it doesn&#39;t quite look &quot;right&quot;?&#160;You can take ten pictures of a boat out at sea that all have the same elements in them, but you pick the best one because of its composition.</p><p>Composition refers to how the different elements of a design are arranged.&#160;Compositional flow&#160;is what determines how your eye is led through this design.&#160;Where do your eyes go the first second you look at an image or design?&#160;Where does it go next?&#160;What catches your eye?</p><p>Until now, you would have unconsciously used this to judge what designs look good to you.&#160;If you think about this consciously when creating a design, you can use this to determine where to place the most important information first.&#160;For example, if you are creating an advertisement flyer and want people to take advantage of a sale, make your flyer is designed such that your eyes are drawn first to the &quot;SALE&quot; or &quot;BUY NOW&quot; sections of your design.</p><p>Rule of Thirds</p><p>The rule of thirds is a very basic but highly effective technique that artists and designers have been using for decades.&#160;Divide your page into three columns and three rows.&#160;The rule of thirds states that the main focal points of your image should be at the points where the lines intersect.</p><p>You can test this out by picking a design that you like from a magazine or printing out a design and drawing the lines over it to see where they intersect.</p><p>License:&#160;All Rights Reserved</p><p>Use the links in&#160;the Additional Resources&#160;section at the end of this module to learn more.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('dc100f27315fd3cb3c477e5b9c54d59d','adobe-photoshop-m2-l7-summary','9c7468f447af0a19cfaa4ac78392f6ab','Summary','text',12,'<h2>Summary</h2><section><h3>Module 2 Summary</h3><p>Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Working in the Design Industry Part II!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this session, you:</p><p>Demonstrated knowledge of digital image terminology.</p><p>Demonstrated knowledge of how color is created in digital images.</p><p>Communicated visually using the elements and principles of design and common design techniques.</p><p>Identified and use common typographic adjustments to create contrast, hierarchy, and enhanced readability/legibility.</p><p>Demonstrated knowledge of common photographic/cinematic composition terms and principles.</p><p>Additional Resources</p><p>The following websites are additional resources to learn more about this topic.&#160;(Not required reading)</p><p>RGB and Color Channels in Photoshop Explained(opens in a new tab)</p><p>Essential Photoshop Color Settings</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7f629f0fbbda78c706ce217de7cf2abc','adobe-photoshop-m2-l8-module-2-project','9c7468f447af0a19cfaa4ac78392f6ab','Module 2 Project','text',12,'<h2>Module 2 Project</h2><section><h3>Module 2 Project</h3><p>2400</p><p>Adobe Photoshop</p><p>Working in the Design Industry Part II - Project</p><p>Project</p><p>In this assignment, you will use what you’ve learned about basic design principles and digital image terminology to write an essay.</p><p>Pick a piece of artwork of your choice to base your essay on. This can be a classical painting, modern digital artwork, or even a print advertisement that you found visually appealing.</p><p>Write a two-page, double-spaced paper on your assessment of the artwork based on the following factors:</p><p>The visual appeal of the artwork, why you think it is appealing, and how that ties into the basic principles of design.</p><p>The use of color and/or typography in the artwork and an evaluation of how they have been used to create contrast, visual impact, etc.</p><p>The composition of the image.</p><p>Review the rubric below to see how you will be graded.</p><p>Working in the Design Industry Part II Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Understand basic principles of design</p><p>8 points The student demonstrates an understanding of the basic principles of design and common design techniques.</p><p>7-6 points The student demonstrates an adequate understanding of the basic principles of design and common design techniques. The essay contains some accurate details and concepts.</p><p>5-0 points The student demonstrates little to no understanding of the basic principles of design and common design techniques, and the essay contains inaccurate details or little to no explanation of concepts.</p><p>8</p><p>Understand use of color and typography</p><p>8 points The student demonstrates an understanding of the use of color and typography in designs.</p><p>7-6 points The student demonstrates an adequate understanding of the use of color and typography in designs. The essay contains some accurate details and concepts.</p><p>5-0 points The student demonstrates little to no understanding of the use of color and typography in designs. The essay contains inaccurate details or little to no explanation of concepts.</p><p>8</p><p>Understand image layouts and composition</p><p>8 points The student demonstrates an understanding of image layouts and composition.</p><p>7-6 points The student demonstrates an adequate understanding of image layouts and composition. The essay contains some accurate details and concepts.</p><p>5-0 points The student demonstrates little to no understanding of image layouts and composition. The essay contains inaccurate details or little to no explanation of concepts.</p><p>8</p><p>Total Points:&#160;24</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('bcfb5ef4ec04d35b06d1b71ad9cc5a86','adobe-photoshop-m2-l9-module-2-quiz','9c7468f447af0a19cfaa4ac78392f6ab','Module 2 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Design Industry Part 2. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('a8b683f68c9695b78a6b50708f7615ec','adobe-photoshop-module-3','ee9c9635d1344f63172dfbcc5883d9ea','Module 3: Setup and Interface Part 1',3) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('15078ad91c50003f155799e77e237355','adobe-photoshop-m3-l1-introduction-purpose-and-objectives','a8b683f68c9695b78a6b50708f7615ec','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi, welcome back! This is the intro video for the module on Project Setup and Interface Part 1. In the last two modules, we’ve already laid down some of the foundational elements and critical concepts of this Photoshop course. You got an insight into the big picture of working in the design industry. You also learned about crucial design principles and techniques, as well as common graphic design terms and their definitions.</p><p>Now, it’s finally time to dip our toes into Photoshop! Let’s dive into Project Setup and Interface.</p><p>In this module, you will get comfortable with some very important Photoshop basics. You will learn how to setup a new project in Photoshop and the various program settings available. You’ll learn about key concepts like resolution, orientation and color modes. Before you can actually use Photoshop, you need to get comfortable with all of the elements of the Photoshop interface. So, we’ll walkthrough all the fantastic tools in the Photoshop interface that you can use to bring your designs to life. And, as with any project, it is always important to stay organized, so we’ll show you how you can completely organize and customize your Photoshop workspace. You can show, hide, nest and dock various panels, and you can even save custom workspaces for different projects to help you achieve maximum efficiency. So, let’s get started!</p><p>Module Description</p><p>License:&#160;All Rights Reserved</p><p>The Photoshop Interface is a treasure trove of useful tools and settings.&#160;The first step for any beginner user of Photoshop is to get acclimatized with the interface so they can begin to identify the different sections and tools available.&#160;Students will learn how to get started with Photoshop by creating a new document.&#160;They will also get an overview of all the elements of the Photoshop interface and their functions.&#160;Finally, students will learn how to customize the Photoshop workspace and preferences in a way that is both convenient and efficient.</p><p>Objectives</p><p>In this module, students will:</p><p>Set appropriate document settings for printed and onscreen images</p><p>Create a new document preset to reuse for specific project needs</p><p>Identify and manipulate elements of the Photoshop interface</p><p>Organize and customize the workspace</p><p>Configure application preferences</p><p>Polling Question</p><p>Have you ever used Photoshop before?</p><p>Yes&#160;No</p><p>Results:</p><p>Yes&#160;100%</p><p>Which of these tasks can be done using Photoshop?</p><p>Edit photographs</p><p>Design websites and mobile apps</p><p>Edit videos</p><p>Illustrate original art</p><p>All of the above</p><p>Results:</p><p>Edit photographs&#160;100%</p><p>How many of your classmates have dabbled in Photoshop?&#160;Did you know that you can do all of these tasks using Photoshop?&#160;Let&#39;s dive in and learn more.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b567e6ab7f774e7fb9d12a8f62135dc7','adobe-photoshop-m3-l2-lesson-1','a8b683f68c9695b78a6b50708f7615ec','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>New Documents in Photoshop</h3><p>New Documents in Photoshop</p><p>There are two ways in which you can start working with Photoshop.&#160;You can either open an existing image in Photoshop, or you can create a new document in Photoshop.</p><p>Note:&#160;These screenshots may look a little different depending on the version of Photoshop you are using, but the basic functions will remain the same.</p><p>Usually, you would open an existing image in Photoshop if you want to edit a photograph or video.&#160;Opening images is quite different from creating new documents, and we’ll discuss this further in later modules.</p><p>When you create a new document in Photoshop, you are basically starting with a blank canvas.&#160;If you choose to create a blank document, you can then import images, graphics, photos, or other design assets into your document.&#160;This is an ideal option if you want to create a design layout from scratch, for example, flyers, posters, cards, etc. You just need to create a new blank document with the correct dimensions you need and just add all the components required.</p><p>You can also use this option to explore your creativity and draw or paint digital illustrations and paintings.&#160;Photoshop gives you a whole array of brushes, pens and various other tools to adjust colors, effects, and more.&#160;You can also scan and import your own drawings or designs and combine multiple images.</p><p>So, let’s see how you can easily create a new document in Photoshop.</p><p>Creating a New Document in Photoshop</p><p>To create a new document in Photoshop, you need to use the New Document dialog box.&#160;There are a few ways in which you can do this.&#160;When you launch Photoshop, you will see the&#160;Start&#160;screen.&#160;Simply click the&#160;Create New&#160;or&#160;Start New&#160;button.</p><p>Opening a new document:&#160;Option 1</p><p>You can also use the File menu to open a new document.&#160;Just click&#160;File&#160;in the top&#160;Menu&#160;bar and click&#160;New.</p><p>Opening a new document:&#160;Option 2</p><p>You can also use the keyboard shortcut&#160;Ctrl+N&#160;(Windows) or&#160;Command+N&#160;(Mac) to open a new document.</p></section><section><h3>Exploring the New Document Window</h3><p>Exploring the New Document Window</p><p>Let’s explore all the elements you see here in the&#160;New Document&#160;window.</p><p>Photoshop New Document</p><p>Along the top of the window, you can see several categories;&#160;Recent,&#160;Saved,&#160;Photo,&#160;Print,&#160;Art &amp; Illustration,&#160;Web,&#160;Mobile, and&#160;Film &amp; Video.</p><p>By default, when you create a blank document, the&#160;New Document&#160;window always opens on the&#160;Recent&#160;tab.&#160;If you have recently been working on any documents, you will see those in the area below.</p><p>The&#160;Saved&#160;tab will contain custom presets that you have created and saved.&#160;You’ll learn more about what presets are in just a little while.</p><p>When you click any of the categories that you see on the top of the New Document window,&#160;you will see two sections below,&#160;Blank Document Presets&#160;and&#160;Templates, and you will also see a sidebar called&#160;Preset Details.</p><p>Let&#39;s take a detailed look at all the settings in the&#160;Preset Details&#160;column.</p><p>Both templates and presets are categorized into the tabs that you see at the top of the window,&#160;Photo,&#160;Print,&#160;Art &amp; Illustration,&#160;Web,&#160;Mobile, and&#160;Film &amp; Video.</p><p>Blank Document Presets&#160;are basically blank documents that have pre-defined settings like dimensions, resolution, etc. As you can see, the ones displayed above are of different sizes, so you can choose the one best suited to the device or project you’re working on.&#160;You can also click the&#160;View All Presets&#160;link here to view all the available presets.</p><p>You also have the option to choose from a number of&#160;templates&#160;from Adobe Stock that already come with reusable elements, graphics, layouts and illustrations that you can use for your documents.&#160;Simply select a template and customize it for your document.&#160;You can also search for templates using the&#160;Search&#160;bar at the bottom of the window.</p><p>Next, let’s discuss the&#160;Preset Details&#160;column on the right.&#160;When you select a preset from the list of provided presets, you will see all of its specifications in the&#160;Preset Details&#160;section.&#160;You can use this section to modify the settings of any preset.</p><p>Click each hotspot on the image to learn more.</p><p>5</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Screenshot showing the Preset Details section</p><p>The hotspot points on the image are as follows:</p><p>Width and Height</p><p>These denote the size of the document. You can also specify the unit of measurement to use form the drop-down menu.</p><p>Orientation</p><p>You can choose if your document should be in Landscape or Portrait orientation.</p><p>Artboards</p><p>An artboard is like a layer in your document. You can choose whether your document should have artboards here.</p><p>Resolution</p><p>The resolution of an image is basically the number of pixels per inch of the image, and it determines the fineness of detail in the image. The higher the number of pixels, the greater the resolution and quality of the image. Here, you can adjust the resolution of your document. 300 is usually the standard resolution for print.</p><p>Color Mode</p><p>Here, you can choose the color mode for your document. You can choose from options like RGB, CMYK, Grayscale and others. RGB is the most commonly used setting.</p><p>Bit Depth</p><p>You also have the option to change the document’s bit depth and can choose from 8 bit, 16 bit or 32 bit. The bit depth denotes the number of bits needed to store color in an image. The higher this value is, the more accurate the color representation in the image. In most cases, you can leave this as 8-bit.</p><p>Background Contents</p><p>You also have the option of choosing a background color for your document. You can choose black, white, or any custom color using Photoshop’s color picker. You can also choose to have a transparent background for your document.</p></section><section><h3>Creating a New Document Using Presets</h3><p>Creating a New Document Using Presets</p><p>Now, l<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2be24c9793cb3e1ca7f19e7f06b42b83','adobe-photoshop-m3-l3-lesson-2','a8b683f68c9695b78a6b50708f7615ec','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Modify and Save Custom Presets</h3><p>Modify and Save Custom Presets</p><p>You’ve already seen how easy it is to create a new document using Photoshop presets.&#160;But many times, you may need to change the settings based on what you want to create.&#160;Let’s see how you can modify and save custom presets.</p><p>Custom Preset Settings</p><p>You know that all of the settings of a preset are shown in the&#160;Preset Details&#160;column.&#160;So, let’s say you have selected this Photo preset,&#160;Landscape 8 x 10.</p><p>You can modify the&#160;Height&#160;and&#160;Width&#160;values here to anything you want.&#160;You can also click the measurement unit box and select a different unit of measurement.</p><p>You can easily change the orientation of the document by clicking the&#160;Portrait&#160;icon here.&#160;You’ll see that the Height and Width values immediately get swapped.</p><p>And in this way, you can change all of the other settings of your document as well.&#160;For instance, you can change the&#160;Color Mode&#160;of the document and choose one of the other color modes like Grayscale or CMYK.&#160;Since you are just starting to learn about using Photoshop, it is recommended that you stick to RGB.</p><p>Check the&#160;Resources&#160;page at the end of this module to learn more about RGB and other color modes.</p><p>You can also change the&#160;Bit Depth&#160;of the document to&#160;16-bit&#160;or&#160;32-bit.&#160;Again, as you are just starting out, you can leave this as 8-bit.</p><p>Check the&#160;Resources&#160;page at the end of this module to learn more about bit depth and how it affects the quality of your documents and images.</p><p>Next, you can change the background color of your document to black or any other you want.</p><p>Once you have made all the changes you want, you can easily save this as your own custom preset.&#160;Enter your own name for the preset.&#160;Ideally, you should make this a descriptive name so that you can easily identify it when you search for it the next time.&#160;To save the custom preset, just click the&#160;Save&#160;icon at the top and you’re done!</p><p>Let’s see an example of how this is done.</p><p>Often, when you’re creating a new document in Photoshop, you may not find a preset that meets all your requirements. Let’s say that you want to create a document with the dimensions 11x15 inches. If you look through the presets available here, none of these have the settings that you want.</p><p>You can easily modify one of these presets to create a custom preset. Let’s choose this preset and in the&#160;Preset Details&#160;panel, all you need to do is to change the&#160;Height&#160;and&#160;Width&#160;dimensions. So let&#39;s change the height to&#160;11&#160;and the width to&#160;15. Now let&#39;s say that instead of a portrait orientation you want a landscape orientation. So let&#39;s just change that as well. And finally, let’s change the&#160;Background Contents. If you click this drop-down list, you&#39;ll see that you have the option to choose from&#160;White, Black,&#160;or the default&#160;Background Color&#160;of Photoshop. You also have the option to select a custom color. Just click this tile right here. This pulls up the Photoshop&#160;Color Picker. If you know the values of the color that you want to pick, then just enter those right here. If not, just select a color from this palette here, click the&#160;OK&#160;button, and that&#39;s it!</p><p>Once you’ve made all the changes to the settings that you need, click the&#160;Create&#160;button. Now, if in case, you need to use this preset again for another document, instead of having to come in here and make all of these changes again, what you can do is to simply click this&#160;Save&#160;button right. Give this preset a name. For this example, let’s just name this&#160;Demo, 11 x 15&#160;and click the&#160;Save Preset&#160;button.</p><p>And as you can see, under the&#160;Saved&#160;tab, here is the preset that you saved. So, the next time you need to create a document using this preset, just select it from here and click the&#160;Create&#160;button and here is your new&#160;document.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7524220723706cb0a2e0af477682949e','adobe-photoshop-m3-l4-lesson-3','a8b683f68c9695b78a6b50708f7615ec','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Photoshop Interface</h3><p>Photoshop Interface</p><p>Now that you’ve learned how to create a new document in Photoshop, let’s explore the Photoshop interface.&#160;Photoshop is packed with a large number of features and tools that are categorized into different sections.&#160;The best part about Photoshop is that you can modify and customize all these sections to suit your needs and create your own personal workspace.</p><p>When you open an image in Photoshop, this is what the Photoshop interface looks like.</p><p>Photoshop Interface</p><p>Document Window:</p><p>This is one of the biggest sections of the Photoshop interface and is where your document or image will be displayed.&#160;This is where you will create and edit your document.</p><p>Document Tabs:</p><p>You can open multiple documents in Photoshop.&#160;All of these documents open in different document windows that are tabbed.</p><p>You can also group or dock document windows in some cases.&#160;The tab shows you the name of the document, the type of file it is, and the zoom level it is at.&#160;You will learn more about working with multiple documents later in this course.</p><p>Tools Panel or Toolbar:</p><p>The toolbar or the tools panel is on the left of the Photoshop interface.&#160;This panel contains all of the tools that you will use to edit your documents, images, artwork, etc. You can find a&#160;tool for everything from selecting and cropping images to painting, drawing, and adding various shapes to your image.</p><p>In the default view, the toolbar appears as a single, long column of tools.&#160;You can easily expand the toolbar by clicking the double-arrows at the top of the toolbar—this view displays the same tools, just in two shorter rows.</p><p>Most of these tools are grouped into categories based on their functions.&#160;We’ll go into the details of how to use these tools later in the course, but for now, here’s an overview of the different categories of tools you will find.&#160;The screenshot here shows the different categories separated by color:</p><p>A:&#160;Selection Tools:&#160;Use these to select and move sections of your document or image in different ways.</p><p>B:&#160;Crop and Slice Tools:&#160;Use these tools to crop, slice or select sections of your document or image.</p><p>C:&#160;Measuring Tools:&#160;Use these to measure and select colors and objects on a document or image.</p><p>D:&#160;Retouching Tools:&#160;Use these for a myriad of functions including photo corrections, editing, painting,&#160;and other enhancements.</p><p>E:&#160;Painting Tools:&#160;These are a set of various brushes, pens and paint tools that you can use to create drawings and paintings.</p><p>F:&#160;Drawing and Type Tools:&#160;Use these tools to add drawings and text to your documents.</p><p>G:&#160;Navigation Tools:&#160;Use these tools to move, rotate and zoom into your document or image.</p><p>This may seem like a lot of tools to you, but Photoshop actually has many more tools.&#160;Did you notice that some of these icons have a little triangle at the bottom corner?&#160;This just means that this is a nested tool&#160;or a combination of multiple similar tools.&#160;You’ll learn more about using all of the tools in the Toolbar in a later module.</p><p>Options Bar</p><p>Next, we have the Options bar.&#160;The Options bar appears at the top of the Photoshop window, right below the Menu bar, and it shows the options for whichever tool you have selected in the Tools panel.</p><p>For example, in the screenshot below, the Rectangular Marquee tool is selected, and you can see the options related to it in the Options bar above.</p><p>Now, if you go ahead and select another tool, like the&#160;Crop&#160;tool, you will see that the Options bar has changed to the settings for the Crop tool.</p><p>Menu Bar</p><p>This is a standard element of most applications.&#160;The Menu bar runs across the top of the Photoshop window and has all the main program-level functions and commands grouped into various categories.&#160;For example, you can use the&#160;File&#160;menu to save your work.&#160;You can use the&#160;Edit&#160;menu to set preferences and make many different types of changes to the Photoshop interface as well.&#160;We won’t go into all of the Menu functions here and will cover relevant functions as we move on in the course.&#160;Feel free to explore all the Menu options on your own.</p><p>Panels and Panel Groups</p><p>On the right side of your Photoshop window, you will see a column of boxes that are called Panels.&#160;Panels are designed to help you monitor and modify your work as you go along.&#160;You can stack, group or dock panels in various configurations to make your workspace more usable.</p><p>Because there are so many different types of panels available, Photoshop groups similar panels together into Panel Groups.&#160;Take a look at this screenshot here.&#160;There are three key panel sections or groups; the&#160;Color Panel, the&#160;CC Library Panel&#160;and the&#160;Layers Panel.</p><p>Color Panel:</p><p>This panel will show you the color values for the foreground and background colors in your document or image.&#160;You can use this panel to adjust the color levels, change the color models, or choose background or foreground colors.</p><p>CC Library Panel:</p><p>The Libraries panel will contain assets you have created earlier in Photoshop as well as other Adobe CC tools like Illustrator, InDesign, etc. It makes it easier for you to reuse and share assets.&#160;You can also upload assets into the library for future use.</p><p>Layers Panel:</p><p>This is the most important panel because this is where you will add, delete, and edit the layers of your document or image.&#160;What is a&#160;layer?&#160;Well, do you remember the scene from Iron Man where Tony Stark draws the initial design for the Iron Man suit on multiple layers of tracing paper?&#160;Each sheet is like a layer in Photoshop that you can use to create complex designs and documents.</p><p>You will learn more about working with the different panels in the coming modules.</p><p>Workspaces</p><p>Workspaces in Photoshop are basically a preset arrangement of the various interface elements.&#160;They determine which panels are displayed, how they are arranged, what tools are shown, etc.</p><p>Why do we have Workspaces?&#160;Because Photoshop is such a versatile tool, there are so many different types of people that can use it for <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7710ef8a98f9d2e5c93768e7fc1ddcfa','adobe-photoshop-m3-l5-lesson-4','a8b683f68c9695b78a6b50708f7615ec','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Manage Documents</h3><p>Manage Documents</p><p>In this lesson, we’ll go into all the ways in which you can customize your Photoshop workspace.&#160;Photoshop is very versatile and allows you to move, group, and manipulate your Document windows and panels.&#160;Let’s first see how you can manage multiple documents in Photoshop.</p><p>You can open multiple images in Photoshop. You can see here that I have three images open, and Photoshop displays them as&#160;tabbed document windows. You can easily switch between the images just by clicking on the tabs. If you are more comfortable using keyboard shortcuts, you can just use&#160;Ctrl + Tab (Windows)&#160;or&#160;Control + Tab (Mac)&#160;to switch between tabs. You can also easily change the order of the tabs. Simply click and drag them to the left or right position and drop them.</p><p>There is another way in which you can view your images in Photoshop, and that is as a&#160;Floating Document Window. Just click and hold a tab and drag it away from the other tabs. It will undock and separate from the group and appear as a “floating” window. You can do this to all of the other tabs as well. To dock the image again, simply click the header and drag it back to the tabs.</p><p>You can also use the Menu to dock and undock the images. Let’s say you want to make all images floating windows. Click&#160;Window, select&#160;Arrange&#160;and click&#160;Float All in Windows. As you can see here, all three images are in floating windows. To dock all of these images again, just click&#160;Window&#160;again, select&#160;Arrange&#160;and click&#160;Consolidate All to Tabs,&#160;and all images have been docked again as tabs.</p></section><section><h3>Manage Panels</h3><p>Manage Panels</p><p>Panels are a large part of the Photoshop interface, and you will use them extensively when you work in Photoshop.&#160;There are many ways in which you can modify, manipulate and customize panels.&#160;This can seem very overwhelming if you are new to Photoshop, but we’ll go over how you can easily organize your panels.</p><p>Photoshop panels appear in a column on the right side of the Photoshop interface. They are usually grouped in 2-3 tabs based on their functions. You can rearrange these tabs in many different ways. Let’s start off with seeing how to&#160;dock and undock panels. A dock is basically a collection of panels or panel groups that are displayed together. You can dock and undock panels by moving them.</p><p>To move a single panel, just click and hold the panel and drag it away from its dock. As you are moving this panel, you can see&#160;blue highlighted areas. These are basically potential drop zones where you can dock the panel. Just drop the panel in a drop zone and it will get re-docked. If you move this panel to an area that is not in the drop zone, it floats freely and is basically a&#160;floating panel.</p><p>You can also move entire panel groups. Just select and hold the title bar of the panel group and drag it out of the dock. You can move and re-dock this in the same way as you did with the panels.</p><p>You can also create a vertical dock like this, which is also knowns as the&#160;secondary panel&#160;if that is more convenient for you. To expand the secondary panel, just click the double arrows at the top, and to collapse this, just click the arrows again. This will give you a wider document window to work in.</p><p>Now let’s see how you can&#160;add and remove panels. Photoshop has a ton of panels that you can add to your workspace. Click the&#160;Window&#160;button in the top&#160;Menu&#160;bar. This is a full list of all of the available panels in Photoshop. To add any of these to the workspace, just select it. You&#39;ll see that it has been added to the secondary panel here. You can click the double arrows to collapse it. You can then move this and reposition it to wherever you want.</p><p>To remove a panel, just right-click it and select&#160;Close. You can also click this icon here and select&#160;Close&#160;to close just this panel, or&#160;Close Tab Group&#160;to close this entire tab group. I&#39;ll select&#160;Close.</p><p>You can very easily resize panels. Just drag any side of the panel to resize it. You know that when you drag a panel out of the dock and not into another drop zone, it becomes a floating panel. Let&#39;s say you have multiple floating panels. You can also stack them together so that they move as a single unit. To stack a floating panel, just drag the panel to the bottom of another panel, and you&#39;ll see the blue highlighted area again; drop it here. Now, both these panels will act as a single floating panel.</p><p>As you can see, there are a ton of ways in which you can move the panels around and arrange them based on your requirements. Now, let’s say you moved the panels around but now you want to reset it to how it was originally. No problem! Just click the&#160;Workspace&#160;icon and select&#160;Reset Essential. All of your panels will be reset to the default Essentials layout.</p></section><section><h3>Manage Workspaces</h3><p>Manage Workspaces</p><p>You have learned about all the elements of the Photoshop interface, the toolbar, menus, document windows, and panels.&#160;You have also learned how you can customize all these elements.&#160;Now, let’s see how you can save your workspace so that you can use the same settings the next time you use Photoshop, and how you can delete or reset the workspace.</p><p>When you open Photoshop, the default workspace you see here is the Essentials workspace. Once you rearrange the panels or toolbar to suit your preferences, you need to have a way to save this workspace so that you can use it again. To save your custom workspace layout, all you need to do is click&#160;Window, select&#160;Workspace&#160;and then click&#160;New Workspace. You can also click the&#160;Workspace&#160;icon and then click&#160;New Workspace.</p><p>Now just name this workspace whatever you want; I’ll name this “Demo”. As you can see here, all of your panel locations will be saved in this workspace. You also have the option to save any custom keyboard shortcuts you may have created, as well as any custom menus or toolbars. Here, I&#39;ve changed the toolbar to a two-panel view, so I&#39;ll just select&#160;Toolbar&#160;and click&#160;Save. Now, any time you click the&#160;Workspace&#160;icon, you will see the new workspace listed here.</p><p>Now let’s say that after a while o<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('696eeb3d0761703e0f2ea39b54e79634','adobe-photoshop-m3-l6-lesson-5','a8b683f68c9695b78a6b50708f7615ec','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Setting Application Preferences</h3><p>Setting Application Preferences</p><p>For you to be able to use Photoshop efficiently and comfortably, it’s important for you to be able to customize it based on how you work and what your preferences are.&#160;In this lesson, we’ll cover some of the settings and preferences that can help you fully personalize your Photoshop experience.</p><p>You have learned all about customizing the Photoshop interface, but there are other back-end preferences that you can modify to improve its performance and efficiency.&#160;Photoshop has all sorts of preferences that you can modify, and they are divided into multiple categories, but we’ll just go over the most important ones you need to know about as a beginner.</p><p>First, let’s talk about how you can access the&#160;Preferences&#160;window.&#160;If you are using Windows, just click&#160;Edit&#160;in the&#160;Menu&#160;bar and select&#160;Preferences&#160;and click&#160;General.&#160;On a Mac, click the&#160;Photoshop&#160;menu, select&#160;Preferences&#160;and click&#160;General.</p><p>There are many categories listed here on the left.&#160;You will learn more about them as you begin to use Photoshop.</p><p>Interface Preferences</p><p>Now, if you click&#160;Interface, you will see all of the options available that let you customize the Photoshop interface.&#160;From here, you can control the background color, theme, font sizes, how the menu appears, etc. This is another way you can customize Photoshop to your preferences.</p><p>Tools Preferences</p><p>If you click the&#160;Tools&#160;tab, you will see the different tool-related preferences that you can set.</p><p>Since you are starting off with Photoshop, Tooltips would be a very useful tool for you to use.&#160;Make sure the&#160;Show Tooltips&#160;checkbox is selected.&#160;Just roll your cursor over an icon or button, you will see a short description of the object.&#160;They are a great tool to learn about the different options available in Photoshop.</p><p>Performance Preferences</p><p>This is another useful section that will help you improve the performance of Photoshop if it is sluggish or slow at times.</p><p>The&#160;Memory Usage&#160;section will show you how much of your computer’s memory is reserved to be used by Photoshop.&#160;The default value here is 70%, but you can increase this if you feel like Photoshop is running slow.</p><p>Tip:&#160;When you work on Photoshop, it is best that you keep the usage of other programs or applications to a minimum.&#160;Photoshop is a heavy application and uses a large portion of your computer’s memory, so for optimal performance, close all other applications you aren’t using.</p><p>Scratch Disks Preferences</p><p>Next, let&#39;s learn about scratch disks.</p><p>A&#160;scratch disk&#160;is a section of your computer&#39;s hard drive that Photoshop uses as additional memory if it runs out of system memory.&#160;If your computer has enough memory, Photoshop will not need to use the scratch disk.&#160;But if it does, it will use the hard drive you have selected in this section.</p><p>This option is usually only relevant if you have multiple drives.&#160;In many cases, you may have only one main hard drive or Startup disk in your computer.&#160;In this case, it will be selected by default as you can see here.&#160;If, however, you have multiple drives, you can select another drive as the scratch disk.&#160;Since your operating system uses the main Startup disk extensively, it is better to choose another drive as your backup for Photoshop so as to get better performance.</p><p>Additionally, if you know the speeds of your hard drives, you can choose the faster hard drive here for better performance.</p><p>Units &amp; Rulers Preferences</p><p>Rulers in any application help you position images or objects on your document in a precise manner.&#160;You will usually see rulers across the top and left sides of the window.&#160;Rulers have markers that will show you where the pointer is when you move it over your document.</p><p>In Photoshop, you can change the unit of measurement of the rulers.&#160;There are also other settings to modify units for various elements like the Preset resolution, Column size, etc.</p><p>Grids, Guides &amp; Slices Preferences</p><p>The grid and guides are tools that have a similar function to rulers; they help you position or align images or objects on your document.</p><p>The grid is a very useful tool and appears as a non-printing checkered grid of lines over your document.&#160;You can also choose to have this appear as dots.&#160;Grids help you align elements symmetrically.&#160;The spacing in the grid is also the same for all images.</p><p>Guides are movable vertical and horizontal lines over the image.&#160;You can move them, remove them and you can even lock them, so they stay fixed on the screen.&#160;Objects can be aligned and snapped to guides.</p><p>Photoshop also has a feature called Smart Guides that help you automatically align shapes and selections.&#160;Whenever you create a shape, these smart guides will appear automatically.</p><p>You can adjust your preferences for the Grids and Guides from this section.&#160;You can make changes to their default colors, the style, as in whether they should be straight lines, dotted lines, etc., and even the spacing of the grid.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c5bf773598c70f287e4d12892e1871ef','adobe-photoshop-m3-l7-module-3-summary','a8b683f68c9695b78a6b50708f7615ec','Module 3 Summary','text',12,'<h2>Module 3 Summary</h2><section><h3>Summary</h3><p>Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Project Setup and Interface Part I!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Set appropriate document settings for printed and onscreen images</p><p>Create a new document preset to reuse for specific project needs</p><p>Identify and manipulate elements of the Photoshop interface</p><p>Organize and customize the workspace</p><p>Configure application preferences</p><p>Additional Resources</p><p>The following articles&#160;and websites are additional resources to learn more about this topic.&#160;(Not required reading)</p><p>Overview of Photoshop:</p><p>Dream it.&#160;Make it.(opens in a new tab)</p><p>Get to know Photoshop(opens in a new tab)</p><p>Learn more about the Photoshop Interface:</p><p>Getting to know the Photoshop Interface(opens in a new tab)</p><p>Learn more about color modes:</p><p>RGB and Color Channels in Photoshop Explained(opens in a new tab)</p><p>Color Modes(opens in a new tab)</p><p>Understand what bit depth or color depth means:</p><p>The Benefits Of Working With 16-Bit Images In Photoshop(opens in a new tab)</p><p>Understand image resolution:</p><p>Image size and resolution(opens in a new tab)</p><p>Image Resolution, Pixel Dimensions and Document Size in Photoshop(opens in a new tab)</p><p>Learn more about improving Photoshop performance:</p><p>Optimize Photoshop CC performance</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c68263cbd950d9f03650c27f267c23f8','adobe-photoshop-m3-l8-module-3-project','a8b683f68c9695b78a6b50708f7615ec','Module 3 Project','text',12,'<h2>Module 3 Project</h2><section><h3>Module 3 Project</h3><p>2400</p><p>Adobe Photoshop</p><p>Project Setup and Interface Part I - Project</p><p>Project</p><p>In this assignment, you will apply all that you have learned about the project setup and the Photoshop interface to perform the following tasks. You will need to use Photoshop to perform these tasks. In some of these tasks, you may need to take screenshots to label them as well.</p><p>Create a new project in Photoshop. This project should be an A4-sized document in landscape mode.</p><p>Create a custom preset in Photoshop. The custom preset should have a document size of 9 x 13 inches, it should be in landscape mode, and have the background color set to the RGB values 255, 255, 153. Save this preset with the name “Demo, 9 x 13”. Create a new project using this preset.</p><p>Take a screenshot of your Photoshop interface, paste it onto a Word or PowerPoint document, and label the various components of the interface. You must label the following areas:</p><p>Toolbar or Tools panel</p><p>Panels and panel groups</p><p>Document window</p><p>Document tabs</p><p>Menu bar</p><p>Options bar</p><p>Make the following changes to your Photoshop workspace. Take screenshots of these tasks to share with your instructor:</p><p>Open two documents or images in Photoshop.</p><p>Change the Tools panel or Toolbar to a two-column view.</p><p>Undock the Color panel and make it a floating panel. Then, undock the Swatches panel and dock it under the Color panel.</p><p>Open Photoshop Preferences and make the following changes. Take screenshots of these tasks to share with your instructor:</p><p>Change the Interface Color Theme to the black theme.</p><p>Ensure that Tooltips are enabled.</p><p>Change the unit of the Rulers to centimeters.</p><p>Project Setup and Interface Part I Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Set Document Settings</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Create New Preset</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately with attention to detail and meeting all requirements.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors in the preset settings.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well and the preset was not created as instructed.</p><p>4</p><p>Identify Interface Elements</p><p>4 points Demonstrated a strong understanding of the objective. All the interface elements were identified correctly.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. Almost all the interface elements were identified correctly, with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. Little to none of the interface elements were identified correctly.</p><p>4</p><p>Customize Workspace</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately and the workspace was organized as instructed.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors in organizing the workspace.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Configure Preferences</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately and all the preferences were configured as instructed.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors in some of the preferences.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e2c38f562ad6162dd90a1dc1995aa7cd','adobe-photoshop-m3-l9-module-3-quiz','a8b683f68c9695b78a6b50708f7615ec','Module 3 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Setup and Interface Part 1. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('b8858c1c61912bade55d199bdbb6fdcc','adobe-photoshop-module-4','ee9c9635d1344f63172dfbcc5883d9ea','Module 4: Setup and Interface Part 2',4) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('535481cb38272626fd8bb888640c09ac','adobe-photoshop-m4-l1-introduction-purpose-and-objectives','b8858c1c61912bade55d199bdbb6fdcc','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Select a StudentCTEdemo_photoshop</p><p>Hi there! This is the intro video for the module on Project Setup and Interface Part II. In the last module, you got familiar with some important Photoshop basics like opening a new document, using presets and templates. You learned about the Photoshop interface and all of its different elements. And you also learned how to organize the Photoshop workspace.</p><p>In this second module on Project Setup and Interface, we’ll move on to learning all about some fantastic non-printing tools that are a part of the Photoshop interface and will help you in your designs or workflow. You’ve already gotten an introduction to some of these tools, like rulers, grids, and guides. In this module, you’ll learn exactly how you can use these tools and how helpful they are. While working in Photoshop, you will also need to import assets from many different sources, like if you want to edit photos that you took on your digital camera, or you painted or drew artwork that you want to refine using Photoshop. So, we’ll discuss how you can import images from various sources into Photoshop, and how you can place assets in Photoshop. We’re just getting started on our journey to discover Photoshop, and there’s so much more to learn!</p><p>Module Description</p><p>Select a StudentCTEdemo_photoshop</p><p>Photoshop is a complex tool, but it also has some great features in place to make it easier for you to use Photoshop.&#160;In this module, students will learn how to easily navigate a document.&#160;They will learn how rulers, grids, and guides can make it so much easier to place objects and align them on a document.&#160;They will also learn all the different ways to import images and place assets in a Photoshop document.</p><p>Objectives</p><p>Select a StudentCTEdemo_photoshop</p><p>In this module, students will:</p><p>Navigate a document</p><p>Use rulers</p><p>Use guides and grids</p><p>Open or import images from various devices</p><p>Place assets in a Photoshop document and use the Adobe Camera Raw interface to process images</p><p>Polling Question</p><p>Select a StudentCTEdemo_photoshop</p><p>Which of these things do you want to do using Photoshop?</p><p>Edit photos that I take on my digital camera/phone&#160;Create original artwork or enhance my paintings/drawings&#160;Use it for schoolwork like projects, reports, etc.&#160;Multiple/none of the above</p><p>Results:</p><p>Create original artwork or enhance my paintings/drawings&#160;100%</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('49d7ffa5543a9452a7de790628ae229c','adobe-photoshop-m4-l2-lesson-1','b8858c1c61912bade55d199bdbb6fdcc','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Zooing Images</h3><p>Zooming Images</p><p>Select a StudentCTEdemo_photoshop</p><p>Navigating a Document</p><p>Let’s kick off this module by learning how to navigate a document.&#160;This refers to performing tasks like zooming in and out of an image, panning or scrolling an image, rotating an image, and the tools available in Photoshop that will help you perform these tasks.&#160;These are all simple but essential tasks that will help you immensely when you work in Photoshop.&#160;We’ll go over how you can do all of these both accurately and efficiently.</p><p>Let’s start off by learning how to zoom in and out of images.</p><p>Zooming Images</p><p>When you open an image in Photoshop, you can see what zoom level it is currently at by just looking at the document tab.&#160;For example, in the image below, the zoom level is 25.1%.</p><p>You can also see this zoom level at the bottom of the document window.</p><p>There are a few different ways in which you can zoom in and out of your images, and you can choose the one you are most comfortable with.</p><p>Menu Bar:</p><p>You can use the menu bar to zoom in and out of an image as well.&#160;Just click&#160;View&#160;and you will see a few zoom options in the drop-down list.</p><p>You can click either&#160;Zoom In&#160;or&#160;Zoom Out&#160;from the list to zoom in or out of the image.&#160;Each time you click this, there is a small-sized incremental increase or decrease in the zoom level of the image.&#160;So, if you want to zoom in or out all the way, this method would be very tedious, as you would need to keep clicking&#160;View&#160;and either&#160;Zoom In&#160;or&#160;Zoom Out.</p><p>You can also use the keyboard shortcuts shown here, that is&#160;Ctrl + +&#160;to zoom in or&#160;Ctrl + -&#160;to zoom out.&#160;&#160;On a Mac, you need to use the&#160;Command&#160;button instead of the Ctrl button.</p><p>A limitation with the zoom commands is that they only zoom in and out of the center of the image.&#160;You will then need to switch to a different tool to move around to focus on other areas of the image.</p><p>In the&#160;View&#160;menu, you will also see an option to “Fit on Screen”.&#160;This is basically used to fit the image within the document window.&#160;So, if your image is zoomed in completely, clicking this will zoom out so that the full image is displayed within the document window.</p><p>Next in the list is the&#160;100%&#160;option.&#160;This option basically displays the image at full size or at its actual size.&#160;If your image is large, then it will show zoomed in like this.</p><p>Viewing the image in this mode will show you all the details of the image and will give you an idea of the quality of the image as well.</p><p>Zoom Tool:</p><p>This is the most versatile tool available to zoom in and out of your image in Photoshop.</p><p>While the above options also allow you to zoom, they offer little in terms of being able to control which area of the image you zoom into and are not very intuitive.&#160;The&#160;Zoom&#160;tool is the magnifying glass tool you see here in the&#160;Photoshop Toolbar.&#160;You can click the icon or press the letter ‘Z’ to use the keyboard shortcut to access it.</p><p>As soon as you click it, you will see the corresponding options changing in the&#160;Options&#160;bar.&#160;Let’s quickly walk through all the options here and we’ll see a video on how you can use the Zoom tool.</p><p>Click each hotspot to learn the function of each of these icons.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Hotspot activity exploring the Zoom options bar</p><p>The hotspot points on the image are as follows:</p><p>Zoom Out</p><p>Use this to zoom out of the image.</p><p>Fill Screen</p><p>Use to zoom the current window to fill the screen.</p><p>100%</p><p>Click to view the image at full size or 100% size.</p><p>Fit Screen</p><p>Use to fit the image within the confines of the document window.</p><p>Scrubby Tool</p><p>Click and move this left and right to scale the image. Moving left will zoom out and moving right will zoom in to the image.</p><p>Zoom In</p><p>Use this to magnify or zoom in to the image.</p></section><section><h3>Using the Zoom Tool</h3><p>Using the Zoom Tool</p><p>Select a StudentCTEdemo_photoshop</p><p>This video will go over how you can use all the Zoom features in the Options bar that you just learned about.</p><p>Let’s take a look at how you can use Photoshop’s Zoom tool to zoom in and out of an image. Just click the&#160;Zoom&#160;icon at the bottom of the toolbar, and you’ll see all of the zoom options up here in the&#160;Options&#160;bar. Now you&#39;ll see that the&#160;Zoom In&#160;icon, this one right here with the plus sign in it, is selected by default. All you have to do to zoom into any part of the image is to position your tool over the image and click. You can keep clicking to zoom in further.</p><p>To zoom out, just select the&#160;Zoom Out&#160;icon, that&#39;s the one with the minus sign in it, and once again, click on the image, and you can keep clicking to zoom out. Clicking the Zoom In and Zoom Out icon again and again every time you want to zoom in or out can become tiresome.&#160;So when you’re in the Zoom In mode, you can just press and hold the&#160;Alt&#160;key (if you’re using Windows) or the&#160;Option&#160;key (on a Mac) and you’ll see here that the plus sign on the cursor automatically changes to a minus sign. This works with both Zoom In and the Zoom Out options. So, let&#39;s say you have Zoom Out selected and you press and hold the Alt key, you&#39;ll see that it changes to a Zoom In icon.</p><p>Now, if you’re working with a large image, instead of clicking multiple times to zoom into the image, you can just click and keep your mouse button held down to continuously zoom into the image. The image will continue to zoom until you release the mouse button. The same thing works with zooming out as well. Just click and hold until you want to zoom and stop.</p><p>Next, let’s talk about the&#160;scrubby zoom&#160;tool. This is the scrubby zoom tool, so let’s just select this. Now, all you have to do is click anywhere on the image and just drag left to zoom out of the image and drag it right to zoom into the image. So, I just click and drag left, or click and drag right to zoom in. This is a really easy way to zoom in and out of the image.</p><p>Now, if you disable the scrubb<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('44bda6173cbc9cea1abd402ffee5f069','adobe-photoshop-m4-l3-lesson-3','b8858c1c61912bade55d199bdbb6fdcc','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Showing and Hiding Rulers</h3><p>Showing and Hiding Rulers</p><p>Select a Student</p><p>Rulers&#160;help you position or place elements on the screen.&#160;You’ll find rulers in most commonly used writing and editing software and applications, many of which you must be familiar with, like Microsoft Word and PowerPoint.</p><p>By default, Photoshop doesn’t display rulers.&#160;You can use the Menu bar to show or hide rulers in Photoshop.&#160;Just click&#160;View&#160;and select&#160;Rulers.&#160;You can also use the keyboard shortcut&#160;Ctrl + R&#160;(on Windows) or&#160;Command + R&#160;(on Mac) to display the ruler.</p><p>Rulers appear along the top and left sides of the document window.&#160;The default measurements are in inches, but you can change this to other units of measurement, which we’ll cover later.</p><p>If you look closely, you will see that the “0” on both rulers are aligned with the top-left corner of your document or image.&#160;This point is called the ruler’s&#160;zero origin.&#160;This makes it easier for you to place objects on your document.&#160;For example, let’s say you are creating a document but need to leave a 1-inch margin all around for printing.&#160;You can use the ruler to make sure anything you place on the document is inside the margin and won’t get cut off when you print your document.</p></section><section><h3>Moving the Zero Origin</h3><p>Moving the Zero Origin</p><p>Select a Student</p><p>Now, you know that the zero origin of the ruler is on the top-left corner of your document, but you can also move this to any position on your document.&#160;Just position your pointer over the intersection of the two rulers and click and drag down over the document.&#160;Release your mouse button at the position you want the origin to be.&#160;You’ll see that the zeroes on the ruler have now moved.&#160;You can now use this new origin to align objects, grids, and guides—we’ll cover this in the next lesson.</p></section><section><h3>Changing the Measurement Unit on Rulers</h3><p>Changing the Measurement Unit on Rulers</p><p>Select a Student</p><p>By default, the ruler in Photoshop is set to measure in inches.&#160;You can easily change this at any time by simply right-clicking on the ruler and selecting one of the other options available in the drop-down list.</p><p>You can also change this from the&#160;Preferences&#160;window.&#160;In the last module, you learned about setting the ruler preferences in Photoshop, do you remember how to access the&#160;Preferences&#160;window?&#160;If you are using a Windows computer, in the menu bar, click&#160;Edit, select&#160;Preferences, and click&#160;Units &amp;&#160;Rulers.&#160;On a Mac, click the&#160;Photoshop&#160;menu,&#160;select&#160;Preferences, and click&#160;Units &amp;&#160;Rulers.</p><p>You can then change the unit of measurement of the ruler, along with other measurement settings.</p></section><section><h3>Vocabulary</h3><p>Vocabulary</p><p>Select a Student</p><p>Match&#160;the vocabulary words below with their definitions.&#160;These are terms from both Lesson 1 and 2.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this lesson.</p><p>Tab through this activity to read the feedback for your answers</p><p>Feedback</p><p>A tool that allows you to magnify documents or images.</p><p>Zoom tool</p><p>Correct!</p><p>It magnifies an image when you click and drag the image right or left, respectively.</p><p>Navigator Panel</p><p>Incorrect</p><p>A tool that helps you pan and scroll through a document or image.</p><p>Hand tool</p><p>Correct!</p><p>A panel that allows you to zoom and pan an image via a thumbnail-sized version of the image.</p><p>Scrubby zoom</p><p>Incorrect</p><p>It is a part of the Hand tool and allows you to turn the canvas of an image without distorting its quality.</p><p>Rotate tool</p><p>Correct!</p><p>They are vertical and horizontal measurement scales that help you measure and place elements on your document.</p><p>Rulers</p><p>Correct!</p><p>It is the starting point of the vertical and horizontal rulers.&#160;It is usually at the top-left corner of your image or document.</p><p>Zero Origin</p><p>Correct!</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>A tool that allows you to magnify documents or images.</p><p>Zoom tool</p><p>Rotate tool</p><p>Navigator Panel</p><p>Rulers</p><p>Hand tool</p><p>Zero Origin</p><p>Scrubby zoom</p><p>Correct!</p><p>2.</p><p>It magnifies an image when you click and drag the image right or left, respectively.</p><p>Scrubby zoom</p><p>Hand tool</p><p>Rulers</p><p>Rotate tool</p><p>Zero Origin</p><p>Zoom tool</p><p>Navigator Panel</p><p>Incorrect</p><p>3.</p><p>A tool that helps you pan and scroll through a document or image.</p><p>Navigator Panel</p><p>Hand tool</p><p>Scrubby zoom</p><p>Zero Origin</p><p>Zoom tool</p><p>Rulers</p><p>Rotate tool</p><p>Correct!</p><p>4.</p><p>A panel that allows you to zoom and pan an image via a thumbnail-sized version of the image.</p><p>Rulers</p><p>Navigator Panel</p><p>Zoom tool</p><p>Hand tool</p><p>Scrubby zoom</p><p>Rotate tool</p><p>Zero Origin</p><p>Incorrect</p><p>5.</p><p>It is a part of the Hand tool and allows you to turn the canvas of an image without distorting its quality.</p><p>Zero Origin</p><p>Rotate tool</p><p>Hand tool</p><p>Navigator Panel</p><p>Rulers</p><p>Scrubby zoom</p><p>Zoom tool</p><p>Correct!</p><p>6.</p><p>They are vertical and horizontal measurement scales that help you measure and place elements on your document.</p><p>Zero Origin</p><p>Hand tool</p><p>Rotate tool</p><p>Zoom tool</p><p>Navigator Panel</p><p>Rulers</p><p>Scrubby zoom</p><p>Correct!</p><p>7.</p><p>It is the starting point of the vertical and horizontal rulers. It is usually at the top-left corner of your image or document.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('061a1007e64f8efeacfee29a6ac9b1d9','adobe-photoshop-m4-l4-lesson-4','b8858c1c61912bade55d199bdbb6fdcc','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Opening an Image</h3><p>Opening an Image</p><p>Select a StudentCTEdemo_artsav</p><p>There are many different ways in which you can import images into Photoshop.&#160;It may seem like opening an image is a simple task, and it is, but because Photoshop is such a versatile tool, there are many different sources you can open images from.&#160;You can open images you have saved on your computer, or photos you took on your camera, or even images that you scanned using a scanner.</p><p>Opening Images from a File</p><p>Let’s start with the easiest way to open images, and that is from a folder on your computer.&#160;When you start Photoshop, you will see the&#160;Start Workspace&#160;which has an&#160;Open&#160;button on the left.&#160;Click the&#160;Open&#160;button, and from here, you can navigate to the folder where your image is stored.</p><p>If you have already opened an image before in Photoshop, it will be shown in the&#160;Recent Files&#160;section the next time you open Photoshop.&#160;So, all you need to do is select it from here and it will open the image.</p><p>Next, once you have opened an image in Photoshop, if you want to open another one, you can also use the&#160;File&#160;menu.&#160;Just click&#160;File&#160;and click&#160;Open.&#160;From here, you can navigate to the folder containing your photos and open the one you want.</p></section><section><h3>Importing Images from Digital Cameras</h3><p>Importing Images from Digital Cameras</p><p>Select a StudentCTEdemo_artsav</p><p>Importing Images from Digital Cameras</p><p>You may want to transfer photographs you took using your digital camera onto your computer and into Photoshop for editing and processing.&#160;To do this, you can use a program called&#160;Adobe Bridge&#160;that comes bundled with Adobe Photoshop.&#160;Adobe Bridge is basically a file browser tool that makes it very easy for you to find images on your computer, organize, and rename them.&#160;You can also apply specific metadata to them.</p><p>You can import images from your digital camera in a few different ways.</p><p>You can use the&#160;Get Photos From Camera&#160;command in Adobe Bridge to download photos from your camera.&#160;You can then organize your photos, rename them, etc.</p><p>You can use a card reader or directly connect your camera to a computer and transfer the photos to a drive on your computer or directly into Adobe Bridge.</p><p>Most digital cameras come with software that helps you transfer photos to a computer.&#160;This could be software like&#160;Windows Image Acquisition (WIA)&#160;for Windows or&#160;Image Capture&#160;for Mac.&#160;Read your camera documentation for information on how to use this software.</p></section><section><h3>Importing Scanned Images</h3><p>Importing Scanned Images</p><p>Select a StudentCTEdemo_artsav</p><p>Importing Scanned Images</p><p>You can easily scan your documents, drawings or paintings and import them into Photoshop.&#160;Most scanners have an application that you can use to scan and save images onto your computer.&#160;You can then import those images into Photoshop.</p><p>If your scanner doesn’t provide software or drivers that are compatible with your computer, you can also use third-party scanning software like&#160;VueScan&#160;or&#160;Silverfast.</p><p>You can save your scanned documents as TIFF files, and then open them in Photoshop.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f9c2eb48da0c480850ce4dc98c81ba16','adobe-photoshop-m4-l5-lesson-5','b8858c1c61912bade55d199bdbb6fdcc','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Smart Objects</h3><p>Smart Objects</p><p>Select a Student</p><p>The&#160;Place&#160;command in Photoshop helps you place images or any object onto your Photoshop document as a Smart Object.</p><p>What are Smart Objects?</p><p>Smart objects&#160;are a very useful feature of Photoshop.&#160;They are layers that contain the image data of Photoshop images.&#160;Smart objects are basically containers that protect the original source and characteristics of an image.&#160;This makes it so that no matter what edits you do to the image, like scaling, skewing, or rotating it, the original image is always preserved and can be restored.</p><p>Some of the benefits of using smart objects are:</p><p>You can perform non-destructive edits and transforms, which means you can scale, rotate, skew, distort or warp a layer without losing the original quality of the image because it doesn’t affect the original data.</p><p>You can add filters to an image and restore it any time you want.</p><p>You can edit one smart object and automatically update all the linked instances, so this is very useful when you’re working with reusable presets or templates and need to replace an element across multiple documents.</p><p>There are many more benefits of smart objects, and you’ll learn more about them as we move on in the course.</p></section><section><h3>Placing Files in Photoshop</h3><p>Placing Files in Photoshop</p><p>Select a Student</p><p>There are different ways in which you can place images in Photoshop.</p><p>If you use Adobe Illustrator to create artwork, you can simply copy and paste your art from Illustrator onto your Photoshop document.&#160;In Illustrator, just choose&#160;Edit&#160;and click&#160;Copy, and in Photoshop, click&#160;Edit&#160;and&#160;Paste.&#160;You can choose the settings you want in the&#160;Paste&#160;dialog box and click&#160;OK.</p><p>The other ways in which you can place files in Photoshop is as embedded images or as linked images.&#160;In the&#160;File&#160;menu, you will see two options,&#160;Place Embedded&#160;and&#160;Place&#160;Linked.</p><p>Choosing the embedding option basically adds an image to your document.&#160;When you add a linked image, Photoshop adds an image to your document but maintains a link to the original document in your folders.&#160;If you make any changes to the main source image file, the changes will be reflected in the linked image.</p><p>Linked objects are a very useful feature.&#160;Let’s say you are creating 3-4 different posters for a bake sale, and all the posters have the same footer showing the date, location, etc. If you need to make any global changes like the colors or dates, you’ll need to go into each poster’s Photoshop file and update the dates.&#160;But with linked objects, you only need to make the changes to the main source image file, and the changes will be reflected in all the instances.</p><p>by Shutterstock</p><p>License:&#160;All Rights Reserved</p></section><section><h3>Place Embedded and Linked Images</h3><p>Place Embedded and Linked Images</p><p>Select a Student</p><p>Let’s see how you can place linked and embedded images in Photoshop.</p><p>To place an embedded image in a document, click&#160;File&#160;and select&#160;Place Embedded. Select the image you want to add and click&#160;Place. You can resize this image and move it to where you want on the document. You can see that this image is automatically added as a smart object, which is indicated by this icon right here in the&#160;Layers&#160;panel.</p><p>To add a linked image, click&#160;File&#160;and select&#160;Place Linked. Once again, just select an image you want to add and click&#160;Place. You can resize this image as well. You can see that this image is a linked image by this icon right here.</p><p>You can easily convert a linked image to an embedded image, and vice versa. To convert a linked image to an embedded image, just right-click this layer and select this “Embed Linked” option. You&#39;ll see that the icon has changed and this is now an embedded image. Similarly, you can also convert an embedded image to a linked image. Just right-click the embedded image and&#160;click this “Convert to Linked” option. Because you are converting an embedded image to a linked image, you are going to have to save the linked file, and that will become the main source file for the linked image. So, I&#39;m going to save this on the desktop. And you can see that this icon has changed to a linked icon. So, if I make any changes to the source file on the desktop, you will see the changes reflected here. Let’s see an example of this.</p><p>I have two documents here. They both have different layouts, but they have the same image. You can see that this image here is linked. And the same in this document as well. To edit this linked image, right-click on it and click the “Edit Contents” option. The image will open in a separate tab. Ideally, any change that I make and save here should be reflected in both the documents. So, let’s go ahead and make some changes. Let&#39;s change the color balance of this image, and I&#39;m going to adjust this to make it a little more red and pink. Okay, that looks fine and I&#39;ll click&#160;Save.&#160;The image has been saved, now let’s go back and check the other two documents. There you go! You can see that the image has been updated here, and in this document as well. As you can see, with linked images, it is really easy to make changes in one place and have it reflect in multiple documents at once. This is how embedded and linked images work.</p></section><section><h3>Using Adobe Camera Raw</h3><p>Using Adobe Camera Raw</p><p>Select a Student</p><p>A camera raw image is an unprocessed image that has been captured by a digital camera.&#160;You can think of a camera raw file as a photo negative.&#160;To get the actual photo, you need to process the negative first.&#160;Similarly, camera raw images need to be processed first before you can edit them in Photoshop.</p><p>Adobe provides Camera Raw software as a plugin with Photoshop to help you process raw files.&#160;It also works with Adobe Bridge, so you can directly import images from your camera into Adobe Bridge, and then transfer them from Bridge to Camera Raw for processing.</p><p>To do this, in Adobe Bridge, select the raw file you want to upload and click&#160;File&#160;and&#160;Open in&#160;Camera Raw.</p><p>The image will be opened in Camera Raw.&#160;You can see that there<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('d6d061205be44dad246fc619da68e743','adobe-photoshop-m4-l6-summary','b8858c1c61912bade55d199bdbb6fdcc','Summary','text',12,'<h2>Summary</h2><section><h3>Module 4 Summary</h3><p>Summary</p><p>Select a Student</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Project Setup and Interface Part II!</p><p>Make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Navigated a document</p><p>Used rulers</p><p>Used guides and grids</p><p>Opened or imported images from various devices</p><p>Placed assets in a Photoshop document and used the Adobe Camera Raw interface to process images</p><p>Additional Resources</p><p>Select a Student</p><p>The following books, articles, and websites are additional resources to learn more about this topic.&#160;(Not required reading).</p><p>Lesson 1Photoshop Image Navigation Tips Tricks and Shortcuts(opens in a new tab)</p><p>Lesson 3Add Visual Interest To Your Photos With The Rule Of Thirds(opens in a new tab)</p><p>Lesson 4Acquire images from cameras and scanners(opens in a new tab)</p><p>Lesson 5What is Camera Raw?(opens in a new tab)</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('587aafc5ab2ebabaafdc1a88dacd3634','adobe-photoshop-m4-l7-module-4-project','b8858c1c61912bade55d199bdbb6fdcc','Module 4 Project','text',12,'<h2>Module 4 Project</h2><section><h3>Module 4 Project</h3><p>2400</p><p>Adobe Photoshop</p><p>Project Setup and Interface Part II - Project</p><p>Project</p><p>In this assignment, you will apply all that you have learned about the project setup and the Photoshop interface to perform the following tasks. You will need to use Photoshop to perform these tasks. Take screenshots after you have completed each step. You can save the screenshots as images or in a Word/PPT document.</p><p>Open an image in Photoshop. Launch the Navigator panel and use the&#160;view box to zoom into a section of the image.&#160;(Take a screenshot after this step is complete.)</p><p>Open a blank document in Photoshop. Change the default unit of the Ruler to pixels. Then, move the zero origin of the ruler to a new location.&#160;(Take a screenshot after this step is complete.)</p><p>Create a new guide layout with the following specifications: 6 columns and 6 rows, each with a gutter of 20 pixels, and add a margin of 35 pixels. Save the new guide layout with a descriptive name.&#160;(Take screenshots of the new guide layout on a blank document. The rulers should be visible.)</p><p>Take a photo on a digital camera and open it in Photoshop using Adobe Bridge.&#160;(Take a screenshot of your image open in Adobe Bridge.)</p><p>Place an image in Photoshop as an embedded image. Then, convert the image to a linked image.&#160;(Take a screenshot after each step and highlight how you can tell if it is an embedded or linked image.)</p><p>Project Setup and Interface Part II Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Navigate a document</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Use rulers</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately with attention to detail and meeting all requirements.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well and rulers were not created as instructed.</p><p>4</p><p>Use guides and grids</p><p>4 points Demonstrated a strong understanding of the objective. The new guide layout was created correctly.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. Almost all the instructions to create the new guide layout were followed correctly, with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. Little to none of the instructions to create a new guide layout were followed correctly.</p><p>4</p><p>Open or import images from various devices</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately and the images were imported as instructed.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Place assets in Photoshop</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately and as instructed.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('fdf53b40844d41fa247ec6639fe6d9f2','adobe-photoshop-m4-l8-module-4-quiz','b8858c1c61912bade55d199bdbb6fdcc','Module 4 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Setup and Interface Part 2. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,7,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('0e8999f6230c6dc76db3da88188c679b','adobe-photoshop-module-5','ee9c9635d1344f63172dfbcc5883d9ea','Module 5: Setup and Interface Part 3',5) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5b6f67a5748c4f388ae46055d9355103','adobe-photoshop-m5-l1-introduction-purpose-and-objectives','0e8999f6230c6dc76db3da88188c679b','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Select a Student</p><p>Welcome back! This is the intro video for the module on Project Setup and Interface Part III. So far, you’ve learned a lot about starting a new project in Photoshop and getting familiar with the Photoshop interface. You learned how to use a lot of really useful interface tools to make it easier to position, align and manage objects and images in Photoshop.</p><p>In this third module on Project Setup and Interface, we’re going to dive into the world of colors! Photoshop gives you a multitude of color tools to play with and explore your creativity. You can completely customize the colors and gradients you want to choose, pick from an array of color and paint tools like brushes, symbols, graphic styles and patterns, and you can even create custom swatches and palettes. Let’s explore all the color tools that Photoshop has to offer!</p><p>Module Description</p><p>Select a Student</p><p>License:&#160;All Rights Reserved</p><p>Photoshop is a must-know tool for anyone interested in photography, graphic design, art,&#160;and illustration because of the myriad of color editing tools available.&#160;This module will introduce students to ways in which they can select, use, and modify background colors, gradients, and swatches in Photoshop.&#160;They will also learn how to use Photoshop libraries to browse and edit brushes, graphic styles, and patterns.</p><p>Objectives</p><p>Select a Student</p><p>In this module, students will:</p><p>Set the active foreground and background color</p><p>Create and customize gradients</p><p>Create and edit swatches</p><p>Open and browse libraries of included brushes, symbols, graphic styles, and patterns</p><p>Create and edit brushes, symbols, styles, and patterns</p><p>Polling Question</p><p>Select a Student</p><p>Which of the topics you&#39;ve learned about so far have you found most interesting or useful?</p><p>Creating a document in Photoshop&#160;Navigation in Photoshop&#160;Photoshop tools and panels&#160;Importing assets into Photoshop</p><p>Results:Photoshop tools and panels&#160;100%</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3a79c66bfce509b86ea3491887f311d3','adobe-photoshop-m5-l2-lesson-1','0e8999f6230c6dc76db3da88188c679b','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Foreground and Background Colors</h3><p>Foreground and Background Colors</p><p>Select a Student</p><p>Photoshop has a number of tools you can use to add color to your images and documents.&#160;This includes tools like the Brush tool, Type tool, Shape tool, the Color and Swatches panels, and many more.</p><p>In Photoshop, you can store colors in the Foreground and Background color boxes.&#160;These boxes are found at the bottom of the Toolbar.</p><p>‘A’ shows you the default foreground and background colors.&#160;You can click this icon to return to the default colors.</p><p>‘B’ shows you the current Foreground color.&#160;You can click it to change the foreground color using the Color Picker.</p><p>‘C’ is the current Background color.&#160;You can click it to change the background color using the Color Picker.</p><p>You can click the ‘D’ icon to easily switch the foreground and background colors.</p><p>Foreground Box</p><p>Background Box</p><p>The&#160;Foreground box&#160;will show you the primary color that will be used if you select and use any of these color tools.&#160;The default foreground color, as you can see here, is black.&#160;The foreground color is used to paint, fill and stroke selections.</p><p>The&#160;Background box&#160;will show you a secondary color, which is white by default.&#160;Background colors are used to make gradient fills and also to fill in the areas of an image that you erase.&#160;It is also there so you can easily switch between two colors while drawing or painting.</p></section><section><h3>Ways to Choose Foreground and Background Colors</h3><p>Ways to Choose Foreground and Background Colors</p><p>Select a Student</p><p>There are many ways in which you can select a foreground and background color.&#160;You can use the&#160;Eyedropper tool, the&#160;Color Picker, the&#160;Color panel, or the&#160;Swatches panel.</p><p>Eyedropper Tool</p><p>You can find the Eyedropper tool on the toolbar.&#160;This tool helps you click any part of your image and use it as a sample to select a new foreground or background color.&#160;You can pick this sample from the image you have open or from anywhere else on the screen.</p><p>Click each hotspot to learn more.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Options bar when the eyedropper tool is selected</p><p>The hotspot points on the image are as follows:</p><p>Sample</p><p>This drop-down allows you to sample colors either from just the current layer or from all the layers in the document.</p><p>Sample Size</p><p>This drop-down basically allows you to select if you want the tool to read the precise value of the pixel you click on (the ‘Point Sample’ option) or if you want to choose a pixel grid size and read the average value of the pixels in that area.</p><p>Sampling Ring</p><p>This icon is selected by default. It basically appears as a color preview ring around the eyedropper tool when you click it.</p><p>Eyedropper tool</p><p>The Eyedropper tool is used to select foreground and background colors. Selecting this tool will show you the Options bar shown here.</p><p>Color Picker</p><p>The Color Picker is the most full-featured way to pick a color in Photoshop.&#160;The Adobe Color Picker allows you to input specific values and choosecolors using different color models; HSB, RGB, Lab, CMYK, and even the hexadecimal value of the color.</p><p>Here is a walkthrough of what each of these color models are.</p><p>Click each tab to learn more.</p><p>Next Tab</p><p>HSB</p><p>Uses the&#160;Hue, Saturation, and&#160;Brightness&#160;to define a color.&#160;Hue is measured in degrees as it specifies an angle from 0&#176; to 360&#176; on the color wheel.&#160;Saturation and Brightness are specified as percentages.</p><p>RGB</p><p>Uses the&#160;Red, Green&#160;and&#160;Blue&#160;values to define a color. The values for these colors range from 0 to 255, where 0 indicates no color and 255 is the pure color.</p><p>Lab</p><p>In this model,&#160;L&#160;specifies the&#160;luminance&#160;of the color, the&#160;A&#160;value denotes the degree of&#160;red&#160;or&#160;green&#160;in the color,&#160;and the&#160;B&#160;value denotes the degree of&#160;blue&#160;or&#160;yellow&#160;in the color. L values range from 0 to 100, and the A &amp; B values range from -128 to 127.</p><p>CMYK</p><p>Uses the&#160;Cyan, Magenta, Yellow,&#160;and&#160;Black&#160;color values to define a color. These are all denoted as percentage values.</p><p>Hexadecimal value</p><p>The hexadecimal value or&#160;Hex&#160;code of color is based on the syntax&#160;#RRGGBB, where every two characters represent red, green, and blue colors. The values of these colors are integers in the range of 00 to FF, where FF is the pure color.</p><p>Note:&#160;To learn more about the different color models and about how and where they are used, check the&#160;Additional Resources&#160;page at the end of this course.</p><p>The color picker shows you the exact numerical values of the colors you choose.&#160;You can save the values to be used later for another document, or if you have the values of a color you want to use, you can directly enter them here as well.</p><p>Color Panel</p><p>The Color panel is very similar to the Color Picker and is usually shown by default on the Panels column on the right.&#160;If it is not visible, you can easily select it from the&#160;Window&#160;menu.&#160;The Color panel works in mostly the same way the Color Picker does.&#160;You can use the slider to select the hue you want, and then use the Color Field to choose the shade you want to use.&#160;The Color panel also shows you the current Background and Foreground colors, which will be the same as those shown in the Toolbar.</p><p>By default, the Color panel will show you the&#160;Hue&#160;spectrum of colors.&#160;You can easily change this to another spectrum by clicking the Color panel menu button and selecting another color model.</p><p>Swatches Panel</p><p>The Swatches panel is usually paired with the Color panel on the right Panels column.&#160;If not, you can select it from the&#160;Window&#160;menu.&#160;The Swatches panel shows you the colors that you use most frequently.</p><p>You can easily add or delete colors from the panel or can also display different libraries of colors for different projects.&#160;You can also create custom swatches or color schemes for a project and save them.&#160;You’ll lea<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1a0b3d35f47eed836f47f809cda3e700','adobe-photoshop-m5-l3-lesson-2','0e8999f6230c6dc76db3da88188c679b','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Gradient Tool</h3><p>Gradient Tool</p><p>Select a Student</p><p>Gradients are a gradual change of color that sweeps over an image or shape.&#160;You can use them to blend colors in your artwork, show subtle color changes to indicate shapes or shadows, or you can also layer them to blend multiple images and create interesting effects.</p><p>There are many ways in which you can add gradients to your images and documents in Photoshop.&#160;Photoshop gives you an option to choose from an array of basic, preset gradients, and you can also use the&#160;Gradient Editor&#160;to customize and save your own gradients.</p><p>Let’s start off by looking at the&#160;Gradient&#160;tool; you can find it in the Toolbar.&#160;If you don’t see it right away, don’t worry.&#160;It is nested within the&#160;Paint Bucket&#160;tool, so just press and hold down the&#160;Paint Bucket&#160;tool and you should see the&#160;Gradient&#160;tool in the popup.</p><p>Let’s take a look at all the options available in the&#160;Options&#160;bar when you select the&#160;Gradient&#160;tool.</p><p>Click each hotspot to learn more.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Options bar when the Gradient tool is selected</p><p>The hotspot points on the image are as follows:</p><p>Blending Mode</p><p>This controls how the gradient will blend with the contents of a layer when you use a painting or editing tool on an image. The Mode drop-down has a number of modes available that you can choose from.</p><p>Opacity</p><p>This controls the transparency of the blending mode that you choose. At 100% the blending mode is fully visible and as the percentage reduces, the transparency increases.</p><p>Gradient Styles</p><p>This determines how the starting and ending points of the gradient affect its appearance. There are five different gradient styles you can choose from, Linear, Radial, Angle, Reflected, and Diamond.</p><p>Reverse Colors</p><p>You can use this icon to switch the background and foreground colors that have been selected.</p><p>Dithering</p><p>This option adds some noise to your gradients to make your image look like it has smoother color transitions. It also reduces banding between colors.</p><p>Transparency</p><p>This option enables you to use the &#39;Foreground to Transparent&#39; gradient option effectively.</p><p>Gradient Picker</p><p>Photoshop has a number of preset gradients that you can choose from this drop-down list.</p></section><section><h3>Drawing Gradients</h3><p>Drawing Gradients</p><p>Select a Student</p><p>Now, let&#39;s take a look at how you can easily draw gradients in Photoshop.&#160;We&#39;ll also explore some of the different gradient styles that you can use.</p><p>To draw a gradient, first select the&#160;Gradient&#160;tool from the Toolbar. In the&#160;Options&#160;bar, you can pick a preset gradient from the&#160;Gradient Picker&#160;drop-down list. Let’s select the default Foreground to Background gradient for now. To draw a gradient, just click in your document to set a starting point for the gradient, hold down the mouse button, and drag and drop the gradient line at the other end. You’ll see a gradient appear on the document which looks exactly like the preview you see up here. You can drag this line from anywhere on the page, so if you drag from this corner down to this one, here&#39;s how the gradient will look. The start and stop points determine where the gradient starts and ends. If you want to draw perfectly straight lines, then after you have clicked on your starting point, press and hold the Shift key. This constrains the line to an angle of 45 degrees, and you’ll see that the line snaps to a perfectly straight line. So just drag and then you can drop it.</p><p>You can easily change the colors of the gradient by using the&#160;Color Picker. Just click the Foreground and Background tiles and select whichever color you want to replace them with. You’ll see that doing this also changes the colors in the Gradient Picker drop-down list. That&#39;s because this is the foreground to background gradient, and this is how it looks on your document. You can always change this back to the default colors by clicking this icon here. If you have created a gradient that you want to save to use later, just click this settings icon right here and select&#160;New Gradient. You can name this gradient and save it. If you go back to the Settings menu, you will also see that there are many other preset gradient sets that you can choose from.</p><p>Now, let&#39;s look at the gradient styles. You can see that the&#160;linear gradient&#160;is selected by default. You can also select one of the other four options. Let’s check them out. These icons show you a tiny preview of how they will look. For each of these styles, you will need to modify your start and stop points based on the type of gradient it is.</p><p>For example, let&#39;s select the&#160;Radial Gradient. Now, the radial gradient shades from the starting point to the ending point in a circular pattern. So, let&#39;s drag from the center of the image to the outside. In this gradient style, you’ll see that the foreground color is in a circle in the center fading out to the background color at the outside edges of the document.</p><p>Now, let&#39;s try out the&#160;Angular Gradient. The angular gradient&#160;shades in a counterclockwise sweep around the starting point, to form this type of pattern.</p><p>Next, a&#160;Reflected Gradient&#160;is like a linear gradient placed in front of a mirror. Basically, it mirrors the gradient on both sides of the starting point, like this.</p><p>And finally, the&#160;Diamond Gradient&#160;shades from the middle to the outer corners in a diamond pattern.</p><p>Another useful tip to remember is that you can easily switch between the foreground and background colors at any time by clicking this&#160;Reverse&#160;icon, and that will change how your gradient looks as well.</p></section><section><h3>Foreground to Transparent Gradient</h3><p>Foreground to Transparent Gradient</p><p>Select a Student</p><p>So far, you’ve learned a lot about gradients and how you can apply some of the preset gradients in Photoshop.&#160;Another important preset gradient you should know about is the&#160;Foreground to Transparent&#160;gradient.&#160;Let’s take a look at how you can use this gradient.</p><p>Select the&#160;Foreground to Transparen<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ad60d6dc414055e1a47eefe072e04b18','adobe-photoshop-m5-l4-lesson-3','0e8999f6230c6dc76db3da88188c679b','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Swatches</h3><p>Swatches</p><p>Swatches are a very useful tool in Photoshop.&#160;You can collect and organize swatches into different color palettes that you can pull up at any time.&#160;For example, let’s say you’ve taken a picture when you were out on a hike and you love the colors in the picture.&#160;You can use the same colors to create some artwork of your own.&#160;You just open the image in Photoshop, create swatches of the key colors in the image, and save the swatches as a swatch set.&#160;You can then use that swatch set to choose colors from and create your own original artwork.</p><p>Let’s see how you can create swatches from the colors of an image, and how you can save those swatches as a set that you can reuse at any time.</p></section><section><h3>Create &amp; Edit Swatches</h3><p>Create &amp; Edit Swatches</p><p>Deleting Default Swatches</p><p>Photoshop will show you a swatch set by default.&#160;You can add colors to the same swatch set and save them as a new set.&#160;But the better option would be to delete all of the swatches and create a fully custom swatch set.&#160;Don’t worry, you can always reset the swatch to show the original colors.</p><p>To delete existing swatches, just select and drag the swatches down to the trash bin icon and drop them.&#160;Unfortunately, Photoshop doesn’t have an option to delete all the swatches at once, so you will need to drag and delete each one of them.</p><p>Once you have a blank Swatches panel, you can start adding colors.</p><p>Adding Colors to the Swatch Panel</p><p>To add colors to the swatch panel, you will use the&#160;Eyedropper&#160;tool.&#160;Select the&#160;Eyedropper&#160;tool from the Toolbar and click a color on the image to sample it.&#160;You can see the color you have selected in the foreground color box.</p><p>Click the color if you want to make any adjustments to it in the&#160;Color Picker&#160;panel.&#160;Once you are happy with the color, move your mouse to the empty area on the swatch panel.&#160;You will see the&#160;eyedropper&#160;cursor icon has changed to a&#160;paint bucket&#160;icon.&#160;Just click anywhere in the panel to convert the sample to a swatch.&#160;You will see a popup asking you to name the color.&#160;You can add a name and click&#160;OK.&#160;You will see the first color swatch in the panel.</p><p>In the same way, keep adding more colors to the panel until you have added all the colors you want to add.&#160;You can add as many colors and shades as you like.</p><p>Saving a New Swatch Set</p><p>Now that you have created a new swatch set, you can save it by clicking the&#160;Swatches menu&#160;icon and selecting&#160;Save Swatches.</p><p>You will see a popup asking to name the swatch.&#160;Enter a name for your new swatch and click the&#160;Save&#160;button.&#160;Make sure you leave the path as it is, as Photoshop will save the swatch in the same directory as the other default swatches.</p><p>Once your new swatch set is saved, you can reset the swatch set to the default colors.&#160;Just open the menu and click&#160;Reset Swatches.</p><p>The panel will be reset with the default swatches.&#160;Next time you need to use your custom swatches for a document, just click the&#160;Swatches&#160;menu and select the swatch you created.&#160;Photoshop will ask you if you want to replace the current swatch or just add your swatch to it.&#160;Replace it and click&#160;OK.</p><p>You can now use this new swatch to create any artwork or document you want.</p><p>Editing a Swatch Set</p><p>You can always add, delete and update swatches in your new swatch set.&#160;Just use the&#160;Swatches&#160;menu to save your changes.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('723f3e2a833a67a97f87c464daed3613','adobe-photoshop-m5-l5-lesson-4','0e8999f6230c6dc76db3da88188c679b','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Preset Manager</h3><p>Preset Manager</p><p>Photoshop has multiple libraries of preset brushes, styles, patterns, shapes, and tools.&#160;You can use the Preset Manager to access and manage all of these different presets in one place.&#160;For example, in the last lesson, you saw how there are different sets of color swatches available, and how you can switch between them.&#160;You also saw that there was a default swatch set defined in Photoshop.&#160;You can change which swatch set is displayed by default using the Preset Manager.</p><p>In the same way, you can also switch between different sets of other presets, or even create new libraries of custom and imported presets.&#160;Once you update your Preset Manager, you can access the updated libraries from all of the different tools, menus, and options bars they are associated with.</p><p>To view the Preset Manager, just click&#160;Edit, select&#160;Presets&#160;and click&#160;Preset Manager.</p><p>The&#160;Preset Manager&#160;window appears.&#160;Here, you can see many different types of presets.</p><p>You can easily adjust how the presets are displayed by clicking the&#160;Settings&#160;icon and selecting from the options provided.&#160;Different views are useful for different preset types, as they give you a preset of how that tool or setting would look when used.</p><p>Click through the slides below to see how each of the preset views look.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>(opens in a new tab)</p><p>Text only:&#160;This just displays the name of the preset and is useful once you are familiar with the presets.</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;6</p><p>Next</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>(opens in a new tab)</p><p>Small Thumbnail: This is the default view and shows you a small thumbnail of each item.</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;6</p><p>Next</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>(opens in a new tab)</p><p>Large Thumbnail: This shows you a large thumbnail of each item.</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;6</p><p>Next</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>(opens in a new tab)</p><p>Small List: This shows the name and a small thumbnail of each item.</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;6</p><p>Next</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>(opens in a new tab)</p><p>Large List: This shows the name and a large thumbnail of each item.</p><p>Previous</p><p>Slide&#160;5&#160;of&#160;6</p><p>Next</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>(opens in a new tab)</p><p>Stroke Thumbnail: This option is only available for Brush presets and shows you a sample of how the brush strokes will look.</p><p>Previous</p><p>Slide&#160;6&#160;of&#160;6</p><p>Next</p></section><section><h3>Explore Brushes</h3><p>Explore Brushes</p><p>A brush preset is basically a pre-defined brush tip with specific characteristics like size, shape, hardness, stroke, etc. Photoshop gives you a library of preset brushes to choose from, but you can also create your own brushes, modify the existing preset brushes, or even download new brushes from the Adobe Photoshop website.</p><p>To fully explore the brush presets, open the brush panels from the&#160;Window&#160;menu by selecting&#160;Brush Settings&#160;and&#160;Brushes.</p><p>In the&#160;Brushes&#160;panel, you can explore all the available brushes from the library.&#160;By default, the Brushes panel has four folders.&#160;You can open each folder and select the brush you want to use from this list.</p><p>You can find a wide variety of free and purchased brushes that are available for Adobe Photoshop CC subscribers.&#160;Just click the&#160;Menu&#160;button in the&#160;Brushes&#160;panel and click&#160;Get More Brushes.&#160;This will take you to the Photoshop website, where you can browse through multiple brush packs for different types of illustrations and drawings.&#160;These brush packs will be downloaded as ABR files which you can then import into Photoshop.</p></section><section><h3>Explore Shapes and Symbols</h3><p>Explore Shapes &amp; Symbols</p><p>The&#160;Custom Shape&#160;tool is an often overlooked but very useful feature in Photoshop.&#160;You can view these shapes from the Preset Manager, but you can also access them from the Shape tool.</p><p>The&#160;Custom Shape&#160;tool is nested with the other shape tools like the&#160;Rectangle&#160;tool and&#160;Elliptical&#160;tool, so select it from that list.</p><p>Next, you can explore all the custom shapes that are available from the&#160;Options&#160;bar.&#160;Click the&#160;Shape&#160;drop-down list.&#160;Here, you can see a list of different shapes and symbols that you can add to your documents.</p><p>You can also click the&#160;Settings&#160;icon to view other shape sets that are available in Photoshop.</p><p>Let’s select&#160;All&#160;to view all the available shapes.</p><p>You can see that there are so many different shapes just ready to use in Photoshop.&#160;All you need is to select the shape you want, draw it and color it as you need.</p></section><section><h3>Explore Styles</h3><p>Explore Styles</p><p>Photoshop offers a number of preset styles and effects that you can apply to the objects on a layer.&#160;This includes styles like shadows, glows, bevels, etc. These styles are applied over objects in a non-destructive way so that you can always revert to your original image or shape.</p><p>Let’s explore what graphic styles are available in Photoshop.&#160;For this, you need to open the&#160;Styles&#160;panel.&#160;Do this by clicking&#160;Window&#160;and selecting&#160;Styles.</p><p>The&#160;Styles&#160;panel is added to your panels.&#160;You can move this panel to wherever you want on your workspace.&#160;As you can see, there are a number of preset styles available here.</p><p>You can use the&#160;Settings&#160;menu to change how these styles a<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b4951cfa3ce290d08e9a8de1cf1df9af','adobe-photoshop-m5-l6-lesson-5','0e8999f6230c6dc76db3da88188c679b','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Create &amp; Edit Brushes</h3><p>Create &amp; Edit Brushes</p><p>You’ve seen how you can access the library of brushes in Photoshop.&#160;You can also create your own custom brushes, group them and save them to your library.&#160;You can create brushes that apply color to images in a variety of ways.&#160;You can either build a brush from scratch by selecting everything from the brush tip and its color to the size, opacity, angle and more.&#160;You can also choose an existing brush and modify it to suit your needs.&#160;You can save any brush that you create or modify.</p><p>We cannot go into all of the different permutations and combinations of brushes that you can create, so make sure you use the links in the&#160;Additional Resources&#160;section at the end of this course to explore other exciting ways in which you can customize brushes.&#160;You will also find some great resources on the Photoshop website, as well as on YouTube.</p><p>First, let’s get familiarized with the&#160;Brush Settings&#160;panel.</p><p>On the top right, you can see a number of&#160;brush tip&#160;thumbnails to choose from.&#160;The number in each of these is the size of the tip, which you can adjust using this slider or by entering a value.</p><p>The&#160;Brush Tip Shape&#160;column in the left will show you the preset brush dynamics that are enabled for the brush tip that you select.&#160;You can add or remove dynamics based on your requirements.</p><p>You can use the&#160;Flip X,&#160;Flip Y, and&#160;Angle&#160;fields to adjust the angle of the brush stroke.</p><p>Roundness&#160;indicates the roundness of the brush stroke.&#160;Circular brushes will have a Roundness of 100% while linear brushes will have a roundness of 0%.&#160;Values in between indicate elliptical brushes.</p><p>Hardness&#160;is only available for round and square brushes and it controls the size of the brush’s hard center.&#160;Reducing the hardness gives your brush stroke softer, blurred edges.</p><p>Spacing&#160;controls the space between the brush marks in a stroke.&#160;You can use this in case of patterned or paint-type brush strokes to make the marks look more or less scattered.</p><p>Let’s see a simple example of how you can create a new brush and save it.</p><p>Start by selecting a new foreground color. Click the foreground color tile to open the Color Picker. Use the slider to select a new color and click&#160;OK. Next, let’s select the&#160;Brush&#160;tool and open the&#160;Brush Settings&#160;panel. You can see thumbnails of different brush tip options here. Let&#39;s select this&#160;Hard Round&#160;brush tip as a starting point. Now, the objective here is to create a highlighter tip. So, let’s increase this size to about&#160;200px. Now, because this is going to be a highlighter tip, it needs to look more angular. You can enter an angle directly here, or you can drag this arrow to the angle that you need. Next, the tip here looks too round, so let’s reduce the roundness to&#160;30%. Okay, all of these settings look fine. So, let’s close the Brush settings and make a few more adjustments.</p><p>Up here in the Options bar, you can see different&#160;Modes&#160;available. Because we’re trying to create a highlighter effect, let’s select a different mode, like&#160;Multiply. What this mode does is that when you add brush strokes over each other, it multiplies the color in the overlap to make it look darker in between, like it would if you drew with a highlighter on paper. Now, what else does a highlighter do? It has transparency so that it can show the text through the highlight. So, to replicate that, let’s change the&#160;Opacity&#160;here to&#160;25%.</p><p>Okay, now let’s test it out! I have some text here and I’ve added another layer so that the highlighter appears on a layer above the text. You can add strokes over this text, and as I&#39;m doing this, you can see that the overlap area is darker.</p><p>You can also mix it up and add two different colors to come up with more interesting effects! This was a really basic example of creating your own brushes, but as you can see, the possibilities are endless!</p><p>To save this brush as a preset, click the&#160;Brushes&#160;panel, and click the&#160;New Group&#160;icon down here. Let&#39;s name this group, I’ll call this&#160;My Group&#160;and click&#160;OK. Next, select the group click the&#160;Create New Brush&#160;icon. Name your new brush. I’ll call this&#160;Pink highlighter. You can choose which settings you want to include here. Let’s select all of these and click&#160;OK. You’ll see that the new brush appears here as a preview, and the color is indicated in this little swatch. You can select this brush from your new group folder at any time to use in your documents.</p></section><section><h3>Create &amp; Edit Shapes and Symbols</h3><p>Create &amp; Edit Shapes and Symbols</p><p>The&#160;Custom Shape&#160;tool is nested within the other shape tools in the Photoshop Toolbar.&#160;Let’s see how you can use the Custom Shape tool to create shapes and symbols in Photoshop.</p><p>To select the&#160;Custom Shape&#160;tool, click and hold the&#160;Rectangle&#160;tool and select the&#160;Custom Shape&#160;tool. You need to make sure you are drawing vector shapes because they are flexible, editable, and resolution-independent. This means that you can edit and scale them as much as you want without distorting the shape. So, to make sure you are selecting a vector shape, make sure that the Tool mode here is always&#160;Shape. Next, to select a shape, click this drop-down arrow. You can select one of these preset shapes, or you can click the&#160;Settings&#160;icon and select&#160;All&#160;to view all of the preset shapes that are available in Photoshop. Click&#160;OK. You can expand this box by dragging it out from here. As you can see, Photoshop gives you a lot of custom shapes and symbols to choose from.</p><p>To choose a shape, just double click on its thumbnail. Next, you need to choose a color for the shape. Click the&#160;Fill&#160;box in the&#160;Options&#160;bar. Right up here, you can see a few icons. This is the&#160;No Color&#160;icon, the&#160;Solid Color&#160;icon, the&#160;Gradient&#160;icon, and the&#160;Pattern&#160;icon. Let’s go with a solid color. You can select from the Swatches given here, or you can click this last icon to open the Color Picker.</p><p>Once you&#39;ve selected your color, we’re ready to draw the shape. To draw a shape, cli<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('070681b6dc35bb6254d5d89275182d18','adobe-photoshop-m5-l7-module-5-summary','0e8999f6230c6dc76db3da88188c679b','Module 5 Summary','text',12,'<h2>Module 5 Summary</h2><section><h3>Module 5 Summary</h3><p>Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module&#160;on Project Setup and Interface Part III!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Set the active foreground and background color.</p><p>Created and customized gradients.</p><p>Created and edited swatches.</p><p>Opened and browsed libraries of included brushes, symbols, graphic styles, and patterns.</p><p>Created and edited brushes, symbols, styles, and patterns.</p><p>Additional Resources</p><p>The following articles and websites were referenced in this module.&#160;If you want to learn more about colors, gradients, and brushes,&#160;check some of them out!&#160;(Not required reading)</p><p>Lesson 1</p><p>About color(opens in a new tab)</p><p>Set up color management(opens in a new tab)</p><p>Lesson 2</p><p>Blending Modes(opens in a new tab)</p><p>Lesson 5</p><p>Create and modify brushes(opens in a new tab)</p><p>Get Over 1000 More Brushes In Photoshop CC 2018</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('63da4b314dc1c9530e0a127530789679','adobe-photoshop-m5-l8-module-5-project','0e8999f6230c6dc76db3da88188c679b','Module 5 Project','text',12,'<h2>Module 5 Project</h2><section><h3>Module 5 Project</h3><p>2400</p><p>Adobe Photoshop</p><p>Project Setup and Interface Part III - Project</p><p>Project</p><p>In this assignment, you will apply all that you have learned about the project setup and the Photoshop interface to perform the following tasks. You will need to use Photoshop to perform these tasks. In some of these tasks, you may need to take screenshots and label them as well. You can save the screenshots as images or add them all to a Word/PPT document.</p><p>Open the attached image (birthday.png(opens in a new tab)) in Photoshop. Use it to create a custom color swatch and save it.&#160;(Take a screenshot of your saved custom swatch.)</p><p>Create a gradient using lighter versions of three colors from your custom color swatch. Make sure you save the new gradient.&#160;(Take a screenshot once this task is complete.)</p><p>Create a new brush style of your choosing and save it. Use the brush to decorate your card.&#160;(Take a screenshot once this task is complete.)</p><p>Add decorative shapes to your card. Create at least one shape with a solid fill using colors from your custom swatch, one with a gradient fill using your custom gradient, and one using one of the preset Photoshop styles.&#160;(Take a screenshot once this task is complete.)</p><p>Use one of the shapes to create and save a custom pattern. Open another document and apply the pattern.&#160;(Take a screenshot once this task is complete.)</p><p>Once you are done with all the tasks, save your Photoshop documents for review.</p><p>Project Setup and Interface Part III Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Set the active foreground and background color.</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Create and customize gradients.</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately with attention to detail and meeting all requirements.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well and gradients were not created as instructed.</p><p>5</p><p>Create and edit swatches.</p><p>5 points Demonstrated a strong understanding of the objective. The new swatch was created correctly.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. Almost all the instructions to create the new swatch were followed correctly, with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. Little to none of the instructions to create a new swatch were followed correctly.</p><p>5</p><p>Use the libraries of included brushes, symbols, graphic styles, and patterns and create new ones.</p><p>5 points Demonstrated a strong understanding of the objectives. The tasks were performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objectives. The tasks were performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objectives. The tasks were not performed well.</p><p>5</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('aae2af3b0632bbe80eeb8b6800450c39','adobe-photoshop-m5-l9-module-5-quiz','0e8999f6230c6dc76db3da88188c679b','Module 5 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Setup and Interface Part 3. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('ccb52b6be36b61ecde90ca987d01b1fd','adobe-photoshop-module-6','ee9c9635d1344f63172dfbcc5883d9ea','Module 6: Organizing Docs Part 1',6) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('12dd8e4cf5e22ac3ff554106953626fb','adobe-photoshop-m6-l1-introduction-purpose-and-objectives','ccb52b6be36b61ecde90ca987d01b1fd','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Welcome back! This is the intro video for the module on Organizing Documents Part I. How’s your Photoshop journey been so far? By now, you should be armed with a good understanding of design basics and basic project setup and interface options in Photoshop. We’ll now move on to what is arguably the most important part of Photoshop, that is, Layers! As you learn more about layers, you’ll see how they are an essential part of anything you do in Photoshop.</p><p>So what exactly are layers? Layers are basically like a stack of acetate sheets. They look like they’re one single document, but they are actually made up of multiple elements drawn on separate sheets. Okay, so they’re on different sheets, what’s the big deal? The great part of having elements on separate sheets is that you can add, delete, or modify elements on these sheets without making any changes to any of the other layers. You can even hide layers to see how your document looks with or without some elements. Let’s say you’re illustrating in Photoshop. You spend hours and come up with a beautiful illustration.</p><p>But you’re not quite happy with the results and you want to change the layout of the elements in your illustration. If you were doing this on paper, you would have to re-do the entire illustration! But with Photoshop layers, you can keep individual elements on different layers, thus allowing you to move them around and modify them as you please to easily create something like this.</p><p>Module Description</p><p>License:&#160;All Rights Reserved</p><p>Layers can help you manage all of the design elements of your document.&#160;They give you the flexibility to work on individual elements and adjust them as many times as you want till you have the perfect results.&#160;In this module, you will learn all about the Layers panel and how you can use it to create and modify layers.&#160;You’ll learn the mechanics of working with multiple layers on complex projects.&#160;You will also be introduced to new concepts like flattening and merging layers, as well as different types of layers.</p><p>Objectives</p><p>In this module, students will:</p><p>Use the Layers panel to modify layers</p><p>Manage layers in a complex project</p><p>Work with multiple layers</p><p>Flatten and merge layers</p><p>Recognize the different types of layers in the Layers panel</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('45b218c71240b0dbaff2b0f8a1534def','adobe-photoshop-m6-l2-lesson-1','ccb52b6be36b61ecde90ca987d01b1fd','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Layers Panel</h3><p>Layers Panel</p><p>Let’s kick off this module by exploring the&#160;Layers&#160;panel.&#160;You can find the Layers panel in the lower right corner of the Photoshop screen.&#160;It lists all of the layers, groups, and layer effects.&#160;You can use this panel to add, edit, delete, show, hide, and group layers.</p><p>Click each hotspot to learn more.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Activity to explore the different sections of the Layers panel.</p><p>The hotspot points on the image are as follows:</p><p>Filter Options</p><p>These settings allow you to apply and adjust filters to the layers.</p><p>Blend Mode and Opacity</p><p>These setting allow you to adjust how layers blend with each other.</p><p>Lock Options</p><p>These settings give you different options to lock and unlock elements on layers.</p><p>Layers and Groups</p><p>This section shows all the layers and groups of your document, along with a name and preview thumbnail.</p><p>New and Other Options</p><p>Use the icons in this section to create new layers, effects, adjustments, etc, as well as to delete layers.</p><p>You can also access additional commands and layer editing options in the&#160;Layers panel menu.</p><p>You can click&#160;Panel Options&#160;from the&#160;Panels&#160;menu to adjust the display settings of the panel, like the size of thumbnails and other settings.</p><p>You can also access layer settings from Photoshop’s top menu bar by clicking the&#160;Layer&#160;button.</p></section><section><h3>Adding &amp; Duplicating Layers</h3><p>Adding &amp; Duplicating Layers</p><p>When you create a blank document in Photoshop, it opens with only a Background layer.&#160;This is the base layer of your document.&#160;To add a new layer to your document, click the&#160;Create a&#160;new layer&#160;icon at the bottom of the Layers panel.&#160;You can also open the&#160;Layer menu&#160;and click&#160;New Layer.&#160;If you are more comfortable using keyboard shortcuts, just enter&#160;Shift + Ctrl + N&#160;(on Windows) or&#160;Shift + Command + N&#160;(on Mac).</p><p>A new layer is added.&#160;You’ll notice the thumbnail has a checkerboard pattern on it, which indicates that this is a transparent layer.</p><p>Always keep an eye on which layer is selected when you click the&#160;Create a&#160;new layer&#160;icon.&#160;Your new layer will be added right above that layer.&#160;So, if you want to create a new layer just above the Background layer, just select it and then create a new layer.</p><p>You can also duplicate layers in Photoshop.&#160;Just select the layer you want to duplicate.&#160;Drag the layer to the&#160;New Layer&#160;icon and drop it.&#160;A duplicate layer will be created.&#160;You can also select the layer and then click&#160;Duplicate Layer&#160;from the&#160;Layer&#160;panel menu.</p></section><section><h3>Renaming Layers</h3><p>Renaming Layers</p><p>When you create a new layer, it has a generic name like “Layer 1”.&#160;You can rename this so that it is easier to find elements in your Layers panel.&#160;To rename a layer, just double-click on the layer name.&#160;It will become editable and you can enter any name you want.</p></section><section><h3>Moving Layers</h3><p>Moving Layers</p><p>The way that layers are displayed in the Layers panel is how they are layered on your document.&#160;So, layers shown at the top of the list will appear above the layers below.&#160;For example, in the screenshot below, the layer &#39;Vacation&#39;&#160;is placed on top of the layers &#39;Green gradient&#39;&#160;and &#39;pier&#39;, which is why it appears over the two elements in the image here.</p><p>You can easily move it by selecting and dragging it up or down.&#160;So if you move the &#39;Vacation&#39;&#160;layer down below the&#160;&#39;Green gradient&#39;&#160;layer, you will see that it appears behind the gradient in the image.</p></section><section><h3>Hiding &amp; Showing Layers</h3><p>Hiding &amp; Showing Layers</p><p>If you look at the Layers panel, you will see an&#160;Eye&#160;icon at the beginning of each layer.&#160;This icon indicates the layer visibility.&#160;While working on documents with multiple layers, you may want to hide one or more layers so that you can work directly on another layer.&#160;Hiding layers can also help&#160;you visualize how your document may look with or without one or more elements.&#160;This doesn’t delete the layer, it simply hides it.</p><p>To hide a layer, just click the&#160;Eye&#160;icon.&#160;You can hide as many layers as you want.&#160;To show hidden layers, simply click the&#160;Eye&#160;icon again.</p><p>There may be situations where you have a large number of layers in a document.&#160;To hide or show multiple layers at once, you can just click the&#160;Eye&#160;icon once and drag down to hide or show them all.</p></section><section><h3>Locking &amp; Unlocking Layers</h3><p>Locking &amp; Unlocking Layers</p><p>Photoshop gives you a few different ways to lock layers and elements on the layer.&#160;Let’s take a closer look at the&#160;Lock&#160;options.</p><p>Lock transparent pixels:&#160;This locks only the transparent pixels of an image.&#160;This way, you can lock the transparent areas of an image and only make changes to the main content area of the image.</p><p>Lock image pixels:&#160;This locks all the pixels, both content and transparent, on the layer.</p><p>Lock position:&#160;This locks the position of a layer to prevent it from being accidentally moved around in the document.</p><p>Lock all:&#160;This locks all elements of the layer.</p><p>You can select any of these lock options by clicking on the icon.&#160;To unlock the layer, just click the icon again.&#160;If any of these lock options are selected, you will see a lock appear against that layer.&#160;You can also click that lock icon to unlock the layer.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('262de99c57107deee3243c31b7d3856d','adobe-photoshop-m6-l3-lesson-2','ccb52b6be36b61ecde90ca987d01b1fd','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Managing Layers with Layer Groups</h3><p>Managing Layers with Layer Groups</p><p>License:&#160;All Rights Reserved</p><p>Managing Layers with Layer Groups</p><p>Once you start using layers, you will see just how much easier they make it for you to work in Photoshop.&#160;Although layers make editing and retouching images and documents much easier, you may find that you have a really large number of layers piling up, which can be difficult to track and manage.</p><p>There are a few things you can do to organize and sort your layers.&#160;If your computer desktop was filled with files and applications, what would be the first thing you would do to organize them?&#160;Categorize them into folders and subfolders!&#160;Similarly, in Photoshop, the first thing you can do is create&#160;Layer Groups.</p><p>You can categorize the items on your document, and then group them into layer groups.&#160;You can organize these groups however you want.&#160;Although, it is best to group layers that appear in a sequence and are not in different places in your document because that can cause elements to get misaligned and distort your layout.</p><p>To create a layer group in Photoshop, just click the&#160;Group&#160;icon at the bottom of the Layer panel. A new group will be created with a generic name like “Group 1”. You can easily rename this by double-clicking the folder and entering a new name. You can then drag and drop the layers that you want to group into the folder. Just make sure that when you drop the layers, you place them in the correct order.</p><p>Another way of creating a group is to use the Shift key to select all the layers that you want, and then opening the Layer panel’s menu and select&#160;New Group From Layers. This will create a new group with the layers that you selected. you can also just drag these down to the Group icon and drop them there, and it will automatically create a new group.</p><p>To open a layer group and view the layers in it, just click this arrow button. The layers in that group will appear in a staggered view below the folder. In this way, you can create multiple groups and keep them closed and neat. This allows you to clearly see the different groups of elements on your document and work on them as required. Another advantage of grouping layers is that you can easily hide or lock all the layers in a group.</p><p>To remove layers from a group, just right-click the group and select&#160;Ungroup Layers. You can also open the group and drag and drop the layer outside. You will see a line appearing showing you a drop zone where you can drop the layer. This is a good option if you want to just remove a few layers and you don’t want to remove all the layers from the group.</p><p>In the same way that you created a Layer group, you can also create a group of different groups. Select all the groups you want to nest inside a group, right-click them and select&#160;New Group From Layers. Give the new group a name. And just like that, you can create an entire hierarchy of elements, all neatly organized into groups.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ea31a008f2fb180ed10ced8fc8b9911a','adobe-photoshop-m6-l4-lesson-3','ccb52b6be36b61ecde90ca987d01b1fd','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Selecting Layers</h3><p>Selecting Layers</p><p>Let’s look at some of the different tasks you may need to do when working with multiple layers.</p><p>When you are working on a document with multiple layers, you can select a layer from the Layers panel to work on it.&#160;A selected layer is called an&#160;active layer, and you can see the name of the active layer on the&#160;Document&#160;tab.</p><p>There are many tasks for which you need to work on multiple layers at once.&#160;This includes tasks like aligning, moving, transforming, applying styles, and more.&#160;You can select multiple layers from the&#160;Layers&#160;panel or using the&#160;Move&#160;tool in Photoshop.</p></section><section><h3>Selecting Layers in Photoshop</h3><p>Selecting Layers in Photoshop</p><p>While watching the video below, open your own Photoshop document and try to follow the steps along with the video.</p><p>There are a few different ways in which you can select multiple layers in Photoshop. If you want to select a series of adjoining layers, click the first layer, and then press and hold down the Shift key and click the last layer. All the layers in between the two will be selected. If you need to select non-adjoining layers, then just press and hold the Ctrl key (or the Command key in Mac) and individually select the layers. And if you need to select all of the layers of your document, just click the&#160;Select&#160;menu here and select&#160;All Layers. You can also use this keyboard shortcut.</p><p>If you have a large number of layers, it can become difficult to scroll through all of the layers to find the layers that you want to select. In this case, you can use the&#160;Filter&#160;options to filter the layers using different categorizations. For example, the default option here is&#160;Kind,&#160;which is short for &#39;kind of layer&#39;. All you need to do is click these icons right here, and as you can see, this will filter for&#160;pixel layers, this will filter for&#160;adjustment layers, this filters for&#160;type or text layers. So, if I click here, I only see the text layers displayed.</p><p>You can also apply this to multiple layers. So let&#39;s say I select this and I filter for shape layers as well, it will show me all the layers that fulfill either one or all of these filters.</p><p>Instead of&#160;Kind, you can also use other categories to filter layers. For example, if you have used some kind of naming convention for your layers, you can enter keywords to filter out those layers. Similarly, you can also filter layers that have a similar kind of effect applied to them. The filter feature is really useful if you want to filter layers to group them, or to apply effects or filters to a certain type of layer.</p><p>You can also select layers from the document window itself using a really useful feature called&#160;Auto-select. First, make sure the&#160;Move&#160;tool is selected. In the Options bar, you will see this icon selected. This is the Auto-select option. This feature allows you to automatically select a layer or group when you click on it. It also gives you the option to select a layer or group using this drop-down list here. So let’s say I want to select a layer. If I click here, you can see in the Layers panel that it has selected this layer. But if I change this to &#39;group&#39; and click in the same place, you&#39;ll see that&#160;it has selected the entire group.</p><p>Another thing you can do is right-click on the document itself, and a popup appear showing you a list of layers and groups that contain pixels at this point. So you can see that if you right-click at different places, you&#39;ll see a different list of layers.</p><p>Here’s another great trick that you can use. To select all the layers in one particular section or area of the document, all you need to do is to click and drag your mouse over the area, and all the layers that you pass your cursor over will be selected. Now, if you scroll down, you&#39;ll see that the image right here hasn&#39;t been selected even though my cursor rolled over it. One thing to remember here is that locked layers will not be selected, so if you want to include those in your selections, make sure that you unlock them first.</p></section><section><h3>Grouping vs. Linking Layers</h3><p>Grouping vs.&#160;Linking Layers</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>You’ve already seen how you can group layers to organize them.&#160;You also learned how to filter layers so that you can group them.&#160;When you select a group, all the layers in the group are also selected.</p><p>When you&#160;group layers, they are usually grouped in a certain order and will need to be kept in that order.&#160;If you group a layer that is right at the bottom and one right at the top of all layers, then the alignment and layout of layers will be distorted.</p><p>The alternative to this is to&#160;link layers.&#160;Linked layers form a relational bond between them which allows you to make certain changes to all linked layers at once.&#160;You can also link layers from different groups, as well as in different locations on your document, meaning that you can link your top layer with one of the lower layers, and it will not affect your document layout.</p><p>Generally, you would link layers that you want to&#160;transform, move, scale,&#160;or&#160;resize together.&#160;But remember, if you make a change to a linked layer, it will affect all other linked layers, irrespective of which group they are in.</p><p>To link layers or groups, select them using one of the methods you learned about earlier, and click the&#160;Link&#160;icon at the bottom of the&#160;Layers&#160;panel.&#160;You will see a link icon appear near all the linked layers.</p><p>Now, let’s say you want to move all the linked layers.&#160;Just select one of the linked layers and move it, you will see that all the linked layers also move along with it.</p></section><section><h3>Align and Distribute Layers</h3><p>Align and Distribute Layers</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>When you work with multiple layers, you may often need to align all the layers with each other to be more symmetrical or organized.&#160;Now, if you were using a tool like PowerPoint, or even Adobe Illustrator, you can just select all of the items by dragging your cursor over them and use the Align tools provided to align them.</p><p>But in Photoshop i<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e53ea910179767410d2e199bd2f3d3e7','adobe-photoshop-m6-l5-lesson-4','ccb52b6be36b61ecde90ca987d01b1fd','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Merging Layers</h3><p>Merging Layers</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Let’s say you are working on a document in Photoshop that uses multiple layers.&#160;Once you finalize your document, you may find that your file size is quite large.&#160;One of the things you can do to reduce this file size is to&#160;merge layers.&#160;Merging layers causes the data of all of the layers to be merged into one layer.&#160;If any areas of the layers overlap, then the data of the layers on top will replace the data of the lower images.&#160;If there are overlapping transparent areas, they will remain transparent.</p><p>You should always make sure you are merging layers that are final and don’t need any more edits because once you save a merged file, you cannot go back in and edit the layers.</p><p>You also have the option to merge layers into a new layer that will be created in addition to the original layers.&#160;That way, you can always go back in and edit your original layers and re-merge them if required.&#160;The challenge here is that after merging the layers, if you make any changes to the merged file, like adding a filter or effects, you will need to re-do those changes if you go back in and make changes to the original layers.</p><p>Another thing to note is that if you merge text layers, they will be converted to images and will no longer be editable.&#160;So always make sure any text layer you want to merge are final and will not require changes before you merge them.</p></section><section><h3>Merging Layers as a Smart Object</h3><p>Merging Layers as a Smart Object</p><p>All the challenges related to merging layers have one simple solution—just convert your layers into smart objects.&#160;Smart objects&#160;are a fantastic feature because they give you the flexibility to go in and edit objects even after they are merged.&#160;Because they are non-destructive, you can go in and edit your individual layers at any time and any changes you make will be reflected in your merged document.</p><p>To do this, all you need to do is to convert all the layers you want to merge into smart objects.&#160;You can then merge the layers as usual.</p></section><section><h3>Merging Layers Example</h3><p>Merging Layers:&#160;Example</p><p>Let&#39;s take a look at an example of merging layers in Photoshop.</p><p>I have a document here with multiple layers. To merge these layers, all I need to do is select the layers that I want to merge, open the&#160;Layers panel&#160;menu, and click&#160;Merge Layers. You can also use the keyboard shortcut&#160;Ctrl + E&#160;in Windows or&#160;Command + E&#160;in Mac. And all the layers will be merged into a single layer. Let&#39;s undo this.</p><p>You can also just keep the layers that you want to merge visible. So I&#39;ll remove visibility from these layers. Now, let&#39;s just merge the layers that are visible. To do this, go back to the Layers panel menu and click&#160;Merge Visible. Again, you can choose to use the keyboard shortcut Shift + Ctrl E and only the visible layers will be merged.</p><p>If I select this merged layer, you&#39;ll see that it is no longer editable. So, if I need to make any changes to these individual, original layers, there is no way I can do that right now. So let me undo this change. A solution to this is to merge these layers as a separate layer. So to do that, let’s go back to the menu, and before you click on&#160;Merge Visible, just press and hold down the&#160;Alt&#160;key, or you can use the keyboard shortcut&#160;Alt + Shift + Ctrl + E&#160;on Windows or&#160;Alt + Shift + Command+ E&#160;on Mac. The merged layer is created as a separate layer and the original layers are still here.</p><p>Now, this option is better, but you will still need to redo any changes you make to this merged file if you need to go back in and modify any of the original layers. So let’s see how you can combat this. First, I&#39;ll make all the layers visible.&#160;Select all the layers that you want to merge, open the Layers panel menu, and select&#160;Convert to Smart Object. This will convert all the layers into smart objects and merge them into a single layer. Now here’s the awesome part, because you used merged layers that were smart objects, you can easily edit the original layers by just double-clicking the thumbnail of this new layer. This will open in a new document window. And the best part is, all of the original layers are still here! So now, I can just select any layer that I want, make whatever changes that I want to it, and just save it. And if you go back to the original document, because the layers were smart objects, all of the changes are reflected here! So anytime you need to merge layers, make sure that you first convert your layers to smart objects first so that you can always go back in and make any changes that you need to.</p></section><section><h3>Flatten Layers</h3><p>Flatten Layers</p><p>Flattening is similar to merging. It reduces the file size by merging all of the layers into the background layer and discarding any hidden layers. One thing to remember is that because all of the layers are being merged into the background, all transparency of the flattened layers will be lost. Also, while merged layers can still be saved as a .PSD file, flattened images are always images when you save them and will be in a .JPG format. You cannot revert to the un-flattened state once you flatten your document, so make sure the document is final before you do this.</p><p>To flatten layers, first, make sure all the layers you want to flatten are visible. Then open the&#160;Layers&#160;panel menu and click&#160;Flatten Image. All the layers will be flattened into a single image.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7394f8d7dbaba8238f305d7c01d5243b','adobe-photoshop-m6-l6-lesson-5','ccb52b6be36b61ecde90ca987d01b1fd','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Types of Layers</h3><p>Types of Layers</p><p>As you start to work with layers, it is important to recognize the different types of layers.&#160;Some of these types are defined by Photoshop itself, while others are defined as you add them to your document.</p><p>It is important for you to be able to identify the types of layers in Photoshop.&#160;This will allow you greater flexibility in performing many tasks, like grouping related layers, filtering based on the type of layer, and more.</p><p>Click each hotspot to learn more.</p><p>Pixel-based Layers</p><p>This is the most basic and default type of layer that is created in Photoshop. This is also called a raster-based layer because it includes a photo or a non-vector drawing or image. The drawback to these types of layers is that because they are non-vector layers, they do not magnify well, so if you try to resize them or make them larger, they will distort or look pixelated.</p><p>Adjustment Layers</p><p>As the name suggests, these layers allow you to modify the color, brightness, saturation, and other settings without modifying the original image. They are similar to fill layers where the entire layer is filled with a gradient, color or pattern.</p><p>Type or Text Layers</p><p>Any time you create a new layer and start typing using a text tool, the layer is converted to a text layer. Text layers are vector layers, which means you can scale them to any size without loss of quality.</p><p>Shape Layers</p><p>Any time you select a shape tool and draw a shape on a new layer, it is converted to a shape layer. Just like Text layers, Shape layers are also vector layers.</p><p>Smart Object Layers</p><p>You can convert any layer to a Smart Object layer, as you’ve learned in this and previous modules. Smart object layers give you the flexibility to make modifications at any time without having to create the image from scratch again.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e98e8cdbb5f925961328bb545ec71d97','adobe-photoshop-m6-l7-module-6-summary','ccb52b6be36b61ecde90ca987d01b1fd','Module 6 Summary','text',12,'<h2>Module 6 Summary</h2><section><h3>Module 6 Summary</h3><p>Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Organizing Documents Part I!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Used the Layers panel to modify layers.</p><p>Managed layers in a complex project.</p><p>Worked with multiple layers.</p><p>Flattened and merge layers.</p><p>Recognized the different types of layers in the Layers panel.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('52dc5b7ae910af6774a41a00bdf8a029','adobe-photoshop-m6-l8-module-6-project','ccb52b6be36b61ecde90ca987d01b1fd','Module 6 Project','text',12,'<h2>Module 6 Project</h2><section><h3>Module 6 Project</h3><p>2400</p><p>Adobe Photoshop</p><p>Organizing Documents Part I - Project</p><p>Project</p><p>In this assignment, you will apply all that you have learned about using layers to manage the design elements of a document. You will need to use Photoshop to perform these tasks. In the last module, you created a birthday card in Photoshop. You can use the same .psd file to do the following tasks. Take screenshots after completing each step and save them as image files or add them to a Word/PPT document.</p><p>Open your Photoshop document and duplicate one of the existing layers. Rename the layer with the word “Duplicate” added to the title and hide the new layer.&#160;(Take a screenshot once the task is complete.)</p><p>Next, create a layer group and organize all of your layers into groups.&#160;(Take a screenshot once the task is complete.)</p><p>Select all the shape layers in your document and link them to each other.&#160;(Take a screenshot once the task is complete. The screenshot should show the link icons next to the linked layers.)</p><p>Demonstrate how you can merge all the layers in your document while still being able to edit the original layers. Also, flatten the document into a separate layer.&#160;(Take a screenshot of the merged and the flattened layer once the task is complete.)</p><p>Take screenshots of 3 different types of layers and explain how you can identify them.&#160;(You can save the screenshot in a Word/PPT document and add your explanations in the document.)</p><p>Review the rubric below to see how you will be graded.</p><p>Organizing Documents Part I Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Use the Layers panel to modify layers</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Manage layers in a complex project</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately with attention to detail and meeting all requirements.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well and layer groups were not created as instructed.</p><p>4</p><p>Work with multiple layers</p><p>4 points Demonstrated a strong understanding of the objective. The linking of layers was done correctly.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. Almost all the instructions to link layers were followed correctly, with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. Little to none of the instructions to link layers were followed correctly.</p><p>4</p><p>Flatten and merge layers</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately and merging and flattening was done as instructed.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Recognize the different types of layers</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately and as instructed.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7cf41f7c41666a2125af6d0df098f6d5','adobe-photoshop-m6-l9-module-6-quiz','ccb52b6be36b61ecde90ca987d01b1fd','Module 6 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Organizing Docs Part 1. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('24b1d8a12143148190121e0f3ccc1573','adobe-photoshop-module-7','ee9c9635d1344f63172dfbcc5883d9ea','Module 7: Oraganizing Docs Part 2',7) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('eeafef935afcce5d9e02c0c82db769e2','adobe-photoshop-m7-l1-introduction-purpose-and-objectives','24b1d8a12143148190121e0f3ccc1573','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Select a Student</p><p>Hey there! This is the intro video for the module on Organizing Documents Part II. You’ve made a great start with learning about Photoshop Layers. You now know all the basics, what layers are, how you can use the layers panel to create, manage and modify layers. You also learned about different things you can do with layers, like grouping, hiding, locking, merging and flattening them.</p><p>But there’s still so much more you can do with layers! You can play with the transparency and opacity of a layer to create complex images, you can use blending modes and masks to add texture and fun to your images. Photoshop gives you so many different ways of editing your photos and we’ve only begun to scratch the surface. You’ll learn about destructive and non-destructive methods of editing photos and when to choose which option. So let’s dive in!</p><p>Module Description</p><p>Select a Student</p><p>In this module, students will learn how to modify a layer’s visibility by adjusting opacity and using blending modes.&#160;They will learn about masks and how to apply them to layers.&#160;Students will gain an understanding of what non-destructive and destructive editing are, as well as the key differences between them.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3db58b2de1d1917a5bccd97785e5017f','adobe-photoshop-m7-l2-lesson-1','24b1d8a12143148190121e0f3ccc1573','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Adjusting Opacity</h3><p>Adjusting Opacity</p><p>Select a Student</p><p>In Photoshop, the transparency function is what enables you to have transparent areas on an image or layer.&#160;You have seen some examples of how you can use transparency when you learned about gradients.&#160;There are some image formats that don’t support transparency and thus cannot be transparent or have transparent layers.</p><p>Opacity is defined as the extent to which something blocks light.&#160;There are a few different settings in Photoshop that you can use to specify the opacity of layers and images.&#160;Layer Opacity&#160;and&#160;Fill Opacity&#160;help you control the opacity of a layer in Photoshop.&#160;Blending Modes&#160;are another tool you can use to specify how pixels are affected when you use a paint or editing tool.</p><p>Let’s start off by learning about Overall Opacity and Fill Opacity.&#160;While they both control the transparency of your layers, they have different applications and effects on your layers.</p></section><section><h3>Overall Opacity</h3><p>Overall Opacity</p><p>Select a Student</p><p>You can find the controls for both&#160;Overall Opacity&#160;and&#160;Fill Opacity&#160;in the&#160;Layers&#160;panel right next to each other.</p><p>Both of these settings control the opacity of a layer.</p><p>The overall opacity controls the transparency of a layer—that is, to what degree a layer blocks or shows the layer underneath it.&#160;If a layer has 100% opacity, it will look completely opaque and you won’t be able to see the next layer beneath it at all.&#160;If a layer has 1% opacity, it will be almost fully transparent.</p><p>To adjust the overall opacity, just select a layer in the Layers panel and modify the percentage value in the&#160;Overall Opacity&#160;field.</p><p>Note:&#160;Remember that you cannot change the opacity of the background layer or of a locked layer.&#160;So in these cases, either change the background layer to a regular layer or first unlock the layer.</p></section><section><h3>Fill Opacity</h3><p>Fill Opacity</p><p>Select a Student</p><p>At the outset, the Fill Opacity may seem to be the same as the Overall Opacity.&#160;You can adjust the Fill Opacity of an image, shape or text to make it more or less transparent.</p><p>They seem to be doing the same thing, right?&#160;Let&#39;s talk about the difference between Overall and Fill Opacity.</p><p>The Overall Opacity also affects any layer styles, effects or blending modes that you may have applied to a layer.&#160;But the Fill Opacity only affects pixels, shapes, and text on a layer.&#160;It doesn’t affect the opacity of any effects applied to the layer like strokes, drop shadows, bevels, etc. What does that mean?&#160;Let’s see this with an example.</p><p>We have a shape here that has a pink outline applied to it.&#160;This outline is called a&#160;stroke&#160;in Photoshop.&#160;A stroke is basically any colored border that you can add around a selection, path or layer in Photoshop.&#160;We’ll first change the Overall Opacity and then the Fill Opacity.</p><p>When you adjust the Overall Opacity, you can see that the stroke around the shape also becomes more transparent as you reduce the opacity.</p><p>When you adjust the Fill Opacity, the stroke of the shape remains fully opaque and only the ‘fill’ becomes more transparent.&#160;The Fill Opacity setting doesn’t have an impact on any layer styles or effects, which allows you to create interesting effects on photos, shapes, and text which would not be possible by just adjusting the Overall Opacity.</p></section><section><h3>Overall Opacity vs. Fill Opacity</h3><p>Overall Opacity vs.&#160;Fill Opacity:&#160;Example</p><p>Select a Student</p><p>Let&#39;s see an example of the type of effects that you can apply using Fill Opacity that cannot be achieved with Overall Opacity.</p><p>To see the differences between Overall Opacity and Fill Opacity, let’s take a look at an example. I have an image here, and I’ve added a layer of text over it. I’ve duplicated this layer so that you can see the differences when I adjust the Overall Opacity versus the Fill Opacity.</p><p>Now, in both of these layers, you can see here that I have applied some layer effects, which is denoted by this fx symbol here. I can expand this to see what effects have been applied. I’ve applied a Bevel &amp; Emboss effect which you can&#39;t really see here in this image, and I’ve also applied a Drop Shadow and an orange Stroke which you can see clearly.</p><p>Now, let’s see what happens if I adjust the opacity. First, let’s hide the other layer. Next, let’s select this layer and let&#39;s reduce the Overall Opacity. So, just click this drop-down and drag the slider down. Now, as I&#39;m dragging this lower, you can see that the entire layer is getting more and more transparent, including the Stroke and the Drop Shadow.</p><p>Now, let&#39;s see what happens if I adjust the Fill Opacity. Let’s hide this layer and make the other layer visible. Now, let&#39;s select this layer and let’s adjust the Fill Opacity. As I reduce the opacity, you will see that only the fill, that is the white part of the text is becoming more transparent. The Stroke and the Drop Shadow remain unaffected, and if I keep reducing the opacity lower and lower, you will see the Bevel &amp; Emboss effects emerging.</p><p>So you can see how you can play with the layer effects and adjust the Fill Opacity to create unique effects that cannot be achieved with just adjusting the Overall Opacity.</p></section><section><h3>Blending Modes</h3><p>Blending Modes</p><p>Select a Student</p><p>by Shutterstock</p><p>License:&#160;All Rights Reserved</p><p>You just learned how to use opacity to control the visibility of pixels of an image or shape and create different effects.&#160;Many times, using just opacity can be limiting and may not give you the kind of exciting, interesting results you may be looking to create.</p><p>Blending modes give you an array of creative ways to blend images and layers.&#160;They are very easy to use and are a great tool to use for editing and touching up photos.</p><p>But what are blending modes?</p><p>In Photoshop, blending modes determine how pixels in different layers blend or interact with each other.&#160;You can access the blending modes either from the Layers panel or from the Options bar when you select paint tools like the Brush tool, Paint Bucket tool, Blur tool, Stamp tool, etc.</p><p>Ph<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f42dbb0c742c71481af0d8079a5bffe5','adobe-photoshop-m7-l3-lesson-2','24b1d8a12143148190121e0f3ccc1573','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Layer Masks</h3><p>Layer Masks</p><p>Layer masks may seem like an advanced topic, but the fundamentals are quite simple.&#160;Layer masks basically allow you to control the transparency of a layer.&#160;You can add a mask to a layer to hide certain portions of that layer and thereby reveal portions of the layers below it.&#160;Masking is a great way of combining two or more images seamlessly, or for removing objects from an image.</p><p>What about Opacity?</p><p>Now, you may ask, doesn’t the Opacity feature do the same thing?&#160;Control the transparency of a layer?&#160;Right you are!&#160;But there is one key difference.&#160;When you adjust the opacity of a layer, you are changing the opacity of the&#160;entire&#160;layer.&#160;This is useful in some situations, but when you want to combine two images, you may only want to make certain parts of the image transparent to let the other image show through.&#160; The Opacity feature doesn’t let you control this.&#160;So this is where masks come in.</p><p>How about the Eraser tool?</p><p>Another Photoshop tool that can adjust transparency is the Eraser tool.&#160;You can use it just as you would use a brush and erase off part of the image you don’t want to show, and it will reveal the content from the layer below it.&#160;That should work, right?&#160;While this does technically give you the results you want, it is never recommended to use the Eraser tool for this task.&#160;That’s because any edits you make with the Eraser tool are permanent, that is, it is a Destructive Edit.&#160;(We’ll discuss destructive edits in details in the next lesson.&#160;) But why does it matter if it is permanently removed?&#160;Well, if you realize later on that you have erased too much of the image, or that you want the original image back to blend it with another image, then you will not be able to retrieve your original image from Photoshop.&#160;You would then need to open the original image, if you still have it, and start work from scratch.</p><p>How does Masking Work?</p><p>Layer masks, like the name suggests, are masks that sit over your layer.&#160;You can edit the transparency of your layer by making edits to the mask, thus leaving your image in its original state.</p><p>A layer mask is a grayscale image, which means it only uses the colors black, white, and all the shades of gray in between them.&#160;So why only these colors?&#160;In a layer mask, white represents the areas of the image that should remain completely visible.&#160;Black represents the area of the image that should be completely erased.&#160;And any shade of gray will make that area of the image partially transparent.</p><p>When you add a mask to a layer, the default color is white, which means that the entire image will be&#160;100% visible.&#160;The mask uses black to show which areas of the image should be&#160;100% transparent.&#160;So when you want to hide certain areas of an image using a layer mask, you would choose the&#160;Brush tool,&#160; select the color black and then paint the areas that you want to make transparent.&#160;You can use different brush styles like a soft edge brush, etc., to give you those gray tones to make those areas partially transparent, almost like a gradient effect.</p></section><section><h3>Creating Layer Masks</h3><p>Creating Layer Masks</p><p>Let’s see how you can easily use layers masks to blend two images.</p><p>The first step is to open the two images that you want to combine in Photoshop. I already have two images open here. Next, you need to position the images in the way that you want to blend them. So, to do that, I’ll just move this image a little to the left, I&#39;ll hide this layer, and I&#39;ll move this image a little to the right. That looks fine. Now, I want to blend this top image into the lower image. This means that I will need to hide parts of the top image to let the bottom image show through. So the first step is to select the top layer and click the&#160;Add Layer Mask&#160;icon at the bottom of the&#160;Layers&#160;panel.</p><p>Now the image still looks the same, but if you look in the Layers panel, you will see that the layer thumbnail is now linked to a white layer mask thumbnail. If you remember, white means that the image will be completely visible, as you can see here. Let’s see what happens if you fill this layer with black. To do that, make sure the layer mask thumbnail is selected. You can see that it is selected by this border around it. Now, let&#39;s go up to the&#160;Edit&#160;menu and click&#160;Fill. from this drop-down list, let&#39;s select&#160;Black&#160;and click&#160;OK. This will make the entire layer mask black. You can see here that the top layer is now completely transparent, and you can only see this second layer here. Now let’s see what happens if you fill this with gray. So go back to the&#160;Fill&#160;window, click the drop-down list again, and select&#160;50%&#160;Gray&#160;and click&#160;OK.</p><p>Now, you’ll see that the layer has re-appeared, but the entire layer is semi-transparent. This looks similar to how it would if you would have used the Opacity setting to adjust the visibility. Let’s go back to the default white background. Click&#160;OK.</p><p>Now, we’ll be using the&#160;Brush tool&#160;to select the parts of the layer that we want to hide. So select the&#160;Brush&#160;tool and let’s adjust the brush settings in the&#160;Options&#160;bar. But first, make sure that your foreground color is black. If not, just click this icon here to reset the color to the default settings. Next, open the&#160;Brush Preset Picker. Let’s increase the brush size, and reduce the Hardness to 0. That will give us that gradient effect with completely soft edges.</p><p>Now, let’s paint the areas of the image that we want to hide. You’ll notice that there is no brush color while I’m painting this, but with each stroke, you can see that the parts that I am painting over are becoming transparent. I’ll keep going till I get the effect that I want. Because I changed the hardness settings to 0%, you can see that the edges over here are completely smooth, and it looks like both the images are blending perfectly into each other.</p><p>Now, if you look at the layer mask thumbnail, you can see the black areas where I masked the image. If you want to view just the layer mask separately, just press and hold down the Alt key (in Windows) or the Options key (in Mac) and click the thumbnail. This<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3ec91c288b0cb5f88b699bc8a53c003f','adobe-photoshop-m7-l4-lesson-3','24b1d8a12143148190121e0f3ccc1573','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>What is Non-Destructive Editing</h3><p>What is Non-Destructive Editing?</p><p>Non-destructive editing is a technique that allows you to make changes to your image without overwriting the original image content.&#160;This means that the original pixels of the image are always intact and available whenever you need to access it.&#160;Because non-destructive editing always maintains all of the data of the image, this also means that the image quality doesn’t degrade when you make edits.&#160;Photoshop gives you a number of options to perform non-destructive editing.&#160;You just learned about one of them, that is using masks to modify a layer’s visibility.</p><p>Take a look at this video to understand why it is always better to work non-destructively in Photoshop.</p><p>Video Title:&#160;Why Work Non-destructively in Photoshop?</p><p>Video Publisher:&#160;photoshopCAFE(opens in a new tab)</p><p>License:&#160;No known copyright restrictions</p><p>Smart Objects</p><p>Smart objects are a very useful feature of Photoshop.&#160;They are layers that contain the image data of Photoshop images.&#160;Smart objects are basically containers that protect the original source and characteristics of an image.&#160;This makes it so that no matter what edits you do to the image, like scaling, skewing, or rotating it, the original image is always preserved and can be restored.</p><p>Some of the benefits of using smart objects are:</p><p>You can perform non-destructive edits and transforms, which means you can scale, rotate, skew, distort or warp a layer without losing the original quality of the image because it doesn’t affect the original data.</p><p>You can add filters to an image and restore it any time you want.</p><p>You can edit one smart object and automatically update all the linked instances, so this is very useful when you’re working with reusable presets or templates and you want to replace an element across multiple documents.</p><p>License:&#160;No known copyright restrictions</p><p>Smart Filters</p><p>Any filter that is applied to a Smart Object is called a Smart Filter.&#160;When you apply any of Photoshop’s filters to a smart object, it automatically becomes an editable, non-destructive smart filter.</p><p>One of the main advantages of using smart filters is that you can change its settings at any time without worrying about the loss in quality or even making permanent changes to the image.&#160;You also have the option to turn smart filters on and off, change the order in which they are applied, and add blend modes to them.&#160;Because they are non-destructive, you have the flexibility to experiment and try out different things in a safe space without worrying about making irreversible changes.</p><p>All you need to do is convert a layer to a smart object, and then use the Photoshop Filter menu to apply a filter.&#160;It will show up in the Layers panel as a Smart Filter.</p><p>Here is a video that uses simple examples to explain how Smart Objects and Smart Filters work.</p><p>Video Title:&#160;Photoshop Smart Objects Explained Using 7 Hot Tips</p><p>Video Publisher:&#160;photoshopCAFE(opens in a new tab)</p><p>License:&#160;No known copyright restrictions</p><p>Adjustment Layer</p><p>You learned about adjustment layers in earlier modules.&#160;Adjustment layers are basically used to apply color and tone adjustments to layers without actually changing or modifying the pixels of the layer.&#160;You can easily add adjustment layers on top of your image layers, and then apply any filters, color modes, or other color and tone settings to that layer.&#160;This is a fantastic way of touching up photos without permanently altering them.</p><p>To perform adjustments that are non-permanent and non-destructive, simply add a New Adjustment Layer from the Layers panel in Photoshop.&#160;Now, you can make any adjustments to this layer without worrying about permanently altering your image.</p><p>Because all the adjustments are made on a separate layer, you can always go back to that layer and make changes and modifications, or even delete the layer to go back to your original image.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5f2c8c5c825251290758d4cc753aa08e','adobe-photoshop-m7-l5-lesson-4','24b1d8a12143148190121e0f3ccc1573','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>What is Destructive Editing</h3><p>What is Destructive Editing?</p><p>Destructive editing sounds like your image is being destroyed, but all it means is that you are permanently editing your image.&#160;In destructive editing, all the changes made to the pixels of your image are permanent, and the original content data is not saved in Photoshop.&#160;This has been the primary method of editing photos for decades.&#160;Photoshop does give you certain tools that you can use to edit images non-destructively, but a majority of Photoshop tools are still considered to be destructive editing tools.</p><p>License:&#160;No known copyright restrictions</p><p>Painting</p><p>All of the paint tools in Photoshop are considered to be destructive tools, that is, any changes you make to the pixels of your document using these tools are permanent.&#160;This includes the&#160;Paint Bucket&#160;tool,&#160;Brush&#160;tool,&#160;Stamp&#160;tools, etc. It is always best to save a copy of your original image before you make any changes to it so that at any time, you can revert to the original image if needed.</p><p>License:&#160;No known copyright restrictions</p><p>Adjustments</p><p>You just learned about adjustments in Photoshop.&#160;But aren’t they non-destructive?&#160;There is a way that you can apply adjustments to your images destructively as well.&#160;Just select your image, click the&#160;Image&#160;menu, select&#160;Adjustments, and you will see the full list of adjustments available in Photoshop.&#160;If you select an adjustment from this menu, it is applied directly onto your image layer.&#160;Because of this, it permanently alters your image and is considered a destructive edit.</p><p>License:&#160;No known copyright restrictions</p><p>Erasing</p><p>You learned about this earlier in this module.&#160;When you erase a portion of an image, you are essentially deleting those pixels and they are no longer available in Photoshop.&#160;That is not always a bad thing, and in certain cases, erasing is a better option as well.&#160;Always be careful when you erase parts of an image because it could mean a lot of rework and you will have to start from scratch.&#160;&#160;An alternative to erasing an image is using masks.</p><p>License:&#160;No known copyright restrictions</p><p>Rasterizing</p><p>Graphic elements in Photoshop can either be vectors or rasterized (bitmap) images.&#160;By default, shapes and text are created as vector graphics.&#160;Vector graphics are made up of lines and shapes that are defined by vectors.&#160;You can freely move, resize, or modify vectors without losing clarity or definition.</p><p>When you rasterize an image, Photoshop converts the vector graphic into pixels, and your image will then have fixed dimensions.&#160;This means that they will have a grid of pixels that represent the image.&#160;Depending on the resolution of the image, you can only zoom in so far before the image starts to distort until you finally see a grid of squares or pixels.</p><p>Certain tools like paint, eraser, fill (basically most destructive tools) will only work on rasterized layers.&#160;So when you use these tools and convert an image to a rasterized image, it loses its ability to be freely resized, scaled, and be edited.&#160;Essentially, it becomes a destructive layer.</p><p>At some point, you will always need to rasterize your image in order to be able to use the tools you need.&#160;So always save a copy of the vector image as a layer in your document, so that you can always go back to it if needed.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('be456c56f06e951bbbfb1e8a0187e41b','adobe-photoshop-m7-l6-module-7-summary','24b1d8a12143148190121e0f3ccc1573','Module 7 Summary','text',12,'<h2>Module 7 Summary</h2><section><h3>Module 7 Summary</h3><p>Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Organizing Documents Part II!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Adjusted a layer&#39;s opacity, blending mode, and fill opacity</p><p>Created, applied, and manipulated masks</p><p>Understood non-destructive editing:&#160;Smart Objects, Smart Filters, and adjustment layer</p><p>Understood destructive editing:&#160;painting, adjustments, erasing, and rasterizing</p><p>Organized a document based on various specifications</p><p>Additional Resources</p><p>The following articles and websites are additional resources to learn more about this topic.&#160;(Not required reading).</p><p>Lesson 1:</p><p>Blending Modes(opens in a new tab)</p><p>Lesson 2:</p><p>How To Fill A Shape With A Photo In Photoshop(opens in a new tab)</p><p>How To Place An Image In Text(opens in a new tab)</p><p>Lesson 4:</p><p>Image essentials</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e180f6ca990dc4fca09feee612ee4889','adobe-photoshop-m7-l7-module-7-projects','24b1d8a12143148190121e0f3ccc1573','Module 7 Projects','text',12,'<h2>Module 7 Projects</h2><section><h3>Module 7 Project</h3><p>2400</p><p>Adobe Photoshop</p><p>Organizing Documents Part II - Project</p><p>Project</p><p>In this assignment, you will apply all that you have learned about modifying layer visibility, and destructive and non-destructive editing tools.&#160; You will need to use Photoshop to perform these tasks. Make sure you save your Photoshop documents as .psd files once you are done. In some steps, you may be required to take screenshots after completing each step and save them as image files or add them to a Word/PPT document.</p><p>Open an image in Photoshop and duplicate the layer. Demonstrate the differences between adjusting the layer&#39;s opacity and adjusting the fill opacity by adding objects and effects to the layers. Make sure you save the Photoshop file once you are done.&#160;(Take a screenshot of both layers once the task is complete.)</p><p>Open an image of a person or object in Photoshop. Create a clipping mask in a rectangular shape so that it isolates the person or object on your image. Make sure you save the Photoshop file once you are done.&#160;(Take a screenshot once the task is complete.)</p><p>In a PPT or Word document, create a comparison table of destructive and non-destructive edits. List the main differences between the two types of editing. List the common tools that fall under each category, and explain why those tools are destructive or non-destructive.</p><p>Review the rubric below to see how you will be graded.</p><p>Organizing Documents Part II Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Opacity and blending mode</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Masks</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately with attention to detail and meeting all requirements.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well and the mask was not created as instructed.</p><p>5</p><p>Non-destructive editing tools</p><p>5 points Demonstrated a strong understanding of the objective. The differences and tools were explained correctly.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. Almost all the instructions were followed correctly, with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. Little to none of the instructions were followed correctly.</p><p>5</p><p>Destructive editing tools</p><p>5 points Demonstrated a strong understanding of the objective. The differences and tools were explained correctly.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('665ad0c9223c5f4dfab616ec16690916','adobe-photoshop-m7-l8-module-7-quiz','24b1d8a12143148190121e0f3ccc1573','Module 7 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Oraganizing Docs Part 2. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,7,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('0727574e448e158fa7e4e0952049a993','adobe-photoshop-module-8','ee9c9635d1344f63172dfbcc5883d9ea','Module 8: Visual Elements Part 1',8) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('59ca6d23f5e93dc55b1b7165e594a0e5','adobe-photoshop-m8-l1-introduction-purpose-and-objectives','0727574e448e158fa7e4e0952049a993','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi guys! Welcome back to another module. This is the intro video on Creating and Modifying Visual Elements Part I. You’ve covered a lot of ground in your Photoshop journey so far. You’ve learned some essential basics about the design industry, you’ve learned to navigate around the Photoshop interface and set up a project, and you’ve also learned how to organize your documents using layers.</p><p>This module will give you an insight into the power of the paintbrush as you explore some of the core painting and drawing tools in Photoshop. If you can dream it, you can draw it! Photoshop has tools for everything from painting symmetrical patterns, creating polished digital artwork, or even getting that real-life feel of drawing and painting using pencils, pens, markers, and brushes. Adobe also offers you a whole suite of custom brush presets to choose from. Whether you want to illustrate manga comics, or produce calligraphy, whether you want to create realistic charcoal drawings or explore the painting styles of French Impressionists, Photoshop has you covered with custom brushes for all these styles!</p><p>Not an artist or painter? No problem! Photoshop’s drawing and painting tools aren’t just for creating artwork. You can also use them to enhance your photos, add texture, or fix flaws with precision and accuracy.</p><p>Typography is another key aspect of your designs. Use the comprehensive type tools in Photoshop to add text to your images and documents. Adobe gives you free access to 1000’s of beautiful fonts to choose from, and Photoshop allows you to create fun and exciting text effects, apply different text treatments, add text in different shapes and paths, and so much more. So let’s get started!</p><p>Module Description</p><p>Photoshop is a haven for the creative mind, and there is a multitude of drawing, painting and text tools to explore.&#160;In this module, students will learn how to create designs and images using a variety of tools.&#160;They will also learn how to add and manipulate text using various typographic settings in Photoshop.</p><p>Objectives</p><p>In this course, students will:</p><p>Create images using a variety of tools</p><p>Modify and edit vector images using a variety of vector tools</p><p>Use type tools to add typography to a design</p><p>Adjust character settings in a design</p><p>Adjust paragraph settings in a design, and convert text to graphics</p><p>Polling Question</p><p>Which of these experiences do you think would be missing if you use Photoshop to draw or paint?</p><p>Being able to hold a pencil or brush at an angle to get an angled stroke</p><p>Getting realistic-looking pen, pencil or brush strokes</p><p>Being able to adjust the intensity of the stroke with pressing harder or lighter</p><p>Being able to shade or contour</p><p>Multiple or none of the above</p><p>Results:</p><p>Multiple or none of the above&#160;50%</p><p>Being able to shade or contour&#160;50%</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c374aac0c25c67f2c81cc56f89f726cb','adobe-photoshop-m8-l2-lesson-1','0727574e448e158fa7e4e0952049a993','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Drawing in Photoshop</h3><p>Drawing in Photoshop</p><p>You can draw in Photoshop using the&#160;Pen&#160;tool, the&#160;Freeform Pen&#160;tool, the&#160;Curvature Pen&#160;tool, or any of the&#160;Shape&#160;tools.&#160;You’ve briefly learned about these tools earlier in the course when you were introduced to the Photoshop Toolbar.&#160;Let’s quickly recap to see which tools you can use to draw and what they do.</p><p>Click each hotspot on the image to learn more about each tool.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>The hotspot points on the image are as follows:</p><p>Pen Tool</p><p>The Pen tool allows you to draw precise paths, vector shapes or selections.</p><p>Freeform Pen Tool</p><p>The Freeform pen tool lets you draw freehand paths or shapes.</p><p>Curvature Pen Tool</p><p>This is a simplified version of the standard Pen tool and it allows you to draw complex paths and shapes.</p><p>Point Tools</p><p>These tools allow you to adjust the points in any shape that you draw using the Pen and Freeform Pen tools.</p><p>When you draw in Photoshop, you are essentially creating vector shapes and paths.&#160;When you choose any of the above tools, your first step will be to choose a drawing mode from the Options bar.&#160;This determines if you are creating a vector shape on its own layer, a work path on an existing layer, or a rasterized shape on an existing layer.&#160;Let’s learn more about what these are.</p><p>Vector Shapes:&#160;You can draw vector shapes that are resolution-independent using the shape or pen tools in Photoshop.&#160;It is always preferable to draw vectors because they maintain their size and clarity when they are resized, printed, or saved as a PDF.&#160;Vectors can also be edited at any time.</p><p>Paths:&#160;A path is an outline that you can fill or stroke with color, or you could turn them into selections.&#160;You can easily change the shape of a path by editing its anchor points.</p><p>Work Path:&#160;A work path is a temporary path that appears in the Paths panel and defines the outline of a shape.</p></section><section><h3>Drawing using the Pen Tool</h3><p>Drawing using the Pen Tool</p><p>The&#160;Pen tool&#160;is generally one of the more feared tools in Photoshop because it can be a little frustrating to use if you don’t understand fully how it works.&#160;Nevertheless, it is a very useful tool once you get the hang of it.&#160;Generally, the Pen tool is used more like a selection tool than a tool for drawing and is often called the&#160;Paths tool&#160;because it is essentially all about drawing paths.</p><p>In this tutorial, we’ll briefly cover how you can easily draw straight lines to create a shape or selection using the Pen tool.</p><p>Draw using Standard Pen Tool</p><p>The simplest path that you can draw using the Pen tool is a straight line.&#160;Just select the&#160;Pen&#160;tool from the Toolbar.&#160;Then, click at a starting point to begin drawing the line.&#160;This is your first&#160;anchor point.&#160;If you drag away, you’ll see a straight line has formed.&#160;Click again at the second anchor point to define where you want that line segment to end.&#160;You can press and hold the&#160;Shift&#160;key to constrain the line to multiples of 45&#176; angles.</p><p>Keep clicking in the desired directions you want.&#160;To complete the path, you can close it out as a loop by clicking over the first anchor point.&#160;If you want to leave it as an open path, just&#160;Ctrl-click&#160;(Windows) or&#160;Command-click&#160;(Mac) anywhere away from the lines you just drew.</p><p>Note:&#160;To learn more about drawing curves and other shapes using the standard Pen tool, check out the&#160;Additional Resources&#160;page at the end of this module.</p><p>Draw using the Curvature Tool</p><p>The&#160;Curvature&#160;tool is nested within the Pen tool icon in the Photoshop Toolbar.&#160;It is a simplified and much more user-friendly version of the standard Pen tool.&#160;It allows you to draw complex shapes and paths without needing to understand the more complex aspects of the Pen tool like adjusting the control handles or choosing the right path direction and angles.&#160;The Curvature tool draws curved lines by default, but you can also easily use it to draw straight lines.</p><p>The best way for you to understand how to use the Curvature tool is to see it in action.</p><p>Let’s start by creating a new document and adding a guide layout so you can get a clear idea of how to use the Curvature Pen tool. I’ve created a new document of 3 x 3 inches or 900 x 900 pixels here, and I have added a custom guide layout of 6 rows and 6 columns.</p><p>Next, let’s select the Curvature Pen tool. To begin drawing, let’s click at a starting point in the document. This square you see here is called the&#160;anchor point. To draw a straight line, just move your cursor and click at another spot. You will see that this draws a straight line. To draw a curve, you will always need three points; one at each end of the curve, and one to map the arc or angle of the curve. So because we only have two points so far, this appears as a line.</p><p>Now if you look at the Options bar, you will see a&#160;Settings&#160;icon here. You can use these settings to change the color of the path so that it is more visible. This doesn’t determine the color of the shape itself, it is only for you to be able to see the path clearly. So, let’s change this color and let&#39;s also increase the thickness of the line.</p><p>Going back to the shape, let’s click at the next point, and you’ll see that it immediately changes to a curve. Let’s follow through and add another anchor point, and the curve is extended further. Now, let’s complete this and close off this shape by clicking on the starting point. So this is how you can draw a simple circle using the Curvature Pen tool.</p><p>You can always change the shape by clicking and dragging an anchor point to new locations. You can also add new anchor points by clicking on the path and dragging them to additional places to change the curve of the shape.</p><p>If you look closely, all of the anchor points in this shape are curved. They’re called&#160;curve points. You can easily change this to a&#160;corner point&#160;by double-clicking a curve point. If you’ve added an extra point and you want to delete it, just select the point and press the&#160;Backspac<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f77dd3aefb6a7be7bb48898afb41849a','adobe-photoshop-m8-l3-lesson-2','0727574e448e158fa7e4e0952049a993','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Shape Tools</h3><p>Shape Tools</p><p>Photoshop has six key Shape tools that you can choose from; the&#160;Rectangle&#160;Tool, the&#160;Rounded Rectangle&#160;Tool, the&#160;Ellipse&#160;Tool, the&#160;Polygon&#160;Tool, the&#160;Line&#160;Tool, and the&#160;Custom Shape&#160;Tool.</p><p>Let’s quickly recap what each of these tools can be used for.</p><p>Click each hotspot on the image to learn more about each tool.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Click Hotspot activity to explore the Shape tools</p><p>The hotspot points on the image are as follows:</p><p>Rectangle Tool</p><p>Use this to draw rectangular vector shapes, paths or pixel shapes. Press and hold the Shift key to force it into a perfect square shape.</p><p>Rounded Rectangle Tool</p><p>Use this to draw a rectangle with rounded corners. Use the Shift key to force the shape into a rounded square.</p><p>Ellipse Tool</p><p>Use this to draw elliptical vector shapes, paths or pixel shapes. Press and hold the Shift key to draw a perfect circle.</p><p>Polygon Tool</p><p>Use this to draw polygonal, straight-edged vector shapes, paths or pixel shapes. Specify the number of sides of the shape in the Options bar.</p><p>Line Tool</p><p>Use this to draw straight lines, either as shapes or paths. Specify the line weight in the Options bar.</p><p>Custom Shape Tool</p><p>Use this tool to select and draw custom shapes. Either choose from one of Photoshop’s preset shapes or you can create your own.</p><p>Drawing Modes</p><p>Before you start drawing any shapes, you first need to select the drawing mode.&#160;Photoshop gives you three drawing modes to choose from, Shape, Path or Pixel.&#160;You can select these from the drop-down list in the Options bar when you select the Shape tool.</p><p>Each of these options allows you to draw very different types of shapes, that is, vector shapes, paths or pixels.</p><p>Shape:&#160;Selecting this option creates a vector shape on a separate layer.&#160;This is the most preferable option because vector shapes are editable, flexible and scalable.</p><p>Paths:&#160;Selecting this option draws a work path on the current layer that you have open.&#160;You can then use this path to make a selection, create a vector mask, or fill and stroke with color to create raster graphics.</p><p>Pixel:&#160;You should only choose this option when you want to create raster images.&#160;Choosing this option paints directly on a layer using pixels.</p></section><section><h3>Creating and Editing Vector Shapes</h3><p>Creating and Editing Vector Shapes</p><p>Creating shapes in Photoshop is very simple.&#160;You can easily customize the specifications for your shape using the&#160;Options&#160;bar.</p><p>Each shape tool has its own custom settings that you can specify based on the type of shape.&#160;Here are some of the common settings you can specify.</p><p>Fill:&#160;Choose what color to fill the shape with.&#160;You can also choose a pattern or gradient.</p><p>Stroke:&#160;Select a stroke color, gradient or pattern.&#160;You can also select the thickness and style of the stroke.</p><p>Dimensions:&#160;Specify the height and width of the shape.&#160;You can either specify this before you draw the shape or draw the shape and fine-tune this later.&#160;To maintain the aspect ratio of the shape, press and hold the Shift key as you draw the shape.</p><p>Path Operations:&#160;In Photoshop, you can choose to add multiple shapes and have them interact in different ways, like combining shapes, subtracting a shape, etc. You can choose from a variety of options.</p><p>There are other more specific options as well such as selecting a preset shape when you use the Custom Shape tool, or the number of sides when you use the Polygon tool.</p><p>To create a shape, just select one of the&#160;Shape&#160;tools.&#160;Choose a color and stroke for the shape.&#160;Then, specify any other settings like the dimensions, number of sides, etc. Click and drag on your document to draw the shape.&#160;To constrain the shape to a circle, square or a 45-degree angle, press and hold down the Shift key while you drag.</p><p>Once you have created a shape, it appears as a layer in the Layers panel.</p><p>This is a vector shape and you can resize it or edit it at any time.&#160;You can use the&#160;Path Selection Tool&#160;to select the shape.&#160;You can then edit the fill color, stroke, or dimensions from the&#160;Properties panel.</p><p>If you want to move and reposition the shape, switch to the&#160;Move&#160;tool.&#160;You can also drag the shape using the Path Selection tool.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c0dcb508e455eb2eb1728fbaf6effa3d','adobe-photoshop-m8-l4-lesson-3','0727574e448e158fa7e4e0952049a993','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Typography</h3><p>Typography</p><p>License:&#160;All Rights Reserved</p><p>Photoshop is usually only seen as a photo editing and design tool, but it actually offers very comprehensive options and controls to add, edit, and customize text.&#160;Type in Photoshop, much like shapes, consist of vector-based type outlines.&#160;This means that you can scale, resize or apply effects to type without losing out on crisp, sharp edges.&#160;You can use the Type tool to add horizontal or vertical type by selecting either the&#160;Horizontal Type tool&#160;or the nested&#160;Vertical Type tool.&#160;Once you select the Type tool, you can use the Options bar to specify the type settings like the font, font size, alignment, color, etc. You can also use the&#160;Character&#160;and&#160;Paragraph&#160;panels to modify various other aspects of your text.</p><p>Adding Type</p><p>There are three ways in which you can create type in Photoshop.&#160;All three methods start with first selecting the Type tool from the Photoshop Toolbar.</p><p>Point Type:&#160;This is when you click in an image or document and enter text.&#160;This is an easy way to add a few words to your document or image.</p><p>Paragraph Type:&#160;This is when you click and drag to create a section and then enter text.&#160;This option uses the boundaries of the shape you create to limit the characters that you type.&#160;This is a useful option when you need to enter a paragraph or line in a specific area of the document.</p><p>Type on a Path:&#160;This is a fun option where you can create a path using the Pen or Shape tools in Photoshop and then enter type to follow the edge of the open or closed path.&#160;If you enter more text than can fit on the path, you will see a small plus symbol appearing on the path.&#160;Text will always flow in the direction in which the path was added.</p><p>Now, let’s see a quick example of how you can easily add type to a document.</p><p>Adding type to your images and documents in Photoshop is very easy. Let’s select the&#160;Type tool. You can see that you have the option of either selecting the&#160;Horizontal Type tool&#160;or the&#160;Vertical Type tool, depending on how you want your text to be aligned. Let’s select the default Horizontal Type tool.</p><p>If you look up here at the Options bar, you can see that you can set your font type, size, style, and other settings here. You can also choose to go in and change these settings later after you have added the text. So, for now, let’s just click in the document area to create point type. You’ll see that as soon as you click in the document, you will see a live preview of placeholder text. This basically gives you a preview of how the font and font size will look. You can just choose a new font right now, or you can enter some text, and then make the changes as needed.</p><p>Let&#39;s first select this text and open the fonts drop-down list. You’ll see that as I roll over the fonts in the drop-down, you can see a preview of how it looks in the document. Let&#39;s select this font and I&#39;ll increase the font size. Once you are done with these changes, just click this checkmark here to accept the changes.</p><p>Let’s say I want to add a paragraph of content. Let’s click and drag to define a selection box. Now, you can enter the text you want in the selection box. You can also resize this box however you need to, and you can change the alignment options using the options in the Options bar. Once you are done, click the&#160;Commit&#160;option in the&#160;Options&#160;bar.</p><p>To add type along a path, you first need to create a path. You can do this by creating a shape or by drawing a path using the Pen tool. Let’s create a simple circle shape. Select the Ellipse tool and make sure that the mode Path is selected here. Now, click and hold down the Shift key and drag your cursor to draw a perfect circle.</p><p>Next, let’s select the type tool. This time, I&#39;ll select the font beforehand, and let&#39;s change the color as well. Now, click on the path, and you&#39;ll see the live preview placeholder text appearing on the path.&#160;Enter the text you want. You can use the Path Selection tool here to adjust the angle and position of the text on the path. Once you&#39;ve adjusted the angle of the text, you can always switch back to the Text tool, select the text, and make changes again. Once you&#39;re happy with your text, don&#39;t forget to click the Commit icon to save your changes. This is how you can easily add text to your documents in Photoshop.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c18adb2476fea50c79e0aa563173b76f','adobe-photoshop-m8-l5-lesson-4','0727574e448e158fa7e4e0952049a993','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Adjust Character Settings</h3><p>Adjust Character Settings</p><p>Apart from the options that you see in the Options bar when you select the Text tool, Photoshop also gives you more advanced settings to control using the&#160;Character panel&#160;and the&#160;Character Style panel.&#160;Let’s take a look at the customizations you can make using each of these panels.</p><p>Character Panel</p><p>You can access the&#160;Character&#160;panel from the&#160;Window&#160;menu in Photoshop.&#160;The Character panel is usually added to the secondary panel column.&#160;You can see that there are many settings here that are also found in the Options bar like the font type, size, and style.</p><p>You can change these common settings from either the Options bar or the Character panel, whichever is more convenient for you.</p><p>One more common setting you will see here is the&#160;Anti-Aliasing option.&#160;This is used to ensure that the characters always appear sharp and clear and the edges always look smooth.&#160;Without Anti-Aliasing, characters would look jagged when you zoom into them.&#160;This option is usually left at the default&#160;‘Sharp’&#160;option, but you can try out the other options and pick the one that works best for you.</p><p>Now, let’s take a look at some of the more advanced settings in the Character panel, starting with&#160;Leading.</p><p>This option controls the spacing between the lines of type.&#160;The default selection here is&#160;Auto.&#160;This is usually fine, but depending on the font you are using, you may need to adjust this value.&#160;When you adjust this value, think about if your text looks natural and easily readable, and always consider the size of your document.&#160;For example, is it going to be printed as a large poster or banner, or a smaller card or postcard?&#160;Visualize what the final product will look like when you adjust these values.</p><p>Below the Leading option, you will see an option to adjust the&#160;Tracking.&#160;This setting controls the spacing between the characters.&#160;You can either select from one of the preset values available in the drop-down list or you can enter your own custom value directly into the field.</p><p>There are many ways you can modify the tracking value to create a bigger visual impact.&#160;For example, you can select a specific word and adjust the tracking value for just that word.</p><p>Next, let’s move on to&#160;Kerning.&#160;Kerning also adjusts the spacing between characters, but do not confuse it with tracking, as they are quite different.&#160;Tracking controls the spacing between a range of characters, but kerning only controls the&#160;spacing between two characters.&#160;To set a kerning value, you need to click between the two characters where you want to adjust the spacing, or else the option will be greyed out.</p><p>Next, you can scale the type either vertically or horizontally using the&#160;Vertical and Horizontal Scale&#160;options.</p><p>You can select specific characters that you want to scale or you can scale the entire text as well.&#160;This is usually not recommended as it distorts the font and can look odd.</p><p>Next comes the&#160;Baseline Shift&#160;option.&#160;This option allows you to stylize the text by selecting and moving characters above or below the baseline of the font, like the example here.</p><p>Below this, you can see another set of type options that you can choose, like Faux Bold and Italics, Underline, Strikethrough, etc. And finally, you can also choose a different language from this panel as well.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b8cb7b78e17d48e9615c47ea22616650','adobe-photoshop-m8-l6-lesson-5','0727574e448e158fa7e4e0952049a993','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Adjust Paragraph Settings</h3><p>Adjust Paragraph Settings</p><p>Just as you can adjust advanced character settings, you can also use the&#160;Paragraph panel&#160;and the&#160;Paragraph Styles panel&#160;to access advanced paragraph settings.&#160;Let’s see how you can use these panels.</p><p>Paragraph Panel</p><p>You can access the&#160;Paragraph&#160;panel from the&#160;Window&#160;menu in Photoshop.&#160;The Paragraph panel is usually added to the secondary panel column.&#160;You can see that there are many settings here that are also found in the Options bar like the alignment options.</p><p>You can change these common settings from either the Options bar or the Paragraph panel, whichever is more convenient for you.</p><p>Let’s start off with the first set of icons you see in the Paragraph panel, and that is the&#160;alignment and justification options.&#160;These work like the options you would see in Word or other similar tools.&#160;You can select how you want your text to be aligned, and you can select how you want the spacing between the words of a paragraph.</p><p>Next, you will see the&#160;Indent options.&#160;These options allow you to add space on the left or right side of the entire paragraph, or just before the first line of the paragraph.</p><p>And next is another commonly used setting, that is adding a space before or after a paragraph.&#160;To use either of these tools, just select the paragraphs where you want to add the spacing and click the icon.</p><p>The final option you see is a&#160;Hyphenate&#160;checkbox.&#160;This is used to break longer words into the next line, especially when you use the justification controls.&#160;This just improves the visual Look-and-feel of the paragraph.</p></section><section><h3>Character and Paragraph Styles</h3><p>Character and Paragraph Styles</p><p>Apart from the standard Character and Paragraph panels, you also have the option to set styles for characters and paragraphs as you would do in Word or PowerPoint.&#160;A paragraph style includes both character and paragraph formatting settings.&#160;You can create different styles and save them in Photoshop to use whenever you need.&#160;You can also add and format text in your document, select the text and then save it as a style in Photoshop to use later.</p><p>Here is a video showing how you can use character and paragraph styles in your document.</p><p>Video Title:&#160;Paragraph &amp; Character Styles in Photoshop</p><p>Video Publisher:&#160;Adobe Photoshop</p></section><section><h3>Convert Text to Graphics</h3><p>Convert Text to Graphics</p><p>Photoshop gives you the option to convert text to graphics.&#160;You have two options, you can convert text to vector shapes, or you can rasterize it to create an image.&#160;But which option should you choose, and why?</p><p>There are some key differences between vector shapes and raster images, and you have seen examples of this earlier in the course.&#160;Converting your text into vector shapes gives you the option to still rotate, scale, and skew the shape without losing out on quality, resolution, or clarity.&#160;If you need to adjust the color of the text after converting it to a shape, you can easily just select the Shape layer and change the&#160;Fill&#160;color from the&#160;Options&#160;bar.</p><p>To convert your text into a vector shape, select the text layer, right-click the layer and select&#160;Convert to Shape.&#160;Your text will be converted to a shape.</p><p>So in what situations would you rasterize text?&#160;There are some tools in Photoshop like the Brush tool, Eraser and Paint Bucket tool, filters, etc. that only work on rasterized layers.&#160;So, if you want to apply any of these tools, effects or filters to your text, then rasterizing is the way to go.&#160;Just remember that if you scale your text after it is rasterized, there will be some loss of quality and your text will no longer be editable.</p><p>To convert your text into a raster image select the text layer, right-click the layer and select&#160;Rasterize Type.&#160;Your text will be rasterized and will no longer be editable.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9051ddbc357517eac66c138c3f6109e1','adobe-photoshop-m8-l7-module-8-summary','0727574e448e158fa7e4e0952049a993','Module 8 Summary','text',12,'<h2>Module 8 Summary</h2><section><h3>Module 8 Summary</h3><p>Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Creating and Modifying Visual Elements Part I!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Created images using a variety of tools</p><p>Modified and edited vector images using a variety of vector tools</p><p>Used type tools to add typography to a design</p><p>Adjusted character settings in a design</p><p>Adjusted paragraph settings in designs and converted text to graphics</p><p>Additional Resources</p><p>The following articles&#160;and websites were referenced in this module.&#160;(Not required reading)</p><p>Lesson 1</p><p>Use the Standard Pen Tool(opens in a new tab)</p><p>Beginners Guide To The Pen Tool(opens in a new tab)</p><p>Draw straight lines and smooth curves with precision and ease(opens in a new tab)</p><p>Lesson 2</p><p>Working with shape tools(opens in a new tab)</p><p>Modify Shapes(opens in a new tab)</p><p>Lesson 3</p><p>Design with great-looking typography(opens in a new tab)</p><p>Lessons 4 &amp; 5</p><p>Format Characters(opens in a new tab)</p><p>Format Paragraphs</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('d9fd9e3cfb6c58f9d548441136e73223','adobe-photoshop-m8-l8-module-8-project','0727574e448e158fa7e4e0952049a993','Module 8 Project','text',12,'<h2>Module 8 Project</h2><section><h3>Module 8 Project</h3><p>2400</p><p>Adobe Photoshop</p><p>Creating and Modifying Visual Elements Part I - Project</p><p>Project</p><p>In this assignment, you will apply all that you have learned about the core design tools in Photoshop. You will need to use Photoshop to perform these tasks. Take screenshots after completing each step and save them as image files or add them to a Word/PPT document.</p><p>Open a Photoshop document and draw a simple shape of your choosing using the Pen tool. You can use a guide layout to help you. Once you are done, convert it to a Shape and fill it with a color.&#160;(Take a screenshot once the task is complete.)</p><p>Draw a shape using each of the Shape tools in Photoshop. Each shape should be on a different layer and have a different fill, stroke, and dimensions.&#160;(Take a screenshot once the task is complete.)</p><p>Open an image in Photoshop, and add some text to go with it. This can be any sample text on the image.&#160;Use at least 2 methods of adding text, Point type, paragraph type, or type on a path.&#160;(Take a screenshot once the task is complete.)</p><p>Using the same document you used for the above task, modify the character settings of the text you added. Increase the leading and tracking values, and add a baseline shift to one keyword.&#160;(Take a screenshot once the task is complete.)</p><p>Using the same document you used for the above two tasks, adjust the indent and justification values for a paragraph.&#160;(Take a screenshot once the task is complete.)</p><p>Review the rubric below to see how you will be graded.</p><p>Creating and Modifying Visual Elements Part I</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Create images using a variety of tools</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Create and edit vector images</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Use type tools</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Adjust character settings</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Adjust paragraph settings</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6e55f7f59fbcbb406c53cbdc13543955','adobe-photoshop-m8-l9-module-8-quiz','0727574e448e158fa7e4e0952049a993','Module 8 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Visual Elements Part 1. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('6693a582181b4a3464c8e565d289f03a','adobe-photoshop-module-9','ee9c9635d1344f63172dfbcc5883d9ea','Module 9: Visual Elements Part 2',9) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4fd1b176c7ffe191896db3e3eb440a13','adobe-photoshop-m9-l1-introduction-purpose-and-objectives','6693a582181b4a3464c8e565d289f03a','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Welcome back, everyone! This is the intro video on Creating and Modifying Visual Elements Part II. In the last module, you learned to use all of the fun paint and typography tools available in Photoshop. Let’s keep the creativity ball rolling in this module as well! In this module, you will learn about the importance of selections when you edit an image.</p><p>But what are selections? A selection is a way to isolate a part of an image so that you can make changes to specific areas instead of the entire image. Because Photoshop is such a comprehensive program, it gives you multiple different types of selection tools that you can use to make simple and advanced selections. Now, you may be thinking, why do I need so many different selection tools? In what situations would I use them?</p><p>Let’s say you have a picture of a field of flowers with a butterfly flying over them, and you want to make it look like there are multiple butterflies all over. Or if you have a group photograph where some people appear darker because they’re standing in the shadow, while others are brighter. Or even if you have a great picture of yourself that you want to share online but you want to replace the dull background with something else. You can use selections to easily do all of these tasks!</p><p>So let’s dive right in and see how you can use all of Photoshop’s fantastic selection tools.</p><p>Module Description</p><p>The selection tools in Photoshop give you the flexibility to choose which areas of an image you want to make changes to.&#160;This allows you to apply multiple effects and filters to specific areas for more in-depth editing and refinement.&#160;In this module, students will learn to make, modify, and refine selections using various selection tools.&#160;They will also learn how to rotate, flip and modify elements of their images.&#160;Finally, students will get a brief overview of how to apply some basic auto-correction methods and tools in Photoshop.</p><p>Objectives</p><p>In this module, students will:</p><p>Make selections using a variety of tools</p><p>Modify and refine selections using various methods and save and load selections</p><p>Modify the canvas or artboards</p><p>Rotate, flip, and modify individual layers, objects, selections, groups, or graphical elements</p><p>Apply basic auto-correction methods and tools</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e4618fbba3fe38a16b088950bcc6d143','adobe-photoshop-m9-l2-lesson-1','6693a582181b4a3464c8e565d289f03a','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Selection Tools in Photoshop</h3><p>Selection Tools in Photoshop</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>The introduction to this module already gave you an idea of why selections are required and are such an important part of using Photoshop.&#160;When you look at a photo you can easily identify different objects in the photo.&#160;But Photoshop doesn’t look at the photo in quite the same way.&#160;To Photoshop, all the different objects are just differently colored and shaded pixels and the software cannot ‘see’ objects, only pixels.</p><p>You can read more about this using the links shared in the&#160;Additional Resources&#160;section at the end of this module.</p><p>There are many different selection tools available in Photoshop, and each of them allows you to select things in an image in different ways.&#160;For geometric selections, you can use the&#160;Rectangular&#160;or&#160;Elliptical&#160;Marquee&#160;tools.&#160;For more freehand selections, you can use the different nested&#160;Lasso&#160;tools.&#160;If you need to make selections based on color or brightness, you can use the&#160;Magic Wand tool.&#160;For easier, quicker selections, just use the&#160;Quick Selection tool.&#160;You can even combine and use multiple selection tools if just one doesn’t do the trick.</p><p>Let’s go over some of the most commonly used selection tools in Photoshop.</p></section><section><h3>Marquee Selection Tools</h3><p>Marquee Selection Tools</p><p>The marquee selection tools help you make selections based on simple geometric shapes.&#160;The marquee tool is actually a collection of four nested tools, the&#160;Rectangular Marquee tool, the&#160;Elliptical Marquee tool, and the&#160;Single Row&#160;and&#160;Single Column Marquee tools.</p><p>The Rectangular Marquee tool is used to make rectangular or square selections.</p><p>The Elliptical Marquee tool is used to make elliptical or circular selections.</p><p>The last two tools are used to make a 1-pixel wide selection and are usually used in web-design.&#160;We won’t go into a detailed explanation of these two tools in this course.</p><p>To use the&#160;Rectangular Marquee tool, select it from the Toolbar and just click and drag on the image to select an area.&#160;You will see a marching ants outline around the selection area.</p><p>You can use the&#160;Elliptical Marquee tool&#160;in the same way.&#160;Just select the tool from the Toolbar and click and drag to draw an elliptical selection on your image.</p></section><section><h3>Lasso Tools</h3><p>Lasso Tools</p><p>The Marquee selection tools allow you to make simple geometric selections, but there will be other instances when you need to make more complex selections, for example selecting a flower, a person, or even an object like a shoe or a car.&#160;The&#160;Lasso tools&#160;in Photoshop allow you to make freeform selections around objects in a photo, much like how you would outline or trace them out using pen and paper.</p><p>The Lasso tools are also a set of nested tool that includes the basic&#160;Lasso tool, the&#160;Polygonal Lasso tool, and the&#160;Magnetic Lasso tool.</p><p>Lasso tool:&#160;This is the most basic lasso tool used to draw freehand selections.&#160;To make freehand selections, you can use the standard&#160;Lasso tool&#160;in Photoshop.&#160;All you need to do is to click and drag to draw a freehand selection around the image you want to select.&#160;This is very similar to if you were tracing out an outline over an image using pen and paper.&#160;To close the selection, just draw all the way back to the initial point.&#160;If you don’t reach the point where you started and just release the mouse button before, Photoshop will join the starting and ending selection points with a straight selection line like this.</p><p>Polygonal Lasso tool:&#160;This is used to draw straight-sided polygonal selections.&#160;While the Marquee tools also allow you to draw polygonal shapes, you can only use it for rectangles and squares.&#160;The Polygonal Lasso tool gives you the flexibility to draw polygons with multiple sides, and in any angle or direction.</p><p>To use the Polygonal Lasso tool, just click on the starting point.&#160;Click at the next point.&#160;A straight line will appear between them.&#160;Keep clicking on new points in the same way.&#160;To close the selection, click back on the first point.&#160;You can also double-click anywhere on the image and Photoshop will close the selection by drawing a straight line between the starting and last point.</p><p>Magnetic Lasso tool:&#160;This is the most useful of the Lasso tools because it allows you to draw selections where the border snaps to the edges of clearly defined areas in the image.&#160;You can use the Magnetic Lasso tool to make complex selections in high-contrast images.&#160;Higher contrast between the background and the image is always beneficial because this is an&#160;edge-detection tool&#160;that searches for the edge of the image as you drag around it and snaps to it.</p><p>Tip:&#160;You can change the cursor of the Magnetic Lasso tool to a more useful icon by clicking the&#160;Caps Lock&#160;key on your keyboard.&#160;The cursor changes to a circle with a small crosshair at the center which you can use to mark the outline of your selection.</p><p>To begin a selection using the Magnetic Lasso tool, just click on the edge of the area you want to select.&#160;Now, as you move your mouse along the edge, you will see a small line being dropped from the center of the cursor to the edge of the image, almost like a thread being dropped.&#160;Make sure you keep the edge within this circle of the cursor to ensure that you’re dropping the line on the correct areas.</p><p>To zoom in on the image as you are drawing the selection, press&#160;Ctrl&#160;and the&#160;+ sign&#160;on&#160;Windows&#160;or&#160;Command&#160;and the&#160;+ sign&#160;on&#160;Mac.&#160;To zoom out, you can press&#160;Ctrl&#160;and the&#160;- sign&#160;on&#160;Windows&#160;or&#160;Command&#160;and the&#160;- sign&#160;on&#160;Mac.</p><p>You can also refine your selection using the&#160;Options&#160;bar.&#160;To increase the width of the cursor circle, you can increase the&#160;Width&#160;value.&#160;If your image has poor contrast, you can reduce the&#160;Contrast&#160;value to make more accurate selections.</p><p>We’ll learn more about how you can refine and edit your selections in the next lesson<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e604247479227cd5764ce4ba5b772871','adobe-photoshop-m9-l3-lesson-2','6693a582181b4a3464c8e565d289f03a','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Keyboard Modifiers</h3><p>Keyboard Modifiers</p><p>When making selections, keyboard modifiers or shortcuts are your best friends!&#160;They allow you to customize how you make selections, add or subtract selections, move them, confine them to perfect squares or circles, and much more.&#160;With a little practice, you can easily master making complex selections using simple selection tools.</p><p>Here are some quick reference cards for some of the most common keyboard shortcuts you will use and what they do.&#160;You can use these shortcuts with all of the selection tools in Photoshop.</p><p>Flip each card to learn some useful keyboard shortcuts.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>&#171; Back</p><p>Ctrl + D or Command + D</p><p>Ctrl + D or Command + DCtrl + D or Command + D:&#160;Use this shortcut to deselect a selection.</p><p>Shift + drag over the area you want to add</p><p>Shift + drag over the area you want to addShift + drag over the area you want to add:&#160;You can add sections to a selection using this shortcut.</p><p>Alt + drag or Option + drag over the area you want to remove</p><p>Alt + drag or Option + drag over the area you want to removeAlt + drag or Option + drag over the area you want to remove:&#160;You can subtract sections from a selection using this shortcut.</p><p>Spacebar + drag</p><p>Spacebar + dragSpacebar + drag:&#160;You can use this shortcut to reposition a selection while you are selecting it.</p><p>Shift + drag</p><p>Shift + dragShift + drag:&#160;You can use this shortcut to constrain marquee selection tool to create a perfect square or perfect circle.</p><p>Alt + drag or Option + drag</p><p>Alt + drag or Option + dragAlt + drag or Option + drag:&#160;Use these shortcuts to draw a selection from the center out.</p><p>Shift + Alt + drag or Shift + Option + drag</p><p>Shift + Alt + drag or Shift + Option + dragShift + Alt + drag or Shift + Option + drag:&#160;You can combine the previous two commands to draw a selection from the center out, as well as constrain it to a square or circle.</p><p>⟳ Flip Card</p><p>Next &#187;</p><p>Flashcard&#160;1&#160;of&#160;7</p><p>Flashcard Transcript</p><p>Ctrl + D or Command + D:&#160;Ctrl + D or Command + D: Use this shortcut to deselect a selection.</p><p>Shift + drag over the area you want to add:&#160;Shift + drag over the area you want to add: You can add sections to a selection using this shortcut.</p><p>Alt + drag or Option + drag over the area you want to remove:&#160;Alt + drag or Option + drag over the area you want to remove: You can subtract sections from a selection using this shortcut.</p><p>Spacebar + drag:&#160;Spacebar + drag: You can use this shortcut to reposition a selection while you are selecting it.</p><p>Shift + drag:&#160;Shift + drag: You can use this shortcut to constrain marquee selection tool to create a perfect square or perfect circle.</p><p>Alt + drag or Option + drag:&#160;Alt + drag or Option + drag: Use these shortcuts to draw a selection from the center out.</p><p>Shift + Alt + drag or Shift + Option + drag:&#160;Shift + Alt + drag or Shift + Option + drag: You can combine the previous two commands to draw a selection from the center out, as well as constrain it to a square or circle.</p><p>There are many more shortcuts that you can explore.&#160;Take a look at the&#160;Additional Resources&#160;page at the end of the course for reference links.</p></section><section><h3>Common Settings in the Options Bar</h3><p>Common Settings in the Options Bar</p><p>When you select any of the selection tools in Photoshop, you will see some common icons and settings in the&#160;Options&#160;bar.&#160;The most common icons you will see are the different&#160;Selection Options.</p><p>These are very useful and as you practice using the Photoshop selection tools, you will find these to be very powerful because they allow you to customize how you work with selections.</p><p>Click each hotspot to learn more.</p><p>New Selection icon</p><p>This is usually selected by default when you choose the Marquee or Lasso selection tools. This is just the basic option used to create selections.</p><p>Add to Selection icon</p><p>If you have already made a selection, choosing this icon allows you to draw another selection that will be added to your first selection.</p><p>Subtract from Selection icon</p><p>This icon does the opposite of the previous one. Here, if you have already made a selection and want to refine it by cutting out parts you want to exclude, then select this icon and select the areas to subtract from the selection.</p><p>Intersect with Selection icon</p><p>This icon helps you select an area of intersection between two selections. You can use this option for more complex selections.</p><p>Feathering</p><p>This option allows you to feather or soften the edges of a selection. You can use this option to create a vignette or fade effects in your selections.</p></section><section><h3>Making Simple Modifications to Selections</h3><p>Making Simple Modifications to Selections</p><p>In this video, you will learn how to make simple modifications to selections, such as, moving, deselecting, and snapping selections to a fixed ratio.&#160;You will also learn to add to, subtract from, and combine selections.</p><p>Let’s take a look at how you can make some simple modifications to selections, like adding to, subtracting from, deselecting, and deleting selections.</p><p>Let’s look at a simple example using the&#160;Rectangular Marquee&#160;tool&#160;from the Toolbar. Let’s draw a selection by clicking and dragging over the image. While you’re dragging over the image, if you find that you didn’t start selecting from the right position, just press and hold down the&#160;Spacebar&#160;without releasing the mouse button. Now, if you move your mouse, you’ll see that the selection you’ve made also moves. Just adjust it to the right position, release the Spacebar, and continue making your selection. If you’ve already made a selection and need to adjust the position, just click within the selection and drag it to adjust it to the right position.</p><p>To deselect a selection, go up to the&#160;Select&#160;menu and choose&#160;Deselect. An easier way to do this is to just use the shortcut&#160;Ctrl + D&#160;on&#160;Windows&#160;or&#160;Command + D&#160;on&#160;Mac.</p><p>If you want to draw a square <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('13d564da9905d280c1ebc2fcc35d3642','adobe-photoshop-m9-l4-lesson-3','6693a582181b4a3464c8e565d289f03a','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Cropping and Straightening Images</h3><p>Cropping and Straightening Images</p><p>You’ve learned all about selections in the last two lessons.&#160;Now, let’s look at some of the ways in which you can transform digital graphics and media by modifying the canvas or artboards that you are working on.&#160;&#160;One of the most popular tools used to modify the canvas is the&#160;Crop tool.&#160;The crop tool isn’t just used to crop out parts of a photo.&#160;You can also use the Crop tool to resize images, straighten them, and even expand them.</p><p>Let’s take a look at how you can use the crop tool to improve the composition of images and straighten them. I have an image open here, and straight away I can spot a few issues with this image.</p><p>Let’s first select the Crop tool. You’ll see that the entire image is selected with this border. This region is called the crop box. You can drag any of these corners to adjust the shape and size of this image. You can also use the different crop options in the Options bar. Photoshop gives you a number of preset aspect ratios or crop sizes that you can choose from. So, if you want to crop this image to a particular size, like say 4 by 5 inches, just select it, and you will see that the crop box is adjusted to those dimensions. Let’s select&#160;Front Image&#160;so that we have the full image selected, and this also shows you the dimensions as well as the image resolution up here.</p><p>Now, the first thing you will notice is that the image is off axis. There are two ways in which you can straighten this image. If you roll your mouse the outer edge of the image, you will see the cursor changes to this curved transform arrow. This activates the transform tool and you can just drag and turn the image to straighten it. Another easier option is to use the Straighten feature from the Options bar. Just select this option. Then, just draw a straight line on the image to indicate where it should be straight. You don’t have to draw it all the way from one end to the other, you just need enough so Photoshop can detect how to level the image. And this automatically straightens out the image. Now, you can resize the crop box to adjust your image as needed.</p><p>If you want to change the height or width of this image, just click the Clear button and then adjust the edges again. Once you are done with the changes, you need to select the Commit icon to save the changes. But before you do this, make sure that this icon is de-selected. This ensures that the area outside the crop box is still saved even after you commit the changes. That way, if at a later point, you need to recover parts of the original image, you can simply select the Crop tool again, and as you can see, the cropped parts of the image are still intact.</p></section><section><h3>Expanding the Canvas</h3><p>Expanding the Canvas</p><p>There may be times when you need to expand your document canvas.&#160;You can do this for many reasons, like adding a border around your image or adding space on one or more sides of your image to add other elements like graphics or text.&#160;You can do this using the&#160;Canvas Size&#160;command in Photoshop.</p><p>If you click the&#160;Image&#160;menu in Photoshop, you will see two options,&#160;Image Size, and&#160;Canvas Size.&#160;The Image Size option is used to increase the size of your image, whereas the Canvas Size option doesn’t affect the size of the image at all.&#160;It only modifies the size of the canvas by letting you add space around the image.</p><p>Once you click the&#160;Canvas Size&#160;option, you will see this popup.</p><p>Here, you can see two sections, the&#160;Current Size,&#160;and the&#160;New Size&#160;sections.&#160;The Current Size section shows you the current dimensions of the image.&#160;In the section below, you can enter new values for either or both the width and height of the image.</p><p>The unit of measurement is in pixels, which works well for images being prepared for online use.&#160;If you are intending on using this image for printing purposes, then it is better to use inches as the unit of measurement, as it makes it easier to visualize the printed image with inch values.&#160;You may not always know the exact value that you want this to be expanded to, but you can always tell Photoshop by how much to increase the width or height of the image.&#160;To do this, select the&#160;Relative&#160;checkbox.&#160;This sets the number to&#160;0&#160;and you can increase it to the number of pixels you want to add.&#160;Let’s add&#160;500&#160;pixels to the width of the image.&#160;Let’s leave the height value as&#160;0.</p><p>Now, if you click&#160;OK, you will see that Photoshop has extended the canvas on both sides of the image.&#160;Remember, the 500 pixels that you added have been distributed on both sides of the canvas.</p><p>You also have the option to add canvas on only one side of the image by adjusting the anchor point in the&#160;Canvas Size&#160;popup.&#160;This tells Photoshop where to align the image with respect to the canvas extension.&#160;So, if you click on the middle right cell here, all of the pixels you add here will be added to the left of the image.</p><p>You can also choose a background color for the canvas that you are adding to the image by adjusting the values in the&#160;Canvas extension color&#160;drop-down menu.</p></section><section><h3>Resizing vs. Resampling</h3><p>Resizing vs.&#160;Resampling</p><p>Have you ever enlarged a photo, only to find that it looks pixelated and blurry?&#160;Having an understanding of image size and resolution is very important when you work with digital or printed images.&#160;We’ve covered what image size and resolution mean in earlier modules.</p><p>If you want to refresh your basic concepts, check out the articles shared in the&#160;Additional Resources&#160;section at the end of this module.</p><p>There are two ways in which you can change the size of an image in Photoshop, you can either&#160;resize&#160;it or&#160;resample&#160;it.&#160;But what is the difference between the two?&#160;The biggest differentiator between the two is the number of pixels in the image or the pixel dimension.</p><p>Resizing:</p><p>The total number of pixels in the image remains the same.</p><p>Document size (print size) is related to the resolution (pixels/inch) of the image.</p><p>When you resize an image, its resolution automatically changes because the number of pix<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('58d107fa9e89434c9c9fffc9742d258b','adobe-photoshop-m9-l5-lesson-4','6693a582181b4a3464c8e565d289f03a','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Transforming Images in Photoshop</h3><p>Transforming Images in Photoshop</p><p>The&#160;Transform&#160;command in Photoshop is once of the most useful tools you will use.&#160;You can apply transformations to scale, rotate, skew, stretch, distort, or warp images.&#160;You can apply these transformations to an entire image, a selection, a layer, or multiple layers.&#160;You can also apply transformations to paths, shapes, masks, and more.</p><p>You can find the Transform commands in the&#160;Edit&#160;menu in Photoshop.</p><p>You’ll notice here that there are two transform commands;&#160;Free Transform&#160;and&#160;Transform, which gives you a bunch of options in a pop-out menu.</p><p>Both tools have the same functions, the only difference is that the Free Transform tool is easier to use because you can apply all the transformations in one continuous operation.&#160;So, instead of choosing Rotate, Scale, Skew or other commands each time, you can just use the Options bar or your keyboard shortcuts to make changes.</p><p>Transform Commands</p><p>The first thing you need to do is to select what you want to transform.&#160;Select your image, layer, shape or path, use the&#160;Move&#160;tool or the&#160;Path Selection&#160;tool to select the item, open the&#160;Edit&#160;menu and click&#160;Free Transform.&#160;You will see a border appear around the item.&#160;If you right-click on your image, you will see all of the different commands you can apply.</p><p>Here are all of the different types of changes you can make to your selections or images using the&#160;Transform&#160;command:</p><p>Scale:&#160;You can enlarge or reduce the size of an item.&#160;You can scale horizontally, vertically, or both horizontally and vertically.</p><p>Rotate:&#160;You can turn an item around its center.&#160;You can also change the center reference point to another position on the item to rotate it around that point.</p><p>Skew:&#160;You can use this to slant an item vertically and horizontally.</p><p>Distort:&#160;This function allows you to stretch an item in all directions.</p><p>Perspective:&#160;You can use this to apply a one-point perspective to an item.</p><p>Warp:&#160;This feature manipulates the shape of an item.</p><p>Rotate 180, Rotate 90 Clockwise, Rotate 90 Counter Clockwise:&#160;These commands let you rotate the item by a specific angle.</p><p>Flip:&#160;This allows you to flip the item vertically or horizontally.</p><p>Once you have made all the transformation changes you need, click the&#160;Commit&#160;icon in the&#160;Options&#160;bar.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6ec3384bcd6f1e2d56f719640f328301','adobe-photoshop-m9-l6-lesson-5','6693a582181b4a3464c8e565d289f03a','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Auto-Correction Tools</h3><p>Auto-Correction Tools</p><p>Photoshop gives you some simple auto-correction options to correct minor issues with tone and color in an image.&#160;There are three tools that are very simple and therefore also the most widely used tools for quick corrections.&#160;These are the&#160;Auto Tone,&#160;Auto Contrast, and&#160;Auto Color&#160;commands.</p><p>The best part of these commands is that you don’t need to go into the more technical aspects of color tones, contrast adjustments or color channels.&#160;You can simply use them to boost your images and improve their inherent color, tone, and contrast.</p><p>You can access these three commands from the&#160;Image&#160;menu in Photoshop.</p><p>I have an image here that has poor contrast and tone, and the colors lean more towards the reds.&#160;Let’s see how we can improve this image.&#160;We’ll apply each of the auto-correction commands separately and see the effect they have on the final image.&#160;I’ll show you a side-by-side comparison so you can see the differences.</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Auto Tone</p><p>The&#160;Auto Tone&#160;command is very similar to the Auto Contrast command.&#160;It darkens the darkest pixels, lightens the lightest pixels, and then distributes the other tonal values of each color channel one by one.&#160;So Auto Tone basically boosts the overall contrast as well as the colors in the image.</p><p>To apply this command, just click the&#160;Image&#160;menu and select&#160;Auto Tone.&#160;Here are the before and after results.</p><p>Auto Contrast</p><p>This is the most straightforward of the three auto correction tools.&#160;The&#160;Auto Contrast&#160;command improves the overall contrast of the image by making the dark pixels darker and making the light pixels lighter.&#160;It boosts the overall contrasts and makes the colors stand out more.</p><p>To apply this command, just click the&#160;Image&#160;menu and select&#160;Auto Contrast.&#160;Here are the before and after results.</p><p>Auto Color</p><p>Finally, the&#160;Auto Color&#160;command does the same as the other two commands, but it also balances the color in the image by correcting unwanted color casts and making the mid-tones more neutral.&#160;In most cases, you can use just the Auto Color command and boost both the contrast and fix any tone and color issues</p><p>To apply this command, just click the&#160;Image&#160;menu and select&#160;Auto Color.&#160;Here are the before and after results.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('dd7553501112eac49180088724097198','adobe-photoshop-m9-l7-module-9-summary','6693a582181b4a3464c8e565d289f03a','Module 9 Summary','text',12,'<h2>Module 9 Summary</h2><section><h3>Module 9 Summary</h3><p>Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on&#160;Creating and Modifying Visual Elements Part II!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Make selections using a variety of tools</p><p>Modify and refine selections using various methods and save and load selections</p><p>Modify the canvas or artboards</p><p>Rotate, flip, and modify individual layers, objects, selections, groups, or graphical elements</p><p>Apply basic auto-correction methods and tools</p><p>Additional Resources</p><p>The following articles and websites were referenced in this module.&#160;(Not required reading)</p><p>Why Do We Need Selections In Photoshop?(opens in a new tab)</p><p>Keys for selecting and moving objects(opens in a new tab)</p><p>Image size and resolution(opens in a new tab)</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('df9f8187192e27926ba4192d17b23ab4','adobe-photoshop-m9-l8-module-9-project','6693a582181b4a3464c8e565d289f03a','Module 9 Project','text',12,'<h2>Module 9 Project</h2><section><h3>Module 9 Project</h3><p>2400</p><p>Adobe Photoshop</p><p>Creating and Modifying Visual Elements Part II - Project</p><p>Project</p><p>In this assignment, you will apply all that you have learned about in this module. You will need to use Photoshop to perform these tasks. Take screenshots after completing each step and save them as image files or add them to a Word/PPT document.</p><p>Open an image in Photoshop. Make a selection using two different selection tools to create a complex selection. You can choose any two selection tools for this task.&#160;(Take a screenshot once the task is complete, and make a note of which selection tools you used.)</p><p>Open an image with a plain colored background, for example, an image showing the plain sky or one with a solid-colored background. Inverse and mask the background of the image, and replace it with another background image.&#160;(Take a screenshot once the task is complete. Make sure you also save the image for review.)</p><p>Open an image in Photoshop. Expand the canvas of the image by 400 pixels vertically and horizontally. Then, prepare the image for printing by changing the resolution to 300 pixels/inch.&#160;(Save the image once you are done.)</p><p>Open an image in Photoshop and use the Transform command to warp the shape of the image.&#160;(Take a screenshot once the task is complete.)</p><p>Open an image in Photoshop and apply one of the auto-correction tools to enhance the image.&#160;(Take before and after screenshots once the task is complete.)</p><p>Review the rubric below to see how you will be graded.</p><p>Creating and Modifying Visual Elements Part II</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Make selections using a variety of tools</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Modify and refine selections</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Modify the canvas or artboards</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Transform elements</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Apply basic auto-correction methods and tools</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c7b7426e096323ae5f486d78d25eddf9','adobe-photoshop-m9-l9-module-9-quiz','6693a582181b4a3464c8e565d289f03a','Module 9 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Visual Elements Part 2. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('39e17da81dea254f423725abeb3100cf','adobe-photoshop-module-10','ee9c9635d1344f63172dfbcc5883d9ea','Module 10: Visual Elements Part 3',10) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('693e8fe97f91dbeb6fa01e715b26149d','adobe-photoshop-m10-l1-introduction-purpose-and-objectives','39e17da81dea254f423725abeb3100cf','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hello and welcome back! This is the intro video on Creating and Modifying Visual Elements Part III. It’s hard to believe we’re almost at the end of our Photoshop journey! If you’ve been following along and practicing with each of the modules we’ve covered so far, you should have a good understanding of how to use Photoshop and most of its tools. But we’ve saved the best for the last! In this module, we’ll dive into the fantastic reconstructing and retouching techniques that Photoshop is famous for. You’ll learn about everything from removing red-eye in photos to modifying the appearance of photos using filters and styles.</p><p>So let’s dive right in and explore all the different ways in which you can manipulate digital graphics and media using the full suite of Photoshop’s repair and reconstruction tools.</p><p>Module Description</p><p>Photoshop is, first and foremost, a photo editing tool.&#160;In this module, students will learn how to use various tools, settings, and commands to repair and reconstruct images.&#160;They will learn how to evaluate the color, tone, brightness, and the overall appearance of the image and determine what tools, adjustments, and filters they can apply to enhance it.&#160;Students will also learn to work with layer styles.</p><p>Objectives</p><p>In this module, students will:</p><p>Use various tools to repair and reconstruct images</p><p>Evaluate or adjust the appearance of objects, selections, or layers using various tools</p><p>Apply photographic changes to images using tools and adjustments</p><p>Use filters to modify images destructively or non-destructively</p><p>Apply, modify, copy, and remove layer styles as well as create, manage, and save custom layer styles</p><p>Polling Question</p><p>Which of these advanced editing processes are you most excited to learn about?</p><p>Removing red-eye</p><p>Adjusting the appearance of objects, faces, etc.</p><p>Applying different effects and filters to photos</p><p>Applying different styles to documents</p><p>Multiple of the above or other</p><p>Make a selection to see the results so far.</p><p>Let&#39;s see how your answer compares to your classmates!&#160;During the module, see if your answer changes as you learn more about the different types of edits you can make in Photoshop.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('497f2e4340f2ed04bfe4a199e7512697','adobe-photoshop-m10-l2-lesson-1','39e17da81dea254f423725abeb3100cf','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Healing Tools</h3><p>Healing Tools</p><p>Photoshop gives you multiple tools that you can use to retouch and repair photos.&#160;You can use these tools to touch up photos and remove blemishes, correct red-eye in photos, whiten teeth, and many more such edits.</p><p>The great part about the retouching tools is that you can easily make these changes non-destructively by touching up the blemishes on a separate layer.&#160;Just add a layer over your image and make sure you select Sample All Layers, and any retouching or repairs you make will be made on the new layer, leaving your original image untouched if you ever need to revert to it.</p><p>Healing Tools</p><p>Let’s start off by learning about the different healing tools in Photoshop.</p><p>Healing Brush tool:&#160;This tool lets you paint with a sample or pattern to repair imperfections.&#160;As the name suggests, this is essentially a brush tool.&#160;To use this tool, you first need to select sample pixels to tell Photoshop to what it needs to match your selection.&#160;Then, you paint over the imperfections in your image.&#160;Photoshop uses the sampled pixels to replace the imperfections with pixels that not only match the color of your selection but also matches the texture, lighting, shading, and transparency of the sampled pixels to give you a realistic repair.&#160;Because of this, the healed area blends seamlessly into the rest of the image.&#160;Healing tools are especially useful when removing blemishes or scuff marks from the skin on your images, among other things.</p><p>First, you need to select the&#160;Healing Brush&#160;tool.&#160;You can fine-tune your brush settings like the brush size, hardness, etc. from the&#160;Options&#160;bar.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Healing tool Options bar</p><p>The hotspot points on the image are as follows:</p><p>Aligned</p><p>Select this if you want to sample pixels continuously as you use the tool. You can deselect this if you want to continue using the sampled pixels from the initial sampling point.</p><p>Mode</p><p>You can specify the blending mode here. For example, if you are using a soft brush, you can choose Replace to preserve the texture and grain at the edges of the brush stroke.</p><p>Source</p><p>Here you can specify where pixels should be sampled from. You can either select a sample from the image, or choose a pattern.</p><p>Diffusion</p><p>This controls the degree of diffusion of the pasted region. If you are correcting an image that has a lot of grain or finer textured details, choose a lower diffusion value. If you are working with smooth areas on an image, you can use a higher diffusion value.</p><p>Sample</p><p>You have the option of sampling data from other layers in your document as well.</p><p>The first step is to set a sampling point on the image.&#160;Press and hold down the&#160;Alt&#160;key on&#160;Windows&#160;or&#160;Option&#160;key on&#160;Mac&#160;and click on an area on the image.&#160;Then, click and drag over the areas you want to correct on the image.&#160;The pixels from your selection are melded with the pixels you paint over.</p><p>Spot Healing Brush tool:&#160;This tool removes blemishes and objects.&#160;It works similarly to the Healing Brush tool and can be used for quick touch-ups.&#160;But because you are correcting smaller blemishes, the Spot Healing Brush tool doesn’t require you to make a sample selection.&#160;It automatically samples pixels from around the area you click on to heal the blemish.</p><p>Select the&#160;Spot Healing Brush&#160;tool and choose a brush size and blending mode.&#160;Because you don’t need to make a sample pixel selection yourself, this tool gives you an option to choose from three types of selections it can make.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Spot healing tool Options bar</p><p>The hotspot points on the image are as follows:</p><p>Content Aware</p><p>This compares nearby areas to fill in the pixels. We’ll learn more about this option later in the module.</p><p>Create Texture</p><p>This will use pixels in the selection to create a texture.</p><p>Proximity Match</p><p>This will choose pixels around the edge of your selections to use as a patch.</p><p>Once you choose your settings, just click or drag over areas you want to fix.</p><p>Patch tool:&#160;This tool repairs imperfections in a selected area of an image using a sample or pattern.</p><p>The patch tool is a great way to replace pixels from one area with pixels from another area.&#160;This also works similarly to the other Healing tools.&#160;You can also use the Patch tool to clone areas of an image.</p><p>The Patch tool works a lot like a selection tool.&#160;You can patch areas in two ways, you can either select the blemish and drag it to a Source area on the image that you want it to match, or you can select a clean area on the image and drag it to the blemish to patch it.&#160;Depending on which option you want to go with, make the selections in the Options bar.</p><p>Then, draw a selection on the area you want to repair or copy, and drag it over the other area.</p><p>Red Eye tool:&#160;The Red Eye tool removes the red reflection caused by a flash.&#160;We’ve all been there before, you take a great picture but when you look closely, someone in the picture has red eyes.&#160;Photoshop lets you easily remove red-eye in flash photos of people and even animals.</p><p>Just select the&#160;Red Eye&#160;tool in Photoshop, and click or drag a small selection on the red eye.&#160;It should disappear immediately.&#160;If you still see some red remaining in the eye, you can undo the change, refine your selection by adjusting the settings in the&#160;Options&#160;bar, and click again.</p><p>Pupil Size:&#160;Use this to increase the size affected by red-eye.</p><p>Darken Amount:&#160;Use this to set the darkness of the correction.</p><p>In most cases, you can just go with the default values of these settings.&#160;Just click once again on the eye and any remaining traces of red eye should be removed.</p></section><section><h3>Clone Stamp Tool</h3><p>Clone Stamp Tool</p><p>The Clone Stamp tool allows you to sample a part of an image and paint it over another part of the image. This is very useful for duplicating objects in an image. For example, if you have an imag<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('41dd6c90279ca04a0eae9fbb167b08ac','adobe-photoshop-m10-l3-lesson-2','39e17da81dea254f423725abeb3100cf','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Adjustments and Adjustment Layers</h3><p>Adjustments and Adjustment Layers</p><p>At its core, Photoshop is a powerful image editor.&#160;Among other things, it offers an array of commands and tools that help you edit your photos by improving contrast, adjusting color balance, removing color casts, adjusting and enhancing shadows, brightness, and highlights, and so much more.</p><p>These commands are called&#160;Adjustments&#160;and you can access them directly from the&#160;Image&#160;menu in Photoshop.</p><p>One of the only disadvantages of using adjustments from the Image menu is that they are all destructive edits, which means that any edit your make could permanently alter, modify, or even destroy pixels and thereby the quality of your images.</p><p>A workaround to this is to edit using&#160;Adjustment Layers&#160;in Photoshop.&#160;Basically what this does is to create a separate layer over your image on which all of the edits are made.&#160;This means you always have a record of all the changes you make to an image, you can delete or modify these edits at any time, and you can always go back to your original image.</p><p>To add an Adjustment layer, just select the layer, and click the&#160;New Adjustment Layer&#160;icon in the Layers panel.</p><p>You can also add the Adjustment panel to your workspace so you can easily access it at any time.&#160;Just click the&#160;Window&#160;menu and select&#160;Adjustments.&#160;The panel will be added to your workspace, and you can move and dock it as per your convenience.</p><p>Over the next few pages, we’ll explore a few of the types of adjustments you can apply to edit the appearance of your images, but there are many others that you can explore as well.</p><p>Video Title:&#160;The 19 Adjustment Layers in Photoshop Explained</p><p>Video Publisher:&#160;Dansky</p></section><section><h3>Reading Histograms</h3><p>Reading Histograms</p><p>The histogram in Photoshop is one of the most valuable tools that you will need to use while editing photos.&#160;A histogram is basically a graph that denotes the tonal range or the range of brightness of an image.&#160;So when you look at the graph in a histogram, from left to right, the graph denotes the levels of black to white in the image.</p><p>This doesn’t mean that histograms only talk about black and white or greyscalecolors.&#160;Histograms also apply to colors and show the range of tonal distribution in terms of colors as well.&#160;For example, whites and yellows are lighter, brighter colors as compared to blues and greens.</p><p>But why do we need histograms?&#160;There are many times when you look at an image and you&#160;know&#160;that there is something off about it, but you just can&#39;t put your finger on what exactly it is.&#160;Also, what constitutes a ‘good’ picture can be very subjective.&#160;A histogram gives you an objective view of the balance of tones and colors in an image and helps you fine-tune those details and create a more well-balanced image.</p><p>Take a look at this video that explains how you can use histograms to analyze and adjust the appearance of photos.</p><p>Video Title:&#160;Histograms</p><p>Video Publisher:&#160;Tony &amp; Chelsea Northrup</p><p>Use the links in&#160;the Additional Resources&#160;section at the end of this module to learn more.</p></section><section><h3>Adjusting Brightness and Contrast</h3><p>Adjusting Brightness and Contrast</p><p>You can use the Brightness/Contrast adjustment to make adjustments to the brightness, contrast, and tone of an image.&#160;These are fairly common settings that you may have adjusted in other tools or programs as well.&#160;Increasing the brightness just increases the tonal values and increases the highlights in the image.&#160;Reducing the brightness decreases tonal values and increases the shadows in the image.&#160;Contrast adjustments just alter the overall tonal values of the image.</p><p>Just click the&#160;Brightness/Contrast&#160;icon in the&#160;Adjustments panel, or click the&#160;New Adjustment Layer&#160;icon and select&#160;Brightness/Contrast.</p><p>Now, in the&#160;Properties&#160;panel, you can drag the brightness and contrast sliders to adjust the levels.</p><p>If you look at the&#160;Layers&#160;panel, you will see that the adjustment is added as a separate layer over your image.&#160;If you hide this layer, you’ll notice that the original image is still intact.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ea04ca0b519875fcef41e95e9eb1cdea','adobe-photoshop-m10-l4-lesson-3','39e17da81dea254f423725abeb3100cf','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Dodge, Burn, and Sponge Tools</h3><p>Dodge, Burn, and Sponge Tools</p><p>If you had to guess what these three tools do in Photoshop just by their names, chances are, you’d be stumped.&#160;Photoshop was built as a tool for photographers, and as such, a lot of the tools in Photoshop are made to replicate actual, traditional darkroom processes and techniques.</p><p>Dodging referred to lightening an image, burning referred to darkening an image, and sponging involved adjusting the color saturation.</p><p>Fun Fact:&#160;If you look at the icons for these tools in Photoshop, they seem a little odd, right?</p><p>The lollipop type icon of the&#160;Dodge tool&#160;is actually mimicking an actual darkroom technique to lighten photos, which was to stick a circular piece of cardboard at the end of a stick or hanger, and use this ‘device’ to control the amount of light falling on the developing image to control the lightness of the image.</p><p>The&#160;Burn tool’s&#160;icon looks like a hand making the letter “O”.&#160;Once again, this was a technique used in the darkroom to focus light onto the paper and burn through the hole to darken areas of the image.</p><p>And finally, the&#160;Sponge tool&#160;is probably the most obvious of the three.&#160;In the darkroom, a sponge saturated with chemicals would be used to increase or decrease the color saturation on images.</p><p>Let’s see how you can use these tools to edit photos.</p><p>Dodge and Burn Tools</p><p>These tools operate in similar ways.&#160;Once you select either of these tools from the Toolbar, you will see these settings in the&#160;Options&#160;bar.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Dodge and Burn tool Options bar</p><p>The hotspot points on the image are as follows:</p><p>Exposure</p><p>As in the darkroom, you can specify the exposure of the tool. The default value here is 50%.</p><p>Range</p><p>This defines which range of colors on the image the tool should focus on. For example, if you select Midtones and use the tool, it will change only the midtone shades on the image. Similarly, if you choose Shadows, it will target the dark areas of the image, and if you choose Highlights, it will target the light areas of the image.</p><p>Airbrush</p><p>This option allows you to use the brush as an airbrush.</p><p>Protect Tones</p><p>Select this option to protect the tones and minimize clipping in the shadows and highlights.</p><p>Brush settings</p><p>You can refine the type of brush tip, size, hardness, etc.</p><p>To use either of these tools, select it from the Toolbar, specify the settings in the&#160;Options&#160;bar and just drag over the areas you want to touch-up in the image.</p><p>Using the Dodge tool:</p><p>Using the Burn tool:</p><p>Sponge Tool</p><p>This tool is used to saturate or desaturate the colored areas of an image.&#160;When you select the Sponge tool, you will see a few different options in the Options bar.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Sponge tool Options bar</p><p>The hotspot points on the image are as follows:</p><p>Flow</p><p>This is different from exposure. Flow controls the rate at which the effect is applied to the image. So, if the Flow is set to 100%, you will make the changes fastest. If you want the effect to be applied gradually over multiple strokes, reduce this value.</p><p>Mode</p><p>You can select if you want to saturate or desaturate the photo.</p><p>Vibrancy</p><p>This is similar to the Protect Tones setting in the Burn and Dodge tools, but here, you are minimizing clipping for saturated or desaturatedcolors.</p><p>To use this tool, select it from the Toolbar, make the adjustments in the&#160;Options&#160;bar, and drag over the areas you want to touch-up in the image.</p><p>Using the Sponge tool:</p></section><section><h3>Blur, Sharpen and Smudge Tools</h3><p>Blur, Sharpen and Smudge Tools</p><p>There are many ways in which you can control the sharpness or blur of an image in Photoshop.&#160;There are multiple tools, filters, and masks you can use to fine-tune your images, whether you need to apply edits over the entire image or choose specific areas of the image to enhance.</p><p>Take a look at the&#160;Additional Resources&#160;page at the end of this module for helpful tips that you should keep in mind while sharpening images.</p><p>We’ll cover the filters that you can use to sharpen and blur images in the next module.&#160;Here, let’s discuss the&#160;Blur,&#160;Sharpen, and&#160;Smudge&#160;tools in the Photoshop toolbar.&#160;All of these tools work like paint tools and allow you to work on specific areas of the image.</p><p>Blur Tool</p><p>The blur tool softens the hard edges in an image.&#160;To blur areas in your image, first select the Blur tool from the Toolbar.</p><p>In the Options bar, you can refine the settings by selecting a brush tip, brush size, etc. You can also use a blending mode to define how the pixels blur.&#160;The strength defines the strength with which each brush stroke is applied.</p><p>Sharpen Tool</p><p>This tool increases the contrast around the edges to give the impression of images becoming sharper.&#160;You can keep painting over the image to increase the sharpness.</p><p>To sharpen areas on an image, first select the Sharpen tool.&#160;Choose a brush tip and other settings.&#160;You can select the Protect Details icon to enhance detail and minimize the chances of the image looking pixelated.&#160;If you are going for a more exaggerated sharpening edge, keep this setting off.</p><p>Smudge Tool</p><p>This tool basically simulates the effect of running your finger through wet paint.&#160;Essentially, this tool picks up the pixels from the spot you start your brush stroke and smudges it in the direction of the stroke.</p><p>Select the Smudge tool and specify the brush settings in the Options bar.&#160;You can choose the Finger Painting option to add the foreground color to your brush stroke.</p></section><section><h3>Photo Filter Adjustment</h3><p>Photo Filter Adjustment</p><p>Another way in which you can enhance your photos is by using the&#160;Photo Filter&#160;adjustment layer in Photoshop. This setting allows you to add a color tint to your photos.</p><p>Just select the&#160;New Adjustment Layer&#160;icon and select&#160;Photo Filter.</p><p>As soon as you add this adjustm<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7dc4b2327fa79091db37b5c046006702','adobe-photoshop-m10-l5-lesson-4','39e17da81dea254f423725abeb3100cf','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Using Filters</h3><p>Using Filters</p><p>License:&#160;All Rights Reserved</p><p>Filters are a great way to touch-up photos and apply special effects that alter the appearance of images.&#160;Think of it as the original Instagram filters, only much more versatile and customizable.</p><p>Filters in Photoshop can be applied destructively or non-destructively.&#160;You&#39;ve learned about this earlier in the course.&#160;When applied destructively, filters can permanently alter the pixels on an image and thereby affect the image quality.&#160;This will also mean that you cannot revertt older versions of the image.</p><p>On the other hand, Smart Filters can be applied to Smart Objects, and are therefore non-destructive.&#160;These are basically stored as layer effects in the Layers panel, much like how you would see adjustments when you apply them to layers.&#160;This means you will always have a record of what filters were applied to the image and can go in and edit or delete them.</p></section><section><h3>Applying Filters</h3><p>Applying Filters</p><p>Al of the filters in Photoshop are available in the&#160;Filter&#160;menu.&#160;You can choose to apply these filters either destructively or non-destructively.&#160;To apply Smart Filters to layers or objects, just convert them to Smart Objects.&#160;You have already learned how to convert a layer or object to a Smart Object.</p><p>To view all the available filters in Photoshop, just click the&#160;Filter&#160;menu.</p><p>There are a ton of filters available in Photoshop, make sure you explore them all to see how they can be used.&#160;Here is an overview of all the main categories of filters you can choose from:</p><p>3D filters</p><p>Artistic filters</p><p>Blur filters</p><p>Brush Stroke filters</p><p>Distort filters</p><p>Noise filters</p><p>Pixelate filters</p><p>Render filters</p><p>Sharpen filters</p><p>Sketch filters</p><p>Stylize filters</p><p>Video filters</p><p>Other filters</p><p>To read more about each of the different filters under these categories, check the links in the&#160;Additional Resources&#160;section at the end of this module.</p></section><section><h3>Filter Gallery</h3><p>Filter Gallery</p><p>The Filter Gallery in Photoshop gives you access to a whole slew of photo filters and effects that you can apply to your images, layers or objects.&#160;Not all the filters in the filter menu are available in the Filter Gallery.&#160;To access the gallery, just click the&#160;Filter&#160;menu and select&#160;Filter Gallery.</p><p>You will see a popup with a preview of the image on the left, a number of filter categories on the right, and the last column on the right has more specific settings that you can modify for each type of filter.</p><p>Use the&#160;Zoom&#160;buttons at the bottom of the preview box to adjust the size of the preview.</p><p>Select the filter you want from the filter categories.&#160;The great thing about this is that you can see a preview of how your image looks with different filters applied and can also adjust the settings before finalizing a filter.&#160;Once you are happy with the filter, click&#160;OK.</p><p>If you applied filters on a Smart Object, your Smart Filter will appear in the Layers panel below your image layer.</p></section><section><h3>Blending and Fading Filters</h3><p>Blending and Fading Filters</p><p>Do you know how in Instagram, you can select a filter and then adjust the intensity of the filter as well using a slider?&#160;Well, Photoshop did it first!&#160;After applying a filter to a layer, you can go back and adjust the opacity and blending mode of any filter.</p><p>If you are applying filters destructively, you can use the&#160;Fade&#160;command in Photoshop to do this.&#160;In fact, the Fade command can also control the opacity and blending mode of painting and erasing tools as well as color adjustments.&#160;Just select the layer that you have applied the filter to, click the&#160;Edit&#160;menu and select&#160;Fade Filter Gallery.</p><p>You can drag the slider to adjust the opacity of the filter.&#160;You can also choose a blending mode from the&#160;Mode&#160;drop-down list.</p><p>If you use Smart Filters on your document, you will not be able to access the&#160;Fade&#160;popup from the&#160;Edit&#160;menu.&#160;Instead, you can access similar settings from the Layers panel.&#160;Just double-click the&#160;Edit Blending Options&#160;icon next to the filter in the Layers panel.</p><p>You can then select the blending mode and the opacity and click&#160;OK&#160;to save the changes.</p><p>Tips on Working With Smart Filters</p><p>When you apply Smart Filters to layers, you have a lot more flexibility because you can apply multiple filters to the same layer, rearrange or delete them, or edit the opacity and blending modes at any time.</p><p>To edit a Smart Filter, just double-click the&#160;Smart Filter&#160;in the&#160;Layers&#160;panel.&#160;You can set your filter options and make any other modifications needed and click&#160;OK.</p><p>If you don’t want to delete a Smart Filter but just temporarily hide it, you can do that as well by just turning off the visibility in the&#160;Layers&#160;panel.</p><p>Another great advantage is that you can easily duplicate filters that you have already added and apply them to other layers or objects in your document.&#160;All you need to do is&#160;Alt + drag (in Windows)&#160;or&#160;Option + drag (on Mac)&#160;the Smart Filter from one Smart Object to another.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('dc0b5cead163801cde4441d4ef3d9424','adobe-photoshop-m10-l6-lesson-5','39e17da81dea254f423725abeb3100cf','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Layer Effects and Styles</h3><p>Layer Effects and Styles</p><p>Photoshop allows you to add a myriad of photo and text effects to your images and designs.&#160;You can add drop shadows, bevels, strokes, gradients, patterns, glows, and many more such effects to your documents.&#160;When you apply one or more different effects to a layer or layer group in your document, it becomes a&#160;layer style.&#160;You can also apply blending modes to layer styles to define how the different effects blend together.&#160;Layer styles are also non-destructive, which means they do not permanently alter the pixels on your image.</p><p>So how do you go about adding effects and layer styles to your document?</p><p>Photoshop has an array of&#160;preset styles&#160;for you to choose from.&#160;These styles are a combination of different effects in Photoshop that are grouped based on their function.&#160;&#160;For example, you will find a library of preset styles that you can use to create different types of buttons.</p><p>If you do not find a preset style that has all the effects that you want to apply, you can also create&#160;custom styles&#160;on your own.&#160;You can do this by editing a preset style, or by creating your own style from scratch by adding effects to the image one by one.&#160;Once you save a custom style, it becomes a preset style so that you can access it at any time.</p><p>Before you can apply styles, there is one thing you should remember.&#160;You cannot apply styles directly to the background or base layer of a document.&#160;So, always duplicate your background layer or convert it to a layer in Photoshop before you start applying styles.</p></section><section><h3>Applying Preset Styles</h3><p>Applying Preset Styles</p><p>View Preset Styles</p><p>So how do you view the effects and styles available in Photoshop?</p><p>To view the preset styles available in Photoshop, select&#160;Window&#160;and click&#160;Styles.&#160;A new panel will be added to your workspace.&#160;Here, you can see a set of default preset styles to choose from.</p><p>In Photoshop, preset styles are grouped into libraries based on their function.&#160;To see the other libraries of styles available in Photoshop, click the panel’s&#160;Menu&#160;button.&#160;Here, you can see a list of different libraries.&#160;Just select a library to load the preset styles from that library.</p><p>You can change how the preset styles are displayed.&#160;Just click the&#160;Menu&#160;button of the panel and select from one of the views provided.</p><p>Applying Preset Styles to a Layer</p><p>To apply a preset style to a layer, just click a style in the Styles panel.&#160;You can also drag and drop the style onto the layer if you want to add the style to a particular object on the layer.</p><p>If you drag another style onto the same layer or object, it will replace the existing style.&#160;So, after applying one style, if you want to add (and not replace) another style onto the same layer, then press and hold down the&#160;Shift&#160;key as you drag the style onto the layer or object.&#160;It will be added to the existing effects.</p><p>Copy Layer Styles</p><p>If you have multiple layers in a document, and you want to copy the same style to a different layer, just&#160;Alt + drag (in Windows)&#160;or&#160;Option + drag (in Mac)&#160;the style onto the other layer.</p><p>If you have a large number of layers in your document, it can be difficult to drag effects between layers.&#160;In these cases, you can also right-click the style and click&#160;Copy Layer Style.&#160;Then, click the destination layer and right-click the layer, and click&#160;Paste Layer Style.</p></section><section><h3>Exploring the Layer Style Window</h3><p>Exploring the Layer Style Window</p><p>You can create a custom style by editing an existing preset style using the&#160;Layer Style window.</p><p>There are a few different ways you can open the Layer Style window:</p><p>Double-click the layer outside the layer name or thumbnail.</p><p>Select the layer and click the&#160;fx&#160;icon in the Layers panel.&#160;Select the effect that you want to add to the preset style.&#160;This will launch the Layer Style window.</p><p>You can also click the&#160;Layer&#160;menu, select&#160;Layer Style&#160;and select an effect that you want to add.</p><p>Layer Style Window</p><p>The Layer Style window is your one-stop-shop for creating and editing styles.&#160;On the left panel, you will see the current style applied to the layer, and the effects within that layer selected with checkboxes.&#160;You will also see a&#160;Blending Options&#160;tab that you can use to add and edit the different blending modes.</p><p>If you open the Layer Style window by double-clicking on a layer with a style already applied to it, you will only see the effects of that style in the left panel.</p><p>If you opened the Layer Style window on a layer with no styles applied, you will see all the available effects in the left panel.&#160;You can create custom styles using one or more of the following effects:</p><p>Click each tab to learn more.</p><p>Next Tab</p><p>Bevel &amp; Emboss</p><p>Add different combinations of highlights and shadows to a layer.</p><p>Stroke</p><p>Outlines the object on the current layer using color, a gradient, or a pattern.</p><p>Inner Shadow</p><p>Adds a shadow inside the edges of the layer’s content, giving the layer a recessed appearance.</p><p>Inner &amp; Outer Glow</p><p>Adds a glow to the inner or outer edges of the layer’s content.</p><p>Satin</p><p>Gives a satin finish to the layer or object using interior shading.</p><p>Color, Gradient, and Pattern Overlay</p><p>Fills the layer’s content with a color, gradient, or pattern.</p><p>Drop Shadow</p><p>Adds a shadow behind the contents on the layer.</p></section><section><h3>Creating a Custom Style</h3><p>Creating a Custom Style</p><p>You’ve learned how to launch the Layer Style window.&#160;Now, let’s see how you can create or edit your own custom styles in Photoshop.</p><p>To create a custom style from scratch, just double-click the layer outside the thumbnail or layer name. The Layer Style window appears. Here, you can select any of the effects from the left panel and edit the settings here based on your requirements. Let’s add a color overlay on this image. The default cover overlay is a grey color with 100% opacity. Let&#39;s change this color and click&#160;OK. And let’s also adjust the Opacity so w<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ba7b542606d0498dd6cde318fa15b24f','adobe-photoshop-m10-l7-module-10-summary','39e17da81dea254f423725abeb3100cf','Module 10 Summary','text',12,'<h2>Module 10 Summary</h2><section><h3>Module 10 Summary</h3><p>Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module&#160;on Creating and Modifying Visual Elements Part III.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Used various tools to repair and reconstruct images.</p><p>Evaluated or adjusted the appearance of objects, selections, or layers using various tools.</p><p>Applied photographic changes to images using tools and adjustments.</p><p>Used filters to modify images destructively or non-destructively.</p><p>Applied, modified, copied, and removed layer styles as well as created, managed, and saved custom layer styles.</p><p>Additional Resources</p><p>The following articles and websites were referenced in this module.&#160; (Not required reading)</p><p>Fix photos faster with content-aware tools(opens in a new tab)</p><p>How ŞakirYildirim created “Crawler”(opens in a new tab)</p><p>View histograms and pixel values(opens in a new tab)</p><p>How To Read And Understand Image Histograms In Photoshop(opens in a new tab)</p><p>Sharpening recommendations(opens in a new tab)</p><p>Filter effects reference</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ff1673bf7481c17c77d597c11c378ff3','adobe-photoshop-m10-l8-module-10-project','39e17da81dea254f423725abeb3100cf','Module 10 Project','text',12,'<h2>Module 10 Project</h2><section><h3>Module 10 Project</h3><p>2400</p><p>Adobe Photoshop</p><p>Creating and Modifying Visual Elements Part III - Project</p><p>Project</p><p>In this assignment, you will apply all that you have learned about the core design tools in Photoshop. You will need to use Photoshop to perform these tasks. Take screenshots after completing each step and save them as image files or add them to a Word/PPT document.</p><p>Take a picture with your phone or camera. It is preferable to use an image with minor blemishes in it, for example, a table with watermarks on it, or dirt marks on a person or clothes. Use the repairing and reconstructing tools in Photoshop to edit out minor blemishes or issues in the photo.&#160;(You may use more than one healing tool if required. Take before and after screenshots and make a note of which tool(s) you used.)</p><p>Take another image with your phone or camera. Open the histogram and make an assessment of the brightness and tone of the image. Write out an explanation on a Word document along with a screenshot of the histogram and image.</p><p>Open an image in Photoshop and use any two photo editing tools (Dodge, Burn, Sponge, Blur, Sharpen or Smudge tools) to edit and enhance the image. Apply the tools separately, and take before and after screenshots to show the differences.</p><p>Use the same image as step 3 and apply a filter non-destructively to the image. You can choose a filter from any of the available libraries in Photoshop.&#160;(Take a screenshot once the task is complete.)</p><p>Create a custom style of your choosing in Photoshop. You can choose to create this from scratch or by modifying an existing style. Make sure you save the style with a descriptive name.&#160;(Take a screenshot once the task is complete.)</p><p>Review the rubric below to see how you will be graded.</p><p>Creating and Modifying Visual Elements Part III</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Use tools to repair and reconstruct images</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Evaluate or adjust the appearance of objects</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Apply photographic changes to images</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Use filters to modify images destructively or non-destructively</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Work with layer styles</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('962da1c403c8edb9a4d3bb759ce85d6f','adobe-photoshop-m10-l9-module-10-quiz','39e17da81dea254f423725abeb3100cf','Module 10 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Visual Elements Part 3. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('3deb59b98a62ba0ed4ae849da1354549','adobe-photoshop-module-11','ee9c9635d1344f63172dfbcc5883d9ea','Module 11: Publishing Digital Media',11) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e126ee6f2c04837c6800419425a6f10b','adobe-photoshop-m11-l1-introduction-purpose-and-objectives','3deb59b98a62ba0ed4ae849da1354549','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi everyone, and welcome! This is the intro video on the module on Publishing Digital Media. This is the final module of the Photoshop course. It’s been an exciting journey diving into all of the fantastic features that Photoshop has to offer. You’ve learned about basic but critical aspects of working in the design industry, both with teams and clients. You explored the Photoshop interface and the various tools and commands available. You learned how to create documents and organize them using the various tools and panels in Photoshop. Next, you handled more complex topics by creating and modifying visual elements of images and documents using various functions. By now, you should have an idea of just how many things you can do with Photoshop. Just like any other tool, you’ll keep getting better at it the more you use it, so make sure you explore Photoshop and experiment to build beautiful designs!</p><p>In this module, we’ll cover an important last step in this Photoshop journey—publishing and exporting your digital media. Because Photoshop allows you to work with so many different types of documents, it also gives you multiple options to prepare and export your data in various formats and for various purposes.</p><p>Module Description</p><p>Photoshop gives you multiple ways and formats in which you can export your documents, images, and designs for digital use, printing, or for further processing in other tools or programs.&#160;In this module, students will learn how to adjust project specifications and save their files in the correct format.&#160;Students will also learn about exporting project elements in various formats.&#160;Finally, we’ll go over the structure and test prep students will need for the ACA Photoshop Certification Exam.</p><p>Objectives</p><p>In this module, students will:</p><p>Check the document for errors and project specifications.</p><p>Save in the native file format for Photoshop (.psd).</p><p>Save documents in appropriate image formats for print or screen.</p><p>Export project elements.</p><p>Understand the structure and test prep necessary for the ACA Photoshop Certification Exam.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('434494ab6c276f171d44733601ad8ce6','adobe-photoshop-m11-l2-lesson-1','3deb59b98a62ba0ed4ae849da1354549','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Color Space</h3><p>Color Space</p><p>License:&#160;All Rights Reserved</p><p>By now, you know that Photoshop is a robust, powerful tool.&#160;Earlier on in this course, you learned about how colors are created in digital images.&#160;Photoshop allows you to specify color settings that will determine just how many colors are available to you when you work on your documents and images.</p><p>It is logical to assume that more colors mean more detail in the image, and therefore better-looking images.&#160;But the color settings you choose depends on multiple factors.</p><p>Now, you must be wondering, what is color space?</p><p>To understand this, you need to open the Color Settings in Photoshop.&#160;For this, click the&#160;Edit&#160;menu and select&#160;Color Settings.</p><p>Don’t be intimidated by the number of settings in this window.&#160;At this level, we’ll only focus on the&#160;Working Spaces&#160;section.&#160;The settings in this section, that is the working space, are what determine which&#160;color space&#160;is used.&#160;A color space is what specifies which the range of colors that are available.&#160;Photoshop uses different color spaces for printing and for digital use.</p><p>It is recommended that you use sRGB when preparing the document for web use because it defines the color space that is used by most monitors to view web content.&#160;sRGB is also the default setting for most digital cameras as well.</p><p>If you are preparing documents for print, it is best that you use Adobe RGB as the color space because it includes several printable colors that are not included in sRGB.&#160;This has a great impact on print quality.</p><p>Make sure you check these settings before printing or exporting your document.</p><p>To read more about the color settings in Photoshop, check the links in the&#160;Additional Resources&#160;section at the end of this module.</p></section><section><h3>Resolution and Pixel Dimensions</h3><p>Resolution and Pixel Dimensions</p><p>License:&#160;All Rights Reserved</p><p>The terms resolution and pixel dimensions have come up multiple times in this course, and they are important concepts for you to understand because these factors come to the forefront when you prepare a document for export or print.</p><p>We covered these topics in an earlier module, where you learned how to resize and resample documents to prepare them for web or print use.&#160;You need to keep these factors in mind when you prepare your image or document.</p><p>If you are preparing a document for print, it is better to specify the image size in terms of the printed dimensions, that is usually measured in inches, as well as the resolution, which will determine the quality of your printed output.</p><p>If you are preparing a document for web use, the pixel dimension is all that you need to worry about because that is what determines how it appears on a webpage.&#160;The resolution doesn’t really matter in web use.</p><p>You can check and adjust these settings by clicking the&#160;Image&#160;menu and selecting&#160;Image Size.&#160;Refer to the earlier modules for details on how to resize and resample your document for print and web use.</p></section><section><h3>Metadata</h3><p>Metadata</p><p>Metadata is essential information that Photoshop saves about your document, such as, the author name, color space, copyright information, and any keywords that you may have assigned to the file.&#160;If you’ve transferred pictures from your digital camera to your computer, and then checked the properties of the image, you will be able to see all the metadata that the camera attached to the image, such as the date and time the picture was taken, height and width, file size, etc.</p><p>Metadata is very useful when you want to add copyright information for your images and documents, or to organize your files both on your computer and when you use them in other programs like Adobe Bridge, etc.</p><p>To add metadata to your file, just click the&#160;File&#160;menu and select&#160;File Info.&#160;This window displays all the metadata for your file.&#160;You can populate the fields as required.</p><p>Some important fields to consider, based on where you will be using these files, are&#160;Document Title,&#160;Author,&#160;Description,&#160;Keywords,&#160;Copyright Status&#160;and&#160;Copyright Notice.&#160;Explore the other tabs to view other metadata that you may want to add.</p><p>&#171;Resolution and Pixel Dimensions</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6c3b4c897124bfa264850243fe82dddd','adobe-photoshop-m11-l3-lesson-2','3deb59b98a62ba0ed4ae849da1354549','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Saving Files</h3><p>Saving Files</p><p>Once you have finished working on your file or image, and you have prepared your document, the next step is choosing a file format to save your files.&#160;Why is this so important?&#160;This is because depending on the file format you choose, your image data or the pixels in your document will be processed in different ways.&#160;For example, some formats preserve the layers in your document, while others may flatten them.&#160;Some may maintain transparency while others may fill the background with white.</p><p>As a best practice, it is always recommended to save your file in the native Photoshop file format, that is in PSD format.&#160;This allows you to preserve a master copy of your file in case you need to go back in and extract specific objects or layers, make edits to the file, or if your exported file is lost or corrupted.</p><p>Saving your file as a PSD document is easy.&#160;Just click the&#160;File&#160;menu and click&#160;Save As.</p><p>Choose the location where you want to save the file.&#160;Enter a name for the file and choose&#160;Photoshop&#160;as the file type.&#160;Once you do this, you will see that the checkboxes&#160;As a Copy&#160;and&#160;Layers&#160;have become active.</p><p>If you are going to return and work on this document again, then only ensure that the&#160;Layers&#160;check box is selected, and click&#160;Save.</p><p>If, however, you are also planning on exporting the file in other formats, make sure you select the&#160;As a Copy&#160;option.&#160;This is because if you don’t, Photoshop will save your open file as a PSD file and close it.&#160;To avoid this, save the master file as a copy, and then you can save this file in other formats for print or screen use.</p><p>Once you click Save, you will see a popup for&#160;Photoshop Format Options.&#160;Always make sure that the&#160;Maximize Compatibility&#160;checkbox is selected.&#160;This ensures that even if you open your Photoshop file in another version of Photoshop, it remains compatible and opens without any errors.&#160;Click&#160;OK&#160;and your file will be saved as a PSD.</p><p>Fun fact, a lot of printers nowadays let you print directly from PSD files.&#160;You can also open PSD files directly from other Adobe programs like InDesign to incorporate your designs into layouts or other files.</p><p>The only downside of saving a document as a PSD file is that the file size can become large.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f8deeb50377258d2e09456eb92a599dd','adobe-photoshop-m11-l4-lesson-3','3deb59b98a62ba0ed4ae849da1354549','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Image Formats</h3><p>Image Formats</p><p>You’ve learned how to save your file as a master file.&#160;Now, let’s see how you can choose to save and your image in formats for print or screen use.&#160;Photoshop allows you to save your document in over 20 different file formats.&#160;But don’t worry, you will only ever need to use a handful of these formats.&#160;Let’s go over a few different file formats and how you can use them.</p><p>JPG or JPEG</p><p>This is a fairly common image format and is quite widely and commonly used.&#160;It supports 24-bit color.&#160;When you save a document as a JPEG, it compresses the file size by flattening the layers in your document and selectively discarding data.&#160;This doesn’t mean that you will lose any of your graphics or images, Photoshop only does this as a way of reducing the file size.</p><p>You can use JPEG images for web use&#160;because they can easily be uploaded and shared online.&#160;The only thing you need to be mindful of is to avoid resaving a JPEG file repeatedly.&#160;So let’s say you work on a Photoshop document using a JPEG image, add some text and other elements to it, and save it as a JPEG.&#160;Then you import that JPEG into another Photoshop file and work on it some more.&#160;Each time you save this file, it distorts the quality of the image.&#160;This is why it is so important to save your master PSD files so that you can just go back to the original file and make any changes if needed.</p><p>PNG</p><p>This is a great file format to use when you want to preserve transparent pixels on your document.&#160;This is something JPEG cannot do.&#160;You can use PNG files for web use.&#160;Another advantage of PNG is that it is a lossless file format, which means that when you save a file as a PNG, it compresses the image to reduce the size but it doesn’t degrade the quality of the image at all.&#160; You can also save PNGs multiple times without any loss in quality.&#160;This makes PNGs a great choice for web use.</p><p>The only downside is that PNG doesn’t support CMYK colors, which means that you cannot print PNG files.</p><p>TIFF</p><p>This file format is mainly used when you want to prepare your document for print.&#160;Like PSD, this format also supports all of Photoshop’s features, which means you can save photos while maintaining the highest quality.&#160;This usually also means that TIFF files are large in size.</p><p>TIFF is the universally accepted format for commercial printing, and most print vendors will request files in this format for prints of the best quality.</p><p>EPS</p><p>This is another standard print format.&#160;They are not as commonly used nowadays, but many printers may request this.&#160;And EPS file is basically a set of print instructions for the printer.&#160;You may rarely use this format, as the TIFF format is more versatile.</p><p>Check out the&#160;Additional Resources&#160;section at the end of this module for a comprehensive list of supported formats in Photoshop.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c64f2f04f334d348afaf6415745a4e99','adobe-photoshop-m11-l5-lesson-4','3deb59b98a62ba0ed4ae849da1354549','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Exporting in Photoshop</h3><p>Exporting in Photoshop</p><p>You’ve learned how to save the native PSD file, as well as how to save your file in different image formats for print and web use.&#160;Now, let’s discuss how to export different project elements.</p><p>Exporting your document or elements of your document allows you to push out finished products while still working on your PSD document.&#160;You can access all of the Export commands in Photoshop by clicking the&#160;File&#160;menu and selecting&#160;Export.</p><p>There two main ways you can export in Photoshop.&#160;You can use the&#160;Quick Export&#160;command to quickly export the document to a particular file format.&#160;The default format here is&#160;PNG, but you can easily change this from the&#160;Export Preferences&#160;window.</p><p>If you want to export specific layers or objects, or need to specify different sizes and other settings while exporting your document, you can use the&#160;Export As&#160;function.</p><p>Take a look at this video to understand the different export options.</p><p>I have a document here that has multiple layers. Let’s take a look at the different ways in which I can export this document. Click&#160;File, select&#160;Export, and click&#160;Export As. In this popup, you have a number of options available. You can choose the format in which you want to export your file here. So I can choose JPG and I can also choose the quality of the file. You can also make changes to the image size here. Often when you’re printing your artwork, you’ll want to leave padding around the document so that when you frame your artwork, only the padding gets hidden by the frame. You can add that padding here by adjusting the canvas size. You can choose whether to include the metadata in your document by selecting Copyright and Contact Info. And you can change the color space of the document.</p><p>Here on the left, you can see the&#160;Scale All&#160;option. You can use this section to add different sizes in which you want to export your document. All you have to do is click this plus icon here, and you&#39;ll see the different sizes being added. This is a really useful function in many situations, for example, if you have designed a logo and want to save it in multiple sizes to use in different places, or if you have designed a webpage but want to save it in different sizes for different devices.</p><p>Now, let’s cancel and go back to the document for a minute. You can see that this document has multiple layers. Photoshop also allows you to export individual layers of your document. All you need to do is select the layers you want to export, right-click the layers and select&#160;Export As. Now, in the Export As popup, you’ll see all the layers that you selected listed here in the left panel. You can now make the same edits to each layer individually. So, I can change the size of this layer, I can add a canvas around this layer, or make any other changes to this layer.</p><p>In the same way, you can also export different layer groups. Once you&#39;ve selected all the options that you want, just click&#160;Export All&#160;to export your files.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('89c0d3721e83018719978447162a8ca3','adobe-photoshop-m11-l6-lesson-5','3deb59b98a62ba0ed4ae849da1354549','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Certification</h3><p>Certification</p><p>License:&#160;All Rights Reserved</p><p>We’ve reached the end of this course on Photoshop.&#160;By now, you should have a good grasp on all of the fantastic features available in Photoshop and how you can use them to do everything from touching up and editing photos, to creating original, innovative artwork.</p><p>All of this training has been put in place to enable you to enhance your skills and get certified as an Adobe Certified Professional.&#160;This certification is a globally-recognized stamp on your profile that demonstrates your proficiency and understanding of digital skills.</p><p>In order to earn this certification, you will need to pass a rigorous examination administered through a Certified Authorized Testing Center (CATC).&#160;In this final lesson, we’ll give you an idea of what the structure of the examination will be like, what to expect, and how you can prepare yourself to ace the exam!</p></section><section><h3>Exam Structure &amp; Walk-through</h3><p>Exam Structure &amp; Walk-through</p><p>The Photoshop exam is a timed examination.&#160;You will have 50 minutes to complete 33 questions.</p><p>Note:&#160;All exams undergo continuing psychometric analysis and the number of questions is subject to change.</p><p>These exams evaluate both your knowledge and skills using two types of questions:</p><p>Linear questions:&#160;These are the standard multiple-choice, true/false or matching type questions that assess your knowledge and understanding of basic concepts.</p><p>Performance-based questions:&#160;These questions will have you perform steps in a simulated Photoshop application so you can demonstrate your skills in the actual work environment.</p><p>Let’s look at how these two sections will be structured.</p><p>Tutorial:&#160;You will start off with a tutorial introducing you to the exam, how to navigate it, and how to answer questions.&#160;&#160;This is not a timed task, so take your time to read through and understand the rules.</p><p>Questions:&#160;This is the first section that contains linear questions.&#160;The timer starts as soon as you begin this section.</p><p>Section Summary:&#160;Once you complete a section and submit the questions, you will see a summary that allows you to review only the questions.&#160;You cannot revisit questions once submitted, so make sure they are final.</p><p>Tutorial:&#160;The timer is paused for a tutorial on how to proceed with the next section of the exam.&#160;Again, take your time to understand the rules.</p><p>Tasks:&#160;This second section contains performance-based questions or tasks that you will need to perform in a virtual Photoshop environment.&#160;The timer will resume where you left off as soon as you begin this section.</p><p>Section Summary:&#160;Once you complete the second section, you can review the tasks you just completed in the Section Summary page.</p><p>Leave Feedback:&#160;After you have submitted both sections, you can leave feedback on the exam, tasks or questions.</p><p>License:&#160;All Rights Reserved</p><p>The best way to prepare yourself for the Photoshop examination is to practice, practice, practice!&#160;The projects you’ve completed throughout this course are a great way for you to do this.&#160;Re-do the projects with different images and use different tools to perform the tasks.&#160;Explore Photoshop and practice using all of the different tools.</p><p>You can also use the additional resource links shared throughout this course and explore those websites for more tutorials, forums, and insight into the different ways in which you can use Photoshop.&#160;Finally, share and discuss your work and creative ideas with your classmates and friends.&#160;Working collaboratively is a great way to discover new creative direction and explore all that Photoshop has to offer.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c54aab867feb5d4d20ae873e534b1679','adobe-photoshop-m11-l7-module-11-summary','3deb59b98a62ba0ed4ae849da1354549','Module 11 Summary','text',12,'<h2>Module 11 Summary</h2><section><h3>Module 11 Summary</h3><p>Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Publishing Digital Media.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Checked documents for errors and project specifications.</p><p>Saved files in the native file format for Photoshop (.psd).</p><p>Saved files in the appropriate image formats for print or screen</p><p>Exported project elements.</p><p>Understood the structure and test prep necessary for the ACA Photoshop Certification Exam.</p><p>Additional Resources</p><p>The following articles and websites were referenced in this module.&#160; (Not required reading)</p><p>6 Color Settings in Photoshop That You Need to Know(opens in a new tab)</p><p>Customize color settings(opens in a new tab)</p><p>Basic troubleshooting steps to fix most issues(opens in a new tab)</p><p>Supported file formats</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a4b887121c3c73036efa3106a0683437','adobe-photoshop-m11-l8-module-11-project','3deb59b98a62ba0ed4ae849da1354549','Module 11 Project','text',12,'<h2>Module 11 Project</h2><section><h3>Module 11 Project</h3><p>2400</p><p>Adobe Photoshop</p><p>Publishing Digital Media - Project</p><p>Project</p><p>In this assignment, you will use what you have learned to check your document and export it in various formats.</p><p>Create a Photoshop document with multiple layers. You can choose from one of these types of documents:</p><p>A collage of multiple photos</p><p>A layout for a card with a message on it</p><p>Original artwork created using Photoshop tools</p><p>Check the settings of the document to ensure there are no errors and they fit the description provided above. Save the file as a PSD file. Save a version of the file as a JPEG image. Then, export all the layers as separate PNGs.</p><p>Review the rubric below to see how you will be graded.</p><p>Publishing Digital Media Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Check document and project specifications</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Save in native file format</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Save in appropriate format for print or screen</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Export project elements</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0b468ccd8d3d18897c3737a4f26c5095','adobe-photoshop-m11-l9-module-11-quiz','3deb59b98a62ba0ed4ae849da1354549','Module 11 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Publishing Digital Media. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('af9590f3d87baba1fe0c188933d0988f','adobe-photoshop-module-12','ee9c9635d1344f63172dfbcc5883d9ea','Module 12: Course Project Empty',12) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('cf446db90b30e0a163c32c260226afca','adobe-photoshop-m12-guided-learning','af9590f3d87baba1fe0c188933d0988f','Guided Learning','text',15,'<h2>Course Project Empty</h2><p>Build and apply the essential concepts in this module through guided explanation, practical examples, and reflective activities.</p>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('1b7a882437ceef16e2eee4264f551e88','adobe-photoshop-module-13','ee9c9635d1344f63172dfbcc5883d9ea','Module 13: Course Summary and Final Exam',13) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4b72b54a05ebcec62b7f7d2a6b9ceed4','adobe-photoshop-m13-l1-course-summary-and-final-exam','1b7a882437ceef16e2eee4264f551e88','Course Summary and Final Exam','text',12,'<h2>Course Summary and Final Exam</h2><section><h3>Course Wrap Up and Summary</h3><p>Course Wrap Up and Summary</p><p>We&#39;re at the last leg of our exciting Photoshop journey!&#160;We hope this course has equipped you with the knowledge needed for you to master the learning objectives of this course.&#160;Photoshop is a tool that is best learned by doing, which is why we gave you a ton of videos and activities to practice your skills.&#160;You should now be ready for the final exam.</p><p>Our main objective on this journey has been to push away the veil of mystery from Photoshop and enable you to discover all of the creative possibilities it has.&#160;Keep exploring Photoshop and use the resources to discover more interesting, creative ways to use Photoshop.&#160;Whether you choose to pursue a career in Graphic Designing or not, this course has given you some fantastic skills that you can still apply in other fields or even as a hobby.</p><p>Complete the final exam on the next page and submit it to complete this activity.</p></section><section><h3>Course Final Exam</h3><p>Final Exam</p><p>ABCABC</p><p>Directions:&#160;Read each question carefully and then choose the correct answer.</p><p>You have already taken this quiz and will not be able to retake it.</p><p>You should ask the client questions about the target audience around which of these factors?&#160;(Select all that apply)</p><p>Age group</p><p>Educational background</p><p>Geographical location</p><p>Cultural aspects</p><p>What are wireframes used for in web design?</p><p>They are used in web design to map the structure of a page</p><p>They are full-feature working samples of a final product</p><p>They are wire model structures made to mock-up designs</p><p>True or false?&#160;Your project plan should take into account what needs to be done, how it needs to be done, by when it needs to be done, and who you will be working with.</p><p>True</p><p>False</p><p>What is the fair use doctrine?</p><p>It states that you can use any assets that you find on the internet without permissions.</p><p>It states that you can use small portions of assets without permission for certain purposes.</p><p>It states that you must pay a fair price before using assets created by others.</p><p>It states that all original works are legally protected and cannot be used by anyone else.</p><p>True or false?&#160;Most professional photographers don’t get model or location release forms signed because it doesn’t affect their ability to sell photos.</p><p>True</p><p>False</p><p>What are the characteristics of vector graphics?&#160;(Select all that apply.)</p><p>They are made up of lines and curves</p><p>They can be resized and scaled without loss of quality</p><p>Their file size is very small</p><p>They are also called raster graphics</p><p>What is CYMK color mode most commonly used for?</p><p>Web designs</p><p>Both web and print use</p><p>It is rarely used</p><p>Printing and publishing</p><p>What is white space in a design?</p><p>It is the negative space or space left unmarked in a design</p><p>It is the background layer of an image</p><p>It is the spacing between characters</p><p>It is the amount of white in the colors used in the design</p><p>Where are display fonts commonly used?</p><p>Magazines and newspapers</p><p>Articles and website text</p><p>Titles, headers, and graphic-heavy designs</p><p>Compositional flow determines what your eyes are drawn to when you first look at a design.</p><p>True</p><p>False</p><p>What are document presets?</p><p>They are templates of designs</p><p>They are blank documents with pre-defined settings</p><p>They are the settings available for a document</p><p>True or false?&#160;You can save custom blank document presets in Photoshop.</p><p>True</p><p>False</p><p>What does the Options bar of the Photoshop interface contain?</p><p>It shows you the options for the tool that you select from the Toolbar</p><p>It shows you all the tools available</p><p>It shows you the program-level functions</p><p>How would you undock a panel and dock it in another place?</p><p>Close the panel and add it again from the Window menu.</p><p>Drag the panel out to undock it, then drag over the area you want to dock it and re-dock it.</p><p>Drag a panel out and release it.</p><p>From where can you modify the interface options like background color, theme, font sizes, etc.?</p><p>Open the Preferences window from the Edit menu (Win) or Photoshop menu (Mac)</p><p>Open the Toolbar options</p><p>Open the Panel options from the Window menu</p><p>Open File menu</p><p>What is the best way to rotate an image non-destructively in Photoshop?</p><p>You cannot rotate an image non-destructively</p><p>You can use the Transform tool</p><p>You can use the Rotate tool</p><p>You can use the Move tool</p><p>Why would you move the zero origin of the ruler in Photoshop?</p><p>To move where the corner of the document appears in the workspace</p><p>You cannot move the zero origin of the ruler</p><p>To align or measure objects from a point on the document</p><p>What is a guide layout?</p><p>It is a custom arrangement of guides that you can make and save as a preset</p><p>It is the appearance of your workspace when you add guides to it</p><p>It is an outline or sketch to guide how you place items on the document</p><p>It is a grid added on the document</p><p>What is the difference between guides and smart guides?</p><p>They are both movable lines, but objects snap to smart guides, making them more useful</p><p>They are the same, guides are just a shorter way of saying smart guides</p><p>Guides are a fixed grid of lines whereas smart guides are movable lines</p><p>What are the different commands you can use to place images in Photoshop?</p><p>Place Image</p><p>Place Embedded</p><p>Place Copied</p><p>Place Linked</p><p>What does the Swatches panel contain?&#160;(Select all that apply)</p></section><section><h3>Course Final Exam</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Photoshop lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Photoshop interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('03ce2a56d942e0fce2884524fef5c54b','adobe-photoshop-course-mastery-assessment','1b7a882437ceef16e2eee4264f551e88','Course Mastery Assessment','assessment',30,'<h2>Course mastery assessment</h2><p>Bring together knowledge and application from the complete course. Achieve at least 80% to satisfy the assessment requirement for certification.</p>',NULL,1,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO assessments (id,slug,course_id,title,pass_mark,questions) VALUES ('38d205214c2fc01581ad174d84dca052','adobe-photoshop-course-mastery-assessment','ee9c9635d1344f63172dfbcc5883d9ea','Adobe Photoshop Course Mastery Assessment',80,CAST('[{"id":"adobe-photoshop-course-mastery-assessment-q1","type":"multiple-choice","prompt":"Before starting a practical task in Design Industry Part 1, which action best demonstrates professional judgement?","options":["Clarify the intended outcome, constraints, and success criteria before choosing tools.","Choose the fastest tool and define the goal afterward.","Copy the first available example without checking its fit.","Begin production immediately and leave requirements for final review."],"answer":"Clarify the intended outcome, constraints, and success criteria before choosing tools.","explanation":"Strong practice begins with a clear outcome, constraints, and measurable success criteria.","clue":"Think about what must be understood before execution begins."},{"id":"adobe-photoshop-course-mastery-assessment-q2","type":"multiple-choice","prompt":"A first attempt in Design Industry Part 2 does not meet the requirement. What is the strongest next step?","options":["Compare the result with the criteria, identify the cause, revise, and test again.","Submit the attempt unchanged because the task is complete.","Replace the criteria with measures the attempt already meets.","Discard all evidence and restart without diagnosing the issue."],"answer":"Compare the result with the criteria, identify the cause, revise, and test again.","explanation":"An evidence-led improvement cycle diagnoses the gap before a focused revision and retest.","clue":"Use feedback and evidence to improve the next attempt."},{"id":"adobe-photoshop-course-mastery-assessment-q3","type":"multiple-choice","prompt":"Which evidence most credibly demonstrates applied competence in Setup and Interface Part 1?","options":["A completed work sample with decisions, checks, feedback, and reflection documented.","A claim that the topic was understood without a work sample.","A list of tools with no explanation of how they were used.","An unfinished draft that has not been checked against requirements."],"answer":"A completed work sample with decisions, checks, feedback, and reflection documented.","explanation":"Competence is best demonstrated through completed, reviewed evidence and reflective reasoning.","clue":"Choose evidence that shows both the result and how quality was established."},{"id":"adobe-photoshop-course-mastery-assessment-q4","type":"multiple-choice","prompt":"When work in Setup and Interface Part 2 could affect people, data, safety, or the environment, what should the learner do?","options":["Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","Proceed without checks when the intended outcome is positive.","Treat ethical and safety considerations as optional after delivery.","Hide known limitations so stakeholders remain confident."],"answer":"Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","explanation":"Responsible practice makes risk, consent, standards, and safeguards part of the work itself.","clue":"Professional quality includes the impact of the work, not only the output."},{"id":"adobe-photoshop-course-mastery-assessment-q5","type":"multiple-choice","prompt":"How should a learner transfer skills from Setup and Interface Part 3 to a new workplace or project context?","options":["Analyse the new context, adapt the method, test assumptions, and evaluate the result.","Repeat the original steps unchanged regardless of context.","Use only familiar methods and ignore new constraints.","Wait for a complete example to copy before making any decision."],"answer":"Analyse the new context, adapt the method, test assumptions, and evaluate the result.","explanation":"Transfer requires adapting core principles to new constraints and validating the result.","clue":"Core principles remain useful, but their application must fit the new context."}]' AS JSON)) ON DUPLICATE KEY UPDATE title=VALUES(title),pass_mark=VALUES(pass_mark),questions=VALUES(questions);
INSERT INTO courses (id,slug,academy_id,moodle_id,title,description,level,duration,price,is_free,status)
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('63ad9e92abe464a4f882631b92325040','adobe-premiere-pro-module-0','48ab1932af65ef3f9d0793cd5a02da34','Module 0: Introduction, Purpose, Objectives, Summary',0) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a4f4099ba6a5d9d02068ad3849edd55a','adobe-premiere-pro-m0-l1-module-0-introduction','63ad9e92abe464a4f882631b92325040','Module 0 Introduction','text',12,'<h2>Module 0 Introduction</h2><section><h3>Intro and Overview</h3><p>Course Intro Video</p><p>Select a Student</p><p>Mute</p><p>From feature films and marketing videos to social media reels, videos are on every screen around us. All videographers and filmmakers strive to produce stunning videos to express their creativity. But even the most talented videographers need some help to edit and fine-tune their videos and take them to the next level.</p><p>Adobe Premiere Pro is one of the most comprehensive and widely used digital video editing programs in the world. Whether you are a beginner experimenting with editing techniques for your social media videos, or studying to be a professional videographer to produce high-definition videos for the big screen, you can do it all using Adobe Premiere Pro. This course prepares students for Adobe’s Premiere Pro Associate certification exam. Students can start with zero experience and learn how to navigate and work in Premiere Pro. It will help them lay a strong foundation towards pursuing a career in the world of digital video creation and design.</p><p>Course Navigation</p><p>Select a Student</p><p>In this Course Navigation, we’ll go over the overall course structure and what you can expect in each of the modules in this course.</p><p>Before You Begin</p><p>Before we go over the navigation and structure of the course, here are a few important things you should do:</p><p>Make sure you have Adobe Premiere Pro open on your computer when you start the course.&#160;You can follow along with the reading material and instructional videos and explore Premiere Pro as you learn about it.</p><p>Make sure you have Office suite programs or basic word processing programs installed on your computer, as you will require them for your project work.</p><p>Navigating the Course</p><p>Within each section, you can easily navigate between the pages either with the menu on the left or with the left/right arrows on the bottom.&#160;This allows you to move between PAGES within each section.&#160;Once you are done with all the pages in a section, you can either click at the top on the title of the course, or you can click at the very bottom of the page to the next section.&#160;It’s very important to make sure you finish every page in a section BEFORE moving to the next section.</p><p>(opens in a new tab)</p><p>This image shows a typical course page with navigation bars on the left side as well as the bottom.&#160;The course number, title, and content will vary from course to course.</p><p>License:&#160;All Rights Reserved</p><p>Course &amp; Module Structure</p><p>The course is divided into 7 modules, with an initial introductory module that you are now taking.&#160;This introductory module is intended to make you familiar with the course structure and explain some basic but important concepts about sources, plagiarism as well as the syllabus of this course.</p><p>Each module of the course will be structured as shown in the diagram here.</p><p>Each module has an introduction, 4-5 lessons, and a summary and quiz at the end of the module.&#160;We begin each module with an introductory video into the topics that will be covered in that module.&#160;You can use the video controls to adjust the volume, captions, and speed of the video based on your preferences.</p><p>Each lesson of the module will cover a different topic for that module.&#160;Lessons contain multiple pages of content that comprise of instructional content as well as instructional videos.&#160;Follow along and explore Premiere Pro yourself as you learn about its features and tools in each lesson.</p><p>As you will learn in the syllabus, the introduction, video, and reading pages are graded on participation, meaning you get credit for going through every page and activity in the module.</p><p>After each lesson is a concept check or reflection where you&#39;ll either input an answer or work with flashcards or maybe a sorting exercise to review and firm up the concepts that were taught in that section.&#160;The reflections are either journal entries or discussion prompts.&#160;To participate in a class-wide discussion, you’ll click on a link to read the questions or prompts, and then participate in the discussion by adding a new discussion topic and eventually commenting on posts from other students.&#160;You&#39;ll see this repeat itself through all the sections.</p><p>Every module ends with a module summary.&#160;Once you are finished with each lesson, you will need to complete a project and a quiz.</p><p>The project gives you a chance to practice what you learned in that module in Premiere Pro.&#160;Every module will have a different project and will give you a chance to be creative, explore all the tools yourself, and learn by doing.</p><p>Finally, the module quiz is pretty straightforward as they are mostly multiple-choice and true/false questions.</p><p>Many aspects of grading or other features of the course may be changed by your individual schools and instructors.&#160;So please refer to the updated instructions or grading procedures that they provide.</p><p>For additional help, you can reach out to your instructor or contact the help desk of your LMS.</p><p>Course Objectives</p><p>Select a Student</p><p>In this course, students will:</p><p>Understand critical concepts related to working with colleagues and clients as well as crucial legal, technical, and design-related knowledge.</p><p>Navigate the interface and program settings that assist in an efficient and effective workflow.</p><p>Demonstrate the ability to ingest digital assets for a project.</p><p>Organize the structure of video projects using layers, tracks, and assets for efficient workflow.</p><p>Use core tools and features of the application, as well as tools that affect the sequences within the project.</p><p>Publish and export video and audio sequences in multiple formats for various publishing platforms.</p><p>Sources and Plagiarism</p><p>Select a Student</p><p>Sources and Bias</p><p>Throughout this course, you will be asked to write reports or complete assignments.&#160;You may also be asked to research content from external sources, such as news articles and videos.</p><p>As a student, you will be required to research assignments using credible sources.&#160;But how can you tell if a source really is &quot;credible&quot;?&#160;A credible source is one that is factually correct and trustworthy and is considered to have a good level of expertise in the field.&#16<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('7f7747d9a87665908071d898f36c06f6','adobe-premiere-pro-module-1','48ab1932af65ef3f9d0793cd5a02da34','Module 1: Video Industry Part 1',1) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('d0d2328e802ce17507ea16026ece725f','adobe-premiere-pro-m1-l1-introduction-purpose-and-objectives','7f7747d9a87665908071d898f36c06f6','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Select a StudentCTEdemo_premiereproMatthew Barber</p><p>-02:15</p><p>Mute</p><p>Hi, I’m Mr. Southwick and I’ll be one of your instructors for this course on Adobe Premiere Pro. This is the intro video for Working in the Video Industry Part 1. You’ll see me introducing each module in this course, providing an overview of the topics you’ll cover in each one. Throughout the course, you’ll have a variety of ways to learn the material. There will be readings, videos, screenshot tutorials, images, and much more. But our ultimate goals are two-fold. First, so that you learn how to use Premiere Pro. And second, so that you are best prepared to take (and pass!) the Adobe Certification exam on Premiere Pro.</p><p>As with most things in life, we learn best by doing, and something like Premiere Pro is no exception. So, as you are going through the course, I’d encourage you to have Premiere Pro up and running on your computer. Follow along, try things for yourself, and experiment! It’s ok and even encouraged to make mistakes. One because that’s how we learn, and two, there’s always the ability to undo an action!</p><p>Premiere Pro is a complex program and can be overwhelming for someone who is brand new to it. But we’ll be walking through it slowly, step by step, to get you comfortable with all the key features of this software. And occassionally in the course, I’ll take you through some screenshot tutorials of Premiere Pro.</p><p>Premiere Pro is an industry-standard, used by everyone from beginners to professionals to create, edit, and design high-quality videos. Don’t let the fact that Premiere Pro is used by professional videographers intimidate you! It is extremely user-friendly, and with our detailed tutorials, you will be able to do everything from simple video edits, to incorporating graphics and texts into your videos, applying cool effects and transitions, and designing professional-grade videos!</p><p>In this module, you’ll get an insight into the video design industry and how Premiere Pro fits into it. You’ll get an understanding of the real-world processes that take place in video design, and the processes and standards you need to have in place before you start using Premier Pro.</p><p>Legal and ethical considerations also come into the picture when you need to ask yourself questions like, “Is it okay for me to record in public?” or “Can I reuse footage or clips from other sources like someone else’s videos or movies?” You’ll learn about all this and more in this introduction to the video industry.</p><p>Module Description</p><p>Select a StudentCTEdemo_premiereproMatthew Barber</p><p>by Shutterstock</p><p>License:&#160;All Rights Reserved</p><p>Working in the video design industry is more than just knowing how to use video editing tools.&#160;There are crucial design, legal, and technical aspects that you must take into consideration when you work on any design project.&#160;Another key factor is how you work with colleagues and clients, and how well you are able to communicate your ideas and design visions.&#160;In this module, students will learn critical skills to recognize what their audience needs, and how to communicate with colleagues and clients about design plans.&#160;They will also learn the legal ramifications of copyright, permissions, and licensing when using digital&#160;content.</p><p>Objectives</p><p>Select a StudentCTEdemo_premiereproMatthew Barber</p><p>In this module, students will:</p><p>Identify the purpose, audience, and audience needs for preparing images and determine whether the content is relevant to the purpose, audience, and audience needs.</p><p>Communicate with colleagues and clients about design plans demonstrating knowledge of techniques for communicating about design plans with peers and clients.</p><p>Demonstrate knowledge of basic project management concepts.</p><p>Determine the type of copyright, permissions, and licensing required to use specific content identifying legal and ethical considerations for using third-party content, such as copyright, permissions, and licensing.</p><p>Polling Question</p><p>Select a StudentCTEdemo_premiereproMatthew Barber</p><p>Which of these aspects of working in digital video design and development are you most intimidated about?</p><p>Working with clients and colleagues</p><p>Coming up with creative design ideas</p><p>Editing videos&#160;Managing projects and time</p><p>Obtaining permissions to use copyright and licensed content</p><p>Results:</p><p>Obtaining permissions to use copyright and licensed content&#160;100%</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9b71eba791a79cd23ae3a3c5b7c98ed9','adobe-premiere-pro-m1-l2-lesson-1','7f7747d9a87665908071d898f36c06f6','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Gathering Information</h3><p>Gathering Information</p><p>You can create videos for school projects, for television or news broadcasts, for films, movies, or documentaries, or even just for plain fun.&#160;Whatever the purpose, the first step is to have a clear understanding of the purpose of the video you are creating and the audience for the video.</p><p>Unlike many other fields where client requirements are clear and measurable directives, working in the video industry can be much more challenging.&#160;There are a number of key factors you need to keep in mind to ensure a smooth, productive, and long-lasting business relationship with your clients.</p><p>Asking the Right Questions:</p><p>Any new project starts with understanding what the client wants.&#160;Make it a point to understand what the client’s goals are and what they hope to achieve with the video you are creating.&#160;The same principle applies if you are creating a video for other purposes like for social media or a school project.</p><p>Make sure you ask the right questions to get the information you need.&#160;Here are some examples.</p><p>Click the hotspots on the image to learn more.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Image of a person thinking</p><p>The hotspot points on the image are as follows:</p><p>Question 1</p><p>What is the subject of the video?</p><p>Question 4</p><p>What is the goal of your video – for example, your approach will differ if you are shooting an instructional video versus a video for an advertisement.</p><p>Question 2</p><p>What time of day do you need to shoot the video?</p><p>Question 3</p><p>What type of equipment will you require?</p><p>Listen to what your client has to say and ask questions to refine the information they are giving you.&#160;Make sure you take notes while in discussion with the client so you can also note down any follow-up questions that you may have.&#160;Make a note of examples or recommendations made by the client.</p><p>byPressmaster</p><p>License:&#160;All Rights Reserved</p><p>Understand the Audience:</p><p>When you work on a project, your client isn’t only the person who gave you the project, your client is also the end-user of your designs, the audience!&#160;Any designs that you create must take your target audience into consideration.&#160;In the next few modules, you will begin to learn about all the different editing techniques you can use as well as different transitions and effects that you can apply.&#160;When you begin to practice these techniques, try to think of videos or movies that you have seen that have caught your eye.&#160;What made them memorable?&#160;Try to notice the different ways in which the video was edited and what different techniques were applied, and what made it appealing to you as a consumer of that video.</p><p>Consider the target audience factors like:</p><p>Age group</p><p>Educational background</p><p>Geographical location</p><p>Cultural aspects</p><p>Technical expertise</p><p>Consider this scenario.&#160;Let’s say that you are a fitnessYouTuber creating workout videos for people who are beginners and are just starting out on their fitness journey to a healthier lifestyle.&#160;What things do you think you will need to keep in mind before you start creating your videos?&#160;Here is how you can understand your audience:</p><p>Research and define your target audience:&#160;You may find that your audience consists predominantly of individuals who are between 30-45 years old and who want to improve their health and get fit.&#160;Most people in this age group have jobs and families and may have limited time during the week to devote to exercise.&#160;This could be a key consideration when you decide the length of your videos or even how many videos you create each week.</p><p>Identify audience goals and needs:&#160;What are the goals your audience wants to achieve by watching your videos?&#160;They may want to get in better shape, lose weight, and learn about healthy eating and exercise habits.</p><p>Conduct surveys:&#160;Now that you have a description of your target audience, you can survey people who fall into this category and ask them about their preferred forms of exercise, the difficulties or challenges they encounter, and the kinds of workout information they value the most.</p><p>By understanding your audience, you can tailor your video content to meet their needs effectively.&#160;To keep viewers interested throughout their fitness journey, you may create beginner-friendly workout videos with variations for different fitness levels.&#160;You may also provide guidance on healthy eating for weight loss, and include motivational elements to keep viewers engaged throughout their fitness journey.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('965326b2b5dc37c3a811cd01ac87aceb','adobe-premiere-pro-m1-l3-lesson-2','7f7747d9a87665908071d898f36c06f6','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Communication with Clients and Peers</h3><p>Communication with Clients and Peers</p><p>When you watch a 5-minute YouTube video, you rarely think about all of the efforts that have gone into creating, editing, and producing that video.&#160;Video production is usually a team effort, with multiple players each with their own essential roles.&#160;It is essential for all members of this team to have open communication and work together to achieve their collective goals.&#160;Constructive feedback and peer reviews help bring out different perspectives and suggestions to develop a great video.</p><p>There are three key stages in the video production process:</p><p>Click each card to learn more.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>&#171; Back</p><p>Pre-production</p><p>Pre-productionThis stage involves the design, planning, and communication</p><p>Production</p><p>ProductionThis is the stage when the video is captured</p><p>Post-production</p><p>Post-productionThis is the final stage when all the elements are put together.&#160;This is where you will use Premiere Pro to edit the video, add transitions, music, and other effects.</p><p>⟳ Flip Card</p><p>Next &#187;</p><p>Flashcard&#160;1&#160;of&#160;3</p><p>Flashcard Transcript</p><p>Pre-production:&#160;This stage involves the design, planning, and communication</p><p>Production:&#160;This is the stage when the video is captured</p><p>Post-production:&#160;This is the final stage when all the elements are put together. This is where you will use Premiere Pro to edit the video, add transitions, music, and other effects.</p><p>Let’s discuss the pre-production stage – this stage is all about preparation and groundwork.&#160;In the first stage, you will design and outline the approach and plan for your video.&#160;This critical stage sets the tone for your entire video project, so it is often the longest stage in the process.</p><p>There are many key steps in the pre-production stage, and these can vary based on the type of project, its complexity, and other factors.&#160;Broadly speaking, the pre-production stage includes:</p><p>Click each term to learn more.</p><p>Video Goal and Strategy</p><p>What are you hoping to achieve with your video? Think about the audience of the video and what objective you are hoping to meet. This information will help you formulate a strategy that will help you achieve that goal.</p><p>Production Brief</p><p>A production brief is a document that summarizes what you want to achieve from the video. Based on the complexity of the video project, this may include information about the video objectives, audience, any message that you want to convey, and also information like your budget and timeline.</p><p>Creative Approach</p><p>This is where you will conceptualize the video. You and your team will discuss what your creative strategy will be and what should be included in the video. This step is a great opportunity for collaborative thinking and teamwork.</p><p>Video Script &amp; Storyboard</p><p>Next, it is time to put down your creative approach in the form of a video script. Try to visualize the video as you write the script. Pay attention to the tone of the video and the different people who will be in the video. It may help to rehearse the video script with your team to ensure you are being concise and the video follows a comfortable pace.</p><p>A storyboard is a visual representation of a video based on the script. This will help you visualize how the video will be shot. It also helps in planning where you want to apply different effects, where you may want to use close-up shots, what type of lighting you will require, etc.</p><p>Casting, Location Scouting, and Scheduling</p><p>Once again depending on the complexity of your video project, you will need to search for locations to shoot the video, audition people who will be cast in the video, as well as think of timelines and scheduling.</p><p>Consider the following scenario.&#160;Let’s say that you are creating a promotional video for a new smartphone.&#160;Now let’s break down the pre-production steps that you will take:</p><p>Your main objective is to highlight the key features of the smartphone and target tech-savvy consumers.</p><p>You will then write a script that outlines the scenes, dialogue, voiceover, and any necessary visual cues for the video.</p><p>You will create a shot list and storyboard to visualize the scenes and plan the camera angles, movements, and transitions.</p><p>To create the video, you may need a studio setup, actors or models showcasing the smartphone, and props related to technology and lifestyle.</p><p>Throughout all these stages, it is essential to keep track of client feedback and map it to their initial requirements.&#160;Are you still in line with what the client wants?&#160;Has the client strayed from what they wanted and are going in a different direction?&#160;What impact does that have on the effort or complexity of the project?&#160;These are all essential questions you need to ask at every stage.&#160;As always, keep an open channel of communication with your team and clients about all of these factors.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6810fa6a3fc43bda0fd5b2b955ad530a','adobe-premiere-pro-m1-l4-lesson-3','7f7747d9a87665908071d898f36c06f6','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Project Management</h3><p>Project Management</p><p>The next two stages of video development will require good project management skills and team coordination.&#160;project management is going to be an essential part of working in the design industry.&#160;You may be the best designer with the most creative ideas, but if you are unable to meet deadlines, manage your clients, or communicate effectively with your team, you will not be successful.&#160;The main goal of project management is to be organized at every stage of the project.&#160;Let’s take a look at each stage:</p><p>Click each tab to learn more about each stage.</p><p>Next Tab</p><p>Video Production</p><p>This is where the magic happens!&#160;In this stage, you implement all the plans created in the pre-production stage and record the video.&#160;Project management is key at this stage because you must ensure you stick to your schedule and budget limits.&#160;While shooting the video, make sure you have extra b-roll footage that you can use while editing the final video.</p><p>Post-Production</p><p>In the final stage, you will use all of the skills that you will learn in this course to import and edit all of the raw footage to create your final video. Your initial storyboard is very useful at this stage, as you can refer to your vision for the video and sift through all of your footage to clip and edit what you require.</p><p>Next, depending on the requirements for your video, you will need to record a voiceover and synchronize it with your video. You may also want to use background music or audio effects to enhance the video. Other enhancements you can make include adding effects, text slides, transitions, or even animations.</p><p>Another key part of the post-production stage is&#160;color correction. This is done to ensure the entire video looks cohesive and is in line with any branding guidelines or pre-defined color palettes you need to follow.</p><p>Key Project Management Skills</p><p>Some of the key components of project management are planning, time management, clear and open communication, and maintaining a professional attitude.&#160;These skills will help you immensely as you work through these two stages of video production.</p><p>For example, let’s say that you are creating a corporate training video.&#160;In this situation, you will need to collaborate with the client and production team to determine the training objectives, target audience, key messages, and intended outcomes of the training.</p><p>License:&#160;All Rights Reserved</p><p>Planning:</p><p>Start off your design process by charting out a project plan.&#160;You’ve already learned how to understand your client requirements in the last few lessons.&#160;Your project plan should take into account&#160;what&#160;needs to be done,&#160;how&#160;it needs to be done,&#160;by&#160;when&#160;it needs to be done, and&#160;who&#160;you will be working with.</p><p>Within your project plan, create timelines and milestones for specific tasks along with due dates.&#160;You should also be aware of what the review process will be with the client.</p><p>If you are working with a team on a project, make sure everyone has individually assigned tasks and that they follow up on their own responsibilities.</p><p>License:&#160;All Rights Reserved</p><p>Time management:</p><p>This is an essential step no matter what you do, whether you are in school or a working professional.&#160;As you gain experience in the design industry, you will be able to gauge how much time different tasks take.&#160;Allocate time for each task in your project plan and stick to a schedule.&#160;Make a note of all deadlines that have been met, and also those that haven’t been met so that you can plan for unforeseen delays.</p><p>So how would you use time management during video production?&#160;For effective time management, you will discuss with the client and create a production schedule to ensure that the different tasks, such as scriptwriting, model casting, location scouting, and equipment setup, are completed on time.&#160;During post-production, time management helps organize the editing process and create deadlines for various members on your team who may be working on the project.</p><p>License:&#160;All Rights Reserved</p><p>Communication:</p><p>Another essential part of project management is to always have open, clear communication with your team and clients.&#160;When working with a team, make it a practice to give each other constructive feedback.&#160;Instead of “I don’t like it,” say something like “Have you considered using a more colorful background?”</p><p>Along with giving feedback, it is also essential that you be open to feedback from others.&#160;Your listening skills play a big role in having good communication skills.</p><p>When communicating with clients, it is important to remember that the client is not always right.&#160;Just because they said so is not always a reason to change the design.&#160;You are the design expert in this situation, so make sure that you consider the requirements of the project, client, and audience and decide if the client’s feedback improves the design of the project.&#160;If a client makes a suggestion that seems to be going away from the direction of the project, bring that to light in a professional manner.&#160;For example, “That’s a great idea, but I think our audience may not relate to it.&#160;I think it would have more of an impact if we…”</p><p>For clear and open communication, set up regular meetings with the client and other key stakeholders to discuss progress and updates, address any concerns, and provide feedback on creative decisions.&#160;This will help you understand if you are meeting the training objectives and expectations.&#160;&#160;Keeping a professional attitude also helps establish credibility, builds strong client relationships, and contributes to the project&#39;s overall success.</p><p>Once you begin to incorporate these basic project management principles into your work process, you will find that rather than it being another thing added to your plate, it will greatly ease and enhance your creative process.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('328b580a845f722f6c52a8d8733e33c3','adobe-premiere-pro-m1-l5-lesson-4','7f7747d9a87665908071d898f36c06f6','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Copyright and Licensing</h3><p>Copyright and Licensing</p><p>License:&#160;All Rights Reserved</p><p>When you work in a creative industry, it&#39;s easy for the line between ‘inspiration’ and ‘copying’ to get blurred.&#160;As designers, you should be the first to understand the importance of giving credit where credit is due.&#160;It is your responsibility as creatives to ensure that you are aware of where the content you are using is sourced from, whether it is a quote, an article, photos, artwork, music, or even icons and logos.&#160;There are serious legal and ethical considerations and ramifications of using content created by someone else.</p><p>There are many different types of copyright, permissions, and licensing options available, and you need to be aware of what can be used where.&#160;Here are some of the principal rules of copyright you should be aware of:</p><p>Click each term to learn more.</p><p>Academic standards</p><p>Academic standards&#160;for copyrighted material are higher than others. Researchers and scholars are considered experts in their fields and have a greater responsibility for sharing their opinions and ideas with the world. Because of this, they are held to higher standards of honesty and must give credit for all their research, including when they quote someone else’s words or even if they paraphrase those quotes in their own words. As a researcher, even if you paraphrase what someone else says, you still need to give them credit for it.</p><p>Copyright</p><p>Copyright is a form of&#160;legal protection for original works of authorship, whether unpublished or published, that is&#160;tangible and/or perceptible.</p><p>Copyright requires that anyone who wants to use an asset created by someone else must first obtain their permission to modify, copy, share, or edit the asset. This applies to almost everything that you may find on the internet, like results in an image search, online articles, videos, artwork, music, and other similar assets.</p><p>Many designers and artists would be okay with you copying or editing their work as long as you credit them in your work. When in doubt, always reach out to the owner of the work and ask for permission.</p><p>You can pay a &quot;licensing fee&quot; to use these assets under certain specified conditions, including but not limited to, number of uses, method of use, permission to edit or modify the asset, etc.</p><p>Public Domain</p><p>While it is good to be cautious and assume that everything you search for is protected by copyright, there are still some exceptions, such as assets that fall under the&#160;public domain.</p><p>Under US law, some items automatically become available under public domain after a certain number of years. But how will you know if an image or video is free for use under public domain? Just add the correct keywords in your search, or filter your search results using the different use cases provided.</p><p>Creative Commons</p><p>A&#160;Creative Commons&#160;license is one of many public copyright licenses that allow the free distribution of “work” that is otherwise copyrighted. Creators use CC licenses when they want to give other people the right to freely share, use, modify, and build upon a work that they have created, in a bid to expand the range of creative works available to the public.</p><p>Derivative works</p><p>Derivative works&#160;are copyrighted materials that have been altered or changed. These materials are also protected by copyright laws. Let’s say you use Photoshop to make changes to a copyrighted photo. That photo is still protected by copyright laws and you may not use it without written permission.</p><p>Fair use doctrine</p><p>Fair use doctrine&#160;is part of the copyright laws and states that small portions of materials can be used without explicit written permission of the creator for certain purposes, like news reporting or schoolwork. This doctrine doesn’t clearly define what “limited” means, so be careful of overusing material. This doctrine also requires that you must give credit to the creator of the material that you are using.</p><p>Factors that determine fair use include:</p><p>Amount:&#160;You can only use a small amount of the asset in your work. For example, you can use a small clip of a song, but you cannot copy or modify the entire song.</p><p>Purpose:&#160;You must use the asset to create something new or for a new purpose.</p><p>Nature:&#160;Fair use applies more in situations where the work or asset is based on non-fiction or based in fact.</p><p>Effect:&#160;Whatever you do with the asset should not negatively impact the original creator. This includes making monetary benefits off someone else&#39;s work.</p><p>As you can see, a lot of this can be quite subjective. Some situations where it can apply include if you are using content for school or academic work, for reporting news, or to create parodies or comedy content.</p><p>Intellectual property</p><p>Intellectual property&#160;is anything that a person has written or created. This can include artwork, text, photos, music, sounds, and so on.</p><p>Royalty Free</p><p>Royalty free&#160;assets are not &#39;free&#39; assets. They are copyrighted assets that you can purchase once and then use as many times as you want without the need to pay royalties or license fees for each “use”.</p><p>Ethical Considerations</p><p>As the saying goes, do unto others as you would have them do unto you. How would you feel if someone were to use something you created without your permission? For example, if you post your artwork online, and someone else copies it, modifies it slightly, and starts to sell the artwork as their own. That&#39;s not fair, right?</p><p>Always give credit where credit is due.</p><p>Imagine that you are shooting a promotional video for a new product launch.&#160;The video requires background music, stock footage, and images.&#160;Where would you source these assets from?</p><p>Music:&#160;Wherever you choose to use music from, you must make sure that you do not use copyrighted music without permission.&#160;Just because it is available on the Internet does not mean that it is free to use as you choose.&#160;It is always best practice to contact the copyright holder and obtain a license or permission to use the music.&#160;You can also use a music licensing platform that offers a specific license for commercial use.</p><p>Videos:&#160;Apart from any video footage that you have<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0ef349ab638f84754bb646cd23ec457f','adobe-premiere-pro-m1-l6-lesson-5','7f7747d9a87665908071d898f36c06f6','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Release Forms</h3><p>Release Forms</p><p>License:&#160;All Rights Reserved</p><p>Just as you have copyright laws for using content created by other individuals, there are also rules in place that determine what you can and cannot take photos of and use commercially.</p><p>Legally, it is completely fine for you to videotape or photograph anything and everyone on public property within reasonable community standards.&#160;You do not need permission to take photographs in these situations.&#160;You can even sell these pictures, as many photographers do, to stock websites, products or media companies, etc.</p><p>Permissions come into the picture when you, or the buyer, choose to publish the photograph.</p><p>Model Release</p><p>A model release is a legal release signed by the subject of a photograph or video giving you permission to publish the photo or video in one form or another.</p><p>For example, let’s say that you are shooting an advertisement for a greeting card company.&#160;You go to your local park and find that there is a wedding going on.&#160;You take a video of the bride and groom walking down the aisle, and the wedding party, and you use to incorporate it into your advertisement.&#160;In this situation, is it okay for you to use the video of the wedding without their permission?&#160;Since this was a private event, you must get a Model Release and permission from all the people at the wedding in order to be able to use the footage to create a commercial video.&#160;This model release will provide legal permission from the people being recorded to use their images/footage in the advertising campaign and related promotional materials.</p><p>Click here to download a sample model release form.(opens in a new tab)</p><p>Location Release</p><p>A location release is a legal release signed by the owner or owners of a private property where you took photographs or videos, giving you permission to publish the photo or video in one form or another.</p><p>Let’s say that a film production company is planning to shoot a historical movie that is set in the 18th&#160;century.&#160;You have identified an old castle that can be used as a location in the movie.&#160;This castle is privately owned.&#160;A location release would be necessary for this scenario.&#160;The castle&#39;s owners will grant authorization through a location release for the property to be used as a shooting location.</p><p>As a photographer, it is not essential for you to get the model or location release for photographs you take unless you plan on publishing them yourself.&#160;But most professional photographers get the release forms signed because of the convenience.&#160;It gives them better chances of selling the photograph to a buyer who wants to publish the photo without the hassle of having to find the people or locations in the photo and get releases signed after the fact.</p><p>Click here to download a sample location release form.</p></section><section><h3>model-release-form</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>location-recording-permission-form</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0b54a543e6e38230812df2080bd47eea','adobe-premiere-pro-m1-l7-module-1-summary','7f7747d9a87665908071d898f36c06f6','Module 1 Summary','text',12,'<h2>Module 1 Summary</h2><section><h3>Module 1 Summary</h3><p>Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on&#160;Working in the Video Industry Part I!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified the purpose, audience, and audience needs for preparing images and learned to determine whether the content is relevant to the purpose, audience, and audience needs.</p><p>Learned to communicate with colleagues and clients about design plans.</p><p>Demonstrated knowledge of basic project management concepts.</p><p>Understood the legal and ethical considerations for using third-party content, such as copyright, permissions, and licensing.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a2a03af98d703f7609db134066a048b9','adobe-premiere-pro-m1-l8-module-1-project','7f7747d9a87665908071d898f36c06f6','Module 1 Project','text',12,'<h2>Module 1 Project</h2><section><h3>Adobe Premiere Pro</h3><p>Adobe Premiere Pro</p><p>8100</p><p>Working in the Video Industry Part I - Project</p><p>Project</p><p>For this assignment, you will interview a member of the video design community to gain their perspective on creating videos.</p><p>Find an interviewee who is working as a videographer or develops videos, and who agrees to participate in the assignment.</p><p>The interview can be conducted in person, on the phone, virtually, or via email. Prepare at least eight questions that cover topics from this module, such as:</p><p>Client communication and understanding your audience</p><p>Importance of storyboarding and storytelling</p><p>Importance of collaboration and working with teams</p><p>Project management</p><p>Meeting clients&#39; expectations and project requirements while balancing creativity</p><p>Copyright and permissionsSave(opens in a new tab)</p><p>Be ready to ask follow-up questions, as needed, to prompt a more in-depth discussion by the interviewee.</p><p>Your paper should be double-spaced and include:</p><p>Name of the person interviewed, and date and style of the interview (virtual, face to face, etc.)</p><p>A list of the questions that were asked, followed by the interviewee’s answers.</p><p>A conclusion section (2 – 3 paragraphs in length) comparing what you learned from the interview and the concepts explored in this module.</p><p>Review the rubric below to see how you will be graded.</p><p>Working in the Video Industry Part I</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Interview Questions</p><p>8 points Interview questions are well designed to gain insight and perspective from the interviewee. Follow-up questions are used to effectively explore a topic further.</p><p>7-6 points Interview questions are adequately designed to gain some insight and perspective from the interviewee. Follow-up questions are used somewhat effectively to explore a topic further.</p><p>5-0 points Interview questions are poorly designed and unable to gain much insight and perspective from the interviewee. Follow-up questions are not used where needed.</p><p>8</p><p>Conclusion Paragraphs</p><p>8 points Includes in depth comparisons between the interview and course content, references specific details as evidence to support the comparisons made, and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete comparisons between the interview and course content, references some details as evidence to support the comparisons made, and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no relevant comparisons between the interview and course content, references no details as evidence to support the comparisons made, or does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Includes the required content and is formatted neatly.</p><p>1 point Does not include all required content or is not formatted neatly.</p><p>0 points Does not include all required content and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2c823eeb6db1129f07f92defc6363103','adobe-premiere-pro-m1-l9-module-1-quiz','7f7747d9a87665908071d898f36c06f6','Module 1 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Video Industry Part 1. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('df65de5e2ca0c32742a4d36f2852562f','adobe-premiere-pro-module-2','48ab1932af65ef3f9d0793cd5a02da34','Module 2: Video Industry Part 2',2) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b694b2d5992045e40c795fb5b21afcf3','adobe-premiere-pro-m2-l1-introduction-purpose-and-objectives','df65de5e2ca0c32742a4d36f2852562f','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi everyone, and welcome back! This is the intro video for Working in the Video Industry, Part 2. In the last module, you took a step into the world of video design and Adobe Premiere Pro. You learned about some critical aspects of working in the design world, both with teams and with clients. We also briefly discussed the three key stages of video production and what happens in each stage. And we covered some important information about copyright permissions and licensing that you should always keep in mind.</p><p>Before you can learn about using Premiere Pro, you’ll need to be familiar with some of the common terminology used in the video industry. We’ll give you an introduction to basic design principles and best practices used in the video industry. To get the most out of Premiere Pro, you need to start thinking like a videographer. What is the best way to frame a shot? What are the different video techniques you can use and when? What is the importance of cinematic composition?</p><p>These are all questions that we’ll explore together in this module. Let’s get started!</p><p>Before you dive into Premiere Pro, you need to have a strong base knowledge of design principles and video techniques.&#160;In this module, students will be introduced to digital video terminology.&#160;They will learn about the basic building blocks of video production like color and white balance, video formats and audio settings.&#160;They will also be introduced to fundamental design principles and techniques that will be very valuable as they progress in this course.</p><p>Objectives</p><p>In this module, students will:</p><p>Demonstrate knowledge of key terminology related to digital audio, digital video, and video/audio production.</p><p>Demonstrate knowledge of how color is managed in digital video.</p><p>Communicate visually using design principles and standard film/video techniques.</p><p>Identify general design principles and guidelines for editing video.</p><p>Define common photographic and cinematic composition terms and principles and give examples of when and why to use types of shots.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5f289e93d478d23c1e8fd9e8637d9d88','adobe-premiere-pro-m2-l2-lesson-1','df65de5e2ca0c32742a4d36f2852562f','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Digital Video Terminology</h3><p>Digital Video Terminology</p><p>Before we begin, let’s take a look at some common digital video terminology and concepts that you will need to understand and use throughout this course.</p><p>Pixels&#160;are the most basic building blocks of digital images and videos.&#160;Just like paintings or drawings are made up of brush or pen strokes, videos are made up of hundreds or thousands of pixels.&#160;Each pixel is just a block of color, and a digital video is made up of numerous frames, each of which is a grid of pixels.</p><p>One important thing to remember is that a single pixel doesn’t have a fixed size unlike other units of measurement.&#160;The size of a pixel depends completely on the resolution of an image.&#160;Confused?&#160;Don’t worry, we’ll explain this in detail very soon.</p><p>The size of an image or video is defined in terms of&#160;pixel dimensions.&#160;This is basically a count of the total number of pixels in an image or frame of a video.&#160;In a digital format, images and videos are measured in terms of their pixel dimension.&#160;If you look at the specifications on your camera or phone camera, you will see that it may be a 5MP or 8MP camera.&#160;“MP” here refers to “mega pixels”, which is basically “a million pixels”.&#160;So, a 5MP camera will take pictures and videos that contain 5 million pixels (approximately).</p><p>When you talk about the size of videos, you will usually define the resolution of the individual frames of the video.&#160;The&#160;resolution&#160;is a measurement of the pixels per inch of a frame.</p><p>License:&#160;All Rights Reserved</p><p>But what is the&#160;aspect ratio&#160;of a video?&#160;Is it the same as the resolution?&#160;Not quite.&#160;The aspect ratio of a video is the ratio of the width of a video to the height of a video.&#160;Some common aspect ratios you may have seen are 4:3 and 16:9, or even 1:1 as you may have seen used in Instagram videos.</p><p>A video with a 16:9 aspect ratio is often referred to as widescreen or HD (high definition).&#160;It is commonly used in modern TVs, computer monitors, and online video platforms like YouTube.&#160;A video with a 4:3 aspect ratio is known as the standard or SD (standard definition) format.&#160;This aspect ratio was frequently used in the past for analog TVs and older video programs.</p><p>Another term used when describing videos is their&#160;frame rate.&#160;The frame rate of a video is the rate at which each frame of a video is recorded.&#160;In terms of your camera, it is the rate at which the camera shutter opens and closes or the rate at which the camera sensor captures frames of the video you are recording.&#160;You will often see a video’s playback speed defined in terms of&#160;frames per second or fps.&#160;Common frame rates for videos are 24, 25, 29.97, 30, and 50 fps.</p><p>When you watch a movie in a theater or on a Blu-ray disc, it&#39;s likely that it will be shown at 24 fps.&#160;Many TV programs, vlogs, and online videos are created and broadcast at a rate of 30 fps.&#160;A video game may run at 60 fps when you play it on a gaming PC to provide a more immersive and responsive experience.</p><p>Now, let’s talk about&#160;video formats.&#160;There are many different types of video formats, but which one should you use, and does it really make a difference?&#160;Broadly speaking, video formats are what determine the size of your video file.&#160;Unlike an image, a video is made up of multiple components – the video part, any audio integrated into the video, captions, any graphical or animation elements, and codecs that are used to compress and decompress the video.&#160;Some examples of video formats are .mp4, .mov, .avi, .wmv, etc.</p><p>Videos uploaded to YouTube are often in the MP4 format.&#160;On iPhones, videos are often saved in the MOV format.&#160;There are some older films and videos that were recorded in AVI format using early digital cameras.&#160;WMV format may be used by some videos that are hosted on Microsoft websites or older versions of Windows Media Player.</p></section><section><h3>Key Video and Audio Terms</h3><p>Key Terms Related to Video and Audio Production</p><p>Audio is a key component of videos.&#160;Here are some key terms related to audio production.</p><p>Click each term to learn more.</p><p>Sampling rate</p><p>Clipping</p><p>Levels</p><p>Natural/ambient sound</p><p>Room tone</p><p>Foley sound</p><p>Flashcard Transcript</p><p>Sampling rate:&#160;This is the rate at which sound is measured during recording. The higher the sampling rate, the higher the quality of the recorded audio. This also increases the size of the audio file.</p><p>Clipping:&#160;This is a distortion in the audio that occurs when a speaker or amplifier is overloaded, and the audio waveform is “clipped”. The general objective is to always avoid audio clipping.</p><p>Levels:&#160;Audio levels are measured in decibels.</p><p>Natural/ambient sound:&#160;This is the background audio that is recorded when you record audio or videos at an outdoor location. For example, the wind, the sound of birds, people talking in the background, traffic, etc.</p><p>Room tone:&#160;In filmmaking, the room tone is basically the silence that is recorded between dialogues. Think of room tone as the opposite of ambient noise.</p><p>Foley sound:&#160;Foley sounds are sound effect that are added during post-production in videos. For example, sounds added during a fight scene in movies, or other sound effects added like footsteps, chewing, the sound of keys or coins, etc.</p><p>Microphones:</p><p>Depending on the type of video project you are working on, the type of microphone you use will vary.&#160;For example:</p><p>Click each card to view the definitions.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>&#171; Back</p><p>Shotgun microphones</p><p>Shotgun microphonesThese are used when you want precision recording without being affected by ambient noise interference.</p><p>Handheld microphones</p><p>Handheld microphonesAs the name suggests, these are microphones that are easy to use on the go, such as those used by TV presenters and news reporters.</p><p>Lapel microphones</p><p>Lapel microphonesThese are small microphones that are pinned to a person’s tie or clothing.&#160;You will see these microphones often being used in interviews.</p><p<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('510395772011872fad111dc1b57dd9e9','adobe-premiere-pro-m2-l3-lesson-2','df65de5e2ca0c32742a4d36f2852562f','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Color in Digital Videos</h3><p>Color in Digital Videos</p><p>Colors are a very important component of videos.&#160;You can use a color theme to create consistency throughout the video, or you can use a specific color to highlight or enhance specific portions of your video, the options are limitless.</p><p>Color grading&#160;is an important part of the video development and editing process.&#160;It is a process used to modify or enhance the colors in the video to enhance it.&#160;There are many different color grading tools that you can use to edit the colors in your video.&#160;Here are just a few:</p><p>Contrast and brightness:</p><p>All video editing tools have these basic settings that allow you to adjust the contrast and brightness of your image or video.&#160;Adjusting the brightness modifies the amount of light in the colors of the video.&#160;Color contrast refers to the difference in light between something in the foreground and background of a video.</p><p>White balance:</p><p>This setting measures the color temperature in the image.&#160;You can adjust the white balance of an image to make the image warmer or cooler.&#160;This setting is used to ensure that neutral colors are adjusted and balanced out with the other colors in the video.</p><p>Color match:</p><p>In this type of color grading, you can select an image as a reference and apply the color parameters to your image or video.&#160;You can use this to make your shots look more consistent.&#160;Or match it to the style of an existing shot.</p><p>The color palette you choose can completely change the mood and tone of the video you are recording.&#160;For example, to create a creepy and frightening mood in a horror film, desaturatingcolors and cool tones like blue and green are used.&#160;Alternatively, in a product demonstration video, showcasing the product against a background color that contrasts with it may help it stand out and highlight its key features.&#160;Similarly, warm, earthy colors can help a travel vlog convey a sense of nature, adventure, and exploration.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3b12d47ceb70018888faf4af50e63531','adobe-premiere-pro-m2-l4-lesson-3','df65de5e2ca0c32742a4d36f2852562f','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Fundamentals of Designs</h3><p>Fundamentals of Designs</p><p>Video shooting and editing is both a science and an art.&#160;While the technical aspects of videography are very important, you still need to understand a lot of design principles and techniques to create creative, impactful videos.&#160; Let’s discuss a few important techniques.</p><p>Click each term to view the definition.&#160;Scroll through all the flashcards to view all the terms.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>&#171; Back</p><p>Rule of Thirds</p><p>Rule of ThirdsThe rule of thirds is a very basic but highly effective technique that artists and designers have been using for decades.&#160;Divide your frame into three columns and three rows.&#160;The rule of thirds states that the main focal points of your video should be at the points where the lines intersect.&#160;You may have seen these lines while looking through a digital camera lens as well.&#160;You can test this out by picking a design or shot that you like from a magazine or film and drawing the lines over it to see where they intersect.&#160;You will see that the most important elements in the video are often framed within these intersection points.</p><p>Following the Action</p><p>Following the ActionThis is a common technique used by filmmakers where the camera follows the movement of the character throughout the scene.&#160;Most filmmakers use multiple cameras from different angles to shoot these scenes.&#160;This ensures that there is plenty of footage that can be used during the editing process to create smooth transitions and consistency.&#160;From an audience’s point of view, such shots give them a first-person view of what the character is going through, thereby pulling them deeper into the story and giving them a better cinematic experience.</p><p>Leading In and Out of Shots</p><p>Leading In and Out of ShotsWhenever you record videos, always make sure that you leave some time leading in and out of a shot so that there is enough footage that is available for you to use during the editing process.&#160;If you don’t do this, you risk cutting off parts of the audio or video or leaving too little footage to create a smooth transition between different shots.</p><p>Zooms and Pans</p><p>Zooms and PansThis is another commonly used camera technique.&#160;You can zoom in and out of shots for emphasis or context.&#160;Panning is another method where you move the camera right and left to pan across the frame of the subject.</p><p>Shooting B-roll Footage</p><p>Shooting B-roll FootageA-roll footage is the main footage that you shoot for your video.&#160;B-roll footage is supplementary video footage that is shot separately to add enhancements or dramatic effects to a video.&#160;Some examples of B-roll footage include atmospheric shots, shots of crowds or traffic, reenactments or pick-up shots, etc.</p><p>Head Room</p><p>Head RoomThis is a rule that is used in conjunction with the rule of thirds.&#160;Artists have used this concept for centuries while framing the subject of their videos.&#160;Head room refers to the space between the top of the frame and the top of the head of the subject.&#160;The space left on top should be balanced out with the space left on both sides of the image to give it a more aesthetic, balanced appearance.</p><p>L-Cuts and J-Cuts</p><p>L-Cuts and J-CutsThese are both very useful editing techniques used by video editors.&#160;In both these types of cuts, the audio and video both transition at different times.&#160;In an L-cut edit, the audio from one scene continues onto the next scene.&#160;In a J-cut scene, this is reversed.&#160;The audio from the second scene plays over the end of the first scene.</p><p>⟳ Flip Card</p><p>Next &#187;</p><p>Flashcard&#160;1&#160;of&#160;7</p><p>Flashcard Transcript</p><p>If you have watched a nature documentary, you may have noticed that the camera usually starts with a close-up of a butterfly on a flower and gradually zooming out to show the butterfly&#39;s surroundings, giving the viewer context and showing the beauty of the natural setting.&#160;Another example could be a cooking&#160;tutorial video.&#160;The chef describes each step while the camera smoothly pans between various ingredients and cooking utensils, making it simpler for viewers to follow the recipe.</p><p>Flashcard Transcript</p><p>Rule of Thirds:&#160;The rule of thirds is a very basic but highly effective technique that artists and designers have been using for decades. Divide your frame into three columns and three rows. The rule of thirds states that the main focal points of your video should be at the points where the lines intersect. You may have seen these lines while looking through a digital camera lens as well. You can test this out by picking a design or shot that you like from a magazine or film and drawing the lines over it to see where they intersect. You will see that the most important elements in the video are often framed within these intersection points.</p><p>Following the Action:&#160;This is a common technique used by filmmakers where the camera follows the movement of the character throughout the scene. Most filmmakers use multiple cameras from different angles to shoot these scenes. This ensures that there is plenty of footage that can be used during the editing process to create smooth transitions and consistency. From an audience’s point of view, such shots give them a first-person view of what the character is going through, thereby pulling them deeper into the story and giving them a better cinematic experience.</p><p>Leading In and Out of Shots:&#160;Whenever you record videos, always make sure that you leave some time leading in and out of a shot so that there is enough footage that is available for you to use during the editing process. If you don’t do this, you risk cutting off parts of the audio or video or leaving too little footage to create a smooth transition between different shots.</p><p>Zooms and Pans:&#160;This is another commonly used camera technique. You can zoom in and out of shots for emphasis or context. Panning is another method where you move the camera right and left to pan across the frame of the subject.</p><p>Shooting B-roll Footage:&#160;A-roll footage is the main footage that you shoot for your video. B-roll footage is supplementary video footag<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('68b8efe58453f602601f845924b9a5b8','adobe-premiere-pro-m2-l5-lesson-4','df65de5e2ca0c32742a4d36f2852562f','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Video Design Principles and Editing Techniques</h3><p>Video Design Principles and Editing Techniques</p><p>There are many different ways in which you can enhance your videos using various design principles and guidelines for editing videos.</p><p>Sequencing Shots:</p><p>A shot sequence is a collection of multiple related shots.&#160;A video is just a collection of multiple shot sequences.&#160;Think of a video as an essay in which each of the paragraphs is like a shot sequence.&#160;Each paragraph covers a small section of the plot of the essay, and they are all interconnected to tell a cohesive story.</p><p>Sequencing shots in video designing for a movie is the process of arranging individual shots or frames in a logical and coherent order to develop an engaging and meaningful story.&#160;Firstly, you will need to understand the script, characters, plot, and themes conveyed in the movie.&#160;You will have to choose between wide shots, medium shots, close-ups, over-the-shoulder shots to draw the audience’s attention to the right elements within the frame.&#160;Make sure the transitions between shots&#160;are seamless to maintain continuity.</p><p>Every shot sequence can be structured differently.&#160;For example, you could have a shot sequence structured in this way:</p><p>Start with a long shot to move in to set the scene.</p><p>Next, set context by moving out, including close-ups into the scene and wide shots to reveal the scene.</p><p>In the next shot, introduce the subject, object, and both subject and object together.</p><p>You can then include b-roll footage for extra details in the scene.</p><p>When you shoot sequencing shots, you must remember to account for continuity between the shots.&#160;You may have great individual shot sequences, but if they don’t flow into each other well, your overall video or film will not look good.&#160;You can also use other sequences like montages, close-ups, or even slow-motion shots to add additional impact.</p><p>Cuts &amp; Transitions:</p><p>So how do you move between different sequencing shots?&#160;Editors use cuts and transitions to do this.&#160;There are many different types of cuts and transitions that are used by filmmakers.</p><p>Types of cuts:</p><p>Click each tab to learn more.</p><p>Next Tab</p><p>Cutting on action</p><p>This refers to cutting shots when there is movement in the scene.</p><p>Cutaway</p><p>Here, you will cut away from the main scene and jump to an inserted shot for impact, and then cut back to the main shot.</p><p>Crosscut</p><p>This type of cut is used to switch between shots of different locations or situations, for example in a conversation or interview, where you switch between shots of both people in the interview.</p><p>Jump cuts</p><p>These types of cuts are usually used to show the passage of time, or to speed up action shots using disjointed edits.</p><p>Match cut</p><p>Here, when you cut from one shot to another, elements from one scene are used to transition to the next shot either by “matching” the action in the shot or by matching the composition of the shot.</p><p>Types of Transitions:</p><p>Transitions are used to enhance cuts and convey the mood or theme of the scene.&#160;Here are some common types of transitions.</p><p>Click each term to learn more.</p><p>Fade in/out</p><p>This is a transition where you gradually fade the shot in or out of a solid color. Most commonly, this is a fade from or to black, or even white. Usually, a fade to/from black is used to convey more serous emotions, while a fade to/from white is used to convey more light, hopeful emotions.</p><p>Dissolve</p><p>Here, one shot gradually blends or dissolves into another shot. This type of transition is often used to convey the passage of time.</p><p>Smash cut</p><p>This is a transition where you move abruptly from one scene to another.</p><p>Iris</p><p>This is an old-fashioned transition where a circle opens or closes in to reveal the next shot. Think of some of the old movies you may have watched, or even old cartoons like Tom &amp; Jerry – do you remember the iris transition?</p><p>Wipes</p><p>In this transition, we use a wiping animation to transition from one shot to another. This can be a screen wipe from one side to another side of the screen.</p><p>Invisible cuts</p><p>These are cuts made between different scenes to try and make the shots look like they were all shot in a single take.</p><p>L-cut &amp; J-cut transitions</p><p>We covered this earlier in this module. These types of cuts use variable cuts in the audio and video to overlap and transition audio over either the first or second shot.</p><p>Think of the different types of videos and movies you have watched and recollect the different types of cuts and transitions that were used in them.&#160;Here are some examples of types of different cuts and transitions and how they are used in different scenarios.</p><p>Flashbacks</p><p>Action scenes</p><p>Conversations</p><p>Passage of time</p><p>Flashcard Transcript</p><p>Flashbacks:&#160;You may have noticed a fade in/fade out transition being used to show flashbacks or in emotional scenes.</p><p>Action scenes:&#160;For fast-paced action scenes or even in sports movies, you will see a number of jump cuts or cutting on action being used to show the high level of movement in the scene. This is an opportunity to use different types of cuts and transitions to show the movement, build suspense or tension in the scene, or create anticipation.</p><p>Conversations:&#160;Discussions or conversations between two people in a movie or an interview can be shown using crosscuts. This gives the viewer a feeling of being ‘in the room’ and watching the people having a conversation first-hand.</p><p>Passage of time:&#160;How do you show the passing of time in a video? You may be watching a video showing you how a plant grew from a seed to a tree over time, or a movie showing the growing years of a child, or even a recipe video on social media that shows a 2-hour recipe being made in 30 seconds. A number of cuts and transitions can be used in these situations. Dissolve transitions can be used to show different shots blending into one another to indicate the passage of time. Jump cuts can also be used to show this by highlighting key events over multiple disjointed cuts. You can also speed up footage to show the passage of time.</p><p>Typography:</p><p>Text and typography are often undermined but essential parts of a design<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4fd85fda5b2c8c9b65ceb331eb2e7c7f','adobe-premiere-pro-m2-l6-lesson-5','df65de5e2ca0c32742a4d36f2852562f','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Design and Composition</h3><p>Design and Composition</p><p>Types of Shots and Where to Use Them</p><p>The way in which you capture your shots can make a huge difference in the type of feeling or emotion that is conveyed to your audience.&#160;Creating dramatic effect, suspense, fear, joy, or any other emotions – all this can be done using different types of shots.&#160;Let’s take a look at different types of shots and how they are used:</p><p>Click each term to learn more.</p><p>Next Tab</p><p>Close-Up (CU)</p><p>A close-up shot is taken within close range of the subject to capture minute details.&#160;Close-up shots are usually used in emotional shots or to reveal intricate details that the audience needs to pay attention to.</p><p>Extreme Close-Up (ECU)</p><p>Here, we frame the shot extremely close to the subject, so much so that the subject fills the frame of the shot. It is used for emphasis or to focus on a specific action, like an extreme close-up of someone’s mouth as they are delivering a pivotal piece of dialogue.</p><p>Medium Close-Up (MCU)</p><p>Medium close-up shots can have multiple characters in the shot, usually, all being shot from the chest up. Medium close-up shots are used to shoot conversations.</p><p>Medium Shot (MS)</p><p>Medium shots, as the name suggests, are captured at a medium distance from the subject. This allows you to easily use these shots to shoot 2-3 person dialogues. This show is often called the ‘sweet spot’ shot as it shows just enough of the subject as well as the surrounding environment.</p><p>Wide Shot (WS) or Long Shot (LS)</p><p>In these shots, the subject is usually visible from head to toe, along with any other characters and background elements of the location. Wide shots can be used to showcase the location that the character is in, or they can also be used as long shots where the camera is further away from the subject.</p><p>Extreme Long Shot (ELS)</p><p>Here, the camera moves even further away from the subject. In fact, the subject may not be visible in the shot as well. These shots are used to capture the landscape or the scale of what is happening in the scene. For example, they can be used at the beginning of a video to show which city the scene is set in, or in a war movie, it could be used to show the scale of the wear or damage.</p><p>Over-The-Shoulder (OTS)</p><p>This shot is used when two characters are in conversation in the scene. The shot establishes the eye line of each character. This in addition to playing with the depth of field, gives you the ability to draw attention to specific areas of the shot in either the foreground or background of the scene.</p><p>Point Of View (POV)</p><p>This type of shot is used to show what the subject is looking at in the scene. This is often used to establish terror or fear in scenes, for example, a subject staring at the mirror in fear.</p><p>For example, while shooting a nature documentary, a wide shot of a vast grassland is showcased to show the diverse landscape and wildlife.&#160;While shooting a dialogue scene of a movie, a medium shot is used to capture the conversation between the two characters as well as their facial emotions.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3232afbd8c0a197fd71b543a96b69f1b','adobe-premiere-pro-m2-l7-module-2-summary','df65de5e2ca0c32742a4d36f2852562f','Module 2 Summary','text',12,'<h2>Module 2 Summary</h2><section><h3>Summary</h3><p>Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Working in the Video Design Industry Part II!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this session, you:</p><p>Demonstrated knowledge of key terminology related to digital audio, digital video, and video/audio production.</p><p>Demonstrated knowledge of how color is managed in digital video.</p><p>Communicated visually using design principles and standard film/video techniques.</p><p>Identified general design principles and guidelines for editing videos.</p><p>Defined common photographic and cinematic composition terms and principles and gave examples of when and why to use types of shots.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('778c14f379c4cfbf1279c4014b16f410','adobe-premiere-pro-m2-l8-module-2-project','df65de5e2ca0c32742a4d36f2852562f','Module 2 Project','text',12,'<h2>Module 2 Project</h2><section><h3>Module 2 Project</h3><p>Adobe Premiere Pro</p><p>8100</p><p>Working in the Video Industry Part II - Project</p><p>Project</p><p>In this assignment, you will use what you’ve learned about basic design principles and digital image terminology to write an essay.</p><p>Pick a scene from an online video, TV show, or movie of your choice to base your essay on. This can be any short video that you found interesting or that made an impact on you.</p><p>Write a two-page, double-spaced paper on your assessment of the video based on the following factors:</p><p>The visual appeal of the video, why you think it is appealing, and how that ties into the basic principles of video design.</p><p>The use of color, typography, cuts, and transitions in the video and an evaluation of how they have been used to create contrast, visual impact, etc.</p><p>Also, elaborate on the use of sequencing shots, text and topography if any.</p><p>Review the rubric below to see how you will be graded.</p><p>Working in the Video Design Industry Part II Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Understand basic principles of design</p><p>8 points The student demonstrates an understanding of the basic principles of design and common design techniques.</p><p>7-6 points The student demonstrates an adequate understanding of the basic principles of design and common design techniques. The essay contains some accurate details and concepts.</p><p>5-0 points The student demonstrates little to no understanding of the basic principles of design and common design techniques, and the essay contains inaccurate details or little to no explanation of concepts.</p><p>8</p><p>Understand use of color and typography</p><p>8 points The student demonstrates an understanding of the use of color and typography in designs.</p><p>7-6 points The student demonstrates an adequate understanding of the use of color and typography in designs. The essay contains some accurate details and concepts.</p><p>5-0 points The student demonstrates little to no understanding of the use of color and typography in designs. The essay contains inaccurate details or little to no explanation of concepts.</p><p>8</p><p>Understand image layouts and composition</p><p>8 points The student demonstrates an understanding of image layouts and composition.</p><p>7-6 points The student demonstrates an adequate understanding of image layouts and composition. The essay contains some accurate details and concepts.</p><p>5-0 points The student demonstrates little to no understanding of image layouts and composition. The essay contains inaccurate details or little to no explanation of concepts.</p><p>8</p><p>Total Points:&#160;24</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6fc440c98723a66c0cd43e5f0222e3b2','adobe-premiere-pro-m2-l9-module-2-quiz','df65de5e2ca0c32742a4d36f2852562f','Module 2 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Video Industry Part 2. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('0cbc6afde1222b4d5533531f13712e63','adobe-premiere-pro-module-3','48ab1932af65ef3f9d0793cd5a02da34','Module 3: Project Setup & Interface',3) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a9553b1fcb12d32338f5babaa2d45f5b','adobe-premiere-pro-m3-l1-introduction-purpose-and-objectives','0cbc6afde1222b4d5533531f13712e63','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi, welcome back! In the last two modules, we laid down some of the foundational elements and critical concepts of this Premiere Pro course. You got an insight into the big picture of working in the video design industry. You also learned about crucial design principles and techniques, as well as common video design terms and their definitions.</p><p>Now, it’s finally time to dip our toes into Premiere Pro! Let’s dive into this module on Project Setup and Interface.</p><p>In this module, you will get comfortable with some very important basics. You will learn how to set up a new project in Premiere Pro and the various program settings available. Before you can actually use Premiere Pro, you need to get familiar with all of the elements of the Premiere Pro interface. So, we’ll walk through all the fantastic tools in the Premiere Pro interface that you can use to transform your videos. And, as with any project, it is always important to stay organized, so we’ll show you how you can completely organize and customize your Premiere Pro workspace. You can import and manage all of your assets, create sequences, and use various design tools that will help you manage your project workflow. Let’s take a look!</p><p>Module Description</p><p>The Premiere Pro interface is a treasure trove of useful tools and settings.&#160;As beginners who are being introduced to Premiere Pro, the first thing that students will need to do is familiarize themselves with the interface so they can begin to identify the different sections and tools available.&#160;Students will learn how to get started with Premiere Pro by creating a new project and understanding all the elements of the Premiere Pro interface and their functions.&#160;Students will learn how to customize the Premiere Pro workspace and preferences in a way that is both convenient and efficient They will also learn how to use other non-visible design tools during the editing process.</p><p>Objectives</p><p>In this module, students will:</p><p>Set appropriate project settings for video and identify and manipulate elements of the Premiere Pro interface.</p><p>Navigate, organize, and customize the application workspace and configure application preferences.</p><p>Import assets into a project, import media from various sources, and manage assets in a Premiere Pro project.</p><p>Create a sequence that matches the project requirements.</p><p>Use non-visible design tools in the interface to aid in video workflow including navigating a project, timeline markers, and guides.</p><p>Polling Question</p><p>Have you ever used Premiere Pro before?</p><p>Yes&#160;No</p><p>Make a selection to see the results so far.</p><p>Which of these tasks can be done using Premiere Pro?</p><p>Edit videos&#160;Add transtition effects to videos&#160;Perform color correction in videos&#160;Add audio and text to videos&#160;All of the above</p><p>Make a selection to see the results so far.</p><p>How many of your classmates have dabbled in Premiere Pro?&#160;Did you know that you can do all of these tasks using Premiere Pro?&#160;Let&#39;s dive in and learn more.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b4bcd3b100abf0d48e97dca3217198b6','adobe-premiere-pro-m3-l2-lesson-1','0cbc6afde1222b4d5533531f13712e63','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>New Projects in Premiere Pro</h3><p>New Projects in Premiere Pro</p><p>Note:&#160;These screenshots may look a little different depending on the version of Premiere Pro you are using, but the basic functions will remain the same.</p><p>Minimum System Requirements</p><p>Premiere Pro is essentially a video editing software, and because of this, it can be a heavy program to run on your computer.&#160;The video files and assets created using Premiere Pro also tend to be large files.&#160;So, before you begin working on Premiere Pro, make sure you check your system requirements and ensure that they at least meet the minimum system requirements mandated by Adobe Premiere Pro.&#160;You can check this by just searching for the minimum system requirements for Premiere Pro on the Adobe website.</p><p>Note:&#160;It is best to check this against the website as the minimum requirements may change based on the version of Premiere Pro you are currently using.</p><p>Project Files</p><p>In Premiere Pro, you will use&#160;project files&#160;to edit your videos.&#160;A project file contains information about all of the components of your video, including the video clips, audio files, text, transitions, sequences, and more.&#160;Because a lot of these elements can be very heavy, the project file doesn’t store any of these individual elements.&#160;Instead, it only stores information about the settings and editing decisions you made, along with a reference to the location on your computer where each of these components is saved.&#160;Premiere Pro creates folders on your computer to store each of these different files.&#160;So be careful about renaming or moving any of these source files, because the next time you open a project file, you may get an error because Premiere Pro will be unable to find all the source files.&#160;All project files are stored on your computer as&#160;.prproj files.</p><p>Also, any edits that you make in Premiere Pro are made in a&#160;non-destructive&#160;manner.&#160;This means that these changes are not permanent, and you can always access the original source files at any time.</p><p>Creating a New Project File</p><p>When you open Premiere Pro, you will see the Start screen where you can see a list of your Recent files.</p><p>To create a new project, click the&#160;New Project&#160;button.&#160;Once you have been working on Premiere Pro for a while, you may want to open an existing project.&#160;In this case, you can click the&#160;Open Project&#160;button instead and navigate to the location on your computer where the file is stored to open it.</p><p>Next, enter a name for your new project, and then click&#160;Browse&#160;to choose a location to save your project file.</p><p>Generally, you can leave all the other default settings as they are.&#160;You can click&#160;OK&#160;to create a new project.&#160;But first, let’s take a look at the&#160;Scratch Disk Settings.</p><p>Scratch Disk Settings</p><p>Click the&#160;Scratch Disk&#160;tab to view the settings.</p><p>This tab shows you the locations where Premiere Pro will save all the assets of your project.&#160;So, here you can see where the video, audio, previews, downloads, and more assets are saved.&#160;We would recommend you save all your files at the same root location so that you can easily access all the source files when you need them.</p><p>There is also a third tab called Ingest Settings.&#160;For now, we can leave this at the default settings.&#160;We will explain this tab later in this course.&#160;You can now click&#160;OK&#160;to create your new Premiere Pro project file.</p><p>There are also a few other ways in which you can create a new project file in Premiere Pro.&#160;In the application menu bar, click&#160;File, select&#160;New, and click&#160;Project.&#160;You can also use the keyboard shortcut&#160;Ctrl + Alt + N&#160;(on Windows) or&#160;Opt + Cmd + N&#160;(on Mac) to create a new project file.</p></section><section><h3>Interface Overview</h3><p>Interface Overview</p><p>Once you create a new project or open an existing project, you will see the main Premiere Pro workspace.&#160;If you are opening Premiere Pro for the first time, it is likely that you will see this default view.</p><p>The main workspace is broadly divided into 4 main sections or panels.&#160;These 4 panels have been designed and arranged by Adobe in a way that is intuitive and customizable.&#160;We’ll go over each panel in detail in the next lesson.&#160;For now, click each highlighted hotspot on the screenshot to learn more.</p><p>Click each hotspot on the image to learn more.</p><p>5</p><p>Image Hotspots Transcript</p><p>Tools Panel</p><p>Premiere Pro has a set of 11 tools that can help you perform useful tasks during the editing process.&#160;You can either click these icons to perform these tasks, or you can use the related keyboard shortcuts to select the tools.&#160;You can see these keyboard shortcuts if you hover your cursor over each icon – we have added them in brackets alongside each description below for your reference.&#160;Let’s see what each of these tools does.</p><p>Note:&#160;Many tools are grouped together, indicated by the small white arrow at the bottom-right of the icon.&#160;Just click and hold the icon to toggle between any of the grouped tools.</p><p>Selection Tool (V):&#160;You can use this tool to select clips, menu items, buttons, and other objects in the user interface.&#160;This is usually the default selection.</p><p>Track Selection Tool:&#160;You can use this tool to select all the clips to the right or left of the cursor.&#160;If you click and hold your cursor over this icon, you will see two options, the&#160;Track Select Forward tool (A)&#160;to select clips to the right of the cursor, and the&#160;Track Select Backward tool (Shift + A)&#160;to select clips to the left of the cursor in a sequence.</p><p>Ripple Edit Tool (B):&#160;When you use the selection tool and trim a clip, you risk creating an empty space between the clips.&#160;To avoid this, you can use the Ripple Edit tool.&#160;This tool trims the In or Out point of a clip and closes any gaps caused by the edit.</p><p>Rolling Edit Tool (N):&#160;This tool is used when you need to change the in and out points across adjacent clips.</p><p>Rate Stretch Tool (R):&#160;Use this tool to shorten or lengthen a clip in the Timeline.&#160;This tool speeds up or slows down the playback of the clip without the clip being cropped.</p><p><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0a456546be53fe4a121b8b3def996f73','adobe-premiere-pro-m3-l3-lesson-2','0cbc6afde1222b4d5533531f13712e63','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Working with Workspaces</h3><p>Working with Workspaces</p><p>Premiere Pro comes with several pre-defined workspaces, each with a different arrangement of panels that are specific to each type of workspace.&#160;In most cases, you should easily be able to use one of these workspaces for all your editing needs.</p><p>By default, all your projects will open in the&#160;Editing&#160;workspace.&#160;You can switch to another workspace at any time by clicking it in the Workspace bar.&#160;There is also an&#160;Overflow&#160;menu that contains additional workspaces that are not shown in the workspace panel.&#160;You can click the&#160;Edit Workspaces&#160;option in this menu and modify which workspaces are displayed and which are hidden.</p><p>You can also access the workspaces from the top menu bar.&#160;Just click&#160;Window&#160;and select&#160;Workspaces.&#160;Here, you can see a list of all the available workspaces.&#160;You can also use these keyboard shortcuts to access any of these workspaces quickly.</p><p>All the panels in your workspace can be moved, resized, rearranged, added, or deleted based on your requirements.&#160;If you come up with a customized workspace configuration that works best for your needs, you can also save this configuration as a custom workspace.&#160;Just click&#160;Window, select&#160;Workspaces, and click&#160;Save as New Workspace.&#160;You can name your new workspace and use it at any time.</p><p>You will see two options in this menu:</p><p>Save Changes to this Workspace&#160;– this will save any edits you have made to the default workspace.</p><p>Save as New Workspace&#160;– this option will save your edits as a new workspace.</p><p>Depending on which workspaces you use most frequently, you can also rearrange the order in which they appear in the Workspace panel.&#160;To do this, click the chevron icon to open the overflow menu, and click&#160;Edit Workspaces.</p><p>Here, just drag and drop the different workspaces in the order that you want.&#160;As you can see, you can organize them into three categories, workspaces that are displayed in the workspace panel, workspaces that are displayed in the overflow menu, and a final category for workspaces that you don’t want to show at all.&#160;Once you are done with your changes, click&#160;OK&#160;and the order of workspaces will be updated.</p><p>Once you have made all the changes you want, you can easily save this as your own custom preset.&#160;Enter your own name for the preset.&#160;Ideally, you should make this a descriptive name so that you can easily identify it when you search for it the next time.&#160;To save the custom preset, just click the&#160;Save&#160;icon at the top and you’re done!</p><p>When you click any workspace, you will see the menu icon appearing next to the highlighted workspace.&#160;You can click this to reset the workspace to the default settings, save the modified workspace as a new workspace, or open the&#160;Edit Workspaces&#160;window.</p></section><section><h3>Working with Panels</h3><p>Working with Panels</p><p>Premiere Pro panels are very versatile.&#160;You can resize and rearrange them, dock or undock them, make them full-screen, and even group them.</p><p>Panels can easily be resized.&#160;Just scroll your cursor over the edge of any panel till it turns into a double arrow.&#160;Now, you can click and drag the edge of the panel to resize it.&#160;Panels can be resized from all four edges.</p><p>Now let’s look at how you can&#160;dock and undock panels.&#160;If you scroll your cursor over the header of any panel, you will see a single or double small rectangle appearing near the cursor.&#160;When one rectangle appears, it means a single panel will be selected, when two rectangles appear, it means that a group of panels is going to be selected.</p><p>Click and drag the panel and just scroll it over to any other panel.&#160;You will see highlighted areas around the edges of the panel.&#160;These are called&#160;drop zones.&#160;Drop zones are areas where panels can be docked or grouped with other panels.</p><p>Let’s say that we drag a single panel out and roll it over this panel that has grouped panels.&#160;You will see that the top edge has two drop zones.&#160;If I release this panel on the upper drop zone, this panel will become grouped with the other panels.</p><p>If I release the panel in the lower drop zone of the top edge, then it will be added on top of this group of panels as a single panel.</p><p>You can also un-dock panels by just clicking the title and dragging them out of the group.&#160;Now, you can either group this panel with another panel or group, or you can dock it in any other drop zone in the workspace.</p><p>If you un-dock a panel and do not release it over a drop zone but just over the workspace, it will appear as an independent, floating window.&#160;You can move this floating window to another location on the screen or, if you are using a dual-monitor system, you can move it to another monitor as well.</p><p>You can also use the panel menu to perform these actions.&#160;Click the&#160;Menu icon.&#160;As you can see, you can undock the panel as well as make changes to any grouped panels as well.</p><p>Apart from the panels visible on your workspace, there are many other panels that you can add to your workspace to customize it.&#160;Click&#160;Windows.&#160;Here, you can see a list of many panels that you can add to your workspace.&#160;The ones with a checkmark next to them are already present on the workspace.</p><p>If you have a large number of panels grouped together, just place your cursor over the header bar of the panel group and use the scroller on your mouse to easily switch between all the panels.</p></section><section><h3>Configuring Application Preferences</h3><p>Configuring Application Preferences</p><p>Now, let’s take a look at the application preferences.</p><p>On Windows:&#160;Click&#160;Edit, select&#160;Preferences, and click&#160;General.</p><p>On a Mac:&#160;Click&#160;Premiere Pro, select&#160;Preferences,&#160;and click&#160;General.</p><p>The&#160;Preferences&#160;window will be displayed.&#160;The left pane shows you all the different preferences that you can customize.&#160;You can define shortcuts, adjust the brightness of the application, and much more.</p><p>For instance, you can adjust the&#160;bin behavior&#160;when you perform different actions like double-clicking a bin, double-clicking with the S<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('dcd96ff9e2bc33596499907c15f5f496','adobe-premiere-pro-m3-l4-lesson-3','0cbc6afde1222b4d5533531f13712e63','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Transferring Files</h3><p>Transferring Files</p><p>You have learned that the assets that you import into Premiere Pro are just links or shortcuts of the original files.&#160;So, the first thing you need to do before you can import any assets is to make sure that they are moved to your computer or an external drive from your camera or other device’s memory card.</p><p>Note:&#160;Make sure that you drag the entire content of your memory card onto your computer.&#160;This is especially important if you are using a DSLR camera.&#160;While these cameras do create individual .mp4 files, they may also contain other folders called AVCHD or XAVC which contain important metadata related to the images that Premiere Pro will require to open the videos.</p><p>Also, make sure that all the images remain in the same folder, as you may risk corrupting the files if you move them or delete the AVCHD folder.</p><p>By moving all your videos onto your computer, you can make sure that all files are in a fixed location, and you are not risking breaking the link between your Premiere Pro project and your video files.</p></section><section><h3>Importing Assets</h3><p>Importing Assets</p><p>There are multiple ways in which you can import assets into your project file – you can choose which option is most convenient to you.</p><p>You can import all types of audio files into Premiere Pro.&#160;Apart from the standard videos, audio files, and images, you can also import other Premiere Pro files, After Effect files, Photoshop files, and close captioning files.</p><p>Note:&#160;Premiere Pro supports multiple different video and audio formats and contains the software required the run the codecs associated with many of these file types.&#160;Check the Adobe website for a detailed list of file formats that are supported in Premiere Pro.</p><p>You can import files using the Import command or by using the Media Browser.</p><p>Click&#160;File&#160;and select&#160;Import.&#160;You can now navigate to the location where the media is stored on your computer.&#160;You can select one or multiple files to import at a time.&#160;You can also import the entire media folder if you want.&#160;This folder will be added as a new bin in your Premiere Pro project.</p><p>Now, let’s look at how you can import files from the Media Browser.</p><p>The Media Browser will usually be found grouped with your project panel.&#160;If you cannot find it, open it by clicking&#160;Window&#160;and selecting&#160;Media Browser.</p><p>Another option is to use the Assembly workspace.&#160;This is useful if you have a large number of files to browse through because the Media Browser panel is much larger in the Assembly workspace.</p><p>For example, let’s say that your family and relatives have all gathered to celebrate your grandparents’ 50th&#160;wedding anniversary.&#160;All your relatives took photos and videos on their phones of all the events of the day.&#160;You’ve been entrusted to take all their videos and put together an anniversary video to share with the whole family.&#160;In this scenario, you will need to sift through all of the images and videos and edit them together to make your video.&#160;In this instance, using the&#160;Media Browser&#160;panel will help you easily browse through the multiple media files.</p><p>Let&#39;s take a closer look at the&#160;Media Browser&#160;panel.</p><p>Click each hotspot on the screenshot to learn more.</p><p>5</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Media Browser panel in Premiere Pro</p><p>The hotspot points on the image are as follows:</p><p>Search</p><p>The Search bar allows you to search for files using keywords.</p><p>Filter</p><p>You also have the option to filter your results based on file type using the&#160;Filter&#160;icon. So, if you only want to view the MP3 files in your folder, then just select the relevant option from this drop-down list.</p><p>Directory viewer</p><p>If you have attached a camera, external storage drive, or memory card to your computer, you can use the&#160;Directory Viewers&#160;icon to select which directory you want to view.</p><p>Local file browser</p><p>Once you open the Media Browser panel, on the left, you will see a list of your local folders. You can drill down to the path where your files are saved on your computer. The contents of the selected folder will be displayed on the right.</p><p>View options</p><p>At the bottom of the Media Browser, you can see different view options that you can toggle between. You can either use the default list view or switch to a thumbnail view. You can also use this slider to zoom in and out and make the items larger or smaller.</p><p>If you want to preview the video files, just switch to the thumbnail view and run your cursor over the video thumbnail. You can also double-click the video and preview it in the&#160;Source Monitor.</p><p>Once you have navigated to the correct folder, select one or all of the media files you want to import.&#160;To select multiple non-consecutive files, just&#160;Ctrl + click (in Windows)&#160;or&#160;Cmd + click (in macOS)&#160;each of the file names.&#160;To select multiple consecutive files, just&#160;Shift + click&#160;the files.</p><p>Now that you have selected the files you want to import, there are multiple ways you can do this as well.&#160;Right-click over your selection and select&#160;Import.&#160;You can also drag your selection to the Project panel and drop them to import the files.</p><p>Another simple way to import files into Premiere Pro is to do it directly from the&#160;Project panel.&#160;Just double-click in the Project panel, or right-click and select&#160;Import.&#160;Now, navigate to your media folder and follow the same process to select and import your files.&#160;You can also keep your media folder open and drag it and drop it into the Project panel directly.</p><p>Ingesting Assets</p><p>Premiere Pro also gives you the option of importing assets by creating a copy of the asset in your Premiere Pro project.&#160;This is called&#160;Ingesting.&#160;This is useful if you are using an external source for your media files like a connected camera, memory card, or external storage device.&#160;Premiere Pro copies the media file and saves a copy in the same folder as your project.</p><p>Note:&#160;You must have Adobe Media Encoder installed on your computer to use this method to imp<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('364308964fc97f5d4e72525b5730667d','adobe-premiere-pro-m3-l5-lesson-4','0cbc6afde1222b4d5533531f13712e63','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Creating a Sequence</h3><p>Creating a Sequence</p><p>As you have already learned, a sequence is a group or container for media files that will play one after the other.&#160;In Premiere Pro, you can create multiple sequences, specify settings for each sequence, edit and modify the clips in each sequence, and more.&#160;Note that a sequence must contain at least one video track and one audio track.</p><p>The easiest way to create a sequence is to just select all the assets that you want in your sequence and drag them onto the&#160;Timeline&#160;panel.&#160;A new sequence is created.&#160;Note that the files will be added to the Timeline panel in the order that you selected them.</p><p>You will see the new sequence in the Project panel as well with the same file name as one of your existing files.&#160;To avoid any confusion, you can rename this file.&#160;You can easily differentiate between the different types of files in your Project panel by looking at the little icon in the thumbnail.</p><p>Another way of creating a sequence is by clicking the&#160;New Item&#160;icon in the Project panel and selecting&#160;Sequence.&#160;You will see a popup that gives you a list of sequence presets on the left, and a detailed description of the selected preset on the right.</p><p>A sequence preset contains pre-configured settings for a video sequence.&#160;It specifies details like the frame rate, resolution, and audio sampling rate, etc. so that all the assets imported using this sequence preset are all standardized.&#160;So, let’s say that you are using clips recorded on a digital SLR.&#160;Let’s open the&#160;Digital SLR&#160;drop-down list in the&#160;Available Presets&#160;column.&#160;We can then drill down and select the preset we want.&#160;You can see a detailed description of each preset on the right.</p><p>If you need to alter any of the settings, just click the&#160;Settings&#160;tab and make any required changes.&#160;For example, you may want to change the frame rate to a higher value or modify the frame size.</p><p>Similarly, you can modify other settings by clicking the other tabs.&#160;In the&#160;Tracks&#160;tab, you can specify the number of video and audio tracks you will require in this project.&#160;You also have the option to save these settings as a new custom preset.</p><p>Once you have done this, you can add clips into your sequence.&#160;If you use a preset to create a sequence, and you then try to add a media file that doesn’t meet the settings of the sequence preset, you will see a prompt asking you if you want to change the preset settings or keep the original settings.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e990747a3327c69fc1fbb61e367a6c3d','adobe-premiere-pro-m3-l6-lesson-5','0cbc6afde1222b4d5533531f13712e63','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Navigating a Project</h3><p>Navigating a Project</p><p>Now that you have learned how to create a project, import media files, and create a sequence, let’s go over some quick tips on how you can get comfortable with navigating a project.</p><p>You can use the&#160;(+)&#160;and&#160;(-)&#160;buttons on your keyboard to zoom in and out of all your panels.</p><p>These keys work a little differently in the&#160;Timeline&#160;panel.&#160;You can use just the&#160;(+)&#160;and&#160;(-)&#160;buttons to zoom in to the timeline itself.</p><p>You can also use the&#160;Shift + (+)&#160;and&#160;Shift + (-)&#160;buttons to increase the size of the tracks in the&#160;Timeline&#160;panel.</p><p>If you only want to increase the height of a single track, just click the track head and drag it up to increase the height.&#160;This will also give you a preview of each of the clips in the sequence or program file.</p><p>You can use the&#160;tilde key (~)&#160;on your keyboard to open any panel in full screen.&#160;Press the same key once again to return to the default view.</p><p>Next, you will see a blue playhead in the Source, Program, and Timeline panels.&#160;This is also called the&#160;CTI&#160;or&#160;current-time indicator.&#160;You can click and drag this playhead to scrub through the video or timeline.&#160;You can also use the spacebar on your keyboard to play or pause the video.</p><p>When you are editing a large number of video clips, playing and watching each and every video clip can be very time-consuming.&#160;A way to speed up this process is to use the&#160;jkl keyboard shortcuts.&#160;Here is what each of these keys does:</p><p>J key:&#160;plays the video backward.&#160;Clicking this multiple times plays the video backward faster.</p><p>K key:&#160;pauses the playback – this works just like the spacebar.</p><p>L key:&#160;plays the video forwards.&#160;Clicking this multiple times plays the video forwards faster.</p><p>You can also combine these keys with the Shift key for slower, more precise movements.</p><p>Another useful keyboard shortcut is the&#160;backslash (\) key.&#160;You can use this to view the entire timeline.</p></section><section><h3>Using Markers</h3><p>Using Markers</p><p>Markers are like bookmarks that help you mark out important points in your video sequence.&#160;They don’t have any visual impact on the video itself but serve as a great tool that you can use to mark out key areas such as a point in the video where you want to add audio or multiple points in a video where you want to add effects or transitions.</p><p>To create a marker, all you need to do is to drag the playhead to the point in the video or audio where you want to add a marker, and then press the&#160;M&#160;key.&#160;You can also right-click at that point and click&#160;Add Marker.</p><p>You can easily delete a marker by selecting it, right-clicking, and selecting&#160;Clear Selected Marker.</p><p>If you are adding multiple markers to indicate different things, you can color-code them as well so you can easily identify what each marker is for.&#160;Just select and right-click the marker and click&#160;Edit Marker.&#160;Here, you can change the name and color of the marker and click&#160;OK.</p><p>Note that when you drag the playhead to any point in the Project panel, you will see that the time stamp on the top left (in blue) also changes.&#160;This shows you the current timestamp of the position of the playhead.</p><p>You can adjust the volume level of an audio clip by dragging the audio line running through the middle of the audio file up or down.</p><p>In some cases, you may want the audio level to be higher or lower at different points and also have it fade in and out at different points.&#160;To do this, you can use&#160;keyframes.&#160;To create a keyframe, press and hold down the&#160;Command key (in macOS) or the Ctrl key (in Windows).&#160;When you scroll over the audio line, you will see that the icon changes to a plus sign.&#160;Click at the point in the audio file where you want to add a keyframe.&#160;You can click on multiple points.</p><p>You can also do this by selecting the&#160;Pen&#160;icon in the&#160;Tools&#160;panel and using this tool to click at the points that you want to add keyframes.&#160;Now, switch back to the&#160;Selection&#160;tool and you can drag the audio line at the keypoints to adjust the volume of the audio and have it fade in or out.</p><p>To delete a keyframe, just select it and press&#160;Delete&#160;on your keyboard.</p><p>Action and Title Safe Areas</p><p>When you use a digital camera, you see different guides and borders that mark out areas within which you should position your subject.&#160;This outer margin is left to account for any cropping that may occur in different devices you may view your photo or video on.&#160;The same is true for videos in Premiere Pro.</p><p>Premiere Pro defines safe margins or areas that serve as a visual guide to indicate areas within which you should position all your actions and titles.&#160;You can view these margins by right-clicking in the&#160;Program&#160;panel and selecting&#160;Safe Margins.</p><p>You should place all the important action and text within these margins, as anything outside the margin is at risk of being cropped depending on the display being used.&#160;You may have noticed this happening in YouTube where the video player covers text that may have been added at the bottom of the video, or any quick links or popups at the top cover up any titles or images at the top of the video.</p><p>You can also customize the size of the safe margins easily.&#160;Click the Program panel&#160;Settings&#160;icon, select&#160;Overlay Settings, and click&#160;Settings.&#160;Here, you can modify the width of the safe margin.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('835c6e060c30fc2bf85684bc81ea25a6','adobe-premiere-pro-m3-l7-module-3-summary','0cbc6afde1222b4d5533531f13712e63','Module 3 Summary','text',12,'<h2>Module 3 Summary</h2><section><h3>Module 3 Summary</h3><p>Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Project Setup and Interface!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Created a new project with appropriate project settings for video and identified and manipulated elements of the Premiere Pro interface.</p><p>Navigated, organized, and customized the application workspace and configured application preferences.</p><p>Imported assets into a project, imported media from various sources, and managed assets in a Premiere Pro project.</p><p>Created a sequence that matches the project requirements.</p><p>Used non-visible design tools in the interface to aid in video workflow including navigating a project, timeline markers, and guides.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('509e66fd484209e9ba946c531139c204','adobe-premiere-pro-m3-l8-module-3-project','0cbc6afde1222b4d5533531f13712e63','Module 3 Project','text',12,'<h2>Module 3 Project</h2><section><h3>Module 3 Project</h3><p>Adobe Premiere Pro</p><p>8100</p><p>Project Setup and Interface - Project</p><p>Project</p><p>In this assignment, you will apply all that you have learned about the project setup and the Premiere Pro interface to perform the following tasks. You will need to use Premiere Pro to perform these tasks. In some of these tasks, you may need to take screenshots to label them as well.</p><p>Create a new project in Premiere Pro. Take a screenshot of the Premiere Pro interface and label the different sections. (You can use a Word document or PowerPoint document to do this.)</p><p>Resize and rearrange at least 2 panels in the workspace based on your preferences.</p><p>If you have a digital camera with videos that you have recorded, then transfer the videos using the methods you learned in this module. Next, import the video and audio assets into your new project and organize them into bins. Make sure you rename the bins that you create. If you do not have videos that you have already recorded, here are some ideas to get you started:</p><p>If you have pets, record videos of them playing at a park, beach, or even at home. You can create a fun video of your pets and also include pictures into the video.</p><p>Record videos of a celebration like a birthday party or wedding. Also incorporate photos from the event into your video.</p><p>If you like to watch or play sports, take videos of a game. You could also narrate what is happening in the game.</p><p>Take a video of you or someone else cooking a recipe. You have the opportunity to incorporate text and different transitions into your video here.</p><p>If you like being outdoors, you could take videos of the scenery or birds and animals you see during a hike.</p><p>Create and rename a new sequence.</p><p>Add markers at regular intervals in the video. Next, add keyframes at appropriate places to fade in and fade out the audio in your sequence.</p><p>Project Setup and Interface - Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Creating project</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Organizing the workspace</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately with attention to detail and meeting all requirements.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors in the preset settings.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well and the preset was not created as instructed.</p><p>4</p><p>Importing assets</p><p>4 points Demonstrated a strong understanding of the objective. All the interface elements were identified correctly.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. Almost all the interface elements were identified correctly, with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. Little to none of the interface elements were identified correctly.</p><p>4</p><p>Creating a sequence</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately and the workspace was organized as instructed.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors in organizing the workspace.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Using non-visible design tools</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately and all the preferences were configured as instructed.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors in some of the preferences.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('bfeb80c3d3e382d59505800154c4a9cf','adobe-premiere-pro-m3-l9-module-3-quiz','0cbc6afde1222b4d5533531f13712e63','Module 3 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Project Setup & Interface. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('5cc0a14d441e16022f9437b874be2c13','adobe-premiere-pro-module-4','48ab1932af65ef3f9d0793cd5a02da34','Module 4: Visual Elements Part 1',4) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0bed7eedb1e992530f917d579324e522','adobe-premiere-pro-m4-l1-introduction-purpose-and-objectives','5cc0a14d441e16022f9437b874be2c13','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Select a Student</p><p>Welcome back to this module on Creating and Modifying Visual Elements, Part 1!</p><p>By now, you should be armed with a good understanding of design basics and basic project setup and interface options in Premiere Pro. You should now be ready to dive into organizing a project and learning how to make a rough cut of your video. One of the most essential elements you will use for this is sequences! As you go through this module, we’ll give you some great tips and tricks on how to add different types of media files to your project to create sequences, manage sequences in different types of projects, and much more!</p><p>Unless you are making a silent film, audio is another essential part of any video! So in this module, we’ll show you how you can add audio and manage your audio levels. Once you have all the building blocks in place, you will be ready to create a rough-cut of your video using all of the different tools and panels you learned about! Don’t worry about getting everything perfect just yet, as editing is a process. Additionally, Premiere Pro is highly flexible and allows you to make mistakes and correct them as you go. You can lay out your videos and audio in different ways, cut and crop them, layer them, undo actions, and finally, preview them to see what works best.</p><p>Module Description</p><p>Select a Student</p><p>Sequences help you structure and organize all of the media elements of your project.&#160;They give you the flexibility to work on individual elements and edit, crop and adjust them as many times as you want till you have the perfect results.&#160;In this module, you will learn all about the using the Timeline panel to manage all your media elements.&#160;You will also learn about editing and adjusting the visibility of tracks and audio levels.&#160;Finally, you’ll learn how to place images and videos into a sequence to create a rough-cut of a video.</p><p>Objectives</p><p>Select a Student</p><p>In this module, students will:</p><p>Use the Timeline panel to manage video and audio tracks.</p><p>Modify basic track visibility and audio levels.</p><p>Create a video rough-cut using a variety of tools and panels.</p><p>Manage sequences in a complex project.</p><p>Place images and video into a sequence.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1e4be6d5f08ea3f28c3df9f2886a9cd3','adobe-premiere-pro-m4-l2-lesson-1','5cc0a14d441e16022f9437b874be2c13','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Managing Clips in the Timeline Panel</h3><p>Managing Clips in the Timeline Panel</p><p>Select a Student</p><p>You have learned how to import assets and create basic sequences.&#160;Now, let’s look at how you can manage your assets in the Timeline panel.&#160;To begin, let’s take a closer look at the&#160;Timeline&#160;panel and the various tools available here.</p><p>Let’s begin by understanding two key terms:&#160;clips and tracks.&#160;Are they the same thing?</p><p>Click each term to learn more.</p><p>Next Tab</p><p>Clips</p><p>If you look at any edited video or movie, you’ll notice that they all have multiple different pieces of videos and audio that are stitched together.&#160;When you work in Premiere Pro, each of these pieces is a clip.&#160;You use multiple different audio and video clips together, crop and edit them, add effects, cuts, and transitions, and finally end up with your completed video.</p><p>Tracks</p><p>So, what are tracks? If you look in the Timeline panel, you will see multiple horizontal rows. These are tracks. You will also notice that there is a thick horizontal line running through the middle. The tracks above this line are all names V1, V2, V3 – these are the video tracks. The tracks below this line are all named A1, A2, A3 – these are all audio tracks. All the video and audio clips that you add to a sequence are added into these respective tracks.</p><p>Along the top of the track, you can see the timeline that shows you the length of the sequence.&#160;The blue marker is the&#160;Current Time Indicator (CTI)&#160;or&#160;playhead.&#160;It shows you your current position in the video preview that is displayed in the&#160;Program&#160;panel.&#160;You can drag the playhead to scroll through the clips.</p><p>You can see that by default, there are three video tracks and three audio tracks.&#160;You can add or remove tracks as required.&#160;When you add multiple videos to the timeline, new video tracks will appear above existing video tracks, whereas new audio tracks will appear below existing audio tracks.</p><p>Let’s assume you are shooting an interview with an actor after the great success of their latest movie.&#160;While preparing the final video, you will add clips of the interview as well as of the movie.&#160;In Premiere Pro, you will be able to stitch these multiple video clips together and add effects, cuts, and transitions, and finally end up with your completed video of the interview.</p></section><section><h3>Managing Tracks</h3><p>Managing Tracks</p><p>Select a Student</p><p>Adding and Deleting Tracks</p><p>You can easily add or delete tracks.&#160;Just right-click the track and select&#160;Add Tracks.&#160;You can enter the number of tracks you want to add and specify where they should be added, and then click&#160;OK.</p><p>Deleting tracks is just as easy.&#160;Just right-click above the tracks and select&#160;Delete Tracks.&#160;You can then either delete all the empty tracks, or specify which tracks you want to delete, and then click&#160;OK.</p><p>Locking and Unlocking Tracks</p><p>When you work with multiple audio and video clips, there is always the chance that you may accidentally move, edit, or delete the wrong clip.&#160;To avoid this, you have the option to lock tracks.&#160;Just click the&#160;lock icon&#160;on all the tracks you want to lock.&#160;Now, none of the assets on this track can be edited.&#160;To unlock the tracks, just click the lock icon once again.</p><p>Expanding Tracks</p><p>The height of all the tracks is editable.&#160;Just scroll over the top edge of a track till the cursor changes to a height-adjustment arrow.&#160;Now just click and drag the track up or down to increase the height.&#160;In case of video tracks, this will reveal a small thumbnail of the video clip.&#160;This is especially helpful in case of the audio tracks, as you can view the full audio waveform in detail.&#160;If you zoom in, this will help you in identifying breaks in the audio and make edits easily.</p><p>Source Patching and Track Targeting</p><p>The concept of source patching and track targeting can be confusing in Premiere Pro.&#160;In most cases, you will not need to use these as there are other ways to edit your video clips.&#160;However, it is always good to be aware of all the tools available so you can choose which methods you are most comfortable with using.</p><p>In the Timeline panel, you will see two columns with numbered video and audio tracks.&#160;The first column is where you control the&#160;source patching, and the second one controls the&#160;track targeting.&#160;These two functions are not related.</p><p>If you do not have any clips selected, you will not see anything in the source patching column.&#160;The source patching column controls where the clips from the Source panel are patched or added onto your timeline.&#160;For example, in some instances, you may want to overwrite other clips on your timeline, or you may want to add new clips onto new tracks.&#160;All of this is controlled by the source patching icons.</p><p>Track targeting is used when you copy and paste clips.&#160;You can use this to control to which tracks the video and audio elements of a copied clip are pasted.</p><p>We’ll learn about both these functions in detail in the next few lessons.</p><p>While creating a video of your favorite beach, you will shoot a number of short videos of the beach and capture its beauty.&#160;Later, while making a complete video you may want to add background music to the video.&#160;You may also want to add a voice-over giving the details of the location and mix it with some background music.&#160;You will be able to add the tracks and patch them in the video using the options available in Premiere Pro.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7e28264de815c2172fd5727e9258fbab','adobe-premiere-pro-m4-l3-lesson-2','5cc0a14d441e16022f9437b874be2c13','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Modify Basic Track Visibility</h3><p>Modify Basic Track Visibility</p><p>Select a Student</p><p>You’ve learned that there are multiple video and audio tracks.&#160;But why do we need so many?&#160;Can’t we add all the videos on one track and all the audio on another?&#160;Multiple tracks are useful in many instances.&#160;For example, you may have one common background music running throughout a video, and also have dialogues spoken over them.&#160;Similarly, you may have a video that has a medium shot of a scene, but you want to show some close-up shots in between.&#160;You can do all of this by layering your tracks.</p><p>While editing more complex videos, this can become quite confusing, as you may be working with so many different clips on multiple tracks.&#160;When you add video clips to your project, you can add them at the end of an existing video clip.&#160;You also have the option to add clips on top of other clips to layer them.&#160;This way, you can transition in and out of other clips.&#160;When you preview your video, only the video frames at the top of the tracks are visible in the&#160;Program&#160;panel.</p><p>To simplify the editing process, you can hide different tracks to view the clips on the other tracks without any obstructions.&#160;You can do this using the&#160;visibility icon, which is an&#160;eye icon&#160;that you can see on the left.</p><p>To show a hidden track, just click the eye icon again.</p><p>So, how do you do the same thing with audio files?&#160;With audio, you have a few different options.&#160;You will notice that the audio tracks do not have the eye icon.&#160;Instead, you will see an&#160;M&#160;and&#160;S button.&#160;The&#160;M&#160;stands for&#160;Mute, which does the same thing that the eye icon does for the video tracks.&#160;It will mute all the audio clips on that track.</p><p>Let’s say you have one background audio clip, and multiple different layered audio and dialogue audio clips layered over it.&#160;If you want to only listen to the background score, you will need to mute all of the other tracks one by one, and this could be quite tedious when you work with large projects.&#160;So, in this case, you can use the&#160;S&#160;or&#160;Solo button.&#160;When you click this the button turns yellow, and only the audio clips that are present on that track will play.&#160;All other tracks will be muted as long as the&#160;S button&#160;is active.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9dd6515f4c21ba16403560028973abe2','adobe-premiere-pro-m4-l4-lesson-3','5cc0a14d441e16022f9437b874be2c13','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Creating a Rough Cut</h3><p>Creating a Rough Cut</p><p>Select a Student</p><p>Now let’s put together all that you have learned so far and put together a rough cut of a video using multiple video and audio clips!&#160;A rough-cut is an initial draft of a video or film where you roughly edit multiple video and audio clips and arrange them together in a logical sequence.&#160;Note that since all edits in Premiere Pro are non-destructive, you can always go back and undo any cuts or edits and adjust as needed.&#160;When you add a clip into the timeline, it creates an instance of the main source clip.&#160;Any edits you make to this clip are not permanent and do not impact the main source clip.&#160;You can drag a single clip onto the timeline multiple times to create multiple instances of the same clip.&#160;This way, you can use different parts of a single clip in different places in your video.</p><p>You have already learned how to import assets and create a sequence in Premiere Pro.</p><p>Note:&#160;Once you create a new sequence, always rename it so that you can easily identify it in your Project panel.&#160;Now, let’s start editing!</p><p>Editing Clips</p><p>A sequence can contain multiple clips.&#160;You can rearrange the position of these clips by just clicking and dragging them along the timeline.&#160;You will see that when you drag a clip next to another clip, it snaps to the end of the clip.&#160;This is very useful when you want to make sure that all clips are aligned correctly and there is no gap left in between.</p><p>When you scroll over the ends of a clip in the timeline, you will see that the cursor changes to a bracket arrow.&#160;If you click and drag the clip left or right, you can crop the beginning or end of a clip.</p><p>As you drag the clip to crop it, you will see a preview of your edit in the&#160;Program&#160;panel.&#160;If there is another clip after the one you are cropping, you will see a preview of both clips.&#160;This is helpful when you want to align the last frame one clip to transition smoothly into the beginning of the next clip.</p><p>Splitting or Cropping Using the Razor Tool</p><p>But what happens if you want to cut out a portion from the middle of a clip?&#160;To do this, you can use the&#160;Razor&#160;tool.&#160;Just select the&#160;Razor&#160;tool from the toolbar.&#160;Then, click the points on the clip where you want to make cuts.&#160;To delete a part of the clip, switch back to the&#160;Selection&#160;tool, select the clip and click the&#160;Delete&#160;key on your keyboard.&#160;You can then drag the individual parts of the clip and rearrange them as required.</p><p>Remember that because edits in Premiere Pro are non-destructive, you can always recover the deleted part of your clips.&#160;Just hover your cursor over the end of the clip and drag it out.&#160;You will see that the part that you deleted has been recovered.</p><p>In and Out Points in the Source Panel</p><p>There is another more efficient way of inserting clips into your timeline using&#160;In and Out points&#160;in the&#160;Source&#160;monitor.&#160;As you already know, you can use the&#160;Source&#160;monitor to preview your clips before you add them to the timeline.&#160;When you preview your clips, you can decide what part of the clip you want to trim out and what part you want to use.&#160;For example, you may have a long pause at the beginning of a video, or a few seconds at the end of the video where you walk towards the camera to shut it off that are unnecessary clips that you want to edit out.&#160;You can use In and Out points in the Source panel to make selections of sections that you want to pull into the Timeline.</p><p>First, play the clip to find a frame where you want your clip to begin.&#160;You can use the&#160;J, K, and L keys&#160;as well as the spacebar on your keyboard to speed up, pause, or rewind the clip.&#160;You can also drag the blue playhead along the timeline to quickly scrub through the clip.</p><p>Now, click the&#160;Mark In&#160;icon (which looks like an open curly bracket) in the Source panel to mark where you want the clip to start.&#160;You can also use the keyboard shortcut&#160;I.</p><p>You will see that all of the clip from the In point until the end of the clip is highlighted.&#160;Now, in the same way, select an out point for your clip and click the&#160;Mark Out&#160;icon or use keyboard shortcut&#160;O.</p><p>The timer on the right will show you the duration of the In/Out clip that you marked out.&#160;You can drag the ends of the highlighted In/Out clip to adjust the length of your clip.&#160;Now, when you insert this clip into your timeline, only the section that you have marked out will be inserted into the timeline.</p><p>You can perform this action in advance for all your clips and then add all of them to the timeline.&#160;This is an efficient way of editing your clips for a rough cut as you are marking out all your edits before they are added to the timeline, thus saving you the time you may have wasted in cropping and re-aligning all the clips one by one in the timeline.</p><p>Insert and Overwrite</p><p>You already know how to drag and drop clips onto the timeline from the Project panel.&#160;Another way of doing this is to use the&#160;Insert (,)&#160;and&#160;Overwrite (.)&#160;icons in the Source panel.&#160;You can also use the keyboard shortcuts to access these functions.&#160;What do each of these icons do, and how do they differ?</p><p>There are many different ways in which you may want to add clips to a timeline.&#160;When you drag and drop a clip onto the timeline, you can place it anywhere you want.&#160;You can place a clip before or after another clip, or even overlap over an existing clip.&#160;When you overlap a clip over another clip, one of two things can happen:</p><p>Click each term to learn more.</p><p>Next Tab</p><p>Overwrite Edit</p><p>Here, the part of the new clip that overlaps the existing clip replaces it.&#160;For example, you may have seen videos where a person is talking about something and the video cuts to a clip that shows what the person is talking about in the audio.&#160;You can use this function by clicking the Overwrite icon in the Source panel.</p><p>Insert Edit</p><p>Here, the new clip is inserted in between an existing clip. In this case, the existing clip is split at the point where you insert the new clip. For example, you may have shot a scene from different angles and<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('487ec8f45edbd7e857929d88da0cacdc','adobe-premiere-pro-m4-l5-lesson-4','5cc0a14d441e16022f9437b874be2c13','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Nesting Sequences</h3><p>Nesting Sequences</p><p>Select a Student</p><p>Now that you have an idea of creating a rough cut of a video and performing basic edits to a video, let’s look at a few useful tools you can use to manage sequences in a complex project.</p><p>Nesting is the process of grouping different clips or sequences into one sequence.&#160;This function is especially useful when you work with large, complex projects with multiple clips and sequences.&#160;Some of the benefits of nesting clips or sequences are as follows:</p><p>Click each term to learn more.</p><p>Reusing sequences</p><p>You can group different clips or sequences together and reuse them at different points in your video.</p><p>Apply effects</p><p>You can easily apply effects to all the clips in a sequence or multiple sequences by nesting them and then applying the effect only once to the nested sequence.</p><p>Applying multiple effects</p><p>Sometimes, if you have already applied an effect to a clip, and then try applying another effect on the same clip, you will get an error. If you nest this clip, it will appear as an un-edited nested sequence to Premiere Pro and allow you to apply another effect to the clip.</p><p>Apply different effects to copies</p><p>You can copy a nested sequence multiple times in a video, and you can also apply different effects to each copy of the nested sequence.</p><p>Organizing the timeline</p><p>Nested sequences are also a great way to streamline and organize your timeline. This also helps you to avoid moving or deleting clips by mistake.</p><p>It is very easy to nest clips or sequences.&#160;Just select all the elements on your timeline that you want to nest, right-click the selection and select&#160;Nest.&#160;Name your nested sequence and click&#160;OK.</p><p>You can open your nested sequence at any time by double-clicking it in the timeline panel.&#160;Here you can see all the different clips within this nest.&#160;You can now apply any effects that you want to this nested sequence, copy and paste it multiple times in your video, and more.</p><p>Nesting sequences is a great way to keep your projects organized.&#160;It also helps make large projects feel less overwhelming to edit.&#160;However, it is always recommended to make a copy of your clips before nesting them together.</p><p>Imagine you are preparing a travel video showing your adventures during a trip.&#160;You have hours of footage from various sites you visited, and you want to make a video that highlights the best moments from your trip.&#160;You can create separate nested sequences for each location rather than editing each clip separately on the main timeline.&#160;Select all the clips that you want to nest, right-click, and select Nest.&#160;Name your nested sequence and click OK.</p></section><section><h3>Multi-Camera Source Sequence</h3><p>Multi-Camera Source Sequence</p><p>Select a Student</p><p>Premiere Pro makes it very easy for you to edit videos shot on multiple cameras without having to cut and crop clips from each source clip multiple times.&#160;Let’s say you are editing a wedding video that was shot on multiple cameras.&#160;The audio for all of these clips will, in all probability, be the same across all clips, with just the camera angles differing.&#160;Let’s see how you can edit all these multiple camera source clips in one shot.</p><p>In this video, we’ll learn how to create a multi-camera source sequence.</p><p>First, we have imported all of our videos into the&#160;Project&#160;panel, and created a new bin using these clips. Now, select and right-click the bin and select&#160;Create Multi-Camera Source Sequence. This popup appears, where you can rename your new sequence. I’ll leave the name as it is. If the clips in your sequence have the same audio that you want to use to synchronize the clips, then you can select&#160;Audio. If you want to synchronize by In or Out points, or even by Timecode, you can select those options as well. Note that if any of your video clips do not contain audio, or if there is an audio mismatch, you will get an error message and you cannot create this sequence. You can leave all the other settings as they are for now and click&#160;OK.</p><p>Now you will see two new files that have been created in your Project panel – a new multi-cam sequence, and a&#160;Processed Clips&#160;folder. You can rename this new sequence by double-clicking it. Now that you have created this multi-cam sequence, you can either drag and drop this into the timeline or right-click it and select&#160;New Sequence from Clip. You will see the preview of the new sequence in the Program monitor. You may notice that only one clip appears here. Don’t worry, this isn’t a mistake. You just need to change the view in the Program monitor. So, click the plus icon (and I have already done this beforehand) and drag and drop the&#160;Toggle&#160;Multi-Camera View&#160;icon onto the toolbar. And click the ok button. Now, if you click this icon, you will see a split view. On the left, you can see all the clips in your sequence, and on the right, you can see a preview of the sequence – by default this will show you the first video in the sequence.</p><p>Now, if you scrub through the video using the blue playhead, you will see that different videos appear and disappear at different times. This just means that the lengths of the videos are different and when the parameter that you selected (that is, audio, or in and out time, etc.) are synchronized, this is the order in which the videos appear. The yellow outline shows you which video clip is active. You can click each video clip to view a preview of that video. Also, notice that there is also a yellow line that appears along the top of the timeline panel, which acts as an indicator of the length of each clip that is selected.</p><p>Now, how do you go about editing these videos? Premiere Pro automatically numbers these clips in the order that they appear in the Program panel. So, this first video is 1, second is 2, third is 3, and so on. Let’s move the playhead to the beginning and press spacebar to play it. You can see all the 5 videos playing here.</p><p>Premiere pro allows you to edit all 5 videos simultaneously. The idea is that once you press spacebar and start playing the videos, you can click on the video that you want clips to appear from. And Premiere Pro will cut and arrange these clips in that order.</p><p>So let’s say I select this <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('25e827cb5d41e430fedf75af590f30dc','adobe-premiere-pro-m4-l6-lesson-5','5cc0a14d441e16022f9437b874be2c13','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Automating to Sequence</h3><p>Automating to Sequence</p><p>Select a Student</p><p>Premiere Pro allows you to automate sequences so you can easily create a sequence of video clips synchronized to an audio file, easily create slideshows, or even time-lapses.&#160;Always start by keeping all of your clips organized so that all the clips or images you want to automate are in the same folder.&#160;Also, remember to mark out the in and out points for all your video clips so that they are all ready to be imported and automated into a sequence.</p><p>Next, organize the files in your bin in the order you want them to appear in the timeline.&#160;You can do this by either sorting by one of the headings provided here or switching to the Icon view and dragging your items to rearrange them in the right order.</p><p>Now, let’s say you have one audio file, and you want to insert all your video clips sequentially to the beat of the music.&#160;Start by creating a new sequence and dragging your music track onto the timeline.&#160;Now, you can use the&#160;M&#160;key to place markers at the different spots on the audio track where you want to insert your video clips.&#160;Just play the audio file and press the&#160;M&#160;key at each breakpoint.</p><p>Once you are done, you are ready to insert your video clips.&#160;Open the bin containing the video clips you just organized.&#160;If you have already arranged them in the order that you want them to appear, just select all the videos.&#160;If not, you can select each clip one by one in the right order while pressing and holding down the&#160;Ctrl&#160;or&#160;Command&#160;key.&#160;Then, click the&#160;Automate to Sequence&#160;icon at the bottom of the&#160;Program&#160;panel.</p><p>You will see a popup with multiple options.&#160;You can select the order in which the clips should be added.&#160;In this case, since we have created markers, you can select the placement method as&#160;At Unnumbered Markers&#160;so that each video clip will be placed at the markers you created.&#160;Since we are using an audio file, make sure you use&#160;Overwrite Edit&#160;so that the video clips appear over the audio file and don’t get inserted in between the audio.&#160;You can also set the clip duration to either use the In/Out points you defined, or set it to a fixed number of frames.&#160;Once you are done, click&#160;OK.&#160;All your clips will be added to the timeline and be aligned to the markers you created.</p><p>Similarly, you can also create a sequence using images to synchronize images to an audio file or create a timelapse using a series of timelapse images.&#160;Follow the same steps to organize your files and automate the sequence.&#160;In the case of a timelapse, you can change the settings to show 1 frame per second and turn off all transitions.&#160;If you are synchronizing images to an audio clip, you can include default image transitions or align images to markers as well.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4f5b8578bf336a1757396af208fdfeaf','adobe-premiere-pro-m4-l7-module-4-summary','5cc0a14d441e16022f9437b874be2c13','Module 4 Summary','text',12,'<h2>Module 4 Summary</h2><section><h3>Module 5 Summary</h3><p>Summary</p><p>Select a Student</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Project Setup and Interface Part I!</p><p>Make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Used the Timeline panel to manage video and audio tracks.</p><p>Modified basic track visibility and audio levels.</p><p>Created a video rough-cut using a variety of tools and panels.</p><p>Managed sequences in a complex project.</p><p>Placed images and video into a sequence.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('95321d5d6392f4844ca4ac19ff81e4f8','adobe-premiere-pro-m4-l8-module-4-project','5cc0a14d441e16022f9437b874be2c13','Module 4 Project','text',12,'<h2>Module 4 Project</h2><section><h3>Module 4 Project</h3><p>Adobe Premiere Pro</p><p>8100</p><p>Organizing, Creating and Modifying Visual Elements Part I - Project</p><p>Project</p><p>In this assignment, you will apply all that you have learned about organizing, creating, and modifying visual elements in Premiere Pro to perform the following tasks. You will need to use Premiere Pro to perform these tasks. In some of these tasks, you may need to take screenshots and label them as well. You can save the screenshots as images or add them all to a Word/PPT document.</p><p>Open the Premiere Pro project that you created in the last module project. Add 2 video tracks and 2 audio tracks to the Timeline.&#160;(Take a screenshot once this task is complete.)</p><p>Make sure you have imported and organized at least 5 video clips and 2 audio clips. Mark out the in and out times in all the video clips. Next, add one audio file to the Timeline panel and add markers where you want to add the videos.&#160;(Take a screenshot once this task is complete.)</p><p>Use the Automate to Sequence option to add videos to the Timeline. You can now use the Razor tool to make any edits if needed in any of the clips.&#160;(Take a screenshot once this task is complete.)</p><p>Use the Overwrite option to add another video clip onto the timeline.&#160;(Take a screenshot once this task is complete.)</p><p>Select some clips to create a nested sequence.</p><p>Once you are done with all the tasks, save your Premiere Pro project for review.</p><p>Organizing, Creating and Modifying Visual Elements Part I Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Use the Timeline panel to manage video and audio tracks.</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Modify basic track visibility and audio levels.</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Create a video rough-cut using a variety of tools and panels.</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Manage sequences in a complex project.</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Place images and video into a sequence.</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('492a44e1b94d279c752703dfe6a90214','adobe-premiere-pro-m4-l9-module-4-quiz','5cc0a14d441e16022f9437b874be2c13','Module 4 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Visual Elements Part 1. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('d643056c314cd2a57f77941302d99097','adobe-premiere-pro-module-5','48ab1932af65ef3f9d0793cd5a02da34','Module 5: Visual Elements Part 2',5) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('135825bfc986a0bc23a3c82777b6f67b','adobe-premiere-pro-m5-l1-introduction-purpose-and-objectives','d643056c314cd2a57f77941302d99097','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Select a Student</p><p>Hey there! Welcome back to another module. You’ve covered a lot of ground in your Premiere Pro journey so far. You’ve learned some essential basics about the video design industry, you’ve learned to navigate around the Premiere Pro interface and set up a project, and you’ve also learned how to organize your assets and create a rough cut of a video.</p><p>In this module, we’ll dive into another key visual element in your videos – titles and text! Typography is a key aspect of your designs. Use the comprehensive tools in Premiere Pro to add and animate titles, text, and basic shapes to your video. Adobe gives you free access to thousands of beautiful fonts to choose from. Premiere Pro is packed with loads of preset text layouts, fun effects, and different text treatments that you can apply to your projects.</p><p>We’ll also look at various other ways in which you can trim and refine your clips to polish your rough-cut video clips. You’ll learn to speed up videos to create time-lapses, or add slow-motion effects, or even change the direction of a video clip. We’ll also discuss various ways in which you can adjust the audio in a video. So let’s get started!</p><p>Module Description</p><p>Select a Student</p><p>In this module, students will learn how to add and animate titles, text and shapes in a video.&#160;They will learn how to use the various tools available in Premiere Pro to trim footage, refine edits and resize clips.&#160;Students will also learn how to modify different clip settings to adjust the speed of a video.&#160;Finally, students will learn to adjust the audio settings of a video as well.</p><p>Objectives</p><p>Select a Student</p><p>In this module, students will:</p><p>Add and animate titles and modify title properties including creating superimposed text and shapes in a video sequence, using appropriate character and paragraph settings in a title, and animating title elements.</p><p>Trim footage for use in sequences including resizing clips using a variety of tools.</p><p>Modify and refine clip trims using various methods.</p><p>Modify clip settings and change the speed or direction of a video clip.</p><p>Adjust the audio of a video clip.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0cb0491e608dad1fcb93f21e94a88241','adobe-premiere-pro-m5-l2-lesson-1','d643056c314cd2a57f77941302d99097','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Adding Titles and Shapes</h3><p>Adding Titles and Shapes</p><p>Select a Student</p><p>Premiere Pro allows you to add and animate text and titles to your videos.&#160;The best way to do this is using the&#160;Graphics&#160;workspace and the&#160;Essential Graphics&#160;panel.&#160;Both these features contain multiple preset templates and detailed settings that allow you to create titles, add text and graphics, as well as animate all these elements from one location.</p><p>You can open the Graphics workspace by clicking&#160;Graphics&#160;in the workspace bar.&#160;If it is not visible, just click&#160;Window, select&#160;Workspaces, and click&#160;Graphics.&#160;By default, the Graphics workspace contains the Essential Graphics panel on the right.&#160;If you don’t see this, you can easily enable it by clicking&#160;Window&#160;and selecting&#160;Essential Graphics.</p><p>The Essential Graphics panel has two main tabs –&#160;Browse&#160;and&#160;Edit.</p><p>Browse tab</p><p>Edit tab</p><p>The&#160;Browse&#160;tab contains all of the preset graphic templates available in Premiere Pro.&#160;There are basic templates available in the My Templates tab, as well as numerous free and paid templates available on Adobe Stock.&#160;You can search for templates in either of these tabs using keywords.</p><p>The&#160;Edit&#160;tab is where you will edit and adjust the properties of the text and graphics that you add to your project.&#160;Note that graphics are organized in layers, and each graphic element can contain multiple layers of text and shapes.</p><p>Adding Text</p><p>Let’s see how you can easily add text to your project.&#160;You can do this in two ways:</p><p>Using the Type Tool</p><p>Using preset templates in the Essential Graphics panel</p><p>Start by positioning the playhead where you want to insert the text.&#160;Now, you can use the&#160;Type Tool&#160;in the toolbar, click anywhere in the Program Monitor, and type the text you want to enter.</p><p>You can also take advantage of the multiple preset templates available in Adobe Premiere Pro.&#160;Just search for the type of text you want to add in the&#160;My Templates&#160;tab.&#160;For example, let’s search for “title”.&#160;Now, if you want to insert this text over an existing video clip, then you can select and drag it to a track above the clip.</p><p>If you want to add the text in between clips or before a clip begins, press and hold the&#160;Ctrl&#160;or&#160;Command&#160;key as you drag the title to the timeline.&#160;This will shift the clips and insert the title before the clip without overwriting it.</p><p>Once you have added a text box to your project, click it to edit the text.&#160;You will see a number of different settings appear in the&#160;Edit&#160;panel.&#160;Double-click the box and type in the text.&#160;Then, select the box or the text and adjust all of these settings as required.</p><p>There are many creative ways in which you can incorporate text into your videos.&#160;Here are some examples:</p><p>Next Tab</p><p>Contrast</p><p>Always be mindful of the font color of the text you are using in relation to the colors in the video in the background.&#160;For example, if you are working on a video that was shot at night, and you use black text, it will not be visible.&#160;Also think of the duration for which the text is going to be visible on the screen, and what changes are going on during that time in the video in the background.&#160;You can also use solid-colored shapes behind your text to make it stand out more.</p><p>Text Placement</p><p>Location is everything! Think of where you are placing the text - will you choose to center the text or put it in the lower third? Remember that anything that you display front and center in your video will indicate that it is important, so ideally you should only center align things like title text. Use safe margins to ensure that you are placing text within the safe bounds of the video.</p><p>Fonts and Typography</p><p>There is a whole world of fonts that you can choose from. Adobe has a large library of fonts that are available for use, and you can also choose to download customized fonts from various online sources. You can combine different types of fonts for a more stylish approach. However, as a rule, avoid using more than three different types of fonts at a time. You can experiment with different font colors, styles, opacity, and other characteristics like spacing and boldness. Whichever approach you choose, it is important to keep your fonts consistent throughout your video as well.</p><p>Be Mindful of Tone</p><p>If you are creating a video of a birthday celebration, you wouldn’t use sad background music, right? Similarly, the type of font you use should also match the tone of the video. For example, if you see Comic Sans font being used in a news reporting, you wouldn’t be able to take them seriously! Adjust the type of font you use based on the tone you are going for in your video. For example, Sans Serif fonts usually look more modern than Serif fonts, and can have different applications.</p><p>Creativity</p><p>Finally, don’t be afraid to explore various creative ways to use fonts in your videos. For example, you can use masking to incorporate text into your video by making it look like the video is playing in the letters of the font over a solid background. You can animate your font and synchronize it with the audio or movements in the video</p><p>Essential Graphics Panel Settings</p><p>Let’s go over the different settings available here.</p><p>Click each term to learn more.</p><p>5</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Screenshot of the Essential Graphics panel with the following sections highlighted in red: Layers, Align and Transform, Styles, Text, and Appearance</p><p>The hotspot points on the image are as follows:</p><p>Layers</p><p>Shows the different text layers in the graphic</p><p>Align and Transform</p><p>Contains settings to align the elements on the video stage</p><p>Styles</p><p>Similar to Styles in other word processing applications, you can define Styles that can be reused in other projects</p><p>Text</p><p>Contains all the text editing and formatting settings</p><p>Appearance</p><p>Contains the color settings for the text that you add</p><p>Let&#39;s look at each of these in more detail.</p><p>Layers</p><p>The top section shows the different te<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c4056e8679097f326d91ee289a7c1f7e','adobe-premiere-pro-m5-l3-lesson-2','d643056c314cd2a57f77941302d99097','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Trimming Footage by Resizing Clips</h3><p>Trimming Footage by Resizing Clips</p><p>Select a Student</p><p>Aspect Ratios</p><p>The aspect ratio of a video is the ratio of the width of the video to the height of the video.&#160;Based on the recording standards used to record the video, different videos can have different aspect ratios.&#160;For example, most videos are shot in either a 4:3 or 16:9 aspect ratio.&#160;Nowadays, you also have videos shot on the phone in a 1:1 aspect ratio for use on Instagram or vertical videos made using other mobile apps.</p><p>When you work with multiple video clips, there is a chance that different video clips use different aspect ratios.&#160;Other assets like images can also have different aspect ratios.&#160;Because of this difference in aspect ratio, they may appear distorted when they are all imported into a sequence.</p><p>Premiere Pro is smart – it automatically tries to compensate for the difference in the pixel aspect ratios.&#160;But, if you still see any distortions, you can manually specify an aspect ratio for each file.</p><p>Setting Aspect Ratio for Sequences</p><p>When you create a sequence, you can adjust the&#160;sequence settings&#160;and set a common aspect ratio for all the clips in that sequence.&#160;To do this, just right-click the sequence and select&#160;Sequence Settings.&#160;Alternatively, if you use the&#160;New Sequence&#160;button, open the&#160;Settings&#160;tab.</p><p>Here, you can specify the frame size and aspect ratio of all the elements in that sequence.</p><p>Scaling from Effects Control Panel</p><p>There may be instances where you need to scale the video to crop out unwanted parts of the video.&#160;For example, let’s say you have video clips of a tutorial on using a computer application.&#160;These video clips, unfortunately, also show you the bottom toolbar of your computer, as well as the header of the web browser you used in the tutorial.&#160;To hide these parts of the video and make the video look more streamlined and neater, you can use the&#160;Scale&#160;function in the&#160;Effects Control&#160;panel.</p><p>Select the video that you want to scale and click the&#160;Toggle animation&#160;icon for&#160;Scale.&#160;Now, you can click and drag your cursor left or right on the number to increase or decrease the scaling.&#160;Once you are happy with the scaling, you can preview the video to take a look at the edits.</p><p>Letterboxing</p><p>When you find that two different media files have different aspect ratios, there is another way in which you can reconcile the different values.&#160;For example, if you have a video recorded with a 4:3 aspect ratio and another clip recorded with a 16:9 aspect ratio, the sequence will leave a black band above and below the video.&#160;This is called&#160;letterboxing.&#160; You can eliminate these black bars by adjusting the scale like we just discussed.&#160;You may have seen these black bars when you watch some older movies.</p><p>You have shot a video using a professional camera that records in a 16:9 aspect ratio.&#160;However, you want to upload the video to Instagram, which uses a 1:1 aspect ratio.&#160;You can easily do it by simply adjusting the scales.</p><p>Pan and Scan</p><p>This is another technique you can use when your source files have one aspect ratio, but you need to publish your video in a different aspect ratio.&#160;In this case, you can pan the horizontal position of a larger frame within a smaller one so that the important action is always displayed.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7c7a027238dc38f3c48cbc74fca4410d','adobe-premiere-pro-m5-l4-lesson-3','d643056c314cd2a57f77941302d99097','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Editing Clips</h3><p>Editing Clips</p><p>Select a Student</p><p>You have already learned about the basic tools that you can use to edit and trim your video clips.&#160;Now, let’s take a look at some more methods and tools that you can use to refine your clip trims in Premiere Pro.</p><p>Adjusting In and Out Points</p><p>You have learned how to set in and out points for your video clips.&#160;You can easily adjust the in and out points of footage that you have already inserted onto the timeline.&#160;Double click the clip on the timeline.&#160;It will appear in the&#160;Source&#160;panel and you can see the&#160;In and Out points&#160;marked out.</p><p>If you scroll over the middle of the&#160;In/Out bar, you will see the cursor changes to a hand.&#160;Now, you can click and drag this selection across the timeline of this clip to adjust the position of the In/Out points.&#160;You can also click and drag the ends of the In/Out points in or out to increase or decrease the duration of the clip.&#160;You will see that the changes are reflected in the clip in the&#160;Timeline&#160;panel as well.</p><p>J-Cuts and L-Cuts</p><p>These cuts are used to edit the transitions of audio and video from one clip to another.&#160;You have learned the basics of J cuts and L cuts earlier in this course.&#160;Now, let’s take a look at how these edits are made.</p><p>A J-cut introduces the audio of the next scene before the visuals of the next scene appear.&#160;An L-cut on the other hand continues the audio of a scene into the beginning of the next scene.</p><p>Welcome to this video on Editing Clips with J-Cuts and L-Cuts!</p><p>Here, we have a project with a few clips that contain both video and audio. Let’s start with J-cuts. First, let’s snap the second clip to the end of the first clip. Now, for a J-cut, we want the audio for the second scene to start in the end of the first scene. So, for this, we need to first overlap the two videos. Drag the second video over the last few seconds of the first video. Now, to make a J-cut, we need to trim only the video part of the second video. To do this, you first need to unlink the video and audio of the second clip. Select the clip, right-click and select Unlink. Now, in the toolbar, select the Rolling Edit tool. So, press and hold the Ripple Edit tool and you can select the Rolling Edit tool. Now, you need to hold down the Alt or Option key on your keyboard and drag the beginning of the second video clip out to the end of the first video clip. So, I’m holding down the alt key, and I’ve dragged out the video until it has snapped to the end of the first video clip.</p><p>You can now add an audio effect to smoothen out the transition. This is how you can do a J-cut in end of the first clip itself.</p><p>Now, let’s look at an L-cut. Once again, you can make sure the two clips are snapped together. This time, we want the audio of the first clip to trail into the beginning of the second clip. This time, move the first clip to overlap a few seconds of the second clip. Then, make sure the audio and video of the first clip are unlinked. Now, just use the Rolling Edit tool again along with the Alt or Option key to drag the video portion of the second clip so it overlaps the first clip. This is how you can create an L-cut in Premiere Pro.</p><p>When switching between locations, you may use a J-Cut to display the new location&#39;s sound before exposing the visuals.&#160;For example, if a character is moving from a busy city street to a library, the background sounds of the library may begin before the visuals in the video change.&#160;An L-Cut can be used in a scene when two characters have a conversation to highlight the listener&#39;s emotional response and build tension by showing their response before they begin speaking.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2731c1f1828b7e242a34fd05d0f88d37','adobe-premiere-pro-m5-l5-lesson-4','d643056c314cd2a57f77941302d99097','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Clip Settings</h3><p>Clip Settings</p><p>Select a Student</p><p>Let’s take a look at a few modifications that you can make that will help you work more efficiently in Premiere Pro.</p><p>Setting Poster Frame</p><p>We have already discussed the importance of organizing your media files by renaming them and organizing them into bins.&#160;Another challenge you may face when you work with multiple video clips is not being able to identify what each clip contains by just looking at the thumbnail.&#160;By default, the thumbnail in the&#160;Icon View&#160;of the&#160;Project&#160;panel shows you the first frame of the video.&#160;In many instances, this can be a blank white or black frame that doesn’t really tell you what is inside the video clip.&#160;You can change this thumbnail – or poster frame – with just a few simple steps.</p><p>When you view your clips in the&#160;Icon&#160;view, you can scrub through the video by running your cursor from left to right.&#160;You can also use the&#160;J, K, and L keys&#160;to speed through the video and preview it.&#160;Use one of these methods and scrub through the video to a frame that you think is a good representation of that clip.&#160;Then, right-click the clip and select&#160;Set Poster Frame.&#160;The frame you stopped at will be set as the poster frame for that thumbnail.&#160;You can repeat this process for all the video clips in your project.&#160;Doing this will save you a lot of time during the editing process.</p><p>Creating Proxies</p><p>A lot of the videos that you work with in Premiere Pro may be very heavy files, especially if they are 4K or 8K videos.&#160;These heavy videos can put a huge load on the processing power of your computer and cause lags or delays in the editing process.&#160;To avoid this, you can create lower-resolution, proxy versions of the video clips in your project.&#160;These serve as stand-ins for the full-resolution clips and allow you to work smoothly without any lags.&#160;Once you have finished your edits, you can then easily apply those same changes to the original full-resolution clips and export them when you are done with your project.</p><p>To create proxies, simply select the video clips in your&#160;Project&#160;panel, right-click them, select Proxy, and click&#160;Create Proxies.&#160;You will see a popup.&#160;Here, you can choose the format and preset for your proxy.</p><p>We can keep these to a low-resolution proxy.&#160;Make sure you save the proxy file next to the original file and click&#160;OK.&#160;The proxies will be created.&#160;Now, in your&#160;Program&#160;panel, select the&#160;Plus&#160;icon, and then drag and drop the&#160;Toggle Proxies&#160;icon onto the toolbar.&#160;You can use this icon to switch between the full-resolution and proxy versions of your clip.</p><p>This is how you can use proxies to speed up your editing process in Premiere Pro.</p></section><section><h3>Video Speed</h3><p>Video Speed</p><p>Select a Student</p><p>Premiere Pro allows you to change the speed and duration of one or more clips in your project at a time.</p><p>What is video speed?</p><p>What is video duration?</p><p>The speed of a clip refers to the rate at which it is played versus the rate of the original video.</p><p>The duration refers to the length of the clip from the In point to the Out point.&#160;You may set a fixed duration for a video clip and then have the video speed up or slow down to fill the required duration.</p><p>There are a few different functions you can use to control these settings:</p><p>Clip Speed/Duration setting</p><p>Rate Stretch tool</p><p>Time Remapping setting</p><p>Let’s take a look at each one in turn.</p><p>Clip Speed/Duration</p><p>You can access the&#160;Clip Speed/Duration&#160;function in a few different ways.&#160;Begin by selecting one or more clips.&#160;You can then click&#160;Clip&#160;in the menu bar and select&#160;Speed/Duration.&#160;Alternatively, just right-click on the selected items and select&#160;Speed/Duration.</p><p>In the popup, you can see all the speed and duration settings for the clip.&#160;You can see that the speed and duration are linked.&#160;This means that if you slow down the clip speed, the duration automatically increases.&#160;Similarly, if you reduce the duration of the clip, the speed increases.</p><p>If you want to change either of these parameters without affecting the other, click the&#160;link icon&#160;to un-link them before you modify the values.&#160;Note that if you unlink the values and decrease the speed of a clip, the part of the clip that exceeds the duration will be edited out.&#160;If you try to increase the speed of a clip, you will see that this is not possible.&#160;This is because for the speed to increase, the duration MUST decrease, which is not possible since the values are unlinked.</p><p>The same goes in the case of only modifying the duration – you can only decrease the duration, which will crop the video.&#160;You cannot increase the duration, as this would mean that the video would need to be slowed down, which is not possible since the values are unlinked.</p><p>Also note that once you unlink the values, they will remain unlinked for all future clips you may modify the&#160;Speed/Duration&#160;for.&#160;So, make sure to check if the values are linked the next time that you make any modifications.</p><p>You can select the&#160;Reverse Speed&#160;checkbox to play the clip backward.&#160;If your video clip also has audio, you can select the&#160;Maintain Audio Pitch&#160;checkbox to keep the audio component at its current pitch even when you make changes to the speed or duration.</p><p>When you make changes to speed or duration, the size of the video clip may increase or decrease on the timeline.&#160;If you have other clips following the edited clip, you can select the&#160;Ripple Edit, Shifting Trailing Clips&#160;checkbox to ensure that all the following clips remain snapped to the edited clip and are shifted on the timeline.</p><p>Let’s assume you are editing the video of a football game that took place last night.&#160;The game was intense and full of exciting moments.&#160;You want to highlight a few of the exciting moments to make it more engaging for viewers.&#160;Here, you can reduce the speed of the video to draw the viewer’s attention to show the skills of the player.</p><p>Rate Stretch Tool</p><p>The Rate Stretch tool is a quicker way of changing the speed and duration of a c<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('18a20a23b72326c5e02b42dd3a185f37','adobe-premiere-pro-m5-l6-lesson-5','d643056c314cd2a57f77941302d99097','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Audio Editing</h3><p>Audio Editing</p><p>Select a Student</p><p>Now, let’s talk about audio.&#160;As you know, all of the audio tracks that are either linked to your video clips or added independently to your project appear on the audio tracks below the video tracks on the timeline.</p><p>Audio Volume</p><p>Volume is the output level of an audio clip.&#160;It controls the loudness of a clip, not the tone.&#160;One of the most basic edits you will need to make for audio is to adjust the volume.&#160;This is especially important when you are working with multiple audio clips which can all have varying volumes.&#160;Before you begin adjusting the volume of the audio, expand the track so you can see the full audio waveform clearly.&#160;The audio waveform is a visual representation of the audio and shows you the high and low points within each audio clip.&#160;You will notice that there is a horizontal line running through the middle of the waveform.&#160;This is an indicator of the base audio level.&#160;You can drag this line up or down to increase or decrease the volume of the clip.</p><p>Premiere Pro also allows you to increase or decrease the volume of a clip at different points using&#160;audio keyframes.&#160;To create a keyframe, press and hold down the&#160;Ctrl&#160;or&#160;Command&#160;key and click on the audio level.&#160;You can create multiple keyframes at all the points where you want the audio level to vary.&#160;You can then drag the keyframes higher to increase the volume or lower to reduce the volume.&#160;You can also move the keyframe left or right to adjust its position in the clip.</p><p>Audio Gain</p><p>Audio gain is the input level of an audio clip, which is the level of the audio going into the system.&#160;It measures how loud the input of the channel is and controls the tone and not the loudness of an audio clip.&#160;You can adjust the audio gain for one or more clips using the Normalize command.&#160;To do this, select the clip or clips that you want to normalize.&#160;Select&#160;Clip,&#160;Audio Options, and click&#160;Audio Gain.</p><p>If you have selected multiple clips, Premiere Pro simplifies the process for you by automatically calculating the peak amplitude of these clips.&#160;You can use this as a reference to adjust the gain value by a specific amount, or you can choose to normalize all the peaks to a specific value and click&#160;OK.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('141e7f5811dc1a43777f3602d0ad8ce3','adobe-premiere-pro-m5-l7-module-5-summary','d643056c314cd2a57f77941302d99097','Module 5 Summary','text',12,'<h2>Module 5 Summary</h2><section><h3>Module 5 Summary</h3><p>Summary</p><p>Select a Student</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module&#160;on Organizing, Creating, and Modifying Visual Elements Part II!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Add and animate titles and modify title properties including creating superimposed text and shapes in a video sequence, using appropriate character and paragraph settings in a title, and animating title elements.</p><p>Trim footage for use in sequences including resizing clips using a variety of tools.</p><p>Modify and refine clip trims using various methods.</p><p>Modify clip settings and change the speed or direction of a video clip.</p><p>Adjust the audio of a video clip.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3eaf5db8f35a1567e8ecda08c5c56741','adobe-premiere-pro-m5-l8-module-5-project','d643056c314cd2a57f77941302d99097','Module 5 Project','text',12,'<h2>Module 5 Project</h2><section><h3>Module 5 Project</h3><p>Adobe Premiere Pro</p><p>8100</p><p>Organizing, Creating and Modifying Visual Elements Part II - Project</p><p>Project</p><p>In this assignment, you will apply all that you have learned about organizing, creating, and modifying visual elements in Premiere Pro to perform the following tasks. You will need to use Premiere Pro to perform these tasks. In some of these tasks, you may need to take screenshots and label them as well. You can save the screenshots as images or add them all to a Word/PPT document.</p><p>Open the Premiere Pro project that you created in the last module project. It&#39;s time to add some shapes and text to your project! Be creative and make use of all the different formatting options available in the Essential Graphics panel. Add at least 1 shape and 2 text boxes. Keep in mind the useful tips that you learned about using text in videos. (Take a screenshot once this task is complete.)</p><p>Next, it is time to add some animation to the text. Apply different effects to each text box using keyframes.&#160;(Take a screenshot once this task is complete.)</p><p>Next, you need to refine your edits. Use J-cuts, L-cuts, and adjust the in and out points of the clips.&#160;(Take a screenshot once this task is complete.)</p><p>Set poster frames for all the clips.&#160;Use any two methods to adjust the speed and duration of two of the clips.&#160;(Take a screenshot once this task is complete.)</p><p>Use keyframes to adjust the audio volume and gain.</p><p>Once you are done with all the tasks, save your Premiere Pro project for review.</p><p>Organizing, Creating and Modifying Visual Elements Part II Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Add and animate text and shapes</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Trim footage</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Modify and refine clips</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Modify clip settings, speed, and duration</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Adjust audio of a video clip</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c07a8757e00b24b43bfced5a9d43806f','adobe-premiere-pro-m5-l9-module-5-quiz','d643056c314cd2a57f77941302d99097','Module 5 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Visual Elements Part 2. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('d6d7e708e98fb3d1ff80cf7500af345d','adobe-premiere-pro-module-6','48ab1932af65ef3f9d0793cd5a02da34','Module 6: Visual Elements Part 3',6) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4080be30a38068249de0611b1234e605','adobe-premiere-pro-m6-l1-introduction-purpose-and-objectives','d6d7e708e98fb3d1ff80cf7500af345d','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Select a Student</p><p>Hi and welcome back to another module. Let’s quickly recap what we’ve learned so far. You’ve learned some essential video basics, you’ve learned to navigate around the Premiere Pro interface and set up a project, and you’ve also learned how to organize your clips using sequences.</p><p>This module will give you an insight into the power of effects, transitions, and motion effects in Premiere Pro. If you can dream it, you can create it! Premiere Pro has a large bank of effects and transitions that you can use to enhance your videos, create smooth transitions, and add stylistic features to all of your clips.</p><p>Learn to fine tune-your video effects to give them a clean, professional look and feel. You can even create your own custom preset effects and transitions that you can use and reuse for multiple projects.</p><p>So let’s get going!</p><p>Module Description</p><p>Select a Student</p><p>License:&#160;All Rights Reserved</p><p>Premiere Pro is a haven for the creative mind, and it contains a multitude of effects, transitions, and other settings to explore.&#160;In this module, students will learn about some basic editing techniques to manipulate audio and video clips.&#160;They will also learn how to use Effect controls and adjust different transitions and effect settings.&#160;Students will learn about adjustment layers and how they can be used.</p><p>Objectives</p><p>Select a Student</p><p>In this module, students will:</p><p>Use basic editing techniques and effect presets to manipulate digital audio and video including auto-correction methods and tools and audio and video effects presets.</p><p>Apply and adjust effects presets on multiple clips in separate tracks by using adjustment layers.</p><p>Use Effect Controls to modify video in a sequence including modifying video effect settings.</p><p>Apply and adjust video motion effects and composite video tracks.</p><p>Manage audio in a video sequence including adding audio to a sequence and adjusting the audio on the timeline or using the Effect Controls panel.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f17f67c347717198ec39f994ef916ede','adobe-premiere-pro-m6-l2-lesson-1','d6d7e708e98fb3d1ff80cf7500af345d','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Auto-Correction Methods</h3><p>Auto-Correction Methods</p><p>Select a Student</p><p>Color Correction vs.&#160;Color Grading</p><p>These are probably common terms that you have heard before, but is there a difference between the two or are they the same thing?&#160;Color correction and color grading both have to do with the adjustment of colors in a video, but the similarities end there.</p><p>Color correction&#160;deals with normalizing footage to look like it would if you were to see the same scene in real life.&#160;So, you can think of color correction as the process of fixing any issues in lighting or the color balance in an image to make it look as natural as possible.</p><p>Color grading&#160;is slightly more complex and more specialized.&#160;It involves making more detailed edits to the video to help convey a particular tone or mood with the aesthetic.&#160;Color grading is similar to applying an Instagram filter to your pictures and videos.&#160;Color grading involves more stylistic edits.&#160;For example, changing the tone and white balance of a scene in a horror movie to make it look scarier and more mysterious, or highlighting the main character in a scene so that they stand out in the middle of all the background characters and elements.</p><p>Let’s take a look at some of the basic auto-correction methods and tools that you can use in Premiere Pro.</p><p>Welcome to this video on Basic Auto-Correction Methods.</p><p>Let’s start by opening&#160;Color&#160;workspace. You can also just open the LumetriColor panel in your Editing workspace by clicking&#160;Window&#160;and selecting&#160;LumetriColor. Now, select the video clip you want to start editing. If you have worked with Photoshop or other image editing tools before, you may be used to placing the playhead anywhere on the timeline as the image remains the same throughout. But in the case of a video, it’s a good practice to scrub through the video clip and find a good spot to use as a reference frame to do your color correction. Ideally, don’t use one of the beginning or ending frames, as these may have more moving subjects or transitions flowing into the next clip. Instead, pick a frame that clearly shows the main subjects of your clip so that any corrections made will uniformly applied to the entire clip.</p><p>Now, another thing to note is that the Program Monitor shows you a preview of where the playhead is on your timeline. This is done irrespective of which clip is selected, but the color correction edits you make are made to the clip that is selected, not the one the playhead is on. So always make sure you have the right clip selected before making edits, or else you may end up editing the wrong clip.</p><p>In the LumetriColor panel, you will see 6 main sections. You can expand or collapse them by clicking the header. Let’s start with the&#160;Basic Correction&#160;section. [DELETE] You can see many different color correction settings here, but you should always start by clicking the&#160;Auto&#160;button. Premiere Pro automatically applies a basic correction to the video. You can see the before and after of the edit by clicking the checkbox on or off.</p><p>Another key component of color correction is adjusting the white balance of the clip. The white balance adjusts the lighting and ambient color of the video to a more neutral, balanced state. You can tell when the white balance of a clip is off balance when something in the clip that should be white appears in a shade of another color. To fix this, user the&#160;WB eyedropper&#160;tool and click the area on the clip that should be white. You can also use the Temperature and Tint sliders to adjust the balance of the Blue-Red and Green-Magenta color tints in the video.</p><p>The&#160;Tone&#160;section contains different parameters you can use to adjust the tonal scale of the clip. We have already used the Auto adjustment that Premiere Pro does automatically. Once you become more comfortable with editing videos, you can adjust all of these values yourself by dragging the slider to the left or right and correcting the colors in your video. This is how you can color correct your video clips.</p><p>Now let’s take a look at color grading. For this, click the&#160;Creative&#160;tab. Here, the&#160;Look&#160;drop-down list contains a huge list of preset effects that you can apply to your video clips. This should be pretty easy to use for any of you who have used Instagram filters before. You can use the arrows on the thumbnail here to view a small preview of each of these looks, or you can select a look directly from the drop-down list. To apply a look to your clip, just click the thumbnail. You can then adjust the&#160;Intensity&#160;slider to adjust the intensity of the effects.</p></section><section><h3>Audio and Video Effects Presets</h3><p>Audio and Video Effects Presets</p><p>Select a Student</p><p>Audio and Video Effects</p><p>Premiere Pro contains a huge variety of audio and video effects that you can apply to your clips.&#160;These effects can do anything from changing the speed or zoom of a clip to adjusting the color values, distorting images, manipulating the sound, or much more.&#160;You can apply any of the different preset effects available in Premiere Pro, or you can create custom effects and save them as new custom presets that you can reuse at any time.</p><p>To apply effects, you need to open the&#160;Effects&#160;panel.&#160;This is usually grouped with the&#160;Project&#160;panel.&#160;If you don’t see this panel, you can open it from the&#160;Window&#160;menu.</p><p>You will also use the&#160;Effect Controls&#160;panel to refine your effect settings.</p><p>There are some basic effects that are intrinsic and present in all media clips.&#160;These are&#160;Motion,&#160;Opacity,&#160;Time Remapping, and&#160;Volume.&#160;If you click any clip that you have not applied any effects to and then open the&#160;Effect Controls&#160;panel, you will see only these four basic effects.</p><p>Note:&#160;Video clips without audio will not contain the Volume effect.</p><p>All of the standard effects in Premiere Pro are sorted into the&#160;Video Effects&#160;and&#160;Audio Effects&#160;folders.&#160;You can open these and browse through all of the different effects available to you.&#160;Once you get more familiar with the different effects available in Premiere Pro, you can even search for them using keywords.</p><p>All the video effects in th<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f8010394a27870354e7bcca2ea40fefa','adobe-premiere-pro-m6-l3-lesson-2','d6d7e708e98fb3d1ff80cf7500af345d','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Using Adjustment Layers</h3><p>Using Adjustment Layers</p><p>Select a Student</p><p>Adjustment layers are a powerful tool that you can use to apply effects to multiple clips in the timeline.&#160;They allow you to apply tonal and color adjustments to your images and video clips without having to make any permanent changes to the clips themselves.&#160;Adjustment layers are transparent layers and do not contain any content.&#160;They only contain effects that are applied to all the tracks below them.</p><p>You can combine multiple effects on a single adjustment layer, and you can also use multiple adjustment layers if you need to adjust multiple effects.&#160;If you have used Photoshop before, the adjustment layers in Premiere Pro work in a very similar manner as they do in Photoshop.</p><p>To create an adjustment layer, just click the&#160;New Item&#160;icon in the&#160;Project&#160;panel and select&#160;Adjustment Layer.&#160;In the popup, you can specify the video settings for the adjustment layer.&#160;By default, these will match your sequence settings.&#160;Click&#160;OK.</p><p>You will see the new adjustment layer has been added to the&#160;Project&#160;panel.&#160;You can now drag and drop it over the clip or clips that you want to adjust.&#160;Click and drag the ends of the adjustment layer to overlap all the clips you want it to apply to.</p><p>You can now add any of the effects from the Effects panel to this adjustment layer.&#160;For example, let’s drag and drop the&#160;LumetriColor&#160;effect onto the adjustment layer.</p><p>You can now switch to the&#160;Effect Controls&#160;panel and adjust all of these effect settings as required.&#160;Make sure you preview the clips as your edit to verify what your edits look like as you make them.</p><p>Using adjustment layers helps you apply effects uniformly across multiple clips so that your project looks consistent and cohesive.</p><p>Let’s say you are working on editing a short film.&#160;The scenes in that film are shot at different locations and light conditions.&#160;To maintain consistency throughout the video, you can use adjustment layers for color correction and grading and easily make changes in the video.&#160;Adjustment layers are the easiest way to color-grade multiple clips at once.&#160;You can use them to apply the same visual effects to multiple clips that overlap.&#160;This can save you a lot of time in the editing process.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4407777ec90cdf160f12b6dd822f2c36','adobe-premiere-pro-m6-l4-lesson-3','d6d7e708e98fb3d1ff80cf7500af345d','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Using the Effect Controls Panel</h3><p>Using the Effect Controls Panel</p><p>Select a Student</p><p>You have already learned how to add effects and transitions to your video and audio clips in Premiere Pro.&#160;Let’s take a closer look at the&#160;Effects Control&#160;panel and how you can use all of its settings.</p><p>As you already learned, this panel will always have some default effects that are available for all clips in your project.&#160;&#160;You will also see a timeline view on the right side of the panel.&#160;This may be hidden by default.&#160;You can always view it by clicking the arrow at the top right corner of the panel.&#160;This timeline shows you the timeline of the selected clip you are working on.</p><p>All of the effects are denoted by the&#160;fx&#160;icon.&#160;You can use the arrows on the left of the panel to expand or collapse all the effects listed here.&#160;You can show or hide effects by clicking the&#160;fx icon.</p><p>Within each effect, you can see each of the parameters that you can adjust for that effect.&#160;You will notice a&#160;stopwatch&#160;icon at the beginning of each parameter.&#160;This is the&#160;Toggle animation&#160;icon that you can use to enable and add keyframes to modify the effects across the clip.</p><p>All of the values in blue are editable.&#160;You can either click the value and type in a new value, or you can click and drag your cursor left or right to change the value.</p><p>Note:&#160;If you press and hold the&#160;Shift&#160;key while you drag your cursor, the values will increase or decrease in increments of 10.</p><p>To add keyframes for any of these parameters, click the&#160;Toggle animation&#160;icon.&#160;Then, select the point in the clip where you want to add a keyframe and select the circular&#160;Add/Remove Keyframe&#160;icon.&#160;If this icon is blue, a keyframe is added.&#160;If you click it again, the keyframe is removed.&#160;You can adjust the value of the effect at each point that you insert a keyframe.</p><p>Finally, if you want to undo any of the changes that you have made to the effects of a clip, just click the&#160;Reset Parameter&#160;arrow at the end of each effect.</p><p>For example, you can use keyframes for precise changes if you want to gently fade in the audio of a clip or apply an effect over time.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6da40ad3fd4cd7574a699de3852bf499','adobe-premiere-pro-m6-l5-lesson-4','d6d7e708e98fb3d1ff80cf7500af345d','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Applying Motion Effects</h3><p>Applying Motion Effects</p><p>Select a Student</p><p>The&#160;Motion&#160;effect is a default effect that is available for all clips in Premiere Pro.&#160;You can use this effect to modify the position, scale, or rotation of a clip in your project.</p><p>You can view all the different motion effects in the&#160;Effect Controls&#160;panel.</p><p>Adjusting Position of and Effect</p><p>Let’s take a look at how you can use each of these, starting with the&#160;Position&#160;effect.&#160;First, let’s apply an effect to a clip on the Timeline.&#160;For example, let’s apply&#160;Lighting Effects&#160;to a clip by dragging and dropping the effect on the clip in the Timeline.</p><p>You can see that a flare effect has been added to the clip.&#160;You can now adjust various parameters of this effect in the&#160;Effects Control&#160;panel.&#160;For instance, you can change the&#160;Position&#160;parameters to move the flare to a different location on the clip.</p><p>Now, select&#160;Lighting Effects&#160;in the&#160;Effects Control&#160;panel.&#160;You will see blue handles and clip anchors that appear on the clip in the&#160;Program&#160;panel.&#160;You can use these to adjust the position of the flare and modify its shape.</p><p>Scaling a Clip</p><p>You can also scale a clip or lighting effect for impact or visual effect.&#160;Just select the clip in the&#160;Program&#160;monitor and use the handles and anchor points to scale it.&#160;If you want to maintain the aspect ratio while scaling it, press and hold the&#160;Shift&#160;key as you drag the corner or edges.</p><p>In some instances, you may want to scale only along one dimension or edge.&#160;You can do this as well.</p><p>You can also do this from the&#160;Effects Control&#160;panel by adjusting the values of the parameters under&#160;Scale.</p><p>Rotating a Clip</p><p>Rotating a video clip is very easy in Premiere Pro.&#160;Double-click to select the clip in the Program panel.&#160;Scroll the cursor at the outer edge of the corners till they change to a curved&#160;Rotate arrow.&#160;You can now click and drag the clip to rotate it.</p><p>You can also use the&#160;Rotation&#160;setting under&#160;Motion&#160;in the&#160;Effect Controls&#160;panel to do this.&#160;Just open the settings and change the value of the angle.&#160;Alternatively, you can drag the circle icon around to rotate the clip.</p></section><section><h3>Composite Video Tracks</h3><p>Composite Video Tracks</p><p>Select a Student</p><p>A composite is a combination of multiple images or clips.&#160;To create a composite in Premiere Pro, you can adjust the opacity of one or more images so that other images can be visible through them.&#160;You can use the Effect Controls panel to adjust this opacity, and you can use keyframes to fade this opacity up or down between the clips or images.&#160;If you want to composite images together without changing their transparency, you can use different&#160;blending modes&#160;to blend the images together.&#160;These are effects that are applied when multiple elements are composited together.</p><p>Colors, Alpha Channels, and Mattes</p><p>All of the color information of a clip is stored in three channels – red, blue, and green.&#160;Images can also be transparent, so there is a fourth channel called the&#160;alpha channel&#160;where transparency information is stored.&#160;Alpha channels are a way to store transparency information separate from the color information.</p><p>In Premiere Pro, when you view any item that contains alpha channel elements, remember that:</p><p>White = completely opaque</p><p>Grey = partially transparent</p><p>Black = completely transparent</p><p>A&#160;matte&#160;is a layer that is used to define the transparent areas of that layer or another layer.&#160;In this case, the color white is used to define opaque areas and the color black is used to define transparent areas.</p><p>Keying</p><p>Keying is the process of defining transparency using a specific color value.&#160;This feature is used when you want to easily replace a monotone, consistent background color with another image or video.&#160;There are two types of keys that are used:</p><p>Click each tab to learn more.</p><p>Next Tab</p><p>Luma Key</p><p>This function is based on the brightness level or luminance value of an image.&#160;Here, you would generate a matte by applying a luma key to your shot.&#160;You would then define what brightness level would be defined as opaque and what brightness level would be considered transparent.</p><p>Chroma Key</p><p>This function is based on a specific color value of an image and designates all pixels with that color value transparency. Blue and green are the most commonly usedcolors to execute chroma keying.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('843332cdc2e6a138e512e688eeae5607','adobe-premiere-pro-m6-l6-lesson-5','d6d7e708e98fb3d1ff80cf7500af345d','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Managing Audio in a Sequence</h3><p>Managing Audio in a Sequence</p><p>Select a Student</p><p>Audio and video go hand in hand, which is why Adobe Premiere Pro allows you to add, edit and add effects to audio files in your project.&#160;You can mix audio from multiple tracks, use footage with different formats of audio tracks and customize your project as required.</p><p>Sequences can contain many different types of audio tracks:</p><p>Click each term to learn more.</p><p>Standard</p><p>This can take both mono and stereo audio clips.</p><p>Mono</p><p>It contains only one audio channel that either reproduces the channel so it plays on both left and right sides or plays only through one of the channels.</p><p>Stereo track</p><p>This is dual-channel audio that is recorded on both left and right channels.</p><p>Adaptive track</p><p>This can contain mono, stereo, and adaptive clips.</p><p>5.1</p><p>This contains three front audio channels, two rear/surround audio channels, and one audio channel routed to a subwoofer.</p><p>Now, let’s look at a few different ways in which you can manage the audio in your project.</p><p>Merging Clips</p><p>In many instances, your project will contain audio and video clips that were recorded separately and will need to be synchronized in the project.&#160;Premiere Pro allows you to organize and synchronize your audio using the Merge Clips function.&#160;You can merge one or multiple clips together in a single video clip.</p><p>Note:&#160;Merged clips can have multiple audio clips but can only have one video clip.</p><p>To merge clips in the&#160;Project&#160;panel, select the video clip and then use&#160;Shift + click&#160;to select one or more audio clips that you want to merge with it.</p><p>Then, right-click the selection and click&#160;Merge Clips.&#160;You can also do this from the&#160;Clip&#160;menu by selecting&#160;Merge&#160;Clips.&#160;You can then select one of the available options to synchronize the clips.&#160;You can also choose to rename your file here.&#160;Once you are done, click&#160;OK.&#160;The new merged clip will appear in the&#160;Project&#160;panel.</p><p>You can perform the same steps in the&#160;Timeline&#160;panel as well.</p><p>Note:&#160;If you merge clips in the&#160;Timeline&#160;panel, they can only be synchronized from&#160;Clip Start&#160;for each clip.&#160;If you want to synchronize the clips using any of the other parameters, you will first need to do this in the&#160;Project&#160;panel before you drag them onto the Timeline.</p><p>Synchronizing Clips</p><p>You can synchronize clips so that they are all aligned in the Timeline panel.&#160;Once you do this, you can create a merged clip.&#160;To do this, you will first need to align the clips in the Timeline panel so that they are synchronized.&#160;Then, select the clips you want to synchronize, right-click and select&#160;Synchronize.</p><p>Select the point from which you want to synchronize the clips and then click&#160;OK.&#160;The clips will now be synchronized.</p><p>Linking and Unlinking Audio</p><p>Many times, the video clips that you import may contain audio, but you may not want to use it, but replace it with different audio that you recorded separately.&#160;You may have noticed that audio and video files are generally linked in Premiere Pro.&#160;So, to remove the audio from a video clip, you will first need to unlink them.</p><p>Select the video clip in the Timeline panel, right-click and select&#160;Unlink.&#160;The video and audio clips will now be unlinked.&#160;You can now choose to delete the audio or move it to be used elsewhere in your project.</p></section><section><h3>Adding Audio Transitions and Effects</h3><p>Adding Audio Transitions and Effects</p><p>Select a Student</p><p>Just as you can add effects and transitions to video clips, Premiere Pro also provides you with a wide variety of audio effects and transitions that you can use.&#160;You can view all of them in the&#160;Effects&#160;panel that is docked with the&#160;Project&#160;panel.&#160;Here, you can see the&#160;Audio Effects&#160;and&#160;Audio Transitions&#160;folders.</p><p>Most of these effects can be used on mono, stereo, and 5.1 clips.&#160;You can also apply effects to individual clips or to the entire track.&#160;You can apply effects and transitions to audio clips the same way that you do for video clips.</p><p>Crossfades&#160;are the most commonly used transitions for audio clips.&#160;Audio transitions are added in between two audio clips and usually overlap the ends of both clips.&#160;There are three types of crossfades available in Premiere Pro:</p><p>Click each term to learn more.</p><p>Next Tab</p><p>Constant Gain</p><p>Changes audio at a constant rate through the transition – this can sound abrupt</p><p>Constant Power</p><p>Creates a smooth transition where the audio of the first clip slowly fades and that of t the second clip slowly increases.</p><p>Exponential Fade</p><p>Fades out and fades in the two clips over a smooth logarithmic curve.</p><p>To apply a transition, simply drag and drop the transition in between two audio clips.&#160;Note that to overlap a transition between two audio clips, there must be no gap between the clips.&#160;You can then scroll over the transition effect and drag the box outwards when the icon changes to a bracket to increase its duration.</p><p>Alternatively, you can double-click the transition to open the&#160;Duration&#160;popup and set a new duration here.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('49265903dc3b770c80296b02558ab4fe','adobe-premiere-pro-m6-l7-module-6-summary','d6d7e708e98fb3d1ff80cf7500af345d','Module 6 Summary','text',12,'<h2>Module 6 Summary</h2><section><h3>Module 6 Summary</h3><p>Summary</p><p>Select a Student</p><p>Great Work!&#160;You have successfully completed this module on Organizing, Creating, and Modifying Visual Elements Part III!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Used basic editing techniques and effect presets to manipulate digital audio and video including auto-correction methods and tools and audio and video effects presets.</p><p>Applied and adjusted effect presets on multiple clips in separate tracks using adjustment layers.</p><p>Used Effect Controls to modify video in a sequence including modifying video effect settings.</p><p>Applied and adjusted video motion effects and composite video tracks.</p><p>Managed audio in a video sequence including adding audio to a sequence and adjusting the audio on the timeline or using the Effect Controls panel.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b6ab26c6a68e19fb0fdb4c925817cef1','adobe-premiere-pro-m6-l8-module-6-project','d6d7e708e98fb3d1ff80cf7500af345d','Module 6 Project','text',12,'<h2>Module 6 Project</h2><section><h3>Module 6 Project</h3><p>Adobe Premiere Pro</p><p>8100</p><p>Organizing, Creating and Modifying Visual Elements Part III - Project</p><p>Project</p><p>In this assignment, you will apply all that you have learned about editing techniques, adjustment layers, effects, and transitions. You will need to use Premiere Pro to perform these tasks. You can reuse the project file that you created in the last module. Take screenshots after completing each step and save them as image files or add them to a Word/PPT document.</p><p>Open your Premiere Pro project and apply color correction to the clips in the video. Next, apply two different effects to two clips in your project.</p><p>Next, create an adjustment layer for the sequence and apply a different effect of your choice to the layer.</p><p>Use the Effect Controls panel to adjust the settings of the effects and transitions.</p><p>Apply motion effects to modify the position, scale, or rotation of clips in your project.</p><p>Finally, merge and synchronize the audio files in the project. Then, apply audio transition effects to make the transitions sound smooth and seamless.</p><p>Review the rubric below to see how you will be graded.</p><p>Organizing, Creating and Modifying Visual Elements Part III</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Use basic editing techniques</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Use adjustment layers</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately with attention to detail and meeting all requirements.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well and layer groups were not created as instructed.</p><p>4</p><p>Use Effect Controls to modify video effect settings</p><p>4 points Demonstrated a strong understanding of the objective. The linking of layers was done correctly.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. Almost all the instructions to link layers were followed correctly, with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. Little to none of the instructions to link layers were followed correctly.</p><p>4</p><p>Apply and adjust video motion effects</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately and merging and flattening was done as instructed.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Manage audio in a video sequence</p><p>4 points Demonstrated a strong understanding of the objective. The task was performed accurately and as instructed.</p><p>3-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('75f4f4f46960ba6417929ae03c818f9f','adobe-premiere-pro-m6-l9-module-6-quiz','d6d7e708e98fb3d1ff80cf7500af345d','Module 6 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Visual Elements Part 3. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('b96593bac35508df3a7b5546750d62eb','adobe-premiere-pro-module-7','48ab1932af65ef3f9d0793cd5a02da34','Module 7: Publishing Digital Media',7) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('536771afb16319c33b085fc66ba49201','adobe-premiere-pro-m7-l1-introduction-purpose-and-objectives','b96593bac35508df3a7b5546750d62eb','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Select a Student</p><p>i everyone, and welcome to this final module of the Premiere Pro course. It’s been an exciting journey diving into all of the fantastic features that Premiere Pro has to offer. Let’s recap what you have learned! We started with basic but critical aspects of working in the video design industry, both with teams and clients. We explored the Premiere Pro interface and the various tools and commands available. We learned how to put together a rough cut of video clips and organize them using the various tools and panels in Premiere Pro. Next, we handled more complex topics by creating and modifying visual elements of video and audio clips as well as text elements using various functions. By now, you should have an idea of just how many things you can do with Premiere Pro. Just like any other tool, you’ll keep getting better at it the more you use it, so make sure you explore Premiere Pro and experiment to design creative, impactful videos!</p><p>In this module, we’ll cover an important last step in this Premier Pro journey—publishing and exporting your digital media. Because Premiere Pro allows you to work with so many different types of media files, it also gives you multiple options to prepare and export your data in various formats and for various purposes.</p><p>Hopefully by the end here, you have been able to capture the vision of what is possible with Premiere! There are so many things out there to image, create, edit, and publish. You are well on your way to seeing that vision and those ideas become reality.</p><p>Module Description</p><p>Select a Student</p><p>Premiere Pro gives you multiple ways and formats in which you can export your video and audio sequences for digital or web use, screen use, or for use on other devices or programs.&#160;In this module, students will learn how to check their project for errors and ensure all the correct project specifications are set.&#160;Students will also learn about exporting and archiving project elements in various formats.&#160;Finally, we’ll go over the structure and test prep students will need for the ACA Premiere Pro Certification Exam.</p><p>Objectives</p><p>Select a Student</p><p>In this module, students will:</p><p>Check a project for errors and project specifications.</p><p>Export and archive video and audio sequences including exporting a clip, range of frames, a single frame, or an entire sequence.</p><p>Export using the Adobe Media Encoder.</p><p>Archive a project.</p><p>Understand the structure and test prep necessary for the Adobe Certified Professional credential.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3edea107b3b01d480db885f87751595e','adobe-premiere-pro-m7-l2-lesson-1','b96593bac35508df3a7b5546750d62eb','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Checking for Errors</h3><p>Checking for Errors</p><p>Select a Student</p><p>Before you can export your video, you should always check your project for any errors that may cause problems during export.</p><p>Click each term to learn more.</p><p>Spell Checks</p><p>Make sure that you check all of the text components of your video to ensure that there are no typos or spelling mistakes.</p><p>Gaps in Timeline</p><p>Since Premiere Pro is a non-linear editing system, blank gaps in between clips are a common problem. Scrub through your timeline to spot any empty spaces. Select and right-click the empty space and select&#160;Ripple Delete. This fix works well when you have a small- to a medium-sized project, but when you work with larger projects, this can be very time-consuming. You can easily find gaps in a large project by clicking&#160;Sequence, selecting&#160;Go to Gap, and selecting&#160;Next in Sequence. You can use the keyboard shortcut&#160;Shift +;&#160;to do this faster, and then ripple delete the gaps.</p><p>Frame Rate and Aspect Ratio</p><p>Make sure that select the proper frame rate for your video. Frame rate isn’t just a consideration in terms of the quality of the video output, but also in terms of the bandwidth and playback ability. If you are working with heavy files with a high frame rate, reducing the frame rate can help improve playback when you have limited bandwidth. However, most videos look better when they use their original frame rates. So, based on the type of output you are exporting, and where you will be using those videos, you can vary this value.</p><p>The same goes for frame size. If you increase the frame size, your video quality gets affected.</p><p>Title Safe Area</p><p>We discussed this at the beginning of this course. The title safe area is a rectangular area that is used to define the area visible on television. Depending on where you will be viewing your videos, make sure you take the title safe area into consideration while making your edits to ensure you haven’t framed your subjects in a way that they get cropped or are out of the frame.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('215136379712242a4aae5d0bb62b6324','adobe-premiere-pro-m7-l3-lesson-2','b96593bac35508df3a7b5546750d62eb','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Exporting Clips, Range of Frames, or Sequences</h3><p>Exporting Clips, Range of Frames, or Sequences</p><p>Select a Student</p><p>Premiere Pro gives you the flexibility to choose exactly what you want to export.&#160;You can easily export a clip, a range of frames, or an entire sequence directly to the Web or mobile devices, or as a standard media file.</p><p>Let’s start with the quickest way to export a sequence using&#160;Quick Export.&#160;Select the sequence you want to export and click the&#160;Quick Export&#160;icon at the top right corner of your workspace.</p><p>You will see a popup with a default&#160;Match Source&#160;preset selected.&#160;Click the blue file location to select where you want to save your video file and click the&#160;Export&#160;button.&#160;That’s it!&#160;Your video will immediately be exported.</p><p>You can also mark out in and out points on your timeline and export only a part of a sequence.&#160;Then, click&#160;File, select&#160;Export, and click&#160;Media.&#160;You can also use the keyboard shortcut&#160;Control + M&#160;or&#160;Command + M.</p><p>The&#160;Export Settings&#160;popup is displayed.&#160;Here, you can see all the different export settings that you can modify.&#160;You can choose the format of your output file and choose one of the many available presets.&#160;Premiere Pro has different presets for&#160;Twitter, Facebook, Vimeo,&#160;and&#160;YouTube.&#160;You can choose the preset based on the audience, distribution, and playback specifications for your video.</p><p>You can also customize other export options such as those listed in the&#160;Effects, Video, Audio,&#160;and other tabs.&#160;Once you are done, you can click the&#160;Export&#160;button to immediately export the video.&#160;If you have multiple videos that you want to export, you can use the Adobe Media Encoder and click the Queue button to add the encoding job to the queue.&#160;Once you have added all the videos you want to export to the queue, you can click the play icon to encode and export all of them together.</p><p>The settings that you use to export your video will depend on multiple factors, such as where you will be using the video.&#160;Let’s assume you have worked on and edited a short film.&#160;The film will be shown at a film festival.&#160;You can use the Export Settings feature to select a high-quality format.&#160;You can also select a cinematic frame rate of 24fps.&#160;You can also choose the format of your output file.&#160;Additionally, you can choose the preset based on the specifications of your video.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('31eacc6aad43f12012103cb97ede8678','adobe-premiere-pro-m7-l4-lesson-3','b96593bac35508df3a7b5546750d62eb','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Exporting using the Adobe Media Encoder</h3><p>Exporting using the Adobe Media Encoder</p><p>Select a Student</p><p>Let’s say that you are working on a video project for a client, and they ask for an interim review so they can see your progress.&#160;You could use the information from the previous lesson to export the project.&#160;Now, let’s say the client immediately writes back and asks for samples in different formats for Vimeo, Facebook, and other formats.&#160;This would mean that you would need to keep repeating the export process and change the settings each time, which can be very time-consuming.&#160;This would also mean that you would need to stop working and wait until all the files are exported before you can resume work.</p><p>So, what’s the solution?&#160;Adobe Media Encoder can solve all your problems!</p><p>It allows you to:</p><p>Queue files for export so that you can batch process them and export multiple files at once</p><p>Export files in the background and continue to work in Premiere Pro</p><p>Export the same file in multiple different formats at once</p><p>Export files to multiple different locations at once</p><p>Let’s see how this works.&#160;Adobe Media Encoder is integrated with Adobe Premiere Pro.&#160;In fact, the&#160;Export Settings&#160;window that you use to export your files is generated by Media Encoder.&#160;Here, you will see that there is one more option apart from&#160;Export, and that is to&#160;Queue.&#160;This sends the files to Media Encoder to render in the background, allowing you to continue to work on your project in Premiere Pro.</p><p>Once you click&#160;Queue, the project will be added to the Media Encoder’s queue.&#160;Here, you can see all of the export settings that you selected.&#160;You can easily change these settings by clicking these links.&#160;For instance, you can change the Preset or the destination file location.</p><p>You can continue to add multiple different sequences or clips that you want to export in the same way.&#160;Once you are ready to publish, click the&#160;Start Queue&#160;icon (the green play button).</p><p>Note that this is being rendered in the background, so you can go back to Premiere Pro and continue working on your project.</p><p>Even if you have already started the queue, you can keep adding new sequences to it by repeating the above process, or by simply dragging and dropping the sequence from Premiere Pro into Media Encoder.</p><p>Once an item has finished rendering, you can right-click it and select&#160;Duplicate&#160;to render it again, or you can select&#160;Reset Status&#160;to apply a different preset to the sequence and then render it.</p><p>Just drag and drop a preset onto the item and it is now ready to export with the new settings.</p><p>Another great option is that you can click the&#160;Add Output&#160;icon and add multiple outputs for the same file, and then change the presets for each output.</p><p>Note that Adobe Media Encoder creates a clone of your sequence and adds it to the queue so you can continue to work on your sequence without disruptions.&#160;This means that after you render a file, if you continue to make edits to it, those edits will not be reflected in the older version in the Media Encoder.</p><p>As a video editor, you have just finished editing a TV commercial in Adobe Premiere Pro.&#160;This commercial needs to be shown on different platforms – YouTube, television and Instagram.&#160;You can use Adobe Media Encoder to create all these versions efficiently and simultaneously.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('73d16c54af3524478069114bb5a94777','adobe-premiere-pro-m7-l5-lesson-4','b96593bac35508df3a7b5546750d62eb','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Archiving a Project</h3><p>Archiving a Project</p><p>Select a Student</p><p>The Premiere Pro Project Manager helps you manage all of the files associated with your projects in an efficient manner.&#160;This is especially useful when you work with large projects with multiple clips and media formats.</p><p>You can use the Project Manager to do two key functions:</p><p>You can collect and copy all of your current project files to a single location.</p><p>You can consolidate all the files associated with your project and transcode it into a single codec that can be archived.&#160;At any point, you can retrieve this archived project to re-edit it in Premiere Pro.</p><p>To launch the Project Manager, click&#160;File&#160;and select&#160;Project Manager.</p><p>This is the&#160;Project Manager&#160;window.</p><p>Click each hotspot on the image to learn more about what each setting does.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Screenshot of the Project Manager window</p><p>The hotspot points on the image are as follows:</p><p>Sequence</p><p>In the&#160;Sequence&#160;section, select all the sequences that you want to select.</p><p>Resulting Project</p><p>If you select&#160;Collect Files and Copy to New Location, all the files associated with the selected sequences will be copied to a single location.</p><p>If you select&#160;Consolidate and Transcode, then all the selected footage will be transcoded into a single codec to be archived.</p><p>Options</p><p>You can then check or uncheck all of the options on the right based on which of these actions you want to perform. For example, you may choose to exclude any unused clips from your archive.</p><p>Destination Path</p><p>You can modify the destination path where files are saved.</p><p>Once you are done, click&#160;OK.&#160;The project will be copied or transcoded based on the settings you selected.</p><p>Let&#39;s say you work as a video editor for a production company.&#160;Your assignment is to create a promotional video for a new product launch.&#160;There are multiple video clips, images, audio files, and various sequences that need to be edited together.&#160;As you start working, you realize that some of the files might be duplicates.&#160;In Premiere Pro, you can select &quot;Project Manager.&quot; And select &quot;Collect Files and Copy to New Location,&quot; all the relevant media files and sequences will be copied to a new folder.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('26bb1a42befacfd4a958c04135e0c195','adobe-premiere-pro-m7-l6-lesson-5','b96593bac35508df3a7b5546750d62eb','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Certification</h3><p>Certification</p><p>Select a Student</p><p>by Shutterstock</p><p>License:&#160;All Rights Reserved</p><p>We’ve reached the end of this course on Premiere Pro.&#160;By now, you should have a good grasp on all of the fantastic features available in Premiere Pro and how you can use them to do everything from combining multiple video clips to adding effects, transitions, and editing the color of videos to create original, innovative videos.</p><p>All of this training has been put in place to enable you to enhance your skills and get certified as an Adobe Certified Professional.&#160;The certification is a globally recognized stamp on your profile that demonstrates your proficiency and understanding of digital skills.</p><p>In order to earn this certification, you will need to pass a rigorous examination administered through a Certified Authorized Testing Center (CATC).&#160;In this final lesson, we’ll give you an idea of what the structure of the examination will be like, what to expect, and how you can prepare yourself to ace the exam!</p></section><section><h3>Exam Structure &amp; Walk-through</h3><p>Exam Structure &amp; Walk-through</p><p>Select a Student</p><p>The Premiere Pro exam is a timed examination comprised of two sections.&#160;You will have 50 minutes to complete both these sections.</p><p>Note:&#160;All exams undergo continuing psychometric analysis and the number of questions are subject to change.</p><p>These exams evaluate both your knowledge and skills using two types of questions:</p><p>Linear questions:&#160;These are the standard multiple-choice, true/false or matching type questions that assess your knowledge and understanding of basic concepts.</p><p>Performance-based questions:&#160;These questions will have you perform steps in a simulated Premiere Pro application so you can demonstrate your skills in the actual work environment.</p><p>Let’s look at how these two sections will be structured.</p><p>Tutorial:&#160;You will start off with a tutorial introducing you to the exam, how to navigate it, and how to answer questions.&#160; This is not a timed task, so take your time to read through and understand the rules.</p><p>Questions:&#160;This is the first section that contains linear questions.&#160;The timer starts as soon as you begin this section.</p><p>Section Summary:&#160;Once you complete a section and submit the questions, you will see a summary that allows you to review only the questions.&#160;You cannot revisit questions once submitted, so make sure they are final.</p><p>Tutorial:&#160;The timer is paused for a tutorial on how to proceed with the next section of the exam.&#160;Again, take your time to understand the rules.</p><p>Tasks:&#160;This second section contains performance-based questions or tasks that you will need to perform in a virtual Premiere Pro environment.&#160;The timer will resume where you left off as soon as you begin this section.</p><p>Section Summary:&#160;Once you complete the second section, you can review the tasks you just completed in the Section Summary page.</p><p>Leave Feedback:&#160;After you have submitted both sections, you can leave feedback on the exam, tasks or questions.</p><p>License:&#160;All Rights Reserved</p><p>Note that during the performance-based section of your exam, a few features in your simulated Premiere Pro application will be disabled, including:</p><p>Open</p><p>Help</p><p>Adobe Bridge</p><p>Adobe Stock</p><p>CC Library</p><p>Only use the Certification Test workspace to perform your tasks (unless specified otherwise).</p><p>The best way to prepare yourself for the Premiere Pro examination is to practice, practice, practice!&#160;The projects you’ve completed throughout this course are a great way for your to do this.&#160;Re-do the projects with different video and audio clips and use different tools to perform the tasks.&#160;Try out different types of edits, transitions, and effects.&#160;Explore Premiere Pro and practice using all of the different tools.</p><p>The internet is also a great source of inspiration and a well of information from other video developers who have applied their Premiere Pro skills.&#160;Explore these resources to see examples of how others have edited their videos, take a look at sample projects, or just try to identify how you can replicate different effects that you have seen applied in the videos you watch.&#160;Finally, share and discuss your work and creative ideas with your classmates and friends.&#160;Working collaboratively is a great way to discover new creative directions and explore all that Premiere Pro has to offer.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('302d67142e31becdcfa82f9b5d834000','adobe-premiere-pro-m7-l7-module-7-summary','b96593bac35508df3a7b5546750d62eb','Module 7 Summary','text',12,'<h2>Module 7 Summary</h2><section><h3>Module 7 Summary</h3><p>Summary</p><p>Select a StudentCTEdemo_artsav</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Publishing Digital Media.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Checked a project for errors and project specifications.</p><p>Exported and archived video and audio sequences including exporting a clip, range of frames, a single frame, or an entire sequence.</p><p>Exported using the Adobe Media Encoder.</p><p>Archived a project.</p><p>Understood the structure and test prep necessary for the ACA Premiere Pro Certification Exam.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9c97c09baeaf62fe318d6409ced559f3','adobe-premiere-pro-m7-l8-module-7-project','b96593bac35508df3a7b5546750d62eb','Module 7 Project','text',12,'<h2>Module 7 Project</h2><section><h3>Module 7 Project</h3><p>Adobe Premiere Pro</p><p>8100</p><p>Publishing Digital Media - Project</p><p>Project</p><p>In this assignment, you will use what you have learned to check your Premiere Pro project and export it in various formats.</p><p>Create a Premiere Pro project with video clips, audio clips, and text elements. You can choose from one of these types of videos:</p><p>A funny compilation video of your pets</p><p>A short travel video made from videos you took on a recent trip or vacation</p><p>A video of your choice made with friends/family (this could even be from a birthday or wedding celebration, or another event)</p><p>Check the project to ensure there are no errors. Save the file as a PRPROJ file. Then, export your video in the following formats: Match source, Facebook, and YouTube using the Adobe Media Encoder.</p><p>Once you have published the videos, archive your project.</p><p>Review the rubric below to see how you will be graded.</p><p>Publishing Digital Media Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Check a project for errors and project specifications.</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Export using the Adobe Media Encoder.</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Archive a project.</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Save project documents.</p><p>5 points Demonstrated a strong understanding of the objective. The task was performed accurately.</p><p>4-2 points Demonstrated a satisfactory understanding of the objective. The task was performed adequately with a few errors.</p><p>1-0 points Demonstrated little to no understanding of the objective. The task was not performed well.</p><p>5</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('60ba921c7dbed5abced872cf088d8ac1','adobe-premiere-pro-m7-l9-module-7-quiz','b96593bac35508df3a7b5546750d62eb','Module 7 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Publishing Digital Media. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('038a96dba2cad586431cfabbe5dcc3f7','adobe-premiere-pro-module-8','48ab1932af65ef3f9d0793cd5a02da34','Module 8: Course Summary and Final Exam',8) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('bda0b8a51708ff84754188216858508a','adobe-premiere-pro-m8-l1-course-summary-and-final-exam','038a96dba2cad586431cfabbe5dcc3f7','Course Summary and Final Exam','text',12,'<h2>Course Summary and Final Exam</h2><section><h3>Course Summary Wrap-up</h3><p>Course Wrap Up</p><p>Select a StudentCTEdemo_artsavMatthew Barber</p><p>We&#39;re at the last leg of our exciting Premiere Pro journey!&#160;We hope this course has equipped you with the knowledge needed for you to master the learning objectives of this course.&#160;Premiere Pro is a tool that is best learned by doing, which is why we gave you a ton of videos and activities to practice your skills.&#160;You should now be ready for the final exam.</p><p>Our main objective on this journey has been to push away the veil of mystery from Premiere Pro and enable you to discover all of the creative possibilities it has.&#160;Keep exploring Premiere Pro and use the resources to discover more interesting, creative ways to use Premiere Pro.&#160;Whether you choose to pursue a career in video development and editing or not, this course has given you some fantastic skills that you can still apply in other fields or even as a hobby.</p><p>Complete the final exam on the next page and submit it to complete this activity.</p></section><section><h3>Final Exam</h3><p>Final Exam</p><p>Select a StudentCTEdemo_artsavMatthew Barber</p><p>Analytics:Off</p><p>Answer Key:Off</p><p>ABCABC</p><p>Directions:&#160;Read each question carefully and then choose the correct answer.</p><p>You have already taken this quiz and will not be able to retake it.</p><p>What can you use the Project Manager for in Premiere Pro?</p><p>Collect and copy all of your current project files to a single location.</p><p>Consolidate all the files associated with your project and transcode it into a single codec for archive.</p><p>Download all the assets in your project.</p><p>Publish all of your sequences.</p><p>How do you add in and out points in a video clip?</p><p>Crop the video to the size of the clip you want to mark the in and out points</p><p>Right-click the points in the video clip and select Add In or Add Out</p><p>Select position to add in or out point, and click the + or – key on your keyboard</p><p>Select position to add in or out point, and click the open or closed curly bracket icon</p><p>Where can you import assets from in Premiere Pro?&#160;(Select all that apply)</p><p>Media Browser</p><p>File menu</p><p>Import menu</p><p>Project panel</p><p>What are proxies used for in Premiere Pro?</p><p>To be able to work on high-resolution files</p><p>To create duplicates of media files</p><p>To be able to work smoothly on lower-resolution files</p><p>To create multiple sequences</p><p>What setting do you need to select to make sure any text boxes snap and align to other shapes on the clip?</p><p>Snap in Program Monitor</p><p>Snap All</p><p>Align and Transform</p><p>Transform</p><p>Which of the following can you do using the Adobe Media Encoder?</p><p>Batch process files for export</p><p>Export files in the background and continue to work in Premiere Pro</p><p>Export the same file in multiple different formats at once</p><p>Export files to multiple different locations at once</p><p>What is the keyboard shortcut to export media in Premiere Pro?</p><p>Control + M or Command + M</p><p>Control + E or Command + E</p><p>Control + F or Command + F</p><p>Control + P or Command + P</p><p>What is the fair use doctrine?</p><p>It states that all content is free for use by anyone</p><p>It states that no content can be used by anyone else</p><p>It states that small portions of materials can be used provided credit is given</p><p>It states that a license payment must be made to use anyone’s content</p><p>What is a point-of-view shot used for in videos?</p><p>Shows a conversation between two characters in a scene</p><p>Shows a close up of the subject in the scene</p><p>Shows what the subject is looking at in the scene</p><p>Shows a full-length shot of the subject in the scene</p><p>Which of the following are different types of transitions you can apply to your videos?&#160;(Select all that apply.)</p><p>Wipes</p><p>L-cuts</p><p>J-cuts</p><p>Dissolve</p><p>What button can you use to ensure only audio clips on one track play?</p><p>M button</p><p>A button</p><p>S button</p><p>Eye button</p><p>True or false?&#160;White balance is the measurement of the color temperature of an image.</p><p>True</p><p>False</p><p>What is the sampling rate of a video?</p><p>Rate at which sound is measured during recording</p><p>Audio levels</p><p>The distortion of the audio during recording</p><p>Background audio recorded in a file</p><p>True or false?&#160;Premiere Pro allows you to automate sequences and create timelapses.</p><p>True</p><p>False</p><p>How do you dock and undock panels in Premiere Pro?</p><p>Click and drag panels, drop them in the drop zone</p><p>Shift-click panels and then click the area you want to drop it in</p><p>Right-click the panel and select Move, and then select the location</p><p>You cannot dock and undock panels</p><p>What is the Current Time Indicator?</p><p>It is the playhead that shows your current position in the video</p><p>It shows you the timeline of the video</p><p>It shows you the duration of the clip</p><p>It is a counter that calculates the time you spent editing the video</p><p>What is a storyboard in video production?</p><p>It is the script of the video</p><p>It is the music lyrics of the video</p><p>It is a visual representation of the video based on the script</p><p>It is a recorded pilot episode of the video</p><p>_____________ fades out and fades in the two clips over a smooth logarithmic curve.</p><p>Constant gain</p></section><section><h3>Final Exam</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Adobe Premiere Pro lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Adobe Premiere Pro interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('42d4988e6f59902ffe644d539589d852','adobe-premiere-pro-course-mastery-assessment','038a96dba2cad586431cfabbe5dcc3f7','Course Mastery Assessment','assessment',30,'<h2>Course mastery assessment</h2><p>Bring together knowledge and application from the complete course. Achieve at least 80% to satisfy the assessment requirement for certification.</p>',NULL,1,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO assessments (id,slug,course_id,title,pass_mark,questions) VALUES ('557b2eddf6f69a80f1190cde3dedb6d5','adobe-premiere-pro-course-mastery-assessment','48ab1932af65ef3f9d0793cd5a02da34','Adobe Premiere Pro Course Mastery Assessment',80,CAST('[{"id":"adobe-premiere-pro-course-mastery-assessment-q1","type":"multiple-choice","prompt":"Before starting a practical task in Video Industry Part 1, which action best demonstrates professional judgement?","options":["Clarify the intended outcome, constraints, and success criteria before choosing tools.","Choose the fastest tool and define the goal afterward.","Copy the first available example without checking its fit.","Begin production immediately and leave requirements for final review."],"answer":"Clarify the intended outcome, constraints, and success criteria before choosing tools.","explanation":"Strong practice begins with a clear outcome, constraints, and measurable success criteria.","clue":"Think about what must be understood before execution begins."},{"id":"adobe-premiere-pro-course-mastery-assessment-q2","type":"multiple-choice","prompt":"A first attempt in Video Industry Part 2 does not meet the requirement. What is the strongest next step?","options":["Compare the result with the criteria, identify the cause, revise, and test again.","Submit the attempt unchanged because the task is complete.","Replace the criteria with measures the attempt already meets.","Discard all evidence and restart without diagnosing the issue."],"answer":"Compare the result with the criteria, identify the cause, revise, and test again.","explanation":"An evidence-led improvement cycle diagnoses the gap before a focused revision and retest.","clue":"Use feedback and evidence to improve the next attempt."},{"id":"adobe-premiere-pro-course-mastery-assessment-q3","type":"multiple-choice","prompt":"Which evidence most credibly demonstrates applied competence in Project Setup & Interface?","options":["A completed work sample with decisions, checks, feedback, and reflection documented.","A claim that the topic was understood without a work sample.","A list of tools with no explanation of how they were used.","An unfinished draft that has not been checked against requirements."],"answer":"A completed work sample with decisions, checks, feedback, and reflection documented.","explanation":"Competence is best demonstrated through completed, reviewed evidence and reflective reasoning.","clue":"Choose evidence that shows both the result and how quality was established."},{"id":"adobe-premiere-pro-course-mastery-assessment-q4","type":"multiple-choice","prompt":"When work in Visual Elements Part 1 could affect people, data, safety, or the environment, what should the learner do?","options":["Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","Proceed without checks when the intended outcome is positive.","Treat ethical and safety considerations as optional after delivery.","Hide known limitations so stakeholders remain confident."],"answer":"Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","explanation":"Responsible practice makes risk, consent, standards, and safeguards part of the work itself.","clue":"Professional quality includes the impact of the work, not only the output."},{"id":"adobe-premiere-pro-course-mastery-assessment-q5","type":"multiple-choice","prompt":"How should a learner transfer skills from Visual Elements Part 2 to a new workplace or project context?","options":["Analyse the new context, adapt the method, test assumptions, and evaluate the result.","Repeat the original steps unchanged regardless of context.","Use only familiar methods and ignore new constraints.","Wait for a complete example to copy before making any decision."],"answer":"Analyse the new context, adapt the method, test assumptions, and evaluate the result.","explanation":"Transfer requires adapting core principles to new constraints and validating the result.","clue":"Core principles remain useful, but their application must fit the new context."}]' AS JSON)) ON DUPLICATE KEY UPDATE title=VALUES(title),pass_mark=VALUES(pass_mark),questions=VALUES(questions);
INSERT INTO courses (id,slug,academy_id,moodle_id,title,description,level,duration,price,is_free,status)
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('02849cdc2b5e339a158215f1cea8d499','space-travel-and-solar-system-module-0','2a892040eda1f32ee69b17d25aad96dd','Module 0: Introduction, Purpose, Objectives, Summary',0) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7bf2bc9ba160ee954badaffb6aa9281d','space-travel-and-solar-system-m0-l1-module-0','02849cdc2b5e339a158215f1cea8d499','Module 0','text',12,'<h2>Module 0</h2><section><h3>Course Intro and Navigation</h3><p>Course Intro Video</p><p>Human civilization has always been defined by exploration. Ever since humans first looked upward, we have wondered what’s out there in space and how do we get there?</p><p>Fortunately, we live in an age where humanity has already made great progress in space travel, from the space race to the shuttle program and the international space station. But more important are the possibilities in the near future. This course will explore the ideas and near-impossible visions of science fiction writers, which are being turned into reality by todays innovators. Can we really build colonies on the moon, on mars, and moons of other planets? What would life be like there? Is asteroid mining practical and how would that even work? We’ll discover how humanity could be affected by space as a new frontier for war and conflict. We’ll also dive into the theories for interstellar travel.</p><p>To ensure our long-term survival, humans will become an interplanetary species. It’s not a matter of if… only when. These ambitious aims will require a new generation of enthusiastic and resourceful pioneers to blaze the rocket-powered trail into the unknown.</p><p>Course Navigation</p><p>Welcome to this course on&#160;Space Travel!&#160;To get you started in Module 0, we have included the video below, which provides some navigation help and other details about the course.</p><p>Other sections of this Module 0 include the Course Syllabus and a Syllabus Quiz, so read&#160;through the syllabus carefully and thoroughly!</p><p>Hi and welcome to this orientation video for this course. As we go through this video, some details may differ depending on which course you are taking and the learning management system, or LMS, that your school uses, but the overall structure generally stays the same for each course.</p><p>After you complete this navigation tutorial video for module zero you should read through the course objectives, a section on sources and plagiarism, the syllabus, and finally take the syllabus quiz. Now, a few things on navigation. Within each section, you can navigate between pages either with the menu here on the left, or with the left/right arrows near the bottom. Again, that will allow you to move between PAGES within each section. Once you are done with all the pages in a section, you can either select home at the top of the course. Or you can select “Next” at the very bottom of the page to the next section. It’s very important to make sure you finish every page within a section BEFORE moving to the next section.</p><p>Ok, once you are done with Module 0, you&#39;ll move on to start your first module. Within each module there is an introduction, somewhere between 4 and 6 lessons, and then a summary and assessments at the end. First, within the introduction, if you select it, it should look something like this. Each module will start at this page which contains a 30 to 60 second introductory video that will introduce and discuss some of the concepts that you&#39;ll learn and review during this module. Let’s talk about the videos. You can also turn closed captioning on or off by clicking the CC button. Next is the setting button, where you can adjust the speed that the videos will play. Maybe you like to hear things a little faster at 1.25x. Or maybe there is a concept that is difficult, and you would like to slow down. These next two icons allow the video window to pop out, or for the video window to go full-screen. For many videos, there will also be a transcript of the video below.</p><p>The next page is a description of the module. Then we move on to objectives which explains what the student will learn during this module. Next there is typically is a polling question. Sometimes this appears at the beginning of a module and sometimes it appears at the end. But it&#39;s just a way to take a guess or to voice your opinion on a certain issue and you can click on whichever you&#39;d like and see how your answer compares to your classmates.</p><p>You will next come to a vocabulary activity. Most of these will also be at the beginning as a formative assessment, meaning that you aren&#39;t expected to know the answers but take your best guess as this is an ungraded quiz. For instance, you can pick a word drag it over and then check your answer to see that it was incorrect you keep trying again and see if you can get them all lined up. Again, this allows you to just familiarize yourself with the various vocabulary words that will be introduced in this module. Alternatively you can select on the alternative activity and it&#39;s more of a multiple choice format. So again this is an ungraded quiz. You can close it out right there. Next, we move to the lessons. As said before, there are 4 to 6 lessons within each module. So you&#39;ll see each lesson represents more or less a day&#39;s worth of work and contains a video, a reading, and then either a concept check or reflection. As you will learn in the syllabus, the introduction, video, and reading pages are graded on participation, meaning you get credit for going through every page and activity in the module. Your school may or may not be using participation, so please check with your instructor on whether or not you will be receiving participation credit in your course.</p><p>The videos and their functionality we have already talked about. Next we go into the readings which obviously will have additional content and details to read. It will also frequently contain images as well as embedded videos. These are videos that add a lot of visual detail to the materials and again just hitting play there. Some videos are longer, so we try to limit video clips to 2 to 5 minutes, so in some cases you will only see a small clip of a larger video.</p><p>After the video and reading is a concept check or reflection where you&#39;ll either input an answer or work with flashcards or maybe a sorting exercise to review and firm up the concepts that were taught in that section. The reflections are either journal entry or discussion prompts. To participate in class-wide discussion, you’ll select this link to read the questions or prompts, and then participate in the discussion by adding a new discussion topic and eventually commenting on posts from other students.&#160;You&#39;ll see this repeat itself through the rest of the sections. After which you&#39;ll find a quick summary. Once you are finished<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('1e442ea20dd21be26913d1a9f4906fdc','space-travel-and-solar-system-module-1','2a892040eda1f32ee69b17d25aad96dd','Module 1: Intro to Space Travel',1) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7fe7002cfd4b51b7abe1b3bbc1914232','space-travel-and-solar-system-m1-l1-introduction-purpose-and-objectives','1e442ea20dd21be26913d1a9f4906fdc','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi, I’m Mr. Proctor, and I’ll be one of your instructors for this course on the Future of Space Travel.</p><p>Movies about space are a good way to identify human fears and hopes. On the fear side, some movies show humans being attacked by all sorts of alien life. On the hope side are movies that show humans making contact with alien life or discovering new worlds. But very few science-fiction movies depicting life in space capture the fact that a lot of space exploration is about math, engineering, procedures repeated over and over, and trial and error.</p><p>The reality, that putting people in space and launching satellites into orbit requires a lot of people doing a lot of repetitive jobs, doesn’t make for a really exciting film. One movie that comes close is The Martian. It shows Matt Damon’s character surviving on Mars alone, not because of his strength but because of science and, eventually, he gets off the planet because of teamwork.</p><p>In this module, you’ll meet the people behind the kind of science and teamwork that, one day, might take us to Mars. We’ll look at the history and the challenges space travel and exploration has had to face and still faces. Finally, we’ll look at the influence of politics on space programs and what the future holds.</p><p>Module Description</p><p>by www.shutterstock.com</p><p>License:&#160;All Rights Reserved</p><p>At the beginning of the 20th&#160;century, space travel seemed like an impossible dream, one that had been on the mind of writers, poets and inventors for thousands of years.&#160;The first recorded mention of “space crafts” appeared in the Hindu poem&#160;Ramayana, written over many centuries starting in the 3rd&#160;century BC.&#160;It described machines capable of flying in and outer space.&#160;This was followed by many other examples but it wasn’t until the 17th&#160;century that a writer described travelling to the Moon.&#160;Now, 300 years later, serious plans are being considered to put human boots on Mars.</p><p>This module looks at the fascinating history of space travel identifying its origins, prominent figures, key innovations, and technological advances.&#160;Students will look at how politics impacted space travel between countries and within countries while reviewing successes and challenges of the space program.&#160;The module will also preview exciting topics that will be covered throughout the course on the possibilities of space travel during the students’ lifetime.</p><p>Objectives</p><p>In this module, students will</p><p>Outline the history of space travel and contrast past technological changes with current opportunities</p><p>Analyze the political history of space travel and its impact on innovation.</p><p>Discuss the challenges space travel has faced over the last century and the solutions which overcame them</p><p>Construct a timeline of innovation, technological advances, historical turning-points, successes, and failures within the last century identifying prominent figures which impacted space travel</p><p>Preview the goals, plans, and possibilities for space travel over the next 50 years, including moon and Mars exploration, space tourism, and asteroid mining</p><p>Polling Question</p><p>If you could travel anywhere in our solar system, where would you do?</p><p>Visit a planet&#160;Find the end of the solar system&#160;Search for life</p><p>Results:</p><p>Visit a planet&#160;50%</p><p>Search for life&#160;50%</p><p>How did your destination compare to your classmates?&#160;Let’s see how your answer changes as you learn more about the history, present day and future of space travel.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Tab through this activity to read the feedback for your answers</p><p>Feedback</p><p>The theory and practice of navigation beyond the Earth’s atmosphere.</p><p>Astronautics</p><p>Correct!</p><p>Period (1947-1989) when the USA and the Soviet Union were battling for supremacy on the world political stage.</p><p>Cold War</p><p>Correct!</p><p>Already used in many applications on Earth to produce electric power for homes and cars.&#160;They convert light into energy.</p><p>Photovoltaic cells</p><p>Correct!</p><p>The process of transferring activities from the public to the private sector.</p><p>Privatization</p><p>Correct!</p><p>When Mars and the Earth are closest to each other.&#160;At those moments, only half the energy would be needed to travel to the red planet.</p><p>Low-energy windows</p><p>Correct!</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>The theory and practice of navigation beyond the Earth’s atmosphere.</p><p>Cold War</p><p>Privatization</p><p>Astronautics</p><p>Photovoltaic cells</p><p>Low-energy windows</p><p>Correct!</p><p>2.</p><p>Period (1947-1989) when the USA and the Soviet Union were battling for supremacy on the world political stage.</p><p>Low-energy windows</p><p>Privatization</p><p>Photovoltaic cells</p><p>Astronautics</p><p>Cold War</p><p>Correct!</p><p>3.</p><p>Already used in many applications on Earth to produce electric power for homes and cars. They convert light into energy.</p><p>Photovoltaic cells</p><p>Privatization</p><p>Low-energy windows</p><p>Astronautics</p><p>Cold War</p><p>Correct!</p><p>4.</p><p>The process of transferring activities from the public to the private sector.</p><p>Astronautics</p><p>Low-energy windows</p><p>Privatization</p><p>Cold War</p><p>Photovoltaic cells</p><p>Correct!</p><p>5.</p><p>When Mars and the Earth are closest to each other. At those moments, only half the energy would be needed to travel to the red planet.</p><p>Low-energy windows</p><p>Photovoltaic cells</p><p>Cold War</p><p>Astronautics</p><p>Privatization</p><p>Correct!</p><p>Tab through this activity to read the feedback for your answers</p><p>Feedback</p><p>A device that responds to some form of input from its environment such as heat, motion, light, pressure and more.</p><p>Sensor</p><p>Correct!</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('fe4349af5a5782cdd1256db3265c50e1','space-travel-and-solar-system-m1-l2-lesson-1','1e442ea20dd21be26913d1a9f4906fdc','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>SpaceTravel Introduction</h3><p>SpaceTravel Introduction</p><p>Before watching the video, consider the following question:</p><p>What contribution do you think space exploration has made to the advancement of science and technology?</p><p>Welcome back, this is Video 1 of this module on the Introduction to Space Travel.</p><p>Who hasn’t looked up at the stars on a clear night and wondered what is out there? Space beyond planet Earth is the stuff of dreams and possibilities. Are we alone? Was there ever life elsewhere in the galaxy? Is life even possible on another planet in our solar system? Space exploration has only begun to answer these questions but every time a little more information is collected, we get to scratch off a little bit more of the paper covering the mystery. It’s a bit like taking your time ripping up the paper on a birthday present to enjoy that moment of mystery before you discover what the gift is.</p><p>In 1969, Neil Armstrong was the first man to set foot on the Moon. Perhaps more than any other event in space exploration history, this first moon walk remains one of the most celebrated.</p><p>But space travel goes way beyond these important steps on another celestial body. Over the last 60 years, there have been over 300 space flights involving a crew and more than 8,000 man-made objects launched into space.</p><p>Almost 5,000 of these objects are satellites orbiting the Earth providing communication, observation, and scientific services. The GPS function on your smartphone which allows you to use Google maps for example, wouldn’t be possible without satellites. The other objects that have been launched have gone to explore the universe and the planets of our solar system.</p><p>In 2007, Neil Armstrong said: “From the time of our birth, it is our instinct to explore. To map the lands, we must explore. To chart the seas, we must explore. To make new discoveries, we must explore. Three decades have passed since a human being has set foot on another world. It is time for America to take the next steps to explore the Earth, Moon, Mars, and beyond.”</p><p>Armstrong’s words highlight the fact that space exploration is about a lot more than just going into space. You may not realize it but the technology that has been developed to support space travel has completely changed the world on Earth as well. Here’s a list of 9 technologies developed for space you benefit from every day without perhaps knowing it:</p><p>SATELLITE TELEVISION. Ever wondered how networks like CNN can show you images of any event happening on the planet at any time? The first communication television satellite Telstar 1 was launched in 1962. Since then, viewers have been able to see events from all over the planet in real-time.</p><p>WEATHER FORECAST. It used to be difficult to predict the weather. While it’s still by no means perfect, forecasters can follow patterns easily thanks again to satellites and provide the amazing images of hurricanes travelling across the Atlantic Ocean for example. This means people are a lot more prepared than they used to be when dangerous conditions are coming.</p><p>NAVIGATION. Global Positioning Systems or GPS can function because of satellites orbiting the Earth 24/7. So, you can thank space technology the next time you’re looking for the closest pizza place.</p><p>MEDICINE. Monitoring the health of astronauts when they go into space has always been a primary concern. Spacesuits are equipped with all sorts of miniature sensors, which are devices that respond to some form of input from their environment such as heat, motion, light, and pressure, that are the grandparents of wearable technology like today’s fitness trackers.</p><p>ALTERNATE ENERGY. To go into space, scientists had to figure out how to create liquid fuel. So, the next time you hop onto a hybrid bus, chances are you’re travelling on a hydrogen fuel cell that owes its existence to space travel.</p><p>LAPTOPS. The space in a rocket is limited so equipment like computers must be as small as possible. Next time you grab your laptop, remember that it’s small, in part, because of the technology developed for space ships.</p><p>MATERIALS. Over the last 60 years of space exploration, scientists and engineers have created new materials that have made their way into our lives. Both memory foam, used in more and more mattresses today, and space blankets, which you can find in all first-aid kits, were developed in 1966 to protect astronauts.</p><p>ROBOTICS. That one is probably obvious. Any space craft that goes into space is filled with robots that perform all sorts of experiments and collect data in places where humans can’t go yet. That technology can then be used here on Earth. The rover Curiosity for example, is packed full of robotic features that allow it to explore the surface of Mars and send back what it finds to scientists at NASA.</p><p>ENVIRONMENTAL STATE. As you can imagine, there’s no better view of the Earth than from space. Science satellites can keep an eye on the state of the planet such as the level of pollution, forest fires, the oceans, the size of deserts, and many other aspects.</p><p>As you can see, our lives would be very different if it wasn’t for space exploration.</p><p>In 2001, American Dennis Tito spent $20 million to visit the International Space Station (ISS) by hitching a ride on a Russian Soyuz. He spent almost 8 days in space and was the first ever space tourist. Only six other tourists made it to the ISS; all travelling aboard a Soyuz space ship.</p><p>More and more private companies and wealthy investors are funding the development of space crafts for tourism purposes. Virgin Galactic is probably the most famous but seven other companies are also reportedly close to being able to launch tourists into space. Chances are, space vacations could be a possibility within your lifetime. Will it be Europe or the Moon this year? That may be a legitimate question to ask your family in the near future.</p></section><section><h3>Space Travel History</h3><p>Space Travel History</p><p>License:&#160;All Rights Reserved</p><p>Traveling to the Moon in Literature</p><p>From the moment they could observe the stars, humans have been fascinated by outer space.&#160;It’s not surprising then that many would choose to write stories about building machines to travel there.&#160;Here are some novels among the most accurate at predicting the future.</p><p>In 1608, German mathematic<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('524df0497e0a76dfbe0386aa19c4c68d','space-travel-and-solar-system-m1-l3-lesson-2','1e442ea20dd21be26913d1a9f4906fdc','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Space Agencies</h3><p>Space Agencies</p><p>While watching, think about the following questions:</p><p>When you think of politics, you often think of new laws or political parties fighting over an election, but in space?&#160;What kinds of politics can affect space travel and exploration?</p><p>Welcome back, this is Video 2 of this module on the Introduction to Space Travel.</p><p>Until recently all space exploration, travel and science has been the job of governmental agencies, primarily NASA in the USA, Roscosmos in Russia and the European Space Agency (ESA) out of the European Union. But why do these organizations exist and why are they organized the way they are?</p><p>NASA and Roscosmos grew out of the Cold War, that period between 1947 and 1989 when the USA and the Soviet Union were battling for supremacy on the world political stage. Here’s a map of what the world looked like during that period.</p><p>The ESA grew partially out of a need for European countries to have a joint space program, which wasn’t tied to either the USSR or the USA. So, clearly politics has played a large role in space exploration.</p><p>When space travel and exploration was the exclusive domain of governments, you could sort of expect that the exploration and innovations were being done, if not for all humanity, at least for the betterment of the people who lived in the home country of the agency doing the exploration.</p><p>But what about now? The term technopolitics refers to the intersection between technology and politics. And now, more than ever, that intersection is in private, for profit, hands. The best, most obvious example is that of Elon Musk and Space X. While he is perhaps more famous for his Tesla cars, Musk’s Falcon rockets are about to become the only way the USA resupplies the ISS and, soon, sends astronauts there.</p><p>During the Cold War, the launching of satellites and being the first on the Moon drove humans into space. If you look at the US moves into satellite launches and then manned space travel, you see that it was largely driven as a reaction to the USSR entering that domain. But the influence of the US and Russian competition has gone way further than just that first drive into space.</p><p>A perfect example is the Apollo project, designed around the Saturn family of rockets. Its goal was manned space exploration, largely focused on the Moon. These rockets were good at their job, cost effective (for a project as big as landing on another planet) and seem suitable for applications today.</p><p>So, what happened? Why isn’t NASA launching humans and satellites into space using, say, a Saturn 10 rocket? The short answer is, again, the Cold War. The slightly longer answer is “the Cold War and US President Richard Nixon”. With Nixon’s fixation (right or wrong) with the Soviet Union and his desire to launch spy satellites, the idea of a cheaper, reusable, manned space vehicle was born, namely the Space Shuttle.</p><p>While the Space Shuttle program did allow for some amazing science, the main goal was manned satellite deployments. To achieve this, the Saturn rocket program and all other rockets designed for manned space exploration lost their funding. With the shift to orbital and space station-based space work and no heavy lift capability of their own, the US was eventually, ironically, forced to use Russian rockets to deliver astronauts to the ISS.</p><p>In fact, since 1998, the NASA budget compared to the US Government’s total spending has been dropping and doesn’t even get close to 1% as this graphic shows.</p><p>That’s where the politics are now. The appetite for manned space exploration is low but at the same time there’s a push to make it to Mars. The problem is that the government is not really providing resources to accomplish a mission of this size.</p><p>So, what comes next? Unless there’s a sudden increase in NASA’s budget, privatization, which is when public activities are transferred to the private sector, seems to be way forward. The 2019 budget, for example, plans to cut US governmental support to the ISS by 2025. This means that after 2025, the only way a US presence will continue on the ISS is if a private company funds it. The same conclusion is being drawn about low-earth orbit missions, which are flights into space that are just outside the atmosphere.</p><p>So, what are the pros and cons of this shift to private companies taking over for NASA? On the positive side, private companies might be able to do things in a cheaper and more agile way. In theory, this could off-load the cost of space exploration to private companies and save the government a lot of money. The problem is that private industry is driven by profit and may not have any interest in doing some of the more exploratory or scientific work that NASA does because they will see no return on their investment. One idea that experts see as being reasonable is offloading the simpler tasks (like resupplying the ISS, for instance) while NASA focuses on bigger, longer term projects that have no profit incentive.</p></section><section><h3>Space Travel Privatization</h3><p>Space Travel Privatization</p><p>License:&#160;All Rights Reserved</p><p>A Middle Ground?</p><p>While there are those who think that space travel should be left to governmental agencies, the reality is that shrinking budgets and the imposed need to turn a profit has meant that, even at NASA, there is a growing appetite to outsource some of their mundane tasks.&#160;If you think about it, a resupply mission to the ISS is just the space version of truck delivery.&#160;Once you have the technology figured out, it becomes routine.&#160;Robert Frost is an instructor and flight controller at NASA.&#160;In an interview, he said that a lot of work could be outsourced but that companies weren&#39;t interested in pursuing work in which they may not see profits for quite some time.</p><p>The Dangers of Privatization in One Story</p><p>When you cut budgets and you insist on money-saving decisions, you can wind up with some funny, unintended consequences.&#160;Take the decision to end the Saturn rocket program for example.&#160;It effectively left the USA and NASA with no heavy lift rockets, the kind you need to launch satellites into space after the Space Shuttle program was stopped.&#160;The only solution is to buy seats on rockets launched by the Russians.&#160;This has become necessary because the replacement programs, by Boeing a<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('fbc879ab05659d90d3e172718cadebdd','space-travel-and-solar-system-m1-l4-lesson-3','1e442ea20dd21be26913d1a9f4906fdc','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Space Travel Rocket Science</h3><p>Space Travel Rocket Science</p><p>While watching, consider the following:</p><p>Imagine you want to throw an object in the air as high and as fast as you can.&#160;What would you need?</p><p>Welcome back, this is Video 3 of this module on the Introduction to Space Travel.</p><p>A hundred years ago, space travel was the stuff of fiction, but a few visionaries were already making lists of challenges to overcome and checking them off one by one. Here are some of the most challenging aspects of space travel and how they were overcome.</p><p>There are two main types of fuels: solid or liquid. If you’ve done some physics at school, you might remember Newton’s Third Law of Motion:</p><p>“For every action, there is an equal and opposite reaction.”</p><p>This theory is important to understand how rockets are launched. To put it simply, when an engine produces hot exhaust gases, which happens when fuel is burned, they flow out the back of the engine. Based on Newton’s law, this creates an opposite reaction in the form of thrust that propels the rocket into the air.</p><p>You can clearly see the exhaust escaping the bottom end of the rocket as the fuel is burned. This is what’s propelling Space X’s Falcon into the air.</p><p>Now that you understand the importance of fuel, let’s talk about one of the greatest challenges facing space travel: Using the right fuel to propel an object at more than 25 thousand miles per hour, which is the speed needed to escape the Earth’s gravity.</p><p>We already mentioned Konstantin Tsiolkovsky who came up with a mathematical equation in 1903 to calculate what a rocket would need to escape the Earth’s gravitational pull and orbit around the planet. The Russian scientist had figured out that liquid hydrogen and oxygen could be used instead of solid fuel. It matters because liquid fuels are more efficient than solid fuels.</p><p>A perfect example of a solid fuel “rocket” is a firework. Here’s a diagram that shows what’s going on inside fireworks.</p><p>When the fuse is lit, it touches the bottom of the firework first where a compartment holds some gunpowder that ignites and provides the thrust, which is the force that launches the rocket. The amount of gunpowder is calculated carefully because when it’s burnt, the rocket stops going up.</p><p>While this is going on, the fuse continues to travel inside the tube until it reaches another chamber filled with gunpowder and explosives which produce the points of light. The distance between the two caches of gunpowder determines the altitude of the fireworks. This time, when the fuel is ignited, it explodes and produces what we see when we watch fireworks.</p><p>Liquid fuels can provide more precise energy because they can be throttled. It’s a complex process but to put it simply, when you create a pinching point, also called a nozzle or throat, you force the gas to remain in the combustion chamber longer.</p><p>As it expands, it needs more space so it accelerates to create enough space and, as a result it cools down. By the time it escapes the chamber, it’s going faster and provides more thrust.</p><p>Modern rockets use a mix of solid and liquid fuels. Solid fuels are used during the take off because they provide a burst of energy and liquid fuels are used once the rocket clears the atmosphere for more precise maneuvering. With liquid fuels, it’s possible to turn the engine on and off. Once they’re ignited, solid fuels can’t be extinguished.</p><p>Now that the fuel challenge to escape Earth’s gravity has been solved, many scientists are turning their attention to even better fuel that can speed up space ships. Let’s face it, unless we can go a lot faster, chances are we’ll never make it to planets far away in our solar system even if we can figure out how to survive in space.</p><p>To put things in perspective, it would take on average 162 days to fly to and land on Mars based on the speed of the fastest spacecraft ever launched and a number of possible approaches. Reaching the moons of Jupiter would cost you five to seven years of your life. And that’s just a one-way ticket!</p><p>The problem is two-fold: The faster you get off the Earth, the faster you go in space. Once in space, you can’t replenish your fuel to continue propelling yourself. This is the reason why NASA has been looking at methane as a possible fuel. The reason is that it could take astronauts to Mars, where methane has been detected. How astronauts would be able to harvest this methane to propel their engine further down the galaxy remains a mystery.</p><p>Space is not exactly a welcoming environment for humans. Depending on its location, an object can get extremely hot or extremely cold. Space radiation can cause cancer, cataracts and possibly Alzheimer’s. The lack of gravity causes the human body all sorts of problem. And there’s no supermarket to get some food or water. So, staying healthy in space presents a big challenge.</p><p>NASA is working on genetically modified foods (also called Genetically modified organisms, or GMOs) that could be grown in space. Remember that space is a tricky, zero-gravity environment where water bubbles would prefer floating rather than penetrating the soil to feed plants. An engineer at NASA is working on a water filter made of Genetically modified bacteria that could act as a filter that replenishes itself with water.</p><p>One possible solution to many of these problems would be the creation of an artificial gravity, which could be achieved by creating a centrifugal force. A great example of a centrifuge is the washing machine. When it drains the water, it spins at high speed and it pulls all the clothes to the outer walls of the drum. This is essentially artificial gravity.</p><p>Of course, the idea is not to spin the astronauts! Instead, scientists are imagining different shapes of space ships which could have a double wall with the outside one spinning and creating the gravity.</p><p>As you can see, there are still many challenges to overcome if humans are going to explore space beyond the Moon.</p></section><section><h3>Space Missions</h3><p>Space Missions</p><p>License:&#160;No known copyright restrictions</p><p>What do you think are the main challenges facing space travelers?&#160;In its&#160;Time and Navigation:&#160;The untold story of getting from here to here&#160;online series, the Smithsonian lists four major challenges space navigators must overcome.&<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('100265ffb588e7017a5454babf56ef1d','space-travel-and-solar-system-m1-l5-lesson-4','1e442ea20dd21be26913d1a9f4906fdc','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Space Rocket History</h3><p>Space Rocket History</p><p>When you think of the past of space travel and exploration, you probably think of the Space Shuttles or of rockets like the SpaceX Falcons.&#160;But how far back do you think the history of thinking about rockets for space stretches?</p><p>Welcome back, this is Video 4 of this module on the Introduction to Space Travel.</p><p>As far back as 1813, scientist like William Moore in the UK were writing about launching rockets into space. His work was independently added to by Konstantin Tsiolkovsky, the Russian scientist mentioned earlier, who published “The Exploration of Cosmic Space by Means of Reaction Devices,” considered to be the first serious work showing how, in theory, humans could reach space.</p><p>From here things start going from the theoretical to the applied. Robert H. Goddard filed for a patent for multistage and liquid-fueled rockets, wrote an influential paper called &quot;A Method of Reaching Extreme Altitudes&quot; and then, on March 16, 1926 launched the world’s first liquid fueled rocket.</p><p>In Germany at about the same time, Hermann Julius Oberth, was following the same path as Goddard. In just 6 years, he went from self-publishing his rejected thesis &quot;By Rocket into Planetary Space&quot; to launching his first liquid fueled rocket.</p><p>As with many human inventions, scientists also saw some the destructive potential of rockets. As early as the 1920s, scientists such as Robert Esnault-Pelterie, considered to be one of the fathers of modern rocketry, were publishing papers discussing the use of rocket for bombardments.</p><p>The idea really took flight in 1933 when Wernher von Braun started work on what would become the V2 rocket. This weapon would result in the death of over 9,000 civilians and 12,000 forced laborers who helped build the rockets. Along the way, it would also become the first rocket to travel into space. This is why, once the Nazi German regime collapsed, most of the V2 rocket scientists were offered jobs at NASA.</p><p>From 1946 onwards, civilian space programs in the USA and USSR began to accelerate. The milestones might seem simple by today’s standards–first picture of Earth from 105 kilometers, first animals in space (fruit flies!?), first dogs in space–but they each represented a huge leap forward towards space travel. Then in October of 1957 came a real breakthrough and wakeup call for the US space program: the launching of the world’s first satellite by the USSR. Sputnik was more of a research and propaganda tool than a satellite in today’s understanding of the term.</p><p>Over the next 11 years, humankind went from being able to put an object like Sputnik in a temporary orbit, to taking pictures of the Earth from space, to the first human space flight by Yuri Gagarin of the USSR.</p><p>From the moment that humans made it to space, it was just a matter of time before someone landed on the Moon. On July 20, 1969, the USA’s Apollo 11 crew, made up of Neil Armstrong, Michael Collins and Buzz Aldrin landed on the Moon and then relaunched and returned to Earth.</p><p>Once the Moon landing was made, attention shifted to sending probes and rovers to distant planets and to establishing more permanent presence in space. In 1971 the USSR put up Salyut 1, the first manned space station followed by Mir in 1986. The current International Space Station (or ISS) became operational in November of 1998.</p><p>Simultaneously with the development of the ISS was the development and flights of the Space Shuttle program by NASA.</p><p>More recently the USA, the ESA and Russia have also clocked up impressive feats of exploration with unmanned vehicles, from rovers on Mars, to landings on comets. Other countries have completed feats in space as well. Israel’s Beresheet Moon Lander was supposed to land on the moon, but ended up crashing instead. Japan landed a probe on an asteroid (and detonated an explosive on the surface!). Clearly the reach for outer space has the interest and imagination of people all across the world.</p></section><section><h3>NASA Technologies and Products</h3><p>NASA Technologies and Products</p><p>License:&#160;No known copyright restrictions</p><p>But What’s in it For Us?</p><p>One of the questions that NASA and other space agencies always face is a variation on the “what’s in it for me” question.&#160;They face this from governments, politicians and normal everyday citizens.&#160;We spend a lot of money on space exploration and things like the ISS, and it feels like we should get something back in return.</p><p>It turns out that NASA technology has impacted our lives in ways you probably never even thought of.&#160;Did you have a good night’s sleep last night?&#160;If you did it on a memory foam bed, you’re sleeping on some of your tax dollars and NASA research in action.&#160;Temper foam, or memory foam, was first developed at NASA to protect airplane passengers in a crash.&#160;It’s now used in beds, pillows and several other safety and comfort applications.</p><p>Smooth drive into school today?&#160;As early as 1971, Goodyear was using the technology they helped develop to make parachutes, make better radial tires, and help the Viking explorer land more softly on Mars.</p><p>When your baby brother or sister was born, did a nurse or doctor check their temperature with a thermometer in their ear?&#160;That&#39;s a spin-off from 1991 that uses the same technology NASA uses to measure the temperature of stars and planets.</p><p>Detection of chemical weapons, improved mine safety, better firefighting equipment, safer landmine removal, artificial heart pumps and, oddly, cordless vacuums, all have their roots in NASA programs and technology.</p><p>Expand each item in the list below to learn about other everyday products based on NASA technology.</p><p>License:&#160;No known copyright restrictions</p><p>Cordless Power Tools</p><p>Intended Use: NASA developed cordless power tools for use in space missions, where the absence of gravity made it challenging to use traditional corded tools.</p><p>Technology Impact: The development of lightweight, battery-powered tools without cords revolutionized the power tool industry. Cordless drills, saws, and other tools provide portability, convenience, and freedom of movement, enabling easier and more efficient construction, repairs, and DIY projects.</p><p>Water Purification Systems</p><p>Intended Use: NASA developed advanced <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('913e7671b31240050468ece7d6a11c1e','space-travel-and-solar-system-m1-l6-lesson-5','1e442ea20dd21be26913d1a9f4906fdc','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Space Exploration</h3><p>Space Exploration</p><p>Now that you know a lot more about space travel and its challenges, what do you think the future will bring?</p><p>Welcome back, this is Video 5 of this module on the Introduction to Space Travel.</p><p>After celebrating its 60th anniversary, NASA continues to push the boundaries of space research and travel. But the US is not alone with Russia anymore. China is also capable of sending people into space and more and more groups and countries like Europe, India and Japan also have solid space programs.</p><p>So, what does the future of space travel and exploration have to offer?</p><p>The Moon was the first destination for astronauts. After a first manned landing by Apollo 11 in 1969, it was explored many more times by both the Soviet Union (now Russia) who landed a rover in 1970, and the US. To this day, only American astronauts have set foot on the Moon. A total of 12 Americans walked on the Moon and six explored the surface in rovers.</p><p>When people start talking about travelling to Mars and beyond, the Moon practically seems like it’s just around the corner. It’s not surprising then, that many countries have plans to build permanent stations on the surface or in obit while others are talking about mining operations on our nearest neighbor. NASA for example, is studying plans to place the Gateway, a similar version of the ISS in orbit around the Moon to test different technologies in partnership with US companies.</p><p>Here’s a graphic produced by NASA showing its future plans. As you can see, there’s a lot of activity planned around the Moon including plans to map its resources and see if they can be mined.</p><p>Mining in space has become a hot topic. Not only are countries like China talking about potential resources to be mined on the Moon but others like Germany, the US and Japan have been attempting to land on asteroids to collect samples, something that’s proven quite tricky because asteroids spin quickly, they often don’t have flat surfaces, and they have very little gravity.</p><p>Asteroids are rocks of different sizes and shapes that orbit around the Sun but are too small to be planets. The biggest one is Ceres. It looks like a planet but it’s much smaller. China plans to send a mission to Ceres in the 2020s to collect samples.</p><p>You might be wondering why countries should bother trying to land on asteroids if it’s so hard. Well, because many scientists think they might contain water. If they do and that water can be accessed by passing space ships, it could be turned into hydrogen and oxygen and used as fuel to travel further. Think of it as a gas station on your way to Jupiter. Planetary Resources, which is an asteroid mining company, estimates that the 16,000 rocks that are spinning near Earth could hold two trillion tons of water!</p><p>Finding water on asteroids and developing a way to mine it could help future missions to Mars. After the Moon, Mars is the most studied planet in our solar system. Many robotic explorers including probes, rovers, orbiters, have been sent to study it and are still active.</p><p>After roaming the surface, the Curiosity rover is supposed to start drilling and delivering samples this year, if the scientists can get the drill working again. Its older brother, the Opportunity, will continue to roll around the planet 15 years after it landed. Rovers are providing crucial information to prepare for an eventual human landing such as the best landing sites and the location of water.</p><p>But this is just the beginning. NASA has big plans for Mars as shown in this graphic. It’s gradually collecting information and building the stepping stones to eventually send a crew during the next low-energy window, which is in 2033. Low-energy windows happen when Mars and the Earth are closest to each other. At those moments, only half the energy would be needed to travel to the red planet.</p><p>As astronauts go further and further and technology makes space travel easier, it’s not surprising to see companies wanting to offer common people a chance to see the Earth from outer space. No technical skills required, but you might need to pass minimal fitness tests. And, mostly, you’ll have to pay quite a lot of money for the privilege. Virgin Galactic wants a $250,000 dollar deposit to reserve your seat on one of its flights!</p><p>Billionaire Richard Branson’s Virgin Galactic will use its WhiteKnightTwo jet aircraft to take up to six passengers at an altitude of 50,000 feet before releasing them in the SpaceShipTwo and letting them make their way back to Earth.</p><p>Another billionaire, Amazon’s Jeff Bezos, has also launched his space flight company Blue Origin. So far, he says he only wants to make space travel safer and cheaper, but hundreds of people have already shown an interest in flying on the company’s space ships.</p><p>Another company… and billionaire, Elon Musk’s Space X, has been flying missions for years now. Its Dragon rocket has been delivering cargo to the ISS since 2012. So far, no tourists on its flights but Musk has promised to take two paying tourists around the Moon.</p><p>People who have gone to space describe feeling dizzy and nauseous. They forget which way is up and feel disoriented because their blood is rushing to their heads since it’s not being pulled down by gravity. Still interested?</p><p>As you can see, space travel and exploration are only beginning. The next 50 years promise to be quite exciting!</p></section><section><h3>Future of Space Travel</h3><p>Reading 5</p><p>(opens in a new tab)</p><p>2004 Class of Astronauts&#160;by NASA</p><p>License:&#160;Public Domain</p><p>Flying on All Cylinders</p><p>It&#39;s hard to believe NASA is already 60 years old.&#160;We&#39;ve learned so much since it began exploring space in 1958.&#160;Using telescopes, satellites, probes, landers, rovers, a space station as well as astronauts, NASA and its partners have increased our knowledge of our planet and solar system beyond expectations.&#160;Not resting on its many successes, NASA has more projects on its to-do list than ever.&#160;Watch this short video to get a sense of where it’s going:</p><p>[ MUSIC ]Since its inception, the International Space Station has been powered by large, heavy and complex solar panels. But, as expected, these panels have slowly degraded over time. As a part of an experiment, the station&#39;s robotic arm unfurled the first ROSA - Roll Ou<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6f7c21741fcd3f6009b5907bd183335b','space-travel-and-solar-system-m1-l7-module-1-summary','1e442ea20dd21be26913d1a9f4906fdc','Module 1 Summary','text',12,'<h2>Module 1 Summary</h2><section><h3>Module 1 Summary</h3><p>Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Intro to Space Travel!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Outlined the history of space travel and contrast past technological changes with current opportunities</p><p>Analyzed the political history of space travel and its impact on innovation.</p><p>Discussed the challenges space travel has faced over the last century and the solutions which overcame them.</p><p>Constructed a timeline of innovation, technological advances, historical turning-points, successes, and failures within the last century identifying prominent figures which impacted space travel.</p><p>Previewed the goals, plans, and possibilities for space travel over the next 50 years, including moon and Mars exploration, space tourism, and asteroid mining.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('fff7a2898dbc61161cf86593ebe3d67b','space-travel-and-solar-system-m1-l8-short-answer-assignment','1e442ea20dd21be26913d1a9f4906fdc','Short Answer Assignment','text',12,'<h2>Short Answer Assignment</h2><section><h3>Short Assignment</h3><p>3300</p><p>Space Travel</p><p>Intro to Space Travel - Short Answer Assignment</p><p>Short answer assignment</p><p>Based on what you’ve learned in this module, choose&#160;one&#160;of the following questions and answer it on a two-page, double-spaced paper, and explain your answers:</p><p>What do you think the future of NASA, and space exploration, is? Remember to refer to the readings and videos to back up your answer.</p><p>What do you think the most important step towards making space travel possible was? Remember to refer to the readings and videos to explain your answer.</p><p>Intro to Space Travel</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('251fdae1282aca6433b0dd2c429241d5','space-travel-and-solar-system-m1-l9-module-1-project','1e442ea20dd21be26913d1a9f4906fdc','Module 1 Project','text',12,'<h2>Module 1 Project</h2><section><h3>Module 1 Project</h3><p>3300</p><p>Space Travel</p><p>Intro to Space Travel - Project</p><p>Project</p><p>For this project, imagine you are hosting a dinner party with 6 people (including yourself) in the history of Space Travel. You can include people mentioned in this module and also find additional figures in the history of Space Travel to include. They can be people that are living or deceased.</p><p>Create an invitation for this party and explain its purpose</p><p>Create a seating chart</p><p>Create a three-course menu (for example, you could serve Italian food for your guest of honor, Galileo Galilei, since he is Italian)</p><p>Then, in a few paragraphs, address the following questions:</p><p>Who would you invite and why?</p><p>Why have you arranged the seating the way that you did?</p><p>What topics would you discuss?</p><p>What questions would you want to ask to each guest?</p><p>What do you think each person would be surprised at in modern Space Travel?</p><p>Intro to Space Travel</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Invitation, Seating Chart, and Menu</p><p>8 points The presentation demonstrates a strong understanding of space travel, its history, and current participants. It contains all the necessary details about at least five figures in the history of space travel.</p><p>7-6 points The presentation demonstrates a moderate understanding of space travel, its history, and current participants. It contains most of the necessary details about at least five figures in the history of space travel.</p><p>5-0 points The presentation demonstrates little to no understanding of space travel, its history, and current participants. It contains little to no necessary details about at least five figures in the history of space travel.</p><p>8</p><p>Questions and Topics</p><p>8 points All questions are answered thoroughly the the topics of discussion relate directly to the topics of this module.</p><p>7-6 points Most questions answered thoroughly and the the topics of discussion somewhat relate to the topics of this module.</p><p>5-0 points Little to no questions are answered thoroughly and the the topics of discussion show little to no relation to the topics of this module.</p><p>8</p><p>Formatting</p><p>2 points Includes the required content and is formatted neatly.</p><p>1 point Does not include all required content or is not formatted neatly.</p><p>0 points Does not include all required content and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c7a2c1bd7a9f5d3fd3210cf479c2f184','space-travel-and-solar-system-m1-l10-module-1-quiz','1e442ea20dd21be26913d1a9f4906fdc','Module 1 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Intro to Space Travel. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('7302789819b068cbc13e2f545a65e7b7','space-travel-and-solar-system-module-2','2a892040eda1f32ee69b17d25aad96dd','Module 2: Apollo and Shuttles',2) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2f2005a33100c20c4a7ce644e5dcbd6d','space-travel-and-solar-system-m2-l1-introduction-purpose-and-objectives','7302789819b068cbc13e2f545a65e7b7','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi, I’m Ms. Jacobs, and I’ll be one of your instructors for this course on the Future of Space Travel. This is the intro video on The Apollo and Shuttle Programs.</p><p>This module reflects on the history of missions to outer space from the initial attempts to put a man on the Moon to the many missions that followed. You will learn about key moments in space travel history throughout the world constructing a timeline of events and discoveries.</p><p>Rather than just focusing on the successes, you will also learn about the challenges, failures and even deaths associated with space exploration. You will be expected to sift through the evidence to try and decide if the rewards of space travel are worth the risks. Speaking of rewards, this module will turn the focus from the products and monetary rewards gained through space travel and exploration and, instead look more closely at the pure scientific discoveries afforded by space programs.</p><p>Throughout the module, we will look at some key moments in space travel, with an emphasis on the early days of space travel and the Apollo Project. We’ll move on to the Space Shuttle program, as well as a look at probes, space telescopes and rovers.</p><p>Apollo 11 Saturn V lifting off on July 16 1969&#160;by NASA</p><p>License:&#160;Public Domain</p><p>In this module, you will learn about key moments in the history of space travel and exploration.&#160;We will drill down into the accidents and failures that lead to the successes we know today.&#160;Throughout, we’ll focus on specific eras and projects to see what they achieved and the kinds of obstacles they faced.&#160;Along the way, you’ll meet some of the astronauts who tasted victory and learn the names of those who paid the ultimate price while trying to expand humankind’s understanding of the galaxy.</p><p>You’ll also learn that putting humans into space might get the most media interest, but that some of the biggest scientific discoveries have been made by probes and telescopes.&#160;We’ll also take some time to look more closely at some of the biggest failures of the space age.&#160;So, buckle up, it’s going to be an interesting and bumpy ride.</p><p>Objectives</p><p>In this module, you will:</p><p>Compare and contrast the space programs in China, the U.S, and the Soviet Union/Russia identifying time periods of competition between these entities</p><p>Discuss the Apollo Missions and their benefit to space travel today</p><p>Evaluate the construction of Space Shuttles over time and the innovations which have led to today’s Space Shuttle</p><p>Analyze a sample of failed space missions and the mechanical or human error associated with the failure.</p><p>Discuss successful space missions and their significant impact on history</p><p>Polling Question</p><p>What are the biggest moments in space exploration and discovery?</p><p>The moon landing&#160;Launch of the Space Shuttle&#160;Hubble Telescope</p><p>Make a selection to see the results so far.</p><p>How did your answer compare to your classmates?&#160;Let’s see how your answer changes as you learn more about the history of space exploration.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>When a spacecraft docks or anchors to another craft or station.</p><p>Laser-ranging device</p><p>When a drill bit open at one end is pushed into the surface so that the hollow part gets filled with the sample.</p><p>Berthing</p><p>Someone who studies the materials that make up the Earth, and in this case the Moon, to see how it evolved.</p><p>Geologist</p><p>Equipment designed to make measurements.</p><p>Core-tube samples</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>When a spacecraft docks or anchors to another craft or station.</p><p>Berthing</p><p>Laser-ranging device</p><p>Core-tube samples</p><p>Geologist</p><p>2.</p><p>When a drill bit open at one end is pushed into the surface so that the hollow part gets filled with the sample.</p><p>Core-tube samples</p><p>Geologist</p><p>Laser-ranging device</p><p>Berthing</p><p>3.</p><p>Someone who studies the materials that make up the Earth, and in this case the Moon, to see how it evolved.</p><p>Core-tube samples</p><p>Laser-ranging device</p><p>Geologist</p><p>Berthing</p><p>4.</p><p>Equipment designed to make measurements.</p><p>Berthing</p><p>Core-tube samples</p><p>Laser-ranging device</p><p>Geologist</p><p>Small boards, usually made of silicon and packed with circuits for microprocessing and memory</p><p>Sub-orbital</p><p>A device that sends waves through a planet to get a sense of its internal structure.&#160;It can also be used to detect seismic events like moonquakes or the impact of debris or meteoroids.</p><p>Seismic detector</p><p>Any vehicle meant for travel or operation outside of Earth’s atmosphere.&#160;Includes both vehicles with and without human crews .</p><p>Microchips</p><p>When an object is launched into outer space and then falls back to Earth, which means it doesn&#39;t orbit.</p><p>Spacecraft</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Small boards, usually made of silicon and packed with circuits for microprocessing and memory</p><p>Sub-orbital</p><p>Seismic detector</p><p>Microchips</p><p>Spacecraft</p><p>2.</p><p>A device that sends waves through a planet to get a sense of its internal structure. It can also be used to detect seismic events like moonquakes or the impact of debris or meteoroids.</p><p>Microchips</p><p>Sub-orbital</p><p>Spacecraft</p><p>Seismic detector</p><p>3.</p><p>Any vehicle meant for travel or operation outside of Earth’s atmosphere. Includes both vehicles with and without human crews .</p><p>Microchips</p><p>Seismic detector</p><p>Sub-orbital</p><p>Spacecraft</p><p>4.</p><p>When an object is launched into outer space and then falls back to Earth, which means it doesn&#39;t orbit.</p><p>Spacecraft</p><p>Seismic detector</p><p>Microchips</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a9ef272892b02be5be9924cc41317fc3','space-travel-and-solar-system-m2-l2-lesson-1','7302789819b068cbc13e2f545a65e7b7','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Different Countries Space Program History</h3><p>Different Countries Space Program History</p><p>While watching these videos,&#160;think about the following:</p><p>When you think of space exploration, you probably think of the Russians and the USA.&#160;Which other countries do you think have made significant contributions to space travel and exploration?</p><p>Hi and welcome to Video 1 for this module on The Apollo and Shuttle Programs.</p><p>It’s pretty clear the Russians and Americans get all the glory and attention but are they the only countries doing space exploration? Hardly! In fact, the Indian Space Research Organization successfully launched a probe to Mars, with their own rocket, on their very first try and for a budget of about $75 million, roughly ten percent of what NASA spent on a comparable mission.</p><p>Let’s have a look at the most active space agencies and their milestones and then spend some time focusing on historical space races, and the ones that are ongoing.</p><p>We already know that India has its own space program, with satellite launching capabilities and the ability to send a probe to Mars, but which other countries are playing a role in space exploration?</p><p>China is one of the three countries, with the USA and Russia, who are capable of launching humans into space. With the second largest fleet of spacecraft in orbit, China also has a crewed space flight program and have launched two space stations of their own Tiangong-1 and Tiangong-2. Both stations have been visited by crewed and automated spacecraft and were launched as prototypes and tests for the larger station China plans to start assembling in space as of 2019.</p><p>The Japanese Aerospace Exploration Agency (JAXA) is a bit of a dark horse. They don’t do a lot of flashy “look at me!” projects, they just get out and about putting things into space really, really well. They have been launching satellites since 1970 and are very active in satellites that monitor the Earth’s atmosphere.</p><p>One of their areas of research is the concept of “solar sails”. Essentially, it’s a spacecraft like a small probe for example, that uses a sail or kite deployed as a solar panel to collect solar energy which it then uses to power itself. Here’s what it looks like:</p><p>The project is called Japanese Interplanetary Kite-craft Accelerated by Radiation Of the Sun (or IKAROS). It was designed to reach Venus, which it passed in December of 2010. It got as far as 230 million kilometers from Earth and is now in orbit around the Sun. Pretty impressive considering it’s only 50 square feet!</p><p>Ok, this is cheating a bit, because the European Space Agency isn’t one country, but it is one of the biggest space agencies. Two of its biggest contributors, France and the United Kingdom, are countries though and both have made significant contributions to space exploration, as part of the ESA and individually. The ESA’s headquarters is in Paris and many of their launches take place in their overseas department, French Guiana. The UK also has a substantial satellite fleet in orbit around the Earth and was one of the major contributors to the ExoMars program, which put a satellite in orbit around Mars.</p><p>Snow? Sure. Hockey?Absolutely.Space?Really? Yes, really. Canada was the third country to put a satellite into space and built the Shuttle Remote Manipulator System (SRMS) for the Space Shuttle program. If you’ve ever seen pictures of a robotic arm deploying a satellite from inside one of the Space Shuttles, or being used to inspect the exterior of one for damage, then you’ve seen the SRMS, or Canadarm, in action. The country also contributed 1.4 billion dollars to the construction of the International Space Station (ISS), including providing Canadarm 2, a larger version of the original.</p><p>Basically, all of these other programs exist in the shadow of the original two big space programs, and their race for firsts in space.</p><p>Let’s take a quick tour through the history of the important decades in the Russian and United States’ space programs:</p><p>In the mid 1950s the Cold War was starting to look like it might heat up. Part of the reason everyone was keen on rockets and spaceships in general, was that the Second World War had shown countries what military rockets could do. Space was also unclaimed territory, and both the USSR and the USA were scared that the other would dominate and have some kind of strategic/military advantage. Into this world, in 1957, was launched Sputnik (the Russian word for “traveler”), which was the first satellite.</p><p>Suddenly the Americans were behind. They responded in 1958 with the launch of the first US satellite, Explorer 1. In the same year, NASA came into existence. In 1959, the Russians managed to send the first probe, Luna 2, which was designed to crash into the Moon. The 1960s were the busiest years, and probably the most exciting, of the early space programs. On the Soviet side, cosmonaut Yuri Gagarin became the first person to orbit the Earth in Vostok 1 in April of 1961.</p><p>The US tested their Mercury capsule with chimpanzees, and then, finally, in May of 1961 Alan Sheppard went into space but it wasn’t until 1962 that John Glenn became the first American to orbit the Earth.</p><p>At this point NASA went into hyper-drive. Their budget increased by 500% and their number of employees ballooned to over 400,000 (between direct NASA employees and contractors at other companies). All of them were focused on getting to the Moon before the Soviets.</p><p>Even though the Americans didn’t know it at the time, the Soviet program was struggling. They suffered the death of chief engineer and founder of the Soviet space program, Sergey Korolyov. They also debated internally about the utility of going to the Moon.</p><p>In December of 1969, Apollo 8 became the first space mission to put humans in orbit around the Moon. Shortly thereafter on a date that’s now famous, on July 20th, 1969, Neil Armstrong became the first human to walk on the Moon.</p><p>Setting foot on the Moon was an important milestone in the history of humanity! But once it was achieved, the space race started to lose steam. Russians tried four times to launch lunar landers but one of their test rockets blew up on the launch-pad in what was the largest rocket explosion ever. The space race, at least symbolically, ended with the so-called “handshake in space” where a US Apollo rocket docked with a So<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8b0e3b3b7c353ad54e7c5970da7bfe15','space-travel-and-solar-system-m2-l3-lesson-2','7302789819b068cbc13e2f545a65e7b7','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Apollo Moon Landing</h3><p>Apollo Moon Landing</p><p>There’s no doubt the Apollo missions were exciting and groundbreaking, but do you think they taught us things that are still applicable today?</p><p>Welcome back, this is Video 2 of this module on The Apollo and Shuttle Programs.</p><p>Even though it’s relatively close, we really didn’t know very much about the Moon until we landed on its surface. Given that it’s our closest neighbor, this is an odd state of affairs. The Apollo missions changed all of this.</p><p>Take Apollo missions 8 (December 21, 1968) and 10 (May 18, 1969) for example. Both were test missions, meant to make sure that different components of the lander and orbiter modules were working correctly. But, because they were doing this while in orbit around the Moon they had the opportunity to photograph and collect scientific observations about the Moon’s surface.</p><p>Apollo 11 (July 20, 1969), the first to land on the Moon, delivered even more knowledge. In the 21 hours Armstrong and Aldrin spent on the surface, they deployed scientific equipment, including a laser-ranging device designed to make measurements, and a seismic detector that sent waves through the Moon to get a sense of its internal structure and is used to detect seismic events like moonquakes or the impact of debris or meteoroids. The mission also collected a large sample of lunar material, as well as two core-tube samples of the Moon’s surface which are obtained when a drill bit, open at one end, is pushed into the surface so that the hollow part gets filled with the soil. They also took many pictures, both panoramic of the landing zone and close ups of the surface.</p><p>Subsequent missions deployed even more scientific equipment and experiment packages. Astronauts brought home even more samples. Apollo 15 (July 26, 1971) included the first deployment of the Lunar Roving Vehicle, basically a dune buggy for space, which allowed the crew to explore further away from their spacecraft.</p><p>Finally, during Apollo 17 (December 7, 1972) the crew managed to drive a total of around 100 kilometers (around 62 miles). This mission returned the largest cache of samples from the Moon, as well as scientific equipment from earlier missions. Interestingly, Apollo 17 was the first mission to have a professional geologist, Harrison Schmitt, on board. A geologist is someone who studies the materials that make up the Earth, and in this case the Moon.</p><p>The goal of “landing a man on the moon and returning him safely to the earth,” which is a famous quote from President John F. Kennedy from 1961, is a pretty good one, but the Apollo missions wanted to do more than landing men on the Moon. They wanted to do the following:</p><p>- Establish the technology to meet other national interests in space.</p><p>- Achieve preeminence in space for the United States.</p><p>- Carry out a program of scientific exploration of the Moon.</p><p>- Develop people&#39;s capability to work in the lunar environment.</p><p>It’s pretty clear that the Apollo missions managed these goals, but what about any benefits? In the first module, we talked about some of the products and services that exist because of NASA such as GPS navigation and other products, but we didn’t mention the way the space race, and Apollo specifically, impacted just about every aspect of our lives.</p><p>It’s possible you’ve come across the meme online that says: “the iPhone is more powerful than all of the computers that put the Apollo astronauts on the moon.” Did you think this was a joke? Well, it turns out to be true! That said at the time, the Apollo Guidance Computer (AGC) was at least 10 years ahead of its time and, unlike today’s iPhone, it was very stable and… crash proof. So, how did a computer like the AGC influence today’s technology?</p><p>The short answer is size and weight. The longer answer is perhaps best explained by Daniel Lockney, the editor of Spinoff, NASA&#39;s annual publication which showcases NASA projects with the private sector. He said:</p><p>MASS INTO SPACE = MONEY</p><p>What does that mean exactly? Well, the cost for putting one pound into space is about $10,000. You can imagine that a computer like the IBM 360 mainframe, which took up most of a room, can’t possibly be launched into space. Clearly, something smaller was needed (not to mention something that used a lot less energy).</p><p>The need for smaller and lighter technology triggered the era of the integrated circuit, the ancestor of the modern microchip. Microchips, which are small boards packed with circuits for micro processing and memory, are at the center of all our modern technology. We owe a great debt to the Apollo missions that have made our computers smaller, lighter, faster, and less power hungry. So, while it’s fun to make fun of the early computers and compare them to today’s phones, the phone wouldn’t exist if it wasn’t for those early computers and the need to make them smaller and lighter.</p><p>In many ways, the effects of Apollo and its legacy can’t be measured purely in inventions made, or cellphones sold, but in the way it transformed our attitude towards innovation and technology. For good or for ill, they popularized the attitude of “grind away at a problem in a room with all the smartest people you can find.” This attitude has become the default template for Silicon Valley and the whole tech industry.</p><p>But perhaps the greatest impact of the Apollo missions is the way it allowed us to really see the Earth. In fact, many people think that the modern environmental movement really gained traction after two photos by NASA were published:</p><p>Blue Marble, a photo taken by the crew of Apollo 17 on their way to the moon, was one of the first images of the entire planet. It shows the entirety of the Earth’s Southern Hemisphere, with Africa and most of Asia in view. Some people believe it is the most reproduced image ever.</p><p>Earthrise, which was taken in 1968, shows the Earth “rising” above the horizon of the Moon. It was taken by astronaut William Anders during the Apollo 8 mission to the Moon. It too became an image symbolic of the Earth’s fragility and how it’s all we’ve got.</p><p>In the end, the Apollo missions, which ran from 1961 to 1972, left humankind with a much better understanding of the Moon but also the Earth. They set up the future of space travel and gave us a solid base for technological advancement.</p></section><section><<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7d16b064613aa27d85d1aac918cf06c4','space-travel-and-solar-system-m2-l4-lesson-3','7302789819b068cbc13e2f545a65e7b7','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Post Apollo 11 Advancement</h3><p>Post Apollo 11 Advancement</p><p>While watching this video, keep an eye out for answers to the following questions:</p><p>Most people know that it was an Apollo that reached the Moon, but do you know what the Space Shuttle program accomplished?&#160;How about when it started?&#160;Were you aware that it ended?</p><p>Welcome back, this is Video 3 of this module on The Apollo and Shuttle Programs.</p><p>People born after 1972 weren’t around when the Apollo rockets were going to the moon. Instead, the Space Shuttles have been the most recognized space ships of the last 30 years.</p><p>But first, let’s go back to the mid 1940’s when World War 2 was coming to an end. After the Nazi Germans surrendered, the Americans, British and Russians all rushed in to grab as many German rocket scientists and V2 rockets as they could. They also picked up other prototypes and plans.</p><p>One of them was for a long range, sub-orbital flying bomber which was to be launched into outer space from Germany before descending all the way to America on bombing raids. Different plans were submitted. One of the most promising was by Eugen Sanger, a German engineer. He came up with a design for a reusable, winged rocket called Silbervogel, or “Silver Bird” in German. The idea never got built, but it was interesting enough that it spawned the American rocket-powered X-15 plane. It also influenced the Dyna-Soar military space plane, which was cancelled but looked a lot like the future shuttle.</p><p>All of this happened in the 1950s so you might wonder why it took until around 1972 to really start the Space Shuttle program. Well, as you saw in the last module, NASA was pretty busy in the 50s and 60s, what with the small matter of beating the Russians to the Moon.</p><p>But in 1972 under U.S. President Richard Nixon, once the landing on the Moon was achieved, the Space Shuttle really came back to life. By 1981, STS-1, the first Space Shuttle mission, was launched. This first mission was a test flight and carried only two crew members, Commander John W. Young and Pilot Robert L. Crippen.</p><p>Do you think it was easy to switch from Apollo rockets to reusable space shuttle rockets? I mean, it’s rocket science, how hard can it be? Well, it took over 10 years to get the Space Shuttle flying. Apollo rockets, were meant to be used once and then discarded. The shuttle would be a reusable spacecraft that was meant to perform many different missions and tasks in space.</p><p>Before NASA could launch the first shuttle in 1981, they had to work out a number of technical problems. First, would the thing fly? Think about it, until then space was reached by strapping a relatively small capsule to the top of a really big rocket. The capsule would orbit or land on the Moon, then it would come back to Earth, parachute into the sea and get scooped up by a Navy ship. The capsule would never be used again. Now, the plan was that the Space Shuttles, or orbiters, would be strapped to a HUGE booster rocket, be shot into space. Then they’d orbit the Earth and dock with the ISS, re-enter the Earth’s atmosphere, glide to a gentle landing like an airplane. After that, they’d get repaired and, theoretically, be able to do it again fairly quickly. Easy peasy, right?</p><p>Well, despite the challenges, that generation’s engineers and scientists ultimately created 5 shuttles, which flew 135 missions with a total of 355 astronauts over a 30-year period. Let’s take a look at some of these key dates in sequence:</p><p>January 5th, 1972: US President Richard Nixon signed the bill authorizing $5.5 billion of funding for the creation of the Space Shuttle program.</p><p>September, 1976: The Enterprise, named for the Star Trek spaceship, is unveiled. This prototype, without engines or heat shields, was never destined to fly in space, but was designed to test in atmosphere flight characteristics.</p><p>April 12, 1981: LIFTOFF! The first Space Shuttle, Columbia, went into space. For 54 hours, the crew tested the Space Shuttle’s systems and then landed back on Earth. Mission accomplished!</p><p>November 11, 1982: The first “operational” flight of the Space Shuttle program, and the 5th flight for Columbia. This flight featured a larger crew of four and deployed two satellites. It was also meant to feature the first spacewalk of the program, but one of the astronauts was sick and the spacesuits were found to be malfunctioning.</p><p>April through August 1983: In the year 1983, there were some important firsts in the NASA program. In April of that year, Sally Ride became the first American woman to fly into space. She went on to fly another mission, worked on several key roles at NASA, taught physics and, as far as we know, is the only LGBT astronaut in history.</p><p>In August of the same year, GuionBluford became the first African American astronaut to go to space. An ex-US Airforce fighter pilot, flight instructor, Ph.D. and engineer, Bluford joined NASA in 1979 and would go on to fly on four Space Shuttle missions.</p><p>January 28, 1986: Seven NASA crew members were killed when the Space Shuttle Challenger exploded shortly after liftoff. NASA grounded the Space Shuttle fleet and investigated, discovering that a faulty o-ring (gasket) was at fault. The Space Shuttles would remain grounded until 1988, when they returned to launching satellites, as well as deploying and servicing the Hubble Space Telescope.</p><p>August 1995: The Space Shuttle Atlantis docks with the Russian space station Mir, the first US-Russian space mission.</p><p>December 1998: The Space Shuttle Endeavor carries part of what would become the ISS into space to be attached with the Russian “Unity” capsule which was already orbiting the Earth.</p><p>February 2003: The Space Shuttle Columbia breaks up as it’s reentering the Earth’s atmosphere. It is later determined that the failure was because some of the heat shields had been damaged by debris when it was being launched.</p><p>February 2011: Discovery launches with the last US piece of the ISS. It is its 39th and final flight.</p><p>May 2011: Endeavor’s 25th and last flight to deliver a $2 billion-dollar particle detector into space.</p><p>July 2011: Atlantis launches for a 12-day resupply mission to the ISS. It’s the shuttle programs last flight. After 30 years and 135 flights, the Space Shuttle era finally came to an end.</p></section><section><h3>Space Program and Space Shuttles Miss<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('975cea71c0e016768c1200450e8f8718','space-travel-and-solar-system-m2-l5-lesson-4','7302789819b068cbc13e2f545a65e7b7','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Astronauts Space Travel</h3><p>Astronauts Space Travel</p><p>Welcome back, this is Video 4 of this module on The Apollo and Shuttle Programs.</p><p>John Glenn, NASA astronaut and U.S. Senator, was once asked what it was like to be sitting in the rocket waiting to launch. His answer:</p><p>“I felt exactly how you would feel if you were getting ready to launch and knew you were sitting on top of 2 million parts, all built by the lowest bidder on a government contract.”</p><p>Think about it… a rocket is basically a really big, well-controlled bomb. The original rockets were that, plus they were relatively untested. Then you put a tiny little capsule, smaller than the average bathroom in the US, on top of the rocket, pack some equipment and a few people in it, and then light it up. Given the complexity of the machines involved, the inherent danger of playing with fuel of this nature and what they were trying to do (flying to space!), it’s actually an impressive achievement that there haven’t been more deaths and accidents since the beginning of space exploration. But let’s not minimize the danger.</p><p>Let’s start with the obvious and look at deaths that took place in space. As of September 2018, 18 people have died in space, in four different accidents.</p><p>Vladimir Komarov was an experienced Russian cosmonaut, pilot and engineer. He died in April of 1967 when the parachute on his Soyuz module failed to deploy.</p><p>On June 30th of 1971, the crew of Soyuz 11, all were killed when their spacecraft decompressed in space when separating from the Salyut 1 space station.</p><p>On January 28th, 1986 the entire crew of the Challenger, Michael J. Smith, Dick Scobee, Ronald McNair, Ellison Onizuka, Christa McAuliffe, Gregory Jarvis, and Judith Resnik were killed when a gasket in the solid rocket booster failed. The gasket failure allowed a plume or jet of burning rocket fuel to damage the structure of the booster, and twist it so the Space Shuttle was sent into a spin.</p><p>In 2003, the crew of the Space Shuttle Columbia: David Brown, Laurel Clark, Michael Anderson, Ilan Ramon, Rick Husband, KalpanaChawla, and William McCool were killed when damage to the heat shields on the Space Shuttle lead to it overheating and disintegrating as it reentered the Earth’s atmosphere.</p><p>There were also a number of near misses and accidents that could have turned into disasters, including fires on the Mir space station, holes in the bottom of the Mir and ISS stations, ammonia leaks, as well as many incidents involving damaged thermal protection.</p><p>The reality is that just getting rockets off the ground, and even training to do so, is also a dangerous business. Eleven astronauts or cosmonauts have died during training or testing sessions, some of them on the launch pad. Five NASA astronauts have died while engaging in training or transport flights, and several were killed in accidents involving fires in their space capsules.</p><p>The most notable of these accidents was the Apollo 1 training fire in 1967 which killed Virgil &quot;Gus&quot; Grissom, Ed White, and Roger B. Chaffee.</p><p>When you think of the deaths in space travel, you automatically think of space suit failures and explosions in space. Certainly, that’s what the media, and the first part of this section, has focused on. But approximately 11 times more non-astronauts have died due to accidents than have astronauts. Depending on how you count the deaths, somewhere around 325 people have been killed in a variety of accidents, failures, crashes and explosions related to space exploration. Some of the notable deaths include Max Valier, the noted rocket scientist, who was killed when one of his own rockets failed.</p><p>But two disasters in Russia have claimed almost 150 people. The October 24th, 1960 “Nedelin Catastrophe” was a launch pad explosion which killed 100 military and technical personnel. It is considered the largest rocket explosion of all time. Another launch pad explosion in 1980 in Plesetsk killed 48 people. The Soviet Union tried to cover up these failures and only really admitted they had happened in the late 1990s.</p><p>The same sort of cover-up may have happened in China in 1996 when a “Long March” rocket veered off course 22 seconds after launch and slammed into a nearby village. Depending on who you believe, there were as few as six and as many as several hundred deaths.</p><p>All in all, getting people and satellites into space is a dangerous and tricky business. While there have been many deaths, the mortality rate is still relatively low at between 1 and 4% depending on the source. Clearly, any loss of human life is tragic. But in the context of a risky venture like space exploration, those that have died, or put their lives of the line, in the pursuit of furthering knowledge and discovery, deserve our admiration and respect.</p></section><section><h3>Failed Space Travel Missions</h3><p>Failed Space Travel Missions</p><p>(opens in a new tab)</p><p>Space Shuttle Discovery on its way to Launch Pad&#160;by NASA/Frank Michaux</p><p>License:&#160;Public Domain</p><p>When movies meet reality</p><p>So much of our understanding of space disasters is shaped by Hollywood.&#160;Let’s have a look at some of the space movies of the last 25 years and how realistic they are.</p><p>In the 2013 film Gravity, Sandra Bullock and George Clooney are two astronauts separated from their Space Shuttle after it’s struck by debris.&#160;The reality is that, given how much space junk is now floating in orbit around Earth, this sort of scenario is actually possible.</p><p>Apollo 13, which came out in 1995 and stars Tom Hanks, looks at the near-fatal accident on the Apollo 13 mission.&#160;You can read more about the official NASA account.&#160;Obviously, in this case, the scenario of the movie is believable since it’s based on reality.</p><p>Deep Impact&#160;which came out in 1998 and stars Morgan Freeman and Tea Leoni, looks at the impact of a comet hitting Earth with catastrophic consequences.&#160;A plan is formulated that&#39;s actually close to the best theory at the times; to fly alongside the comet until it latches on to the space craft&#39;s gravity.&#160;It can then be maneuvered off course slowly by the spacecraft.</p><p>In the movie The Martian, released in 2015, Matt Damon is left behind on Mars by himself after a storm forces his crew to take off without him.&#160;He’s forced to survive in a damaged station buil<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('da36ef86c36c9da05c5067d810d338cc','space-travel-and-solar-system-m2-l6-lesson-5','7302789819b068cbc13e2f545a65e7b7','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Space Rovers, Satellite and Discoveries</h3><p>Space Rovers and Discoveries</p><p>While watching this video, think about the following questions:</p><p>When you think of successful space exploration missions, which ones come to mind?&#160;Humans going somewhere in a spaceship or probes analyzing a distant planet?</p><p>Welcome back, this is Video 5 of this module on The Apollo and Shuttle Programs.</p><p>When thinking about space travel, the first thing that might pop into your mind are the trips to the Moon, the construction of the ISS and perhaps the shuttle science missions. But the reality is that most of the big scientific discoveries in space travel have been done by spaceships or observatories with no human crew onboard. In fact, when Space.com came up with a list of the 10 Greatest NASA Science missions only one, the Apollo missions, involved human crews. So, in the rest of this module, let’s have a look at some of the science that has been produced, and ignore the commercial products or returns on investment that these exploration missions have created.</p><p>The Pioneer 10 and Pioneer 11 probes were used to study Jupiter. Pioneer 10 went on to do flybys of Saturn and Neptune and, even though it was launched in 1972, sent its final signal on January 23, 2003. Pioneer 11, launched in 1973, focused its attention on Jupiter and Saturn.</p><p>Both these probes gave humans their first close-up looks at these planets and went on to leave the orbit of our solar system. NASA received a final useful signal from Pioneer 11 on November 1995 and a final, faint signal in 2002.</p><p>Probably the most successful, and longest traveling, probes are the Voyagers. In fact, the two Voyagers keep trading the title of farthest human-made object from Earth on a regular basis. As of September 30th, 2018, Voyager 1 is 13 million miles from the Sun, while Voyager 2 is a bit closer at 11 million miles from the Sun. Together the probes completed their primary mission in 1989 after visiting Jupiter, Saturn, Uranus and Neptune, 12 years after their launch. The two probes are now on a mission extension phase called the Voyager Interstellar Mission (VIM) which has seen them go beyond the planets to the boundaries of our solar system.</p><p>With the two probes having enough battery power to last until the mid-2020s, the mission has at least another 5-7 years to go. Currently, they’re trying to map the heliopause boundary, which is the outer edge of our Sun’s magnetic field.</p><p>Probably the most famous of all the probes that are still out there are the Mars rovers: Spirit and Opportunity and the more recent Curiosity. Of the three, only Curiosity is still operational, but, given that Spirit and Opportunity functioned for years beyond their original mission length of 90-days, it would seem NASA got a lot of bang for their buck from these rovers.</p><p>Among the discoveries made by the trio of rovers is that there was once liquid water on Mars. They discovered ancient Mars could have been hospitable to microbial life and they’ve returned important data about radiation levels, which will allow NASA to design suits and ships to protect any future astronauts who might make it to the Red planet. Curiosity completed its initial tasks in December of 2012 and at that point, NASA extended its mission indefinitely. Basically, Curiosity will continue to be operated and send back scientific data as long as it’s functional.</p><p>The spaceships that go places, roam around or land humans get all the glory, but a lot of the science that has been done by NASA has been done by their fleet of space telescopes.</p><p>The Wilkinson Microwave Anisotropy Probe (WAMP) was operational from between 2001 and 2010. Its mission was to measure differences in Cosmic Microwave Background (or CMB) radiation which allows scientists to study the universe&#39;s geometry, content, and evolution; and to test the Big Bang model. By every measure, the WAMP was a success, providing scientists with the clearest picture yet of the universe’s age and shape.</p><p>Even more successful, and famous, is the Hubble Space Telescope. Since its launch over 28 years ago, Hubble has peered into the furthest reaches of the galaxy. Some of the discoveries it’s made include working out the age of the universe (13.7 billion years young, thank you very much). It’s also been able to look at galaxies in the deep universe, basically looking back in time.</p><p>When it wasn’t busy figuring out how old the universe is, it discovered four of the five moons that orbit Pluto as well as helped scientists understand the seasons of the other planets. The Hubble has been serviced a number of times by Space Shuttles, but, given the program no longer exists, there is no way to repair or replace any of its parts. Currently, estimates suggest it will fail completely and return into Earth’s atmosphere sometime between 2028 and 2040.</p><p>This module has continued to lay the groundwork of space travel and explore the history of space travel over the last 70 plus years. There have been advancements and setbacks, heroes and heroines, probes and spaceships, all in the name of pursuing scientific knowledge, and exploring the edges of the unknown.</p></section><section><h3>Space Technologies Advancement</h3><p>Space Technologies Advancement</p><p>Revolutionary Impact</p><p>The Voyager probes, Voyager 1 and Voyager 2, have been historically significant in various ways.&#160;Expand the items in the list below to learn more.</p><p>(opens in a new tab)</p><p>Voyager spacecraft&#160;by NASA/JPL</p><p>License:&#160;Public Domain</p><p>Grand Tour of the Outer Solar System</p><p>The Voyager probes were the first spacecraft to conduct a grand tour of the outer solar system. They visited and captured detailed images and data from Jupiter, Saturn, Uranus, and Neptune, providing humanity with unprecedented knowledge about these distant gas giants and their moons.</p><p>Pioneering Planetary Flybys</p><p>Voyager 1 conducted close flybys of Jupiter and Saturn, while Voyager 2 extended the exploration to Uranus and Neptune. These planetary encounters allowed scientists to study the planets&#39; atmospheres, magnetic fields, rings, and moons in great detail, revolutionizing our understanding of these celestial bodies.</p><p>Iconic Pale Blue Dot Image</p><p>Voyager 1 captured the iconic &quot;Pale Blue Dot&quot; image in 1990. From the outer reaches of the solar system, it turned it<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('eaeecfc65f92ef9f377c0c9623f2d8b2','space-travel-and-solar-system-m2-l7-module-2-summary','7302789819b068cbc13e2f545a65e7b7','Module 2 Summary','text',12,'<h2>Module 2 Summary</h2><section><h3>Module 2 Summary</h3><p>Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Apollo and Shuttles!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this session, you:</p><p>Compared and contrasted the space programs in China, the U.S, and Soviet Union/Russia identifying time periods of competition between these entities</p><p>Discussed the Apollo Missions and their benefit to space travel today</p><p>Evaluated the construction of Space Shuttles over time and the innovations which have led to today’s Space Shuttle</p><p>Analyzed a sample of failed space missions and the mechanical or human error associated with the failure.</p><p>Discussed successful space missions and their significant impact on history</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('62447939efc18ec1a8bd4befc51ed404','space-travel-and-solar-system-m2-l8-module-2-assignment','7302789819b068cbc13e2f545a65e7b7','Module 2 Assignment','text',12,'<h2>Module 2 Assignment</h2><section><h3>Module 2 Assignment</h3><p>3300</p><p>Space Travel</p><p>Apollo and Shuttles - Short Answer Assignment</p><p>Short answer assignment</p><p>For this writing assignment, choose&#160;one&#160;of the&#160;two short answer prompts below and write a two-page, double spaced paper addressing the questions/topics listed.</p><p>1. Which mission or missions we’ve discussed in this module has done the most to prepare us for visiting another planet, like Mars? Explain your answers with references to the module’s videos and readings.</p><p>2. Do you think we should abandon spaceships that have human crews completely? Explain your reasoning and refer to the videos and readings in the module.</p><p>3.&#160; Should we be visiting other planets or should we launch spaceships that help us understand our own planet first?</p><p>Review the rubric below to see how you will be graded.</p><p>Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5e94da749f847cf76b87dc831f8d0e23','space-travel-and-solar-system-m2-l9-module-2-project','7302789819b068cbc13e2f545a65e7b7','Module 2 Project','text',12,'<h2>Module 2 Project</h2><section><h3>Module 2 Project</h3><p>3300</p><p>Space Travel</p><p>Apollo and Shuttles - Project</p><p>Project</p><p>For this assignment, you will interview an adult about their experiences and perspectives regarding Space Travel (with a focus on the Apollo and Space Shuttle programs).</p><p>Find an interviewee, preferably someone who was alive during the moon landing (and remembers it), but it could be anyone who is passionate about Space Travel.</p><p>The interview can be conducted in person, on the phone, virtually, or via email.</p><p>Prepare at least eight questions that cover topics from this module. For example, you could ask about where they were and how they felt about the moon landing, how they felt about other achievements and tragedies in space travel, and their perspective on the future of space travel.</p><p>Be ready to ask follow-up questions, as needed, to prompt more in-depth discussion by the interviewee.</p><p>Your paper should be double-spaced and include:</p><p>Name of the person interviewed, and date and style of the interview (virtual, face to face, etc.)</p><p>Each question asked, followed by the interviewee’s answers.</p><p>A conclusion section (2 – 3 paragraphs in length) comparing what you learned from the interview and the concepts explored in this module.</p><p>Review the rubric below to see how you will be graded.</p><p>Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Interview Questions</p><p>8 points Interview questions are well designed to gain insight and perspective from the interviewee. Follow-up questions are used to effectively explore a topic further.</p><p>7-6 points Interview questions are adequately designed to gain some insight and perspective from the interviewee. Follow-up questions are used somewhat effectively to explore a topic further.</p><p>5-0 points Interview questions are poorly designed and unable to gain much insight and perspective from the interviewee. Follow-up questions are not used where needed.</p><p>8</p><p>Conclusion Paragraphs</p><p>8 points Includes in depth comparisons between the interview and course content, references specific details as evidence to support the comparisons made, and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete comparisons between the interview and course content, references some details as evidence to support the comparisons made, and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no relevant comparisons between the interview and course content, references no details as evidence to support the comparisons made, or does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Includes the required content and is formatted neatly.</p><p>1 point Does not include all required content or is not formatted neatly.</p><p>0 points Does not include all required content and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0ab72c4d04adf8276ea0d6e352444728','space-travel-and-solar-system-m2-l10-module-2-quiz','7302789819b068cbc13e2f545a65e7b7','Module 2 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Apollo and Shuttles. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('bb0ce3c8cd47f378c2c047b84f1e25a5','space-travel-and-solar-system-module-3','2a892040eda1f32ee69b17d25aad96dd','Module 3: Satellites & Space Station',3) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6a32356423293c33dff0809cc0b35006','space-travel-and-solar-system-m3-l1-introduction-purpose-and-objectives','bb0ce3c8cd47f378c2c047b84f1e25a5','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Intro Description Objectives</h3><p>Introduction</p><p>Hi and welcome back. This is the intro video on the International Space Station and Satellites.</p><p>Rockets get all the glory; they’re flashy, there’s lots fire and noise and they have astronauts or cosmonauts on board and all that good stuff. But we never think about what they deliver into space, the satellites, the space stations, the science experiments and telescopes. We focus on the flashy member of the team and forget about the parts that are doing all the science, a bit like focusing on the star forward and not the goal keeper.</p><p>In this module, we’ll be looking at the history of the International Space Station, the cooperation it has fueled, as well as the other space craft orbiting the earth. You’ll learn more about the Hubble space telescope, the oldest human made object still orbiting the earth, and the satellites that make it so men don’t have to stop and ask for directions. Finally, we’ll explore the ways that the two superpowers use space and satellites.</p><p>So, buckle-up, it’s going to be a wild ride!</p><p>Module Description</p><p>ISS-49 crew members in the Kibo lab&#160;by NASA</p><p>License:&#160;Public Domain</p><p>Objectives</p><p>In this module, students will</p><p>Discuss the history of space stations before the International Space Station.</p><p>Analyze the role of international politics in the creation of the International Space Station.</p><p>Describe a typical day in the life of an astronaut aboard the International Space Station.</p><p>Construct a timeline of the introduction of satellites into space.</p><p>Discuss the technological advancements made possible by satellites.</p><p>Evaluate how satellites have impacted the military in superpower countries.</p><p>Polling Question</p><p>When was the first time someone thought of a place to live in space?</p><p>1900s&#160;1920s&#160;1950s&#160;1970s</p><p>Results:</p><p>1900s&#160;100%</p><p>Do most satellites look into space, or are they mostly focused on the Earth?</p><p>They look into space&#160;They are focused on Earth</p><p>Results:</p><p>They are focused on Earth&#160;100%</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Tab through this activity to read the feedback for your answers</p><p>Feedback</p><p>An artificial object which has intentionally be put in orbit.</p><p>Satellite</p><p>Correct!</p><p>A satellite that humans can live on.</p><p>Space Station</p><p>Correct!</p><p>A robotic spacecraft that does not orbit the earth.</p><p>Probe</p><p>Correct!</p><p>Satellites that are less than 10 kilograms (about 22 pounds) and are quite small, usually less than the size of a loaf of bread.</p><p>Femtosatellite</p><p>Incorrect</p><p>A satellite with a mass of less than 3.5 oz (about 100 grams).&#160;These tiny satellites, about the size of a postage stamp, are deployed in a swarm or cloud.</p><p>Nanosatellites</p><p>Incorrect</p><p>A weapon, be it nuclear, chemical, or biological that can cause mass casualties, massive damage to a structure or to the biosphere of the planet</p><p>Weapons of mass destruction</p><p>Correct!</p><p>Very weak gravity, as found on the space station.</p><p>Micro-gravity</p><p>Correct!</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>An artificial object which has intentionally be put in orbit.</p><p>Micro-gravity</p><p>Space Station</p><p>Nanosatellites</p><p>Femtosatellite</p><p>Satellite</p><p>Weapons of mass destruction</p><p>Probe</p><p>Correct!</p><p>2.</p><p>A satellite that humans can live on.</p><p>Nanosatellites</p><p>Probe</p><p>Space Station</p><p>Satellite</p><p>Femtosatellite</p><p>Weapons of mass destruction</p><p>Micro-gravity</p><p>Correct!</p><p>3.</p><p>A robotic spacecraft that does not orbit the earth.</p><p>Probe</p><p>Femtosatellite</p><p>Nanosatellites</p><p>Weapons of mass destruction</p><p>Satellite</p><p>Space Station</p><p>Micro-gravity</p><p>Correct!</p><p>4.</p><p>Satellites that are less than 10 kilograms (about 22 pounds) and are quite small, usually less than the size of a loaf of bread.</p><p>Femtosatellite</p><p>Satellite</p><p>Space Station</p><p>Nanosatellites</p><p>Probe</p><p>Micro-gravity</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e204af29df4a49bc8bee2bea69d25ea6','space-travel-and-solar-system-m3-l2-lesson-1','bb0ce3c8cd47f378c2c047b84f1e25a5','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Space Station Initial Idea</h3><p>Space Station Initial Idea</p><p>While watching this video, consider the following:&#160;For most students taking this course, the International Space Station has always been there, a bit like the internet, but did you know that there were space stations before it?</p><p>Hi and welcome to Video 1 for this module on the International Space Station and Satellites.</p><p>Given that the first space station actually orbited the earth in 1971, you might be surprised to discover that the idea has existed in science fiction since 1869, when the Atlantic monthly published a story by Edward Everett Hale called “The Brick Moon”. In it, Hale describes life on a space station which also works as a communications satellite.</p><p>It took another 50 years before someone came up with the term “space station.” By this point it was moving out of the realm of science fiction and into the hands of scientists. The person who proposed the term was Hermann Oberth, a pioneer in rocketry from Romania. A few years later the Austrian scientist and space travel theorist, Herman Noordung published blueprints to an orbital space station.</p><p>Fast forward a few decades and Wernher von Braun is on the Disney TV show Tomorrowland, showing off his plans for a space station. His idea was that this station could do triple duty as an observatory, research facility and staging point for missions to the Moon and Mars.</p><p>Remember, this plan was floated in the late 60s when NASA was busy with getting to the moon. But after they had managed that small feat, they started looking at the possibility of launching a real space station. The issue was that getting the pieces into space with the Apollo rockets would cost more than building the space station itself. So, until the space shuttle program was a reality, they were limited to smaller attempts. One was Skylab, launched in 1973. It was a temporary space station for three crewmembers. It was also the single US-only space station to ever be launched.</p><p>On the Russian side, their first space station, the Salyut 1, was launched in 1971. It was a three-person station that was only in orbit for 175 days. Between 1971 and 1986 the Russians put up five more space stations, some which stayed in orbit for up to 5 years. Their final solo station, the MIR, was in space for 15 years and was the first modular space station, the building style used for the ISS.</p><p>So, it’s 1991, MIR is up there, the US hasn’t had a space station since Skylab and, suddenly the USSR ceases to be a country. The Cold War is over, and the new Russia is nowhere near as big, or rich as the old USSR. While Russia and the USA aren’t exactly best friends, they are no longer active adversaries. Think of them as space frenemies.</p><p>So the first era of cooperation begins with American (and European) astronauts visiting MIR. In total, various space shuttles visited MIR nine times. NINE TIMES! They delivered cosmonauts, supplies and science experiments, as well as staying on board. An interesting fact was that there was only a limited number of designated sleeping quarters, so when onboard MIR, visiting space shuttle crew had to sleep wherever there was wall space to clip their sleeping bags to.</p><p>Beginning in 1998, the Russians built and launched the Zarya module, which was actually owned by the USA. It was designed to initially function as a power source, propulsion and guidance system for the ISS during construction. But these days, it is mostly used for storage. Next up the US built and delivered Unity. This connected to Zarya at one end, and provided an airlock for visiting space shuttles at the other. In the following years the ISS grew, as parts of its super structure, new solar arrays and the Pir docking compartment, the Destiny lab, Quest airlock and CanadaArm2.</p><p>Then came a pause while the space shuttles were grounded. But when they resumed operations, a new piece of the ISS was added at the rate of roughly two a year through 2011. The ISS is now made up of 15 pressurized modules with a final five to be added by 2020.</p></section><section><h3>Space Station and Visits</h3><p>Space Station and Visits</p><p>Think about the relationship between Russia and the USA, or Russia and most of Europe, during your lifetime.&#160;Best friends?&#160;Always looking out for each other?&#160;Or more rivals who are close to being enemies?&#160;Realistically the Russian/US relationship is incredibly complex, they are both huge countries with large militaries who have interests across the globe; interests which overlap and conflict on a regular basis.&#160;After all, the whole race to the Moon and space was fueled, at least in part, by the Cold War and the urge to be the first up there.&#160;So, how do they get along?</p><p>STS-131 ISS Expedition 23 in-flight crew portrait&#160;by NASA</p><p>License:&#160;Public Domain</p><p>Politics Aside</p><p>One of the best things about the space station isn’t the science, or the structure itself, but the way that everyone involved gets along, in spite of the fact that some of the countries aren’t always the best of friends.&#160;In many ways, the current cooperation can be traced back to the early 1970s and an agreement between the Russians and the USA to cooperate in space called the Apollo and Soyuz program.&#160;This agreement leads to the Soyuz and Apollo dockings (and the handshake in space that you learned about earlier).</p><p>But how did the space station come to be?&#160;Well, the Apollo and Soyuz program was extended to the Space Shuttle and Mir program, which ran from 1994 till 1998 when the ISS was started.&#160;The program saw US space shuttles visit the Mir space station and NASA astronauts stay onboard for extended periods as crew.&#160;Not without its controversies – the Russians saw the US astronauts as guests, not partners, and the US often felt like they had no idea what was going on Mir, especially during accidents (there were two, a fire and a collision with a resupply spaceship).</p><p>In turn, the US started to limit its resources as the ISS project started to ramp up, and they often didn’t have money to funnel into Mir.&#160;Some astronauts also felt that the space station project drained off some of the more experienced crew, which should have been sent to Russian station.</p><p>The ISS itself is a managed jointly by the countries that signed to the Space Station Intergovernmental Agreement&<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('abbead63d297ef8ade6c2b10808076f1','space-travel-and-solar-system-m3-l3-lesson-2','bb0ce3c8cd47f378c2c047b84f1e25a5','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Living in Capsule and Space</h3><p>Living in Space Capsule and Station</p><p>While watching this video, consider the following questions:</p><p>What do you think it’s like up there in the space station?&#160;Do you think you could sleep in a sleeping bag attached to a wall?&#160;Would living in micro-gravity be awesome or just bizarre?</p><p>Welcome back, this is Video 2 of this module on the International Space Station and Satellites.</p><p>So you wake up in your little room, in your sleeping bag and it’s time to get washed up for a new day in space! So you want to wash your hair? No problem, you’re covered. It’s just that you’re going to use a tiny bit of water and then a rinseless shampoo to do it.</p><p>Time to brush your teeth? Think about how you do that at home on Earth, a simple task right? What about in space where everything wants to float away? Do you think other astronauts would like a blob of used toothpaste and water floating around? Probably not, right? The routine for space teeth brushing is quite tricky when you deal with zero gravity (or more accurately, microgravity). You are also more limited in the facilities, for example, no sink to spit into!</p><p>Once an astronaut is washed up, they ready to face the day. So, what’s next? FOOD! Have you ever gone on a camping trip? All your food in little foil packages and baggies? Space travel is a bit like that, but without the bears. That said, you can’t just stick some tatertots in a foil bag and rush off into space. The food has to fit six main categories to be allowed onto the space station:</p><p>- Compact: There isn’t a lot of space on the ISS</p><p>- Lightweight: In an earlier module we talked about how much it cost to put things in space. So, clearly weight matters.</p><p>- Nutritious: The crew needs to eat well, so no junk food.</p><p>- Tasty: Because there is no gravity on the ISS, the crew’s sinuses don’t drain the same. So, it’s like they have a cold a lot of the time, meaning their sense of taste isn’t as good. Foods must be really tasty.</p><p>- Sticky or wet: No gravity means crumbs and little bits of food float away, so all food needs to be a bit wet or sticky. Even salt and pepper.</p><p>- Processed or pasteurized: This one is pretty simple. When you buy food for at home, you want it to stay as fresh as possible for as long as possible and that’s when you have access to a grocery store. In space it’s not like you can pop out to the corner shop to get some more milk, so everything has to last the length of the mission.</p><p>Don’t worry, when a resupply mission arrives, the crew has a chance to have some fresh food, and they even get to pack some special snacks. Some of the snacks are foods from their home country or home culture. Canadian astronaut Chris Hadfield’s crew got to try maple syrup cookies and smoked, candied wild salmon. ISS crew can also pack on some snacks from their families for their own consumption. This is just for their own enjoyment, not because they help with nutrition.</p><p>So, you’ve done your science, checked in with mission control, had some food, what else? Oh right, you have to exercise so you don’t lose too much muscle density while in space. This sounds a bit trivial, but being in space makes you lose about 1% of your bone density per month. For comparison, an older person on Earth might lose around 1% of their bone density per year. Exercising counteracts this problem.</p><p>For workout gear the ISS crew has three choices:</p><p>One: Exercise bike. Works like a bike back on earth, but they have to be strapped on so they don’t float away. This is used to get cardio exercise.</p><p>Two: Treadmill. Like a treadmill back on earth this works muscles, cardio and bone density through the impacts with each stride. Unlike a treadmill back home the runner wears a harness which creates downforce to simulate running on Earth.</p><p>This is what’s called an Advanced Resistive Exercise Device. Basically this is an all-in-one strength training system for space. They can perform squats, deadlifts, bench presses, arm curls and a variety of other strength exercises. This way, astronauts can float by and ask questions like: “hey do you know where the weight room is?”</p><p>There’s one other thing they need think about. You know how when it’s a hot day or you have a really hard work out and the sweat’s dripping off you? That’s not the sweat magically going downwards, that’s gravity pulling it that way. No gravity, no dripping sweat. In fact, it pools on the ISS crew member’s bodies when they are working out. What hi-tech piece of equipment do they use to solve this problem? A towel.</p><p>Right, food, drink, exercise, tooth brushing, sleep (in a funny sleeping bag with arm holes), we’ve covered everything, right? Not so fast. What about, you know, going to the bathroom?</p><p>This is where things get a little tricky, and possibly messy. For, ummm, number two there is a tiny space toilet to sit on. It uses a slight suction to make sure everything goes where it belongs. For number one the toilet comes with a hose and, thankfully, color coded nozzles that does much the same thing: suction guides the urine where it needs to go. The rules are that if you make a mess, you’re in charge of cleaning it up.</p></section><section><h3>Space Station Tour</h3><p>Space Station Tour</p><p>License:&#160;No known copyright restrictions</p><p>So, you’ve heard how they eat and sleep, and go to the bathroom, but what does this place look like?&#160;Let’s take a little tour around the space station.</p><p>Google Reaches for the Stars</p><p>You know how when you want to look at a restaurant or make sure the address is right for your friend’s house and you go on Google Street View?&#160;Those images are taken by Google Cars, basically regular cars with cameras on a mast.&#160;You may have even seen one in your neighborhood.&#160;Obviously, you can’t drive a car into space and then inside the ISS, but Google did the next best thing, they worked out a camera system that gives you a Google Street View tour of the ISS.</p><p>More on food</p><p>Still thinking about food on the ISS?&#160;Maybe you’re even wondering how the US crew members get to celebrate holidays like Thanksgiving.&#160;They do!</p><p>Watch this video which shows what it&#39;s like to eat in space.</p><p>[Music]Now our coffee packet is filled with nice hot water. We just need a little plastic straw, insert the straw, take the cap off, and <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e4e178e3c298b108de4010298320ef49','space-travel-and-solar-system-m3-l4-lesson-3','bb0ce3c8cd47f378c2c047b84f1e25a5','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Space Satellites</h3><p>Space Satellites</p><p>So the space station is cool, and has accomplished a lot and space toilets are interesting, but what else is up there?&#160;Can you name a few of the things that we can do or know about our planet which are because of satellites?</p><p>Welcome back, this is Video 3 of this module on The International Space Station and Satellites.</p><p>Even though it stopped sending signals in 1965, seven years after its launch in 1958, Vanguard 1, a US Navy-launched-satellite is still up there, orbiting Earth. In fact, Tim Floher, who is works for the European Space Agency as a space debris expert, has calculated that Vanguard will be up there for hundreds if not thousands more years.</p><p>Launched quickly, partially in response to Sputnik, Vanguard 1 was the first to use solar power, was able to show that Earth bulged at the equator as well as measuring our atmospheric density. It also mapped meteorites which surround the Earth, important information for future space craft. Finally, as a military satellite it also worked on calculations that would lead to more accurate intercontinental ballistic missle launches, if that was ever needed. It is, in many ways, the grand parent of just about every modern satellite which has been launched since.</p><p>Before humans could really launch anything into space, we had to do a LOT of math. Let’s review some history. First we came up with the model that said that Earth was the center of the galaxy. Then, in the 14th century, Ibn al-Shatir produces calculations that suggest that it is in fact the Sun that is stationary. This theory is finally fully fleshed out by Copernicus in the 16th century, followed by further observations by Tycho Brahe proving the same theory.</p><p>At this point, in the 17th Century, the Italian astronomer Galileo Galilei improves upon the telescope well enough to prove Copernicus’ theory that the Sun is the center of the universe. For his trouble the Roman Inquisition finds him guilty of heresy. Fast forward another century and the German mathematician and astronomer Keppler is the first to use the word “satellite” and to calculate orbits by moons. Newton comes along later in the 17th Century with his calculations of gravity and laws of motion. Suddenly we have the basics of the math used to work out orbits and a lot of space travel.</p><p>This ushered in a period of Science Fiction writing about space stations, satellites and the like. This culminated in 1957, when the Russians launched Sputnik. Suddenly the fictional was reality. From there, the satellite business really picked up. In 1960 the first weather satellite was launched, Tiros-1 was able to detect and chart hurricanes and send images of cloud cover. The first communications satellite went up in 1962, Telstar-1, which was in low-orbit and allowed for trans-Atlantic television broadcasts. Today there are thousands of these satellites in orbit, providing all manner of international broadcast capabilities. In 1970, the Chinese join the club with the launch of their Dongfanghong 1 satellite. They were followed by European Space Agency in 1979. Fast forward to 1994 and the first parts of the GPS or Global Positioning System are in place, allowing satellite navigation here on earth.</p><p>Most of the probes we’ve sent out into space are sort of like satellites that are designed to travel instead of going into orbit around earth. In fact the definition of a probe is a robotic spacecraft that does nor orbit the Earth. In many ways, these probes have been our most successful spacecraft, even though they carried no people into space.</p><p>One of the first probes launched, in 1959, was Luna 3. This Russian probe took pictures of the far side of the Moon, which were automatically developed and then sent back to Earth by taking videos of them from an onboard video camera. In 1972 Pioneer 10 is launched, it passes Jupiter in 1973 and then begins its trip out of our Solar System. Its twin follows it into space the following year. Its last successful data transfer occur on the 30th anniversary of its launch, on March 3, 2002 and then again in April of the same year. Its last signal is received in 2003 when NASA sends a message to it to turn off its last operational experiment.</p><p>Viking 1 and 2 are the next pair of probes to be sent off into space by NASA. Launched in 1975, they both include a lander and successfully arrive in 1976 and send back signals for the next seven years.</p><p>In 1977 the rock stars of the probes are launched, Voyager 1 and Voyager 2, which are both still going and sending back data, are able to prove that Jupiter moon Io has volcanic activity, that Jupiter has rings like Saturn and that the rings around Saturn are made up of braided structures. The two Voyagers are now about 13 million miles from Earth and continue to send back data, 41 years after they were launched.</p><p>Closer to home satellites were really coming into their own, once we worked out how to use them for communications and how to launch them into geostationary orbits.</p><p>The international communications scene was forever changed with the launching of Early Bird, a satellite owned by Comsat, which was quickly followed by Intelsat II and III. This was the birth of a permanent communications network, which allowed a half billion people to watch Apollo 11 land on the Moon.</p><p>With international systems under control, countries started to look closer to home. The Soviets launched a domestic service satellite called Molniya in 1965. The Canadians followed in 1972 with Anik, the first North American domestic service communications satellite. The US joined the party in ’74, with Westar. While early on these satellites were originally used only for telephone and data transfers, it wasn’t long before companies like HBO worked out they could rent time on satellites so they could broadcast sports events.</p><p>From there through the 1990s, with the advent of low earth orbit satellites handling internet traffic, cellphone calls, and nearly instant news feeds, satellites helped shrink the distance between all of humanity.</p></section><section><h3>Voyager 2 Satellite</h3><p>Voyager 2 Satellite</p><p>Satellites started out as this crazy expensive thing that only countries and huge companies could afford.&#160;Now they are coming down to the point that normal people, or groups of normal people, can almost afford them.</p><p>The Long Travel<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9c9c30a647a88b5101df4cefc46bf051','space-travel-and-solar-system-m3-l5-lesson-4','bb0ce3c8cd47f378c2c047b84f1e25a5','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Satellite Use Cases</h3><p>Satellite Use Cases</p><p>While watching, think about the following question:&#160;Looking out into space, showing the newest TV show or sports event, these are all cool, but what kinds of discoveries do you think satellites have made?</p><p>Welcome back, this is Video 4 of this module on The International Space Station and Satellites.</p><p>While it’s true that a lot of the satellites that are up there are focused out towards the galaxy, many of them are actually engaged in earth sciences and are looking back at us to learn more about our home. Let’s look at what they are doing:</p><p>First, weather. By watching out for extreme weather, like hurricanes, weather satellites have saved lives by giving people earlier warnings so they can evacuate.</p><p>Second, the Ozone. The ozone is a layer in our atmosphere that protects us from solar radiation, satellites were used to monitor how badly we were damaging it with certain chemicals. This monitoring and realization lead us to ban these chemicals, which helped slow global warming. The ozone layer looks like it will return to normal by 2071.</p><p>Next, Climate change. Another huge use of satellites is in monitoring climate change and pollution. From space, these satellites can track temperature changes, changes in the amount of sea ice and monitor things like phytoplankton and their role in locking in carbon. The newest generation of satellites will be able to map droughts before they happen and produce more accurate models about the loss of sea ice. All of this may yet help us to undo the damage caused by climate change.</p><p>At the dawn of the satellite age, they were tiny! Vangard was referred to as the “grapefruit satellite.” But over time they grew, in part because they were being asked to do more complicated things and miniaturization hadn’t caught up. But now satellites are getting small again. In fact, they are getting so small that there are plans to be able to launch them from aircraft, rather than having to use rockets. NASA has come up with a class of satellites called CubeSats. These nanosatellites are based on a measurement system called “U” which is 10 centimeters (or about 4 inches) per side. To qualify as a nanosatellite, it has to be less than 10 kilograms (or about 22 pounds). The NASA CubeSat makes it into this class easily with a weight of less than three pounds. They are meant to be deployed as auxiliary cargo when rockets go up for other tasks. To date, 43 CubeSats have deployed, carrying a variety of systems and experiments onboard.</p><p>With the smaller NASA and commercial satellites available, the possibility of launching satellites for smaller, more specialized tasks for private or smaller government agencies is suddenly a reality. One of the side effects of this rush to get small satellites into space is that there needs to be cost effective launch capabilities. Think about it, there’s not much sense in launching something the size of a loaf of bread into space on a rocket designed to resupply the ISS. Enter the smaller commercial players, like New Zealand’s Rocket Lab. From their launch pad on a sheep and cattle farm near Mahia, on New Zealand’s North Island, they have already put four satellites in space, all with a rocket of their own design using a 3D printed engine from Rutherford.</p><p>These smaller satellites are already up there doing tests on solar sail technology, space and Earth weather patterns, radiation blooms and a number of other scientific tests. The commercial side of the small satellite boom is focused on things like tracking ships in real time as well as tasks like providing pollution and weather tracking in real-time. It’s amazing (and a little scary) to think what is possible with so many tiny satellites up there, looking down on planet earth.</p></section><section><h3>Types of Satellite</h3><p>Types of Satellite</p><p>Tiny satellites.&#160;Huge satellites.&#160;All this talk of satellites makes you wonder what they look like, what they can do and the cost of putting them up in orbit.&#160;Let’s learn a bit more about this.</p><p>Creative Commons&#160;Maya-1 Nanosatellite&#160;by RoyKabanlit&#160;is licensed under&#160;CC BY-SA 4.0(opens in a new tab).</p><p>The Future is Small</p><p>Part of the benefit of smaller satellites is that they are quicker to build.&#160;A larger, more complex satellite can take up to 10 years to build and deploy, while NanoSats are smaller, use off the rack standardized components and can go from start to deployment in under a year.</p><p>While we’re talking about size, think about smartphones.&#160;When the first one came out it was relatively large and underpowered (your uncle&#39;s Blackberry) but now the only reason a smartphone must be big is because people like the larger screens, realistically an Apple Watch probably packs the same processing power as the first smartphones.&#160;The same principle applies to satellites, while we&#39;ve been talking about NanoSatellites that are about the size of a loaf of bread.&#160;There are other, smaller models called femtosatellites, which are as small as a postage stamp or computer chip and are meant to be deployed in groups or swarms.&#160;While, clearly, you’re not going to get data or resolutions like the Hubble from something the size of a postage stamp, the cost of putting something that small and light in space is the fraction of a cost of a huge satellite.</p><p>If you’re wondering what some of these satellites look like, you can go to the NASA gallery on their CubeSatpage.&#160;While you’re there you can also take a look at the video gallery to see some of the satellites in action.&#160;Watch this video below to learn more about the engineering behind the CubeSats:</p><p>Pause</p><p>-04:19</p><p>Mute</p><p>[ MUSIC ]</p><p>Small satellites yield big discoveries - Presented by Science@NASA. Remember the old adage: Big things come in small packages? NASA has updated it - in the form of CubeSats. Imagine a real, working satellite that&#39;s so small you can hold it in your hands. Just 4 inches, or 10 centimeters across, these cubes can be expanded incrementally depending on their specific mission objectives. The technology packed into these tiny denizens of space is impressive. Originally developed in 1999 by Cal Poly San Luis Obispo and Stanford University for educational purposes, NASA has since used them for new science missions and to test new electronics, sen<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2bebafef9e8671325560958078062d7e','space-travel-and-solar-system-m3-l6-lesson-5','bb0ce3c8cd47f378c2c047b84f1e25a5','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Military Satellite</h3><p>Military Satellite</p><p>While watching the video below, think about the following question:</p><p>Until now we’ve been largely focused on how satellites can be used for scientific and exploration purposes, but can you think of ways that orbiting spacecraft can be used for military purposes?</p><p>Welcome back, this is Video 5 of this module on The International Space Station and Satellites.</p><p>When you think of the military in space you probably have some sort of image of Star Wars and space battles with lasers and missiles in mind. The reality is a bit more mundane. Think about all the civilian applications that satellites have: looking at things, listening to things, communications, helping people find their way, and predicting the weather. These are all tasks that military satellites do, but with more secure communications channels, accuracy and advanced capabilities that aren’t available to the civilian market.</p><p>So let’s look at what these military satellites do in a bit more detail:</p><p>One, Reconnaissance and surveillance. A lot of what any military does is keep tabs on what enemies and potential enemies are up to. So, the ability to watch without being detected is a big deal. There are two main kinds of satellites in this category. First there are those that send images in near real time, like the US CRYSTAL and the Russian Terilen. While not able to send video, they can take pictures every couple of seconds.</p><p>The other kind of satellite, which is now less common, is one that uses film cameras and then uses a parachute system to drop the film to Earth for processing. Russia seems to still operate these satellites, but the US stopped when a Russian submarine was seen loitering in the recovery area of a US drop! Reportedly, the best of the US satellites can see a softball-sized object from space. These satellites also intercept all kinds of communications, be they military or civilian cellphone traffic.</p><p>Two, Navigation. If you pop down to your local REI or Cabela&#39;s you can get a GPS and your smartphone uses it too to give you directions, but did you know that the GPS network that you log onto with your device is the property of the US Navy? The system works roughly the same whether you’re in the military or not: the device gets a signal from satellites, which in turn tell you where you are.</p><p>Three, Warning Systems. The biggest military threat to human life remains nuclear weapons. One of the tasks of military satellites it to monitor for missile launches, the repositioning of mobile launchers and to watch for nuclear tests.</p><p>Currently the USA operates a network of satellites, called Space-Based Infrared System, which is charged with tracking both Intercontinental Ballistic Missiles and shorter range “in theater” missiles of the kind used by the Iraqis during the Gulf War.</p><p>Finally, Communications. Given that the enemy, and some of your friends, are trying to always figure out what you’re up to, it only makes sense that the military needs communications satellites. They provide three main kinds of communications and data services: Wide band, for high bandwidth transfers, like video or other large files and narrow band, which is used for basic communications that don’t take much bandwidth, think phone calls and skype. The last kind is Protected, this is for communications that need to be totally secure. Normally satellites that provide this level of communications also have anti-jamming and nuclear survivability features built in.</p><p>Another class of satellite that people wonder about are space born weapons. Currently there is an international treaty that prohibits the use of space for weapons of mass destruction, like nuclear or chemical weapons, but that hasn’t stopped people from looking at using satellites to attack other countries. Recently there have been moves to develop satellites that can service and upgrade other satellites while in space. Clearly a spacecraft with the ability to drill, unscrew and attach itself to a friendly satellite could do the same to a hostile one.</p><p>Even surveilling other satellites is top-secret. The US satellite Prowler was designed to go into orbit and then navigate to within a few yards of Russian satellites, with the intent of investigating them, as well as interrupting and intercepting their communications with their base stations.</p><p>So, right now the military satellite market is crowded with huge satellites that can do amazing things. But, just like on the civilian side, huge means expensive to launch, which means you launch fewer satellites, which, ultimately leads to less coverage. So, like in the civilian market, the belief is that the future of military satellites is in more and smaller spacecraft.</p><p>The US military is even looking at using commercial satellites for some of its needs, but there is a hiccup. Their receiving systems are so out of date that they can receive signals from the newer satellites. Clearly this will need to be changed so they can use newer systems.</p><p>This module has continued a look at the history of space travel and exploration, with a peak at what might be possible in the near future. We have looked at the extremes of international cooperation on projects like the ISS, and on the other hand, the use of satellites for spying and waging war. But for us, in our daily lives, we can definitely be thankful for the scientific knowledge gained from the work done on space stations. And we can enjoy some of the bounties of modern living: GPS location services, satellite radio, and satellite TV.</p></section><section><h3>Military Satellite Use Cases</h3><p>Military Satellite Use Cases</p><p>Space Laser Satellite Defense System Concept&#160;by U.S. Air Force</p><p>License:&#160;Public Domain</p><p>So there are commercial satellites, military satellites, and some satellites that are so secret we don’t even know for sure if they exist.&#160;In this reading, we’ll look a bit at what’s really out there and how some of the civilian and military tech can be used to do really useful things.</p><p>Tracking the Warbirds</p><p>First off, how many active military satellites do we know about?&#160;Currently, there are 950 active military satellites currently in orbit around the Earth.&#160; If you want to learn more the Union of Concerned Scientists, an international watchdog group, has put together a spreadsheet with more details <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('645272e17005904345283b533035b63e','space-travel-and-solar-system-m3-l7-module-3-summary','bb0ce3c8cd47f378c2c047b84f1e25a5','Module 3 Summary','text',12,'<h2>Module 3 Summary</h2><section><h3>Module 3 Summary</h3><p>Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on the International Space Station and Satellites!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Discussed the history of space stations before the International Space Station.</p><p>Analyzed the role of international politics in the creation of the International Space Station.</p><p>Described a typical day in the life of an astronaut aboard the International Space Station.</p><p>Constructed a timeline of the introduction of satellites into space.</p><p>Discussed the technological advancements made possible by satellites.</p><p>Evaluated how satellites have impacted the military in superpower countries.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8f68338d67dd2560221b3bb8d2303ee4','space-travel-and-solar-system-m3-l8-module-3-assignment','bb0ce3c8cd47f378c2c047b84f1e25a5','Module 3 Assignment','text',12,'<h2>Module 3 Assignment</h2><section><h3>Module 3 Assignment</h3><p>3300</p><p>Space Travel</p><p>International Space Station and Satellites - Short Answer Assignment</p><p>Short answer assignment</p><p>For this writing assignment, choose&#160;one&#160;of the three short answer prompts below and write a two-page, double-spaced paper addressing the questions/topics listed.</p><p>1)&#160;What do you think the future holds for the space station? Do you think another one will replace it? Do you think it will be used as a staging area for missions to Mars? Would a series of stations make sense?</p><p>2)&#160;You’ve read a bit about the probes we’ve sent out, do you think that probes make more sense for space exploration than crewed space ships?</p><p>3)&#160;You’ve read about some sof the things that satellites can already do, what other tasks can you come up with? Do a little reading, and then make some suggestions for future satellites. Think about power sources, what size they might be, what they might be able to do in a few years.</p><p>Review the rubric below to see how you will be graded.</p><p>Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('53beb5d7ce434f72b43dee0fe95d9deb','space-travel-and-solar-system-m3-l9-module-3-project','bb0ce3c8cd47f378c2c047b84f1e25a5','Module 3 Project','text',12,'<h2>Module 3 Project</h2><section><h3>Module 3 Project</h3><p>3300</p><p>Space Travel</p><p>International Space Station and Satellites - Project</p><p>Project</p><p>Part 1: For this assignment, imagine you’ve been asked to write a guest post for a local news blog. The topic is the risks and opportunities of the risks and opportunities of small satellites. Research the topic and choose your stance, then try to convince your readers with persuasive arguments and solid support. The blog post should be three to five paragraphs long.</p><p>Part 2: After you’ve written the post, you get the chance to look at the topic from another point of view by writing a reader response that offers different or opposing ideas. The response should be respectful, give some support for the argument, and be two to three paragraphs in length.</p><p>Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Article</p><p>8 points The blog post demonstrates a strong understanding of the pros and cons of small satellite projects. It is persuasive, contains several specific and accurate details and supporting facts and thoroughly expands on the thoughts discussed.</p><p>7-6 points The blog post demonstrates a strong understanding of the pros and cons of small satellite projects. It is persuasive, contains several specific and accurate details and supporting facts and somewhat expands on the thoughts discussed.</p><p>5-0 points The blog post demonstrates little to no understanding of the pros and cons of small satellite projects. It is not persuasive or contains few to no specific and accurate details and supporting facts and does not expand on the thoughts discussed.</p><p>8</p><p>Review Comments</p><p>8 points The review comment offers valid and well developed opposing arguments to the content of the blog. It gives specific details to support the statements made.</p><p>7-6 points The review comment offers valid and somewhat developed opposing arguments to the content of the blog. It gives some details to support the statements made.</p><p>5-0 points The review comment offers invalid or undeveloped opposing arguments to the content of the blog. It gives little to no detail to support the statements made.</p><p>8</p><p>Citations</p><p>2 points Resources are used effectively to support arguments and are cited properly.</p><p>1 point Resources are used somewhat effectively to support arguments and are cited properly.</p><p>0 points Resources are not used effectively to support arguments and are cited improperly.</p><p>2</p><p>Mechanics</p><p>2 points Formatted neatly and contains few, if any, spelling or grammar errors.</p><p>1 point Formatted neatly and contains several spelling or grammar errors.</p><p>0 points Formatting is not neat or contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1a93869c0c1b75070f5d0c17fe9938b2','space-travel-and-solar-system-m3-l10-module-3-quiz','bb0ce3c8cd47f378c2c047b84f1e25a5','Module 3 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Satellites & Space Station. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('85762d16251ed28eefbfcda66b36b66a','space-travel-and-solar-system-module-4','2a892040eda1f32ee69b17d25aad96dd','Module 4: Moon Base',4) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ff7ab3f0f0a042e979ae14ab62f62ff5','space-travel-and-solar-system-m4-l1-introduction-purpose-and-objectives','85762d16251ed28eefbfcda66b36b66a','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Pause</p><p>-00:43</p><p>Hello earthlings, welcome back. This is the intro video for the module on the Moon Base.</p><p>The Moon… we’ve all been introduced to it at a very young age. Whether it’s in children’s books like Goodnight Moon and other stories, or simply when we first noticed its constant presence in the night sky, the Moon is a mystery to be solved. The fact that we can easily see with the naked eye that it has an interesting surface with dark flat patches and jagged peaks, only adds to the mystery. It seems so calm and peaceful especially when compared to planets like Mars, which seems so angry with its bright red color, or Jupiter with its furious storms of the gas giant.</p><p>The Apollo missions gave us enough of a taste of our closest neighbor but it’s been more than 50 years since we paid it a visit. Many people think we need to go back but this time… they think we should stay. If you’re a science-fiction fan, a hundred images must be running through your head of the way Moon bases have been represented.</p><p>In this module, you’ll learn about the history of the Moon and its influence on the Earth. You’ll learn about the challenges of setting up an outpost of the Moon but also about the potential advantages of doing so. Finally, you’ll learn about the dangers of living in space and some potential solutions to make it possible.</p><p>Module Description</p><p>License:&#160;All Rights Reserved</p><p>In this module, we’ll look at the history of the Moon, how it was formed in relation to the Earth and how its gravity influences our planet.&#160;We’ll even imagine a world without the Moon.&#160;Then, we’ll look at the possibility of building a base on the Lunar surface and think about the advantages and the disadvantages of that idea.</p><p>From scientific to commercial benefits, tourism opportunities and a stepping stone to explore the rest of the universe, the Moon is filled with possibilities.&#160;But it’s not that simple.&#160;Is humanity ready to settle on other celestial bodies?&#160;Has it learned from the lessons of life on Earth?&#160;Can countries and commercial organizations get along and cooperate to make space exploration beneficial for everyone?</p><p>Objectives</p><p>In this module, students will</p><p>Discuss the present and historical impact of the Moon on Earth.</p><p>Analyze the geographic features of the Moon and the advantages/disadvantages of building a base on the Moon.</p><p>Evaluate the political and future innovative benefits of placing a base on the Moon.</p><p>Identify the physiological requirements for those residing on a Moon base.</p><p>Analyze the impact of a Moon base to future colonization of Mars and other planets.</p><p>Polling Question</p><p>Which of the following best describes your view of the moon?</p><p>A cold, empty place&#160;A world filled with wonderful possibilities?</p><p>Make a selection to see the results so far.</p><p>If you could go to the moon, would you like to go?</p><p>Yes&#160;No</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match the definitions with the key vocabulary words that will be reviewed in this module.</p><p>Study of how light (visible, ultraviolet, and infrared) behaves.</p><p>Cataracts</p><p>Uses curved mirrors that reflect light to form an image.</p><p>Atomic theory</p><p>Equipment designed to make measurements</p><p>Reflecting telescope</p><p>Latin plural word for seas (singular is mare) used to describe certain regions of the surface of the Moon.</p><p>Optics</p><p>Scientific theory that looks at matter and its composition.</p><p>Maria</p><p>A clouding of the eye that causes vision problems.</p><p>Laser-ranging device</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Study of how light (visible, ultraviolet, and infrared) behaves.</p><p>Atomic theory</p><p>Maria</p><p>Laser-ranging device</p><p>Reflecting telescope</p><p>Optics</p><p>Cataracts</p><p>2.</p><p>Uses curved mirrors that reflect light to form an image.</p><p>Maria</p><p>Optics</p><p>Atomic theory</p><p>Cataracts</p><p>Laser-ranging device</p><p>Reflecting telescope</p><p>3.</p><p>Equipment designed to make measurements</p><p>Maria</p><p>Atomic theory</p><p>Cataracts</p><p>Reflecting telescope</p><p>Optics</p><p>Laser-ranging device</p><p>4.</p><p>Latin plural word for seas (singular is mare) used to describe certain regions of the surface of the Moon.</p><p>Optics</p><p>Reflecting telescope</p><p>Maria</p><p>Atomic theory</p><p>Cataracts</p><p>Laser-ranging device</p><p>5.</p><p>Scientific theory that looks at matter and its composition.</p><p>Maria</p><p>Cataracts</p><p>Optics</p><p>Atomic theory</p><p>Laser-ranging device</p><p>Reflecting telescope</p><p>6.</p><p>A clouding of the eye that causes vision problems.</p><p>Laser-ranging device</p><p>Maria</p><p>Reflecting telescope</p><p>Optics</p><p>Cataracts</p><p>Atomic theory</p><p>Process used by plants, algae and some bacteria to turn sunlight into chemical energy.&#160;This process releases oxygen into the atmosphere.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5cc7c752096c844a16924a9a647d3202','space-travel-and-solar-system-m4-l2-lesson-1','85762d16251ed28eefbfcda66b36b66a','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Moon Influence on Earth</h3><p>Moon Influence on Earth</p><p>While watching this video,&#160;consider the following question:&#160;When you look at the Moon on a clear night, do you just marvel at its beauty or think about the many ways it impacts the Earth?</p><p>Hi and welcome to Video 1 for this module on The Moon Base.</p><p>We’re all used to seeing the Moon and most of us probably don’t think twice about its formation, why it’s orbiting the Earth and what influence it has on our planet. Considering it’s the closest celestial body to Earth and it played such a large role in space exploration to date, let’s find out a bit more about this bright presence in our night sky.</p><p>Did you know that the study of the surface of the Moon is called selenography and that scientists have studied the Moon for a very long time? As early as 450 BC, the Greek philosopher Democritus already noticed that the Moon’s surface was made up of peaks and valleys. Democritus was famous for his atomic theory of the universe (which looks at matter and its composition).</p><p>But it wasn’t until the 17th century when telescopes were invented to help scientists take a closer look at the Earth’s natural satellite. The first type of telescope, the refracting telescope, uses a lens to gather light from the object they’re observing and focus that light to form an image. Then there are reflecting telescopes, which use curved mirrors that reflect light to form an image. These were developed along with advancement in optics, which look at how light behaves.</p><p>This allowed astronomers to start measuring and mapping the surface of the Moon. In 1834, Johann Heinrich von M&#228;dler produced the first large-scale map of the Moon.</p><p>The maps got more and more detailed such as this one from 1881 but it wasn’t until 1959 that a human-made object actually got close enough to the Moon to take photographs. The Soviet Luna 3 was the first spacecraft to take multiple images of the far side of the Moon; the side that’s not visible from Earth. The images weren’t very good by today’s standards, but it was still an important milestone.</p><p>After that, many spacecraft took photographs of the Moon. The US spacecraft included the Rangers (from 1961-1965), the Lunar Orbiters (from 1966-1967) and the Surveyors (1966-1968). The Soviet Union’s spacecraft, the Lunokhods (1970-1973) also contributed. But the most complete set of images was collected by Clementine in 1994.</p><p>The Clementine spacecraft was packed with equipment and managed to capture high-resolution, ultraviolet and infrared images of every side of the Moon as well as its two poles.</p><p>Photographs are great and certainly helped humans get a better sense of the Lunar surface but they don’t tell us much about the composition of this celestial body or how it was formed. The Apollo missions allowed scientists to learn a lot more about the Moon. They collected a treasure trove of information and samples that gave us a much better idea of the composition and history of our closest neighbor.</p><p>Apollo 8 (1968) and Apollo 10 (1969) took many photographs from orbit and came back with their close-up observations. Apollo 11, famous for being the first to land on the Moon, deployed scientific equipment (a laser-ranging device to take measurements and a seismic detector to study the internal structure and detect moonquakes) and collected core samples of the soil in addition to taking many photographs. Apollo 15 (1971), Apollo 17 (1972) and other missions brought back even more observations and a large number of samples that kept scientists on Earth busy for years and allowed us to gain a lot more knowledge about the Moon, its surface, and its history.</p><p>Even with the naked eye, it’s easy to see the craters and what looks like points of impact on the surface of the Moon. It’s one of its main features along with its white color. Scientists have done a lot of research to figure out what could possibly have created these craters. Using the material and information collected by space missions and analyzing digital maps of the surface, a team at the NASA Lunar Science Institute discovered that the marks left on the surface come from debris hitting at high speeds, causing craters to form. The higher the speed, the deeper and bigger the crater.</p><p>It’s a bit like when you throw a rock on the water. If you try to skip the surface, you don’t disturb the water too much but if you throw a rock in the air, it’s going to make a crater where it hits the water because it’s going to gain speed on the way down and hit with more force. Scientists have found two types of craters which seem to correspond to two waves of impact. The older craters are on average 30 to 40% smaller than the “younger” ones. After analyzing rock samples, scientists estimate the more recent craters are roughly four billion years old and were created as a result of what they call a “lunar cataclysm.”</p><p>You might be wondering why this matters here on Earth. Well, it matters because our planet and the Moon have a unique relationship. We can’t see as much of earth’s history anymore due to millions of years of geological and meteorological changes, like erosion. But what we can’t see here may still exist on the Moon, which has no wind, rivers or shift of tectonic plates that might erase its past.</p><p>Scientists believe the Earth was formed 4.54 billion years ago when asteroid debris orbiting the Sun started piling up onto each other, forming our planet. Then a planet the size of Mars collided with Earth creating debris that eventually became the Moon using a similar process. The collisions didn&#39;t stop there as more asteroid debris hit the Moon, Earth, Venus, and Mars after a rearrangement of the bigger planets (Jupiter, Saturn, Uranus, and Neptune). Scientists believe this might have caused some Earth debris to hit the Moon. These pieces of Earth could provide precious clues about our planet’s history.</p><p>Understanding the Moon could help us understand the history of the Earth but it’s also important because the two celestial bodies move in sync with each other. Ever wondered why there’s a hidden or dark side of the Moon? It’s because the time it takes the Moon to spin around its axis is exactly the same as the time it takes to orbit once around the Earth. So, no matter where you are, you always see the same side of the Moon.</p><p>Tides are created by the Moon’s gravitational pu<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8370208400c28a8cd4f536dc7fa2b531','space-travel-and-solar-system-m4-l3-lesson-2','85762d16251ed28eefbfcda66b36b66a','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Moon Land Features</h3><p>Moon Land Features</p><p>If there was a base on the Moon where you could go spend your vacations, would you go?</p><p>Welcome back, this is Video 2 of this module on The Moon Base.</p><p>Before building anything, you have to examine the foundations you’re building on. That’s a fairly simple thing to do on Earth but a little more complicated when you plan to build something that requires a 239,000-mile journey into space. Here’s what we know about the foundations on the Moon.</p><p>The Moon’s surface has been shaped in great part by the bombardment of debris but some of its features also come from lava flows. Overall, the lunar surface is made up of highlands and maria, which in this case doesn’t mean Maria from West Side Story, but instead the Latin word for seas. Both highlands and marias are marked by craters.</p><p>The maria, which look like dark flat patches, only cover 17% of the total surface of the Moon mostly on the side that faces the Earth. At first, scientists thought they were filled with water (which is why they named them maria) but they now know it’s impossible to have liquid water on the surface of the Moon because it’s too dry. They now think they contain lava that got out through cracks or surface material that got liquefied by the heat of the impact from asteroids and spread into existing craters where it eventually cooled down and hardened. The depth of the maria ranges from 0.6 to 2.5 miles. The largest mare (singular for maria) is the Mare Frigoris or Sea of Cold with a diameter of almost 900 miles!</p><p>The highlands, which cover 83% of the surface, are made up of mountains pockmarked by craters. Here again, the scientists used a name (mountain) that made sense to them but it’s important to understand that these mountains weren’t created by shifts in the tectonic plates like on Earth. On the Moon, there are no tectonic plates or volcanic activity. Instead, they were created by the impact of asteroids. The mountains are essentially the rims of craters. The tallest mountains on the Moon are Mons Hadley standing at 15,000 feet and Mons Hadley Delta at 11,484 feet. The pair was made famous during the Apollo 15 mission (in 1971) with many photos being taken in front of them.</p><p>We now have a rough sense of the Lunar surface but that’s just one of the many factors to consider when thinking about building anything on the Moon. What about the environment?</p><p>On a sunny day on the Moon, the temperature can rise up to 260 degrees F but when the Moon turns its back to the Sun, the thermometer can drop to minus 280 degrees F. The temperatures are even more extreme at the poles and in craters that never get sunlight because the Moon only has a very slight axis tilt of 1.54 degrees.</p><p>How did the astronauts survive in these temperatures you might ask? Lots and lots of layers! This graphic shows the 14 layers used to protect astronauts from the cold, the heat, small flying objects, and the loss of air pressure. LCVG means Liquid Cooling and Ventilation Garment.</p><p>This kind of protection would also be needed for any structure built to house humans on the Moon. Regolith, which is pulverized moon rock, could be used to shield any construction from radiation but it’s estimated that a thickness of 2.5 meters (a little over 8 feet) would be required. At least, it would be a local material that wouldn’t need to be transported from Earth.</p><p>As if overcoming temperatures wasn’t enough, people settling on the Moon would also have to live in a low-gravity environment which is 1/6th of that on Earth. What does that mean in practical terms? On top of making it difficult to keep anything down, low gravity would also make construction very difficult. For example, on Earth when you use a drill, the surrounding air keeps the heat caused by the friction down. But on the Moon, the lack of air means that same friction could generate a lot of heat so much so that the drill could fuse with the rock!</p><p>On earth, Construction sites also use explosives when they need to clear a particularly difficult obstacle. Explosions in a vacuum which is when all air and gases have been removed from an environment like on the Moon would cause enormous damage because there is no atmosphere to slow down the debris flying in all different directions at high speeds.&#160; This is a big obstacle because most experts think any structure on the moon would have to be built underground.&#160; To protect humans from the impact of debris hitting the surface in addition to temperatures and radiation.&#160; Between 2009 and 2016, the Lunar Reconnaissance Orbiter Camera recorded 200 new impact craters as wide as 140 feet in diameter, so the danger is constant.&#160; Another important obstacle builders would have to overcome is the lack of suitable supplies on the moon.&#160; Even if materials could be designed on earth to account for all these obstacles, they would still need to be transported to the Moon.&#160; That would involve incredibly complicated logistics considering how small space crafts are and the cost could be enormous.&#160; This means the more materials engineers can find that are already on the moon, the better.&#160; So why bother building anything on the moon if its so complicated.&#160; Well, here are a few reasons.&#160; It could serve as a sanctuary if an asteroid were to threaten to hit the earth.&#160; It could serve as a staging ground for missions to go deeper into space, like Mars, for example.&#160; It would make a great vacation destination for some people.&#160; It could allow us to study the Moon more closely and the earth from outside.&#160; If we’re serious about sending humans to further explore into our solar system such as a trip to mars setting up camp on the moon could provide precious information about daily life on another planet and its effects on the body. A lot of information has already been collected on the International Space Station (ISS), but it closely orbits the earth and is not a planet.&#160; Being on the moon permanently would also allow us to study it more closely.&#160; Several countries are already talking about mining resources there.&#160; While the idea of sending settlers to the moon is very exciting, it does come with many disadvantages.&#160; First of all, it would cost a lot of money and use a lot of resources.&#160; Then, there are no laws on the moon.&#160; Would humans destroy the moon&#39;s envi<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('d05e03eddad57187a57b3c4bc5f11179','space-travel-and-solar-system-m4-l4-lesson-3','85762d16251ed28eefbfcda66b36b66a','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Moon Base Benefits</h3><p>Moon Base Benefits</p><p>While watching this video, think about this question:&#160;Let’s say a base is actually built on the Moon.&#160;What do you think would be its benefit to us?</p><p>Welcome back, this is Video 3 of this module on The Moon Base.</p><p>It seems that more than ever, space programs in many countries and commercial interests are working towards a common goal of settling humans on other planets. We’ve looked at the potential benefits for research in the first two sections of this module. Now we’re going to look at the political and commercial advantages of building a base on the Moon, but also at what some call the “survival of the species” imperative.</p><p>Space exploration is very expensive so it’s no surprise it’s been financed mostly by governments in the past trying in part to motivate national pride but also to stimulate technological innovation. The space race of the 1960s is a perfect example of this. There was no bigger agenda at the time than putting American boots on the Lunar surface.</p><p>Have a look at this graphic showing NASA’s budgets between 1958 and 2017. Notice how the biggest budgets were between 1963 and 1969 when the US and the Soviet Union were trying to get to the Moon first. And it worked. American astronauts did make it to the Moon on July 20, 1969 and the technology developed to get them there transformed our daily life here on Earth.</p><p>But, as soon as the goal was attained, the budget started to decrease and today, it’s only a fraction of what it was. People like Elon Musk, CEO of SpaceX, believe we need to set a new and difficult goal to attain to stimulate investment again. Building a base on the Moon or on Mars would certainly qualify as a challenging goal.</p><p>Currently, only three countries had or have the capability to send humans to the Moon: The US, Russia and China. But other players are also planning to join that elite group. They are Europe, India and Japan. But many commercial organizations have also entered the space race, more often than not using the billions of dollars they accumulated in the tech industry. In addition to Musk, already mentioned, Amazon’s Jeff Bezos and Virgin’s Richard Branson have also created companies and are building rockets to visit space.</p><p>A lot of money is being spent on space at the moment, but all the players will probably have to cooperate if humanity has a chance of colonizing other celestial bodies. Already, NASA gave $6.8 billion to SpaceX and Boeing to build rockets that can take astronauts and cargo to the ISS. This might seem like a lot of money but don’t forget that since the space shuttle program ended in 2011, American astronauts have had to hitch a ride to the ISS on Russian Soyuz rockets at a cost as high as $82 million per seat, essentially financing the Russian space program.</p><p>Bezos is also interested in collaborating with NASA but he’s more interested in the Moon. He thinks it’s the first logical step before going to Mars. He wants to develop a partnership between Blue Origin and NASA to deliver cargo to the Moon, sort of like an Amazon space service. He loves the idea of the Moon village concept proposed by the European Space Agency (ESA) and thinks collaboration is the way to go. In fact, in May of 2019, Bezos unveiled a moon lander prototype and discussed plans to refuel the lunar lander with ice from the moon. It will be interesting to see the fast-evolving developments with Blue Origin. Who knows, maybe by the time you are taking this course, they will have already landed on the moon!</p><p>One argument that’s been made to support the need to build a base off-planet is nothing short of the survival of our species. While he’s not the only one to think that, Elon Musk is one of the most well-known advocates of that idea.</p><p>He said: “I think there is a strong humanitarian argument for making life multi-planetary, in order to safeguard the existence of humanity in the event that something catastrophic were to happen, in which case being poor or having a disease would be irrelevant, because humanity would be extinct. It would be like, “Good news, the problems of poverty and disease have been solved, but the bad news is there aren’t any humans left.”</p><p>These doomsday predictions are based on the past, specifically, how dinosaurs disappeared. There are two popular theories to explain what happened to dinosaurs. Both are based on the fact that we find the metal iridium all over the planet, even in oceans.</p><p>- Theory #1: An asteroid or comet, which contain iridium, hit the Earth in Mexico’s Yucat&#225;n Peninsula creating a 110-mile-wide crater.</p><p>- Theory #2: Magma erupted from the Earth’s core rich in iridium, and covered 1 million square miles of India, 1.5 miles thick.</p><p>Both theories have evidence of happening 65 million years ago, which is exactly when dinosaurs went extinct. Both events would have caused a lot of debris to be thrown into the atmosphere blocking sunlight and preventing photosynthesis, destroying the food chain in the process. Both events would have caused a lot of iridium to be released and spread all over the planet.</p><p>Those pushing for colonizing other planets and moons believe that a similar event is inevitable in our future and want to make sure at least some of our civilization survives. But not every tech billionaire thinks space is the only solution. Richard Branson, the founder of Virgin Galactic, likes to separate his goals and those of Jeff Bezos, founder of Blue Origin, and from those of Elon Musk.</p><p>Richard Branson said: “I think Jeff and ourselves are more interested in how we can use space to benefit the Earth, because the Earth is, in my opinion, extremely beautiful and needs to be protected. And we’ve just learned about some of the ways we can protect Earth by using space.”</p><p>Critics of Musk’s approach say that focusing so much on colonizing Mars means humans are privileged over Earth and all the other species. It’s also only a goal for the very rich since a ticket to Mars could cost between $200,000 and half a million dollars.</p><p>Beyond the obvious prestige that would come with being the first country to build a base on the Lunar surface, here are some additional benefits. A settlement on the Moon could be used as:</p><p>- A mining colony: The Moon is thought to be rich in iron, titanium and other metals</p><p>- A refueling hub to go further into sp<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('dd4adcedcd4777028b12e890ee4dcbaa','space-travel-and-solar-system-m4-l5-lesson-4','85762d16251ed28eefbfcda66b36b66a','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Lunar Surface Designs and Physiology</h3><p>Lunar Surface Designs and Physiology</p><p>In the last section, we asked you to imagine your own design for a base on the Lunar surface.&#160;How much of an impact do you think physiological requirements would have on your design?</p><p>Welcome back, this is Video 4 of this module on The Moon Base.</p><p>We’ve been talking about the possibility of building a base on the Lunar surface and we’ve touched a bit on the requirements of human life on other planets. In this section, we’re going to look a lot more closely at human physiology (specifically how the human body functions normally) and what would be needed to sustain human life on the Moon and other planets, and during space travel.</p><p>In your biology class, you learned that the human body needs certain things to survive. It doesn’t take a rocket scientist (pun intended) to know that we need oxygen to breathe, and water and food to feed our bodies. But we also benefit from many aspects of our environment on Earth like gravity and the conditions that allow photosynthesis. We’re also very lucky to have an atmosphere that protects us from radiation, extreme heat from the Sun, and debris from meteorites. But outside of the Earth’s atmosphere, things are very different and a lot more hostile to the human body.</p><p>NASA’s Human Research Program identified five dangers to human life and well-being if we were to travel to Mars, many of which apply just as well to life on the Moon. Let’s go through each of them.</p><p>One: Radiation</p><p>On Earth, we’re shielded from radiation by two things: our atmosphere and the magnetic field. Our atmosphere provides a protection equivalent to a sheet of metal that’s 3 feet thick. Earth’s magnetic field is generated by electric currents from the planet’s liquid iron core that extend into space.</p><p>But in outer space, humans don’t have any natural protection from the radiation produced by our Sun and other sources in our galaxy and beyond. Why does radiation matter? You’ve probably already heard about the effects of radiation here on Earth. When people are exposed to it, they become sick. Well, the same is true in outer space. Radiation is made up of subatomic particles that rip through the body and damage human DNA molecules, preventing them from reproducing properly. The result is an increased risk of cancers and other diseases.</p><p>Just to give you an idea, on its way to Mars, the rover Curiosity calculated that an astronaut on a 253-day trip to the red planet would be bombarded by the equivalent radiation of receiving a full CT scan here on Earth every five or six days, which would increase the chance of fatal cancers.</p><p>Two: Distance</p><p>The Moon is 239 thousand miles away from Earth or roughly three days away with current technologies. While that may not seem too far, it does mean that any settlers would have to be self-sufficient to a large degree. After all, you can’t pop out to the supermarket or the drugstore if you need a loaf of bread or some pain killers. And even if colonies can be resupplied periodically, the more they can do themselves, the lower the cost of a lunar base.</p><p>What does this mean in practical terms for human well-being? It means you would need to be able to produce and preserve at least some of your own food and medicine. It would also be helpful if you could perform some medical tests and procedures on yourself and others.</p><p>Three: Isolation and confinement</p><p>Different people need different levels of interaction but whether you’re a social butterfly or someone who prefers to be alone, being confined to a small space with nowhere to go ever, can take a toll on humans. NASA has found that no matter what, even the most social group of people will eventually develop some issues such as low morale or mood swings, that might compromise communication.</p><p>Four: Gravity</p><p>Being able to bounce around in a low gravity environment sounds like a lot of fun, right? Well, now imagine trying to play your favorite sport when your feet don’t want to stay on the ground and you have to wear thick gloves. Not so easy… or fun! Gravity on the Moon is only 17% of Earth’s gravity, which would make working a little awkward. But it also has some consequences on the human body.</p><p>Moving from one type of gravity to another can have many effects such as making you disoriented, unbalanced, or sick to your stomach. It can also reduce your hand-eye and head-eye coordination. The most lasting impact would be the loss of bone density at the fast rate of 1% per month. When you lose bone density, you have a higher risk of breaking them. This also happens to people on Earth as they age.</p><p>Five: Hostile-closed environments</p><p>You don’t have to go to outer space to understand that a closed environment can become unhealthy. Just think about your bedroom in winter when it’s too cold or in summer when it’s too hot to open the window. It starts feeling “less fresh” very quickly. Now imagine you’re sharing your room with 3 other people, each with his or her own music taste. Pretty soon you start feeling stressed out, you don’t sleep well and if anyone catches a cold, everyone gets it. That’s how it would feel to live in space.</p><p>The International Space Station (ISS) hovers just under 250 miles above the surface of the planet and completes a rotation of the Earth every 90 minutes. Over the last 18 years, astronauts, cosmonauts (which is the preferred name in Russia) and space tourists from 17 different countries have experienced life in space on board the ISS. They&#39;ve made an enormous contribution to understand the impact of space on the human body better.</p><p>Even though the station is still relatively close to Earth, many of the effects would still apply to settlers living on the Moon. Here are a few of the most important observations:</p><p>- Humans lose muscle tone and bone density in zero gravity so astronauts have to exercise two and a half hours each day using a treadmill and elastic ropes.</p><p>- Living in confined spaces causes loneliness and stress. Russian cosmonaut Valery Ryumin once said about his time on the Soviet orbital space station Salyut 6 (which was in space in the late 70’s and early 80’s): &quot;All the conditions necessary for murder are met if you shut two men in a cabin measuring 18 feet by 20 and leave them together for two months.&quot;</p><p>- Radiation can lead to cancer<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('211f5244f744795ba6bdd148b2a69132','space-travel-and-solar-system-m4-l6-lesson-5','85762d16251ed28eefbfcda66b36b66a','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Moon Scientific Discoveries</h3><p>Moon Scientific Discoveries</p><p>While watching this video, think about the following:&#160;Colonizing the Moon would be cool, and may well lead to all sorts of scientific discoveries, but it&#39;s probably just a stepping stone on the way to Mars.&#160;What benefits are there to going to the Moon first?</p><p>Welcome back, this is Video 5 of this module on The Moon Base.</p><p>It’s so close you can almost touch it. It takes three days to fly to the Moon by a rocket. In a few short years, we could probably send reusable spaceships there and it would become like any other kind of flight. But is that really what we should be doing with the Moon? Turning it into Earth 2, but with a little more bounce? In this section, we&#39;ll take a look at the idea of using the Moon as a staging ground for further exploration and the challenges it would present.</p><p>Do you know how gravity keeps everything on Earth nicely stuck to the ground? This is great for, say, your dog or little sister, but not great when you want to launch a rocket. Think about it, if you&#39;re trying to launch something in the air like a rock for example. You can pick a small rock and throw it up easily but if you want it to go really high, you’ll need a heavier rock and you’ll need a lot more energy. It’s the same thing with a rocket. The heavier it is, the higher you can go but the more fuel you’ll need to escape the Earth’s gravitational pull. This requirement is called &quot;delta-v budget&quot;. Put simply, the more mass you want to put into space, the more fuel you need.</p><p>Here’s another example. When you go on a family drive, a bus ride to a local park, or a school field trip for a few hours, you might pack a lunch and a jacket in case it rains. But what about a trip for a week? Suddenly, you need more than lunches, snacks and some clothes. Now, imagine you&#39;re going on a camping trip. You’ll have to bring a tent, a sleeping bag, and a lot more food. You’ve gone from a small pack to the trunk of a car full of stuff. The longer you&#39;re going, the more stuff you&#39;re taking, the more fuel you need for the car. You also need fuel for your body in the form of food!</p><p>What if you could cut your backpack’s weight in half? Launching rockets from the Moon would have the same effect because the closer to Earth you are, the more its gravity pulls you back. To reach low Earth orbit, you need a delta-v requirement of 9.4 kilometers per second or kps. Then, to free yourself from low Earth orbit requires an additional 3.2 kps, so a total of 12 kps. In comparison, it would only take a v-delta requirement of 2.6 kilometers per second to escape the Earth&#39;s gravity (called the &quot;gravity well&quot;) from the Moon. Suddenly, you can see the advantage of leaving from the Moon instead of Earth if your plan is to continue further into the galaxy.</p><p>Right, enough math, what does this mean practically?</p><p>“Less gravity = more payload”</p><p>If you want a really big payload to go to a far-off planet, like Mars for example, then the Moon is the launch site for you. Once you&#39;re putting most of the rocket&#39;s power into lifting payload instead of breaking free of the Earth&#39;s gravity well, then you can ship more equipment with you and use a lot less fuel in the process.</p><p>Since the Moon can be mined for water, which can then be used to make hydrogen, it could become a refueling station. In terms of cost, it&#39;s possible that the Moon colony or base would actually be able to pay for itself in savings we&#39;d make for further space exploration.</p><p>One of the greatest problems in space travel and colonization is electrical power. You need a lot of power to get places, you need a lot of power to run systems and you&#39;d need a lot of power to run a colony or moon-based station. The problem then becomes, where do you get this power? Think about the ISS, they generate the power they need with solar panels. But there&#39;s a trick, the ISS houses a maximum of six crew. For just these six crew members and the equipment on the ISS, they have eight solar array wings, each of which is 115 feet long and 39 feet wide. That’s massive and may not be practical for a moon base! However, continual developments in solar panel technology here on earth may help reduce the size of panels in the future.</p><p>What might be an alternative to solar power? Enter the nukes! One of the most cost-effective ways to produce energy is to use a nuclear reactor. Currently, a lot of nuclear reactors use plutonium, which is unstable, dangerous, needs to be mined and is the same stuff that is used to make bombs. But newer reactors, which are still in the testing stage, will use uranium isotopes, which are easy to find and more stable.</p><p>The idea is to make tiny reactors, called Kilopower, which will be able to power complex rockets and, potentially, whole settlements.</p><p>So, the Moon or Mars? Will we be Martians or Moon people?</p><p>The Moon is closer, so that would seem to make it the most logical choice for a colony and permanent settlement. Oddly though, given how close it is to our planet, it would probably be more difficult to engineer for.</p><p>One of the biggest problems with the Moon is the length of its day and the day to night temperature change. On Earth, obviously, the day is 24 hours long. Our bodies and society are set up around this time. A Moon day? 28 days. So, really late bedtimes and a lot of daylight to get stuff done, right? The issue isn&#39;t really the daytime, it&#39;s the night.</p><p>On a winter day, depending on where you live, you might need a long sleeve shirt or a parka during the day when the Sun is up. But at night? You might need a hoodie and a warm hat, or a huge parka and a sweater and maybe even snow pants. In these cases, we&#39;re probably only talking about a 10 or 15-degree difference in temperature. How would you have to dress if there was more than a 500-degree Fahrenheit difference between day and night? Think about what kind of house you&#39;d need and how tough your car would have to be. Those are the kind of issues that living on the Moon would bring. Mars, on the other hand, has a day that&#39;s a bit longer than 24 hours, so the day to night temperature changes aren&#39;t nearly as drastic.</p><p>Ok, so the days are very long on the Moon, but what about the atmosphere? Mars is so far away, it must be harsher. Nope. Once<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c704b11d90a33a6bbf09c28513f20837','space-travel-and-solar-system-m4-l7-module-4-summary','85762d16251ed28eefbfcda66b36b66a','Module 4 Summary','text',12,'<h2>Module 4 Summary</h2><section><h3>Module 4 Summary</h3><p>Module 4 Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on the Moon Base!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Discussed the present and historical impact of the moon on the earth.</p><p>Analyzed the geographic features of the moon and the advantages/disadvantages of building a base on the moon.</p><p>Evaluated the political and future innovative benefits of placing a base on the moon.</p><p>Identified the physiological requirements for those residing on a moon base.</p><p>Analyzed the impact of a moon base to future colonization of Mars and other planets.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('042afe8ea4d37dfb15936c727209a8df','space-travel-and-solar-system-m4-l8-module-4-assignment','85762d16251ed28eefbfcda66b36b66a','Module 4 Assignment','text',12,'<h2>Module 4 Assignment</h2><section><h3>Module 4 Assignment</h3><p>300</p><p>Space Travel</p><p>Moon Base - Short Answer Assignment</p><p>Short answer assignment</p><p>Based on what you’ve learned in this module, choose&#160;one&#160;of the following questions and answer it on a two-page, double-spaced paper, and explain your answers:</p><p>Should we build a base on the Moon or simply visit it often? Explain the advantages and disadvantages of a Lunar base.</p><p>The 1967 Outer Space Treaty adopted by the United Nations sets up some guidelines for space exploration. Take a closer look at the principles and make them future proof based on what you learned in this module. For example, one of the proposed solution to prevent an asteroid from hitting Earth is to blow it up using nuclear weapons, which goes against principle #4. Do you think it should be changed?</p><p>Do you think it’s dangerous to let so many commercial companies like SpaceX, Boeing, Blue Origin, etc. develop the technology to take humans into space? What are the advantages and disadvantages according to you?</p><p>Moon Base Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b948c4ad87d4c6f587f0f7cfba9616d6','space-travel-and-solar-system-m4-l9-module-4-project','85762d16251ed28eefbfcda66b36b66a','Module 4 Project','text',12,'<h2>Module 4 Project</h2><section><h3>Module 4 Project</h3><p>3300</p><p>Space Travel</p><p>Moon Base - Project</p><p>Project</p><p>For this assignment, pretend you have become the world next multi-billionaire and have decided to make space tourism and moon travel part of your legacy to humanity. Assume you have created or obtained the necessary technology to make a visit to a newly built moon base possible. Now, you just need some customers! Create a brochure to attract tourists to visit the moon.</p><p>Your brochure should:</p><p>Be aimed at a target audience (families, college students, seniors, etc.)</p><p>Discuss the details and steps of preparation for a trip to the moon</p><p>Outline the timeline of a voyage, including time spent in near-earth orbit, traveling to and from the moon, and time spent on the moon’s surface</p><p>Explain the risks involved in take-off, travel, and re-entry, as well as any potential long-term health risks</p><p>Address the exciting things that travelers could learn, see, and experience while traveling in space and while on the surface of the moon</p><p>Be clear, organized, and positive to help inform the reader</p><p>Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Content</p><p>8 points The brochure demonstrates a strong understanding of the role of the PT/PTA and preventative physical therapy.</p><p>7-6 points The brochure demonstrates a satisfactory understanding of the role of the PT/PTA and preventative physical therapy.</p><p>5-0 points The brochure demonstrates little to no understanding of the role of the PT/PTA and preventative physical therapy.</p><p>8</p><p>Details</p><p>8 points The brochure contains several specific and accurate details of preventative care strategies and effectively describes what individuals can do to improve physical health.</p><p>7-6 points The brochure contains some specific and accurate details of preventative care strategies and adequately describes what individuals can do to improve physical health.</p><p>5-0 points The brochure contains few to no specific and accurate details of preventative care strategies or does not adequately describe what individuals can do to improve physical health</p><p>8</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Presentation</p><p>2 points The brochure is well organized and presented in an engaging way.</p><p>1 point The brochure is somewhat organized and is presented in a slightly engaging way.</p><p>0 points The brochure is not organized well or is not presented in an engaging way.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0a909e98bdae83ac75822d029d372f4a','space-travel-and-solar-system-m4-l10-module-4-quiz','85762d16251ed28eefbfcda66b36b66a','Module 4 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Moon Base. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('a26b18dbe647d03720222905e4935a98','space-travel-and-solar-system-module-5','2a892040eda1f32ee69b17d25aad96dd','Module 5: Mars 5 Colony',5) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('889c646374a6890477270732abe62d9b','space-travel-and-solar-system-m5-l1-introduction-purpose-and-objectives','a26b18dbe647d03720222905e4935a98','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi and welcome back. This is the intro video on the Mars Colony.</p><p>Martians… let your imagination chew on that word for a second. Are you picturing the Looney Tunes character Marvin the Martian or a taller, stronger, more intelligent and more advanced super race? Do you think of a peaceful society willing to share its technology or one ready for war and invasion?</p><p>The truth is we don’t know much about Mars. After all, we can&#39;t just see it up close in our night sky like we can with the Moon. We know it has a bright reddish-orange color, which is why it’s called the Red Planet. We know there are no Martians, at least not anymore, but the many NASA missions that have collected information about Mars seem to show that some form of life existed at some point in time.</p><p>In this module, you’ll learn all there is to know about Mars, its history, its composition, and whether it could sustain life. This information will then help you consider the possibility of colonizing the Red Planet and what it would take in terms of resources and protection for humans to survive the trip and build an outpost on its surface. Are you ready? It’s going to be a fascinating module!</p><p>Module Description</p><p>License:&#160;All Rights Reserved</p><p>In this module, we’ll look at the history of Mars, how it was formed, and how its position in our solar system have contributed to it becoming the Red Planet.&#160;We’ll see current theories about the possibility of life on Mars in the past and its ability to sustain life now, which is a crucial piece of the puzzle for those who want to colonize it.</p><p>As you can imagine, it won’t be easy.&#160;You’ll have a chance to examine the many requirements to colonize Mars successfully.&#160;From transportation to supplies and medical aid, and what humans would have to endure if they set foot on what appears to be a very hostile environment based on what we know so far.</p><p>Finally, we’ll look at the plans for a future Mars colony being drawn up by many countries and commercial companies like SpaceX.&#160;Will it be the mid-2030s when Mars is closest to Earth?</p><p>Objectives</p><p>In this module, students will</p><p>Discuss the historical evidence of the ability of Mars to sustain life.</p><p>Analyze the current theories on colonizing Mars.</p><p>Identify the infrastructure required to provide transportation, supplies, and medical aid to a Mars Colony.</p><p>Identify the physiological requirements for those residing on a Mars Colony.</p><p>Construct a timeline of colonization theories and future predictions around a successful Mars Colony.</p><p>Polling Question</p><p>When you think about Mars, do you see it as .&#160;.&#160;.</p><p>a place we should colonize&#160;a world that&#39;s very toxic to human life</p><p>Make a selection to see the results so far.</p><p>If you could, would you like to go to Mars?</p><p>Yes, sign me up now&#160;Not ever&#160;Maybe once its safe</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>A clouding of the eye that causes vision problems.</p><p>Photosynthesis</p><p>When Mars, which has an elliptical orbit, gets closer to the Sun, every two years.</p><p>Photon</p><p>A particle of light that carries energy.</p><p>Cataracts</p><p>Process used by plants, algae and some bacteria to turn sunlight into chemical energy.&#160;This process releases oxygen into the atmosphere.</p><p>Perihelion</p><p>When you never get enough sleep.</p><p>Chronic sleep deprivation</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>A clouding of the eye that causes vision problems.</p><p>Photosynthesis</p><p>Cataracts</p><p>Chronic sleep deprivation</p><p>Photon</p><p>Perihelion</p><p>2.</p><p>When Mars, which has an elliptical orbit, gets closer to the Sun, every two years.</p><p>Chronic sleep deprivation</p><p>Perihelion</p><p>Photosynthesis</p><p>Cataracts</p><p>Photon</p><p>3.</p><p>A particle of light that carries energy.</p><p>Perihelion</p><p>Photon</p><p>Photosynthesis</p><p>Chronic sleep deprivation</p><p>Cataracts</p><p>4.</p><p>Process used by plants, algae and some bacteria to turn sunlight into chemical energy. This process releases oxygen into the atmosphere.</p><p>Cataracts</p><p>Photosynthesis</p><p>Chronic sleep deprivation</p><p>Perihelion</p><p>Photon</p><p>5.</p><p>When you never get enough sleep.</p><p>Photon</p><p>Photosynthesis</p><p>Chronic sleep deprivation</p><p>Cataracts</p><p>Perihelion</p><p>Charles Darwin wrote “On the Origin of Species” in 1859 after seeing, based on extensive research that species adapt to their environment over time in order to survive and multiply.</p><p>Terraforming</p><p>Measurement used to calculate the level of radiation someone has been exposed to.</p><p>Sievert</p><p>Process by which a planet is transformed so that it provides an environment that’s similar to Earth.</p><p>Theory of evolution by natural selection</p><p>Part of the eye that collects light and sends messages to the brain to form an image.</p><p>Retina</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Charles Darwin wrote “On the Origin of Species” in 1859 after seeing, based on extensive research that species adapt to their environment over time in order to survive and multiply.</p><p>Terraforming</p><p>Theory of evolution by natural selection</p><p>Sievert</p><p>Retina</p><p>2.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b66588068cf0a77cabac1ea3ba7d9aef','space-travel-and-solar-system-m5-l2-lesson-1','a26b18dbe647d03720222905e4935a98','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Commonalities between Earth and Mars</h3><p>Commonalities between Earth and Mars</p><p>While watching these videos, consider the following question:&#160;Do you think Mars and Earth have anything in common?</p><p>Hi and welcome to Video 1 for this module on the Mars Colony.</p><p>Mars is very mysterious. Maybe it’s the bright red color or maybe it’s the fact that even though it shares many common features with Earth, it seems deadly and hostile. Of course, our perception of Mars could also have something to do with the many science-fiction books and movies with stories of Martians ready to invade our planet. So, before we go on to talk about the possibility of colonizing Mars, let’s get a few facts straight.</p><p>Mars formed in the same way as all the other planets in our solar system when debris orbiting the Sun started piling up into each other to form planets. It’s a bit like when you make a snowman and it keeps growing and growing as you roll the ball and more snow sticks to it. For those who don’t live in a climate where it snows, it would be comparable to Playdoh or even baking and how a small object can get bigger as you add more material. Of course, the process that created the planets was a lot less gentle.</p><p>Mars is roughly the same age as the Earth at roughly 4.6 billion years old. Eventually, the heat caused by all the impacts created different layers and the denser elements like iron sunk to the center and became the core of Mars in the same way it did on our planet. The heat also caused volcanoes to grow and erupt. Gases were released as the planet cooled to form an atmosphere at first but the cooler Mars became, the thinner the atmosphere.</p><p>You might be wondering why Mars and Earth aren’t more alike if they formed in the same way and are about the same age? One factor is that Mars formed in about 10 million years while the Earth took 10 times longer. Then, there’s the constant bombardment of high-energy photons and magnetic storms by the Sun, which has stripped Mars of its atmosphere.</p><p>So why wasn’t Earth affected? Because it has a very strong magnetic field that protects it against the effect of photons. The sunlight that gets in is trapped by greenhouse gases, and goes on to power the climate on Earth and help regulate temperatures.</p><p>Let’s take a closer look at photons and their effect. An atmosphere is made up of gases. The Sun is constantly sending hot solar winds across the solar system. In these winds are charged particles and high energy photons. A photon is a particle of light that carries energy. The Earth’s magnetic field is strong enough to deflect most of the particles but on other planets like Mars, which doesn’t have a magnetic field, the photons split the molecules in the atmosphere. This makes the gases lighter and allows them to escape the planet’s gravity into space. Eventually, only heavier gases like carbon dioxide are left.</p><p>NASA believes Mars lost its atmosphere between 4.2 and 3.7 billion years ago.</p><p>Looking at them, you might think that Mars and the Earth don’t have anything in common but you’d be wrong. Here are 10 things they share:</p><p>They’re both planets. Earth is the third and Mars the fourth planet in our solar system.</p><p>They both have an atmosphere. Mars is 96% carbon dioxide, 1.9% argon and 1.9% nitrogen compared to 78% nitrogen, 21% oxygen and 1% argon on Earth.</p><p>They both have a gravity, although that of Mars is only 38% of gravity on Earth.</p><p>They both have seasons because they both rotate on a similar tilted axis. The temperature in the summer at the Equator is very earth-like going as high as 95 degrees Fahrenheit but in winter, it can drop as low as negative 225 degrees Fahrenheit because Mars’ thin atmosphere can’t store much of the Sun’s heat.</p><p>They both have mountains and canyons. Olympus Mons is the largest volcano and second-highest known mountain in our solar system, roughly three times the height of Mount Everest! Here’s a photo of it taken by NASA’s Viking orbiter. VallesMarineris is the largest canyon in our solar system with a length of 2,500 miles and a depth of 4.3 miles. Here’s a topographic map showing just how big it is. For comparison, the Grand Canyon is 277 miles long and a mile deep.</p><p>They both have days of similar length (24 hours on Earth versus 24 hours 39 minutes on Mars).</p><p>They both have a core, surrounded by a mantle, surrounded by a crust although the Earth’s mantle and core have multiple layers. Here’s a graphic showing a simplified view of the layers of several planets in our solar system.</p><p>They both have moons. Mars even has two: Phobos and Deimos, believed to be asteroids that got captured by the planet’s gravity.</p><p>They both have storms. We all know the power of hurricanes, tornadoes, cyclones and other natural disasters on Earth. Mars gets hit with massive dust storms with winds as high as 100 mph (the equivalent of a category 2 hurricane). These storms can cover the entire planet.</p><p>And 10. They both have water although it’s completely frozen on Mars. If the ice cap at the Martian South pole melted, the entire planet would be covered with 36 feet of water.</p><p>Now that we know what Mars and the Earth have in common, let’s see how they’re different. Here are 5 facts to give you an idea:</p><p>Mars is about half the size of Earth. If you took all the land masses on Earth (excluding the oceans), you could make Mars.</p><p>The orbit of Mars is more elliptical (or oval-like) in shape compared to the Earth’s circular orbit.</p><p>A year on Mars is 687 days compared to 365 on Earth. That’s the time it takes to orbit the sun completely.</p><p>Mars only gets 43% of the sunlight the Earth gets because it is 1.52 times further from the Sun.</p><p>The tectonic plates on Mars don&#39;t move anymore as they do on Earth.</p><p>You now know a lot more about Mars but one important question remains: Was there or is there life on Mars? Or at least, is there evidence that the Red Planet could sustain life? The answers to these questions could make a base on Mars easy! Or it could make it almost impossible.</p><p>So, what’s needed for a planet to sustain life? According to Christopher McKay, an astrogeophysicist and senior scientist at NASA, there are a number of crucial elements to look for:</p><p>Is there water?</p><p>Does the temperature allow for the water to be in a liquid form?</p><p>Is there enough sunlight to provide t<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3ebf7f13b2e6c871d5f030c1f6aad27c','space-travel-and-solar-system-m5-l3-lesson-2','a26b18dbe647d03720222905e4935a98','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Cost of Colonizing Mars</h3><p>Cost of Colonizing Mars</p><p>While watching this video, think about if it is worth spending billions of dollars to colonize Mars.</p><p>Welcome back, this is Video 2 of this module on the Mars Colony.</p><p>There seems to be an increasing talk about visiting and colonizing Mars. A lot of people making declarations in the media about why we should and why we shouldn’t. It can be hard to keep track of the arguments on both sides so here’s a summary of the contenders and the critics of launching a human mission to the Red Planet.</p><p>It’s hard to ignore all the pronouncements made by Elon Musk, CEO of SpaceX, about why we should set up a colony on Mars. He thinks that going to Mars is necessary “to safeguard the existence of humanity in the event that something catastrophic were to happen” like an asteroid hitting the Earth for example. “Protecting the human race from disappearing” is the most common argument made by those who want to colonize Mars.</p><p>Other companies have much lower ideals. Take Dutch company Mars One for example. It’s making plans to send robots and communication equipment first and then a human crew by 2031. Why? As a reality TV show! They’ve been screening contestant-volunteers willing to risk their lives for a one-way ticket to Mars. They want to narrow it down to two men and two women, each from a different continent here on Earth.</p><p>Other companies like Boeing and Lockheed Martin work closely with NASA to build rockets and other space equipment. These companies don&#39;t have plans to colonize Mars. Their only goal is to build the means to get there and back. In 2007, NASA gave Boeing a contract to build the Ares rocket, which was supposed to be used to launch the next generation of rockets, the Orion, but the program was cancelled in 2010. In 2014, NASA gave Boeing another contract to share the transport of astronauts to the ISS with Space X.</p><p>As for Lockheed Martin, they worked on several projects for NASA. Currently, they’re working on the Orion Crew Exploration Vehicle, which is a key component of NASA’s plans for future space exploration. More specifically, they’re building the command module and the European Space Agency (ESA) is building the service module. They also presented something they call Mars Base Camp; a science lab orbiting Mars, where settlers could perform experiments as they do on the ISS.</p><p>Currently, NASA, Roscosmos, the Russian space agency, and the China National Space Administration are the only three national space agencies who have announced plans to go to Mars. Their reason for going has a lot more to do with science. Even though Russian President, Vladimir Putin, has declared his intention of sending people to Mars, Russia is probably the least advanced and Roscosmos haven’t announce any definitive plans to do so.</p><p>China is moving full-steam ahead with its space program. First, in early 2019, they landed a spacecraft on the far side of the Moon, something that had never been done. The Chinese haven’t made it a secret that they have their eyes on Mars.</p><p>And then, there’s NASA and their goal is purely scientific. They want to keep studying Mars and make plans to get there to eventually in the 2030s with a crewed mission. They’re putting a lot of hope in their new capsule, the Orion. In November 2018, NASA managed to land their latest probe on Mars, the InSight. They’re the only space agency to have successfully landed probes on Mars.</p><p>So, to recap… some people see colonizing Mars as a necessity to save the human race. Others view it as entertainment. But the most common argument to settle people on Mars is science.</p><p>A lot of people are really excited about the idea of colonizing Mars but can you think of a few reasons why it’s a bad idea? Some critics can. Here are a few things to consider:</p><p>Should we go?</p><p>With all this talk about how and when we should go to Mars, it seems we’ve forgotten about whether we should. So far, human explorers have been very careful to sterilize everything they’ve sent into space. That’s because everything leaving the Earth’s surface brings with it trillions of microbes that may be harmless here but could cause devastation on another planet or even in space.</p><p>A good example is what happened when Europeans colonized the Americas. Christopher Columbus and subsequent expeditions brought many diseases with them such as smallpox and influenza killing hundreds of thousands and possibly millions. And it works both ways. Columbus is also believed by scientists to have brought back syphilis to Europe when he came back from South America.</p><p>Elon Musk, who is one of the people pushing the most for a Mars colony and is not bound by governmental rules, was highly criticized earlier in 2018 for sending off a Tesla car and a mannequin into orbit without sterilizing them first. Some scientists called this “the largest load of earthly bacteria to ever enter space”. The car is now floating in space and we might never know what impact it’s going to have.</p><p>So, let’s say we make it to Mars and we’re not careful about the microbes we carry and they find their way onto the surface. First, they could contaminate the planet’s ecosystem. Mars may not seem like much but we still don’t know much about its environment or the lifeforms it might be hiding. After all, Opportunity, the longest-running rover on Mars, has only covered 28 miles in 14 years, which is great considering the environment but a tiny part of the whole planet.</p><p>Another thing to consider is that we might lose the evidence of life that we haven’t yet discovered. If Earth microbes make it onto Mars and we then discover evidence of life, we’ll never know for sure if it came from Earth or was already on Mars. This has made famous scientist and writer Carl Sagan say:</p><p>“If there is life on Mars, I believe we should do nothing with Mars. Mars then belongs to the Martians, even if the Martians are only microbes … the preservation of that life must, I think, supersede any other possible use of Mars.”</p><p>Another big question mark has to do with Earth itself and us as a species. Are we responsible enough as beings to be trusted with setting up a colony on another planet? Many would say that the damage we’ve done to our environment means we’re the last species that should be trusted. What would humans do to the Moon or Mars? Science-fiction doesn’t give us <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8dfbd9fd1430f086a587bac25755795b','space-travel-and-solar-system-m5-l4-lesson-3','a26b18dbe647d03720222905e4935a98','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Trip to Mars Requirements</h3><p>Mars Colony - Lesson 3</p><p>Trip to Mars Requirements</p><p>While watching this video, think about what you would pack if you had one piece of luggage to take on a mission to Mars.</p><p>Welcome back, this is Video 3 of this module on The Mars Colony.</p><p>That’s it, you’ve made your decision… you’re going to Mars. Now, what should you pack and how will you get there?</p><p>Obviously, the first thing you need to sort out is how to get there. Currently, no one has a spaceship capable of taking humans to Mars.</p><p>Elon Musk, the CEO of SpaceX, is without a doubt the most vocal advocate for installing a colony on Mars. To achieve that goal, his company is working on the Big Falcon Rocket (BRF), a reusable spaceship capable of transporting 100 colonists to Mars.</p><p>NASA and its partners are working on the Orion spacecraft but the American space agency is not making a beeline for Mars. Instead, it wants to use Orion to test technologies and procedures that could, eventually, be used on a trip to Mars. First, it plans to explore asteroids, the Moon, then the space between Earth and Mars, and finally Mars. The first flight for Orion is planned for the 2020s and Mars is the target in the 2030s. If you’re interested, you can follow the spacecraft’s progress on the NASA Orion Spacecraft webpage.</p><p>So, if you want to head for Mars, take your time, it won’t be for a while.</p><p>When a spacecraft is eventually ready to go to Mars, a lot of thought will have to be given to the supplies that should make the trip. The more supplies, the less space, the heavier, the more fuel is needed. So, carrying the right supplies in the right amount is crucial. The more colonists can do with supplies or the more than can use local resources, the better.</p><p>For example, a 3D-printer could use local resources to create equipment or tools. A water-recycling system could be used to collect and reuse any liquid but also to produce oxygen. Seeds, or vacuum-sealed vegetables, could be used to grow food. NASA has been trying to grow potatoes in space conditions for some time for example, and the ISS has been successful at growing green-leafy vegetables.</p><p>Mars does have a few advantages :</p><p>- Its atmosphere is mostly carbon dioxide, gas plants use to breathe and recycle into oxygen for humans to breathe.</p><p>- Experiments in Hawaii, which has volcanic soil similar to that of Mars, also show that it can grow plants.</p><p>- Because of the lower gravity (38%), the soil can hold more water and the water and nutrients in plants will drain more slowly than on Earth.</p><p>That said it’s also colder and less sunny on Mars so settlers will have to find ways to shelter and heat their crops.</p><p>In the end, the key will be to ensure that everything that goes on the list should fulfill more than one use or could be used with local resources to make something else. This is especially true since space on the spacecraft will be needed for supplies during the trip like food, exercise and communication equipment, some water to get started, etc.</p><p>Have you seen the 2015 movie, The Martian with Matt Damon? If you haven’t, you need to see it! It deals with a lot of the issues we’ve been discussing. It shows a possible habitat for survival on Mars and it includes nine real-life technologies developed by NASA such as: the farm, water recycling (gross, but necessary), the ion propulsion system, and the Radioisotope Thermoelectric Generators (RTGs), also called “space batteries.”</p><p>These are all existing technologies that could be and probably will be adapted to life on Mars.</p><p>Taking things one step further, in 2016, NASA asked six companies to come up with habitat prototypes that need to be: Self-sustaining, sealed against the thin atmosphere, and capable of supporting life for extended periods without support from Earth. What would you create if you were given that project?</p><p>Even the healthiest human beings can get injured or become sick but what do you do when you’re six months away from Earth? Even if you have trained medical colonists, you can’t bring a whole hospital with you. One possible solution would be to use a 3D-printer, loaded with templates, to build the tools you need when you need them.</p><p>Surgery will be the biggest challenge at least in transit. Without going into the gory details, you can imagine that surgery in a zero-gravity environment could be… messy, not to mention a potential bio-hazard. The experts still haven’t quite figured out how to solve that problem. You might also think that some medical procedures could be performed by medical robots controlled by surgeons on Earth but that would require reliable and near-instant communication with Earth. This won’t be the case on Mars.</p><p>What about medicine? Colonists can’t carry every possible medicine with them and even if they could, their best-before date would eventually expire. So, NASA’s Human Research Program is trying to figure out what the most probable medical emergencies would be and what types of equipment and medication would be needed to solve them. They’re also testing packaging that would preserve medication in a space environment for as long as possible.</p><p>Do you see these as impassable obstacles or interesting problems to be solved? When humans first entered outer space in 1961, no one knew exactly how they’d get to the moon. But with dedicated minds (and funding) they made it happen in a mere 8 years. Something similar could be possible to overcome the challenges of establishing a colony on Mars!</p></section><section><h3>Trip to Marks Needs for Survival</h3><p>Trip to Marks Needs for Survival</p><p>(opens in a new tab)</p><p>Concept image of the interior of a deep space habitat&#160;by NASA</p><p>License:&#160;Public Domain</p><p>It’s impossible to predict what a trip to Mars and settlement on its surface will be like.&#160;But it doesn’t prevent us from imagining and testing what that might look like.</p><p>Space Habitats</p><p>Deep space habitats will play a crucial role in the survival of colonists whether they settle on the Moon, Mars or any other planet.&#160;Even though the conditions from one planet or moon to the next may vary greatly, habitats will have to provide some key elements.&#160;Nasa describes space habitats as:</p><p>“… a safe place for astronauts in space and on other worlds to achieve NASA’s human exploration goals, with inte<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('928b51baf9d2677574edd04fa37bf42f','space-travel-and-solar-system-m5-l5-lesson-4','a26b18dbe647d03720222905e4935a98','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Human Needs for Mars Survival</h3><p>Human Needs for Mars Survival</p><p>While watching this video, consider the following question:</p><p>If you had to live on Mars, what physical and psychological characteristics do you think you would need to survive?</p><p>Welcome back, this is Video 4 of this module on The Mars Colony.</p><p>Many of the same physiological requirements of settlers on the moon also apply to those who want to go to Mars. That said, the Moon and Mars are very different environments so let’s see what special abilities future Martians would need to have.</p><p>Ever wonder why astronauts sent to the International Space Station (ISS) have a six-month rotation? In part, it’s in preparation for a trip to Mars, which would take that length of time… (times two, if you plan to come back). Scientists have used the ISS to study the physical effects of living in space and they&#39;ve found it affects a person&#39;s muscles, bone density, balance and cardiovascular system.</p><p>Radiation however, will be a bigger concern not only for travelers to and from Mars, but also for colonists. Scientists already know that being in space increases the risk of developing cancer and cataracts, which is a clouding of the eye that causes vision problems. Astronauts on the ISS are on the edge of the Earth’s atmosphere so they’re still partially shielded from the worse. But Mars is not protected by an atmosphere so the effects would be more drastic. NASA’s rover Curiosity has calculated that a return trip to Mars plus 500 days on the surface would expose astronauts to a cumulative 1.01 sieverts of radiation.</p><p>Here’s a chart that shows different levels of exposure from getting a CT scan all the way to travelling to Mars and spending time there. As you can see, the levels of exposure are much higher on the way to and on the surface of Mars.</p><p>A sievert is a measurement used to calculate the level of radiation someone has been exposed to, which is something that happens for a number of reasons on Earth. For example, if you get an X-ray at the dentist, you’ll be exposed to 0.01 mSv. A millisievert (mSv) is the equivalent of one sievert. A chest X-ray would give you a dose of 0.02 mSv.</p><p>At 1.01 sieverts, astronauts would be exposed to a dose that can cause fatal cancer in five out of 100 people. And that’s just what we know. No one knows how radiation would affect colonists who choose to stay on Mars. One thing is sure, the human body is not made for space, and settlers would need to find ways to protect themselves from the harmful effects of radiation both inside shelters and out.</p><p>Another worry is that even if colonists adapt to life on Mars, and that’s a big if, their bodies might be so changed by the experience that they might never be able to return to Earth and pick up where they left off. When astronauts return from their six months on the ISS, they usually have a hard time standing and orienting themselves in an environment with gravity but at least their bodies readjust because it’s something that’s familiar to them.</p><p>On Mars, the gravity is 38% of that on Earth so colonists will find it easier to adjust but if they stay there long enough, their bodies might be transformed so much, they won’t be able to cope with the full gravity on Earth. So far, no human has lived for an extended period of time outside of Earth’s orbit. While the studies done on the ISS are very useful, they can’t predict what would happen in deeper space and how the human body would evolve in that context.</p><p>Scientists believe Martians might evolve into a different species in the same way animals on isolated islands, like the Galapagos, did. That’s the basis for Darwin’s theory of evolution by natural selection, which found that species adapt to their environment over time in order to survive and multiply. Except the changes are more than likely to be accelerated on Mars because the environment is so drastically different than Earth. Children born on Mars might be even more different since their bodies will never have experienced Earth’s gravity and environment.</p><p>Experts have been wondering how Martians might evolve and here are some possible answers:</p><p>- Stronger bones. We know the lack of gravity can lead to bone density loss so, to adapt to the 38% gravity on Mars, settlers might develop stronger bones over time.</p><p>- Bigger eyes. Mars gets less sunlight than Earth. For that reason, Martians’ eyes might adapt by becoming bigger so they can catch more light on their retina, which is the part of the eye that collects light and sends messages to the brain to form an image.</p><p>- A different skin color. Experts don&#39;t agree on this one. Some think colonists would become very pale because of the lack of sunlight and long periods of time spent inside. Others believe they would become very dark to cope with the lack of protection from the Sun. A third group thinks they might develop an orange color because their skin will stop being pigmented by melanin, like on Earth, and instead be pigmented by carotenoids, the same molecule that gives carrots their color. No one thinks they’ll be green though.</p><p>- Reproduction. In order to change, colonists will need to have children. It’s mostly in the next generations that Martians will start seeing physiological changes. Some suggest that they’ll need a “gravity chamber” where the children will need to grow before being exposed to the harsh Mars environment.</p><p>One extreme solution that’s been proposed is to simply skip evolution and transform the human body genetically right away before even going to Mars but no one has gone far enough to suggest how this could be done. Until then, scientists will instead try to find people who already have the right characteristics, such as more resistance to radiation, or more resilience to isolated conditions, stronger bones, etc.</p><p>Having the right physical characteristics is really important to make a good astronaut or settler, but there are other factors to consider. The psychological impact of being so far away from home is another challenge they’ll have to deal with. Feeling lonely is easy to fix when you’re on the ISS. A quick phone call to loved ones on Earth is always an option but communications on the way to Mars or after landing on its surface might not be as easy considering there’s a 20-minute delay.</p><p>An experiment called Mars-500 was conducted in Moscow b<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9ac2de7d603a8f38849f8609ee354572','space-travel-and-solar-system-m5-l6-lesson-5','a26b18dbe647d03720222905e4935a98','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Mars Colonization Possibilities</h3><p>Mars Colonization Possibilities</p><p>While watching this video, consider whether or not you think humanity will colonize Mars in your lifetime.</p><p>Welcome back, this is Video 5 of this module on The Mars Colony.</p><p>So far in this module, we looked at what’s needed to make it to Mars and survive on its surface. But we still have one important question to answer: When should we go?</p><p>Once humans have spacecraft capable of transporting them to Mars, nothing really prevents them from going. That said some moments are better than others. That’s because the Earth and Mars’ orbits around the Sun are different, which is why a year on Earth (365 days) is roughly two on Mars (687 days).</p><p>You already know that the Earth and Mars orbit around the Sun. But every two years, they line up so that our planet is between the Sun and Mars in what’s called opposition. At that point, the two planets are at their closest. Launching a mission to Mars so that the spacecraft reaches Mars when it hits opposition would save a lot of time, fuel and money.</p><p>Several companies and space programs are developing rockets and spacecrafts to go further into space. The initial goal is to continue to resupply the ISS but SpaceX, Virgin Galactic, Blue Origin, also have plans to take tourists into orbit and eventually to the Moon. NASA has a three-step plan to colonize other planets :</p><p>Earth Reliant. This is the current stage during which NASA is testing the effects of life in space using the ISS.</p><p>Proving Ground. Plans are in the works to return to the Moon and to test the safe return of astronauts to Earth.</p><p>Earth Independent. Humans will head off to Mars to set up a colony.</p><p>Exploration Mission-1 (EM-1) plans to launch the capsule Orion into space using the Space Launch System (SLS), which is essentially a powerful rocket. The three-week mission will be crew-less and go 280,000 miles away from Earth and past the Moon into deep space. It will be the furthest a ship has ever gone.</p><p>Exploration Mission-2 (EM-2) scheduled for 2021 will be taking astronauts into space and around the Moon using the SLS and Orion again for a duration between 8 and 21 days. The crew will perform tests and maneuvers as it orbits the Earth and the Moon. Once EM-1 and EM-2 have been completed, the Orion will start building the Gateway.</p><p>The Gateway will be “an all-in-one solar-powered communications hub, science laboratory, short-term habitation module, and holding area for rovers and other robots” in orbit around the Moon and will serve to support surface and orbital exploration. Currently, five companies have been asked to submit concepts for the Gateway.</p><p>While NASA is busy, SpaceX will be focusing on Mars, planning to reach the Red Planet by 2022 to create habitats for future colonists. During the first two years, the goal will be to find a reliable source of water. Then, in 2024, 40 brave humans will make the trip to Mars. This schedule seems highly optimistic. NASA is a bit more cautious and doesn’t see itself sending humans to Mars until the 2030s.</p><p>It’s almost impossible to predict what will happen after Earthlings land on Mars to colonize the planet but some organizations have built projections all the way to the 22nd century. Here’s what they see happening decade by decade:</p><p>2030s: More and more settlers and scientists land on Mars to study it, and to live and work there. More resources are extracted, greenhouses and a fish farm are built to provide food, and habitats grow. The first child is born and might never be able to go to Earth.</p><p>2040s: An orbital station is built. An artificial meat farm is built. The base station continues to grow and transport is built between it and mining stations including a hyperloop line. The first mission to Phobos and Deimos, Mars’ two moons, and the first attempt to climb Olympus Mons happen. A nuclear fusion power station is built.</p><p>2050s: The population continues to grow and more countries join the US and China on Mars creating their own bases. Large-scale domes are being built.</p><p>2060s: Nuclear fusion spaceships cut travel time between Earth and Mars bringing more colonist than ever before. The population explodes from 10,000 to more than 50,000 with 25,000 in Mars City alone.</p><p>2070s: Now that the colonies on Mars are well established and that a station exists on Phobos, humans can travel even further and the first mission leaves to explore the moons of Saturn. Population reaches 200,000 people.</p><p>2080s: Mars gets its own government. The price of visiting Mars drops and even middle-class people can afford it. Space elevators are built between the surface and Phobos. Population reaches 500,000 people.</p><p>2090s: The Phobos elevator is finished, tourism expands, and the planet gets its millionth inhabitant.</p><p>2100s: Mars becomes independent and self-sufficient. It also becomes a port for exploration further into space. Terraforming is progressing with water starting to flow on the surface and simple plants being able to survive. Framing expands and the population continues to grow to reach 30 million people.</p><p>Do you think it’s possible that this could happen in the next hundred years? Or is it all just a pipe dream? It will be fascinating to watch the small steps and giant leaps that humanity will take in your lifetime towards the ambitious goal of colonizing Mars!</p></section><section><h3>Mars Exploration Probabilities</h3><p>Mars Exploration Probabilities</p><p>You saw in the video that the path to Mars is starting to take shape.&#160;As space programs around the world and companies continue to develop technologies and build spacecraft, we get one step closer to reaching Mars every day.</p><p>NASA’s Exploration Missions</p><p>NASA is cautious in its approach to Mars, preferring to move towards it slowly.&#160;First, it has to finish building, with the help of its partners, the parts it needs for Exploration Mission-1 (EM-1) and Exploration Mission-2 (EM-2).&#160;EM-1 and EM-2 will use NASA’s new Space Launch System (SLS) to launch the new Orion capsule into outer space.</p><p>Watch the videos below to learn more about the missions.&#160;The first video is a refresher from earlier in the course.</p><p>Explorer 1 was launched on February 1958 at 3:48 a.m. UTC on a Juneau one rocket from launch complex 26 at Cape Canaveral, Florida. Its goal was t<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b18f43a424b84d2a2c2da471cda7a924','space-travel-and-solar-system-m5-l7-module-5-summary','a26b18dbe647d03720222905e4935a98','Module 5 Summary','text',12,'<h2>Module 5 Summary</h2><section><h3>Module 5 Summary</h3><p>Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module&#160;on the Mars Colony!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Discussed the historical evidence of the ability of Mars to sustain life.</p><p>Analyzed the current theories on colonizing Mars.</p><p>Identified the infrastructure required to provide transportation, supplies, and medical aid to a Mars Colony.</p><p>Identified the physiological requirements for those residing on a Mars Colony.</p><p>Constructed a timeline of colonization theories and future predictions around a successful Mars Colony.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('be067a9ecb94f9999aebdd92ffb4a6b3','space-travel-and-solar-system-m5-l8-module-5-assignament','a26b18dbe647d03720222905e4935a98','Module 5 Assignament','text',12,'<h2>Module 5 Assignament</h2><section><h3>Module 5 Assignment</h3><p>3300</p><p>Space Travel</p><p>Mars Colony - Short Answer Assignment</p><p>Short answer assignment</p><p>Based on what you’ve learned in this module, choose&#160;one&#160;of the following questions and answer it on a two-page, double-spaced paper, and explain your answers:</p><p>In this module, we discussed the technical challenges of getting to Mars but we also looked at the ethical issues around going in the first place. Using the sources in the modules, and any others you might find on your own, construct an argument based on the question &quot;should we go&quot;. Do you think that some people are using going to Mars as a way to avoid dealing with our problems here? Are we going to repeat our mistakes there? What if there is life on Mars, just not humanoid? Do their lives not count?</p><p>Imagine you did get chosen to go to Mars. Given what we know about the travel time and the need for Mars and Earth to line up, we know that the trip would be a minimum of 2 years. What would you need to be happy on this kind of mission? Are their things you know you&#39;d leave behind? What do you think you&#39;d miss the most? What kind of activities would you want to do while traveling to Mars? When answering this question, make sure you think about the weight and space restrictions on any space ship. You should also think about how long you&#39;ll be away. It may not make sense to take a thing that needs AA batteries or special food that could go bad.</p><p>Mars Colony Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b73eb05b292dfe78fe69288ee0881a6b','space-travel-and-solar-system-m5-l9-module-5-project','a26b18dbe647d03720222905e4935a98','Module 5 Project','text',12,'<h2>Module 5 Project</h2><section><h3>Module 5 Project</h3><p>3300</p><p>Space Travel</p><p>Mars Colony - Project</p><p>Project</p><p>For this project, you are a marketing director at an ad agency. Your client, an environmental group, has come to you with a big concern. They are worried about humankind’s potential impact on Mars if we start setting up colonies on Mars. They worry that human’s will negatively impact the natural state of Mars by changing the atmosphere or terraforming the red planet. They have asked you to create a large one-page ad to run in the New York Times outlining the dangers of a Mars Colony, both for humans and for nature.</p><p>Your advertisement should:</p><p>Be aimed at a specific target audience (Space Travel professionals or the general public)</p><p>Describe the problem</p><p>Highlight the risks</p><p>Persuade the audience</p><p>Address common concerns</p><p>Be creative, engaging, and appropriate for the audience</p><p>Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Content</p><p>8 points The advertisement demonstrates a strong understanding of the technology involved with the Space Travel product and the problem it is addressing. It contains several specific and accurate details.</p><p>7-6 points The advertisement demonstrates a satisfactory understanding of the technology involved with the Space Travel product and the problem it is addressing. It contains some specific and accurate details.</p><p>5-0 points The commercial demonstrates little to no understanding of the technology involved with the Space Travel product and the problem it is addressing. It contains few to no specific and accurate details.</p><p>8</p><p>Persuasive</p><p>6 points The advertisement effectively explains the benefits of the product and is effectively aimed at a target audience.</p><p>5 points The advertisement adequately explains the benefits of the product and is sufficiently aimed at a target audience.</p><p>4-0 points The advertisement does not adequately explain the benefits of the product and is not effectively aimed at a target audience.</p><p>6</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Presentation</p><p>2 points The advertisement is well organized and presented in an engaging way.</p><p>1 point The advertisement is somewhat organized and is presented in a slightly engaging way.</p><p>0 points The advertisement is not organized well or is not presented in an engaging way.</p><p>2</p><p>Visual/Audio Appeal</p><p>2 points Uses appropriate visuals or audio in an engaging way</p><p>1 point Uses appropriate visuals or audio in a satisfactory way</p><p>0 points Uses inappropriate visuals or audio.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('dd876d0a061c47a2e0eaafeaaa80d7f8','space-travel-and-solar-system-m5-l10-module-5-quiz','a26b18dbe647d03720222905e4935a98','Module 5 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Mars 5 Colony. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('52fc894074bcaf0c52f3f0c69eefdbdf','space-travel-and-solar-system-module-6','2a892040eda1f32ee69b17d25aad96dd','Module 6: Asteroid Mining',6) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8ff61f01c6d74d40d41c25853e07dac0','space-travel-and-solar-system-m6-l1-introduction-purpose-and-objectives','52fc894074bcaf0c52f3f0c69eefdbdf','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi everyone, welcome back. This is the intro video for the module on Asteroid Mining.</p><p>Have you seen the 1998 movie, Armageddon? In the movie, an asteroid the size of Texas is heading toward Earth-threatening life on the planet. NASA discovers the problem when the Space Shuttle Atlantis is hit and destroyed by a shower of meteors. They decide the only way to save Earth is to send a rag-tag oil exploration crew (led by Bruce Willis and Ben Affleck) to land on the asteroid, drill holes, and plant a thermonuclear device. The theory is that it will split the asteroid in two and send each section past the planet.</p><p>Sounds crazy, right? Well, not entirely. NASA has catalogued more than 18,000 Near-Earth Objects (NEOs) with about 900-1,000 that have a diameter larger than that of one kilometer (0.6 miles). Many of them could someday hit Earth. Protecting our planet is just one of the reasons that make asteroids worth studying.</p><p>In this module, we’ll see how asteroids can also tell us a lot about our evolution because they were formed at the same time the planets in our solar system were formed. We’ll learn more about what these celestial bodies are made of and see how scientists can make connections between samples of asteroids fallen to Earth, called meteorites, and those collected through space missions.</p><p>The composition of asteroids is another aspect we’ll explore in this module because there’s a lot of talk about potentially mining them, because many are believed to contain elements that are rare on Earth like Helium-3 and platinum for example. Asteroids are also seen as possible refueling stations for space travelers since many of them contain ice water that could be harvested along the way.</p><p>So, get ready to learn all about asteroids!</p><p>Module Description</p><p>by Sergey Nivens</p><p>License:&#160;All Rights Reserved</p><p>Planets, moons, and stars were once the only celestial bodies we heard about.&#160;But not anymore!&#160;Asteroids have found their way to the top of the topic pile.&#160;Here’s why.</p><p>Considering our solar system has millions of asteroids, it’s surprising they didn’t get more attention until recently.&#160;Several factors have contributed to changing that.&#160;First, asteroids contain a lot of history.&#160;They were formed at the same time as the planets in our solar system and many asteroid fragments, called meteorites, have fallen to Earth where they can be examined.</p><p>A second important factor is the protection of our planet.&#160;Tracking existing asteroids is vital to ensure that we have an advanced warning if one is on a collision course with Earth.&#160;NASA, among others, is designing possible solutions to deflect or destroy asteroids which could hit Earth.</p><p>Finally, this module discusses the concept of asteroid mining, its economic benefits, and perceived cost.&#160;Students will learn about the leaders in the asteroid mining thought industry, how asteroid mining will be done, and identify both technical and legal barriers to its inception.</p><p>Objectives</p><p>In this module, students will</p><p>Discuss the formation of asteroids and present their different types and locations.</p><p>Understand the economic benefits to asteroid mining including perceived cost and value.</p><p>Identify the leaders in the asteroid mining industry and describe their potential role in future asteroid mining.</p><p>Describe the current theories on the process of asteroid mining.</p><p>Discuss the legal and ethical challenges presented in asteroid mining.</p><p>Polling Question</p><p>When you think of asteroids, do you see them as .&#160;.&#160;.</p><p>chunks of rock, tumbling through space&#160;potential resources</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>The largest cluster of asteroids that orbits the Sun located between Mars and Jupiter.</p><p>Mond process</p><p>An instrument used to detect the presence of elements of the periodic table.</p><p>Helium-3</p><p>A gas that could be used in the future to fuel non-radioactive power plants and it’s very rare on Earth.</p><p>Gamma-ray spectrometer</p><p>A technique used to separate nickel from other metals like iron and cobalt.</p><p>Asteroid belt</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>The largest cluster of asteroids that orbits the Sun located between Mars and Jupiter.</p><p>Mond process</p><p>Gamma-ray spectrometer</p><p>Helium-3</p><p>Asteroid belt</p><p>2.</p><p>An instrument used to detect the presence of elements of the periodic table.</p><p>Mond process</p><p>Asteroid belt</p><p>Gamma-ray spectrometer</p><p>Helium-3</p><p>3.</p><p>A gas that could be used in the future to fuel non-radioactive power plants and it’s very rare on Earth.</p><p>Asteroid belt</p><p>Helium-3</p><p>Gamma-ray spectrometer</p><p>Mond process</p><p>4.</p><p>A technique used to separate nickel from other metals like iron and cobalt.</p><p>Gamma-ray spectrometer</p><p>Asteroid belt</p><p>Helium-3</p><p>Mond process</p><p>Asteroids that come close to Earth and even cross its orbital path.</p><p>Spectrographic analysis</p><p>Based on the knowledge that objects reflect the light of a certain color.&#160;For example, a reddish reflection usually means that the object is probably rich in iron and nickel, at least on the surface.</p><p>Greeks</p><p>Asteroids that share an orbit with a planet.&#160;These ones are in front of a planet.</p><p>Near-Earth asteroids</p><p>Asteroids that share an orbit with a planet.&#160;These are the ones trailing a planet.</p><p>Trojans</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Asteroids that come close to Earth and even cross its orbital path.</p><p>Spectrographic analysis</p><p>Trojans</p><p>Near-Earth asteroids</p><p>Greeks</p><p>2.</p><p>Based on the knowledge that objects reflect the light of a certain color. For example, a reddish reflection usually means that the object is probably rich in iron and nickel, at least on the surface.</p><p>Trojans</p><p>Spectrographic analysis</p><p>Near-Earth asteroids</p><p>Greeks</p><p>3.</p><p>Asteroids that share an orbit with a planet. These ones are in front of a planet<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c331621e65c4f0a3630162bad721a3c0','space-travel-and-solar-system-m6-l2-lesson-1','52fc894074bcaf0c52f3f0c69eefdbdf','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Asteroid Mateor Dwarf Planet</h3><p>Asteroid, Meteor and Dwarf Planet</p><p>Do you know the difference between an asteroid, a meteor and a dwarf planet?</p><p>Hi and welcome to Video 1 for this module on Asteroid Mining.</p><p>We hear a lot about the danger of asteroids hitting Earth but very little about where they come from and what they are. Considering there are millions of them floating around in our solar system, it might be a good idea to learn a little more about them.</p><p>An asteroid is essentially a chunk of rock and dust. It can be as small as a car or as big as Ceres. With a diameter of approximately 587 miles, Ceres is so big, it’s been given the designation of a minor or dwarf planet. The second largest asteroid in our solar system is Vesta with a diameter of around 329 miles.</p><p>You’ve probably heard of asteroids, meteoroids, meteors, meteorites and even comets but what’s the difference? Well, let me tell you.</p><p>- An asteroid is a rocky space object that orbits the Sun.</p><p>- A meteoroid is a small piece of an asteroid that broke loose. This can happen when asteroids hit each other.</p><p>- A meteor is a meteoroid that enters the Earth’s atmosphere and, as it gets vaporized, it creates a streak of light in the sky, also called a shooting star.</p><p>- A meteorite is a meteor that wasn’t vaporized when it crossed the Earth’s atmosphere and landed on the surface.</p><p>- A comet is another type of body that orbits the Sun but is made of ice and dust instead of rock. As it travels, it vaporizes, which creates a tail.</p><p>What we know about asteroids comes mainly from meteorites and from a handful of missions that have flown by, observed and landed on the rocky bodies. NASA’s Galileo for example, orbited Jupiter for almost eight years in the 1990s and sent images of the asteroids Gaspra, Ida, and Dactyl.</p><p>Another NASA probe, the NEAR Shoemaker, launched in 1997, was the first mission to land on an asteroid successfully. NEAR sent photographs of asteroid 253 Mathilde on its way to another asteroid, Eros. It collected 160,000 images and eventually landed on Eros in 2001. There, it was able to use a gamma-ray spectrometer, which is an instrument used to detect the presence of elements of the periodic table. It found that the asteroid’s chemical composition was similar to meteorite samples collected on Earth.</p><p>Japan has also been testing technology to land on asteroids. In 2005, the Japanese Aerospace Exploration Agency (JAXA) landed the spacecraft Hayabusa on the asteroid Itokawa. The spacecraft returned to Earth in 2010 with a small sample of dust. It was the first spacecraft ever to land and take off successfully from the surface of an asteroid.</p><p>In 2018, Japan’s Hayabusa2 successfully landed two hopping rovers called MINERVA-II1A and MINERVA-II1B, on the Ryugu asteroid, located between Venus and Mars, where they’ve been taking photos. It was the first successful landing of roving robots on an asteroid. The Hayabusa2 also dropped another lander, this one a joint German and French mission, a few weeks later.</p><p>The Dawn spacecraft, launched by NASA in 2007, was able to study the two largest asteroids, Ceres and Vesta, over an eleven-year period. It found that Vesta has a dry surface that’s similar to the rocky surface of Earth and its gravity seems to indicate that it has an iron core. Ceres is similar to icy moons like Europa and seems to have a lot of water ice under its surface accounting for 25% of its total mass.</p><p>The latest research mission, NASA’s OSIRIS-Rex, arrived at the asteroid Bennu in December 2018. It will spend two years studying the asteroid, focusing on its trajectory, and collecting samples before returning to Earth in 2023. Already, the probe has detected water locked inside the clay indicating that water existed on the surface of Bennu at some point.</p><p>Ever heard of the asteroid belt? It’s the largest cluster of asteroids that orbits the Sun. It’s located between Mars and Jupiter. According to NASA, it contains between 1.1 and 1.9 million asteroids with a diameter larger than 1 kilometer (0.6 miles).</p><p>Some asteroids are called near-Earth asteroids because they come close to Earth with some even crossing the planet’s orbital path. As of 2016, NASA had found 14,464 near-Earth asteroids and kept a close eye on them to make sure they don&#39;t pose a threat.</p><p>Other asteroids share the same orbit as planets. They’re called trojans or, in the case of Jupiter, trojans and greeks because the very large planet has so many. Greeks precede Jupiter on the orbital path and trojans follow it. The Earth has a trojan named 2016 HO3, a small asteroid with a diameter between 120 and 300 feet. NASA plans to launch the probe Lucy in 2021, specifically to study seven Jupiter trojans and greeks.</p><p>But where do they come from? You’ve already seen in this course that our solar system formed about 4.6 billion years ago. We talked about the formation of the Earth and Mars, which grew out of debris that got fused together. Well, asteroids are leftover parts. They never got the chance to be included into a planet so, they just collected together to form the belt or got pulled into the gravity of planets.</p><p>Just like planets, asteroids are made mainly of rocks and dust. NASA classifies asteroids into one of three categories:</p><p>- The most common asteroids are the C-type (chondrite). Dark in appearance, they’re among the most ancient objects in the solar system. Scientists think they probably contain clay and silicate rocks.</p><p>- S-type (&quot;stony&quot;) asteroids are made up of silicate materials and nickel-iron.</p><p>- Finally, M-type asteroids contain metals (nickel-iron). The composition can vary depending on how far from the Sun the asteroid was when it formed. The closer it was, the hotter it would have been and they would have melted partially with their iron content sinking to the center forcing volcanic lava to the surface.</p><p>Asteroids are difficult to measure and study because most of them have irregular shapes and, as they rotate around the Sun, they also tumble at high speed. The growing interest in them comes from the fact that they might contain different kinds of metal, some of them rare, that some believe could be mined and returned to Earth. In the next two sections, we’ll have a closer look at the concept of asteroid mining.</p></section><section><h3>Asteriod Naming Converntion<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('841adb93c0031458ee49cb68917847e3','space-travel-and-solar-system-m6-l3-lesson-2','52fc894074bcaf0c52f3f0c69eefdbdf','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Methods for Asteroid Mining</h3><p>Methods for Asteroid Mining</p><p>Asteroid mining… can you imagine how it could be done?&#160;Do you think there’s a future in it?</p><p>Welcome back, this is Video 2 of this module on Asteroid Mining.</p><p>Even though this is a course about space travel, we often have to talk about economics, because it costs so much to develop the technology to send spacecraft into space. So, in this section, you’re going to learn a little bit about economics so you can evaluate the benefits of mining asteroids.</p><p>Don’t worry, you won’t have to learn about micro and macro-economics, or how to calculate the cost of living. Our adventure into economics will be limited to understanding the perceived cost and value of asteroid mining.</p><p>First ask yourself this question: Why do you think gold and platinum are expensive? If you said because they’re rare, you get 10 points! It’s true that the rarer something is, the higher its value. Proponents of asteroid mining argue that many different resources found in space are very rare on Earth.</p><p>We’re hearing a lot of predictions about the value of precious metals and rare resources coming from outer space. For example, an ounce of Helium-3 could be worth $40,000, making it 33 times more valuable than gold. Helium-3 is a gas that could be used in the future to fuel non-radioactive, clean power plants and it’s very rare on Earth.</p><p>Considering the rarity of some of the resources that are believed to be available on asteroids, it could make sense from an economic point of view to go mine them. But the value of these minerals has to be put against the cost of getting them. That’s another important principle in economics: cost vs return.</p><p>Imagine you want to make lemonade. You obviously have to go buy lemons. Let’s say you buy $20 worth of lemons and a bag of sugar for $5. After you add water, you get 50 glasses. You charge $2 per glass. So, your cost is $20 + $5= $25 and your return is 50 glasses X $2 = $100. Your profit then will be $100 - $25 = $75. In this case, it was worth it to make lemonade.</p><p>But that was an easy-ish example. You know how much sugar and lemons cost, and how many glasses you’d get from those inputs. And you have a good idea of how much you could charge. With asteroid mining, things like costs and how much you could make are all up in the air! It’s all educated guesses, called assumptions. You can’t just put a value on all the possible resources you’ll find on asteroids. You also have to consider the technology that will need to be developed.</p><p>Imagine you’ve been given the task of coming up with a short list of asteroids that are good candidates for mining. How would you go about it?</p><p>You could start with a technology that already exists. It’s called spectrographic analysis. Basically, we know that certain things reflect light, so if we shine a light on an asteroid and it looks reddish, it’s probably rich in iron and nickel, at least on the surface. We also know from experience here on Earth, that the presence of iron and nickel usually means that platinum is also present. Considering an ounce of platinum is worth $800, finding an asteroid that contains it could make it an exciting prospect.</p><p>But a high concentration of a resource isn&#39;t the only factor to consider. Remember the lemonade stand? We saw that in the best-case scenario, you’d make $75 profit. But what if you don’t sell enough and you end up being stuck with a lot of extra lemonade? Or what if you put up signs all over the neighborhood and you run out? Evaluating the potential of asteroids has to include other factors as well. Here are a few of them:</p><p>How far is it? In earlier modules, we talked about the time and cost involved in space travel. If the asteroid is far away, then it has to be even more worth it. Think of it like this: if you&#39;re walking along the street and you see a $10 bill lying on the ground, just there on the sidewalk ready to be picked up. All you have to do is bend over. But the same $10 bill trapped in a sewer drain would require that you lift the big, heavy grate. Suddenly that $10 is a lot of work.</p><p>How fast is it moving? Let&#39;s go back to that $10 bill again. If it&#39;s just sitting there on the sidewalk, then you&#39;ll pick it up no problem. But what if it’s stuck to the back of a bus? In the same way, landing on an asteroid that’s going relatively slow is a lot easier than landing on a fast one. Professor Martin Elvis, an astrophysicist at Harvard University says that to make it worth mining, an asteroid has to be going at less than 4.5 kilometers per hour (about 2.8 miles an hour).</p><p>How big is it? Back to our $10 bill. You might not go after a $10 bill if it was stuck to a bus or down a sewer drain, but what if it was a $100-dollar bill? The same decision process holds for asteroids. Unless there’s enough mineral to mine, the trip might not be worth it. Professor Elvis calculated that asteroids need to be larger than 1 kilometer (about.62 of a mile) in diameter to be worth the trouble.</p><p>How many resources are there? Think about the sewer drain again; $10 is probably not enough to convince you to get your hands dirty. A $100 bill might make you hesitate. But what if you looked into a really nasty looking sewer and saw a whole fat stack of $100 bills? You&#39;d probably run off to find a pry bar as fast as you could. Professor Elvis figures 10 parts per million of platinum would make the trip worth it. In fact, his calculations say that for a mining trip to be worth the time and the effort, the payday would have to be around $1 billion dollars.</p><p>We still don’t really have the tools to evaluate what&#39;s up there with any kind of accuracy yet. First, we need to make surveying probes that return to Earth with samples, but Professor Elvis estimates that of the 17,000 near-Earth asteroids, only about 10 should make the short list of candidates.</p><p>So space mining, just like your lemonade stand, or picking up that $10 dollar bill, has to be worth it.</p></section><section><h3>Asteroid Mining Technologies and Processes</h3><p>Asteroid Mining Technologies and Processes</p><p>Asteroid capture-plan B&#160;by NASA</p><p>License:&#160;Public Domain</p><p>In the video, we talked about the money side of asteroid mining, but what about the &quot;how&quot;?&#160;Let&#39;s look at some of the plans that are being developed.</p><p>Catch a<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('22c7a36e06adea9156671e3975367678','space-travel-and-solar-system-m6-l4-lesson-3','52fc894074bcaf0c52f3f0c69eefdbdf','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Asteroids Mining Minerals and Mining Companies</h3><p>Asteroids Minerals and Space Mining Companies</p><p>Select a Student</p><p>More than one person has said that the first trillionaires will be made in space.&#160;Do you think that’s possible in your lifetime?</p><p>Welcome back, this is Video 3 of this module on Asteroid Mining.</p><p>Once you know that some asteroids might contain rare metals like plutonium and that a football field-sized asteroid might be worth $2.5 billion dollars, you can understand why companies are interested in going to space. Let’s have a look at the main players in the asteroid mining industry.</p><p>One of the most active asteroid mining companies is US-based Planetary Resources. They’re focused on the following projects:</p><p>They want to locate and collect water, which will be used to produce fuel and supply deep space missions.</p><p>They want to mine and collect &quot;structural&quot; resources to build structures in space. Because it would be outside of the Earth&#39;s gravitational pull, and would not require extremely expensive rockets launching into space, theoretically this would both cut the cost of construction and it would mean that structures (like gigantic orbiting space habitats) of any size could be built.</p><p>They want to mine precious metals to manufacture high-end electronics, laboratory equipment and spacecraft components in space.</p><p>To date they have launched two small test satellites and are planning larger, deep space versions soon.</p><p>Another important player is the UK’s Asteroid Mining Company. Their focus is on identifying suitable asteroids and then, mining them. They have a first satellite going up in 2020, with another test going up 2023 and aim to have their first mining probe going up in 2028.</p><p>They’re focusing on two approaches:</p><p>Mining resources and returning them to Earth. They want to recover 20 tons of Platinum Group Metals on their first mining mission using their Asteroid Mining Probe One, which is a two-piece lander that separates, with one part staying on the asteroid and the other flying home to Earth.</p><p>Mining resources to use them in space for manufacturing.</p><p>Contrary to the other players mentioned, Bradford Space, with locations in Sweden, Holland, Luxembourg and the USA, already has experience making parts for space ships and satellites. In fact, some of their products went into space as part of the Space Shuttle program.</p><p>It’s also now gearing up to mine in space. Bradford is focusing on providing some of the infrastructures for deep space work. Their water-based propulsion system is a perfect match for mining water from asteroids.</p><p>Japan has been an important player in the field of asteroid research, landing several spacecraft and rovers in the last 15 years. So, it&#39;s no surprise that a Japanese company, iSpace, is also interested in asteroid mining. The company is working on the development of a tiny (under 4kg) robot rover that will be cheap to launch, because of its size, and capable of harvesting resources on the Moon.</p><p>They plan to have a lander and rover combo on the Moon by 2021, with a goal of having an industrial platform to ensure regular shipments back to Earth by 2023.</p><p>When you think about space exploration powerhouses, you’re probably not thinking about Luxembourg, a tiny European country (about 1,000 square miles) with a population of about 600,000 people. That&#39;s about three times the size of New York City and about 14 times fewer people.</p><p>But never underestimate Luxembourg! It’s one of the biggest governmental players in the space mining industry. So, how did a tiny, landlocked country in the middle of Europe get to be a big player in the future of space mining? Tax breaks and funding. Luxembourg’s government has set aside $223 million to fund research into space mining and has been giving tax breaks to companies willing to set up their offices there. In 2016, the government bought a share of Planetary Resources for $28 million.</p><p>They’re also pioneers when it comes to the law ruling asteroid mining. In 2017, Luxembourg was the first European country to pass a space mining law stating that no one can own an asteroid but that they can own all the resources they’re able to extract from it. The USA has similar laws, but hasn&#39;t done much in the way of trying to kick start this industry.</p><p>To say that the asteroid mining industry is in its early days would be a meteor-sized understatement! It’s so early that many careers, opportunities, and possibilities haven’t even been thought up yet. While there are some early pioneers, it will take brilliant minds, daring explorers, and innovative engineers to work out all the details. But the monetary prize is unfathomable. The bank Goldman Sachs predicted that asteroid mining will make the world’s first trillionaire. Additionally, there’s much to be done by mining experts, geologists, physicists, technicians, and a host of other career fields to pursue. Today’s students will have the chance to shape the technology and opportunity for this trillion-dollar asteroid mining industry.</p></section><section><h3>Space Private Companies</h3><p>Space Private Companies</p><p>Select a Student</p><p>Knowing these companies exist is one thing, but in this reading, let’s dig a bit deeper and learn more about them.&#160;Expand each section below to learn about what each company is doing.</p><p>SpaceX</p><p>SpaceX, founded by Elon Musk in 2002, has quickly become a prominent player in the space industry. They have developed the Falcon 9 rocket and Dragon spacecraft, which have been used for numerous launches to the International Space Station (ISS) under NASA&#39;s Commercial Crew Program. SpaceX is currently focused on developing the Starship, a fully reusable spacecraft intended for crewed missions to the Moon, Mars, and beyond. They are also working on the Starlink satellite constellation, a project aimed at providing global broadband internet coverage.</p><p>Blue Origin</p><p>Blue Origin, founded by Jeff Bezos in 2000, is dedicated to advancing space technology and making space more accessible. They have developed the New Shepard suborbital rocket, designed for human space tourism and scientific research. Blue Origin is also working on the New Glenn rocket, a reusable launch vehicle intended for orbital missions. They have plans for lunar lander development in support of NASA&#<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('69c536be515159b37aa1ded7462c38f6','space-travel-and-solar-system-m6-l5-lesson-4','52fc894074bcaf0c52f3f0c69eefdbdf','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Process of Finding Asteroids with Minerals</h3><p>Process of Finding Asteroids with Minerals</p><p>Select a Student</p><p>You now know there could be some benefits to asteroid mining and you know who might be the leaders going forward but we haven’t talked yet about the process of finding the minerals in the first place.&#160;How do we know what an asteroid is made out of without actually analyzing its soil and rocks?</p><p>Welcome back, this is Video 4 of this module on Asteroid Mining.</p><p>So, you want to find an asteroid that&#39;s worth something? Where do you start? Well, first you have to find a Near Earth Object, or NEO (which is a fancy science way of saying &quot;you have to find an asteroid&quot;). For the most part, this is done with Earth-based telescopes. The best of the current crop is Catalina Sky Survey (CSS) near Tucson, Arizona.</p><p>Once you find a suitably-sized and located asteroid, the next step is to work out what it&#39;s made of, and if it&#39;s worth mining. At present, the best way to do this is through high-sensitivity spectral imaging which will enable scientists to discover the presence of water and the carbon make-up of the asteroid, which would indicate whether it was worth mining or not. Telescopes like the Hubble can do this.</p><p>In terms of size, you would have to use measuring equipment, which would also be used to establish the trajectory of the asteroid. Finally, establishing the mass of the asteroid can be done via observations of how the asteroid interacts with other celestial bodies it passes and how it reacts to radiation.</p><p>Most of these calculations are aimed at locating asteroids that can be moved into low Earth orbit for mining. There are two basic sizes and types of asteroids you can target with two techniques. The first technique is referred to as &quot;Get A Whole One” by some scientists. This is the approach that would be used if the target asteroid was small enough, so you could grab the whole thing with a space ship and move it to orbit. The second approach, which would be used if the target asteroid was too large, is sometimes called the Pick Up A Rock approach. In this case, a 7-meter square piece of the asteroid would be cut off, and then returned to Earth orbit to be mined.</p><p>Once you find an asteroid that contains something of value, how do you actually go about extracting it? The techniques that have been proposed are based on the mining experience on Earth. Here are five possibilities:</p><p>Scraping it off. Experts think that many asteroids are covered with debris. In that case, a piece of equipment that can scoop or scrape the surface could be used for mining.</p><p>Dig deep. But what if the minerals are not on the surface? If equipment can be designed to pinpoint the location of minerals accurately, a shaft could potentially be drilled to mine them. The greatest difficulty would be creating a device that can collect the minerals and bring them to the surface.</p><p>Attract it. In the case of asteroids with a high metal composition, a powerful magnet could be used to collect minerals.</p><p>Heat it up. C-type asteroids contain materials, such as water, that could be released when heated. This would be really useful for space travel.</p><p>The Mond process. Asteroids with a high level of nickel could be mined using the Mond process, which is a technique used to separate nickel from other metals like iron and cobalt.</p><p>We know very little about asteroid mining, but we know even less about its impact. Asteroids are celestial bodies that move in space. Some orbit around the Sun while others are knocked off course and spin through space. Whatever their trajectory, removing part of their mass through mining could influence where they go once mining is done. The other way we could impact the movement of asteroids is by landing a mining vehicle on its surface. While a tiny rover and lander are probably not going to be that big a deal, what of a larger, Curiosity-sized vehicle being landed at high speed? An asteroid with a safe trajectory could suddenly be turned into a space-borne missile headed right for Earth. Remember, several of the attempts to land probes on Mars resulted in spectacular crashes.</p><p>Finally, as we&#39;ve seen, one of the other theories being studied involves putting the asteroid, or part of it, in low earth orbit around Earth. While this sounds reasonable, it raises several possibilities and questions. Firstly, does the depleted Asteroid just stay in orbit? Because, given how much space junk and dead satellites are already up there this could be an issue. Or does it de-orbit and enter the Earth&#39;s atmosphere and burn up? If that&#39;s the case, how safe will that be? Will we get a light show or will parts of the planet be hit with the equivalent of a space shotgun blast? These are all questions we&#39;ll have to answer no matter which technique we use.</p></section><section><h3>Asteroids Mining Techniques</h3><p>Asteroids Mining Techniques</p><p>Select a Student</p><p>One of the problems we have when discussing mining techniques is that we really don&#39;t know what will work and what will be affordable until it&#39;s tried.&#160;Right now, the majority of the asteroid and space mining techniques are really just theoretical.&#160;So, will picking up the dust be good enough?&#160;Will we have to dig holes?&#160;No one really knows.</p><p>With the Power of the Sun</p><p>One of the most promising by-products of asteroid mining is fuel for deeper space exploration.&#160;One process that is being examined is called Optical Mining.&#160;This process uses the power of the sun, focused by various devices, to heat up an asteroid and then capture the vapors that it releases and stores them as fuel for satellites or other spacecraft.&#160;One of the main companies that is looking at this is TransAstra.</p><p>As we continue to go forward and learn even more about the opportunities, let&#39;s take a look at the history of asteroid mining.</p><p>Human beings consume resources. They alter their environment so they can reproduce. It&#39;s a very definition of biological life. The problem is we&#39;re running out of room, we&#39;re running out of resources, and now we&#39;re running out of time, so we need a plan. There&#39;s a lot of different resources in space that we are interested in, and we have already found some perspective asteroids that could be mine. What you&#39;re doing as <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('111b8f3e88cd745336e2d6c139debeaf','space-travel-and-solar-system-m6-l6-lesson-5','52fc894074bcaf0c52f3f0c69eefdbdf','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Space Minerals Market</h3><p>Space Minerals Market</p><p>Select a Student</p><p>While watching the video below, think about the following:&#160;If you could, would you buy an asteroid to mine it?</p><p>Welcome back, this is Video 5 of this module on Asteroid Mining.</p><p>You might be wondering how you would even go about buying an asteroid? The simple answer is you can’t legally own an asteroid. The United Nations adopted The Outer Space Treaty in 1967, to set some guidelines around space exploration. The main goal of the treaty was to protect human life and the scientific evidence of life on other planets, but it also says that countries can’t own things outside of Earth.</p><p>Of course, you’d be right to think that things were very different back in 1967 and no one could imagine how fast our technology would develop. So, countries, including the US, have started looking for loopholes. In 2015, Congress passed the US Commercial Space Launch Competitiveness Act, also called the Space Act, which allows American companies to keep the materials they mine from bodies in space, without having to own them. The argument is that space is like international waters on Earth. Without owning the water, companies and countries can fish in international waters and keep what they get. This is a precedent many other countries are following.</p><p>Another wrinkle in spacing mining is that since no person can own an asteroid, no government is able to claim jurisdiction over them. So, how are things taxed? It might be straightforward for things that are mined in space and then refined and turned into goods here on Earth. In that case, the government could charge import duties, and clearly they can tax profits and the sales of the finished goods. Can you imagine the presidential debate in 2040, where the candidates argue about the size of the space import tax?</p><p>But what about things manufactured in space which never come back to Earth? How does sales tax work at a space-based gas station? No easy answers there…</p><p>Even if it is legal to mine asteroids or other celestial bodies like the Moon and Mars, should we do it? Here are a few questions for you to think about:</p><p>- If we disrupt outer space, don’t we destroy our chances of ever finding how humanity began?</p><p>- Shouldn’t space benefit all of humanity, not just already rich companies?</p><p>- How can we control and hold accountable what companies do out there?</p><p>- If we look at how some companies pollute and destroy the environment here on Earth, how can we trust them not to do the same in space?</p><p>- Could space mining lead to conflicts, possibly armed conflicts?</p><p>Combine this with the legal front, where the situation we see developing is that some countries, the USA and Luxembourg, for instance, are ignoring international law and customs. They are allowing corporate interests to decide what is best for all of humanity in this arena. We may be in for a bumpy legal and philosophical ride before the first mining trip even starts!</p><p>So, if we&#39;re going into space with profit as our motive and not science, who&#39;s going to get rich? The answer to that, unsurprisingly, is &quot;the usual suspects&quot;. Sure, some of the tech people who design the rockets, robots, space gas stations and mining techniques will get rich, and the people who refine the resources probably will as well. But the real winners will be people who are, by any measure, already well off.</p><p>The costs to get to asteroids, the costs to mine and refine, all are very high, so surely if a person risks their money they should get rewarded? Well, think back to the issue of taxation we discussed early in the video. With no taxation to try and better society and no requirement to return samples to scientists, even that part of the Outer Space Treaty is now moot. Furthermore, without regulations, with no rules about how to mine, how to dispose of waste or asteroids once they are depleted, for-profit companies will be heading off into the void to do whatever they want. Think of mining disasters here on Earth, or of some of the pollution associated with resource extraction, be it oil, mining or even lumber. Now imagine this taking place in deep space, far from prying eyes, or, perhaps worse, right above our heads in low earth orbit.</p><p>Hopefully this module has got you thinking about the pros, cons, and potential of asteroid mining. For most of you, it may not have even crossed your radar yet! But if we as humanity are to achieve some of the other audacious goals in space travel, being able to safely and profitably mine asteroids is going to be a massive stepping stone.</p></section><section><h3>Space Minerals Regulations and Risks</h3><p>Space Minerals Regulations and Risks</p><p>Select a Student</p><p>So, space for all humankind, versus space for profit for a select few already rich people?&#160;Privatized profit and socialized risk or cheaper prices on rare materials and an endless supply of rocket fuel?&#160;With asteroid mining in its infancy what comes next is critical for both the future of space travel and exploration and, potentially for both Earth&#39;s economy and our galaxy&#39;s environmental health.</p><p>Wild, Wild West</p><p>The issue is that unregulated resource extraction has always led to environmental blowback and cleanup nightmares.&#160;In fact, the same can be said of regulated resource extraction.&#160;The fear is that, with no laws, or with some countries ignoring international laws, space will wind up being owned by individuals or the companies they control.</p><p>The Frozen Path</p><p>One of the places that might provide an example of how space could work might be found right here on Earth.&#160;Antarctica is one of the four &quot;commons&quot; identified under international law.&#160;A common, in this usage, is a place &quot;outside the territory of nation states and beyond the normative inhabitable zones of the human species&quot;.&#160;The others are space, the atmosphere, and the high seas.&#160;So the idea is that in these areas no one government is in charge.</p><p>All the Issues</p><p>As a final reading for this section, it might be good to do an overview of all the issues surrounding the commercialization and mining of space.&#160;Considering the ethical and legal issues is important, but there are also so philosophical ones to consider as well.&#160;Think about all the space invasion movies or TV sh<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9608d87d7bcb7377b1bdb2907203af81','space-travel-and-solar-system-m6-l7-module-6-summary','52fc894074bcaf0c52f3f0c69eefdbdf','Module 6 Summary','text',12,'<h2>Module 6 Summary</h2><section><h3>Module 6 Summary</h3><p>Summary</p><p>Select a Student</p><p>asteroid icon</p><p>License: All Rights Reserved</p><p>Great Work! You have successfully completed this module on Asteroid Mining!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies. Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Discussed the formation of asteroids and presented their different types and locations.</p><p>Understood the economic benefits to asteroid mining including perceived cost and value.</p><p>Identified the leaders in the asteroid mining industry and described their potential role in future asteroid mining.</p><p>Described the current theories on the process of asteroid mining.</p><p>Discussed the legal and ethical challenges presented in asteroid mining.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7893f2537d98b0a236b6e19f7d718134','space-travel-and-solar-system-m6-l8-module-6-assignment','52fc894074bcaf0c52f3f0c69eefdbdf','Module 6 Assignment','text',12,'<h2>Module 6 Assignment</h2><section><h3>Module 6 Assignment</h3><p>3300</p><p>Space Travel</p><p>Asteroid Mining - Short Answer Assignment</p><p>Short answer assignment</p><p>Based on what you’ve learned in this module, choose&#160;one&#160;of the following questions and answer it on a two-page, double-spaced paper, and explain your answers:</p><p>Do you trust companies to be “good citizens” in space? Do you think we should let them mine asteroids? Explain your position.</p><p>Do you think we should set stricter guidelines for what companies do in space? What would you suggest? If you don&#39;t think there need to be more regulations, please explain your position as well.</p><p>Wii, Kinect and Active Gaming Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4bf9814e0e924ab240ea3beb358f7c3b','space-travel-and-solar-system-m6-l9-module-6-project','52fc894074bcaf0c52f3f0c69eefdbdf','Module 6 Project','text',12,'<h2>Module 6 Project</h2><section><h3>Module 6 Project</h3><p>3300</p><p>Space Travel</p><p>Asteroid Mining - Project</p><p>Project</p><p>You are the owner of an asteroid mining company and need to hire people to be part of your team. Create a job posting with the following sections:</p><p>Company Description (this is YOUR company, so it should reflect your values and how you feel you want your company to operate)</p><p>Job Title</p><p>Position Summary</p><p>Ideal Candidate Traits</p><p>Minimum Qualifications</p><p>Risks involved</p><p>Potential rewards</p><p>Use the information in this module as well as your own research about requirements for particular jobs.</p><p>Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Content</p><p>8 points The job posting demonstrates a strong understanding of the position. Use of information from the module and additional research is used throughout the job posting.</p><p>7-6 points The job posting demonstrates a satisfactory understanding of the position. Some use of information from the module and additional research is used in the job posting.</p><p>5-0 points The job posting demonstrates little to no understanding of the position. Few to no examples from the module or external research is present in the job posting.</p><p>8</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Presentation</p><p>2 points The timeline is clear, organized, and presented well.</p><p>1 point The timeline is somewhat clear and organized and the presentation is adequate.</p><p>0 points The timeline is not clear and organized or is not presented well.</p><p>2</p><p>Follows Assignment Prompts</p><p>8 points All prompts were followed in a clear and organized way.</p><p>7-6 points Most prompts were followed in a clear and organized way.</p><p>5-0 points Few to no prompts were followed and organization was unfocused.</p><p>8</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f22d9729129f9403b9141b916f057604','space-travel-and-solar-system-m6-l10-module-6-quiz','52fc894074bcaf0c52f3f0c69eefdbdf','Module 6 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Asteroid Mining. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('20a3b9112f5b6f97fa2741ffca147a5d','space-travel-and-solar-system-module-7','2a892040eda1f32ee69b17d25aad96dd','Module 7: Solar System Exploration',7) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ff7e5b51227045a5e8212fca5d20810d','space-travel-and-solar-system-m7-l1-introduction-purpose-and-objectives','20a3b9112f5b6f97fa2741ffca147a5d','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi and welcome back. This is the intro video on Solar System Exploration.</p><p>Right now, space explorers are focusing most of their attention on the Moon and Mars. They are, after all, our closest neighbors. But what about further out? What mysteries and possibilities exist on other planets and moons? Will they be just a stepping stone for humans to go even further out, into deep or even interstellar space?</p><p>In this module, you’ll learn about the climate and conditions on Venus, engage in discussion about the possibility of terraforming the surface, or creating floating cities there. Moving past Venus, we’ll look at Jupiter and Saturn’s many moons, and try and decide if humans could one day live there.</p><p>Then you’ll have a chance to reflect on the vast distances that we must conquer in order to travel within our solar system. We’ll also discuss the limitations of our current technology. Finally, you’ll learn about the importance of water in space travel and take a look at destinations beyond Neptune that might be suitable for colonization.</p><p>Module Description</p><p>License:&#160;All Rights Reserved</p><p>In this module, we’ll go way beyond our nearest neighbors, the Moon and Mars.&#160;We’ll take a closer look at and consider other planets, such as Jupiter and Saturn and their moons as potential sites for colonization.</p><p>Would Venus be suitable for human exploration or habitation?&#160;Do the moons of Jupiter or Saturn contain water, and would they ever support human colonies?&#160;Could these celestial bodies be launching points for deep space and interstellar travel?</p><p>This module will also discuss the increasing difficulties and logistical challenges of expanding our reach further away from the comfort of planet Earth.</p><p>Objectives</p><p>In this module, students will</p><p>Describe the climate and conditions on the planet Venus and discuss the possibility of terraforming or creating floating cities on Venus.</p><p>Identify Jupiter’s moons, including the 4 Galileo moons, and evaluate their potential for sustaining life and colonies.</p><p>Compare the distances required to travel within our solar system and describe limitations given current technology.</p><p>Describe the importance of water in space travel.</p><p>Identify other moons, planets, and bodies at Saturn and beyond that could support colonies.</p><p>Polling Question</p><p>Do you think we’ll set up a colony on another planet or moon within your lifetime?</p><p>Yes&#160;No</p><p>Make a selection to see the results so far.</p><p>How did your answer compare to your classmates?&#160;Let’s see how your answer changes as you learn more about several planets and moons in our solar system and their potential for human colonization.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>The way astronomers describe solar distances.&#160;An AU equals the mean distance between the Sun and Earth which equals 93 million miles or 8 light-minutes.</p><p>Magnetosphere</p><p>A process that can be used to run liquids through a membrane, letting water molecule through but stopping “unwanted” molecules from things like salts, bacteria and parasites for example.</p><p>Ice quakes</p><p>When large amounts of water shoot up out of the ice.</p><p>Forward Osmosis</p><p>The space around a celestial body, like Earth, that is charged with particles that deflect radiation among other things.</p><p>Astronomical Units (AU)</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>The way astronomers describe solar distances. An AU equals the mean distance between the Sun and Earth which equals 93 million miles or 8 light-minutes.</p><p>Magnetosphere</p><p>Astronomical Units (AU)</p><p>Forward Osmosis</p><p>Ice quakes</p><p>2.</p><p>A process that can be used to run liquids through a membrane, letting water molecule through but stopping “unwanted” molecules from things like salts, bacteria and parasites for example.</p><p>Ice quakes</p><p>Magnetosphere</p><p>Forward Osmosis</p><p>Astronomical Units (AU)</p><p>3.</p><p>When large amounts of water shoot up out of the ice.</p><p>Ice quakes</p><p>Magnetosphere</p><p>Astronomical Units (AU)</p><p>Forward Osmosis</p><p>4.</p><p>The space around a celestial body, like Earth, that is charged with particles that deflect radiation among other things.</p><p>Ice quakes</p><p>Astronomical Units (AU)</p><p>Magnetosphere</p><p>Forward Osmosis</p><p>Body of a significant size that orbits a star but hasn’t “cleared its neighborhood” around its orbit.</p><p>Minor (dwarf) planet</p><p>When photons from a light source are absorbed by a semiconductor material in water.&#160;The reaction splits the water molecules into hydrogen (for rockets) and oxygen (for humans).</p><p>Retrograde</p><p>When celestial bodies orbit in the same direction as a planet.</p><p>Photocatalysis</p><p>When celestial bodies orbit in the opposite direction as a planet.</p><p>Prograde</p><p>Terraforming is a hypothetical process where we deliberately change the atmosphere and surface of a planet to make it more “Earth-like” so we can live on it.</p><p>Terraforming</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Body of a significant size that orbits a star but hasn’t “cleared its neighborhood” around its orbit.</p><p>Prograde</p><p>Photocatalysis</p><p>Terraforming</p><p>Retrograde</p><p>Minor (dwarf) planet</p><p>2.</p><p>When photons from a light source are absorbed by a semiconductor material in water. The reaction splits the water molecules into hydrogen (for rockets) and oxygen (for humans).</p><p>Prograde</p><p>Minor (dwarf) planet</p><p>Terraforming</p><p>Retrograde</p><p>Photocatalysis</p><p>3.</p><p>When celestial bodies orbit in the same direction as a planet.</p><p>Prograde</p><p>Terraforming</p><p>Minor (dwarf) planet</p><p>Retrograde</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('08560975bcfae1bf2355d941b12bb7b2','space-travel-and-solar-system-m7-l2-lesson-1','20a3b9112f5b6f97fa2741ffca147a5d','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Living in Venus Planet</h3><p>Living in Venus Planet</p><p>While watching this video, consider&#160;the following questions:</p><p>When you imagine us living on Venus, what do you see?&#160;Pod-like structures on the surface?&#160;Or maybe floating cities?</p><p>Hi and welcome to Video 1 for this module on Solar System Exploration.</p><p>Let&#39;s be clear here, the worst weather you&#39;ve ever seen, even hurricanes, lightning storms or blizzards are nothing compared to Venus on a good day. The fact that the atmosphere is made up almost completely of carbon dioxide guarantees it&#39;s going to get windy. It&#39;s also hot at about 860 degrees Fahrenheit (or 462 Celsius). Venus gets its angry weather from its thick cloud cover and its nitrogen levels, about four times that of Earth. This show us what the worst example of greenhouse gases in the solar system can do.</p><p>Venus, the second planet from the sun, is interesting in several other key ways. First of all, it spins on its axis &quot;backwards&quot; compared to Earth. There are a few theories to explain why it has a clockwise rotation, instead of counter-clockwise like Earth. One possible explanation is that the unique rotation is caused by the Sun&#39;s gravitational pull, combined with an atmospheric tide caused by the planet&#39;s thick atmosphere. Another possibility is that the planet was hit by an asteroid hard enough to get it spinning the other way. Or maybe it was Superman?</p><p>It’s also really slow, rotating once every 243 Earth days. But, because the atmosphere is so hostile, the temperature doesn’t really dip or rise when one side is facing the Sun or not, as it does here on Earth.</p><p>It should be clear to you by now that setting up a tent or a light structure on the surface of Venus is pretty much a no go. So why are we even discussing going there? Well, here’s the odd thing. The spot that is the most like Earth’s atmosphere, in the whole solar system, is about 50-60 kilometers (or 30-40 miles) above the surface of Venus. At that distance from the surface, the oxygen and hydrogen have risen above the heavier gases that blanket the planet, and the air pressure is similar to Earth’s. Now, given that we’re not birds, this doesn’t seem to help us a great deal. But here’s the thing, there are studies that suggest we could build floating cloud cities where we could live above the planet.</p><p>NASA has even put together a concept, called the High-Altitude Venus Operational Concept (or HAVOC). The theory goes that a series of blimps, geostationary floating platforms and other floating or flying modules could become the site of our Venusian colony.</p><p>While going to Venus to set up flying cloud cities in balloons seems far-fetched, it’s not like we haven’t visited before. In fact, we’ve sent so many probes there that, if there was alien life on Venus, they might be feeling a bit intruded upon. Starting in 1961 with the Soviet Union’s failed Sputnik 7 mission, all the way to 2018’s BepiColombo probe from the ESA, which did two Venus flybys, we’ve been sending some kind of spacecraft to Venus at least once a decade.</p><p>Let’s take a look at some of the most successful missions:</p><p>Mariner 2: Launched August 8th, 1962 by NASA, this was the first successful flyby of Venus that returned scientific data. It discovered the slow rotation speed of Venus, the high heat and pressures on the surface, as well as the continuous cloud cover.</p><p>Venera 4: This probe was launched by the Soviet Union on the 12th of June 1967 and it sent back data about the composition of Venus’ atmosphere, as well of confirming the lack of magnetic field.</p><p>Venera 7: This was the first landing on Venus. It was sent up in August of 1970 by the Soviet space program, and only managed to broadcast weak signals for about 23 minutes. It sent back temperature, air pressure and wind readings, giving us the first weather report from Venus.</p><p>Mariner 10: While parts of its equipment failed, NASA’s Mariner 10 gave us the first close-up photo of Venus, confirmed that there was circulation in Venus’ atmosphere.</p><p>Venera 9 through 16: From 1975 to 1983, the Russian space program sent up eight different flybys, orbiters, and lander missions to Venus. They sent back measurements about wind speed, temperature, atmosphere, as well as images of lava formations, sound recordings from Venus as well as the first color photos from the surface.</p><p>Magellan: Launched in May of 1989, NASA&#39;s Magellan mission looked at tectonics and landforms and other geographic phenomena on Venus. It showed that Venus has none of the plate tectonics that Earth does and that 85% of the surface is covered with volcanic flows. Did you ever play “the ground is lava” as a little kid? Sounds like fun on Venus!</p><p>Parker Solar Probe: The most recently launched probe to Venus, NASA’s Parker Solar Probe, will do six flybys of Venus, starting in December of 2019. It is going to attempt to trace the flow of energy, acceleration of the solar wind and the heating of the solar corona.</p><p>With so much attention on Mars, it seems like Venus has not been getting the love (despite being named after the Roman goddess of love!) And while its environment and temperature are completely inhospitable, some unique possibilities like floating platforms, remain. Without a doubt, our neighboring Venus should be a planet that we continue to learn more about.</p></section><section><h3>Venus Characteristics</h3><p>Venus Characteristics</p><p>(opens in a new tab)</p><p>Venus in front of a colorful star field&#160;by Dotted Yeti</p><p>License:&#160;All Rights Reserved</p><p>We now know what the atmosphere around Venus is like and we understand that the surface is made up of the same basic elements as Earth.&#160;But is it too inhospitable to colonize?&#160;NASA scientists think that for the first part of its existence Venus was inhabitable.&#160;That it had water and was closer to what Earth is like today.&#160;In this reading, we’ll look at some of the theories behind turning back time and making it so that maybe, one day, humans will live on the Venetian surface.</p><p>Into the Way&#160;Back&#160;Machine</p><p>Before we look at ways to change Venus to be more suitable for us to live on, we need to look at where it all started.&#160;If we travel back a mere 715 million years in the past, the Venetian climate was similar to ours.&#160;According to scientists at NASA’s God<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9a4fa172247f07423a2c019d9670dfb4','space-travel-and-solar-system-m7-l3-lesson-2','20a3b9112f5b6f97fa2741ffca147a5d','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Jupiter moons</h3><p>Jupiter moons</p><p>While watching this video, think if you know the answer to the following question:&#160;How many moons do you think the planet Jupiter has?</p><p>Welcome back, this is Video 2 on this module on Solar System Exploration.</p><p>We saw in the last module that Jupiter plays a key role in our solar system. It’s often called a gas giant because of its very large mass, which is 2.5 times bigger than all the other planets combined! Because of that, it attracts and keeps in orbit millions of asteroids and more moons than there are states in the US. It’s no wonder scientists are looking at Jupiter when they think about potential future human colonies in space. Let’s take a closer look at its many possibilities.</p><p>On Earth, we’re used to having a single moon but imagine being on a planet surrounded by 79! That would be quite a sight, right? Let’s forget for a second that you couldn’t actually stand on Jupiter, because its atmosphere is made up of gases, and imagine you’re looking up at the sky. Well, you’d see so many moons, you wouldn’t know which one to focus on. Maybe the moon Ganymede would catch your attention? After all, it’s even bigger than the planet Mercury. Or maybe it’s the yellowish moon Io that would shine bright in the sky because it’s the moon that orbits the closest to Jupiter.</p><p>Every year, scientists discover new moons around Jupiter, thanks to advancements in telescope technology and the many probes that have visited the planet over the years. Scott Sheppard from the Carnegie Institution for Science discovered 51 of them!</p><p>Now, let’s have a closer look at a the most interesting moons and groups.</p><p>The Amalthea cluster is actually the closest to Jupiter and is made up of Metis, Adrastea, Amalthea, and Thebe. These moons don’t get as much attention as the next group because of their small size, which is less than 200 km in diameter.</p><p>The “rock stars” of Jupiter are the Galilean moons, which include Io, Europa, Ganymede, and Callisto. They get their name from the famous Italian astronomer, physicist, and engineer Galileo Galilei who discovered them in 1610 using a simple telescope. These moons spin in the same direction as the planet, which is called a prograde direction. If they weren’t in Jupiter’s orbit, they would no doubt be considered planets because of their size.</p><p>Io for example, is the fourth largest moon in our solar system and roughly the same size as our moon. It is striking with its bright yellow color and shiny surface that makes it look more like a cool bowling ball than a planet.</p><p>Other clusters, such as the Carme, Ananke, and Pasiphae groups follow a retrograde path, which means they orbit in a direction opposite to that of Jupiter. These groups are much further from the planet and include 25 moons.</p><p>Discovered in 2018, the Valetudo moon is a bit of a rebel. It follows a prograde direction in a cluster of retrograde moons. Because it’s crossing the path of other moons, astronomers and scientists believe there’s a high chance that it will eventually collide with one of them.</p><p>These are only some of Jupiter’s many moons and clusters, but it should give you a good idea of how dynamic celestial activity is around the planet. Of course, a large part of this activity is a result of Jupiter’s enormous size. Some of the moons are even being considered for possible human colonies. Let’s explore that further.</p><p>Of all of Jupiter’s orbiting celestial bodies, three of the Galilean moons, Europa, Ganymede, and Callisto have caught the attention of scientists as potential sites for future colonies. Io, the fourth moon, has more than 400 active volcanoes and over a hundred mountains, some taller than Earth’s Mount Everest. Its proximity to Jupiter makes it impossible to colonize because of the intense radiation. Let’s have a look at the three contenders in order of their proximity to the giant planet.</p><p>Europa is slightly smaller than our moon and has a really smooth surface. Scientists believe it probably has an iron-nickel core surrounded by liquid water and protected by a thick crust of ice. They also think the water below the icy surface might be warmed by both heat energy and tidal movements.</p><p>If that’s the case, life could exist beneath the surface near hydrothermal vents; which have been known to sustain life here on Earth in cold deep ocean conditions. All of these facts could make life on Europa possible, which is why it’s one of the strongest contenders for human colonization.</p><p>Ganymede is unique on many levels. You already know that it’s really large, but did you know it’s the only moon in our solar system to have a magnetosphere? The Earth has a magnetic field, which protects us from the Sun’s radiation. Even though Ganymede’s magnetic field is much smaller, it’s still a unique characteristic.</p><p>This moon has also been visited by many spacecrafts over the years, which is why we know about the magnetosphere, but also about the likelihood of a liquid ocean deep underneath the surface, close to the liquid iron core. Just like its neighbor, Europa, that ocean is covered with a thick ice crust.</p><p>Just like Ganymede, Callisto has some unique features. For example, its Valhalla crater is the largest in our solar system at almost 4,000 kilometers in diameter. That’s roughly the distance between Los Angeles and New York City! In fact, Callisto is covered with craters and is very old. It’s also believed to have a liquid ocean deep under the surface that could sustain life.</p><p>Contrary to Europa and Ganymede, Callisto doesn’t show any signs of geological activity but it’s still a contender because its greater distance from Jupiter means it receives lower levels of radiation.</p><p>All three moons are believed to meet several key conditions for possible colonization. They all have a thin atmosphere, water, and possible heat sources. In this section’s reading, we’ll explore the possibility of terraforming and colonizing Jupiter and its moons even further.</p></section><section><h3>Jupiter Characteristics</h3><p>Jupiter Characteristics</p><p>A lot of data has been collected over the years about our solar system’s biggest planet:&#160;Jupiter.&#160;It’s impossible to ignore it because it controls so much of what’s going on in our solar system.&#160;It’s also on the way to deep space exploration.&#160;What have we learned about the giant planet and it<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('d0360b42ffa61ae536f02735c7bdc93c','space-travel-and-solar-system-m7-l4-lesson-3','20a3b9112f5b6f97fa2741ffca147a5d','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Space Travel Distances to Planets</h3><p>Space Travel Distances to Planets</p><p>While watching this video,&#160;think about the following questions:</p><p>We talk about traveling to other planets like it’s a simple thing, but do we really understand the distances?&#160;How long do you think it would take to get to Venus?&#160;How about Jupiter or Saturn’s moons?</p><p>Welcome back, this is Video 3 of this module on Solar System Exploration.</p><p>Have you ever been on a long car trip or vacation somewhere? Remember how boring it got, even if you were on a bus or train, where you could stretch your legs a bit? Now imagine that trip taking an entire year. And then imagine that the trip is with only five people in very limited quarters. Playing “I spy with my little eye” on your way to another planet will get old quickly:</p><p>“I spy something… black.”</p><p>“Space?”</p><p>“Uh. Yep, you got it… again.”</p><p>Now there’s a lot of talk of traveling or even colonizing Mars, right? Let’s put things in perspective. At its closest to Earth, Mars is 55 million kilometers away. Depending on when a mission launches, a trip to Mars would take between six to eight months. If you’re not up for a six- to eight-month journey, how about Venus? At a mere 40 million kilometers, it’s a lot closer. Well, that trip would take you at least four months.</p><p>Maybe you’re a born adventurer and neither time nor distance scares you. Then let’s consider another destination that people mention as a possible human colony: Europa, one of Jupiter’s moons. When Earth and Jupiter are closest together, the distance between them is 365 million miles (588 million kilometers). The various spacecraft we have sent to examine Jupiter has taken anywhere from 13 months to six years depending on their path. For example, the spacecraft Galileo took six years to get to Jupiter because it also orbited Earth, Venus and an asteroid on its way to the giant planet.</p><p>Maybe the prospect of spending 13 months in a cramped capsule does not bother you. But unfortunately, with today’s technology, the most time an astronaut could survive traveling through space is only four months.</p><p>One of the biggest challenges to space travel is fuel. Essentially, the longer you can accelerate and go really fast, the shorter your trip will be. Let’s go back to your road trip to grandma’s house. If the car or bus could safely go 200 miles per hour (or 322 kilometers per hour) for the whole trip, you’d be there in no time. But the kinds of cars that can go at that speed, the amount of fuel you’d burn, and the weight of the fuel would be completely impractical. So instead, you travel there at about 55 miles per hour (about 89 kilometers per hour) to make the engine as efficient as possible, and keep the fuel load to a reasonable level.</p><p>The same restrictions, multiplied by many times, exist with space travel. Let’s say you want to launch a spaceship that’s got enough fuel to go to Venus very quickly. It also needs to carry six crew members, supplies to keep them healthy and fed, and some kind of experimental living shelter, like the HAVOC, which you learned about earlier. To carry all those people and their supplies, plus the HAVOC, the ship will have to be large and heavy. Then, you have to add the fuel to get to Venus quickly. Suddenly, the already big ship is huge, which means more fuel again to get it off Earth. This is why current research is focusing on more economical ways to explore the solar system.</p><p>So, how can we get up to higher speeds without needing more fuel? Currently, there are a few different techniques. The oldest, and slowest, is the Hohmann transfer technique. Basically, you put an object, in this case a manned spacecraft, into orbit around the Earth, and wait until the target destination is close enough that you can transfer orbits. Using this method, you only need fuel to establish the original orbit around Earth and to transfer to an orbit around Mars. The downsides to this method are that the further you&#39;re going, the more complicated the calculations become and the speed is low. A trip to Mars would take at least 8 and a half months.</p><p>In the gravitational slingshot method, you use the gravitational pull of a moon or planet to make a spaceship faster. The resulting speed can be up to twice the velocity of the planet or moon that the spacecraft slingshots around.</p><p>Another similar method is called the powered slingshot, or the Oberth effect. In this method, the spacecraft would fire its engines as it reaches the closest point to the moon or planet it is going to slingshot around. Again, the engine would only be on for a limited amount of time, but it can multiply the change of the velocity that the spacecraft would achieve with an unpowered slingshot.</p><p>As we dream about visiting and colonizing other planets, it’s important to remember that our solar system is vast! Today’s technology, even though it seems very advanced to us, is still not up to the task of traveling very far in a reasonable amount of time.</p></section><section><h3>Space Travel Solutions</h3><p>Space Travel Solutions</p><p>This all sounds a bit dire:&#160;space is vast, our ships are slow, and getting there faster will require more fuel, which, in turn, will require more fuel to get into space.&#160;So, what are the solutions?&#160;And how vast is vast?</p><p>Measuring Space</p><p>Even though we have been talking about space in terms of kilometers or miles, scientists actually only use those terms when trying to communicate a sense of distance to non-scientists.&#160;The actual measure they use is AU or&#160;Astronomical Units.&#160;An AU is the mean distance between the Earth and the Sun, so 93 million miles, or 8 light-minutes.&#160;Sometimes, it’s hard to imagine or visualize how far things are from each other in our solar system.</p><p>(opens in a new tab)</p><p>Creative Commons&#160;Astronomical unit&#160;by Huritisho&#160;is licensed under&#160;CC BY-SA 4.0(opens in a new tab).</p><p>Take a look at the video below to get a better sense of planetary distance.</p><p>Earth is a big place. If you could drive around the entire planet, it would take more than 16 days of non-stop driving at highway speeds. But, compared to some of the planets in our solar system, it&#39;s pretty small. We often see planets displayed as similar in size like this to make details on smaller planets easier to see. In reality, the s<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('31bcc06878ca33aa12229c1cb0a9edcf','space-travel-and-solar-system-m7-l5-lesson-4','20a3b9112f5b6f97fa2741ffca147a5d','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>The Importance of Water in Space</h3><p>The Importance of Water in Space</p><p>While watching this video, think about the following questions:</p><p>Water… do you think it’s important in space travel?&#160;After all, rockets don’t drink water and we can carry our own, right?</p><p>Welcome back, this is Video 4 of this module on Solar System Exploration.</p><p>When you think about the desert, what do you see? Most of us would imagine a sandy, hot, and very dry place, right? Well, in many ways, space also fits that description except it’s really cold and the sand is replaced with dust. Water is rare in space and when it exists, it doesn’t come from a tap or a big lake but from ice or oceans covered with thick ice crusts. The fact that humans can only last for up to a week without water, makes the lack of accessible water in space a big challenge in exploration.</p><p>In the vastness of the frozen vacuum of space, it would seem that there aren&#39;t a lot of sources of water. It&#39;s not like you can pull your spaceship up to a water station, fill up and then keep going. This is problematic for two obvious reasons. Firstly, because humans need water to live and, secondly, because it&#39;s possible that we can use water to produce both hydrogen to fuel spaceship engines and oxygen for humans to breath.</p><p>So, where can we get water? Well, even though there isn’t a great, cosmic water cooler we can pull up to with our space ships, it turns out that water is lurking all over the solar system, we just have to be clever about finding it. So where should we look?</p><p>Well our first port of call is closer than you think. On August 20, 2018 NASA scientists announced they had found surface ice at the poles of our nearest neighbor, the Moon.</p><p>Based on studies by India’s Chandrayaan-1 spacecraft, we now know that at the southern pole of the Moon, the ice is more abundant, because some of its deeper craters are never directly exposed to sunlight. Meanwhile, at the Lunar north pole, the ice is thinner, but spread out over a wider area.</p><p>But where else can we find water? Thanks to the Galileo probe, we know there’s a lot of water on some of Jupiter’s many moons, especially Europa, Ganymede, and Callisto. These are all believed to have deep liquid oceans underneath very thick ice crusts. Europa for example, hides a 100-kilometer ocean underneath its frozen exterior that may even harbor extra-terrestrial aquatic life.</p><p>The moons of Saturn are even more promising because some of them seem to have large deposits of water or other liquids on or near the surface. Near the south pole of Enceladus for example, the Cassini spacecraft observed geysers shooting out of cryovolcanoes, which are volcanoes that are frozen. Considering there are over one hundred of these geysers and that some of what they project is water, it would make collecting water more possible.</p><p>Clearly, getting water from any of these moons would be a big challenge, especially given its distance from Earth. We would wind up needing as much water to get there as we’d be able to collect. Even if we got there it, there would still be many complications. This includes radiation levels and, in the case of Saturn’s moon Titan, figuring out a way to collect the water from under lakes of methane, the same stuff used on Earth as a fuel.</p><p>Are there any possible water collection points closer to home, apart from the Moon? Well, comets could be contenders. Some people refer to them as &quot;dirty snowballs&quot; since they are made up of ice and leftover dust from when the solar system was formed. Some scientists think it’s possible that the water on Earth actually comes from comet impacts. The melted water that they delivered, by smashing into the Earth, was then trapped by our atmosphere. So, perhaps we could mine comets for water as we travel into space.</p><p>Another possibility we may have to consider is that we leave Earth with a certain amount of water that we recycle and reuse. An article by Phys.org explains that:</p><p>“The idea is to make a fortified drink that provides hydration and nutrients from all sources available aboard a spacecraft, such as wastewater and even urine. The method set for testing uses a process known as forward osmosis.”</p><p>According to Michael Flynn, a scientist at NASA’s Ames Research Center, forward osmosis would allow us to clean and reuse water. Essentially, water is passed through a membrane that lets the water molecule through but stops the “unwanted” molecules like those that make up “salts, sugars, starches, proteins, viruses, bacteria and parasites.” The really attractive part of this process is that it doesn’t use any energy and it can be reused over and over again, which makes it uniquely suited for space exploration where electricity is always at a premium. NASA has studies which are ongoing with this technology on the ISS, where they are trying to see if it can be used to filter water in order to extend the water supply.</p><p>It’s clear that water is important for human explorers to survive, but making fuel and oxygen are going to be equally as important. A study released in 2018 shows that it’s possible to use a combination of water, a semiconductor material, and solar light to create hydrogen and oxygen, even in zero gravity.</p><p>The process is called photocatalysis. Essentially, photons from a light source, which in this case could be sun or starlight, are absorbed by a semiconductor material in the water. The reaction splits the water molecules into hydrogen (for rockets) and oxygen (for humans). Another advantage of this process is that it can be reversed using a fuel cell, basically a battery.</p><p>As you can see, water is a key component of space travel. Before humans can explore our solar system further, they’ll have to figure out how to recycle it and collect it.</p></section><section><h3>Ring of Saturn and Water in Space</h3><p>Ring of Saturn and Water in Space</p><p>(opens in a new tab)</p><p>Enceladus&#160;by NASA</p><p>License:&#160;Public Domain</p><p>Imagine you step off your spacecraft on Enceladus, one of Saturn’s moons, after a long flight and you walk over to a geyser shooting out of a cryovolcano and refill your water bottle.&#160;Science-fiction?&#160;Yes and no.</p><p>Enceladus:&#160;A Unique Moon</p><p>One particular aspect of Enceladus makes it quite unique in our solar system and very interesting for scientists in search of wa<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b4d68fa67e5ea457d5085a8d109011dd','space-travel-and-solar-system-m7-l6-lesson-5','20a3b9112f5b6f97fa2741ffca147a5d','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Life in Space</h3><p>Life in Space</p><p>While watching this video, think about if there’s less or more of a chance of finding life the further we go from Earth.</p><p>Note:&#160;in video A, it is mentioned that Saturn has as many as 62 moons.&#160;Astronomers are discovering new moons all the time, and as of 2023, that number is up to 124!</p><p>Welcome back, this is Video 5 of this module on Solar System Exploration.</p><p>We saw earlier that some of Jupiter’s Galilean moons offer some promising options for future human colonies but they’re not the only ones. A little deeper into our solar system, the moons of Saturn also seem to hide liquid oceans. But Enceladus, however, is constantly spouting plumes of water. So, let’s discover the moons of Saturn and examine their potential for human colonization. Then, let’s go even further and discover the world of trans-Neptunian objects.</p><p>Before taking a closer look at Saturn’s moons, let’s talk about the planet. It’s the second largest in our solar system after Jupiter and it’s mostly known for its rings. From Earth, it’s hard to see that there are thousands of rings. They’re made of rocks and ice coated with dust from comets and asteroids that exploded before getting to the planet. Each ring orbits around Saturn at a different speed.</p><p>Saturn shares many similarities with its bigger neighbor Jupiter. It’s mostly made of hydrogen and helium so humans couldn’t land on the surface. It has a solid iron/nickel core, wrapped in rocks, and a liquid hydrogen layer. It also has a very strong magnetic field. Another similarity is that Saturn also has many moons; possibly as many as 62.</p><p>Even though it looks really smooth, the surface of Saturn is battered by extreme winds and is not at all welcoming to humans who would get crushed and vaporized by its extreme pressure. One storm in particular is quite unique and spectacular. It’s called the North Pole Hexagon because of its shape and could be hundreds of kilometers high. No one knows for sure what causes it or how it keeps going. All they know is that it appears and disappears depending on the season. Considering one Saturn year is like 30 Earth years, the seasons are very long so it’s not easy to be there at the right time to observe it.</p><p>That’s probably why Cassini, the NASA probe that has given us most of our knowledge on Saturn, didn’t notice it at first. The probe orbited the planet 294 times between 2004 and 2017. At the end of its last orbit, it was sent into the planet’s atmosphere and was vaporized. Luckily, the hexagon storm appeared during that time.</p><p>Just like the moons of Jupiter, Saturn’s moons have attracted a lot of attention as possible sites for human colonization. Most of them are quite small but a few, show some promise.</p><p>Let’s start with the largest moon, Titan. The only other moon in our solar system bigger than Titan is Ganymede but that&#39;s not its only unique characteristic. It&#39;s also the only known moon to have an atmosphere and the only celestial body other than Earth where liquid has been found on the surface. Titan is similar to Earth in many ways but with a different component.</p><p>Because it experiences seasonal patterns including wind and rain, the surface of Titan shows features that we also find on Earth like rivers, lakes, seas (probably filled with liquid methane and ethane), and dunes. If you swap water for methane, Titan has a cycle similar to our water cycle. One major difference though is that all this happens at a much lower temperature of negative 290 degrees Fahrenheit.</p><p>Some experts think that, if we could get there, Titan may actually be easier to settle than our moon or Mars. First, it has several sources of energy (chemical, wind, hydro, and solar). Second, it has an atmosphere. Settlements could be built on its surface similar to those built in Antarctica. They would be protected against harmful radiation and large meteorites. Finally, ice exists that could be used for insulation as well as a source of water. Oxygen could also be extracted from the ice and used to create fuel for a spacecraft like Elon Musk&#39;s BFR, which includes supercooled liquid methane and liquid oxygen.</p><p>We talked briefly about the Enceladus geysers of water in the previous section, but let’s have a closer look at this surprising moon. Images of Enceladus collected by Cassini show what looks like a papier-mache sphere with a relatively smooth white surface and blue creases all over until you get to the south pole where it looks like you’re suspended above a pod of whales spraying water as they surface.</p><p>This phenomenon has been baffling scientists for years. They couldn’t understand how such a small moon, with a diameter just over 300 miles, was able to generate enough energy to sustain a liquid ocean. But a recent theory based on 3D simulations believes the heat could be generated by friction in a non-solid core where the rocks are constantly being thrown around like in a washing machine. If true, this would make Enceladus truly unique in our solar system and definitely a candidate for further exploration and, maybe one day, colonization.</p><p>Beyond Saturn, we find two more planets in our solar system: Uranus and Neptune. Sorry, no Uranus jokes in this video. They’re not considered as sites for human colonization as they are also gas giants. But Uranus is sometimes mentioned as a possible robot-led mining site for helium-3. But a growing number of scientists are proposing that we look past Neptune for possible human habitats.</p><p>British theoretical physicist and mathematician Freeman Dyson has suggested an idea even further out. Trans-Neptunian objects (or TNOs), which are celestial bodies that orbit the Sun but are located further than the planet Neptune, could be a lot more suitable to human colonization than planets. The largest TNOs are Eris, Pluto, 2007 OR10, Makemake, and Haumea. They’re considered dwarf or minor planets, which are bodies of a significant size that orbit a star but haven’t “cleared the neighborhood” around their orbit. “Cleared the neighborhood” means there are no other bodies of similar size other than its own moon in its orbit. Pluto never cleared its neighborhood and was “demoted” to a dwarf planet in 2006 because it didn’t have enough size to be gravitationally dominant.</p><p>But these dwarf planets are far from being alone out there. It’s estimated the Kuiper belt and Oort<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a2f4d837b1652e11b6d2d4bafc6f029a','space-travel-and-solar-system-m7-l7-module-7-summary','20a3b9112f5b6f97fa2741ffca147a5d','Module 7 Summary','text',12,'<h2>Module 7 Summary</h2><section><h3>Module 7 Summary</h3><p>Module 7 Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Solar System Exploration!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Described the climate and conditions on the planet Venus and discussed the possibility of terraforming or creating floating cities on Venus.</p><p>Identified Jupiter’s moons, including the 4 Galileo moons, and evaluated their potential for sustaining life and colonies.</p><p>Compared the distances required to travel within our solar system and described limitations given current technology.</p><p>Described the importance of water in space travel.</p><p>Identified other moons, planets, and bodies at Saturn and beyond that could support colonies.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('69855a155ed92b5f82e445fd41f9320b','space-travel-and-solar-system-m7-l8-module-7-assignment','20a3b9112f5b6f97fa2741ffca147a5d','Module 7 Assignment','text',12,'<h2>Module 7 Assignment</h2><section><h3>Module 7 Assignment</h3><p>3300</p><p>Space Travel</p><p>Solar System Exploration - Short Answer Assignment</p><p>Short answer assignment</p><p>For this writing assignment, choose&#160;one&#160;of the two short answer prompts below and write a two-page, double spaced paper addressing the questions/topics listed.</p><p>Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p><p>1)&#160;Thinking about what we know about the environments on the different planets and moons we discussed in this module, their distances from Earth and the technologies available to reach them, which of them do you think humans should try and visit first? Should we just go for an explorative visit, as we did with the Moon? Or should we be gearing up to colonize other places? Explain your answers with reference to the videos and readings.</p><p>2)&#160;Let’s focus on the actual travel and life support side of space travel. Knowing that the distances are vast, the time frames long and hurdles to colonizing other planets huge, which do you think are the most important problems we will have to solve before we can visit or colonize some of these far away moons or planets? Make sure you review the videos and readings and make reference to them when explaining which problems, you think we have to solve before we can truly be space explorers. You are expected to address several of these problems and suggest which solutions you learned about make the most sense.</p><p>Review the rubric below to see how you will be graded.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5196c8e5d4bc40e7221537a93320386b','space-travel-and-solar-system-m7-l9-module-7-project','20a3b9112f5b6f97fa2741ffca147a5d','Module 7 Project','text',12,'<h2>Module 7 Project</h2><section><h3>Module 7 Project</h3><p>3300</p><p>Space Travel</p><p>Solar System Exploration - Project</p><p>Project</p><p>For this assignment, it is the year 2100. Mars, as well as all the habitable moons of Saturn and Jupiter, have colonies. And all the asteroids in the asteroid belt have been ‘claimed.’ It’s time to start looking for opportunities beyond Neptune. In this project, you will create a presentation to describe the potential for space exploration and mining in the Kuiper Belt. You will conduct your own research to support your claims. You can use a presentation software such as PowerPoint or Prezi to create your presentation. Be sure to cite any resources for images and other content.</p><p>Your presentation should:</p><p>Describe the location and objects of the Kuiper Belt</p><p>Compare differences from and similarities to the Main Asteroid Belt</p><p>Discuss rewards and challenges of mining asteroids in this region</p><p>Highlight new technologies that will be required to reach this location and extract and mine materials from this region</p><p>Be organized and engaging</p><p>Review the rubric below to see how you will be graded.</p><p>Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>the Kuiper Belt</p><p>8 points The presentation effectively describes the location and objects of the Kuiper Belt as well as the new technologies required to extract and mine materials from its region.</p><p>7-6 points The presentation adequately describes the location and objects of the Kuiper Belt as well as the new technologies required to extract and mine materials from its region.</p><p>5-0 points The presentation does not adequately describe the location and objects of the Kuiper Belt as well as the new technologies required to extract and mine materials from its region.</p><p>8</p><p>Compare</p><p>8 points The presentation demonstrates a strong understanding of the differences and similarities to the Main Asteroid Belt and discusses the rewards and challenges of mining asteroids in this region. It contains several specific and accurate details.</p><p>7-6 points The presentation demonstrates a moderate understanding of the differences and similarities to the Main Asteroid Belt and discusses the rewards and challenges of mining asteroids in this region. It contains several specific and accurate details.</p><p>5-0 points The presentation demonstrates little to no understanding of the differences and similarities to the Main Asteroid Belt and discusses the rewards and challenges of mining asteroids in this region. It contains several specific and accurate details.</p><p>8</p><p>Presentation</p><p>2 points The presentation is clear and organized.</p><p>1 point The presentation is somewhat clear and organized.</p><p>0 points The presentation is not clear and organized.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c5c4002fa7227c4aecb4334431d606d7','space-travel-and-solar-system-m7-l10-module-7-quiz','20a3b9112f5b6f97fa2741ffca147a5d','Module 7 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Solar System Exploration. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('4c8472dc6b8d423ceed15c0bb918b8f4','space-travel-and-solar-system-module-8','2a892040eda1f32ee69b17d25aad96dd','Module 8: Robots and War in Space',8) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ba7de6556d1cc370bb4dd1c44594c743','space-travel-and-solar-system-m8-guided-learning','4c8472dc6b8d423ceed15c0bb918b8f4','Guided Learning','text',15,'<h2>Robots and War in Space</h2><p>Build and apply the essential concepts in this module through guided explanation, practical examples, and reflective activities.</p>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('b223f9c61494ecc607668504bf06c8ac','space-travel-and-solar-system-module-9','2a892040eda1f32ee69b17d25aad96dd','Module 9: Spacecraft Technology',9) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('899e4dfd1cb3cd154c0f0cc0cc0fa04c','space-travel-and-solar-system-m9-l1-introduction-purpose-and-objectives','b223f9c61494ecc607668504bf06c8ac','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction and Overview</h3><p>Introduction</p><p>Hi everyone, welcome back. This is the intro video for the module on Spacecraft Technology.</p><p>Spacecraft technology is almost like a magical world where everything is possible and no idea is too crazy. It’s that spirit that fuels the imagination of scientists, engineers, software developers, roboticists and many more. They are developing the next crop of spacecraft that will take humanity further than ever before. This may, someday, allow us to colonize another planet or moon.</p><p>In this module, you’ll discover the world of spacecraft technology. You’ll learn about the many things that go into the design of a craft capable of making it into outer space successfully while protecting its cargo; including human beings. There are many challenges including the cost of building spacecrafts, the risks involved in sending humans into space, and the constant possibility that it might not work once it’s out there. Buckle up and get ready for a wild ride!</p><p>Module Description</p><p>V2 space rocket ready for take off&#160;by Fred Mantel</p><p>License:&#160;All Rights Reserved</p><p>Since the first spacecraft, the V2 rocket, was launched by Germany in 1944, humankind has continued to launch objects beyond Earth’s atmosphere.&#160;This has included satellites, robots, a car, and even some Legos.&#160;But there is a giant leap in difficulty when we talk about sending living beings into outer space with the expectation that they’ll survive the trip.&#160;Human life is even more fragile in space so ensuring the survival of astronauts as they travel in and out of the Earth’s atmosphere or settle on a celestial body or permanent spacecraft is not an easy feat.</p><p>In this module, you’ll learn about what makes this possible.&#160;Spacecraft technology is evolving at a very rapid pace not only to send robots and probes where humans can’t go yet but also to help humans survive at tremendous speeds, extreme temperatures, and deadly radiation.&#160;You’ll also get a preview of what is on the horizon of spacecraft design and will allow us to go farther and farther from our home planet.</p><p>Objectives</p><p>In this module, students will</p><p>Describe the difficulties of human space travel that must be addressed in spacecraft design</p><p>List the subsystems of spacecraft and define the function of each one</p><p>Summarize the technology and science that enable rocket propulsion and spacecraft re-entry</p><p>Examine the risks, costs, and potential of reusable rockets</p><p>Compare historical and current spacecraft with possible future designs that may support interplanetary and interstellar travel</p><p>Evaluate a day in the life of an astronaut on a spacecraft or space station, describing elements of the spacecraft that allow humans to survive and work</p><p>Polling Question</p><p>If you could choose a spacecraft as a birthday gift, would you choose .&#160;.&#160;.</p><p>the Star Wars’ single-seat Starfighter&#160;the Resolute in the Netflix series Lost in Space in which you can travel to another planet with your family, land and live&#160;the Starship Enterprise - put me on the bridge in the commander&#39;s chair&#160;a regular space shuttle will do</p><p>Results:</p><p>a regular space shuttle will do&#160;100%</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Tab through this activity to read the feedback for your answers</p><p>Feedback</p><p>Force that acts against the direction in which an object is going.</p><p>Drag</p><p>Correct!</p><p>The infrastructure of a spacecraft that provides space for the payload.</p><p>Bus</p><p>Correct!</p><p>Spacecraft system that collects data, validates the information and distributes commands to other subsystems.</p><p>Communication system</p><p>Incorrect</p><p>Spacecraft system that allows communications between people and systems both in space and between Earth and space.</p><p>Command and Data Handling system</p><p>Incorrect</p><p>The minimum speed at which an object can escape the gravity of a celestial body.</p><p>Escape velocity</p><p>Correct!</p><p>Represents the force of acceleration.</p><p>G-force</p><p>Correct!</p><p>Spacecraft subsystem that uses sensors and actuators to position the craft precisely in space.</p><p>Attitude control system</p><p>Correct!</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Force that acts against the direction in which an object is going.</p><p>Attitude control system</p><p>Command and Data Handling system</p><p>Communication system</p><p>Escape velocity</p><p>Drag</p><p>Bus</p><p>G-force</p><p>Correct!</p><p>2.</p><p>The infrastructure of a spacecraft that provides space for the payload.</p><p>G-force</p><p>Escape velocity</p><p>Attitude control system</p><p>Communication system</p><p>Drag</p><p>Bus</p><p>Command and Data Handling system</p><p>Correct!</p><p>3.</p><p>Spacecraft system that collects data, validates the information and distributes commands to other subsystems.</p><p>G-force</p><p>Escape velocity</p><p>Drag</p><p>Command and Data Handling system</p><p>Attitude control system</p><p>Bus</p><p>Communication system</p><p>Incorrect</p><p>4.</p><p>Spacecraft system that allows communications between people and systems both in space and between Earth and space.</p><p>Attitude control system</p><p>Communication system</p><p>Drag</p><p>Escape velocity</p><p>Bus</p><p>Command and Data Handling system</p><p>G-force</p><p>Incorrect</p><p>5.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ef80856ee67793e4b7e756f6fff26fd3','space-travel-and-solar-system-m9-l2-lesson-1','b223f9c61494ecc607668504bf06c8ac','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Space Trips</h3><p>Space Trips</p><p>While watching this video, think this question:&#160;If you were packing for a trip to outer space, what do you think you would need?</p><p>Hi and welcome to Video 1 for this module on Spacecraft Technology.</p><p>So, you’re planning a trip to outer space. Maybe you’re visiting grandma on Mars? Or you booked a sightseeing tour of Venus or a safari around the moons of Jupiter? Whatever your dream vacation may be, you’ll need to make sure your ship comes with a few essentials. According to NASA, the technology should allow you to do the following:</p><p>Breathe. I’m sure you’ll agree that’s kind of crucial. After all, humans don’t do so well without oxygen. An average person can lose consciousness after a minute without oxygen and can have permanent brain damage after three to six minutes. To make breathing possible and safe, a spacecraft must be equipped with a life support system that can supply oxygen. It must also recycle the air and remove the carbon dioxide, or CO2, and the humidity that we produce when we breathe.</p><p>Move. Another obvious key element is being able to move, which means having a propulsion system. As you probably know, spacecrafts are launched into outer space using rockets but once they’re out there, they will need additional fuel for propulsion and course adjustments.</p><p>Stay cool. That one might seem odd. After all, space is cold, right? So, why would you need to stay cool? Well, remember friction from physics class? A spacecraft can go at speeds of up to 25,000 mph. That’s New York to Los Angeles in six minutes! All that speed means a lot of friction that causes the surface to heat up. If the spacecraft is coming back to Earth, it’ll also have to withstand the heat of re-entry. That means having a thermal protection system that keeps the ship and its passengers safe.</p><p>Lay off the suntan. One of the most dangerous things in space is radiation. Human bodies and equipment fall apart when exposed to it. On Earth, we’re protected from the Sun’s radiation by the planet’s magnetic field. But out there, we would get hit with its full force. Scientists are still experimenting with ways to protect crafts and crews against the effects of radiation. For example, they’re looking at plastics and water for their ability to absorb radiation due to their high hydrogen content. Until we figure that one out, exploration will be limited.</p><p>Communicate. Even though there are already several ways to communicate from space, it’s going to get more difficult as we venture further and further away. Messages travel at the speed of light. That means a message from Mars takes 12.5 minutes to arrive. A message from the spacecraft Voyager, which is now at the very edge of our solar system, takes 18 hours to reach Earth. Closely related to communication is navigation. A reliable GPS (let’s call it a Galaxy Positioning System) is an absolute must on any spacecraft.</p><p>This means that any spacecraft should have systems that allow us to breathe, move around, and communicate. Some serious protection against the cold, the heat, and the radiation are also crucial to ensure human beings can survive in space. A lot of these life support systems and technologies are being tested on the International Space Station (ISS) and in extreme regions like the Antarctic and the deserts of Utah.</p><p>Closely related to propulsion is energy. Powering a spacecraft is also essential because the more fuel it carries, the heavier and slower it is, and the less distance it can travel. So far, most rockets and spaceships have been powered by chemical reactions, a bit like what we use for cars. But scientists are looking at other forms of energy that might be more efficient and allow a spacecraft to carry a lot less fuel and/or get more out of the fuel they carry.</p><p>Some of the possibilities include nuclear energy, a form of power we already use on Earth. Curiosity, the Mars rover, is powered by a nuclear generator just like the Viking 1 and Viking 2 Mars landers before it. Essentially, heat is generated as the fuel, made of radioactive isotopes, decays. It’s a bit like a campfire. The heat is generated by the wood as it decays, which in this case means burning. It&#39;s a compact, light and efficient way of generating energy. This generator only weighs 11 pounds.</p><p>Since 1958, and the launch of the American satellite Vanguard 1, solar energy has been used to power spacecrafts. It makes a lot of sense considering the energy generated by our Sun in space is a constant source. The ISS is also powered by large solar panels.</p><p>Another type of power that’s attracting a lot of attention is fusion. Engines powered by some form of fusion energy are seen as the next step in spacecraft evolution. It might hold the secret to long-distance space travel because it’s a lot more efficient than other types of energy. But scientists have to solve a few problems before fusion reactors are ready for space. At the moment, they’re too big and would be very hard to launch into space, and they consume more energy than they generate.</p><p>You’ll learn a lot more about spacecraft engines as we progress in this module.</p></section><section><h3>Survival out of Space</h3><p>Surviving Outer Space</p><p>License:&#160;All Rights Reserved</p><p>We’re closer than we’ve ever been to human space travel.&#160;In the last 60 years, we’ve made great progress but there are still some pretty big challenges to overcome before it’s safe to send humans in outer space for any length of time.&#160;Let’s have a look at some of them and what possible solutions scientists are working on.</p><p>Surviving Outer Space</p><p>Outer space is not a very human-friendly environment.&#160;If it was, we’d all be out there zipping from planet to planet, right?&#160;But if there’s one thing humans are good at, it’s problem-solving.&#160;Within your grand-parents and parents’ lifetimes, humanity has gone from sending a man in a “tin can” around the planet, to having a permanent space station where people live.&#160;That’s a big step.&#160;Let’s see what scientists are doing to reduce the dangers of space travel so humans can take their next leap in space.</p><p>NASA has made a list of “5 Hazards of Human Spaceflight” to outline the challenges and what they’re doing to overcome them.&#160;They are:</p><p>Radiation</p><p>Isolation and confinement</p><p>Distance from Earth</p><p>Gravity (or lack<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1362fc2f2667d2b34f10f76426c56e2e','space-travel-and-solar-system-m9-l3-lesson-2','b223f9c61494ecc607668504bf06c8ac','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Spacecraft Sub-System</h3><p>Spacecraft Sub-Systems</p><p>Can you name some of the subsystems a spacecraft would need to function?</p><p>Welcome back, this is Video 2 of this module on Spacecraft Technology.</p><p>In the first section, we looked at what a spacecraft would need to keep human passengers alive. You also learned about the biggest dangers that face humans in deep space and some possible solutions to overcome them. Now, you’re going to learn about the mechanics of it all. How does a spacecraft function? What kind of systems does it need?</p><p>Think about the things that a spacecraft must do. Video 1 had a lot of interesting things to say about that. In everyday terms, a spacecraft needs to be able to move, navigate, and communicate. Then, if it’s carrying life forms (human, animal, or plant), it also needs to keep them alive and protect them against the dangers of space. As you can imagine, spacecrafts are complex machines with many systems all interacting together to ensure everything works safely. Let’s have a closer look.</p><p>Imagine you’re building a soapbox car. Here’s a nice one in action. The first thing you need to build is the body of the car. On a spacecraft, that’s called the bus, which is essentially the structure of the craft that provides space for the payload. The payload is everything that’s needed to complete a mission so it can vary a lot, but it can include for example, a crew, scientific equipment, and smaller crafts to be deployed. In the soapbox car, you would be the payload.</p><p>In order to stay comfortable and safe, you would need to add a few things like a seat, preferably a nice padded one, and a roll bar wrapped in foam or rubber to protect your head and neck in case your car rolls over. That means, the body or the bus also has to be solid enough to protect the payload and be able to withstand the forces applied to it. After all, you wouldn’t want to hit a bump in the road and go flying because your seat has detached from your car, right?</p><p>In space, these forces are even more extreme and the consequences much worse. So, on top of a padded seat and a roll bar, you would need a few extra things like a thermal control system. This is used to keep temperatures in the spacecraft at acceptable levels for the payload. And don’t forget about a life support system.</p><p>Now that your car has a nice body, you need to start looking at how it’s going to move. After all, it won’t go very far without other essential elements such as wheels, steering and breaks. Even though friction is different in space, the navigation system is essentially trying to achieve the same goal; controlling the movement and orientation of the vehicle. On your car, you might add a steering wheel while in a spacecraft, it might be a joystick like this one in the Space Shuttle. You’ll probably put your wheels on axles so you can turn and adjust your direction. Since they don’t touch the ground, spacecrafts usually rely on fins rather than wheels to adjust their trajectory.</p><p>Two subsystems help with the navigation: the attitude control and command and data handling (CDH) systems. Starting from what’s called the inertial frame of reference, which is when a body is not being impacted by any force, the attitude control system uses sensors and actuators to position the craft precisely in space. For example, it might ensure that a solar-powered spacecraft is always positioned to take the most advantage of the Sun’s energy. The CDH system is a bit like your brain as you’re driving your soapbox car. It receives messages, validates the information and distributes commands to other subsystems. You might not realize it but when you drive, you take into account all sorts of data like the road conditions, curves, people on the sidelines, etc. and you process that information very quickly to send commands to your hands and feet controlling the steering wheel and pedals.</p><p>So, your soapbox car looks awesome and has all the necessary parts to keep you safe… now what? Just like a soapbox car, a spacecraft can’t get itself into space alone. Both vehicles need a temporary boost. To get your car going, the muscle power of a few people should do the trick, especially if you start at the top of a ramp or a hill. But a spacecraft needs to escape the Earth’s atmosphere so it needs a bit more oomph! That’s where the launch system comes in. It includes a vehicle, generally a rocket, the pad, which is where the vehicle is attached with the spacecraft strapped to it, a fueling station and a few other subsystems, all working together to launch the craft into space.</p><p>Once in space, a craft might need to make some adjustments and will need to rely on its power to move. This is where the propulsion system comes in. Depending on the type of engine, it could have a tank to house fuel, and valves and pipes to distribute that fuel to thrusters, which would be controlled by the crew or computers to maneuver. Propulsion works closely with the power system, which is used to help the spacecraft move around and power all of the different subsystems that it relies on to function. This system could rely on solar energy, which would mean the need to attach solar panels that are deployed in space to collect sunlight. It could also rely on nuclear energy or batteries to supply power.</p><p>Soapbox cars rarely have any means of propulsion other than the power they get from launch or the incline of a hill but you could imagine one that would have a canister of nitrous oxide that you open at some point to give it extra speed. It could also have solar panels that feed a booster.</p><p>Finally, it’s possible you’ve gone all out and added some special features to your soapbox car but in general, a spacecraft needs a few extra components you won’t find on a car like a communication system for example. When in space, a craft and its crew might need to communicate with people on Earth and with other crafts. Even within a spacecraft, the subsystems communicate with each other making this last system one of the most important. Here’s an example of all the various communication systems used by the International Space Station to communicate with Earth and other spacecrafts. As you can see, there is a lot going on.</p><p>So, to summarize, a spacecraft needs the following components:</p><p>- A structure called a bus, capable of withstanding the impact of launch, re-entry, landing, etc. depending on the<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('aab71345f9fb995e711f56a74ea97871','space-travel-and-solar-system-m9-l4-lesson-3','b223f9c61494ecc607668504bf06c8ac','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Spacecraft Launches</h3><p>Spacecraft Launches</p><p>While watching this video,&#160;consider the following question:&#160;You’ve probably seen many rockets being launched into space by now on TV or the internet.&#160;How do you think it works?</p><p>Welcome back, this is Video 3 of this module on Spacecraft Technology.</p><p>As we look into the future and the possibility of sending spacecrafts further into outer space to colonize planets and moons, two functionalities are going to be even more crucial. First, their ability to maneuver.Second, the capability to take off, re-enter the Earth’s atmosphere, and land safely. Let’s have a look at the science behind these functionalities.</p><p>Without going too deep, let’s quickly talk about Newton’s laws of motion. The first law says that an object at rest, like a rocket sitting on the launch pad, is in a balanced state. As long as the force of gravity holding the rocket is equal to the force of the supporting ground, it’ll stay there.</p><p>Newton’s second law is about movement and the creation of an unbalanced state. It says that an object will move if the force applied to it is greater than the force holding it back. So, when the rocket gets ignited, the force generated will lift the spacecraft. As long as the force generated remains higher than the force of gravity, the spacecraft will continue to ascend. When the fuel is exhausted, the spacecraft will continue for a bit because of its momentum but it’ll start slowing down and eventually fall back down unless it’s far enough from the atmosphere.</p><p>Finally, the third law says that any force applied is met with an equal and opposite reaction. That means when the rocket takes off, it’s met with drag trying to hold it back. To make things a bit easier, engineers spend a lot of time thinking about the shape and the texture applied to a spacecraft. There’s a good reason why rockets all look similar. The cone shapes and the smooth texture of the components help reduce drag just like they do on airplanes and even cars.</p><p>Most spacecrafts never come back to Earth (at least in one piece!). Some go on to explore the rest of our solar system and other celestial bodies. But so far, the vast majority orbit the Earth. Did you ever wonder how they stay up there? What prevents the ISS or the thousands of satellites from falling back to Earth? After all, the planet’s gravity should pull them back, right?</p><p>Well, it does but it’s possible for objects to stay in orbit as long as they maintain a speed of 17,500 mph and orbit in the same direction as the planet spins (eastward). If their speed drops below that level, they’ll get too close to the upper layers of the atmosphere and get pulled back. That’s how satellites are “retired”. They enter the atmosphere where they burn up.</p><p>The push to build reusable spacecrafts is making re-entry a hot (pun intended!) topic and a lot of research is being done to try and make it as easy and as safe as possible. But before looking at that, let’s try to understand why it’s so difficult in the first place.</p><p>Ever heard of escape velocity? It’s the minimum speed at which an object can escape the gravity of a celestial body.</p><p>The minimum speed to escape gravity will vary depending on the body’s mass and radius but in the case of Earth, a spacecraft must reach a speed of at least 25,000 mph to make it into outer space.</p><p>Now let’s look at this in reverse. If it takes that much speed to escape the planet’s gravity, you can imagine that when an object gets close to the atmosphere, it’s going to be pulled towards the Earth. It’s a bit like magnets. If you hold two of them far from each other, they won’t cause attraction but as you bring them closer, the pull is going to get stronger.</p><p>At re-entry, when a spacecraft hits the upper atmosphere, it is going to be moving fast as its getting pulled by gravity. At that speed, an enormous amount of friction is created as it hits air molecules and, friction means heat. The temperature around the spacecraft can reach 3,000 degrees F as it falls through the atmosphere. And that’s one of the challenges of re-entry… making sure the craft and its crew stay safe. The destruction of the Space Shuttle Columbia in 2003 is a very sad reminder of what happens when heat protection is not sufficient. This tragic accident was caused by insulation that fell off during take-off and hit the left wing damaging the heat protection layer. Upon re-entry, the extreme heat was able to enter the wing, and melt the structure.</p><p>So how can spacecrafts avoid burning up in the atmosphere? The answer: a combination of shape and thermal protection. Let have a look at each element.</p><p>The design chosen for a reentry vehicle is not random. There’s a lot to consider. The spacecraft must:</p><p>- Be able to withstand extremely high and low temperatures.</p><p>- Be strong enough to survive the landing.</p><p>- Be able to slow down at a very precise rate. Too fast and it will be crushed.</p><p>- Be able to hit a very precise angle. Too shallow and the capsule will skip off the surface of the atmosphere. Too steep and the heat might be too high and it’ll burn up.</p><p>So, a lot of research goes into finding the most efficient, safe and maneuverable shapes. It’s not surprising then to see many crafts with similar shapes. The Apollo command module and the Russian Soyuz capsule are classic examples of what’s called the cone angle shape. They both have a concave bottom and the rest of the craft is tapered either like a cone or a bell. There are several scientific reasons behind that shape.</p><p>The bottom is turned towards the Earth during re-entry taking the biggest heat impact and allowing for deceleration. Pointing the blunt end this way also gives the astronauts more maneuverability.</p><p>Thermal protection and shape work together to keep the payload safe and as comfortable as one can be when flying through the atmosphere at incredibly high heat and speed. The tapering means the rest of the capsule gets less hot. The bottom pointed towards the Earth means the impact is concentrated and extra protection can also be applied there. But what does this protection look like and what can withstand a 3,000-degree heat?</p><p>Two processes have been used to provide spacecrafts with what’s called a heat shield:</p><p>Thermal soak: Ceramic tiles are soaked in a resin and then attached to the spacecraft. This was the met<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3dd9c1a611a85b5c7f0dcd2a6d2ea05c','space-travel-and-solar-system-m9-l5-lesson-4','b223f9c61494ecc607668504bf06c8ac','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Cost of Building Spacecraft</h3><p>Cost of Building Spacecraft</p><p>When you see one of SpaceX’sspacecrafts launch into orbit, have you ever stopped to consider how much it cost to build?</p><p>Welcome back, this is Video 4 of this module on Spacecraft Technology.</p><p>Building spacecrafts is very expensive and almost all of them are expendable, which means they’ll be used only once. This presents a significant challenge for those who have plans to build colonies on other celestial bodies. Using a new spacecraft every time would make the cost too great. So, NASA and other companies like SpaceX, who plan to set up colonies on Mars, are now looking to build reusable rockets. Let’s see how that would change space exploration.</p><p>How many times a year do you think your parents go to the grocery store? Well, the average American went 1.6 times a week in 2018. Multiply that by 52 weeks and you get a total of just over 83 visits a year. Now, are you sitting? Imagine that every time you visit the supermarket, you abandon your car and go buy a new one. Sounds crazy, right? At the end of the year, you would have a mountain of cars and have spent a lot of money.</p><p>Well, until now, except for the Space Shuttles, that’s exactly what space exploration has done. Thousands of spacecrafts have been launched into space and their components like booster rockets, are either floating in orbit or further out in space, abandoned on other celestial bodies or have made their way back to Earth to burn in the atmosphere and never be used again. Even the Space Shuttle program wasn’t entirely reusable since its shuttles didn’t come back with the booster rocket. Considering the cost of a spacecraft can vary between hundreds of millions to billions of dollars and that launching it into space costs additional millions, you can see how much of a waste of money, resources, and energy it represents.</p><p>Ever heard of the 3 Rs? If not, they’re the basic principles of sustainability. To counteract the increasing amount of waste being shipped to landfills, the 3Rs tell us to reduce, reuse, and recycle. Well, how about applying the same principles to space?</p><p>That’s exactly what more builders (government and private) are trying to do by developing spacecrafts that can, at least partially, be reused. This in turn also reduces the number of resources being used. Their prime target at the moment is what’s called the first stage rocket, which is the large tube filled with fuel that gets the spacecraft up into or above the atmosphere. It is also the most expensive component! For example, SpaceX’s Falcon 9 rocket costs about $30 million dollars.</p><p>As Elon Musk said at a conference in 2016:</p><p>&quot;I tell my team: imagine there&#39;s a palette of cash that was plummeting through the atmosphere and it was going to burn up and smash into pieces. Wouldn&#39;t you try to save it? Probably yes.&quot;</p><p>Here’s a graphic that shows how SpaceX is trying to save its first stage rockets. On the left, you can see the spacecraft ascending. When it leaves the atmosphere, the rocket booster detaches itself and while the Dragon continues towards its destination, to deliver a payload to the ISS in this case, the Falcon 9 flips around and returns to Earth where it lands on a platform. Not only is the landing of the 230 feet tall Falcon 9 impressive from a technical point of view but experts also estimate that reusing it could slash 30% off the cost of launching payload, not to mention reducing the debris floating in orbit or reentering the atmosphere.</p><p>Transporting a pound of payload to low Earth orbit (LEO) has cost around $10,000 dollars for decades. The use of SpaceX’s Falcon Heavy, which will be able to lift three times as much as the Falcon 9, will reduce that cost to $638 dollars per pound. This is possible because reusable rockets will make the cost of building the Falcon Heavy only 33% more than the Falcon 9. So, there are a lot of advantages to reusable rockets.</p><p>One of the driving forces behind the race to reduce costs by making some spacecraft components reusable is space tourism. Currently, the cost of a ticket to fly in LEO would be somewhere between $200,000 and $250,000 dollars. As you can imagine, there aren’t too many customers with that kind of money. Reducing the cost of launching spacecrafts by reusing the first stage rocket, could open the door to more space tourists. It also means more opportunities like the creation of colonies on the Moon and Mars, and asteroid mining.</p><p>Some companies are already going further by developing fully reusable spacecrafts. Virgin Galactic is testing the WhiteKnightTwo, a carrier aircraft, and the SpaceShipTwo, that can take tourists into LEO. As you can see in this image, the SpaceShipTwo is attached in the center. In this image, you can see the WhiteKnightTwo returning after releasing the SpaceShipTwo at 50,000 feet. Both vehicles can glide back down for a runway landing making them fully reusable.</p><p>So far, SpaceX and Blue Origin’s spacecrafts have been unmanned. The only crewed space flights are Virgin Galactic’sSpaceShipTwo tests. But in 2014 one of these test flights ended in tragedy killing one of its two pilots and it wasn’t even in space. So, adding a human crew and sending them into space will raise the risk and costs and the further they go, the higher the risk.</p><p>Some of the risks come from the technology itself. Some experts at NASA for example, have expressed their concerns about the way fuel is handled on the Falcon 9. The engineers at SpaceX have come up with an ingenious way to pack more into the rocket. They keep it at extremely cold temperatures to shrink its size allowing them to add more propellant. The danger comes from the fact that to use this method, the fuel has to be loaded at the last minute, when the crew is already on board. This means, if anything happens, like a spark, it could lead to an explosion that would kill the entire crew.</p><p>A Falcon 9 rocket blew up in that manner in 2016. Thankfully, it wasn’t crewed. But the rocket and the payload, a multimillion-dollar satellite, were destroyed. While some of the companies pushing the boundaries of space are more open to embracing risk, organizations like NASA, are a lot more cautious and conservative when it comes to human life and the destruction of technology that has costs millions and billions of taxpayers’ money.</p></section><section><h3>S<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7e0faba0c7c1358baa1a204c9e2c9642','space-travel-and-solar-system-m9-l6-lesson-5','b223f9c61494ecc607668504bf06c8ac','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Future of Spacecraft Design</h3><p>Future of Spacecraft Design</p><p>Spaceplanes, capsules, the Enterprise, X-wings?&#160;What do you think the future of spacecraft design will look like?</p><p>Welcome back, this is Video 5 of this module on Spacecraft Technology.</p><p>To look forward into the future, it helps to know where we’ve come from. So, before thinking about where we are now or where we’re going, let’s take a few moments to see where we started. For this video, we’ll focus on spacecrafts that were designed to carry humans into space, but it’s important to remember that the first true spacecraft, in the sense that it left the Earth’s atmosphere and lingered in orbit, was Sputnik 1, way back in 1957. In fact, the launch of Sputnik is what started the space race between the US and the Soviet Union.</p><p>The first spacecraft that took a human being into space was the Vostok 1. It carried the Soviet cosmonaut Yuri Gagarin into orbit around the Earth in April of 1961. A month later, it was American Alan Shepard’s turn to travel around the Earth in the Mercury Freedom 7. Both ships were variations on the space capsule design, with Gagarin’s Vostok having a spherical landing capsule, while the Freedom 7 was clearly the older sibling of the landers that would eventually go to the Moon.</p><p>The next spacecrafts to leave Earth’s orbit were all part of the Mercury or Vostok programs. In total, there were six Vostok flights between 1961 and 1963 and roughly the same number of flights for the Mercury program at about the same time.</p><p>Project Gemini, which ran between 1961 and 1966, was a bridge between the Mercury and Apollo programs. It had several specific goals:</p><p>- First, to extend the time astronauts spent in Earth orbit for an eventual Moon landing. The goal was to hit between eight days and two weeks.</p><p>- Second, to practice meeting and docking with other spacecrafts.</p><p>- Third, to perform activities outside the spacecrafts like spacewalks, to see what humans were able to do.</p><p>- Fourth, to practice and perfect re-entry and landing techniques</p><p>The ten crewed Gemini missions included such firsts as a spacewalk by an American and the first space rendezvous when Gemini 6A and 7 met up in space. In terms of design, the Gemini capsule was very similar to previous programs but it was capable of carrying not one, but two crew members.</p><p>During Project Gemini, the Soviet Union was accomplishing many of the same tasks, including the first spacewalk by Alexei Leonov in 1965 and docking between Soyuz 4 and 5, which featured the first in-orbit crew transfer.</p><p>From then on, all eyes turned to the Apollo program, which ran between 1961 to 1972. At its height, the program employed 400,000 people and relied on the support of 20,000 companies and universities. Starting with the disastrous 1967 Apollo 1 mission, where all three astronauts were killed on the launch pad, to Apollo 11, which landed on the Moon, through to 1972’s Apollo 17, the last mission to the Moon, Apollo dominated the space race.</p><p>In terms of design, Apollo capsules were direct descendants of the Mercury and Gemini modules, and they remained largely unchanged throughout the entire program.</p><p>The Soviet Union also had plans to land on the Moon. Their Soyuz program was designed for that purpose but once the US beat them there, they changed their focus towards establishing permanent stations in space. If the name Soyuz sounds familiar, it’s because we still hear it today since the Russian space agency is still using them to send people and supplies to the International Space Station.</p><p>This brings us to what can be considered the modern age of space travel, which can be divided into two main themes: space planes and capsules.</p><p>In 1972, US President Richard Nixon announced that NASA was developing the first reusable launch vehicle, the Space Shuttle. This program would become NASA’s only crewed spacecraft until the program ended in July of 2011. It featured many exciting firsts, including many science experiments, satellite deployments, as well as helping build and then transport crew and supplies to the ISS.</p><p>At the time, the design of the Space Shuttle was quite revolutionary. It was the first time, and last until recently, that a spacecraft could land just like a regular airplane. It was made of an orbiter (the plane-like craft) containing the payload, an external tank (the orange tube in the middle, and two solid rocket boosters. The only expendable part was the external tank. The two rocket boosters were dropped after two minutes and deployed parachutes to land in the ocean where they were recovered.</p><p>The Russian Space Agency also designed a similar space shuttle called the Buran. While one of their spacecrafts, the Orbiter OK-1K1, achieved an un-crewed orbit of Earth, the program was effectively ended by a combination of the end of the Soviet Union and a huge storm that destroyed the spacecraft and its hanger.</p><p>Even as it was developing the Buran shuttle, the Russian space program continued to work on space station technology and to refine the design of the highly reliable Soyuz. While NASA gets a lot of attention, especially in the English-speaking world, the fourth generation of Russian Soyuz has been a very important player in the construction and maintenance of the ISS, especially since the US no longer has a crewed space program. Without the Soyuz, Americans couldn’t make it to the ISS.</p><p>This era has also seen the rise of non-state space agencies. The most famous, and successful of these, is Elon Musk’s SpaceX. Currently, they are the only non-Russian space program that is capable of resupplying the ISS and are expected to be able to send replacement crews by 2020. The company is also working on heavy lift rockets with NASA to ensure the US space program no longer has to rely on the Russians to get into space.</p><p>So, we know where we’ve come from, we know the state of play right now, but what about the future?</p><p>In the near term, the development of the SpaceX Interplanetary Transport System (also called the Big Falcon Rocket or BFR) will continue with the goal of eventually colonizing Mars. The BFR includes the Super Heavy launch vehicle, the Starship passenger, and the tanker and cargo spacecraft. The Super Heavy is designed as a two-stage rocket. The top half, Starship, would be pushed into space by the first stage, the ac<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c1b641fec9b7e29e8396886b88de5e59','space-travel-and-solar-system-m9-l7-module-9-summary','b223f9c61494ecc607668504bf06c8ac','Module 9 Summary','text',12,'<h2>Module 9 Summary</h2><section><h3>Module 9 Summary</h3><p>Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Spacecraft Technology!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Described the difficulties of human space travel that must be addressed in spacecraft design</p><p>Listed the subsystems of spacecraft and defined the function of each one</p><p>Summarized the technology and science that enabled rocket propulsion and spacecraft re-entry</p><p>Examined the risks, costs, and potential of reusable rockets</p><p>Compared historical and current spacecraft with possible future designs that may support interplanetary and interstellar travel</p><p>Evaluated a day in the life of an astronaut on a spacecraft or space station, describing elements of the spacecraft that allow humans to survive and work</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('65bf227c7ee0bad5e8424b7999f02f25','space-travel-and-solar-system-m9-l8-module-9-assignment','b223f9c61494ecc607668504bf06c8ac','Module 9 Assignment','text',12,'<h2>Module 9 Assignment</h2><section><h3>Module 9 Assignment</h3><p>3300</p><p>Space Travel</p><p>Spacecraft Technology - Short Answer Assignment</p><p>Short answer assignment</p><p>The life of an astronaut on a spacecraft is very different from one spent on Earth and certainly different than our daily lives. In this assignment, you’re going to explore what it means to live in space. Start by looking at the following articles.</p><p>A Day in the Life of Astronauts on the ISS</p><p>Living aboard the International Space Station (ISS) is an extraordinary experience that requires strict schedules, adaptability, and a strong sense of teamwork. In this article, we explore a typical day in the life of an astronaut, from morning routines to work, exercise, and sleep.</p><p>Morning Routine:&#160;As the space station orbits the Earth, astronauts wake up to a carefully planned schedule. Upon rising, they begin their morning routine, which includes personal hygiene tasks such as brushing their teeth, washing their face, and grooming. Due to the lack of gravity, astronauts use special &quot;no-rinse&quot; hygiene products to maintain cleanliness. They also take care to change into their daily clothing, typically consisting of comfortable shirts, shorts, and socks.</p><p>Breakfast and Mealtime:&#160;After completing their morning routine, astronauts head to the galley, a small kitchen area aboard the ISS. Meals are carefully prepared, packaged, and sent to the space station, providing astronauts with a variety of nutritious options. Foods are specially processed to ensure they can be safely consumed in a microgravity environment. Astronauts rehydrate their food, warm it if necessary, and enjoy their meals using Velcro and duct tape to prevent items from floating away.</p><p>Working on Experiments and Tasks:&#160;With breakfast consumed, astronauts begin their workday, which involves conducting scientific experiments, maintenance tasks, and other assigned responsibilities. Each astronaut has specific duties based on their expertise and ongoing research objectives. They work in collaboration with scientists on the ground to gather data, perform tests, and monitor experiments that contribute to our understanding of space and its effects on the human body.</p><p>Exercise and Physical Fitness:&#160;Maintaining physical fitness is crucial for astronauts living in microgravity. Regular exercise helps counteract the muscle and bone loss experienced in space. The ISS is equipped with exercise equipment such as treadmills, stationary bikes, and resistance machines specifically designed for use in a weightless environment. Astronauts spend a dedicated portion of their day engaging in cardio and strength exercises to preserve their health and well-being.</p><p>Free Time and Communication:&#160;In their limited free time, astronauts have the opportunity to connect with their loved ones on Earth through email, video calls, or social media. They may also engage in personal hobbies, such as reading, listening to music, or taking photographs of Earth. Some astronauts participate in educational outreach activities, conducting experiments that school children can follow and learn from back on Earth.</p><p>Working and Sleeping in Space:&#160;The workday aboard the ISS is structured, with specific time allocated for various tasks. Astronauts carefully document their work, record observations, and ensure the accurate collection of data. The ISS operates on Coordinated Universal Time (UTC), allowing astronauts to align their schedules with mission control centers around the world. After a full day of work, astronauts prepare for a good night&#39;s sleep. They strap themselves into sleeping bags that are attached to the walls of their crew cabins to prevent drifting during sleep. A sleep schedule of around eight hours is essential to ensure proper rest and rejuvenation.</p><p>A day in the life of an astronaut aboard the International Space Station is a meticulously planned and executed routine. From morning routines and mealtimes to working on experiments, staying fit, and enjoying free time, astronauts adapt to the unique challenges of living and working in microgravity. Their dedication to scientific research, maintaining physical fitness, and nurturing personal connections on Earth exemplifies the extraordinary commitment required to explore and understand the mysteries of space.</p><p>Daily Life of Astronauts in Space: Balancing Work, Health, and Exploration</p><p>Living and working in space is a remarkable experience that requires meticulous planning, adaptability, and collaboration. This article delves into the daily life of astronauts aboard the International Space Station (ISS), highlighting their routines, tasks, and the challenges they face while conducting groundbreaking research and pushing the boundaries of human exploration.</p><p>Morning Rituals:&#160;Astronauts begin their day in space by waking up according to a carefully structured schedule. They follow a personal hygiene routine that includes brushing their teeth, washing their face, and using specially designed &quot;no-rinse&quot; products to maintain cleanliness in the microgravity environment. After dressing in comfortable clothing, they prepare themselves mentally and physically for the day ahead.</p><p>Nutrition and Meals:&#160;Breakfast on the ISS is an opportunity for astronauts to replenish their energy levels and prepare for a productive day. Meals are meticulously planned, packaged, and transported to the space station, ensuring a balanced diet rich in nutrients. Astronauts rehydrate and warm their meals, often using Velcro and fasteners to prevent them from floating away in the weightless environment.</p><p>Work and Scientific Endeavors:&#160;The primary focus of an astronaut&#39;s day is conducting scientific experiments and research. Each astronaut has specific tasks aligned with ongoing mission objectives and collaborations with scientists on Earth. They meticulously follow protocols, document observations, and collect data that contribute to a deeper understanding of space, human health, and the potential for future space exploration.</p><p>Physical Fitness and Exercise:&#160;Maintaining physical fitness is crucial during extended stays in space. Astronauts devote a significant portion of their day to exercise, using specially designed equipment such as treadmills, resistance devices, and exercise bicycles. Regular workouts help counteract muscle and bone lo<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4612d8f8c26cda988082f2b4a0f48164','space-travel-and-solar-system-m9-l9-module-9-project','b223f9c61494ecc607668504bf06c8ac','Module 9 Project','text',12,'<h2>Module 9 Project</h2><section><h3>Module 9 Project</h3><p>3300</p><p>Space Travel</p><p>Spacecraft Technology - Project</p><p>Project</p><p>Begin by expanding the section below to read the article. Then read the instructions that follow for the assignment details.</p><p>The Gut Microbiome: A Critical Consideration for Deep Space Travel</p><p>As humanity looks towards long-duration deep space missions, new research highlights the impact of space travel on the gut microbiome of astronauts. The delicate balance of microorganisms residing in our digestive system plays a crucial role in our overall health and well-being. This article delves into the emerging understanding of how deep space travel affects the gut microbiome and the potential implications for astronaut health during extended missions.</p><p>The Gut Microbiome</p><p>Our Microbial Partners: The gut microbiome consists of trillions of microorganisms, including bacteria, viruses, fungi, and other microbes. This complex ecosystem influences various aspects of human physiology, from digestion and nutrient absorption to immune system regulation and even mental health. A diverse and balanced gut microbiome is crucial for overall well-being.</p><p>The Effects of Deep Space Travel on the Gut Microbiome</p><p>Studies conducted on astronauts aboard the International Space Station (ISS) have revealed significant changes in the gut microbiome during space travel. Microgravity, radiation exposure, altered diet, stress, and the use of antibiotics in space can disrupt the delicate balance of microbial communities within the gut. These disruptions may lead to a decrease in overall microbial diversity and potentially impact astronaut health.</p><p>Implications for Nutrient Absorption and Immune Function</p><p>The gut microbiome plays a pivotal role in nutrient absorption and the maintenance of a healthy immune system. Altered microbial composition and function due to space travel could impair these essential functions. Reduced nutrient absorption may result in nutrient deficiencies and compromised astronaut health. Furthermore, alterations in the gut microbiome can impact the immune response, potentially rendering astronauts more susceptible to infections and diseases during long-duration missions.</p><p>Psychological and Behavioral Effects</p><p>Mounting evidence suggests that the gut microbiome communicates bidirectionally with the central nervous system, influencing brain function and behavior. Changes in the gut microbiome composition during space travel may contribute to psychological and behavioral effects, including alterations in mood, cognition, and sleep patterns. These factors are critical to astronaut well-being and mission success.</p><p>Mitigating the Impact</p><p>Understanding the impact of deep space travel on the gut microbiome is essential for developing strategies to mitigate potential negative effects. Research is underway to identify methods to promote and maintain a healthy gut microbiome in space. This includes personalized nutrition plans, prebiotic and probiotic interventions, and the development of spacecraft environments that support microbial diversity and balance.</p><p>The Future of Gut Health in Space Exploration</p><p>As we venture into longer space missions, such as crewed missions to Mars, preserving astronaut health becomes paramount. Strategies to monitor and manage the gut microbiome during deep space travel will be crucial for maintaining crew well-being and optimizing mission success. Ongoing research, collaboration among space agencies, and innovative approaches will pave the way for advancements in understanding and addressing the challenges posed by the space environment.</p><p>The gut microbiome is a complex and vital component of human health, and its potential alterations during deep space travel warrant attention. As we push the boundaries of space exploration, it is crucial to prioritize the well-being of astronauts and understand the impact of space travel on their gut microbiomes. By comprehensively studying and developing strategies to maintain a healthy gut microbiome in space, we can safeguard the health and resilience of astronauts and enable successful deep space missions in the future.</p><p>In this assignment, you will create an infographic that describes the risks of radiation to space travel and possible solutions. Infographics are visual charts that take a complicated or boring topic and present them in a fun, quick, and visually engaging way. You can choose from a variety of web tools available to make your graphic.</p><p>Your infographic should:</p><p>Describe what radiation is and its effects on the human body</p><p>List the types of radiation in space and provide details of each</p><p>Discuss possible solutions to overcome radiation exposure by space travelers</p><p>Be creative and visually engaging</p><p>Have a title and be organized and succinct</p><p>Use citations when referencing facts or information you researched</p><p>Review the rubric below to see how you will be graded.</p><p>Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Content</p><p>8 points The infographic demonstrates a strong understanding of radiation&#39;s effects on space travel</p><p>7-6 points The infographic demonstrates a satisfactory understanding of radiation&#39;s effects on space travel</p><p>5-0 points The infographic demonstrates little to no understanding of radiation&#39;s effects on space travel</p><p>8</p><p>Supporting Information</p><p>6 points The infographic contains several specific and accurate details, including examples, solutions, and limitations.</p><p>5 points The infographic contains some specific and accurate details, including examples, solutions, and limitations.</p><p>4-0 points The infographic contains few to no specific and accurate details, including examples, solutions, and limitations.</p><p>6</p><p>Presentation</p><p>4 points The infographic is well organized and presented in an engaging way.</p><p>3 point The infographic is somewhat organized and is presented in a slightly engaging way.</p><p>2-0 points The infographic is not organized well or is not presented in an engaging way.</p><p>4</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors. All resources are cited as needed.</p><p>1 point Contains several spelling or grammar errors. Resources are cited as needed.</p><p>0 points Contains numerous spelling or gram<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f474267bbb9bf0a211645db89d16b668','space-travel-and-solar-system-m9-l10-module-9-quiz','b223f9c61494ecc607668504bf06c8ac','Module 9 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Spacecraft Technology. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('5e3d555b2f300c72f8f0ecc45f2746d7','space-travel-and-solar-system-module-10','2a892040eda1f32ee69b17d25aad96dd','Module 10: Intersteller Travel',10) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ad4aeee9c00c5c961ba38e910af20c18','space-travel-and-solar-system-m10-l1-introduction-purpose-and-objectives','5e3d555b2f300c72f8f0ecc45f2746d7','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi and welcome back. This is the intro video on Interstellar Travel.</p><p>Some of the most iconic space travel movies have always glamorized faster-than-light travel! Fans of Star Trek the next generation can fondly recall Captain Jean-Luc Picard saying, “Prepare for warp speed!” Or maybe if you are more of a Star Wars fan, and you get chills thinking about the Millennium Falcon making its jump into hyperdrive. Are these and other ideas of interstellar travel just wishful thinking, or is there any theoretical basis that could one day allow humankind to travel to distant stars?</p><p>This module will explore the reasons and motivations behind interstellar travel and some of the basic math and physics that underpin this field. And no one wants to get to another star, only to have no hope of setting roots down on another planet. So we’ll also look at the science of exoplanets and the breath-taking progress that is accelerating that field.</p><p>Then we’ll jump into the theoretical and creative ideas that physicists have drawn up for interstellar travel. We’ll see if there is any merit to ideas like sails, nuclear fusion, ramjets, and wormholes. No one said it would be easy, so we’ll look at the challenges and risks as well. Will we ever get to another star? Who knows? But it certainly can’t be done unless a new generation can understand the ideas that have come before them and use their creativity and imagination to come up with the breakthrough that may one day lead to faster-than-light travel.</p><p>Module Description</p><p>License:&#160;All Rights Reserved</p><p>The stars in the night sky sometimes look so close you can almost reach out and grab them.&#160;But with today’s technology and speed limits, it would take hundreds or thousands of human lifetimes to reach even the closest star.&#160;But that has not stopped humankind from dreaming, inventing, and writing about the possibilities of interstellar travel.&#160;Students will learn need-to-know terms such as astronomical units, light speed, exoplanet, propulsion, and g-force.&#160;Then it will describe theories of achieving interstellar travel, including the feasibility of an interstellar mission.&#160;This module will explore the limits of the galaxy and universe; the very edges of technology, physics, and science.</p><p>Objectives</p><p>In this module, students will</p><p>Identify the reasons and motivations behind interstellar travel</p><p>Define astronomical units, lightyear, propulsion, and gravity units</p><p>Examine the discovery of exoplanets and their possibility of supporting life</p><p>Discuss the feasibility of an interstellar mission given energy requirements, distances, and risks</p><p>Evaluate challenges to interstellar travel based on today’s technologies</p><p>Describe theories for interstellar travel, citing ideas from physics and science fiction</p><p>Polling Question</p><p>Based on what you know before starting this module, what do you think is the most feasible way to achieve interstellar travel?</p><p>Solar Sails&#160;Nuclear Technology&#160;Wormohles&#160;Warp Drives&#160;I&#39;m not sure, but I&#39;m excited to learn more in this module</p><p>Make a selection to see the results so far.</p><p>Let&#39;s see how your answer compares to your classmates!&#160;During the module, let’s explore the challenges and opportunities of interstellar travel!</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>travel between stars or planetary systems</p><p>Exoplanet</p><p>the distance between the earth and the sun.&#160;A unit of length used to measure distances within the solar system or other stars</p><p>g force</p><p>distance light travels in a vacuum in one calendar year</p><p>Light year</p><p>the force that attracts an object toward the center of the earth, or toward any other object having mass</p><p>Astronomical Unit (AU)</p><p>acceleration that causes an accelerating object to experience a force in the opposite direction of the acceleration</p><p>Goldilocks Zone</p><p>planets outside our solar system</p><p>Interstellar travel</p><p>refers to a habitable zone where the temperature is just right for water to exist on a planet</p><p>Gravity</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>travel between stars or planetary systems</p><p>Gravity</p><p>Light year</p><p>Goldilocks Zone</p><p>g force</p><p>Interstellar travel</p><p>Astronomical Unit (AU)</p><p>Exoplanet</p><p>2.</p><p>the distance between the earth and the sun. A unit of length used to measure distances within the solar system or other stars</p><p>Light year</p><p>g force</p><p>Interstellar travel</p><p>Gravity</p><p>Goldilocks Zone</p><p>Exoplanet</p><p>Astronomical Unit (AU)</p><p>3.</p><p>distance light travels in a vacuum in one calendar year</p><p>Goldilocks Zone</p><p>g force</p><p>Interstellar travel</p><p>Light year</p><p>Astronomical Unit (AU)</p><p>Exoplanet</p><p>Gravity</p><p>4.</p><p>the force that attracts an object toward the center of the earth, or toward any other object having mass</p><p>Exoplanet</p><p>Gravity</p><p>Astronomical Unit (AU)</p><p>Light year</p><p>g force</p><p>Interstellar travel</p><p>Goldilocks Zone</p><p>5.</p><p>acceleration that causes an accelerating object to experience a force in the opposite direction of the acceleration</p><p>Goldilocks Zone</p><p>Astronomical Unit (AU)</p><p>Exoplanet</p><p>g force</p><p>Light year</p><p>Gravity</p><p>Interstellar travel</p><p>6.</p><p>planets outside our solar system</p><p>Exoplanet</p><p>Light year</p><p>Interstellar travel</p><p>Astronomical Unit (AU)</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('76bac21bc70af8d5e2ac955050ffda79','space-travel-and-solar-system-m10-l2-lesson-1','5e3d555b2f300c72f8f0ecc45f2746d7','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Interstellar Challenges</h3><p>Interstellar Challenges</p><p>While watching, think about which hurdle you feel is the most difficult one scientists have to overcome.</p><p>Hi and welcome to Video 1 for this module on Interstellar Travel.</p><p>An appropriate question to start with when considering interstellar travel is simply: why? Sure, it seems interesting to read or watch science fiction and imagine what it would be like to skip across the galaxy from star to star. When we zoom out and think about the vast expanse of the universe which could be billions of lightyears across in size and contain one hundred billion galaxies, there is the natural human curiosity to explore and find out what is out there. But as we’ll see throughout this module, nothing close to this is even feasible given the technology we have today and our understanding of science and physics. Additionally, there are so many more immediate challenges to deal with, both on earth, and exploration to take place right here within our solar system. Why should humanity even bother with the lofty but unreasonable goal of traveling to other stars?</p><p>It’s certainly a valid question, so let’s explore what some scientists, philosophers, and authors have offered as reasons to explore, or even attempt to explore, other stars and planets outside of our solar system.</p><p>Let’s start with the most practical reasons.</p><p>First, the technologies used to make interstellar flight possible could also be used on earth. Dr. Andreas Tziolas is a former NASA research fellow and founded an organization called Icarus Interstellar, which is a non-profit organization dedicated to making interstellar flight possible.</p><p>In a 2016 article, he listed some key interstellar technologies. If these were developed successfully for interstellar travel, they would have a tremendous benefit on earth. Some of the ones he mentioned are:</p><p>- Solar power: harvesting energy efficiently from the sun to power an interstellar flight could yield enormous benefits for energy generation on earth.</p><p>- Fusion power: another clean energy innovation, solving the riddle of fusion power safely and efficiently could also help lead humanity away from fossil fuels.</p><p>- Renewable materials: a field called nanotechnologies is at the cutting edge of creating new materials that could be recycled and rearranged in an interstellar mission. The applications for this technology on earth for pharmaceuticals, energy, and science are endless.</p><p>- And finally, medicine: figuring out ways to allow humans to survive in deep space where radiation, among many other problems, are constantly attacking the human body. Breakthroughs in medicine could also have spillover effects and help with solving other complex diseases and health problems that we face on earth.</p><p>Beyond practical applications, there is an immense amount of scientific knowledge to be gained from exploring outside our solar system. True, we have satellites, probes, and other scientific instruments that have looked through the sky. We have and will continue to learn a lot from the images and information produced by these instruments, which for the most part have been on earth, in near-earth orbit, or within our solar system. In fact, only one human probe has ventured beyond Neptune and Pluto (back in the day, Pluto was considered a planet in our solar system). But it remains that we will be able to learn so much more about other stars by getting much closer.</p><p>So what is out there, and what can we hope to learn? The first thing to remember is that space between stars is pretty empty, but it’s not entirely void of any mass or particles. This mass is called interstellar medium. Again, from near-earth observation, we have an idea of what’s there, but if we can send probes through the interstellar medium, we can understand things like its density, composition, temperature, and radiation levels. This is important because we will need to know the properties of the materials that future interstellar missions (likely traveling at very high speeds) will be going through. Furthermore, understanding the mysterious dark matter and dark energy that exists between stars will help scientists unravel some of the fundamental questions around the origin and early development of the universe.</p><p>The author Ian Crawford summed it up well by saying “Space exploration presents a vast new field of activity with literally infinite potential for discovery and intellectual stimuli of multiple kinds, certainly a far richer range than we could ever hope to experience by remaining on our home planet.”</p></section><section><h3>Exploring Interstellar Travel</h3><p>Exploring Interstellar Travel</p><p>To begin this reading section, watch the following video which builds on reasons to explore and pursue interstellar travel:</p><p>So so far in this course, we&#39;ve been talking mostly about earth&#39;s orbit and maybe visiting the other planets. Now but as we&#39;ve talked about in the planets course really, our own solar system is, I mean, I think it&#39;s very interesting. But there are no planets with lush jungles. There&#39;s no intelligent life out there to meet. They&#39;re they&#39;re all near barren icy wastelands. Um, so really, what we could do with that being much more fun to go off and find a nice earth-like planet to do that we&#39;re gonna have orbiting another star. We&#39;re going to have to interstellar. So that means going to a new star rather than into planetary just going to a new planet exactly, you know, and as you said, it&#39;s nice to study the solar system like as an exhibit in the museum. But for holiday destinations you really have to go somewhere else. And that&#39;s going to be the the focus kind of ofof this part of the course. Which is the last part is the the challenges, and the opportunities, let&#39;s say that we present ourselves in traveling to a different star system. Now I think the first thing that we have to think about when we&#39;re talking about interstellar travel is it&#39;s a whole different ball game. Like, okay, I could ride a cycle. It&#39;s now saying I&#39;m gonna go ride in the tour de France. It&#39;s a very different set of challenges. One that is very in the realm of down-the-road possibilities. So we&#39;re really getting into more science fiction, that&#39;s right and then solid science at this point. I mean, at the moment, the furthest we&#39;v<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e510a05419b6b48ff427674920c2f4ad','space-travel-and-solar-system-m10-l3-lesson-2','5e3d555b2f300c72f8f0ecc45f2746d7','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Planet discovery Methods</h3><p>Planet discovery Methods</p><p>While watching this video, pay attention to the various creative ways that astronomers have been able to discover the existence of planets orbiting other stars.</p><p>Welcome back, this is Video 2 of this module on Interstellar Travel.</p><p>As of early 2017, NASA scientists from the Kepler program had identified over 4,000 planets outside of our solar system. These are known as exoplanets, or planets outside our solar system that orbit another star. And that&#39;s just in a quarter of one percent of the night sky!</p><p>But how is it even possible that these exoplanets are discovered? Even with the biggest telescope, you can imagine this is an extremely hard task to see something so far away. Well, first off, telescopes have come a long way since the days of Galileo. Even 100 years ago, the world’s largest telescope at the time was just about 8 feet long. Today’s instruments are much bigger and more precise. Some telescopes are even located in space in near earth orbit. Being out beyond earth’s atmosphere gives them a much clearer picture of the universe. But still, how do astronomers detect that exoplanets exist around a star? And can they assess things like planet size, location around its star, and whether or not it has water and an atmosphere? Let’s take a look at the 3 main ways that exoplanets are found: wobbles, ticks, and winks. (Those sound like characters from a kid’s show!)</p><p>The “wobbles” technique, or more precisely, the radial velocity technique, was used to discover the first exoplanet in 1989. To understand this method, let’s review the simple principle of gravity. The earth and other planets in our solar system orbit the sun due to the sun’s gravity and the fact that the sun is many times larger than all the planets in the solar system. But, even though we are smaller, the planets also have a small amount of gravitational effect on the sun, causing it to wobble. The theory goes that if our sun wobbles due to orbiting planets, other stars that wobble have planets as well. But how do we detect this “wobbling”? You’ve probably heard of the Doppler Effect. This is when a train moving towards you has a higher pitch than moving away from you. We can observe the same thing in the light spectrum from stars. When the star is moving towards us, its light emits slightly bluer colors. When it wobbles away, the light becomes redder. Astronomers can measure the difference in this red versus blue on the light spectrum and make calculations as to the size and orbiting distance of an exoplanet. It’s much easier to find larger planets this way because they produce more wobble. This was the primary way that exoplanets were found through about 2011.</p><p>Next, let’s talk about ticks. No, not the annoying little bugs. The tick, or pulsar timing, method is when an exoplanet is orbiting a specific type of star called a pulsar. It’s called this because it emits beams of radiation, sort of like a blinking flashlight. The flashes happen on a very regular basis. But because the pulsar will wobble a bit from its exoplanets, this timing is thrown off. So with extremely accurate measurements, astronomers can detect the orbiting planet by changes in the pulsar timing. But pulsar stars aren’t that common, so only about 18 confirmed exoplanets had been discovered with this method through 2014.</p><p>The 3rd&#160;method that we’ll cover in this video is the winks or transit method. Since 2012, this has overtaken the wobbles technique and become the most common way of finding exoplanets. First, let me explain what an orbital plane is. Planets orbit around a star in a relatively constant circle or elliptic. What direction this plane is facing depends on how a star and a star’s system was formed. Now from the vantage point of the earth, some stars have orbital planes that line up with earth, meaning that a planet will pass between its parent star and us. When a planet passes in front of a star, it blocks a small amount of its light. Now, as you would expect, the bigger the planet, the more light is blocked. The smaller the planet, the less light is blocked. Back in 2004, only 7 exoplanets were discovered this way. With the increasing sophistication of telescopes and other equipment, we’ve gotten much more precise at finding exoplanets in this manner. Fast-forward only 10 years to 2014, and over 700 exoplanets were observed and confirmed with the winks or transit method!</p><p>Exoplanet science is a fascinating branch of astronomy, and very important in the realm of interstellar travel. Knowing other planets are out there gives us an actual destination to go to. But that also brings up many other questions. Are any of the exoplanets capable of supporting life? More specifically, could they support human life? In this section’s reading, we’ll discuss the habitable zone and other conditions necessary for life on other planets.</p></section><section><h3>Discovering Planets with James Webb Telscope</h3><p>Discovering Planets with James Webb Telescope</p><p>Before diving into more details on exoplanets, watch a segment from this video, which describes the James Webb space telescope, and how it is making Exoplanet discovery possible:</p><p>[Music][Applause]Galaxies are the building blocks of the universe. The giant galaxies we see today, even our own, were built up from many smaller galaxies. But construction isn&#39;t done yet. It continues even today. Full-grown galaxies approach and interact with each other they may collide and eventually merge. As the galaxies approach, the tug of gravity creates tides that distort their shapes. Stars and gas stream into new orbits. Sometimes they&#39;re completely ejected, trailing into the depths of intergalactic space. Gas clouds compressed in the chaos light up with intense rounds of star formation. Because stars create most of the chemical elements, such episodes have a profound effect on a galaxy&#39;s chemical makeup. This infrared image of the entire sky shows half a billion stars. Most are in our galaxy. Some are not. These are companion galaxies that orbit our Milky Way. And some are in between. In 1994, astronomers discovered that some of these stars actually belonged to a different galaxy. It&#39;s called a Sagittarius dwarf elliptical. And the Milky Way is tearing it apart. As the dwarf galaxy passes through the Milky Way&#39;s disk, gravitational tides stretch the dwarf st<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('296f6574f62fea8d9ac392716afddfad','space-travel-and-solar-system-m10-l4-lesson-3','5e3d555b2f300c72f8f0ecc45f2746d7','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Distances and Time for Interstellar Mission</h3><p>Distances and Time for Interstellar Mission</p><p>While watching this video, think of all the immediate challenges that we have with getting things into space (rocket science) and planning crewed missions to the moon or mars.&#160;Now expand these challenges exponentially when considering the distances and length of time required for an interstellar mission!</p><p>Welcome back, this is Video 3 of this module on Interstellar Travel.</p><p>Ok, so with the rapidly evolving science of exoplanet discovery, we will start narrowing down the best locations that could serve as a second earth. We just need to pack our bags, “fire up the engines” so to speak and get on with it, right?! Well, I hate to throw some cold water on the enthusiasm, but let’s take a step back and assess some of the major challenges to human interstellar travel. This is before we even consider the real and theoretical ways to get there. These challenges include distance, cost, and risk to humans.</p><p>The planetary system Trappist-1, which holds the most habitable-zone planets, is a whopping 235&#160;trillion&#160;miles away. That would take 39 years traveling at the speed of light to reach. Even the closest star to earth, Proxima Centauri, which also has an earth-sized exoplanet, is still 4.3 light years away. If we look at it in terms of AU, it is 268 thousand AU away, or over 9,000 times farther away than Neptune. What’s the problem with these distances? No spacecraft ever built can travel anywhere near fast enough to get there in a human lifetime. If the Voyager 2 probe, which left our solar system back in 2012 had gone in the direction toward Proxima Centauri, it wouldn’t reach there for another 75 thousand years!</p><p>Perhaps the biggest complaint about pursuing interstellar travel is how darn expensive it would be. Not millions- that&#39;s petty change compared to the numbers that economists speculate- not billions either- we are talking potentially TRILLIONS- maybe even a hundred trillion dollars to make an interstellar program happen. And that money must come from somewhere. Who wants to pay more taxes?</p><p>Another argument: humans are too fragile and needy. People with this view tend to be in favor of sending unmanned probes beyond our galaxy. Taking humans out of the equation makes the spacecraft much smaller (no food, water, supplies, living space, and other necessities) and therefore more efficient. It also takes away problems like anti-gravity on human health and exposure to extraterrestrial microbes. It&#39;s hard to predict what kind of microbes could exist on other planets that our bodies are not capable of fighting. What happened to the Native Americans when Europeans first started colonizing America is a bleak reminder that our bodies take time to adapt to foreign pathogens.</p><p>Without the protection of the Earth&#39;s atmosphere and magnetic field, radiation in space can cause cancer in a hurry.</p><p>Furthermore, no gravity wreaks havoc on the body after a time. Even following an exercise regimen, crew members of the International Space Station lost muscle volume and peak power after six months on the ISS. Then there&#39;s the question of what kind of toll that would take on the human mind. No one knows the psychological effects that could come from an extended mission because no one has ever had to endure one. But it&#39;s safe to say that it would be mentally taxing being on a cramped spacecraft for months, if not years at a time.</p><p>Food and water aren&#39;t available at grocery stores in space. That means it would all have to come from the spacecraft itself. Growing food is very difficult in zero G. Not to mention, it would take up a considerable amount of room on the spacecraft.</p><p>Current waste-water filtration systems, like those used on the ISS, need maintenance. Sometimes they need new parts. It would be very difficult to anticipate all the maintenance and spare parts needed to make the water filtration work in deep space for the duration of an interstellar flight. Although, advancing technologies like 3D printing of spare parts may make this less of a challenge. But because of the time involved, the technologies in an interstellar mission must be able to self-repair and/or be 100% reliable.</p><p>Even if the spacecraft did manage to get to a planet, scientists would have to know exactly what the gravity of that planet was like in order to safely land. Considering the speed that the spacecraft would likely be traveling at when it arrives at the planet, slowing it down without a crash landing would take precision.</p><p>This is just a sampling of the issues that scientists, engineers, and physicists must overcome to make interstellar travel happen. There are likely more problems that no one has even thought of too. Despite the immense problems, there are still scientists working to make interstellar travel happen.</p></section><section><h3>Challenges of Manned Interstellar Travel</h3><p>Challenges of Manned Interstellar Travel</p><p>License:&#160;All Rights Reserved</p><p>Imagine being part of the first ever interstellar exploration mission to an identified Earthlike planet.&#160;Imagine the view of a brand-new planet as it fills up the viewport.&#160;It&#39;s more beautiful and amazing than you could ever imagine.&#160;So what is standing between you and this dream?&#160;In short, a whole lot of science, each and every step of the way.</p><p>Mankind has always been fascinated by the idea of interstellar travel, venturing beyond our solar system to explore distant worlds.&#160;However, the pursuit of manned interstellar travel is riddled with formidable challenges and limitations.&#160;Let&#39;s delve a bit deeper into the complexities and current understanding surrounding the feasibility of manned interstellar travel, examining the scientific, technological, and physiological obstacles that stand in our path.</p><p>Let&#39;s take a look at a few of the things standing in our way as we work on developing interstellar travel opportunities.&#160;Expand each section below.</p><p>The Limitations of Speed</p><p>One of the fundamental challenges in interstellar travel is the vast distances involved. Even with our current propulsion technologies, achieving the necessary speeds to reach nearby star systems within a human lifespan remains a significant hurdle. However, recent advancements in theoretical physics, such a<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('faa045fc54dd557d53818aa4f8f4ec46','space-travel-and-solar-system-m10-l5-lesson-4','5e3d555b2f300c72f8f0ecc45f2746d7','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Interstellar Travel Methods</h3><p>Interstellar Travel Methods</p><p>While watching this video, pay attention to the opportunities, challenges, and risks of each proposed interstellar travel method.</p><p>Welcome back, this is Video 4 of this module on Interstellar Travel.</p><p>All right, we’ve already discussed some of the massive difficulties of interstellar travel including the unfathomable distances, the exorbitant costs, and the risk to human health. But where’s the fun if we stop there? Assuming solutions get worked out for those challenges, there’s still the actual question of getting there. It’s a question of technology to move an object from point A to point B. In this video, we’ll look at some propulsion technologies, to see if they have any merit.</p><p>What about the basic rocket propulsion that is used to get astronauts in space today? Can’t we just burn up more and more fuel until we accelerate a ship to the speed of light? Unfortunately, that process is highly inefficient and would not generate anywhere near the amount of thrust needed for interstellar travel on any reasonable timetable. The fastest a chemical rocket could get to is 10% of the speed of light.</p><p>This is also compounded by the same fuel problem that we have when blasting a rocket from earth. More fuel equals more weight, which requires more fuel to accelerate. This is why we say this process is inefficient. While this brute force method may be the technology that gets us to the moon, Mars, and maybe someday moons of other planets, it does not seem like a reasonable candidate for interstellar propulsion.</p><p>Nuclear propulsion is more efficient and provides more thrust than chemical propulsion used in rockets today. Nuclear fusion rockets would harness the energy released when two nuclei combine. The sun and stars are fusion-powered, and in theory, our rockets may soon be too.</p><p>The flip side of nuclear fusion is nuclear fission, also known as splitting atoms. Inside an atom, is a nucleus consisting of positively charged protons and neutral neutrons, orbited by electrons. Protons, neutrons, and electrons, are collectively known as nucleons. When the bonds between the nucleons break, a large amount of energy is released.</p><p>Of all the technologies discussed in this module, nuclear propulsion is probably the one that scientists are closest to making a reality. Nuclear energy, whether through fusion, fission, or otherwise, is more efficient and provides more thrust than conventional chemical propulsion. Right now, however, this is a proposed solution more for interplanetary travel rather than interstellar travel.</p><p>The most difficult part is creating a reactor that does not use more energy than it creates. Scientists have yet to figure out how to do that! While here on earth we have nuclear power plants, the technology still has a long way to go before it can be used to power a spaceship. Plus, there’s still a ban on sending nuclear materials into space!</p><p>Other variations in the nuclear category include ion propulsion, nuclear electric thrusters, nuclear pulse, and nuclear thermal propulsion. A final wildcard is an antimatter engine. When antimatter and matter come in contact, they annihilate each other. This process releases a tremendous amount of energy. There are still massive practical challenges to this though, such as generating antimatter in large enough quantities and making sure the explosion occurs when we want it to.</p><p>Interestingly, interstellar theories have borrowed a key component of maritime travel- sails! There are all kinds of sails proposed for interstellar travel. Solar, beamed, magnetic solar wind, and electric solar wind are all proposed methods. Although where they derive most of their propulsion is different, they all operate on the idea of creating a sail, attaching it to a spacecraft and receiving a “push” from the energy, in the form of solar photons or laser beams. These sailing concepts would provide another way to travel without having to take massive amounts of fuel along. Let&#39;s look at solar and laser, in particular.</p><p>A solar sail would work by a large, thin sail that would get a push from sunlight. The sun gives off photons which have energy but no mass. A close pass by the sun could accelerate a spacecraft with a solar sail enough to get to the outer solar system or even Alpha Centauri, the nearest star system from us.</p><p>A massive laser pointed at a&#160;laser sail&#160;would provide even further momentum than that of a solar sail. A laser would enable the photons to be focused enough that they provide even more energy than solar photons.</p><p>But is the sail concept actually feasible? It is possible for the right kind of sail to harness the photon energy emitted from the sun or from a laser and glide across the galaxy. In other words, the science all checks out. One of the great benefits of these methods is that there is no need to carry the necessary fuel on the spacecraft. The proposed sails would also be much faster than conventional rockets, perhaps up to 20 or 30% of the speed of light.</p><p>As we said, solar sails work best closer to the sun, but the effect starts to diminish as the spacecraft gets farther away. One way to address this is to create a laser and send it to somewhere like one of Jupiter&#39;s moons to keep the spacecraft accelerating as it gets farther from the sun. The more complex issue is building a sail big enough to gain the kind of distance we want. We are talking about sails that are miles wide! As well as a laser with enough power for the job. Although these technologies are probably a long way into the future, they work comfortably with the physical laws scientists already know.</p></section><section><h3>Chemical Rockets &amp; Nuclear Methods</h3><p>Chemical Rockets and Nuclear Interstellar Travel Methods</p><p>For this section’s reading, we’ll start by checking out a video that recaps the first two methods (chemical rocket and nuclear).&#160;Then, we will look at a unique option for using sails to get to another star in our lifetime.</p><p>First, watch a segment of the video below that discusses the impractical rocket option as well as nuclear/antimatter options:</p><p>Is interstellar travel possible? I mean, it&#39;s a fair question. it&#39;s a fair question, and of course, there&#39;s nothing like physically preventing travel to another star. Like there&#39;s, there&#39;s no law of <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3dabc40ab869a71c8c076cea8311da11','space-travel-and-solar-system-m10-l6-lesson-5','5e3d555b2f300c72f8f0ecc45f2746d7','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Required Technology Developments</h3><p>Required Technology Developments</p><p>While watching, think about what technologies scientists need to develop for each theory.</p><p>Welcome back, this is Video 5 of this module on Interstellar Travel.</p><p>Now let’s move beyond the practical and really use our imaginations for this next section. After all, many great discoveries and inventions once started out as impossible. But through imagination, brainstorming, hard work, and luck, previous generations of scientists were able to give us the technologies that we enjoy today. Could we have a similar breakthrough in the future that will enable one of these technologies to take us to another star system? Only time will tell, but for now, let’s find out what the dreamers have to say regarding warp speed, wormholes, and the ramjet.</p><p>Let’s start with the Bussard Interstellar Ramjet, because it also deals with the concept of propulsion. This theory focuses on hydrogen fusion propulsion. In Bussard&#39;s theory, an electromagnetic scoop collects interstellar hydrogen and uses hydrogen fusion to drive the spacecraft. So there’s no need to take the hydrogen along with you! In this theory, the spacecraft would actually get more and more efficient the faster it goes. This theory makes many appearances in science fiction writings as well.</p><p>The biggest benefit to this theory is that by using the electromagnetic scoop to collect hydrogen, there&#39;s no need to take the amount of fuel that would be required on a conventional rocket. One hurdle, however, is that the ramscoop is likely to cause major drag, which would slow down the spacecraft. Another problem is the hydrogen fusion that Bussard originally thought of occurs only in the heart of stars. Bringing it to a spacecraft is far beyond what scientists are capable of today.</p><p>The concept of warp speed is usually taken as a given in science fiction books and movies that involve traveling between stars. But what exactly is it, and is there any merit to the concept of “warp speed” or “warp drive?” Let’s dive into this idea and see if it’s solely in the realm of fiction, or if there is any real-life basis in physics that could result in warp speed being possible.</p><p>This theory of interstellar space travel involves manipulating the gravitational fields of space. Manipulating the gravitational fields would, in theory, allow the distance between a spacecraft and a distant target to collapse making interstellar travel possible in seconds or even minutes. In warp drive, the gravitational fields of space are manipulated and “warped” in such a way that it shortens the distance between two points in the universe.</p><p>A scientist by the name of Miguel Alcubierre gets credit for writing a paper that postulates how the concept could work within general relativity. According to his theory, faster than light speed travel would not only be possible, but it also would not have some of the problems associated with traveling that fast, such as time distortion. He outlined the mathematical foundation for such a concept in his paper.</p><p>Unfortunately, there are some BIG holes in the plan. First, there is no way to control the warp drive. That doesn’t inspire a lot of confidence, does it? Second, it requires HUGE amounts of energy. Basically, it would require the mass-energy equivalent of the entire known universe. Fortunately, scientists at NASA have theorized a way to reduce the amount of energy that a warp drive would need. Not only that, but Dr. Harold White even gave the theory more feasibility by proposing new concepts to warp drive and promoting advanced propulsion projects. Finally, we just don&#39;t have the necessary technology to make this safe. For example, we would need shields to protect from interstellar medium such as space dust and gas.</p><p>One of the more popular theories that would shorten the distance between two places across the universe is&#160;wormholes. Wormholes are very popular in science fiction. They are mentioned in movies and books like&#160;Star Trek,&#160;Deja-vu,&#160;Marvel Universe&#160;movies,&#160;Interstellar,&#160;Stargate,&#160;A Wrinkle in Time,&#160;Contact&#160;and many others. Also known as an “Einstein-Rosen Bridge” (the two scientists who first proposed the theory), wormholes are like space-time tunnels. In theory, you would enter the wormhole in one location, and come out somewhere else in the universe. Wormholes are passages through space-time that would create “shortcuts” between two far distant places in the universe.</p><p>Both wormholes and warp drive do an excellent job of hypothesizing ways that could shorten the distance and time required to travel between two points. If we could figure out how to actually create wormholes, then that would limit the problems of propulsion even farther because we could choose the exact starting and end-point. There would be no need to account for pesky details like propulsion, slowing down, or life support!</p><p>The biggest problem: we still have never even found a wormhole! However, Einstein&#39;s Theory of General Relativity mathematically predicts their existence. Besides never having spotted one, there are other problems associated as well. For one, they are speculated to be microscopic in size when first generated. Scientists are assuming that as the universe expands, some of the wormholes that are out there will grow in size too. Another major obstacle- they probably don&#39;t stay open very long. That makes them almost useless for travel. To make it stable, it would need what is called “exotic matter” which we&#39;ve only seen hints of in certain situations. So, while wormholes are a fun idea to think about, and certainly make the story lines of movies more cohesive, it’s definitely the farthest out there in terms of actual possibilities for human travel across the universe.</p><p>Given all we know about interstellar space travel, the hurdles to overcome, the technology to be invented, the ENORMOUS costs, and the dangers involved, should we even bother? Should we move on to more earth-bound problems and let aliens- should they ever arrive- give us their secrets? Nah… that would take all the fun out of discovery, problem-solving, and exploration that could occupy humanity for the next hundreds or thousands of years!</p></section><section><h3>Numerous Challenges to Interstellar Travel</h3><p>Numerous Challenges to Interstellar Travel</p><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9d8d5b9678c8503098e23674e532329b','space-travel-and-solar-system-m10-l7-module-10-summary','5e3d555b2f300c72f8f0ecc45f2746d7','Module 10 Summary','text',12,'<h2>Module 10 Summary</h2><section><h3>Module 10 Summary</h3><p>Module 10 Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Interstellar Travel!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified the reasons and motivations behind interstellar travel</p><p>Defined astronomical units, lightyear, propulsion, and gravity units</p><p>Examined the discovery of exoplanets and their possibility of supporting life</p><p>Discussed the feasibility of an interstellar mission given energy requirements, distances, and risks</p><p>Evaluated challenges to interstellar travel based on today’s technologies</p><p>Described theories for interstellar travel, citing ideas from physics and science fiction</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('cffb3c3d8d2ff591bf26b617c6c484f7','space-travel-and-solar-system-m10-l8-module-10-assignment','5e3d555b2f300c72f8f0ecc45f2746d7','Module 10 Assignment','text',12,'<h2>Module 10 Assignment</h2><section><h3>Module 10 Assignment</h3><p>3300</p><p>Space Travel</p><p>Interstellar Travel - Short Answer Assignment</p><p>Short answer assignment</p><p>Based on what you’ve learned in this module, choose one of the prompts below and write a two-page, double-space paper, and explain your answers:</p><p>Option 1: This module only provided a very brief overview of the various ideas and technologies that could be possible for interstellar travel. Pick one that sounded most interesting or mysterious to you. Perform additional research online and write a two-page paper exploring the details and limitations of that theory, beyond what was already covered in this module.</p><p>Option 2: With the approval of a parent or guardian, choose a relevant movie, book, or TV show that deals with interstellar travel. What technology is used? Does the movie “gloss over” some of the challenges and limitations of interstellar travel, or do they discuss them and have mitigating factors? How fast can their ships go? What are the objectives of interstellar travel in this movie or show? Do they address the question of time dilation at near light speeds, and if so, how does this affect communication and travel between star systems? Write a two-page paper that addresses these questions (and/or other topics related to interstellar travel that are discussed in the movie).</p><p>Review the rubric below to see how you will be graded.</p><p>Interstellar Travel Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Content</p><p>8 points Paper demonstrates a strong understanding of the content. It contains several specific and accurate details.</p><p>7-6 points Paper demonstrates a solid understanding of the content. It contains some specific and accurate details.</p><p>5-0 points Paper demonstrates little to no understanding of the content. It contains few to no specific and accurate details.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>N/A</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('d69bbf0c5e44be01850b29c51e00ebb1','space-travel-and-solar-system-m10-l9-module-10-project','5e3d555b2f300c72f8f0ecc45f2746d7','Module 10 Project','text',12,'<h2>Module 10 Project</h2><section><h3>Module 10 Project</h3><p>3300</p><p>Space Travel</p><p>Interstellar Travel - Project</p><p>Project</p><p>It’s the year 2053, and you have just been elected the Secretary General of the International Congress (the successor to the United Nations).&#160; The Congress has been considering allocating two trillion dollars to pursuing interstellar travel. This is a significant investment in money! There will also likely be lives lots through experimentation on radical propulsion technologies, as well as space-based testing of human survivability. All the scientists and expert witnesses have given their opinions and testimony.</p><p>The Congress is fairly divided and there is a small group in the middle who could be persuaded either to support the project, or reject the project. Now, everyone is looking to you, the new leader, as to what direction they should go. Write a 3-5 minute speech (1 to 1 &#189; pages of text) that lays out your opinion on why the congress should support the funding and risking lives to pursue interstellar travel. Or conversely why the funds should be used elsewhere if the technology is too infeasible and the risks are too high.</p><p>If possible, record your speech either with audio or video, and submit this file as your project. If that is not possible, the written speech can be submitted instead.</p><p>Review the rubric below to see how you will be graded.</p><p>Interstellar Travel Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Content</p><p>8 points The speech demonstrates a strong understanding of interstellar travel. It contains several specific and accurate details.</p><p>7-6 points The speech demonstrates a satisfactory understanding of interstellar travel. It contains some specific and accurate details.</p><p>5-0 points The speech demonstrates little to no understanding of interstellar travel. It contains few to no specific and accurate details.</p><p>8</p><p>Persuasive</p><p>6 points The speech effectively defends the decision to fund or not fund the project and is effectively aimed at a target audience.</p><p>5 points The speech adequately defends the decision to fund or not fund the project and is sufficiently aimed at a target audience.</p><p>4-0 points The speech does not adequately defend the decision to fund or not fund the project and is not effectively aimed at a target audience.</p><p>6</p><p>Presentation</p><p>2 points The speech is clear, organized, and presented well.</p><p>0 points The speech commercial is not clear and organized or is not presented well.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Visual/Audio Appeal</p><p>2 points Uses appropriate visuals or audio in an engaging way.</p><p>1 point Uses appropriate visuals or audio in a satisfactory way.</p><p>0 points Uses inappropriate visuals or audio.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('46d81bcad4a062d029f0c9f0e34c710b','space-travel-and-solar-system-m10-l10-module-10-quiz','5e3d555b2f300c72f8f0ecc45f2746d7','Module 10 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Intersteller Travel. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('ce4d85220ca37e29bd6146d5ee26f78b','space-travel-and-solar-system-module-11','2a892040eda1f32ee69b17d25aad96dd','Module 11: Course Summary & Final Exam',11) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f29fd9b7ff3dc93ba02b42912243eeae','space-travel-and-solar-system-m11-l1-course-summary-and-final-exam','ce4d85220ca37e29bd6146d5ee26f78b','Course Summary & Final Exam','text',12,'<h2>Course Summary &amp; Final Exam</h2><section><h3>Course Summary</h3><p>Final Video</p><p>Thanks everyone for watching and sticking with us to the end of this module and the end of this course. Hopefully you feel that you have confidently mastered the learning objectives and are ready for the final test. More importantly, I hope there are areas that piqued your interest so that you will continue learning more about space travel and maybe even make a career out of it. And who knows, maybe you will be the first person to step on Mars, or the first to find life on Europa, or the author the next version of a space treaty, or the scientist who discovers the first wormhole. Or maybe even invent a new transportation technology that no one has even thought up yet.</p><p>Thanks again and may the force be with you!</p></section><section><h3>Final Exam Part 1</h3><p>Final Exam - Part 1</p><p>Answer Key:Off</p><p>ABCABC</p><p>Directions:&#160;Read each question carefully and then choose the correct answer.</p><p>The science of thrust is governed by Newton’s Third law, which states:</p><p>What goes up, must come down.</p><p>Two objects cannot occupy the same space at the same time.</p><p>For every action, there is an equal and opposite reaction.</p><p>Force is equal to the change in momentum per change in time.</p><p>Which of the following would happen if the Moon suddenly disappeared?</p><p>Stronger winds</p><p>Less extreme tides</p><p>Shorter days</p><p>In the Space.com top 10 list of greatest scientific missions, how many involved human crews?</p><p>All of them</p><p>Three, the Space Shuttles, Apollo and the ISS</p><p>One</p><p>Four, the Space Shuttles, the ISS, Mir and the Soyuz program</p><p>Both the Soviet Union and the United States used parts of the Nazi V2 rocket program as the basis of their space programs.</p><p>True</p><p>False</p><p>The photos named Earthrise and Blue Marble are thought to have helped with the creation of the modern environmental movement.</p><p>True</p><p>False</p><p>What of the following can explain the extinction of dinosaurs 65 million years ago?&#160;(Select all that apply)</p><p>They were infected with a virus and became sterile so they weren’t able to reproduce anymore.</p><p>A very large asteroid hit the Earth releasing a lot of debris into the atmosphere preventing photosynthesis.</p><p>An eruption of magma caused greenhouse gases which blocked sunlight and made the temperature unbearable on Earth.</p><p>An over-population of Tyrannosaurus (T-Rex) led to all the other species becoming extinct and eventually, the T-Rex, a carnivore didn’t have anything to eat.</p><p>Which of the following would make a good environment for a Moon base?</p><p>The top of Ons Hadley</p><p>Lava tunnels</p><p>The poles</p><p>Which if the following is NOT a task military satellites perform?</p><p>Launching nuclear missles</p><p>Navigation</p><p>Surveillance</p><p>Communcation</p><p>The two scientists who worked on the “rocket equation” were:</p><p>Isaac Newton and Robert Goddard</p><p>Hermann Oberth and Robert Esnault-Pelterie</p><p>Yuri Gagarin and Alan Shepard</p><p>Konstantin Tsiolkovsky and William Moore</p><p>Which of the following affect the human body in space?</p><p>Radiation</p><p>Gravity</p><p>Isolation</p><p>All of the above</p><p>How long were the Spirit and Opportunity rovers meant to remain operational?</p><p>3 years</p><p>10 years</p><p>3 months</p><p>1 year</p><p>Which of the following attributes IS NOT something NASA looks for in an appropriate food for the ISS?</p><p>Tasty</p><p>Flakey</p><p>LIghtweight</p><p>Compact</p><p>CubeSats are weigh approximately _________pounds.</p><p>100 pounds</p><p>1,500 pounds</p><p>10 pounds</p><p>3 pounds</p><p>The first space station was:</p><p>Mir</p><p>Skylab</p><p>ISS</p><p>Salyut 1</p><p>There is evidence of water on the Moon.&#160;True or false?</p><p>True</p><p>False</p><p>The first commercial communications satellite, launched by Comsat, was named Early Worm.</p><p>True</p><p>False</p><p>The first human-made object to orbit the Earth was?</p><p>Apollo 2</p><p>Sputnik</p><p>Explorer 1</p><p>A chimpanzee in a rocket ship</p><p>Privatization is being suggested for some space exploration tasks because:&#160;(Choose all the answers that apply.)</p><p>It’s cheaper</p><p>NASA is bored of launching missions</p><p>Private companies are better suited for some tasks</p><p>Budget cuts mean that NASA must pick and choose what it can and can’t do.</p><p>One of the things that the Apollo missions made possible are:</p><p>Microchips</p><p>Better tinfoil</p><p>Better winter boots</p><p>More comfortable beds</p><p>Because of a lack of environmental restrictions, Russia is already using nuclear reactors in space.</p></section><section><h3>Final Exam Part 2</h3><p>Final Exam - Part 2</p><p>Answer Key:Off</p><p>ABCABC</p><p>Directions:&#160;Read each question carefully and then choose the correct answer.</p><p>What is the percentage of satellites still in orbit that are active?</p><p>40%</p><p>90%</p><p>10%</p><p>25%</p><p>Jupiter&#39;s moon Io is the best candidate for the terraforming of all the planet&#39;s moon.&#160;True or false?</p><p>True</p><p>False</p><p>What’s the name of the moment when the Earth, the Sun, and Mars line up?</p><p>Discovery</p><p>Opposition</p><p>Alignment</p><p>Orbital match</p><p>What is terraforming?</p><p>The art of creating a copy of the Earth using clay</p><p>The process by which the Earth was formed</p><p>The process by which a planet (other than the Earth) is transformed so it’s more like the Earth</p><p>The search for a planet that’s exactly like the Earth</p><p>Using current technology, an average trip to Mars would take how long?</p><p>12-18 months</p><p>18-20 months</p><p>2 months</p><p>6-8 months</p><p>Most American astronauts have come from the military.&#160;True or false?</p><p>True</p><p>False</p><p>One of the biggest countries in the growing field of space and asteroid mining is?</p><p>Malta</p><p>USA</p><p>France</p><p>Luxemburg</p><p>Why is water an essential component of space travel?&#160;(Select all that apply)</p><p>For travelers to drink</p><p>To keep the windows clean</p><p>To breathe</p><p>To turn into fuel</p><p>What is currently the best way to try and work out the composition of an asteroid?</p><p>Looking with a regular telescope</p><p>Sending a probe to take a look</p><p>Pictures from the ISS</p><p>Spectral imaging</p><p>Which of the following is an effect of being confined for a long period of time?&#160;(Select all <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Space Travel and Solar System lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Space Travel and Solar System interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('461d318712851c1f7237df29fb60a6e3','space-travel-and-solar-system-course-mastery-assessment','ce4d85220ca37e29bd6146d5ee26f78b','Course Mastery Assessment','assessment',30,'<h2>Course mastery assessment</h2><p>Bring together knowledge and application from the complete course. Achieve at least 80% to satisfy the assessment requirement for certification.</p>',NULL,1,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO assessments (id,slug,course_id,title,pass_mark,questions) VALUES ('5e52b2776a73b45ddd28b990b9b472fa','space-travel-and-solar-system-course-mastery-assessment','2a892040eda1f32ee69b17d25aad96dd','Space Travel and Solar System Course Mastery Assessment',80,CAST('[{"id":"space-travel-and-solar-system-course-mastery-assessment-q1","type":"multiple-choice","prompt":"Before starting a practical task in Intro to Space Travel, which action best demonstrates professional judgement?","options":["Clarify the intended outcome, constraints, and success criteria before choosing tools.","Choose the fastest tool and define the goal afterward.","Copy the first available example without checking its fit.","Begin production immediately and leave requirements for final review."],"answer":"Clarify the intended outcome, constraints, and success criteria before choosing tools.","explanation":"Strong practice begins with a clear outcome, constraints, and measurable success criteria.","clue":"Think about what must be understood before execution begins."},{"id":"space-travel-and-solar-system-course-mastery-assessment-q2","type":"multiple-choice","prompt":"A first attempt in Apollo and Shuttles does not meet the requirement. What is the strongest next step?","options":["Compare the result with the criteria, identify the cause, revise, and test again.","Submit the attempt unchanged because the task is complete.","Replace the criteria with measures the attempt already meets.","Discard all evidence and restart without diagnosing the issue."],"answer":"Compare the result with the criteria, identify the cause, revise, and test again.","explanation":"An evidence-led improvement cycle diagnoses the gap before a focused revision and retest.","clue":"Use feedback and evidence to improve the next attempt."},{"id":"space-travel-and-solar-system-course-mastery-assessment-q3","type":"multiple-choice","prompt":"Which evidence most credibly demonstrates applied competence in Satellites & Space Station?","options":["A completed work sample with decisions, checks, feedback, and reflection documented.","A claim that the topic was understood without a work sample.","A list of tools with no explanation of how they were used.","An unfinished draft that has not been checked against requirements."],"answer":"A completed work sample with decisions, checks, feedback, and reflection documented.","explanation":"Competence is best demonstrated through completed, reviewed evidence and reflective reasoning.","clue":"Choose evidence that shows both the result and how quality was established."},{"id":"space-travel-and-solar-system-course-mastery-assessment-q4","type":"multiple-choice","prompt":"When work in Moon Base could affect people, data, safety, or the environment, what should the learner do?","options":["Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","Proceed without checks when the intended outcome is positive.","Treat ethical and safety considerations as optional after delivery.","Hide known limitations so stakeholders remain confident."],"answer":"Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","explanation":"Responsible practice makes risk, consent, standards, and safeguards part of the work itself.","clue":"Professional quality includes the impact of the work, not only the output."},{"id":"space-travel-and-solar-system-course-mastery-assessment-q5","type":"multiple-choice","prompt":"How should a learner transfer skills from Mars 5 Colony to a new workplace or project context?","options":["Analyse the new context, adapt the method, test assumptions, and evaluate the result.","Repeat the original steps unchanged regardless of context.","Use only familiar methods and ignore new constraints.","Wait for a complete example to copy before making any decision."],"answer":"Analyse the new context, adapt the method, test assumptions, and evaluate the result.","explanation":"Transfer requires adapting core principles to new constraints and validating the result.","clue":"Core principles remain useful, but their application must fit the new context."}]' AS JSON)) ON DUPLICATE KEY UPDATE title=VALUES(title),pass_mark=VALUES(pass_mark),questions=VALUES(questions);
