INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('320e562830361177627b9da7c698a9e9','teaching-as-a-profession-course-mastery-assessment','2b1bf46486a6ef3872b44e72305375ee','Course Mastery Assessment','assessment',30,'<h2>Course mastery assessment</h2><p>Bring together knowledge and application from the complete course. Achieve at least 80% to satisfy the assessment requirement for certification.</p>',NULL,5,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO assessments (id,slug,course_id,title,pass_mark,questions) VALUES ('da78176509ad6f77c670fe922ad3b6d4','teaching-as-a-profession-course-mastery-assessment','424e301af3a885ab4f1bb3ce13379795','Teaching as a Profession Course Mastery Assessment',80,CAST('[{"id":"teaching-as-a-profession-course-mastery-assessment-q1","type":"multiple-choice","prompt":"Before starting a practical task in Professional Identity and Ethics, which action best demonstrates professional judgement?","options":["Clarify the intended outcome, constraints, and success criteria before choosing tools.","Choose the fastest tool and define the goal afterward.","Copy the first available example without checking its fit.","Begin production immediately and leave requirements for final review."],"answer":"Clarify the intended outcome, constraints, and success criteria before choosing tools.","explanation":"Strong practice begins with a clear outcome, constraints, and measurable success criteria.","clue":"Think about what must be understood before execution begins."},{"id":"teaching-as-a-profession-course-mastery-assessment-q2","type":"multiple-choice","prompt":"A first attempt in How Learning Happens does not meet the requirement. What is the strongest next step?","options":["Compare the result with the criteria, identify the cause, revise, and test again.","Submit the attempt unchanged because the task is complete.","Replace the criteria with measures the attempt already meets.","Discard all evidence and restart without diagnosing the issue."],"answer":"Compare the result with the criteria, identify the cause, revise, and test again.","explanation":"An evidence-led improvement cycle diagnoses the gap before a focused revision and retest.","clue":"Use feedback and evidence to improve the next attempt."},{"id":"teaching-as-a-profession-course-mastery-assessment-q3","type":"multiple-choice","prompt":"Which evidence most credibly demonstrates applied competence in Planning Inclusive Learning?","options":["A completed work sample with decisions, checks, feedback, and reflection documented.","A claim that the topic was understood without a work sample.","A list of tools with no explanation of how they were used.","An unfinished draft that has not been checked against requirements."],"answer":"A completed work sample with decisions, checks, feedback, and reflection documented.","explanation":"Competence is best demonstrated through completed, reviewed evidence and reflective reasoning.","clue":"Choose evidence that shows both the result and how quality was established."},{"id":"teaching-as-a-profession-course-mastery-assessment-q4","type":"multiple-choice","prompt":"When work in Teaching and Facilitation Practice could affect people, data, safety, or the environment, what should the learner do?","options":["Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","Proceed without checks when the intended outcome is positive.","Treat ethical and safety considerations as optional after delivery.","Hide known limitations so stakeholders remain confident."],"answer":"Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","explanation":"Responsible practice makes risk, consent, standards, and safeguards part of the work itself.","clue":"Professional quality includes the impact of the work, not only the output."},{"id":"teaching-as-a-profession-course-mastery-assessment-q5","type":"multiple-choice","prompt":"How should a learner transfer skills from Assessment and Feedback to a new workplace or project context?","options":["Analyse the new context, adapt the method, test assumptions, and evaluate the result.","Repeat the original steps unchanged regardless of context.","Use only familiar methods and ignore new constraints.","Wait for a complete example to copy before making any decision."],"answer":"Analyse the new context, adapt the method, test assumptions, and evaluate the result.","explanation":"Transfer requires adapting core principles to new constraints and validating the result.","clue":"Core principles remain useful, but their application must fit the new context."}]' AS JSON)) ON DUPLICATE KEY UPDATE title=VALUES(title),pass_mark=VALUES(pass_mark),questions=VALUES(questions);
INSERT INTO courses (id,slug,academy_id,moodle_id,title,description,level,duration,price,is_free,status)
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('6e2f89a50f744622ce6f7585d107d5ae','transportation-technologies-module-0','504e3ab88df8552a07116f12aea44099','Module 0: Introduction, Purpose, Objectives, Summary',0) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8a216a0182931674319a7db47b6a665d','transportation-technologies-m0-l1-introduction-purpose-and-objectives','6e2f89a50f744622ce6f7585d107d5ae','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Course Intro, Nav, Objectives, Syllabus</h3><p>Course Intro Video</p><p>For as long as there have been cars and airplanes, there have been people trying to put them together. So…. Where’s my flying car? This course is going to teach you some of the newest and most innovative transportation ideas out there. Some of them are already here – and others may be decades away from ever happening. We are going to talk about driverless cars and drones, Supersonic planes and submarines, We’ll even learn about space travel, and of course, flying cars. And more than just tell you about the technologies, we’re going to explore what makes them work, and what might stop them from becoming a reality. You’ll walk away with knowledge to participate in some of the most important debates we will have in society around transportation in the coming years. And you’ll be equipped to take your education even further and find jobs and careers in the most cutting-edge transportation technologies out there.</p><p>Course Navigation</p><p>Welcome to this course on the Future of Transportation!&#160;To get you started in Module 0, we have included the video below, which provides some navigation help and other details about the course.</p><p>Other sections of this Module 0 include the Course Syllabus and a Syllabus Quiz, so read&#160;through the syllabus carefully and thoroughly!</p><p>Hi and welcome to this orientation video for this course. As we go through this video, some details may differ depending on which course you are taking and the learning management system, or LMS, that your school uses, but the overall structure generally stays the same for each course.</p><p>After you complete this navigation tutorial video for module zero you should read through the course objectives, a section on sources and plagiarism, the syllabus, and finally take the syllabus quiz. Now, a few things on navigation. Within each section, you can navigate between pages either with the menu here on the left, or with the left/right arrows near the bottom. Again, that will allow you to move between PAGES within each section. Once you are done with all the pages in a section, you can either select home at the top of the course. Or you can select “Next” at the very bottom of the page to the next section. It’s very important to make sure you finish every page within a section BEFORE moving to the next section.</p><p>Ok, once you are done with Module 0, you&#39;ll move on to start your first module. Within each module there is an introduction, somewhere between 4 and 6 lessons, and then a summary and assessments at the end. First, within the introduction, if you select it, it should look something like this. Each module will start at this page which contains a 30 to 60 second introductory video that will introduce and discuss some of the concepts that you&#39;ll learn and review during this module. Let’s talk about the videos. You can also turn closed captioning on or off by clicking the CC button. Next is the setting button, where you can adjust the speed that the videos will play. Maybe you like to hear things a little faster at 1.25x. Or maybe there is a concept that is difficult, and you would like to slow down. These next two icons allow the video window to pop out, or for the video window to go full-screen. For many videos, there will also be a transcript of the video below.</p><p>The next page is a description of the module. Then we move on to objectives which explains what the student will learn during this module. Next there is typically is a polling question. Sometimes this appears at the beginning of a module and sometimes it appears at the end. But it&#39;s just a way to take a guess or to voice your opinion on a certain issue and you can click on whichever you&#39;d like and see how your answer compares to your classmates.</p><p>You will next come to a vocabulary activity. Most of these will also be at the beginning as a formative assessment, meaning that you aren&#39;t expected to know the answers but take your best guess as this is an ungraded quiz. For instance, you can pick a word drag it over and then check your answer to see that it was incorrect you keep trying again and see if you can get them all lined up. Again, this allows you to just familiarize yourself with the various vocabulary words that will be introduced in this module. Alternatively you can select on the alternative activity and it&#39;s more of a multiple choice format. So again this is an ungraded quiz. You can close it out right there. Next, we move to the lessons. As said before, there are 4 to 6 lessons within each module. So you&#39;ll see each lesson represents more or less a day&#39;s worth of work and contains a video, a reading, and then either a concept check or reflection. As you will learn in the syllabus, the introduction, video, and reading pages are graded on participation, meaning you get credit for going through every page and activity in the module. Your school may or may not be using participation, so please check with your instructor on whether or not you will be receiving participation credit in your course.</p><p>The videos and their functionality we have already talked about. Next we go into the readings which obviously will have additional content and details to read. It will also frequently contain images as well as embedded videos. These are videos that add a lot of visual detail to the materials and again just hitting play there. Some videos are longer, so we try to limit video clips to 2 to 5 minutes, so in some cases you will only see a small clip of a larger video.</p><p>After the video and reading is a concept check or reflection where you&#39;ll either input an answer or work with flashcards or maybe a sorting exercise to review and firm up the concepts that were taught in that section. The reflections are either journal entry or discussion prompts. To participate in class-wide discussion, you’ll select this link to read the questions or prompts, and then participate in the discussion by adding a new discussion topic and eventually commenting on posts from other students.&#160;You&#39;ll see this repeat itself through the rest of the sections. After which you&#39;ll find a quick summary. Once you are finished with each lesson, you see three more assignments here: the short answer assignment, the project and the quiz. The short answer assignment is generally a one to two-page paper, written after every modu<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('c45008e591510e51e29a32e1f92ce096','transportation-technologies-module-1','504e3ab88df8552a07116f12aea44099','Module 1: Intro to Future Trans',1) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b37bcf4961546298bcb4b2a19709bed5','transportation-technologies-m1-l1-introduction-purpose-and-objectives','c45008e591510e51e29a32e1f92ce096','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi I’m Ms. Clark, and I’ll be one of your instructors on the Course on Flying Cars and the future of transportation!</p><p>Have you ever stopped to think about what transportation will be like 5, 10, or 50 years from now? Have you ever seen an amazing transportation technology in a futuristic movie or video game and thought, “what if that could be made into reality?” If you’ve ever asked those questions, then this course is for you.</p><p>This module will get you started by learning and evaluating some of the most cutting edge and futuristic transportation ideas out there. Some might arrive years from now, while others may be decades away… or never happen at all. We are going to talk about flying cars, and jet packs, driverless cars and drones, hyperloop and supersonic jets. We’ll even get into the water and talk about something called supercavitation. And of course, we’ll explore space flight and interstellar travel.</p><p>Let’s get started!</p><p>Module Description</p><p>byGeorgeman</p><p>License:&#160;All Rights Reserved</p><p>How different would your life be if your only alternative to walking to your destination was to saddle up a horse and ride there?&#160;Before steam engines, when horse transportation was your best option, people probably didn&#39;t give it much thought.&#160;People saddled up their horses or jumped in their wagons.&#160;That was just life!&#160;It&#39;s only because we now know the convenience of cars and airplanes that the idea of only being able to take a horse seems painfully slow, horribly uncomfortable, and woefully inefficient.&#160;What will people 100 years from now say about the transportation of our era?&#160;How much more speedy, efficient and safe will transportation be then?</p><p>This module aims to answer those questions.&#160;It will start by reviewing the history of transportation and how key inventions of transportation modes led to big changes in society.&#160;It takes a look at where we stand today, including problems with our current infrastructure and transportation systems.&#160;Finally, the module introduces some of the newest emerging transportation technologies like flying cars, hyperloop, and driverless cars, just to name a few.</p><p>Objectives</p><p>In this module, students will</p><p>Outline the history of transportation and contrast past technological changes with current opportunities</p><p>Define ubiquity and discuss adoption of previous technologies such as the telephone</p><p>Analyze the technology adoption curve and relate it to the adoption of future transportation technologies</p><p>Describe limitations with current transportation modes and how future technologies can help solve some of these problems</p><p>Match future transportation modes with their definition</p><p>Evaluate a framework to evaluate futuristic transportation technologies</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Warning:&#160;json_decode() expects parameter 1 to be string, object given in&#160;/srv/app/current/blocks/interactive_definitions/controller.php&#160;on line&#160;238</p><p>Vertical Take-off and Landing Vehicle, also known as a flying car</p><p>Hyperloop</p><p>A car that can operate without a human driver</p><p>Driverless car</p><p>A company that is developing a vac-train, which is a train that sits above a magnetic track and moves through a vacuum tube to reduce friction</p><p>Jetpack</p><p>a device worn over the shoulders like a backpack and enabling the wearer to travel through the air or space by means of jet propulsion which uses oxygen in the combustion process</p><p>VTOL</p><p>encompassing an object in a bubble to reduce drag</p><p>Supercavitation</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Vertical Take-off and Landing Vehicle, also known as a flying car</p><p>Answers for question: 1</p><p>Jetpack</p><p>Supercavitation</p><p>Hyperloop</p><p>VTOL</p><p>Driverless car</p><p>2.</p><p>A car that can operate without a human driver</p><p>Answers for question: 2</p><p>VTOL</p><p>Supercavitation</p><p>Driverless car</p><p>Hyperloop</p><p>Jetpack</p><p>3.</p><p>A company that is developing a vac-train, which is a train that sits above a magnetic track and moves through a vacuum tube to reduce friction</p><p>Answers for question: 3</p><p>Jetpack</p><p>VTOL</p><p>Driverless car</p><p>Hyperloop</p><p>Supercavitation</p><p>4.</p><p>a device worn over the shoulders like a backpack and enabling the wearer to travel through the air or space by means of jet propulsion which uses oxygen in the combustion process</p><p>Answers for question: 4</p><p>Jetpack</p><p>VTOL</p><p>Driverless car</p><p>Hyperloop</p><p>Supercavitation</p><p>5.</p><p>encompassing an object in a bubble to reduce drag</p><p>Answers for question: 5</p><p>Driverless car</p><p>VTOL</p><p>Supercavitation</p><p>Hyperloop</p><p>Jetpack</p><p>Warning:&#160;json_decode() expects parameter 1 to be string, object given in&#160;/srv/app/current/blocks/interactive_definitions/controller.php&#160;on line&#160;238</p><p>faster than the speed of sound and up to Mach 5</p><p>Supersonic Speed</p><p>an autonomous and remotely controlled vehicle</p><p>Ubiquity</p><p>personal rapid transit; a form of public transportation that uses small automated vehicles on specially built guideways</p><p>Technology Adoption Curve</p><p>the fact of being very common, or appearing everywhere</p><p>Infrastructure</p><p>theory about how individuals and groups implement new technologies</p><p>PRT</p><p>the basic physical and organizational structures and facilities (e.g., buildings, roads, and power supplies) needed for the operation of a society</p><p>Drone</p><p>Alternative Activity</p><p>&#171;Objectives</p><p>Alternative Activity</p><p>Match description with a choice.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('d0c40ec5fc171a4aadbf5f1627970456','transportation-technologies-m1-l2-lesson-1','c45008e591510e51e29a32e1f92ce096','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>History of Transportation Development Achie</h3><p>History of Transportation Development Achievement</p><p>While watching this video, keep an eye out for an example of when a newer transportation technology was &quot;ditched&quot; for an older transportation mode.</p><p>Welcome, this is video 1 for this module on the Introduction to the Future of Transportation.</p><p>Let&#39;s face it- when it comes to getting from here to there, no one wants to just walk. That&#39;s why dating back to 6,000 BC, someone thought to themselves, “I bet if I strap something to my feet I can get down this snowy mountain a heck of a lot faster than trying to walk in knee-deep snow.” Okay, maybe that wasn&#39;t their&#160;exact&#160;thought, but regardless, someone had the idea back in prehistoric times to create the first pair of skis.</p><p>Canoes and rafts were also among the earliest transportation inventions. Unlike canoes and rafts today which are mainly used for recreational purposes, these made long journeys up and down rivers and even across the ocean!</p><p>Eventually domestication of animals came into play. Although there is some uncertainty as to when exactly this happened, it was probably somewhere around 4,000 BC. As trade increased, so did roads and trails to accommodate the animals who helped carry goods from place to place.</p><p>Next came the wheel. One of the reasons it took humans comparatively long to get around to inventing it is because there are no similar designs in nature. It&#39;s 100% the creation of humans. Interestingly, its first application was NOT for transportation, but for pottery!</p><p>About 300 years after it was created, someone thought to fashion a chariot of sorts. Now animals (and people) could pull heavier loads.</p><p>You&#39;d think that once people caught the vision of the wheel, they&#39;d never go back to the “old ways.” But that&#39;s not the case. In the Middle East, people ditched the wheel in favor of camels once camel saddles came around and roads started to decline with the fall of the Roman Empire.</p><p>This just goes to show that just because some mode of transportation works now, does not mean it will work well in the future.</p><p>The steam engine came around in 1769. That was a real game changer. Boats were among the first to make use of the steam engine, and began puffing along at average speeds of 5 miles per hour. Some of you are probably thinking “Ummmm.... I can run faster than that!” But the important part was that the boats were able to carry heavy, heavy loads without depending on nearly as much human power or wind and currents.</p><p>The first quarter of the 1800s saw the dawning of the locomotive engine. Before trains came along, people were limited to traveling on land by how fast a horse could gallop. Trains made it so people could get farther, faster. It also had a unifying effect across Europe and the United States as railroads physically connected people as the tracks expanded.</p><p>The automobile was a European invention of the 19th&#160;century. However, their wide spread usage got its start in the United States during the early 20th&#160;century. As was the American manufacturing way, cars were produced in higher quantities at lower prices than in Europe. This is how the famous Ford Model T came to be.</p><p>The more widespread cars became, the more they began to affect daily life. More and more people began to spread to the suburbs now that they had a convenient way to get to the city. Women were no longer confined to their homes. Highways, interstates, and overpasses filled the landscape. From 1915 to 1930, the average farm horse population decreased by 1/3. With fewer horses on the streets, streets became cleaner- less horse manure to deal with. On the other hand, more cars also meant more air pollution.</p><p>Also during the 20th&#160;century, submarines created a stealthy way for countries to approach the enemy&#39;s waters. The submarine also allowed humans to explore an environment that was largely a mystery up until that point- the depths of the sea.</p><p>From the road, to the sea, now let&#39;s talk about the sky. For centuries people had been trying to find a way to mimic birds to fly. But the Wright brothers revolutionized the concept of human flight with their first sustained, controlled and powered flight in 1903. World War II spiked a production of airplanes. After that, the commercial industry really kicked off as airplanes became the go-to method for long journeys both for people and cargo. The first supersonic- or faster than the speed of sound- jet was getting people across the Atlantic Ocean by the latter half of the century.</p><p>Finally, rockets made their debut also during the last half of the 20th&#160;century. Spurred on by what is called “the space race” between the former Soviet Union and the United States, interest and investment in space exploration exploded. Perhaps the biggest accomplishment during this space race was developing a rocket capable of taking Neil Armstrong and Buzz Aldrin to the moon.</p><p>Now that we know a bit about humanity&#39;s achievements in transportation so far, the next section will take a look at what it takes to make these innovations a part of our everyday life.</p></section><section><h3>History of Transportation</h3><p>History of Transportation</p><p>(opens in a new tab)</p><p>Snowshoe (racket to walk atop snow)</p><p>License:&#160;All Rights Reserved</p><p>Making Walking Easier</p><p>Think about your shoes, for just a minute.&#160;You probably don&#39;t give them too much thought throughout the day.&#160;They are just something you wear.&#160;Think about if you had to walk around without them during the winter or in the blistering heat of summer.&#160;Feet coverings were among the first, prehistoric inventions designed to make foot transportation a little more comfortable.&#160;Other ancient innovations include skis and snowshoes.</p><p>Roads</p><p>As people carried goods to and from places, tracks were naturally created at places where many people traveled.&#160;When animals became domesticated (which historians estimate to be around 4000 BC), tracks started to widen and flatten even more.&#160;Animals provided much-needed labor and helped create civilizations.&#160;Now people could do more than just hunt.&#160;They could trade, travel, and communicate more than ever.</p><p>Around the 4th&#160;or 5th&#160;millennium BC, animal-drawn vehicles, like <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9930e9732683ebdfbf635f5221abc9ca','transportation-technologies-m1-l3-lesson-2','c45008e591510e51e29a32e1f92ce096','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Adoption Curve of New Technology</h3><p>Adoption Curve of New Technology</p><p>While watching, think about&#160;what it means for someone to &quot;adopt&quot; a technology.</p><p>Welcome back, this is video 2 for this module on the Introduction to the Future of Transportation.</p><p>I&#39;m going to make some seemingly basic assumptions about what I might find in your home. Electric light bulbs likely fill your house. A fireplace is no longer a given. It might be nice to have in the winter to add some warmth, or simply for ambiance. But it&#39;s no longer essential, especially since you have a central heater, and a stove and oven to cook. For food that needs to be cooled to store, it&#39;s a good thing you have a refrigerator! There&#39;s at least one cell phone in your house and when you get bored, there&#39;s always good old coloredtv to watch!</p><p>Most of these things are a given in a household today, but they haven&#39;t always been. Some of these things took decades to become ubiquitous, or common place. For example, it took 30 years for electricity to reach just 10% adoption by society. Smartphones, on the other hand, hit the 40% adoption mark in just 10 years.</p><p>Why is that? Let&#39;s start by talking about the adoption curve, which is a useful way to break up users of a new technology or product. It’s called a curve after a principle in statistics known as the “bell curve”, but maybe an easier way to think about is like a pie chart, which has 5 pieces. The first piece of the pie is the innovators- this small sliver, roughly 2%, are risk takers and the first to use a new technology. After them comes early adopters- those who start using it after the innovators and comprise 14% of the total population. Then a lot more people start seeing the benefit of a new technology and more start adopting. The early majority is the next 34%, taking the total users up to 50%. After that, late majority adds another 34%, and laggards- the last of the bunch who take the number to 100%.</p><p>To date, there have only been two human-invented technologies that have crossed from the early majority to the late majority if we look at the population of the world as a whole. Can you guess what those are?</p><p>The first, is electricity. Electricity is used by over 80% of the world wide population. The second, is text messaging.</p><p>Once electricity became widely adopted, there was an explosion in the invention and adaptation of things like washing machines, electric stoves, and refrigerators over the next 50 years.</p><p>Here&#39;s the key- a new technology will only go as far as the adoption of the technologies preceding it. Email will always be dependent on the adoption of the internet. In places where there is no internet, there&#39;s no email usage or smartphone usage.</p><p>Let&#39;s tie this all back to our course. If we are talking about driverless cars, for example, driverless cars are always going to have a ceiling on adoption based on the adoption of automobiles. In places like the Amazon rain forest where there are groups of people with no cars and no access to cars, there will probably be no adoption of driverless cars.</p><p>On the other hand, if the internet does become adopted in a place where it previously wasn&#39;t available, there is likely to be a quick adoption of dependent technologies as well, such as email. In a very real sense, technology is a chain effect. Without a strong link ahead of it, a new technology will struggle to take off. However, with a strong starting link, others can quickly follow.</p></section><section><h3>Technology Adoption Curve Phases</h3><p>Technology Adoption Curve Phases</p><p>Technology Adoption Curve</p><p>Do you use Netflix, Snapchat, or Pinterest?&#160;If you do, then you are considered one of the innovators along the technology adoption curve.&#160;The technology adoption curve is a theory about how people use and implement new technologies.&#160;It divides users into five categories.&#160;Press the tabs below to explore the categories.</p><p>Innovators</p><p>Innovators - these are the first to adopt a new technology.</p><p>Early adopters</p><p>Early adopters - adopt new technology once the innovators adopt the technology</p><p>Early majority</p><p>Early majority - this group is a little more cautious and will adopt it once there is a clear benefit to using it</p><p>Late majority</p><p>Late majority - this group is a bit more skeptical and tend to adopt it only when the majority does or when pressured into doing so</p><p>Laggards</p><p>Laggards - are often reluctant to change and often only adopt when something becomes mainstream or traditional</p><p>Next Tab</p><p>Maybe you&#39;re thinking, “Wait, an innovator?&#160;That&#39;s not me.&#160;All my friends were on Snapchat/Pinterest or used Netflix way before me.” While that may be true, compared to the entire US, with 332 million people, or the world as a whole, with some 7.88 billion people, using any one of those three technologies would make you an innovator.</p><p>Your position on the technology adaptation curve could change as the population studied changes.&#160;So while looking at the world as a whole, you are an innovator, while looking at your school&#39;s population, you may be in the early or late majority category.</p><p>The video below talks through the technology adoption curve in greater detail:</p><p>In this video, I&#39;m going to talk to you about the technology adoption lifecycle. Let&#39;s go ahead and define that. Here&#39;s the definition from Wikipedia. The technology adoption lifecycle is a sociological model that describes the adoption or acceptance of a new product or innovation according to the demographic and psychological characteristics of a defined adopter group or groups. We are talking about people here. What&#39;s the effect of people psychology the way that we behave on the adoption of a technology? And by technology, I want you to think of not just widgets, not just things but also processes and ways of doing things. So the first group that we&#39;re going to look at, remember these are groups of people, is the innovators. These might be also termed the techies, so these are the folks that are always playing with new technology. They&#39;re on the bleeding edge. They like technology or new ways of thinking just for technology&#39;s sake. Next, we have the early adopters, so these are the folks that we might consider the visionaries. The<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('dadaf87ecfb4c4c34bff7696017ed696','transportation-technologies-m1-l4-lesson-3','c45008e591510e51e29a32e1f92ce096','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Reasons to Improve Modes of Transport</h3><p>Reasons to Improve Modes of Transport</p><p>While watching, pick what you think is the most compelling reason for future transportation technologies.</p><p>Welcome back, this is video 3 for this module on the Introduction to the Future of Transportation.</p><p>Why bother developing new forms of transportation? What we have is working, right? Well, our current transportation modes are certainly not without their ugly side.</p><p>Let&#39;s start with safety. Unfortunately, 37,000 deaths occur each year in the US alone because of auto accidents. Auto accidents are the leading cause of death for teens, with 6 teens dying every day because of them. And an additional 6,000 being treated daily in emergency rooms for auto accident related injuries.</p><p>Cars are also expensive. I&#39;m not just talking about the cost to buy one off the lot, I&#39;m talking about the fact that traffic accidents are costing society over $160 billion dollars a year. Then there&#39;s the cost to clear and maintain roads and infrastructure.</p><p>Speaking of infrastructure, think for a minute about how much of our land is devoted to cars, buses, and trucks. Not just the roads that we drive on, but the massive amounts of parking lots we have because when we are not using those vehicles, they have to be put somewhere. What else could we do with that space? Perhaps we could build more living spaces, parks, businesses, basketball courts, community pools- I can think of a lot more exciting things to do with the space taken up by parking lots.</p><p>Another problem with cars- traffic! 6.9 billion collective hours are wasted sitting around in traffic. That&#39;s just in 1 year! BILLIONS of human hours that could be much better spent!</p><p>Finally, let&#39;s talk about pollution. Airplanes, cars, buses... nearly all the common transportation modes we use today use fossil fuels. In addition to harming air quality in cities, fossil fuels release carbon dioxide which contributes to the greenhouse effect and global warming. Global warming creates problems for the environment as the climate starts to change, forcing wildlife to deal with changing habitats.</p><p>These problems- safety, cost, infrastructure, traffic, and pollution- are just some of the problems scientists and engineers are working to improve with new and emerging modes of transportation. Some are looking to improve mass transit by making it faster and more convenient to relieve traffic. While others are working on technologies that will take out the most dangerous part of driving- the human driver. Still others are working on implementing green solutions and clean energy to help the environment. And a few take on all these problems. One day- perhaps in your lifetime- some or all of these problems may be a thing of the past thanks to the technologies we&#39;ll cover in this course.</p></section><section><h3>Traffic Costs</h3><p>Traffic Costs</p><p>Have you ever been stuck in traffic?&#160;What were you feeling?&#160;Annoyed?&#160;Angry?&#160;Maybe anxious that you were going to be late.</p><p>Traffic is a huge time waster.&#160;The average urban commuter wasted about 42 hours a year sitting in traffic in 2022.</p><p>Not only does traffic cost us time, it costs us money too.&#160;It costs us $160 billion per year.&#160;On an individual level, that&#39;s $960 per typical motorist.&#160;Over the next few years, these numbers are expected to rise to at least 8.3 billion hours and $192 billion.</p><p>Cutting down on time spent stuck in traffic is one of the big goals of many emerging transportation technologies.&#160;Driverless cars, flying cars, personal rapid transit, delivery drones, and even jetpacks all use traffic reduction as a big reason why their new technology will benefit society.&#160;They each outline in different ways solutions to the problem.&#160;Some call for getting people to places faster collectively, while others take a more individual, streamlined approach.</p><p>Let&#39;s take a look at some of the costs associated with traffic.&#160;Expand the sections below.</p><p>Transportation Tickets</p><p>The cost of purchasing tickets for various modes of transportation, such as airfare, train tickets, bus fares, or cruise ship tickets. These costs vary depending on the distance, destination, class, and season of travel.</p><p>Accommodation Expenses</p><p>The cost of lodging during the travel period, including hotel room charges, vacation rentals, or hostel fees. Accommodation costs depend on factors such as location, quality, amenities, and duration of stay.</p><p>Food and Dining</p><p>The expenses incurred for meals and dining while traveling. This includes the cost of eating out at restaurants, cafes, or street food stalls, as well as groceries and snacks purchased for self-catering. Food costs can vary significantly depending on the destination and dining preferences.</p><p>Transportation within the Destination</p><p>Costs associated with local transportation within the travel destination, such as taxi fares, subway or metro tickets, bus or tram fares, or rental car expenses. The amount spent on transportation within the destination depends on the distance covered, mode of transport, and local transport pricing.</p><p>Sightseeing and Activities</p><p>Expenses for visiting tourist attractions, museums, parks, historical sites, or participating in activities like guided tours, adventure sports, or cultural events. These costs vary based on the specific attractions and activities chosen, as well as any associated entrance fees, tickets, or tour charges.</p><p>Travel Insurance</p><p>The cost of purchasing travel insurance to protect against unforeseen events like trip cancellations, medical emergencies, lost luggage, or flight delays. Travel insurance premiums depend on factors such as the traveler&#39;s age, destination, duration of travel, and coverage options.</p><p>Visa and Documentation</p><p>The expenses related to obtaining necessary travel documents, such as visas, passports, or permits. Costs can include application fees, processing fees, and passport photos. The specific costs vary depending on the traveler&#39;s nationality, destination, and type of documentation required.</p><p>Currency Exchange and Banking Fees</p><p>Charges associated with converting currency or using international banking services while traveling. These costs may include exchange fees, ATM withdrawal fees, <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6199d17d7a7b39f6bae11b47100339d9','transportation-technologies-m1-l5-lesson-4','c45008e591510e51e29a32e1f92ce096','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Types of Modern Transportation Technologies</h3><p>Types of Modern Transportation Technologies</p><p>While watching, think about which new transportation modes you are familiar with already and which are new concepts.</p><p>Welcome back, this is video 4 for this module on the Introduction to the Future of Transportation.</p><p>We&#39;ve hinted at some of them up to this point, but now let&#39;s look at some types of transportation technology we might cover in this course. Keep in mind that as time goes on, this list may change or get re-ordered based on the latest and greatest transportation technologies out there.</p><p>We will of course spend some time talking about driverless cars. Driverless cars are making headlines and are already out on the streets in some cities. We will look at both the technology involved and at some of the impacts they could have on society.</p><p>Driverless cars aren&#39;t the only type of cars we&#39;ll talk about. We will also look at flying cars, or to be more technically correct, vehicles that take off and land vertically. These are commonly called VTOL vehicles for short. Flying cars aren&#39;t just a dream anymore, there are companies that are actually building them. We&#39;ll take a closer look at those companies in that module.</p><p>We&#39;ll also look at something called personal rapid transit or PRT. These are also known as pod cars because they are little vehicles that are, well, pod-like in design. Unlike buses where you have to stop at every stop along the route, pod cars are designed for point to point and on-demand travel. Also in this module, we&#39;ll look at a few motorcycle/car hybrids.</p><p>Another mode we are going to consider is Hyperloop. This proposed system would use magnetic levitation and low pressure tubes to zip riders at unprecedented speeds. Imagine getting from Los Angeles to Las Vegas in less than a half hour!</p><p>We won&#39;t ignore maritime transport either. In particular, we&#39;ll talk about supercavitation- a process that encompasses an object in a bubble to reduce drag in the water. We will also look at the future of other sea-faring vessels in that module as well.</p><p>People often joke that they thought we&#39;d all be able to strap a jetpack on our backs and fly off to wherever we need to go by now. In our jetpack module, we&#39;ll investigate why so few people have ever worn a jetpack and whether or not they are a viable mode of future transportation.</p><p>Speaking of jets, there&#39;s a module on supersonic jets as well. Supersonic means faster than the speed of sound. Interestingly, supersonic jets were around just a few decades ago. Our module will take a look at why they are no longer around and what scientists are working to improve from past supersonic jets.</p><p>Also up in the air (literally) is the future of delivery drones. Think of how much quicker it would be to get a pizza if traffic, stop lights, and stop signs didn&#39;t interfere with delivery time.</p><p>Then we go even higher in the air. Like all the way to outer space. We&#39;ll look at rockets and the future of space travel. We will take space travel one step farther... well, more like a gazillion steps farther, and look at interstellar travel, which is traveling beyond our solar system.</p><p>I am really excited to tell you about these amazing technologies, the companies working to make them happen, and even sharing with you how you can get involved in the future of transportation.</p></section><section><h3>Modes of Transport to Cover</h3><p>Modes of Transport to Cover</p><p>Are you wondering which modes of transportation we&#39;re going to cover in this course?&#160;Well, here&#39;s a list and a brief description of the exciting things to come:</p><p>Driverless cars</p><p>Driverless cars: also known as autonomous cars or self-driving cars. These are cars capable of getting around without a human driver involved in most of the process. This is such an exciting and involved future technology that we are going to devote two modules to driverless cars. One module will focus more on the technology and the other will focus on the implications to society.</p><p>Drones</p><p>Drones: these are autonomous and remote controlled vehicles. You&#39;ve probably seen them around; they are becoming more and more popular. We&#39;ll look at how they could serve delivery businesses and other sectors of the economy as well.</p><p>Flying cars</p><p>Flying cars: imagine being able to fly over rush hour traffic. That&#39;s dream could be a reality with flying cars, or vertical take-off and landing (VTOL) vehicles. Not only do they bypass traffic, they also don&#39;t require the extensive runway that airplanes require.</p><p>Hyperloop</p><p>Hyperloop: this proposed method of transportation involved magnetic levitation and low pressure tubes to reduce friction and get a crowd of people to their destination faster than cars and even airplanes.</p><p>Interstellar travel</p><p>Interstellar travel: this is space travel beyond our solar system. We&#39;ll investigate what makes interstellar such a daunting task and proposed theories for making it happen.</p><p>Jetpack</p><p>Jetpack: these devices are warn on the back like a backpack and provide thrust and lift to get the wearer off the ground. You&#39;ve probably seen them on tv or maybe even in person at something like a sporting event. We&#39;ll talk about whether there&#39;s a future for them in our every-day lives.</p><p>PRT</p><p>PRT: this stands for personal rapid transit. It&#39;s a form of public transportation that uses small automated vehicles on specially built guideways. This would take the convenience of public transportation and the privacy and point-to-point capability of personal transportation to create an alternative for getting from place to place. This module will also look at other ways of getting from place to place like segways, monowheels and motorcycle/car hybrids.</p><p>Space travel</p><p>Space travel: in this module, we&#39;ll explore rockets and emerging reusable rockets. We will look at how reusable rockets could change the future of space travel. We&#39;ll also look at a few companies working to make this possible.</p><p>Supercavitation</p><p>Supercavitation: think that the future of transportation is limited to the land and air? Think again! Supercavitation which takes an object and encloses it in a bubble which reduces drag in the water, is another mode worth investi<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0a39672fa3b2eca52a906d1f5d515a6c','transportation-technologies-m1-l6-lesson-5','c45008e591510e51e29a32e1f92ce096','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Evaluating type of Transport to Use</h3><p>Evaluating type of Transport to Use</p><p>While watching, think about why you use the forms of transportation you use.</p><p>Welcome back, this is video 5 for this module on the Introduction to the Future of Transportation.</p><p>In the 1950s, the Betty Crocker brand, which is a brand of General Mills, released their “just add water” cakes to the world. Everything was contained in the mix- no need for milk, eggs, or any other ingredient other than the mix and water. The eggs and milk were already in the mix in powdered form. After the success they had with instant pancakes, they thought for sure instant cakes were going to be a huge hit. Well, they thought wrong.</p><p>Unlike pancakes, which are made in the rush of the morning, cakes are made for special occasions. People felt guilty putting so little effort into something that was meant to be special. So what did General Mills do? They told consumers to add an egg. And just like that, sales soared.</p><p>An interesting story, but what does this have to do with our course on transportation? Well, it goes to show that just because a technology or product designed to make our lives easier becomes available, doesn&#39;t necessarily mean it will be adopted into society.</p><p>There&#39;s a certain framework we all use when evaluating whether or not to use a product. Our framework for evaluating a cake versus our framework for evaluating a driverless car, for example, will be a bit different, but the framework should provide a sense of whether or not the technology provides the key components we value in that type of product or service.</p><p>Let&#39;s talk about a framework for evaluating new and emerging modes of transportation.</p><p>One element should be the cost. It&#39;s likely going to be difficult to convince anyone to adopt any transportation system that costs more than what people are already use to paying for a similar system. For example, if people are used to paying around $125 for a ticket from Los Angeles to Las Vegas, a Hyperloop ticket for $1,125 is going to be tough to sell. Even if it is a time saver. Also included in the analysis of cost is where the money is going to come from to create the new technology or system. Is it going to raise taxes in an area? On the other side of that, will it provide tax breaks for those who use it? A system requiring a brand new infrastructure is likely to be more expensive than a technology that fits in with our already existing one.</p><p>Another element to consider is the impact on the environment. Like we&#39;ve already mentioned, most of the transportation modes we will discuss are trying to incorporate clean energy. However, there are other facets to consider such as what building new infrastructure could do to the environment. Or whether the parts necessary to create electronics and batteries deplete other natural resources.</p><p>Safety, of course is a big part of our evaluation when it comes to transportation. Very few people are going to want to ride a system that only has a 50/50 chance of enabling them to live to tell the tale. But it&#39;s not just the safety of those using the system that we need to consider. We also need to consider the safety of those around the transportation modes such as pedestrians.</p><p>Another element should be the technology itself. It&#39;s one thing if engineers already have the technological foundation and are just working to refine and perfect it. It&#39;s quite another to need technology that is going to require an undiscovered, theoretical energy source, or one that would require a complete shift in the laws of physics.</p><p>Finally, we need to keep in mind the consumer experience. A new technology might be 99.9% safe, completely pollution-free, cost-effective, and all set to go from the technological standpoint, but if it&#39;s as comfortable as sitting on cinder blocks, then it&#39;s going to be a hard sell. Other essentials in this category might be things like how well it fits into the average person&#39;s lifestyle, the learning curve for using the technology, and how people will perceive users- are they going to seem cool using it? Or is it going to hurt their social status?</p><p>This is going to be a great course. Get ready to learn, read, discuss, and think critically about some amazing technologies on our horizon.</p></section><section><h3>Evaluating Proposed Mode of Transport</h3><p>Evaluating Proposed Mode of Transport</p><p>License:&#160;All Rights Reserved</p><p>Evaluation Process</p><p>When you use a new product for the first time, how do you decide if you like it or not?&#160;You&#39;re likely thinking, “well, it depends on the product.” That is very true.&#160;You&#39;re likely to use different criteria when evaluating a new phone than you use when evaluating a new bed, for example.&#160;How it feels when you lie down on it is likely high on your list of criteria for a bed, but probably not on your list for a phone!</p><p>Like all products and technologies, these modes of transportation we will cover in this course also need to stand up to a framework of evaluation to determine whether they are viable or not.&#160;Here&#39;s what a checklist for evaluating a proposed method of transportation might look like.&#160;Expand the sections below.</p><p>Cost</p><p>This considers factors like whether or not a consumer has to buy the entire system (like a car) in order to take full use of it or whether they can pay per use (like a taxi or bus). Other factors to consider with cost are how the new technology compares in prices to more traditional modes of transportation. For example, how much more will it cost to ride on a supersonic jet versus a traditional jetliner. Tax money is another issue. If the public is going to have to fund a system which requires a specific infrastructure, the impact to tax payers is something to consider.</p><p>Environmental Impact</p><p>This goes beyond the question of whether it cause more or less pollution (although that certainly is a big consideration). We also have to consider whether it calls for natural resources and how we will extract those resources. Another consideration is what building the infrastructure will do to the environment.</p><p>Safety</p><p>Is it safe for the rider or user? Is it safe for those around the system? Another component that will be largely unique to future modes of transportation is if the user&#39;s informatio<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9a6c67262972861cf399588a4fd07a79','transportation-technologies-m1-l7-module-1-summary','c45008e591510e51e29a32e1f92ce096','Module 1 Summary','text',12,'<h2>Module 1 Summary</h2><section><h3>Module 1 Summary</h3><p>Module 1 Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on the Introduction to the Future of Transportation!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Outlined the history of transportation and contrasted past technological changes with current opportunities</p><p>Defined ubiquity and discussed adoption of previous technologies such as the car and telephone</p><p>Analyzed the technology adoption curve and related it to the adoption of future transportation technologies</p><p>Described limitations with current transportation modes and how future technologies can help solve some of these problems</p><p>Matched future transportation modes with their definition</p><p>Evaluated a framework to evaluate futuristic transportation technologies</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('365668a1e864988db42cc4782d7d3979','transportation-technologies-m1-l8-module-1-assignment','c45008e591510e51e29a32e1f92ce096','Module 1 Assignment','text',12,'<h2>Module 1 Assignment</h2><section><h3>Module 1 Assignment</h3><p>Module 1 Assignment</p><p>Transportation</p><p>Introduction to the Future of Transportation - Short Answer Assignment</p><p>Short answer assignment</p><p>For this writing assignment, write a two-page, double spaced paper addressing the questions/topics listed.</p><p>Analysis and Application: Using the frame work from section 5, evaluate an existing mode of transportation.</p><p>For example, take a bicycle and describe its cost (how much does a bike cost, how much is maintenance and upkeep?), its environmental impact (pretty low because it&#39;s powered by a human!), its safety (what are the risks and safety precautions of a bike rider?), its technology (a bike&#160;was invented a long time ago), and its user experience.</p><p>Review the rubric below to determine how you will be graded.</p><p>Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c1c72798c03c981eaa557121510913b9','transportation-technologies-m1-l9-module-1-project','c45008e591510e51e29a32e1f92ce096','Module 1 Project','text',12,'<h2>Module 1 Project</h2><section><h3>Module 1 Project</h3><p>Module 1 Project</p><p>Transportation</p><p>Introduction to the Future of Transportation - Project</p><p>Project</p><p>In this assignment, you will create a timeline of the history of transportation technology through the present, and then make predictions of technologies that you expect or hope to see in the future. Use a presentation software (such as PowerPoint or Prezi) to create the timeline. Be sure to cite any resources for images and other content.</p><p>Your timeline should include:</p><p>at least ten different transportation history entries</p><p>name, date, and descriptions of each entry</p><p>two fictional entries of what you predict for the future of transportation with name, date, and detailed descriptions of each fictional entry</p><p>Review the rubric below to see how you will be graded.</p><p>Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Content</p><p>8 points The timeline demonstrates a strong understanding of the development of transportation based on available technologies and needs. It contains all the required details about the ten history entries.</p><p>7-6 points The timeline demonstrates a satisfactory understanding of the development of transportation based on available technologies and needs. It contains most of the required details about the ten history entries.</p><p>5-0 points The timeline demonstrates little to no understanding of the development of transportation based on available technologies and needs. It contains few to no specific and accurate details about the ten history entries.</p><p>8</p><p>Prediction</p><p>8 points The two predictions of future transportation technologies are extremely creative and relevant to today’s trends and technology. The descriptions thoroughly expand on the concepts discussed.</p><p>7-6 points The two predictions of future transportation technologies are sufficiently creative and relevant to today’s trends and technology. The descriptions adequately expand on the concepts discussed.</p><p>5-0 points The two predictions of future transportation technologies are incomplete or are not creative and relevant to today’s trends and technology. The descriptions do not expand on the concepts discussed.</p><p>8</p><p>Presentation</p><p>2 points The timeline is clear, organized, and presented well.</p><p>1 point The timeline is somewhat clear and organized and the presentation is adequate.</p><p>0 points The timeline is not clear and organized or is not presented well.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('fe005cdfddaa595a486ca8171a6c8e13','transportation-technologies-m1-l10-module-1-quiz','c45008e591510e51e29a32e1f92ce096','Module 1 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Intro to Future Trans. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('5f7adf535405c222996079a632d514c8','transportation-technologies-module-2','504e3ab88df8552a07116f12aea44099','Module 2: Flying Cars',2) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e5d88e76c889a60b8a517f3a18fbeb61','transportation-technologies-m2-l1-introduction-purpose-and-objectives','5f7adf535405c222996079a632d514c8','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi I’m Mr. Southwick, welcome to this module on flying cars!</p><p>We have cars. We have airplanes. We have helicopters. So... WHERE IS MY FLYING CAR? It can&#39;t be THAT hard to develop, right? Sure, their mechanics may be mind-boggling, safety precautions unending, supportive fuel a bit tricky, and never mind that an entire infrastructure and regulations would have to be built just for the sky...</p><p>Okay, so maybe there are a whole lot of problems standing the way between you and your little aerial speedster. Does that mean that engineers have hung their hats and walked away from the idea of flying cars?</p><p>No, actually. Recently, many technological developments are coming together at just the right time to make this generation’s engineers believe that flying cars will be here in the near future. Improvements in lightweight materials, fuel efficiency, and battery storage, among many other technologies are making this possible. Let’s get started!</p><p>Module Description</p><p>Futuristic illustration of a flying car.</p><p>License:&#160;All Rights Reserved</p><p>From fiberglass cars with wings strapped to the top of vehicles looking like they came straight out of a science fiction movie, the concept of flying cars has evolved with time and technology.&#160; In this module, we will explore and understand what a Vertical Takeoff and Landing (“VTOL”) vehicle is, the history of flying cars, current flying car projects, the pros and cons of such vehicles, and careers in the field of VTOL technology.</p><p>Objectives</p><p>In this module, students will</p><p>Define what a Vertical Take-Off and Landing vehicle is and how it is different from existing modes of transportation</p><p>Identify historical attempts at building flying cars and technological advances that have contributed to the emergence of flying cars</p><p>Predict when they will ride in a flying car and justify their prediction</p><p>Examine existing companies that develop flying cars and match&#160;a project name with each company</p><p>Describe current prototypes and demonstrate a basic understanding of their underlying technologies</p><p>Compare the pros and cons of flying cars on the economy, society, the environment, and safety</p><p>Appraise future career opportunities and pathways in the flying car industry</p><p>Polling Question</p><p>What year do you think you will take your first ride in a flying car?</p><p>Before 2020&#160;2020-2025&#160;2025-2030&#160;After 2030&#160;Never</p><p>Results:</p><p>2025-2030&#160;100%</p><p>How did your prediction compare to your classmates?&#160;Let’s see how your answer changes as your learn more about flying cars!</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Warning:&#160;json_decode() expects parameter 1 to be string, object given in&#160;/srv/app/current/blocks/interactive_definitions/controller.php&#160;on line&#160;238</p><p>vertical takeoff and landing; refers to aircrafts that can take off and land vertically such as a helicopter</p><p>Rotorcrafts</p><p>autonomous aerial vehicle; an aircraft that is programmed to fly by itself, without a pilot or driver</p><p>AAV</p><p>aircraft that lifts by using rotor blades spinning around a central mast</p><p>VTOL</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>verticaltakeoff and landing; refers to aircrafts that can take off and land vertically such as a helicopter</p><p>Answers for question: 1</p><p>AAV</p><p>Rotorcrafts</p><p>VTOL</p><p>2.</p><p>autonomous aerial vehicle; an aircraft that is programmed to fly by itself, without a pilot or driver</p><p>Answers for question: 2</p><p>Rotorcrafts</p><p>AAV</p><p>VTOL</p><p>3.</p><p>aircraft that lifts by using rotor blades spinning around a central mast</p><p>Answers for question: 3</p><p>Rotorcrafts</p><p>AAV</p><p>VTOL</p><p>technology used to shape blades or wings in order to give an aircraft lift</p><p>Airfoil technology</p><p>the type of engine used to rotate helicopter blades</p><p>Ultra-redundancy</p><p>a safety technique used to ensure that if a system fails, there are sufficient backups to ensure safety</p><p>Prototype</p><p>a first or preliminary model of something, from which other forms are developed or copied</p><p>Turboshaft</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>technology used to shape blades or wings in order to give an aircraft lift</p><p>Answers for question: 1</p><p>Turboshaft</p><p>Prototype</p><p>Airfoil technology</p><p>Ultra-redundancy</p><p>2.</p><p>the type of engine used to rotate helicopter blades</p><p>Answers for question: 2</p><p>Prototype</p><p>Airfoil technology</p><p>Ultra-redundancy</p><p>Turboshaft</p><p>3.</p><p>a safety technique used to ensure that if a system fails, there are sufficient backups to ensure safety</p><p>Answers for question: 3</p><p>Ultra-redundancy</p><p>Prototype</p><p>Turboshaft</p><p>Airfoil technology</p><p>4.</p><p>a first or preliminary model of something, from which other forms are developed or copied</p><p>Answers for question: 4</p><p>Turboshaft</p><p>Prototype</p><p>Airfoil technology</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4ba38da4c0afb40f9c827492f8616add','transportation-technologies-m2-l2-lesson-1','5f7adf535405c222996079a632d514c8','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>What is a Flying Car</h3><p>What is a Flying Car</p><p>While watching this video,&#160;think about a time you were stuck in traffic and what being stuck in traffic kept you from.</p><p>Welcome to the Flying Cars module – video 1.</p><p>So what exactly is a flying car? Well, there are lots of definitions, really. It can be anything from a hover craft to a road-able airplane. But for this module, we are going to focus on the future of&#160;vertical take-off and landing vehicles, also known as VTOL vehicles. The vehicles can take off and land- you guessed it- vertically. In other words, they wouldn&#39;t require the long runway of an airplane to takeoff. Instead the vehicles would lift off vertically from the ground, much like a helicopter.</p><p>In fact, a helicopter IS considered a VTOL. A helicopter is a type of VTOL vehicle known as a&#160;rotorcraft. A rotorcraft lifts by using rotor blades spinning around a central mast.</p><p>To get a better understanding of what VTOL is, let&#39;s learn more about airfoils and turboshafts.</p><p>First, an airfoil is a part of an aircraft designed specifically with air currents in mind. In the case of a helicopter, this refers to the rotor blades.</p><p>Second, a unique feature of the helicopter compared to an airplane is the&#160;turboshaft&#160;engine. This is what makes the blades rotate.</p><p>Those two components- airfoil technology and the turboshaft engine- are of primary interest to developing flying cars because they are what make the vertical take-off and landing possible.</p><p>So why don&#39;t we all just have a bunch of mini helicopters parked in our garage? What are engineers trying to improve upon? here&#39;s where the helicopter falls short:</p><p>One: The cost. The fuel cost alone to operate your own personal helicopter is more than the majority of people would be able to afford. The flying car prototypes we will examine seek to be more fuel efficient and cost effective transportation options.</p><p>Two: It&#39;s hard to vary the size. Unlike automobiles where you can fairly easily have everything from a tiny coupe to a double-decker bus, helicopters don&#39;t scale as well. Although there are small helicopters that fit 1-2 people, they are still much larger than a typical car and most people would have nowhere to conveniently store it, unlike a car in a home garage. And you can forget about trying to park your helicopter downtown! One of the reasons engineers haven&#39;t given up on the flying car dream is that they are seeking a way to find a solution to congested roads in urban areas by utilizing airspace.</p><p>Three: Speed. While some VTOL vehicle prototypes are focusing on taking the place of, or working in tandem with cars, others are more focused on covering large distances fast. These companies are working on combining the vertical takeoff and landing concept of a helicopter with the speed of an airplane.</p><p>Four: Difficulty to operate: While learning to drive a car can take place during a semester-long high school driver’s ed course, helicopter training is much more intensive. Certification to become a helicopter pilot takes a significant amount of ground instruction and flight time, and is much more expensive.</p><p>It is these 4 limitations to helicopters- cost, inability to vary the size or scale, speed, and difficultly to operate- that engineers hope to improve upon when designing a flying car. As you will see, some of the flying cars we will discuss seek to improve on just one of these issues, others all four.</p></section><section><h3>Concept of VTOL for Flying Cars</h3><p>Concept of VTOL for Flying Cars</p><p>The Right Time</p><p>Almost as soon as cars became mainstream, engineers and forward thinkers started dreaming up how to make cars fly.&#160; Now, over 100 years and over 80 attempts later, many technological developments are coming together at just the right time to make this generation’s engineers believe that flying cars will be here in the near future.&#160;Improvements in lightweight materials, fuel efficiency, and battery storage, among many other technologies, are making this possible.</p><p>Watch this video about the Lilium Jet to see just how close engineers are to making flying cars a part of normal life.</p><p>We promised the world a five-seater jet. Today we are delivering on that promise. It takes off and lands vertically. It&#39;s fully electric. This is the Lilium jet.[Music]This is the first time that we have a full-scale full-weight prototype of that five-seater version. This is the next step in mobility as we perceive it. What we&#39;re trying to achieve here is an air mobility revolution. We look at what is possible by the laws of physics.[Music]Our principle of maximum simplicity combined with a level of safety. It is really something that makes us unique. This is the product. There&#39;s nothing like this. There&#39;s always a risk if you do something you.[Music]At some point, you have to say we have tested everything, now let&#39;s fly this aircraft.[Music]There&#39;s this one moment where everything comes together and where it&#39;s make-or-break. This is the everything defining moment for all of us. Taking off the three, two, one.[Music]First flights are always crucial, but the launch, of course, for us, is just a small piece in this whole process. The testing will go on, the refinements, the engineering will all continue.</p><p>Video Title:&#160;Lilium unveils five seater all electric air taxi</p><p>Video Publisher:&#160;Tech World</p><p>License:&#160;Creative Commons Attribution license (reuse allowed)</p><p>by photostock77</p><p>License:&#160;All Rights Reserved</p><p>VTOLs</p><p>Key to understanding flying cars is the concept of VTOL vehicles.&#160;VTOL stands for vertical takeoff and landing, and it refers to aircraft that can take off and land vertically.&#160;Vertical take-off and landing vehicles are the focus of many current flying car undertakings because the ability to take off and land vertically means there is no need for an extensive runway.&#160;This space-saving feature allows more flexibility and freedom than traditional airplanes.&#160;And by utilizing airspace, it frees up and/or bypasses road congestion caused by a high volume of cars.</p><p>Watch the video below to learn about the history of the Yakolev Yak-38 Forger:</p><p>[Music]The Yakolev yak-38 Forger was the only vertical takeoff and landing aircraft of the soviet navy. It was also the <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6bee1e8c24127b6a5a3006093fabb155','transportation-technologies-m2-l3-lesson-2','5f7adf535405c222996079a632d514c8','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Award Worthy Flying Cars Attempt</h3><p>Award Worthy Flying Cars Attempt</p><p>While watching this video,&#160;think about which historic flying car you think was the best attempt.</p><p>Welcome back, this is video 2 of the Flying Cars module.</p><p>Did you know that there are about 80 patents on file at the United States Patent and Trademark Office for different kinds of flying cars? Perhaps unsurprisingly, most of these have never actually flown. But let&#39;s take a look at some of the more award-worthy attempts.</p><p>The “trailblazer” award goes to: Glen Curtiss&#39; Autoplane which debuted in 1917 at the Pan-American Aeronautical Exposition. But World War I started, and development of the vehicle stopped. The Autoplane never flew. Nevertheless, credit is due for such forward thinking at the time.</p><p>The “Tiny Flyer” Award goes to: Henry Ford&#39;s “Sky Flivver” back in 1926 and it did actually fly on a couple occasions. The project, however, was abandoned in 1928 when the test pilot died in a Flivver crash. Yikes. What the Sky Flivver did was excite the public with the idea of a mass-produced affordable airplane</p><p>The “Took The Concept Literally” Award goes to: Henry Dreyfuss&#39;sConvair car which flew in 1947. Basically, it took a fiberglass car body and threw a wing and engine module on the roof. And, perhaps surprisingly, it did make a 1 hr 18 minute flight over San Diego. Two prototypes were built, but along the way, public enthusiasm was lost and it never made it to production. Kudos all the same for building a literal flying car.</p><p>The “Hold Your Breath for the Landing” Award goes to: The Ryan Aircraft Corporation&#39;s X-13 Vertijet. Takeoff and flight in this aircraft was pretty easy. The landing, on the other hand was a bit of a nightmare because the pilot had to make a near-blind landing. However, the X-13 was a pioneer in what is called the thrust vectoring system which became a crucial part of advanced combat aircraft.</p><p>And finally, The Straight Out of a Sci-Fi Movie Award goes to: Fred Baker&#39;s Sky Commuter, which was developed in the 1980’s. A lot of money was sunk into the project. But now it&#39;s just a blurb in history books. Although it never flew, credit is due for garnering so much support and money into the project.</p><p>These are just a few of the more interesting and innovative designs that brought us that much closer to flying cars in society becoming a reality.</p></section><section><h3>Past Flying Cars Design Attempt</h3><p>Past Flying Cars Design Attempt</p><p>Currently, there are about 80 patents on file at the United States Patent and Trademark Office for different kinds of flying cars.&#160;Examining some of the earlier attempts will help us further understand what current engineers are trying to improve upon with their own flying cars.&#160;Expand the sections beneath each image to learn more about it.</p><p>Curtiss Autoplane displayed at New York Aero Show, 1917</p><p>License:&#160;Public Domain</p><p>Autoplane</p><p>1917 Glen Curtis debuted his “Autoplane” at the Pan-American Aeronautical Exposition.&#160;With an aluminum body, plastic windows, and a heater for passengers, the autoplane was aiming to be more comfortable than the airplanes of the time. When World War I started, development halted, and the project never resumed. Although it was built and designed to fly supposedly, the Autoplane never flew.</p><p>Ford Flivver Replica</p><p>Creative Commons&#160;(opens in a new tab)is licensed under&#160;CC BY-SA 4.0(opens in a new tab).</p><p>Ford Sky Flivver</p><p>Almost 10 years later, in 1926, Henry Ford built the Sky Flivver.&#160;Although more plane-like than car-like, the Sky Flivver had the public excited by the prospect of personal flying vehicles. The Sky Flivver was small. So small, in fact, it could fit in Ford&#39;s office, which was one of his specifications. In 1928, a distance-record-breaking test was undertaken. Unfortunately, an engine stoppage occurred, causing the Flivver to go down and with it, the pilot, Harry Brooks. The Flivver washed up, but the pilot&#39;s body was never found. The pilot and Ford were friends, and the wreck upset Ford to the point that production of the Sky Flivver stopped.</p><p>(opens in a new tab)</p><p>ConvairCar Model 116</p><p>License:&#160;Public Domain</p><p>ConVairCar</p><p>In 1947 brought perhaps one of the most literal interpretations of the flying car. Henry Dreyfuss&#39;sConVairCar featured a fiberglass car body, wing, and engine module on the roof. Two prototypes were built. The first body was destroyed during a demonstration flight when a low fuel situation forced the vehicle into an emergency landing. A second prototype was built, but the enthusiasm was no longer there. The ConVairCar never went into production.</p><p>Ryan X-13 Vertijet</p><p>License:&#160;Public Domain</p><p>Ryan X-13 Vertijet</p><p>Also, during the 1950s, the armed forces became highly interested in VTOL technology. Considering how large and vulnerable airbases can be, it is not hard to see why vertical take-off and landing vehicles, with their space-saving, low-profile setup areas, were highly appealing to this sector. The X-13 Vertijet was the aircraft funded by the Air Force to achieve vertical take-off and landing. To take off, the launch bed was elevated vertically, allowing the X-13 to hang from suspended cables with a partially retractable hook. The pilot would then increase the throttle until the hook lifted off the cable, speed up vertically, then switched to forward flight. Things became considerably more difficult when it came to landing. Because the airframe obstructed the pilot&#39;s view, it was very difficult for the pilot to judge the distance from the ground, which resulted in lots of radio communication with someone below the aircraft. Competing programs cut the funding for the program, and the X-13 flew for the last time on September 30, 1957.&#160;It pioneered thrust vectoring systems, which became a crucial component to combat aircraft by the end of the twentieth century.</p><p>Boeing Sky Commuter</p><p>License:&#160;No known copyright restrictions</p><p>Sky Commuter</p><p>The 1980s saw the creation of the Sky Commuter. Boeing engineers spent $6 million developing this particular flying car concept. The flying car featured three road wheels for driving and takeoff/landing. Forward movement was to be provided by gas turbine engines. The engines were linked to ea<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('046a0475d2be3ac7696c1ad8722400fe','transportation-technologies-m2-l4-lesson-3','5f7adf535405c222996079a632d514c8','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Current Companies Developing Flying Cars</h3><p>Current Companies Developing Flying Cars</p><p>While watching this video, listen for which companies are developing flying cars today.&#160;Which one sounds most&#160;interesting to you?</p><p>Welcome back, this is video 3 of the Flying Cars module.</p><p>So... where exactly are we today? It’s clear that early “flyers” or attempts at flying cars have led to where we are today. Now, let&#39;s explore what engineers and innovators have in the works around the world.</p><p>Think Uber is just an app that gets you a ride somewhere? Think again. Uber is working toward building an electric VTOL aircraft to enhance its ride-sharing business. After your little flight in the sky on one of their aircrafts, Uber will then connect you to one of their ground-based drivers to finish getting you where you need to go. The project is known as “Uber Elevate”</p><p>Over in China, a company called Ehang is developing the Ehang 184. Passengers enter their desired location on a device inside the vehicle and this autonomous aerial vehicle (or AAV) sets off to get you where you need to go. Thanks to its electric power, it’s a greener option.</p><p>Also getting in on the autonomous aerial action is Terrafugia&#39;s TF-X. Unlike the Ehang 184, however, the TF-X is meant to be both a sky and road vehicle. This VTOL vehicle would takeoff, fly and land completely autonomously. Drivers would still manually handle the roads, however. Another separating feature is that the TF-X would still be gasoline based, unlike some of the electric options that are being worked on today. The company is projecting to have a production version by 2025.</p><p>Remember the Lilium Jet mentioned at the beginning of the module? This all-electric vehicle could get you from London to Paris in an hour. With safety being such a substantial concern both in the minds of the public and engineers, the Lilium Jet uses a concept called “ultra-redundancy.” That means the components are independent, so that in the event of a single engine failure- or even multiple engine failures- the system can still land safely. It will, however, require a pilot to drive.</p><p>Airbus has two developments in the works. One is a single-rider AAV VTOL under its Project Vahana. The other development is a flying taxi system called CityAirbus. Multiple riders could book the CityAirbus using an app. Although it won&#39;t just show up to your door to get you to school or work. You would have to board and land at the “nearest helipad.”</p><p>Toyota is creating the “Cartivator” with the ambitious goals for the autonomous vehicle to light the Olympic flame in Tokyo for the 2020 summer Olympic Games. The flying car project called Skydrive, is part of the Cartivator project and will be the vehicle to light the flame. Toyota’s second goal is to transport athletes between the Olympic village and various venues around the area using the Cartivator. We’ll see if that actually happens.</p><p>Now, these are just a few of the many companies and projects that are making credible attempts at building VTOLs. And no doubt this list will continue to grow.</p></section><section><h3>Current Flying Car Projects</h3><p>Current Flying Car Projects</p><p>Below are some Flying Car projects that are underway.&#160;(Note:&#160;articles are optional reading, but videos are required).&#160;Which one do you think sounds the most promising?</p><p>Uber Elevate</p><p>This century is also seeing its fair share of attempts to make flying cars commonplace.&#160;Uber is a location-based app that pairs riders with private drivers to enable riders to get where they want to go.&#160;However, Uber has no intentions of getting left behind as technology leaps forward.&#160;Uber is working toward building an electric VTOL aircraft that will function to shorten urban commutes.&#160;The project is called “Uber Elevate.” The goal is to strengthen and add to their already successful business strategy by connecting Uber Elevate riders with ground drivers to take them to their final destination.</p><p>To learn more about the Elevate, check out the video below.</p><p>A video showing a demonstration of Ubers first new air taxi.</p><p>Video Title:&#160;Uber gives first look into its new air taxi service</p><p>Video Publisher:&#160;NobelZi</p><p>License:&#160;Creative Commons Attribution license (reuse allowed)</p><p>Note:&#160;There are no closed captions for this video.</p><p>TAI TF-Kaan</p><p>The TAI TF-Kaan is another AAV in the works.&#160;Interestingly, the TF-X is meant to function both in the air and on the road.&#160;This VTOL vehicle would takeoff, fly and land completely autonomously, but drivers would be required to manually handle the roads, however.&#160;Unlike the Ehang, however, this particular AAV VTOL will use gasoline.&#160;A prototype initial flight is scheduled for some time 2023.&#160;As for production-quality&#160; planes, an in-service date is scheduled from 2025 to 2030.</p><p>To learn more about the TAI TF-Kaan, check out the video below.</p><p>The TF-X.A four-seat hybrid with wings. No runway needed. Computer controlled flight. Just tell it where you want to go. It flies for you. Twin electric motor pods. Distributed electrical system. A megawatt of power lifts you. Electric motors and a 300 hp engine team up. Engine recharges the batteries. Ducted fan provides thrust. Propellers fold for cruise. 200 MPH cruise speed. 500 mile range.When you arrive, it laned safely for you. You always have the final say if it’s safe to land. In seconds and airplane…becomes a car…Providing true door-to-door transportation. All motors…Subscribe for new videos…</p><p>Video Title:&#160;THE CAR s FUTURE TECNOLOGY 2018 Terrafugia TF X ALL MOTORS</p><p>Video Publisher:&#160;Home Decor</p><p>License:&#160;Creative Commons Attribution license (reuse allowed)</p><p>Note:&#160;There are no closed captions for this video.</p><p>Let&#39;s take a look at a few more projects.&#160;Press the tabs below.</p><p>Lilium Jet</p><p>We mentioned the Lilium Jet at the beginning of the module.&#160;This all-electric vehicle would transport riders from London to Paris, or Chicago to Detroit, in an hour.&#160;To combat safety issues, the jet follows the concept of “ultra-redundancy,” mean the components are independent, so that in the event of a single engine failure- or even multiple engine failures- the system can still land safely because there are so many “back-ups” s<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('42284ee82e7db59bf1bfa924119e444b','transportation-technologies-m2-l5-lesson-4','5f7adf535405c222996079a632d514c8','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Pros and Cons of VTOL Flying Cars</h3><p>Pros and Cons of VTOL Flying Cars</p><p>While watching this video, think about what excites you the most about flying cars and what worries you the most about them.</p><p>Welcome back, this is video 4 of the Flying Cars module.</p><p>Now that we know what they are, their history, and have had a glimpse into their future, are VTOL vehicles are worth the effort, money, and time to create? Let&#39;s look at some of the pros and cons.</p><p>What sort of an impact would VTOL vehicles have on the economy? The commercialization of VTOL vehicles would create a number of jobs and add more positions in existing jobs for the economy. We will need people to create rules and regulations. Specialized mechanics.Engineers with backgrounds in VTOL vehicles. Software engineers to make sure AAVs get us to the right place. And so many more that we may not even be able to predict at this point. We will discuss potential jobs and careers later in the module.</p><p>Another potential benefit is bringing down the cost of housing in some cities by making downtown areas more accessible. One of the reasons that housing in cities like New York City is sky high is because of high demand for housing that is close to where people work. If commutes become easier and faster, than needing to live close to work may not be such a big deal. As people move away from cities, this will then potentially bring down the cost of housing in the cities.</p><p>But what about the downside? Would this hurt certain industries? Most of the VTOL aircrafts- especially electric ones- would be limited to short, urban routes. After all, a battery can only operate for so long. Unless there was to be a sudden massive, change in the price of oil, airlines will still remain more cost-effective for years to come. It&#39;s unlikely that the automobile industry would take a huge hit initially either. If you live in a suburban area, and you need to go to the grocery store, taking off in a VTOL aircraft is a little over the top for the need. Cars and mass-transit systems like buses are still going to be the most cost-effective solution for the majority of people. At least initially.</p><p>The aspect of future technology that may cause some to lose their jobs isn&#39;t a feature that is being explored by flying cars alone. It&#39;s driverless or autonomous technology. And that technology is already being put into practice by airplanes, cars, and trucks. So there may not be a rush for “flying car taxi drivers” if they are mostly autonomous to being with.</p><p>How would widespread adoption of VTOLs affect society? Let&#39;s look at 3 possibilities.</p><p>One: Connection- Speeding up travel time, both by speed of the vehicle and by bypassing road traffic, would allow people to get connected faster and easier than ever before.</p><p>Two: Time- Instead of traveling by car for two hours you could take a time-saving 12 minute flight.</p><p>Three: Societal classes- It is possible that initially, we could see flying cars divide the “haves” from the “have nots.” With those who have most likely being the rich. This would improve their lives, but how about the lives of those who can&#39;t afford it. Would this cause resentment toward those who can afford flying cars? It&#39;s worth remembering however, that the first cell phone cost about $5,000, but today they are much more common place and affordable. This could happen with flying cars as well as technology improves and becomes less expensive.</p><p>A big aim of the companies working toward VTOL vehicles is to use green technology to clean up our air. Many have found going electric to be the answer. Rather than burning fuel to power the engine, the motor would be electric. Not only does this mean no carbon emissions from the engine, it also means that there would be less noise pollution.</p><p>However, eliminating emissions is just one part of the tangled web of environmental improvement. For example, one of the concerns about electric cars is that the electronics throughout the car uses rare metals. It&#39;s possible that rare metals would be necessary for VTOL vehicles as well since they too will be electric. These metals are usually not hanging out in plain sight, just waiting for us to collect them. No, instead they are usually in inconvenient places that require destructive mining to get them out.</p><p>Another consideration is the impact more flying vehicles would have on wildlife, particularly birds. Would more air traffic mean more harm to birds? Airplanes already have problems hitting birds. Imagine the destruction that could happen with more flying vehicles.</p><p>Things get even more worrisome when we consider safety concerns. Most buildings are designed to withstand a car crashing into it on the ground. However, a VTOL aircraft crashing into it, is a completely different issue.Furthermore, what happens when the battery is dying and an immediate landing is necessary? For the safety of those below, a VTOL aircraft couldn&#39;t just immediately land the way a car can just immediately pull over.And the big question that has everyone nervous about autonomous cars- what happens if the auto function stops working? If the autonomous function fails in an AAV, will the passenger need to know how to fly it in order to make a safe landing? Do they parachute out?</p><p>Potential safety issues are one of the biggest issues that these companies have to figure out and are probably what will make the general population most hesitant to embrace the AAVs and VTOL vehicles.In this module we’ve only touched on some of the benefits and drawbacks of VTOL vehicles. There are no clear-cut answers, and some of the negative aspects will need to be addressed by engineers, entrepreneurs, politicians and regulators, and us as a society.</p></section><section><h3>Pros and Cons of Flying Cars</h3><p>Pros and Cons of Flying Cars</p><p>Without a doubt, flying cars would have major benefits.&#160;However, like most technology, there could be significant drawbacks as well.&#160;Let&#39;s explore some of the pros and cons of the proposed flying cars.</p><p>(Click the plus sign (+) below to read more about each topic for both pros and cons).</p><p>Flying Car Pros</p><p>Impact on Economy</p><p>First, let us consider the impact flying cars would have on the economy. The commercialization of VTOL vehicles would create a number of jobs and add more positions in existing fields f<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2b943e0012403ff80f30a55e78b5a17f','transportation-technologies-m2-l6-lesson-5','5f7adf535405c222996079a632d514c8','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Career Positions in AAVs and VTOL Vehicles</h3><p>Career Positions in AAVs and VTOL Vehicles</p><p>While watching this video, think about what you could do right now to prepare to work in the field of flying cars.</p><p>Welcome back, this is video 5 of the Flying Cars module.</p><p>So, are you ready to build a flying car? Would you like to be involved in the creation, planning, and development of VTOL vehicle technology? We touched on this before, but let&#39;s look more closely at the types of positions available for those interested in a career in AAVs and VTOL vehicles.</p><p>To get directly involved in the technology and development aspect of flying cars, companies are looking for: software engineers, calculation engineers, mechanical engineers, engineer engineers (you get the point!) and electrical technicians to name a few. Check the career section of websites of companies mentioned in this module, or just google “flying car or VTOL engineer jobs” to see what comes up. Many companies have listings on their websites for vacant positions. While it may seem premature to start looking for jobs while still in high school, getting a preview of the educational and experience requirements of jobs will give you ideas of steps to take to get on a path towards one of these jobs.</p><p>One thing that all of the companies have in common is their need for engineers. Creative engineers are crucial to forward-thinking companies. They need engineers who, not only excelled in school, but who also have the creativity and innovation to think differently about the way things are done, to spot ways that things can be improved, and, importantly, who have the persistence to work through puzzles and stumbling blocks.</p><p>So what kind of schooling does it take to be a flying car engineer? It depends on the type of engineering you want to pursue. Although some of the engineering positions only require a 4 year degree plus and perhaps a couple years of experience, many of the positions require even more schooling (meaning graduate degrees) and several years of additional industry experience.</p><p>However, if you have no desire to be an engineer, there are still ample opportunities to contribute to this field. Indirect positions, in other words, jobs that aren&#39;t directly concerned with the technology and development of aircrafts, but are nevertheless needed to help drive the industry forward include: public relations reps, accountants, recruiters, policy analysts, and others.</p><p>To get your feet wet, many of the companies offer internships for undergraduate students. These internships are competitive, however, so it would be to your advantage to participate in any science, technology, engineering, and math (also known as STEM) classes and programs available to you at this stage in your schooling.</p><p>Another interesting pathway to consider is Udacity&#39;s Flying Car Nanodegree Program. According to Udacity’s website, this program closely examines autonomous flight and air transportation. Perhaps most excitingly of all, it includes hands-on projects for students to gain practical experience in the field.</p><p>This is an exciting industry to be a part of, and from what we&#39;ve learned in this module, it is only going to grow.</p></section><section><h3>Careers in Flying Cars</h3><p>Careers in Flying Cars</p><p>If future you wants to brag about working in the flying car industry, there are a variety of career options to investigate.&#160;Currently, Lilium has a number of positions open for those interested in developing and improving the Lilium Jet.&#160;Support positions include:&#160;public relations rep, accountants, recruiters, and others.</p><p>For those interested in being more directly involved in the technology and development aspect, the company is looking for:&#160;software engineers, calculation engineers, mechanical engineers, and electrical technicians to name a few.&#160;All the available positions are listed on their website under “careers.”</p><p>Lilium is not the only company hiring in the industry.&#160;Terrafugia and Airbus also have listings on their websites for vacant positions.&#160;One common need throughout all companies is the need for skilled engineers.&#160;The requirements for these positions range from a bachelor&#39;s degree to a doctorate degree depending on the position level and the particular skill set.</p><p>Preparation Through STEM Courses</p><p>This need for engineers is one of the reasons public schools from elementary through high school are putting such an emphasis on science, technology, engineering, and math or STEM learning.&#160;Schools today are realizing how crucial these positions are to solving some of our world&#39;s problems like traffic and environmental concerns, and are working to provide those who will enter the workforce to solve these problems with the best background possible.&#160;So even before a student sets foot on a college campus, he or she can prepare to be a part of the science and technology industries by taking advantage of the classes and programs offered at the high school level and in communities.</p><p>Internships</p><p>For those who would like to experience work-life at a VTOL company while still in college, many of the companies offer internships.&#160;These internships, although competitive would allow you to experience the day to day life of working in the company before you graduate from college.</p><p>Udacity&#39;s Flying Car Engineering Program</p><p>According to Udacity&#39;s website “You’ll learn the core concepts required to design and develop robots that fly.&#160;You’ll work with the quadrotor test platform and our custom flight simulator to implement planning, control, and estimation solutions.&quot;</p><p>Let&#39;s explore some exciting careers in this sector.&#160;Expand each section below.</p><p>Car Engineer</p><p>As a flying car engineer, you would be involved in the design, development, and testing of flying car prototypes. This job requires expertise in aerospace engineering, mechanical engineering, and possibly electrical engineering. You would work on creating innovative propulsion systems, aerodynamic designs, and ensuring the safety and performance of flying cars.</p><p>Flight Test Pilot</p><p>Flight test pilots play a crucial role in evaluating and assessing the performance, handling, and safety of flying cars. They conduct test flights, collect data, and provide feedback on the fl<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('bf5862354700463666e0d126e25f8309','transportation-technologies-m2-l7-module-2-summary','5f7adf535405c222996079a632d514c8','Module 2 Summary','text',12,'<h2>Module 2 Summary</h2><section><h3>Module 2 Summary</h3><p>Module 2 Summary</p><p>byBloomicon</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Flying Cars!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this session, you:</p><p>Defined what a VTOL vehicle is and how it is different from existing modes of transportation</p><p>Identified historical attempts at building flying cars and technological advances that have contributed to the emergence of flying cars</p><p>Described current prototypes and demonstrate a basic understanding of their underlying technologies</p><p>Compared the pros and cons of flying cars on the economy, society, the environment, and safety</p><p>Predicted when they will ride in a flying car and justify their prediction</p><p>Examined existing companies&#160;that develop flying cars and matched a&#160;project name with each company</p><p>Appraised future career opportunities and pathways in the flying car industry</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3c0019d6c70416355d245be00f73176a','transportation-technologies-m2-l8-module-2-assignment','5f7adf535405c222996079a632d514c8','Module 2 Assignment','text',12,'<h2>Module 2 Assignment</h2><section><h3>Module 2 Assignment</h3><p>Module 2 Assignment</p><p>Transportation</p><p>Flying Cars - Short Answer Assignment</p><p>Short answer assignment</p><p>For this writing assignment, write a two-page, double spaced paper addressing the questions/topics listed.</p><p>Career Exploration:&#160;Visit the career section of a website of one of the flying car companies mentioned in the module or through your own research. Choose a position that sounds interesting and answer the following questions/prompts:</p><p>Write a summary of the job description</p><p>What are the requirements of the job in terms of education, experience, and language?</p><p>What steps would&#160;you have to take to secure that position in the future?</p><p>What&#160;do you think would be the most interesting aspect of the job?</p><p>Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8f7ca04a4a4d7db3f87c0ca4e6249734','transportation-technologies-m2-l9-module-2-project','5f7adf535405c222996079a632d514c8','Module 2 Project','text',12,'<h2>Module 2 Project</h2><section><h3>Module 2 Project</h3><p>Module 2 Project</p><p>Transportation</p><p>Flying Cars - Project</p><p>Project</p><p>In this assignment, choose one flying car project that is currently underway and create a one-page magazine ad to promote it to its intended consumer.</p><p>Your advertisement should:</p><p>Give the name of the company and product</p><p>Describe the product in detail, in your own words</p><p>Explain the benefits and appeal of the product</p><p>Be engaging, organized, and persuasive</p><p>Include any citations necessary for information and images</p><p>Review the rubric below to see how you will be graded.</p><p>Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Content</p><p>8 points The advertisement demonstrates a strong understanding of flying car technology. It contains several specific and accurate details.</p><p>7-6 points The advertisement demonstrates a satisfactory understanding of flying car technology. It contains some specific and accurate details.</p><p>5-0 points The advertisement demonstrates little to no understanding of flying car technology. It contains few to no specific and accurate details.</p><p>8</p><p>Persuasive</p><p>8 points The ad effectively persuades the customer of the perks of using this product and is effectively aimed at a target audience.</p><p>7-6 points The ad adequately persuades the customer of the perks of using this product and is sufficiently aimed at a target audience.</p><p>5-0 points The ad does not effectively persuade the customer of the perks of using this product or is not effectively aimed at a target audience.</p><p>8</p><p>Presentation</p><p>2 points The ad is well organized and presented in an engaging way.</p><p>1 point The ad is somewhat organized and is presented in a slightly engaging way.</p><p>0 points The ad is not organized well or is not presented in an engaging way.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7cbdd4e62807df98e8ac673aa32df10e','transportation-technologies-m2-l10-module-2-quiz','5f7adf535405c222996079a632d514c8','Module 2 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Flying Cars. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('1d052ba9c3e52abf85cda76ce0ff8050','transportation-technologies-module-3','504e3ab88df8552a07116f12aea44099','Module 3: Self-Driving Car Tech',3) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('19c90d6466e034cdd0c6d2e04a380a0d','transportation-technologies-m3-l1-introduction-purpose-and-objectives','1d052ba9c3e52abf85cda76ce0ff8050','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi, this is the introduction to the module on Driverless Car Technology.</p><p>Right now, thousands of brilliant minds are working toward preventing more than 6 million car crashes and 35,000 deaths per year from car accidents in the United States. They are dreaming up, designing, and building cars so futuristic, we may hardly recognize them as cars at all. They are working with cutting-edge software, hardware, LiDAR, and robotics. Perfecting, advancing, and streamlining the very best of autonomous technology.</p><p>And if none of that impresses you, they&#39;re doing it while making upwards of&#160;$200,000&#160;per year-&#160;straight out of college.</p><p>This is the world of autonomous driving vehicles, and it&#39;s the topic of this module. In this module, we are going to identify key technologies that enable self-driving cars. We will define and explore the role of sensors and algorithms in allowing driver-less cars to operate. And finally, we&#39;ll discover career opportunities and educational pathways in this new and growing industry.</p><p>Module Description</p><p>A man in a Autonomous driving test vehicle&#160;by riopatuca</p><p>License:&#160;All Rights Reserved</p><p>Self-driving cars are coming.&#160;In fact, in some places, they are already on the streets.&#160;In this module, we are going to examine the technology behind self-driving cars.&#160;We will examine how sensors in cars “see” an object and respond accordingly, as well as how fleets of driverless cars learn from each other, through a process called machine learning, by driving millions of miles on the road.&#160;And finally, we will investigate what the future might hold for those&#160;considering a career in the industry.</p><p>Objectives</p><p>In this module, students will</p><p>Describe the 6 levels of autonomous driving</p><p>Classify a driving feature into one of the 6 levels of autonomous driving</p><p>Identify key technologies that enable self-driving cars</p><p>Define algorithm and explain how algorithms allow self-driving cars to operate</p><p>Identify career opportunities in self-driving cars and educational paths to enter those careers</p><p>Examine technologies that enable self-driving trucks</p><p>Polling Question</p><p>When would you be willing to ride in a driverless car?</p><p>It can deliver my pizza, but I wouldn’t want to ride in one&#160;I’d be willing to try riding in one today!&#160;Once the technology is advanced enough that it is safer than riding with a human driver&#160;Only when the technology is so advanced that there is no possibility of an accident&#160;Never</p><p>Make a selection to see the results so far.</p><p>How did your prediction compare to your classmates?&#160;Let’s see how your answer changes as you learn more about driverless car technology!</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>also known as autonomous cars, robotic cars, or self-driving cars, and are cars that utilize robotics in order to navigate and sense the environment around the vehicle without human input</p><p>Sonar</p><p>sound navigating and ranging.&#160;It uses sound waves to detect and measure the distance of objects</p><p>Self-driving car</p><p>radio direction and ranging.&#160;It uses radio waves to measure distance</p><p>Radar</p><p>light detection and ranging.&#160;It uses laser beams to detect objects</p><p>Lidar</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>also known as autonomous cars, robotic cars, or self-driving cars, and are cars that utilize robotics in order to navigate and sense the environment around the vehicle without human input</p><p>Answers for question: 1</p><p>Sonar</p><p>Radar</p><p>Self-driving car</p><p>Lidar</p><p>2.</p><p>sound navigating and ranging. It uses sound waves to detect and measure the distance of objects</p><p>Answers for question: 2</p><p>Sonar</p><p>Radar</p><p>Self-driving car</p><p>Lidar</p><p>3.</p><p>radio direction and ranging. It uses radio waves to measure distance</p><p>Answers for question: 3</p><p>Self-driving car</p><p>Sonar</p><p>Radar</p><p>Lidar</p><p>4.</p><p>light detection and ranging. It uses laser beams to detect objects</p><p>Answers for question: 4</p><p>Self-driving car</p><p>Sonar</p><p>Radar</p><p>Lidar</p><p>a field of study that focuses on advancing machines&#39; abilities to interpret an image or series of images</p><p>Algorithm</p><p>a set of rules used to solve a problem</p><p>Deep learning</p><p>a collection of algorithms used in machine learning, used to model high-level abstractions in data</p><p>Platooning</p><p>science, technology, engineering, and math.&#160;Crucial components to the field of self-driving cars</p><p>Computer vision</p><p>pairing trucks 30-50 feet apart to be more aerodynamic and save fuel</p><p>STEM</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>a field of study that focuses on advancing machines&#39; abilities to interpret an image or series of images</p><p>Answers for question: 1</p><p>Platooning</p><p>Computer vision</p><p>Deep learning</p><p>STEM</p><p>Algorithm</p><p>2.</p><p>a set of rules used to solve a problem</p><p>Answers for question: 2</p><p>Algorithm</p><p>Platooning</p><p>Deep learning</p><p>STEM</p><p>Computer vision</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f68b000ffbb5cbbc16cab9bcc446057b','transportation-technologies-m3-l2-lesson-1','1d052ba9c3e52abf85cda76ce0ff8050','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Level Differences of Autonomous</h3><p>Level Differences of Autonomous</p><p>While watching this video, pay attention to the difference between a driver assisted car and a self-driving car.</p><p>Welcome this is video one for this module on Driverless Car Technology.</p><p>Perhaps you&#39;ve been hearing the phrase “autonomous car” or “self-driving car” or “driver-less car.” All of these terms mean essentially the same thing. Simply put, they refer to a computer-controlled car that drives itself.</p><p>That seems pretty straightforward until we start throwing around other terms like driver assisted, conditional automation, and full automation. All these phrases actually mean different things and refer to different levels in the world of self-driving technology. Let&#39;s break down the different levels and use examples to understand their differences.</p><p>Level 0, or no automation means the driver is handling the car the entire time. Even a car with forward-collision monitoring is considered a level 0 because although it may blink or beep at you to let you know the car in front of you is getting way too close for comfort, it&#39;s not actually going to stop you. Another example is regular cruise control. This is the world we have been living in for the last 50 years plus. And as we know, human drivers can make mistakes and can also be distracted or drowsy. As technological advances have improved, car makers have started to add features to assist drivers.</p><p>This brings us to Level 1, which adds some driver assistance. Driver assisted means the system can EITHER steer OR control speed but not both at the same time. Adaptive cruise control is an example of a level 1 feature because the car can sense when it is approaching another car and will decelerate to maintain a set gap. Most new cars sold by 2021 will have emergency breaking, also level 1 feature. Lane keeping assistance is another example because the car will actively take over the steering function to help prevent unintentional lane wandering.</p><p>At level 2 we get partial automation. This is when, in some situations, a car can both steer AND accelerate or decelerate at the same time. Traffic jam assist and the autopilot function on highways are examples of level 2 functions. Even though the car is doing some of the work, the driver must still be ready to resume control IMMEDIATELY.</p><p>When we get to level 3, we get conditional automation. In other words, the car is capable of being in control for a significant amount of time, but if things start to get a little dicey and the system can&#39;t function correctly, the car is going to tell you to intervene (kind of like driving with someone who has their learner&#39;s permit). Currently, there are no cars on the market operating at a level 3. Interestingly, Google&#39;s self-driving project achieved level 3 when the car was able to drive itself from the on-ramp to the off-ramp of a highway. However, they chose not to commercialize the car. They found that those who test drove it put too much faith in the system and couldn&#39;t be counted on to reliably resume control.</p><p>The bulk of effort for self-driving car companies is happening at level 4 or the high automation level. Here, the car is fully capable of driving the entire time under certain conditions. The driver doesn&#39;t even need to act as a backup as long as it&#39;s within the conditional limits. These limits include things like bad weather or certain speeds. At a nuclear power plant in France, there are 6 Navya shuttles operating at a level 4 actively taking workers around the private workplace.</p><p>Finally, there is level 5 or full automation. At this level, there are no restrictions on the car&#39;s driving and no driver is needed at all. Some theorize that cars may look completely different at this level. After all, if everything is controlled by the car at all times, there&#39;s no need for anything a driver would use like a steering wheel or brake and gas pedals. It would all be controlled by the car&#39;s computer.</p><p>Now that you understand the levels of autonomy, we can talk about the technology involved at the different levels. We can also explore how technology progresses as the car gains more autonomy.</p></section><section><h3>Defining Autonomous Levels</h3><p>Defining Autonomous Levels</p><p>Introduction</p><p>Let&#39;s begin by understanding what we mean when we say “self-driving car.” Self-driving cars are also known as autonomous cars, robotic cars, or driver-less cars.&#160;All these names refer to cars that utilize robotics in order to navigate and sense the environment around the vehicle without human input.</p><p>Or at least that&#39;s the capability of a level 5 driver-less car.&#160;Driver-less cars range in their autonomous abilities from level 0, which is a car with no self-driving features.&#160;Even if it has monitoring systems to alert the driver of a possible collision, it is still considered level 0 because, aside from setting off visual or auditory warnings, the car is still completely under the driver&#39;s control.</p><p>Level 0</p><p>The levels actually begin at zero.&#160;At level zero, there is no automation.&#160;Even if the car has warning systems, if the driver must monitor and actively drive the whole time and the car cannot take over under any situation, then it is a level zero car.</p><p>Read about the other levels by expanding the corresponding sections below.</p><p>License:&#160;All Rights Reserved</p><p>Level 1</p><p>A level one car has one or more autonomous features and uses driver assistance. It may be able to control speed or steering, but not both simultaneously. The driver must still monitor the drive the entire time.</p><p>License:&#160;All Rights Reserved</p><p>Level 2</p><p>At level two, there is partial automation. Some luxury car companies are currently producing vehicles that can control both speed and steering at the same time. An active driver is still needed behind the wheel at all times to monitor what the other cars are doing and what is going on in the environment.</p><p>License:&#160;All Rights Reserved</p><p>Level 3</p><p>Level three cars provide conditional autonomy. At this level, autonomy is based on the condition of the road or situation. The car will handle driving as long as conditions are optimal, but once the system recognizes an upcoming problem, it is going to notify the driver to intervene. Some companies are<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b9fe18bf2405c51dfbe5a7026e08d2ea','transportation-technologies-m3-l3-lesson-2','1d052ba9c3e52abf85cda76ce0ff8050','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>How Driver-less Cars Work</h3><p>How Driver-less Cars Work</p><p>While watching this video,&#160;see if you can spot ways scientist have “borrowed” concepts from biology.</p><p>Hello and welcome back, this is video 2 for this module on Driverless Car Technology.</p><p>Let’s start with a basic question: How do driver-less cars work? Of course, the answer to that could take years to explain. For some engineers, it’s their life&#39;s work. But throughout this video and module, we are going to attempt to answer that question. Fortunately, we won’t worry about the basics of how a car and the internal combustion engine work. We’ll stick to the sensors and technologies that are added to, or even built into cars, which make autonomous driving possible. Let’s start with some important sensor technologies, namely: sonar, radar, LiDAR, and digital imaging.</p><p>We&#39;re going to start by talking about sonar. The idea for sonar came from observing animals in nature. A dolphin uses echolocation to help it navigate under water where visibility is only a few feet. The dolphin makes a high pitch sound underwater. When the sound waves hit an object, some of that sound echoes back to the dolphin. Based on how long the sound took to get back, the dolphin can determine how close the object is.</p><p>After World War One, humans figured that if it worked for animals under water, maybe it could work for humans somehow.</p><p>Although sonar is useful and cheap at level zero - for example letting you know that you are about to hit that parked car behind you- it doesn&#39;t have the range that self-driving cars demand.</p><p>Radar is similar to sonar, but instead of sound waves, it uses radio waves. Radar has a much farther range of detection and tracking. It also works in just about any kind of weather.</p><p>Radar technology has the sort of range we need for self-driving cars. But we&#39;re not all the way there yet. For one, radar cannot detect small objects. This is a big problem if there&#39;s say, a rock in the road that is too big to be run over but too small to be detected by radar. Radar also can&#39;t tell us exactly what an object is, just that something is there.</p><p>That is where LiDAR, or light detection and ranging, really shines (no pun intended!). Sorry to disappoint you, but LiDAR is not a device that tells you when someone is lying. Being able to detect even small objects and build an exact 3D image of an object is where LiDAR really becomes a desirable component to driverless cars. LiDAR is the technology Google&#39;s “Waymo” uses.</p><p>LiDAR uses a similar process to sonar and radar except it uses laser beams. The laser beams are sent out and when they hit an object, they bounce back. Based on exactly how long it took the light to bounce back, LiDAR is able to generate a 3D map.</p><p>Imagine being in a dark room full of objects. You can&#39;t see them, but you know they are there. You have a can of glow in the dark spray paint. As you spray the paint around, the objects come into view. Now imagine you had not just one can of paint, but millions of cans of paint firing in all directions. You&#39;d figure out the objects in the room pretty quickly. This analogy gives you a simple idea of how LiDAR works. Except instead of spray paint, LiDAR uses laser beams. And they are firing every second.</p><p>Being able to detect small objects and generate a 3D map is another huge step toward self-driving cars. But LiDAR isn&#39;t perfect either. For one, it&#39;s extremely expensive. The other shortcoming is its less-than-impressive performance in bad weather conditions. With enough snow, the sensor, which is usually on top of the car, can be completely covered mid journey.&#160;Yikes!</p><p>In fact, Tesla, a major automotive company is out to create a driver-less car and they&#39;re not sitting back waiting for the LiDAR problems to sort out. They are building driver-less cars using 8 surround cameras to provide 360 degrees of visibility. It also uses ultrasonic sensors and forward-facing radar.</p><p>Finally, let&#39;s talk about the role digital cameras play in driver-less technology. Digital cameras are like the eyes of the self-driving car. For digital cameras to work, light comes streaming in from the object you are taking a picture of and hits the image sensor chip. The chip breaks the picture up into millions of pixels. The sensor them measures how bright the pixel is and its color and assigns it a number. It does this for every pixel. This numeric form is what the computer understands.</p><p>Although extremely useful, digital cameras have shortcomings too. For one, there is no depth calculation. To combat this issue, some manufacturers place multiple digital cameras on a single car. Then, the car&#39;s computer can reconstruct a 3-D model of the scene. Another solution is structured-light cameras which can calculate depth. However, these cameras don&#39;t work well during the day. They also don&#39;t work well beyond about 10 yards.</p><p>As we can see, all of these technologies have some use, along with some drawbacks. Engineers must figure out a way to piece together all the information that comes from a combination of sensors. The developments of these technologies, Radar, sonar, and LiDAR in the past hundred years has been crucial to creating self-driving cars. As scientists and engineers perfect these technologies, it will, in turn bring us that closer to capable, safe, self-driving cars.</p></section><section><h3>Key Hardware Technologies for Driverless Ca</h3><p>Key Hardware Technologies for Driverless Car</p><p>License:&#160;All Rights Reserved</p><p>Let’s start by looking at some of the key hardware technologies that go into making a driverless car possible.&#160;Expand the sections below.</p><p>Sonar</p><p>First, let&#39;s look at sonar. Sonar stands for sound navigating and ranging. It uses sound waves to detect and measure the distance of objects.&#160;This is similar to echolocation, which is how animals like bats, dolphins, and whales navigate.</p><p>It wasn&#39;t until after World War One that humans began to use sonar. The first application was for submarines. Sonar was a breakthrough for submarine warfare. When you are underwater, light and radio waves don’t travel so well, but luckily sound does! You can imagine the welcome relief it was to have a way to detect objects while deep underwater.</p><p>Newer cars sometimes use this technology for parking <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f1c7493ff39dbc566d07d0ecc8fbbebd','transportation-technologies-m3-l4-lesson-3','1d052ba9c3e52abf85cda76ce0ff8050','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Three Steps Driverless Cars Navigate</h3><p>Three Steps Driverless Cars Navigate</p><p>While watching this video,&#160;pay attention to the role digital photos play in helping machines learn!</p><p>Hey and welcome back, this is video 3 for this module on Driverless Car Technology.</p><p>Teaching or programming a robot to do something that a human does requires a fairly standard procedure. We map out or outline the steps that a human must take in order to complete an action. Then we teach a robot to perform those same steps. Simple right? Well, as you can imagine, driving a car is a complex process, with a lot of variables, or things that can change. Think of all the information that a human driver must process: the weather, other drivers, pedestrian, traffic rules, signs, as well as unspoken “rules of the road”. A human driver gathers all that information, combines it with what they learned in driver’s education plus years or decades of previous experience driving, and makes decisions or actions based on that information. Can we really teach a robot to do and master something so complex?</p><p>Of course, this is possible, because there are already self-driving cars out there on the road. So how do they make it work? It really comes down to three steps: observe, process, and act.</p><p>The observing part takes place through the sensors that we discussed in the first video: Sonar, Radar, LiDAR, and digital imaging components all take in information about the cars surroundings. The final step, acting, is relatively simple and has been within the realm of robotics programming for decades. Once a course of action has been chosen, actuators make the car turn, hit the brakes, push the gas pedal, etc.</p><p>The middle step, processing, is by far the trickiest and most complex. The car’s computer needs to make sense of those objects observed by LiDAR, RADAR, Sonar, and Digital Images. In comes the field of computer vision, a relatively new branch of computer science. It&#39;s the field that improves a machine&#39;s ability to interpret images.</p><p>That might seem all fine and easy but let&#39;s investigate this for a minute. Let&#39;s take dogs for example. Here is a picture of a dog sitting face-on. But a dog is still a dog when it&#39;s lying on its back or when it&#39;s partially hidden. What about when the dog walks on its hind legs? WE know that it is still a dog in all of these scenarios, but the computer must be taught to recognize a dog in all these and MANY more scenarios.... and that&#39;s JUST for identifying a dog!</p><p>Luckily, we live in the age of the internet! The internet is a goldmine of pictures and images. Thanks to the work of nearly 50,000 people under a project called Imagenet, approximately 15 million images were analyzed, categorized, and labeled to provide a robust data network for machine learning.</p><p>Thanks to this data, computer scientists have developed layers and layers of algorithms to enable a machine to correctly identify an object under a variety of situations. Once the object is identified, then algorithms programmed into the computer of a driver-less car determine how the car reacts. Algorithms are a set of rules or procedures that tell the computer what to do when it comes across a particular problem.</p><p>This process of feeding the computers visual data and programming layers and layers of algorithms is called deep learning. When it comes to self-driving cars, it&#39;s pretty important that a computer can correctly identify a group of pedestrians as being people and not as being a group of trees! Thanks to deep learning, robots are growing more accurate every mile driven.</p></section><section><h3>Computer Vision of Driverless Cars</h3><p>Computer Vision of Driverless Cars</p><p>Now let’s move on to some software technologies that go into making a driverless car possible.</p><p>Computer Vision</p><p>Another crucial component of driverless cars is computer vision.&#160;Computer vision, or machine vision as it is also known, is a field of study that focuses on advancing machines&#39; abilities to interpret an image or series of images.&#160;For example, it is not enough for a driverless car to recognize that there is an object on the road.&#160;The driverless car must be able to distinguish whether it is a paper bag that can be run over or a big rock that should be avoided.</p><p>Watch the following video to see a driverless car in action:</p><p>A video showing a demonstration of a driverless car In Royal Greenwich.</p><p>Video Title:&#160;Driverless cars in Royal Greenwich</p><p>Video Publisher:&#160;Royal Greenwich</p><p>License:&#160;Creative Commons Attribution license (reuse allowed)</p><p>Note:&#160;There are no closed captions for this video.</p><p>Review the tabs below to learn about some important concepts when it comes to driverless vehicles.</p><p>Algorithm</p><p>Let&#39;s back up and understand what an algorithm is.&#160;An algorithm is a set rules used to solve a problem.&#160;For instance, maybe you or one of your friends knows how to solve a Rubik’s cube.&#160;If you just turn the sides randomly, it’s practically impossible to get all the colors to line up on each side.&#160;In order to solve it, a set of rules needs to be followed, in order, to get each side to line up.&#160;There are actually many different types of algorithms and techniques used for solving Rubik’s cubes.</p><p>As related to computer science, an algorithm is a set of rules or procedures programmed into a computer to enable the computer to solve particular problems.&#160;Just about every task performed by a computer uses an algorithm.&#160;And driver-less technology is no different.</p><p>Deep Learning</p><p>So how does a computer go from recognizing that there is an object to correctly identifying that object? The answer lies in a concept called deep learning.</p><p>Deep learning is “a subfield of machine learning concerned with algorithms inspired by the structure and function of the brain called artificial neural networks.”</p><p>Deep learning is inspired by how we learn. A child learns to correctly identify objects by seeing it in a variety of situations, environments, positions, etc. So, step one to teaching a computer to see is by feeding the computer system a wide variety of images. Thanks to a project called Imagenet, computer scientists are able to feed millions of pictures to the computer. The project took millions of digital photos upl<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('39454def3d7d618d9b65437354a641b0','transportation-technologies-m3-l5-lesson-4','1d052ba9c3e52abf85cda76ce0ff8050','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Careers in Driver-less Technology</h3><p>Careers in Driver-less Technology</p><p>While watching, pay attention to programs that will lead you to a career in driver-less technology.</p><p>Welcome back, this is video 4 for this module on Driverless Car Technology.</p><p>Hopefully by now you’ve grasped the amazing potential of the technology within self-driving cars. All of these technologies are also opening completely new fields and opportunities. Are you itching to become a part of this growing field? Carnegie Mellon University in Pittsburgh offers a graduate program called “computer vision” through the computer science school.</p><p>Clearly this is a field of study that has massive applications to driver-less cars. Companies working on such projects are hiring people from this program. And they&#39;re hiring them with pay packages nearing $200,000 right after school! That is pretty much unheard of, even in engineering, which is already well-known for being a comparatively high paying industry for graduates.</p><p>Carnegie Mellon isn&#39;t the only school that offers programs in computer vision. The University of Texas, Massachusetts Institute of Technology (MIT), Princeton, New York University, and many more offer similar programs of study. Because they are working with such cutting-edge technology, and let’s not forget the pay packages, these programs are EXTREMELY competitive to get into. A strong background in math, physics, engineering, and/or computer science is crucial. In fact, these are great areas to consider majoring in for an undergraduate degree.</p><p>But what about even before college? Are there programs available to high school students to help you gain an edge in this competitive field? The answer is yes! There are a variety of summer programs for high school students interested in science, technology, engineering, and math, or&#160;STEM&#160;programs. The top programs, like the top colleges, are very selective as well. These programs look at your grades, particularly in math and science, recommendations from teachers, and your participation in other science and math programs. Showing a course like this on your application will help as well. Look into STEM courses and programs at your school or offered through community programs. If someone you know is in the field (or heck even if you don’t know them!), reach out to them and let them know your interest and passion for driverless car technology. You never know where good ol&#39; word of mouth will take you!</p><p>There are also free or relatively inexpensive online courses that really dig into the technical aspects of computer science and self-driving cars. Stanford University has a free Intro to Computer Science course through their Udacity program. In fact, Udacity even has a nanodegree program in self-driving car engineering! But the program does require quite a bit of background knowledge, so take advantage of free courses from Udacity or other online education providers, which are essential background knowledge for the nanodegree.</p><p>Now let’s talk about several different companies that are searching for employees in the driverless car industry and what they are looking for in candidates. The first group of course to consider are the car companies themselves. Tesla, Ford, Toyota, and General Motors have all announced big commitments to driverless cars. Many of these companies are looking for software and systems engineers to help them build and perfect the technologies for their self-driving cars.</p><p>Next, consider that all these car companies don’t make every single part from scratch! They have supplier partners that design and build parts that go into their cars. These companies, such as Delphi and Continental, also need engineers to develop the products and algorithms that will be building blocks for tomorrow’s driverless cars.</p><p>Then there are technology companies like Google or Baidu, which is known as the “Google of China”. While these companies aren’t making cars themselves from scratch, they are integrating the hardware (or the car) with the algorithms and technologies, like LiDAR to solve problems.</p><p>One final group we can mention as far as career opportunities are university and research institutions. MIT has a computer science and artificial intelligence lab which is looking for engineers, and the Southwest Research Institute needs researchers to work on cooperative systems.</p><p>As you can see, opportunities abound for engineers and problem-solvers to really push things forward in autonomous vehicles. Whether it&#39;s to help make the roads safer to save lives or to earn a substantial paycheck (or both!), a career working with driverless cars, is definitely something to consider.</p></section><section><h3>Automotive Jobs of the Future</h3><p>Automotive Jobs of the Future</p><p>License:&#160;All Rights Reserved</p><p>Automotive Jobs of the Future</p><p>The number of people it takes to make cars “smarter” is substantial.&#160;As cars become more connected and technologically advanced, the types of jobs available in the industry will change as well.</p><p>More and more technology-centered careers will open in the automotive sector.&#160;Take a look at some of the careers that will likely be available in the auto industry in the next decade or so.&#160;Pick your top 5 career paths, which sound interesting, in the list below and click on the title to learn more about that career.</p><p>Electrical engineers</p><p>Analytic experts</p><p>Interaction designers</p><p>Web programmers</p><p>Autonomous driving engineers</p><p>Customer care experts</p><p>Sustainability integration experts</p><p>Industrial engineers</p><p>3D printing engineer</p><p>Alternative propulsion engineer</p><p>Flashcard Transcript</p><p>Electrical engineers:&#160;more and more electrical components are being added to cars. Not to mention, electric cars are becoming more and more common. Therefore, it is likely car companies will need highly qualified electrical engineers to develop this growing trend.</p><p>Analytic experts:&#160;as smart cars collect more data, analytic experts will need to configure algorithms in order for the data to be useful to the driver.</p><p>Interaction designers:&#160;all the bells and whistles of a futuristic car mean nothing if they are not easy enough for the drivers to make use of those features. Interaction designers will ensure function, artistry, and usability come togethe<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b9584cb8073b3ef126204815fd1c60f1','transportation-technologies-m3-l6-lesson-5','1d052ba9c3e52abf85cda76ce0ff8050','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Driverless Trucks of the Future</h3><p>Driverless Trucks of the Future</p><p>While watching the video below, think about how driverless trucks could look in the future.</p><p>Top tech topic. Volvo Truck’s Cabin-Less Self-Driving-Vera. Vera is a set to go to work moving containers around da logistics center. Scania’sCabless Truck shows what the driverless future of mining looks like. Tesla Semi Truck.The safest, most comfortable truck ever. Four independent motors provide maximum power. T-Pod: Einride- Sweden’s Electric Robo-Truck. Made for life in the forest-remote control system for self-driving truck. Mercedes Benz- The future truck 2025. The future truck 2025 forecasts a less demanding long haul. Kodiak Robotics truck startup.A Google, Uber self-driving veteran. Self-driving trucks are more futuristic than the hype would indicate. Here you can find the latest incredible inventions and welcome to Top Tech Topic Channel!! The amazing future of this world. Thanks for watching, please subscribe. Volvo Truck-VERA. Cabin-less driving hauler takes on its first job. Is getting prepared for her first assignment.Electric.Connected.Autonomous. Vera will form part of a transport solution. In collaboration with ferry and logistics company DFDS. Several Vera vehicles are intended to operate on a pre-defined route, partly on public roads. Transporting goods from a logistics center to a port terminal in Gothenburg. The purpose is to enable a seamless transport flow. “This assignment is the first step of a progressive journey, for Vera and the transport industry.” Scania’s cables truck. Shows what the driverless future of mining looks like.An autonomous connected transport concept.Runs on renewable biofuel.Scania AXL. Tesla Semi Truck. Semi is the safest, most comfortable truck ever. Unworkable.Preposterous.Unreasonable.Unfeasible.Impractical.Unachievable.Impossible. T-Pod: Einride. Electric Robo-truck is made for list in the forest. And it’s here. The world’s first Autonomous inter-connected loggin truck. All-electric, heavy duty, T/Log. It always seems impossible until it’s done. Intelligent movement.Einride is transforming the way we transport goods. Sweden’s Electric Robo-Truck. Remote control system for self-driving truck. Every year around 500 million barrels of oil are used to fuel European trucks alone. This is the T-Pod. Einride’s electric, self-driving truck. The T-Pod can carry 15 pallets of goods for 124 miles…Producing zero emissions. But the T-Pod doesn’t just rely on self-driving technology… It’s remote operation abilities allows drivers to monitor and operate multiple trucks at once. The T-Pod is part of a much larger infrastructure…That allows the T-Pods to go on much longer journeys…And finally transform a hugely outdates industry. Einride.Einride is the Change. #ZeroEmissionTransport. Mercedes Benz. The future truck 2025 forecasts a less demanding long haul. Long-haul trucking will be the first commercial application of autonomous technology at scale. Kodiak Robotics. A Google, Uberraises $40M for robot truck startup. 16 months ago Kodiak Robotics was founded to make that vision a reality. Today, we’re coming to Texas. Delivering freight using our self-driving technology.Making Texas our home base for testing and operations.All while keeping safety our top priority. Our journey is just beginning. It’s an exciting road ahead. Kodiak. Kodiak.ai. Meet Mark from Los Angeles, 24 years on the road. SELF Driving Truck. Truck driver connect with uber freight. Mark picked up a load this morning using Uber Freight. He’s doing short haul to transfer in Topock, Arizona. Meet one of Uber’s self-driving trucks, operated by Larry. The self-driving truck is on a long haul from the Midwest. Both trucks arrive in Topock at the same time. In the coming years, transfers like this will happen all across America. They’ll still require the hands-on work that only truckers can do. The self-driving truck heads east for another long haul. And Mark takes his new load west back to Los Angeles. He’ll be home in time for dinner. UBER. Refuse handling like you’ve never seen it before. VOLVO takes out the trash. With an autonomous garbage truck. Right now Volvo trucks and Swedish waste management company Renova are testing how autonomous vehicles can contribute to safer and more efficient refuse handling in a better working environment. Driving a truck in a built up residential area imposes major demands on safety. The refuse truck being used in a test continuously monitors it’s surroundings and immediately stops if an obstacle appears. The first time the truck is used in a new area it’s route is mapped with the aid of sensors and GPS. Next time the truck knows exactly where to drive. At the first stop the bin is emptied the same way as today. When the operation is complete, the truck reverses automatically to the next bin on the drivers command. If the street is blocked, the truck can automatically drive around the obstacle. The driver does not need to walk to the cab every time the truck moves. And since there is not need to get in and out of the truck all the time, there is less risk of work-related injuries. A lot of research and development before self-driving refuse trucks can become a reality. But with out a doubt, vehicles with varing degrees of automation will be apart of our future. Volvo trucks.Driving progress.Starsky Robotics. Make trucks autonomous and remote controlled. Here’s to the endless roads. To early mornings.To time alone. To the ones we miss. And the endless days without them. Here’s to the new way. The future of driverless trucks is here. And they’re not driverless. Thanks for watching! TopTechTopic Channel. Futuristic Self Driving Truck.</p><p>Video Title:&#160;These Trucks are Ahead Of Tesla | 10 Amazing Future Trucks ▶1</p><p>Publisher:&#160;TopTechTopic</p><p>Video&#160;License:&#160;Creative Commons Attribution license (reuse allowed)</p><p>Note:&#160;There are no closed captions for this video.</p><p>In the next reading, you&#39;ll continue to learn about the future of trucking.&#160;You will discover some of the key strategies being applied to the technology of trucking to move from conceptualization to reality!</p></section><section><h3>Future of Driverless Trucks</h3><p>Future of Driverless Trucks</p><p>(opens in a new tab)</p><p>The Future of Truck Drivers and the Trucking Industry in the Era of Driverless Trucks</p><p>The advent of driverless vehicles, inc<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('bdf34a6afd3be342af2a215abc7684b2','transportation-technologies-m3-l7-module-3-summary','1d052ba9c3e52abf85cda76ce0ff8050','Module 3 Summary','text',12,'<h2>Module 3 Summary</h2><section><h3>Module 3 Summary</h3><p>Module 3 Summary</p><p>Autonomous self-driving vehicle with radar 3D&#160;by Martial Red</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Self Driving Car Technology!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Differentiated between the 6 levels of automation in self driving cars</p><p>Classified a driving feature into one of the 6 levels of autonomous driving</p><p>Identified key technologies that enable self-driving cars (LiDAR, radar, other sensors)</p><p>Defined algorithm and explain how algorithms allow self-driving cars to operate</p><p>Identified career opportunities in self-driving cars and educational paths to enter those careers</p><p>Examined technologies that enable self-driving trucks</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5e760ffada2109fb5d33e3640a14c92e','transportation-technologies-m3-l8-module-3-assignment','1d052ba9c3e52abf85cda76ce0ff8050','Module 3 Assignment','text',12,'<h2>Module 3 Assignment</h2><section><h3>Module 3 Assignment</h3><p>Module 3 Assignment</p><p>Transportation</p><p>Self-driving Car Technology - Short Answer Assignment</p><p>Short answer assignment</p><p>For this writing assignment, choose&#160;one&#160;of the two short-answer prompts below and write a two-page, double-spaced paper addressing the questions/topics listed.</p><p>1.&#160;Career Exploration:&#160;Visit the career section of Google&#39;s Waymo project, or choose a job you research online. Choose a position that sounds interesting and answer the following questions/prompts:</p><p>Write a summary of the job description</p><p>What are the requirements of the job in terms of education, experience, and language?</p><p>What steps would you have to take to secure that position in the future?</p><p>2.&#160;Book, Movie, or TV review:&#160;With the approval of a parent or guardian, find a book, movie, or TV show to read or watch, which features a driverless vehicle (you can find plenty of ideas online), and answer the following questions:</p><p>How is the driverless car being used?</p><p>What technologies are mentioned or used with the driverless car? If none are specifically mentioned, what technologies do you think are used (or are implied)?</p><p>Is the driverless car portrayed positively or negatively?</p><p>What are the riders doing in the car while it is driving them?</p><p>Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('79e43cc9eabf16a846c31414b19da623','transportation-technologies-m3-l9-module-3-project','1d052ba9c3e52abf85cda76ce0ff8050','Module 3 Project','text',12,'<h2>Module 3 Project</h2><section><h3>Module 3 Project</h3><p>Module 3 Project</p><p>Transportation</p><p>Self-driving Car Technology - Project</p><p>Project</p><p>In this assignment, you will create an infographic that explains and examines self-driving cars. &#160;&#160;Infographics are visual charts that take a complicated or boring topic and present them in a fun, quick, and visually engaging way. Infographics are designed with a purpose in mind: often to inform or persuade. You can choose from a variety of web tools available to make your graphic.</p><p>Your infographic should:</p><p>Differentiate between the levels of automation in self-driving cars</p><p>Have a theme or purpose (to argue for or against self-driving cars, detailed explanation of one type, discussing possible careers in the field, describing the new technologies involved, etc.)</p><p>Discuss some of the technologies involved</p><p>Point out positive and negative features of the technology</p><p>Persuade the audience with facts</p><p>Be creative and visually engaging</p><p>Be organized and succinct</p><p>Use citations where needed</p><p>Review the rubric below to see how you will be graded.</p><p>Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Content</p><p>8 points The infographic demonstrates a strong understanding of the types of self-flying cars and their technology. It contains several specific and accurate details, including positive and negative features.</p><p>7-6 points The infographic demonstrates a satisfactory understanding of the types of self-flying cars and their technology. It contains some specific and accurate details, including positive and negative features.</p><p>5-0 points The infographic demonstrates little to no understanding of the types of self-flying cars and their technology. It contains few to no specific and accurate details, including positive and negative features.</p><p>8</p><p>Persuasive</p><p>6 points The infographic effectively presents a theme or opinion and thoroughly supports it with facts.</p><p>5 points The infographic adequately presents a theme or opinion and sufficiently supports the it with facts.</p><p>4-0 points The infographic does not effectively present a theme or opinion or does not sufficiently support it with facts.</p><p>6</p><p>Presentation</p><p>4 points The infographic is well organized and presented in an engaging way.</p><p>3 point The infographic is somewhat organized and is presented in a slightly engaging way.</p><p>2-0 points The infographic is not organized well or is not presented in an engaging way.</p><p>4</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1273fbd1a6ae0c6885feba3eecfdadc8','transportation-technologies-m3-l10-module-3-quiz','1d052ba9c3e52abf85cda76ce0ff8050','Module 3 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Self-Driving Car Tech. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('c61917250f2b66bfd056efe68ac3f13d','transportation-technologies-module-4','504e3ab88df8552a07116f12aea44099','Module 4: Self-Driving Cars in Society',4) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('328f707a59422db720cd6eb5247feb1e','transportation-technologies-m4-l1-introduction-purpose-and-objectives','c61917250f2b66bfd056efe68ac3f13d','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>close</p><p>Welcome, this is the introduction to the module on Driverless Cars in Society.</p><p>Let me tell you a bit about Homer. Homer provides taxi services to residents of a retirement community. In this particular retirement community, the average age is 76. Many are unable to drive anymore, so Homer&#39;s services are highly desirable. One day, Homer was driving along with Ms. Jackson, an 82 year old in the community. Suddenly, he saw an approaching golf cart and jerked to a stop. Slowly, Homer inched forward, but jerked to a stop again when the golf cart cut right in front of the taxi.</p><p>The golfers went along unharmed. Ms. Jackson continued to her destination, not minding the jerky ride. And Homer continued to drive other residents to and from various places.</p><p>It&#39;s a pretty boring story... except for one major detail. Homer is not a taxi driver. Homer IS the taxi, created by a company named Voyage which creates self-driving taxis for residential communities.</p><p>This module is going to dig deep into the implications that self-driving cars will have on society. There are a lot of positives to this technology, but several risks as well. There are many questions with no clear-cut answers, but nevertheless are ones that you, me, and all of us will need to figure out as citizens, riders, and pedestrians.</p><p>Module Description</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Self-driving car technology is advancing quickly.&#160;In some cities, there are already self-driving cars on the streets.&#160;But do we really need self-driving cars?&#160;Is society ready for self-driving cars?&#160;In this module, we will start by outlining the need for driverless vehicles by explaining some of the problems and drawbacks of the current human-operated world we currently live in.&#160;Then we are going to examine the pros and cons of driverless cars.&#160;We will look at the benefits and risks of several aspects of driverless cars, including safety, cybersecurity, mobility, cities, and jobs.&#160;We will examine social dilemmas and privacy issues associated with self-driving cars in society.&#160;By the end of this module, you will be able to examine both sides of the issue of self-driving</p><p>Objectives</p><p>In this module, students will</p><p>Examine the risks and costs of human operated cars</p><p>Evaluate the risks and benefits of self-driving cars</p><p>Discuss ethical dilemmas in driverless car engineering and operation</p><p>Choose an aspect of society that will be impacted by self-driving cars (such as parking, traffic, accidents, jobs, mobility) and argue for or against self-driving cars</p><p>Interview a parent, teacher, or other adult about self-driving cars and hypothesize about the acceptance of self-driving cars in society</p><p>Polling Question</p><p>What concerns you most about riding in a driverless car?</p><p>Potential software malfunction resulting in a crash&#160;The car may be hacked&#160;It will cause even more traffic&#160;Not sure if it would even work&#160;I’m not worried at all</p><p>Make a selection to see the results so far.</p><p>How did your prediction compare to your classmates?&#160;Let’s see how your answer changes as your learn more about driverless cars in society!</p><p>Vocabulary</p><p>Match the definitions with the key vocabulary words that will be reviewed in this module.</p><p>also known as autonomous cars, robotic cars, or self-driving cars, and are cars that utilize robotics in order to navigate and sense the environment around the vehicle without human input</p><p>Hive-mind</p><p>sharing of information and processes between individuals or systems</p><p>Self-driving car</p><p>situation in which there is conflict between individual and collective interest</p><p>Robo-jacking</p><p>high-jacking an autonomous machine</p><p>Social dilemma</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>also known as autonomous cars, robotic cars, or self-driving cars, and are cars that utilize robotics in order to navigate and sense the environment around the vehicle without human input</p><p>Answers for question: 1</p><p>Robo-jacking</p><p>Self-driving car</p><p>Hive-mind</p><p>Social dilemma</p><p>2.</p><p>sharing of information and processes between individuals or systems</p><p>Answers for question: 2</p><p>Hive-mind</p><p>Self-driving car</p><p>Social dilemma</p><p>Robo-jacking</p><p>3.</p><p>situation in which there is conflict between individual and collective interest</p><p>Answers for question: 3</p><p>Hive-mind</p><p>Social dilemma</p><p>Self-driving car</p><p>Robo-jacking</p><p>4.</p><p>high-jacking an autonomous machine</p><p>Answers for question: 4</p><p>Hive-mind</p><p>Self-driving car</p><p>Social dilemma</p><p>Robo-jacking</p><p>several limitations of human drivers, and major causes of accidents:&#160;Drowsy, Drunk, Distracted, Drugged</p><p>Drafting</p><p>also called platooning.&#160;When a group of trucks drive close to the truck in front of them to reduce wind resistance and save fuel</p><p>Second-order effect</p><p>a radical change in an industry, business strategy, etc., especially involving the introduction of a new product or service that creates a new market</p><p>Disruption</p><p>an outcome that is different than the first desired outcome, but are directly related to the initial decision</p><p>4D&#39;s</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>several limitations of human drivers, and major causes of accidents: Drowsy, Drunk, Distracted, Drugged</p><p>Answers for question: 1</p><p>Second-order effect</p><p>Drafting</p><p>Disruption</p><p>4D&#39;s</p><p>2.</p><p>also called platooning. When a group of trucks drive close to the truck in front of them to reduce wind resistance and save fuel</p><p>Answers for question: 2</p><p>Disruption</p><p>4D&#39;s</p><p>Drafting</p><p>Second-order effect</p><p>3.</p><p>a radical change in an industry, business strategy, etc., especially involving the introduction of a new product or service that creates a new market</p><p>Answers for question: 3</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7532a87d8b22d3c8cc7546254b655d60','transportation-technologies-m4-l2-lesson-1','c61917250f2b66bfd056efe68ac3f13d','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Pros of Driverless Cars</h3><p>Pros of Driverless Cars</p><p>While watching this video,&#160;think about a time you were stuck in traffic and what being stuck in traffic kept you from.</p><p>Welcome, this is video 1 for this module on Driverless Cars in Society.</p><p>So, are driverless cars just one step closer to a dystopian future, where robots control every aspect of our lives and governments monitor our every move? Or is it a tremendous invention, one that will free millions from the drudgery of driving and sitting in traffic and reduce accidents and deaths from human-caused errors? Obviously, time will tell. But it’s not likely to be as bad as the naysayers predict, or as amazing and immediately transforming as its proponents predict. But given its potential to bring massive changes to the everyday lives of, well, anyone who uses a car, it’s important that we analyze both the positive aspects… as well as the negatives.</p><p>Let’s start with the positives of driverless cars, compared to the traditional human-driven method. As we’ve alluded to before, traffic accidents are a big problem in the U.S. Traffic accidents cost over $160 billion dollars a year, and what’s worse, over 37,000 deaths occur each year from accidents. In fact, auto accidents are the leading cause of death for teens, with 6 teens dying every day because of them. And an additional 6,000 being treated every day in emergency rooms for auto-accident-related injuries. You might be thinking, “most of these are due to mechanical errors, or the weather, right”? Unfortunately, 90% of accidents are caused by HUMAN error!</p><p>And if you have been fortunate enough not to be hurt in an auto accident, there is a good chance you have been stuck in the resulting traffic from one. Traffic is another major issue for drivers.</p><p>6.9 billion collective hours are wasted thanks to traffic. Yes, BILLIONS of human hours we all spend staring at the break lights a head of us! Think of all the art that could be created in that time, the books that could be written, or at the very least all Netflix that could have been watched in that time.</p><p>And if hours don&#39;t impress you, traffic accidents are costing us over $160 billion dollars a year in the U.S. That&#39;s about $750 per person. I don&#39;t know about you, but I can think of a thing or two I&#39;d like to spend $750 dollars on.</p><p>For decades we&#39;ve just accepted this as part of the “deal” with automobiles: that it is inherently risky and there will always be human and mechanical errors that will result in accidents, traffic, and even death. In response, car makers have focused on adding entertainment and safety features such as seat belts, car seats, and airbags to make cars more enjoyable and safer. But what if there&#39;s a better way? The next sections of this module are going to look at how society may or may not improve if we take the human driver out of the driving equation.</p></section><section><h3>Drawbacks of current Human Driver Se</h3><p>Drawbacks of current Human Driver Setup</p><p>Introduction</p><p>We can start this module by&#160;discussing some of the drawbacks of our current &quot;human driver&quot; setup in society today.&#160;Press through the tabs below.</p><p>Traffic</p><p>In a long list of daily annoyances, sitting in traffic (especially when it&#39;s unexpected) is pretty near the top of the list as the most annoying.&#160;Americans spend nearly a hundred hours a year in traffic.&#160;That is a big number, and it represents a lot of wasted potential since productivity is limited while sitting in a car waiting to inch forward.</p><p>In terms of dollars and cents, traffic congestion costs us $160 billion.&#160;On an individual level, that&#39;s $960 per typical motorist.&#160;To make things even worse, those numbers are not projected to decrease.</p><p>And the bad news doesn&#39;t stop there.</p><p>Auto Fatalities</p><p>Have you heard about the high schools that are holding “mock car crashes?”&#160;The idea is to give students a chance to see the consequences of impaired and distracted driving by using student and teacher actors as well as law enforcement and emergency medical professionals to simulate the scene of a car crash. While you may or may not agree with this method, the fact that auto accidents are the second leading cause of death for teens certainly warrants extra attention.&#160; Every day eight teens, ages 16-19, die from auto accidents.</p><p>In the U.S., nearly 43,000 people die in auto accidents each year.&#160;The majority of those accidents do NOT happen because a car suddenly blew up without any warning. No, the majority of those happen because people drink alcohol and drive, try to drive while distracted, or while drowsy. In short, most of those accidents happen because people are getting behind the wheel while in conditions not fit for driving or are not paying attention.</p><p>Parking</p><p>What happens after we finally get through traffic and avoid collisions? We get out of our cars, and our cars sit idly in lots, garages, and driveways. Unfortunately, cars cannot disappear and reappear whenever we need them. This means there must be a spot for all the cars that are not on the roads. Think of how many venues,&#160;like arenas and stadiums,&#160;where the parking lots are even bigger than the actual building! If you look across the entire world,&#160;there are 1 billion cars, and they sit idle in parking lots 95% of the time, requiring massive amounts of space for parking spaces in homes, suburbs, and cities.</p><p>Next Tab</p><p>&quot;Yay!&#160;A traffic jam!&quot;</p><p>-No one ever</p><p>License:&#160;All Rights Reserved</p><p>Solutions</p><p>In the past, the solution to the problem has been to adapt the car to the driver.&#160;Drivers get stuck in traffic:&#160;give them better surround sound, comfier seats, climate control, and a dvd player for the kiddos in the back.&#160;Drivers make mistakes:&#160;give them seatbelts, air bags, and a sturdier car frame.</p><p>But maybe there is another solution.&#160;And maybe that solution is to take the human driver completely out of the picture.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('95613f90c32224b1714e63da4864bc2b','transportation-technologies-m4-l3-lesson-2','c61917250f2b66bfd056efe68ac3f13d','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Advantages of Fully Autonomous Car</h3><p>Advantages of Fully Autonomous Car</p><p>While watching, see if you can discover how driverless cars can improve auto traffic and safety.</p><p>Welcome back, this is video 2 for this module on Driverless Cars in Society.</p><p>Before we open the can of worms that is self-driving cars, let&#39;s be clear about what a self-driving car is. A self-driving car utilizes robotics in order to sense and navigate the environment around the vehicle with little or no human input. Other names, include “driverless car” and “autonomous car.” Self-driving cars range in their autonomous abilities from a car with no self-driving features, up to a car that can safely drive with no human driver at all. For this module, when we speak about driverless cars, we are referring to cars that are either highly or fully automated. Let&#39;s consider the advantages of a highly automated or fully autonomous car.</p><p>First, driverless cars have 360 degrees of visibility. They are aware of every single car in their radius. While we have features such as rear-view mirrors or backup cameras, it is nothing compared to being able to see perfectly in all directions.</p><p>Second: Driverless car sensors and cameras have virtually none of our distractions. They aren&#39;t trying to text, they aren&#39;t tired, they aren’t eating with both hands, they aren&#39;t listening to someone in the backseat, and they haven&#39;t had too much to drink. Driverless cars have one job- drive as safely as possible.</p><p>Finally: They are programmed to respond in the safest way. Remember our earlier example with Homer. The car sensed approaching golf carts and stopped. Whether or not a human driver would follow that same course of action depends on the driver. Perhaps a human driver might speed up to try and get ahead before the golf car crosses the street.</p><p>So, can robots do any better? Does that mean there will be zero accidents when all cars are operating at full autonomy? Clearly not as there have already been deaths reported from accidents, where the car was autonomously driven. What is the right balance here? Does a robot need to be as safe as an average human driver? Does it need to be 10 times safer? 100 times safer? Clearly there is no easy answer, as people are rightly concerned with robot-driven cars getting in fatal accidents. But, if there is the potential to drastically bring down the 37 thousand deaths that occur in the US (not to mention hundreds of thousands worldwide), then this could be a big positive of self-driving cars.</p><p>Another important factor to remember is that no operating system is perfectly reliable. Have you ever experienced an app freeze and crash on your phone? Or while trying to watch a video online, have you ever seen that spinning wheel or hourglass for what seems like an eternity while the network loads? In a self-driving car, an app freeze or crash or delays in the network could quite literally lead to a fatal crash.</p><p>Also, never underestimate the power of human stupidity! It&#39;s possible that some people could start weaving in and out of autonomous cars, just for sport or other dangerous behavior that we can&#39;t even imagine yet.</p><p>Again, keep in mind that we are talking about high or full automation here; NOT driver assistance. Driver assistance does little to reduce the effects of the deadly 4Ds: drunk, drowsy, drugged, or distracted drivers.</p><p>Have I convinced you that driverless technology is the way to go? Well, don&#39;t be too sure yet. We still need to look a little more closely at some of the potential risks of driverless tech.</p></section><section><h3>Driverless Car Safety</h3><p>Driverless Car Safety</p><p>Answer Key:Off</p><p>Distraction</p><p>Do you think you are/would be a safe driver?&#160;Do you think you can tune out distractions?&#160;How about your ability to multitask?&#160;Take this demo to measure your distractibility.&#160;(We&#39;ll wait!)</p><p>http://www.nytimes.com/interactive/2010/06/07/technology/20100607-distraction-filtering-demo.html(opens in a new tab)</p><p>(Note:&#160;if your computer or device does not support Flash and is not working, you can skip this exercise.)</p><p>What was your score with 2 distractions?&#160;What was your score with 6 distractions?&#160;Write your answers in the box below:</p><p>How did you do?&#160;What Stanford University researchers found was that high multitaskers do not handle multiple distractions well.</p><p>This has an interesting implication for the world of self-driving cars.&#160;Human error is the leading cause of auto accidents.(1)&#160;This includes recognition errors (approx.&#160;41%), decision errors (33%), performance errors (11%), non-performance errors (7%), and other human errors (8%).&#160;One of the factors associated with decision errors is distraction.</p><p>Problems with Driver Assistance</p><p>Researchers are finding that mere driver assistance lulls people into a false sense of security.&#160;They stop paying attention.&#160;They become distracted to the point that they are so engaged in the other activity they are doing, they lose contextual awareness.&#160;As a result, when forced to grab the wheel, they are less capable of taking over safely.</p><p>In fact after a “napping incident,” Google&#39;s Waymo project decided that it was best not to ask the drivers to interfere at all.&#160;In fact, the only two drive controls on their Chrysler Pacifica minivans are buttons for starting a ride and for telling the vehicle to pull over at the soonest opportunity.</p><p>Driverless Car Safety</p><p>Let’s quickly review the definition of a&#160;self-driving car&#160;(also called a driverless car or autonomous car):&#160;a car that utilizes robotics in order to navigate and sense the environment around the vehicle without human input.</p><p>This idea of giving as little control to “human drivers” is the growing consensus among driverless car developers.&#160;The statistics back up the idea.&#160;The EnoCenter for Transportation estimated in 2013 that if 90% of the cars in the US were autonomous, it would prevent 4.2 million accidents and save roughly 20,000 lives per year (the number of driving-related deaths would drop from over 32,000 per year to less than 12,000!</p><p>What could make driverless cars so much safer?&#160;For one, driverless cars have 360 degrees of visibility.&#160;That alone is something no human has.&#160;Second, dr<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f4736fd07f015be1ec5240152a5113ec','transportation-technologies-m4-l4-lesson-3','c61917250f2b66bfd056efe68ac3f13d','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Self-Driving Car Decision Making</h3><p>Self-Driving Car Decision Making in Dilema</p><p>While watching this video, see if you can&#160;identify the meaning of the term “social dilemma.&quot;</p><p>Welcome back, this is video 3 of this module on Driverless Cars in Society.</p><p>Imagine you&#39;re the driver of a runaway trolley and the brakes have gone out. You can steer only from one narrow track onto another. Five men are working on one track, and one man is working on the other. Anyone on the track you steer to is bound to be killed. Which track do you choose?</p><p>This scenario is known as The Trolley Problem and was first conceived by Philippa Foot in 1967. There are other variations of The Trolley Problem that continue to get more complicated, such as: what if the one person were a young child and the other 5 were older. Or what if the one person were a family member, while the other 5 were strangers? As you can tell, this can result in very morbid scenarios, none of which have a clear-cut answer, which is why they are called social or ethical dilemmas.</p><p>Perhaps not surprisingly, people are swapping out the trolley in the story for self-driving cars, and asking how a driverless car will decide who to put in harm’s way if there is a challenging scenario. It may seem unethical that a self-driving car&#39;s reaction in a scenario was defined by the car&#39;s software programmer before the incident even occurred.</p><p>However, there are two important counter points to consider:</p><p>One: A self-driving car will conduct a more rapid and rational risk/benefit analysis than a drunk driver, self-centered, or drowsy driver is able to make.</p><p>Two: Self-driving cars will have more information to use to make the decision. Self- driving cars will have 360 degrees of visibility. They may “see” options in a situation that a human driver could not see.</p><p>While people may argue about the social dilemmas of self-driving cars, the truth is that even human drivers perform risk/cost analysis while driving. The real issue is that we, as a society, may have to define a set of ethical codes. Do we trust one another to make the best rules? And how should these rules be made? By politicians, regulators, car manufacturers, software engineers, or citizen groups? How would these rules change and adapt over time?</p><p>As you can see, there are many questions that no one has the answer for today, but will need to be worked out before driverless cars will be adopted by a majority of people.</p></section><section><h3>Driverless Car Social Dilema</h3><p>Driverless Car Social Dilema</p><p>(opens in a new tab)</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Social Dilemma</p><p>How DO programmers program a car to respond safely in a given situation?&#160;Is it to avoid harm to the passenger?&#160;To avoid the least amount of property damage?&#160;Or is it to avoid harming the least number of people?</p><p>When asked if, as a pedestrian, they would want driverless cars that are programmed to avoid harming a single passenger or avoid harming a group of pedestrians?&#160;People generally responded that they want the car to avoid harming a group of pedestrians.&#160;However, when asked if they would ride in this type of car, people said no!</p><p>This is called a social dilemma.&#160;Who lives and who dies in complicated and unforeseen scenarios is a question that could keep some people from adopting driverless cars.&#160;Understandably, some may be hesitant to get in a car not knowing whether or not that car is programmed to sacrifice them in order to save others and in which situations.&#160;Driverless carmakers, however, insist that such scenarios are increasingly rare because they are focused on developing the safest car possible, not the most ethical car.</p><p>The truth, however, is the self-driving car&#39;s software must quantify the value of human and animal life.&#160;And that makes people uncomfortable.</p><p>Let&#39;s examine some social dilemmas related to driverless vehicles as well as potential solutions for these dilemmas.&#160;Expand each section below.</p><p>Ethical Decision Making</p><p>Driverless vehicles may face situations where they have to make split-second ethical decisions, such as choosing between protecting the occupants or pedestrians in a potential collision. This raises moral dilemmas and societal concerns about the programming of these decisions.</p><p>Potential Solutions: Developing comprehensive ethical guidelines and standards for autonomous vehicles can help address these dilemmas. Public input, industry collaboration, and regulatory oversight are essential in establishing a consensus on ethical decision-making algorithms that prioritize safety and minimize harm.</p><p>Job Displacement</p><p>The widespread adoption of driverless vehicles may lead to job displacement for professional drivers, such as truckers, taxi drivers, and delivery personnel. This could have significant economic and social implications, particularly for those reliant on these occupations.</p><p>Potential Solutions: Governments and industries should proactively plan for the transition, offering retraining programs and new employment opportunities in areas like maintenance, supervision, and fleet management. Collaboration between stakeholders can facilitate a smoother transition and mitigate the impact on affected workers.</p><p>Privacy and Data Security</p><p>Driverless vehicles collect vast amounts of data, including location information, driving patterns, and personal preferences. Ensuring the privacy and security of this data is crucial to protect individuals from potential misuse or unauthorized access.</p><p>Potential Solutions: Implementing robust data encryption, anonymization techniques, and stringent data protection regulations can safeguard personal information. Companies must be transparent about data collection and usage, obtaining informed consent from users while providing options to opt out.</p><p>Hacking and Cybersecurity</p><p>The increased connectivity and reliance on technology in driverless vehicles create vulnerabilities to cyber threats. Malicious actors could exploit these vulnerabilities, potentially leading to safety risks and privacy breaches.</p><p>Potential Solutions: Investing in robust cybersecurity measures, including regular software updates, intrusion detection systems, and encryption protocols, can help mitigate hacking ris<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5d24dcb29ee86ca267010d2e47e5b509','transportation-technologies-m4-l5-lesson-4','c61917250f2b66bfd056efe68ac3f13d','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Security &amp; Privacy of Driverless Cars</h3><p>Security &amp; Privacy Risk of Driverless Cars</p><p>While watching this video, pay attention to potential security and privacy risks of driverless cars.</p><p>Welcome back, this is video 4 of this module on Driverless Cars in Society.</p><p>Imagine one day you become the President of the United States. You are riding in your autonomous car when suddenly the car swerves and starts heading toward a cliff- your driverless car has been “hacked.” Someone overrode the system and changed your destination!</p><p>And what if a hacker intercepts an entire network of cars and programs them to come to an immediate halt or crash into each other, for example? Not only are single cars at risk of being hacked, but all interconnected cars could be tampered with if hackers break into a network.</p><p>Driverless cars developers are going to have to stop car hackers before they even exist.</p><p>A company called CyMotive Technologies established a joint venture with Volkswagon, a car maker. One venture is working to protect autonomous cars, the other is working to simulate hacker attacks. That is one way a company is working toward increasing cyber security.</p><p>But until car companies develop safe, reliable networks and software, and always stay one step ahead of threatening hackers, there is a big cybersecurity risk.</p><p>Another big issue- privacy. Since driverless cars will always be connected to the internet in order to alert vehicles of software updates, road conditions, and traffic updates, it will make them trackable. Furthermore, just like Google Maps and Uber have information stored about where you&#39;ve gone and can predict where you are going, driverless cars will likely collect similar data.</p><p>Who is collecting, accessing, and using that data is the big question on the minds of many. It might not seem like such a big deal if all the car companies do with the data is try to make your future driving experiences easier, but what if they sell your information to a third party?</p><p>Congress is already concerned about the privacy issue. Two senators created The Security and Privacy in Your Car Act that would direct National Highway Traffic Administration and Federal Trade Commission to establish federal standards to secure cars and protect drivers&#39; privacy. That seems like a step in the right direction, but clearly much more is needed in this area before the majority of people will be comfortable with the security and privacy risks presented by driverless cars.</p><p>Finally, the price of these autonomous cars today can be around $100,000! Remember all those sensors we talked about at the beginning of the module? Those don’t come cheap. It’s possible that driverless cars become just another luxury item for the rich, driving inequality even further.</p><p>Now these three downsides: security, privacy, and cost are only three of many potential risks with driverless cars. What others can you think of? We’ll continue to explore other issues throughout the rest of this module.</p></section><section><h3>Components of Driverless Car Security</h3><p>Components of Driverless Car Security</p><p>License:&#160;All Rights Reserved</p><p>Let&#39;s look at some key components of driverless vehicle security.&#160;Expand each section below.</p><p>Robojacking</p><p>What if you were sitting in your self-driving car when all of the sudden a small gang stood in front of your car and refused to move? Your car would be frozen since it would be programmed to not run into people. If there was no manual overdrive option on the car, you would have no way of speeding off to safety.</p><p>Robojacking is the hijacking of an autonomous machine, in this case, a driverless car. And it is just one way hackers and criminals could take advantage of self-driving cars.</p><p>Other ways hackers will be able to “attack” self-driving car is by breaching and compromising data from car sensors, digital maps, and operating systems. With the self-driving car needing to update its information, like maps, there must be a way to verify that the information is secure, authentic, and certified.</p><p>Privacy</p><p>Related to the risk of cyber-attacks is the issue of privacy. If the data of everything the car “sees” is being stored, then that data can be retrieved by police, for example. If a crime is reported in a particular area and the police are looking for a suspect, the police could find which cars were in the area around the time of the incident and investigate whether or not the cars “saw” something in particular.While that may be a potential benefit- solving crimes- that also raises the question of privacy. How would you feel knowing that, given there are enough driverless cars on the road, you (and everyone else) is nearly always being recorded and every move tracked? Who would have access to the data and how would it be used?</p><p>The issue of privacy is definitely something to consider, but it assumes that the data on self-driving cars will be recorded and saved. That is a hurdle in and of itself. All those cars having all that information recorded and stored would require a HUGE amount of physical storage to keep all that information. Plus it would require a system for archiving and retrieval. Perhaps information will only be kept for a certain amount of time and is then deleted to make room for new information.</p><p>Cameras on the car could take pictures of its passengers or pedestrians. Those pictures could be sent to the government for face recognition. Or those pictures could be sent to marketing departments. Marketers would get a clear idea of what people are using and wearing and at what ages.</p><p>An important point to consider, however, is that most Americans are already walking around with a device capable of tracking their every move. Cellphones do just that. For most people, the convenience, security, and connection of having a cellphoneoutweighs the fact that to complete an incoming call, cellphone companies must know the carrier&#39;s location.</p><p>Legislation</p><p>Passengers of self-driving cars would need some sort of privacy protection. At the very least, everyone should know what data is being collected and who will have access to that data. At least that&#39;s what Senators Markey and Blumenthal believe. They have introduced The Security and Privacy in Your Car Act (SPY act). This piece of legislation would direct National Highwa<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b67f4820a05649b559a42aeb4824e2c3','transportation-technologies-m4-l6-lesson-5','c61917250f2b66bfd056efe68ac3f13d','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Driverless Cars Mobility Benefits</h3><p>Driverless Cars Mobility Benefits</p><p>While watching this video, pay attention to how greater mobility will help society in some ways and cause problems in other ways.</p><p>Welcome back, this is video 5 of this module on Driverless Cars in Society.</p><p>Now let&#39;s talk about mobility. Remember the elderly Ms. Jackson from the story at the beginning of the module? She is just one of the many, many people who would benefit from the mobility driverless cars would provide. Imagine being blind and no longer having to maneuver as many streets and sidewalks on foot or having to rely on friends and family for a ride.</p><p>Society would benefit as well as the disabled, blind, and elderly gained more mobility. They might be able to acquire jobs that were previously unavailable to them because they could not physically get to the place of employment. These individuals could fulfill positions in the economy that needs to be filled.</p><p>It wouldn&#39;t just be the elderly, blind, and disabled that could get out and about more. Inexpensive transportation could mean that collectively we are out and about more often than ever. This would particularly benefit areas where public transportation is not well established. It would also take out the problem of having to drive AND navigate to a new place. The car would simply do both of those things for you easily.</p><p>Can you think of any particular drawbacks or second order effects of more mobility?</p><p>How about the potential for more traffic? If we have a bunch of individuals each of whom normally take the bus to work instead decide to take a driverless car because it&#39;s quicker and cheaper, than the roads will have that many more cars to accommodate. So many of the streets in the United States are already too crowded, that adding not just a few, but potentially MANY more cars, could be disastrous to traffic. The government or transportation companies will need to provide incentives to encourage ride-sharing and public transportation in order to combat potential traffic issues.</p><p>Self-driving cars have the potential to bring the cost of ride-sharing and other transportation services way down. That&#39;s because drivers are one of the most expensive parts to any service involved in transporting people or things.</p><p>But did you know that the most common job in the U.S. is truck drivers? Almost 3% of all working Americans are drivers of sorts, whether that’s truck drivers, taxi drivers, or bus drivers. That’s over 4.4 million people! So what is going to happen to those jobs, the people behind them, and their families if robot-controlled, driverless cars suddenly become the norm?</p><p>After all, a trucking company does not have to pay a self-driving car a salary, healthcare, and other benefits. The impact of driverless technology on trucking is an example of disruption, which is a radical change in an industry. A disruption typically involves the introduction of a new product or service (in this case, driverless transportation) that creates a new market. There are new jobs created (driverless car engineers), while others are lost (such as truck drivers).</p><p>There are a few important things to keep in mind before worrying too much about lost trucking jobs. First, even though the technology is available, it could take many, many years before vehicle automation takes those jobs. And even if driverless cars do hit the road in mass numbers, it’s likely that they will be required to have a human operator for the foreseeable future, just in case anything goes wrong. We should also remember that with America’s dynamic economy, jobs are getting changed and lost all the time, with new ones taking their places. One way to help those who face job-loss would be for job training to provide new skills, so the drivers can transition into new jobs at similar wages.</p><p>What about human health? If driverless cars take the place of activities like bike riding and walking to and from places, than the safety gained from fewer accidents might just be replaced by the problem of declining health.</p><p>Are cities ready for self-driving cars? Statistics say no, they are not. Only 6% of the US largest cities’ have transportation plans with a consideration of driverless cars. That seems like a lot of catching up to do for a technology that already exists, with a lot of benefits and question marks.</p><p>I hope this module has gotten you thinking about the risks and potential benefits of driverless cars. This will no doubt be a hot and important issue in the coming years. I’d encourage you to keep an eye out for more news and articles on this topic. And most importantly, add your well-informed voice to the conversation that is taking place regarding driverless cars in society.</p></section><section><h3>Second Order Effect</h3><p>Second Order Effect</p><p>Second Order Effects</p><p>Today’s high school students are going to be tomorrow’s engineers, coders, designers, and business and government leaders.&#160;So it is important that you start thinking about the implications and effects of driverless cars.&#160;There are going to be pros and cons, positives and negatives, risks and opportunities.&#160;And they aren’t going to line up perfectly… ok we have 10 positives and 9 negatives so we should do it!&#160;The world isn’t that clear cut, so a thoughtful approach needs to be taken.</p><p>Additionally, it’s important to think through second order effects; that is outcomes that are a result of the first decision, but not necessarily intended.&#160;For example, with driverless cars, we have explained that it could reduce highway deaths significantly, which is a good thing.&#160;But did you know that a lot of organ transplants come from people that die in car crashes?&#160;So people waiting in a hospital for a new heart, liver, or kidney, are going to have to wait even longer if self-driving cars are used by a large percentage of the population.&#160;That’s one example of a second order effect, and it’s important to think about other changes that will ripple through the economy and society with driverless cars.</p><p>Press through the tabs below to read about some second order effects.</p><p>Mobility</p><p>The elderly, the blind, and the disabled are three key groups that would likely experience an increase in quality of life if they were able to use driverless cars.&#160;They would have more mobility, <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f9f4a23239d94f0a8230ca4a775bddef','transportation-technologies-m4-l7-module-4-summary','c61917250f2b66bfd056efe68ac3f13d','Module 4 Summary','text',12,'<h2>Module 4 Summary</h2><section><h3>Module 4 Summary</h3><p>Module 4 Summary</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Self Driving Cars in Society!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Examined the risks and costs of human operated cars</p><p>Evaluated the risks and benefits of self-driving cars</p><p>Discussed ethical dilemmas in driverless car engineering and operation</p><p>Chose an aspect of society that will be impacted by self-driving cars (such as parking, traffic, accidents, jobs, mobility) and argue for or against self-driving cars</p><p>Interviewed a parent, teacher, or other adult about self-driving cars and hypothesize about the acceptance of self-driving cars in society</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8369c81a2eccb98be3c982fbc181c396','transportation-technologies-m4-l8-module-4-assignment','c61917250f2b66bfd056efe68ac3f13d','Module 4 Assignment','text',12,'<h2>Module 4 Assignment</h2><section><h3>Module 4 Assignment</h3><p>Module 4 Assignment</p><p>Transportation</p><p>Self-driving Cars in Society - Short Answer Assignment</p><p>Short answer assignment</p><p>For this assignment, interview a parent, teacher, or other adult about self-driving cars and discuss the acceptance of self-driving cars in society.</p><p>Here are some potential questions you could ask them:</p><p>Question 1: On a scale from 1-10 how attentive of a driver would you say you are?</p><p>Question 2: Which do you trust more, yourself or a driverless car in control of the car? Why?</p><p>Question 3: Which do you trust more, a driveless car or a 16 year old who just got his license? Why?</p><p>Question 4: What risks do you think are involved in using driverless cars?</p><p>Question 5: What benefits do you think there are to using driverless cars?</p><p>After you have interviewed them, write a&#160;two-page, double spaced&#160;paper that answers the following questions:</p><p>Is there are difference between how older and younger people view driverless cars? Why do you think that is?</p><p>If a person learns more about the benefits of driverless cars, would they be more likely to use one? Why or why not?</p><p>Did the person you interview bring up new risks or other ideas around driverless cars that you hadn’t considered?</p><p>What in your mind is the biggest risk of using a driverless car? What is the biggest benefit and why?</p><p>Review the rubric below to see how you will be graded.</p><p>Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f7a3f01753c74270159ed2fcf537bfc1','transportation-technologies-m4-l9-module-4-project','c61917250f2b66bfd056efe68ac3f13d','Module 4 Project','text',12,'<h2>Module 4 Project</h2><section><h3>Module 4 Project</h3><p>Module 4 Project</p><p>Transportation</p><p>Self-driving Cars in Society - Project</p><p>Project</p><p>Part 1: For this assignment, imagine you’ve been asked to write an editorial article for a national newspaper’s website. The topic is the safety of self-driving cars. You get to choose your stance (positive or negative) and the safety issue you’d like to discuss: robojacking, privacy, city street design issues, programming ethics, etc. The article should be three to five paragraphs long.</p><p>Part 2: After you’ve written the article, you get the chance to look at the topic from another point of view by writing two responses that offer different or opposing ideas. The comments should be respectful, give some support for their argument, and each be one to two paragraphs in length.</p><p>Review the rubric below to see how you will be graded.</p><p>Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Article</p><p>8 points The editorial demonstrates a strong understanding of one safety concern associated with self-driving cars. It is persuasive, contains several specific and accurate details and thoroughly expands on the thoughts discussed.</p><p>7-6 points The editorial demonstrates a strong understanding of one safety concern associated with self-driving cars. It is persuasive, contains several specific and accurate details and somewhat expands on the thoughts discussed.</p><p>5-0 points The editorial demonstrates little to no understanding of one safety concern associated with self-driving cars. It is not persuasive or contains few to no specific and accurate details and does not expand on the thoughts discussed.</p><p>8</p><p>Review Comments</p><p>8 points Two review comments offer valid and well developed opposing arguments to the content of the article. Each comment gives specific details to support the statements made.</p><p>7-6 points Two review comments offer valid and somewhat developed opposing arguments to the content of the article. Each comment gives some details to support the statements made.</p><p>5-0 points Review comments offer invalid or undeveloped opposing arguments to the content of the article. Each comment gives little to no detail to support the statements made.</p><p>8</p><p>Formatting</p><p>2 points Includes the required content and is formatted neatly.</p><p>1 point Does not include all required content or is not formatted neatly.</p><p>0 points Does not include all required content and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1b1e1fad850200c4194f835bb0fb81eb','transportation-technologies-m4-l10-module-4-quiz','c61917250f2b66bfd056efe68ac3f13d','Module 4 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Self-Driving Cars in Society. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('277407abb8a5914c60a44759dfac013a','transportation-technologies-module-5','504e3ab88df8552a07116f12aea44099','Module 5: Drones',5) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c75f14627839b21918bd02dbcbb43a86','transportation-technologies-m5-l1-introduction-purpose-and-objectives','277407abb8a5914c60a44759dfac013a','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>-00:31</p><p>Mute</p><p>You open your door and discover a package containing that thing you ordered the other day- sweet! It got here even earlier than you anticipated. You step outside and grab the package just in time to see some sort of small helicopter thing hover for a second and return to the sky. How did the package get there? Well, yes the drone delivered it, but how did the package get there? How did it go from sitting in a warehouse somewhere, on to an aircraft with no pilot on board, to your doorstep? In short, how do drones work? Let’s get started to find out how!</p><p>Module Description</p><p>White drone, quadrocopter, with photo camera&#160;by Ksander</p><p>License:&#160;All Rights Reserved</p><p>They take photos, spray pesticides, rescue swimmers, and deliver packages.&#160;They survey damage, explore new land, and occasionally, they hit someone in the face.&#160;Yikes!&#160;They are aerial drones.&#160;And even though they don’t move people from place to place, drones are still an emerging transportation technology that will grow in importance in the years to come.</p><p>This module will explain what drones are and how they are different from other aircraft.&#160;It will provide an introduction to how drones fly, are controlled, and operate autonomously.&#160;The module will examine the impact drones have on jobs today and future jobs involving drones.&#160;We will examine some of the current uses for drones and their safety.&#160;By the end of the module, you will be able to formulate an opinion about drone use, and explain whether or not you think they do more harm or good for the world.</p><p>Objectives</p><p>In this module, students will</p><p>Define drones and distinguish drones from other types of aerial technology and transportation</p><p>Describe technologies that allow drones to fly, be controlled remotely, and operate autonomously</p><p>Determine the impact of drone delivery on jobs and the environment</p><p>Identify how drones are used to deliver food, healthcare supplies, and packages</p><p>Assess the safety of drone delivery</p><p>Predict when they will receive their first package delivered by drone</p><p>Identify career&#160;opportunities in drones and educational paths to enter those careers</p><p>Polling Question</p><p>When do you think you (or someone in your family) will receive their first package delivered by drone?</p><p>Before 2020&#160;2020-2024&#160;2024-2028&#160;After 2028&#160;Never</p><p>Results:</p><p>Before 2020&#160;100%</p><p>How did your prediction compare to your classmates?&#160;Let’s see how your&#160;prediction changes as you learn more about the&#160;opportunity&#160;and risks of drones!</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>an autonomously and remotely controlled vehicle</p><p>Drone</p><p>flying vehicle without a human pilot on board, often synonymous with drones</p><p>Rotors</p><p>an assembly of rotating blades that enable lift and stability for a rotorcraft</p><p>Global Positioning System (GPS)</p><p>propulsive force</p><p>Unmanned aerial vehicles</p><p>a system of computers, satellites, and receivers that is able to determine the latitude and longitude of a receiver</p><p>Thrust</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>an autonomously and remotely controlled vehicle</p><p>Answers for question: 1</p><p>Drone</p><p>Unmanned aerial vehicles</p><p>Thrust</p><p>Global Positioning System (GPS)</p><p>Rotors</p><p>2.</p><p>flying vehicle without a human pilot on board, often synonymous with drones</p><p>Answers for question: 2</p><p>Drone</p><p>Thrust</p><p>Unmanned aerial vehicles</p><p>Global Positioning System (GPS)</p><p>Rotors</p><p>3.</p><p>an assembly of rotating blades that enable lift and stability for a rotorcraft</p><p>Answers for question: 3</p><p>Drone</p><p>Unmanned aerial vehicles</p><p>Global Positioning System (GPS)</p><p>Rotors</p><p>Thrust</p><p>4.</p><p>propulsive force</p><p>Answers for question: 4</p><p>Global Positioning System (GPS)</p><p>Rotors</p><p>Drone</p><p>Thrust</p><p>Unmanned aerial vehicles</p><p>5.</p><p>a system of computers, satellites, and receivers that is able to determine the latitude and longitude of a receiver</p><p>Answers for question: 5</p><p>Drone</p><p>Rotors</p><p>Unmanned aerial vehicles</p><p>Thrust</p><p>Global Positioning System (GPS)</p><p>device used to control a machine via signals transmitted from a radio or electronic device</p><p>Remote Control</p><p>instrument used to measure acceleration in a vehicle</p><p>Altimeter</p><p>instrument used to determine a vehicle&#39;s altitude</p><p>Accelerometer</p><p>well defined procedure used to solve a problem</p><p>Algorithm</p><p>a subset of machine learning that has networks which can learn unsupervised from unlabeled data such as digital photos</p><p>Deep Learning</p><p>Alternative Activity</p><p>Match description with a choice.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('07d26dfaaa1315e45dcd3ce970a8f2d8','transportation-technologies-m5-l2-lesson-1','277407abb8a5914c60a44759dfac013a','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>What is a Drone &amp; their use Case</h3><p>What is a Drone &amp; their use Case</p><p>While watching this video, pay attention to the difference between drones and other flying vehicles.</p><p>Welcome to the Drone module – video 1.</p><p>A drone is any autonomously or remotely guided vehicle. It doesn&#39;t matter if the vehicle is operating on land, in water, or the air, the key component is that there is no pilot inside the vehicle. Yes, someone is still responsible for the operation of the drone, but that person may be far away from the physical location of the drone. This remote operation is what distinguishes drones from a plane or helicopter, both of which are designed for a pilot to navigate&#160;within&#160;the vehicle.</p><p>One of the amazing things about drones, is that drones have some degree of intelligence. In other words, the pilot does not have to be fully engaged in every aspect of the flight. The drone can self-stabilize and hold a position.</p><p>Drones are NOT designed to carry passengers. This is what distinguishes drones from flying cars. Drones can, however, carry packages, supplies, cameras, or other sensors.</p><p>You may hear the term, UAV or UAS in reference to drones. UAV stands for unmanned aerial vehicle and UAS stands for unmanned aerial systems. We will use all three terms- UAV, UAS, and drone- interchangeably in this module.</p><p>So where might you see a drone? Well, they are certainly becoming more popular everywhere but here are a few places you might notice drones in your own life now or in the near future:</p><p>At live events like concerts. Since they are free moving, they can capture footage from any direction and hover above the crowd.</p><p>Delivering small packages. You might have heard about Amazon&#39;s use of drones to deliver packages, but other industries may follow soon as well. For example, pizza delivery would be much faster since drones could fly right past traffic.</p><p>Home maintenance. There are certain places in homes that are just hard to get to! They require a ladder of questionable stability or crawling through tight, dark, uncomfortable spots. Sending a drone to check out these places makes life for homeowners much more pleasant.</p><p>There are other uses too. We will get into some of these other uses in future sections.</p></section><section><h3>Terms and Drone use Cases</h3><p>Terms and Drone use Cases</p><p>What is a Drone?</p><p>Before we get into the uses of drones, let&#39;s ensure there is a clear understanding of what a drone is.&#160;Drones are unmanned aerial vehicles (UAVs) that are either remotely controlled or fly autonomously using onboard computers.&#160;&#160;The important concept to understand is that these robotic machines do not have a human on board.&#160;But just because there is no human on board does not mean that humans are completely uninvolved.&#160;Drone pilots still need to actively control the drone either by pre-programming the drone correctly before flight or by controlling the drone via remote while it is in flight.</p><p>Watch the video below to learn a little more about drones.</p><p>So, what is a drone? Well, that&#39;s what this whole project lab is about drone technology, right? Well, what if you don&#39;t know what a drone is? So we&#39;re gonna take a couple minutes to talk about what drones are, at least how we explain them in the lab. So that you&#39;ll have a better understanding of what to expect. So most of you probably know what a drone is. A drone is something that we call another name for a drone actually, it&#39;s called a UAV, unmanned aerial vehicle, that means that it&#39;s a vehicle that can fly but doesn&#39;t have an actual pilot on board, right? So here we have some examples of some drones and probably jobs. So these are actually drones that are made to be flown indoors, but you can get drones that are much, much bigger than this. Here&#39;s one of the drones that we use for our drone racing lab, and as you can see, this one actually has a camera on it. So we use this along with some goggles to actually be able to see from the vantage point of the drone, so it&#39;s like you&#39;re riding on the drone. Okay, and that&#39;s pretty cool, so we use that in our racing lab. Here&#39;s a little bit bigger version of this. Here you have a camera on it with an antenna broadcast video, and so you can kind of see these are our racing drones, okay? Again a drone important part to remember is that a drone is an unmanned aerial vehicle. The drones that will we&#39;ll use actually have four motors and blades, so they&#39;re called quadcopters quad meaning four, but you can get hexacopters which have six propellers the motors in octave copters, but the quadcopter is very stable to fly there&#39;s actually a great drum for beginners, and that&#39;s one of the reasons we use it. So if you didn&#39;t know what a drone was, hopefully, you do now and have a better idea of kind of what to expect as you go through this project lab. But comes with the prop guard here pretty much like a game, so this helps so as you&#39;re bumping the walls and other obstacles, you don&#39;t run into your propellers here and cause a drone to crash, so it&#39;s very forgiving, very durable. He uses a 3.7 lipo battery which we should have a link for you to get replacing batteries for that and extra batteries as well, so this is a very, very good drone. The other added bonus for this drone is the remote here, which doubles as a remote for the drone simulator, so if you&#39;re able to download the simulator from drl.com, you can actually fly on a computer. So you&#39;ll get a more realistic sense of actually flying through courses and in races, and you can use this remote as a controller on your computer as well or your Mac, so that&#39;s what I like about just this whole combo.[Music]Just pulling them back.[Music]Then we should get a little bit better at that. You can also do left, and right, so the drone is just like the car, so there&#39;s a port in the back, front in the back, and a left on the right side, and so we always tell the kids to practice standing behind the drone so that way you know the only annotation then you push for the right and left and back. The drone moves forward-backward, left to right, just said you were thinking okay, and then once you&#39;re able to kind of get a little bit better at that just the basic moves, then you can start to do this more complicated by going<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('52c55c567350462b2712426adee77a22','transportation-technologies-m5-l3-lesson-2','277407abb8a5914c60a44759dfac013a','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Key Components of the Drone</h3><p>Key Components of the Drone</p><p>While watching this video, pay attention to the key components of drones.</p><p>Welcome back, this is video 2 of the Drone module.</p><p>Let’s start by giving a basic idea of how an aircraft with rotors works. As a rotor spins, it pushes air down. As this happens, the air pushes up on the rotor, which gives it lift. The faster the rotor spins, the greater the lift.</p><p>In fact any movement- whether it&#39;s lift, flight, turning, or landing- is controlled by decreasing/increasing the rotors. To do that, there must be a controller that can increase or decrease the power to each individual rotor.</p><p>That seems pretty straightforward. But picture a modern drone, which typically has four rotors (called a quadcopter). Imagine trying to manually control each of these 4 rotors&#160;at the same time&#160;to get it to going at the exact speed you need for a particular movement. That would be intense.</p><p>However, with a computer controlled system, all the pilot needs to do is use something like a joystick to tell the drone what to do, and let the computer handle the details. Add in an accelerometer and gyroscope and the drone is now experiencing smooth flying, as the accelerometer and gyroscope make tiny adjustments in the rotor power. To get where it needs to go, some drones are equipped with&#160;global positioning system&#160;(GPS). This is obviously a major oversimplification, but it is a great starting point in understanding how a drone works.</p><p>The next piece of the puzzle is understanding how they can be controlled with no pilot on board. The key to that sentence is&#160;on board. There is still a pilot involved in the drone&#39;s flight. That pilot just might happen to be thousands of miles away! At least that&#39;s the case with military drones.</p><p>The US military sends drones when manned flight is considered too risky or difficult. The takeoff and landing are handled locally. Then the sensors on the drone provides information to the ground team via satellite. The ground team then makes decisions on what the drone should do based on the information received.</p><p>To launch, land, and navigate, the drone pilot uses a&#160;control. What that control looks like varies depending on the type of drone. Whatever its form, it typically uses radio waves to communicate with the drone. Wi-fi can be transmitted on the right radio wave spectrum which smart phones and tablets can tap into easily.</p><p>GPS relays the position of the drone back to the pilot. Another cool feature is that the GPS logs the drone&#39;s launch spot so the drone can return unassisted. One of the challenges unique to aerial drones is that there is a full 360 degrees in any direction in which the drone can move. The drone must be able to avoid obstacles associated with this range. Another problem is that some of the situations where drones would be very helpful are places without GPS capability. That is one of the reasons engineers are working on making drones smarter and more autonomous.</p><p>To give you an idea of just how advanced drone technology is becoming, NASA has successfully tested a prototype drone that can detect an object in its flight path. The Ikhana drones, as they are called, were programmed to handle 200 various aviation scenarios. They made 11 flights. The Ikhana drones successfully avoided objects in the flightpath and also sent data back to researchers on the ground. Ensuring drones do not run into each other or other objects has been one of the main issues for the Federal Aviation Administration (FAA). The FAA is key to making commercial drone services a reality. So this ability NASA has given their drone is a big milestone.</p></section><section><h3>Drone Components and Technology</h3><p>Drone Components and Technology</p><p>This section will review some of the key components and technology in drones.&#160;Press through the tabs below.</p><p>Rotors</p><p>How does a drone go from sitting on the ground to hovering hundreds of feet in the air?</p><p>Let&#39;s take a look at some physics:</p><p>Most drones use rotors to control their flight.&#160;A rotor works a lot like a fan.&#160;As the blades rotate, they push the air down.&#160;In response, the air pushes up on the rotors.&#160;To fly, the force of air must be greater than the pull of gravity.&#160;(Note:&#160;for this section, we are focusing on &#39;quadcopter&#39; drones, or drones with 4 rotors that provide lift.&#160;These are the most common drones, and different than larger military drones, which fly more like airplanes).</p><p>Thrust</p><p>To climb higher, whoever is controlling the drone increases the thrust, or speed of the rotors so that the upward force is greater than the weight of the drone. To come down, the thrust must decrease so the net force is downward. To hover, the thrust must be equal to the gravitational force pulling down on the drone.</p><p>Manually controlling each individual rotor would be extremely difficult. Luckily computers take away some of that difficulty. Drones today are equipped with some fantastic technology features.</p><p>Accelerometer and Altimeter</p><p>A drone knows it needs to correct something because it has been programmed with algorithms. Algorithms are a set of rules or procedures to follow when solving a particular problem or calculation. So if the wind begins to blow while a drone is in flight, a certain algorithm leads the drone to making the necessary corrections to maintain flight.</p><p>Until recently, a global positioning system or (GPS) was crucial to drone flight. GPS is a system of computers, satellites, and receivers that are able to determine the latitude and longitude of a receiver. In the case of unmanned aviation, they relay the position of the aerial vehicle.</p><p>The problem with using GPS is that it is not available in all areas of the world. To work around this problem, deep learning is being utilized in drone technology. Deep learning enables a computer to learn by observing. The computer learns to recognize an object through seeing thousands or millions of photos of the object from every angle and in different lighting or situations. Algorithms are programmed into the computer to instruct the drone on how to proceed once it identifies an object.</p><p>Object Detection</p><p>Now, back to how this applies to aerial drones. Places where drones would be helpful are often places that<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f36ca01782b756f4c27a7f47e58e514f','transportation-technologies-m5-l4-lesson-3','277407abb8a5914c60a44759dfac013a','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Drone use cases</h3><p>Drone use cases</p><p>While watching this video, pay attention to ways companies may use drones.</p><p>Welcome back, this is video 3 of the Drone module.</p><p>We discussed it a bit in the first section, but let&#39;s look a little more at how people can use drones.</p><p>Perhaps one of the better known drone applications is by Amazon&#39;s program, Prime Air. In December 2016, the company made its first ever drone delivery. The delivery took 13 minutes from click to drop off to a customer in Cambridge, England. While progress for the program is slow, thanks largely to regulation obstacles, it would mean that the company would no longer be solely dependent on delivery trucks.</p><p>The same goes for companies that deliver food as well. Without having to sit in traffic, a pizza could get to you in no time! ...Provided someone doesn&#39;t shoot the drone down and eat it first (we&#39;ll get into that in the next section!).</p><p>Drones are known for taking incredible photos. Using a drone for aerial photography is not only more cost effective, it&#39;s also safer. Real estate agents are particularly loving the spectacular footage of their client&#39;s homes that drones are able to capture.</p><p>Let&#39;s not overlook the value of drones in emergency relief. Their small size makes them perfect for fitting in tight spaces, unlike bulky helicopters. Drones can be flown into areas that are still unstable without endangering the life of a pilot or crew. They can help in search and rescue efforts by locating people who are injured and/or stranded. Some of the most vital resources- food and water- can be delivered via drones as well.</p><p>Keller Rinauldo&#39;sstartup company, Zipline, is the first drone delivery system to operate at a national scale. The drones transport blood and plasma to remote clinics in East Africa. The company has a distribution center and when a doctor or nurse sends a WhatsApp letting Zipline know what they need,Zipline can pull the blood from their stock.</p><p>Then they load the drone, known as Zip, and the drone accelerates from 0 to 100 kilometers per hour. One minute before the drone arrives, the hospital receives a notification to go receive the delivery. In addition to routine deliveries, the company has made over 400 emergencies deliveries. Perhaps it is this- the life saving potential drones have- that is the most impressive aspect of drone usage.</p></section><section><h3>Current Drone Use Cases</h3><p>Current Drone Use Cases</p><p>See full size image(opens in a new tab)</p><p>License:&#160;All Rights Reserved</p><p>Drone Uses</p><p>Drones are still in their infancy.&#160;Society is only beginning to realize some of the applications drone use could have in the world.&#160;Expand the sections below to examine some jobs that a drone could do or, in some cases, are already doing:</p><p>Pesticide application</p><p>When a human applies pesticides, he or she has to be extremely careful since it involves applying chemicals to reduce bugs in crops. It usually involves layers of protective clothing while working in the hot sun. Even when an airplane is used to apply pesticides (called “crop dusting”), it&#39;s still a dangerous job for a human. Crop dusting has the highest accident rate in general aviation. Drones not only do the job more efficiently and accurately thanks to their technology, but safer as well.</p><p>Aerial photography</p><p>Whether flying over a celebrity&#39;s house, an active volcano, or beautiful landscapes, drones are being used for all kinds of aerial photography projects. They are much cheaper and easier for photographers to use than having to rent a plane or helicopter.</p><p>Lifeguard</p><p>On average, it takes a human lifeguard about 90 seconds to reach a person in trouble. It takes a drone about 30 seconds. Although not able to jump in and save a person, the drone is able to deploy a flotation device for the victim.</p><p>And saving drowning victims is not the only beach service a drone provide. In California, drones are also used to check for sharks.</p><p>A video showing the RA-MINI Linear Actuator Series. Life-Preserver trigger for a drone.</p><p>Video Title:&#160;Lifeguard drone - REGNER&#174; RA-MINI actuator trigger</p><p>Video Publisher:&#160;REGNER&#174;</p><p>License:&#160;Creative Commons Attribution license (reuse allowed)</p><p>Note:&#160;There are no closed captions for this video.</p><p>Spotting poachers</p><p>At Chitwan National park in Nepal, drones patrol the skies reveal poachers below, on the ground. And it&#39;s working. Endangered species populations are on the rise, and reported incidences of poaching are on the decline.</p><p>close</p><p>Drones and conservation.A technology profile report. You hear a lot about drones these days, but what is a drone? A type of bee?The low thrum of a bagpipe in the distance? Well, yes, but that&#39;s not the type of drone we&#39;re talking about here. Drones and conservation are unmanned aerial vehicles remotely controlled devices that fly at low elevations carrying cameras, GPS systems and other measuring devices to collect data. Drones can gather valuable information from places where it would be arduous or even impossible for a human to reach by land. Drones can fly over forests and savannas and take images of wildlife and their surroundings. Scientists can use these images to determine the number of animals in the landscape. The overall health of the ecosystem and what threats may exist. For example, they may use drones to count the elephants and rhinos in an area or map the locations of tree nesting species such as orangutans. Drones can carry different types of cameras, including standard RGB, thermal imaging and infrared. Some drones can be launched with a simple tossed into the air, while others can do vertical takeoff and landing. Some aerial drones can even take off and land in water. Drones can help scientists determine the current state of a forest to understand whether trees have been clear-cut, burned, or replaced with crop trees, like the palms on the left side of this image. Still, images from drones can be stitched together to produce a picture of a larger area. When combined with data from other technologies, drone images can produce highly accurate three-dimensional renderings of an area. Data from drones can be used to corroborate data from ground surveys and vice versa. Drones equipped with Wi-Fi can be used to retrieve i<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('bbf3e9bebd46d2d8a2d79717b794dd8d','transportation-technologies-m5-l5-lesson-4','277407abb8a5914c60a44759dfac013a','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Drawbacks of Drones</h3><p>Drawbacks of Drones</p><p>While watching this video, listen for the risks associated with drones.</p><p>Welcome back, this is video 4 of the Drone module.</p><p>Although drones have incredible potential for good during disasters, drone use is still new territory. There are still new laws and policies being developed to govern when and how drones can be used in an emergency situation. This is often frustrating for drone operators who want to get in and help as quickly as possible.</p><p>One of the reasons the drone operators have to wait for clearance during disasters is because drone can&#39;t be located by other aircraft. The transponders used on planes to keep track of each other are not used on drones. If drones were deployed wherever, whenever, this could be disastrous and potentially fatal for organizations like the national guard. Add that to the fact that drones are not typically strong enough to lift a person, the delay in drone deployment can make sense.</p><p>And those aren&#39;t the only drawbacks of drones. Occasionally, drones go wild and injure people or property nearby. For example, as part of a holiday promotion, the restaurant TGI Friday&#39;s was using drones carrying mistletoe above diners, prompting them to kiss. Unfortunately, one of the drones crashed into the face of a photographer cutting her. In another crash incident, a drone used to photograph a triathlon crashed into one of the athletes, requiring stitches.</p><p>Although Amazon Air has made a successful drone delivery, there are still a number of issues with drone delivery. One of the biggest issues being drone law. Considering there is still debate about whether drones fall under the category of aircraft for legal purposes, it&#39;s safe to say there is quite a ways to go until the laws around commercial drone use are squared away.</p><p>Then there are the devices designed to bring down drones that are popping up (in addition to an old-fashioned rifle). How these devices are going to be regulated and who is going to have access to them is still unclear. If they become fairly easy to access, then people could shoot down drones that fly over their private property.</p><p>Add in hack risks, interference with other aerial vehicles, and drug smuggling, and it&#39;s no wonder that the Federal Aviation Administration is being cautious in their allowance of drones.</p><p>Most drones are not designed with high level security. This means it doesn&#39;t take a top level hacker to tamper with a drone. If the drone is operating on a company&#39;s wireless network, a hacked drone would mean interference with operations and functionalities of key smart devices. Any data or trade secrets stored in a drone would also be at risk for exposure in the event of a hack.</p><p>In one August of 2015, a record 12 incidences drones interfered with air traffic across the country. Total for the year were over 700 close calls between drones and planes and helicopters. Despite laws in place to prevent drones from being near airports, they are spotted there nonetheless. They are also being spotted at heights much higher than the 400 feet limit.</p><p>Clearly, drones have negative aspects that need to be considered and worked through before there is any chance of widespread use.</p></section><section><h3>Drone Security Issues</h3><p>Drone Security Issues</p><p>(opens in a new tab)</p><p>License:&#160;Public Domain</p><p>Security Issues</p><p>We&#39;ve covered the benefits, now it&#39;s time to look at some of the risks associated with drones.&#160;For one, there are security issues.&#160;It is also not too difficult to hack into most drones.&#160;If this happens to a company drone, any information stored on the drone could be exposed.&#160;This could mean leakage of trade secrets and network data, for example.</p><p>A drone has also crashed in front of the white house, and in many cases, drones are flown too close to airplanes and helicopters.</p><p>Press the tabs below to learn about drone risks.</p><p>Privacy</p><p>Then there are privacy issues.&#160;Many drones come equipped with a camera.&#160;The opportunity to harass, stalk, humiliate, and blackmail is that much easier when the harasser can invade personal space or property and easily obtain images.</p><p>Drone Harm</p><p>It&#39;s not just their pilots that can cause mayhem. The drones themselves have harmed people as well. During a festival in Virginia, a drone being used to record video crashed into the stands, injuring several people in attendance. One also has impacted sensitive environmental area, as one man crashed his drone into a famous hot spring in Yellowstone National Park.</p><p>Drug Smuggling</p><p>Drones are also being caught carrying drugs. This is a problem particularly at the border between Mexico and The US. Police have caught drones smuggling hard drugs across country lines. Listen to the following radio segment from NPR about how prisons are working to keep out drug-smuggling drones.</p><p>Regulations</p><p>The government is trying to limit the dangers drones pose by enacting various laws. For example, drones are not supposed to fly higher than 400 feet. There are also no-fly zones such as near airports. In some states, it&#39;s illegal to stalk with a drone.</p><p>Not everyone is in favor of those laws. Some worry they will stifle innovation and commerce. Others feel some of the regulations are unnecessary. For example, if people live in a place where they have “reasonable right to privacy,” does there need to be a separate law in place governing drones and privacy issues?</p><p>Drone Delivery Issues</p><p>Although Amazon Prime Air has demonstrated the capability of using drones for package delivery, there are some associated concerns. For example, the drone could damage a person or piece of property, it could be “hacked”, or someone could tamper with it upon delivery.</p><p>And the rules and regulations regarding drone delivery are far from in place, at least in the U.S. This is one of the biggest hurdles Amazon has faced with instituting Amazon Prime Air. The FAA has kept tight restrictions on the testing area for Amazon Prime Air. That is why some of the testing and delivery has happened in other countries such as Canada and the U.K.</p><p>Furthermore, if more and more companies use drone technology, it could create air traffic chaos with potentially thousands of drones flying daily. Finally, it might be relativ<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6dde42d9c917585aaa5acb8f1da03130','transportation-technologies-m5-l6-lesson-5','277407abb8a5914c60a44759dfac013a','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Career Path in Drone Industry</h3><p>Career Path in Drone Industry</p><p>While watching this video, think about things you can do right now to prepare for a career working with drones.</p><p>Welcome back, this is video 5 of the drone module.</p><p>What does it take to be a professional drone operator? Well, if you are just interested in a hobby drone, than really all it takes is a knowledge of the rules and regulations for flying a recreational drone.</p><p>If you&#39;d like to make money using your drone, than you will need a remote pilot airman certificate. There are lots of programs out there to help you pass the accompanying test. The Federal Aviation Administration also has a section on their website where you can find study guides and more information about the test content.</p><p>The potentially good and potentially bad part about a career in the drone industry is there is no set path like there is with becoming a doctor or lawyer. It&#39;s great because you can bring your own unique experiences as you pave your own way. The hard part is that it makes figuring out the next step a little tricky.</p><p>One thing you can do is take advantage of any related courses in your school or community. Math, science, engineering, computer science and other technology classes will all help too.</p><p>Companies like Insitu are opening their doors to high schoolers through internships to those interested in drones. These kinds of programs will not only give you an idea of what day to day life is like working in drone development, but will also set you apart if you choose to apply to programs and majors at the college level.</p><p>A degree in software engineering is a great degree to consider. Software engineers design and write programs for computers and electronic devices like drones.</p><p>The military is another career sector that will utilize drones more and more in the future. A military career working with drones takes a special combination of skills and decision making. Drones are capable of furthering aerial intelligence which means not only would you need to be skilled at operating a drone, but analyzing intelligence imagery quickly in order to make crucial decisions.</p><p>If you want to operate UAVs in the air force, then you must be a commissioned officer. That means you must have a college degree.</p><p>One way to figure out your path is to think about your dream job. Would it be repairing drones? Testing them? Designing them? Racing them? Once you figure out what you really want to do, a little internet research looking at current jobs and the requirements listed, will help you build a map of how to get there. Not to be cheesy, but the sky is the limit when it comes to a career in drones!</p><p>Hopefully in this module you’ve been able to see the high potential for drones to be an important part of our transportation mix in the future, while recognizing that there is still a long way to go on rules and security before you get that pizza delivered by drone.</p></section><section><h3>Potential Careers in Drones</h3><p>Potential Careers in Drones</p><p>Potential&#160;Careers in Drones</p><p>Does the idea of using a drone AND being paid sound too good to be true?&#160;Well, you can do just that.&#160;Here are 3 jobs for those skilled at using drones:</p><p>Aerial photographer:&#160;landscapes, sporting events, and real estate properties are just a few things you can get stunning photographs of using a drone.</p><p>Inspection jobs:&#160;drones are perfect for inspecting electrical lines, remote substations, cell towers and for helping insurance companies inspect claims.&#160;And those are only a few potential inspection jobs.</p><p>Engineers:&#160;Amazon&#39;s Prime Air group (the group attempting to make delivery drones a reality) is growing and in need of many types of engineers to assist in drone development, including software development, security, and electrical engineering.</p><p>Expand the sections below to learn more about drone careers.</p><p>Drone Development</p><p>If developing drones is more in line with your interests, then this might interest you.</p><p>“The Association for Unmanned Vehicle Systems International’s AUVSI Foundation has also worked with several universities to develop educational programs in unmanned systems and robotics for high school and four-year college/university undergrad and graduate students. According to the foundation, participating students are frequently offered internships and employment opportunities while still in school.”</p><p>Internship</p><p>Would you like to have an internship and gain legitimate experience while in high school? Insitu, Inc. is a manufacturer, designer, and service provider of unmanned aircraft systems that offer such internships. High schoolers apply directly to their schools, and the school selects the candidate they feel would benefit the most.</p><p>College Level Preparation</p><p>Colleges and universities are beginning to offer programs specifically to prepare students to enter the unmanned aerial sector. For example, Kansas State University -Salina has created a UAS option degree to focus on drone development. Coursework focuses on computer science, electronic and mechanical engineering with unmanned systems. “We won’t have graduated for two to three years,” says Kurt Barnhart, associate dean of research and engagement and executive director of the Applied Aviation Research Center, which oversees the university’s UAS program office. “Our current program graduates operators, analysts, and technicians, and they’re being recruited by all industry sectors. We have one-hundred percent placement right out of school.” Barnhart says that students currently make $60,000 to $80,000, which is a pretty high starting salary.</p><p>Military Opportunities</p><p>The military is another recruiter looking for UAV pilots. Drone work within the military potentially has more serious consequences than some of the other drone fields and would require a cool head and the ability to analyze aerial data.</p><p>Experts predict that as laws and rules get sorted out, and more drones enter society, this field is going to explode with job openings.&#160;Now is truly a great time to start learning more about drones.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f378feffcbbab478cab37afed39dd27d','transportation-technologies-m5-l7-module-5-summary','277407abb8a5914c60a44759dfac013a','Module 5 Summary','text',12,'<h2>Module 5 Summary</h2><section><h3>Module 5 Summary</h3><p>Module 5 Summary</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Drones!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Defined drones and distinguish drones from other types of aerial technology and transportation</p><p>Described technologies that allow drones to fly, be controlled remotely, and operate autonomously</p><p>Determined the impact of drone delivery on jobs and the environment</p><p>Identified how drones are used to deliver food, healthcare supplies, and packages</p><p>Assessed the safety of drone delivery</p><p>Predicted when they will receive their first package delivered by drone</p><p>Identified career opportunities in drones and educational paths to enter those careers</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1c15e65a562cee62b0e484268c0afd0d','transportation-technologies-m5-l8-module-5-assignment','277407abb8a5914c60a44759dfac013a','Module 5 Assignment','text',12,'<h2>Module 5 Assignment</h2><section><h3>Module 5 Assignment</h3><p>Module 5 Assignment</p><p>Transportation</p><p>Drones - Short Answer Assignment</p><p>Short answer assignment</p><p>Article Critical Review:&#160;Now that you have developed an understanding of the benefits and problems with drones, read, compare, and analyze the following two articles (expand each section below).&#160;After doing so, answer the questions that follow in a two-page, double-spaced paper.</p><p>Article 1 - Drone Delivery Takes Flight: The Promise and Challenges for Urban Logistics</p><p>In the rapidly evolving landscape of logistics, drone delivery has emerged as an innovative solution to enhance efficiency and speed. With companies like Amazon at the forefront, the concept of aerial delivery has captured public imagination. However, as drone delivery becomes a reality in urban areas, there are both promises and challenges to be addressed.</p><p>The Rise of Drone Delivery in Urban Areas: In recent years, the concept of drone delivery has gained traction, with companies like Amazon pioneering the development and implementation of this technology. Drones offer the potential for faster and more flexible delivery, particularly in congested urban environments where traffic congestion and the last-mile challenge remain significant hurdles.</p><p>Promises of Drone Delivery: Drone delivery holds several promises that can revolutionize urban logistics:</p><p>Speed and Efficiency: Drones have the capability to bypass traffic congestion and deliver packages directly to customers&#39; doorsteps, significantly reducing delivery times. This swift delivery can greatly benefit time-sensitive goods or emergency situations.</p><p>Cost Savings: Drone delivery has the potential to reduce costs associated with traditional delivery methods, including fuel expenses and labor costs. By automating the delivery process, companies can optimize routes and improve operational efficiency.</p><p>Environmental Benefits: With their electric propulsion systems, drones offer a greener alternative to conventional delivery vehicles, reducing carbon emissions and environmental impact. This aligns with the growing focus on sustainability and mitigating the environmental effects of transportation.</p><p>Challenges and Considerations: While drone delivery holds immense promise, several challenges and considerations need to be addressed:</p><p>Regulatory Framework: The use of drones in urban areas is subject to strict regulations due to safety and privacy concerns. Ensuring compliance with aviation regulations, establishing no-fly zones, and addressing privacy issues are crucial steps in facilitating the integration of drones into urban airspace.</p><p>Infrastructure and Airspace Management: The integration of drones into urban environments requires the development of appropriate infrastructure and airspace management systems. This includes creating landing pads, establishing designated routes, and implementing robust communication networks to ensure safe and efficient drone operations.</p><p>Security and Safety: Preventing unauthorized drone access, mitigating the risk of collisions, and addressing concerns about package theft require robust security measures. Implementing geofencing technology, secure delivery mechanisms, and advanced tracking systems can help enhance security and safety in drone delivery operations.</p><p>Noise and Visual Impact: Urban environments are densely populated, and the noise and visual impact of drones can be disruptive to residents. Striking a balance between the benefits of drone delivery and the quality of life for urban dwellers is essential. Developing quieter and visually unobtrusive drone designs and establishing guidelines for flight paths can help minimize these concerns.</p><p>Drone delivery is poised to revolutionize urban logistics, offering speed, efficiency, and environmental benefits. With ongoing advancements in technology and increasing collaborations between companies, regulators, and communities, the integration of drones into urban airspace is becoming a reality. By addressing challenges related to regulations, infrastructure, security, and social impact, the promise of drone delivery can be realized, transforming the way goods are transported and enhancing the overall efficiency of urban logistics.</p><p>Article 2 - Exploring the Feasibility of Drone Delivery: Fact vs. Fiction</p><p>As the world embraces technological advancements, the future of drone delivery has become a topic of interest and speculation. While the concept of drones buzzing through the skies to deliver packages is intriguing, it is essential to separate fact from fiction and examine the feasibility of this emerging technology.</p><p>Drone Delivery: Fact or Fiction? The notion of drone delivery has captured the public&#39;s imagination, thanks in part to visionary companies like Amazon. However, several factors must be considered to determine the feasibility of widespread drone delivery implementation.</p><p>Technological Challenges: The technology required for drone delivery has made significant strides, but certain challenges remain. These include improving battery life and flight range, enhancing navigation and collision avoidance systems, and developing effective mechanisms for payload release and landing in various environments.</p><p>Regulatory Landscape: The regulatory framework surrounding drone delivery plays a pivotal role in determining its feasibility. Governments worldwide are working to establish guidelines and rules that ensure safety, privacy, and airspace management. Collaboration between regulators, industry stakeholders, and the public is crucial to strike the right balance between innovation and regulation.</p><p>Operational Limitations: Drone delivery faces operational limitations that need to be addressed. Factors such as weight restrictions, adverse weather conditions, and the ability to deliver to densely populated urban areas present significant challenges. Solutions must be developed to overcome these limitations for drone delivery to become a practical reality.</p><p>Last-Mile Delivery: The &quot;last-mile&quot; challenge, referring to the final leg of the delivery process from a distribution center to the customer&#39;s doorstep, is a key consideration. While drones offer potential advantages in terms of speed and efficiency, traditional delivery methods remain crucial for large or heavy items, as well as situations requ<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('837c5bd212b5057a25048fda6618c34f','transportation-technologies-m5-l9-module-5-project','277407abb8a5914c60a44759dfac013a','Module 5 Project','text',12,'<h2>Module 5 Project</h2><section><h3>Module 5 Project</h3><p>Module 5 Project</p><p>Transportation</p><p>Drones - Project</p><p>Project</p><p>In this assignment, you will create a presentation to describe the main components of a drone and some benefits and uses of drones. You can use a presentation software such as PowerPoint or Prezi to create your description. Be sure to cite any resources for images and other content.</p><p>Your presentation should:</p><p>describe the important technology of a quadcopter drone</p><p>discuss current and future innovative uses of drones</p><p>explain benefits of drone use</p><p>discuss negative aspects of drone use</p><p>be organized and engaging</p><p>Review the rubric below to see how you will be graded.</p><p>Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Technology</p><p>8 points The presentation effectively describes the technologies of the quadcopter drone and discusses at least three innovative uses of drones.</p><p>7-6 points The presentation adequately describes the technologies of the quadcopter drone and discusses at least two innovative uses of drones.</p><p>5-0 points The presentation does not adequately describe the technologies of the quadcopter drone and discusses less than two innovative uses of drones.</p><p>8</p><p>Benefits and Limitations</p><p>8 points The presentation demonstrates a strong understanding of the positives and negatives of drone use. It contains several specific and accurate details.</p><p>7-6 points The presentation demonstrates a satisfactory understanding of the positives and negatives of drone use. It contains some specific and accurate details</p><p>5-0 points The presentation demonstrates little to no understanding of the positives and negatives of drone use. It contains few to no specific and accurate details.</p><p>8</p><p>Presentation</p><p>2 points The presentation is clear and organized.</p><p>1 point The presentation is somewhat clear and organized.</p><p>0 points The presentation is not clear and organized.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('01d08af406a28982f92b080b33004700','transportation-technologies-m5-l10-module-5-quiz','277407abb8a5914c60a44759dfac013a','Module 5 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Drones. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('4d7ef65e39e41c85a65a51e2d5a6b996','transportation-technologies-module-6','504e3ab88df8552a07116f12aea44099','Module 6: Hyperloop',6) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a4779157421036728f8345b99e254ef0','transportation-technologies-m6-l1-introduction-purpose-and-objectives','4d7ef65e39e41c85a65a51e2d5a6b996','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi and welcome to the module on the Hyperloop.</p><p>What do you get if you combined an air hockey table, a vacuum, and a high-speed pod-train? Answer: Elon Musk&#39;s proposed Hyperloop! This proposed form of transportation would whisk cargo through a series of tubes at over 700 miles per hour. Hyperloop One is one of many companies that are developing a vactrain, a concept that was invented way back in 1799! If realized, the Hyperloopvactrain would become the fifth mode of transportation (with boats, trains, motor vehicles, and airplanes being numbers 1-4) and could completely change the transportation industry.</p><p>In this module, we are going to dive into all things Hyperloop, its technologies, some potential positives, as well as risks. Perhaps more than most futuristic transportation concepts, Hyperloop has received a lot of criticism as something that will never actually work. But a lot of money and people are at work trying to make this a reality. We’ll see what your conclusion will be at the end of the module.</p><p>Module Description</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>So you need to get from Los Angeles to Las Vegas.&#160;You could take a car and be there in about six to eight hours.&#160;You could take a plane and get there in a little over an hour.&#160;Or perhaps in the not-too-distant future, you could take the Hyperloop and get there in a whopping thirty minutes.</p><p>This module is all about the proposed Hyperloop and vactrain concept.&#160;Starting with the technology, the module will explain what a vactrain is and a bit about the physics behind it.&#160;Second, it will investigate whether the concept of Hyperloop is actually practical, given costs and the&#160;current state of technology.&#160;Third, the module will examine the risks associated with such a system.&#160;After having looked at the technology and hurdles behind the system, the module will take a look at the current state of Hyperloop development and what the future holds.&#160;Finally, the module goes over careers and opportunities in the vactrain sector.</p><p>Objectives</p><p>In this module, students will</p><p>Define key technological and engineering aspects of a vactrain</p><p>Examine the historical development of the vactrain concept</p><p>Debate whether Hyperloop is practical given costs and current technologies</p><p>Discuss risks of the Hyperloop system, such as system failures or susceptibility to terrorism or natural disasters such as earthquakes</p><p>Predict when the Hyperloop or another vactrain will be operational and open to the public</p><p>Identify career opportunities in vactrain technology and educational paths to enter those careers</p><p>Polling Question</p><p>What year do you think you will take your first ride in the Hyperloop?</p><p>Before 2025&#160;2025-2030&#160;After 2030&#160;Never</p><p>Make a selection to see the results so far.</p><p>How did your prediction compare to your classmates?&#160;Let’s see how your answer changes as your learn more about the Hyperloop!</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>is a system in which containers (carriers) are propelled through a network of tubes by compressed air or by vacuum</p><p>Pylons</p><p>a method by which an object is suspended with no support other than magnetic fields</p><p>Pneumatic tube transportation</p><p>structural support towers</p><p>Magnetic levitation</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>is a system in which containers (carriers) are propelled through a network of tubes by compressed air or by vacuum</p><p>Answers for question: 1</p><p>Pylons</p><p>Pneumatic tube transportation</p><p>Magnetic levitation</p><p>2.</p><p>a method by which an object is suspended with no support other than magnetic fields</p><p>Answers for question: 2</p><p>Pneumatic tube transportation</p><p>Pylons</p><p>Magnetic levitation</p><p>3.</p><p>structural support towers</p><p>Answers for question: 3</p><p>Magnetic levitation</p><p>Pylons</p><p>Pneumatic tube transportation</p><p>very high-speed rail transportation system that uses magnetic levitation and vacuum-like tubes</p><p>Drag</p><p>a pneumatic lifting device used to move heavy loads on flat, non-porous surfaces.&#160;Uses thin layer of air to float objects off the ground</p><p>Vactrain</p><p>resistance to the motion of an object through the air.&#160;Increases with speed</p><p>Friction</p><p>rubbing between solid objects.&#160;Remains constant</p><p>Air caster skis</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>very high-speed rail transportation system that uses magnetic levitation and vacuum-like tubes</p><p>Answers for question: 1</p><p>Friction</p><p>Vactrain</p><p>Air caster skis</p><p>Drag</p><p>2.</p><p>a pneumatic lifting device used to move heavy loads on flat, non-porous surfaces. Uses thin layer of air to float objects off the ground</p><p>Answers for question: 2</p><p>Friction</p><p>Vactrain</p><p>Air caster skis</p><p>Drag</p><p>3.</p><p>resistance to the motion of an object through the air. Increases with speed</p><p>Answers for question: 3</p><p>Drag</p><p>Vactrain</p><p>Friction</p><p>Air caster skis</p><p>4.</p><p>rubbing between solid objects. Remains constant</p><p>Answers for question: 4</p><p>Vactrain</p><p>Friction</p><p>Drag</p><p>Air caster skis</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('cfd1ae6c93831ac5d9955735dbddcd7a','transportation-technologies-m6-l2-lesson-1','4d7ef65e39e41c85a65a51e2d5a6b996','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Origin of Hyperloop Term and How they Work</h3><p>Origin of Hyperloop Term and How they Work</p><p>While watching the video below, pay attention to how magnets can be used to make objects levitate!</p><p>Welcome back, this is video one for the module on the Hyperloop.</p><p>Elon Musk seems to be getting quite a bit of attention for his proposed transportation system called the Hyperloop. However, the idea of vactrains, which is the term for the type of technology used for the Hyperloop, dates back long before Musk published his research paper. George Medhurst proposed moving goods through cast-iron pipes by using air pressure. His railway which was built in London 1844, used pressurized air until 1847. More pressurized air, or pneumatic, railways were built during the 1850s.</p><p>Over 100 years ago, in 1910, Robert Goddard, designed a train that would go from Boston to New York in just 12 minutes! If that sounds incredible now, just think how extraordinary the idea must have been back then! It was never built, but the proposed idea called for a train that floated on a track inside a vacuum sealed tunnel.</p><p>Clearly innovative people have been dreaming up vactrain technology long before the word “hyperloop” was ever uttered. So what is this Hyperloop and how does it work? The Hyperloop is a proposed transportation system of pods traveling at high speeds through near-vacuum tubes. Furthermore, the pods would sit on air caster skis, like how an air hockey puck floats on an airhockey table. The combination of the vacuum-like environment and the floating pods means there&#39;s little friction. Little friction means higher speeds. Musk projected that the Hyperloop would reach maximum speeds of 760 miles per hour! An electric motor would launch the pods until levitation takes place and the pod begins cruising.</p><p>So that was the original plan, as proposed by Musk. Two companies that are leading the pack in making this a reality, Hyperloop One and Hyperloop Transportation Technologies, take a slightly different approach. The low-pressure tubes are still a key component, but instead of air caster skis for levitation, the companies use a form of magnetic levitation. In their approach, pod-side magnets repel a passive track, creating levitation. This is a type of magnetic levitation known as passive magnetic levitation. The low pressure reduces drag, which is the resistance to the motion of an object through the air. Levitating the pods means there&#39;s no friction or rubbing between the pods and the tracks. The result- estimated speeds of 670 miles per hour.</p><p>Let’s dig in more to see if these speeds can become a reality, or if this is all just a pipe dream!</p></section><section><h3>Vactrain History</h3><p>Vactrain History</p><p>(opens in a new tab)</p><p>Vactrain History</p><p>Ten years ago, no one had ever heard the term “Hyperloop.” Now, due to its increasing media attention, it is being discussed around the world.&#160;However, vactrains, which use magnetic levitation and pressurized air and is the technology behind the Hyperloop, dates back to 1799.&#160;During this time, inventor George Medhurst proposed moving goods through cast-iron pipes via air pressure.&#160;He actually built a railway station in London that relied on pressurized air.</p><p>And Medhurst&#39;s railway was not the last of its kind.&#160;The mid 1850’s saw the development of several more pneumatic, or pressurized air, railways.</p><p>American rocket pioneer, Robert Goddard designed a train that would go from Boston to New York in a mere 12 minutes.&#160;Although the train system was never built, it was the original vactrain system, combining magnetic levitation and a vacuum-sealed tunnel.</p><p>Others have also proposed similar systems.&#160;MIT designed a vacuum-tube train system in the early 1990s which also would have used magnetic tracks.&#160;In the early 2000s, a company called ET3 designed a system using car-sized pods that would travel in pneumatic, elevated tubes using magnetic levitation.</p><p>Let&#39;s take a brief look at the vactrain timeline.&#160;Expand each section below.</p><p>1910s - Early Concepts</p><p>The concept of evacuated tube transportation, also known as the vactrain, is first proposed by inventor and engineer Robert Goddard in the early 1910s. He envisions a system where trains travel through a low-pressure vacuum tube, reducing air resistance and allowing for high-speed transportation.</p><p>1930s - Further Developments</p><p>In the 1930s, additional patents and concepts for evacuated tube transportation systems are developed by various inventors. These ideas lay the groundwork for future advancements in the technology.</p><p>1972 - ET3 Proposal</p><p>In 1972, Daryl Oster proposes the Evacuated Tube Transport (ET3) system, a vactrain concept that aims to achieve extremely high speeds, reaching up to 6,500 km/h (4,000 mph). This proposal gains attention and sparks further interest in vactrain technology.</p><p>1980s - Initial Prototypes</p><p>During the 1980s, small-scale prototypes and feasibility studies of vactrain systems are conducted. Researchers begin exploring magnetic levitation (maglev) technology as a means to lift and propel the trains inside the evacuated tubes.</p><p>1990s - The Swissmetro Project</p><p>The Swissmetro project is launched in the 1990s, with the aim of developing a vactrain system for high-speed transportation in Switzerland. The project proposes connecting major cities like Zurich, Geneva, and Basel through evacuated tubes.</p><p>2000s - Continued Research and Investment</p><p>In the early 2000s, interest in vactrain technology continues to grow, and several research institutions and private companies invest in the development of vactrain prototypes. The focus is on improving maglev technology, creating more efficient propulsion systems, and addressing safety concerns.</p><p>2013 - Elon Musk&#39;s Hyperloop Proposal</p><p>In 2013, entrepreneur Elon Musk publishes a white paper outlining the concept of the Hyperloop, a high-speed transportation system utilizing vactrain principles. The proposal generates significant public interest and leads to the formation of various Hyperloopstartups.</p><p>2017 - First Hyperloop Test</p><p>In 2017, the first full-scale Hyperloop test track is constructed in Nevada, USA. Several companies, including SpaceX and Virgin Hyperloop, conduct competitions and trials to demonstrate the feasibility of t<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('184a2fde2ec0119323a40b9349197cd2','transportation-technologies-m6-l3-lesson-2','4d7ef65e39e41c85a65a51e2d5a6b996','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Feasibility of Hyperloop and Cost</h3><p>Feasibility of Hyperloop and Cost</p><p>While watching the video below, think about the benefits of building a smaller, test version of the Hyperloop system.</p><p>Welcome back, this is video 2 for the module on the Hyperloop.</p><p>So... will the Hyperloop system actually work? Meaning, will it actually do all that it was designed to do? That depends on who you ask.</p><p>Hyperloop One initially tested their system in May of 2017. The test sled, which used magnetic levitation and pneumatic tube transportation, hit 70 miles per hour in just over five seconds. And it’s likely by the time you are watching this, additional and faster tests have been performed.</p><p>Critics point out that those results are a long way from the near 700 miles per hour Hyperloop One originally projected. Furthermore, how many places are truly a straight shot from one location to another without having to turn corners and climb hills?</p><p>Hyperloop One counters that criticism by saying that the results indicate that with a longer track, top speeds can be reached, and that the important thing to focus on is that the system worked. Propulsion, braking, the levitation system, and the near-vacuum systems worked!</p><p>At this point, whether the test points to the feasibility of the idea or whether the test is just smoke and mirrors detracting from the real problems, remains to be seen.</p><p>It seems like a pretty awesome transportation system, getting from LA to Vegas in a half hour, but what about the costs? And does the technology really work the way it has been theorized to work?</p><p>Hyperloop believers are particularly enthusiastic about the potential cost saving of the technology. Originally, it was estimated to cost $6 billion to build a track from LA to San Francisco. To put this in perspective, a high-speed rail link would cost an estimated $68 billion. However, that $6 billion number is likely to be a little bit of an underestimate... by more than half. Leaked documents from Hyperloop One suggest that an even shorter route would cost more like $13 billion.</p><p>Critics suspect that even the $13 billion is an underestimate. Michael Anderson, a professor of at the University of California at Berkeley, predicts that the cost of the system would reach $100 billion. That is a HUGE number and would make the economics of Hyperloop completely unrealistic.</p><p>So that&#39;s looking at the costs to build. But what about the cost to ride?Hyperloop One&#39;s website is pretty vague on the actual cost to ride, merely stating that it depends on the route. It does say that the goal is to make it affordable for everyone to ride.</p><p>Of course, that would be assuming&#160;their&#160;economics are correct. If Professor Anderson is right, then it&#39;s likely to only be available to the super rich because of the high cost they&#39;d have to pass on to the riders.</p></section><section><h3>Hyperloop One Test &amp; Cost Comparison</h3><p>Hyperloop One Test &amp; Cost Comparison</p><p>Hyperloop is inexpensive and it works!&#160;Or at least that is what Hyperloop enthusiasts believe.</p><p>Hyperloop One Test</p><p>Hyperloop developers would have a hard time raising a single penny more if it starts to look like the technology itself does not even work.&#160;Luckily for supporters and investors, the developers are out to prove that it does work.&#160;In July of 2017 Hyperloop One tested a full-scale hyperloop on its test track.&#160;The track was 500 meters long and the pod was able to get going to almost 200 miles per hour.</p><p>Watch the test run in the video below:</p><p>Imagine traveling non-stop at up to 670 miles per hour above land or underground. This is a virgin Hyperloop, one a fast and effortless form of transportation that expands possibilities. It starts with an electric motor, which is broken up into two basic components. The rotor, which rotates and the stator, which is stationary. The stator is an electromagnet, so when an electric current passes through it, the rotor is magnetically attracted to spin. Unlike a normal electric motor, the Virgin Hyperloop One motor isn&#39;t circular. It&#39;s linear, and the rotor is on the pod, which is propelled magnetically as it moves over the stator. Virgin Hyperloop one&#39;s proprietary technology uses magnetic levitation to guide and lift the pod off the track. Nearly all of the air inside the Hyperloop tube is removed using a series of vacuum pumps. This effectively creates our own sky inside the tube as if you are quietly flying at 200,000 feet above sea level. This reduces drag, so only the smallest amount of electricity is needed to achieve extraordinary speeds, and it creates a more cost and energy-efficient system than high-speed rail or airline transport. Virgin Hyperloop One will be automated by the most advanced systems in the world, allowing a safe and efficient journey that&#39;s never delayed or overbooked. Our vision is not only to move passengers but also cargo DP world cargo speed will deliver goods closer to the cost of trucking at the speed of flight. Sustainable operations powered by renewable energy utilizing network capacity for both freight and passengers, goods are seamlessly transferred to autonomous vehicles while passengers are taken to the heart of the city. Rapid, effortless deliveries and the freedom from having to plan too far ahead.A collective system that unlocks greater capacity for growth. Virgin Hyperloop One is the first new form of mass transportation in more than a hundred years. Fundamentally, it will change the way we travel, work, and live. Welcome to the future. Welcome to Virgin Hyperloop One.[Music]</p><p>Video Title:&#160;Virgin Hyperloop One | The Road Ahead:&#160;Reimagining Mobility</p><p>Video Publisher:&#160;Cooper Hewitt</p><p>License:&#160;Creative Commons Attribution license (reuse allowed)</p><p>The test in July 2017 was a big victory for Hyperloop One.&#160;It traveled 4.5 times further, achieved 2.7 times more speed, and experienced 3.5 times more horsepower than any prior test.&#160;While the speeds were not the 600+ miles per hour max that the company claims Hyperloop can reach, nevertheless, the company feels this validates that the science is there; that given the proper amount of track to gain speed, Hyperloop could reach such speeds.&#160;It also validates the technology- a vacuum-like tunnel and magnetic levitation enable very fast transpo<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7e3341e991de9d7a2290221dbcae5074','transportation-technologies-m6-l4-lesson-3','4d7ef65e39e41c85a65a51e2d5a6b996','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Passenger Safety of the Hyperloop</h3><p>Passenger Safety of the Hyperloop</p><p>While watching the video below, pay attention to the potential risks and what the hyperloop companies plan to do to eliminate or reduce those risks.</p><p>Welcome back, this is video 3 for the module on the Hyperloop.</p><p>Costs, technology, the human ability to withstand a 30-minute potential roller coaster... we&#39;ve really only reached the tip of the iceberg, so to speak, of the potential problems with hyperloop.</p><p>Let&#39;s look at safety. Remember, the Hyperloop is essentially a vacuum tube. The air is being pumped out. Dr. Phil Mason, former Cornell University chemist stated that, “any rupture or crack in the Hyperloop capsule for any reason would expose the passengers to a hard vacuum, causing them to die in exactly the same way they would in deep space.” Basically, the kind of stuff nightmares are made of.</p><p>Dr. Mason even conducted a small scale test simulating a crack letting air in the tube. The result- the pressure change wrecked the tube and accelerated the mini Hyperloop to levels that would have killed passengers. Ready to ride the hyperloop yet?</p><p>Keep in mind that is the voice of a critic. Let&#39;s be fair and look at what HyperloopOne says would happen in the event of a crack or breach. First, they claim the tubes will be thick, strong, and very difficult to puncture. Nevertheless, they feel they would be prepared to safely handle the situation. The pods would be built to withstand extreme pressure and changes in pressure. According to the website, the pods would likely be able to glide safely to the nearest station. The only thing missing from this plan is exactly HOW and WHAT technology will do those things. Nevertheless, they assure us they will.</p><p>Here&#39;s another issue. When steel gets hot, it expands. With bridges, this problem is solved by using expansion joints. Those joints, however, would not work for a vacuum tube. And IF expansion joints were used, if one broke, the entire system would collapse, air would flood in, and disaster would strike.</p><p>Not to worry, says Hyperloop One. The tubes would be mounted on a series of pylons to allow for slip, thermal expansion, and earthquakes. Pylons, for those of you unfamiliar with the term, are towers that support a structure.</p><p>Another concern is terrorist attacks. Mass transit systems are appealing targets to terrorists because transportation systems contain a large amount of people in a consolidated space.</p><p>Again, Hyperloop One says they&#39;re on this problem. The same amount of security at an airport will exist in the Hyperloop system. But because pods will be coming and going so fast, the security checks should be much faster than airport security. However, airport-like security does little to stop terrorists from targeting the pylon structures and miles and miles of the tube track.</p><p>So now that we&#39;ve discussed the reality of the hyperloop a little more, what do you think? Would you want to take the opening ride?</p></section><section><h3>Hyperloop Risk and Claims</h3><p>Hyperloop Risk and Claims</p><p>(opens in a new tab)</p><p>Creative Commons&#160;is licensed under&#160;CC BY-SA 4.0(opens in a new tab).</p><p>Hyperloop One</p><p>Press through each tab below to learn more about Hyperloop One.</p><p>Hyperloop Risks</p><p>How safe do you feel when you get on an airplane?&#160;Do you even think about the risks of flying, or do you just walk through security, board the plane, and put on your headphones, hardly paying attention to the safety briefing?&#160;Hyperloop developers hope riders will have that sort of safe and secure feeling when riding the Hyperloop.</p><p>Terrorism</p><p>History shows that terrorists take advantage of mass transit systems for terrorist attacks. The fact that large groups of people congregate in a relatively small area makes mass transit systems high targets for terrorists. For that reason, Hyperloop One proposes the same high-security checks airports employ before boarding an airplane. However, the system will supposedly go much faster at a hyperloop station because pods will be coming and go so much more frequently and systematically than airplanes.</p><p>Pylons and Structural Safety</p><p>Safety within the station does not necessarily translate to safety outside the station. The pylons (structural support towers) that support the Hyperloopsystem, may still be targets. And there is no indication that there will be guards standing watch at each pylon.Pylons are also the proposed solution for problems related to thermal expansion, which is what happens when steel gets hot. As well as the solution to earthquakes since the tube is not rigidly fixed at any point. According to Musk, inside each pylon could be two lateral dampers and one vertical damper. The dampers are devices that would absorb seismic activity.</p><p>Some engineers raise their eyebrows in skepticism about the feasibility of this pylon and damper plan. Engineer Kristen Ray said, “A simple damper will not suffice for the major seismic activity potential in the San Francisco and Los Angeles areas with a structure that needs to keep such exact tolerances due to the high speeds.”</p><p>Tube Stability</p><p>Another potential issue is the thickness of the tube. If a crack or breach happened, disaster would strike. Dr. Phil Mason, a former Cornell University explained that, “... a single breach in the Hyperloop would probably kill everybody else in the Hyperloop because air would rush into the tube at about the speed of sound.”</p><p>Next Tab</p><p>Hyperloop Claims</p><p>So the solution, according to Hyperloop One, is to build thick, strong tubes made of steel and tubes and pods that can withstand sudden pressure changes.&#160;Although that sounds reassuring, it raises the question:&#160;won&#39;t that make the construction extremely expensive?&#160;After all, the pylons and dampers are going to have to support extremely thick tubes, not just in optimal conditions, but in extreme weather and natural disasters too.</p><p>One safety feature Hyperloop One claims they will have is the ability to section off parts of the route.&#160;That way, in theory, they could limit problems to just one area.&#160;Furthermore, the company plans to build sensors to notify of any problems or air breaches.</p><p>Furthermore, all Hyperloop One pods will be autonomous.&#160;This eliminates driver-related errors<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a1bd41d98413614c74f07f88e87dcbc8','transportation-technologies-m6-l5-lesson-4','4d7ef65e39e41c85a65a51e2d5a6b996','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Hyperloop Project Obstacles</h3><p>Hyperloop Project Obstacles</p><p>While watching the video below, think about your earlier answer to the question “When do you think you&#39;ll take your first ride on the Hyperloop?”.&#160;See if it changes after the video!</p><p>Welcome back, this is video 4 for the module on the Hyperloop.</p><p>Based on everything you&#39;ve learned about what current Hyperloop tests have shown and the safety and practicality features that have yet to be worked out, would it surprise you to learn that Hyperloop One aims to be operational by 2021? According to their website, that&#39;s the goal!</p><p>Let&#39;s just make a quick list of things that&#160;still&#160;need to be worked out before all systems are go for the Hyperloop:</p><p>One: Safety regulations and certifications</p><p>Two: Funding,</p><p>Three: Agreements from all cities, states, and municipalities involved</p><p>Four: Environmental Impact Statements drawn up</p><p>And of course, building and perfecting the technology</p><p>However, this list is limited to what needs to be done to build in the United States. Lots of locations outside the US are interested in Hyperloop routes as well. Other countries that have expressed interest include: England, India, Mexico, Canada, Dubai, and South Korea.</p><p>For a while, it seemed like Dubai would be the front-runner to see a hyperloop project come to fruition. There were even rumors that a route was proposed between two airports in Dubai. However, in April of 2018, these rumors were denied by the Dubai government, who said that “the system is still under the process of research and development,” and that they “will study several options for determining the route which will be announced in the future.” They also need to “determine the feasibility of implementation and reduce the potential risks, and maximize the benefit of the project.”</p><p>However, by the time you are taking this course, there may by other projects in other countries that are much further down the path. It will be an exciting industry to keep and eye on. But given all the steps listed earlier, it’s a safe bet that a hyperloop track won’t appear out of thin air! The process of developing and testing the first hyperloop system will take many years.</p></section><section><h3>Critics of Hyperloop One</h3><p>Critics of Hyperloop One</p><p>Critics are very skeptical about Hyperloop One&#39;s ambitious goals.&#160;Several barriers have been brought up in the article&#160;from Wired.com&#160;(which is focused on another Musk project, The Boring Company, but many of the principles also apply to Hyperloop).&#160;Consider the following questions as you read through this section.</p><p>How long could an environmental impact study take?&#160;Why do you think it would take so long?&#160;What aspects of the environment would need to be considered?</p><p>Why is Hyperloop One trying to overcome other barriers when the technology still is not proven?</p><p>Why do you think building a Hyperloop costs so much money?&#160;What are some of the main expenses involved?</p><p>If you were a state or city regulator, would you&#160;consider approving a Hyperloop track through your&#160;state or city?&#160;Why or why not?</p><p>Expand each section below to learn about why critics believe that Hyperloop One has and will continue to face significant challenges that can prevent it from ever seeing the light of day.</p><p>(opens in a new tab)</p><p>Creative Commons&#160;is licensed under&#160;CC BY-SA 4.0(opens in a new tab).</p><p>Technological Complexity and Safety Concerns</p><p>The Hyperloop concept proposes transporting passengers or cargo at extremely high speeds through low-pressure vacuum tubes. This ambitious idea poses numerous technological challenges, including maintaining the vacuum conditions over long distances, coping with thermal expansion and contraction, and ensuring passenger safety in the event of system failure or accidents. Demonstrating the safety and reliability of such a system at scale has been a major obstacle.</p><p>Cost and Funding</p><p>Building the infrastructure required for the Hyperloop, including long vacuum tubes and high-speed tracks, would be an expensive endeavor. Critics argue that the initial proposal&#39;s estimated costs might not be realistic and that actual expenses could significantly exceed projections. Securing the necessary funding for such a massive transportation project has been challenging, especially considering the uncertainties surrounding its feasibility.</p><p>Regulatory and Legal Hurdles</p><p>Implementing the Hyperloop requires overcoming various regulatory and legal challenges, particularly in terms of safety certifications, liability issues, and obtaining permits for land acquisition and construction. The existing transportation regulatory framework may not adequately address the unique characteristics of the Hyperloop, leading to further delays and uncertainties.</p><p>Competition from Existing Transportation Modes</p><p>The Hyperloop faces strong competition from established transportation modes, such as airplanes and high-speed trains. Convincing travelers and governments to shift from proven, well-established options to a relatively unproven and high-risk technology can be challenging.</p><p>Energy Consumption</p><p>While the Hyperloop aims to be energy-efficient, the constant acceleration and deceleration of pods to achieve high speeds could still require substantial energy consumption, especially if the system scales up to serve a large number of passengers. Ensuring a sustainable and low-energy operating model has been a point of concern.</p><p>Logistical and Infrastructure Challenges</p><p>Building an extensive network of tubes for the Hyperloop presents logistical and engineering challenges, especially when considering the vast distances that some proposed routes might cover. Developing such an infrastructure on a global scale, often traversing diverse landscapes and regions with different geological and environmental considerations, could be a complex and expensive task.</p><p>Lack of Real-World Testing at Scale</p><p>There have not been any full-scale operational Hyperloop systems carrying passengers or cargo. Demonstrating the viability of the technology through real-world testing is crucial for gaining public trust, investor confidence, and government support.</p><p>It&#39;s essential to note that some companies and projects ha<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3321f5296a31f75c4ec4ff0037e2959d','transportation-technologies-m6-l6-lesson-5','4d7ef65e39e41c85a65a51e2d5a6b996','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Careers in Hyperloop Development</h3><p>Careers in Hyperloop Development</p><p>While watching the video below, think about how your own talents and experiences could contribute to Hyperloop development.</p><p>Welcome back, this is video 5 for the module on the Hyperloop.</p><p>We&#39;ve talked a lot about the hurdles standing in the way of Hyperloop. We&#39;ve listed a lot of criticisms and potential problems. Some of you might have dismissed Hyperloop as just a cool, but unrealistic dream. Some of you might be thinking “yeah, there are hurdles...&#160;but what if!”</p><p>If you fall into the latter group, it&#39;s likely Hyperloop One, Hyperloop Transportation Technologies, or another hyperloop development company could use you and your attitude. So how do you get involved with those companies?</p><p>You could start with a summer internship while in college. Hyperloop One has both engineering and non-engineering internships. The engineering internships generally go to those with majors in: aerospace engineering, electrical engineering, mechanical engineering, manufacturing engineering, industrial engineering, civil engineering, computer science, and material science. As with many other industries and companies, performing well during internships could lead to full-time employment. Hyperloop One has a massive list of engineering needs on all aspects of the hyperloop systems, from batteries and hyperstructures, to pod and safety engineering. Most of their positions require at least a bachelor’s degree in engineering, along with 2-plus years of experience. Sometimes, but not always, internships can put you on the fast track with a company.</p><p>What about non-engineers? Hyperloop One also has non-engineering internships for those of you who are Hyperloop believers, but don&#39;t want to be future engineers. The groups for these positions include: business strategy, finance, information technology, legal, marketing, and talent operations. That doesn’t mean you can be totally ignorant of the engineering aspects of the business. Interacting with teams of engineers requires a knowledge of what they are doing and what challenges they face.</p><p>Hyperloop could change the world. It&#39;s amazing to think YOU could be part of that change.</p></section><section><h3>Future of Hyperloop and Obstacles</h3><p>Future of Hyperloop and Obstacles</p><p>The Future of Hyperloop</p><p>It is a bit amazing to think that prior to 2013, hardly anyone was talking about vactrains as a viable mode of transportation.&#160;Elon Musk had not written his 57-page white paper outlining the technology.&#160;Hyperloop One and Hyperloop Transportation Technologies did not even exist.&#160;While ambitious and innovative, the project&#39;s future is not exactly bright - at least according to experts at SXSW in 2023.</p><p>Jack Phillips, director of infrastructure and mechanical engineering advisor at Texas Guadaloop, a company developing hyperloop technology, lamented that it didn&#39;t feel like progress was being made.&#160;Unfortunately, the sad truth is that the development of the Hyperloop presents more of a political and societal perception problem than an engineering one (to be overcome).</p><p>Speaking at SXSW 2023 in Austin, Texas, Phillips listed several obstacles, including price, a lack of safety rules, and the availability of more conventional forms of transportation.</p><p>Expand the sections below to learn more.</p><p>Technology</p><p>Technology also played a role. Phillips pointed out that Musk&#39;s 2013 Hyperloop white paper suggested utilizing an air-bearing pneumatic levitation system, in which air enters tiny holes to lift and propel the passenger capsule without touching the tunnel walls. His Guadaloop team is also working on the same technology that received SpaceX&#39;s 2017 Innovation Award.</p><p>The Hyperloop industry has, he claimed, &quot;really seen a massive shift all to maglev (magnetic levitation)&quot; in place of air-bearing. This is due to the additional advantages that maglevs provide, such as the significantly larger &quot;air gaps&quot; between the capsule and the tube, increased levitation energy efficiency, and reduced maintenance costs. Minor air gaps in an air-bearing system experience significant wear at high speeds, and even minor debris could cause ruptures that would necessitate additional repairs or replacements.</p><p>However, the technology to make the Hyperloop a reality is available, so &quot;why does it feel like we&#39;re still so far away?&quot; stated Phillips.</p><p>Regulations</p><p>One is that since the Hyperloop is a novel technology, no laws currently govern it. &quot;Hyperloop can&#39;t scale in America because the regulations to do so safely and effectively don&#39;t even exist yet,&quot; he claimed. Additionally, because the Hyperloop impacts communities and the environment, a complicated network of state, local, county, and federal entities must coordinate their efforts to regulate it.</p><p>Therefore, while established transportation businesses lobby lawmakers in Washington, government officials have opted to pursue high-speed rail advancements rather than cope with new technology, according to Phillips. He continued that the &quot;sheer cost&quot; of developing the Hyperloop is another significant obstacle.</p><p>License:&#160;No known copyright restrictions</p><p>The Swiss Project</p><p>A nonprofit Swiss research organization called EuroTube Foundation&#39;s R&amp;D director, Lorenzo Benedetti, offers a different perspective.&#160;The government is supporting his group&#39;s efforts to construct the Hyperloop.</p><p>According to Benedetti, the Swiss government has designated EuroTube as a national facility of strategic importance.&#160;They help us create this technology because they recognize that we are approaching a tipping point when (auto and train) traffic cannot be controlled any longer, and we must offer an innovation.</p><p>Additionally, according to Benedetti, Switzerland&#39;s government owns the ground 30 meters below the surface, and &quot;they can do whatever they want,&quot; including constructing Hyperloop tunnels.</p><p>But according to him, even building the testing tunnel would be &quot;very expensive.&quot; &quot;Basically, we are in a never-ending cycle of, &#39;Should I invest more money now to develop things that we are not sure will work?&#39; That is where we are.</p><p>However, Benedetti noted that because Sw<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5d72eb54f5e5dcfcd3259a6c0992751d','transportation-technologies-m6-l7-module-5-summary','4d7ef65e39e41c85a65a51e2d5a6b996','Module 5 Summary','text',12,'<h2>Module 5 Summary</h2><section><h3>Module 5 Summary</h3><p>Module 5 Summary</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on the Hyperloop!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Defined key technological and engineering aspects of a vactrain</p><p>Examined the historical development of the vactrain concept</p><p>Debated whether Hyperloop is practical given costs and current technologies</p><p>Discussed risks of the Hyperloop system, such as system failures or susceptibility to terrorism or natural disasters such as earthquakes</p><p>Predicted when the Hyperloop or another vactrain will be operational and open to the public</p><p>Identified career opportunities in vactrain technology and educational paths to enter those careers</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2ebce1fcb7341d898f3b6fa616ee9b35','transportation-technologies-m6-l8-module-5-assignment','4d7ef65e39e41c85a65a51e2d5a6b996','Module 5 Assignment','text',12,'<h2>Module 5 Assignment</h2><section><h3>Module 5 Assignment</h3><p>Module 5 Assignment</p><p>Transportation</p><p>Hyperloop - Short Answer Assignment</p><p>Short answer assignment</p><p>Imagine that someone has proposed to build Hyperloop terminal and track in your city. You have been asked to be on the panel of decisions makers. What questions would you have for developers? What unique challenges would your city face if Hyperloop was proposed to go through it? What opportunities would it create? Finally, write an opinion/recommendation as&#160;one of the decision makers, arguing for or against the Hyperloop terminal in your city.</p><p>Type out your answers to these questions in a two-page, double-spaced document.</p><p>Review the rubric below to see how you will be graded.</p><p>Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('d1d1048696360efb55b22eff915c95cc','transportation-technologies-m6-l9-module-5-project','4d7ef65e39e41c85a65a51e2d5a6b996','Module 5 Project','text',12,'<h2>Module 5 Project</h2><section><h3>Module 5 Project</h3><p>Module 5 Project</p><p>Transportation</p><p>Hyperloop - Project</p><p>Project</p><p>In this assignment, you will create a chart to compare the pros and cons of Hyperloop and vactrain systems. You can make a T-chart, table, or any other format that clearly organizes short, detailed descriptions of the pros and cons.</p><p>After creating the chart, write a two-paragraph conclusion discussing whether you think vactrains are viable in your lifetime and if you’d like to see one developed in a city near you.</p><p>Review the rubric below to see how you will be graded.</p><p>Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Diagram</p><p>8 points The chart includes at least four valid statements in each pro and con category, and the chosen information demonstrates a strong understanding of vactrains.</p><p>7-6 points The chart includes at least three valid statements in each pro and con category, and the chosen information demonstrates an adequate understanding of vactrains.</p><p>5-0 points The chart includes less than three valid statements in each pro and con category, and the chosen information demonstrates little to no understanding of vactrains.</p><p>8</p><p>Conclusion</p><p>8 points The conclusion effectively explains the benefits and risks of vactrains and includes relevant support and explanation.</p><p>7-6 points The conclusion sufficiently explains the benefits and risks of vactrains and includes some relevant support and explanation.</p><p>5-0 points The conclusion does not effectively explain the benefits and risks of vactrains and includes little to no support and explanation.</p><p>8</p><p>Formatting</p><p>2 points Chart and conclusion are both clear and well organized.</p><p>1 point Chart and conclusion are mostly organized.</p><p>0 points Chart and conclusion are not organized.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b38841946d2154a81480f54dabab4ed6','transportation-technologies-m6-l10-module-5-quiz','4d7ef65e39e41c85a65a51e2d5a6b996','Module 5 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Hyperloop. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('9058d72c6eafa5270d58fe783479ac1f','transportation-technologies-module-7','504e3ab88df8552a07116f12aea44099','Module 7: Jetpacks',7) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a05bf15e0bdb7e15c2af4e9ebdbf2eed','transportation-technologies-m7-l1-introduction-purpose-and-objectives','9058d72c6eafa5270d58fe783479ac1f','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Is it a bird? Is it a plane? Is it a flying drone? Well, I think we can all agree that whatever it is, it&#39;s probably NOT a jetpack! And why is that? We have jets, we have backpacks... how hard is it to come up with an “everyday” jetpack?</p><p>This module will look at what a jetpack is and what separates it from other modes of transportation. Next, we will identify technological advances that have contributed to jetpacks. Then we&#39;ll look at historical and current prototypes and how those technologies worked.We&#39;ll look at the risks involved in wearing and using a jet pack, and by doing so, figure out whether or not jetpacks will ever become a regular means of transportation, or if it will simply be of the water-powered variety, used only at tourist destinations. Finally, we&#39;ll take a look at a company that is actively involved in jetpack development.</p><p>Module Description</p><p>License:&#160;All Rights Reserved</p><p>Does the idea of blasting off the ground with nothing but a mini rocket on your back thrill you?&#160;If so, then it is likely you have dreamed of using a jetpack.&#160;And you are not the first to dream of it.&#160;People have been asking for decades, “where is my jetpack?” Some big companies are asking this question as well.&#160;In late 2017, the giant company Boeing, which makes jumbo jets, offered a $2 million prize to anyone who can produce an “easy to use, personal flying device.”</p><p>This module will define what a “jetpack” is and how it differs from other forms of technology.&#160;Second, it will identify technological advances that have contributed to the emergence of jetpacks.&#160;Third, the module will look at historical creations as well as modern jetpacks and how they operate.&#160;Next we will discuss the risks and limitations associated with jetpacks.&#160;This will bring us to a discussion about whether or not jetpacks will be used as a regular means of transportation.&#160;Finally, we will examine an existing company that develops jetpacks.</p><p>Objectives</p><p>In this module, students will</p><p>Describe what a jetpack is and how it is different from existing modes of transportation</p><p>Identify technological advances that have contributed to the emergence of jetpacks</p><p>Describe historical and current prototypes and demonstrate an understanding of their underlying technologies</p><p>Discuss the risks involved in wearing and operating a jetpack</p><p>Predict whether jetpacks will be used as a regular means of transportation</p><p>Examine an existing company that develops jetpacks</p><p>Polling Question</p><p>If you had the chance, would you try using a jetpack?</p><p>Absolutely!&#160;Probably&#160;Probably Not&#160;Definitely Not!&#160;Maybe only the water jetpack</p><p>Make a selection to see the results so far.</p><p>How did your answer compare to your classmates?&#160;Let’s see how your answer changes as your learn more about the technology and risks of jetpacks!</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>a device worn over the shoulders like a backpack and enabling the wearer to travel through the air or space by means of jet propulsion which uses oxygen in the combustion process</p><p>Combustion</p><p>an engine using jet propulsion</p><p>Jetpack</p><p>rapid chemical combination of a substance with oxygen, involving the production of heat and light</p><p>Exhaust Gases</p><p>an engine that operates by the combustion of its contents, providing thrust as in a jet engine but without depending on the intake of air for combustion</p><p>Rocket</p><p>waste gases expelled from an engine, turbine, or other machine</p><p>Jet engine</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>a device worn over the shoulders like a backpack and enabling the wearer to travel through the air or space by means of jet propulsion which uses oxygen in the combustion process</p><p>Answers for question: 1</p><p>Combustion</p><p>Jetpack</p><p>Exhaust Gases</p><p>Jet engine</p><p>Rocket</p><p>2.</p><p>an engine using jet propulsion</p><p>Answers for question: 2</p><p>Jet engine</p><p>Combustion</p><p>Exhaust Gases</p><p>Rocket</p><p>Jetpack</p><p>3.</p><p>rapid chemical combination of a substance with oxygen, involving the production of heat and light</p><p>Answers for question: 3</p><p>Exhaust Gases</p><p>Jetpack</p><p>Rocket</p><p>Combustion</p><p>Jet engine</p><p>4.</p><p>an engine that operates by the combustion of its contents, providing thrust as in a jet engine but without depending on the intake of air for combustion</p><p>Answers for question: 4</p><p>Combustion</p><p>Rocket</p><p>Jet engine</p><p>Jetpack</p><p>Exhaust Gases</p><p>5.</p><p>waste gases expelled from an engine, turbine, or other machine</p><p>Answers for question: 5</p><p>Rocket</p><p>Exhaust Gases</p><p>Jetpack</p><p>Combustion</p><p>Jet engine</p><p>uses a large force of water to propel the wearer above the water</p><p>Small Rocket Lift Device</p><p>term used by the army to refer to jetpack-like devices</p><p>Hydrojet pack</p><p>a colorless, viscous, unstable liquid with strong oxidizing properties; used in rocket belt technology</p><p>Catalyst</p><p>a colorless, odorless, unreactive gas used to displace hydrogen peroxide in rocket belt technology</p><p>Hydrogen Peroxide</p><p>is a substance that increases the rate of a chemical reaction without undergoing any permanent change itself</p><p>Nitrogen</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>uses a large force of water to propel the wearer above the water</p><p>Answers for question: 1</p><p>Hydrogen Peroxide</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('dfdeb72716b9b623fc9566a192528ec6','transportation-technologies-m7-l2-lesson-1','9058d72c6eafa5270d58fe783479ac1f','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Difference between Jets &amp; Rockets Powered</h3><p>Difference between Jets &amp; Rockets Powered</p><p>While watching this video, see if you can understand the difference between how a jet is powered and how a rocket is powered.</p><p>Welcome to the Jet Pack module – video 1.</p><p>For reasons that are unclear to those of us who are afraid of heights, lots of people seem to love the idea of blasting off into the air wearing little more than a souped up backpack. Some call it a jet pack. Others call it a rocket belt or a rocket pack, but usually the idea is all the same- a device small enough to fit on the wearer&#39;s back yet strong enough to lift them 200 feet into the air by means of jet propulsion.</p><p>The ability to strap it to the wearer is a key component in separating jetpacks from other forms of futuristic personal transportation such as flying cars and hover boards. It is also a key component to why they aren&#39;t widely available or adopted. This is a point we will discuss further in the next section.</p><p>While people may use the terms jetpack or rocket pack interchangeably, the technology behind a jet and a rocket is actually quite different. A jet works by taking in air, compressing it by using a turbine, and pushing it out the back, mixing it with fuel and combusting it in the process. The air taken in is crucial because it contains oxygen which is needed for combustion.</p><p>On the other hand, a rocket carries all its fuel and oxidizer- like liquid oxygen- mixes them together and then combusts them. Rockets kind of work the same way as letting the air out of a balloon. The air goes one way at high speeds and the rocket moves in the opposite direction.</p><p>So to differentiate, for a jet, the oxygen in the air is crucial whereas the rocket has all it needs within its system. In this module we will look at both jetpacks and rocketpacks throughout history as well as current models. We will also make sure to distinguish which one we are talking about.</p><p>Maybe you&#39;ve seen some videos floating around the internet that feature people being blasted above the water with streams of water gushing behind them. These mostly recreational devices are known as hydrojet packs. A hydrojet pack is powered by a huge amount of water propelling the rider over 20 feet in the air. Because it needs so much water, there is no way a rider could carry it all. Rather, a jet ski sucks up the water and shoots it through a hose into the jetpack.</p><p>So although the rider may be “tethered,” and limited to locations with lots of water, the upside is that since hydrojet packs are usually done in the ocean or a lake, there isn&#39;t the risk of running out of propulsion material. Meaning, you get a much longer ride with a hydrojet pack than you do a “traditional” jetpack which has historically been limited to about 30 seconds. We&#39;ll explore why this is later in the course.</p></section><section><h3>How Jet Engine, Rockets &amp; Hydro Jet Pack Work</h3><p>How Jet Engine, Rockets &amp; Hydro Jet Pack Work</p><p>For anyone that has ever had a dream they could fly, you know the exhilaration that comes from realizing 1.&#160;You aren&#39;t plummeting to your death and 2.&#160;That flying is&#160;awesome!&#160;Now imagine if you did not have to be asleep to fly but could do it anytime and anywhere you wanted.</p><p>That&#39;s the fantasy behind jetpacks.&#160;A jetpack is a device worn like a backpack that enables the wearer to travel through the air by using jet propulsion.&#160;Press the tabs below to learn about jet engines, rockets, and hydrojet packs.</p><p>Jet Engines</p><p>To get an idea of how a jetpack works, let&#39;s first look at how a jet engine works.&#160;A jet engine converts high-energy liquid fuel into a powerful thrust or powerful force.&#160;It uses a chemical reaction called combustion in which it burns fuel with oxygen in the air to release an energy that powers the jet, or in this case, the jetpack.</p><p>The terms rocket pack or rocket belt are often used interchangeably with jetpack.&#160;Obviously, jets and rockets are not the same things, so technically speaking, a rocket pack/ rocket belt is not the same thing as a jetpack.</p><p>Rockets</p><p>To find out what makes a jetpack different from a rocket pack, let&#39;s find out how a rocket works. For a rocket to work, exhaust gases (gases emitted from the combustion of fuels) come out of the engine nozzle at high speeds. This pushes the rocket upward.</p><p>So far a jet engine and a rocket engine are not too crucially different from one another. The main difference is that jets intake oxygen from the air to burn fuel. Rockets carry their own oxygen. That is why rockets, but not jets, can travel into space. A rocket carries the oxygen with it, so that even if there is no oxygen- like in outer space- the rocket can still work.</p><p>Throughout this module, we will look at both jetpacks and rocket packs since the overall idea is the same. Both aim to provide a way for users to strap a device on their bodies to fly through the air. This is different from other futurist transportation ideas such as hoverboards or flying cars, both of which require a device you ride in or on.</p><p>Hydrojet Pack</p><p>Sitting somewhere in the middle between jetpacks and other forms of transportation is a hydrojet pack. These recreational devices have become increasingly popular over the past five years or so. Hydrojet packs are powered by water. A forceful amount of water shoots out the bottom of the rider&#39;s pack propelling the rider over 20 feet in the air.</p><p>A force that strong requires a great deal of water. More water than a person could carry in a pack. Instead, a jet ski or similar device sucks up the water through a hose. The hose shoots the water into the pack which lifts the rider high above the water.</p><p>So even though the rider is tethered by the hose, the ride can go on for quite a while since the rides are usually in an ocean or lake which has a nearly endless supply of water for the activity. And people love it!</p><p>Next Tab</p><p>A video showing someone using a Jetpack and how it works.</p><p>Video Title:&#160;WATER JETPACK</p><p>Video Publisher:&#160;haakvanhaaften</p><p>License:&#160;Creative Commons Attribution license (reuse allowed)</p><p>Note:&#160;There are no closed captions for this video.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('93b7a44d98c3c9f48c6cc322a4fbcb58','transportation-technologies-m7-l3-lesson-2','9058d72c6eafa5270d58fe783479ac1f','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>How Jetpacks Wear Work</h3><p>How Jetpacks Wear Work</p><p>While watching this video, try to identify the two alternative types of fuel used for jetpacks.</p><p>Welcome back, this is video 2 of the Jet pack module.</p><p>Corsets, overalls, belts... Now there&#39;s three words I never thought I&#39;d use in the same sentence! What am I talking about? Jetpack wear, of course! Each one- corsets, overalls, and belts- have been used to keep a jetpack on a rider.</p><p>Although for most of us, the idea of a jetpack is mostly just a fun way to envision getting around, the US army had serious interest in a jetpack&#39;s potential in the late 1950s. They began examining companies that could provide a “Small Rocket Lift Device.” They hired Bell Aerosystems and lead engineer, Wendell Moore, who developed the Bell Rocket Belt which ran on hydrogen peroxide.</p><p>However, 5 gallons of hydrogen peroxide fuel for only 20 seconds of flight time meant that the Bell Rocket Belt was of little use to the army. On top of that, there was no “plan B” if the system started to fail during flight because it flew too low for a parachute to deploy. Further development was canceled.</p><p>Nevertheless, all existing rocket packs since then have been based on Bell Rocket Belt design. In the original system, the wearer is strapped to a rigid glass-plastic corset which distributes the weight of pack on his back. The corset has a tubular frame with three cylinders fixed to it. Two of the cylinders contain liquid hydrogen peroxide and the other compressed nitrogen.</p><p>The rocket engine is in the top part of the corset. The engine consists of a gas generator and two pipes which end with jet nozzles.</p><p>Stay with me here, this is going to get complicated and chemistry-y, but it’s important to know the details of how it work. First, compressed nitrogen displaces the liquid hydrogen peroxide which is piped to the gas generator. In the generator it reaches a catalyst- or substance that increases the rate of a chemical reaction. In this case, the catalyst is silver plates covered with a thin layer of samarium nitrate. So once it contracts the catalyst, it decomposes. The result is a mix of steam and oxygen gas. The hot gases travels through insulated pipes and into the jet nozzles. Here the gases are first constricted and then allowed to expand. This accelerates them to supersonic speed and generates thrust, or force.</p><p>Since the exhaust jet and the pipes are very hot, the pilot wears thermal resistant overalls. The device also makes a shrill, screeching sound, so better throw on some hearing protection as well.</p><p>Like I said, this- the hydrogen peroxide system- was the foundational technology for all future rocket belt systems. Others have been made, most for entertainment purposes like in the James Bond movie Thunderball, which features Sean Connery wearing a Bell Rocket Belt in a scene.</p><p>But there&#39;s one particular edition of the Rocket Belt that deserves a little more attention. In the 1990s, Brad Barker, Joe Wright, and Larry Stanley joined forces with inventor Doug Malewicki to develop a new rocket pack. Called the RB 2000, the rocket belt used the same design as Bell&#39;s except the actual construction of it used titanium, aluminum, and composite materials. They were able to increase flight time to 30 seconds.</p><p>The RB 2000 was flown on June 12 1995... this is where things start to sound straight out of a mystery thriller. Stanley accused Barker of fraud. Barker took the RB 2000 to an unknown location. The next year, Stanley successfully sued Barker and demanded he return the rocket belt and pay up to 10 million dollars in costs and damages. And it only gets worse from here. Barker refused to deliver, so Stanley kidnapped him and held him captive in a box. Baker escaped after eight days! Stanley was convicted of kidnapping and sentenced to 8 years in prison. The rocket belt never was recovered.</p><p>As we discussed in the previous model, both jet engines and rocket engines have served as the technological basis for flying packs. Throughout the years, there have also been successful (successful in the sense that they didn&#39;t blow up or anything) models that used jet engines.</p><p>Packs with a turbojet engine are filled with kerosene-based jet fuel. They are more efficiency, have longer flight times, and fly higher. However, they are more complex and expensive to design. However, there are a few current, noteworthy designs which we&#39;ll get to in the next section.</p></section><section><h3>Needed Components of Jetpacks to Work</h3><p>Needed Components of Jetpacks to Work</p><p>Bell Rocket Belt No.2 and suit housed inside the National Air and Space Museum&#39;s Steven F. Udvar-Hazy Center.&#160;Photographed August 15, 2007 in Chantilly, Virginia.</p><p>License:&#160;All Rights Reserved</p><p>We can access a near-infinite amount of information on a device we carry around in our pockets.&#160;We use that same device to connect to people halfway around the world.&#160;We have medicine that has nearly wiped out diseases that were killing us mere decades ago.&#160;Despite all these amazing advances, or perhaps because of them, people still ask, “Where&#39;s my jetpack?” If we can do all those things listed above, why can&#39;t we strap ourselves to a device and fly anywhere we want, any time we want?</p><p>Small Rocket Lift Devices</p><p>A lot of the development in the jetpack or rocket belt technology has happened because of the US Army&#39;s interest in the technology.&#160;Although their interest in “Small Rocket Lift Devices” (SRLD)&#160;has been less about getting out of traffic jams and more about things like overcoming minefields, reconnaissance, and crossing rivers.&#160;In the 1960s, the army began working with Wendell Moore of Bell Aerosystems to create an SRLD.&#160;Moore created the Bell Rocket Belt.</p><p>Let&#39;s examine SRLDs a little more.&#160;Expand the sections below to identify the components of SRLDs.</p><p>Rocket Motor</p><p>The rocket motor is the heart of a small rocket lift device. It consists of a combustion chamber and a nozzle. The combustion chamber ignites a propellant, such as solid or liquid fuel, generating high-pressure gases. These gases are expelled through the nozzle, producing thrust to lift the device off the ground.</p><p>Payload Compartment</p><p>The payload compartment is the section of the rocket lift device that houses the payl<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8c6989304da4e55ec4767817ff065b88','transportation-technologies-m7-l4-lesson-3','9058d72c6eafa5270d58fe783479ac1f','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Past &amp; Current Development of Jetpacks</h3><p>Past &amp; Current Development of Jetpacks</p><p>While watching this video,&#160;look for modern developments that have led to further advances with the jetpack.</p><p>Welcome back, this is video 3 of the Jet pack module.You know when you&#39;re flying around and someone makes a comment about your jetpack... ok, so most of us have never worn a jetpack in our lives, but that doesn&#39;t mean they are not around. They&#39;re just mostly used in the entertainment setting- movies, sporting events... even the opening ceremonies of the 1984 Olympics. They also find their use in outer space, helping astronauts return to their space craft in the event that they become untethered. And progress toward better and better models presses on in this millenium.In 2006, Yves Rossy, a Swiss pilot invented a kerosene-burning jetpack with wings. He has flown over the Swiss Alps, across the English Channel, and crashed into the Straight of Gibralter (and lived to tell the tale!). The jet pack uses four small jet engines. Since the jet engines produce exhaust, Rossy uses a thermal resistant suit similar to the ones firefighters and race car drivers wear.What&#39;s particularly cool about Yves Rossy is that he claims to be &quot;the first person to gain altitude and maintain a stable horizontal flight thanks to aerodynamic carbon foldable wings.&quot; Those wings fold by hinges at the midpoint.Here&#39;s how a typical flight works for him: First Rossy rides to a predetermined height in an airplane. Then just before jumping out of the plane, he ignites the engines using an electronic starter so that all 4 start at the same time. The wings are still folded at this point. The wings open during his free-fall which lets him fly horizontally for several minutes. He deploys a parachute to help him land.In November of 2015, JetPack Aviation&#39;s CEO David Mayman flew around the Statue of Liberty (she remained as unimpressed as ever...) in the JB-10. This is truly a modern jetpack. In addition to two modified jet turbine engines, there are also many sensors. Gyroscopes and an accelerometer monitor the pack hundreds of times per second. The report back to the electronic controls which monitor thrust. A lot of the work is done by these sensors and technology as opposed to being done by the pilot.Mayman cites the development of the smartphone as being crucial to the development of their jetpack. Sensor like accelerometers used to cost thousands of dollars. Now, thanks to the development of smartphones which also use sensors like accelerometers, they are available for 10 cents.Another advancement that makes jetpacks today more efficient than ever before is the development of small but powerful engines. Until recently, flight time was limited to a minute or so. In contrast, the JB-10 can fly for nearly 10 minutes.One of the really cool features of this modern jetpack is that just about anyone can learn to use it. It only takes about 3 hours of training. Compared to about 150 hours of training it takes to learn to fly a helicopter, 3 hour is nothing.If you&#39;re thinking about buying one, well, it&#39;ll set you back about $250,000. Though similar to most new technologies and hardware, the cost may come down over time.Another more contemporary jetpack is the Martin Jetpack which reaches 5000 feet in altitude using a V-4 gas engine and 2 duct fans. We will look a little more closely at this jetpack system in the final section of this module.</p></section><section><h3>Jetpack Development over the Years</h3><p>Jetpack Development over the Years</p><p>If your heart is set on wearing a jetpack in this lifetime, you may be in luck.&#160;There are still engineers and inventors working to improve jetpack technology.</p><p>Inventor Yves Rossy</p><p>In the 2000’s, a Swiss pilot name Yves Rossy has flown his incredible jetpack with wings over the English Channel, over the Swiss Alps, and attempted to cross the Straight of Gibraltar with it, but had to make a crash landing into the water.&#160;(He was fine.) He even flew over Dubai.&#160;Check out the video below to see his flight.</p><p>A video showing someone using a Jetpack to fly over the city of Dubai.</p><p>Video Title:&#160;JetmanOver Dubai</p><p>Video Publisher:&#160;Auden Cabello</p><p>License:&#160;Creative Commons Attribution license (reuse allowed)</p><p>Note:&#160;There are no closed captions for this video.</p><p>His personal flying device&#160;uses four small jet engines.&#160;Being able to fit four small jet engines on a wearable pack is a technological advancement that has made modern jetpacks more efficient.&#160; With so much hot exhaust coming from four jet engines, Rossy wears a thermal resistant suit, similar to what a racecar driver would wear.</p><p>One of the amazing things about Rossy&#39;s flights is how he is able to fly horizontally.&#160;To do this, first, he rides in an airplane up to the necessary altitude.&#160;As he prepares to jump out of the plane, he ignites the jet engines using an electronic starter.&#160;The starter enables all four engines to start at the same time.</p><p>After which, he immediately jumps out of the plane with the wings still folded at a hinge in the middle.&#160;The wings open during his free-fall.&#160;The aerodynamic wings help him fly horizontally for several minutes.&#160; A parachute helps him land once his kerosene-based fuel gets low.</p><p>JB-11 Jetpack</p><p>If you have $340,000 and you are unsure how to spend it, you are in luck!&#160;That is the cost of the JB-11, a jetpack developed by JetPack Aviation.&#160;If that&#39;s a little out of your price range (or a lot!) don&#39;t despair- you can still take jetpack pilot lessons and learn to fly one in about three hours.</p><p>The JB-11 is truly a modern creation.&#160;It uses sensors like gyroscopes and accelerometers to monitor the wearer&#39;s flight.&#160;Being able to use these sensors is in many ways due to smartphone development.&#160;With the development of the smartphone, such sensors went from thousands of dollars to mere cents in costs.&#160;Such sensors allow technology to do much of the monitoring that, in the past, had to be done by the pilot.</p><p>A video showing a demonstration of the JB10 Turbojet Jetpack.</p><p>Video Title:&#160;JetPack Aviation - JB10 Turbojet JetPack Flight Demonstration</p><p>Video Publisher:&#160;Military Archive</p><p>License:&#160;Creative Commons Attribut<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e61cd8e75b9e01dc99b3d3014f592bce','transportation-technologies-m7-l5-lesson-4','9058d72c6eafa5270d58fe783479ac1f','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Risk &amp; Limitations with Jetpacks</h3><p>Risk &amp; Limitations with Jetpacks</p><p>While watching this video, think about whether or not the risks and limitations of jetpacks and rocket belts make the technology worth pursuing.</p><p>Welcome back, this is video 4 of the Jet pack module.</p><p>Why don&#39;t we all fly jetpacks to work or to school? Is it the heavy price tag? In this module we are going to look at some of the risks and limitations associated with jetpacks and rocketbelts.</p><p>First, let&#39;s start with the image of having a small rocket strapped to your back, complete with pillars of fire streaming as you take off (Stock photo of illustrated jet pack with fire coming out the back). Think about that- pillars of fire right by your legs! Not only is that a fire hazard to anything flammable around you, you would have to wear extremely protective (and likely expensive) clothing every single time you flew.</p><p>Do you have to put on special clothing to ride in the car or on an airplane? No.</p><p>Another problem with rocket belts is that you have to carry all of your own fuel. And the amount of fuel we can carry is only enough to last for a few seconds. Basically enough time to blast up into the air, wave “hi mom!” and look for a spot to land.</p><p>Loading more fuel means a heavier pack which then is too heavy to overcome the pull of gravity. So you can forget having a backup supply for emergencies.</p><p>Jetpacks too are limited by gravity. Although they have longer flight times, the amount of time a jetpack can fly is still limited by the fact that it takes a great deal of energy to go upward. That energy comes from fuel. And just like with a rocket belt, the more fuel you add, the heavier it gets and the more fuel you need to move it, and it turns into a vicious cycle.</p><p>Which means there is a limited sweet spot where the jetpacks are light enough to be worn and provide upward thrust, but also provide sufficient fuel. A limited sweet spot means a limited flight time which essentially means a limited flight distance.</p><p>As we mentioned before, jetpacks are pricey. Most are far more expensive than a car. They typically run from $70,000 to $250,000.You might be wondering how safe a jetpack is. Perhaps surprisingly, there have been no recorded deaths from jetpacks. But that&#39;s mostly because hardly anyone has ever flown a jetpack and those who have, were highly monitored and/or experienced.</p><p>It&#39;s no secret that humans are lousy car drivers. We are easily distracted and make bad decisions. And that&#39;s just going forward and backward. Think about how potentially more difficult and dangerous it would be to have people trying to maneuver not just forward and back, but now having 360 degrees to monitor. It could potentially be a dangerous mess.</p><p>Furthermore, if you are driving and your fuel gauge malfunctions causing your car to run out of gas unexpectedly, most of the time you can pull over and deal with the inconvenience. However, if your jetpack unexpectedly runs out of fuel, well, it means you are now plummeting to the ground with rather unpleasant consequences for you and anyone who happens to be right below you.</p><p>Even if the physics of jetpack flight were somehow overcome, the prices lowered, and the safety figured out, there&#39;s still a whole lot to figure out in the sky. Like speed limits, right of way, lanes, etc. Once you add drones and flying cars to the mix – the sky can get complicated pretty quickly. Those things may seem like an inconvenience, but they are a necessary one if transportation is to have any sort of order. Developing infrastructure in the sky would not happen overnight, just like it didn&#39;t happen overnight for roads.</p><p>Despite all these obstacles, there are still companies that remain optimistic that jetpacks could become a daily reality. We will investigate one of these companies next.</p></section><section><h3>Rocket Belt &amp; Jetpack Limitations</h3><p>Rocket Belt &amp; Jetpack Limitations</p><p>We have touched on a few of the limitations to jetpack technology in previous sections, but now we are going to get down to the nitty gritty.&#160;What is the problem with jetpacks and rocket belts?&#160;Why don&#39;t we all have one?</p><p>Rocketbelt Limitations</p><p>Let us look first at the rocket belt.&#160;Like we mentioned before, rocket belts have not changed much over the past few decades.&#160;Their flight time is still limited to under a minute, fuel still remains expensive, and they still do not fly high enough to have a back-up parachute.</p><p>The problem with rocket belts can really be summed up in two points.</p><p>Humans are not meant to fly.&#160;Nothing about our bodies is aerodynamic.&#160;Our bodies are essentially useless weight once we get up to the sky.&#160;Weight that must somehow be lifted off the ground.</p><p>Gravity is always (literally) pulling us down.&#160;Because rocket belts require the pilot to carry all the necessary fuel, the pack cannot be too heavy.&#160;If it&#39;s too heavy, even more fuel is needed to overcome gravity.&#160;More fuel means a heavier pack.&#160;Heavier packs need more fuel.</p><p>It&#39;s a vicious cycle.&#160; One that leaves rocket belts at a flight time of less than a minute.&#160;Spending money on a device that only gets you thirty seconds of travel time is unpractical.&#160;This is why rocket belts have been largely limited to theatrical presentations.</p><p>(opens in a new tab)</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Jetpack Limitations</p><p>Jetpacks, although more efficient, have their limitations as well.&#160;They still burn up quite a bit of fuel to get lift.&#160;More fuel burned means more money.&#160;This makes them expensive and thereby impractical for the majority of people.</p><p>Safety is another issue with personal flying devices is the additional awareness required to navigate.&#160;In a car, a driver must be aware of what is going on behind, in front, and on either side of him.&#160;What is going on above or below is rarely a concern.&#160;In the sky, however, there are all sides and angles to be aware of and monitor.&#160;This translates to more potential dangers.</p><p>Another safety issue what happens in the event of a malfunction.&#160;Because jetpacks are used mostly in highly controlled and monitored situations, there have not been too many disasters involving jetpacks.&#160;Howe<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7faf501cf00f1ae7971b9e701c22449b','transportation-technologies-m7-l6-lesson-5','9058d72c6eafa5270d58fe783479ac1f','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Martin Jetpack Life Saving Potential</h3><p>Martin Jetpack Life Saving Potential</p><p>While watching this video,&#160;see if you can figure out why Martin Jetpack views their technology as capable of saving lives.</p><p>Welcome back, this is video 5 of the Jet pack module.</p><p>If you are wondering where you can find these jetpack dreamers, look no further than Martin Jetpack.</p><p>The Martin Jetpack is considered an Optionally Piloted Hovering Air Vehicles or OPHAVs. This means it can fly both manned or unmanned.</p><p>The company is particularly interested in promoting what they claim to be the jetpack&#39;s life-saving potential. Because it is relatively small compared to a helicopter or airplane, it can be deployed from a truck or trailer, thereby saving time between the call and arrival of air support. Some of the other proposed life-saving uses include: supply delivery, rapid deployment of specialist teams and equipment, and surveillance.</p><p>Currently, the jetpack uses automotive fuel. The engine drives twin-ducted fans to produce a vertical takeoff and landing. The company is pursuing other types of fuel as well.</p><p>The jetpack is also designed with the user in mind. Because of its patented technology, it does not require the use of blades unlike other personal vertical takeoff and landing vehicles.</p><p>If you&#39;re worried about safety, they&#39;ve got you covered there as well. Some of the safety features include a ballistic parachute, impact absorbing undercarriage, covered rotors, hands free stability, and even a roll cage, just to name a few. Depending on the type of flight, it can run for up to 30 minutes and fly up to 2,500 feet.In addition to life saving uses, the Martin Jetpack aims to be of commercial value as well. The company is looking to make a more cost-effective technology for situations that typically require a helicopter. Some of the roles where their jetpack could potentially be of use include: pipeline and powerline inspection maritime (meaning things having to do with boats) operations superstructure inspections like communication towers aerial filming and scanning logistical support</p><p>If you&#39;re hoping to own your own soon... I hate to be a dream killer, but according to their website, the Martin Jetpack for the private/recreation market will be limited to already qualified pilots sometime around 2020.</p><p>Not to worry, not all hope is lost. They estimate that by 2030, the regulations will be in place to allow personal jetpacks.</p><p>I hope you’ve enjoyed this somewhat off the wall module on jetpacks. For some of you, jetpacks represent the ultimate manifestation in personal mobility, while others may think it’s just plain crazy. Either way, it’s a technology definitely worth keeping your eyes on!</p></section><section><h3>Use cases of Jetpacks</h3><p>Use cases of Jetpacks</p><p>Martin Aircraft Company</p><p>Located in New Zealand, the Martin Aircraft Company is one of the world leaders in jetpack development.&#160;Although it started quite humbly in the garage of Glen Martin in 1981, by 2010, The Martin Jetpack had been named one of Time Magazine&#39;s top 50 inventions.</p><p>Watch a few minutes of the video below (or the whole thing if you want to!) to see five jetpacks in action.</p><p>Video Title:&#160;5 Amazing Personal Aircraft | Human Flight Machine ▶ 5</p><p>Video Publisher:&#160;TopTechTopic</p><p>License:&#160;Creative Commons Attribution license (reuse allowed)</p><p>Note:&#160;There are no closed captions for this video.</p><p>At that point, first responders began showing interest in the product and the company began to realize the life-saving potential the jetpack had.</p><p>Life-Saving Potential</p><p>Some of the ways the company feels the Martin Jetpack can be used to save lives include:</p><p>Accessing difficult to reach places</p><p>Being loaded onto a truck or trailer; thereby eliminating the time required to call in and wait for air support to arrive on the scene.</p><p>Supply delivery</p><p>Reconnaissance (in other words, scoping things out ahead of time)</p><p>Although to look at The Martin Jetpack, you may wonder if they are pushing the limit of what is actually considered a “jetpack” a bit.&#160;The device is made not so much with a backpack style, but rather something meant to be stepped into.&#160;It features a roll cage and a shock absorbent undercarriage.&#160;Features one typically does not associate with jetpacks but nevertheless have usefulness for the device.</p><p>The Martin Jetpack is designed to be both safest and lightest aircraft.&#160;It is made of lightweight composite material and uses automotive fuel for lift.&#160;Automotive fuel, although available in most parts of the world, it is neither clean nor renewable.&#160;The company is, however, pursuing other forms of fuel.</p><p>Additional Uses</p><p>Although the company seems particularly enthusiastic about the life-saving potential of the jetpack, the company also proposes some other uses for it.</p><p>For the Martin Aircraft Company, they feel the biggest limitation to making the Martin Jetpack available for personal use is not the technology, but rather the regulations required to make it (and other flying and/or autonomous vehicles) part of society.</p><p>Whether or not jetpacks will ever become a regular part of transportation is debatable.&#160;But whether or not you believe in the potential of jetpacks, you have to applaud the visionaries who see beyond what is happening today and, instead, look to what could be in the future.</p><p>Expand the items in the list below to learn more about how jetpacks could be used.</p><p>Search and Rescue Operations</p><p>Jetpacks can be invaluable in search and rescue operations, allowing first responders to quickly reach remote or inaccessible areas. Their ability to maneuver in challenging terrain, such as mountains or dense forests, enables rapid response and potentially saves lives.</p><p>Aerial Inspections and Maintenance</p><p>Jetpacks can facilitate aerial inspections of tall structures, such as power lines, wind turbines, or skyscrapers. Technicians equipped with jetpacks can easily access and assess these structures, identifying maintenance needs and performing repairs efficiently.</p><p>Emergency Medical Services</p><p>Jetpacks have the potential to revolutionize emergency medical services by providing rapid transport for medical professionals. In critical situations, such as<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c7e9a654ac898046b7f5cc7431158a86','transportation-technologies-m7-l7-module-7-summary','9058d72c6eafa5270d58fe783479ac1f','Module 7 Summary','text',12,'<h2>Module 7 Summary</h2><section><h3>Module 7 Summary</h3><p>Module 7 Summary</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Jetpacks!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Described what a jetpack is and how it is different from existing modes of transportation</p><p>Identified technological advances that have contributed to the emergence of jetpacks</p><p>Described historical and current prototypes and demonstrate an understanding of their underlying technologies</p><p>Discussed the risks involved in wearing and operating a jetpack</p><p>Predicted whether jetpacks will be used as a regular means of transportation</p><p>Examined an existing company that develops jetpacks</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5b6a195ceb8d53c76ae05a3343e7c1c2','transportation-technologies-m7-l8-module-7-assignment','9058d72c6eafa5270d58fe783479ac1f','Module 7 Assignment','text',12,'<h2>Module 7 Assignment</h2><section><h3>Module 7 Assignment</h3><p>Module 7 Assignment</p><p>Transportation</p><p>Jetpacks - Short Answer Assignment</p><p>Short answer assignment</p><p>For this writing assignment, choose&#160;one&#160;of the two short answer prompts below and write a two-page, double spaced paper addressing the questions/topics listed.</p><p>1.&#160;Concept Review:&#160;Based on what you have learned in this module,&#160;combined with additional outside sources, predict whether or not jetpacks will ever be used as a regular means of transportation. For this assignment, gather relevant information from multiple digital sources, assess the credibility and accuracy of each source, and integrate the information while avoiding plagiarism.</p><p>Write a two-page double space paper that states your prediction and your reasons and justification for&#160;that prediction based on what we have learned in this module.</p><p>2.&#160;Book, Movie, or TV review:&#160;With the approval of a parent or guardian, find a book, movie, or TV show to read or watch, which features a&#160;Jetpack. Some ideas are The Rocketeer (1991) or BobaFett&#39;s use of a jetpack in the original Star Wars trilogy&#160;and answer the following questions:</p><p>How is the jetpack being used?</p><p>Is the jetpack&#160;portrayed positively or negatively?</p><p>What risks or malfunctions occur while the rider is using the jetpack?</p><p>What technologies are mentioned or used with the jetpack? If none are specifically mentioned, what technologies do you think are used (or are implied)?</p><p>Review the rubric below to see how you will be graded.</p><p>Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('69ed178aea184f264f04ab3089f403e7','transportation-technologies-m7-l9-module-7-project','9058d72c6eafa5270d58fe783479ac1f','Module 7 Project','text',12,'<h2>Module 7 Project</h2><section><h3>Module 7 Project</h3><p>Module 7 Project</p><p>Transportation</p><p>Jetpacks - Project</p><p>Project</p><p>In this assignment, you will create a television commercial for a jet pack. Imagine you work for a company that is developing jet packs and they are ready to be put on the market. Select one type of jet pack and use what you’ve learned to imagine the details of your product, then persuade your target audience that it’s worth the investment! You can use video or a presentation software (such as PowerPoint or Prezi) to create the commercial. Be sure to cite any resources for images and other content as needed.</p><p>Your commercial should:</p><p>be aimed at a specific target audience</p><p>fit in a 30-60 second time slot</p><p>describe the features of the product</p><p>highlight the technology used in the jetpack</p><p>persuade the audience about the appeal of the product</p><p>address common concerns consumers might have</p><p>be creative, engaging, and appropriate for a TV audience</p><p>Review the rubric below to see how you will be graded.</p><p>Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Content</p><p>8 points The commercial demonstrates a strong understanding of the features and technologies of the chosen type of jet pack. It contains several specific and accurate details.</p><p>7-6 points The commercial demonstrates a satisfactory understanding of the features and technologies of the chosen type of jet pack. It contains some specific and accurate details.</p><p>5-0 points The commercial demonstrates little to no understanding of the features and technologies of the chosen type of jet pack. It contains few to no specific and accurate details.</p><p>8</p><p>Persuasive</p><p>6 points The commercial successfully explains the benefits of the product and is effectively aimed at a target audience.</p><p>5 points The commercial adequately explains the benefits of the product and is sufficiently aimed at a target audience.</p><p>4-0 points The commercial does not adequately explain the benefits of the product and is not effectively aimed at a target audience.</p><p>6</p><p>Presentation</p><p>2 points The commercial is clear, organized, and presented well.</p><p>1 point The commercial is somewhat clear and organized and the presentation is adequate.</p><p>0 points The commercial is not clear and organized or is not presented well.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors and fits into the time specifications. All resources are cited as needed.</p><p>1 point Contains several spelling or grammar errors or does not fit into the time specifications. Resources are cited as needed.</p><p>0 points Contains numerous spelling or grammar errors and does not fit into the time specifications, or resources are not cited where needed.</p><p>2</p><p>Visual Appeal</p><p>2 points Uses appropriate visuals in an engaging way.</p><p>1 point Uses appropriate visuals in a satisfactory way.</p><p>0 points Uses inappropriate visuals.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a2d1d2eafe5fdcce629c5c503f8a81e5','transportation-technologies-m7-l10-module-7-quiz','9058d72c6eafa5270d58fe783479ac1f','Module 7 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Jetpacks. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('4cfc925ac5024671aaba2a5fc275edbf','transportation-technologies-module-8','504e3ab88df8552a07116f12aea44099','Module 8: Supersonic Jets',8) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('401568cbdf324dd1c554250ff0e801cc','transportation-technologies-m8-l1-introduction-purpose-and-objectives','4cfc925ac5024671aaba2a5fc275edbf','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi and welcome to this module on Supersonic Jets.</p><p>The Concorde arrived on the heels of the “golden quarter century” in 1976. Technology was advancing at a breathtaking pace. Seemingly suddenly, there were jet planes, spaceships, computers, nuclear power, and on and on. It seemed almost a natural progression that by 1976, people were traveling faster than the speed of sound on a regular basis. So why, over 40 years later, are we actually flying slower? What happened to the Concorde? What happened to supersonic travel?</p><p>And more importantly, is it ever going to make a comeback? Today, there are engineers and scientists working out the kinks of previous models to present new and improved methods of flying faster than a speeding bullet. Let’s take a look, and see if any of their plans will actually work!</p><p>Module Description</p><p>License:&#160;All Rights Reserved</p><p>When the Concorde was retired in 2003 with no successor, it left some people scratching their heads wondering what went wrong.&#160;Was it the crash of 2000?&#160;Was it the cost?&#160;Was it the boom?&#160;Or was it something else?&#160;Why did we fly faster than the speed of sound for 30 years and then...&#160;slow down?</p><p>This module will look at supersonic travel technology.&#160;It will examine how supersonic jets differ from traditional jet liners.&#160;Then the module will explain the “sonic boom” phenomenon.&#160;With this foundation, the module will then look at the technology, costs, operations, and demise of the Concorde.&#160;Next it will examine the pros and cons of supersonic jets in general and whether or not it is realistic to expect supersonic intercontinental flights.&#160;Finally, the module concludes with a look at companies developing supersonic jets as well as career opportunities within the aerospace industry.</p><p>Advantages of Supersonic Jets</p><p>More passengers are transported on international flights daily by a modern supersonic commercial aircraft than by a commercial subsonic airliner.&#160;For instance:&#160;A subsonic plane travels at 550 mph, and a supersonic Mach 3.4 aircraft travels at 2,580 mph.&#160;On a flight, 3,250 miles separate New York from London.&#160;With a takeoff speed of 250 mph and a climb speed of 125 miles per hour for 25 minutes in New York, 20 minutes of taxi time, and an average speed of 500 mph across a distance of 500 miles, it takes 2 hours and 5 minutes to land subsonic in London.&#160;Supersonic flight at 2,580 mph covers 2,625 miles in one hour and two minutes.&#160;As a result, the entire flight would take just over three hours from gate to gate!</p><p>Objectives</p><p>In this course, students will</p><p>Define key technological terms related to supersonic jets and airplane flight</p><p>Differentiate between supersonic jets and regular jet airliners</p><p>Summarize the Concorde supersonic jet program, including its technology, cost, operations, and shortcomings</p><p>Discuss the noise problem of a sonic boom created by supersonic jets</p><p>Identify both pros and cons of supersonic jets, including safety considerations</p><p>Predict when supersonic jets will be used regularly for intercontinental flight</p><p>Examine an existing company that is developing supersonic jets</p><p>Identify career opportunities in aerospace and educational paths to enter those careers</p><p>Polling Question</p><p>What impact do you think commercial supersonic flight would have on society?</p><p>More people would fly because of the faster travel time&#160;It would improve the travel of business class/elite only&#160;No one would be interested&#160;Unsure</p><p>Make a selection to see the results so far.</p><p>How did your prediction compare to your classmates?&#160;Let’s see how your answer changes as your learn more about the technology and risks of jetpacks!</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>slower than the speed of sound</p><p>Hypersonic Speed</p><p>flight at or about the speed of sound</p><p>Afterburner</p><p>faster than the speed of sound and up to Mach 5</p><p>Supersonic Speed</p><p>faster than Mach 5</p><p>Transonic Flight</p><p>the ratio of the speed of an object to the speed of sound</p><p>Subsonic Speed</p><p>an auxiliary burner fitted to the exhaust system of a turbojet engine to increase thrust</p><p>Mach Number</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>slower than the speed of sound</p><p>Answers for question: 1</p><p>Supersonic Speed</p><p>Mach Number</p><p>Subsonic Speed</p><p>Hypersonic Speed</p><p>Afterburner</p><p>Transonic Flight</p><p>2.</p><p>flight at or about the speed of sound</p><p>Answers for question: 2</p><p>Hypersonic Speed</p><p>Mach Number</p><p>Transonic Flight</p><p>Subsonic Speed</p><p>Afterburner</p><p>Supersonic Speed</p><p>3.</p><p>faster than the speed of sound and up to Mach 5</p><p>Answers for question: 3</p><p>Mach Number</p><p>Transonic Flight</p><p>Supersonic Speed</p><p>Afterburner</p><p>Subsonic Speed</p><p>Hypersonic Speed</p><p>4.</p><p>faster than Mach 5</p><p>Answers for question: 4</p><p>Mach Number</p><p>Transonic Flight</p><p>Hypersonic Speed</p><p>Afterburner</p><p>Supersonic Speed</p><p>Subsonic Speed</p><p>5.</p><p>the ratio of the speed of an object to the speed of sound</p><p>Answers for question: 5</p><p>Supersonic Speed</p><p>Afterburner</p><p>Hypersonic Speed</p><p>Mach Number</p><p>Subsonic Speed</p><p>Transonic Flight</p><p>6.</p><p>an auxiliary burner fitted to the exhaust system of a turbojet engine to increase thrust</p><p>Answers for question: 6</p><p>Transonic Flight</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1681b7d1cc438f43b4a388eba7400a1f','transportation-technologies-m8-l2-lesson-1','4cfc925ac5024671aaba2a5fc275edbf','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Science of Speed and Sound</h3><p>Science of Speed and Sound</p><p>While watching this video, pay attention to the relationship between Mach numbers and the speed of sound.</p><p>Welcome back, this is video one for the module on Supersonic Jets.</p><p>Thinking about technology 40 years ago, few of us would trade what we have now for what they had back then. Who would trade in their smartphone for a corded phone? Or the smartphone in your pocket for a massive, antenna-sporting boom box? So isn&#39;t it a little strange that, in terms of international flight, not only are we&#160;not&#160;going any faster, we have actually slowed down? Commercial passengers no longer fly at supersonic speed.</p><p>Let’s step back and talk about the science of speed and sound. To quickly review a principle from elementary-level science, sound is caused when an object vibrates (like a guitar string). This vibration causes air molecules to respond, creating a wave of sound. The speed of this wave, or the speed of sound, is about 768 miles per hour. This speed is referred to by Mach numbers. A mach number is the ratio of the speed of an object to the speed of sound. Anything faster than Mach 1 and up to five times faster than the speed of sound, or Mach 5, is considered supersonic.</p><p>To put this into perspective as to just how fast it is to fly at supersonic speed, a bullet fired from a gun flies at supersonic speeds.</p><p>Supersonic is one of the four speeds of flight. These four speeds are referred to as the regimes of flight. They are:</p><p>First, Subsonic: which is flight slower than the speed of sound or below Mach 1</p><p>Second, Transonic: flight at or about Mach 1</p><p>Third, Supersonic: flight faster than Mach 1 and up to Mach 5</p><p>And Fourth, Hypersonic: flight greater than Mach 5, or faster than 5 times the speed of sound.</p><p>So how on earth (or in the sky!) do we get something to fly faster than the speed of sound? Can a regular jet engine get going that fast or does it require a different kind of system all together?</p><p>On the surface, the principles that make a subsonic jet fly are the same principles that make a supersonic jet fly. First air is sucked in with a fan. Next, a compressor raises the pressure of the air. Third, the compressed air is sprayed with fuel and an electric spark lights the mixture. Now that the gases are burning, they begin to expand. Finally, they blast out of the nozzle in the back of the jet. The gases blasting out of the back provide thrust for the jet to move forward.</p><p>So what are the differences?</p><p>For one, supersonic jets typically use afterburners. Afterburners increase thrust by injecting fuel directly into the exhaust stream, and then burns it by using the remaining oxygen. Gases are able to heat up and expand further, increasing thrust by more than 50%.</p><p>Another difference is that the engine is mounted close to the center line of the jet. Sometimes sitting right behind the intakes, which capture the air. By positioning the engine right behind the intakes, the air flow does not have to change directions. It is more efficient. The intakes are also longer and have sharp edges. Some can even change their geometry in order to handle the air coming in at supersonic speeds. The intakes also have a smaller capture area to minimize drag.</p><p>The overall design of the jets are different as well. Supersonic aircraft generally has a more pointed nose and swept or delta wings as opposed to the more straight wings like traditional airplanes. They are also generally made of lightweight material like titanium whereas traditional airliners are made of composite materials.</p><p>The reason behind why the nose is more pointed and the wings more swept has to do with what happens to the air when the plane starts reaching the speed of sound. We&#39;ll talk about this phenomenon in the next section.</p></section><section><h3>Regimes of Speed</h3><p>Regimes of Speed</p><p>Imagine jetting off from New York to London in the morning, surprising a friend for her birthday, then jumping&#160;back&#160;on a plane to be home in time to hit an evening Broadway show.&#160;All in the same day!&#160;Seems incredible, right?&#160;Well, when you travel at supersonic speed, or faster than the speed of sound, it&#39;s possible.&#160;And up until 2003, people were actually traveling that way.</p><p>Supersonic speed is speed faster than the speed of sound, which travels at about 768 miles per hour.&#160;When comparing speed to the speed of sound, we use Mach numbers.&#160;A Mach number is the ratio of the speed of an object to the speed of sound.&#160;If something is traveling at twice the speed of sound that would be Mach 2, or 1,536 miles per hour (2 X 768) for example.</p><p>Supersonic is one of the regimes of speed.&#160;The four regimes are:</p><p>Subsonic</p><p>This is a speed slower than the speed of sound or slower than Mach 1.&#160;Today&#39;s airliners all fly at subsonic speeds, on average about 575 miles per hour when in flight.</p><p>Transonic</p><p>This is the speed at about Mach 1.</p><p>Supersonic</p><p>As mentioned before, supersonic speed is faster than the speed of sound. It ranges from Mach 1 to Mach 5.</p><p>Hypersonic</p><p>Any speed faster than Mach 5, or five times the speed of sound. Launched vehicles fly at hypersonic speeds while in Earth&#39;s upper atmosphere.</p><p>Next Tab</p><p>Aeronautics</p><p>Aeronautics is the study of the science of flight.&#160;It is thanks to aeronautics that we have figured out how to make jets fly faster at supersonic speeds.</p><p>Supersonic jets are actually similar to subsonic jets in a number of ways.&#160;First, both require oxygen from the air, so air is sucked in with a fan.&#160;Next, a compressor, which is made with many blades attached to a shaft, raises the air pressure.&#160;The blades spin at high speed to compress the air.&#160;Third, the compressed air is sprayed with fuel before a spark ignites the mixture.&#160;While burning, the gases begin to expand.&#160;Finally, they blast out of the nozzle in the back of the jet.&#160;The gases blasting out of the back provide thrust for the jet to move forward.</p><p>Afterburners and Intakes</p><p>The differences are mainly in design and the use of afterburners.&#160;Afterburners inject fuel directly into the exhaust stream coming out of the jet and then burn it by using the remaining oxygen.&#160;Because gases are able to heat up and ex<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0cf23a193336480d3cb7a25c76468ef0','transportation-technologies-m8-l3-lesson-2','4cfc925ac5024671aaba2a5fc275edbf','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>How Sonic Boom is Formed</h3><p>How Sonic Boom is Formed</p><p>While watching this video, pay attention to what causes a sonic boom.</p><p>Hi and welcome back, this is video two for the module on Supersonic Jets.</p><p>What happens when you throw a stone in a still pond? You see ripples or small waves. The waves travel at the same speed in every direction. These growing circles are called wave frets.</p><p>With this image in mind, think about listening to a stationery sound source, like a single speaker. Even though we can&#39;t see them, the source creates sound waves which travel outward. The speed of the waves depends on factors like the temperature and altitude of the air through which they move.</p><p>Now if we have a moving sound source, like a train whistle, instead of nice, even circles, the waves in front of the whistle become bunched closer together. This is how we get the doppler effect where approaching objects sound higher pitched. As long as the whistle or other moving sound source moves slower than the waves themselves, the waves will remain nested within each other.</p><p>All that changes when we start approaching supersonic speeds. At supersonic speeds, the object is traveling faster than the sound it is emitting. When this happens, the waves are forced together and start forming a cone-like shape. When the pressure is released, a boom is emitted. Only after the object has passed will an observer be able to hear the sound, or the sonic boom. Because it is behind the jet, the pilot and any passengers can&#39;t hear the boom.</p><p>Another way to think of the phenomenon is in terms of pressure waves. When an object moves through the air, it makes pressure waves in front and behind it. The waves travel at the speed of sound. So when a jet starts traveling faster than the speed of sound, the waves can&#39;t get out of the way of each other. The waves build up and compress until they form a shock wave at the speed of sound.</p><p>A sonic boom is actually two booms. One caused by the change in pressure when the nose of the jet reaches Mach 1 and the other caused by the change in pressure when the tail of the jet passes and the air pressure returns to normal.</p><p>As long as the object flies faster than Mach 1, there will be a continuous sonic boom. Now a sonic boom every once in a while may not be too disruptive, but supersonic jets flying overhead anytime, anywhere would get really bothersome really quickly. Not to mention, it can inflict real structural damage, like break glass or plaster. This is why, unless previously authorized, there is a ban in many countries on supersonic jet flights.</p></section><section><h3>Components of Sonic Boom</h3><p>Components of Sonic Boom</p><p>License:&#160;All Rights Reserved</p><p>Sonic Boom</p><p>A sonic boom is a loud noise created by supersonic aircraft.&#160;The sound can be heard by a person on the ground when the aircraft flies overhead.</p><p>When a jet flies at supersonic speed, the air around it reacts like a fluid.&#160;Think about it like a boat moving through water.&#160;As the jet travels through the air, the air molecules are disrupted, just like the water around a boat.&#160;The molecules are pushed aside with great force which forms a shock-wave, similar to the wave created by the front of a boat moving through water.</p><p>The shock wave creates a cone of pressurized air.&#160;The pressure builds and is sharply released once the air returns to normal.&#160;The release of pressure after the buildup is the sonic boom.&#160;It is kind of like a balloon bursting when pricked by a pin.&#160;The sharp release of pressure creates the loud pop of a balloon.</p><p>Review the list of the components of a sonic boom below.</p><p>Shock Wave</p><p>The shock wave is the primary component of a sonic boom. It is a strong and concentrated wave of pressure that forms when an object moves through the air faster than the speed of sound (supersonic speed). As the object pushes through the air, it compresses the air molecules in front of it, creating a high-pressure region. This sudden change in pressure propagates as a shock wave.</p><p>Overpressure</p><p>Overpressure refers to the increase in air pressure caused by the shock wave. It is the abrupt rise and fall in atmospheric pressure that occurs as the shock wave passes through an area. The overpressure wave travels outward in all directions from the aircraft, causing a sudden increase in pressure followed by a rapid decrease.</p><p>N-wave and M-wave</p><p>Sonic booms are characterized by two distinct pressure waves: the N-wave and the M-wave. The N-wave is the initial sharp increase in pressure, forming the front of the shock wave. It is a rapid and intense pressure change that occurs as the shock wave passes over an observer. The M-wave follows the N-wave and is a longer-lasting, lower-pressure region as the shock wave continues to move away.</p><p>Boom Carpet</p><p>The boom carpet refers to the area on the ground where the sonic boom is perceived. It is the region beneath the flight path of the supersonic object where the overpressure wave reaches the ground. The size and shape of the boom carpet depend on various factors, including the altitude and speed of the aircraft. (See more on this below).</p><p>Mach Cone</p><p>The Mach cone, also known as the cone of silence or conical shock wave, is a geometric shape formed by the shock wave as it spreads outwards from the supersonic object. It is a cone-like structure with its apex at the aircraft and its base expanding outwards. The Mach cone visually represents the boundary of the sonic boom.</p><p>Double Boom</p><p>In certain cases, a sonic boom may be perceived as a double boom. This occurs when the supersonic object generates two distinct shock waves. The first boom is created by the nose of the aircraft, and the second boom is caused by other parts, such as the wings or tail, catching up to the initial shock wave.</p><p>A video showing many jets flying very low. In the video you also hear the sonic boom when the jet passes by.</p><p>Video Title:&#160;INSANE JETS FIGHTER DEEP CROUD FLYING &amp; ULTIMATE SONIC BOOM COMPILATION</p><p>Video Publisher:&#160;Good Nutzer</p><p>License:&#160;Creative Commons Attribution license (reuse allowed)</p><p>Note:&#160;There are no closed captions for this video.</p><p>Boom Carpet</p><p>Although we only hear one sonic boom from a supersonic jet, there are actually two.&#160;The fir<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ece4240ca08b1bba4ae8a2644bf3cb34','transportation-technologies-m8-l4-lesson-3','4cfc925ac5024671aaba2a5fc275edbf','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>The Concorde Supersonic Jet</h3><p>The Concorde Supersonic Jet</p><p>While watching this video,&#160;pay attention to the factors that contributed to the retirement of the Concorde.</p><p>Welcome back, this is video 3 for the module on Supersonic Jets.</p><p>Mick Jagger, Keith Richards, Barbara Streisand, Richard Gere... these were just some of the celebrities you (or let’s be honest, your grandparents) might have met on a flight aboard the Concorde. True, we aren&#39;t talking about Beyonce, Adele, Justin Beiber, or any of today&#39;s A-list celebrities, but in the days of the Concorde, Jagger, Richards, and Streisand were big time celebrities.</p><p>And it wasn&#39;t just celebrities aboard the supersonic flights. Business men and women were another group of people eager to take advantage of the extremely fast flight times. It&#39;s not hard to understand why. Even though the prices were higher than prices for a standard jetliner, the practicality of it made it worth the splurge. The Concorde saved hours, even days, and helped avoid jet lag.</p><p>So what was a flight aboard the Concorde like? Gifts like a sterling-silver tie clip or picture frame waited on passengers&#39; seats. Business people were given meeting portfolios with Concorde logos. Passengers drank champagne and ate caviar.</p><p>Sounds like the definition of luxury, right? Well, in some ways, yes. But it was also loud. And as one former passenger describes the sensation of climbing to 60,000 feet, it was like “being in a dentist&#39;s chair.” Speaking of chairs, the chairs weren&#39;t the large, plush seats you might imagine. Many passengers agree that the seats weren&#39;t very comfortable. It was built with the technology in mind, rather than the comfort of the customer.</p><p>However, once the plane leveled out, passengers had no idea they were going Mach 1 or Mach 2 unless the pilot announced it.</p><p>So what happened to Concorde? If people were saving time and gaining more productivity, why is it no longer around? It was actually a combination of factors, rather than one particular thing, that led to the retirement of the Concorde in 2003.</p><p>First, the costs of Concorde were so great that they could never be made up through the cost of a ticket – even with charging high prices!</p><p>Second, like we talked about before, noise was an issue. Many countries banned it from their airspace due to the sonic boom. This meant there were fewer routes available for Concorde.</p><p>Third, keeping Concorde safe for passengers was a challenge. It required custom (meaning expensive) maintenance because it was so different than other airplanes.</p><p>Forth, fuel efficiency became more and more of an issue as gas prices rose. Concorde burned TWO TONS of fuel just taxiing onto the runway. Then it was a whopping 100 TONS of fuel from London to New York. Today&#39;s 777 uses less than half that for the same route.</p><p>Fifth, there was a tragic Air France crash of the oldest Concorde in 2000 in which all 109 people on board and four people on the ground were killed after debris from a burst tire caused the fuel tank to burst into flames. The accident shed some light on Concorde&#39;s design flaws which led to expensive updates.</p><p>A little over a year later, the terrorist attacks of September 11, 2001 diminished the number of airline passengers significantly for the next few years.</p><p>With all this stacked up behind it and fuel prices not getting any cheaper, Concorde was retired after its last flight on June 27, 2003.</p></section><section><h3>The Concorde Technology &amp; Retirement</h3><p>The Concorde Technology &amp; Retirement</p><p>License:&#160;All Rights Reserved</p><p>Concorde</p><p>Today, a typical flight from New York to London takes about seven or eight hours.&#160;During your grandparent&#39;s, your parents&#39;, and perhaps even in&#160;your&#160;lifetime, people had the ability from New York to London in only 3 and a half hours.</p><p>These supersonic travel times were the magic of Concorde, a joint project between the United Kingdom and France.&#160;British Aerospace and the French firm Aerospatiale designed the airframe.&#160;Rolls-Royce and France&#39;s SNECMA developed the jet engines.</p><p>These engines were zero-bypass engines, also known as turbojets.&#160;A bypass ratio is the ratio of air passed around a jet engine core to the air burned in the core.</p><p>Watch the following video, which illustrates how a jet engine works:</p><p>Welcome to the aviation world. How a CFM 56-5b turbofan engine works. To make an aircraft move forwards, we need a pushing force or thrust, which we create by making the air accelerate between the front and the back of the engine. This is basically done by the large fan at the front of the engine, through which air passes at a high rate. These are the various components of the CFM 56-5b. The fan which is a large diameter propeller. The low and high-pressure compressors with 13 stages which step by step increase the pressure of the air as it flows through them. The combustion chamber, in which jet fuel is mixed with air and burned.The high and low-pressure turbines in which the pressure of the hot gas is reduced as they drive the compressors and fan. There are five turbine stages. One high pressure and four low pressure. And finally, the exhaust assembly. The CFM 56-5b is a high bypass ratio engine. The primary flow passes through the combustor, while the secondary flow passes only through the fan. Eighty percent of the engine airflow accelerated by the fan is directed into the bypass duct and provides eighty percent of the engine&#39;s thrust. The primary flow passes in succession through the compressors, the combustor and the turbines before being ejected rearwards through the exhaust assembly. The air is compressed in the low and high-pressure compressors, and its temperature can reach 450 degrees Celsius. After which, it enters the combustor, where fuel is injected and ignited. Burning the mixture of fuel and air brings the temperature up to 1700 degrees Celsius. Finally, the accumulated energy is extracted in the five-turbine stages immediately after the combustion section. The pressure of the air drops as it passes through the turbines and makes them spin, and the turbines whose shafts ride within one another concentrically. In turn, drive the fan and the two compressors. The air is then expelled through the primary duct joining the air from the <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6dc4a3a26ea05b840bf43c4febdb1dcd','transportation-technologies-m8-l5-lesson-4','4cfc925ac5024671aaba2a5fc275edbf','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Benefits &amp; Obstacles of Supersonic Travel</h3><p>Benefits &amp; Obstacles of Supersonic Travel</p><p>While watching this video,&#160;think about whether or not the pros outweigh the cons of supersonic travel.</p><p>Welcome back, this is video 4 for the module on Supersonic Jets.</p><p>Are there some things, like travel faster than the speed of sound, that humans are just not meant to do? Or are there real benefits to supersonic travel? Let&#39;s examine the pros and cons:</p><p>First the benefits:</p><p>- Faster travel. This is an obvious one. In theory, this would allow business people to fly from New York to London for a conference, and be back in time to have dinner with family or friends.</p><p>- More trips. Since flight time is so quick, supersonic jets can make more trips, potentially bringing in more money. Of course, this assumes demand for supersonic travel is high.</p><p>- Modern luxury. A fresh start to supersonic travel would mean cutting edge technology inside and outside the plane.</p><p>- Technical Innovations. Even if supersonic commercial flights don&#39;t become a reality, the research put into them will improve air travel in general.</p><p>- Competitive advantage. As with any business, airlines are constantly looking for ways to separate themselves from their competition. Offering supersonic travel would do just that.</p><p>- Health benefits. Sitting for a long time is not good for the body. If your flight is shorter, that means less time sitting on the airplane.</p><p>Now the obstacles:</p><p>- Environmental issues. Like we talked about with Concorde, fuel emissions are incredibly high for supersonic jets.</p><p>- Ultraviolet, or UV, radiation. Supersonic jets have to fly higher than existing aircraft. Higher altitude means that less UV radiation is filtered out. However, faster speed means less time on an airplane in the first place, so this could potentially cancel out this risk.</p><p>- Noise pollution. The dreaded sonic boom.</p><p>- Hard to operate. With their special infrastructure, they require technical know-how.</p><p>- Special maintenance. Airports would have to be able to maintain supersonic jets which require different maintenance from other airplanes.</p><p>- High investment cost, especially with no guarantee that they will go into operation</p><p>- Uncertain demand. Just because it is available, does not necessarily mean that people will want to travel at supersonic speeds, especially if the cost is extremely high.</p><p>- Cost to tax payers. Concorde cost French and British tax payers over $1.5 billion. And it would probably be just as high or higher today. That&#39;s an awful lot of money for a plane you may or may not ever ride.</p><p>- Finally: Limited flight areas. As we discussed in the previous section, there are not a whole lot of countries that permit commercial supersonic flights over land. This means only over-water routes are a true option for supersonic jets.</p><p>Despite all these obstacles, there are still companies that believe in supersonic travel. Who are these companies and what are their plans? We’ll dive into that in the last section of this module.</p></section><section><h3>Supersonic Travel Benefits &amp; Jet Risks</h3><p>Supersonic Travel Benefits &amp; Jet Risks</p><p>Read through the two tabs below and compare the pros and cons of supersonic jet travel.</p><p>Supersonic Travel Benefits</p><p>Having examined the Concorde, you should have an idea of some of the pros and cons associated with supersonic travel.&#160;Let&#39;s outline them a little more succinctly.</p><p>Pros:</p><p>Faster travel:&#160;this enables people to connect faster and more easily with one another.&#160;This also translates to more productivity in many cases.</p><p>More trips:&#160;Since turn around for supersonic jets is so fast, the jet could, at least in theory, make more trips which would bring in more money.&#160;Of course this assumes that there is sufficient demand for supersonic travel to justify more trips.</p><p>Updated interiors:&#160;not only would a fleet of new supersonic jets provide a new exterior to the look of a plane, but it would provide the opportunity to re-imagine the interior of a jet.</p><p>Technical innovation:&#160;noise reduction, emissions reduction, and overall efficiency improvement are key components of supersonic research that will spill over and benefit all areas of aeronautics.</p><p>Competitive advantage:&#160;with so many options for flight today, airlines are constantly on the lookout for ways to set themselves apart from other airlines.&#160;Being able to offer supersonic flight would definitely set those airlines apart.</p><p>Health benefits:&#160;less time sitting on an airplane is a good thing, from a health standpoint.</p><p>Supersonic Jet Risks</p><p>Cons:</p><p>Environmental issues: Burning fuel at such high rates does no favors to the environment. Not only does it contribute to pollution, but it also further depletes a nonrenewable energy source.</p><p>Ultraviolet (UV) radiation exposure: Supersonic fly at a higher altitude compared to regular jetliners. The higher the altitude, the less protection there is from UV radiation. Whether or not that is canceled out by the less time spent in the air because of supersonic speeds remains debatable.</p><p>Noise pollution: No matter how comfortable or fuel efficient developers make the supersonic jet, they will still have to contend with the sonic boom.</p><p>Expert training: Supersonic jets are operationally different than traditional jetliners which means they require special skills and expert knowledge.</p><p>Special maintenance: As was the case with Concorde, a supersonic jet will only be able to go where it can be sufficiently maintained. This may limit the number of airports where it can fly.</p><p>High investment cost: Creating, developing, testing, and certifying a supersonic jet is not cheap. Combine that with the possibility that it will not go into operation, and it is not hard to imagine why some might be hesitant to put forth the necessary investment.</p><p>Uncertain demand: Travelers today demand more than just short flight times. If a supersonic jet cannot meet the other requirements passengers have, there may not be sufficient demand.</p><p>Cost to tax payers: If the project is subsidized by the government (like the Concorde was), that money has to come from somewhere. And that somewhere is the pockets of tax paying citizens.</p><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('d3f6475bd44532bcd1720120470c6d3b','transportation-technologies-m8-l6-lesson-5','4cfc925ac5024671aaba2a5fc275edbf','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Companies Developing Supersonic Jets</h3><p>Companies Developing Supersonic Jets</p><p>While watching this video,&#160;think about whether or not supersonic flight is something you&#39;d like to be a part of for your career.</p><p>Hi everyone and welcome back, this is video 5 for the module on Supersonic Jets.</p><p>At Boom Technologies, Inc. the idea that not only have we as a society not flown any faster than we did 40 years ago, but have lost supersonic capability is nothing short of a tragedy. And it&#39;s a tragedy they seek to fix.</p><p>And they have a point. After all, slower travel time means less time spent at our destination, actually doing what it is we are traveling to do. They&#39;ve also got an impressive team working to make this happen. As a whole, their engineering team has made contributions to over 40 new air and space vehicles. They also claim the sonic boom generated by their airliner, Boom, will be 30 times quieter than Concorde&#39;s boom.</p><p>Boom is not the only supersonic jet being dreamed up. The Aerion Corporation AS2 has significant funding behind it. This plane will reach up to Mach 1.5 and be completely boom-less up to Mach 1.2 thanks to its three jet engines and low-boom aerodynamics. Aerion expects the AS2 to certify in 2023.</p><p>And if those companies aren&#39;t sounding exciting enough, there is Elon Musk&#39;s plan for suborbital rocket travel! That&#39;s right. In September of 2017 Musk proposed using a fleet of reusable rockets to fly people between any two cities on earth in less time than it takes to watch a TV show.</p><p>The idea is not particularly new. The idea of flying through space or extremely high altitudes has been around for decades, but most plans call for planes that can fly that high and at supersonic speeds, not rockets.</p><p>While the idea seems super cool, no doubt, it would not be easy. Not only would they have to prove the rockets could fly safely 100% of the time (or extremely close to it), but the costs would be huge. Then there&#39;s the stresses of spaceflight. The acceleration and G-forces for launch and re-entry would be unlike anything most people have ever experienced.</p><p>Boom Technologies, The Aerion Corporation, Space X, and other companies are pushing the bounds of aviation. Whether or not supersonic travel becomes commonplace, what these companies are doing to expand our technology, knowledge, and imaginations is something that will benefit the world no matter what comes of supersonic travel.</p><p>Hopefully this module on supersonic jets has opened your eyes to some of the real drawbacks from newer transportation modes, and how the wave of a magical technology wand can’t fix all problems immediately. Still, despite the setbacks of the Concorde, there seems to be real potential for commercial supersonic flight to make a comeback, and fly you around the world faster than ever.</p></section><section><h3>Future of Supersonic Travel</h3><p>Future of Supersonic Travel</p><p>Boom Supersonic poses the question, “When you can get there in half the time, where will you go?” Boom Technologies is one of the companies with a purposed supersonic jet, which they call Boom.&#160;Although it may be called “Boom,” the company claims that the sonic boom emitted by Boom will be thirty times quieter than Concorde&#39;s sonic boom.</p><p>According to Boom Technologies, the time for supersonic flight is now.&#160;They attribute a number of modern advances, such as composite fuselages and high temperature (which have only recently been accepted by the Federal Aviation Administration for commercial flight) to making it now the time to pursue supersonic flight.</p><p>Take a look at the video below for a look back at supersonic travel and for a look ahead at what the future may bring.</p><p>Recently United Airlines announced a commercial agreement with a Denver-based supersonic aerospace company called boom supersonic to add 15 of their currently in development boom overture aircraft to United&#39;s fleet by 2029. the agreement also gives United an option to purchase an additional 35 more supersonic aircraft. How will this affect air travel? Is it even viable for airlines to fly supersonic? How will passenger comfort be affected? Will supersonic travel affect the environment in any way? Today I&#39;ll be answering all these questions and more, so strap in and get comfy because today we&#39;re diving deep into the realm of commercial supersonic air travel. Before diving into the future of commercial supersonic air travel and its consequences, I need to talk about the past. Despite what many people think, the first supersonic airliner to take to the skies was the soviet-built Tupolev Tu-144 in December 1968. The concord would come to do this just three months later, in march 1969. Everybody thought commercial supersonic air travel was the future, but what happened? Yes, there was the benefit of speed with the concord being able to complete a flight from New York to London in just under four hours instead of six on a conventional jet aircraft. However, this came at the cost of severe noise pollution, environmental pollution and fuel inefficiency. These three factors, along with high maintenance expenses what, ultimately led to the downfall of the concord. The Tupolev Tu-144, on the other hand, was poorly designed from the beginning and had tech that was lacking years behind that of the concords. Despite these factors, both of these aircraft were retired from commercial and private use by the early 2000s. As of 2021, there are no private or commercial supersonic passenger aircraft in service, but there are quite a few in development. The most promising being that of the boom overture from boom technologies that I talked about earlier in the video. That&#39;s quite the name for an aircraft that&#39;ll certainly comfort passengers knowing that they&#39;re flying on the boom overture. This is United&#39;s supersonic aircraft of choice. Why would united choose to fly supersonic in the first place? The answer is time, environmental and fuel efficiency. The problem with flying supersonic is that the noise created from a supersonic boom the noise an aircraft makes from surpasses the speed of sound, is extremely loud and can even shatter windows from 50 to 60 thousand feet in the air. There&#39;s a reason we didn&#39;t see New York to Los Angeles concord services. The amount of fuel needed to keep the aircraft speed above s<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a732ba3dc28dc54fb6808892f1f1a9fc','transportation-technologies-m8-l7-module-8-summary','4cfc925ac5024671aaba2a5fc275edbf','Module 8 Summary','text',12,'<h2>Module 8 Summary</h2><section><h3>Module 8 Summary</h3><p>Module 8 Summary</p><p>Great Work!&#160;You have successfully completed this module on Supersonic Jets!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Defined key technological terms related to supersonic jets and airplane flight</p><p>Differentiated between supersonic jets and regular jet airliners</p><p>Summarized the Concorde supersonic jet program, including its technology, cost, operations, and shortcomings</p><p>Discussed the noise problem of a sonic boom created by supersonic jets</p><p>Identified both pros and cons of supersonic jets, including safety considerations</p><p>Predicted when supersonic jets will be used regularly for intercontinental flight</p><p>Examined an existing company that is developing supersonic jets</p><p>Identified career opportunities in aerospace and educational paths to enter those careers</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7fcb0e5e9f9dca1e738642083d5ac91a','transportation-technologies-m8-l8-module-8-assignment','4cfc925ac5024671aaba2a5fc275edbf','Module 8 Assignment','text',12,'<h2>Module 8 Assignment</h2><section><h3>Module 8 Assignment</h3><p>Module 8 Assignment</p><p>Transportation</p><p>Supersonic Jets - Short Answer Assignment</p><p>Short answer assignment</p><p>For this writing assignment,&#160;write a two-page, double spaced paper addressing the questions/topics listed.</p><p>Visit the career section of a website of a supersonic jet company (Boom Supersonic, EON Aerospace, Inc., or another one that you find). Choose a position that sounds interesting and answer the following questions/prompts:</p><p>Write a summary of the job description</p><p>What are the requirements of the job in terms of education, experience, and language?</p><p>What steps would you have to take to secure that position in the future?</p><p>What do you think would be the most interesting aspect of the job?</p><p>Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('32c6560ddf8c1f7b427354548a6d30eb','transportation-technologies-m8-l9-module-8-project','4cfc925ac5024671aaba2a5fc275edbf','Module 8 Project','text',12,'<h2>Module 8 Project</h2><section><h3>Module 8 Project</h3><p>Module 8 Project</p><p>Transportation</p><p>Supersonic Jets - Project</p><p>Project</p><p>Part 1: For this assignment, imagine you’ve been asked to write a guest post on a popular news blog. The topic is supersonic jets and whether they should ever be used again. You pick a side to the argument, and make sure to support your thoughts with facts and details. The post should be three to five paragraphs long.</p><p>Part 2: After you’ve written the post, you get the chance to look at the topic from another point of view by writing one reader response that offers an opposing idea. The comment should be respectful, give some support for the argument, and be two to three paragraphs in length.</p><p>Review the rubric below to see how you will be graded.</p><p>Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Blog Post</p><p>8 points The blog post demonstrates a strong understanding of the impact of supersonic jets. It contains several specific and accurate details and thoroughly expands on the thoughts discussed.</p><p>7-6 points The blog post demonstrates a strong understanding of the impact of supersonic jets. It contains several specific and accurate details and somewhat expands on the thoughts discussed.</p><p>5-0 points The blog post demonstrates a little to no understanding of the impact of supersonic jets. It contains few to no specific and accurate details and does not expand on the thoughts discussed.</p><p>8</p><p>Review Comments</p><p>8 points The review comment offers valid and well developed opposing arguments to the content of the blog post. It gives specific details to support the statements made.</p><p>7-6 points The review comment offers valid and somewhat developed opposing arguments to the content of the blog post. It gives some details to support the statements made.</p><p>5-0 points The review comment offers invalid or undeveloped opposing arguments to the content of the blog post. It gives little to no detail to support the statements made.</p><p>8</p><p>Formatting</p><p>2 points Includes the required content and is formatted neatly.</p><p>1 point Does not include all required content or is not formatted neatly.</p><p>0 points Does not include all required content and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f26aa7e51ac31fc1148ee1d9f06eceba','transportation-technologies-m8-l10-module-8-quiz','4cfc925ac5024671aaba2a5fc275edbf','Module 8 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Supersonic Jets. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('cf40750d6d947091f3a74dcb8431524a','transportation-technologies-module-9','504e3ab88df8552a07116f12aea44099','Module 9: Personal Rapid Transit',9) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9a50555f31c6447325217bc5bb16d6ff','transportation-technologies-m9-l1-introduction-purpose-and-objectives','cf40750d6d947091f3a74dcb8431524a','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi, and welcome to the module on personal rapid transit.</p><p>The concept has been around for decades. In theory, they solve nearly every transportation problem. Yet in actuality, only a handful exist. They are personal rapid transit, or PRT, systems, and they are the subject of this module. We will look at why only a few examples exist today and whether or not they still have the potential to become the future of transportation. We will also look at personal transporters- like hoverboards- and how they might fit in getting us from point A to point B. Finally, we&#39;ll look at what would happen if you took the best features of a car and the best of a motorcycle and put them together. Let’s get started!</p><p>Module Description</p><p>License:&#160;All Rights Reserved</p><p>What does a small town in West Virginia, Heathrow Airport in London, and Masdar City, United Arab Emirates all have in common?&#160;They all use a transportation system known as personal rapid transit or PRT.&#160;In this module we are going to explore PRT and other exciting modes of personal transportation.</p><p>This module will define and explain PRTs, as well as related terms.&#160;Then the module will discuss the similarities and differences between the PRT systems and existing modes of transportation.&#160;Next, the module will explore personal transporters and how they might fit in to the world of transportation.&#160;Finally, it will end with a look at how crossing a motorcycle with a car could, potentially, offer a solution to many transportation issues.</p><p>Objectives</p><p>In this module, students will</p><p>Describe Personal Rapid Transit Systems (PRTs) and various forms of Podcars or personal vehicles</p><p>Define key vocabulary words and concepts related to PRTs and podcars</p><p>Compare PRT Systems with existing transport systems and infrastructure</p><p>Examine an existing company that is developing PRTs</p><p>Discuss impediments to building PRTs and evaluate how PRTs’ inability to gain mass adoption might impact other future transportation technologies</p><p>Differentiate between fixed-track PRT systems and personal transportation vehicles</p><p>Polling Question</p><p>Which of the following are you most likely to use to get around downtown (or if you don’t live close to a busy city with a downtown area, what would be your preferred method)?</p><p>personal car (yours or someone you know)&#160;taxi or rideshare service (Uber, Lyft)&#160;subway/light-rail/tram&#160;bus&#160;walking</p><p>Make a selection to see the results so far.</p><p>Let&#39;s see how your answer compares to your classmates!&#160;During the module, see if there&#39;s a mode of transportation that might work even better for you.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>traveling directly from one location to another without unnecessary stops for the traveler</p><p>Point-to-point</p><p>personal rapid transit; a form of public transportation that uses small automated vehicles on specially built guideways</p><p>Personal Transporters</p><p>special tracks used by PRT vehicles</p><p>Guideway</p><p>small automated vehicles typically used by PRT systems</p><p>Podcar</p><p>compact, portable, electrically powered vehicles capable of transporting a single individual</p><p>PRT</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>traveling directly from one location to another without unnecessary stops for the traveler</p><p>Answers for question: 1</p><p>Podcar</p><p>PRT</p><p>Point-to-point</p><p>Guideway</p><p>Personal Transporters</p><p>2.</p><p>personal rapid transit; a form of public transportation that uses small automated vehicles on specially built guideways</p><p>Answers for question: 2</p><p>Point-to-point</p><p>PRT</p><p>Guideway</p><p>Personal Transporters</p><p>Podcar</p><p>3.</p><p>special tracks used by PRT vehicles</p><p>Answers for question: 3</p><p>Personal Transporters</p><p>PRT</p><p>Podcar</p><p>Point-to-point</p><p>Guideway</p><p>4.</p><p>small automated vehicles typically used by PRT systems</p><p>Answers for question: 4</p><p>Guideway</p><p>PRT</p><p>Personal Transporters</p><p>Podcar</p><p>Point-to-point</p><p>5.</p><p>compact, portable, electrically powered vehicles capable of transporting a single individual</p><p>Answers for question: 5</p><p>Podcar</p><p>Personal Transporters</p><p>PRT</p><p>Guideway</p><p>Point-to-point</p><p>Automated Transit Network; another name for personal rapid transit systems</p><p>Headspace</p><p>specialty piece used to create self-balancing devices by enabling the device to maintain equilibrium</p><p>Track switching</p><p>a method that enables a vehicle to switch tracks by means of a device mounted on the vehicle itself</p><p>ATN</p><p>the act of driving or pushing forward</p><p>Vehicle-mounted switching</p><p>the distance between two pods</p><p>Propulsion</p><p>a method that enables a vehicle to switch tracks by means of a device mounted on the tracks</p><p>Gyroscope</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Automated Transit Network; another name for personal rapid transit systems</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0d14583bdd9782f11ee759643bda419c','transportation-technologies-m9-l2-lesson-1','cf40750d6d947091f3a74dcb8431524a','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Issues PRT System Address</h3><p>Issues PRT System Address</p><p>While watching this video, think about the biggest problem that our current transportation systems have and see if PRT systems address that issue.</p><p>Welcome back, this is video 1 for this module on Personal Rapid Transit.</p><p>If you ask people their opinions on which mode of transportation is most efficient, you probably won&#39;t hear many people say, “a bus!” Waiting at stops for the bus to arrive, indirect routes, waiting for passengers to get on/off, changes in schedules... it&#39;s not hard to see why buses aren&#39;t the favorite.</p><p>And many of those inconveniences aren&#39;t limited to buses either. Subways and trains have similar issues. Then there are cars and taxis, but they are subject to traffic conditions and can be more expensive. What if there was another way? Enter, Personal Rapid Transit also known as Automated Transit Networks.</p><p>A Personal Rapid Transit or PRT, is a mode of public transportation that uses small, automated vehicles that operate on a network of specially built guideways, or tracks. Less like a bus, and more like a car, vehicles (which we will call podcars) are designed to fit three to six people in each vehicle.</p><p>Unlike most existing and proposed transportation systems that seek to remedy one or two transportation problems, the PRT system seeks to provide a full solution to urban transportation (urban being in large cities). PRT systems combine the point-to-point efficiency and privacy of a car with the eco-friendly and traffic solving potential of public transportation. Because they travel at reasonable speeds and driver error is eliminated, thanks to the pod&#39;s autonomy, PRTs are a safe solution as well.</p><p>The signifying feature of the PRT system is in its guideway setup. Guideways are arranged so that all the stations are located on sidings with lots of merge and diverge points. Unlike a bus where riders stop at each designated bus stop, the PRT guideway system allows for nonstop point-to-point travel. The lanes are segregated with no pedestrian or other vehicles crossing. This maximizes efficiency. To avoid interference of other vehicles, pedestrians, animals, etc. some use an over-pass system, while other systems are built underneath roads and buildings.</p><p>Furthermore, because PRT vehicles are lightweight, they require smaller guideways and support structures than other systems like light rails. This smaller guideway means it is less expensive to build, uses up less land, and is less visually intrusive. Sounds great, right? We’ll explore whether or not these benefits outweigh the downsides throughout the rest of this module.</p></section><section><h3>Components Constituting PRT</h3><p>Components Constituting PRT</p><p>What is one of the most annoying parts of going downtown?&#160;If you said traffic, driving, navigating, or parking, you are not alone.&#160;Congested roads, limited parking, and trying to figure out where you are and where you need to be can make going downtown stressful, whether you are a passenger or a driver!</p><p>PRT Definition</p><p>Personal Rapid Transit (PRT) aims to alleviate all those stresses with an automated system which utilizes small vehicles, or podcars, on a specially designed guideways.&#160;A rider simply pays for the fare, selects the destination in the PRT&#39;s system, and boards the provided podcars.&#160;Then, the podcar whisks the rider directly to his/her final destination.&#160;There are no other stops along the way.&#160;Expand the items in the list below to identify the components that constitute PRT.</p><p>Individualized Vehicles</p><p>Personal rapid transport (PRT) systems consist of individual vehicles designed to carry a limited number of passengers, typically ranging from one to six individuals. These vehicles can be small, automated, and electrically powered, providing personalized transportation for each passenger.</p><p>Dedicated Infrastructure</p><p>PRT systems require dedicated infrastructure, often in the form of a network of guideways or tracks. These guideways can be elevated, at-grade, or even underground, creating a separate and exclusive transportation system for PRT vehicles. The infrastructure ensures the smooth and efficient movement of the vehicles within the system.</p><p>Point-to-Point Connectivity</p><p>PRT systems offer point-to-point connectivity, allowing passengers to travel directly from their origin to their destination without the need for intermediate stops or transfers. This feature eliminates the inconvenience and time associated with traditional transit systems, providing a faster and more direct transportation experience.</p><p>On-Demand Service</p><p>PRT systems typically operate on an on-demand basis, meaning passengers can request a vehicle when needed, similar to ride-hailing services. This personalized service ensures that vehicles are available when and where passengers require transportation, minimizing waiting times and providing flexibility in travel arrangements.</p><p>Automated Operations</p><p>PRT systems heavily rely on automation and advanced technologies. The vehicles are often fully automated, guided by sensors, computers, and communication systems. This automation ensures precise control, efficient operations, and increased safety within the PRT network.</p><p>Energy Efficiency and Environmental Sustainability</p><p>Personal rapid transport systems prioritize energy efficiency and environmental sustainability. PRT vehicles are often electrically powered, reducing reliance on fossil fuels and minimizing emissions. Additionally, the compact size of the vehicles and the point-to-point connectivity contribute to reduced congestion and improved overall transportation efficiency.</p><p>Integration with Urban Infrastructure</p><p>To be effective, PRT systems need to integrate with existing urban infrastructure. This integration involves seamlessly connecting PRT stations to other modes of transportation, such as bus stops, train stations, or bike-sharing networks. Integration enhances the overall connectivity and accessibility of the transportation system, offering passengers a comprehensive travel experience.</p><p>Guideways</p><p>The guideways, or tracks, allow for point-to-point efficiency because the stations are located off the main line.&#160;Instead of stopping on the main line, the guideways have many merge/diverge points that allow podca<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ee054653d76e461cef07e29ddb486f29','transportation-technologies-m9-l3-lesson-2','cf40750d6d947091f3a74dcb8431524a','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>How Podcar Work</h3><p>How Podcar Work</p><p>While watching this video, see if you can understand the difference between the two switch systems.</p><p>Welcome back, this is video 2 for this module on Personal Rapid Transit.</p><p>Now that we have the overall picture of how they service the public, let&#39;s look a little closer at the logistic of PRTs.</p><p>Like we mentioned in the earlier section, PRTs use electric podcars for propulsion. Propulsion being the force that makes the pods go. Because each podcar is so small, the required electricity for each pod is much less than the electricity needed for large rail cars. They also save on power because there is no set schedule. So, if a podcar is not being used, it is not using power.</p><p>With any rail system, how the vehicle switches from one track to another is an important component. There are typically two ways this can be done. The first, is vehicle-mounted switching. Like the name suggests, this uses a system on the actualpodcar itself to navigate to the correct tracks.</p><p>The benefit of the vehicle-mounted switch is that it is a faster system which allows podcars to travel closer together. Or in other words, allows for less&#160;headspace. Another win for the vehicle-mounted switch system is that if something goes wrong on one podcar, it doesn&#39;t necessarily impact every other podcar in the system.</p><p>The other switch system is a track switch system where the device used to switch vehicles onto the correct track is mounted on the track itself. This is called track switching. Benefits with this system include fewer moving parts on the podcars and better durability.</p><p>Now that we understand a bit about how the podcars move about on the guideways, let&#39;s examine the stations. In most PRT designs, the stations are small, since they won&#39;t see the big crowds that can pour into stations of other public transport systems. They are often automated as well. So rather than being manned by a ticket agent, people can simply use a kiosk to arrange for travel.</p><p>Stations will also be placed off the main line so that podcars can zoom by without having to wait for people to board at intermittent stops.</p><p>To help solidify the concept even further in your mind, in the next section we&#39;ll lay out all the differences and similarities between PRTs and traditional public transportation systems.</p></section><section><h3>Pod Size</h3><p>Pod Size</p><p>(opens in a new tab)</p><p>Creative Commons&#160;is licensed under&#160;CC BY-SA 4.0(opens in a new tab).</p><p>Pod Size</p><p>One of the biggest hurdles in figuring out a PRT is determining the pod size.&#160;In the USA, the average car carries 1.16 people.&#160;In fact, most industrial countries have an average of fewer than 2 people per car.&#160;This low rider-per-car ratio is indicative of peoples&#39; preference not to share a car with strangers.</p><p>So does that mean pods should fit one person?&#160;What about if a small family wants to use the system?&#160;Or a single rider with a bike?&#160;If the pods accommodate such situations, will people be turned off at the idea of potentially sharing a pod with strangers?&#160;Where is the happy medium between offering the privacy of a personal car and the convenience of fitting a small group?&#160;These are not easy questions to answer.&#160;Most are built to accommodate a small group of approximately six people.</p><p>PRT Technology and Terms</p><p>Press through the tabs below to learn some important terms and technology related to PRT.</p><p>Propulsion</p><p>Most proposed PRT systems call for electric propulsion.&#160;Propulsion is the driving force that pushes a pod forward.&#160;To make the pods light, they are powered from the outside, as opposed to onboard batteries, though most include a small battery as emergency backup.&#160;This is more eco-friendly than traditional buses or cars.&#160;Furthermore, where a bus or light rail has a set schedule that runs even if no one is riding, the pods would have designated waiting spots where they would sit until needed by a passenger.&#160;This would save energy and be friendlier to the environment.</p><p>Vehicle-Mounted Switching</p><p>To navigate the tracks, most designs call for vehicle-mounted switching. Proponents of vehicle-mounted switching state that it is faster and allows pods to be closer together (the distance between two unmanned pods is called headspace.) compared to the distance between pods on a track switching system. Another benefit is that if a switch fails on one pod, it will not likely affect other pods.</p><p>However, there are supporters of track switching (what traditional railway systems use) who point out that while vehicle switching may simplify the tracks, track-switching simplifies the cars and involves fewer moving parts. Furthermore, since the parts would be on the track, they could be built for durability without worrying about size or weight.</p><p>Pod Locations</p><p>PRT stations will be similar to subway stations but will operate on a smaller scale since the stations will only need to accommodate a small number of passengers at a time. One key difference, however, is that pods will not be located on the main lane. Rather, there will be sections connected to the main lane by the same junction.</p><p>Next Tab</p><p>PRT Systems vs.&#160;Buses</p><p>While we have spent most of the previous section pointing out the flaws of bus systems, there are actually people who feel that buses are the system to develop, not PRTs.&#160;It is a bold claim, considering all the traffic generated because buses have to stop, wait for people to load and unload, and collect individual fares.</p><p>Countries in Latin America have implemented the bus rapid transit system.&#160;The bus rapid transit (BRT) system lifts buses out of the ordinary flow of traffic and into segregated, high-speed lanes.&#160;Waiting for passengers to pay their fares disappears by utilizing fully-enclosed stations where passengers can pay before the bus even arrives.&#160;Bonus:&#160;this system is MUCH cheaper than PRT.</p><p>Of course, you are left without the eco-friendly and privacy aspects of PRT which could mean that if built, it could be under-utilized if it turns out people value no emissions and privacy over the benefits of PRT.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3790e26a4afb79be273ee8ad7b9eae64','transportation-technologies-m9-l4-lesson-3','cf40750d6d947091f3a74dcb8431524a','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Cost of PRT System for a City</h3><p>Cost of PRT System for a City</p><p>While watching this video,&#160;imagine you are on a city transportation planning board of the largest city in your state.&#160;Would you recommend the addition of a PRT system to your city, or would you recommend something else?</p><p>Welcome back, this is video 3 for this module on Personal Rapid Transit.</p><p>In his book published in 1964, city transportation planner, Don Fichter made a keen hypothesis. He hypothesized that people would not choose a public transportation system over their cars unless that system offered greater flexibility and better end-to-end transit times. This was among the earliest call for a PRT system.</p><p>If the idea has been around for decades, why is it not more commonly implemented? PRT experts and proponents believe it is because politicians and the general public do not fully understand PRT systems and therefore easily dismiss them.</p><p>Issues in implementing a well-designed system in the past include financing, cost overruns, political issues, misapplied technology, and poor design/engineering. Because there is no gold standard example, it makes cities unwilling to implement the system.</p><p>Interestingly, a company called SkyWeb which develops PRT systems, has had over 40 cities tell the company they would love to be the second city to implement the system. Unfortunately, it is impossible to be second if no one is first. Cities are playing a game of chicken; showing interest but backing off until another city makes the first big move.</p><p>Critics of the system feel that PRT is too impractical. They believe the costs will be too high and the system too complex to work anywhere other than large college campuses or airports. There is a valid point, especially about the costs. PRT is estimated to cost $25 to $40 million per mile which is a high price for just about any city or state to spend.</p><p>However, it costs about $100 to $300 million per mile for a light rail system. Compared to those prices, suddenly PRT seems almost cheap. However, tax money is already allocated to buses and lightrails. No city seems to have a large lump of money just waiting to be spent.</p><p>A company called SkyTran feels they have the answer to balancing the pros of PRT with the cons of its required infrastructure. SkyTran is an elevated PRT system that would use magnetic levitation to levitate its “jet-like” vehicles. Thrust would also be generated from electromagnets. As a result, the power needed is significantly less than the energy consumed by other modes of transportation. Another benefit to using magnetic levitation is that there is less wear and tear on components which means it should last a good, long time.</p><p>SkyTran is also unique in that their guideways feature “snap together” rails which can be assembled relatively quickly and easily. The system also has all the benefits of PRT that we have covered such as point-to-point travel, privacy, no unnecessary stops, etc. Perhaps SkyTran is the answer cities are looking for!</p></section><section><h3>Existing PRT Systems</h3><p>Existing PRT Systems</p><p>Despite the convenience, and the many proposed systems, only a few PRTs actually exist.&#160;The oldest and most extensive is in Morgantown, West Virginia, which is on the campus of West Virginia University.&#160;Other places include Heathrow Airport (London England); Suncheon, South Korea; and Masdar City, United Arab Emirates.&#160;Of these other ones, none of them exist quite the way proponents envision.&#160;Most are just alternatives to shuttles and/or automated people movers.</p><p>PRT requires building an entirely new infrastructure, mainly all knew tracks and stations.&#160;Any system that requires a brand new infrastructure is going to be difficult to implement because building a new infrastructure takes money and resources.&#160;Buses, on the other hand, can just utilize the roads already built in a city which makes them a much cheaper form of public transportation for a city to implement.</p><p>Expand the sections below to learn about three existing PRT systems.</p><p>Above Ground</p><p>Furthermore, that infrastructure can be quite obtrusive, especially if built above ground. Chicago’s elevated train or “L-train”, for example, was built in the 1890’s and would be much more expensive and difficult to build today. There is a reason it is one of the few cities in the U.S. with significant amount of above-ground track (Los Angeles, New York City, and Philadelphia are others). As mentioned before, many designs call for above-ground guideways in order to maximize efficiency. However, an above-ground system may be very noticeable and restrict views. However, many designers are coming up with designs that would blend the infrastructure into the cityscape as best as possible.</p><p>PRT systems aim to be everything to everyone, as far as transportation options are concerned. Interestingly, this aim could prove to be a potential pitfall to the system. As more people use the system, it becomes less able to accommodate private or semi-private destination demands. This reduces it to more of a light-rail system, making multiple stops. But it would be unable to handle a rush-hour crowd.</p><p>Perhaps rather than a cure-all, it is best to look at PRTs as a cure-some. Perhaps there are some areas that are better suited than others for the PRT system. For example, small to mid-sized cities that do not already have well-established transit system already. Other useful places are campuses, airports, and new cities.</p><p>The system was a good fit for the city of Masdar because it was being built from scratch with the intention of discouraging private vehicles. For new cities, it also nearly eliminates the problem of disrupting surroundings. However, there are not many brand new cities built from scratch out there (at least not in the US).</p><p>PRT Systems vs.&#160;Driverless Cars</p><p>There is yet another obstacle in the way- driverless cars. Companies are actively developing and even implementing driverless cars already. Driverless cars offer all the benefits of the PRT system without the expensive infrastructure.</p><p>In a driverless car, passengers would get the privacy, the ease of navigation, and the freedom to engage in other activities. Driverless cars even one-up the PRT systems because, unlike PRTs, a driverless car can take a passenger from his/her house to his/<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('67444cf6bb73a0669d3f5e621f48a55a','transportation-technologies-m9-l5-lesson-4','cf40750d6d947091f3a74dcb8431524a','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Use case of Personal Transporter</h3><p>Use case of Personal Transporter</p><p>While watching this video, pay attention to the different types of personal transporters and think about which kind you would like to use the most!</p><p>Welcome back, this is video 4 for this module on Personal Rapid Transit.</p><p>Perhaps PRT is overthinking things a little bit. I mean, if you have to find a way to get to a station anyway, why not just take your car to a parking lot just outside the crazy congestion of a city then use a personal transporter to get you the rest of the way?</p><p>By personal transporter I mean a compact, portable, electrically powered vehicle for transporting a single individual.</p><p>Personal transporters are great in many ways. For one, they require no infrastructure. Just regular ol&#39; sidewalk will do! They also don&#39;t require any kind of stations or stops. Most are pretty inexpensive too, especially compared to buying a car. And obviously, they get you where you need to go faster than walking. Bonus- they are electric which means no need to buy gas and no direct polluting emissions from the vehicle!</p><p>Most personal transporters fit into one of four categories:</p><p>Category one: Electric kick scooter- this is a self-moving version of the classic Razr scooter. You stand on a platform or “deck” with a wheel behind you and a wheel in front of you. To steer, you turn the handlebars. Most kick scooters also let you move “the old fashioned way” by using your foot. Not the fanciest of personal transporters, but in many cases, they can get the job done.</p><p>Category two: Self-balancing scooter- if you want something a little more futuristic looking, then self-balancing scooters might make you perk up a little. These include all self-balancing powered portable devices with two parallel wheels. This is the category where Segways and the Segway miniPRO fit.</p><p>Another pretty awesome device in this category are self-balancing hoverboards. Just to be clear, the entire board doesn&#39;t hover! The two wheels stay very much on the ground. It has two motorized wheels connected to pads where the rider puts his foot. The rider controls the speed by leaning forward or backward. Direction is controlled by twisting the pads. You&#39;ve probably seen a few of these out and about. Maybe you even own one! For less than $350, they are much more affordable than a car and are comparable to some bikes in cost.</p><p>Category three: Electric skateboards- like a regular skateboard, you control these by shifting your weight. The difference is, of course, you don&#39;t have to use your foot to push it along. An electric motor takes care of that for you. Speed is controlled by a hand held throttle or weight-sensor controls. Hub motors, which were first introduced in 2015, have made the motors on these devices more quiet, more responsive, and allow the skateboard to be used as an unpowered device without feeling really heavy.</p><p>Category four is the self-balancing unicycle. Unicycles are notoriously hard to learn to ride. But the self-balancing kind make it much easier. These use gyroscopes, reaction wheels, and/or auxiliary pendulums to help the rider balance. To control the speed, just lean forward or back. To steer, just twist the unit using your feet.</p><p>There are a couple more devices that don&#39;t quite fit into the categories above but are probably worth mentioning since you may see them in the future, especially in airports. One is Honda&#39;s Uni-Cub. Like the other self-balancing devices, the Uni-Cub moves as the rider leans forward or backward and turns when the rider leans. It is meant to keep the rider closer to eye level with a walking person and also leave the riders hands free.</p><p>The Modobag is no doubt designed with travelers in mind. This rideable piece of luggage will get you to your connecting flight with time to spare! It features telescope handlebars which mean they can slide up when you are ready to ride, and slide down when you need to load your luggage into an overhead bin.</p><p>If you&#39;re like me, you might be thinking these all sound like so much fun and you want to try all of them. While they may be fun and save you from having to... you know... walk (heaven forbid we ever do anything so boring as walk!) They are not without their downsides. The biggest one is probably the fact that most of these aren’t great for use outside and can be rendered useless in anything heavier than a gentle sprinkle of rain.</p><p>In the next section we&#39;ll look at one last method of personal transportation that might provide some of the solutions that PRT and personal transporters can&#39;t provide.</p></section><section><h3>Types of Personal Transporters</h3><p>Types of Personal Transporters</p><p>Imagine you had to go from your house to a destination about a mile away.&#160;Which of the following would you most likely use to get there?</p><p>Bike&#160;Skateboard/longboard&#160;Walk/run&#160;Scooter/moped&#160;Car</p><p>Make a selection to see the results so far.</p><p>It should be pretty clear by now that building an entire infrastructure from scratch is an expensive, headache-inducing undertaking.&#160;On the other hand, finding parking for a car can be stressful too.&#160;&#160;And no one wants to sit around and wait for a bus.&#160;So what other ways are there to get from, say, a store downtown to a restaurant about a mile away in a crowded urban city?</p><p>Personal Transporters</p><p>Hoping to be the answer to those problems are personal transporters.&#160;Personal transporters are compact, portable, electrically powered vehicles capable of transporting a single individual.&#160;Most personal transporters fall into one of four categories.&#160;Press each tab to learn more.</p><p>Electric Kick Scooters</p><p>These vehicles have two in-line wheels with a platform for the rider to stand on and handlebars for steering.&#160;Most fold up, making them conveniently transportable.&#160;To get it going, the rider just needs to twist the throttle.&#160;The Razor e-series are popular electric kick scooters as well as Speedway Mini 4 Pro.</p><p>Self-balancing Scooters</p><p>These differ from electric kick scooters in that the wheels are parallel instead of front and back. Examples in this category are Segways and Segway Mini products. Also fitting into this category are vehicles known as “hoverboards” sometimes referred to as “self-balancing board<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6872669e5e5173db85ecf7a665e7a04f','transportation-technologies-m9-l6-lesson-5','cf40750d6d947091f3a74dcb8431524a','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Companies Developing Personal Transporters</h3><p>Companies Developing Personal Transporters</p><p>While watching this video,&#160;see if you can see how the C-1 and i-road combine the best features of cars and motorcycles.</p><p>Welcome back, this is video 5 for this module on Personal Rapid Transit.</p><p>So cars are big, create congested roads, and emit pollution into the air, but get you exactly where you want to go. Buses can transport a group of people, but are typically subjected to the same traffic as cars, follow a schedule, and have fixed stops. PRTs avoid unnecessary stops, require little station waiting time, and bypass traffic, but are expensive to build, difficult to carve into already developed cities, and travelers may have to arrange additional transportation to get to their final destination. Personal transporters are small, compact, can get you to an exact destination, and require no special infrastructure, but are only practical for short distances and decent weather. IS THERE ANY OTHER SOLUTION?!</p><p>Lit Motors says there is! They have created a vehicle which combines the stability and full enclosure of a car, with the compact freedom of a motorcycle. It&#39;s called the C-1.</p><p>Stability and motorcycle in the same sentence? Yes! It features a gyro stability system which allows the C-1 to stay upright in the event of a collision. It also employs mechanical backups for further safety and stability. And like a car, it has seatbelts and airbags. It is also self-balancing and has a reverse function, unlike motorcycles which require the rider to use her feet.</p><p>The fully-enclosed body and gyro stability systems mean that the C-1 will handle like a car in the event of bad weather. The company is also working to make an all-wheel drive version as well which would take the safety yet another step up. With a base price expected to be around $24,000 it is similarly priced to a small car. Because it is fully electric, there may be some incentives available in some areas which would bring the cost down even more.</p><p>Lit Motors isn&#39;t the only company going the motorcycle, car hybrid route either. Toyota has developed the i-road. This vehicle has a lot of the same features as the C-1, but uses three wheels- two in front and one in back. It&#39;s already out on the roads being tested and users are providing feedback.</p><p>The i-road has a maximum speed of around 30 miles per hour and a range of about 30 miles. This makes it convenient for quick trips around the city or neighborhood, but won&#39;t get you too far beyond that.</p><p>While both are capable of carrying a passenger or a small load of groceries, or a suitcase, or something similar, neither is designed for families. For that reason, these types of vehicles are probably best suited as commuter vehicles or for quick outings.</p><p>I hope this has been a fun and interesting module for you! We’ve covered a lot, from public transportation PRT systems, to hoverboards and segways, to motorcycle/car hybrids. There are a lot of ways to get a person from point A to point B, and this module shows that they can be creative and fun, while improving on the existing systems and modes that we currently have.</p></section><section><h3>C-1 and I-Road Motorcycle Features</h3><p>C-1 and I-Road Motorcycle Features</p><p>C-1</p><p>Would you rather drive a car or a motorcycle?&#160;Your answer is probably “it depends.” It depends on the weather, where you&#39;re going, the type of terrain, how fast you need to get there, how far, etc. To be sure, each has their own pros and cons.</p><p>Motorcycles can weave in and out of traffic, park in tight spaces, take up less room (which lowers overall traffic congestion), can go farther on less fuel, and are pretty fun to drive!&#160;On the downside, they are notoriously unstable, do not protect the rider from the elements, and lack the safety features of a car.</p><p>Most cars, on the other hand, are fully-enclosed, have many safety features, steer easily, and are stable.&#160;On the downside, they take more fuel to run, require large parking spaces, and contribute to traffic and congestion.</p><p>However, both provide the privacy and point-to-point travel that people want from transportation modes.</p><p>What if you could get the best features of both in one vehicle?&#160;The Lit Motors C-1 is a cross between a motorcycle and a car.</p><p>It&#39;s like a motorcycle in that it has two wheels, is compact and narrow enough to allow the rider to weave in and out of traffic, and leans to turn.&#160;The C-1 is like a car in that it is all enclosed, has a reverse mode, and similar steering.</p><p>With environmental concerns growing in the minds of the public, the C-1 runs on a rechargeable battery, not fossil fuels.</p><p>Gyroscopic Stability System</p><p>Where the C-1 really stands out from a traditional motorcycle is in its stability and safety.&#160;The vehicle features a patented gyroscopic stability system.&#160;The gyroscopes are controlled by the vehicle.&#160;This allows the C-1 to lean itself into and out of turns, and stay upright when stopped or even in the event of a collision.&#160;The gyroscopic stability system brings the stability of a car to the two-wheeled system of a motorcycle.</p><p>Being enclosed enables the developers to add safety features traditionally found in cars.&#160;There are seatbelts, airbags, and a steel reinforced chassis.&#160;Climate control and a premium sound system are perks to this sort of enclosed set up too!</p><p>They are not in production yet, but the video below highlights the C-1 design and features.</p><p>We&#39;re taking smartphone a spaceship technology on a motorcycle platform with the safety of a car. Basically, it&#39;s a is a robot motorcycle. It itself bounces and really increases like you know your safety and your range and the excitement of riding a motorcycle. 200 miles per charge, it&#39;s a two-wheel drive, wheel hub motor, you know, electric vehicle. Steer it like a car, you sit in it like a car, you have pedals like a car, but you know the robot side. It takes your Siri input and leans you into turns a lot like a jet fighter. So as you can see, full electronics in here, and this is actually a real gyro right here if I don&#39;t take a look at this.The gyroscopes inside basically output around 1300 foot-pounds of torque. So you basically need a baby elephant to knock it over. It&#39;s a lot like a CMG or a cont<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1b0471ef70dcb561161b150e8f2da272','transportation-technologies-m9-l7-module-9-summary','cf40750d6d947091f3a74dcb8431524a','Module 9 Summary','text',12,'<h2>Module 9 Summary</h2><section><h3>Module 9 Summary</h3><p>Summary</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Personal Vehicles!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Described Personal Rapid Transit Systems (PRTs) and various forms of Podcars or personal vehicles</p><p>Defined key vocabulary words and concepts related to PRTs and podcars</p><p>Compared PRT Systems with existing transport systems and infrastructure</p><p>Examined an existing company that is developing PRTs</p><p>Discussed impediments to building PRTs and evaluate how PRTs’ inability to gain mass adoption might impact other future transportation technologies</p><p>Differentiated between fixed-track PRT systems and personal transportation vehicles</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4625e23909392d95595d5771c5729b0b','transportation-technologies-m9-l8-module-9-assignment','cf40750d6d947091f3a74dcb8431524a','Module 9 Assignment','text',12,'<h2>Module 9 Assignment</h2><section><h3>Module 9 Assignment</h3><p>Module 9 Assignment</p><p>Transportation</p><p>Personal Rapid Transit - Short Answer Assignment</p><p>Short answer assignment</p><p>Choose another transportation mode (cars, light rails, buses, trains, driverless cars) and compare the similarities and differences between that mode and PRT Systems discussed in sections 1 through 3.</p><p>Write your answer in a two-page, double spaced paper.</p><p>(Hint: some things you can compare include: fuel/power type, how many passengers it can carry at a time, infrastructure required, privacy, cost, and many more!)</p><p>Review the rubric below to see how you will be graded.</p><p>Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6acbf9c41e59166f7ae5f48660c07d5e','transportation-technologies-m9-l9-module-9-project','cf40750d6d947091f3a74dcb8431524a','Module 9 Project','text',12,'<h2>Module 9 Project</h2><section><h3>Module 9 Project</h3><p>Module 9 Project</p><p>Transportation</p><p>Personal Rapid Transit - Project</p><p>Project</p><p>In this assignment, you will create an infographic that explains and examines Personal Rapid Transit Systems (PRTs). &#160;&#160;Infographics are visual charts that take a complicated or boring topic and present them in a fun, quick, and visually engaging way. Infographics are designed with a purpose in mind: often to inform or persuade. You can choose from a variety of web tools available to make your graphic.</p><p>Your infographic should:</p><p>describe Personal Rapid Transit Systems (PRTs)</p><p>discuss positive and negative features of the technology</p><p>argue for or against the use of PRTs</p><p>discuss some of the technologies involved</p><p>persuade the audience with facts</p><p>be creative and visually engaging</p><p>be organized and succinct</p><p>use citations where needed</p><p>Review the rubric below to see how you will be graded.</p><p>Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Content</p><p>8 points The infographic demonstrates a strong understanding of PRTs and their technology. It contains several specific and accurate details, including positive and negative features.</p><p>7-6 points The infographic demonstrates a satisfactory understanding of PRTs and their technology. It contains some specific and accurate details, including positive and negative features.</p><p>5-0 points The infographic demonstrates little to no understanding of PRTs and their technology. It contains few to no specific and accurate details, including positive and negative features.</p><p>8</p><p>Persuasive</p><p>6 points The infographic effectively presents a theme or opinion and thoroughly supports it with facts.</p><p>5 points The infographic adequately presents a theme or opinion and sufficiently supports the it with facts.</p><p>4-0 points The infographic does not effectively present a theme or opinion or does not sufficiently support it with facts.</p><p>6</p><p>Presentation</p><p>4 points The infographic is well organized and presented in an engaging way.</p><p>3 point The infographic is somewhat organized and is presented in a slightly engaging way.</p><p>2-0 points The infographic is not organized well or is not presented in an engaging way.</p><p>4</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8d0506c850031bb8942b0e419bfb865c','transportation-technologies-m9-l10-module-9-quiz','cf40750d6d947091f3a74dcb8431524a','Module 9 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Personal Rapid Transit. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('88caa25af800d7fb05c4da98a7cd0564','transportation-technologies-module-10','504e3ab88df8552a07116f12aea44099','Module 10: Supercavitation',10) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7fbd716d03ddcf83e1078a231de068a5','transportation-technologies-m10-l1-introduction-purpose-and-objectives','88caa25af800d7fb05c4da98a7cd0564','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Imagine eating lunch in Los Angeles then dinner that same day in Shanghai, China. You&#39;re probably thinking I’m talking about supersonic travel, and I am! But not in the way you might be imagining. Believe it or not, we&#39;re talking about traveling from LA to Shanghai, not by jet plane or rocket, but by a supercavitation submarine.</p><p>Under the right conditions, supercavitation has the capacity to make even the fastest boats move faster. Under the wrong conditions, it can erode a propeller. Under the right conditions, it could make an entire submarine move at supersonic speeds. Under the wrong conditions, it would cause an unstable, bumpy ride. In this module, we will look at what the right and wrong conditions are for supercavitation as well as the future of marine transportation.</p><p>Module Description</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>In this module, we will get in the water and examine some of the futuristic transportation ideas in the sea.&#160;The focus of the module will be on the concept of supercavitation, which is a technology that has been around for decades, but has been sparsely used and has some serious challenges.&#160;Scientists&#160;are&#160;figuring out solutions to some of these challenges, which may lead to a resurgence in the use of this unique technology.&#160;In the final section, we will also review some other marine transportation modes that incorporate ideas that include autonomous control and clean energy.</p><p>Objectives</p><p>In this module, students will</p><p>Define density, drag, cavitation and supercavitation</p><p>Differentiate between vaporous and artificial cavitation</p><p>Identify historical and future use cases for supercavitation</p><p>Discuss problems associated with supercavitation and potential solutions</p><p>Identify and describe other futuristic marine transportation such as autonomous and fuel-efficient ships</p><p>Create a business plan for a company that utilizes supercavitation</p><p>Polling Question</p><p>What was the purpose for being on a boat the last time you road on one?</p><p>Recreation (e.g. water skiing, wake boarding, etc.)&#160;Vacation (cruise liner)&#160;To get to a destination (i.e. to get from one city to another)&#160;I have never been on a boat&#160;Other</p><p>Make a selection to see the results so far.</p><p>Let&#39;s see how your answer compares to your classmates!&#160;During the module, see if you think marine transportation is likely to become a more normal part of your life!</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>ratio of mass over volume</p><p>Vaporous Cavitation</p><p>the friction between an object and a gas or liquid</p><p>Cavitation</p><p>the formation and collapse of steam-filled cavities</p><p>Density</p><p>achieving high speeds so that the water vaporizes near the nose and cavitation is continually initiated</p><p>Drag</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>ratio of mass over volume</p><p>Answers for question: 1</p><p>Vaporous Cavitation</p><p>Density</p><p>Drag</p><p>Cavitation</p><p>2.</p><p>the friction between an object and a gas or liquid</p><p>Answers for question: 2</p><p>Cavitation</p><p>Drag</p><p>Vaporous Cavitation</p><p>Density</p><p>3.</p><p>the formation and collapse of steam-filled cavities</p><p>Answers for question: 3</p><p>Density</p><p>Cavitation</p><p>Drag</p><p>Vaporous Cavitation</p><p>4.</p><p>achieving high speeds so that the water vaporizes near the nose and cavitation is continually initiated</p><p>Answers for question: 4</p><p>Cavitation</p><p>Vaporous Cavitation</p><p>Density</p><p>Drag</p><p>supplying gas at the right pressure to create a cavity</p><p>Artificial Cavitation</p><p>cylinder-like flotation devices</p><p>Pontoons</p><p>a sharp edge that generates the cavity</p><p>Cavitator</p><p>encompassing an object in a bubble to reduce drag</p><p>Pulsation</p><p>the sensation created by the shrinking and expanding bubble that exposes part of the object to the water</p><p>Supercavitation</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>supplying gas at the right pressure to create a cavity</p><p>Answers for question: 1</p><p>Artificial Cavitation</p><p>Supercavitation</p><p>Pontoons</p><p>Cavitator</p><p>Pulsation</p><p>2.</p><p>cylinder-like flotation devices</p><p>Answers for question: 2</p><p>Artificial Cavitation</p><p>Pulsation</p><p>Cavitator</p><p>Pontoons</p><p>Supercavitation</p><p>3.</p><p>a sharp edge that generates the cavity</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('17272c848894cec5975d0a442cbcc176','transportation-technologies-m10-l2-lesson-1','88caa25af800d7fb05c4da98a7cd0564','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Drag reduction through Supercavitation</h3><p>Drag reduction through Supercavitation</p><p>While watching this video, pay attention to the relationship between drag and supercavitation.</p><p>Welcome to the Supercavitation module – video 1.</p><p>Let’s start with a “duh” question: Why is it easier to move an object through air than through water?</p><p>The short answer is: friction. Water is simply much more dense compared to air... almost 1,000 times denser, in fact! Density, in case you need a refresher, is the ratio of mass over volume. To simplify it even further, density is how compact something is. A bar of gold is more compact or has greater density, than a feather, for example.</p><p>So this greater density that water has compared to air means that there are more molecules packed tightly and strongly together. Back to our example, when dropped in the water, the molecules in the rock come in contact with more molecules that are more tightly and strongly linked together in water than in air. This creates drag.</p><p>Drag is friction between a solid object and a liquid or gas. So in this case, the drag is the friction between the rock and the air, or the friction between the rock and the water.The drag is greater in water than it is in air.</p><p>Drag is the reason why it&#39;s much harder to run 100 meters through water than 100 meters through air. For submarines, drag is a real, well, drag (cue laugh track ;) because drag becomes even greater the faster you try to go.</p><p>Scientists are working to reduce drag by using a process called supercavitation. But before we get into supercavitation, let&#39;s start by understanding cavitation.</p><p>When a propeller moves through the water, it leaves a trail of bubbles behind it. The bubbles are not filled with air, though, they are filled with steam. The steam is produced because the water is actually boiling.You see, a temperature of 100 degrees Celsius is not the only way to make water boil. Lower pressure causes water to boil at lower temperatures. So when a propeller turns quickly, it creates an area of low pressure on the blades. This low pressure causes the water to boil!</p><p>Although it sounds kind of awesome, it&#39;s usually a bad thing. The bubbles or voids as they are called, implode producing shock waves when they&#39;re subjected to high pressure again. Repeated exposure to imploding voids can cause real damage to metal pieces like propellers.</p><p>Enter supercavitation! Supercavitation takes the principles of cavitation and uses it to reduce drag. Basically, it creates a bubble of steam large enough to encompass an entire object. Since the object is now moving through steam, which is a gas, it is able to travel much more quickly through the water.</p><p>Think about how much easier it would be to run on the bottom of a pool if you were constantly surrounded by a bubble that pushed the water out of the way for you the whole time!</p><p>So how do scientists get the bubble around an object? That is what we will cover in the next section.</p></section><section><h3>Drag, Cavitation and Supercavitation</h3><p>Drag, Cavitation and Supercavitation</p><p>Density and Drag</p><p>Have you ever tried to run while in a pool?&#160;It is MUCH harder than running on land.&#160;When you run on land, you are running through air molecules which are much freer and loosely packed together compared to the molecules in the water.&#160;Air has a density, which is mass over volume, of only 1.225 kg/m3&#160;(or kilogram per cubic meter).</p><p>When you are running through water, there are many more molecules more strongly and closely packed together.&#160;Water has a density of 1,000 kg/m3.&#160;That&#39;s almost 800 times greater than the density of air!&#160;No wonder you have to work so much harder- there is a lot to push through.</p><p>Drag is the friction between an object and a gas or liquid.&#160;The drag is greater in water than air because there is more friction, or resistance due to the strongly linked, compact molecules.</p><p>Cavitation</p><p>Did you know that water can boil without the addition of heat?&#160;If the local pressure is lowered to the point that it is lower than the pressure of the water, bubbles or cavities of vapor will start to form, just like when you heat water to 100 degrees Celsius.</p><p>Cavitation is the formation and collapse of these steam-filled cavities.&#160;The cavities collapse or implode when they move to a place where the local pressure is higher than the vapor pressure.&#160;This collapse triggers a shock wave.&#160;The following video helps illustrate this principle:</p><p>A video showing the Propeller Bubble Cavitation.</p><p>Video Title:&#160;Propeller Bubble Cavitation - 3DynaFS</p><p>Video Publisher:&#160;dynaflowinc</p><p>License:&#160;Creative Commons Attribution license (reuse allowed)</p><p>Note:&#160;There are no closed captions for this video.</p><p>Cavitation happens around propellers.&#160;When a propeller rotates quickly, there is an area of low pressure generated on the blades.&#160;This low pressure causes cavitation.&#160;Repeated exposure to cavitation can actually damage the propellers.&#160;Therefore, scientists and engineers work to find a way to avoid cavitation and the corresponding damage.</p><p>Supercavitation</p><p>Supercavitation is a hydrodynamic phenomenon wherein a cavity or air bubble is formed around an object traveling through a fluid medium, typically water, at high speeds.&#160;The cavity reduces frictional drag, allowing the object to achieve much higher velocities than conventional underwater vehicles.&#160;This technology has potential applications in underwater transportation, torpedoes, and other aquatic systems seeking to attain high speeds and efficiency.</p><p>Watch the video below for a demonstration.</p><p>A video showing a Copy of Gigas0001-0250.</p><p>Video Title:&#160;Copy of Gigas0001-0250</p><p>Video Publisher:&#160;BluePrintRandom</p><p>License:&#160;Creative Commons Attribution license (reuse allowed)</p><p>Note:&#160;There are no closed captions for this video.</p><p>Let&#39;s take a look at some additional key terms related to supercavitation.&#160;Expand each section below to learn about each term.</p><p>Acoustic signature</p><p>The noise or acoustic signals produced by a supercavitating object, which can affect stealth capabilities and detection by sonar systems.</p><p>Boundary layer</p><p>The thin layer of fluid adjacent to <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e696f63da14b7d73ff8146d7741b06cc','transportation-technologies-m10-l3-lesson-2','88caa25af800d7fb05c4da98a7cd0564','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>What and How a Cavitator Work</h3><p>What and How a Cavitator Work</p><p>While watching this video,&#160;try to find the answer to the question:&#160;What is a cavitator?</p><p>Welcome back, this is video 2 of the Supercavitation module.</p><p>Now that you understand the concept of supercavitation, let&#39;s focus on how engineers and scientists are able to make this actually happen. First, you need a specially designed, high speed object, like a torpedo or submarine, for example. The object creates a cavitation bubble at its nose which extends all the way to the back end.</p><p>The nose may be flat like a disk or cone shaped, but it will most likely have a sharp edge- the cavitator. The sharp edge initiates the cavity. Forward facing-vents blow gas, thereby expanding the cavity into a supercavity which envelopes the object. Behind the nose, the object is usually long and slender. This makes it easier for the object to stay cocooned in the bubble. The result is a fast, moving object with significantly reduced drag.</p><p>As long as the object is moving fast enough to initiate cavitation, the bubble can be made bigger by injecting more high-pressure gas near the nose. Of course getting a large object to move fast enough to generate cavitation is a significant hurdle in and of itself. We&#39;ll explore this and other limitations in an upcoming section.</p></section><section><h3>Supercavitation Design</h3><p>Supercavitation Design</p><p>In theory, supercavitation could enable a vessel to reach speeds of 750 miles per hour- that&#39;s crazy fast for something moving through water!&#160;Let&#39;s now look at how engineers and scientists create supercavitation.</p><p>The first step that must happen is for an object must be launched fast enough to generate cavitation.&#160;This is why torpedoes were among the first objects to be supercavitated; they are fast enough for the&#160;physics to work.</p><p>Once you have an object moving fast enough (the actual speed needed depends on the size of the object—the larger the object, the faster it needs to go), the object creates a cavitation bubble at its nose.&#160;The nose is either flat or cone-shaped, and features a cavitator.&#160;The cavitator is a sharp edge that generates the cavity.&#160;To enlarge or extend the bubble, generally, vents near the nose blow gas which expands the bubble over the entire object.</p><p>The object can maintain supercavitation in one of two ways:</p><p>Achieving high enough speeds that the water vaporizes near the nose so that cavitation is continually initiated.&#160;This is known as vaporous cavitation.</p><p>Supplying gas to the cavity at the right pressure.&#160;This is known as artificial cavitation.</p><p>Watch the experiment in the video below:</p><p>close</p><p>The vapor pressure of a liquid depends on temperature and does not depend on the amount of the liquid present. The purpose of experiment 3 is to investigate the temperature dependence of vapor pressure for heptane, toluene and water. This video describes the experiment for one liquid. The other liquids will be investigated by placing a different sample into the flask and following the same steps. Before you begin the experiment, be sure you understand how the lab digital manometer works. The reading on the manometer is the amount the pressure has been reduced below atmospheric pressure. If the atmospheric pressure is 710.0 millimeters of mercury and the manometer reads 650.0 millimeters of mercury, then the pressure in the system is 60.0 millimeters of mercury. To zero, the manometer make sure the vacuum is off, and the system is open to the atmosphere turn on the manometer and push the hold button for two to three seconds. Put acetone and dry ice into the Dewar flask. Make sure the thermometer is in the correct position to measure the temperature accurately. Check the apparatus to make sure all Stoppers are firmly in place. To stopcock&#39;s allow air and vapor to go in and out of the system. One stopcock is situated on the safety bottle. Air will enter the experimental system when this stopcock is open. Along with the safety bottle, this stop is a safety feature of the experimental setup. The other stop is situated on the tubing adjacent to the safety bottle. The path to the vacuum pump is closed when this stopcock is closed. The stopcock is used to control the vacuum during the experiment. The apparatus will now be tested for air tightness. Open the high vacuum tap, open the stopcock that leads to the vacuum and evacuate the system to manometer reading approximately equal to 650 millimeters of mercury. Close the stopcock that leads to the vacuum pump. Observe the manometer reading for about 30 seconds. The system is airtight if there is no change in the manometer reading. Open the stopcock on the top of the safety bottle to fill the apparatus with air. Remove the thermometer and stopper from the flask and fill it to slightly more than 1/3 full with the liquid under investigation. Remember to add boiling chips. We stopped with a flask. Start water circulating through the condenser. Seal the system by closing the stopcock on top of the safety bottle. Open the stopcock that leads to the vacuum and evacuate the system to the highest manometer reading, then close the stopcock that leads to the vacuum tap. If the liquid starts to boil right away, open the stopcock on the safety bottle and let some air in. Apply heat to the flask to bring the liquid to a boil. Adjust the real stat and the lab jack to promote a slow, steady boil. Tapping the flask continually promotes even boiling. Observe the boiling point the liquid is boiling when it is bubbling in the flask, and it drips off the condenser and the thermometer. Simultaneously note the boiling temperature and the manometer reading and record them in your logbook. Open the stopcock on the safety bottle to admit enough air to stop the boiling. The manometer reading should drop by 30 to 50 millimeters of mercury. Continue heating until a new boiling point is reached and recorded. Repeat the procedure until the manometer reading is close to zero and the pressure in the system is close to the atmospheric pressure. Make sure you have a minimum of 7 to 8 boiling points recorded. Open the system by opening the stopcock on the safety bottle, remove the heat source and set it aside. Do not turn it off. Cool the liquid in the boiling flask using an ice-water mixture, if required. Pour the sample i<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('840b070137445168210801f7f71078a1','transportation-technologies-m10-l4-lesson-3','88caa25af800d7fb05c4da98a7cd0564','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Applications of Supercavitation</h3><p>Applications of Supercavitation</p><p>While watching this video, listen for the “game changing” supercavitation technology the Chinese claim to have developed.</p><p>Welcome back, this is video 3 of the Supercavitation module.</p><p>Utilizing supercavitation is a natural fit for the military. In order to create supercavitation, you need a fast moving object; preferably one that is long and slender. Furthermore, once supercavitation is initiated, steering becomes very difficult. What fits the description and isn&#39;t steered once it&#39;s launched? Torpedos!In fact, most uses to date have been for military weaponry like torpedoes and projectiles.</p><p>Another common use is supercavitation propellers. The wedge-shaped propellers are submerged in water where the unique shape generates supercavitation which allows the whole boat to move faster. Since the cavity collapses well behind the entire cavity, there is no damage sustained by the boat when the cavity collapses.</p><p>Interestingly, there is a prototype ship known as The Ghost which glides smoothly and can reach over 50 knots (or miles per hour in sailor lingo). Imagine an enclosed ship on wide skiis and that&#39;s kind of what it looks like!To get a little more technical, the ship uses two pontoons, or tubes, which generate the supercavitation because the propellers are located on the front of the pontoons. When the Ghost gets going over 8 knots, struts lift the main body of the ship out of the water. With the ship out of the water, and the propellers and pontoons supercavitated, the Ghost creates one fast, smooth ride.</p><p>So far that is the fastest and best example of carrying people by means of supercavitation. But another method may be on the horizon.</p><p>Chinese scientists claim to have found a way to supercavitate an entire submarine. When under the water, the submarine would shower itself with a special liquid membrane over the surface of the submarine. Details about the project aren&#39;t very forthcoming at this point, but if it works, a submarine would get you across the Pacific Ocean faster than a jet!</p><p>Of course, engineers still have quite a bit of work cut out for them to make this work. We&#39;ll talk more about the difficulties in the next section.</p></section><section><h3>Objects that can be Supercavitated</h3><p>Objects that can be Supercavitated</p><p>(opens in a new tab)</p><p>Creative Commons&#160;is licensed under&#160;CC BY-SA 4.0(opens in a new tab).</p><p>Torpedoes</p><p>During the 1960s, the Soviets began developing a high speed torpedo.&#160;The goal was to create one capable of gliding through the water at speeds four to five times faster than traditional torpedoes.</p><p>The Shkval (Squall) was a supercavitation torpedo capable of speeding through the water at 230 miles per hour.&#160;Designers gave the torpedo a blunt nose with a ring fitted around it.&#160;The ring acted as the cavitator, initiating supercavitation.</p><p>A German-based defense company also used supercavitation when it developed a torpedo, called Barracuda, capable of reaching 250 miles per hour underwater back in 2004.&#160;Iran also claims to have successfully tested a supercavitation torpedo, called Hoot, in May of 2017.</p><p>The United States military has investigated some supercavitating torpedo projects as well.&#160;But due to the obstacles of supercavitation (which we will investigate later in the module), most torpedo projects have been shelved.</p><p>Propellers</p><p>Propellers are another object that can be supercavitated. As we discussed earlier, cavitation damages propellers. However, when the propellers are wrapped in a supercavitating bubble that collapses behind the propeller, the result is a faster boat, thanks to the reduced friction.</p><p>Supercavitating propellers are uniquely wedge-shaped, a sharp leading edge (the cavitator), blunt tailing edge, and concave face. They also have cavities filled with water vapor and gases. These propellers are meant for use on high-speed boats- those moving at over 50 knots or higher- because these propellers are actually not efficient at slower speeds.</p><p>Ghost</p><p>Juliet Marine Systems, Inc. has developed a boat that uses supercavitation in another way. The ship features two tube-like flotation devices (called pontoons) attached to struts. The tubes contain the engine, fuel, and most computing systems. This reduces vulnerability since those systems are protected by the water itself. The main cavity of the ship remains above the water. The propellers are attached to the front of the tubes. The propellers funnel air down through the struts which generate the supercavitation effect around the pontoons.</p><p>Once the ship starts going faster than 8 knots, the struts lift the main cabin of the ship above the water. This means that both the cabin and the pontoons have significantly less drag than traditional boats in water.</p><p>It is called the Ghost because thanks to its stainless steel and aluminum construction, it is nearly invisible to radar and sonar detection. It is designed with military use in mind. The Ghost is capable of missions including anti-surface warfare, anti-submarine warfare, and mine countermeasures.</p><p>Liquid Membrane Technology</p><p>You may have noticed that we have not mentioned any supercavitated submarines. Getting a submarine to go fast enough to generate cavitation is one of the main problems. However, the Chinese claim to be on the path to supercavitating an entire submarine.</p><p>To do so, a submarine first becomes submerged in water. Then, the submarine would shower itself in a liquid membrane all over the surface. The liquid membrane is said to cut down the minimum speed required to enable supercavitation.</p><p>Unlike the other examples of supercavitation we have investigated so far, the Chinese are looking at this not so much with military intentions, but rather civilian transport. If the technology works out, a submarine may get you across the ocean faster than an airplane!</p><p>Next Tab</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a72dba77ed790b59e07f52ab618f8b4e','transportation-technologies-m10-l5-lesson-4','88caa25af800d7fb05c4da98a7cd0564','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Problems with Supercavited Objects</h3><p>Problems with Supercavited Objects</p><p>While watching this video, see if you can think of any remedies or solutions to the problems of supercativation.</p><p>Welcome back, this is video 4 of the Supercavitation module.</p><p>If the Soviet Union developed a supercavitating torpedo decades ago, why are supercavitation torpedoes not the norm today? Like most technologies, the benefits of supercavitation come with tradeoffs.</p><p>First, the Shkval had a short range. Shorter even then the torpedoes of the day. Range has always been an issue for supercavitation. It&#39;s hard to get to and maintain the necessary speeds needed for supercavitation.</p><p>Second, it was noisy, thanks to the hydrojet it used once the booster rocket ran out of fuel to keep it supercavitated. “Noisy” and “weapon” are not a desirable combination because then other boats would hear it coming and be able to move or neutralize the threat.</p><p>Third, the Shkval could not track its target. Since the torpedo traveled in a bubble, the sonar detector needed to be mounted to the cavitator which was too small to fit such a device. This means that the only way for the Shkval to be successful is for the target to stay put once the torpedo is launched. Of course with the supercavitating torpedo being so fast, this is not entirely out of the question. But it is a hurdle nonetheless, especially since the thing was so darn noisy too.</p><p>What about entire submarines using supercavitation? Why aren&#39;t there any of those swimming around? Most of the problems overlap with those we just went over for supercavitationtorpedos. Similar to the speed and range issue, for example, getting a submarine to go fast enough to create supercavitation is NOT easy. Submarines are built to be stealthy, not cruise through water at the speed of a supersonic jet. Getting a submarine to go fast enough for supercavitation to happen would require rethinking the whole design and fueling system of the submarine.</p><p>The noise is another issue. Maintaining a huge bubble over an entire submarine would be very noisy. For war submarines, this is an issue considering submarines whole purpose is stealth. Perhaps one of the solutions to this problem is for submarines to use supercavitation to sprint out of the base and then switch to a slower, stealthier mode at a certain point.</p><p>Another problem would be the impact on the environment. As I mentioned, supercavitationtorpedos use rocket motors. If submarines used this, it would create huge amounts of pollution that would be left in the ocean water.Not to mention the disruption it could cause to ocean life. Can you imagine what would happen to a pod of fish when a supercavitation submarine comes speeding its way? I can&#39;t imagine it ending happily for the fish. Then again, maybe the noise factor, which is commonly thought to be a problem with supercavitation, is actually a good thing. For the fish anyway, it might give them a fighting chance to get out of the way!</p><p>Oh, we&#39;re not done listing problems yet! Another issue is called pulsation. Pulsation is the continual expansion and shrinkage of the bubble that happens during supercavitation. It&#39;s a problem because it might cause instability. When the bubble shrinks, it can cause part of the ship to get wet. If that happens, you get a very bumpy ride. This is a problem that scientists are working to fix.</p><p>Finally, supercavitation makes it extremely difficult to steer a submarine. To steer, control planes would have to pierce the bubble, producing great drag in the process. And at the high speeds generated by supercavitation, these planes would have to be extraordinarily strong otherwise they&#39;d just snap off like little toothpicks.</p><p>Now if the Chinese liquid membrane technology turns out to do all they claim it can do, then many of these problems- such as getting up to the speed needed for supercavitation and steering- will no longer be an issue. So be on the lookout for news and updates about this technology in the future.</p></section><section><h3>Supercavitation Difficulties</h3><p>Supercavitation Difficulties</p><p>We&#39;re pretty sure that if engineers and scientists could develop a technology that had no negative tradeoffs whatsoever, we&#39;d see a bunch of brilliant minds weeping with joy.&#160;But as it stands, no technology is without its drawbacks, and supercavitation is no exception.</p><p>Press each tab below for a breakdown of why supercavitation is not more common:</p><p>Limited range</p><p>Limited range:&#160;to achieve supercavitation, an object has to be moving fast enough to generate the bubble.&#160;Like we talked about in the first section, it is not easy to move through water, thanks to its resistance.&#160;Then, once the speed is achieved, it is difficult to maintain that speed for an extended amount of time.&#160;This means that the realistic range of a supercavitation object is limited.</p><p>Noisy</p><p>Noisy: with the Shkval torpedo, once the booster rocket ran out of fuel, the torpedo switched to a noisy hydrojet to keep going. Needless to say, the military has limited interest in noisy weaponry.</p><p>Cannot track target</p><p>Cannot track target: to track a target, a torpedo uses a sonar detector. Those detectors would need to be mounted on the cavitator, which for the way the Shkval was designed, was too small to fit on it. If the torpedo can&#39;t track the target, the only hope is for the target to stay put. Since a supercavitation torpedo is so fast, it actually could happen that the torpedo gets to the target before it&#39;s able to move, but it&#39;s still a drawback in warfare.</p><p>Environmental impact</p><p>Environmental impact: if submarines have to use rocket fuel the way that supercavitation torpedoes do, it would be devastating to marine life. All that rocket fuel exhaust would be dumped right into the ocean.</p><p>Pulsation</p><p>Pulsation: sometimes during supercavitation, the bubble shrinks and expands. When the bubble shrinks, it can expose part of the object to the water. Pulsation is the continual expansion and shrinkage of the bubble that happens during supercavitation. If this happened to a submarine, anyone on board would be taking a very bumpy ride. This is a problem scientists at Penn State are working to overcome.</p><p>Lack of steering</p><p>Lack of steering: To steer, control planes would have to pierce th<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('40ee1b788040671cafc7c7f07968cbb9','transportation-technologies-m10-l6-lesson-5','88caa25af800d7fb05c4da98a7cd0564','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Future Autonomous Ships</h3><p>Future Autonomous Ships</p><p>While watching this video, look&#160;for applications of other technologies (solar power, autonomous technology) that are making their way into maritime transportation.</p><p>Welcome back, this is video 5 of the Supercavitation module.</p><p>When you think of someone traveling from England to New York by boat, you probably think of someone making the journey about 200 years ago, right? Airliners are so fast and efficient, that we don&#39;t even think of traveling great distances by boat, unless it&#39;s on a cruise ship, of course.</p><p>But here&#39;s the thing: airplanes can&#39;t carry thousands of passengers or extremely heavy cargo. Boats are still the premiere heavyweight transporters. For that reason, engineers and ship designers are working to create boats that are more eco-friendly, larger, and more efficient to meet the demands of the future. Let&#39;s take a look at a couple ships of the future.</p><p>A cruise operating company called MSC Cruises signed an order with ship manufacturer STX France for two cruise ships, with the option for two more. The four ships will become MSC Cruises&#39; World Class. These mega cruise ships will be powered by liquefied natural gas- or LNG. In addition to the LNG-powered engines, the ships will also feature a new generation waste water treatment system.Interestingly, the boat will be shaped like a Y which will enable panoramic ocean views as well as offer more balcony rooms. It will also feature a “G bow” positioned vertically at 90 degrees for better stability, hydrodynamics, and guest comfort. Other cool features include a glass pool lounge, family- friendly villages, and a panoramic aft.</p><p>If you&#39;re interested in giving this ship a try, you and 6,849 of your closest friends can book a cruise in 2022.</p><p>When you think of Rolls-Royce, what do you think of? A car?Maybe a jet engine?Probably not ships. Well, that might change in the not-too-distant future.</p><p>Rolls-Royce has announced plans to develop an autonomous ship. These sea-drones will act as “scouts,” scoping out what is ahead. Possible missions for the ship include surveillance, patrolling, mine detection, and fleet screening.</p><p>While it might sound like creating an autonomous ship means removing humans from the setup, that is not the case at all. The unmanned ships will still need monitoring. Land-based control centers will enable small teams to be able to monitor ships across the world. With interactive smart screens, holograms, drones, and voice recognition systems, the control center will be like something straight out of a science fiction movie.</p><p>Hopefully by now you can see that the future of transportation isn&#39;t just limited to the land and sky. New technology is going to affect every aspect of transportation, including the sea.</p></section><section><h3>Future of Maritime Transportation</h3><p>Future of Maritime Transportation</p><p>We have spent the majority of this module looking at supercavitation.&#160;We&#39;d be remiss, however, if we did not look at the future of maritime transportation on the whole.</p><p>There are some key technological advancements that are spilling over into the future of maritime transportation.&#160;One of those is autonomous technology.</p><p>The future of maritime transportation is poised for significant advancements and transformations driven by emerging technologies, environmental concerns, and changing global trade dynamics.&#160;Take a look at some key trends and developments that will shape the future of maritime transportation by expanding each section below.</p><p>Digitalization and Automation</p><p>The maritime industry is embracing digital technologies and automation to enhance efficiency, safety, and sustainability. Automation in ship operations, including autonomous vessels and remote-controlled systems, is expected to reduce human error and optimize vessel performance.</p><p>Smart Ports and Logistics</p><p>Ports are becoming more technologically advanced, incorporating Internet of Things (IoT) devices, artificial intelligence (AI), and data analytics to streamline cargo handling, improve vessel traffic management, and optimize supply chain logistics.</p><p>Green Shipping</p><p>The maritime industry is under increasing pressure to reduce its environmental impact. The future of maritime transportation will see a transition toward cleaner fuels, such as LNG (liquefied natural gas), biofuels, and the adoption of zero-emission technologies like hydrogen fuel cells and battery-electric propulsion.</p><p>Emission Reduction and Regulations</p><p>Stricter environmental regulations are driving the adoption of eco-friendly technologies, emissions monitoring, and reporting systems. The International Maritime Organization&#39;s (IMO) sulfur and carbon emission regulations are already influencing vessel design and operations.</p><p>Decentralized and Autonomous Shipping</p><p>Advances in AI, communication technologies, and blockchain are paving the way for decentralized shipping networks, enabling autonomous vessels to coordinate and operate independently with minimal human intervention.</p><p>Arctic Shipping</p><p>As Arctic ice melts due to climate change, new shipping routes are opening up, leading to increased interest in Arctic navigation. However, this raises concerns about environmental impacts and the need for stringent regulations to protect the sensitive ecosystem.</p><p>Digital Twinning</p><p>The use of digital twin technology, where physical ships are replicated as virtual models, allows for real-time monitoring, predictive maintenance, and performance optimization, leading to cost savings and improved vessel reliability.</p><p>Alternative Propulsion Systems</p><p>Maritime transportation is exploring various alternative propulsion systems, such as wind-assisted propulsion (e.g., sail technology), solar panels, and air lubrication systems, to reduce fuel consumption and emissions.</p><p>Unmanned Surface Vehicles (USVs)</p><p>USVs are gaining traction for various applications, such as surveying, environmental monitoring, and surveillance. They offer cost-effective and versatile solutions for data collection in maritime environments.</p><p>Advanced Navigation and Collision Avoidance</p><p>The future of maritime transportation will involve more advanced navigation systems, including satellite-based technologies, to enhance vessel s<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7d3c8ad47854f9647b2c8fded3e23a27','transportation-technologies-m10-l7-module-10-summary','88caa25af800d7fb05c4da98a7cd0564','Module 10 Summary','text',12,'<h2>Module 10 Summary</h2><section><h3>Module 10 Summary</h3><p>Module 10 Summary</p><p>byAndriiSymonenko</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Supercavitation (and other maritime transportation technologies)!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Defined density, drag, cavitation and supercavitation</p><p>Differentiated between vaporous and artificial cavitation</p><p>Identified historical and future use cases for supercavitation</p><p>Discussed problems associated with supercavitation and potential solutions</p><p>Identified and described other futuristic marine transportation such as autonomous and fuel-efficient ships</p><p>Created a business plan for a company that utilizes supercavitation</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0b6f3db7f7b351b38898f201508882c2','transportation-technologies-m10-l8-module-10-assignment','88caa25af800d7fb05c4da98a7cd0564','Module 10 Assignment','text',12,'<h2>Module 10 Assignment</h2><section><h3>Module 10 Assignment</h3><p>Module 10 Assignment</p><p>Transportation</p><p>Supercavitation - Short Answer Assignment</p><p>Short answer assignment</p><p>Create a business plan of a company that utilizes supercavitation. Be as creative as you want. Some general topics for ideas could include: making products (submarines, torpedoes) for the military, tourism, package delivery and transportation. Answer the following questions in a two-page, double-spaced paper:</p><p>What is your company’s name (this is the most important part!)?</p><p>What products or services does your company provide?</p><p>Who are your potential customers? How would this business make money?</p><p>What engineering or technical problems need to be addressed before your business idea is feasible?</p><p>Review the rubric below to see how you will be graded.</p><p>Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('56bd5e3b2437bc3e468e15c9f627aaeb','transportation-technologies-m10-l9-module-10-project','88caa25af800d7fb05c4da98a7cd0564','Module 10 Project','text',12,'<h2>Module 10 Project</h2><section><h3>Module 10 Project</h3><p>Module 10 Project</p><p>Transportation</p><p>Supercavitation - Project</p><p>Project</p><p>In this assignment, you will create a chart to compare the pros and cons of pursuing the use of supercavitation in submarines. You can make a T-chart, table, or any other format that clearly organizes short descriptions of the pros and cons of each type of headset.</p><p>After creating the chart, write a two-paragraph conclusion discussing whether you think this technology is something that should be pursued, and why.</p><p>Review the rubric below to see how you will be graded.</p><p>Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Diagram</p><p>8 points The chart includes at least three valid statements in each pro and con category, and the chosen information demonstrates a strong understanding of supercavitation.</p><p>7-6 points The chart includes at least two valid statements in each pro and con category, and the chosen information demonstrates an adequate understanding of supercavitation.</p><p>5-0 points The chart includes less than two valid statements in each pro and con category, and the chosen information demonstrates little to no understanding of supercavitation.</p><p>8</p><p>Conclusion</p><p>8 points The conclusion effectively explains the opinion of whether the technology is worth developing and includes relevant support and explanation.</p><p>7-6 points The conclusion sufficiently explains the opinion of whether the technology is worth developing and includes some relevant support and explanation.</p><p>5-0 points The conclusion does not effectively explain the opinion of whether the technology is worth developing and includes little to no support and explanation.</p><p>8</p><p>Formatting</p><p>2 points Chart and conclusion are both clear and well organized.</p><p>1 point Chart and conclusion are mostly organized.</p><p>0 points Chart and conclusion are not organized.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c5d549faa7e7c09e42b6bf7e92892b8b','transportation-technologies-m10-l10-module-10-quiz','88caa25af800d7fb05c4da98a7cd0564','Module 10 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Supercavitation. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('babf506f0e9b677ca95eeabb56a80afd','transportation-technologies-module-11','504e3ab88df8552a07116f12aea44099','Module 11: Space Travel',11) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('17d4ca0714945f844479c83a52f27835','transportation-technologies-m11-l1-introduction-purpose-and-objectives','babf506f0e9b677ca95eeabb56a80afd','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>We&#39;ve explored the future of transportation on land, in the air, and under the sea, but there&#39;s still one exciting area left to explore- space. This module is all about space travel- the pros, the cons, and the companies and governments that are daring enough to take on the challenges.</p><p>Module Description</p><p>by NASA</p><p>License:&#160;Public Domain</p><p>Have you ever been to outer space?&#160;Do you know anyone who has been to outer space?&#160;Do you know&#160;anyone&#160;who knows someone who has been to outer space?&#160;We&#39;re guessing your answer is no.&#160;Why is it that nearly 50 years after man first walked on the moon that space travel remains so rare?</p><p>In this module we will briefly discuss the history of space exploration and the benefits and cost associated.&#160;We&#39;ll also define words and terms related to rockets and space travel.&#160;Then we&#39;ll take a closer look at reusable rockets- how they would benefit the space industry and what challenges go into creating one.&#160;Next, we&#39;ll discuss companies that are developing commercial space travel.&#160;Finally, we&#39;ll explore careers in the space travel industry.</p><p>Objectives</p><p>In this module, students will</p><p>Outline the history of space travel and contrast past technological changes with current opportunities</p><p>Analyze the political history of space travel and its impact on innovation.</p><p>Discuss the challenges space travel has faced over the last century and the solutions which overcame them</p><p>Construct a timeline of innovation, technological advances, historical turning-points, successes, and failures within the last century identifying prominent figures which impacted space travel</p><p>Preview the goals, plans, and possibilities for space travel over the next 50 years, including moon and Mars exploration, space tourism, and asteroid mining</p><p>Polling Question</p><p>When do you think people will start taking vacations to outer space?</p><p>Before 2030&#160;2030-2040&#160;2040-2050&#160;After 2050&#160;Never</p><p>Make a selection to see the results so far.</p><p>How did your prediction compare to your classmates?&#160;Let’s see how your answer changes as your learn more about space travel!</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition. This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>for every action, there is an equal and opposite reaction</p><p>Newton&#39;s Third Law of Motion</p><p>type of chemical which a fuel requires to burn</p><p>Oxidizer</p><p>a reusable launch vehicle which would launch a payload into orbit, renter the earth&#39;s atmosphere, land, refueled, and the process repeated</p><p>Orbit</p><p>the curved path of a space object or spacecraft around a star, moon, or planet</p><p>Single stage to orbit</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>for every action, there is an equal and opposite reaction</p><p>Answers for question: 1</p><p>Orbit</p><p>Single stage to orbit</p><p>Newton&#39;s Third Law of Motion</p><p>Oxidizer</p><p>2.</p><p>type of chemical which a fuel requires to burn</p><p>Answers for question: 2</p><p>Newton&#39;s Third Law of Motion</p><p>Single stage to orbit</p><p>Oxidizer</p><p>Orbit</p><p>3.</p><p>a reusable launch vehicle which would launch a payload into orbit, renter the earth&#39;s atmosphere, land, refueled, and the process repeated</p><p>Answers for question: 3</p><p>Oxidizer</p><p>Single stage to orbit</p><p>Orbit</p><p>Newton&#39;s Third Law of Motion</p><p>4.</p><p>the curved path of a space object or spacecraft around a star, moon, or planet</p><p>Answers for question: 4</p><p>Oxidizer</p><p>Single stage to orbit</p><p>Orbit</p><p>Newton&#39;s Third Law of Motion</p><p>also known as low earth orbit. An orbit around the earth with less than 1,200 miles in altitude</p><p>Reusable rocket</p><p>a rocket composed of parts which have been previously used</p><p>International Space Station</p><p>An earth-orbiting space craft which is the result of international cooperation</p><p>Near earth orbit</p><p>the rocket&#39;s carrying capacity for things like crew, cargo, scientific instruments, and other equipment</p><p>Payload</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>also known as low earth orbit. An orbit around the earth with less than 1,200 miles in altitude</p><p>Answers for question: 1</p><p>Reusable rocket</p><p>Near earth orbit</p><p>International Space Station</p><p>Payload</p><p>2.</p><p>a rocket composed of parts which have been previously used</p><p>Answers for question: 2</p><p>International Space Station</p><p>Payload</p><p>Near earth orbit</p><p>Reusable rocket</p><p>3.</p><p>An earth-orbiting space craft which is the result of international cooperation</p><p>Answers for question: 3</p><p>Near earth orbit</p><p>Payload</p><p>Reusable rocket</p><p>International Space Station</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3301d7d91ff463f6ea43c0f9fa916550','transportation-technologies-m11-l2-lesson-1','babf506f0e9b677ca95eeabb56a80afd','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Current and Previous effort for Space Travel</h3><p>Current and Previous effort for Space Travel</p><p>Consider the following question as you watch the video:</p><p>What things do you use in your daily life that have their origins based in space technology?</p><p>Welcome to the Space Travel module – video 1.</p><p>In order to talk about where we as humans are going with space travel, let&#39;s first review where we&#39;ve been. Let&#39;s talk briefly about this history of space travel.</p><p>We&#39;ll start with October 3, 1942. World War II was raging on when Nazi Germany launched the V2 rocket. This was the first rocket to successfully reach the boundary of space, or 100 kilometers from the ground.</p><p>In 1957 the Soviet Union launched the satellite, Sputnik. It was the first satellite to orbit the earth. Today, satellites influence what we see on tv, our ability to communicate, how we pay for things, and even our ability to access the internet. Back then, what Sputnik did was usher in the age of intense space exploration, particularly in the USA.</p><p>Now you may be interested to know that before any person first got a view of space, a monkey, dogs, rabbits, mice, and rats all got that view first before any country dared to send a person.</p><p>While the first monkey was sent to space in 1949, it wasn&#39;t until 1961 that a man named Yuri Gagarin of the USSR became the first human in space. The US sent also sent a man to space just a few weeks later.</p><p>Now that people were able to go to space, and more importantly, return to tell the tale, the focus of space exploration turned to getting humans to the moon. On July 20, 1969 the Apollo 11 mission did just that. Neil Armstrong and Buzz Aldrin became the first humans to set foot on the moon. Five more Apollo missions landed on the moon between 1969 and 1972.</p><p>In 1971, the USSR launched Salyut 1 which was the first space station. America followed suit and launched their own space station in 1973.</p><p>Voyager 1, a probe, was launched in 1979. Today, Voyager 1 is the farthest human made object from the earth!Now let&#39;s jump to 1998 when the US, Canada, Japan, Russia, and 11 European nations collaborated to create the international space station. The first part was launched that November.</p><p>Finally, let&#39;s conclude with April 28, 2001 when American Dennis Tito became the first tourist in space. He paid the Russian space program a whopping 20 million dollars to join along on an 8 day orbit in space.</p><p>Humans have explored space for over 6 decades now. Have you ever stopped to think about how the impact space travel has had on your life? True, you&#39;ve probably never been to space or even known someone who has, but that doesn&#39;t mean you haven&#39;t benefited from space travel.</p><p>Have you ever noticed that some cement stairs, parking lots, and roads have grooves cut into them? This safety grooving helps increase traction to prevent injury. The technique was first developed and tested by Langley Research Center, a component of NASA.</p><p>If you&#39;ve enjoyed a good night’s sleep on a temper foam or “memory foam” bed or pillow, you have another NASA research center to thank. The technology was originally developed to provide passengers with more padding in the event of an airplane crash. It&#39;s soft and high energy absorbing properties make it ideal for padding. Today, it is used in mattresses, pillows, cars, prosthetic, and sports safety equipment- just to name a few.</p><p>One of the challenges to long-term space exploration missions is maintaining basic supplies like water. As scientists have worked to develop water purification system that turns waste water into purified drinking water. This technology has benefited underdeveloped regions with contaminated water.</p><p>The list of products and systems that have their roots in space technology is longer than we have time to cover. But some of the greatest developments to come from our 50 years of space exploration aren&#39;t tangible objects.Space exploration is a world-wide endeavor. It acts as a starting ground for countries to develop relationships and cooperation. Perhaps the greatest example of this is The International Space Station (or ISS). Over 60 nations have participated in ISS activities. Due to costs, this unique laboratory would not be available to any one nation, but through partnerships, the program benefits all invested nations.</p><p>Space exploration also supports innovation and economic prosperity. The company, SpaceX alone employs over 5,000 people (according to their website). As SpaceX and similar companies grow, it will increase our economic activity. Space transportation systems, planetary mining for resources, and space tourism could grow from these companies. As these things grow, so will the need for qualified teams and individuals to provide the technology and support necessary.</p><p>In 1968 a photograph was taken of the Earthrise as seen from lunar orbit. That photograph became an iconic symbol for space&#39;s ability to alter our perception of our place in the universe. When seen from the moon, things like political boundaries seemed trivial, and it provided even further support to the truth that life on earth is precious and fragile.The developments to come from space exploration in the next 60 years will be exciting to see and be a part of.</p></section><section><h3>The journey of Space Travel Initiatives</h3><p>The journey of Space Travel Initiatives</p><p>License:&#160;All Rights Reserved</p><p>Traveling to the Moon in Literature</p><p>From the moment they could observe the stars, humans have been fascinated by outer space.&#160;It’s not surprising then that many would choose to write stories about building machines to travel there.&#160;Here are some novels among the most accurate at predicting the future.</p><p>In 1608, German mathematician and astronomer Johannes Kepler wrote the novel&#160;Somnium, which means the dream in Latin.&#160;In the story, a 14-year-old Icelandic boy named Duracotus learns about astronomy and is told of a pathway between the Earth and the Moon through which humans can be pushed.&#160;During the trip, humans must be sedated, protected against the cold and wear damp sponges in their nostrils to be able to breathe.&#160;This remarkable story was no doubt inspired by the great scientific advancements of the 17th&#160;century and it describes the two sides of the Moon,<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2c0703320c76a47b12d7369e88c7a966','transportation-technologies-m11-l3-lesson-2','babf506f0e9b677ca95eeabb56a80afd','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Challenges in getting People to Outer Space</h3><p>Challenges in getting People to Outer Space</p><p>While watching, think about the challenges scientists and engineers face in getting people to outer space.</p><p>Welcome back, this is video 2 of the Space Travel module.</p><p>After a successful trip to the moon, many people speculated that it wouldn&#39;t be long before humans walked on Mars too. But Mars still remains unexplored by anything more than rovers, and only a handful of people have set foot on the moon. The truth is, space travel is almost just as challenging today as it was decades ago. Why is that?</p><p>Well, a big portion of that answer is because humans haven&#39;t changed. We still need air to breath, food to eat, and water to drink. Our bodies still start to atrophy, or waste away, after extended amounts of time in zero gravity. Radiation, which is extremely potent in space, is still as deadly as ever to our bodily systems. In short, space is not human friendly.</p><p>To be able to handle the dangers of space takes a huge amount of extremely careful planning. The rockets must be in top condition. Even when we think we have checked, double checked, and triple checked everything, The Challenger and Columbia space shuttles are harsh reminders that something as simple as a seal or a piece of insulation can have deadly consequences if not properly working.</p><p>Then there&#39;s the question of what will we find when we get where we are going. For example, the atmosphere on Mars is much more dynamic compared to the atmosphere on earth. For a spacecraft carrying humans, it would take an entry, decent, and landing (EDL) capable of handling ten times the mass and volume of what the current vehicles that carry robots to Mars are capable of carrying.</p><p>But before that happens, scientists have to figure out the best way to get humans there and back in the first place. That&#39;s the biggest hurdle- how to carry enough fuel for that kind of mission? More fuel makes the spacecraft heavier. A heavier spacecraft means more fuel is needed. And around and around the cycle goes.</p><p>Then there&#39;s the NASA&#39;s budget- or budget cuts- I should say, which is a real limitation. Development is very much tied to the budget. One of the possible solutions is to work together with other nations, and with private companies, to send a human crew to Mars.</p><p>Another solution is reusable rockets. Not having to start from scratch to build a rocket could cut down on the tremendous cost it takes to build a rocket. We will talk more about the idea of reusable rockets in the next section.</p></section><section><h3>Pros &amp; Cons of Space Travel Privatization</h3><p>Pros &amp; Cons of Space Travel Privatization</p><p>License:&#160;All Rights Reserved</p><p>A Middle Ground?</p><p>While there are those who think that space travel should be left to governmental agencies, the reality is that shrinking budgets and the imposed need to turn a profit has meant that, even at NASA, there is a growing appetite to outsource some of their mundane tasks.&#160;If you think about it, a resupply mission to the ISS is just the space version of truck delivery.&#160;Once you have the technology figured out, it becomes routine.&#160;Robert Frost is an instructor and flight controller at NASA.&#160;In an interview, he said that a lot of work could be outsourced but that companies weren&#39;t interested in pursuing work in which they may not see profits for quite some time.</p><p>The Dangers of Privatization in One Story</p><p>When you cut budgets and you insist on money-saving decisions, you can wind up with some funny, unintended consequences.&#160;Take the decision to end the Saturn rocket program for example.&#160;It effectively left the USA and NASA with no heavy lift rockets, the kind you need to launch satellites into space after the Space Shuttle program was stopped.&#160;The only solution is to buy seats on rockets launched by the Russians.&#160;This has become necessary because the replacement programs, by Boeing and SpaceX, are not ready yet.</p><p>An equally odd situation is that the engines that power the US Atlas V rockets, which are used to launch satellites, are bought from Russia.&#160;The RD-180 Engine is designed and manufactured in Russia and is very inexpensive compared to comparable engines manufactured in the USA.</p><p>(opens in a new tab)</p><p>License:&#160;United States Government Work</p><p>These purchases are not without controversy, the late Senator John McCain actively tried to block the use of these engines and tried to pass laws and funding amendments to force NASA to use US manufactured engines or US-based space companies like Space X.</p><p>Privatization of Space Travel</p><p>You already know that the privatization of space travel refers to the involvement of private companies in the development, funding, and operation of space exploration missions, spacecraft, and related services.&#160;Traditionally, space travel was primarily undertaken by government agencies such as NASA (National Aeronautics and Space Administration) in the United States and Roscosmos in Russia.&#160;However, in recent years, there has been a significant rise in private companies entering the space industry, aiming to offer commercial space travel, satellite launches, and other space-related services.</p><p>Examples of privatized space travel initiatives include:</p><p>SpaceX:&#160;Founded by Elon Musk in 2002, SpaceX has become one of the most prominent private space companies.&#160;It has developed the Falcon 1, Falcon 9, and Falcon Heavy rockets, as well as the Dragon spacecraft.&#160;SpaceX has successfully delivered cargo to the International Space Station (ISS) and is actively working on the development of the Starship, a fully reusable spacecraft intended for crewed missions to the Moon, Mars, and beyond.</p><p>Blue Origin:&#160;Founded by Jeff Bezos in 2000, Blue Origin focuses on developing technologies for human spaceflight and building a future in which millions of people can live and work in space.&#160;Blue Origin&#39;s New Shepard rocket has completed several successful suborbital test flights with the goal of carrying tourists to the edge of space.</p><p>Below, read about some pros and cons of the privatization of space travel.&#160;Expand each section.</p><p>Pros</p><p>Innovation and Competition: Private companies bring innovation and competition to the space industry,<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('159678bd16d1ccd9bc859c17cb3eae3e','transportation-technologies-m11-l4-lesson-3','babf506f0e9b677ca95eeabb56a80afd','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>How Rockets Move Upwards</h3><p>How Rockets Move Upwards</p><p>While watching, pay attention to what Newton&#39;s Third Law of Motion states and its relationship to rockets.</p><p>Welcome back, this is video 3 of the Space Travel module.</p><p>I want you to imagine a fireman who is fighting a fire with a hose. With water blasting out of the hose at extremely high pressures, the fireman has to hold on tight to the hose and brace his feet on the ground to keep from getting knocked over. Why is that? Now think about a goldfish swimming in a tank. To go forward, the goldfish uses its fins to push water behind it. Both the fire hose and goldfish are examples of Newton&#39;s third law of motion which states that for every action, there is an equal and opposite reaction.</p><p>When the water comes out of the hose at high pressure, the opposite reaction is that the hose pushes back with the same force on the fireman. In the example of the goldfish, the goldfish pushes the water behind it and the water pushes back with equal force, moving the fish forward.</p><p>Great, so what does Newton&#39;s third law of motion have to do with space travel? Well, burning rocket fuel causes exhaust to exit out the back of the rocket, and as an equal and opposite reaction, thrust is produced at the front of the rocket, propelling it forwards.</p><p>To get a little more detailed, in a rocket engine, exhaust gas is produced through combustion. Combustion is the chemical reaction of a fuel and an oxidant. Once combustion happens, the hot exhaust rushes out the back of the rocket. As a reaction, a thrusting force is generated on the engine mount. This thrust accelerates the rocket. That&#39;s why a rocket is able to move forward in space where there is no gravity. The thrust of the rocket is not dependent on pushing against something external.How far a rocket can go is related to how much fuel is contained inside the engine as well as the qualities of that fuel.</p><p>Now that you have an overview of how rockets move, let&#39;s talk a little bit about rocket engines and why rockets, not jets, can go to space. This will be a little bit of a review from the module about jet packs and rocket belts. But it&#39;s worth repeating here. Jets intake oxygen from the air to burn fuel. Rockets, on the other hand, carry their own oxygen. That is why rockets, but not jets, can travel into space. A rocket carries the oxygen with it, so that even if there is no oxygen- like in outer space- the rocket can still work.</p><p>Now that you have a basic understanding how rockets work, let&#39;s talk about the concept of “reusable rockets.” According to Boeing&#39;s website, a single 747 airplane costs about roughly 300-400 million dollars. That&#39;s just to buy it. Then you have to fuel it and pay someone to fly it. The average airborne cost of a Boeing 747 is about $24,000-$27,000 PER HOUR! With prices like that, how is it that any of us can afford to fly ever?</p><p>The reason plane tickets don&#39;t generally cost hundreds of thousands of dollars or more is because planes are reusable. They may not make their profit back on the first passenger or cargo flight, but over time, they will make that money back and then some.</p><p>One of the biggest hurdles standing in the way of space travel is the cost associated with rockets. When the space shuttle program was running, it cost over one and a half billion dollars per launch, for a total of over 200 billion dollars in its lifetime.With these kinds of prices, no wonder companies are looking into reusable rockets. Similar to the concept of “reusing” an airplane over and over, if a company can reuse all or even some of the rocket parts, that could mean significant cost savings. More cost savings means potentially more space travel. More space travel means more knowledge gained.</p><p>The ideal reusable rocket is known as the single stage to orbit vehicle, or SSTO vehicle. The concept is to use a reusable launch vehicle which has the ability to launch a payload into orbit, renter the earth&#39;s atmosphere, and land. Then it can be refueled and the process repeated.</p><p>Remember that a rocket carries all its own fuel and oxidizing agent with it. This means that rockets have to find the perfect balance between mass of fuel, the supporting vehicle, and the payload itself.</p><p>Currently, the only way rockets achieve orbit is by stripping away the mass of the support structure and fuel tanks as the fuel empties. The final payload is approximately 2-4% of the original mass, pre-launch. This happens in steps, like for SpaceXs&#39; Falcon 9-R, or all at once, like NASA&#39;s Space Shuttle.</p><p>The Space Shuttle attempted to recover and reuse the orbiter and solid rocket boosters, but the refurbishing costs ended up being so high that any money saved was hardly worth the effort. Plus, there were a few devastating accidents that left many people questioning the safety and reliability of reusable rocket parts.</p><p>Recently, private company SpaceX has made great strides in reusable rocket technology. They launched a partly used rocket into orbit at a lower cost than a new rocket. This is a big step toward making commercial rocket launches economically feasible.</p><p>However, SpaceX still has a long way to go. If people feel anxious buying a used car, imagine how much more convincing it will take to make people comfortable with the idea of a used rocket. SpaceX is going to have to prove not just once or twice, but many times that a partly used rocket can fly into orbit safely and reliably. They will have to demonstrate that this can be done without compromising that delicate balance of fuel, support, and payload.</p></section><section><h3>Main Challenges Facing Space Travelers</h3><p>Main Challenges Facing Space Travelers</p><p>License:&#160;No known copyright restrictions</p><p>What do you think are the main challenges facing space travelers?&#160;In its&#160;Time and Navigation:&#160;The untold story of getting from here to here&#160;online series, the Smithsonian lists four major challenges space navigators must overcome.&#160;Press each tab below.</p><p>Motion</p><p>Imagine trying to jump on a wobbly log whilst you&#39;re swinging from a rope with your head upside down.&#160;Would you make it?&#160;Whether you hit the target or not, it would give you a good sense of what astronauts have to deal with.&#160;In space, not only is the ship moving, but your target is also<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8c73214d16c62a7099764bb9167359b8','transportation-technologies-m11-l5-lesson-4','babf506f0e9b677ca95eeabb56a80afd','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Current Companies in Space Travel Offering</h3><p>Current Companies in Space Travel Offering</p><p>As you watch the video below, think about how space travel could change in your lifetime.</p><p>Welcome back, this is video 4 of the Space Travel module.</p><p>You and I are pretty lucky. We are going to witness an amazing turn in history in regards to space travel.</p><p>Until the new millennium, most advances is space travel were made by government programs such as NASA in the United States. But all of that is changing. Not only are private companies perusing space travel, they are actually making significant advances in hurdles that have long challenged space travel.</p><p>One of those companies is SpaceX. As we mentioned in the previous section, SpaceX has successfully launched a rocket with a previously used booster. Not only that, they have also made successful cargo deliveries to the International Space Station and are slated to deliver more. Their ultimate goal- enable people to live on other planets. That&#39;s quite the lofty goal! But SpaceX is on its way to proving that it is capable of achieving big things.</p><p>Another company is Virgin Galactic. The company aims to provide suborbital flights into space for paying customers. With deposits from more than 700 people, there are clearly people willing to pay to take a suborbital flight. Cutting edge technologies for this company includes a feathered re-entry system which is designed to return the craft safely to earth after touching the edge of space. And a hybrid liquid/solid fuel rocket engine system.</p><p>The company has suffered a couple of fatal crashes which have set development behind, but the company remains optimistic that they will be able to bring space travel to the masses.</p><p>One more company we will discuss is Blue Origin, which was founded by Jeff Bezos, who also founded the company Amazon back in the 90s. Blue Origin is also pursuing reusable rocket technology. Their reusable rocket, &#39;New Shepherd” made history with the first ever vertical landing from space.</p><p>For the New Shepherd, a pressurized capsule sits on top of a rocket booster. The two components launch and accelerate vertically until the engine cuts off after a couple minutes. Then the capsule continues to glide into space while the booster free falls then performs an autonomous vertical landing. When the capsule is ready for landing, it deploys a parachute. Both components are reusable.</p><p>These private companies are not without critics. Some, like the director of the Hayden Planetarium, Neil DeGrasse Tyson, feel that private enterprises will not be the ultimate pioneers of space travel. He feels that issues like quarterly reports will prevent the long-term focus that programs like space travel require. In his view, the government is better suited for such undertakings.It will be interesting to see where the bulk of space exploration comes from in your life time- the government or these private enterprises.</p></section><section><h3>By Products from NASA Space Technologies</h3><p>By Products from NASA Space Technologies</p><p>License:&#160;No known copyright restrictions</p><p>But What’s in it For Us?</p><p>One of the questions that NASA and other space agencies always face is a variation on the “what’s in it for me” question.&#160;They face this from governments, politicians and normal everyday citizens.&#160;We spend a lot of money on space exploration and things like the ISS, and it feels like we should get something back in return.</p><p>It turns out that NASA technology has impacted our lives in ways you probably never even thought of.&#160;Did you have a good night’s sleep last night?&#160;If you did it on a memory foam bed, you’re sleeping on some of your tax dollars and NASA research in action.&#160;Temper foam, or memory foam, was first developed at NASA to protect airplane passengers in a crash.&#160;It’s now used in beds, pillows and several other safety and comfort applications.</p><p>Smooth drive into school today?&#160;As early as 1971, Goodyear was using the technology they helped develop to make parachutes, make better radial tires, and help the Viking explorer land more softly on Mars.</p><p>When your baby brother or sister was born, did a nurse or doctor check their temperature with a thermometer in their ear?&#160;That&#39;s a spin-off from 1991 that uses the same technology NASA uses to measure the temperature of stars and planets.</p><p>Detection of chemical weapons, improved mine safety, better firefighting equipment, safer landmine removal, artificial heart pumps and, oddly, cordless vacuums, all have their roots in NASA programs and technology.</p><p>Expand each item in the list below to learn about other everyday products based on NASA technology.</p><p>License:&#160;No known copyright restrictions</p><p>Cordless Power Tools</p><p>Intended Use: NASA developed cordless power tools for use in space missions, where the absence of gravity made it challenging to use traditional corded tools.</p><p>Technology Impact: The development of lightweight, battery-powered tools without cords revolutionized the power tool industry. Cordless drills, saws, and other tools provide portability, convenience, and freedom of movement, enabling easier and more efficient construction, repairs, and DIY projects.</p><p>Water Purification Systems</p><p>Intended Use: NASA developed advanced water purification systems for astronauts to recycle and purify water during long-duration space missions.</p><p>Technology Impact: The technology developed for space travel has been adapted to create efficient and compact water purification systems for everyday use. These systems eliminate contaminants, bacteria, and viruses from water sources, providing safe drinking water in homes, offices, and emergency situations.</p><p>Scratch-Resistant Lenses</p><p>Intended Use: NASA needed durable and scratch-resistant materials for space helmet visors to protect astronauts&#39; eyes during extravehicular activities.</p><p>Technology Impact: The development of scratch-resistant coatings and materials for space helmets paved the way for scratch-resistant lenses in eyeglasses, sunglasses, and camera lenses. These lenses offer improved durability, clarity, and protection against scratches and abrasions.</p><p>Dustbusters/Handheld Vacuums</p><p>Intended Use: NASA developed compact, lightweight, and powerful vacuum cleaners for use in space shutt<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('04d37d299766e0b4ce3cb34a3edbf8e5','transportation-technologies-m11-l6-lesson-5','babf506f0e9b677ca95eeabb56a80afd','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Careers in Space Travel</h3><p>Careers in Space Travel</p><p>While watching, think about how you could combine your interests with a career in space travel.</p><p>Welcome back, this is video 5 of the Space Travel module.</p><p>Are you interested in a career in space travel? Let&#39;s talk about some of the paths you can take to get there.</p><p>Astronomy is the study of stars and space objects. That is a pretty fitting science for someone interested in studying space travel! In this profession, you&#39;d likely gather and analyze information to better understand celestial bodies. You&#39;d probably learn to use equipment like telescopes and probes in outer space. Although to secure a job somewhere like NASA as an astronaut, you will need to earn a PhD which means lots of schooling, so an eager-to-learn attitude, and a lot of math, is a must-have in this profession.</p><p>Engineers play a crucial role in space programs and businesses. You could be a mechanical engineer, electronic engineer, computer engineer, or aerospace engineer to find a job in space travel. Most of these positions require a bachelor’s degree.</p><p>At the associate degree level, a degree in aerospace engineering technology could land you a job at NASA. Aerospace engineering and operations technicians assist engineers and scientists. This might mean assisting to design, develop, and test a spacecraft. If this sounds interesting to you, look into technical schools and junior colleges to see what programs they offer.</p><p>Not all jobs are in the science and engineering sector. After all, people have to keep track of how much money is being spent, communicate with the public about current projects, and even photograph (or snapchat) milestones and achievements.</p><p>As space travel advances, careers could open up that we have not even thought of. Perhaps astronauts undergoing extended stays on the moon or even mars will need special psychologists to help them prepare and work through the mental struggles of being away from earth for so long. Or maybe a space communications specialist, making sure the crews and space stay in communication with their home bases. Or maybe you&#39;ll operate a space hotel!</p><p>Now that we are at the end of this module, I hope you’ll agree with me that space travel is an exciting, growing field. You are in a great position to take advantage of the industry expansion if you learn and prepare yourself.</p></section><section><h3>Possibilities to Power Space Ships</h3><p>Possibilities to Power Space Ships</p><p>(opens in a new tab)</p><p>2004 Class of Astronauts&#160;by NASA</p><p>License:&#160;Public Domain</p><p>Flying on All Cylinders</p><p>It&#39;s hard to believe NASA is already 60 years old.&#160;We&#39;ve learned so much since it began exploring space in 1958.&#160;Using telescopes, satellites, probes, landers, rovers, a space station as well as astronauts, NASA and its partners have increased our knowledge of our planet and solar system beyond expectations.&#160;Not resting on its many successes, NASA has more projects on its to-do list than ever.&#160;Watch this short video to get a sense of where it’s going:</p><p>[ MUSIC ]Since its inception, the International Space Station has been powered by large, heavy and complex solar panels. But, as expected, these panels have slowly degraded over time. As a part of an experiment, the station&#39;s robotic arm unfurled the first ROSA - Roll Out Solar Array - in 2017, testing a new and unique concept. Instead of a rigid solar panel, ROSA was crafted from a composite carbon fiber containing an array of solar cells that can be deployed and retracted similar to a tape measure, using stored strain energy of the material. ROSA was also lightweight and generated power with more efficiency. Now, larger versions of ROSA technology, known as iROSA, are being installed on the station permanently through a series of launches and spacewalks. The arrays augment the existing power supply and restore power to previous levels when the original arrays were installed. ROSA technology is also an important part of future exploration. It will serve as a power source for Gateway, the planned multi-purpose outpost orbiting the Moon. It will also help power DART, the Double Asteroid Redirection Test, as it makes its way to the Didymos asteroid system. ROSA - proven on the space station and powering its way to the Moon and beyond our planet&#39;s reach.</p><p>Video Title:&#160;NASA ScienceCasts:&#160;The Power of the Station&#39;s New Solar Arrays</p><p>Video Publisher:&#160;ScienceAtNASA</p><p>License:&#160;Creative Commons Attribution license (reuse allowed)</p><p>The Fuel of the Future</p><p>We saw earlier how important the right fuel would be to make faster space travel a reality.&#160;While they&#39;re still just theories, many scientists are imagining and testing different possibilities to power space ships that include:</p><p>NUCLEAR</p><p>The possibility of using nuclear energy to power rockets was abandoned in the 1970s but it’s becoming more popular again as NASA is aiming for Mars. Essentially, the rocket would be equipped with a reactor just like a nuclear power plant that produces electricity except it would be used to heat liquid hydrogen to power the spacecraft. It would allow for much smaller crafts and faster travel. Because it doesn’t have to deal with the same environmental restrictions, Russia is far ahead using this type of fuel and is already using 30 reactors in space.</p><p>SOLAR</p><p>One source of fuel that exists naturally in space is that of the Sun. Some scientists believe we could harness that energy. Solar powered space crafts would be much lighter and require a lot less fuel to launch. Once in space, they could unfold thin, lightweight solar panels to collect energy to charge the photovoltaic cells cutting storage in half. Photovoltaic cells are already used in many applications on Earth to produce electric power for homes and cars. The flow of electrons created can then be used to ionize the gas xenon, turning it into propellant to feed the thrusters.</p><p>WARP SPEED</p><p>If you’re a&#160;Star Trek&#160;fan, you’ve heard of warp speed, which allows a ship to travel great distances very quickly by bending time and space. While it all sounds like science-fiction and may not happen for quite some time, some scientists at NASA are working on the problem.</p><p>Last Call for Passengers on a Flight to the Moon</p><p>W<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('273029aca04e24e4065b242d71898d33','transportation-technologies-m11-l7-module-11-summary','babf506f0e9b677ca95eeabb56a80afd','Module 11 Summary','text',12,'<h2>Module 11 Summary</h2><section><h3>Module 11 Summary</h3><p>Module 11 Summary</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on Space Travel!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Reviewed the history of rocket use and space exploration</p><p>Compared the benefits gained from space travel with the challenges and costs</p><p>Defined key vocab words related to rockets and space travel</p><p>Described the challenge of creating reusable rockets</p><p>Examined an existing company that is developing commercial space travel</p><p>Identified career opportunities in space travel and educational paths to enter those careers</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8519beddf35321701e9d91049cba0fb2','transportation-technologies-m11-l8-module-11-assignment','babf506f0e9b677ca95eeabb56a80afd','Module 11 Assignment','text',12,'<h2>Module 11 Assignment</h2><section><h3>Module 11 Assignment</h3><p>Module 11 Assignment</p><p>Transportation</p><p>Space Travel - Short Answer Assignment</p><p>Short answer assignment</p><p>Based on what you’ve learned in this module, choose&#160;one&#160;of the following questions and answer it on a two-page, double-spaced paper, and explain your answers:</p><p>What do you think the future of NASA, and space exploration, is? Remember to refer to the readings and videos to back up your answer.</p><p>What do you think the most important step towards making space travel possible was? Remember to refer to the readings and videos to explain your answer.</p><p>Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('411af96cf1722b9932a10f03d0e25b20','transportation-technologies-m11-l9-module-11-project','babf506f0e9b677ca95eeabb56a80afd','Module 11 Project','text',12,'<h2>Module 11 Project</h2><section><h3>Module 11 Project</h3><p>Module 11 Project</p><p>Transportation</p><p>Space Travel - Project</p><p>Project</p><p>In this assignment, you will create a presentation about the future of space travel. You can use a presentation software such as PowerPoint or Prezi to create your description. Be sure to cite any resources for images and other content.</p><p>Your presentation should:</p><p>discuss the benefits gained from space travel</p><p>evaluate the current challenges and costs of space travel</p><p>describe the impact that reusable rockets might have</p><p>evaluate the challenges of reusable rockets</p><p>predict what will make the biggest impact on space travel in your lifetime</p><p>be organized and engaging</p><p>Review the rubric below to see how you will be graded.</p><p>Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Current Space Travel</p><p>8 points The presentation effectively describes the benefits of space travel and effectively evaluates the challenges and costs.</p><p>7-6 points The presentation adequately describes the benefits of space travel and adequately evaluates the challenges and costs.</p><p>5-0 points The presentation does not adequately describe the benefits of space travel or evaluate the challenges and costs.</p><p>8</p><p>Future of Space Travel</p><p>8 points The presentation demonstrates a strong understanding of the positives and negatives of reusable rocket use. It contains several specific details describing opinions of the future of space travel.</p><p>7-6 points The presentation demonstrates a satisfactory understanding of the positives and negatives of reusable rocket use. It contains some specific and details describing opinions of the future of space travel.</p><p>5-0 points The presentation demonstrates little to no understanding of the positives and negatives of reusable rocket use. It contains few to no specific and details about the future of space travel.</p><p>8</p><p>Presentation</p><p>2 points The presentation is clear and organized.</p><p>1 point The presentation is somewhat clear and organized.</p><p>0 points The presentation is not clear and organized.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('745c71986aea1bbbf2d5cfe050b7f8d5','transportation-technologies-m11-l10-module-11-quiz','babf506f0e9b677ca95eeabb56a80afd','Module 11 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Space Travel. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('76539eb77e2c91a0868016c647c32a70','transportation-technologies-module-12','504e3ab88df8552a07116f12aea44099','Module 12: Interstellar Travel',12) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b79064d6478f8ea8975fde4d56aa86da','transportation-technologies-m12-l1-introduction-purpose-and-objectives','76539eb77e2c91a0868016c647c32a70','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Most futuristic transportation modes we have discussed seem realistic or practical. In many cases, prototypes are being tested already. It seems like it’s only a matter of time before they become part of our lives. Now it&#39;s time to dream even bigger... We are going to talk about something that currently only exists in science fiction- interstellar travel. The technology, the physics, and the challenges are so mind-blowingly difficult, that it will take the collective efforts of the world&#39;s most creative, bold, and intelligent thinkers, likely over many generations, to ever find possible solutions. Let’s take a look.</p><p>Module Description</p><p>byShutterstock</p><p>License:&#160;All Rights Reserved</p><p>In 1903, the president of the Michigan Savings Bank advised Henry Ford&#39;s lawyer, Horace Rackham, NOT to invest in the Ford Motor Company.&#160;He said, “The horse is here to stay but the automobile is only a novelty – a fad.”&#160;(1)&#160;It seems safe to say, the bank president was wrong.&#160;Very wrong.&#160;Today there are many scientists who look at interstellar travel and say it&#39;s only a matter of time before we travel there.&#160;Other scientists look at interstellar travel and say it will never happen.&#160;Which group will prove right?</p><p>This module will identify the challenges to interstellar travel.&#160;It will explain need-to-know terms such as astronomical units, light speed, propulsion, and g-force.&#160;Then it will describe theories and the pros and cons of each theory in achieving interstellar travel.&#160;Then it will discuss the feasibility of an interstellar mission.&#160;By the end, you will be able to make an informed prediction as to when, if ever, interstellar travel will be launched.</p><p>Footnote:</p><p>Szczerba, R. J. (2015, January 09).&#160;15 Worst Tech Predictions Of All Time.&#160;Retrieved January 01, 2018, from&#160;https://www.forbes.com/sites/robertszczerba/2015/01/05/15-worst-tech-predictions-of-all-time/#30c54c9d1299</p><p>Objectives</p><p>In this module, students will</p><p>Predict when, if ever, an interstellar voyage will be launched and justify the prediction</p><p>Identify challenges to interstellar travel based on today’s technologies</p><p>Define astronomical units, light speed, propulsion, and gravity units (G-force)</p><p>Describe theories for interstellar travel possible</p><p>Compare pros and cons of proposed methods to achieve interstellar travel</p><p>Discuss feasibility of an interstellar mission given energy requirements and risks</p><p>Polling Question</p><p>What do you think is keeping society from interstellar travel?</p><p>Today&#39;s technology makes it unfeasible&#160;We need to thoroughly examine our solar system first&#160;People aren&#39;t interested&#160;Too many problems on earth that need to be solved first&#160;I don&#39;t know</p><p>Make a selection to see the results so far.</p><p>How did your prediction compare to your classmates?&#160;Let’s see how your answer changes as your learn more about&#160;interstellar travel!</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>travel between stars or planetary systems</p><p>Interplanetary travel</p><p>travel between planets of the solar system</p><p>Light year</p><p>the distance between the earth and the sun.&#160;A unit of length used to measure distances within the solar system or other stars</p><p>Astronomical Unit (AU)</p><p>distance light travels in a vacuum in one calendar year</p><p>Interstellar travel</p><p>the force that attracts an object toward the center of the earth, or toward any other object having mass</p><p>Gravity</p><p>acceleration that causes an accelerating object to experience a force in the opposite direction of the acceleration</p><p>g force</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>travel between stars or planetary systems</p><p>Answers for question: 1</p><p>Interplanetary travel</p><p>Interstellar travel</p><p>Astronomical Unit (AU)</p><p>Gravity</p><p>g force</p><p>Light year</p><p>2.</p><p>travel between planets of the solar system</p><p>Answers for question: 2</p><p>Gravity</p><p>Light year</p><p>Astronomical Unit (AU)</p><p>g force</p><p>Interplanetary travel</p><p>Interstellar travel</p><p>3.</p><p>the distance between the earth and the sun. A unit of length used to measure distances within the solar system or other stars</p><p>Answers for question: 3</p><p>Gravity</p><p>Astronomical Unit (AU)</p><p>Light year</p><p>Interstellar travel</p><p>g force</p><p>Interplanetary travel</p><p>4.</p><p>distance light travels in a vacuum in one calendar year</p><p>Answers for question: 4</p><p>Interstellar travel</p><p>Light year</p><p>g force</p><p>Interplanetary travel</p><p>Astronomical Unit (AU)</p><p>Gravity</p><p>5.</p><p>the force that attracts an object toward the center of the earth, or toward any other object having mass</p><p>Answers for question: 5</p><p>Interplanetary travel</p><p>Interstellar travel</p><p>Gravity</p><p>Astronomical Unit (AU)</p><p>g force</p><p>Light year</p><p>6.</p><p>acceleration that causes an accelerating object to experience a force in the opposite direction of the acceleration</p><p>Answers for question: 6</p><p>Astronomical Unit (AU)</p><p>Interstellar travel</p><p>Interplanetary travel</p><p>Light year</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('79a5b57a3516de8f1d5ed61a19903741','transportation-technologies-m12-l2-lesson-1','76539eb77e2c91a0868016c647c32a70','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Problems with Travelling to Other Planets</h3><p>Problems with Travelling to Other Planets</p><p>Consider the following question as you watch the video:</p><p>Which hurdle you feel is the most difficult that scientists will have to overcome to realize interstellar travel?</p><p>Welcome to the Interstellar Travel module – video 1.</p><p>NASA scientists have identified 4,034 planet candidates with 2,335 of those confirmed as exoplanets, or planets outside our solar system that orbit another star (like how we orbit the sun). Nearly 50 of those planets are considered “Earthlike.” And that&#39;s just in .25% of the night sky- less than 1%!</p><p>How cool would that be if even one of those had some sort of intelligent civilization on it? Starship Enterprise here we come, right?! Although finding these planets is a major accomplishment for scientists, it is one thing to find these planets, and quite another to actually&#160;get&#160;there. As it turns out, there are all kinds of technological bummers that are keeping you from communicating with or visiting an interstellar pen pal.</p><p>And the vast majority of these problems all have to do with the distance these planets are from Earth. So far, in fact, that they make the moon look like a hop, skip, and a jump away. The planetary system Trappist-1 (which holds the most habitable-zone planets), for example, is a whopping 235&#160;trillion&#160;miles away. That would take 39 years traveling at the speed of light to reach. Minor problem with that- okay BIG problem with that- no spacecraft ever built can travel anywhere near that fast. With our current technology it would take over 300,000 years to get to just the nearest planet outside our solar system. Ain&#39;tnobody got time for dat!</p><p>What isn&#39;t hindered by distance is hindered by money. It takes some serious cash- we&#39;re talking hundreds of millions of dollars- just to&#160;launch&#160;the Mars Curiosity rover. Then there&#39;s the cost of technologies that we haven&#39;t even developed but we&#39;ll need to have for interstellar travel. That will cost a penny or two (zillion!)</p><p>And just want are those technologies we&#39;ll need to develop? Well given that we&#39;ve never done it and we keep running into more problems as scientists look more into it, it&#39;s hard to say. But for starters there&#39;s...</p><p>Take off- like I mentioned, it&#39;s very expensive to launch a rocket. A spaceship with a crew and all the necessary supplies is likely to be massive and need massive amounts of fuel. And be massively expensive.</p><p>Propulsion- back to the distance thing- there&#39;s jus t not a feasible way to propel us that far through space quickly yet.</p><p>Space trash- yes, space trash. There are about 17,000 softball sized objects orbiting Earth that the US Space Surveillance System is monitoring. These aren&#39;t just gently floating objects. They are traveling at speeds of 17,500 miles per hour. A collision with even a small object at that speed would cause serious damage.</p><p>Navigation- transmissions to deep space still takes hours, and the stars can tell you where you are going, but not where you are.</p><p>Food and water- it is downright hard to grow a garden in zero gravity. And the current water filtration system used by the International Space Station needs repairing from time to time. In deep space, there&#39;s no cargo delivery for necessary parts.</p><p>Human health- radiation is an issue. We are talking a big, cancer causing issue. Added to that is the issue of muscle atrophy and bone decay after extended amounts of time at zero gravity.</p><p>Finally, there&#39;s the landing. Imagine fixing all the problems we just mentioned, plus all the others we haven&#39;t, only to make a lethal crash landing.&#160;Not&#160;the kind of first impression we&#39;d want to make on another planet!</p><p>Despite all these challenges, there are still many brilliant minds, yours included I hope, who believe the dream of interstellar travel is worth pursuing.</p></section><section><h3>Key Terms for Interstellar Travel</h3><p>Key Terms for Interstellar Travel</p><p>To begin this reading section, watch the following video which builds on reasons to explore and pursue interstellar travel:</p><p>So so far in this course, we&#39;ve been talking mostly about earth&#39;s orbit and maybe visiting the other planets. Now but as we&#39;ve talked about in the planets course really, our own solar system is, I mean, I think it&#39;s very interesting. But there are no planets with lush jungles. There&#39;s no intelligent life out there to meet. They&#39;re they&#39;re all near barren icy wastelands. Um, so really, what we could do with that being much more fun to go off and find a nice earth-like planet to do that we&#39;re gonna have orbiting another star. We&#39;re going to have to interstellar. So that means going to a new star rather than into planetary just going to a new planet exactly, you know, and as you said, it&#39;s nice to study the solar system like as an exhibit in the museum. But for holiday destinations you really have to go somewhere else. And that&#39;s going to be the the focus kind of ofof this part of the course. Which is the last part is the the challenges, and the opportunities, let&#39;s say that we present ourselves in traveling to a different star system. Now I think the first thing that we have to think about when we&#39;re talking about interstellar travel is it&#39;s a whole different ball game. Like, okay, I could ride a cycle. It&#39;s now saying I&#39;m gonna go ride in the tour de France. It&#39;s a very different set of challenges. One that is very in the realm of down-the-road possibilities. So we&#39;re really getting into more science fiction, that&#39;s right and then solid science at this point. I mean, at the moment, the furthest we&#39;ve gone with humans is the moon and space probes out past pluto. Yep. And uh, as we&#39;ll see in a second, uh, that&#39;s not very far compared to the distances involved in interstellar travel. It really is, as you said, it really is in the realm of of science fiction and and just not anytime soon, and I think we sometimes think of, oh sure, we can get to the moon. We&#39;re talking about the mars, interstellar&#39;s next. Well, not quite, and this is what we&#39;re going to focus on in this part of the course is this those real limitations now there is real work to be done in real science to be had, <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('bd5ae08f5cd71d83a98dda46df5a63d9','transportation-technologies-m12-l3-lesson-2','76539eb77e2c91a0868016c647c32a70','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Explanation of Interstellar Key Terms</h3><p>Explanation of Interstellar Key Terms</p><p>While watching, listen for key terms you do not know and listen for an explanation.</p><p>Welcome back, this is video 2 of the Interstellar Travel module.</p><p>I&#39;m excited to tell you about the fascinating theories scientists have created about how interstellar travel could work. But before we get to that, we need to cover some basic terms.</p><p>Let&#39;s start with the term interstellar travel. You&#39;ve probably picked up on what it means already, but just to be clear, interstellar travel refers to travel between stars or planetary systems. The reason interstellar travel is so much harder than interplanetary spaceflight, which refers to travel between planets of the solar system, is the distance it takes to get there. We talked about that in the first module.</p><p>For interplanetary spaceflight, the distances between planets is less than 30 astronomical units, or AU s. Astronomical units are a unit of length that astronomers and other space scientists use to measure distances within the solar system or other stars. A single astronomical unit is the distance between the sun and the earth, about 93 million miles. That&#39;s a LOT of miles!</p><p>Interstellar travel requires traveling hundreds or thousands of astronomical units away- in terms of miles, that&#39;s math I can&#39;t even do! The numbers start getting so big, that it makes more sense to talk about distance in terms of light years. Don&#39;t be confused by the word year. A light year isn&#39;t a measure of time, but distance. It&#39;s the distance light travels in a vacuum in one year. It&#39;s about 5.9 trillion miles.</p><p>So in order for interstellar travel to happen in less than hundreds of thousands to millions of years, than scientists need to figure out how to get a spacecraft flying at or near the speed of light. That would mean flying at 186,000 miles per second! Even at light-speed it would still over 4 years to reach Proxima Centauri, which is the nearest star and exoplanet outside our solar system.</p><p>Another set of terms to get familiar with center around gravity. Gravity is a natural phenomenon by which all things with mass are brought toward one another. On earth, gravity gives weight to physical objects. Gravity is also responsible for causing the planets to orbit the sun, the moon to orbit Earth, the formation of tides, and even the evolution of solar systems, stars, and galaxies. So gravity is a big deal!</p><p>And a lot of things go wrong for the human body when there is no gravity. We covered that in the previous section. Because gravity makes such a difference to our bodies and physical objects in general, scientists use g-force to measure the type of acceleration that causes the perception of weight. 1-g is the force of gravity on earth. This is 9.8 meters per second.</p><p>So 1-g is what we&#39;re used to, it’s what you or I am experiencing right now. Occasionally we experience different amounts of g forces- like when riding a roller coaster. But the human body can only stand so much variation from the normal 1-g we are used to. Like we discussed, zero gravity which would mean 0-gs, is harmful to the body. But so are high amounts.</p><p>We can tolerate high amounts of g force only for a split second. Sustained exposure to more than about 10g can lead to permanent injury, especially if the direction you are accelerating is downward. And generally speaking, anything above 100g is lethal- even after just a few seconds.</p><p>Scientists must take this into account when figuring out space propulsion. Acceleration isn&#39;t too big of an issue since it can be done gradually so as not to overwhelm the body with g forces. But deceleration is another issue. A “sudden” stop (I say sudden, but really it would still take days to stop if you had been traveling at the speed of light), say to avoid collision, would exert a tremendous amount of g forces on those in the spacecraft.</p><p>Now that we have an understanding of these terms, we can start discussing different theories of how interstellar travel might be possible.</p></section><section><h3>Exoplanet Discovery Possibility</h3><p>Exoplanet Discovery Possibility</p><p>Before diving into more details on exoplanets, watch a segment from this video, which describes the James Webb space telescope, and how it is making Exoplanet discovery possible:</p><p>[Music][Applause]Galaxies are the building blocks of the universe. The giant galaxies we see today, even our own, were built up from many smaller galaxies. But construction isn&#39;t done yet. It continues even today. Full-grown galaxies approach and interact with each other they may collide and eventually merge. As the galaxies approach, the tug of gravity creates tides that distort their shapes. Stars and gas stream into new orbits. Sometimes they&#39;re completely ejected, trailing into the depths of intergalactic space. Gas clouds compressed in the chaos light up with intense rounds of star formation. Because stars create most of the chemical elements, such episodes have a profound effect on a galaxy&#39;s chemical makeup. This infrared image of the entire sky shows half a billion stars. Most are in our galaxy. Some are not. These are companion galaxies that orbit our Milky Way. And some are in between. In 1994, astronomers discovered that some of these stars actually belonged to a different galaxy. It&#39;s called a Sagittarius dwarf elliptical. And the Milky Way is tearing it apart. As the dwarf galaxy passes through the Milky Way&#39;s disk, gravitational tides stretch the dwarf stars into long streams that wrap around the galaxy&#39;s orbit. For the dwarf, it&#39;s a fatal attraction. For the Milky Way, it&#39;s but one of many similar events that shaped our home galaxy. But there&#39;s something much bigger headed our way. M31, the Andromeda galaxy, this is no dwarf. It&#39;s the Milky Way&#39;s biggest neighbor of roughly the same size, mass and type. Astronomers say the crash will begin about two billion years from now. This supercomputer simulation shows how the event may unfold over billions of years. The first pass distorts the two great spirals stars are tossed into the intergalactic night like sparks thrown from a campfire. Our sun, complete with planets in tow, could be similarly ejected. Each pass blurs the identities of each galaxy; eventually, Andromeda and the Milky Way will m<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('49203baa467f7bde1582cede74eb80e7','transportation-technologies-m12-l4-lesson-3','76539eb77e2c91a0868016c647c32a70','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>The Concept of Warp Drive or Speed</h3><p>The Concept of Warp Drive or Speed</p><p>Pay attention to the different types of interstellar theories and see if you can think of any science fiction you may have seen or read.</p><p>Welcome back, this is video 3 of the Interstellar Travel module.</p><p>“Prepare for warp speed.” Star Trek enthusiasts know that phrase, but what exactly is it, and is there any merit to the concept of “warp drive” or “warp speed.” This theory of interstellar space travel involves manipulating the gravitational fields of space. Manipulating the gravitational fields would, in theory, allow the distance between a spacecraft and a distant target to collapse making interstellar possible in seconds or even minutes.</p><p>Warps, bends, and folds in the universe could also create wormholes and black holes that other “short-cut” theories suggest. Physicists and science fiction writers in particular tend to focus on wormholes. Wormholes are passages through space-time that would create “shortcuts” between two far distant places in the universe. Here&#39;s a VERY simplified demonstration (with credit to the book A Wrinkle in Time):</p><p>Imagine going from one dot to the other. With normal travel, you&#39;d traverse across the entire length of the paper. But if the paper were to fold in half, (fold paper in half) now the two points are much closer!However, wormholes are theoretical. At least for now.</p><p>What about working a little bit more with what we have already? One of the biggest problems is having to carry our propellant with us. You may recall from earlier modules that rockets have to carry both the fuel and the oxidizer to travel in space. And, of course, the faster you want to go, the more fuel you need.</p><p>Tackling this problem is the Bussard Interstellar Ramjet. In Bussard&#39;s theory, an electromagnetic scoop collects interstellar hydrogen and uses hydrogen fusion to drive the spacecraft. Ta-da! No need to take the hydrogen along with you! In this theory, the spacecraft would actually get more and more efficient the faster it goes. This theory makes appearances in science fiction writings as well.</p><p>Interestingly, interstellar theories have borrowed a key component of maritime travel- sails! There are all kinds of sails proposed for interstellar travel. Solar, beamed, magnetic solar wind, and electric solar wind are all proposed methods. Although where they derive most of their propulsion is different, they all operate on the idea of creating a sail of sorts on a spacecraft and receiving a “push” from the energy of space itself- usually in the form of solar photons.</p><p>These sailing concepts would provide another way to travel without having to take massive amounts of fuel along.Like sails, nuclear energy is another method that has gained a lot of attention and support. Propulsion in this category include nuclear electric ion propulsion, nuclear fusion, nuclear pulse, and nuclear thermal propulsion.</p><p>In case you need a refresher on what nuclear energy is, nuclear energy is energy in the core of an atom. Huge amounts of energy exist in the nucleus of an atom. That energy is released when the bonds holding the atom&#39;s nucleus together break. This means that nuclear energy is both more efficient and provides more thrust than conventional chemical rocket propulsion that is generally used today. Right now, however, this is a proposed solution more for interplanetary travel rather than interstellar travel.</p><p>Now that you have an idea of what the theories are, we will discuss the pros and cons of each type in the next section.</p></section><section><h3>Obstacles to Interstellar Travel Opportunit</h3><p>Obstacles to Interstellar Travel Opportunities</p><p>License:&#160;All Rights Reserved</p><p>Imagine being part of the first ever interstellar exploration mission to an identified Earthlike planet.&#160;Imagine the view of a brand-new planet as it fills up the viewport.&#160;It&#39;s more beautiful and amazing than you could ever imagine.&#160;So what is standing between you and this dream?&#160;In short, a whole lot of science, each and every step of the way.</p><p>Mankind has always been fascinated by the idea of interstellar travel, venturing beyond our solar system to explore distant worlds.&#160;However, the pursuit of manned interstellar travel is riddled with formidable challenges and limitations.&#160;Let&#39;s delve a bit deeper into the complexities and current understanding surrounding the feasibility of manned interstellar travel, examining the scientific, technological, and physiological obstacles that stand in our path.</p><p>Let&#39;s take a look at a few of the things standing in our way as we work on developing interstellar travel opportunities.&#160;Expand each section below.</p><p>The Limitations of Speed</p><p>One of the fundamental challenges in interstellar travel is the vast distances involved. Even with our current propulsion technologies, achieving the necessary speeds to reach nearby star systems within a human lifespan remains a significant hurdle. However, recent advancements in theoretical physics, such as the concept of warp drives and wormholes, offer intriguing possibilities for faster-than-light travel. While theoretical in nature, such concepts require breakthroughs in understanding and harnessing exotic phenomena, which are yet to be realized.</p><p>Energy Requirements</p><p>Interstellar travel demands an extraordinary amount of energy. The propulsion systems needed to propel a spacecraft to a significant fraction of the speed of light would require an energy source far beyond our current capabilities. Developing sustainable and efficient propulsion systems, such as fusion or antimatter engines, is a formidable engineering feat that lies beyond our current technological grasp.</p><p>Time Dilation and Relativity</p><p>Another critical consideration for interstellar travel is the phenomenon of time dilation predicted by Einstein&#39;s theory of relativity. As a spacecraft approaches speeds approaching that of light, time for the travelers slows down relative to the reference frame on Earth. This means that even if we were to achieve near-light speeds, the relativistic effects would result in significant time discrepancies between those aboard the spacecraft and those remaining on Earth.</p><p>Human Longevity and Adaptation</p><p>Interstellar journeys spanning several generations raise concern<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('62081a0b3f12fdcdaceb18a18e1d1310','transportation-technologies-m12-l5-lesson-4','76539eb77e2c91a0868016c647c32a70','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Wormhole and Warp Speed</h3><p>Wormhole and Warp Speed Thoeries</p><p>While watching, think about what technologies scientists need to develop for each theory.</p><p>Welcome back, this is video 4 of the Interstellar Travel module.</p><p>Obviously, there have to be limitations to each theory, otherwise we&#39;d be traveling across the universe already! Let&#39;s take a look at what each theory does well, and what its limitations are.</p><p>Let&#39;s start with the shortcuts across space-time:</p><p>Both wormholes and warp drive do an excellent job of hypothesizing ways that could shorten the distance and time required to travel between two points. If we could figure out how to actually create wormholes, than that would limit the problems of propulsion even farther because we could choose the exact starting point- no need to travel to a predetermined point.</p><p>The biggest problem- we have never, ever found a wormhole! Yes, that is a bit of a problem. However, Einstein&#39;s Theory of General Relativity mathematically predicts their existence.</p><p>Besides never having spotted one, there are other problems associated as well. For one, they are speculated to be microscopic in size when first generated. Scientists are assuming that as the universe expands, some of the wormholes that are out there will grow in size too. Another major obstacle- they probably don&#39;t stay open very long. That makes them almost useless for travel. To make it stable, it would need what is called “exotic matter” which we&#39;ve only seen hints of in certain situations.What about warp drive? Although Captain Kirk may have made the concept of “warp drive” famous, a scientist by the name of Miguel Alcubierre gets credit for writing a paper that postulates how the concept could work within general relativity.</p><p>According to his theory, faster than light speed travel would be not only possible, but it would also wouldn&#39;t have some of the problems associated with travel that fast, such time distortion. He outlined the mathematical foundation for such a concept in his paper.</p><p>Unfortunately, there are some BIG holes in the plan. For one, there was no control. Out of control technology doesn&#39;t exactly fill us with comfort.</p><p>For another, it requires HUGE amounts of energy. Pretty much it would require the mass-energy equivalent of the entire known universe. That&#39;s a LOT of energy! Luckily, scientists at NASA found a way to reduce the amount of energy that warp drive would need. Not only that, but Dr. Harold White even gave the theory more feasibility by proposing new concepts to warp drive and promoting advanced propulsion projects.</p><p>Finally, we just don&#39;t have the necessary technology to make this safe. For example, we would need shields to protect from space dust and gas.</p><p>Next, there&#39;s Bussard&#39;s ramjet theory. The biggest benefit to this theory is that by using the electromagnetic scoop to collect hydrogen, there&#39;s no need to take the amount of fuel that would be required on a conventional rocket. One hurdle, however, is that the ramscoop is likely to cause major drag, which would slow down the spacecraft. Another problem is the hydrogen fusion that Bussard originally thought of occurs only in the heart of stars. Bringing it to a spacecraft is far beyond what scientists are capable of today.</p><p>What about sails? Are they more feasible? It is possible for the right kind of sail to harness the photon energy emitted from the sun or from a laser and glide across the galaxy. In other words, the science all checks out. One of the great benefits of these methods is that there is no need to carry the necessary fuel on the spacecraft. The proposed sails would also be much faster than conventional rockets. Perhaps up to 30% of the speed of light.</p><p>Solar sails work best closer to the sun, but the effect starts to diminish as the spacecraft gets farther away.</p><p>One idea is to create a laser and send it somewhere like one of Jupiter&#39;s moons to keep the spacecraft accelerating as it gets farther from the sun.</p><p>The more complex issue is building a sail big enough to gain the kind of distance we want. We are talking about sails that are miles wide! As well as a laser with enough power for the job as well. Although these technologies are probably a ways into the future, they work comfortably within the physical laws scientists already know.Last, let&#39;s talk about nuclear propulsion. Nuclear fusion in particular has some scientists excited because not only is it powerful, the plasma, which is released as exhaust, can be converted into thrust. This gives the vehicle more thrust and more efficiency than current methods.</p><p>The biggest problem with nuclear fusion is in creating the reactor. Currently no reactor is capable of producing more energy than the energy required to generate the reaction. Oh, and there’s an international treaty banning the use of nuclear technology in space.</p><p>As you can see, scientists have a lot to figure out in the future before any of these concepts go from theory to execution. Perhaps YOU will play a role in doing just that.</p></section><section><h3>Popular Intersteallar Travel Theories</h3><p>Popular Intersteallar Travel Theories</p><p>It may surprise you to learn that terms like “warp drive” “hyper drive” “worm holes” and “interstellar ramjet” are not just the inventions of Hollywood silver screens or thrilling page turners.&#160;There is actually some evidence supporting the plausibility of each of these theories.&#160;Let&#39;s take a look at some of the more popular interstellar travel theories.</p><p>Space-Time Shortcuts</p><p>One of the more popular theories that would shorten the distance between two places across the universe is wormholes. Wormholes are very popular in science fiction. They are mentioned in movies like Star Trek, Deja-vu, Marvel Universe movies, and Interstellar and books like A Wrinkle in Time and Contact as well as many other sci-fi works. Also known as an “Einstein-Rosen Bridge” (the two scientists who first proposed the theory), wormholes are like space-time tunnels. In theory, you would enter the wormhole in one location, and come out somewhere else in the universe.</p><p>Another popular shortcut through the universe is the theory of warp drive, a theory mentioned in Star Trek and Star Wars in particular. In warp drive, the gravitational fields of space are manipulated an<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ea89a5d375d091174e41becdf78fa605','transportation-technologies-m12-l6-lesson-5','76539eb77e2c91a0868016c647c32a70','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Pros &amp; Cons of Interstellar Travel Mission</h3><p>Pros &amp; Cons of Interstellar Travel Mission</p><p>While watching, identify what you think are the most compelling reasons for and against pursuing an interstellar travel mission.</p><p>Welcome back, this is video 5 of the Interstellar Travel module.</p><p>Given all we know about interstellar space travel, the hurdles to overcome, the technology to be invented, the ENORMOUS costs, and the dangers involved, should we even bother? Should we move on to more earth-bound problems and let aliens- should they ever arrive- give us their secrets? Let&#39;s talk about some of the reasons for and against interstellar travel.</p><p>Let&#39;s start with the nay-sayers. Perhaps the biggest complaint about pursuing interstellar travel is how darn expensive it would be. Not millions- that&#39;s petty change compared to the numbers economists speculate- not billions either- we are talking potentially TRILLIONS- maybe even a hundred trillion dollars to make an interstellar program happen. And that money has to come from somewhere... more like someones!</p><p>Another argument: humans are too fragile and needy. People with this view tend to be in favor of sending unmanned probes beyond our galaxy. Taking humans out of the equation makes the spacecraft much smaller (no food, water, supplies, living space, and other necessities) and therefore more efficient. It also takes away problems like anti-gravity on human health and exposure to extraterrestrial microbes.</p><p>And finally, there are those who feel it is just too risky. There are potential problems that we cannot even imagine coming up against that we will come up against with such an undertaking. Imagine the devastation of sending a large manned spacecraft only to encounter a fatal disaster scientists did not predict.</p><p>All right, now let&#39;s discuss what the yay-sayers have to say. Sometimes when technology is invented to solve one particular problem in a field, it can actually be applied to a much broader use and audience. For example, figuring out how to feed an entire crewed spaceship for months, years, decades, or even generations might help us figure out how to solve hunger here on earth.</p><p>Another compelling reason is to hedge our bets for our species&#39; survival by making it so not every human is on earth. A giant asteroid could devastate the earth in an instant. If some people are on another planet, well, human existence can continue. In fact, the sun is going to expand enough to make living on earth impossible... of course that is billions of years into the future, but it&#39;s predicted to happen. It is probably best to start working on an exit strategy now since it will likely be a complicated one.</p><p>Hopefully you’ve been able to get a glimpse of what a fascinating topic interstellar travel is. And there are a whole host of issues like wait time calculation, time dilation, antimatter, and many others that we didn’t even have time to cover. It will be amazing to see what scientists and engineers are able to achieve in this field during our lifetime.</p></section><section><h3>Challenges of Interstellar Travel</h3><p>Challenges of Interstellar Travel</p><p>Having gone through just a handful of the technological and logistical challenges involved with interstellar travel, it&#39;s easy to think people should just forget it.&#160;In fact, there are many naysayers out there.&#160;So, what are the challenges?&#160;Take a look at the tabs below.</p><p>Cost</p><p>One of the biggest arguments raised by the opposition to interstellar travel is the enormous associated cost.&#160;Some economists predict an interstellar program could cost around 100 trillion dollars.&#160;And that would be for an unmanned mission!</p><p>The costs for a manned mission would be even more expensive because of the necessity to keep people alive.&#160;Not to mention finding a way to make sure that g-forces are optimal for travel AND destination.&#160;Even if we found a way to make people “sleep” through space, that would still be an enormous additional cost.&#160;That money could be spent on more pressing issues like pollution, for example, naysayers argue.</p><p>Humans are Fragile and Needy</p><p>Before modern medicine, plagues and diseases devastated populations. If our bodies have a hard time-fighting earth-born disease, imagine how much more difficult it would be to find microbes and germs from other planets. We would know nothing about another planet&#39;s microbes without extensive research beforehand. If there was a harmful microbe that&#160;scientists somehow missed in the research, it could have devastating consequences.</p><p>As we mentioned earlier, humans need a lot of supplies. They would need air, food, water, health supplies, sleeping and living quarters, just to name a few. If any of those things were to cease to exist on an interstellar flight, well, so would people.</p><p>Too Risky</p><p>The final argument against interstellar travel that we&#39;ll discuss is the level of risk. Even if we were confident that we knew exactly what kind of microbes were on another planet, even if we had the propulsion figured out, and even if we found a way to carry along all the necessary supplies... there is still the possibility that we could encounter something we did not prepare to encounter.</p><p>Imagine the devastation of something fatal happening to an entire multi-generational spacecraft. Space is too vast, too foreign, and too dangerous, the naysayers argue.</p><p>Given these arguments and the technology hurdles to overcome, you may be thinking interstellar travel is never going to happen and we should not bother. But let&#39;s take at some of the more compelling reasons for pursuing interstellar travel.</p><p>Beneficial Technology</p><p>A lot of the problems that would need to be solved to make manned interstellar travel happen would benefit life on Earth if solved. For example, developing a more efficient, more powerful energy source.Or finding new ways to feed people in a limited amount of space. These and many others have direct applications to making life better for those who remain on earth.</p><p>Multi-planetary Species</p><p>One of the most prominent theories about what happened to the dinosaurs is that the Earth was hit by a devastating asteroid. Even if that theory turns out to be false, there is no reason why that couldn&#39;t happen to the earth in the future.</<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('92295bb499b782b00bf57d5e032de126','transportation-technologies-m12-l7-module-12-summary','76539eb77e2c91a0868016c647c32a70','Module 12 Summary','text',12,'<h2>Module 12 Summary</h2><section><h3>Module 12 Summary</h3><p>Module 12 Summary</p><p>License:&#160;All Rights Reserved</p><p>Great Work!&#160;You have successfully completed this module on&#160;Interstellar Travel!</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified challenges to interstellar travel based on today’s technologies</p><p>Defined astronomical units, light speed, propulsion, and gravity units (G-force)</p><p>Described theories for interstellar travel possible</p><p>Compared pros and cons of proposed methods to achieve interstellar travel</p><p>Discussed feasibility of an interstellar mission given energy requirements and risks</p><p>Predicted when, if ever, an interstellar voyage will be launched and justify the prediction</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4288cb3acc4dcefbadefc1d3ca823a8b','transportation-technologies-m12-l8-module-12-assignment','76539eb77e2c91a0868016c647c32a70','Module 12 Assignment','text',12,'<h2>Module 12 Assignment</h2><section><h3>Module 12 Assignment</h3><p>Module 12 Assignment</p><p>Transportation</p><p>Interstellar Travel - Short Answer Assignment</p><p>Short answer assignment</p><p>For this writing assignment, choose&#160;one&#160;of the&#160;two short answer prompts below and write a two-page, double spaced paper addressing the questions/topics listed.</p><p>Option 1:&#160;Lately, there has been speculation and news reports alleging that the government is hiding information about UFOs. Search online for a recent article, news story, video, podcast, or other media (include the URL in your assignment), then answer the questions below in a two-page, double-spaced paper:</p><p>Why do you think the government withheld the information from the public?</p><p>If UFOs exist, what does this tell us about interstellar travel?</p><p>Imagine you are the head of a public debate about whether or not an Aerospace Threat Program should exist. First, pick which side of the debate you are on (for the program or against it). Then, write a persuasive speech highlighting key points of your argument.</p><p>Option 2:&#160;Movie review: With the approval of a parent or guardian, watch the 2014 movie&#160;Interstellar&#160;(or another movie with interstellar travel concepts – approved in advance by your instructor) and answer the following questions:</p><p>Describe the interstellar travel theories mentioned in the movie (wormholes and black holes). How does the portrayal of these theories compare to what you learned in the course?</p><p>What aspects of the technologies were confusing or didn’t make sense to you as you watched the movie?</p><p>Time dilation, though not covered in detail in this module, is an important theory around interstellar travel. Describe how was the principle of time dilation was portrayed in the movie.</p><p>Do you think science fiction books and movies help the development of interstellar travel theories? Or do they just portray unrealistic ideas that have no basis in our current understanding of science?</p><p>Review the rubric below to see how you will be graded.</p><p>Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('206f21c29a71a760fef506a595a7150b','transportation-technologies-m12-l9-module-12-project','76539eb77e2c91a0868016c647c32a70','Module 12 Project','text',12,'<h2>Module 12 Project</h2><section><h3>Module 12 Project</h3><p>Module 12 Project</p><p>Transportation</p><p>Interstellar Travel - Project</p><p>Project</p><p>In this assignment, you will select one interstellar travel theory to evaluate. Create a presentation to describe the theory, its technology, and its pros and cons. &#160;Be sure to cite any resources for images and other content as needed.</p><p>Your presentation should:</p><p>describe one interstellar travel theory</p><p>discuss what is known/developed toward the theory and what still needs to be</p><p>explain the benefits of this theory over others</p><p>discuss negatives to this type of interstellar travel</p><p>be organized and engaging</p><p>Review the rubric below to see how you will be graded.</p><p>Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Theory Description</p><p>8 points The presentation effectively describes one type of interstellar travel and the technology involved.</p><p>7-6 points The presentation adequately describes one type of interstellar travel and the technology involved.</p><p>5-0 points The presentation does not adequately describe one type of interstellar travel and the technology involved.</p><p>8</p><p>Benefits and Limitations</p><p>8 points The presentation demonstrates a strong understanding of the positives and negatives of this type of interstellar travel. It contains several specific and accurate details.</p><p>7-6 points The presentation demonstrates a satisfactory understanding of the positives and negatives of this type of interstellar travel. It contains some specific and accurate details.</p><p>5-0 points The presentation demonstrates little to no understanding of the positives and negatives of this type of interstellar travel. It contains few to no specific and accurate details.</p><p>8</p><p>Presentation</p><p>2 points The presentation is clear and organized.</p><p>1 point The presentation is somewhat clear and organized.</p><p>0 points The presentation is not clear and organized.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Transportation Technologies lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Transportation Technologies interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ced1614a39582d7924ff33cb0bff8c0c','transportation-technologies-m12-l10-module-12-quiz','76539eb77e2c91a0868016c647c32a70','Module 12 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Interstellar Travel. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('66c2f24274819c19154931df73961ab8','transportation-technologies-course-mastery-assessment','76539eb77e2c91a0868016c647c32a70','Course Mastery Assessment','assessment',30,'<h2>Course mastery assessment</h2><p>Bring together knowledge and application from the complete course. Achieve at least 80% to satisfy the assessment requirement for certification.</p>',NULL,10,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO assessments (id,slug,course_id,title,pass_mark,questions) VALUES ('a0a48fddca0d1ccc0ba1bcc3cdede7c4','transportation-technologies-course-mastery-assessment','504e3ab88df8552a07116f12aea44099','Transportation Technologies Course Mastery Assessment',80,CAST('[{"id":"transportation-technologies-course-mastery-assessment-q1","type":"multiple-choice","prompt":"Before starting a practical task in Intro to Future Trans, which action best demonstrates professional judgement?","options":["Clarify the intended outcome, constraints, and success criteria before choosing tools.","Choose the fastest tool and define the goal afterward.","Copy the first available example without checking its fit.","Begin production immediately and leave requirements for final review."],"answer":"Clarify the intended outcome, constraints, and success criteria before choosing tools.","explanation":"Strong practice begins with a clear outcome, constraints, and measurable success criteria.","clue":"Think about what must be understood before execution begins."},{"id":"transportation-technologies-course-mastery-assessment-q2","type":"multiple-choice","prompt":"A first attempt in Flying Cars does not meet the requirement. What is the strongest next step?","options":["Compare the result with the criteria, identify the cause, revise, and test again.","Submit the attempt unchanged because the task is complete.","Replace the criteria with measures the attempt already meets.","Discard all evidence and restart without diagnosing the issue."],"answer":"Compare the result with the criteria, identify the cause, revise, and test again.","explanation":"An evidence-led improvement cycle diagnoses the gap before a focused revision and retest.","clue":"Use feedback and evidence to improve the next attempt."},{"id":"transportation-technologies-course-mastery-assessment-q3","type":"multiple-choice","prompt":"Which evidence most credibly demonstrates applied competence in Self-Driving Car Tech?","options":["A completed work sample with decisions, checks, feedback, and reflection documented.","A claim that the topic was understood without a work sample.","A list of tools with no explanation of how they were used.","An unfinished draft that has not been checked against requirements."],"answer":"A completed work sample with decisions, checks, feedback, and reflection documented.","explanation":"Competence is best demonstrated through completed, reviewed evidence and reflective reasoning.","clue":"Choose evidence that shows both the result and how quality was established."},{"id":"transportation-technologies-course-mastery-assessment-q4","type":"multiple-choice","prompt":"When work in Self-Driving Cars in Society could affect people, data, safety, or the environment, what should the learner do?","options":["Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","Proceed without checks when the intended outcome is positive.","Treat ethical and safety considerations as optional after delivery.","Hide known limitations so stakeholders remain confident."],"answer":"Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","explanation":"Responsible practice makes risk, consent, standards, and safeguards part of the work itself.","clue":"Professional quality includes the impact of the work, not only the output."},{"id":"transportation-technologies-course-mastery-assessment-q5","type":"multiple-choice","prompt":"How should a learner transfer skills from Drones to a new workplace or project context?","options":["Analyse the new context, adapt the method, test assumptions, and evaluate the result.","Repeat the original steps unchanged regardless of context.","Use only familiar methods and ignore new constraints.","Wait for a complete example to copy before making any decision."],"answer":"Analyse the new context, adapt the method, test assumptions, and evaluate the result.","explanation":"Transfer requires adapting core principles to new constraints and validating the result.","clue":"Core principles remain useful, but their application must fit the new context."}]' AS JSON)) ON DUPLICATE KEY UPDATE title=VALUES(title),pass_mark=VALUES(pass_mark),questions=VALUES(questions);
