INSERT INTO modules (id,slug,course_id,title,position) VALUES ('33c3cba13e9724707ad7754c46185969','intuit-design-for-delight-module-0','92a4f5cdddc7f69042b22cbdf20f300f','Module 0: Introduction, Purpose, Objectives, Summary',0) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('36de39f68bf49b146dc6ebc2cae21531','intuit-design-for-delight-m0-l1-teachers-guide','33c3cba13e9724707ad7754c46185969','Teachers Guide','text',12,'<h2>Teachers Guide</h2><section><h3>Intuit Design for Delight Pacing Guide</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>Intuit Design for Delight Blended Learning Guide</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>Translating the Language in a Course Page</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>How to View Students Quiz and Concept Check Answers 2</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>How to Recalculate and Sync Student Gradebooks.docx - Google D</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><section><h3>How to View Students Participation</h3><p>This supplied course resource is incorporated into the guided lesson sequence. Work through the concept with Thandi, record your key observations, and apply it in the lesson activity.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('b71ba16cc7187f3285fbf5757865977c','intuit-design-for-delight-module-1','92a4f5cdddc7f69042b22cbdf20f300f','Module 1: Intro',1) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6e6808d78e376a331726302863a6f417','intuit-design-for-delight-m1-l1-introduction-purpose-and-objectives','b71ba16cc7187f3285fbf5757865977c','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Course Intro Nav Objectives Syllabus</h3><p>Course Intro Video</p><p>Think about the last product or service you recommended to a friend. What made it stand out? In some way, it delighted you as a customer. In this course, you&#39;ll learn how to create those exceptional customer experiences. You&#39;ll dive deep into customer needs, brainstorm creative solutions, and test your ideas. You&#39;ll explore real world techniques like deep customer empathy, the go broad too narrow principle, and rapid experimentation to create experiences that people love. This course will also prepare you for the Intuit Design for Delight innovator certification. With this professional certification on your resume, you&#39;ll stand out to future employers as an innovative problem solver, and every business can benefit from team members like that. Whatever your career goals, this course gives you the tools to transform great ideas into real impact.</p><p>Course Navigation</p><p>Welcome to this course on Intuit Design for Delight !&#160;To get you started in Module 0, we have included the video below, which provides some navigation help and other details about the course.</p><p>Other sections of this Module 0 include the Course Syllabus and a Syllabus Quiz, so read&#160;through the syllabus carefully and thoroughly!</p><p>Hi and welcome to this orientation video for this course. As we go through this video, some details may differ depending on which course you are taking and the learning management system, or LMS, that your school uses, but the overall structure generally stays the same for each course.</p><p>After you complete this navigation tutorial video for module zero you should read through the course objectives, a section on sources and plagiarism, the syllabus, and finally take the syllabus quiz. Now, a few things on navigation. Within each section, you can navigate between pages either with the menu here on the left, or with the left/right arrows near the bottom. Again, that will allow you to move between PAGES within each section. Once you are done with all the pages in a section, you can either select home at the top of the course. Or you can select “Next” at the very bottom of the page to the next section. It’s very important to make sure you finish every page within a section BEFORE moving to the next section.</p><p>Ok, once you are done with Module 0, you&#39;ll move on to start your first module. Within each module there is an introduction, somewhere between 4 and 6 lessons, and then a summary and assessments at the end. First, within the introduction, if you select it, it should look something like this. Each module will start at this page which contains a 30 to 60 second introductory video that will introduce and discuss some of the concepts that you&#39;ll learn and review during this module. Let’s talk about the videos. You can also turn closed captioning on or off by clicking the CC button. Next is the setting button, where you can adjust the speed that the videos will play. Maybe you like to hear things a little faster at 1.25x. Or maybe there is a concept that is difficult, and you would like to slow down. These next two icons allow the video window to pop out, or for the video window to go full-screen. For many videos, there will also be a transcript of the video below.</p><p>The next page is a description of the module. Then we move on to objectives which explains what the student will learn during this module. Next there is typically is a polling question. Sometimes this appears at the beginning of a module and sometimes it appears at the end. But it&#39;s just a way to take a guess or to voice your opinion on a certain issue and you can click on whichever you&#39;d like and see how your answer compares to your classmates.</p><p>You will next come to a vocabulary activity. Most of these will also be at the beginning as a formative assessment, meaning that you aren&#39;t expected to know the answers but take your best guess as this is an ungraded quiz. For instance, you can pick a word drag it over and then check your answer to see that it was incorrect you keep trying again and see if you can get them all lined up. Again, this allows you to just familiarize yourself with the various vocabulary words that will be introduced in this module. Alternatively you can select on the alternative activity and it&#39;s more of a multiple choice format. So again this is an ungraded quiz. You can close it out right there. Next, we move to the lessons. As said before, there are 4 to 6 lessons within each module. So you&#39;ll see each lesson represents more or less a day&#39;s worth of work and contains a video, a reading, and then either a concept check or reflection. As you will learn in the syllabus, the introduction, video, and reading pages are graded on participation, meaning you get credit for going through every page and activity in the module. Your school may or may not be using participation, so please check with your instructor on whether or not you will be receiving participation credit in your course.</p><p>The videos and their functionality we have already talked about. Next we go into the readings which obviously will have additional content and details to read. It will also frequently contain images as well as embedded videos. These are videos that add a lot of visual detail to the materials and again just hitting play there. Some videos are longer, so we try to limit video clips to 2 to 5 minutes, so in some cases you will only see a small clip of a larger video.</p><p>After the video and reading is a concept check or reflection where you&#39;ll either input an answer or work with flashcards or maybe a sorting exercise to review and firm up the concepts that were taught in that section. The reflections are either journal entry or discussion prompts. To participate in class-wide discussion, you’ll select this link to read the questions or prompts, and then participate in the discussion by adding a new discussion topic and eventually commenting on posts from other students.&#160;You&#39;ll see this repeat itself through the rest of the sections. After which you&#39;ll find a quick summary. Once you are finished with each lesson, you see three more assignments here: the short answer assignment, the project and the quiz. The short answer assignment is generally a one to two-page paper, written after every module, that will allow you to explore and apply the princi<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('931b7387b037349e04c2e07facca8a2b','intuit-design-for-delight-module-2','92a4f5cdddc7f69042b22cbdf20f300f','Module 2: Design for Delight Concept',2) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2ce159ef5a8f8d9b7ed0ff9d98e3811d','intuit-design-for-delight-m2-l1-introduction-purpose-and-objectives','931b7387b037349e04c2e07facca8a2b','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi and welcome to this module on Design for Delight Concepts!</p><p>Let’s start off by imagining it’s a Friday night and you’re craving pizza! And you have two places to choose from. At the first pizza place, the food tastes amazing, the workers are friendly, and the service is quick. If you went there, you know you’d leave feeling happy and satisfied. But at the second pizza place, the food is burnt great, the workers don’t seem to care, and you feel like your experience didn’t matter to them. It’s a no-brainer which one you would pick, right? But why is there such a big difference? This is where Design for Delight comes in. It’s a process businesses use to make sure customers not only get what they need but also enjoy the entire experience.</p><p>In this module, we’ll explore the core ideas behind Design for Delight, which will teach you how to create products or services that make customers happy—whether it&#39;s pizza, an app, a technology product, or really anything else. We’ll introduce concepts like Deep Customer Empathy, which helps you understand the needs and feelings of your customers, and the Go Broad to Go Narrow principle, where you brainstorm many ideas and then focus on the best ones. Finally, you’ll see how Rapid Experiments with Customers allows you to quickly test your ideas and improve them based on real-world feedback. These skills are not just useful for businesses but also for creatively solving everyday problems in school and life.</p><p>By learning how to understand the relationship between problems, solutions, and benefits, you’ll gain a new perspective on what makes a great product or service. Knowing how to design with the customer in mind can help you build better, more delightful experiences for everyone.</p><p>Module Description</p><p>In this module, you will explore some of the essential principles that enhance customer experiences.&#160;You will identify and define Deep Customer Empathy, Go Broad to Go Narrow, and Rapid Experiments with Customers.&#160;You will also learn about the three metrics of customer delight and the crucial role of the customer.&#160;By examining the relationship between the customer problem, the solution, and the customer benefit, you will gain a comprehensive understanding of how these elements interconnect.&#160;Additionally, you will explore looping concepts, which involve iterative processes to refine solutions continuously.&#160;Finally, you will define and describe the importance of prototyping and experimentation, gaining practical insights into creating and testing prototypes to drive innovation and delight your customers.</p><p>Objectives</p><p>In this module, students will:</p><p>Identify and define the Deep Customer Empathy principle, the Go Broad to Go Narrow principle, and the Rapid Experiments with Customers principle.</p><p>Identify the three metrics of customer delight and the role of the customer.</p><p>Describe the relationship between the customer problem, the solution, and the customer benefit.</p><p>Describe looping concepts.</p><p>Define and describe prototyping and experimentation.</p><p>Polling Question</p><p>Which do you think is the best way for customers to be involved in the creation of a new product?</p><p>collaborating with a business from the early stages&#160;giving feedback after a prototype is created&#160;having customer advisory boards that meet and provide insights&#160;allowing team members meet with and observe customers in their normal environments to understand their needs</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Definition</p><p>the ability to sense other people&#39;s emotions, coupled with the ability to imagine what someone else might be thinking or feeling</p><p>iteration</p><p>an early sketch, model, or mock-up of an idea that people can interact with and offer feedback on</p><p>empathy</p><p>the process of making successive versions or improvements to an existing product, service, or process based on feedback, data, and market demands</p><p>feedback looping</p><p>the process of using customer or employee responses (the outputs of a product, service, or process), to create a better product, service, or process</p><p>prototype</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>the ability to sense other people&#39;s emotions, coupled with the ability to imagine what someone else might be thinking or feeling</p><p>Answers for question: 1</p><p>feedback looping</p><p>empathy</p><p>iteration</p><p>prototype</p><p>2.</p><p>an early sketch, model, or mock-up of an idea that people can interact with and offer feedback on</p><p>Answers for question: 2</p><p>feedback looping</p><p>iteration</p><p>prototype</p><p>empathy</p><p>3.</p><p>the process of making successive versions or improvements to an existing product, service, or process based on feedback, data, and market demands</p><p>Answers for question: 3</p><p>empathy</p><p>feedback looping</p><p>iteration</p><p>prototype</p><p>4.</p><p>the process of using customer or employee responses (the outputs of a product, service, or process), to create a better product, service, or process</p><p>Answers for question: 4</p><p>empathy</p><p>iteration</p><p>prototype</p><p>feedback looping</p><p>Definition</p><p>a persistent or recurring problem (as with a product or service) that frequently inconveniences or annoys customers</p><p>ideation</p><p>the process of developing and conveying prescriptive ideas to others, typically in a business setting</p><p>synergy</p><p>the&#160;interaction of elements that when combined produce a total effect that is greater than the sum</p><p>scaling</p><p>a way to grow a company while maintaining or increasing profitability</p><p>pain point</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>a persistent or recurring problem (as with a product or service) that frequently inconveniences or annoys customers</p><p>Answers for question: 1</p><p>scaling</p><p>ideation</p><p>pain point</p><p>synergy</p><p>2.</p><p>the process of developing and conveying prescriptive ideas to others, typically in a business setting</p><p>Answers for question: 2</p><p>scaling</p><p>ideati<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('39630bfdede27b560b4e5196ee8d898c','intuit-design-for-delight-m2-l2-lesson-1','931b7387b037349e04c2e07facca8a2b','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>What is Intuit Design for Delight</h3><p>What is Intuit Design for Delight</p><p>Hi and welcome to Lesson 1 for this module on Design for Delight Concepts!</p><p>When starting a new business, you want to create a product that people will love! But where do you begin? How do you make sure your product is exactly what customers need, even if they don&#39;t know it yet? These are questions that companies like Intuit have been quite successful in answering. Founded in 1983, Intuit is best known for its popular financial software products like TurboTax, QuickBooks, and Mint. These products didn’t become household names by chance. They became indispensable tools for millions because Intuit has a powerful approach to understanding its customers and designing products that delight them.</p><p>One of the key concepts that we’ll explore in this course on Design for Delight is empathy, but not just any empathy—deep customer empathy. At a basic level, empathy involves understanding and sharing the feelings of another person. For example, if you see a friend struggling with their homework and feel bad for them, that&#39;s empathy. However, deep customer empathy goes beyond just understanding a customer&#39;s feelings; it involves immersing oneself in the customer&#39;s world to gain comprehensive insights into their behaviors, motivations, and pain points. This means not just guessing what might help a customer but actually walking in their shoes to experience their challenges firsthand. For instance, when designing TurboTax, Intuit didn’t just think about what people might need to file taxes; they studied how real people interacted with their finances, identified where they got stuck, and then built solutions that made the process easier and even enjoyable.</p><p>Deep customer empathy lays the foundation for what happens next: brainstorming. However, true brainstorming isn&#39;t as simple as just throwing out a few ideas. It’s about creating an environment where no idea is off-limits. Often, when we try to come up with new ideas, we tend to self-limit. We reject ideas before they’re even fully formed! This might be because they seem too wild, too impractical, or just plain weird. But in true brainstorming sessions, especially at innovative companies, the goal is to suspend judgment and explore every possibility. This approach ensures that even the most unconventional ideas get a chance to be heard. After all, some of the best innovations (like the car, rocket, or smartphone) come from ideas that initially seem far-fetched.</p><p>Once you have a collection of ideas, the next step is to test them. And this is where lean experimentation and minimum viable products (or MVPs) come into play. Lean experimentation is a process where companies quickly test ideas with real customers to see what works and what doesn’t. Instead of spending years perfecting a product only to find out it’s not what customers want, companies use MVPs—a stripped-down version of the product that includes just enough features to test its core functionality. This approach benefits both companies and customers. For companies, it means less wasted time and resources because they can pivot quickly, or improve their product based on real feedback. For customers, it means they get products that are more aligned with their needs. This is because their feedback directly influences the product&#39;s development.</p><p>When you put all these pieces together—deep customer empathy, true brainstorming, and lean experimentation—you get the core of what Intuit calls &quot;Design for Delight.&quot; This approach is about more than just creating products; it&#39;s about creating experiences that customers truly love. And the examples we’ll cover throughout the course will cover physical products like a sweater or a cup of coffee, or services like tax return preparation or consulting. The Design for Delight approach is applicable in any business setting, and even other organizations like schools or non profits as well.</p><p>By deeply understanding the customer, encouraging limitless creativity, and testing ideas quickly, companies can design products that not only meet a customer’s needs but also surprise and delight them in ways they never expected.</p><p>In the end, whether you&#39;re designing financial software (like Intuit) or starting your own new business with an innovative product, these principles are foundational. Empathy allows you to understand your customers and their pain points better, brainstorming opens up the door to innovation, and lean experimentation ensures you&#39;re on the right track. When combined, these elements create a powerful strategy for success!</p><p>What is Intuit Design for Delight?</p><p>Intuit, a global financial software company known for products like TurboTax, QuickBooks, and Mint, has cultivated a unique design philosophy called Design for Delight (D4D).&#160;This methodology is centered on deeply understanding customers and creating solutions that not only meet their needs but also delight them.&#160;The D4D approach is built on three core principles:&#160;Deep Customer Empathy, Go Broad to Go Narrow, and Rapid Experiments with Customers.&#160;This section provides a comprehensive overview of each principle, defining its significance and illustrating how it contributes to Intuit’s success in delivering exceptional user experiences.</p><p>Deep Customer Empathy</p><p>Let&#39;s discuss the first principle:&#160;Deep Customer Empathy.&#160;Deep Customer Empathy is the principle of profoundly understanding the needs, motivations, and experiences of customers.&#160;It goes beyond surface-level interactions and delves into the emotional and contextual aspects of customers’ lives.&#160;This empathy is not just about recognizing what customers say they need, but also about uncovering latent needs and pain points that they may not be able to articulate themselves.</p><p>Expand the sections below to learn how Deep Customer Empathy can be implemented.</p><p>Observation and Engagement</p><p>Teams engage directly with customers through interviews, observations, and immersive experiences. They spend time in the customer’s environment to see how they interact with products and services in real-world contexts.</p><p>Empathy Mapping</p><p>This tool helps visualize what customers are thinking, feeling, saying, and doing. It aids in understanding their experiences in multiple dimensions and identifying a<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('89d859586ec14a0d441101813c5324f1','intuit-design-for-delight-m2-l3-lesson-2','931b7387b037349e04c2e07facca8a2b','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Metrics of Customer Delight</h3><p>Metrics of Customer Delight</p><p>Metrics of Customer Delight and the Role of the Customer</p><p>The D4D framework is not only a methodology for designing exceptional products but also a philosophy that places the customer at the center of the innovation process.&#160;Central to this approach are the three key metrics of customer delight that guide Intuit’s product development and the essential role that customers play in this process.&#160;This section explores these metrics and the pivotal role of customers in ensuring that products truly delight and serve their needs.</p><p>Three Metrics of Customer Delight</p><p>To measure the success of its Design for Delight approach, Intuit focuses on three primary metrics of customer delight:&#160;Customer Satisfaction (CSAT), Net Promoter Score (NPS), and Customer Effort Score (CES).&#160;Each of these metrics provides unique insights into different aspects of the customer experience.</p><p>Press through each tab below to learn about the details of these metrics.</p><p>Customer Satisfaction (CSAT)</p><p>Definition</p><p>Customer Satisfaction (CSAT) measures how satisfied customers are with a product, service, or specific interaction.&#160;It is typically gauged through surveys that ask customers to rate their satisfaction on a scale (e.g., 1 to 5 or 1 to 10).</p><p>Importance</p><p>CSAT provides direct feedback on customer happiness and immediate satisfaction with a product or service.&#160;High CSAT scores indicate that customers’ needs and expectations are being met effectively.</p><p>Implementation</p><p>Surveys:&#160;After key interactions or at regular intervals, customers are asked to rate their satisfaction.</p><p>Feedback Analysis:&#160;Responses are analyzed to identify common themes, strengths, and areas for improvement.</p><p>Net Promoter Score (NPS)</p><p>Definition</p><p>Net Promoter Score (NPS) measures the likelihood that customers would recommend a product or service to others. Customers respond to the question: “On a scale of 0 to 10, how likely are you to recommend our product/service to a friend or colleague?”</p><p>Importance</p><p>NPS is a powerful indicator of customer loyalty and overall satisfaction. A high NPS suggests that customers are not only satisfied but also willing to act as promoters, enhancing word-of-mouth marketing and driving growth.</p><p>Implementation</p><p>Survey Question:&#160;The single NPS question is included in customer surveys.</p><p>Promoters, Passives, Detractors:&#160;Customers are categorized based on their scores (Promoters: 9-10, Passives: 7-8, Detractors: 0-6). The NPS is calculated by subtracting the percentage of detractors from the percentage of promoters.</p><p>Customer Effort Score (CES)</p><p>Definition</p><p>Customer Effort Score (CES) measures how easy it is for customers to interact with a company and resolve issues. Customers are asked to rate the ease of their experience, often with statements like: “The company made it easy for me to handle my issue.”</p><p>Importance</p><p>CES highlights the friction points in the customer journey. Lower effort scores indicate a smoother, more convenient experience, which is critical for customer satisfaction and retention.</p><p>Implementation</p><p>Ease of Experience Surveys:&#160;After interactions with customer service or using the product, customers rate the ease of their experience.</p><p>Process Improvement:&#160;Feedback is used to streamline processes, simplify interfaces, and reduce customer effort.</p><p>Next Tab</p><p>The Role of the Customer in Design for Delight</p><p>In Intuit’s D4D framework, customers play an indispensable role in the design and development process.&#160;Their involvement ensures that products are tailored to real needs and preferences, fostering deeper engagement and satisfaction.</p><p>Let&#39;s further explore the role of the customer.&#160;Press the plus (+) in each box below to learn more.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Four boxes explaining the role of the customer in D4D Co-Creation and Collaboration Continuous Feedback Customer Advocacy Human-Centered Design</p><p>The hotspot points on the image are as follows:</p><p>Co-Creation and Collaboration</p><p>Involvement</p><p>Customers are involved in the early stages of product development through co-creation sessions, workshops, and feedback loops. They help identify pain points, suggest features, and validate concepts.</p><p>Benefits</p><p>Co-creation fosters a sense of ownership and connection among customers. It ensures that products are built with a clear understanding of user needs and that solutions are relevant and practical.</p><p>Continuous Feedback</p><p>Mechanism</p><p>Intuit actively seeks continuous feedback from customers throughout the product lifecycle. This includes beta testing, usability testing, and regular surveys.</p><p>Benefits</p><p>Continuous feedback allows for real-time improvements and iterations. It ensures that products evolve based on actual user experiences and changing needs, enhancing relevance and user satisfaction.</p><p>Human-Centered Design</p><p>Approach</p><p>Human-centered design at Intuit involves empathy and immersion in customers’ lives. Teams spend time with customers in their environments, understanding their daily routines, challenges, and contexts.</p><p>Benefits</p><p>This deep immersion leads to products that are not only functional but also emotionally resonant. It ensures that solutions fit seamlessly into customers’ lives, addressing both explicit and latent needs.</p><p>Customer Advocacy</p><p>Empowerment</p><p>Intuit empowers its customers to act as advocates by creating delightful experiences that they are eager to share. Programs like customer advisory boards and advocacy groups enable customers to provide strategic insights and promote products within their networks.</p><p>Benefits</p><p>Customer advocates help drive organic growth through word-of-mouth referrals and authentic endorsements. This not only boosts the company’s reputation but also builds a loyal customer base.</p><p>The metrics of customer delight—Customer Satisfaction (CSAT), Net Promoter Score (NPS), and Customer Effort Score (CES)—are critical in guiding Intuit’s Design for Delight approach.&#160;These metrics provide valuable insights into customer experiences, satisfaction, and loyalty<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9ce56a1db58ea2bb1d7b53dead0715de','intuit-design-for-delight-m2-l4-lesson-3','931b7387b037349e04c2e07facca8a2b','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Customer Problem &amp; Solution</h3><p>Customer Problem &amp; Solution</p><p>The Interplay of Customer Problem, Solution, and Benefit in D4D</p><p>As you have learned, the D4D approach emphasizes the importance of deeply understanding customer problems, designing effective solutions, and ensuring that these solutions translate into tangible customer benefits.&#160;In this section, we will explore the relationship between the customer problem, the solution, and the customer benefit within the context of Intuit&#39;s D4D framework.</p><p>Understanding the Customer Problem</p><p>A customer problem is a specific issue or pain point that a customer experiences.&#160;It may be a task that is difficult to complete, a goal that is hard to achieve, or an aspect of life that could be significantly improved with the right solution.&#160;Identifying and understanding these problems is the first step in Intuit’s D4D process.</p><p>Accurately identifying the customer problem is crucial because it ensures that the development efforts are focused on real, impactful issues.&#160;Misunderstanding or overlooking customer problems can lead to solutions that are ineffective or irrelevant, wasting resources and potentially alienating customers.</p><p>Press through the tabs to learn about identifying customer problems and pain points.</p><p>Empathy and Immersion</p><p>Intuit teams immerse themselves in customers&#39; lives to observe and understand their experiences.&#160;This includes shadowing customers, conducting in-depth interviews, and using empathy mapping to capture emotional and practical aspects of their problems.</p><p>Data and Feedback Analysis</p><p>Customer feedback from various sources—surveys, support calls, social media, and product reviews—is systematically analyzed to identify common pain points and areas of frustration.</p><p>Customer Journey Mapping</p><p>By mapping out the end-to-end customer journey, Intuit identifies critical touchpoints where customers encounter difficulties, thereby highlighting opportunities for improvement.</p><p>Check out the video below to watch how a customer journey map is created.</p><p>Next Tab</p><p>Let’s put ourselves in the shoes of a customer a customer buying… shoes! To truly understand this customer’s experience, we use a powerful tool called the Customer Journey Map.&quot;</p><p>A Customer Journey Map breaks down the experience into 5 key stages: Awareness, Consideration, Purchase, Use, and Support.</p><p>At each stage, we document what the customer does, thinks, and feels. This helps us visualize their entire experience.</p><p>Journey mapping also highlights critical touchpoints—moments where the customer interacts directly with your product. Here, they might encounter difficulties, like a confusing payment process.</p><p>These are pain points—areas where customers may experience frustration or confusion. Identifying these is crucial because every negative experience is a chance for improvement.</p><p>By mapping the journey and identifying pain points, we can design better solutions. Whether it’s increasing awareness, simplifying a purchase process, or offering better support, each improvement enhances the overall experience.</p><p>A well-crafted Customer Journey Map doesn’t just tell you where your customers have been—it shows you where you can take them. And that makes all the difference in designing delightful experiences. Start mapping your customer journey today and discover how small changes can lead to big impacts.</p><p>Crafting the Solution</p><p>A solution is a product, feature, or service designed to address a specific customer problem.&#160;In the context of Intuit’s D4D, solutions are crafted with a deep understanding of the customer problem and are iteratively developed to ensure they effectively meet customer needs.</p><p>Creating a well-crafted solution that directly addresses the identified customer problem is essential for delivering value.&#160;Solutions that are not closely aligned with customer needs can lead to poor adoption and customer dissatisfaction.</p><p>Press through the tabs to learn about the development process of crafting a solution.</p><p>Ideation and Brainstorming</p><p>Using the Go Broad to Go Narrow principle, Intuit encourages the generation of a wide range of ideas through brainstorming sessions.&#160;This divergent thinking phase ensures that no potential solution is overlooked.</p><p>Prototyping and Experimentation</p><p>The most promising ideas are quickly prototyped and tested with real customers. Rapid Experiments with Customers allow Intuit to gather feedback and make necessary adjustments early in the development process.</p><p>Iterative Refinement</p><p>Based on customer feedback, solutions are continuously refined. This iterative approach ensures that the final product is both effective in solving the customer problem and user-friendly.</p><p>Next Tab</p><p>Using the Go Broad to Go Narrow principle, Intuit encourages the generation of a wide range of ideas through brainstorming sessions.&#160;This divergent thinking phase ensures that no potential solution is overlooked.</p><p>Realizing the Customer Benefit</p><p>The customer benefit is the tangible and intangible value that customers receive from using the solution.&#160;Benefits can include time savings, increased efficiency, reduced stress, and improved financial outcomes, among others.</p><p>Delivering clear and significant customer benefits is the ultimate goal of the D4D approach.&#160;When customers experience real value from a solution, it leads to higher satisfaction, loyalty, and positive word-of-mouth, driving business success.</p><p>Press through the tabs to learn about the realization process.</p><p>Ease of Use and Accessibility</p><p>Intuit ensures that solutions are intuitive and easy to use, minimizing the effort required by customers to achieve their goals.&#160;The Customer Effort Score (CES) is often used to measure this aspect.</p><p>Outcome Measurement</p><p>The effectiveness of the solution is measured through key metrics such as Customer Satisfaction (CSAT) and Net Promoter score (NPS). These metrics help quantify the benefits experienced by customers.</p><p>Continuous Improvement</p><p>Even after a solution is launched, Intuit continues to gather feedback and make improvements. This ensures that the solution remains relevant and continues to deliver benefits over time.</p><p>Next Tab</p><p>The Interrelationsh<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('85ee7bf070a6650242d87bee56f9eaea','intuit-design-for-delight-m2-l5-lesson-4','931b7387b037349e04c2e07facca8a2b','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Looping Concept for Testing</h3><p>Looping Concept for Testing</p><p>Intuit&#39;s D4D methodology is built around the continuous improvement and refinement of products to ensure they consistently meet and exceed customer expectations.&#160;Central to this process are looping concepts, which facilitate iterative development and ensure that customer feedback is integrated at every stage.&#160;This section explores the looping concepts within D4D, their significance, and how they contribute to the creation of delightful customer experiences.</p><p>What are Looping Concepts?</p><p>Looping concepts refer to iterative cycles of testing, feedback, and refinement.&#160;Rather than following a linear, one-time development process, looping allows teams to continuously improve their products based on real-world user feedback.&#160;This approach helps in identifying issues early, adapting to changing needs, and ultimately delivering solutions that truly delight customers.</p><p>Let&#39;s examine the looping concepts in D4D.</p><p>Empathy Loop</p><p>The Empathy Loop involves continuously understanding and re-understanding customer needs, motivations, and pain points.&#160;This loop emphasizes the importance of staying connected with customers throughout the product development process.</p><p>The Empathy Loop ensures that the team remains aligned with the customer’s evolving needs and experiences.&#160;It helps in uncovering latent needs that customers might not explicitly articulate but are crucial for delivering a delightful product.</p><p>Expand the sections below to learn about the process.</p><p>Observation</p><p>Regularly observe customers using the product in their natural environment to gain insights into their behaviors and challenges.</p><p>Engagement</p><p>Engage with customers through interviews, surveys, and direct feedback to understand their experiences and gather new insights.</p><p>Analysis</p><p>Analyze the gathered data to identify patterns, unmet needs, and areas for improvement.</p><p>Ideation Loop</p><p>The Ideation Loop involves generating, refining, and selecting ideas through a cyclical process.&#160;This loop fosters creativity and innovation by encouraging divergent thinking followed by convergent thinking.</p><p>The Ideation Loop ensures that no potential solution is overlooked and that the best ideas are selected for development.&#160;It fosters a creative environment where innovation thrives, leading to solutions that can significantly enhance customer delight.</p><p>Expand the sections below to learn about the process.</p><p>Brainstorming</p><p>Conduct brainstorming sessions to generate a wide array of potential solutions without immediate judgment or dismissal of ideas.</p><p>Evaluation</p><p>Evaluate the generated ideas based on feasibility, impact, and alignment with customer needs.</p><p>Prototyping</p><p>Develop prototypes of the most promising ideas to visualize and test them.</p><p>Experimentation Loop</p><p>The Experimentation Loop involves testing prototypes with real customers, gathering feedback, and iterating based on the results.&#160;This loop is crucial for validating assumptions and ensuring that the product effectively addresses customer problems.</p><p>The Experimentation Loop reduces the risk of launching a product that fails to meet customer expectations.&#160;By continuously testing and iterating, Intuit can ensure that the final product is polished, user-friendly, and aligned with customer needs.</p><p>Expand the sections below to learn about the process.</p><p>Prototype Testing</p><p>Test prototypes with a selected group of customers to gather initial feedback on usability, functionality, and overall satisfaction.</p><p>Feedback Collection</p><p>Collect detailed feedback from customers through surveys, interviews, and observation during testing sessions.</p><p>Iteration</p><p>Refine the prototype based on the feedback and repeat the testing process until the product meets the desired standards.</p><p>Implementation Loop</p><p>The Implementation Loop involves the final stages of product development, including scaling, launching, and ongoing improvement.&#160;This loop ensures that the product remains relevant and continues to deliver value post-launch.</p><p>The Implementation Loop ensures that the product not only successfully reaches the market but also continues to evolve based on user feedback.&#160;It reinforces Intuit’s commitment to long-term customer delight and product excellence.</p><p>Expand the sections below to learn about the process.</p><p>Scaling</p><p>Prepare the product for wider release, ensuring that it can handle increased usage and integrate smoothly with existing systems.</p><p>Launch</p><p>Introduce the product to the broader market with a strategic rollout plan that includes marketing, customer support, and training.</p><p>Continuous Improvement</p><p>Post-launch, continue to collect customer feedback and make iterative improvements to enhance the product’s performance and customer satisfaction.</p><p>Case Study:&#160;Intuit Turbo Tax</p><p>Let&#39;s look at a real-life example of how these iterative processes were used to improve Intuit&#39;s Turbo Tax, a home tax preparation software product.&#160;Press through each tab below to review what happened during each looping concept.</p><p>Empathy Loop</p><p>The Empathy Loop involved observing customers during the tax filing season.&#160;Teams conducted in-home visits to see how users interacted with the software and where they encountered difficulties.&#160;This deep understanding helped identify specific pain points, such as confusion over tax deductions and frustration with data entry.</p><p>Ideation Loop</p><p>Based on insights from the Empathy Loop, the Ideation Loop generated multiple ideas to simplify the tax filing process. Brainstorming sessions led to innovative features like automated data imports from financial institutions and step-by-step guidance.</p><p>Experimentation Loop</p><p>Prototypes of these new features were tested with a group of customers. Feedback revealed that while users appreciated the automated data import, the step-by-step guidance needed more clarity. Iterative refinements were made to enhance the user interface and instructions.</p><p>Implementation Loop</p><p>After successful iterations, the refined features were scaled and integrated into the final product. Post-launch, continuous feedback was collected, leading to furth<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('610ed07745711486579d80d5970e5e93','intuit-design-for-delight-m2-l6-lesson-5','931b7387b037349e04c2e07facca8a2b','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Prototyping &amp; Experimentation</h3><p>Prototyping &amp; Experimentation</p><p>Prototyping and Experimentation</p><p>Central to the Design for Delight methodology are the practices of prototyping and experimentation.&#160;These practices enable Intuit to iteratively develop and refine products by actively engaging with customers throughout the design process.&#160;This section delves into the concepts of prototyping and experimentation within the context of D4D, defining their roles, processes, and benefits.</p><p>What is Prototyping?</p><p>Prototyping is the process of creating preliminary models or simulations of a product to explore ideas and validate concepts.&#160;Prototypes can range from simple sketches and wireframes to more complex interactive models.&#160;In the context of D4D, prototyping is used to quickly and effectively visualize ideas, test hypotheses, and gather feedback from users.</p><p>Types of Prototypes</p><p>Low-Fidelity Prototypes</p><p>Sketches and Wireframes:&#160;Basic representations of concepts, focusing on layout and structure.</p><p>Paper Prototypes:&#160;Hand-drawn versions of the product interface that can be used in usability testing.</p><p>Medium-Fidelity Prototypes</p><p>Digital Mockups:&#160;More detailed designs created using design tools like Figma or Sketch, providing a better sense of look and feel.</p><p>Interactive Prototypes:&#160;Clickable versions of digital mockups that simulate user interactions.</p><p>High-Fidelity Prototypes</p><p>Fully Functional Models:&#160;Near-complete versions of the product with functional features, allowing for more realistic user testing.</p><p>Beta Versions:&#160;Early releases of the product that are distributed to a limited audience for real-world testing.</p><p>Next Tab</p><p>Prototyping Process</p><p>Press the plus (+) in each section below to learn about that part of the prototyping process.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Prototyping Process: Idea generation Prototype development User testing Iteration</p><p>The hotspot points on the image are as follows:</p><p>Idea Generation</p><p>Start with brainstorming and sketching out initial ideas based on customer insights and identified problems.</p><p>Prototype Development</p><p>Create prototypes at varying levels of fidelity, depending on the stage of development and specific goals.</p><p>User Testing</p><p>Present prototypes to customers to gather feedback on usability, functionality, and overall experience.</p><p>Iteration</p><p>Refine and improve the prototypes based on user feedback, repeating the cycle as needed.</p><p>Importance of Prototyping</p><p>Prototypes help translate abstract ideas into tangible forms, making it easier to communicate concepts and gather feedback.&#160;It&#160;allows for early testing of ideas, helping to identify potential issues and validate assumptions before significant resources are invested.&#160;By involving users in the testing process, prototypes ensure that the product is designed with the customer’s needs and preferences in mind.</p><p>Experimentation in Design for Delight</p><p>Experimentation involves systematically testing hypotheses and iterating on solutions based on empirical evidence and user feedback.&#160;In D4D, experimentation is a continuous process of learning and refining, ensuring that the final product is not only functional but also delightful for customers.</p><p>Press through each tab below to learn about the experimentation process, types of experiments, and the importance of experimentation.</p><p>Experimentation Process</p><p>Hypothesis Formation:&#160;Based on customer insights and feedback, formulate hypotheses about how specific features or changes will impact the user experience.</p><p>Designing Experiments:&#160;Develop experiments to test these hypotheses, using prototypes to simulate the product or feature in question.</p><p>Testing:&#160;Conduct experiments with real users in controlled settings or real-world environments to gather data on user interactions and feedback.</p><p>Data Analysis:&#160;Analyze the results of the experiments to determine whether the hypotheses are supported or refuted.</p><p>Iteration:&#160;Use the insights gained from experimentation to refine the product, continually testing and iterating until the desired outcomes are achieved.</p><p>Types of Experiments</p><p>Usability Testing:&#160;Observing users as they interact with the prototype to identify usability issues and areas for improvement.</p><p>A/B Testing:&#160;Comparing two versions of a feature or design to see which one performs better in terms of user engagement and satisfaction.</p><p>Surveys and Interviews:&#160;Collecting qualitative feedback from users to understand their experiences and preferences.</p><p>Field Trials:&#160;Deploying prototypes in real-world settings to observe how they perform in actual use cases.</p><p>Importance of Experimentation</p><p>Evidence-Based Decisions:&#160;Experimentation provides empirical data that helps in making informed decisions about product features and design changes.</p><p>Risk Mitigation:&#160;By testing ideas early and often, experimentation reduces the risk of launching a product that fails to meet customer needs or expectations.</p><p>Continuous Improvement:&#160;Experimentation fosters a culture of continuous learning and improvement, ensuring that products evolve in response to user feedback and changing needs.</p><p>Next Tab</p><p>Integration of Prototyping and Experimentation in D4D</p><p>Synergistic Relationship</p><p>Prototyping and experimentation are closely intertwined in the D4D methodology.&#160;Prototypes serve as the foundation for experimentation, providing the tangible models needed to test hypotheses and gather user feedback.&#160;Conversely, experimentation informs the development of prototypes, guiding iterations and improvements based on empirical data.</p><p>Iterative Cycles</p><p>The iterative cycles of prototyping and experimentation involve the steps below.&#160;Press the plus (+) in each circle to learn more.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Identify Customer Problems:&#160;Use empathy and customer insights to identify key problems and pain points. Generate Ideas:&#160;Brainstorm potential solutions and create low-fidelity prototype<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('23eae32d2eb3b4c34e5a185ec4ebd600','intuit-design-for-delight-m2-l7-module-1-summary','931b7387b037349e04c2e07facca8a2b','Module 1 Summary','text',12,'<h2>Module 1 Summary</h2><section><h3>Module 1 Summary</h3><p>Module 1 Summary</p><p>Great Work!&#160;You have successfully completed this module on Design for Delight Concepts.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified and defined the Deep Customer Empathy principle, the Go Broad to Go Narrow principle, and the Rapid Experiments with Customers principle.</p><p>Identified the three metrics of customer delight and the role of the customer.</p><p>Described the relationship between the customer problem, the solution, and the customer benefit.</p><p>Described looping concepts.</p><p>Defined and described prototyping and experimentation.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a9e1a433d14441594ce6d8e933423d39','intuit-design-for-delight-m2-l8-module-1-test-prep','931b7387b037349e04c2e07facca8a2b','Module 1 Test Prep','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Design for Delight Concept. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,7,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c0970110eee6191e6eaf79a1733b782c','intuit-design-for-delight-m2-l9-module-1-assignment','931b7387b037349e04c2e07facca8a2b','Module 1 Assignment','text',12,'<h2>Module 1 Assignment</h2><section><h3>Module 1 Assignment</h3><p>Module 1 Assignment</p><p>Intuit Design for Delight</p><p>Design for Delight Concepts - Short Answer Assignment</p><p>Short answer assignment</p><p>In this module, you learned about the metrics of customer delight and the role of the customer in designing products.&#160;For this writing assignment, write a two-page, double-spaced paper addressing the questions/topics listed.</p><p>Explain the importance of each of the three primary metrics used by Intuit to measure customer delight: Customer Satisfaction (CSAT), Net Promoter Score (NPS), and Customer Effort Score (CES). How do they contribute to understanding customer experiences?</p><p>Describe the various ways customers are involved in Intuit&#39;s design and development process, including co-creation and collaboration, continuous feedback, customer advocacy, and human-centered design. How do these practices ensure that Intuit&#39;s products are aligned with real customer needs and preferences?</p><p>Based on the reading, how would you apply the concepts of customer delight metrics and customer involvement in a project or product development you are interested in?</p><p>Consider a product or service you use frequently. How could the company behind it benefit from implementing Intuit&#39;s Design for Delight principles? Provide specific suggestions.</p><p>Review the rubric below to determine how you will be graded.</p><p>Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('57ad6c9de7cb9f1c176eb1d7fa20858a','intuit-design-for-delight-m2-l10-module-1-project','931b7387b037349e04c2e07facca8a2b','Module 1 Project','text',12,'<h2>Module 1 Project</h2><section><h3>Module 1 Project</h3><p>Module 1 Project</p><p>Intuit Design for Delight</p><p>Design for Delight Concepts - Project</p><p>Project</p><p>Intuit Design for Delight is built on three core principles:</p><p>Deep Customer Empathy</p><p>Go Broad to Go Narrow</p><p>Rapid Experiments with Customers</p><p>Imagine that you are creating a product. It can be anything you want. It can be your version of something that already exists or something you create. In a slide presentation, describe how you would utilize the core principles to develop or improve your product. Your presentation should:</p><p>Describe your product.</p><p>Create at least two slides for each of the core principles.</p><p>On each one, describe a way that you would implement that principle.</p><p>For example, for Deep Customer Empathy, you might describe an immersive experience a customer has with your product.</p><p>Conclude with a summary page about how the three principles would help you align your product with what customers need.</p><p>Utilize relevant images or other graphics to make your presentation visually appealing and engaging.</p><p>Review the rubric below to determine how you will be graded.</p><p>Design for Delight Concepts Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Content</p><p>8 points The content shows a strong understanding of the three core principles in Design for Delight. Each principle is explained well, and the implementation examples are well thought out and relevant.</p><p>7-4 points The content shows an understanding of the three core principles in Design for Delight. Each principle is explained fairly well, and the implementation examples are mostly relevant.</p><p>3-0 points The content shows little to no understanding of the three core principles in Design for Delight. The examples are not relevant.</p><p>8</p><p>Presentation</p><p>8 points The presentation follows the guidelines. The content is engaging and visually appealing.</p><p>7-6 points The presentation mostly follows the guidelines. The content is relatively engaging and visually appealing.</p><p>5-0 points The presentation does not follow the guidelines.</p><p>8</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Formatting</p><p>2 points Project is formatted according to stated instructions.</p><p>0 points Project is not formatted according to stated instructions.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,9,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('d3560dbc07698d78f057ff5c09e1fa72','intuit-design-for-delight-m2-l11-module-1-quiz','931b7387b037349e04c2e07facca8a2b','Module 1 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Design for Delight Concept. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,10,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('77ece592a88bec397ade3692f0ec7025','intuit-design-for-delight-module-3','92a4f5cdddc7f69042b22cbdf20f300f','Module 3: Customer Empathy Part 1',3) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('20133c06c60ea4c072b1a2f5e9131f9d','intuit-design-for-delight-m3-l1-introduction-purpose-and-objectives','77ece592a88bec397ade3692f0ec7025','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi and welcome to this module on Developing Deep Customer Empathy Part 1!</p><p>Don’t you hate it when products don’t work like they should? Let’s say you buy a brand-new pair of wireless earbuds, only to find out they constantly disconnect or the sound cuts out when you move. Frustrating, right? Now, imagine if the company that made those earbuds had observed people using them. They noticed these problems before you experienced them. They could have fixed the issues and delivered a product that works exactly as you expect. That’s the power of learning about customers through observation, and in this module, you’ll discover how to use that skill to create better products and services.</p><p>We’ll start by focusing on how to observe customers and identify the specific challenges they face. From there, you’ll learn how to summarize what you’ve observed and turn it into a customer problem statement—a clear definition of the issue that needs to be solved. You’ll also learn the key components of a problem statement and how to craft one yourself, using real-world situations to practice. Finally, you’ll take it a step further by imagining the ideal customer state—what the perfect experience would look like once the problem is solved.</p><p>Learning how to observe and respond to customer needs is a valuable skill that will help you make a difference.</p><p>Module Description</p><p>In this module, you will learn how to understand your customers deeply through careful observation, allowing you to identify their key challenges accurately.&#160;You will develop insights about your observations through discussions and reflections.&#160;From there, you will define a clear and concise customer problem statement.&#160;Finally, you will conceptualize the ideal customer state, envisioning the best possible outcome for your customers based on your findings and insights.</p><p>Objectives</p><p>In this module, students will</p><p>Learn about customers through observation.</p><p>Identify the customer challenge.</p><p>Summarize what you learned</p><p>Define the customer problem statement.</p><p>Identify the components of a customer problem statement.</p><p>Given a situation, create or complete a customer problem statement</p><p>Conceptualize the ideal customer state.</p><p>Polling Question</p><p>Which of the following do you think would be the best way to identify customer challenges?</p><p>customer interviews&#160;surveys&#160;shadowing customers&#160;using customer support data&#160;social media monitoring</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Definition</p><p>watching interactions, processes, or behaviors as they occur</p><p>customer-centric</p><p>capturing interactions through recorded sessions or analytics, providing a broader data set for analysis</p><p>usability testing</p><p>a method of determining the functionality of a&#160; product by observing real users as they attempt to utilize it</p><p>indirect observation</p><p>a business strategy that prioritizes the client experience and building long-term relationships</p><p>direct observation</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>watching interactions, processes, or behaviors as they occur</p><p>Answers for question: 1</p><p>usability testing</p><p>customer-centric</p><p>direct observation</p><p>indirect observation</p><p>2.</p><p>capturing interactions through recorded sessions or analytics, providing a broader data set for analysis</p><p>Answers for question: 2</p><p>direct observation</p><p>indirect observation</p><p>usability testing</p><p>customer-centric</p><p>3.</p><p>a method of determining the functionality of a&#160; product by observing real users as they attempt to utilize it</p><p>Answers for question: 3</p><p>indirect observation</p><p>customer-centric</p><p>direct observation</p><p>usability testing</p><p>4.</p><p>a business strategy that prioritizes the client experience and building long-term relationships</p><p>Answers for question: 4</p><p>usability testing</p><p>indirect observation</p><p>customer-centric</p><p>direct observation</p><p>Definition</p><p>an articulation of the specific challenges or pain points that clients experience</p><p>ideal customer state</p><p>a representation of the person or people who buy a company&#39;s products or services</p><p>customer persona</p><p>a circumstance where customers are not just satisfied but genuinely delighted with their interactions and experience</p><p>empathy mapping</p><p>a team process that helps to identify the thoughts and feelings of a particular group of customers about a specific issue; captures what customers say, think, feel, and do regarding the problem</p><p>customer problem statement</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>an articulation of the specific challenges or pain points that clients experience</p><p>Answers for question: 1</p><p>customer problem statement</p><p>empathy mapping</p><p>ideal customer state</p><p>customer persona</p><p>2.</p><p>a representation of the person or people who buy a company&#39;s products or services</p><p>Answers for question: 2</p><p>empathy mapping</p><p>customer problem statement</p><p>ideal customer state</p><p>customer persona</p><p>3.</p><p>a circumstance where customers are not just satisfied but genuinely delighted with their interactions and experience</p><p>Answers for question: 3</p><p>ideal customer state</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('247c9ac9bd0f370767ae8c57a6ef6574','intuit-design-for-delight-m3-l2-lesson-1','77ece592a88bec397ade3692f0ec7025','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Learning Through Customer Observation</h3><p>Learning Through Customer Observation</p><p>Learning About Customers Through Observation</p><p>Understanding customers deeply is at the heart of Intuit&#39;s Design for Delight (D4D) methodology.&#160;One of the most effective ways to gain this understanding is through direct observation.&#160;This practice allows designers and developers to see firsthand how customers interact with products, uncovering insights that may not surface through surveys or interviews alone.&#160;This section explores how observation is integrated into the D4D process at Intuit, detailing its significance, methods, and benefits.</p><p>The Importance of Customer Observation</p><p>Gaining Genuine Insights</p><p>Observing customers in their natural environment provides an unfiltered view of their behaviors, challenges, and needs.&#160;Unlike self-reported data, which can be biased or incomplete, observation captures authentic interactions and reactions.</p><p>Press through the tabs below to learn more.</p><p>Real-Time Behavior</p><p>See how customers use products in real time, revealing pain points and moments of delight.</p><p>Contextual Understanding</p><p>Understand the context in which customers use the product, including environmental factors and other concurrent activities.</p><p>Unspoken Needs</p><p>Identify latent needs and frustrations that customers may not articulate but are evident through their actions.</p><p>Next Tab</p><p>Building Empathy</p><p>Empathy is crucial in designing products that truly resonate with users.&#160;By observing customers, designers can develop a deeper emotional connection and understanding of their experiences.</p><p>Press through the tabs below to learn more.</p><p>Emotional Responses</p><p>Observe emotional reactions to different aspects of the product, such as joy, frustration, or confusion.</p><p>Routine Interactions</p><p>Understand the role the product plays in customers&#39; daily routines and how it fits into their broader lives.</p><p>Next Tab</p><p>Observe emotional reactions to different aspects of the product, such as joy, frustration, or confusion.</p><p>Methods of Customer Observation</p><p>Direct Observation</p><p>Direct observation involves watching customers interact with products in real time, either in their natural environment or in a controlled setting.</p><p>Indirect Observation</p><p>Indirect observation captures customer interactions through recorded sessions or analytics, providing a broader data set for analysis.</p><p>Review the table below for examples of direct and indirect observation.</p><p>Direct Observation</p><p>Indirect Observation</p><p>In-Home Visits:&#160;Team members visit customers&#39; homes to see how they use the product in their daily lives.</p><p>Video Recording:&#160;Record customer interactions with the product for later review and analysis.</p><p>Shadowing:&#160;Follow customers throughout their day to observe how they interact with the product and other related tools.</p><p>Screen Recording:&#160;Capture customers&#39; on-screen actions to understand how they navigate and use the software.</p><p>Usability Testing:&#160;In a controlled environment, watch customers complete specific tasks with the product to identify usability issues.</p><p>Usage Analytics:&#160;Analyze data from the product&#39;s usage analytics to identify common behaviors and patterns.</p><p>Watch the video below to see some of these observation methods in action.</p><p>When designing a product, truly understanding your customer is essential. One of the best ways to do that is through different types of customer observation. Let’s see how a team at a hypothetical smart blender company used various observation methods to improve their product.</p><p>First, in-home visits. Designers observe how customers use the product in their own space. Here, the customer struggles to find the right setting on the blender. This kind of direct observation reveals real-life challenges.</p><p>Next, shadowing. By following customers through their daily routine, the team notices how the blender’s complicated setup doesn’t fit into busy mornings.</p><p>Usability testing gives designers specific feedback. In this case, the customer successfully follows the digital instructions on the app.</p><p>This helps the team identify problem areas with both the product and its companion app.</p><p>Video recording lets the team analyzebehavior over time, noticing patterns like repeated confusion with the same setting.</p><p>Screen recordings capture how customers navigate the app on their phone, helping the team simplify confusing sections.</p><p>By combining these methods, the team gained deep customer insights—leading to a simpler, more intuitive product that delights users.</p><p>Integrating Observation into the D4D Process</p><p>Press the plus (+) in each section below to learn how observation is integrated into the Design for Delight process.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Integrating Observation Into the D4D Process: Empathy Phase Ideation Phase Prototyping and Experimentation Phase</p><p>The hotspot points on the image are as follows:</p><p>Empathy Phase</p><p>Observation is integral to the Empathy phase of D4D, where the goal is to understand customers deeply.</p><p>Customer Journey Mapping:&#160;Use observations to map out the entire customer journey, identifying key touchpoints and pain points.</p><p>Empathy Mapping:&#160;Create empathy maps that capture customers&#39; thoughts, feelings, and actions based on observational data.</p><p>Ideation Phase</p><p>Insights from observations inform the ideation process, guiding the generation of relevant and impactful ideas.</p><p>Brainstorming Sessions:&#160;Use observational insights to fuel brainstorming, ensuring that ideas are grounded in real customer experiences.</p><p>Prioritizing Ideas:&#160;Prioritize ideas based on the severity and frequency of observed pain points.</p><p>Prototyping and Experimentation Phase</p><p>Observation continues to play a role during prototyping and experimentation, ensuring that iterations are informed by real user interactions.</p><p>Prototype Testing:&#160;Observe customers interacting with prototypes to gather feedback and identify areas for improvement.</p><p>Iterative Refinement:&#160;Continuously refine prototypes based on observational insight<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2ec54efbb0c1ac56424aa3af922f6e85','intuit-design-for-delight-m3-l3-lesson-2','77ece592a88bec397ade3692f0ec7025','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Identifying Customer Challenges</h3><p>Identifying Customer Challenges</p><p>Identifying Customer Challenges in D4D</p><p>The D4D method is centeredaround deeply understanding and addressing customer challenges to create products that not only meet but exceed user expectations.&#160;Identifying customer challenges is a critical step in this process, as it informs the development of solutions that are genuinely valuable to users.&#160;This section explores how Intuit approaches the identification of customer challenges within the D4D framework, emphasizing the importance of this practice and the methods used to uncover these challenges.</p><p>Watch the video below to better understand why identifying customer challenges is critical to the D4D process.</p><p>Hi and welcome to Lesson 2 for this module on Developing Deep Customer Empathy Part 1!</p><p>Let’s start the video with a common hypothetical: a business owner launching a new product. Why don’t we use an example of a coffee shop owner introducing a new line of seasonal drinks? However, soon after the launch, customers start complaining that the drinks are too expensive and that the flavors are too similar to last year’s offerings. What went wrong? Chances are, the product didn’t solve a real problem or meet a specific need. This is why it’s such a big priority to spend time identifying customer challenges before diving into product development (and well before launching a product). Understanding these challenges, which is part of developing empathy, allows companies to create solutions that customers truly value. We want customers to continue to buy the seasonal drinks. We want them to tell their friends. And we want that all-important 5-star review. So without a deep understanding of the customer’s pain points, even the most innovative products can fail to resonate with their intended audience.</p><p>Identifying customer challenges involves much more than just asking customers what they want. In many cases, customers themselves aren’t fully aware of their own needs. That’s where various observation and research methods come in. One of the most effective ways to uncover challenges is through direct observation. For example, if a company is developing a new app for time management, they might observe how people currently manage their time. They can watch how users interact with existing tools, like pen-and-paper notebooks or other existing apps. Another method is conducting in-depth interviews or focus groups with customers. In these, you can ask open-ended questions that encourage them to describe their struggles in detail. Surveys can also be helpful, especially when they target specific behaviors or frustrations.</p><p>Once a team has gathered this valuable information through observation and research, the next step is to analyze it and use it to guide product development. This information is the foundation for creating meaningful solutions. With this information, teams can prioritize solving the most critical pain points. Even more importantly, they can eliminate unnecessary elements that customers don’t care about.</p><p>Let’s look at a real-life example of how this works. Consider Airbnb, a marketplace for short-term house rentals. This company completely transformed the way people travel. In the early stages of Airbnb’s development, the founders faced challenges in getting hosts to list their properties on the platform. After conducting research and talking with potential hosts, they discovered that one of the biggest obstacles was that people were hesitant to post low-quality photos of their homes. This fear made them reluctant to join the platform. With this insight, Airbnb started offering free professional photography services to hosts, dramatically increasing the quality of the photos, and ultimately, the number of property listings.</p><p>Now, let’s break this example down into the phases of Design for Delight: empathy, brainstorming, and experimentation.</p><p>Empathy: Airbnb&#39;s team started by empathizing with their potential hosts. They immersed themselves in the hosts’ experience to understand their hesitations. Rather than just assuming they knew why people weren’t listing their homes, they asked questions and listened carefully. They discovered that the hosts’ reluctance stemmed from a fear that their properties wouldn’t look appealing in photos.</p><p>Brainstorming: With this deep understanding of the host&#39;s challenges, the team entered a brainstorming phase. They considered many possible ways to help hosts overcome their concerns about photography. The team might have considered solutions like photo-editing tutorials, partnerships with photography apps, or even redesigning the listing process to reduce the need for photos. However, they eventually landed on the idea of providing free professional photography services as a way to increase the quality of listings and attract more hosts.</p><p>Experimentation: Next came the experimentation phase, where Airbnb tested their solution. Rather than offering professional photography to all hosts at once, they likely started by offering it to a smaller group to see how it worked. This lean experimentation allowed them to gather feedback from hosts, and refine the process before rolling it out on a larger scale. The results spoke for themselves—high-quality photos made the listings more appealing, which led to more bookings and a significant increase in hosts joining the platform.</p><p>By identifying and addressing customer challenges through observation and research, companies can ensure their products or services align with real-world needs. This process of gathering insights, like Airbnb did in our example, combined with empathy, brainstorming, and experimentation, forms the core of effective product development and can be the difference between a product that fails and one that delights its users.</p><p>The Importance of Identifying Customer Challenges</p><p>Understanding customer challenges is fundamental to designing products that solve real problems and enhance user experiences.&#160;When companies fail to identify and address these challenges accurately, they risk developing products that miss the mark, leading to low adoption rates and customer dissatisfaction.</p><p>Expand the sections below to identify key reasons for identifying customer challenges.</p><p>Customer-Centric Solutions</p><p>By focusing on actual customer problems, Intui<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('341fa0236a6aed4cc37a8042921f8e6c','intuit-design-for-delight-m3-l4-lesson-3','77ece592a88bec397ade3692f0ec7025','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Customer Problem Statement</h3><p>Customer Problem Statement</p><p>Defining the Customer Problem Statement</p><p>A clear and precise customer problem statement is crucial for driving innovation and ensuring that solutions are customer-centric in the D4D methodology.&#160;A well-defined problem statement helps teams focus their efforts on addressing real customer needs, leading to products that deliver meaningful value and delight users.&#160;This section explores the concept of the customer problem statement within the D4D framework, highlighting its importance, components, and how it guides the design process.</p><p>The Importance of a Customer Problem Statement</p><p>A customer problem statement articulates the specific challenges or pain points that customers experience.&#160;It serves as a foundation for the design and development process, ensuring that all efforts are aligned with solving genuine problems.</p><p>Press through the tabs below to learn about the key benefits of a customer problem statement.</p><p>Focused Innovation</p><p>A clear problem statement narrows the focus to specific issues, enabling targeted and effective solutions.</p><p>Customer-Centric Design</p><p>By focusing on real customer needs, solutions are more likely to meet user expectations and drive satisfaction.</p><p>Alignment and Clarity</p><p>A well-defined problem statement aligns the entire team around a common goal, providing clarity and direction.</p><p>Efficient Resource Utilization</p><p>By targeting specific problems, resources are used more efficiently, avoiding the development of unnecessary features.</p><p>Next Tab</p><p>Components of a Customer Problem Statement</p><p>At the core of Design for Delight is the customer.&#160;Who are they?&#160;What challenges are they encountering in their business?&#160;How do they respond to these challenges?&#160;Observing customers in their real environment reveals unexpected insights and a deeper understanding of their pain points.</p><p>Identifying their problem&#39;s root and associated emotions serves as both the foundation and the driving force for our innovation.&#160;When teams focus on a clearly defined problem rather than fixating on a single solution, that’s when creativity thrives.</p><p>The first step is to create a Customer Problem Statement, which includes the following components:</p><p>I am:&#160;(customer persona)</p><p>I am trying to:&#160;(desired outcome)</p><p>But:&#160;(barrier)</p><p>Because:&#160;(root cause)</p><p>Which makes me feel:&#160;(emotions)</p><p>Let&#39;s review some things you need to understand when crafting the customer problem statement.&#160;Expand each section below.</p><p>Customer Persona</p><p>Customer Persona:&#160;A description of the specific customer segment experiencing the problem. This can be a general description, like a job title or a person experiencing a particular issue, or it can be highly specific and be broken down into granular levels. For this example, let&#39;s keep it broad and general.</p><p>Example:&#160;Freelance graphic designers.</p><p>Problem Description</p><p>Problem Description:&#160;A detailed explanation of the problem, including context and specific pain points.</p><p>Example:&#160;Freelance&#160;graphic designers often struggle with managing multiple client projects simultaneously, leading to missed deadlines and dissatisfied clients.</p><p>Impact of the Problem</p><p>Impact of the Problem:&#160;An outline of how the problem affects the customer, including emotional, functional, and financial impacts.</p><p>Example:&#160;This problem results in increased stress, loss of income, and potential damage to the designer&#39;s professional reputation.</p><p>Desired Outcome</p><p>Desired Outcome:&#160;A clear statement of what the customer seeks to achieve by solving the problem.</p><p>Example:&#160;Freelance&#160;graphic designers need an efficient way to organize and track their projects to meet deadlines and maintain client satisfaction.</p><p>Watch this video to learn more about the elements of a customer problem statement.</p><p>In any process of designing products for customer delight, it&#39;s essential to start with a clear customer problem statement. Let’s look at Alex and his backpack to break down the key elements.</p><p>To start, let&#39;s define the customer persona. Alex is a 16-year-old high school student. He’s active, always on the go, and carries heavy textbooks and supplies.</p><p>Now, the problem description: Alex’s backpack is too bulky and poorly organized. It causes physical discomfort, and important items are often hard to find.</p><p>This leads us to the impact of the problem. Carrying a poorly designed backpack affects Alex’s posture, causes physical strain, and wastes time when he can’t easily access what he needs.</p><p>Finally, the desired outcome: Alex needs a backpack that’s lightweight, comfortable, and organized with separate compartments for easy access to his school supplies. It should improve both his comfort and efficiency.</p><p>When we fully understand the customer persona, the problem, the impact, and the desired outcome, we can design products that truly solve real-world issues. In Alex’s case, a better backpack was the perfect solution.</p><p>Design for Delight begins with understanding the customer’s problems.</p><p>Crafting an Effective Customer Problem Statement</p><p>Crafting an effective customer problem statement involves thorough research and a deep understanding of the customer&#39;s experiences.&#160;Here are the steps Intuit follows to create impactful problem statements within the D4D framework.</p><p>Press the plus (+) in each section below to learn about that part of the process.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Steps to defining a customer problem statement: Customer Research Empathy Mapping Synthesize Findings Draft the Problem Statement Validate with Customers</p><p>The hotspot points on the image are as follows:</p><p>Draft the Problem Statement</p><p>Clearly define the customer persona and articulate the problem, its impact, and the desired outcome.</p><p>Ensure the statement is specific, concise, and free of assumptions or solutions.</p><p>Validate with Customers</p><p>Share the problem statement with customers to ensure it accurately reflects their experiences.</p><p>Refine the statement based on feedback to enhance accurac<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('951b1202c62ab543c48ac148bee3d40a','intuit-design-for-delight-m3-l5-lesson-4','77ece592a88bec397ade3692f0ec7025','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Ideal Customer State</h3><p>Ideal Customer State</p><p>The Ideal Customer State in the D4D Methodology</p><p>At its core, D4D focuses on understanding and empathizing with customers, ensuring that solutions not only meet their needs but also exceed their expectations.&#160;Central to this approach is the concept of the &quot;Ideal Customer State.&quot; This section explores what the Ideal Customer State means within the D4D framework, how it is achieved, and why it is crucial for delivering exceptional customer experiences.</p><p>Defining the Ideal Customer State</p><p>The Ideal Customer State represents the ultimate goal for any product or service designed using the D4D methodology.&#160;It is a state where customers are not just satisfied but genuinely delighted with their interactions and experiences.&#160;This state is characterized by several key elements.&#160;Press each tab below to learn about these elements.</p><p>Fulfillment of Needs</p><p>The product or service effectively addresses and fulfills the primary needs and pain points of the customer.&#160;It solves problems efficiently and enhances the customer&#39;s life in a meaningful way.</p><p>Ease of Use</p><p>The customer finds the product or service intuitive and easy to use. There is minimal friction in the user experience, and customers can achieve their goals with minimal effort.</p><p>Emotional Connection</p><p>Customers feel a strong emotional connection to the product or service. This connection is built through positive interactions, reliability, and a sense of trust.</p><p>Exceeding Expectations</p><p>The product or service not only meets but also exceeds customer expectations. It delivers unexpected value or features that enhance the overall experience.</p><p>Customer Empowerment</p><p>Customers feel empowered when using the product or service. They have the tools and resources to make informed decisions and control their interactions.</p><p>Loyalty and Advocacy</p><p>In the Ideal Customer State, customers become loyal advocates for the brand. They are likely to recommend the product or service to others and remain engaged over the long term.</p><p>Next Tab</p><p>Achieving the Ideal Customer State</p><p>Achieving the Ideal Customer State involves a comprehensive approach that integrates customer insights, iterative design, and continuous feedback.&#160;Learn about how Intuit’s D4D methodology facilitates this process by pressing the plus (+) in each section below.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Achieving the Ideal Customer State Empathize Define Ideate Prototype Test</p><p>The hotspot points on the image are as follows:</p><p>Empathize</p><p>Understanding Customer Needs and Pain Points:</p><p>In-depth Research:&#160;Conduct qualitative and quantitative research to understand the needs, desires, and pain points of the target audience.</p><p>Customer Interviews and Surveys:&#160;Engage directly with customers through interviews and surveys to gather detailed insights into their experiences and challenges.</p><p>Examples:</p><p>Conducting user interviews to understand how small business owners manage their finances.</p><p>Using surveys to gather feedback on current financial software and identify areas for improvement.</p><p>Ideate</p><p>Generating Creative Solutions:</p><p>Brainstorming Sessions:&#160;Conduct brainstorming sessions to generate a wide range of ideas and potential solutions.</p><p>Collaborative Workshops:&#160;Involve cross-functional teams, including designers, engineers, and marketers, to contribute diverse perspectives.</p><p>Examples:</p><p>Hosting a workshop to brainstorm features that could simplify expense tracking, such as automated receipt scanning and categorization.</p><p>Define</p><p>Crafting a Clear Problem Statement:</p><p>Synthesizing Insights:&#160;Analyze the data collected during the empathy phase to identify common themes and critical issues.</p><p>Defining the Problem:&#160;Clearly articulate the problem statement that the product or service aims to solve, ensuring it aligns with customer needs.</p><p>Examples:</p><p>Identifying that small business owners struggle with tracking expenses and creating a clear problem statement: &quot;How might we simplify expense tracking for small business owners?&quot;</p><p>Prototype</p><p>Creating Tangible Representations:</p><p>Rapid Prototyping:&#160;Develop low-fidelity prototypes that can be quickly tested and iterated upon.</p><p>User Testing:&#160;Engage customers in testing prototypes to gather feedback and identify areas for refinement.</p><p>Examples:</p><p>Creating a clickable mockup of an expense tracking app and conducting usability tests with small business owners.</p><p>Test</p><p>Validating Solutions with Real Users:</p><p>Feedback Loops:&#160;Continuously seek feedback from customers to validate assumptions and improve the product.</p><p>Iterative Improvements:&#160;Make iterative improvements based on user feedback to ensure the product evolves to meet customer needs.</p><p>Examples:</p><p>Launching a beta version of the expense tracking app and collecting feedback to refine features and user interface.</p><p>Importance of the Ideal Customer State</p><p>Achieving the Ideal Customer State is crucial for several reasons.&#160;Expand each section below to learn more.</p><p>Customer Satisfaction and Loyalty</p><p>When customers are delighted, they are more likely to remain loyal to the brand and continue using the product or service. This leads to long-term customer retention and increased lifetime value.</p><p>Positive Word-of-Mouth</p><p>Delighted customers become brand advocates, sharing their positive experiences with others. This organic word-of-mouth marketing can significantly boost brand reputation and attract new customers.</p><p>Competitive Advantage</p><p>Products and services that achieve the Ideal Customer State stand out in the market. They differentiate themselves by providing exceptional value and experiences that competitors may not offer.</p><p>Sustainable Growth</p><p>By consistently meeting and exceeding customer expectations, companies can drive sustainable growth. Satisfied customers are more likely to make repeat purchases and explore other offerings from the brand.</p><p>Watch the video below for a recap of the ideal customer state.</p><p>Hi and welcome to Lesson 4 for this module on Developing Dee<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1052cf5c49baf5c9bb2ff10c9c520054','intuit-design-for-delight-m3-l6-module-2-summary','77ece592a88bec397ade3692f0ec7025','Module 2 Summary','text',12,'<h2>Module 2 Summary</h2><section><h3>Module 2 Summary</h3><p>Module 2 Summary</p><p>Great Work!&#160;You have successfully completed this module on&#160;Developing Deep Customer Empathy Part I.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Learned about customers through observation.</p><p>Identified the customer challenge.</p><p>Summarized what you learned</p><p>Defined the customer problem statement.</p><p>Identified the components of a customer problem statement.</p><p>Given a situation, created or completed a customer problem statement</p><p>Conceptualized the ideal customer state.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('87ead5001542d490cd6851bc177ae422','intuit-design-for-delight-m3-l7-module-2-test-prep','77ece592a88bec397ade3692f0ec7025','Module 2 Test Prep','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Customer Empathy Part 1. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,6,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f5596b013c41e8d2879adceda8abb86f','intuit-design-for-delight-m3-l8-module-2-assignment','77ece592a88bec397ade3692f0ec7025','Module 2 Assignment','text',12,'<h2>Module 2 Assignment</h2><section><h3>Module 2 Assignment</h3><p>Module 2 Assignment</p><p>Intuit Design for Delight</p><p>Assignment</p><p>Short answer assignment</p><p>Write a two-page, double-spaced paper summarizing your understanding of identifying customer challenges and applying this knowledge using the D4D framework. Your paper should address the following:</p><p>Explain what &quot;identifying customer challenges&quot; entails.</p><p>Discuss why identifying customer challenges is crucial for product development and customer satisfaction.</p><p>Explain how understanding customer challenges fits into each phase of the D4D framework.</p><p>Use what you have learned in the module to react to this scenario: Your company is designing a new smart home device like a thermostat, video doorbell, or some other smart home product (you can define the product further if you would like, but you don&#39;t have to go into great detail for this exercise).</p><p>Describe how you would use the methods you learned about in the module to address the specific challenges customers face with this smart home device.</p><p>Review the rubric to determine how you will be graded.</p><p>Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a2f94e577b46d27ecd52f5e1b9e7c0fa','intuit-design-for-delight-m3-l9-module-2-project','77ece592a88bec397ade3692f0ec7025','Module 2 Project','text',12,'<h2>Module 2 Project</h2><section><h3>Module 2 Project</h3><p>Module 2 Project</p><p>Intuit Design for Delight</p><p>Developing Deep Customer Empathy Part I - Project</p><p>Project</p><p>In this project, you will create an infographic that clearly articulates a customer problem statement by breaking it down into its fundamental components: customer persona, problem description, impact of the problem, and desired outcome. Your infographic will cover each component, providing clarity and insight into the customer experience and setting the stage for effective problem-solving and innovation using the Intuit Design for Delight (D4D) framework.</p><p>1. Begin by reading the scenario below:</p><p>Imagine that a company has recently launched a new smart home device designed to enhance home security. This device includes features such as real-time surveillance, motion detection, and remote access via a mobile app. Despite its advanced features, customers are experiencing significant challenges during the installation and initial setup process. As a result, many customers are frustrated and unable to fully utilize the device’s capabilities.</p><p>Using this scenario, you will identify and define the components of a customer problem statement: customer persona, problem description, impact of the problem, and desired outcome.</p><p>2. Review the components of a customer problem statement by expanding each section below.</p><p>Customer Persona</p><p>Begin by defining a detailed customer persona. This persona should represent the typical user experiencing the problem. You might include demographic information, background, needs, goals, and behaviors. This will help create a vivid picture of who the customer is and ensure the problem statement is grounded in a real-world context. For example, you might create a customer persona that contains:</p><p>Name (e.g., Kim Customer; Jack Baker)</p><p>Age (e.g., 35; mid-thirties)</p><p>Occupation (e.g., teacher; software developer)</p><p>Location (e.g., Boston, MA; suburban area; large city)</p><p>Family (e.g., married with one child; single living alone)</p><p>Tech Savviness (e.g., comfortable, but not an expert)</p><p>Needs and Goals (e.g., wants to enhance home security, especially when travelling)</p><p>Problem Description</p><p>Clearly describe the specific problem the customer is facing. This should be a concise statement that outlines the issue without proposing a solution. Focus on the symptoms of the problem and how they manifest in the customer&#39;s experience. Ensure that this description is specific and detailed enough to be easily understood.</p><p>Impact of the Problem</p><p>Explain the impact that this problem has on the customer. Consider both the practical and emotional effects. How does this problem hinder the customer&#39;s ability to achieve their goals or meet their needs? What frustrations or challenges does it create? This component should convey the urgency and significance of solving the problem.</p><p>Desired Outcome</p><p>Describe the desired outcome from the customer&#39;s perspective. What would a successful resolution look like? How would it improve the customer&#39;s experience and address the issues outlined in the problem description? This should provide a clear vision of what needs to be achieved to delight the customer.</p><p>On your infographic:</p><p>The&#160;Customer Persona&#160;section should include detailed characteristics and an image or illustration to represent the persona.</p><p>The&#160;Problem Description&#160;section should use concise language to describe the problem clearly and can include relevant imagery.</p><p>The&#160;Impact of the Problem&#160;section should illustrate the significance of the issue with examples or quotes from the customer&#39;s perspective.</p><p>Finally, the&#160;Desired Outcome&#160;section should provide a compelling vision of the ideal solution and its benefits to the customer.</p><p>You can use free infographic websites (search &quot;free infographic maker&quot;) or use other software like Word or PowerPoint to complete your infographic.</p><p>Review the rubric below to determine how you will be graded.</p><p>Developing Deep Customer Empathy Part I Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Content</p><p>8 points The content shows a strong understanding of the customer problem statement. It explains each component extremely well and is relevant to the example presented.</p><p>7-4 points The content shows a fair understanding of the customer problem statement. It explains each component relatively well and is relevant to the example presented.</p><p>3-0 points The content shows little to no understanding of the customer problem statement. It does not explain the components well.</p><p>8</p><p>Infographic</p><p>8 points The infographic is well-organized, engaging, and visually appealing.</p><p>7-6 points The infographic is organized and fairly engaging.</p><p>5-0 points The infographic is not well-organized, engaging, or visually appealing.</p><p>8</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Formatting</p><p>2 points Project is formatted according to stated instructions.</p><p>0 points Project is not formatted according to stated instructions.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6db6551ca51bdd17a2d76260e5f9e1d0','intuit-design-for-delight-m3-l10-module-2-quiz','77ece592a88bec397ade3692f0ec7025','Module 2 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Customer Empathy Part 1. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('548aec12cba794386b65db6117196686','intuit-design-for-delight-module-4','92a4f5cdddc7f69042b22cbdf20f300f','Module 4: Customer Empathy Part 2',4) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('178f6efdcaf7a269d1d12e6cc30aafac','intuit-design-for-delight-m4-l1-introduction-purpose-and-objectives','548aec12cba794386b65db6117196686','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi and welcome to this module on Developing Deep Customer Empathy Part 2!</p><p>Have you ever wondered how some of your favorite products just seem to get you? For example, a streaming service that recommends shows based on your viewing habits makes it easy to find your next favorite series without endless scrolling. Or think about a fitness app that adjusts workout plans based on your progress and goals, helping you stay motivated and on track.</p><p>That’s no accident—it’s the result of careful customer observation and design thinking. In this module, we will continue our look into developing customer empathy by learning how to identify and describe various customer observation methods. We’ll explore best practices for observing customers in ways that uncover their actual needs, and you’ll learn how to identify key insights from these observations, like pain points and unexpected surprises.</p><p>But observing customers is only the beginning. You’ll also learn how to take those observations and apply them to creating an &quot;ideal state&quot; for the customer. This means understanding not only what customers want but also envisioning the best possible experience for them. By the end of this module, you’ll be able to create clear statements of the ideal customer state that reflect their desires and guide innovative product design.</p><p>Module Description</p><p>In this module, you will explore various customer observation methods and best practices, learning how to effectively gather valuable insights from your observations.&#160;You will identify key takeaways and significant results, paying particular attention to surprises and pain points experienced by customers.&#160;You will delve into the components of a customer problem statement, and you will practice creating or completing one based on given scenarios.&#160;Additionally, you will identify the elements that make up an ideal state statement, helping you envision the optimal experience for your customers.</p><p>Objectives</p><p>In this module, students will</p><p>Identify and describe customer observation methods and customer observation best practices.</p><p>Identify the important takeaways and most important results from customer observation.</p><p>Identify surprises and pain points.</p><p>Identify the components of an ideal state statement.</p><p>Given a situation, create or complete an ideal state statement</p><p>Polling Question</p><p>With which type of direct observation method are you most familiar?</p><p>shadowing&#160;contextual inquiry&#160;fly-on-the-wall observation&#160;ethnographic research</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Definition</p><p>a qualitative observation method to understand users in their environments</p><p>shadowing</p><p>an observational technique that allows a researcher to collect data by seeing and listening without being noticed (or obtrusive)</p><p>ethnographic research</p><p>a qualitative research method that involves observing people in their natural environment to understand their experiences, perspectives, and everyday practices</p><p>market share</p><p>the likelihood of a study being successful and the ability to overcome potential obstacles</p><p>fly-on-the-wall observation</p><p>the proportion of total sales in an industry controlled by a particular business</p><p>feasibility</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>a qualitative observation method to understand users in their environments</p><p>Answers for question: 1</p><p>ethnographic research</p><p>market share</p><p>shadowing</p><p>feasibility</p><p>fly-on-the-wall observation</p><p>2.</p><p>an observational technique that allows a researcher to collect data by seeing and listening without being noticed (or obtrusive)</p><p>Answers for question: 2</p><p>fly-on-the-wall observation</p><p>feasibility</p><p>ethnographic research</p><p>market share</p><p>shadowing</p><p>3.</p><p>a qualitative research method that involves observing people in their natural environment to understand their experiences, perspectives, and everyday practices</p><p>Answers for question: 3</p><p>feasibility</p><p>market share</p><p>ethnographic research</p><p>fly-on-the-wall observation</p><p>shadowing</p><p>4.</p><p>the likelihood of a study being successful and the ability to overcome potential obstacles</p><p>Answers for question: 4</p><p>fly-on-the-wall observation</p><p>ethnographic research</p><p>shadowing</p><p>feasibility</p><p>market share</p><p>5.</p><p>the proportion of total sales in an industry controlled by a particular business</p><p>Answers for question: 5</p><p>fly-on-the-wall observation</p><p>shadowing</p><p>market share</p><p>feasibility</p><p>ethnographic research</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6c0eb3298425dd3b4e7deedeff9c124c','intuit-design-for-delight-m4-l2-lesson-1','548aec12cba794386b65db6117196686','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Customer Observation</h3><p>Customer Observation</p><p>Customer Observation Methods and Best Practices</p><p>Intuit&#39;s Design for Delight (D4D) methodology is a customer-centric approach to innovation that emphasizes understanding and empathizing with customers to create products and services that exceed their expectations.&#160;Central to this approach is the practice of customer observation, which involves closely studying customers in their natural environments to gain deep insights into their behaviors, needs, and pain points.&#160;This section explores various customer observation methods and best practices specifically tailored to the D4D methodology, highlighting how these techniques contribute to creating delightful customer experiences.</p><p>Review various customer observation methods below.&#160;You&#39;ll also see some examples of these methodologies as they apply to Intuit products.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Shadowing</p><p>ShadowingShadowing involves closely following a customer as they go about their daily activities, especially those related to the product or service in question.&#160;This method provides firsthand insights into how customers interact with products and services in real-world contexts.</p><p>⟳ Flip Card</p><p>Flashcard&#160;1&#160;of&#160;1</p><p>Flashcard Transcript</p><p>Application in D4D</p><p>Observing small business owners managing their finances to understand their pain points with existing financial software.</p><p>Following users through their tax preparation process to identify areas where they struggle and need assistance.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Contextual Inquiry</p><p>Contextual InquiryContextual inquiry is a semi-structured interview method conducted in the user’s environment.&#160;It combines observation with questioning to gain insights into specific tasks and workflows.</p><p>⟳ Flip Card</p><p>Flashcard&#160;1&#160;of&#160;1</p><p>Flashcard Transcript</p><p>Application in D4D</p><p>Conducting interviews with users in their homes or offices while they use Intuit products like QuickBooks or TurboTax.</p><p>Asking customers to describe their thought processes and actions as they navigate through the software.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Fly-on-the-Wall Observation</p><p>Fly-on-the-Wall ObservationFly-on-the-wall observation involves unobtrusively observing customers without interacting with them.&#160;This method is useful for understanding natural behaviors and identifying unarticulated needs.</p><p>⟳ Flip Card</p><p>Flashcard&#160;1&#160;of&#160;1</p><p>Flashcard Transcript</p><p>Application in D4D</p><p>Watching users in a public space, such as a co-working area, to see how they manage their business tasks without interfering with their workflow.</p><p>Observing how customers interact with physical product displays in retail settings to gather insights on product packaging and placement.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Diary Studies</p><p>Diary StudiesDiary studies ask customers to record their activities, thoughts, and feelings related to a product or service over a period of time.&#160;This method provides longitudinal insights into user behavior and experiences.</p><p>⟳ Flip Card</p><p>Flashcard&#160;1&#160;of&#160;1</p><p>Flashcard Transcript</p><p>Application in D4D</p><p>Requesting small business owners to keep a diary of their daily financial management activities and any challenges they encounter.</p><p>Having users document their experiences with a new feature in QuickBooks over several weeks.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Ethnographic Research</p><p>Ethnographic ResearchEthnographic research involves immersing oneself in the customer&#39;s environment for an extended period to deeply understand their culture, behaviors, and needs.</p><p>⟳ Flip Card</p><p>Flashcard&#160;1&#160;of&#160;1</p><p>Flashcard Transcript</p><p>Application in D4D</p><p>Spending weeks within a small business to understand the intricacies of their financial management and operational workflows.</p><p>Engaging with customers in their community settings to see how Intuit products fit into their broader lives and routines.</p><p>Customer Observation Best Practices</p><p>Press the plus in each box below to learn about customer observation best practices.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Customer Observation Best Practices: Embrace Empathy Be Unobtrusive Capture Detailed Notes Look for Patterns and Themes Combine Multiple Methods Iterate Based on Feedback</p><p>The hotspot points on the image are as follows:</p><p>Capture Detailed Notes</p><p>Description:&#160;Detailed, accurate notes are crucial for analyzing observations and drawing meaningful conclusions.</p><p>Best Practices:</p><p>Document specific actions, quotes, and contextual details that illustrate the customer’s experience.</p><p>Use a structured format for note-taking, such as the AEIOU framework (Activities, Environments, Interactions, Objects, Users), to ensure comprehensive coverage.</p><p>Be Unobtrusive</p><p>Description:&#160;Maintaining a low profile during observations ensures that customers behave naturally, providing more authentic insights.</p><p>Best Practices:</p><p>Avoid interfering with the customer&#39;s tasks or asking too many questions during the observation phase.</p><p>Use unobtrusive recording tools, such as discreet note-taking or video recording (with consent), to capture insights without drawing attention.</p><p>Embrace Empathy</p><p>Description:&#160;Empathy is at the heart of the D4D methodology. Observers should strive to see the world through the customer&#39;s eyes, understanding their emotions, motivations, and frustrations.</p><p>Best Practices:</p><p>Approach observations with an open mind, suspending any preconceived notions about customer behaviors.</p><p>Actively listen to <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('bd75c337a4800b7ec9d728f7c7365de2','intuit-design-for-delight-m4-l3-lesson-2','548aec12cba794386b65db6117196686','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Customer Insights</h3><p>Customer Insights</p><p>Unlocking Customer Insights with Intuit’s Design for Delight Methodologies</p><p>Understanding customers and their needs is crucial for any business aiming to create products or services that resonate with its target market.&#160;Intuit’s Design for Delight (D4D) methodology offers a robust framework for achieving this by emphasizing deep customer empathy, idea generation, and rapid experimentation.&#160;Here&#39;s a deep dive into the key takeaways and results businesses can glean from customer observation through D4D methodologies, supported by business examples.</p><p>Let&#39;s first break down the three core elements and the takeaways from each.&#160;Press the plus (+) in each section below.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Key Takeaways from D4D Methodologies Deep Customer Empathy Go Broad to Go Narrow Rapid Experimentation</p><p>The hotspot points on the image are as follows:</p><p>Go Broad to Go Narrow</p><p>Generating Diverse Ideas: Encourage brainstorming and idea generation from diverse perspectives. This process ensures a wide range of solutions are considered before narrowing down to the most promising ones.</p><p>Prioritizing Ideas: Once a broad spectrum of ideas is generated, use criteria such as feasibility, impact, and alignment with customer needs to prioritize and select the best ideas for further development.</p><p>Deep Customer Empathy</p><p>Understanding the Customer Journey: Empathy involves immersing oneself in the customer’s world. This can be achieved through direct interaction, observation, and engagement with customers in their environments.</p><p>Identifying Pain Points and Unmet Needs: By focusing on the customer’s experiences, businesses can uncover latent pain points and needs that customers themselves might not articulate directly.</p><p>Rapid Experimentation</p><p>Prototyping and Testing: Create quick, low-fidelity prototypes to test assumptions and gather feedback. This iterative process allows for refining ideas based on real customer interactions.</p><p>Failing Fast and Learning: Embrace failure as a learning opportunity. Rapid experimentation helps identify what doesn’t work quickly, saving time and resources in the long run.</p><p>The Benefits of Customer Observation</p><p>Customer observation, as a core aspect of Intuit&#39;s Design for Delight methodologies, allows businesses to gain deep insights into customer behaviors and unmet needs.&#160;By directly engaging with customers and understanding their pain points, companies can develop tailored solutions that significantly enhance the user experience, leading to delighted customers.&#160;This not only fosters customer loyalty and satisfaction but also drives innovation and efficiency within the business.&#160;The benefits are multifaceted, including increased market share, improved product development, and streamlined operations, ultimately creating a win-win scenario for both companies and their customers.</p><p>Expand the sections below to look at benefits in real-world scenarios using customer observation via the D4D framework.</p><p>Enhanced Customer Satisfaction and Loyalty</p><p>Example:&#160;A retail company observed that customers were often frustrated with long checkout lines. By implementing self-checkout kiosks and mobile payment options, they reduced wait times and improved overall customer satisfaction. This led to increased customer loyalty and repeat business.</p><p>Innovative Product Development</p><p>Example:&#160;A tech startup utilized customer observation to notice that users struggled with setting up their smart home devices. By redesigning the setup process to be more intuitive and user-friendly, the company not only improved the user experience but also differentiated itself in a competitive market.</p><p>Increased Market Share</p><p>Example:&#160;A beverage company noticed through customer observation that many consumers were seeking healthier drink options. By introducing a new line of low-sugar, natural-ingredient beverages, they tapped into a growing market trend and significantly increased their market share.</p><p>Cost Savings and Efficiency</p><p>Example:&#160;A manufacturing firm observed that workers frequently faced bottlenecks due to outdated machinery. By upgrading equipment based on these observations, they improved production efficiency and reduced operational costs.</p><p>Enhanced Employee Engagement</p><p>Example:&#160;A software company involved its employees in customer observation sessions. This not only provided employees with a deeper understanding of customer pain points but also empowered them to contribute ideas for improvements, boosting overall engagement and morale.</p><p>D4D Application in Various Types of Businesses</p><p>Let&#39;s look at some simple examples of how observation and action might be applied in different settings.&#160;Press through the tabs below to explore.</p><p>Healthcare</p><p>Observation:&#160;A hospital noticed through patient feedback that wait times for appointments were excessively long.</p><p>Action:&#160;Implementing an online scheduling system and streamlining patient flow processes.</p><p>Result:&#160;Reduced wait times, improved patient satisfaction, and better resource allocation.</p><p>Hospitality</p><p>Observation: A hotel chain observed that guests frequently requested late check-outs.</p><p>Action: Offering flexible check-out times and a loyalty program for frequent guests.</p><p>Result: Increased guest satisfaction and repeat bookings.</p><p>Education</p><p>Observation: A university found that students were struggling with accessing online resources.</p><p>Action: Developing a more user-friendly online portal and mobile app for easy access to materials.</p><p>Result: Enhanced student engagement and improved academic performance.</p><p>Retail</p><p>Observation: A clothing retailer observed that shoppers often abandoned their carts due to confusion over sizing.</p><p>Action: Introducing a virtual fitting room and clear size guides.</p><p>Result: Decreased cart abandonment rates and increased sales.</p><p>Next Tab</p><p>Watch this video for more examples of how observations can lead to actions that help customers in all sorts of situations.</p><p>Meet Sam, a student trying to register for next semester’s classes. But like many students, Sam is struggling w<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('d093a3c0708a7a0fbf73b798193f52df','intuit-design-for-delight-m4-l4-lesson-3','548aec12cba794386b65db6117196686','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Identifying Customer Pain Points</h3><p>Identifying Customer Pain Points</p><p>Identifying Surprises and Pain Points Using D4D</p><p>Central to the D4D framework is understanding and addressing customer needs by identifying surprises and pain points through deep customer observation.&#160;Recognizing these elements is critical, as they often reveal the most significant opportunities for innovation and improvement.&#160;This section delves into how businesses can use D4D methodologies to uncover these insights and why it is essential, supported by illustrative scenarios for practical application.</p><p>Enhancing Customer Experience</p><p>Understanding what delights or frustrates customers allows businesses to tailor their offerings to meet and exceed expectations, leading to higher satisfaction and loyalty.</p><p>Driving Innovation</p><p>Surprises and pain points often signal areas ripe for innovation. By addressing these, companies can develop unique solutions that differentiate them in the market.</p><p>Optimizing Resources</p><p>Focusing on the most impactful customer needs ensures that resources are allocated efficiently, maximizing returns on investment.</p><p>Improving Business Processes</p><p>Identifying operational pain points through customer feedback can lead to more streamlined and effective business processes.</p><p>Next Tab</p><p>Surprises and Pain Points Using the D4D Framework</p><p>Again, let&#39;s examine this topic through the methodologies that represent the core of Design for Delight:&#160;deep customer empathy, go broad to go narrow, and rapid experimentation.&#160;Press the plus (+) in each section below to learn more.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Identifying Surprises and Pain Points (Core Principles) Deep Customer Empathy Go Broad to Go Narrow Rapid Experimentation</p><p>The hotspot points on the image are as follows:</p><p>Deep Customer Empathy</p><p>Immersive Observation: Spend time with customers in their environments to gain a firsthand understanding of their experiences. This can involve shadowing customers as they use a product or service, taking note of any difficulties or moments of delight. Such immersive observation helps uncover nuances that may not be apparent through surveys or second-hand reports.</p><p>Empathy Interviews: Conduct open-ended interviews to delve deeply into the customer’s perspective. These interviews should encourage customers to share their stories, emotions, and thoughts related to their experiences. By listening attentively, businesses can gain insights into the underlying reasons for customer behaviors and preferences.</p><p>Go Broad to Go Narrow</p><p>Diverse Idea Generation: Encourage brainstorming sessions with participants from various backgrounds and disciplines to gather a wide range of insights and ideas. This diversity of thought can lead to more creative and innovative solutions. The goal is to generate a broad spectrum of ideas without immediately judging their feasibility.</p><p>Prioritization: Once a broad range of ideas has been generated, evaluate them based on criteria such as feasibility, impact, and alignment with identified customer needs. This process helps narrow down the ideas to the most promising solutions that are both practical and capable of significantly enhancing the customer experience.</p><p>Rapid Experimentation</p><p>Prototyping: Develop quick, low-fidelity prototypes to test assumptions and gather immediate feedback from customers. Prototypes should be simple and inexpensive to create, allowing for rapid iteration. This approach helps validate ideas early and avoid costly mistakes later in the development process.</p><p>Iterative Testing: Use customer feedback to refine prototypes through multiple iterations. Embrace failure as a learning opportunity, understanding that each iteration brings the product closer to meeting customer needs effectively. This iterative process ensures that the final product is well-aligned with customer expectations and preferences.</p><p>Watch this video to see what it looks like when a customer experiences surprises or pain points.</p><p>Customer pain points can appear at any step of the journey. Let’s explore how small surprises or frustrations can impact a customer’s experience—and what can be done to fix them.</p><p>First, meet Laura. She’s trying to order dinner using a restaurant app, but the confusing customization options are causing her trouble.</p><p>When app interfaces aren’t intuitive, customers like Laura are left frustrated, and they may even receive incorrect orders.</p><p>Next, there’s Emma. She ordered a bookshelf online, but the assembly instructions are poorly written and hard to follow.</p><p>Missing parts and confusing instructions can turn a simple task into a frustrating and time-consuming experience.</p><p>Now, meet Jason. He signed up for a mobile plan that promised low fees, but his bill shows unexpected hidden charges.</p><p>When pricing isn’t clear, customers like Jason feel deceived, leading to a loss of trust in the company.</p><p>By identifying these pain points, businesses can take action—whether it’s improving app design, simplifying product instructions, or being transparent about pricing.</p><p>By addressing these surprises, businesses can turn frustration into delight, creating smoother journeys and more satisfied customers.</p><p>Examples and Scenarios</p><p>To illustrate these principles, let&#39;s look at a few examples.&#160;This is a way to begin thinking like a customer and examining experiences through that lens.&#160;Read each scenario and question below.&#160;Then reveal the answer to the question.&#160;Take a moment to reflect on the question before revealing the answer.&#160;This is not a graded assignment.</p><p>Retail Experience</p><p>Scenario:&#160;A customer frequently shops at a local grocery store but often abandons their cart due to long checkout lines.</p><p>Question:&#160;What was a surprise to the customer in this scenario?</p><p>The surprise was discovering that the store had long checkout lines every time they visited, which they did not anticipate initially.</p><p>Tech Product Setup</p><p>Scenario:&#160;A user purchases a new smart thermostat but finds the installation process confusing and time-consuming.</p><p>Question:&#160;What pain point did the customer experience in this scenario?</p><p>Th<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('59aa597f9ed4367aee666338b206530a','intuit-design-for-delight-m4-l5-lesson-4','548aec12cba794386b65db6117196686','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Achieving the Ideal Customer State</h3><p>Achieving the Ideal Customer State</p><p>Creating products and services that truly delight customers is the ultimate goal for many businesses.&#160;Recall that the concept of the &quot;ideal customer state&quot; is central to this mission, encapsulating the perfect alignment of customer expectations and experiences.&#160;Intuit&#39;s Design for Delight (D4D) methodologies provide a robust framework for achieving this state by focusing on deep customer empathy, broad idea generation, and rapid experimentation.&#160;This section explores the components of an ideal customer state, how it can be achieved, and why it is critical for businesses aiming to create delightful experiences.</p><p>The Components of an Ideal Customer State</p><p>There are five components to the Ideal Customer State in the D4D framework:&#160;effortless experience, emotional satisfaction, consistent reliability, personal relevance, and empowerment.&#160;Press each flashcard below to flip it over and learn about that component.&#160;Then press NEXT to move on to the next component.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>&#171; Back</p><p>Effortless Experience</p><p>Effortless ExperienceCustomers can use the product or service with minimal effort and friction.&#160;Processes are intuitive, straightforward, and streamlined.</p><p>Emotional Satisfaction</p><p>Emotional SatisfactionCustomers feel positive emotions such as joy, satisfaction, and trust.&#160;The product or service exceeds their expectations and makes them feel valued.</p><p>Consistent Reliability</p><p>Consistent ReliabilityThe product or service consistently performs as expected.&#160;Customers experience minimal issues and can rely on the product or service to meet their needs.</p><p>Personal Relevance</p><p>Personal RelevanceThe product or service feels personalized and relevant to the customer’s individual needs and preferences.&#160;Customers feel that the solution is designed specifically for them.</p><p>Empowerment</p><p>EmpowermentCustomers feel empowered to achieve their goals using the product or service.&#160;They have access to the necessary resources and support to use the product effectively.</p><p>⟳ Flip Card</p><p>Next &#187;</p><p>Flashcard&#160;1&#160;of&#160;5</p><p>Flashcard Transcript</p><p>Watch the video below to review the ideal customer state and to see what its components might look like in specific scenarios.</p><p>Hi and welcome to Video 4 for this module on Developing Deep Customer Empathy Part 2!</p><p>The ideal customer state is the ultimate goal for businesses when designing products or services. It represents the point at which customers feel fully fulfilled—not just satisfied—with their experience. In this state, customers feel connected to the product or service on multiple levels, leading to loyalty and advocacy for the brand. To reach this ideal, businesses must focus on five key components: effortless experience, emotional satisfaction, consistent reliability, personal relevance, and empowerment. Let’s explore each of these elements using the example of a fitness app designed to help users track workouts, create exercise routines, and monitor fitness goals.</p><p>One of the most important aspects of the ideal customer state is providing an effortless experience. The product or service should be intuitive, requiring minimal effort for the customer to achieve their goals. For our fitness app, this would involve a simple, clean interface that allows users to log workouts, create routines, and check progress easily. For instance, the app should open to a dashboard where all the necessary features are accessible with just a few taps. This seamless navigation makes the app a natural part of the user’s routine, allowing them to focus on their fitness rather than struggling with navigating around the app.</p><p>Emotional satisfaction goes beyond functionality; it&#39;s about how the product makes the customer feel. With a fitness app, emotional satisfaction might come from users reaching personal milestones, such as completing a week of workouts or achieving a personal best. The app could celebrate these achievements with motivational messages like, “Great job! You’re on a 5-day workout streak!” By recognizing user success, the app fosters a positive emotional connection. This motivates the user to continue and deepens their attachment to the product.</p><p>No matter how innovative or user-friendly a product is, consistent reliability is essential. If the product doesn&#39;t work properly, or if it constantly crashes, customers will become frustrated. For a fitness app, reliability means accurate workout tracking, seamless syncing with wearable devices, and ensuring all data is saved correctly. When users can trust the app to consistently perform well, it builds confidence. This reliability reinforces the customer’s satisfaction and keeps them engaged, knowing they won’t face any annoying technical issues.</p><p>Personal relevance ensures that a product feels tailored to the individual’s needs and preferences. This might mean personalized workout recommendations based on the user’s fitness level and goals. For example, if a user prefers strength training over cardio, the app might suggest new weightlifting routines or articles about improving strength. The more the app can adapt to the user’s personal interests and goals, the more engaged the customer will be.</p><p>Empowerment is about giving customers the tools and knowledge to take control of their experience. For the fitness app, empowerment might come from allowing users to set their own fitness goals, create personalized workout plans, and track their progress. The app could also provide educational content like workout tips or nutritional advice, enabling users to make informed decisions about their health. When users feel empowered to manage their fitness journey, they are more likely to stick with the app, as it enhances their confidence and sense of control.</p><p>When these components—effortless experience, emotional satisfaction, consistent reliability, personal relevance, and empowerment—come together, they create the ideal customer state. In the case of the fitness app, this means that users not only find it easy to track their workouts but also enjoy the process and feel more motivated. The app w<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7baba7aa0ee73ad40cc09f317188e62a','intuit-design-for-delight-m4-l6-lesson-5','548aec12cba794386b65db6117196686','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Idea State Statement</h3><p>Idea State Statement</p><p>Crafting an Ideal State Statement Using Intuit&#39;s Design for Delight Framework</p><p>An ideal state statement is a clear, concise description of the perfect customer experience, encapsulating how a product or service should meet and exceed customer needs and expectations.&#160;This statement serves as a guiding vision for product development and innovation within the Intuit Design for Delight (D4D) framework.&#160;This section will cover how to craft an ideal state statement, along with the essential components.</p><p>Components of an Ideal State Statement</p><p>An ideal state statement encapsulates the perfect customer experience, guiding businesses toward creating delightful products and services.</p><p>An Ideal State Statement includes:</p><p>In a perfect world:&#160;(ideal outcome)</p><p>The biggest benefit to me is:&#160;(most important improvement in the customer&#39;s life once outcome is achieved)</p><p>Which makes me feel:&#160;(emotions)</p><p>Press through the tabs below to identify the essential components that form the foundation of an ideal state statement, ensuring it is customer-focused, clear, emotionally appealing, and aligned with business goals.</p><p>Customer Perspective</p><p>The statement should be written from the customer&#39;s viewpoint, reflecting their desires, needs, and experiences.&#160;It should answer the question:&#160;&quot;What would make the customer feel delighted?&quot;</p><p>If customers were to write their ideal state statements, they would begin, &quot;In a perfect world...&quot; and then go on to explain how their needs would be met.&#160;For instance, &quot;In a perfect world, I would have a home gym and a dedicated hour per day to work out.&quot;</p><p>Desired Outcomes</p><p>Clearly outline the specific outcomes or benefits that the customer will experience. These outcomes should be tangible and measurable, addressing both functional and emotional needs.</p><p>Simplicity and Clarity</p><p>Use simple, clear language to ensure that the statement is easily understandable by all stakeholders. Avoid jargon and complex terminology to keep the focus on the customer experience.</p><p>Emotional Appeal</p><p>Include elements that evoke positive emotions such as joy, satisfaction, and trust. This helps to emphasize the delight aspect of the experience.</p><p>Aspirational Yet Achievable</p><p>The statement should be aspirational, pushing the boundaries of what is currently possible, yet remain achievable with effort and innovation. It should inspire the team to strive for excellence while being grounded in reality.</p><p>Alignment with Business Goals</p><p>Ensure that the ideal state aligns with the overall business objectives and strategies. This alignment helps in maintaining a cohesive direction across all business functions.</p><p>Next Tab</p><p>Steps to Craft an Ideal State Statement</p><p>Crafting an ideal state statement involves a systematic approach that starts with understanding customer needs and ends with a refined, validated vision.&#160;Below you will find the steps to help you develop a statement that effectively captures the desired customer experience, driving innovation and satisfaction.&#160;Expand each section to learn about the step.</p><p>1.&#160;Empathize with the Customer</p><p>Conduct empathy interviews and immersive observations to deeply understand the customer&#39;s needs, desires, and pain points. Gather qualitative and quantitative data to inform your perspective.</p><p>2.&#160;Define Desired Outcomes</p><p>Based on the insights gathered, identify the key outcomes that would signify a delighted customer. These outcomes should cover both practical aspects (e.g., ease of use, efficiency) and emotional aspects (e.g., feeling valued, trust).</p><p>3.&#160;Draft the Statement</p><p>Begin drafting the ideal state statement by articulating the customer’s perfect experience in clear and simple language. Focus on describing the experience from the customer’s viewpoint.</p><p>4.&#160;Incorporate Emotional Elements</p><p>Ensure that the statement includes elements that evoke positive emotions. Describe how the customer will feel as a result of the experience.</p><p>5.&#160;Refine and Validate</p><p>Share the draft statement with stakeholders, including customers, if possible, to gather feedback. Refine the statement based on this feedback to ensure it accurately captures the ideal customer experience.</p><p>Examples of Ideal State Statements</p><p>Seeing examples of well-crafted ideal state statements can provide valuable insights and inspiration.&#160;Let&#39;s look at some examples tailored to different industries, demonstrating how to articulate the perfect customer experience in a clear, engaging, and aspirational manner.&#160;Press each flashcard below to flip it and reveal an ideal customer statement.&#160;Then press NEXT to go to the next business scenario.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>&#171; Back</p><p>E-Commerce Platform</p><p>E-Commerce Platform“Customers can effortlessly browse, find, and purchase products on our platform, experiencing joy and satisfaction with every interaction.&#160;They feel valued and understood through personalized recommendations and seamless support, trusting us as their go-to destination for all their shopping needs.”</p><p>Financial Services</p><p>Financial Services“Our customers feel empowered and confident managing their finances, experiencing peace of mind with our transparent, easy-to-use tools and personalized advice.&#160;They trust us to help them achieve their financial goals, feeling secure and valued at every step.”</p><p>Healthcare App</p><p>Healthcare App“Patients can easily navigate our app to book appointments, access medical records, and receive personalized health tips, experiencing relief and satisfaction.&#160;They feel cared for and supported, trusting us as their partner in achieving their health and wellness goals.”</p><p>⟳ Flip Card</p><p>Next &#187;</p><p>Flashcard&#160;1&#160;of&#160;3</p><p>Flashcard Transcript</p><p>Watch this video for a recap of the reading and module.</p><p>Hi and welcome to Video 5 for this module on Developing Deep Customer Empathy Part 2!</p><p>Formulating an &quot;ideal customer state&quot; statement is a powerful way to define the ultimate experience a cus<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('53561f82d260c1838d33673ab2574768','intuit-design-for-delight-m4-l7-module-3-summary','548aec12cba794386b65db6117196686','Module 3 Summary','text',12,'<h2>Module 3 Summary</h2><section><h3>Module 3 Summary</h3><p>Module 3 Summary</p><p>Great Work!&#160;You have successfully completed this module on&#160;Developing Deep Customer Empathy Part II.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified and described customer observation methods and customer observation best practices.</p><p>Identified the important takeaways and most important results from customer observation.</p><p>Identified surprises and pain points.</p><p>Identified the components of an ideal state statement.</p><p>Given a situation, created or completed an ideal state statement</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('623890bf77758f15a068e95f7646e209','intuit-design-for-delight-m4-l8-module-3-test-prep','548aec12cba794386b65db6117196686','Module 3 Test Prep','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Customer Empathy Part 2. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,7,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c7d790f7e2838a73e70d96575c30fe9a','intuit-design-for-delight-m4-l9-module-3-assignment','548aec12cba794386b65db6117196686','Module 3 Assignment','text',12,'<h2>Module 3 Assignment</h2><section><h3>Module 3 Assignment</h3><p>Module 3 Assignment</p><p>Intuit Design for Delight</p><p>Developing Deep Customer Empathy Part II - Short Answer Assignment</p><p>Short answer assignment</p><p>For this writing assignment, write a two-page, double-spaced paper addressing the questions/topics listed.</p><p>First, expand the section below to read the article.</p><p>The Benefits of Customer Observation for Businesses</p><p>The Benefits of Customer Observation for Businesses: Gaining Deep Insights into Customer Behaviors and Unmet Needs</p><p>Understanding customer behaviors and unmet needs is essential for businesses aiming to create products and services that truly resonate with their audience. One of the most effective ways to achieve this understanding is through customer observation. By immersing themselves in the world of their customers, businesses can gather rich, qualitative data that reveals insights often missed by surveys or quantitative methods. This article explores the profound benefits of customer observation, its application in general business contexts, and its critical role within Intuit&#39;s Design for Delight (D4D) framework.</p><p>The Power of Customer Observation</p><p>Customer observation involves watching and analyzing how customers interact with products or services in their natural environments. This method allows businesses to capture authentic behaviors, emotions, and pain points, providing a holistic view of the customer experience. Unlike structured interviews or surveys, observation uncovers subconscious actions and reactions that customers might not articulate verbally.</p><p>One of the primary benefits of customer observation is the ability to identify unmet needs. Customers often adapt to shortcomings in products or services without formally complaining. Through observation, businesses can see these adaptations and identify opportunities for improvement or innovation. For instance, if a coffee shop notices customers frequently rearranging tables to accommodate group meetings, it may indicate a need for more flexible seating arrangements.</p><p>Moreover, observation helps businesses understand the context in which their products are used. This context is crucial for designing solutions that fit seamlessly into the customer&#39;s daily life. For example, a company developing a fitness tracker might observe that users often forget to charge their devices. This insight could lead to the creation of a tracker with longer battery life or alternative charging methods.</p><p>Applying Customer Observation in Business</p><p>Businesses across various industries can leverage customer observation to enhance their offerings. Retail stores, for instance, can observe customer flow and behavior to optimize store layout and product placement. By understanding how customers navigate the space and which displays attract the most attention, stores can create a more engaging and efficient shopping experience.</p><p>In the tech industry, software companies can observe users interacting with their applications to identify usability issues and areas for enhancement. Watching how users navigate through a software interface can reveal confusion points or inefficiencies that need addressing. This direct feedback is invaluable for creating intuitive and user-friendly designs.</p><p>Healthcare providers can also benefit from customer observation. By observing patient interactions within a clinic or hospital, healthcare professionals can identify bottlenecks in service delivery and areas where patient care can be improved. This might include redesigning waiting areas for better comfort and privacy or streamlining check-in processes to reduce wait times.</p><p>Customer Observation in the Intuit D4D Framework</p><p>Intuit&#39;s Design for Delight (D4D) framework places a strong emphasis on customer empathy, and observation is a key component of this approach. The D4D methodology involves deeply understanding customers to create solutions that delight them. Observation allows Intuit to go beyond what customers say they want, revealing deeper insights into their true needs and desires.</p><p>Within the D4D framework, customer observation is used in several stages of the product development process. During the initial discovery phase, it helps identify the real problems customers face. For example, Intuit might observe small business owners managing their finances to understand the specific challenges they encounter with current accounting software. These observations can highlight pain points such as difficulty tracking expenses or generating reports.</p><p>In the ideation phase, insights from customer observation inform brainstorming sessions, ensuring that generated ideas are grounded in real user experiences. By knowing the exact context and behavior of their users, teams can develop more relevant and impactful solutions. For instance, if observation reveals that users frequently switch between different devices, the team might prioritize developing a feature that syncs data seamlessly across platforms.</p><p>During prototyping and testing, observation plays a crucial role in validating assumptions and refining solutions. By observing how customers interact with prototypes, Intuit can gather immediate feedback and iterate quickly. This iterative process ensures that the final product not only meets but exceeds customer expectations, delivering a delightful experience.</p><p>Conclusion</p><p>Customer observation is a powerful tool for businesses seeking to gain deep insights into customer behaviors and unmet needs. By immersing themselves in the customer&#39;s world, businesses can uncover hidden opportunities for innovation and improvement. This method provides a rich, nuanced understanding of the customer experience that cannot be captured through quantitative data alone.</p><p>Incorporating customer observation into the Intuit D4D framework enhances the ability to create products and services that truly delight customers. By emphasizing empathy and continuous iteration, D4D ensures that solutions are not only functional but also deeply satisfying to users.</p><p>As businesses strive to stay competitive and relevant in an ever-changing market, embracing customer observation can lead to more informed decision-making and ultimately, more successful products and services. Understanding and addressing the real needs of customers is the key to creating meaningful and lasting<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9bd01701abca4e561f1ebfc3ede0bb99','intuit-design-for-delight-m4-l10-module-3-project','548aec12cba794386b65db6117196686','Module 3 Project','text',12,'<h2>Module 3 Project</h2><section><h3>Module 3 Project</h3><p>Module 3 Project</p><p>Intuit Design for Delight</p><p>Developing Deep Customer Empathy Part II - Project</p><p>Project</p><p>There are two parts to this project. Both parts can be contained in one presentation. You can use any format you prefer (PowerPoint, Prezi, Slides, etc.).</p><p>Part I: Steps to Crafting an Ideal State Statement</p><p>There are five steps to crafting an ideal state statement:</p><p>Empathize with the customer</p><p>Define desired outcomes</p><p>Draft the statement</p><p>Incorporate emotional elements</p><p>Refine and validate</p><p>For each step:</p><p>Explain what happens during the step.</p><p>Provide a real-life example of how you would complete the step.</p><p>Use graphics or other imagery relevant to the step.</p><p>Part II: Write Ideal State Statements</p><p>Choose three of the scenarios from the list below (expand to read the scenarios and objectives). Be sure to include this information in your presentation so that it&#39;s clear what you&#39;re responding to.</p><p>Write ideal state statements based on the scenarios and objectives you selected. Review the components of an ideal state statement and the examples in this module to be sure that your statement contains all of the necessary elements.</p><p>Include relevant graphics, images, photos, or other media to make this part of your presentation engaging.</p><p>You can write these statements from the customer perspective (&quot;In a perfect world...&quot; or like the examples from the reading where companies are describing the ideal state of their customers and the value the products and services provide)</p><p>Online Grocery Delivery Service</p><p>Scenario: Customers frequently complain about receiving incorrect items or having their deliveries delayed. They also find the app interface confusing and difficult to navigate.</p><p>Objective: Create an ideal state statement for an online grocery delivery service that ensures accuracy, timeliness, and ease of use.</p><p>Fitness App</p><p>Scenario: Users struggle to follow workout routines due to unclear instructions and a lack of personalized recommendations. They often feel unmotivated and unsure of their progress.</p><p>Objective: Develop an ideal state statement for a fitness app that provides clear guidance, personalized workout plans, and motivational support.</p><p>Banking Mobile App</p><p>Scenario: Customers find it challenging to perform basic transactions due to a complex user interface. They also have difficulty accessing customer support when issues arise.</p><p>Objective: Formulate an ideal state statement for a banking app that offers a user-friendly interface and reliable customer support.</p><p>Subscription Box Service</p><p>Scenario: Subscribers are often disappointed with the contents of their monthly boxes, feeling that the items are not tailored to their preferences. They also experience delays in delivery.</p><p>Objective: Craft an ideal state statement for a subscription box service that delivers personalized, high-quality items on time.</p><p>Telemedicine Platform</p><p>Scenario: Patients experience long wait times for virtual appointments and find the process of booking and accessing these appointments cumbersome. They also feel disconnected from their healthcare providers.</p><p>Objective: Create an ideal state statement for a telemedicine platform that offers quick, easy access to virtual healthcare appointments and fosters a sense of connection with providers.</p><p>E-Learning Platform</p><p>Scenario: Students find the platform&#39;s course materials difficult to follow and often struggle to stay engaged. They also have trouble receiving timely feedback on their assignments.</p><p>Objective: Develop an ideal state statement for an e-learning platform that provides engaging, easy-to-understand course materials and prompt, helpful feedback.</p><p>Ride-Sharing Service</p><p>Scenario: Riders frequently encounter issues with driver cancellations, long wait times, and unclear fare estimates. They also feel unsafe during some rides.</p><p>Objective: Formulate an ideal state statement for a ride-sharing service that ensures reliability, transparency, and safety.</p><p>Home Cleaning Service</p><p>Scenario: Customers are often dissatisfied with the quality of the cleaning and the lack of communication regarding appointment times and special requests.</p><p>Objective: Craft an ideal state statement for a home cleaning service that guarantees high-quality cleaning, effective communication, and customization options.</p><p>Retail Clothing Store</p><p>Scenario: Shoppers struggle to find the right sizes and styles due to poor organization and limited inventory. They also find the checkout process slow and inefficient.</p><p>Objective: Create an ideal state statement for a retail clothing store that offers a well-organized shopping experience, ample inventory, and a swift checkout process.</p><p>Event Planning Service</p><p>Scenario: Clients often feel stressed and overwhelmed due to poor coordination and communication with the event planning team. They are also unhappy with the final execution of their events.</p><p>Objective: Develop an ideal state statement for an event planning service that provides seamless coordination, clear communication, and flawless execution of events.</p><p>Review the rubric below to determine how you will be graded.</p><p>Developing Deep Customer Empathy Part II Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Part I</p><p>8 points The content demonstrates a strong understanding of the steps to crafting an ideal state statement. Each step is explained well, has a relevant example, and has relevant imagery.</p><p>7-4 points The content demonstrates a fair understanding of the steps to crafting an ideal state statement. Each step is explained relatively well, has an example, and has imagery.</p><p>3-0 points The content demonstrates little to no understanding of the steps to crafting an ideal state statement. Examples and images are either not used or not relevant to the step.</p><p>8</p><p>Part II</p><p>8 points The three ideal state statements contained all of the necessary components (customer perspective, desired outcomes, simplicity and clarity, emotional appeal, aspirational yet achievable, and alignment with business goals). Each statement works very well with the scenarios and objectives selected.</p><p>7-6 points T<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,9,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2d48d02871441858b547c6333d0348de','intuit-design-for-delight-m4-l11-module-3-quiz','548aec12cba794386b65db6117196686','Module 3 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Customer Empathy Part 2. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,10,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('ee951fac9eb7c5913ab37465a845e85b','intuit-design-for-delight-module-5','92a4f5cdddc7f69042b22cbdf20f300f','Module 5: Brainstorming & Narrowing',5) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7dd536bb657ebd130d6a6e7c562c2625','intuit-design-for-delight-m5-l1-introduction-purpose-and-objectives','ee951fac9eb7c5913ab37465a845e85b','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi and welcome to this module on Brainstorming and Narrowing.</p><p>What does brainstorming have to do with the Design for Delight process? In this module, let’s explore the purpose of brainstorming and how it helps unleash creativity by allowing all ideas to flow freely. But having too many ideas can be just as tricky as having none, so you’ll also learn how to narrow down your brainstorm to focus on the best and most practical solutions.</p><p>Once we’ve generated and narrowed our ideas, how do we communicate them to others? We’ll also introduce you to different methods of representing your ideas visually. You’ll learn what information is essential to include in these representations, so your ideas are understood, appreciated, and ready to be turned into reality. By the end, you’ll be equipped to go from chaotic creativity to structured solutions with confidence.</p><p>Module Description</p><p>In this module, you will learn the purpose of brainstorming and narrowing ideas to foster creativity and focus. You will explore various methods and best practices for both brainstorming and narrowing, ensuring you can generate a wide range of ideas and then refine them effectively. Additionally, you will identify different methods for representing ideas visually and conceptually, along with the key information that needs to be included in these representations to communicate your ideas clearly and effectively.</p><p>Objectives</p><p>In this module, students will</p><p>Identify the purpose of brainstorming and narrowing.</p><p>Identify methods of brainstorming and narrowing.</p><p>Identify best practices for brainstorming and narrowing.</p><p>Identify methods of representing ideas.</p><p>Identify the information necessary in a representation.</p><p>Polling Question</p><p>In your experience, what is the best benefit of brainstorming?</p><p>the quantity of ideas produced&#160;the collaboration&#160;the engagement it encourages&#160;it boosts morale&#160;it reveals hidden potential</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Definition</p><p>a method of generating ideas and sharing knowledge to solve a particular problem, in which participants are encouraged to think without interruption</p><p>narrowing</p><p>clarifying goals, scope, and criteria to focus&#160; brainstorming on the most relevant and feasible ideas</p><p>risk mitigation</p><p>the process of ensuring that all aspects of an organization, including its goals, resources, and activities, are coordinated and in harmony with its overall approach</p><p>strategic alignment</p><p>a strategy to prepare for and lessen the effects of threats faced by a business</p><p>brainstorming</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>a method of generating ideas and sharing knowledge to solve a particular problem, in which participants are encouraged to think without interruption</p><p>Answers for question: 1</p><p>strategic alignment</p><p>brainstorming</p><p>narrowing</p><p>risk mitigation</p><p>2.</p><p>clarifying goals, scope, and criteria to focus&#160; brainstorming on the most relevant and feasible ideas</p><p>Answers for question: 2</p><p>narrowing</p><p>brainstorming</p><p>risk mitigation</p><p>strategic alignment</p><p>3.</p><p>the process of ensuring that all aspects of an organization, including its goals, resources, and activities, are coordinated and in harmony with its overall approach</p><p>Answers for question: 3</p><p>strategic alignment</p><p>narrowing</p><p>risk mitigation</p><p>brainstorming</p><p>4.</p><p>a strategy to prepare for and lessen the effects of threats faced by a business</p><p>Answers for question: 4</p><p>narrowing</p><p>brainstorming</p><p>risk mitigation</p><p>strategic alignment</p><p>Definition</p><p>an idea generation technique in which participants independently jot down their ideas—synchronously or asynchronously</p><p>value proposition</p><p>a visual planning method used to outline and organize a sequence of events or steps in a process involving a series of illustrations or images, often accompanied brief descriptions</p><p>brainwriting</p><p>a statement that clearly identifies the benefits a company&#39;s products and services will deliver to its customers</p><p>storyboarding</p><p>the process of repeatedly gathering and incorporating input from stakeholders or users to refine and improve a product, idea, or process</p><p>iterative feedback</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>an idea generation technique in which participants independently jot down their ideas—synchronously or asynchronously</p><p>Answers for question: 1</p><p>storyboarding</p><p>value proposition</p><p>brainwriting</p><p>iterative feedback</p><p>2.</p><p>a visual planning method used to outline and organize a sequence of events or steps in a process involving a series of illustrations or images, often accompanied brief descriptions</p><p>Answers for question: 2</p><p>storyboarding</p><p>value proposition</p><p>brainwriting</p><p>iterative feedback</p><p>3.</p><p>a statement that clearly identifies the benefits a company&#39;s products and services will deliver to its customers</p><p>Answers for question: 3</p><p>value proposition</p><p>brainwriting</p><p>storyboarding</p><p>iterative feedback</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6a66623468ff73765d54afb8312b3589','intuit-design-for-delight-m5-l2-lesson-1','ee951fac9eb7c5913ab37465a845e85b','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Brainstorming &amp; Narrowing purpose</h3><p>Brainstorming &amp; Narrowing purpose</p><p>The Purpose of Brainstorming and Narrowing</p><p>In the dynamic landscape of modern business and innovation, effective problem-solving and creativity are paramount.&#160;Two critical processes that facilitate these objectives are brainstorming and narrowing.&#160;These methodologies are not only central to the Intuit Design for Delight (D4D) framework but also have wide-ranging applications across various business contexts and everyday life.&#160;This section explores the significance of brainstorming and narrowing, highlighting why these processes are essential for generating and refining ideas.</p><p>The Significance of Brainstorming</p><p>Brainstorming is a creative technique that encourages the free flow of ideas in a group setting.&#160;Its primary purpose is to generate a large volume of ideas, which can later be refined and developed into actionable solutions.&#160;There are some key reasons why brainstorming is crucial.&#160;Expand the sections below to learn more.</p><p>Fostering Creativity and Innovation</p><p>Brainstorming sessions provide a platform for participants to think outside the box, encouraging creative and innovative ideas. By suspending judgment and welcoming all contributions, brainstorming creates an environment where unconventional and potentially groundbreaking ideas can emerge.</p><p>Encouraging Collaboration</p><p>Brainstorming brings together diverse perspectives and expertise, fostering collaboration among team members. This collective approach not only enhances the quality of ideas but also builds a sense of ownership and shared purpose.</p><p>Unlocking Hidden Potential</p><p>Often, the most innovative solutions come from unexpected sources. Brainstorming sessions can reveal hidden talents and insights from team members who may not typically voice their ideas in more structured settings.</p><p>Boosting Engagement and Morale</p><p>Participating in brainstorming sessions can boost employee engagement and morale by giving individuals a voice and an opportunity to contribute to the problem-solving process. This inclusivity can lead to higher levels of motivation and commitment.</p><p>Watch this video to see brainstorming in action.</p><p>Hi and welcome to video 5 for this module on The Anatomy and Physiology of the Human Body!</p><p>As we’ve done several times in this module, let’s start with a common scenario that a nurse might encounter during a normal workday.</p><p>A young athlete comes into the clinic complaining of dizziness and fatigue. At first glance, it could be dehydration, stress, or even lack of sleep. But after a few quick observations, the nurse notices something concerning—his skin looks slightly pale, and his heart rate is faster than normal. Next, the nurse asks some key questions. The nurse discovers that the patient has been feeling unusually cold, bruising easily, and struggling with headaches. These clues point to something beyond just exhaustion. They suggest a possible iron deficiency or anemia. This is just one example of how a strong understanding of anatomy and physiology allows nurses to detect problems early and help patients before their conditions worsen.</p><p>Prevention is always the best strategy when it comes to health. Nurses use their knowledge of how the body works to recognize early warning signs of disease and take action before a problem becomes severe. For example, a patient might come in with swollen legs and shortness of breath. Instead of just treating the swelling with ice or suggesting rest, a trained nurse considers deeper causes. Swollen legs could be a sign of poor circulation, kidney disease, or even heart failure. By understanding how the circulatory system, kidneys, and lungs work together, nurses can connect symptoms to possible underlying conditions, communicate this information to the doctor, and make sure the patient gets the right treatment.</p><p>As you’ll learn in any class on anatomy and physiology, the human body is like a complex machine, with different systems working together to maintain balance. If one system starts to fail, the effects ripple throughout the body. For example, if a person has severe pneumonia (which is a lung infection), the lungs struggle to take in oxygen. This means the heart must work harder to pump oxygen-rich blood to the rest of the body. Over time, this extra strain can lead to heart complications. Similarly, a simple infection in one part of the body, like an untreated tooth abscess, can spread through the bloodstream and cause serious conditions like sepsis—a life-threatening reaction to infection. Nurses are trained to see these connections, which allows them to treat not just symptoms, but the root cause of a patient’s health issue.</p><p>One of the key skills nurses develop is the power of observation. A good nurse doesn’t just listen to what a patient says; they also pay attention to breathing patterns, skin changes, and heart rate fluctuations—all of which can point to larger health concerns. For instance, a patient might not realize that their bluish lips or fingernails indicate low oxygen levels, which could be caused by lung disease, heart problems, or even carbon monoxide poisoning. Another patient might dismiss constant thirst and frequent urination as nothing serious, but a nurse recognizes these as common signs of diabetes. These small but significant details allow nurses to act quickly and prevent serious complications.</p><p>With the right tools and knowledge, nurses help manage health conditions across the body. They use stethoscopes to listen for abnormal lung or heart sounds, blood pressure cuffs to check circulation, and even electrocardiograms (or ECGs) to detect irregular heartbeats. Beyond medical tools, they also use critical thinking and patient communication to uncover hidden health problems. For example, an elderly patient who is losing weight and feeling weak may not mention that they’ve been having difficulty swallowing. A skilled nurse, by asking the right questions and noticing subtle symptoms, can detect that the patient may have a neurological disorder affecting their ability to eat.</p><p>Nurses play a critical role in preventing, detecting, and treating health issues before they become life-threatening. Their deep understanding of anatomy and physiology allows them to see the bigger picture—how all the body’s systems interact <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4ea27662d221d9db9f530aaa960f75e4','intuit-design-for-delight-m5-l3-lesson-2','ee951fac9eb7c5913ab37465a845e85b','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Methods of Brainstorming</h3><p>Methods of Brainstorming &amp; Narrowing</p><p>Methods of Brainstorming and Narrowing</p><p>In the realm of innovation and problem-solving, brainstorming and narrowing are critical processes that drive the generation and refinement of ideas.&#160;These methodologies are integral to the Intuit Design for Delight (D4D) framework, providing structured approaches to creativity and decision-making.&#160;This section explores various methods of brainstorming and narrowing, detailing how these techniques can be effectively carried out to achieve impactful results.</p><p>Brainstorming Methods</p><p>Brainstorming is the process of generating a large number of ideas in a collaborative setting.&#160;The goal is to encourage free thinking and creativity without immediate criticism or judgment.&#160;Below are some effective brainstorming techniques.&#160;Expand the sections below each image to learn about brainstorming methods.</p><p>Classic Brainstorming</p><p>Preparation: Gather a group of 4-6 people, ideally from diverse backgrounds, to bring different perspectives. Appoint a facilitator to guide the session.</p><p>Set the Stage: Define the problem or challenge clearly and frame it as a &quot;How might we?&quot; statement. Establish ground rules such as deferring judgment, encouraging wild ideas, and going for quantity.</p><p>Warm-Up: Start with a quick, unrelated exercise to get the creative juices flowing.</p><p>Brainstorm: Allow participants to share ideas freely, building on each other&#39;s suggestions. Use prompts to keep the momentum going if the group hits a slump.</p><p>Record Ideas: Capture all ideas on a whiteboard or sticky notes, ensuring visibility to all participants.</p><p>7 to Get to 1</p><p>Individual Ideation: Each team member spends 1-2 minutes silently writing down or sketching their &quot;best idea&quot; on a sticky note.</p><p>Sharing and Building: Team members then share their ideas with the group, which generates further brainstorming and refinement of ideas. Each member aims to come up with at least seven distinct ideas.</p><p>Selection: The team reviews all the ideas and selects the boldest one to move forward. This can also be repeated with the bold idea to generate even more variations.</p><p>Brainwriting</p><p>Silent Ideation: Each participant writes down their ideas on a piece of paper.</p><p>Rotation: Papers are passed around the group, with each participant building on the previous ideas.</p><p>Compilation: After several rotations, the ideas are collected and discussed as a group, with additional brainstorming to refine and expand upon them.</p><p>Mind Mapping</p><p>Central Idea: Start with the main problem or challenge written in the center of a whiteboard or large piece of paper.</p><p>Branching: Participants add related ideas around the central concept, creating branches that explore different aspects of the problem.</p><p>Expansion: Continue to add sub-branches, detailing more specific ideas and connections. This visual approach helps in organizing thoughts and identifying relationships between ideas.</p><p>Narrowing Methods</p><p>Narrowing is the process of filtering and refining brainstormed ideas to identify the most viable solutions.&#160;Press through the tabs below to explore some effective narrowing techniques.</p><p>2X2 Matrix</p><p>Criteria Selection:&#160;Define two key criteria for evaluation, such as feasibility and impact on customer benefit.</p><p>Plotting Ideas:&#160;Place each idea on a 2x2 matrix according to how well it meets the criteria.&#160;This visual representation helps in comparing and contrasting different ideas.</p><p>Discussion and Decision:&#160;Use the matrix to facilitate discussion and make intentional decisions about which ideas to pursue.&#160;The top-right quadrant (high feasibility, high impact) often contains the most promising ideas.</p><p>100 Point Narrowing</p><p>Idea Organization: Display all brainstormed ideas on a whiteboard or table where everyone can see them.</p><p>Point Allocation: Each team member is given 100 points to distribute among the ideas based on specific criteria (e.g., biggest customer benefit). Write the points next to each idea.</p><p>Tallying and Focusing: Sum the points for each idea. Focus on the ideas with the highest scores, as these reflect the collective preference and perceived value.</p><p>Dot Voting</p><p>Idea Presentation: Display all ideas on a wall or board.</p><p>Voting: Each participant is given a set number of sticky dots or markers to place on their preferred ideas.</p><p>Selection: Count the dots to see which ideas have the most support. This quick and democratic method helps in identifying the most popular ideas.</p><p>Impact/Effort Matrix</p><p>Criteria Definition: Define the axes of the matrix as &quot;Impact&quot; and &quot;Effort.&quot;</p><p>Plotting Ideas: Place each idea on the matrix based on its perceived impact and the effort required to implement it.</p><p>Analysis: Ideas in the high-impact, low-effort quadrant (quick wins) are often prioritized. This method helps in balancing potential benefits with the resources needed.</p><p>Storyboarding</p><p>Scenario Creation: Draw a series of boxes representing key moments in the customer journey.</p><p>Visualization: Illustrate how the customer interacts with the proposed solution, detailing the steps and experiences.</p><p>Feedback and Refinement: Share the storyboard with others to gather feedback and refine the idea. This visual tool helps in understanding and communicating the customer experience.</p><p>Next Tab</p><p>Tying into the Intuit Design for Delight Framework</p><p>The processes of brainstorming and narrowing are integral to the Intuit Design for Delight (D4D) framework, which emphasizes deep customer empathy, going broad to go narrow, and rapid experimentation.&#160;By systematically generating and refining ideas, businesses can develop innovative solutions that truly delight customers.&#160;Press the plus (+) in each section below to learn about the brainstorming and narrowing activities that happen during that phase.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Tying Brainstorming and Narrowing Methods into the D4D Framework: Deep Customer Empathy Going Broad to Go Narrow Rapid Experimentation</p><p>The hotspot points on the image are as follows:</p><p>Go Broad to Go Narrow</p><p>Thi<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b2a0a5cd0c96080558b306bae415ffe5','intuit-design-for-delight-m5-l4-lesson-3','ee951fac9eb7c5913ab37465a845e85b','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Best Practices for Brainstorming</h3><p>Best Practices for Brainstorming</p><p>Best Practices for Brainstorming and Narrowing</p><p>Brainstorming and narrowing are crucial processes in innovation, problem-solving, and decision-making.&#160;When executed effectively, these techniques can lead to impactful and creative solutions.&#160;This section outlines best practices for both brainstorming and narrowing, providing practical examples to illustrate their application.</p><p>Best Practices for Brainstorming</p><p>In every industry, a &quot;best practice&quot; is a process that has been identified as the most effective way to do something.&#160;Best practices are always evolving, so it&#39;s a great idea to familiarize yourself with best practices in whatever industry you find yourself.</p><p>Watch the video below to learn more about brainstorming best practices, then read about what you watched.</p><p>Hi and welcome to Lesson 3 for this module on Brainstorming and Narrowing.</p><p>Have you ever been in a group project where everyone is asked to brainstorm ideas, only to end up with the same few suggestions repeated over and over? This common scenario highlights the challenges many people face during brainstorming, especially in product design. Brainstorming is meant to be a creative process that generates a wide range of possibilities. However, when done poorly, it can feel unproductive and frustrating. So, what causes groups to get brainstorming wrong, and how can it be done effectively? Let’s take a look at some answers in this video.</p><p>One of the most common reasons brainstorming fails is that we limit ourselves based on what we already know or assume to be true. When faced with a problem, we tend to fall back on familiar solutions or ideas that have worked in the past. This mindset prevents us from thinking outside the box and considering new possibilities that might lead to more innovative product designs.</p><p>Another problem is the fear of being judged. Many people hold back their ideas because they are afraid others will think they are &quot;dumb&quot; or unrealistic. This fear of criticism can severely limit the range of ideas shared during a brainstorming session.</p><p>Groupthink is another issue that derails brainstorming. When people work together in groups, there is often an unconscious desire to conform to what others are thinking. This can prevent people from proposing ideas that challenge the status quo, which is essential for innovation. For example, if everyone in a group agrees that the next product should be smaller and lighter, someone might hesitate to suggest making the product larger but more functional, even if it could be a better idea.</p><p>A lack of diversity also hinders brainstorming efforts. When a group is made up of people with similar backgrounds, experiences, and perspectives, the range of ideas is often limited. In companies, this is especially common when brainstorming groups consist of people from the same department. Their shared understanding might mean they all approach problems in similar ways, reducing the likelihood of coming up with truly creative solutions.</p><p>Moreover, a fixed mindset can get in the way of effective brainstorming. People with a fixed mindset believe that their abilities and intelligence are set in stone, which leads them to avoid taking risks or proposing new ideas. In contrast, people with a growth mindset are more willing to embrace challenges and experiment with different possibilities, which is key to a successful brainstorming process.</p><p>Finally, cultural barriers can also interfere with brainstorming. In some cultures, individuals might be less likely to speak up in group settings, particularly if they hold a lower position in the company hierarchy. This can prevent valuable ideas from being shared and considered, limiting the diversity of thought within the group.</p><p>So how can brainstorming be done right? First, it’s crucial to create an environment where everyone feels comfortable sharing ideas without fear of judgment. This can be achieved by setting clear ground rules that encourage open communication and discourage criticism during the brainstorming process. Everyone should feel safe to voice even the wildest ideas, as they could spark a breakthrough or lead to unexpected solutions.</p><p>Second, it&#39;s important to clearly define the problem and objectives of the brainstorming session. Without a clear direction, the group may wander off-topic, and ideas will be scattered. A well-defined problem helps participants focus their creativity and generate solutions that are relevant and actionable.</p><p>Incorporating creative techniques can also help. For instance, &quot;brain writing&quot; involves having participants write down their ideas anonymously before sharing them with the group. This removes the fear of criticism and allows everyone to contribute equally. Mind mapping is another effective tool, which helps visualize connections between different ideas, leading to a more structured and productive brainstorming session.</p><p>Active facilitation is also key to keeping the brainstorming process on track. A facilitator can help guide the session, ensure everyone has a chance to contribute, and keep the conversation focused. Warm-up exercises, such as quick games or thought experiments, can also help participants get into a creative mindset before diving into the actual brainstorming.</p><p>To sum up, brainstorming can be an incredibly effective tool for product design, but only if done correctly. By fostering an open, judgment-free environment, defining clear objectives, and using creative techniques, groups can overcome common barriers like fear of criticism, groupthink, and lack of diversity. When these elements are in place, brainstorming becomes a powerful tool for innovation and problem-solving.</p><p>So, the next time you find yourself in a brainstorming session, ask yourself: Are we creating the right environment to encourage truly creative thinking? If the answer is yes, you’re on your way to a successful brainstorm!</p><p>Create a Safe Environment</p><p>Encourage Open Communication:&#160;Ensure that all participants feel comfortable sharing their ideas without fear of judgment or criticism.&#160;This fosters a culture of trust and psychological safety, essential for creative thinking.</p><p>Diverse Participation:&#160;Involve people from different backgrounds and <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f598f1fd314ddce3fa8f2d3ba9788468','intuit-design-for-delight-m5-l5-lesson-4','ee951fac9eb7c5913ab37465a845e85b','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Methods of Showing Ideas in D 4D Frm</h3><p>Methods of Showing Ideas in D4D Frm</p><p>Methods of Representing Ideas in the D4D Framework</p><p>A critical component of the D4D framework is the effective representation of ideas, which helps teams communicate, refine, and test their concepts.&#160;This section explores various methods of representing ideas within the D4D framework, combining descriptive paragraphs and bullet points for clarity.&#160;You&#39;ve learned about some of these methods in other sections.&#160;This section will further explain how they can be created, the benefits of using each, and what they might look like when implemented in real-life situations.</p><p>Storyboarding</p><p>Storyboarding is a visual method that illustrates how a customer will interact with a proposed solution.&#160;It helps teams visualize the customer journey and identify potential improvements.&#160;Press through the tabs below to learn about the steps to storyboarding, benefits, and an example.</p><p>Steps to Create a Storyboard</p><p>Identify Key Moments:&#160;Outline the significant steps in the customer&#39;s journey.</p><p>Visualize the Steps:&#160;Draw simple sketches or diagrams of each step.</p><p>Describe Each Step:&#160;Provide a brief description of what happens in each sketch.</p><p>Benefits</p><p>Clarifies how the idea works in real life.</p><p>Highlights customer pain points and opportunities for improvement.</p><p>Facilitates communication within the team and with stakeholders.</p><p>Example</p><p>An app development team creates a storyboard to illustrate how users will navigate a new feature. The storyboard includes sketches of the user logging in, accessing the feature, using it, and achieving their goal.</p><p>Next Tab</p><p>Prototyping</p><p>Prototyping involves creating a tangible or digital model of the proposed solution.&#160;It allows teams to test and refine their ideas quickly.&#160;Press through the tabs below to learn about types of prototypes, steps to creating prototypes, benefits, and an example.</p><p>Types of Prototypes</p><p>Low-Fidelity Prototypes:&#160;Simple models like paper sketches or wireframes that capture the basic concept.</p><p>High-Fidelity Prototypes:&#160;Detailed and interactive models that closely resemble the final product.</p><p>Steps to Prototype</p><p>Choose the Fidelity Level: Decide whether a low- or high-fidelity prototype is appropriate based on the stage of development.</p><p>Create the Prototype: Build the model using available tools and materials.</p><p>Test and Iterate: Gather feedback from users and make necessary adjustments.</p><p>Benefits</p><p>Provides a tangible representation of the idea.</p><p>Identifies usability issues and areas for improvement.</p><p>Enables rapid testing and iteration.</p><p>Example</p><p>A design team creates a low-fidelity prototype of a new website layout using paper sketches. They conduct user testing sessions to gather feedback and refine the design before moving to a high-fidelity digital prototype.</p><p>Next Tab</p><p>Mind Mapping</p><p>Mind mapping is a visual brainstorming tool that helps teams explore and organize ideas around a central concept.&#160;Press through the tabs below to learn about the steps, benefits, and an example of mind mapping.</p><p>Steps to Create a Mind Map</p><p>Start with a Central Idea:&#160;Write the main problem or challenge in the center of a whiteboard or paper.</p><p>Add Branches:&#160;Create branches for related topics or sub-problems.</p><p>Expand the Branches:&#160;Add further details and ideas to each branch.</p><p>Benefits</p><p>Organizes complex information visually.</p><p>Encourages creative thinking and connections between ideas.</p><p>Provides a comprehensive overview of the problem space.</p><p>Example</p><p>A marketing team uses a mind map to brainstorm ideas for a new campaign. The central idea is the product, with branches exploring different target audiences, marketing channels, and promotional tactics.</p><p>Next Tab</p><p>Customer Journey Mapping</p><p>Customer journey mapping involves creating a detailed map of the customer&#39;s experience with a product or service.&#160;It highlights the touchpoints and interactions that customers have throughout their journey.&#160;Press through the tabs below to learn about the steps, benefits, and an example of customer journey mapping.</p><p>Steps to Create a Customer Journey Map</p><p>Identify Stages:&#160;Outline the key stages of the customer journey, from awareness to post-purchase.</p><p>Map Touchpoints:&#160;Identify all the touchpoints where the customer interacts with the product or service.</p><p>Capture Emotions:&#160;Note the customer’s emotions and pain points at each touchpoint.</p><p>Identify Opportunities:&#160;Highlight areas where the customer experience can be improved.</p><p>Benefits</p><p>Provides a holistic view of the customer experience.</p><p>Identifies pain points and opportunities for enhancement.</p><p>Aligns team efforts around customer-centric improvements.</p><p>Example</p><p>A retail company maps the journey of a customer buying a product online. The map includes stages such as product discovery, purchase decision, checkout process, and post-purchase support, highlighting areas for improvement.</p><p>Next Tab</p><p>Role-Playing</p><p>Role-playing is an interactive method where team members act out scenarios to understand customer experiences and identify potential issues.&#160;Press through the tabs below to learn about the steps, benefits, and an example of role-playing.</p><p>Steps to Conduct Role-Playing</p><p>Define Scenarios:&#160;Create scenarios that reflect real customer interactions.</p><p>Assign Roles:&#160;Assign team members to play the roles of customers and service providers.</p><p>Act Out Scenarios:&#160;Perform the scenarios, focusing on customer needs and behaviors.</p><p>Debrief and Discuss:&#160;Analyze the role-playing sessions to identify insights and improvement areas.</p><p>Benefits</p><p>Provides a deeper understanding of customer perspectives.</p><p>Highlights practical issues and potential solutions.</p><p>Fosters empathy and customer-centric thinking.</p><p>Example</p><p>A customer service team role-plays different complaint scenarios to practice handling difficult situations and improve their response strategies.</p><p>Next Tab</p><p>Watch this video to see a demonstration of some of these techniques.</p><p>When it comes to generat<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('55aecc5dd1b4a464e7bef294a2065a3d','intuit-design-for-delight-m5-l6-lesson-5','ee951fac9eb7c5913ab37465a845e85b','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Components of Idea Representation</h3><p>Components of Idea Representation</p><p>Effective representation of ideas is crucial in any innovation process, including the Intuit Design for Delight (D4D) framework.&#160;The ability to communicate concepts, understand customer needs, and iterate on feedback can significantly enhance the development and refinement of products and services.&#160;This section delves into the necessary information required for representing ideas, focusing on the D4D framework and general practices.</p><p>1.&#160;Customer Empathy</p><p>Customer Personas: Detailed profiles of target customers, including demographics, behaviors, needs, and pain points.</p><p>Customer Journey Maps: Visual representations of the customer’s experience with the product or service, highlighting touchpoints, emotions, and potential pain points.</p><p>Example: A team developing a new budgeting app creates personas for different user types (e.g., young professionals, families, retirees) and maps their financial planning journey to identify key features and potential obstacles.</p><p>2.&#160;Problem Statement</p><p>Clear Definition: A concise description of the problem the idea aims to solve, framed as a “How might we” statement to focus the brainstorming process.</p><p>Context and Background: Information about the context in which the problem occurs, including relevant data and insights.</p><p>Example: For a project aimed at reducing customer support wait times, the problem statement might be, “How might we streamline the customer support process to reduce wait times and improve satisfaction?”</p><p>3.&#160;Idea Description</p><p>Concept Overview: A brief summary of the idea, including its purpose and key features.</p><p>Visuals and Sketches: Diagrams, sketches, or mock-ups that visually represent the idea and its components.</p><p>Example: A team proposing a new feature for a fitness app creates a concept overview highlighting how the feature will track workouts and provide personalized feedback, accompanied by wireframe sketches of the user interface.</p><p>4.&#160;Value Proposition</p><p>Customer Benefits: A clear articulation of how the idea will benefit customers, addressing their needs and solving their problems.</p><p>Differentiation: Explanation of what makes the idea unique compared to existing solutions.</p><p>Example: For a new online learning platform, the value proposition might emphasize personalized learning paths, interactive content, and 24/7 access to resources, differentiating it from traditional classroom settings.</p><p>5.&#160;Feasibility Analysis</p><p>Technical Feasibility: An assessment of the technical requirements and challenges associated with implementing the idea.</p><p>Resource Requirements: Identification of the resources needed, including time, budget, and personnel.</p><p>Example: Before developing a new e-commerce feature, a team conducts a feasibility analysis to evaluate the technical infrastructure needed, potential integration challenges, and estimated development costs.</p><p>6.&#160;Impact Assessment</p><p>Customer Impact: Evaluation of how the idea will impact the customer experience, including potential benefits and drawbacks.</p><p>Business Impact: Analysis of how the idea will affect the business, such as increased revenue, market share, or brand loyalty.</p><p>Example: A company considering a subscription model for their software assesses the potential increase in customer retention and recurring revenue, along with the impact on customer acquisition and satisfaction.</p><p>7.&#160;Prototyping and Testing</p><p>Prototype Development: Creation of low- or high-fidelity prototypes to test the idea in a tangible form.</p><p>User Testing and Feedback: Conducting tests with actual users to gather feedback and identify areas for improvement.</p><p>Example: A team developing a new mobile app feature creates a clickable prototype and conducts user testing sessions to gather insights on usability and functionality, iterating based on feedback.</p><p>8.&#160;Implementation Plan</p><p>Action Steps: A detailed plan outlining the steps needed to bring the idea to fruition, including milestones and deadlines.</p><p>Risk Management: Identification of potential risks and strategies to mitigate them.</p><p>Example: For a new product launch, the implementation plan includes market research, product development phases, marketing campaigns, and a timeline for each stage, along with contingency plans for potential delays.</p><p>Complementing the D4D Framework with Comprehensive Idea Representation</p><p>In the D4D framework, representing ideas effectively is critical to achieving the desired customer delight.&#160;By incorporating the elements outlined above, teams can ensure that their ideas are well-defined, customer-centric, and feasible.&#160;This comprehensive representation facilitates better decision-making, more effective communication, and smoother implementation.</p><p>General Best Practices for Idea Representation</p><p>Beyond the D4D framework, the principles of effective idea representation can be applied across various domains and industries.&#160;Watch the video for some general best practices.</p><p>Hi and welcome to Lesson 5 for this module on Brainstorming and Narrowing.</p><p>When presenting ideas, how you communicate them can be just as crucial as the ideas themselves. Whether you&#39;re sharing with colleagues, stakeholders, or customers, following best practices ensures your ideas are clear, engaging, and ready for action. Here are key guidelines to consider for effective idea representation.</p><p>One of the most important rules is to keep things clear and simple. Avoid using unnecessary jargon that could confuse your audience. For example, if a marketing team is pitching a new social media campaign, they should say, &quot;We’ll use targeted ads to reach a wider audience,&quot; instead of complicated technical terms like “cross-channel engagement optimization.”</p><p>Visual aids such as diagrams, sketches, or prototypes can help people grasp ideas quickly. For instance, presenting a wireframe for an app design can clearly show how users would interact with it. This kind of visual makes an abstract idea tangible and easier to evaluate.</p><p>A bad approach would be relying solely on text-heavy presentations. Describing a complex product verbally is much less effective than showing a sketch or prototype. Visuals help bring i<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('aa23a59f72f5f03757576dbff48c6f9e','intuit-design-for-delight-m5-l7-module-4-summary','ee951fac9eb7c5913ab37465a845e85b','Module 4 Summary','text',12,'<h2>Module 4 Summary</h2><section><h3>Module 4 Summary</h3><p>Module 4 Summary</p><p>Great Work!&#160;You have successfully completed this module on&#160;Brainstorming and Narrowing.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified the purpose of brainstorming and narrowing.</p><p>Identified methods of brainstorming and narrowing.</p><p>Identified best practices for brainstorming and narrowing.</p><p>Identified methods of representing ideas.</p><p>Identified the information necessary in a representation.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7350773139462f1691c0a489f1f5e5bf','intuit-design-for-delight-m5-l8-module-4-test-prep','ee951fac9eb7c5913ab37465a845e85b','Module 4 Test Prep','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Brainstorming & Narrowing. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,7,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('fa94692dbb5d129fe470163e8cf854a3','intuit-design-for-delight-m5-l9-module-4-assignment','ee951fac9eb7c5913ab37465a845e85b','Module 4 Assignment','text',12,'<h2>Module 4 Assignment</h2><section><h3>Module 4 Assignment</h3><p>Module 4 Assignment</p><p>Intuit Design for Delight</p><p>Brainstorming and Narrowing - Short Answer Assignment</p><p>Short answer assignment</p><p>In the module, you learned that the ability to communicate concepts, understand customer needs, and iterate feedback can significantly enhance the development and refinement of products and services. You explored the eight components of idea representation, listed below:</p><p>Customer Empathy</p><p>Problem Statement</p><p>Idea Description</p><p>Value Proposition</p><p>Feasibility Analysis</p><p>Impact Assessment</p><p>Prototyping and Testing</p><p>Implementation Plan</p><p>In a two-page, double-spaced paper, discuss why each of these components is crucial to the innovation process. You can use the questions below to guide you as you write.</p><p>Customer Empathy:</p><p>What role do customer personas play in understanding target customers in the D4D framework?</p><p>How can customer journey maps help in identifying key features and potential obstacles in a product or service?</p><p>Problem Statement:</p><p>Why is a clear definition of the problem important in the innovation process?</p><p>How does framing a problem as a “How might we” statement benefit the brainstorming process?</p><p>Idea Description:</p><p>What should be included in a concept overview to ensure clarity?</p><p>Why are visuals and sketches important in the idea description phase, and how can they aid in communication?</p><p>Value Proposition:</p><p>How can clearly articulating customer benefits strengthen an idea&#39;s representation?</p><p>What makes the differentiation of an idea crucial in the value proposition?</p><p>Feasibility Analysis:</p><p>What aspects are considered in a technical feasibility assessment?</p><p>Why is it important to identify resource requirements before implementing an idea?</p><p>Impact Assessment:</p><p>How can evaluating customer impact help refine an idea?</p><p>In what ways can analyzing the business impact guide decision-making in the innovation process?</p><p>Prototyping and Testing:</p><p>What is the purpose of creating low- or high-fidelity prototypes?</p><p>How can user testing and feedback contribute to the iterative improvement of an idea?</p><p>Implementation Plan:</p><p>What are the key components of an effective implementation plan?</p><p>How can identifying potential risks and strategies to mitigate them ensure smoother execution?</p><p>Review the rubric below to determine how you will be graded.</p><p>Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7d7364ca39e833a56865a3936f1a05ed','intuit-design-for-delight-m5-l10-module-4-quiz','ee951fac9eb7c5913ab37465a845e85b','Module 4 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Brainstorming & Narrowing. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('0f541f999179476a3ffab51ca402e6b7','intuit-design-for-delight-module-6','92a4f5cdddc7f69042b22cbdf20f300f','Module 6: Miterm Exam',6) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7cb5c5cc56680474e8bf7d7d6aa45b01','intuit-design-for-delight-m6-l1-miterm-exam','0f541f999179476a3ffab51ca402e6b7','Miterm Exam','text',12,'<h2>Miterm Exam</h2><section><h3>1Mid Term Exam</h3><p>1_Midterm Exam</p><p>Answer Key:Off</p><p>ABCABC</p><p>Directions:&#160;Read each question carefully and then choose the correct answer.</p><p>What distinguishes high-fidelity prototypes from medium-fidelity prototypes?</p><p>High-fidelity prototypes are simple sketches, while medium-fidelity prototypes are fully functional models</p><p>High-fidelity prototypes are paper-based, while medium-fidelity prototypes are digital</p><p>High-fidelity prototypes are used only for initial idea validation, while medium-fidelity prototypes are used for final user testing</p><p>High-fidelity prototypes are near-complete versions with functional features, while medium-fidelity prototypes include interactive elements and detailed designs</p><p>A customer recently acquired a premium smartphone highlighted for its extended battery life.&#160;However, after a few days of use, they found that the battery depletes much quicker than expected, requiring frequent recharging throughout the day.&#160;What surprise did this customer experience?</p><p>The battery life was much shorter than advertised.</p><p>The phone’s camera performance was subpar.</p><p>The user interface was challenging to use.</p><p>The screen resolution was not as high as claimed.</p><p>When customer observation captures pain points and moments of delight as they happen, it is occurring in _____.</p><p>retrospect</p><p>real-time</p><p>simulation</p><p>theory</p><p>What activities are involved during the Test phase when pursuing the Ideal Customer State?&#160;Select all that apply.</p><p>Feedback loops</p><p>Iterative improvements</p><p>Prototype creation</p><p>Customer surveys</p><p>A college student struggles with keeping their study materials organized across various platforms and devices.&#160;They want a solution that integrates their notes, assignments, and schedules into one unified system.&#160;What would be the likeliest ideal state statement for this person?</p><p>In a perfect world, I would have an all-in-one digital study platform that seamlessly integrates notes, assignments, and schedules.&#160;The biggest benefit to me is having everything organized in one place, which makes me feel productive and in control.</p><p>In a perfect world, I would have separate apps for notes, assignments, and schedules.&#160;The biggest benefit to me is having specialized tools for each task, which makes me feel focused and efficient.</p><p>In a perfect world, I would use a physical binder for all my study materials.&#160;The biggest benefit to me is having a tangible reference, which makes me feel organized and prepared.</p><p>In a perfect world, I would have a digital calendar to track my assignments.&#160;The biggest benefit to me is having a clear schedule, which makes me feel disciplined and aware.</p><p>Isabella is interested in seeing how users engage with a product without being physically present, so she can later evaluate these interactions.&#160;Which indirect observation method would be most suitable for Isabella?</p><p>Video recording</p><p>Usage analytics</p><p>Usability testing</p><p>Shadowing</p><p>Which metric assesses the likelihood that customers would recommend a product or service to others?</p><p>Net Promoter Score</p><p>Customer Effort Score</p><p>Customer Satisfaction Score</p><p>Customer Retention Rate</p><p>A manufacturing company carried out detailed customer observations and found that outdated machinery was creating major bottlenecks in their production line.&#160;The company decided to invest in new equipment.&#160;What are the expected outcomes of this decision?&#160;Select all that apply.</p><p>Production efficiency improved, leading to lower operational costs.</p><p>Employee satisfaction increased, as the upgraded equipment made tasks easier.</p><p>The new machinery caused a decline in product quality.</p><p>Operational costs rose without any corresponding improvements in efficiency.</p><p>A smart home security system is facing customer complaints.&#160;Users are experiencing issues with delayed notifications, difficulty in setting up the devices, poor video quality on security cameras, and limited compatibility with other smart home devices.&#160;These problems are leading to security concerns and some users considering switching to a different system.&#160;Which of these challenges would you consider the most critical to address first?</p><p>Improve the setup process to make it more user-friendly and straightforward.</p><p>Fix the delayed notifications to ensure users receive timely alerts.</p><p>Enhance the video quality on security cameras to provide clearer images.</p><p>Increase compatibility with other smart home devices to integrate seamlessly with existing systems.</p><p>When conducting empathy interviews, what should businesses aim to achieve?</p><p>To facilitate open discussions where customers can express their personal experiences and feelings</p><p>Analyzing customer feedback for patterns and trends</p><p>Measuring customer satisfaction with a rating scale</p><p>Gathering statistical data on customer preferences</p><p>Customers who are consistently delighted tend to remain engaged with the brand over time, creating opportunities for cross-selling and upselling.&#160;Which key aspect of the ideal customer state does this describe?</p><p>Customer loyalty and retention</p><p>Competitive advantage</p><p>Increased customer lifetime value</p><p>Enhanced brand reputation</p><p>Maria&#39;s team has begun creating a detailed digital mockup of their new app idea.&#160;They are focusing on the design, layout, and interactive features before moving on to more advanced stages.&#160;Which phase of the prototyping process is this?</p><p>Idea generation</p><p>Prototype develoment</p><p>User testing</p><p>Iteration</p><p>What makes brainstorming an effective tool for enhancing employee motivation and engagement?</p><p>It focuses on assigning tasks based on hierarchical positions rather than input from all team members.</p><p>It provides individuals with a chance to contribute to the problem-solving process, increasing enthusiasm and dedication.</p><p>It requires employees to work independently on separate tasks without collaboration.</p><p>It emphasizes performance evaluations during the idea generation phase.</p><p>Which section of idea documentation outlines the advantages for customers and how the idea stands out from existing options?</p><p>Problem statement</p><p>Idea des<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('20a379c0d5c5f7e6fc496f889bf994f4','intuit-design-for-delight-module-7','92a4f5cdddc7f69042b22cbdf20f300f','Module 7: Performing Customer Exp 1',7) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ca9c06f7462577c448de59a184fbbc61','intuit-design-for-delight-m7-l1-introduction-purpose-and-objectives','20a379c0d5c5f7e6fc496f889bf994f4','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi and welcome to this module on Performing Rapid Customer Experiments, Part 1!</p><p>Creating something new is hard! Whether that’s a new business, a new product, or a new service, the risk of failure is high. But what if you could test your boldest ideas without fear of failure? This module will look at the rapid experiment process. This allows you to quickly gather feedback and make adjustments before committing to big decisions.</p><p>In this module, you’ll dive into the process of running quick, low-risk experiments to gather feedback from real customers. You’ll learn how these rapid experiments allow for testing new ideas without heavy investment. This makes it possible for businesses to quickly see what works and what doesn’t. This approach helps teams adapt to customer needs and pivot when necessary, leading to better products and services.</p><p>A key part of rapid experiments is identifying and testing assumptions. You’ll explore how to recognize assumptions that could make or break your idea, and understand the importance of putting them to the test early. By the end of this module, you’ll be able to describe the rapid experimentation process, understand its purpose, and clearly define the assumptions that need to be validated before moving forward with a new product or solution.</p><p>Module Description</p><p>In this module, you will delve into the rapid experiment process, understanding its steps and significance in testing ideas quickly with customers.&#160;You will identify the purposes of conducting rapid customer experiments, such as validating assumptions and gathering feedback.&#160;You will learn to define and identify assumptions, and you will explore the importance of these assumptions in designing experiments.&#160;By the end of the module, you will be equipped to describe how assumptions shape experiments and why they are crucial for ensuring that your experiments are focused and effective.</p><p>Objectives</p><p>In this module, students will</p><p>Describe the rapid experiment process.</p><p>Identify the purposes of rapid customer experiments.</p><p>Define and identify assumptions.</p><p>Describe experiment assumptions and importance.</p><p>Polling Question</p><p>Assumptions are beliefs or ideas that have not yet been proven but are critical to the success of the hypothesis.&#160;What do you think is the most important way assumptions benefit the rapid experimentation process in D4D?</p><p>shaping the experiment&#39;s approach&#160;driving innovation&#160;defining customer priorities&#160;minimizing risks and costly mistakes</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Definition</p><p>statements or beliefs taken as true without proof in the context of a particular experiment or project</p><p>hypothesis</p><p>a supposition or proposed explanation made on the basis of limited evidence as a starting point for further investigation</p><p>agility</p><p>a business strategy that describes the ability of employees and companies to adapt to change quickly and easily</p><p>business model</p><p>a design for the successful operation of a business, identifying revenue sources, customer base, products, and details of financing</p><p>revenue stream</p><p>a particular means by which a company or individual generates income on an ongoing basis</p><p>assumptions</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>statements or beliefs taken as true without proof in the context of a particular experiment or project</p><p>Answers for question: 1</p><p>revenue stream</p><p>hypothesis</p><p>assumptions</p><p>business model</p><p>agility</p><p>2.</p><p>a supposition or proposed explanation made on the basis of limited evidence as a starting point for further investigation</p><p>Answers for question: 2</p><p>hypothesis</p><p>revenue stream</p><p>agility</p><p>assumptions</p><p>business model</p><p>3.</p><p>a business strategy that describes the ability of employees and companies to adapt to change quickly and easily</p><p>Answers for question: 3</p><p>business model</p><p>agility</p><p>hypothesis</p><p>assumptions</p><p>revenue stream</p><p>4.</p><p>a design for the successful operation of a business, identifying revenue sources, customer base, products, and details of financing</p><p>Answers for question: 4</p><p>hypothesis</p><p>business model</p><p>revenue stream</p><p>agility</p><p>assumptions</p><p>5.</p><p>a particular means by which a company or individual generates income on an ongoing basis</p><p>Answers for question: 5</p><p>agility</p><p>hypothesis</p><p>revenue stream</p><p>business model</p><p>assumptions</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1ded43e4cd06e885c5cc5c4d6656f25c','intuit-design-for-delight-m7-l2-lesson-1','20a379c0d5c5f7e6fc496f889bf994f4','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Intro to the Experiment Process</h3><p>Intro to the Experiment Process</p><p>Introduction to the Experiment Process</p><p>Experimentation is a fundamental aspect of innovation, allowing businesses and individuals to test hypotheses, validate assumptions, and refine ideas based on empirical evidence.&#160;The experiment process involves a systematic approach to exploring new concepts, gathering data, and making informed decisions.&#160;This approach minimizes risks, maximizes learning, and accelerates the development of successful products and services.</p><p>The Rapid Experiment Process</p><p>The rapid experiment process is a streamlined and accelerated version of traditional experimentation.&#160;It emphasizes speed, agility, and iterative learning, enabling teams to quickly test ideas and make necessary adjustments.&#160;This process is particularly valuable in dynamic and competitive environments where timely feedback and continuous improvement are crucial.</p><p>Intuit’s Design for Delight (D4D) framework integrates the rapid experiment process as a core component to drive customer-centric innovation.&#160;The D4D framework is designed to foster a culture of creativity, empathy, and iterative learning, ensuring that products and services meet and exceed customer expectations.&#160;Press the plus (+) in each section below to better understand how the rapid experiment process is implemented within the D4D framework.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>The Rapid Experiment Process in the Intuit Design for Delight (D4D) Framework Define the hypothesis Identify assumptions Design the experiment Conduct the experiment Analyze the results Iterate and refine Implement and scale</p><p>The hotspot points on the image are as follows:</p><p>Define the hypothesis</p><p>The first step in the rapid experiment process is to clearly define the hypothesis. A hypothesis is a testable statement that predicts a potential outcome based on certain assumptions. In the context of the D4D framework, the hypothesis should be customer-focused, addressing a specific need, pain point, or desire. For example, a hypothesis might be, “Introducing a budgeting feature will increase user engagement with our financial app.”</p><p>Identify assumptions</p><p>Once the hypothesis is defined, it’s essential to identify the underlying assumptions that need validation. Assumptions are beliefs or ideas that have not yet been proven but are critical to the success of the hypothesis. Identifying these assumptions helps prioritize what needs to be tested. In our budgeting feature example, assumptions might include, “Users want a budgeting tool integrated into their financial app” and “Users find our proposed budgeting tool easy to use.”</p><p>Design the experiment</p><p>The next step is to design a rapid experiment that will test the hypothesis and its underlying assumptions. This involves creating a minimal viable product (MVP) or prototype that captures the essence of the idea with minimal resources and effort. The experiment design should include clear metrics and criteria for success, ensuring that the results can be measured objectively. For the budgeting feature, this might involve creating a simple prototype of the tool and defining success metrics such as user engagement rates and feedback scores.</p><p>Conduct the experiment</p><p>With the experiment designed, the next step is to conduct it with real users. This involves deploying the MVP or prototype to a select group of customers and observing their interactions and feedback. It’s important to gather both qualitative and quantitative data to gain a comprehensive understanding of the user experience. In the D4D framework, customer empathy is crucial, so actively listening to users and understanding their perspectives is a key focus during this phase.</p><p>Analyze the results</p><p>After conducting the experiment, the data collected must be analyzed to determine whether the hypothesis is validated or needs adjustment. This involves comparing the results against the predefined success criteria and metrics. In the context of the budgeting feature, the analysis might reveal insights into how users interacted with the tool, what they liked or disliked, and whether the feature met their needs.</p><p>Iterate and refine</p><p>Based on the analysis, the next step is to iterate and refine the idea. If the hypothesis is validated, the team can move forward with further development and scaling of the feature. If not, the feedback gathered should inform adjustments to the hypothesis, assumptions, and experiment design. This iterative cycle of testing, learning, and refining ensures continuous improvement and alignment with customer needs.</p><p>Implement and scale</p><p>Once the idea has been thoroughly tested and refined through multiple iterations, it’s ready for full implementation and scaling. This involves integrating the feature into the broader product or service offering and launching it to the entire customer base. Ongoing monitoring and feedback collection are essential to ensure that the feature continues to meet customer expectations and drives desired outcomes.</p><p>Watch this video that illustrates the rapid experiment process in action.</p><p>Rapid experimentation is a quick, effective way to test ideas and improve a product or process. Let’s break down the steps using a simple business case—a startup looking to improve their meal kit service.</p><p>Step 1: Define the hypothesis. The team believes offering 15-minute meal recipes will attract more customers to their meal kit service.</p><p>Step 2: Identify assumptions. The team must confirm that customers really want faster meals, that shorter recipes can work with their ingredients, and that the meals will still taste great.</p><p>Step 3: Design the experiment. They create a special landing page on their website to promote 15-minute meal kits and offer it to a small group of customers for one week.</p><p>Step 4: Conduct the experiment. The team launches the test and observes how customers respond to the 15-minute meal option over the course of a week.</p><p>Step 5: Analyze the results. The data shows that while many customers were interested, some didn’t complete their orders. The team discusses why that might be.</p><p>Step 6: Iterate and refine. Based on the feedback, they simplify the recipe instructions, <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0b55d303c5095364bde8012fc4dc46e4','intuit-design-for-delight-m7-l3-lesson-2','20a379c0d5c5f7e6fc496f889bf994f4','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Purpose of Customer Experiment</h3><p>Purpose of Customer Experiment</p><p>The Purposes of Rapid Customer Experiments</p><p>In the innovation landscape, rapid customer experiments are vital for validating ideas and ensuring that products and services align with customer needs and expectations.&#160;The Intuit Design for Delight (D4D) framework leverages these experiments to drive customer-centric innovation and achieve impactful results.&#160;Building on the rapid experiment process, this section explores the key purposes of rapid customer experiments and their broader implications.</p><p>So, exactly what are these purposes?&#160;Rapid customer experiments are invaluable for:</p><p>Validating assumptions</p><p>Minimizing risk</p><p>Accelerating learning and innovation</p><p>Validating value propositions</p><p>Informing product development</p><p>Building a culture of agility and responsiveness</p><p>Read about these purposes and examples of each below.</p><p>Validating Assumptions</p><p>One of the primary purposes of rapid customer experiments is to validate assumptions. Assumptions are unproven beliefs that underpin a hypothesis. Validating these assumptions through quick and focused experiments helps ensure that the foundational ideas behind a product or service are sound. This is particularly important in the D4D framework, where customer empathy and understanding are prioritized. By validating assumptions early, teams can avoid costly mistakes and ensure that their solutions are genuinely addressing customer needs.</p><p>Example:&#160;A restaurant assumes that customers would appreciate a new menu item based on trending ingredients. They run a rapid experiment by offering the item as a special for a week and gathering customer feedback to validate this assumption.</p><p>Minimizing Risk</p><p>Rapid customer experiments help minimize risk by providing early insights into potential problems and challenges. By testing ideas quickly and gathering feedback, teams can identify and address issues before investing significant resources. This reduces the likelihood of failure and increases the chances of success.</p><p>Example:&#160;A retail store plans to introduce a new loyalty program. They conduct a rapid experiment with a small group of customers to test the program’s features and gather feedback on its attractiveness and usability, identifying potential pitfalls early.</p><p>Enhancing Customer Empathy</p><p>Rapid experiments involve direct interaction with customers, providing valuable insights into their behaviors, preferences, and pain points. This enhances the team&#39;s ability to create solutions that resonate with customers and deliver delightful experiences.</p><p>Example:&#160;A fashion brand developing a new clothing line conducts interviews and focus groups with their target demographic, gaining insights into their style preferences and the challenges they face when shopping for clothes. This empathy-driven approach leads to a more appealing and customer-focused collection.</p><p>Accelerating Learning and Innovation</p><p>Rapid customer experiments accelerate the learning process by providing quick feedback loops. This iterative approach allows teams to learn from each experiment, refine their ideas, and make data-driven decisions. The speed of these experiments fosters a culture of continuous improvement and innovation.</p><p>Example:&#160;A tech startup working on a new mobile game tests different game mechanics and features with small groups of users. Each iteration provides new insights, allowing them to refine the game and ensure it meets user expectations effectively.</p><p>Validating Value Propositions</p><p>A value proposition outlines the benefits that a product or service offers to customers. Rapid experiments help validate whether the proposed value proposition resonates with customers and meets their expectations. This ensures that the product or service delivers real value and stands out in the market.</p><p>Example:&#160;A subscription box service proposes a new monthly box theme. Through rapid experiments, they test whether customers perceive this theme as valuable and are willing to subscribe to it. Positive feedback validates the value proposition and informs further development.</p><p>Informing Product Development</p><p>Rapid customer experiments provide crucial data that informs product development decisions. By understanding what works and what doesn&#39;t, teams can prioritize features, allocate resources effectively, and develop products that are more likely to succeed in the market.</p><p>Example:&#160;An automotive company is developing a new car model with advanced safety features. Through rapid experiments, they test different features with focus groups and gather feedback. The insights gained help prioritize the most valuable features and streamline the development process.</p><p>Building a Culture of Agility and Responsiveness</p><p>The D4D framework encourages a culture of agility and responsiveness, where teams are adaptable and open to change. Rapid customer experiments reinforce this culture by emphasizing quick iterations, real-time feedback, and continuous learning. This agility allows teams to respond swiftly to customer needs and market changes.</p><p>Example:&#160;A healthcare provider exploring a new telehealth service conducts rapid experiments to gather feedback on different aspects of the service, such as appointment scheduling and video consultation quality. This agile approach ensures that the final service aligns with patient needs and adapts to changing healthcare dynamics.</p><p>Watch this video to better understand how rapid customer experiments fit into the D4D framework.</p><p>Hi and welcome to Lesson 2 for this module on Performing Rapid Customer Experiments, Part 1!</p><p>In today’s fast-paced market, businesses need to innovate quickly! And they want to ensure that their products meet customer needs. This is where the concept of rapid customer experiments fits perfectly into the Design for Delight framework. Experiments allow us to validate assumptions, lower risk, and accelerate innovation. Let&#39;s explore how this approach works and why it is so effective.</p><p>Rapid customer experiments are short, iterative tests that allow companies to validate their assumptions about a product or service. They can often do this before committing to development. By quickly putting a prototype in the hands of real c<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6d8fde0fa58ed9c4898e77f0e4964cd9','intuit-design-for-delight-m7-l4-lesson-3','20a379c0d5c5f7e6fc496f889bf994f4','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Assumptions in Rapid Experiments</h3><p>Assumptions in Rapid Experiments</p><p>Introduction to Assumptions in Rapid Experiments</p><p>Assumptions are a fundamental component of the rapid experiment process, playing a crucial role in testing and refining ideas efficiently.&#160;In the context of Intuit’s Design for Delight (D4D) framework, assumptions help guide the direction of experiments, ensuring that teams focus on validating the most critical elements of their ideas.&#160;Understanding and identifying these assumptions is essential not only for successful innovation at Intuit but also for a wide range of applications in various business and creative endeavors.</p><p>What Are Assumptions?</p><p>Assumptions are statements or beliefs taken as true without proof in the context of a particular experiment or project.&#160;They are the foundational ideas that shape how we approach problem-solving and innovation.&#160;In rapid experiments, assumptions underpin hypotheses about customer behavior, market needs, product functionality, and more.&#160;Identifying these assumptions early on is crucial because they represent the elements that, if proven incorrect, could invalidate the entire idea or approach.</p><p>Types of Assumptions</p><p>Press through the tabs below to read about various types of assumptions.</p><p>Customer Assumptions</p><p>Example:&#160;Assuming that customers will prefer a subscription model over a one-time purchase.</p><p>Market Assumptions</p><p>Expectations about the market size, growth, and competitive landscape.</p><p>Example: Assuming there is a significant unmet demand for a new type of eco-friendly packaging.</p><p>Product Assumptions</p><p>Hypotheses about the product’s functionality and features.</p><p>Example: Assuming that adding a new feature will improve user retention.</p><p>Technology Assumptions</p><p>Beliefs about the technical feasibility and performance of a product or service.</p><p>Example: Assuming that a new software update can be integrated seamlessly with existing systems.</p><p>Business Assumptions</p><p>Assumptions about the business model, revenue streams, and cost structures.</p><p>Example: Assuming that reducing prices will lead to a higher volume of sales sufficient to offset the lower margins.</p><p>Next Tab</p><p>Beliefs about what customers need, want, or value.</p><p>Now, let&#39;s take a look at how assumptions work throughout various stages.&#160;Watch the video below.</p><p>In the Design for Delight framework, assumptions play a crucial role at every stage. Assumptions are statements or beliefs taken as true without proof—until we test them.</p><p>Assumptions first show up during brainstorming, where the team generates a list of possible beliefs related to their project. These can be about the customer, the product, or the process. Here, this team is generating ideas for a new mobile app feature that allows users to schedule deliveries.</p><p>After brainstorming comes the prioritization stage. This is where assumptions are ranked based on their potential impact and how uncertain they are. This helps the team focus on what matters most.</p><p>After prioritizing, assumptions are transformed into a testable hypothesis. In this case, the team converts the assumption that users want flexible delivery options into something they can validate.</p><p>With the hypothesis set, the team moves on to experiment design, building an experiment specifically to test whether the assumption holds true.</p><p>Finally, in the data collection and analysis stage, the team determines whether their assumptions were correct. They review the data to see if users truly value flexible delivery options.</p><p>By working through each stage of the Design for Delight framework, assumptions are tested, refined, or even disproven. It’s through this process that teams move closer to solutions that truly delight their customers.</p><p>Identifying Assumptions in the D4D Framework</p><p>In the D4D framework, the process of identifying assumptions involves several steps.&#160;Press the plus (+) in the sections below to learn about each step.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Identifying Assumptions in the D4D Framework Brainstorming Prioritization Hypothesis Formation Experiment Design Data Collection &amp; Analysis</p><p>The hotspot points on the image are as follows:</p><p>Brainstorming</p><p>Generate a list of potential assumptions related to the idea or project. This can be done through team discussions, customer feedback, and market research.</p><p>Example: For a new financial app, the team brainstorms assumptions about user behavior, such as assuming users will frequently use a budget tracking feature.</p><p>Prioritization</p><p>Evaluate and prioritize assumptions based on their impact and the level of uncertainty. Focus on the assumptions that, if proven wrong, would have the most significant negative impact.</p><p>Example: The team identifies that the most critical assumption is that users will trust the app with their financial data, as this is foundational to the app’s success.</p><p>Hypothesis Formation</p><p>Convert prioritized assumptions into testable hypotheses. Clearly define what needs to be tested and what the expected outcome is.</p><p>Example: The hypothesis for the financial app might be, &quot;Users will trust the app with their financial data if it offers bank-level security features.&quot;</p><p>Experiment Design</p><p>Design experiments specifically to test these hypotheses. Ensure that the experiments are structured to provide clear and actionable insights.</p><p>Example: Conduct a pilot test of the app with a focus group, emphasizing the security features, and gather feedback on their trust levels.</p><p>Data Collection &amp; Analysis</p><p>Gather data from the experiments and analyze the results to determine whether the assumptions hold true or need to be re-evaluated.</p><p>Example: The team analyzes feedback from the pilot test to see if users express trust in the app’s security.</p><p>General Applications of Assumptions</p><p>While the D4D framework provides a structured approach to handling assumptions in rapid experiments, these principles can be broadly applied across different industries and contexts.&#160;Press each flashcard below to flip it over, then press NEXT to view the next flashcard.</p><p>In the following slideshow, use <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0f5f4c0b1c309b4b45e92e1ebe9f181c','intuit-design-for-delight-m7-l5-lesson-4','20a379c0d5c5f7e6fc496f889bf994f4','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Assumptions Review, Defining, Role</h3><p>Assumptions Review, Defining, Role</p><p>Review:&#160;Experiment Assumptions and Their Importance</p><p>In the realm of innovation and product development, assumptions play a pivotal role in shaping the direction and success of experiments.&#160;Within the context of the Intuit Design for Delight (D4D) framework, experiment assumptions are fundamental for testing ideas and refining them based on real-world insights.</p><p>Defining Experiment Assumptions</p><p>At the heart of any experimental process lie assumptions—hypotheses or educated guesses about what will happen under certain conditions.&#160;These assumptions can pertain to customer behavior, market dynamics, product functionality, or technical feasibility.&#160;By clearly defining and rigorously testing these assumptions, teams can validate their ideas, minimize risks, and ensure that they are on the right path toward creating valuable and viable solutions.</p><p>The Role of Assumptions in the D4D Framework</p><p>Within the Intuit Design for Delight framework, assumptions are a crucial component of the rapid experimentation process.&#160;The D4D framework emphasizes a deep understanding of customer needs, rapid prototyping, and iterative learning—all of which are driven by the process of making and testing assumptions.&#160;Press the plus (+) in each section below to learn more about assumptions throughout the various processes of the framework.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>The Role of Assumptions in the D4D Framework Customer Empathy Rapid Experimentation Iteration</p><p>The hotspot points on the image are as follows:</p><p>Customer Empathy</p><p>The process begins with developing a deep empathy for the customer. This involves making assumptions about their needs, pain points, and behaviors, which can then be tested through direct engagement and feedback.</p><p>Example: An assumption might be that small business owners need a simpler way to manage their finances. This can be tested by creating a prototype of a simplified accounting tool and gathering feedback from a sample of business owners.</p><p>Rapid Experimentation</p><p>The next step is to design quick, low-cost experiments to test the most critical assumptions. This involves creating prototypes, simulations, or mock-ups that can be used to gather data from real customers.</p><p>Example: A team might assume that a new mobile payment feature will increase transaction speed and customer satisfaction. They could test this by developing a basic version of the feature and observing its performance in a controlled environment.</p><p>Iteration</p><p>Based on the feedback and data collected from these experiments, the product or service is iterated upon. This iterative process helps refine the solution, ensuring it aligns closely with customer needs and expectations.</p><p>Example: If feedback indicates that customers find the new feature confusing, the team can make adjustments and test again, continually refining the solution until it meets customer needs effectively.</p><p>Importance of Experiment Assumptions</p><p>Let&#39;s recap some of the important reasons that assumptions are made during the rapid experiment phase.&#160;Watch the video below to better understand how identifying assumptions is critical.</p><p>Hi and welcome to Lesson 4 for this module on Performing Rapid Customer Experiments, Part 1!</p><p>The key theme of this module is identifying assumptions. We know it is a necessary part of innovation and product development. Assumptions are beliefs that we hold without concrete evidence. And while they offer a starting point, untested assumptions can lead to costly mistakes. Recognizing and validating assumptions early helps us 1) mitigate risk, 2) improve focus, 3) support informed decision-making, and 4) drive iterative improvement. In this video, let’s look at each one of those in greater detail:</p><p>Who likes throwing money away? Certainly no one I know, and definitely not any business. So, simply put, testing assumptions early helps teams save money. They avoid costly errors. Unchecked assumptions can lead to blind spots, causing teams to invest in the wrong direction. For example, a home appliance company might assume customers want a microwave with dozens of preset cooking options. However, they may learn later that most users primarily rely on just a few basic functions like reheat, defrost, and “Add 30 seconds”. So, if they test this assumption early through customer feedback or focus groups, the company can streamline the microwave’s features. In turn, this may lower manufacturing costs. The company can deliver a product that better meets customer needs, reducing the likelihood of poor sales.</p><p>Not all assumptions are equally important. In this process, we want to figure out which are most critical. This way teams can direct time and energy toward solving the key questions that could make or break a project. For instance, testing whether customers like a microwave’s user interface might be more crucial than checking technical performance at the beginning.</p><p>If we make decisions based on assumptions, these can often just be guesses or estimates. However, by testing assumptions first, you can gather real data to inform your choices. For example, the marketing team for our microwave product may assume their audience prefers video content. Instead of going all in on video production, they can run a quick test with a series of both simple videos and articles. So maybe they produce a few short-form, selfie-style videos showcasing features of the microwave. And they also write some how-to articles on their blog page. Then, they can track whether the videos or blogs get more views and likes. If written content performs better, they can pivot and focus on that moving forward. Testing assumptions ensures that decisions are based on evidence rather than guesswork.</p><p>Testing assumptions also supports iterative improvement. Teams can refine their ideas over time. After testing, teams can see which assumptions hold true and which don’t, enabling them to make adjustments that better meet customer needs. For example, if a microwave development team assumes users want numerous presetcooking options, but testing reveals that users prioritize quick buttons for common items like popcorn and nachos, they can <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e389adf1a6dfe9a7ae64bd9a6e5b43b1','intuit-design-for-delight-m7-l6-module-5-summary','20a379c0d5c5f7e6fc496f889bf994f4','Module 5 Summary','text',12,'<h2>Module 5 Summary</h2><section><h3>Module 5 Summary</h3><p>Module 5 Summary</p><p>Nice job!&#160;You have successfully completed this module on Performing Rapid Customer Experiments Part I.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Described the rapid experiment process.</p><p>Identified the purposes of rapid customer experiments.</p><p>Defined and identified assumptions.</p><p>Described experiment assumptions and importance.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6fb5bc84a7a4a9354d51f0396ad797ce','intuit-design-for-delight-m7-l7-module-5-test-prep','20a379c0d5c5f7e6fc496f889bf994f4','Module 5 Test Prep','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Performing Customer Exp 1. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,6,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('15db734babbbac0056997ce8ff2f8de1','intuit-design-for-delight-m7-l8-module-5-assignment','20a379c0d5c5f7e6fc496f889bf994f4','Module 5 Assignment','text',12,'<h2>Module 5 Assignment</h2><section><h3>Module 5 Assignment</h3><p>Module 5 Assignment</p><p>Intuit Design for Delight</p><p>Performing Rapid Customer Experiments Part I - Short Answer Assignment</p><p>Short answer assignment</p><p>Write a two-page, double-spaced paper that addresses the following questions and prompts. Use specific examples from the reading to support your answers and include reflections on the broader implications of these concepts.</p><p>1. Validating Assumptions:</p><p>Explain the importance of validating assumptions in the context of the D4D framework.</p><p>How does validating assumptions help in creating customer-centric solutions?</p><p>2. Minimizing Risk:</p><p>Why is it crucial to identify potential problems and challenges early in the development process?</p><p>3. Enhancing Customer Empathy:</p><p>Discuss the role of customer empathy in the D4D framework.</p><p>4. Accelerating Learning and Innovation:</p><p>Explain how rapid customer experiments accelerate the learning process and foster innovation.</p><p>5. Validating Value Propositions:</p><p>Define what a value proposition is and its significance in product development.</p><p>6. Informing Product Development:</p><p>Describe the role of rapid customer experiments in informing product development decisions.</p><p>How do these experiments help prioritize features and allocate resources effectively?</p><p>7. Building a Culture of Agility and Responsiveness:</p><p>Why is it important for teams to be adaptable and open to change?</p><p>Review the rubric below to determine how you will be graded.</p><p>Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9d3271018bdc7341a692aae3cab0b5b1','intuit-design-for-delight-m7-l9-module-5-project','20a379c0d5c5f7e6fc496f889bf994f4','Module 5 Project','text',12,'<h2>Module 5 Project</h2><section><h3>Module 5 Project</h3><p>Module 5 Project</p><p>Intuit Design for Delight</p><p>Performing Rapid Customer Experiments Part I - Project</p><p>Project</p><p>For this project, you will create an infographic using whatever method you prefer. Just be sure to use a combination of text and media to make your infographic engaging and visually appealing.</p><p>First, read the business scenario below:</p><p>Business Scenario:&#160;Green Bean Caf&#233;, a small but popular coffee shop in a busy downtown area, wants to introduce a new loyalty program to increase customer retention and boost sales. The caf&#233; has a regular customer base, but they believe that a well-designed loyalty program can encourage more frequent visits and higher spending per visit. The owner and the team decide to implement the Intuit Design for Delight (D4D) framework to develop and test their new loyalty program through rapid customer experiments.</p><p>Your infographic will outline each of the seven steps in the D4D rapid experiment process. The steps are listed below. Note that the hypothesis has already been defined:</p><p>Define the hypothesis:&#160;Green Bean Caf&#233; hypothesizes that &quot;Introducing a digital loyalty program that offers a free coffee after every ten purchases will increase customer visit frequency by 20% within the next two months.&quot;</p><p>Identify assumptions - Identify three key assumptions to validate this hypothesis</p><p>Design the experiment - Describe a simple experiment to test the hypothesis</p><p>Conduct the experiment - Explain how a rapid experiment might be conducted to test this hypothesis</p><p>Analyze the results - Describe how the results of the experiment would be collected and analyzed</p><p>Iterate and refine - Provide 2-3 examples of ways the initial hypothesis could be revised based on potential feedback and analysis of results</p><p>Implement and scale - Briefly describe how the final program will be rolled out using the lessons learned from the experiment</p><p>Since you&#39;re not conducting an actual experiment, you can get creative with how you choose to accomplish your goals and what results you encounter. Just be sure that the information in each of the steps aligns well with the initial hypothesis and what you uncover along the way.</p><p>Review the rubric below to determine how you will be graded.</p><p>Performing Rapid Customer Experiments Part I Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Content</p><p>8 points The content shows a strong understanding of the steps in the D4D rapid experiment process. Each step is explained well and the actions taken during the step align well with the objectives of that step.</p><p>7-4 points The content shows a fair understanding of the steps in the D4D rapid experiment process. Each step is explained relatively well, and the actions taken during the step mostly align with the objectives of that step.</p><p>3-0 points The content shows little to no understanding of the steps in the D4D rapid experiment process.</p><p>8</p><p>Infographic</p><p>8 points The infographic is well-organized, engaging, and visually appealing.</p><p>7-6 points The infographic is organized and fairly engaging.</p><p>5-0 points The infographic is not well-organized, engaging, or visually appealing.</p><p>8</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Formatting</p><p>2 points Project is formatted according to stated instructions.</p><p>0 points Project is not formatted according to stated instructions.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('01b06bb5ce1339efca5505bf7d2c4657','intuit-design-for-delight-m7-l10-module-5-quiz','20a379c0d5c5f7e6fc496f889bf994f4','Module 5 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Performing Customer Exp 1. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,9,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('c3a1d4103c0d07f3bed9e3e7fe0c2508','intuit-design-for-delight-module-8','92a4f5cdddc7f69042b22cbdf20f300f','Module 8: Performing Customer Exp 2',8) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('56b59b2ea744565c247f5e5fa00fa507','intuit-design-for-delight-m8-l1-introduction-purpose-and-objectives','c3a1d4103c0d07f3bed9e3e7fe0c2508','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi and welcome to this module on Performing Rapid Customer Experiments Part 2!</p><p>When developing new ideas, not all assumptions carry the same weight. Some assumptions are crucial, while others are less certain or unproven. In this module, you’ll learn how to sift through sets of assumptions to identify the most crucial ones. These are the ones that can make or break your idea. You&#39;ll also discover how to spot the least-proven assumptions and recognize the &quot;Leap of Faith&quot; assumptions that require the biggest stretch of the imagination to be true. By focusing on these key insights regarding assumptions, you&#39;ll be better prepared to shape successful experiments.</p><p>But knowing which assumptions to test is only part of the process. We’ll also look at the components of a well-designed experiment and how to craft a solid hypothesis statement. By the end of this module, you’ll be prepared to create experiments that provide clear answers, as well as hypothesis statements that guide your tests with precision. Armed with these skills, you’ll know exactly what to test, how to test it, and how to make decisions based on the results.</p><p>Module Description</p><p>In this module, you will learn how to evaluate a set of assumptions by identifying the most crucial, the least-proven, and the Leap of Faith assumptions that carry the most risk.&#160;You will explore the essential components of a well-designed experiment and understand what makes a strong hypothesis statement.&#160;You will also gain practical experience by creating or completing hypothesis statements based on given scenarios, ensuring you can effectively apply these concepts to real-world situations.</p><p>Objectives</p><p>In this module, students will</p><p>Given a set of assumptions, identify the most crucial assumptions.</p><p>Given a set of assumptions, identify the least-proven assumptions.</p><p>Given a set of assumptions, identify the Leap of Faith assumptions.</p><p>Identify the components of a good experiment.</p><p>Identify the components of a hypothesis statement.</p><p>Given a situation, create or complete a hypothesis statement.</p><p>Polling Question</p><p>Which part of the rapid experiment process do you think is the most critical?</p><p>defining the hypothesis&#160;identifying assumptions&#160;conducting the experiment&#160;analyzing the results&#160;iterating and refining</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Definition</p><p>assumptions that are fundamental to the success or failure of a product or service</p><p>crucial assumptions</p><p>assumptions that are speculative and require careful attention as they represent the highest level of uncertainty and risk</p><p>hypothesis statement</p><p>high-stakes assumptions that underpin the core of a business idea or product development strategy</p><p>least-proven assumptions</p><p>a testable prediction or educated guess about the relationship between two or more variables, which can be evaluated through experimentation or observation</p><p>Leap of Faith assumptions</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>assumptions that are fundamental to the success or failure of a product or service</p><p>Answers for question: 1</p><p>least-proven assumptions</p><p>crucial assumptions</p><p>hypothesis statement</p><p>Leap of Faith assumptions</p><p>2.</p><p>assumptions that are speculative and require careful attention as they represent the highest level of uncertainty and risk</p><p>Answers for question: 2</p><p>Leap of Faith assumptions</p><p>least-proven assumptions</p><p>crucial assumptions</p><p>hypothesis statement</p><p>3.</p><p>high-stakes assumptions that underpin the core of a business idea or product development strategy</p><p>Answers for question: 3</p><p>hypothesis statement</p><p>crucial assumptions</p><p>least-proven assumptions</p><p>Leap of Faith assumptions</p><p>4.</p><p>a testable prediction or educated guess about the relationship between two or more variables, which can be evaluated through experimentation or observation</p><p>Answers for question: 4</p><p>Leap of Faith assumptions</p><p>least-proven assumptions</p><p>crucial assumptions</p><p>hypothesis statement</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c86b5307820bd46357d688c195e758b4','intuit-design-for-delight-m8-l2-lesson-1','c3a1d4103c0d07f3bed9e3e7fe0c2508','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Understanding Crucial Assumptions</h3><p>Understanding Crucial Assumptions</p><p>As you will recall, assumptions are the unproven beliefs that form the foundation of our hypotheses and ideas.&#160;The ability to identify and validate these assumptions is essential to creating products and services that truly meet customer needs.&#160;This section will explore the concept of crucial assumptions, explain their significance within the Intuit Design for Delight (D4D) framework, and provide practical guidance on how to discern the most critical assumptions from a broader set.</p><p>Review:&#160;What Are Assumptions?</p><p>Assumptions are statements or beliefs we accept as true without proof.&#160;In the context of product development and innovation, assumptions often underpin the hypotheses we formulate about customer needs, behaviors, and preferences.&#160;For example, when developing a new app feature, an assumption might be that users will find it beneficial and easy to use.</p><p>Watch this video to learn about crucial assumptions.</p><p>Hi and welcome to Lesson 1 for this module on Performing Rapid Customer Experiments Part 2!</p><p>Assumptions are the unproven beliefs we use as the foundation for our ideas and hypotheses. Whether we’re designing a product or service, we make assumptions about what people want. However, some assumptions are more important than others. This is especially true when they have a direct impact on the success or failure of a product. These are called crucial assumptions. By honing in on these crucial assumptions early on, companies can hopefully avoid costly mistakes, use resources wisely, and ensure their ideas are going to work.</p><p>Let’s take a look at an example of crucial assumptions by considering a hypothetical physical product: customizable LED shoes.</p><p>Let’s say you are the head of a company developing customizable LED shoes targeted at teenagers. These shoes feature changeable LED colors and patterns for personalization, along with a built-in fitness tracker to monitor steps and activity levels. Your team has developed a hypothesis: “Teens will love customizing their shoes with LED lights and use the fitness tracker, making the product a must-have fashion statement.”</p><p>However, for this hypothesis to succeed, several crucial assumptions must be true. Let’s explore these assumptions and their potential impact on the product’s success.</p><p>The First Critical Assumption: Teens want customizable LED lights on their shoes.</p><p>The company assumes that teenagers care about expressing their personal style and would find customizable LED lights appealing. If this assumption is wrong and teens don’t value LED customization, the core feature of the product may not be enough to drive sales.</p><p>What would be an appropriate test here? The company could survey teens to assess their interest in LED customization features and their willingness to pay for this.</p><p>Second Critical Assumption: The shoes are comfortable and durable.</p><p>It’s assumed that adding LED lights and technology won’t compromise the comfort or durability of the shoes. If the shoes are uncomfortable or easily damaged, even the coolest LED patterns won’t make up for a poor wearing experience.</p><p>A possible test here would be to have teens wear and test prototypes, gathering feedback on comfort, fit, and durability.</p><p>Third: The fitness tracker adds value to the product.</p><p>The company assumes that teens care about tracking their steps and activity levels. If they don’t, the fitness tracker could be seen as an unnecessary addition that increases the price without providing value.</p><p>How would they test this assumption? They could conduct focus groups to determine whether teens see fitness tracking as a valuable feature in their footwear.</p><p>And our final critical assumption is: the battery life is sufficient for daily use.</p><p>It’s assumed that the LEDs and fitness tracker won’t drain the shoe’s battery too quickly, and that the charging process will be convenient. If the battery runs out quickly or charging is too much hassle, teens may lose interest in wearing the shoes regularly.</p><p>For this assumption, prototype testing should measure battery life under normal use and gather feedback on charging ease.</p><p>By reviewing and testing these crucial assumptions, the company can avoid costly mistakes and focus on features that matter to its target audience. For instance, if teens aren’t excited about the LED lights, the company can adjust the design before committing to production. Testing for comfort and usability ensures that the product isn’t just flashy, but also practical for everyday use.</p><p>In conclusion, testing crucial assumptions early in the development process is necessary for creating successful products. Before committing to an idea, ask: What assumptions am I making, and how can I validate them? By questioning these unproven beliefs, companies can create better solutions, avoid risks, and meet the needs of their target audience.</p><p>Identifying Crucial Assumptions</p><p>Not all assumptions carry the same weight.&#160;Crucial assumptions are those that are fundamental to the success or failure of a product or service.&#160;They are the assumptions that, if proven incorrect, could invalidate the entire hypothesis.&#160;Identifying these crucial assumptions early on is vital for focusing efforts on the most important areas and mitigating risks.</p><p>Why Crucial Assumptions Are Critical</p><p>Crucial assumptions are critical because they directly impact the feasibility and viability of an idea.&#160;By focusing on validating these assumptions, teams can avoid costly mistakes, optimize resources, and ensure that their solutions are truly addressing customer needs.&#160;In the D4D framework, this practice of validating crucial assumptions is integral to fostering customer empathy, minimizing risk, and accelerating innovation.&#160;Press the plus (+) in each section below to identify the steps to identify crucial assumptions.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Identifying Crucial Assumptions Define the hypothesis List all assumptions Assess the impact Prioritize crucial assumptions</p><p>The hotspot points on the image are as follows:</p><p>Define the hypothesis</p><p>Start with a clear, customer-focused hypothesis. For example, “Intr<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('89687bba575dab6597150e6c4441fb84','intuit-design-for-delight-m8-l3-lesson-2','c3a1d4103c0d07f3bed9e3e7fe0c2508','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Lease Proven Assumption</h3><p>Lease Proven Assumption</p><p>Understanding Least-Proven Assumptions</p><p>You already have a sense that assumptions guide the direction of experiments and development processes.&#160;However, not all assumptions are created equal.&#160;Some are based on extensive research and past experience, while others are more speculative.&#160;These speculative or least-proven assumptions require careful attention as they represent the highest level of uncertainty and risk.&#160;This section will explore the concept of least-proven assumptions, their role in the Intuit Design for Delight (D4D) framework, and how to identify and address them effectively.</p><p>The Role of Least-Proven Assumptions in the Intuit Design for Delight (D4D) Framework</p><p>The D4D framework emphasizes a customer-centric approach to innovation, leveraging rapid experiments to validate assumptions and ensure alignment with customer needs.&#160;Within this framework, least-proven assumptions are critical as they represent areas of high risk and uncertainty.&#160;By identifying and testing these assumptions early, teams can mitigate potential issues, refine their hypotheses, and ensure that their solutions are viable and desirable.</p><p>Why Least-Proven Assumptions Are Important</p><p>Least-proven assumptions are important because they highlight areas where the most learning is needed.&#160;By focusing on these assumptions, teams can uncover insights that would otherwise remain hidden, leading to more robust and customer-centric solutions.&#160;Ignoring least-proven assumptions can result in wasted resources, misaligned products, and ultimately, failure to meet customer expectations.&#160;Press the plus (+) in each section below to review the steps to identify least-proven assumptions.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Identifying Least Proven Assumptions Define the hypothesis List all assumptions Evaluate evidence Prioritize least-proven assumptions</p><p>The hotspot points on the image are as follows:</p><p>Define the hypothesis</p><p>Begin with a clear, testable hypothesis. For example, “Introducing a social sharing feature will increase user engagement with our app.”</p><p>Least all assumptions</p><p>Identify all underlying assumptions related to the hypothesis. These might include assumptions about customer behaviors, technical feasibility, market conditions, and more.</p><p>Evaluate evidence</p><p>Assess the level of evidence supporting each assumption. Consider factors such as past experiences, market research, and customer feedback.</p><p>Prioritize least-proven assumptions</p><p>Identify assumptions with the least amount of evidence. These are your least-proven assumptions that require immediate testing to validate or refute.</p><p>Before we look at an example, let&#39;s review least-proven assumptions to better understand the value they bring to the rapid experiment process.&#160;Watch the video below.</p><p>Hi and welcome to Lesson 2 for this module on Performing Rapid Customer Experiments Part 2!</p><p>Let’s continue learning about assumptions! Crucial assumptions are those that have a direct impact on the success or failure of a product. Another type of assumption, the least-proven assumption, is equally important, but what does it mean? The least-proven assumption highlights areas where the most learning is needed. They provide valuable insights that teams might otherwise overlook if they only focus on the obvious assumptions. Exploring these speculative assumptions allows us to gain a deeper understanding of what customers truly want.</p><p>Least-proven assumptions are important because they are often speculative. This means they haven’t been validated through research or data. Doesn’t that sound like they should be less urgent than critical assumptions? Actually, no, because they represent areas where teams have the most to learn. In many cases, these assumptions reflect beliefs about user behavior or preferences that haven’t been fully explored. So because of that, testing them can uncover unexpected insights.</p><p>For example, when a company makes a least-proven assumption, such as “users will share our product on social media,” they are speculating about user behavior without solid data to support it.</p><p>Although speculative assumptions may not seem as important as critical ones, they provide valuable insights that can help teams improve their product. Focusing solely on critical assumptions could lead to missed opportunities for innovation or better user experiences. Exploring these less-proven assumptions helps teams understand what drives user behavior and how they can improve their product in unexpected ways.</p><p>Consider a company developing a smart thermostat that learns users’ temperature preferences over time. They assume that adding a feature allowing users to create custom temperature “zones” for different rooms will increase the product’s appeal. While there’s research to suggest that people want more control over their home environments, there are several least-proven assumptions that need to be explored:</p><p>Users will take the time to set up multiple temperature zones.</p><p>Users will find the zoning feature easy to use and beneficial.</p><p>And 3. Users will want to adjust their heating and cooling preferences often enough to make zoning worthwhile.</p><p>Each of these assumptions is speculative and could be incorrect. However, testing these least-proven assumptions could provide valuable insights. Perhaps users don’t want to manage multiple zones but do want more simplified control over general home temperatures. Learning this would help the company refine the product to meet real user needs, even if the zoning feature itself isn’t as popular as expected.</p><p>While least-proven assumptions are speculative and less urgent than critical ones, we can’t forget about them! This is because they uncover new insights and help us understand user behavior more deeply. So, with any assumption, crucial or speculative, we prove them true or false by testing them. This way, teams can learn more about what users truly want and how to shape products in ways that drive satisfaction. Whether it’s a smart thermostat’s zoning feature, or any other product, testing and exploring these least-proven assumptions can lead to better products and more informed decis<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('880bec9e7bab0d1fb2448ccce5035a71','intuit-design-for-delight-m8-l4-lesson-3','c3a1d4103c0d07f3bed9e3e7fe0c2508','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Leap of Faith Assumptions</h3><p>Leap of Faith Assumptions</p><p>Understanding Leap of Faith Assumptions</p><p>Leap of Faith assumptions are high-stakes beliefs that underpin the core of a business idea or product development strategy.&#160;These assumptions are often unproven and speculative, yet they are critical to the success of the venture.&#160;If a Leap of Faith assumption turns out to be false, it could invalidate the entire business model or product concept.</p><p>The Role of Leap of Faith Assumptions in the Intuit Design for Delight (D4D) Framework</p><p>The D4D framework emphasizes a customer-centric approach to innovation, leveraging rapid experiments to validate assumptions and ensure alignment with customer needs.&#160;Within this framework, Leap of Faith assumptions are essential as they represent the riskiest aspects of the hypothesis.&#160;By identifying and testing these assumptions early, teams can mitigate potential failures, refine their strategies, and ensure that their solutions are both viable and desirable.</p><p>Why Leap of Faith Assumptions Are Important</p><p>Leap of Faith assumptions are important because they challenge the fundamental premises of a project.&#160;Addressing these assumptions early allows teams to identify and correct flaws in their thinking before investing significant resources.&#160;This proactive approach prevents costly mistakes and ensures that the development process is grounded in reality.&#160;Press the plus (+) in each section below to review the steps to identify Leap of Faith assumptions.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Identifying Leap of Faith Assumptions Define the hypothesis List all assumptions Evaluate impact and evidence Prioritize Leap of Faith assumptions</p><p>The hotspot points on the image are as follows:</p><p>Define the hypothesis</p><p>Start with a clear, testable hypothesis. For example, “Integrating a virtual reality feature will increase user engagement with our educational platform.”</p><p>List all assumptions</p><p>Identify all underlying assumptions related to the hypothesis. These might include assumptions about customer behavior, technical feasibility, market demand, and more.</p><p>Evaluate impact and evidence</p><p>Assess the impact of each assumption on the success of the project and the level of evidence supporting it. Leap of Faith assumptions typically have a high impact and low evidence.</p><p>Prioritize Leap of Faith assumptions</p><p>Identify assumptions that, if proven false, would significantly jeopardize the project. These are your Leap of Faith assumptions that require immediate validation.</p><p>Example Scenario and Activity</p><p>Read the scenario below and then read the list of assumptions.&#160;See if you can identify the assumptions that could be considered the Leap of Faith assumptions for this hypothesis based on what you&#39;ve learned.</p><p>Scenario:&#160;A startup is developing a new online learning platform that uses artificial intelligence to create personalized learning paths for students.&#160;The team has developed a hypothesis:&#160;“Using AI to personalize learning will significantly improve student outcomes and engagement.”</p><p>List of Assumptions:</p><p>Students prefer personalized learning paths over traditional methods.</p><p>AI can accurately assess students&#39; learning needs and adapt accordingly.</p><p>Teachers are willing to integrate AI-driven tools into their teaching methods.</p><p>Schools have the necessary infrastructure to support AI technology.</p><p>Personalized learning will lead to better academic outcomes.</p><p>The platform is user-friendly for both students and teachers.</p><p>Parents are supportive of AI-driven education tools.</p><p>The cost of implementing AI is justifiable for schools.</p><p>After you have read the scenario and considered the assumptions, expand the section below to reveal the least-proven assumptions for the hypothesis.&#160;This is not a graded assignment.</p><p>Leap of Faith Assumptions</p><p>The following are the Leap of Faith assumptions for the hypothesis in the scenario:</p><p>AI can accurately assess students&#39; learning needs and adapt accordingly:</p><p>This is a core assumption that underpins the entire hypothesis. If AI cannot accurately personalize learning, the platform&#39;s value proposition falls apart.</p><p>Personalized learning will lead to better academic outcomes:</p><p>The hypothesis hinges on the idea that personalization improves outcomes. This assumption needs strong validation to justify the platform&#39;s approach.</p><p>Teachers are willing to integrate AI-driven tools into their teaching methods:</p><p>Teacher adoption is critical for the platform’s success. If teachers are resistant, the platform cannot be effectively implemented.</p><p>Students prefer personalized learning paths over traditional methods:</p><p>Student preference is key to engagement. Without their buy-in, the platform cannot achieve its goals.</p><p>Identifying and validating Leap of Faith assumptions is a critical component of successful innovation within the Intuit Design for Delight framework.&#160;These assumptions represent the riskiest aspects of a hypothesis and addressing them early helps prevent costly mistakes and aligns the development process with reality.&#160;This practice is essential not only within Intuit but also across various industries and business scenarios, making it a fundamental skill for any innovator or product developer.&#160;By mastering the identification and testing of Leap of Faith assumptions, teams can navigate uncertainty more effectively and create solutions that truly resonate with customers.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e89df38e226fdae82bb01b2387d5948a','intuit-design-for-delight-m8-l5-lesson-4','c3a1d4103c0d07f3bed9e3e7fe0c2508','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Components of Good Experiment</h3><p>Components of Good Experiment</p><p>The Components of a Good Experiment</p><p>Experiments can be conducted in any number of environments.&#160;If you have ever taken a science course, you have probably completed a few yourself.&#160;But you have probably also completed many other types of experiments without even realizing it.&#160;Experiments, after all, are just ways to determine what works and what doesn&#39;t.&#160;A well-designed experiment can provide all kinds of useful information.&#160;In this section, we&#39;ll focus on experiments that happen during product development as a means of understanding customer needs, validating assumptions, and creating solutions that delight users.&#160;You know by now that the D4D framework emphasizes customer-centric innovation.&#160;Experiments are a key tool in this process.</p><p>Watch this video to learn about the components of a good experiment.</p><p>Read about eight key components of a good experiment below.&#160;Press the plus (+) in each box to learn more.</p><p>Experiments are key to understanding what works and what doesn’t. Let’s look at 8 steps this team takes to run a successful experiment to improve their coffee shop’s mobile ordering app.</p><p>Step 1: Define the hypothesis. The team believes offering 15-minute meal recipes will attract more customers to their meal kit service.</p><p>Step 2: They identify their assumptions—like customers valuing speed over customization and the app being easy to use.</p><p>Step 3: Define success metrics. The team sets measurable goals, like increasing mobile orders and reducing wait times.</p><p>Step 4: They then create a simple prototype with a new ‘Fast Pick-Up’ option for testing.</p><p>Step 5: Identify the target user group. The team focuses on busy professionals who need quick service.</p><p>Step 6: They also create a data collection plan to track app usage and gather feedback.</p><p>Step 7: Take an iterative approach. Early data reveals room for improvement, so the team refines the app.</p><p>Step 8: They then interact directly with customers, empathizing with their needs and gathering insights.</p><p>By following a structured experiment, the team refines their product, leading to real improvements that delight their customers.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Components of a Good Experiment Clear Hypothesis Identified Assumptions Defined Success Metrics Prototype or MVP</p><p>The hotspot points on the image are as follows:</p><p>Clear hypothesis</p><p>A well-defined hypothesis is the foundation of a good experiment. It is a testable statement that predicts a specific outcome based on certain assumptions. The hypothesis should be customer-focused, addressing a need, pain point, or desire. For example, “Introducing a budgeting feature will increase user engagement with our financial app.”</p><p>Identified assumptions</p><p>Before conducting an experiment, it&#39;s essential to identify the assumptions underlying the hypothesis. These are unproven beliefs that must be validated to ensure the hypothesis is sound. For instance, assumptions might include, “Users want a budgeting tool integrated into their financial app” and “Users find our proposed budgeting tool easy to use.”</p><p>Defined success metrics</p><p>Success metrics are specific, measurable criteria that determine whether the experiment has achieved its goals. These metrics should align with the hypothesis and provide clear benchmarks for evaluation. In the budgeting feature example, success metrics could include user engagement rates, time spent on the feature, and user satisfaction scores.</p><p>Prototype or MVP</p><p>A good experiment uses a minimum viable product (MVP) or prototype to test the hypothesis with minimal resources. The MVP should capture the essence of the idea without extensive development, allowing for quick testing and iteration. For the budgeting feature, this might involve a basic version of the tool integrated into the app for initial user testing.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Components of a Good Experiment Targeted User Group Data Collection Plan Iterative Approach Customer Empathy</p><p>The hotspot points on the image are as follows:</p><p>Targeted user group</p><p>Identifying and engaging the right user group is crucial for obtaining relevant feedback. The selected users should represent the target audience for the product or feature being tested. In our example, the target group might include existing users of the financial app who actively use budgeting tools.</p><p>Data collection plan</p><p>A comprehensive data collection plan outlines how qualitative and quantitative data will be gathered during the experiment. This plan should include methods such as surveys, interviews, usage analytics, and feedback forms. Collecting diverse data types ensures a holistic understanding of user experiences.</p><p>Iterative approach</p><p>A good experiment adopts an iterative approach, allowing for continuous learning and refinement. After each experiment, the results should inform the next steps, leading to successive iterations that progressively improve the product. This aligns with the D4D framework’s emphasis on rapid experiments and iterative development.</p><p>Customer empathy</p><p>Understanding and empathizing with customers is a core component of the D4D framework. Good experiments involve direct interaction with customers, enabling teams to gain insights into their behaviors, preferences, and pain points. This empathy-driven approach ensures that solutions are tailored to real customer needs.</p><p>Tying It All Together:&#160;Intuit D4D Framework</p><p>The Intuit Design for Delight framework places a strong emphasis on customer-centric innovation through rapid experiments.&#160;By incorporating the components of a good experiment, product development teams can ensure that their efforts are aligned with customer needs and driven by data-driven insights.&#160;The D4D framework encourages teams to:</p><p>Define clear, customer-focused hypotheses.</p><p>Identify and validate critical assumptions.</p><p>Use MVPs to test ideas quickly and iteratively.</p><p>Engage with customers directly to build empathy and gather comprehensive feedback.</p><p>Conducting good experiments is <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('336a61ed4f7196b9a89ae7ea33fbf321','intuit-design-for-delight-m8-l6-lesson-5','c3a1d4103c0d07f3bed9e3e7fe0c2508','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Components of Hypothesis Statement</h3><p>Components of Hypothesis Statement</p><p>Understanding the Components of a Hypothesis Statement</p><p>A well-constructed hypothesis statement is essential for conducting meaningful experiments and deriving valuable insights, particularly in product development and innovation frameworks like Intuit’s Design for Delight (D4D).&#160;A good hypothesis statement provides a clear, testable prediction that guides the experimental process.&#160;This section breaks down the components of a hypothesis statement.</p><p>The components of hypothesis statements are on the flashcards below.&#160;Flip over each flashcard by pressing it.&#160;Under each component, you can review examples of what that component may look like as part of a hypothesis statement.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Specificity</p><p>SpecificityA hypothesis should be specific, clearly defining the expected relationship between variables and the conditions under which the relationship is tested.&#160;It should precisely articulate what is being tested and what outcomes are anticipated.</p><p>⟳ Flip Card</p><p>Flashcard&#160;1&#160;of&#160;1</p><p>Flashcard Transcript</p><p>Examples:</p><p>Good:&#160;&quot;Introducing a rewards program will increase customer loyalty by 20% over six months.&quot;</p><p>Poor:&#160;&quot;Introducing a rewards program will improve customer loyalty.&quot;</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Testability</p><p>TestabilityThe hypothesis must be testable, meaning it can be supported or refuted through experimentation and observation.&#160;This requires that the hypothesis is framed in a way that allows for measurable outcomes.</p><p>⟳ Flip Card</p><p>Flashcard&#160;1&#160;of&#160;1</p><p>Flashcard Transcript</p><p>Examples:</p><p>Good:&#160;&quot;Implementing a new navigation menu will reduce user search time by 30 seconds on average.&quot;</p><p>Poor:&#160;&quot;Implementing a new navigation menu will make the website better.&quot;</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Relevance</p><p>RelevanceThe hypothesis should address a specific problem or question that is relevant to the goals of the experiment or project.&#160;It should be aligned with the overarching objectives of the product or business.</p><p>⟳ Flip Card</p><p>Flashcard&#160;1&#160;of&#160;1</p><p>Flashcard Transcript</p><p>Examples:</p><p>Good:&#160;&quot;Offering personalized workout plans will increase user retention in the fitness app by 15% over three months.&quot;</p><p>Poor:&#160;&quot;Offering personalized workout plans will be interesting to users.&quot;</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Clarity</p><p>ClarityThe hypothesis should be clearly articulated and easy to understand.&#160;It should avoid ambiguity, ensuring that all stakeholders have a consistent understanding of what is being tested.</p><p>⟳ Flip Card</p><p>Flashcard&#160;1&#160;of&#160;1</p><p>Flashcard Transcript</p><p>Examples:</p><p>Good:&#160;&quot;Reducing the price of our subscription service by 10% will increase the number of new subscribers by 25% in the next quarter.&quot;</p><p>Poor:&#160;&quot;Reducing the price of our subscription service will attract more customers.&quot;</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Measurability</p><p>MeasurabilityThe hypothesis must include specific metrics or criteria that can be measured to evaluate the outcomes.&#160;This often involves quantifiable variables that can be tracked and analyzed.</p><p>⟳ Flip Card</p><p>Flashcard&#160;1&#160;of&#160;1</p><p>Flashcard Transcript</p><p>Example:</p><p>Good:&#160;&quot;Adding a chatbot feature will reduce customer service response times by 40% within the first three months.&quot;</p><p>Poor:&#160;&quot;Adding a chatbot feature will improve customer service.&quot;</p><p>Let&#39;s review each of these components.&#160;Watch the video below to see how they all come together to form a cohesive hypothesis statement.</p><p>close</p><p>A strong hypothesis statement is the foundation of any successful experiment. Let’s break down the key components of a good hypothesis—using an example at a clothing brand trying to increase website visits and sales by sending out personalized emails to customers.</p><p>First, a good hypothesis needs to be specific. It clearly defines the relationship between variables. In this case, personalized email offers are expected to influence customer website visits. It must also be testable—meaning it can be supported or refuted through experimentation. Here, the team sets a measurable outcome: increasing website visits by 10%.</p><p>Relevance is key. A hypothesis should address a specific problem or question aligned with your objectives. For this team, they’re focused on improving website visits, which should translate into more sales. It should also be clear—easy to understand, so everyone knows exactly what’s being tested.</p><p>Finally, a hypothesis must be measurable. Specific metrics or criteria—like a 10% increase in customer engagement—give the team a clear target to evaluate success.</p><p>A good hypothesis is specific, testable, relevant, clear, and measurable. Here’s the complete hypothesis: ‘If we send personalized email offers, then customer engagement will increase by 10%.’</p><p>With this complete hypothesis statement finalized, the team is ready to put their plan into action!</p><p>Understanding the components of a good hypothesis statement is essential for conducting effective experiments in product development.&#160;A well-crafted hypothesis provides a clear direction for testing and validation, ensuring that experiments are meaningful and actionable.&#160;By focusing on specificity, testability, relevance, clarity, and measurability, teams can create hypothesis statements that drive successful innovation and customer-centric solutions within the Intuit Design for Delight framework.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3acdab455b37e4e311567023d12fc5f7','intuit-design-for-delight-m8-l7-module-6-summary','c3a1d4103c0d07f3bed9e3e7fe0c2508','Module 6 Summary','text',12,'<h2>Module 6 Summary</h2><section><h3>Module 6 Summary</h3><p>Module 6 Summary</p><p>Fantastic!&#160;You have successfully completed this module on&#160;Performing Rapid Customer Experiments Part II.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Given a set of assumptions, identified the most crucial assumptions.</p><p>Given a set of assumptions, identified the least-proven assumptions.</p><p>Given a set of assumptions, identified the Leap of Faith assumptions.</p><p>Identified the components of a good experiment.</p><p>Identified the components of a hypothesis statement.</p><p>Given a situation, created or completed a hypothesis statement.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2528959cbc4a6ecec1a617eadb59d456','intuit-design-for-delight-m8-l8-module-6-test-prep','c3a1d4103c0d07f3bed9e3e7fe0c2508','Module 6 Test Prep','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Performing Customer Exp 2. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,7,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('fc5d87daad3b74896f929495fb871e7e','intuit-design-for-delight-m8-l9-module-6-assignment','c3a1d4103c0d07f3bed9e3e7fe0c2508','Module 6 Assignment','text',12,'<h2>Module 6 Assignment</h2><section><h3>Module 6 Assignment</h3><p>Module 6 Assignment</p><p>Intuit Design for Delight</p><p>Performing Rapid Customer Experiments Part II - Short Answer Assignment</p><p>Short answer assignment</p><p>For this writing assignment, write a two-page, double-spaced paper addressing the questions/topics listed.</p><p>First, read the article below.</p><p>Understanding Crucial Assumptions, Least-Proven Assumptions, and Leap of Faith Assumptions in Rapid Experiments</p><p>Introduction</p><p>In the realm of product development and innovation, particularly within the Intuit Design for Delight (D4D) framework, assumptions play a critical role in guiding experiments and validating ideas. Assumptions are beliefs or statements that are taken to be true without proof. They serve as the foundation for hypotheses and experiments, allowing teams to focus their efforts on what matters most. This article delves into three key types of assumptions: crucial assumptions, least-proven assumptions, and Leap of Faith assumptions, explaining their significance in rapid experiments and their broader applications across various industries.</p><p>Crucial Assumptions</p><p>Definition and Importance</p><p>Crucial assumptions are the core beliefs that are fundamental to the success of a hypothesis. They are the assumptions that, if proven false, could significantly derail the entire project or product development process. Validating these assumptions early in the experimentation process is essential to avoid costly mistakes and to ensure that the foundational ideas are sound.</p><p>Application in Rapid Experiments</p><p>In the D4D framework, rapid experiments are designed to test these crucial assumptions quickly and efficiently. By focusing on what is most important, teams can gather critical data and make informed decisions. This approach minimizes risks and helps prioritize resources effectively.</p><p>Example:</p><p>Imagine a startup developing a new fitness app that assumes users want personalized workout plans. This assumption is crucial because the app&#39;s entire value proposition depends on it. A rapid experiment might involve creating a simple prototype that offers personalized plans and gathering user feedback to validate this assumption.</p><p>Broader Applications</p><p>Crucial assumptions are vital across industries, whether in technology, healthcare, finance, or retail. For instance, a healthcare provider developing a new telehealth service must validate the assumption that patients are comfortable with virtual consultations. This validation can prevent wasted resources and ensure that the service meets patient needs.</p><p>Least-Proven Assumptions</p><p>Definition and Importance</p><p>Least-proven assumptions are those that have the least evidence or data to support them. These assumptions are often the riskiest because they are based on limited information. Identifying and testing these assumptions helps to uncover potential issues early and allows teams to adjust their strategies accordingly.</p><p>Application in Rapid Experiments</p><p>In the D4D framework, least-proven assumptions are prioritized for testing to reduce uncertainty. Rapid experiments focus on gathering data to either validate or invalidate these assumptions, providing a clearer picture of the product&#39;s feasibility and potential success.</p><p>Example:</p><p>Consider a restaurant chain planning to introduce a new vegan menu. An assumption that customers will prefer vegan options is least proven if the restaurant has no prior data on customer preferences. A rapid experiment could involve offering a limited vegan menu at select locations and collecting customer feedback to assess demand.</p><p>Broader Applications</p><p>Testing least-proven assumptions is crucial in any industry where innovation is key. For example, a financial institution launching a new mobile banking feature might have the least-proven assumption that users will trust and adopt the new technology. Early testing can provide the necessary insights to refine the feature before a full-scale rollout.</p><p>Leap of Faith Assumptions</p><p>Definition and Importance</p><p>Leap of Faith assumptions are bold, high-risk assumptions that require a significant leap in thinking. These assumptions often represent the core innovation or the most transformative element, of a product or service. They are called &quot;Leaps of Faith&quot; because they involve a substantial degree of uncertainty and risk.</p><p>Application in Rapid Experiments</p><p>In the D4D framework, Leap of Faith assumptions are tested through rapid experiments to determine if the bold ideas they represent are viable. These experiments are designed to gather crucial insights quickly, allowing teams to pivot or proceed based on the results.</p><p>Example:</p><p>A tech company developing a revolutionary augmented reality (AR) device might have a Leap of Faith assumption that users will find value in using AR for everyday tasks. Testing this assumption through a rapid experiment, such as a pilot program with early adopters, can provide critical feedback and guide further development.</p><p>Broader Applications</p><p>Leap of Faith assumptions are common in disruptive innovations across industries. In retail, a company might assume that a fully automated store experience will appeal to customers. By conducting rapid experiments, such as testing a prototype store in a controlled environment, the company can validate or refute this assumption.</p><p>Applying Assumptions Across Industries</p><p>The principles of testing crucial, least-proven, and Leap of Faith assumptions through rapid experiments are universally applicable. Whether in technology, healthcare, finance, education, or retail, these assumptions guide innovation and development. The D4D framework&#39;s emphasis on rapid experimentation ensures that products and services are continuously refined to meet customer needs and expectations.</p><p>Conclusion</p><p>By understanding and effectively testing these different types of assumptions, students can better grasp the dynamics of product development and innovation, ultimately leading to more successful and customer-centric outcomes.</p><p>In your paper:</p><p>Summarize the article.</p><p>Address the following questions:</p><p>What are crucial assumptions, and why are they important in rapid experiments?</p><p>How do least-proven assumptions differ from crucial assumptions?</p><p>Why are Leap of Fai<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a9215f832978b5a1c664f21e7fa1d1ff','intuit-design-for-delight-m8-l10-module-6-project','c3a1d4103c0d07f3bed9e3e7fe0c2508','Module 6 Project','text',12,'<h2>Module 6 Project</h2><section><h3>Module 6 Project</h3><p>Module 6 Project</p><p>Intuit Design for Delight</p><p>Performing Rapid Customer Experiments Part II - Project</p><p>Project</p><p>For this project, you will practice writing hypothesis statements based on the scenarios provided. Remember that good hypothesis statements are:</p><p>Specific</p><p>Testable</p><p>Relevant</p><p>Clear</p><p>Measurable</p><p>There are 10 scenarios below (expand each one to reveal the scenario and the assumptions). Write a hypothesis statement for each scenario. You can choose the format in which you prefer to submit your hypothesis statements (Word document, PowerPoint, etc.). Be sure to write the scenario at the top so that it is clear which scenario is paired with each statement. Here is a sample for reference:</p><p>Scenario:&#160;A restaurant chain wants to introduce a new loyalty program to increase customer visits.</p><p>Assumptions:</p><p>Customers value a loyalty program.</p><p>A loyalty program will increase repeat visits.</p><p>The proposed loyalty program is easy to use.</p><p>Hypothesis Statement:&#160;&quot;Introducing a new loyalty program will increase repeat customer visits by 20% over the next three months.&quot;</p><p>You can be creative with things like percentages or timeframes since they will not be specified in the assumptions.</p><p>Review the rubric below to determine how you will be graded.</p><p>Scenario 1</p><p>Scenario:&#160;An online retailer wants to test if offering free shipping will increase the average order value.</p><p>Assumptions:</p><p>Customers appreciate free shipping.</p><p>Free shipping will encourage customers to spend more.</p><p>The cost of free shipping is sustainable for the business.</p><p>Scenario 2</p><p>Scenario:&#160;A mobile game developer wants to test if adding daily challenges will increase user engagement.</p><p>Assumptions:</p><p>Players enjoy daily challenges.</p><p>Daily challenges will encourage more frequent gameplay.</p><p>The challenges are varied and interesting enough to retain player interest.</p><p>Scenario 3</p><p>Scenario:&#160;A software company wants to introduce a new customer support chatbot to reduce response times.</p><p>Assumptions:</p><p>Customers prefer quick responses to their queries.</p><p>A chatbot can handle common questions effectively.</p><p>Implementing a chatbot will not significantly increase costs.</p><p>Scenario 4</p><p>Scenario:&#160;A fitness app wants to test if personalized workout plans will increase user retention.</p><p>Assumptions:</p><p>Users prefer workout plans tailored to their needs.</p><p>Personalized plans will motivate users to stay active.</p><p>The app can efficiently generate personalized plans.</p><p>Scenario 5</p><p>Scenario:&#160;A news website wants to test if a new commenting feature will increase user interaction.</p><p>Assumptions:</p><p>Users want to engage with content by commenting.</p><p>A commenting feature will increase the time users spend on the site.</p><p>Moderating comments will not be overly burdensome.</p><p>Scenario 6</p><p>Scenario:&#160;A grocery store chain wants to test if a mobile app for shopping lists will increase in-store sales.</p><p>Assumptions:</p><p>Customers find shopping lists helpful.</p><p>A mobile app will encourage more planned and higher-value purchases.</p><p>The app is user-friendly and reliable.</p><p>Scenario 7</p><p>Scenario:&#160;A subscription box service wants to test if including a surprise item will increase customer satisfaction.</p><p>Assumptions:</p><p>Customers enjoy receiving surprise items.</p><p>A surprise item will positively impact the unboxing experience.</p><p>The cost of including a surprise item is manageable.</p><p>Scenario 8</p><p>Scenario:&#160;A restaurant chain wants to test if offering a new plant-based menu will attract more health-conscious customers.</p><p>Assumptions:</p><p>There is a growing demand for plant-based options.</p><p>Health-conscious customers will be attracted to plant-based menus.</p><p>The restaurant can effectively market the new menu.</p><p>Scenario 9</p><p>Scenario:&#160;An online education platform wants to test if adding gamification elements will increase course completion rates.</p><p>Assumptions:</p><p>Gamification elements make learning more engaging.</p><p>Higher engagement will lead to higher completion rates.</p><p>Gamification elements are easy to integrate into the platform.</p><p>Scenario 10</p><p>Scenario:&#160;A clothing retailer wants to test if personalized email marketing will increase online sales.</p><p>Assumptions:</p><p>Personalized emails resonate more with customers.</p><p>Customers are more likely to make purchases if the emails are relevant to them.</p><p>The retailer can segment their email list effectively.</p><p>Performing Rapid Customer Experiments Part II Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Content</p><p>8 points The content demonstrates a strong understanding of the essential components of good hypothesis statements. The hypothesis statements for each scenario are well-written and contain all the essential elements.</p><p>7-4 points The content demonstrates a fair understanding of the essential components of good hypothesis statements. The hypothesis statements written for the scenarios contain most of the essential elements.</p><p>3-0 points The content shows little to no understanding of the essential components of hypothesis statements.</p><p>8</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,9,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('4ca71609dfce4918b68717ed5d3a34ef','intuit-design-for-delight-m8-l11-module-6-quiz','c3a1d4103c0d07f3bed9e3e7fe0c2508','Module 6 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Performing Customer Exp 2. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,10,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('16276f05a0aa8261e169614117a471a1','intuit-design-for-delight-module-9','92a4f5cdddc7f69042b22cbdf20f300f','Module 9: Performing Customer Exp 3',9) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7e890778c339f8004bad60e246f6e713','intuit-design-for-delight-m9-l1-introduction-purpose-and-objectives','16276f05a0aa8261e169614117a471a1','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hi and welcome to this module on Performing Rapid Customer Experiments Part 3!</p><p>For those born after 2007, it’s easy to take the iPhone for granted. But at the time, it was a game-changing product. But do you think this product was created overnight? Of course not! Prior to launch of the first iPhone, Steve Jobs, the CEO of Apple at the time, and his team went through numerous prototypes. They experimented with different designs and features to refine the product. The team tested multiple touchscreen interfaces, user experiences, and hardware configurations to find the perfect balance. Through continuous prototyping and learning from each iteration, they were able to create a groundbreaking product that revolutionized the tech industry and changed the way we interact with technology.</p><p>After this module, you may not know everything to create the next innovative technology platform. But you will be able to understand different methods of prototyping. These allow you to create early versions of your product or solution to gather feedback and refine your concept. You’ll also learn the key requirements for running a successful experiment, ensuring that your tests provide meaningful results. Whether you’re testing a new product feature or a customer experience, knowing how to run effective experiments is crucial.</p><p>But how do you know if your test was successful? You’ll dive into how to evaluate the outcomes of your tests and extract valuable insights from the data. Finally, you’ll discover how to use what you learned from each experiment to identify the next steps, whether it’s refining your prototype, gathering more data, adjusting your approach, or moving forward with confidence.</p><p>Module Description</p><p>In this module, you will explore various prototyping methods and learn what it takes to design a successful experiment.&#160;You will evaluate the outcomes of your tests to determine their success and identify key insights gained from these experiments.&#160;Additionally, you will learn how to use these insights to determine the next steps in your process, ensuring continuous improvement and innovation in your projects.</p><p>Objectives</p><p>In this module, students will</p><p>Identify prototyping methods.</p><p>Identify requirements of a successful experiment</p><p>Evaluate the success of a test.</p><p>Identify what you learned from the test.</p><p>Describe how to identify the next steps.</p><p>Polling Question</p><p>When conducting an experiment, what do you think is the most important component of a successful experiment?</p><p>a clear and testable hypothesis&#160;well-defined metrics&#160;a large (representative) sample size&#160;ethical considerations&#160;detailed documentation</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Definition</p><p>a statistical process that involves arbitrarily assigning participants to experimental conditions or groups</p><p>correlation analysis</p><p>the act of&#160;keeping participants unaware of whether they are in the control or experimental group</p><p>comparative analysis</p><p>a standard or point of reference against which things may be compared or assessed</p><p>blinding</p><p>exploration of relationships between different variables to understand how they influence each other</p><p>randomization</p><p>evaluation of&#160;test results with previous benchmarks or control groups to evaluate performance</p><p>benchmark</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>a statistical process that involves arbitrarily assigning participants to experimental conditions or groups</p><p>Answers for question: 1</p><p>benchmark</p><p>randomization</p><p>comparative analysis</p><p>correlation analysis</p><p>blinding</p><p>2.</p><p>the act of&#160;keeping participants unaware of whether they are in the control or experimental group</p><p>Answers for question: 2</p><p>randomization</p><p>blinding</p><p>comparative analysis</p><p>benchmark</p><p>correlation analysis</p><p>3.</p><p>a standard or point of reference against which things may be compared or assessed</p><p>Answers for question: 3</p><p>benchmark</p><p>correlation analysis</p><p>blinding</p><p>randomization</p><p>comparative analysis</p><p>4.</p><p>exploration of relationships between different variables to understand how they influence each other</p><p>Answers for question: 4</p><p>comparative analysis</p><p>correlation analysis</p><p>blinding</p><p>randomization</p><p>benchmark</p><p>5.</p><p>evaluation of&#160;test results with previous benchmarks or control groups to evaluate performance</p><p>Answers for question: 5</p><p>comparative analysis</p><p>benchmark</p><p>randomization</p><p>blinding</p><p>correlation analysis</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3aa8352bf072229ac96e067cdf04f716','intuit-design-for-delight-m9-l2-lesson-1','16276f05a0aa8261e169614117a471a1','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>Guide to Prototyping Methods</h3><p>Guide to Prototyping Methods</p><p>Prototyping is a fundamental aspect of product development that involves creating an early model or simulation of a product to test and validate ideas before full-scale production.&#160;It allows designers and developers to explore concepts, identify issues, and gather feedback from stakeholders and users.&#160;The process is crucial in ensuring that the final product meets user needs and expectations.&#160;In this section, we will explore various prototyping methods.</p><p>Review:&#160;Prototyping</p><p>As you&#39;ve learned throughout the readings, prototyping is the practice of building a preliminary version of a product, known as a prototype, to visualize and test its functionality.&#160;This iterative process helps teams experiment with design solutions, assess feasibility, and make informed decisions early in the development cycle.&#160;Prototyping can take many forms, from simple sketches and paper models to complex digital simulations and interactive mockups.</p><p>There are many prototyping methods.&#160;Expand each section below to learn about some.</p><p>Sketches and Diagrams</p><p>Description: The simplest form of prototyping, involving hand-drawn sketches and diagrams to represent ideas and concepts.</p><p>Example: A team designing a new mobile app might sketch different layouts of the user interface on paper to explore various design options.</p><p>Paper Prototypes</p><p>Description: Paper prototypes are low-fidelity physical models made from paper, cardboard, or other simple materials. They are used to simulate user interactions.</p><p>Example: For a new website, designers create a paper prototype with different pages and navigation paths, allowing users to interact with the &quot;site&quot; by moving pieces of paper.</p><p>Wireframes</p><p>Description: Wireframes are low-fidelity digital or hand-drawn representations of a product&#39;s layout. They focus on structure and functionality rather than aesthetics.</p><p>Example: A software development team creates wireframes of an e-commerce site to outline the placement of menus, product listings, and checkout processes.</p><p>Mockups</p><p>Description: Mockups are high-fidelity, static representations of a product&#39;s design, focusing on visual elements such as color schemes, typography, and images.</p><p>Example: Designers produce a mockup of a mobile app, complete with final graphics and branding, to showcase the visual design to stakeholders.</p><p>Interactive Prototypes</p><p>Description: Interactive prototypes are dynamic models that simulate user interactions, providing a more realistic experience of the product’s functionality.</p><p>Example: Using tools like Adobe XD or Figma, developers create an interactive prototype of a mobile banking app, allowing users to click through different screens and perform actions.</p><p>HTML/CSS Prototypes</p><p>Description: These are web-based prototypes built using HTML, CSS, and sometimes JavaScript. They offer a near-final experience of a web application.</p><p>Example: A development team builds an HTML/CSS prototype of a travel booking site, allowing users to search for flights, view results, and go through the booking process.</p><p>3D Prototypes</p><p>Description: Used primarily for physical products, 3D prototypes can be created using 3D printing or CAD software to produce tangible models.</p><p>Example: A hardware company uses 3D printing to produce a prototype of a new smartwatch, allowing testers to wear and interact with it.</p><p>Watch this video to take a look at a few of these prototypes!</p><p>Prototyping is essential in product development—especially when launching something as complex as a video game. It allows teams to test and validate ideas before committing to full-scale production. Let’s walk through the different stages of prototyping, using the development of a new video game as our example.</p><p>First up: sketches and diagrams. The team begins by sketching ideas for the characters, environments, and game mechanics. These simple visuals help map out the core concepts of the game. The diagrams also outline how the game will flow, from early levels to more complex challenges.&quot;</p><p>Next, the team moves on to mockups. This step brings more detail, adding color, textures, and even basic animations to character designs and game environments. Mockups help visualize what the final product could look like, bringing the game’s visual style to life.</p><p>Finally, the team builds 3D models. These detailed, lifelike representations bring characters and environments closer to their final form. 3D models allow the team to test animations, textures, and the overall look of the game component. They can make sure everything works seamlessly.</p><p>Prototyping through sketches, mockups, 3D models, or other methods is an essential part of development, whether that’s for a game or a product. It allows teams to explore ideas, gather feedback, and refine the product before full-scale production.</p><p>The Design for Delight (D4D) framework at Intuit emphasizes rapid experimentation and customer-centric innovation.&#160;Prototyping is integral to this approach, enabling teams to quickly iterate on ideas and validate them with real users.&#160;By using various prototyping methods, Intuit can ensure that new features and products are both innovative and aligned with customer needs.</p><p>Prototyping is a powerful tool in product development, providing a practical way to test and validate ideas before full-scale production.&#160;By leveraging different prototyping methods, teams can explore concepts, identify issues, and gather valuable feedback from stakeholders and users.&#160;In the context of Intuit’s Design for Delight framework, prototyping plays a crucial role in driving customer-centric innovation and delivering products that truly meet user needs.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c6f7ce1f7fe3781d8c40fd60315bb92f','intuit-design-for-delight-m9-l3-lesson-2','16276f05a0aa8261e169614117a471a1','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Requirements of a Successful Experiment</h3><p>Requirements of a Successful Experiment</p><p>Experiments are a cornerstone of the development process, especially within frameworks like Intuit&#39;s Design for Delight (D4D).&#160;Whether developing a new product or making changes to processes or services, conducting successful experiments is essential to validating ideas, testing assumptions, and gathering actionable insights that drive customer-centric innovation.&#160;A successful experiment is not just about following steps but ensuring that each aspect of the experiment is meticulously planned and executed.&#160;In this section, we will review the critical requirements for a successful experiment.</p><p>Expand each section below to learn about the requirements.</p><p>Clear and Testable Hypothesis</p><p>A successful experiment starts with a well-defined, clear, and testable hypothesis. The hypothesis should articulate what you aim to learn or prove through the experiment. It needs to be specific and measurable, setting a clear expectation for the outcome.</p><p>Example:&#160;For a new budgeting tool, the hypothesis might be, “Introducing a simplified budgeting feature will increase user engagement by 20% over the next month.”</p><p>Well-Defined Metrics</p><p>Successful experiments require well-defined metrics to measure the outcomes objectively. These metrics should align with the hypothesis and provide quantifiable data that can be analyzed to determine the success or failure of the experiment.</p><p>Example:&#160;Metrics for the budgeting tool might include user engagement rates, the number of active users, and user feedback scores.</p><p>Control and Experimental Groups</p><p>To accurately assess the impact of changes, it is crucial to have both control and experimental groups. The control group experiences the existing version of the product, while the experimental group interacts with the new version. This comparison helps isolate the effects of the changes being tested.</p><p>Example:&#160;For a new loyalty program in a restaurant chain, the control group would be customers who use the current system, while the experimental group would use the new loyalty program.</p><p>Representative Sample Size</p><p>The sample size for the experiment must be large enough to provide statistically significant results. A small sample size may lead to unreliable conclusions, while a representative sample ensures the findings are robust and generalizable.</p><p>Example:&#160;A mobile app experiment might require thousands of users to participate to draw meaningful insights.</p><p>Randomization</p><p>Randomization involves assigning participants to control and experimental groups randomly. This helps eliminate bias and ensures that differences in outcomes are due to the changes being tested rather than other variables.</p><p>Example:&#160;Randomly assigning users to test different versions of an e-commerce site’s checkout process.</p><p>Blinding</p><p>Blinding means keeping participants unaware of whether they are in the control or experimental group. This prevents their behavior from being influenced by knowing which version they are using.</p><p>Example:&#160;In a drug trial, neither the patients nor the administrators know who receives the actual drug versus a placebo.</p><p>Ethical Considerations</p><p>Ethical considerations are paramount in designing and conducting experiments. Ensuring that participants are treated fairly, their data is handled responsibly, and they are fully informed about the nature of the experiment is crucial.</p><p>Example:&#160;Gaining informed consent from users participating in a usability test for a new app feature.</p><p>Detailed Documentation</p><p>Documenting every aspect of the experiment, from the hypothesis and metrics to the procedure and results, is essential. Detailed documentation ensures transparency, enables replication, and provides a clear record of what was tested and why.</p><p>Example:&#160;Maintaining comprehensive records of an A/B test on a website’s landing page to track changes and outcomes.</p><p>Actionable Insights</p><p>The ultimate goal of an experiment is to gather actionable insights. These insights should guide the next steps in the product development process, whether that involves refining the feature, conducting further tests, or scaling the solution.</p><p>Example:&#160;Analyzing feedback from a new app feature to identify improvements and next steps.</p><p>Successful experiments in product development require meticulous planning, clear hypotheses, well-defined metrics, representative sample sizes, randomization, ethical considerations, and detailed documentation.&#160;By adhering to these requirements, teams can ensure that their experiments yield reliable, actionable insights that drive customer-centric innovation.&#160;In the context of Intuit’s Design for Delight framework, these requirements are crucial for developing features and products that truly meet customer needs and deliver delightful experiences.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c66e2c898df76cb5b737fd2f251b81d2','intuit-design-for-delight-m9-l4-lesson-3','16276f05a0aa8261e169614117a471a1','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Evaluating the Success of a Test</h3><p>Evaluating the Success of a Test</p><p>Evaluating the success of a test is a crucial step that ensures innovations are aligned with customer needs and expectations.&#160;The Design for Delight framework emphasizes rapid experimentation, customer empathy, and iterative development.&#160;Evaluating the success of a test within this framework involves a thorough analysis of various factors to determine whether the experiment has achieved its intended goals.&#160;This section outlines the key components and methodologies for evaluating the success of a test, providing insights that can be applied across industries and contexts.</p><p>Explore these components by expanding the sections below.</p><p>Setting Clear Objectives and Success Criteria</p><p>Objective Setting:&#160;Before conducting a test, it is essential to establish clear objectives. What do you aim to learn or achieve? Objectives should be specific, measurable, attainable, relevant, and time-bound (SMART). This clarity ensures that everyone involved understands the purpose and expected outcomes.</p><p>Success Criteria:&#160;Define the criteria for success. These criteria should be aligned with the objectives and provide quantifiable measures to evaluate the results. Success criteria might include specific metrics such as increased user engagement, improved customer satisfaction, or reduced error rates.</p><p>Example:&#160;Objective: To increase user engagement with a new feature in a mobile banking app. Success Criteria: A 20% increase in user engagement over the next three months, as measured by time spent on the app and the number of returning users.</p><p>Collecting and Analyzing Data</p><p>Data Collection:&#160;Collect both qualitative and quantitative data during the experiment. Quantitative data provides numerical insights (e.g., engagement rates, conversion rates), while qualitative data offers contextual understanding (e.g., user feedback, interviews).</p><p>Analysis Methods:</p><p>Descriptive Analysis:&#160;Summarize the main features of the data collected.</p><p>Comparative Analysis:&#160;Compare results against control groups or previous benchmarks.</p><p>Trend Analysis:&#160;Identify patterns or trends over time.</p><p>Correlation Analysis:&#160;Explore relationships between different variables.</p><p>Example:&#160;In testing a new feature in an e-commerce platform, collect data on user interactions, purchase rates, and feedback. Use comparative analysis to measure changes in user satisfaction before and after the feature launch.</p><p>Understanding Customer Feedback</p><p>Customer Empathy:&#160;Understanding and empathizing with customers is crucial. Analyzing customer feedback helps gauge their experiences, preferences, and pain points.</p><p>Feedback Channels:&#160;Utilize various channels to gather feedback, including surveys, interviews, usability tests, and social media. Pay attention to both positive and negative feedback to gain a comprehensive view.</p><p>Example:&#160;For a new feature in a fitness tracking app, gather feedback through post-use surveys, focus groups, and online reviews. Analyze this feedback to understand user satisfaction and areas for improvement.</p><p>Measuring Against Benchmarks</p><p>Benchmarking:&#160;Compare the test results against established benchmarks. These benchmarks can be internal (e.g., previous product versions) or external (e.g., industry standards).</p><p>Performance Indicators:&#160;Identify key performance indicators (KPIs) that reflect the success criteria. Benchmarks help contextualize the results and assess whether the test met, exceeded, or fell short of expectations.</p><p>Example:&#160;For a new feature in a project management tool, benchmark user engagement and satisfaction against previous versions and competitor offerings to evaluate its performance.</p><p>Iterating Based on Insights</p><p>Continuous Improvement:&#160;A key aspect of product development is iterative development. Use insights gained from the test to refine the product. Successful tests should provide clear directions for the next steps, whether it&#39;s scaling the solution or making adjustments.</p><p>Actionable Insights:&#160;Translate data and feedback into actionable insights. Identify what worked well and what needs improvement. Plan subsequent tests or development phases based on these insights.</p><p>Example:&#160;If a new feature in an online education platform shows increased user satisfaction but high error rates, iterate by improving the error-prone aspects and conducting another test.</p><p>Communicating Results</p><p>Transparency:&#160;Communicate the results of the test to all stakeholders. Transparency ensures everyone is aligned and understands the outcomes and implications.</p><p>Reporting:&#160;Create comprehensive reports that detail the objectives, methodology, data collected, analysis, and conclusions. Highlight key findings and recommendations for future actions.</p><p>Example:&#160;Present a detailed report on a new feature in a CRM system’s test results to the product team, highlighting user engagement improvements and areas needing further refinement.</p><p>Long-Term Monitoring</p><p>Sustained Observation:&#160;Evaluate the long-term impact of the changes implemented. Continuous monitoring helps ensure that the initial success is sustained and adapts to evolving customer needs.</p><p>Feedback Loops:&#160;Establish ongoing feedback loops to keep track of user satisfaction and performance over time. Use this data to make further enhancements.</p><p>Example:&#160;Monitor the long-term use of a new feature in a healthcare app, regularly collecting user feedback and performance metrics to ensure it continues to meet user needs.</p><p>Let&#39;s recap how to determine the success of your testing.&#160;Watch the video below.</p><p>Evaluating the success of a test involves setting clear objectives, collecting and analyzing data, understanding customer feedback, measuring against benchmarks, iterating based on insights, communicating results, and long-term monitoring.&#160;These steps ensure that experiments are not only well-conducted but also provide actionable insights that drive continuous improvement and customer-centric innovation.&#160;By applying these principles, product development teams across various industries can create products and services that truly delight their customers.</p><p>Hi and welcome to Lesson<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('899956baf0c221ef698f4cd1e234dc51','intuit-design-for-delight-m9-l5-lesson-4','16276f05a0aa8261e169614117a471a1','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Test Learning Outcomes</h3><p>Test Learning Outcomes</p><p>Identifying What You Learned from a Test</p><p>In product development, running tests is essential to validate ideas, gather data, and gain insights.&#160;However, the true value of these tests lies in identifying and understanding what you learn from them.&#160;This section delves into the importance of extracting meaningful lessons from tests, the methods for doing so, and how these lessons can enhance the overall product development process.&#160;Understanding the learnings from a test is a crucial precursor to planning future actions, which we&#39;ll discuss in the next section.</p><p>Press the plus (+) in each box below to learn more about the value of learning from tests.</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Learning from Tests: Validating Hypotheses, Understanding Customer Needs, Reducing Uncertainty, Improving Product Features</p><p>The hotspot points on the image are as follows:</p><p>Validating Hypotheses</p><p>Every test is built around a hypothesis, which is a statement predicting an outcome based on certain assumptions. Identifying whether the hypothesis was validated or refuted is a primary learning outcome. This helps in confirming the foundational ideas behind a product or feature.</p><p>Understanding Customer Needs</p><p>Tests provide valuable insights into customer behaviors, preferences, and pain points. By analyzing these insights, you can better understand what your customers truly need and want, leading to more customer-centric products.</p><p>Reducing Uncertainty</p><p>Product development is inherently risky. Learning from tests helps reduce uncertainty by providing concrete data and feedback. This knowledge helps in making informed decisions and minimizing risks in future developments.</p><p>Improving Product Features</p><p>Insights gained from tests can highlight strengths and weaknesses in your product. Understanding these aspects allows you to enhance features that work well and address those that don’t meet customer expectations.</p><p>Before we dive into the methods of learning, let&#39;s recap what it is we need to know.</p><p>close</p><p>Meet the team behind the next-gen toothbrush. Their mission? To create a toothbrush that not only cleans teeth better but also visibly whitens them more effectively than anything on the market.</p><p>Every test begins with a clear hypothesis. The team believes their toothbrush will remove 20% more plaque and whiten teeth in just two weeks. But how do they prove it? Real users test the product at home, giving the team valuable insights. The sensors in the toothbrush monitor how effectively it cleans different areas of the mouth, and how easy it is to use for the average person.</p><p>The team monitors everything. They’re not just looking for plaque removal; they’re paying attention to comfort and ease of use—things that matter just as much to the customer experience.</p><p>After the test, feedback starts to roll in. While the toothbrush removed plaque effectively, users noticed that the whitening effect was less dramatic than expected. Some even found the handle hard to grip when wet.</p><p>These insights are critical. The feedback highlights exactly where the toothbrush succeeded—better plaque removal—and where it fell short. The whitening feature, a key selling point, wasn’t as effective as the team had hoped. And small usability issues, like the slippery handle, could hurt the overall experience.</p><p>With the feedback in hand, the team knows exactly where to focus their next efforts. First, they’ll work on improving the whitening technology, adjusting the formula to make the results more visible after just a few uses. Then, they’ll redesign the handle to ensure a better grip, adding a textured surface that’s easy to hold—even when wet.</p><p>By refining both the whitening and the handle design, the team ensures the toothbrush not only performs better but feels better to use. Every test, every piece of feedback, helps them reduce uncertainty and create a product that truly meets customer needs.</p><p>Methods for Identifying Learning from Tests</p><p>Press through the tabs below to explore some of the ways to identify learning from tests you conduct.</p><p>Data Analysis</p><p>Quantitative data provides measurable evidence of how well a test performed against predefined metrics.&#160;Analyze key performance indicators (KPIs) such as engagement rates, conversion rates, and error rates to draw conclusions about the test’s success.</p><p>Example:&#160;In testing a new feature in a mobile app, you might track metrics like the number of users who tried the feature, their engagement time, and the rate of successful completions.&#160;Analyzing these metrics can reveal how well the feature is performing and where it might need improvement.</p><p>Customer Feedback</p><p>Qualitative data from customer feedback is equally important. Gather insights through surveys, interviews, and usability tests to understand the subjective experiences of users.</p><p>Example:&#160;After introducing a new checkout process in an e-commerce platform, conducting user interviews can reveal whether customers find the process intuitive and what specific challenges they face.</p><p>Comparative Analysis</p><p>Compare the test results with previous benchmarks or control groups to evaluate performance. This comparison helps in understanding the impact of the changes made during the test.</p><p>Example:&#160;If you’ve launched a new loyalty program in a retail app, compare customer retention rates before and after the program’s introduction to assess its effectiveness.</p><p>Trend Analysis</p><p>Identify patterns and trends over time to see how the test results evolve. This can provide insights into whether the initial success is sustained or if there are diminishing returns.</p><p>Example:&#160;Tracking the usage of a new feature over several weeks or months can reveal whether initial engagement levels are maintained or if interest wanes over time.</p><p>Correlation Analysis</p><p>Explore relationships between different variables to understand how they influence each other. This can uncover hidden insights that might not be apparent through simple observation.</p><p>Example:&#160;Analyzing the correlation between user demographics and feature adoption rates can help identify which segments of yo<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3d0d76af5bcf9ebe27aadf17bf1df3ac','intuit-design-for-delight-m9-l6-lesson-5','16276f05a0aa8261e169614117a471a1','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Next Steps after Experiment</h3><p>Next Steps after Experiment</p><p>Identifying Next Steps After Experimentation</p><p>So, now that you have completed an experiment, evaluated its success, and determined what you have learned, what&#39;s next?&#160;Now, it is crucial to identify the next steps.&#160;This stage is where you translate insights into action, ensuring that the knowledge gained is effectively utilized to drive progress.&#160;Within the context of the D4D framework, identifying the next steps is an integral part of fostering continuous innovation and improvement.&#160;This section will guide you through the process of identifying the next steps after experimentation, ensuring that your efforts lead to meaningful outcomes.</p><p>Let&#39;s take a look at how to go about identifying these steps.&#160;Expand each of the sections below to learn more.</p><p>Review the Insights Gathered</p><p>Synthesize Findings: Begin by reviewing the insights gathered from your experiments. Synthesize the data to understand the key takeaways and trends. This involves looking at both quantitative metrics and qualitative feedback.</p><p>Compare Against Objectives: Compare the results against the original objectives and success criteria defined for the experiment. Determine whether the hypotheses were validated or refuted.</p><p>Identify Areas for Improvement</p><p>Highlight Strengths and Weaknesses: Identify what aspects of the experiment worked well and which did not. Highlight strengths that can be leveraged and weaknesses that need to be addressed.</p><p>Prioritize Issues: Not all issues need immediate attention. Prioritize them based on their impact on the overall goals and customer experience.</p><p>Generate Actionable Recommendations</p><p>Develop Recommendations: Develop specific, actionable recommendations based on the insights and areas for improvement. These should be clear and detailed, providing a roadmap for moving forward.</p><p>Align with Strategic Goals: Ensure that the recommendations align with the broader strategic goals of the project or organization. This alignment ensures that the next steps contribute to long-term objectives.</p><p>Plan for Iterations</p><p>Define Iteration Goals: Define what you aim to achieve in the next iteration. Set clear, measurable goals that can be evaluated in subsequent experiments.</p><p>Prepare New Experiments: Plan new experiments to test the recommendations and address identified issues. This iterative approach ensures continuous learning and refinement.</p><p>Communicate Findings and Next Steps</p><p>Stakeholder Communication: Effectively communicate the findings, insights, and proposed next steps to relevant stakeholders. Ensure transparency and clarity to gain buy-in and support.</p><p>Documentation: Document the entire process, including insights, recommendations, and planned actions. This documentation serves as a reference and ensures consistency in future efforts.</p><p>Implement Changes</p><p>Execute Plans: Begin implementing the changes based on the identified next steps. Ensure that the implementation is systematic and monitored closely.</p><p>Monitor Progress: Continuously monitor the progress of the implemented changes. Use feedback and data to assess their impact and make further adjustments as needed.</p><p>Real-World Examples</p><p>Understanding how to identify the next steps after an experiment is crucial across various industries.&#160;By examining real-world examples, we can see how different sectors apply these principles to drive improvement and innovation.&#160;These examples illustrate how the insights gained from experiments lead to actionable recommendations, iterative testing, and effective implementation, ensuring that each step aligns with broader strategic goals and customer needs.</p><p>Press through the tabs below to see how scenarios in three industries may look when it comes to identifying and carrying out next steps.</p><p>Retail Industry</p><p>Scenario:&#160;A retail chain conducts an experiment to test a new in-store layout designed to improve customer flow and increase sales.</p><p>Next Steps:&#160;After evaluating the success of the new layout, they identify areas that caused congestion.&#160;They plan to redesign these areas and conduct another experiment to validate the changes.</p><p>Healthcare Industry</p><p>Scenario: A healthcare provider tests a new telehealth platform to improve patient access to care.</p><p>Next Steps: They learn that while the platform is generally effective, there are issues with user interface complexity. The next steps involve simplifying the interface and testing the revised version with patients.</p><p>Technology Industry</p><p>Scenario: A software company experiments with a new feature in its application aimed at increasing user engagement.</p><p>Next Steps: The experiment shows increased engagement but highlights performance issues. The company plans to optimize the feature for better performance and run additional tests to confirm improvements.</p><p>Next Tab</p><p>By following these steps and comprehensively evaluating each phase, you can effectively identify and implement the next steps after experimentation.&#160;This approach ensures that your efforts lead to meaningful and impactful outcomes, driving continuous improvement and innovation.</p><p>Let&#39;s review what you&#39;ve learned in this lesson and throughout the module.&#160;Watch the video below.</p><p>Hi and welcome to Lesson 5 for this module on Performing Rapid Customer Experiments Part 3!</p><p>At the end of the Design for Delight process, after all the tests and experiments, what comes next? Let’s look at this through an example of a Virtual Reality (or VR) headset that you have developed for educational purposes. With this amazing product, you&#39;ve conducted a series of tests, collecting data on how students and teachers interact with the product in real-world classroom settings. Now, it&#39;s time to use that data to improve your product. Here’s a step-by-step guide on how to continue enhancing any product in the Design for Delight framework.</p><p>The first step is to gather all the data you’ve collected from the product tests. This includes quantitative data, like how long students used the VR headset, how many sessions were completed, and how often technical problems happened. You also need to look at qualitative data, such as feedback from students and teachers about the experienc<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7edaae60374596058649c656d54ce71a','intuit-design-for-delight-m9-l7-module-7-summary','16276f05a0aa8261e169614117a471a1','Module 7 Summary','text',12,'<h2>Module 7 Summary</h2><section><h3>Module 7 Summary</h3><p>Module 7 Summary</p><p>Great Work!&#160;You have successfully completed this module on Performing Rapid Customer Experiments Part III.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified prototyping methods.</p><p>Identified requirements of a successful experiment</p><p>Evaluated the success of a test.</p><p>Identified what you learned from the test.</p><p>Described how to identify the next steps.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a00903c41676d263415fbf5d24e094bc','intuit-design-for-delight-m9-l8-module-7-test-prep','16276f05a0aa8261e169614117a471a1','Module 7 Test Prep','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Performing Customer Exp 3. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,7,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2834b6141c63cd4d8af556b4930280d5','intuit-design-for-delight-m9-l9-module-7-assignment','16276f05a0aa8261e169614117a471a1','Module 7 Assignment','text',12,'<h2>Module 7 Assignment</h2><section><h3>Module 7 Assignment</h3><p>Module 7 Assignment</p><p>Intuit Design for Delight</p><p>Performing Rapid Customer Experiments Part III - Short Answer Assignment</p><p>Short answer assignment</p><p>Throughout this module, you learned about experimentation, various ways to perform and evaluate testing, and how to learn from the results of tests. Finally, you learned about identifying the next steps. This is when everything culminates into action based on what you have learned. In a two-page, double-spaced paper, address the following items about the components of next steps:</p><p>How does reviewing insights and comparing them against objectives help in identifying the next steps after an experiment? Provide an example to support your explanation.</p><p>Why is it important to prioritize issues identified during an experiment? Think of an example of how this prioritization would impact next steps.</p><p>How does aligning actionable recommendations with goals benefit the overall project?</p><p>Reflection: Based on what you&#39;ve learned about next steps, think of a project or experiment in which you&#39;ve participated. Describe how you would identify and implement next steps to ensure continuous improvement and success. Include at least one example from your experience.</p><p>Review the rubric below to determine how you will be graded.</p><p>Short Answer Assignment</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Questions Answered</p><p>8 points All of the questions are addressed in the writing. Each of the answers include full and accurate responses that demonstrate a strong understanding of the content.</p><p>7-6 points All of the questions are addressed in the writing. Some of the answers are incomplete or include partially accurate responses that demonstrate a solid understanding of the content.</p><p>5-0 points All of the questions are not addressed in the writing. The answers lack accurate responses or are missing, demonstrating little to no understanding of the content.</p><p>8</p><p>Supporting Information</p><p>8 points Includes relevant support and explanation and thoroughly expands on the thoughts discussed.</p><p>7-6 points Includes incomplete support and explanation and slightly expands on the thoughts discussed.</p><p>5-0 points Includes little to no related support and explanation and does not expand on the thoughts discussed.</p><p>8</p><p>Formatting</p><p>2 points Meets the two-page double space requirement and is formatted neatly.</p><p>0 points Does not meet the two-page double space requirement and is not formatted neatly.</p><p>2</p><p>Mechanics</p><p>2 points Contains few, if any, spelling or grammar errors.</p><p>1 point Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>2</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,8,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('76f75bfb45285ab18386b16a0595c9d6','intuit-design-for-delight-m9-l10-module-7-project','16276f05a0aa8261e169614117a471a1','Module 7 Project','text',12,'<h2>Module 7 Project</h2><section><h3>Module 7 Project</h3><p>Module 7 Project</p><p>Intuit Design for Delight</p><p>Performing Rapid Customer Experiments Part III - Project</p><p>Project</p><p>For this project, you will create a slideshow based on what you have learned about evaluating the success of a test. You will be provided with three scenarios and will choose one for your project. Follow the guidelines below to see how your slides should be laid out. In addition to text, use graphics (images, photos, drawings, and other media) to make your presentation visually appealing and engaging.</p><p>Title Slide:</p><p>Title: &quot;Evaluating the Success of a Test&quot;</p><p>Name and date</p><p>Slide 1: Scenario Selection</p><p>Scenario 1: New Product Launch&#160;– Your company is launching a new energy drink and needs to test its market acceptance.</p><p>Scenario 2: Website Redesign&#160;– Your company has redesigned its website and wants to test if the new design improves user engagement.</p><p>Scenario 3: Employee Training Program&#160;– Your company has implemented a new training program and needs to evaluate its effectiveness.</p><p>Example:&#160;For this project, I have chosen Scenario 1: New Product Launch.</p><p>Slide 2: Set Clear Objectives and Success Criteria</p><p>Objective:&#160;Define what you aim to achieve with the test.</p><p>Success Criteria:&#160;Specify measurable outcomes that will indicate success.</p><p>Slide 3: Collect and Analyze Data</p><p>Data Collection:&#160;Describe the methods you will use to gather data.</p><p>Data Analysis:&#160;Explain how you will analyze the collected data to draw conclusions.</p><p>Slide 4: Understand Customer Feedback</p><p>Gathering Feedback:&#160;Describe how you will obtain feedback from customers.</p><p>Analyzing Feedback:&#160;Explain how you will interpret the feedback to improve your product or service.</p><p>Slide 5: Measure Against Benchmarks</p><p>Benchmarking:&#160;Identify relevant benchmarks to compare your test results against.</p><p>Analysis:&#160;Explain how you will use these benchmarks to evaluate success.</p><p>Slide 6: Iterate Based on Insights</p><p>Iteration Process:&#160;Describe how you will use insights from the test to make improvements.</p><p>Implementation:&#160;Explain how you will implement these improvements.</p><p>Slide 7: Communicate Results</p><p>Communication Strategy:&#160;Describe how you will communicate the test results to stakeholders.</p><p>Presentation of Data:&#160;Explain how you will present the data to ensure clarity and understanding.</p><p>Slide 8: Monitor Long-term</p><p>Long-term Monitoring:&#160;Explain how you will continue to monitor the product or service after the initial test.</p><p>Ongoing Evaluation:&#160;Describe the methods you will use to ensure sustained success.</p><p>Be sure to use the information you learned throughout the module as you complete your project. You can also expand the section below for a sample project outline if you aren&#39;t sure what information to include on a particular slide.</p><p>Review the rubric to determine how you will be graded.</p><p>Example Project Outline: Mobile App Beta Test</p><p>Title Slide:</p><p>&quot;Evaluating the Success of a Test&quot; Javier Fumero, August 19, 2024</p><p>Slide 1: Scenario Selection</p><p>Chosen Scenario: Mobile App Beta Test</p><p>Slide 2: Set Clear Objectives and Success Criteria</p><p>Example:&#160;The objective of our beta test is to assess the overall user experience and identify any critical bugs before the full launch. Success will be measured by achieving high user satisfaction, resolving the majority of bugs, and maintaining strong user engagement.</p><p>Slide 3: Collect and Analyze Data</p><p>Example:&#160;We will collect data through in-app analytics, user surveys, and a bug-reporting tool. The analysis will involve examining user behavior to understand app usage, evaluating survey responses to gauge satisfaction, and categorizing bugs to prioritize fixes.</p><p>Slide 4: Understand Customer Feedback</p><p>Example:&#160;Feedback will be gathered via in-app surveys, focus groups, and app store reviews. The analysis will involve categorizing feedback into key areas and identifying recurring themes to guide improvements.</p><p>Slide 5: Measure Against Benchmarks</p><p>Example:&#160;We will benchmark our app against industry standards for similar mobile applications, evaluating performance and user satisfaction to ensure we meet or exceed these metrics.</p><p>Slide 6: Iterate Based on Insights</p><p>Example:&#160;Insights from data and feedback will guide our iteration process. We will prioritize bug fixes, enhance key features, and refine the user interface before the next round of testing or full launch.</p><p>Slide 7: Communicate Results</p><p>Example:&#160;Results will be communicated through a detailed report and a presentation to stakeholders. Visual aids will help illustrate key findings and recommended actions.</p><p>Slide 8: Monitor Long-term</p><p>Example:&#160;Post-launch, we will continuously monitor app performance and user feedback, making ongoing adjustments to ensure sustained success and user satisfaction.</p><p>Performing Rapid Customer Experiments Part III Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Content</p><p>8 points The content demonstrates a strong understanding of how to evaluate the success of a test. The examples provided for each of the key components were relevant and well-explained.</p><p>7-4 points The content demonstrates a fair understanding of how to evaluate the success of a test. The examples provided for each of the key components were mostly relevant.</p><p>3-0 points The content demonstrates little to no understanding of how to evaluate the success of a test.</p><p>8</p><p>Slideshow</p><p>8 points The slideshow was structured according to guidelines. It was organized very well, visually appealing, and engaging.</p><p>7-6 points The slideshow was mostly structured according to guidelines. It was organized relatively well and included relevant imagery.</p><p>5-0 points The slideshow was not structured according to the guidelines. It was disorganized and not engaging.</p><p>8</p><p>Mechanics</p><p>4 points Contains few, if any, spelling or grammar errors.</p><p>2 points Contains several spelling or grammar errors.</p><p>0 points Contains numerous spelling or grammar errors.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,9,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('27a50da4619ef7c6ecebdc1aed389995','intuit-design-for-delight-m9-l11-module-7-quiz','16276f05a0aa8261e169614117a471a1','Module 7 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Performing Customer Exp 3. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,10,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('6a38e82cd5ec78ca048ad9150b7431e4','intuit-design-for-delight-module-10','92a4f5cdddc7f69042b22cbdf20f300f','Module 10: Course Wrap & Final Exam',10) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('dc127c031cd72ac6915f47ca4f888101','intuit-design-for-delight-m10-l1-course-wrap-and-final-exam','6a38e82cd5ec78ca048ad9150b7431e4','Course Wrap & Final Exam','text',12,'<h2>Course Wrap &amp; Final Exam</h2><section><h3>Course Wrap Up</h3><p>Course Wrap Up</p><p>We&#39;re at the last leg of our exciting journey!</p><p>We hope this course has equipped you with the knowledge needed for you to master the learning objectives of this course.&#160;You should now be ready for the final exam!</p><p>This final exam has two parts.&#160; Be sure to complete and submit both parts on the next two pages to finish this activity.</p></section><section><h3>Final Exam - Part 1</h3><p>Final Exam - Part 1</p><p>Answer Key:Off</p><p>ABCABC</p><p>Directions:&#160;Read each question carefully and then choose the correct answer.</p><p>Customers who are consistently delighted tend to remain engaged with the brand over time, creating opportunities for cross-selling and upselling.&#160;Which key aspect of the ideal customer state does this describe?</p><p>Customer loyalty and retention</p><p>Competitive advantage</p><p>Increased customer lifetime value</p><p>Enhanced brand reputation</p><p>After customer service calls, customers take a short survey, which produces a CES score.&#160;What would low CES scores indicate?&#160;Select all that apply.</p><p>The customer experienced a number of issues or pain points when trying to resolve their problem.</p><p>The customer had an easy experience on their call.</p><p>The customer service was smooth and the customer was satisfied.</p><p>The customer had to put forth a lot of effort to get their issue resolved.</p><p>What is the primary aim of the &quot;7 to Get to 1&quot; brainstorming approach?</p><p>To immediately choose the best idea from the start without further discussion</p><p>To limit the brainstorming session to just seven ideas only</p><p>To focus on only one idea throughout the entire session</p><p>To explore a wide array of ideas and eventually consolidate them into a single, optimal solution</p><p>Which looping concept involves generating, refining, and selecting ideas through a cyclical process to foster creativity and innovation?</p><p>Ideation Loop</p><p>Implementation Loop</p><p>Empathy Loop</p><p>Experimentation Loop</p><p>Which process is repeated multiple times to ensure that solutions thoroughly address the identified problems?</p><p>Customer support data</p><p>Iterative refinement</p><p>Product usage analytics</p><p>Empathy mapping</p><p>A manufacturing company carried out detailed customer observations and found that outdated machinery was creating major bottlenecks in their production line.&#160;The company decided to invest in new equipment.&#160;What are the expected outcomes of this decision?&#160;Select all that apply.</p><p>Production efficiency improved, leading to lower operational costs.</p><p>Employee satisfaction increased, as the upgraded equipment made tasks easier.</p><p>The new machinery caused a decline in product quality.</p><p>Operational costs rose without any corresponding improvements in efficiency.</p><p>In which phase of formulating an ideal state statement would you explain the emotional impact of the customer experience?</p><p>Incorporate emotional elements</p><p>Assess technical specifications</p><p>Establish operational goals</p><p>Set performance metrics</p><p>Which metric assesses the likelihood that customers would recommend a product or service to others?</p><p>Net Promoter Score</p><p>Customer Effort Score</p><p>Customer Satisfaction Score</p><p>Customer Retention Rate</p><p>The software development team is working on refining a new app based on user feedback from the initial release.&#160;They are focused on making ongoing enhancements to address user concerns and improve the app&#39;s performance.&#160;What is this process called?</p><p>Launching</p><p>Scaling</p><p>Continuous improvement</p><p>Iteration</p><p>Which principle of Intuit’s Design for Delight (D4D) emphasizes profoundly understanding the needs, motivations, and experiences of customers, including their latent needs?</p><p>Deep Customer Empathy</p><p>Go Broad to Go Narrow</p><p>Surface-Level Understanding</p><p>Rapid Experiments with Customers</p><p>Which section of idea documentation outlines the advantages for customers and how the idea stands out from existing options?</p><p>Problem statement</p><p>Idea description</p><p>Value proposition</p><p>Solution overview</p><p>What is the primary goal of immersive observation?</p><p>To collect quantitative data about customer behaviors</p><p>To observe and understand how customers interact with products in their natural environment</p><p>To test new product features in a controlled environment</p><p>To gather feedback through surveys and questionnaires</p><p>Carlos, a UX researcher, invites a group of users to navigate through a new e-commerce app to observe any challenges they encounter.&#160;What type of direct observation is Carlos conducting?</p><p>Usage analytics</p><p>In-home visit</p><p>Usability testing</p><p>Screen recording</p><p>What makes brainstorming an effective tool for enhancing employee motivation and engagement?</p><p>It focuses on assigning tasks based on hierarchical positions rather than input from all team members.</p><p>It provides individuals with a chance to contribute to the problem-solving process, increasing enthusiasm and dedication.</p><p>It requires employees to work independently on separate tasks without collaboration.</p><p>It emphasizes performance evaluations during the idea generation phase.</p><p>What activities are typically conducted during the Empathize phase when aiming for the Ideal Customer State?&#160;Select all that apply.</p><p>In-depth research</p><p>Product testing</p><p>Customer interviews or surveys</p><p>Market analysis</p><p>Observation provides a _____ understanding of a customer&#39;s interaction with a product, taking into account the environment and other simultaneous actions.</p><p>contextual</p><p>hypothetical</p><p>abstract</p><p>numerical</p><p>A smart home security system is facing customer complaints.&#160;Users are experiencing issues with delayed notifications, difficulty in setting up the devices, poor video quality on security cameras, and limited compatibility with other smart home devices.&#160;These problems are leading to security concerns and some users considering switching to a different system.&#160;Which of these challenges would you consider the most critical to address first?</p><p>Improve the setup process to make it more user-friendly and straightforward.</p><p>Fix the delayed notifications to ensure users receive timely aler<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Intuit Design for Delight lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Intuit Design for Delight interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('edc2a4a3998ad4f86b1964c5f90fa462','intuit-design-for-delight-course-mastery-assessment','6a38e82cd5ec78ca048ad9150b7431e4','Course Mastery Assessment','assessment',30,'<h2>Course mastery assessment</h2><p>Bring together knowledge and application from the complete course. Achieve at least 80% to satisfy the assessment requirement for certification.</p>',NULL,1,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO assessments (id,slug,course_id,title,pass_mark,questions) VALUES ('b6f39206ba0a54708ea39dedb2c61dc3','intuit-design-for-delight-course-mastery-assessment','92a4f5cdddc7f69042b22cbdf20f300f','Intuit Design for Delight Course Mastery Assessment',80,CAST('[{"id":"intuit-design-for-delight-course-mastery-assessment-q1","type":"multiple-choice","prompt":"Before starting a practical task in Intro, which action best demonstrates professional judgement?","options":["Clarify the intended outcome, constraints, and success criteria before choosing tools.","Choose the fastest tool and define the goal afterward.","Copy the first available example without checking its fit.","Begin production immediately and leave requirements for final review."],"answer":"Clarify the intended outcome, constraints, and success criteria before choosing tools.","explanation":"Strong practice begins with a clear outcome, constraints, and measurable success criteria.","clue":"Think about what must be understood before execution begins."},{"id":"intuit-design-for-delight-course-mastery-assessment-q2","type":"multiple-choice","prompt":"A first attempt in Design for Delight Concept does not meet the requirement. What is the strongest next step?","options":["Compare the result with the criteria, identify the cause, revise, and test again.","Submit the attempt unchanged because the task is complete.","Replace the criteria with measures the attempt already meets.","Discard all evidence and restart without diagnosing the issue."],"answer":"Compare the result with the criteria, identify the cause, revise, and test again.","explanation":"An evidence-led improvement cycle diagnoses the gap before a focused revision and retest.","clue":"Use feedback and evidence to improve the next attempt."},{"id":"intuit-design-for-delight-course-mastery-assessment-q3","type":"multiple-choice","prompt":"Which evidence most credibly demonstrates applied competence in Customer Empathy Part 1?","options":["A completed work sample with decisions, checks, feedback, and reflection documented.","A claim that the topic was understood without a work sample.","A list of tools with no explanation of how they were used.","An unfinished draft that has not been checked against requirements."],"answer":"A completed work sample with decisions, checks, feedback, and reflection documented.","explanation":"Competence is best demonstrated through completed, reviewed evidence and reflective reasoning.","clue":"Choose evidence that shows both the result and how quality was established."},{"id":"intuit-design-for-delight-course-mastery-assessment-q4","type":"multiple-choice","prompt":"When work in Customer Empathy Part 2 could affect people, data, safety, or the environment, what should the learner do?","options":["Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","Proceed without checks when the intended outcome is positive.","Treat ethical and safety considerations as optional after delivery.","Hide known limitations so stakeholders remain confident."],"answer":"Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","explanation":"Responsible practice makes risk, consent, standards, and safeguards part of the work itself.","clue":"Professional quality includes the impact of the work, not only the output."},{"id":"intuit-design-for-delight-course-mastery-assessment-q5","type":"multiple-choice","prompt":"How should a learner transfer skills from Brainstorming & Narrowing to a new workplace or project context?","options":["Analyse the new context, adapt the method, test assumptions, and evaluate the result.","Repeat the original steps unchanged regardless of context.","Use only familiar methods and ignore new constraints.","Wait for a complete example to copy before making any decision."],"answer":"Analyse the new context, adapt the method, test assumptions, and evaluate the result.","explanation":"Transfer requires adapting core principles to new constraints and validating the result.","clue":"Core principles remain useful, but their application must fit the new context."}]' AS JSON)) ON DUPLICATE KEY UPDATE title=VALUES(title),pass_mark=VALUES(pass_mark),questions=VALUES(questions);
INSERT INTO courses (id,slug,academy_id,moodle_id,title,description,level,duration,price,is_free,status)
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('9ead140276b193a8fa4fa1ab50e0681b','career-exploration-module-0','68d48b60cc4feb626956ed1fd8311e46','Module 0: Introduction, Purpose, Objectives, Summary',0) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('861e235a9d424d04541ece5c76e86714','career-exploration-m0-l1-introduction-purpose-and-objectives','9ead140276b193a8fa4fa1ab50e0681b','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Course Intro Nav Objectives Syllabus</h3><p>Course Intro Video</p><p>This course on Career Exploration introduces students to a wide variety of career pathways. Just like reading a map before embarking on a journey, learning about different careers can provide students with a clearer direction for their future, enabling them to identify their interests, strengths, and the necessary skills they need to develop. Giving students exposure to an array of potential careers can help them become adaptable and versatile, preparing them not just for specific jobs, but for a future where many roles are yet to be known.</p><p>Being aware of the possibilities helps students make informed decisions. They can start to develop a plan for future career preparation. Understanding the abilities, technical skills, and education required for various career paths will prepare students for the challenges ahead. It will equip them with the knowledge they need to chart their own path. Ultimately, by exploring the diverse world of careers, students can begin to envision their future, and take the first steps toward turning their dreams into reality.</p><p>Course Navigation</p><p>Welcome to this course on Career Exploration!&#160;To get you started in Module 0, we have included the video below, which provides some navigation help and other details about the course.</p><p>Other sections of this Module 0 include the Course Syllabus and a Syllabus Quiz, so read&#160;through the syllabus carefully and thoroughly!</p><p>Hi and welcome to this orientation video for this course. As we go through this video, some details may differ depending on which course you are taking and the learning management system, or LMS, that your school uses, but the overall structure generally stays the same for each course.</p><p>After you complete this navigation tutorial video for module zero you should read through the course objectives, a section on sources and plagiarism, the syllabus, and finally take the syllabus quiz. Now, a few things on navigation. Within each section, you can navigate between pages either with the menu here on the left, or with the left/right arrows near the bottom. Again, that will allow you to move between PAGES within each section. Once you are done with all the pages in a section, you can either select home at the top of the course. Or you can select “Next” at the very bottom of the page to the next section. It’s very important to make sure you finish every page within a section BEFORE moving to the next section.</p><p>Ok, once you are done with Module 0, you&#39;ll move on to start your first module. Within each module there is an introduction, somewhere between 4 and 6 lessons, and then a summary and assessments at the end. First, within the introduction, if you select it, it should look something like this. Each module will start at this page which contains a 30 to 60 second introductory video that will introduce and discuss some of the concepts that you&#39;ll learn and review during this module. Let’s talk about the videos. You can also turn closed captioning on or off by clicking the CC button. Next is the setting button, where you can adjust the speed that the videos will play. Maybe you like to hear things a little faster at 1.25x. Or maybe there is a concept that is difficult, and you would like to slow down. These next two icons allow the video window to pop out, or for the video window to go full-screen. For many videos, there will also be a transcript of the video below.</p><p>The next page is a description of the module. Then we move on to objectives which explains what the student will learn during this module. Next there is typically is a polling question. Sometimes this appears at the beginning of a module and sometimes it appears at the end. But it&#39;s just a way to take a guess or to voice your opinion on a certain issue and you can click on whichever you&#39;d like and see how your answer compares to your classmates.</p><p>You will next come to a vocabulary activity. Most of these will also be at the beginning as a formative assessment, meaning that you aren&#39;t expected to know the answers but take your best guess as this is an ungraded quiz. For instance, you can pick a word drag it over and then check your answer to see that it was incorrect you keep trying again and see if you can get them all lined up. Again, this allows you to just familiarize yourself with the various vocabulary words that will be introduced in this module. Alternatively you can select on the alternative activity and it&#39;s more of a multiple choice format. So again this is an ungraded quiz. You can close it out right there. Next, we move to the lessons. As said before, there are 4 to 6 lessons within each module. So you&#39;ll see each lesson represents more or less a day&#39;s worth of work and contains a video, a reading, and then either a concept check or reflection. As you will learn in the syllabus, the introduction, video, and reading pages are graded on participation, meaning you get credit for going through every page and activity in the module. Your school may or may not be using participation, so please check with your instructor on whether or not you will be receiving participation credit in your course.</p><p>The videos and their functionality we have already talked about. Next we go into the readings which obviously will have additional content and details to read. It will also frequently contain images as well as embedded videos. These are videos that add a lot of visual detail to the materials and again just hitting play there. Some videos are longer, so we try to limit video clips to 2 to 5 minutes, so in some cases you will only see a small clip of a larger video.</p><p>After the video and reading is a concept check or reflection where you&#39;ll either input an answer or work with flashcards or maybe a sorting exercise to review and firm up the concepts that were taught in that section. The reflections are either journal entry or discussion prompts. To participate in class-wide discussion, you’ll select this link to read the questions or prompts, and then participate in the discussion by adding a new discussion topic and eventually commenting on posts from other students.&#160;You&#39;ll see this repeat itself through the rest of the sections. After which you&#39;ll find a quick summary. Once you are finished with each lesson, you see three more assignments here: the sho<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('bc1f48a18151d4292fb1ac82263797c8','career-exploration-module-1','68d48b60cc4feb626956ed1fd8311e46','Module 1: Agri Food NR',1) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c0f463f7d19d6a7515998817b9e072b0','career-exploration-m1-l1-introduction-purpose-and-objectives','bc1f48a18151d4292fb1ac82263797c8','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Mute</p><p>Hello and welcome to this course on Career Exploration. I’m Mr. Southwick, and I’ll be one of your instructors, introducing many modules throughout the course.</p><p>Let’s get started with this module on the Agriculture, Food, &amp; Natural Resources career cluster. This career cluster is all about growing, producing, and taking care of the food that we eat and the natural resources that we use. It includes things like farmers who grow fruits and vegetables; ranchers who raise animals; and foresters who take care of the forests. It also includes scientists who create new ways to grow food, people who work in factories to make food, and people who help to make sure that the environment is healthy.</p><p>Without people working in this career cluster, we’d all be on our own to grow our own food. Some of our natural resources would be gone completely because no one would be monitoring the availability of those resources. We&#39;d be without fruit, vegetables, meat, and even all those packages of cereal, chips, cookies, and other snack foods. So, it’s pretty easy to see that this career cluster is extremely important!</p><p>We&#39;ll start by exploring the pathways in the Agriculture, Food &amp; Natural Resources career cluster and the careers in each pathway, so you can have a clear idea of what job titles fall into this cluster.</p><p>You&#39;ll learn about where people in this cluster find jobs. You’ll discover why some, but not all, workers in this industry work outside.</p><p>The module will also give you an overview of the sort of activities people in this cluster perform. This way, you can see if the actual work done is something you would want to spend your time doing in the future. We&#39;ll also discuss the necessary skills, abilities, and talents needed for successful careers in the Agriculture, Food &amp; Natural Resources career cluster. You&#39;ll learn about the level of training and education required for these careers.</p><p>So, let’s get ready to learn about the Agriculture, Food, and Natural Resources career cluster!</p><p>Module Description</p><p>Shutter Stock</p><p>License: All Rights Reserved</p><p>In this module on Agriculture, Food &amp; Natural Resources, we will be exploring the different pathways and careers within this cluster. This includes pathways such as plant systems, &#160;as well as the places that employ individuals with these jobs, the variety of tasks they perform, and the skills, abilities, and talents needed in order to be successful. We will also be discussing the level of training and education required for these jobs. At the end of the module, you will have the opportunity to do some hands-on learning with a module project.</p><p>Objectives</p><p>In this module, students will</p><p>Identify the pathways in the Agriculture, Food &amp; Natural Resources career cluster and the careers in each pathway.</p><p>Describe the types of places that employ individuals who have careers in the Agriculture, Food &amp; Natural Resources career cluster.</p><p>Describe the variety of tasks performed by individuals who have careers in the Agriculture, Food &amp; Natural Resources career cluster.</p><p>List the skills, abilities, and talents needed for careers in the Agriculture, Food &amp; Natural Resources career cluster.</p><p>Identify the level of training and education required for careers in the Agriculture, Food &amp; Natural Resources career cluster.</p><p>Research a career in the Agriculture, Food &amp; Natural Resources career cluster and present findings to the class.</p><p>Apply math, science, and reading skills in the completion of a project or activity related to the Agriculture, Food &amp; Natural Resources career cluster.</p><p>Polling Question</p><p>Which career in the Agriculture, Food &amp; Natural Resources Career Cluster sounds most interesting to you?</p><p>Food scientist&#160;Veterinarian&#160;Park ranger&#160;Environmental scientist&#160;Other</p><p>Results:</p><p>Park ranger&#160;100%</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Warning:&#160;json_decode() expects parameter 1 to be string, object given in&#160;/srv/app/current/blocks/interactive_definitions/controller.php&#160;on line&#160;238</p><p>Growing plants and raising animals to produce food, fiber, and other products.</p><p>Forestry</p><p>Anything in nature that humans can use, like air, water, soil, plants, and animals.</p><p>Environmental Science</p><p>The business of producing and selling agricultural products like crops and livestock.</p><p>Conservation</p><p>Working with forests, which includes taking care of the trees, plants, and animals that live there.</p><p>Animal science</p><p>The study of how to make food safe and nutritious, and how to keep it that way.</p><p>Agribusiness</p><p>Taking care of natural resources and the environment, like using resources wisely and not wasting them.</p><p>Food Science</p><p>The study of animals and how to take care of them.</p><p>Natural Resources</p><p>The study of how people and natural resources interact with each other and how to protect the environment.</p><p>Agriculture</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Growing plants and raising animals to produce food, fiber, and other products.</p><p>Answers for question: 1</p><p>Natural Resources</p><p>Agribusiness</p><p>Food Science</p><p>Agriculture</p><p>Conservation</p><p>Forestry</p><p>Animal science</p><p>Environmental Science</p><p>2.</p><p>Anything in nature that humans can use, like air, water, soil, plants, and animals.</p><p>Answers for question: 2</p><p>Animal science</p><p>Food Science</p><p>Natural Resources</p><p>Forestry</p><p>Agriculture</p><p>Environmental Science</p><p>Agribusiness</p><p>Conservation</p><p>3.</p><p>The business of producing and selling agricultural products like crops and livestock.</p><p>Answers for question: 3</p><p>Environmental Science</p><p>Animal science</p><p>Food Science</p><p>Forestry</p><p>Natural Resources</p><p>Conservation</p><p>Agriculture</p><p>Agribusiness</p><p>4.</p><p>Working with forests, which includes taking care of the trees, plants, and animals that live there.</p><p>Answers for question: 4</p><p>Food Science</p><p>Natural Resources</p><p>A<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8518bace84fb25d7929cb54da1c9f38d','career-exploration-m1-l2-lesson-1','bc1f48a18151d4292fb1ac82263797c8','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>What is Agri, Food, NR Career Cluster</h3><p>What is Agri, Food, NR Career Cluster</p><p>What is the Agriculture, Food &amp; Natural Resources Career Cluster?</p><p>The Agriculture, Food, and Natural Resources career cluster is a group of jobs that involve growing food, taking care of the environment, and managing natural resources.&#160;These jobs involve a variety of activities including growing crops, managing forests, caring for animals, and protecting the environment.</p><p>Pathways</p><p>The Agriculture, Food, &amp; Natural Resources Career Cluster is broken down into five pathways or systems.&#160;Click through the flashcards with images to learn more about each one.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>&#171; Back</p><p>Agribusiness SystemsJobs in this pathway involve managing and running businesses related to agriculture and food production, such as farms, food processing, and retail.</p><p>Animal SystemsJobs in this pathway involve working with animals and animal products, such as livestock and pet care, animal breeding, and veterinary medicine.</p><p>Environmental Service SystemsJobs in this pathway involve creating a sustainable environment such as pollution prevention and environmental analysis.</p><p>Food Products and Processing SystemsJobs in this pathway involve processing and distributing food, such as food production, food safety, and food service.</p><p>Plant SystemsJobs in this pathway involve growing and maintaining plants, such as horticulture, plant science, and landscaping.</p><p>Natural Resources SystemsJobs in this pathway involve managing, conserving, and protecting the natural environment, such as water, land, and energy conservation.</p><p>Power, Structural &amp; Technical SystemsJobs in this pathway involve applying engineering, electronics, power, and structure to agriculture, such as agricultural structure design and agricultural equipment development.</p><p>⟳ Flip Card</p><p>Next &#187;</p><p>Flashcard&#160;1&#160;of&#160;7</p><p>Flashcard Transcript</p><p>Careers in the Agriculture, Food &amp; Natural Resources Career Cluster</p><p>Each of the pathways includes a variety of careers.&#160;See if you can match each set of careers to the correct pathway!</p><p>Warning:&#160;json_decode() expects parameter 1 to be string, object given in&#160;/srv/app/current/blocks/interactive_definitions/controller.php&#160;on line&#160;238</p><p>farmers, grocery store managers, or food marketers</p><p>Agribusiness Systems</p><p>veterinarians, animal trainers, or animal nutritionists</p><p>Environmental Service Systems</p><p>environmental scientists, waste management specialists, and environmental planners.</p><p>Natural Resources Systems</p><p>chefs, food processors, or food safety inspectors</p><p>Food Products and Processing Systems</p><p>gardeners, landscapers, or plant scientists</p><p>Power, Structural, &amp; Technical Systems</p><p>conservationists, foresters, or natural resources managers</p><p>Animal Systems</p><p>agricultural engineers, farm equipment technicians, or agricultural applications software developers</p><p>Plant Systems</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>farmers, grocery store managers, or food marketers</p><p>Answers for question: 1</p><p>Natural Resources Systems</p><p>Agribusiness Systems</p><p>Plant Systems</p><p>Animal Systems</p><p>Environmental Service Systems</p><p>Food Products and Processing Systems</p><p>Power, Structural, &amp; Technical Systems</p><p>2.</p><p>veterinarians, animal trainers, or animal nutritionists</p><p>Answers for question: 2</p><p>Environmental Service Systems</p><p>Plant Systems</p><p>Animal Systems</p><p>Natural Resources Systems</p><p>Power, Structural, &amp; Technical Systems</p><p>Food Products and Processing Systems</p><p>Agribusiness Systems</p><p>3.</p><p>environmental scientists, waste management specialists, and environmental planners.</p><p>Answers for question: 3</p><p>Natural Resources Systems</p><p>Environmental Service Systems</p><p>Animal Systems</p><p>Food Products and Processing Systems</p><p>Power, Structural, &amp; Technical Systems</p><p>Agribusiness Systems</p><p>Plant Systems</p><p>4.</p><p>chefs, food processors, or food safety inspectors</p><p>Answers for question: 4</p><p>Food Products and Processing Systems</p><p>Natural Resources Systems</p><p>Animal Systems</p><p>Plant Systems</p><p>Power, Structural, &amp; Technical Systems</p><p>Agribusiness Systems</p><p>Environmental Service Systems</p><p>5.</p><p>gardeners, landscapers, or plant scientists</p><p>Answers for question: 5</p><p>Environmental Service Systems</p><p>Natural Resources Systems</p><p>Agribusiness Systems</p><p>Food Products and Processing Systems</p><p>Animal Systems</p><p>Power, Structural, &amp; Technical Systems</p><p>Plant Systems</p><p>6.</p><p>conservationists, foresters, or natural resources managers</p><p>Answers for question: 6</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ffad9eba7c30319d38c6a484b1a53733','career-exploration-m1-l3-lesson-2','bc1f48a18151d4292fb1ac82263797c8','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Agri, Food, NR Career Cluster Work</h3><p>Agri, Food, NR Career Cluster Work</p><p>Where People in the Agriculture, Food, &amp; Natural Resources Career Cluster Work</p><p>Just like there are a variety of jobs within the Agriculture, Food, &amp; Natural Resources career cluster, there are many places of employment as well.&#160;Click through the flashcards to learn about some of the work locations for this career cluster.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>People who work at farms grow and take care of crops and animals.</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;8</p><p>Next</p><p>People who work at grocery stores help ensure shoppers can find the foods they need.</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;8</p><p>Next</p><p>People who work at food processing plants help prepare and package food for people to buy.</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;8</p><p>Next</p><p>People who work agricultural research institutes study plants and animals to improve farming and food products.</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;8</p><p>Next</p><p>People who work at livestock production facilities work with livestock animals such as cows, sheep, and chickens, to generate products from those livestock to sell. ork with livestock animals such as cows, sheep, and chickens, to generate products from those livestock to sell.</p><p>Previous</p><p>Slide&#160;5&#160;of&#160;8</p><p>Next</p><p>People who work at fisheries raise or harvest fish for commercial use.</p><p>Previous</p><p>Slide&#160;6&#160;of&#160;8</p><p>Next</p><p>People who work at national parks ensure the safety and health of the land, wildlife, and visitors.</p><p>Previous</p><p>Slide&#160;7&#160;of&#160;8</p><p>Next</p><p>People who work here care for plants and assist people interested in purchasing plants.</p><p>Previous</p><p>Slide&#160;8&#160;of&#160;8</p><p>Next</p><p>People who work in the agriculture industry help provide food for people to buy by growing, taking care of, and processing crops and animals, as well as researching ways to improve them.&#160;They work in places such as farms, grocery stores, food processing plants, agriculture research institutions, livestock production facilities, fisheries, national parks, and plant nurseries.&#160;So whether you like working inside or prefer the great outdoors, you can find a work environment that excites you.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1db2900ddc257612b694ad57048e5b4a','career-exploration-m1-l4-lesson-3','bc1f48a18151d4292fb1ac82263797c8','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Activities of Agri, Food, NR Career</h3><p>Activities of Agri, Food, NR Career</p><p>Activities in the Agriculture, Food &amp; Natural Resources Career Cluster</p><p>People who work in the Agriculture, Food &amp; Natural Resources Career Cluster participate in a variety of activities.&#160;We can divide these activities into seven categories:</p><p>Planting and Growing</p><p>Planting seeds and plants, tending to crops, managing soil, crop rotation, and harvesting.</p><p>Animal Care</p><p>Feeding, grooming, and caring for animals such as cows, chickens, and horses.</p><p>Food Production</p><p>Processing food, manufacturing food products, and packaging.</p><p>Conservation and Preservation</p><p>Protecting natural resources, cleaning up polluted areas, and preventing animal extinction.</p><p>Outdoor work</p><p>Building and maintaining fences, clearing land, and cutting trees.</p><p>Machinery Operation</p><p>Operating tractors, combine harvesters, and other farm equipment.</p><p>Business and Financial Management</p><p>Selling crops, managing budgets, and working with other businesses.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('476929816d02ef60e09525ee582677ad','career-exploration-m1-l5-lesson-4','bc1f48a18151d4292fb1ac82263797c8','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Need Skills for Agri, Food, NR Careers</h3><p>Need Skills for Agri, Food, NR Careers</p><p>Skills, Abilities, and Talents Needed for a Career in Agriculture, Food &amp; Natural Resources</p><p>There are many jobs in the Agriculture, Food &amp; Natural Resources Career Cluster.&#160;Each career will require special skills and abilities.&#160;However, there are a few skills that many of the careers in the cluster require.</p><p>For example, whether you are trying to figure out what is harming the crops on a farm or the capacity of people at a national park, you need to use problem-solving means to think through a problem and come up with a good solution.</p><p>You need to be able to use tools and equipment to do things like plant and harvest crops.&#160;Knowing how this machinery works and how to properly operate it, not only makes the job go faster, it keeps you safe.</p><p>Good communication skills help you explain and discuss your work.&#160;It allows you to educate others on important issues like conservation, nutrition, and animal care.</p><p>In order to improve the environment, find new ways to use resources, and understand our agricultural products, research is important.&#160;Gathering more information allows us to make new discoveries and improvements.</p><p>Many of the jobs in this cluster involve working with animals.&#160;Farmers, for example, must be able to safely handle and care for each animal on the farm.</p><p>Another skill many jobs use in this career cluster is teamwork.&#160;Restaurants, agricultural businesses, and research facilities all rely on team members fulfilling their own unique responsibilities to help the entire group.</p><p>Many people in this industry start their own businesses.&#160;This includes landscapers, farmers, and ranchers.&#160;To run a successful business, it&#39;s essential to have foundational business skills.</p><p>Finally, many of these jobs require knowledge about the soil and the environment.&#160;This enables individuals to know which plants and animals will flourish in certain conditions.</p><p>Read the scenario below and match it to the skills you think would be most helpful:</p><p>A park ranger needs to figure out how many people can visit the park while still maintaining the health of the park’s natural environment.</p><p>Research</p><p>A food scientist wants to investigate the effectiveness of potassium sorbate in helping strawberries last longer.</p><p>Communication</p><p>A farmer needs to use a tractor to prepare the ground for planting.</p><p>Ability to work with animals</p><p>A conservationist wants to educate local schools about the declining bee population in the area.</p><p>Knowledge of soil and the environment</p><p>An alpaca farmer needs to safely sheer the herd to sell their fleece.</p><p>Business management</p><p>A farmer is trying to decide which crop would grow best in Pella, Iowa.</p><p>Problem-solving</p><p>A chef, a line cook, and a server need to make sure everyone receives the correct order on a busy Saturday night.</p><p>Teamwork</p><p>A landscaper wants to start her own business in her local city.</p><p>Operate Machinery</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>A park ranger needs to figure out how many people can visit the park while still maintaining the health of the park’s natural environment.</p><p>Answers for question: 1</p><p>Operate Machinery</p><p>Knowledge of soil and the environment</p><p>Business management</p><p>Ability to work with animals</p><p>Problem-solving</p><p>Communication</p><p>Teamwork</p><p>Research</p><p>2.</p><p>A food scientist wants to investigate the effectiveness of potassium sorbate in helping strawberries last longer.</p><p>Answers for question: 2</p><p>Operate Machinery</p><p>Problem-solving</p><p>Ability to work with animals</p><p>Teamwork</p><p>Knowledge of soil and the environment</p><p>Communication</p><p>Research</p><p>Business management</p><p>3.</p><p>A farmer needs to use a tractor to prepare the ground for planting.</p><p>Answers for question: 3</p><p>Research</p><p>Operate Machinery</p><p>Business management</p><p>Teamwork</p><p>Problem-solving</p><p>Knowledge of soil and the environment</p><p>Ability to work with animals</p><p>Communication</p><p>4.</p><p>A conservationist wants to educate local schools about the declining bee population in the area.</p><p>Answers for question: 4</p><p>Research</p><p>Business management</p><p>Operate Machinery</p><p>Teamwork</p><p>Ability to work with animals</p><p>Problem-solving</p><p>Communication</p><p>Knowledge of soil and the environment</p><p>5.</p><p>An alpaca farmer needs to safely sheer the herd to sell their fleece.</p><p>Answers for question: 5</p><p>Research</p><p>Problem-solving</p><p>Business management</p><p>Ability to work with animals</p><p>Teamwork</p><p>Knowledge of soil and the environment</p><p>Operate Machinery</p><p>Communication</p><p>6.</p><p>A farmer is trying to decide which crop would grow best in Pella, Iowa.</p><p>Answers for question: 6</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('666b89cecb60af5d9c372f4d0ed971df','career-exploration-m1-l6-lesson-5','bc1f48a18151d4292fb1ac82263797c8','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Training Education Requirements</h3><p>Training Education Requirements</p><p>Training and Education Requirements</p><p>Agriculture, Food, and Natural Resources is an incredibly broad career cluster with many different careers.&#160;Each of these careers will require certain types of training and education.&#160;Let’s take a look at some of the types of classes you will want to take, depending on the type of job in this career cluster that interests you.&#160;Click on the hotspot on each image to learn more:</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Image depicting the various areas of study in the Agriculture, Food &amp; Natural Resources Career Cluster.</p><p>The hotspot points on the image are as follows:</p><p>Animal science</p><p>You may need to take classes in biology, chemistry, mathematics, and animal anatomy and physiology. You may also need to take courses in animal nutrition, reproduction, and genetics.</p><p>Environmental science or natural resources management</p><p>You may need to take classes in earth science, hydrology, geology, ecology, and environmental law.</p><p>Food science</p><p>You may need to take classes in chemistry, nutrition, microbiology, food safety, and food engineering.</p><p>Plant science</p><p>You will likely need to take classes in plant biology, botany, and horticulture, as well as classes in plant physiology, ecology, and pest management.</p><p>Agricultural business</p><p>You may need to take classes in agricultural economics, finance, and marketing, as well as classes in agricultural law, accounting, and management.</p><p>Some of the careers in this cluster require a degree from a college in order to find a job in that profession, such as a veterinarian.&#160;Other jobs require specialized certifications, such as a food safety inspector.&#160;However, it is possible to find a job in this profession right after high school.&#160;For example, an assistant on a farm may not need a formal degree or certificate, but instead, may receive on-the-job training.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('30a970a133d144032f839e97fac9af6b','career-exploration-m1-l7-module-1-summary','bc1f48a18151d4292fb1ac82263797c8','Module 1 Summary','text',12,'<h2>Module 1 Summary</h2><section><h3>Module 1 Summary</h3><p>Module 1 Summary</p><p>Great Work!&#160;You have successfully completed this module, Agriculture, Food &amp; Natural Resources.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified the pathways in the Agriculture, Food &amp; Natural Resources career cluster and the careers in each pathway.</p><p>Described the types of places that employ individuals who have careers in the Agriculture, Food &amp; Natural Resources career cluster.</p><p>Described the variety of tasks performed by individuals who have careers in the Agriculture, Food &amp; Natural Resources career cluster.</p><p>Listed the skills, abilities, and talents needed for careers in the Agriculture, Food &amp; Natural Resources career cluster.</p><p>Identified the level of training and education required for careers in the Agriculture, Food &amp; Natural Resources career cluster.</p><p>Researched a career in the Agriculture, Food &amp; Natural Resources career cluster and present findings to the class.</p><p>Applied math, science, and reading skills in the completion of a project or activity related to the Agriculture, Food &amp; Natural Resources career cluster.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1ee1f7b4566848a0fe27e077a3428c9d','career-exploration-m1-l8-module-1-project','bc1f48a18151d4292fb1ac82263797c8','Module 1 Project','text',12,'<h2>Module 1 Project</h2><section><h3>Module 1 Project</h3><p>Module 1 Project</p><p>Career Exploration</p><p>Agriculture, Food &amp; Natural Resources - Project</p><p>For this project, you will choose from two options.&#160; You only need to complete one of these options.&#160; Please find both options and their rubrics below.</p><p>Option 1</p><p>For this option, you will learn more about edible plants that grow in your area. Complete the following steps for your project:</p><p>Step 1: Research herbs, vegetables, and fruits that grow in your area.</p><p>Step 2: Pick two or more of the edible plants and find a recipe that uses both plants (or create your own recipe!)</p><p>Step 3: Prepare the recipe and show the finished food by taking a picture and submitting it with this assignment.</p><p>Your final submission should include the two or more edible plants you researched, the recipe, and a photo of the food you created!</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 1 Rubric: Agriculture, Food &amp; Natural Resources Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Research</p><p>10 points The student correctly identified 2 native edible plants.</p><p>5 points The student correctly identified 1 native edible plant.</p><p>0 points The student did not identify any native edible plants.</p><p>6</p><p>Recipe</p><p>10 points The student submitted a recipe containing the identified edible plants from the research.</p><p>5 points The student submitted a recipe containing one plant from the research.</p><p>0 points The student did not submit a recipe containing the edible plants from the research.</p><p>10</p><p>Photo</p><p>4 points The photo submitted shows the successfully completed recipe.</p><p>3 points The photo submitted shows the recipe was mostly successful.</p><p>0-2 points No photo was submitted and/or the recipe was not successfully made.</p><p>4</p><p>Total Points:&#160;20</p><p>Option 2</p><p>For this option, you will research a particular career that interests you in this cluster. Complete the following steps for your project:</p><p>Step 1: Research your chosen career.</p><p>Step 2: List the following</p><p>Average Salary/Salary Range</p><p>Education Requirements</p><p>Certification Requirements (if any)</p><p>Why you chose that career</p><p>Step 3: Prepare a PowerPoint presentation about your chosen career, including the information you gathered in Step 2 as well as your reason for choosing that career.</p><p>Your final submission should be your PowerPoint containing the information in Step 3.</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 2 Rubric: Agriculture, Food &amp; Natural Resources Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Research</p><p>12 points The student provided a career field that interested them, the average salary or range, and the education/certifications required for the career.</p><p>11-4 points The student provided two of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>3-0 points The student provided one or none of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>12</p><p>Reason for Choosing the Career Field</p><p>4 points The student thoughtfully provided the reason that they are interested in this career.</p><p>N/A</p><p>0 points The student did not provide the reason that they are interested in this career.</p><p>4</p><p>Formatting</p><p>4 points The student&#39;s presentation includes no spelling or grammatical errors.</p><p>3-1 points The student&#39;s presentation includes minimal spelling or grammatical errors.</p><p>0 points The student&#39;s presentation includes a significant amount of spelling or grammatical errors.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c4017077d17fc29cc563e32dde21ae34','career-exploration-m1-l9-module-1-quiz','bc1f48a18151d4292fb1ac82263797c8','Module 1 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Agri Food NR. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('94be6c44c6053c60a0a8d89a1929ee61','career-exploration-module-2','68d48b60cc4feb626956ed1fd8311e46','Module 2: Archit & Construct',2) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0d19c06a0f0ca5fde54bdfc6837635c2','career-exploration-m2-l1-introduction-purpose-and-objectives','94be6c44c6053c60a0a8d89a1929ee61','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Objectives Description</h3><p>Introduction</p><p>Welcome to this module on Architecture and Construction.</p><p>Architects and construction workers help create and maintain the built environment that we live in. Architects design buildings, homes, and other structures to meet the needs of society. Construction workers build these structures according to the designs, ensuring that they are safe and functional. Architects and construction workers have contributed to some of the most identifiable features on the earth such as the Eiffel Tower, TajMahal, Statue of Liberty, Big Ben, and the Colosseum. These structures prove that a well-built and designed structure can outlast those who built it by years, decades, and even centuries.</p><p>If the idea of leaving this sort of legacy excites you but you don’t know where to start- don’t worry! In this module we&#39;ll explore the various pathways in this career cluster. We’ll also talk about the careers each pathway, so if you have a job in this cluster in mind, you’ll have a clear idea of which pathway it falls under.</p><p>You will also learn about where people in the architecture and construction career cluster work and the various types of activities they perform.</p><p>Now, keep in mind that it’s never too early to start preparing for a career. As you learn about the necessary skills, abilities, and talents needed for successful careers in this cluster, you’ll be able to identify the skills and talents you already have, as well as identify some skills and talents you can develop.</p><p>Would you want to live in a house designed or by someone who had never designed so much as a bird house, let alone a house for a person? I didn’t think so! And neither does anyone else. That is why training and education in this cluster are so important. We’ll be sure to give you a solid understanding of training and education it takes to have a career in this field.</p><p>With all of that in mind, I hope you are excited to learn about the Architecture and Construction Career cluster.</p><p>Module Description</p><p>Welcome to this module on the Architecture &amp; Construction career cluster!&#160;In this module, you will discover the design, construction, and maintenance pathways in this cluster.&#160;We will discuss the types of places that employ individuals in this field and the variety of tasks they perform.&#160;You will also learn about the skills, abilities, and talents needed for careers in this field, as well as the level of training and education required for the different types of careers.&#160;After successfully completing the lessons in this module, you will have sufficient background knowledge to complete the end-of-module project which will give you further insight into the activities related to this career cluster.</p><p>Objectives</p><p>In this module, students will</p><p>Identify the pathways in the Architecture &amp; Construction career cluster and the careers in each pathway.</p><p>Describe the types of places that employ individuals who have careers in the Architecture &amp; Construction career cluster.</p><p>Describe the variety of tasks performed by individuals who have careers in the Architecture &amp; Construction career cluster.</p><p>List the skills, abilities, and talents needed for careers in the Architecture &amp; Construction career cluster.</p><p>Identify the level of training and education required for careers in the Architecture &amp; Construction career cluster.</p><p>Research a career in the Architecture &amp; Construction career cluster and present findings to the class.</p><p>Apply math, science, and reading skills in the completion of a project or activity related to the Architecture &amp; Construction career cluster.</p><p>Polling Question</p><p>Below are just a few of the exciting careers in the Architecture &amp; Construction career cluster.&#160;Select the job that sounds most interesting to you based on what you currently know:</p><p>Architect&#160;Construction worker&#160;Civil engineer&#160;Drafter&#160;Other</p><p>Results:</p><p>Construction worker&#160;100%</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Warning:&#160;json_decode() expects parameter 1 to be string, object given in&#160;/srv/app/current/blocks/interactive_definitions/controller.php&#160;on line&#160;238</p><p>The way a building or structure is designed and built, including the style, shape, and materials used.</p><p>Manufacturing</p><p>The process of building a structure or something, like a house or bridge, using materials like wood, metal, and concrete.</p><p>Municipality</p><p>The study of using science to create and design structures, machines, and other things.</p><p>Construction</p><p>The area of a city or town that is controlled by the local government.</p><p>Architecture</p><p>To make a drawing or plan of something.</p><p>Drafting</p><p>The process of making products in large quantities.</p><p>Engineering</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>The way a building or structure is designed and built, including the style, shape, and materials used.</p><p>Answers for question: 1</p><p>Drafting</p><p>Architecture</p><p>Engineering</p><p>Municipality</p><p>Construction</p><p>Manufacturing</p><p>2.</p><p>The process of building a structure or something, like a house or bridge, using materials like wood, metal, and concrete.</p><p>Answers for question: 2</p><p>Municipality</p><p>Manufacturing</p><p>Drafting</p><p>Engineering</p><p>Construction</p><p>Architecture</p><p>3.</p><p>The study of using science to create and design structures, machines, and other things.</p><p>Answers for question: 3</p><p>Engineering</p><p>Municipality</p><p>Construction</p><p>Architecture</p><p>Drafting</p><p>Manufacturing</p><p>4.</p><p>The area of a city or town that is controlled by the local government.</p><p>Answers for question: 4</p><p>Engineering</p><p>Municipality</p><p>Manufacturing</p><p>Drafting</p><p>Construction</p><p>Architecture</p><p>5.</p><p>To make a drawing or plan of something.</p><p>Answers for question: 5</p><p>Manufacturing</p><p>Architecture</p><p>Drafting</p><p>Municipality</p><p>Engineering</p><p>Construction</p><p>6.</p><p>The process of making products in large quantities.</p><p>Answers for question: 6</p><p<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0e58a593fff1fb341eb3badc308268bd','career-exploration-m2-l2-lesson-1','94be6c44c6053c60a0a8d89a1929ee61','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>What is Archt &amp; Constr Career Cluster</h3><p>What is Archt &amp; Constr Career Cluster</p><p>What is the Architecture &amp; Construction Career Cluster?</p><p>The Architecture &amp; Construction career cluster is all about creating and building the things that make our world comfortable and safe.&#160;Architecture refers to the way a building or structure is designed and built, including the style, shape, and materials used.&#160;Construction is the process of building a structure or something, like a house or bridge, using materials like wood, metal, and concrete.&#160;It includes three pathways:&#160;Design &amp; Drafting, Building Construction, Maintenance &amp; Operations.</p><p>Click on the hotspots below to learn more about each pathway:</p><p>5</p><p>Image Hotspots Transcript</p><p>No matter which pathway you choose, you can use your creativity and skills to build a better future for yourself and for the world.&#160;Categorize the careers below into the right pathway:</p><p>Design and Pre-Construction</p><p>Construction</p><p>Maintenance and Operations</p><p>Heavy Equipment Operator</p><p>Highway Maintenance Worker</p><p>Carpenter</p><p>Plumber</p><p>Civil Engineer</p><p>Surveyor</p><p>HVAC technician</p><p>Electrician</p><p>Architect</p><p>Construction Foreman</p><p>AC Repairer</p><p>Drafter</p><p>Alternative Activity</p><p>Categorize each of the following</p><p>HVAC technician&#160;Design and Pre-Construction&#160;Construction&#160;Maintenance and Operations</p><p>Electrician&#160;Design and Pre-Construction&#160;Construction&#160;Maintenance and Operations</p><p>Architect&#160;Design and Pre-Construction&#160;Construction&#160;Maintenance and Operations</p><p>Surveyor&#160;Design and Pre-Construction&#160;Construction&#160;Maintenance and Operations</p><p>Plumber&#160;Design and Pre-Construction&#160;Construction&#160;Maintenance and Operations</p><p>Carpenter&#160;Design and Pre-Construction&#160;Construction&#160;Maintenance and Operations</p><p>Heavy Equipment Operator&#160;Design and Pre-Construction&#160;Construction&#160;Maintenance and Operations</p><p>Drafter&#160;Design and Pre-Construction&#160;Construction&#160;Maintenance and Operations</p><p>Highway Maintenance Worker&#160;Design and Pre-Construction&#160;Construction&#160;Maintenance and Operations</p><p>Construction Foreman&#160;Design and Pre-Construction&#160;Construction&#160;Maintenance and Operations</p><p>AC Repairer&#160;Design and Pre-Construction&#160;Construction&#160;Maintenance and Operations</p><p>Civil Engineer&#160;Design and Pre-Construction&#160;Construction&#160;Maintenance and Operations</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a1ae6d76c92fad0e6be447a5ab44799a','career-exploration-m2-l3-lesson-2','94be6c44c6053c60a0a8d89a1929ee61','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Archit &amp; Constr Careers Cluster Work</h3><p>Archit &amp; Constr Careers Cluster Work</p><p>Where People in the Architecture &amp; Construction Career Cluster Work</p><p>As you’ve learned already, there are many career opportunities in the Architecture &amp; Construction Career Cluster.&#160;These professionals find work at many different places.&#160;Click on the items in the list below to learn more about some of the places of employment:</p><p>Architecture firms</p><p>A business where architects and designers work to design buildings like houses or skyscrapers.</p><p>Engineering firm</p><p>A business where engineers work to figure out how to make the designs from architects, drafters, and planners work in real life, like making sure the building is strong and safe.</p><p>Construction company</p><p>A business where construction workers build buildings designed by architects and engineers.</p><p>Municipalities</p><p>The local government in the area, like a city or a state. They hire workers to plan, design, and build government buildings, public parks, roads, and other structures the government is responsible for creating and maintaining.</p><p>Manufacturing Company</p><p>A business that makes products. They take raw materials and turn them into the things we use every day like furniture, cars, and appliances.</p><p>Now that you know a little about these places of employment, see if you can match each professional to their place of employment:</p><p>Warning:&#160;json_decode() expects parameter 1 to be string, object given in&#160;/srv/app/current/blocks/interactive_definitions/controller.php&#160;on line&#160;238</p><p>Place of Employment</p><p>Angela is working on designing a new office building downtown.</p><p>Engineering Firm</p><p>Olivia is on a team that is responsible for making sure the new bridge in town will be built safely.</p><p>Architecture Firm</p><p>Darren is the foreman overseeing the construction of a new home.</p><p>Municipality</p><p>Diego is a city planner and is responsible for a new park in the area.</p><p>Construction Company</p><p>Avery works on an assembly line for refrigerators.</p><p>Manufacturing Company</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Angela is working on designing a new office building downtown.</p><p>Answers for question: 1</p><p>Architecture Firm</p><p>Construction Company</p><p>Manufacturing Company</p><p>Municipality</p><p>Engineering Firm</p><p>2.</p><p>Olivia is on a team that is responsible for making sure the new bridge in town will be built safely.</p><p>Answers for question: 2</p><p>Construction Company</p><p>Architecture Firm</p><p>Municipality</p><p>Manufacturing Company</p><p>Engineering Firm</p><p>3.</p><p>Darren is the foreman overseeing the construction of a new home.</p><p>Answers for question: 3</p><p>Manufacturing Company</p><p>Architecture Firm</p><p>Engineering Firm</p><p>Municipality</p><p>Construction Company</p><p>4.</p><p>Diego is a city planner and is responsible for a new park in the area.</p><p>Answers for question: 4</p><p>Manufacturing Company</p><p>Construction Company</p><p>Architecture Firm</p><p>Engineering Firm</p><p>Municipality</p><p>5.</p><p>Avery works on an assembly line for refrigerators.</p><p>Answers for question: 5</p><p>Construction Company</p><p>Architecture Firm</p><p>Municipality</p><p>Engineering Firm</p><p>Manufacturing Company</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2f2ff67390ac15fb2b1ee623b51eeb47','career-exploration-m2-l4-lesson-3','94be6c44c6053c60a0a8d89a1929ee61','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Activities of Archit &amp; Constr Cluster</h3><p>Activities of Archit &amp; Constr Cluster</p><p>Activities in the Architecture &amp; Construction Career Cluster</p><p>A lot of work goes into making sure the structures around us are safe and operational.&#160;We need all kinds of workers in the Architecture &amp; Construction Career Cluster performing a variety of tasks to make it happen.&#160;Click on each tab to learn more about common tasks in this cluster.</p><p>Drafting</p><p>Creating plans and drawing building structures.</p><p>Carpentry</p><p>Constructing and installing wood for structures.</p><p>Masonry</p><p>Building structures using brick, concrete, and stone.</p><p>Plumbing</p><p>Installing and maintaining water systems.</p><p>Electrical</p><p>Installing and maintaining electrical systems.</p><p>HVAC</p><p>Installing and maintaining heating, ventilation, and air conditioning systems.</p><p>Roofing</p><p>Installing and maintaining roofs and the other structures on the roof such as gutters.</p><p>Landscaping</p><p>Installing and maintaining landscaping systems and plants</p><p>Next Tab</p><p>Now that you know about some of the tasks and activities in this career cluster, see if you can match the appropriate activity in the blank in the sentences below:</p><p>Warning:&#160;json_decode() expects parameter 1 to be string, object given in&#160;/srv/app/current/blocks/interactive_definitions/controller.php&#160;on line&#160;238</p><p>Sentence</p><p>Word to fill in the blank</p><p>Alvin is _________ a new bridge and will present his design on Friday.</p><p>Landscaping</p><p>Maria showed her great _________ skills when she built a new deck.</p><p>Drafting</p><p>The building is too cold, so we will have someone with expertise in _________ investigate the system.</p><p>Electrical</p><p>Because of the risk of electric shock, only a professional should perform ___________ activities.</p><p>Carpentry</p><p>Cables help keep crews safe when they are _________ at such great heights.</p><p>Plumbing</p><p>We need someone to do the ___________ for the kitchen remodel so the sink works properly.</p><p>HVAC</p><p>The community college’s class on _________ taught me how to create a brick pathway.</p><p>Roofing</p><p>Andy did a great job _________ the new sprinkler system without disturbing any of the plants!</p><p>Masonry</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Alvin is _________ a new bridge and will present his design on Friday.</p><p>Answers for question: 1</p><p>HVAC</p><p>Electrical</p><p>Roofing</p><p>Drafting</p><p>Carpentry</p><p>Landscaping</p><p>Plumbing</p><p>Masonry</p><p>2.</p><p>Maria showed her great _________ skills when she built a new deck.</p><p>Answers for question: 2</p><p>HVAC</p><p>Masonry</p><p>Landscaping</p><p>Roofing</p><p>Drafting</p><p>Electrical</p><p>Plumbing</p><p>Carpentry</p><p>3.</p><p>The building is too cold, so we will have someone with expertise in _________ investigate the system.</p><p>Answers for question: 3</p><p>Drafting</p><p>HVAC</p><p>Carpentry</p><p>Masonry</p><p>Plumbing</p><p>Roofing</p><p>Electrical</p><p>Landscaping</p><p>4.</p><p>Because of the risk of electric shock, only a professional should perform ___________ activities.</p><p>Answers for question: 4</p><p>Masonry</p><p>Landscaping</p><p>Roofing</p><p>Plumbing</p><p>Carpentry</p><p>HVAC</p><p>Electrical</p><p>Drafting</p><p>5.</p><p>Cables help keep crews safe when they are _________ at such great heights.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('269905110fe88f67b0bece60049da55f','career-exploration-m2-l5-lesson-4','94be6c44c6053c60a0a8d89a1929ee61','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Skills for Careers in Archit &amp; Constr</h3><p>Skills for Careers in Archit &amp; Constr</p><p>Skills, Abilities, and Talents Needed for a Career in Architecture &amp; Construction</p><p>Each job in the Construction &amp; Architecture Career Cluster requires certain skills, abilities, and talents.&#160;However, there are some that are common to many of the jobs in this career cluster.&#160;Click through the slideshow to learn more.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Drawing and Modeling:&#160;Architects and drafters must be able to create accurate drawings and models of the structures they design and build.&#160;It’s not enough to just be able to draw well.&#160;They must use math to draw their plans correctly.&#160;In today’s digital world, most professionals use a variety of software programs such as AutoCAD and SketchUp to create drawings and 3D models rather than relying on their sketch work alone.</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;6</p><p>Next</p><p>Technical Knowledge: Inspectors and builders must be familiar with building codes and regulations, materials, and construction methods. They must also understand the cost implications of their designs and be able to identify materials that are cost-effective yet of good quality.</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;6</p><p>Next</p><p>Problem-Solving: A lot of variables can impact a structure such as climate, usage, and height. Professionals in this cluster must be able to identify potential issues with a design or construction project and devise solutions to those issues.</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;6</p><p>Next</p><p>Project Management: Many of the professionals in this cluster must be able to manage some or all of the process from start to finish. This includes overseeing the project, managing budgets, and ensuring that the project is completed on time and within budget.</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;6</p><p>Next</p><p>Communication Skills: Architects and builders must be able to communicate effectively with their clients, contractors, and others on the team. They must be able to explain their ideas clearly and concisely and be able to understand the needs and expectations of their clients.</p><p>Previous</p><p>Slide&#160;5&#160;of&#160;6</p><p>Next</p><p>Attention to Detail: It is very important that architects and construction workers look closely at the details of a structure to make sure it is safe, strong, and well-designed. Even small details can have a big effect on how a structure looks and works. Being careful and paying attention to the details of the project can help it be finished on time and within budget.</p><p>Previous</p><p>Slide&#160;6&#160;of&#160;6</p><p>Next</p><p>Many of the skills listed above are skills you can work on right now!&#160;For example, you can take classes in geometry and art to help with your drawing and modeling skills.&#160;You can ask someone with a background in construction to show you some simple technical skills.&#160;Many classes require projects and teamwork.&#160;By acting as a leader for these projects, you can learn usable project management skills.&#160;You can take classes such as English and debate to help you communicate effectively.&#160;Finally, you can start paying attention to the details all around you.&#160;As you work on some of these skills, you will set yourself up for future success.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6a6d83d7ce3ba539e97f8b88a1daf43f','career-exploration-m2-l6-lesson-5','94be6c44c6053c60a0a8d89a1929ee61','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Training &amp; Education Requirements</h3><p>Training &amp; Education Requirements</p><p>Training and Education Requirements</p><p>People’s safety depends upon people in this career cluster being well-trained and educated in their profession.&#160;Education provides a foundation of knowledge that people can draw upon in practical experiences.&#160;Training helps individuals gain the technical skills needed to do real work.</p><p>If we were to list all of the careers and the training and education those workers receive, you’d be reading this lesson for hours!&#160;Instead, we will focus on some of the common careers in this cluster:</p><p>Architect</p><p>To become an architect, you must receive at least a Bachelor’s degree in Architecture is typically required. However, licensure is also necessary in order to practice architecture, which requires further educational requirements.</p><p>Construction Manager</p><p>Construction managers typically have a Bachelor’s degree as well. They may study Construction Management, Engineering, Architecture, or a related field. Depending on the employer, additional certifications may be necessary as well.</p><p>Civil Engineer</p><p>A minimum of a Bachelor’s degree in Civil Engineering is typically required to become a Civil Engineer. Additional certifications and licensure may also be necessary to practice in certain regions.</p><p>Construction Worker</p><p>No specific training or education is typically required to become a Construction Worker. However, employers may prefer to hire individuals with prior construction experience or trade school certifications.</p><p>Electrician</p><p>Most electricians have a minimum of a high school diploma. They also complete an apprenticeship which provides both background knowledge and hands-on experience. Some states require electricians to register before working as an apprentice. Many states and cities require licensure as well.</p><p>Construction or Building Inspector</p><p>A high school diploma is typically needed. Many professionals have work experience or background training in construction. Many states require licensure or certification.</p><p>Because the educational requirements are so diverse, it is a good idea to start researching jobs that interest you now.&#160;That way you can make a plan for the best path to your future goals.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('d9718944258b87d35ca8382255109b5b','career-exploration-m2-l7-module-2-summary','94be6c44c6053c60a0a8d89a1929ee61','Module 2 Summary','text',12,'<h2>Module 2 Summary</h2><section><h3>Module 2 Summary</h3><p>Module 2 Summary</p><p>Great Work!&#160;You have successfully completed this module on Architecture &amp; Construction.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this session, you:</p><p>Identified the pathways in the Architecture &amp; Construction career cluster and the careers in each pathway.</p><p>Described the types of places that employ individuals who have careers in the Architecture &amp; Construction career cluster.</p><p>Described the variety of tasks performed by individuals who have careers in the Architecture &amp; Construction career cluster.</p><p>Listed the skills, abilities, and talents needed for careers in the Architecture &amp; Construction career cluster.</p><p>Identified the level of training and education required for careers in the Architecture &amp; Construction career cluster.</p><p>Researched a career in the Architecture &amp; Construction career cluster and present findings to the class.</p><p>Applied math, science, and reading skills in the completion of a project or activity related to the Architecture &amp; Construction career cluster.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e2bbe7e9b2320fae24fe6785991deeb5','career-exploration-m2-l8-module-2-project','94be6c44c6053c60a0a8d89a1929ee61','Module 2 Project','text',12,'<h2>Module 2 Project</h2><section><h3>Module 2 Project</h3><p>Module 2 Project</p><p>Career Exploration</p><p>Architecture &amp; Construction - Project</p><p>For this project, you will choose from two options.&#160; You only need to complete one of these options.&#160; Please find both options and their rubrics below.</p><p>Option 1</p><p>For this option, you will construct a miniature version of a historical building using or structure recycled materials. To complete the project, follow these steps:</p><p>Step 1: Research historical buildings and select the one you like the most to replicate. Note the dimensions of the building so you can accurately depict your miniature version.</p><p>Step 2: Create a replica using recycled materials such as paper, cardboard, and plastic. You may use other materials as well as needed. While it does not have to be perfectly scaled, the dimensions should mimic those of the real version. For example, if the building is wider than it is tall, your replica should be that way as well.</p><p>Step 3: Share your replica by taking a picture of each side as well as from above and submitting them with this assignment. Also, include in your submission a write up that includes what building you chose and why you chose it.</p><p>Your final submission will be the photos from each side as well as from the top looking down at the replica as well as the short write-up explaining what building you chose and why.</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 1 Rubric: Architecture &amp; Construction Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Research</p><p>5 points The student researched famous buildings as evidenced by replicating it in a miniature version.</p><p>N/A</p><p>0 points The building does not replicate a famous structure.</p><p>5</p><p>Design and Dimensions</p><p>6-7 points The replica follows the same dimensions as the original structure and is well-designed.</p><p>4-5 points The replica mostly follows the same dimensions as the original structure and the design is okay.</p><p>0-3 points The replica does not follow the same dimensions as the original structure and/or is poorly designed.</p><p>7</p><p>Photos</p><p>7-8 points Photos submitted show all sides and from the top down.</p><p>5-6 points Photos submitted show most sides and from the top down.</p><p>0-4 points Photos not submitted and/or few sides are shown.</p><p>8</p><p>Total Points:&#160;20</p><p>Option 2</p><p>For this option, you will research a particular career that interests you in this cluster. Complete the following steps for your project:</p><p>Step 1: Research your chosen career.</p><p>Step 2: List the following</p><p>Average Salary/Salary Range</p><p>Education Requirements</p><p>Certification Requirements (if any)</p><p>Why you chose that career</p><p>Step 3: Prepare a PowerPoint presentation about your chosen career, including the information you gathered in Step 2 as well as your reason for choosing that career.</p><p>Your final submission should be your PowerPoint containing the information in Step 3.</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 2 Rubric: Architecture &amp; Construction Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Research</p><p>12 points The student provided a career field that interested them, the average salary or range, and the education/certifications required for the career.</p><p>11-4 points The student provided two of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>3-0 points The student provided one or none of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>12</p><p>Reason for Choosing the Career Field</p><p>4 points The student thoughtfully provided the reason that they are interested in this career.</p><p>N/A</p><p>0 points The student did not provide the reason that they are interested in this career.</p><p>4</p><p>Formatting</p><p>4 points The student&#39;s presentation includes no spelling or grammatical errors.</p><p>3-1 points The student&#39;s presentation includes minimal spelling or grammatical errors.</p><p>0 points The student&#39;s presentation includes a significant amount of spelling or grammatical errors.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8f98e8138f16135108b3598519a8bc84','career-exploration-m2-l9-module-2-quiz','94be6c44c6053c60a0a8d89a1929ee61','Module 2 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Archit & Construct. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('445a95879001ac604bd191ff4b4a3a3e','career-exploration-module-3','68d48b60cc4feb626956ed1fd8311e46','Module 3: Arts, Tech, Comms',3) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9990d536c67a3983d0375dd594eb2b99','career-exploration-m3-l1-introduction-purpose-and-objectives','445a95879001ac604bd191ff4b4a3a3e','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hello and welcome to this module on the Arts, A/V Technology, and Communications career cluster. I’m Ms. Jacobs and as one of your instructors, I’ll be introducing several modules throughout this course.</p><p>The Arts, A/V Technology, and Communications career cluster is all about creating, editing, and sharing stories, music, and videos. (And just to be clear as we begin, A/V stands for Audio/Video!) This career cluster encompasses everything from small-budget videos made at home and shared on YouTube to multimillion-dollar theatrical films created in Hollywood. From the actors on screen to the special effects crew convincing us the actors are on another planet, many people work to bring us video entertainment.</p><p>When you attend a concert, play, or dance performance, all of those performers are part of this career cluster. And it’s not just the talent you see on stage. It also includes the directors, lighting and technical crew, stage managers, and other individuals working behind the scenes to make the performance a success.</p><p>When something exciting or noteworthy happens, it’s the job of those in the communications section of this career cluster to share that story. This includes journalists, broadcasters, videographers, video editors, and others.</p><p>You also see the efforts of those in this career cluster every time you see a piece of art. This includes work you see in galleries as well as art for advertising.</p><p>In this module, we&#39;ll be covering a range of topics to help you gain a better understanding of the many exciting aspects of work and production that the Arts, A/V Technology, and Communication cluster entails. You’ll learn about the pathways in this career cluster, places of employment, and an idea of what some of the people in this career cluster do.</p><p>Get ready to learn all about this exciting career cluster- let’s get started!</p><p>Module Description</p><p>License:&#160;All Rights Reserved</p><p>In this module, students will explore the Arts, A/V Technology &amp; Communication career cluster.&#160;The module begins with an overview of the pathways in this career cluster and some of the jobs in the cluster.&#160;Next, students will recognize some of the places that employ individuals in the Arts, A/V Technology &amp; Communication field.&#160;Then the course will begin exploring the practical aspects of achieving employment in this cluster including the variety of tasks people perform, the skills, abilities, and talents needed, and the level of training and education required.</p><p>Objectives</p><p>In this module, students will</p><p>Identify the pathways in the Arts, A/V Technology &amp; Communication career cluster and the careers in each pathway.</p><p>Describe the types of places that employ individuals who have careers in the Arts, A/V Technology &amp; Communication career cluster.</p><p>Describe the variety of tasks performed by individuals who have careers in the Arts, A/V Technology &amp; Communication career cluster.</p><p>List the skills, abilities, and talents needed for careers in the Arts, A/V Technology &amp; Communication career cluster.</p><p>Identify the level of training and education required for careers in the Arts, A/V Technology &amp; Communication career cluster.</p><p>Research a career in the Arts, A/V Technology &amp; Communication career cluster and present findings to the class.</p><p>Apply math, science, and reading skills in the completion of a project or activity related to the Arts, A/V Technology &amp; Communication career cluster.</p><p>Polling Question</p><p>Which job in this cluster sounds most interesting to you?</p><p>Performer (dancer, actor, musician, etc.)&#160;Artist&#160;Journalist&#160;Editor (video, sound, photo, etc.)&#160;Other</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Writing stories or news reports about what is happening in the world.</p><p>Broadcasting</p><p>Technology that uses sound and pictures, like TVs, computers, and projectors.</p><p>Visual arts</p><p>Creating things like drawings, paintings, sculptures, and other artwork using different kinds of materials.</p><p>Journalism</p><p>A form of art where people use their bodies, voices, or instruments to make music, dance, drama, and other forms of entertainment.</p><p>Audio-visual (A/V) technology</p><p>Sending out TV or radio shows to lots of people at the same time.</p><p>Performing arts</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Writing stories or news reports about what is happening in the world.</p><p>Answers for question: 1</p><p>Broadcasting</p><p>Journalism</p><p>Performing arts</p><p>Visual arts</p><p>Audio-visual (A/V) technology</p><p>2.</p><p>Technology that uses sound and pictures, like TVs, computers, and projectors.</p><p>Answers for question: 2</p><p>Audio-visual (A/V) technology</p><p>Visual arts</p><p>Performing arts</p><p>Journalism</p><p>Broadcasting</p><p>3.</p><p>Creating things like drawings, paintings, sculptures, and other artwork using different kinds of materials.</p><p>Answers for question: 3</p><p>Performing arts</p><p>Journalism</p><p>Visual arts</p><p>Audio-visual (A/V) technology</p><p>Broadcasting</p><p>4.</p><p>A form of art where people use their bodies, voices, or instruments to make music, dance, drama, and other forms of entertainment.</p><p>Answers for question: 4</p><p>Audio-visual (A/V) technology</p><p>Performing arts</p><p>Broadcasting</p><p>Journalism</p><p>Visual arts</p><p>5.</p><p>Sending out TV or radio shows to lots of people at the same time.</p><p>Answers for question: 5</p><p>Performing arts</p><p>Broadcasting</p><p>Journalism</p><p>Audio-visual (A/V) technology</p><p>Visual arts</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c0227a2744306c85ec083222b6efcb7c','career-exploration-m3-l2-lesson-1','445a95879001ac604bd191ff4b4a3a3e','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>What is Arts, Tech, Comms Career Cluster</h3><p>What is Arts, Tech, Comms Career Cluster</p><p>What is the Arts, A/V Technology &amp; Communications Career Cluster?</p><p>The Arts, A/V Technology, and Communications Career Cluster centers on jobs that involve creativity and communication.&#160;There are six pathways in this career cluster.&#160;Click on each tab to learn more about the pathways.</p><p>Audio-Video technology and film</p><p>People working in this career cluster create movies, music, and other audio-visual projects.&#160;It involves using equipment and technology such as cameras, microphones, and computers to record and edit pictures and sound.&#160;This technology is used to make movies, music videos, commercials, and other videos.&#160;Some of the jobs in this pathway include videographers, audio systems technicians, animators, lighting designers, and video editors.</p><p>Journalism and broadcasting</p><p>This pathway involves gathering information and sharing it with others, typically through TV, radio, newspaper, or websites. Because of people working in this pathway, people can easily learn about what’s happening in their community, in their country, and around the world. A few of the careers in this pathway include journalist, news reporter/anchor, and media planner.</p><p>Performing arts</p><p>People in this pathway create performances in which artists use their bodies, voice, or objects in artistic expression. The most common forms of performing arts are music, dance, and theater. Some professionals are performers like dancers, musicians, and actors. Others help with the performance off-stage such as directors, choreographers, and stage managers.</p><p>Printing technology</p><p>The work in this pathway focuses on creating physical copies of words, art, and pictures. There are three stages in the printing process—prepress, press and binding, and post-press. Individuals may work in one or all of these stages. Examples of jobs in this pathway include pre-production technician, printing equipment operator, and graphics equipment operator.</p><p>Telecommunications (telecom)</p><p>The professionals in this pathway focus on the interaction between different technological forms of communication such as computers and phones. Some professionals create, improve, and innovate this technology while others install, maintain, and repair it. Some of the professions in this cluster include telecommunications equipment installers, telecom programmers, and network engineers.</p><p>Visual arts</p><p>This pathway focuses on the use of visual arts and design to create and communicate ideas, stories, and messages. It includes creating photos, digital media, sculptures, paintings, and other visual arts. The art may be created for galleries or museums, or it may be used for advertisements, websites, books, magazines, and movies. Careers in this cluster include artists, illustrators, graphic designers, photographers, and art directors.</p><p>Next Tab</p><p>Match the pathway that may be a good fit for each person based on their interest and skills:</p><p>Warning:&#160;json_decode() expects parameter 1 to be string, object given in&#160;/srv/app/current/blocks/interactive_definitions/controller.php&#160;on line&#160;238</p><p>Pathway</p><p>Julia loves drawing on her iPad.</p><p>Performing Arts</p><p>Louise is the go-to person in her house when the internet is not working.</p><p>Printing Technology</p><p>Miguel enjoys creating prints of his photos in the school’s darkroom.</p><p>Journalism &amp; Broadcasting</p><p>Davis loves being in the school play each semester.</p><p>Telecommunications</p><p>The students and faculty never miss Amanda’s write-ups about the sporting event at the school for the school newspaper.</p><p>Visual Arts</p><p>Omar creates fun highlight videos of him and his friends on the skateboards.</p><p>Audio-Video Technology</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Julia loves drawing on her iPad.</p><p>Answers for question: 1</p><p>Journalism &amp; Broadcasting</p><p>Visual Arts</p><p>Audio-Video Technology</p><p>Performing Arts</p><p>Telecommunications</p><p>Printing Technology</p><p>2.</p><p>Louise is the go-to person in her house when the internet is not working.</p><p>Answers for question: 2</p><p>Telecommunications</p><p>Performing Arts</p><p>Printing Technology</p><p>Journalism &amp; Broadcasting</p><p>Audio-Video Technology</p><p>Visual Arts</p><p>3.</p><p>Miguel enjoys creating prints of his photos in the school’s darkroom.</p><p>Answers for question: 3</p><p>Journalism &amp; Broadcasting</p><p>Audio-Video Technology</p><p>Visual Arts</p><p>Printing Technology</p><p>Telecommunications</p><p>Performing Arts</p><p>4.</p><p>Davis loves being in the school play each semester.</p><p>Answers for question: 4</p><p>Telecommunications</p><p>Performing Arts</p><p>Printing Technology</p><p>Visual Arts</p><p>Audio-Video Technology</p><p>Journalism &amp; Broadcasting</p><p>5.</p><p>The students and faculty never miss Amanda’s write-ups about the sporting event at the school for the school newspaper.</p><p>Answers for question: 5</p><p>Audio-Video Technology</p><p>Journalism &amp; Broadcasting</p><p>Visual Arts</p><p>Performing Arts</p><p>Telecommunications</p><p>Printing Technology</p><p>6.</p><p>Omar creates fun highlight videos of him and his friends on the skateboards.</p><p>Answers for question: 6</p><p>Audio-Video Technology</p><p>Visual Arts</p><p>Printing Technology</p><p>Telecommunications</p><p>Performing Arts</p><p>Journalism &amp; Broadcasting</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0b19eca36488f939557b911c66020783','career-exploration-m3-l3-lesson-2','445a95879001ac604bd191ff4b4a3a3e','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Arts, Tech, Comms Career Cluster Work</h3><p>Arts, Tech, Comms Career Cluster Work</p><p>Where People in the Arts, A/V Technology, and Communication Career Cluster Work</p><p>People in the Arts, A/V Technology, and Communication career cluster can find work in a variety of places because creativity is needed everywhere!&#160;Here are some of the common places people in this career cluster work:</p><p>Advertising Agencies</p><p>A company that works with other businesses to create commercials or advertisements that are meant to help those businesses sell their products or services.</p><p>Film Production Companies</p><p>Film Production Companies: A business that makes movies, which are filmed on a set or location and then later edited together and shown in cinemas or on TV.</p><p>Television Networks</p><p>Companies that broadcast shows and movies on TV, usually through cable and satellite systems.</p><p>Digital Media Companies</p><p>Companies create and distribute media such as websites, apps, and games over the internet.</p><p>Radio Stations</p><p>Companies that broadcast music, talk shows, and other programs over the airwaves to people with radios.</p><p>Music Recording Studios</p><p>Places where musicians go to record their songs. The sounds they make are then mixed together and made into a song.</p><p>Publishing Houses</p><p>Companies that publish books, magazines, and other printed materials.</p><p>Graphic Design Firms</p><p>Companies that use art, typography, and other visual elements to create logos, websites, and other visuals for their clients.</p><p>Video Game Design Studios</p><p>Companies that design and create video games for people to play.</p><p>Animation Studios</p><p>Companies that create cartoons, TV shows, movies, and other visuals using computer-generated images.</p><p>Places of employment like those listed above exist almost everywhere.&#160;The best place to look for a job is the one that most closely matches the type of job you are looking for.&#160;For example, a graphic designer would look for work at a graphic design firm.&#160;A journalist might check out a television network.&#160;Those who love drawing and animation may find opportunities at an animation studio.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('cc1d31de9abff4c3c719994f60692c95','career-exploration-m3-l4-lesson-3','445a95879001ac604bd191ff4b4a3a3e','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Activities of Arts, Tech, Comms Cluster</h3><p>Activities of Arts, Tech, Comms Cluster</p><p>Activities in the Arts, A/V Technology &amp; Communications Career Cluster</p><p>People in the Arts, A/V Technology &amp; Communications career cluster perform a variety of tasks.&#160;What those tasks look like depends on the person’s job.&#160;For example, the activities performed by a dancer will be different from those of a video editor.&#160;Click through the slide show below to learn about some of the things people in this career cluster do:</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Creating art, such as music, drawings, or paintings.</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;8</p><p>Next</p><p>Setting up and operating equipment such as cameras, lights, and sound equipment.</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;8</p><p>Next</p><p>Traveling to places where important events are happening in order to share stories.</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;8</p><p>Next</p><p>Practicing for performances.</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;8</p><p>Next</p><p>Using technology and software to perform tasks such as video editing, animation, and sound editing.</p><p>Previous</p><p>Slide&#160;5&#160;of&#160;8</p><p>Next</p><p>Repairing telecommunication systems.</p><p>Previous</p><p>Slide&#160;6&#160;of&#160;8</p><p>Next</p><p>Helping create visually appealing websites, magazines, and advertisements.</p><p>Previous</p><p>Slide&#160;7&#160;of&#160;8</p><p>Next</p><p>Organizing, directing, or participating in performances.</p><p>Previous</p><p>Slide&#160;8&#160;of&#160;8</p><p>Next</p><p>As you can see, the variety of tasks performed in this career cluster varies greatly.&#160;The best way to learn more about what the work of someone in this career cluster is like is by selecting a specific job and learning more about the daily life of someone in that career.&#160;You can learn about this through online videos, reading blogs, and books.&#160;Perhaps the best way of all is by getting to know someone who is already working in this career cluster.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5cdf7a7303305534aaa4ec85dae296e2','career-exploration-m3-l5-lesson-4','445a95879001ac604bd191ff4b4a3a3e','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Skills for Arts, Tech, Comms Career</h3><p>Skills for Arts, Tech, Comms Career</p><p>Skills, Abilities, and Talents Needed for a Career in Arts, A/V Technology &amp; Communications</p><p>Professionals in this career cluster spend years developing their skills and talents.&#160;Here are some of the most common skills, abilities, and talents in this career cluster.&#160;Click on each one to learn more:</p><p>Creativity</p><p>The ability to come up with novel and unique ideas. This is important when creating art, writing, and sharing a message.</p><p>Communication Skills</p><p>The ability to clearly communicate ideas and thoughts through written, verbal, and visual means. Artists, journalists, writers, performers, and directors all need excellent communication skills.</p><p>Technical Expertise</p><p>The ability to understand and use the latest audio/visual technology. This is particularly important for A/V specialists, lighting directors, and video/audio editors.</p><p>Computer Skills</p><p>Knowledge and ability to use computers and related software for creating art or communication pieces. Graphic designers, video/audio editors, and animators all need computer skills.</p><p>Problem-Solving</p><p>The ability to identify and solve problems that arise when creating art or communication pieces. Telecom specialists use problem-solving to figure out system problems. Those involved in the performing arts use problem-solving when a problem arises that could impact the performance.</p><p>Attention to Detail</p><p>The ability to pay attention to the small details that can make a big difference in the quality of art or communication pieces. Artists think through the details of the art they create. Writers pay attention to the words they use and the meanings they convey. Editors look to fix even the smallest mistakes.</p><p>Interpersonal Skills</p><p>The ability to effectively interact and collaborate with other people. Collaboration is an important skill in putting together performances. It is also important to journalists and reporters who must conduct interviews to learn more about events and situations.</p><p>Time Management</p><p>The ability to manage time well in order to complete projects within deadlines. Journalists frequently have deadlines to meet. Performers and artists must be ready with their work by the day of the performance or gallery show.</p><p>Organization Skills</p><p>The ability to organize materials and tasks. There are many components that go into putting on a successful performance, creating a video, and televising the news. It is important that each person understands their task and does their part to stay organized.</p><p>Adaptability</p><p>The ability to adapt and adjust to changing circumstances and technologies when creating art or communication pieces. This field is ever-evolving and it is important that each professional stay current on the latest technology, trends, and events impacting their work.</p><p>Research Skills</p><p>The ability to research a wide variety of information. Journalists must do accurate research to write their stories.</p><p>Planning Skills</p><p>The ability to plan and strategize. Directors and managers must thoroughly plan performances.</p><p>Leadership Skills</p><p>The ability to lead and motivate a team in order to create art or communication pieces. Directors and managers of all kinds of roles must be effective leaders to finish projects well and on time.</p><p>Storytelling</p><p>The ability to create stories or narratives that will be engaging to an audience. Performers, writers, choreographers, and editors all must understand how to tell a story in different ways.</p><p>Visualization Skills</p><p>The ability to visualize and imagine how a piece of art or communication will look or sound before it is created. Choreographers, directors, videographers, and artists all must visualize a performance or piece of art before it’s complete.</p><p>Listening Skills</p><p>The ability to listen carefully to feedback and input from others. This is an important skill for anyone who is part of a production. Whether it is a play, movie, dance, or network program, everyone must listen to one another to avoid complications.</p><p>Musical Ability</p><p>The ability to understand, play, and create music for art or communication purposes. This is important for musicians, composers, music producers, and sound technologists.</p><p>Editing Skills</p><p>The ability to edit audio, video footage, photos, or words in order to create a high-quality art or communication piece. Photo, video, and publication editors all must know what to leave, remove, or fix in a piece of work.</p><p>Public Speaking Skills</p><p>The ability to speak confidently in public. This is important for news anchors, reporters, and actors.</p><p>Now that you have a foundational understanding of these skills, match the best skill to the situation:</p><p>An actor needs to recite a monolog.</p><p>Storytelling</p><p>A video needs to be trimmed down from four minutes to three and a half minutes.</p><p>Listening skills</p><p>A reporter is doing a segment that will recount the life of a major contributor to the community.</p><p>Public Speaking</p><p>A dancer needs to understand the critique the choreographer provides about his technique.</p><p>Problem-Solving</p><p>A director needs to take charge in order to have the entire cast and crew ready for opening night.</p><p>Computer Skills</p><p>A photographer needs to learn the newest version of Photoshop.</p><p>Video Editing</p><p>An orchestra has been practicing at a particular concert hall, but that hall flooded and the performance has been moved to a different location, and the orchestra must make the most of the situation.</p><p>Adaptability</p><p>A telecom worker needs to figure out why one side of the street has internet service and the other does not.</p><p>Leadership Skills</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>An actor needs to recite a monolog.</p><p>Answers for question: 1</p><p>Problem-Solving</p><p>Leadership Skills</p><p>Public Speaking</p><p>Listening skills</p><p>Computer Skills</p><p>Adaptability</p><p>Storytelling</p><p>Video Editing</p><p>2.</p><p>A video needs to be trimmed down from four minutes to three and a half minutes.</p><p>Answers for question: 2</p><p>Problem-Solving</p><p>Storytelling</p><p>Video Editing</p><p>Leadership Skills</p><p>Public Speaking</<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('66489eaf32c151046c82c5a0d41f1204','career-exploration-m3-l6-lesson-5','445a95879001ac604bd191ff4b4a3a3e','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Training and Education Requirements</h3><p>Training and Education Requirements</p><p>The level of training and education required for careers in the Arts, A/V Technology &amp; Communication career cluster depends on the specific job.&#160;Some jobs typically require formal education, while others can be acquired by demonstrating sufficient talent and experience.&#160;Many artists and performers spend years taking lessons and practicing their craft.&#160;These classes may be done through schools, community programs, or private mentorship.</p><p>Here are some of the most common jobs and the typical education and training associated with them.&#160;Click each tab to learn more:</p><p>Graphic Designer</p><p>A graphic designer often has a bachelor&#39;s degree in graphic design or a related field, although some graphic designers get into the field without formal study.&#160;No matter the path, they should be proficient in graphic design software, such as Adobe Photoshop, Illustrator, and InDesign.&#160;They may also need to be knowledgeable in web design, animation, and digital photography.</p><p>Videographer</p><p>A videographer typically needs a bachelor&#39;s degree in video production or a related field. They should be proficient in video production software, such as Adobe Premiere Pro, Final Cut Pro, and After Effects. They may also need to be knowledgeable in lighting, sound, and cinematography.</p><p>Animator</p><p>An animator may have a bachelor&#39;s degree in animation or a related field. They should be proficient in animation software, such as Adobe Flash, Maya, and 3D Studio Max. Additional training may include web design, graphic design, and sound editing. People in this field typically have skills in art and drawing.</p><p>Audio Technician</p><p>An audio technician typically needs education in sound engineering or a related field. They should be proficient in audio engineering software, such as Pro Tools, Logic Pro, and Cubase. They may also need to be knowledgeable in sound recording, mixing, and sound design.</p><p>Photographer</p><p>Many schools offer degrees in photography. However, these skills can be developed through taking classes online and in person, as well as through mentorships. Photographers should be proficient in digital photography and photo editing software, such as Adobe Photoshop and Lightroom.</p><p>Multimedia Artist</p><p>A multimedia artist typically holds a bachelor&#39;s degree in multimedia or a related field. They have experience in multimedia software, such as Adobe Flash, Adobe After Effects, and Adobe Dreamweaver. They may also need to be knowledgeable in graphic design, animation, video production, and web design.</p><p>Web Designer</p><p>A web designer typically needs a bachelor&#39;s degree in web design or a related field. They should understand programming languages such as HTML, CSS, and JavaScript. They may also need to be knowledgeable in graphic design, animation, and web development frameworks.</p><p>Film/Video editor</p><p>A film/video editor typically holds a bachelor&#39;s degree in film/video editing or a related field. They have training in video editing software, such as Adobe Premiere Pro, Final Cut Pro, and Avid Media Composer. They may also need to be knowledgeable in sound editing, color grading, and motion graphics.</p><p>Music Producer</p><p>An applicable degree in this field would be music or music production, if available. A person in this career should have training in production software, such as Pro Tools, Logic Pro, and Ableton Live. They should also have some familiarity with sound engineering, mixing, and music composition.</p><p>Broadcast Technician</p><p>A broadcast technician may have a bachelor&#39;s degree in broadcast engineering or on-the-job training. Knowing equipment such as digital audio consoles and video switchers is an important part of the job. They may also need to be knowledgeable in radio and television production, audio engineering, and computer networking.</p><p>Next Tab</p><p>One of the most exciting things about this career cluster is that you can gain experience and training right now.&#160;For example, you can start watching online tutorials that teach you how to use software like Photoshop.&#160;You can practice skills like writing, art, and music right in the comfort of your own home.&#160;The more you practice and develop complimentary skills in this field, the more you will set yourself up for a successful career in this cluster in the future!</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b70b64de1104c4b11d328893b78ebdff','career-exploration-m3-l7-module-3-summary','445a95879001ac604bd191ff4b4a3a3e','Module 3 Summary','text',12,'<h2>Module 3 Summary</h2><section><h3>Module 3 Summary</h3><p>Module 3 Summary</p><p>Great Work!&#160;You have successfully completed this module on&#160;Arts, A/V Technology &amp; Communications.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified the pathways in the Arts, A/V Technology &amp; Communication career cluster and the careers in each pathway.</p><p>Described the types of places that employ individuals who have careers in the Arts, A/V Technology &amp; Communication career cluster.</p><p>Described the variety of tasks performed by individuals who have careers in the Arts, A/V Technology &amp; Communication career cluster.</p><p>Listed the skills, abilities, and talents needed for careers in the Arts, A/V Technology &amp; Communication career cluster.</p><p>Identified the level of training and education required for careers in the Arts, A/V Technology &amp; Communication career cluster.</p><p>Researched a career in the Arts, A/V Technology &amp; Communication career cluster and present findings to the class.</p><p>Applied math, science, and reading skills in the completion of a project or activity related to the Arts, A/V Technology &amp; Communication career cluster.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7b73d3a59cdd3e5e3e231f0f5aa2f75b','career-exploration-m3-l8-module-3-project','445a95879001ac604bd191ff4b4a3a3e','Module 3 Project','text',12,'<h2>Module 3 Project</h2><section><h3>Module 3 Project</h3><p>Module 3 Project</p><p>Career Exploration</p><p>Arts, A/V Technology &amp; Communications - Project</p><p>For this project, you will choose from two options.&#160; You only need to complete one of these options.&#160; Please find both options and their rubrics below.</p><p>Option 1</p><p>For this option, you will design a poster that promotes a particular cultural event in your area. Your poster should contain the following:</p><p>Information about when &amp; where the event is taking place.</p><p>Graphics, photos, and other images related to the event that are well-designed and enhance the appearance of the poster.</p><p>Information about key participants for the event.</p><p>Be easy to read and visually appealing.</p><p>To submit your project, take a photo of your project as well as a reference to the event where you got the information such as a link to the event or a photo of a flyer or other source.</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 1 Rubric: Arts, A/V Technology &amp; Communications Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Key Information</p><p>5 points Includes what the event is, where it is taking place, and when. The student also submitted a reference with official information about the event and the poster aligns with the official information.</p><p>3-4 points Includes most of the information related to what the event is, where it is taking place, and when. The student also submitted a reference with official information about the event and the poster mostly aligns with the official information.</p><p>0-2 points Missing key information related to what the event is, where it is taking place, and when and/or the student did not submit an original source that aligns with the information on the poster.</p><p>5</p><p>Graphic Elements</p><p>5 points The poster contains well-designed and placed graphics related to the event.</p><p>3-4 points The poster contains adequately designed and placed graphics related to the event.</p><p>0-2 points There are no graphics or the graphics used are not appropriate and/or well-designed.</p><p>5</p><p>Information About Participants</p><p>5 points The poster includes the key participant(s) in the event.</p><p>N/A</p><p>0 points The poster does not mention the key participant(s) in the event.</p><p>5</p><p>Design</p><p>5 points The poster is well-designed and easy to read.</p><p>3-4 points The poster is adequately designed and mostly easy to read.</p><p>0-2 points The poster is not well-designed and/or is difficult to read.</p><p>5</p><p>Total Points:&#160;20</p><p>Option 2</p><p>For this option, you will research a particular career that interests you in this cluster. Complete the following steps for your project:</p><p>Step 1: Research your chosen career.</p><p>Step 2: List the following</p><p>Average Salary/Salary Range</p><p>Education Requirements</p><p>Certification Requirements (if any)</p><p>Why you chose that career</p><p>Step 3: Prepare a PowerPoint presentation about your chosen career, including the information you gathered in Step 2 as well as your reason for choosing that career.</p><p>Your final submission should be your PowerPoint containing the information in Step 3.</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 2 Rubric: Arts, A/V Technology &amp; Communications Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Research</p><p>12 points The student provided a career field that interested them, the average salary or range, and the education/certifications required for the career.</p><p>11-4 points The student provided two of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>3-0 points The student provided one or none of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>12</p><p>Reason for Choosing the Career Field</p><p>4 points The student thoughtfully provided the reason that they are interested in this career.</p><p>N/A</p><p>0 points The student did not provide the reason that they are interested in this career.</p><p>4</p><p>Formatting</p><p>4 points The student&#39;s presentation includes no spelling or grammatical errors.</p><p>3-1 points The student&#39;s presentation includes minimal spelling or grammatical errors.</p><p>0 points The student&#39;s presentation includes a significant amount of spelling or grammatical errors.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1b92924c6422b6339b5ee4c98e18181f','career-exploration-m3-l9-module-3-quiz','445a95879001ac604bd191ff4b4a3a3e','Module 3 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Arts, Tech, Comms. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('5b5a08f65bfb47b9c9d85cc971872619','career-exploration-module-4','68d48b60cc4feb626956ed1fd8311e46','Module 4: Business, Managem, Admin',4) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a03d7afdf96e31fb1d4b3f69f450f055','career-exploration-m4-l1-introduction-purpose-and-objectives','5b5a08f65bfb47b9c9d85cc971872619','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hello and welcome to this module on the Business, Management &amp; Administration career cluster.</p><p>Think business is boring? Think again!</p><p>The Business, Management &amp; Administration career cluster can lead to jobs with high paychecks, opportunities to travel, and opportunities for advancement. It can help open networking opportunities and lead to lifelong connections.</p><p>Whether you’re a self-employed small business owner or the Human Resources manager for a company with 500 employees, people in this career cluster help make businesses and organizations run smoothly and efficiently. They use creativity and innovative thinking to give us a better business experience.</p><p>There are many reasons to investigate this career cluster, and we’re going to provide you with a solid foundation of knowledge in this module.</p><p>We’ll discuss the 5 pathways and where different careers such as entrepreneur, auditor, and administrative assistant fit. You’ll learn about where you can find work and how this sector presents an excellent opportunity to combine multiple interests.</p><p>When you imagine someone working in business, do you imagine them sitting in meetings all day? Don’t worry- there’s more to this cluster than meetings and we’ll talk about some of those interesting activities in this module.</p><p>We’ll also talk about the skills and talents you should develop as well as the education to pursue, so you can be successful in this career cluster.</p><p>As you can see, we have much to cover, so let’s get going!</p><p>Module Description</p><p>License:&#160;Public Domain</p><p>Welcome to this module on the Business, Management &amp; Administration career cluster.&#160;First, this module will take students through the different pathways in this career cluster.&#160;Next, students will learn about different places of employment for careers.&#160;The module will then explore the types of tasks people perform in this cluster.&#160;Students will also learn about the skills, abilities, and talents needed for these careers.&#160;The final lesson will discuss the different jobs available at every level from high school diploma to post-graduate education.&#160;By the end of this module, you will have a better understanding of the different opportunities available in the Business, Management &amp; Administration career cluster.</p><p>Objectives</p><p>In this module, students will</p><p>Identify the pathways in the Business, Management &amp; Administration career cluster and the careers in each pathway.</p><p>Describe the types of places that employ individuals who have careers in the Business Management &amp; Administration career cluster.</p><p>Describe the variety of tasks performed by individuals who have careers in the Business Management &amp; Administration career cluster.</p><p>List the skills, abilities, and talents needed for careers in the Business Management &amp; Administration career cluster.</p><p>Identify the level of training and education required for careers in the Business Management &amp; Administration career cluster.</p><p>Research a career in the Business Management &amp; Administration career cluster and present findings to the class.</p><p>Apply math, science, and reading skills in the completion of a project or activity related to the Business Management &amp; Administration career cluster.</p><p>Polling Question</p><p>Which career in this cluster sounds most interesting to you?</p><p>Chief Executive Officer (CEO)&#160;Human Resources Manager&#160;Marketing Director&#160;Sales Associate&#160;Other</p><p>Results:</p><p>Marketing Director&#160;50%</p><p>Human Resources Manager&#160;50%</p><p>Vocabulary</p><p>Match the definitions with the key vocabulary words that will be reviewed in this module.</p><p>Warning:&#160;json_decode() expects parameter 1 to be string, object given in&#160;/srv/app/current/blocks/interactive_definitions/controller.php&#160;on line&#160;238</p><p>The process of keeping track of money and other financial information.</p><p>Transaction</p><p>An exchange of something of value between two or more people or entities.</p><p>Accounting</p><p>The process of managing, organizing, and controlling a business or other organization.</p><p>Logistics</p><p>Starting your own business or organization.</p><p>Entrepreneurship</p><p>The process of planning, organizing, and controlling the movement of people or goods.</p><p>Administration</p><p>The department of a business or organization that deals with hiring, training, and managing people.</p><p>Human Resources</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>The process of keeping track of money and other financial information.</p><p>Answers for question: 1</p><p>Accounting</p><p>Transaction</p><p>Human Resources</p><p>Administration</p><p>Entrepreneurship</p><p>Logistics</p><p>2.</p><p>An exchange of something of value between two or more people or entities.</p><p>Answers for question: 2</p><p>Human Resources</p><p>Administration</p><p>Entrepreneurship</p><p>Logistics</p><p>Transaction</p><p>Accounting</p><p>3.</p><p>The process of managing, organizing, and controlling a business or other organization.</p><p>Answers for question: 3</p><p>Logistics</p><p>Entrepreneurship</p><p>Human Resources</p><p>Administration</p><p>Transaction</p><p>Accounting</p><p>4.</p><p>Starting your own business or organization.</p><p>Answers for question: 4</p><p>Administration</p><p>Human Resources</p><p>Entrepreneurship</p><p>Transaction</p><p>Accounting</p><p>Logistics</p><p>5.</p><p>The process of planning, organizing, and controlling the movement of people or goods.</p><p>Answers for question: 5</p><p>Human Resources</p><p>Administration</p><p>Transaction</p><p>Accounting</p><p>Entrepreneurship</p><p>Logistics</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a9debcc4a0185d9a9312f5bea3ab6dfb','career-exploration-m4-l2-lesson-1','5b5a08f65bfb47b9c9d85cc971872619','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>What is Business, Manag, Admin Career Cluster</h3><p>What is Business, Manag, Admin Career Cluster</p><p>What is the Business, Management &amp; Administration Career Cluster?</p><p>The Business, Management &amp; Administration career cluster involves the overseeing and managing of businesses, organizations, and other entities.&#160;People in this cluster use their knowledge and skills to make sure that the operations of a business or organization run smoothly and efficiently.&#160;This career cluster includes a variety of business-related tasks such as planning, organizing, and decision-making.&#160;It also includes people who hire, train, and supervise staff, as well as managing budgets, resources, and operations.</p><p>Click on each pathway to learn more about each one and the careers within those pathways:</p><p>General Management Pathway</p><p>This pathway is all about planning, organizing, and making decisions for a business. People in this pathway set goals and help make sure the business has the financial, human, and other resources required to reach those goals. Examples of careers within this pathway include Chief Executive Officer (CEO), auditor, and financial manager.</p><p>Business Information Management Pathway</p><p>This pathway involves using technology to store and manage information for a business. People in this pathway use computers and other technologies to organize data and help people in the business make decisions based on that information. Examples of careers within this pathway include computer systems analyst, database architect, and database administrator.</p><p>Human Resources Management Pathway</p><p>This pathway is all about taking care of people in the business. People in this pathway are responsible for hiring new employees, making sure everyone is being treated fairly, and making sure the work environment is productive and safe. Examples of careers within this pathway include HR manager, recruiter, and labor relations specialist.</p><p>Operations Management Pathway</p><p>This focuses on making sure the business is running smoothly. People in this pathway are responsible for making sure business processes are working well, that the business is meeting deadlines, and that the business is using resources efficiently. Examples of careers within this pathway include operations manager, purchasing manager, and risk management specialist.</p><p>Administrative Support Pathway</p><p>This pathway is all about helping the business run smoothly. People in this pathway are responsible for managing office tasks, helping out with customer service, and ensuring that the business is organized. Examples of careers within this pathway include data entry specialist, administrative assistant, and customer service representative.</p><p>Now that you understand a little bit about the five pathways, see if you can match the career to the pathway:</p><p>Career</p><p>Pathway</p><p>Administrative Assistant</p><p>Operations Management</p><p>Risk management specialist</p><p>General management</p><p>Recruiter</p><p>Business information management</p><p>Database administrator</p><p>Human Resources Management</p><p>Auditor</p><p>Administrative Support</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Administrative Assistant</p><p>Answers for question: 1</p><p>Human Resources Management</p><p>Business information management</p><p>General management</p><p>Administrative Support</p><p>Operations Management</p><p>2.</p><p>Risk management specialist</p><p>Answers for question: 2</p><p>Administrative Support</p><p>Operations Management</p><p>Human Resources Management</p><p>Business information management</p><p>General management</p><p>3.</p><p>Recruiter</p><p>Answers for question: 3</p><p>General management</p><p>Operations Management</p><p>Business information management</p><p>Human Resources Management</p><p>Administrative Support</p><p>4.</p><p>Database administrator</p><p>Answers for question: 4</p><p>Business information management</p><p>Human Resources Management</p><p>General management</p><p>Operations Management</p><p>Administrative Support</p><p>5.</p><p>Auditor</p><p>Answers for question: 5</p><p>Administrative Support</p><p>Business information management</p><p>Operations Management</p><p>General management</p><p>Human Resources Management</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('67402def4bbb01d161d5a9681b05314a','career-exploration-m4-l3-lesson-2','5b5a08f65bfb47b9c9d85cc971872619','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Business, Manag, Admin Career Work</h3><p>Business, Manag, Admin Career Work</p><p>Where People in the Business, Management &amp; Administration Career Cluster Work</p><p>Every organization wants to run smoothly and efficiently.&#160;Because of this, all types of organizations hire people in the Business, Management &amp; Administration career cluster.</p><p>Click on each image to learn more about some of these places and how people in this career cluster help the organization:</p><p>5</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Places of potential employment in the Business, Management &amp; Administration career cluster.</p><p>The hotspot points on the image are as follows:</p><p>Large Companies</p><p>Large companies are businesses that have lots of employees and customers. These businesses need help with human resources, business management, information tracking and analysis, and administration.</p><p>Healthcare Organizations</p><p>Healthcare organizations are businesses that provide medical care and services to people. These organizations need people to help them plan out their operations and make sure they are staying organized.</p><p>Hotels</p><p>Hotels are places where people can stay when they are traveling. They hire people to help them hotels plan out their operations, manage their budgets, and make sure the customers have a positive experience.</p><p>Small Businesses</p><p>Small businesses are usually owned by one or two people. Examples of small businesses include a bakery, a tech company, or a clothing store. Small businesses need people to manage their daily operations and track their finances.</p><p>Nonprofit organizations</p><p>Nonprofit organizations are businesses that do not make a profit and are usually focused on providing services to the community. However, many of the same jobs that are needed to run a regular company are also needed to run a nonprofit such as financial professionals, managers, and administrative support.</p><p>Banks</p><p>Banks are places where people can go to get loans and other financial services. Banks need people to help customers with their money as well as to make sure the bank is operating as it should.</p><p>This career cluster presents a great way to combine multiple interests.&#160;For example, someone with an interest in sports could work for a sports team helping to manage the finances, operations, or human resources.&#160;As another example, someone who is passionate about wellness may enjoy helping a physical therapy, counseling, or doctor’s office with its business.&#160;The possibilities are nearly endless for how you could find a career in this cluster working at a place that excites you!</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2c50cf27ef323ef7489e857392dacff2','career-exploration-m4-l4-lesson-3','5b5a08f65bfb47b9c9d85cc971872619','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Activities in Business, Manag, Admin Careers</h3><p>Activities in Business, Manag, Admin Careers</p><p>Shutterstock</p><p>License:&#160;All Rights Reserved</p><p>Activities in the Business, Management &amp; Administration Career Cluster</p><p>Individuals who have careers in the Business Management &amp; Administration career cluster have a variety of interesting tasks.&#160;They work to make sure that businesses run smoothly and are successful.&#160;Click on the tabs to learn more about some of these tasks:</p><p>Writing Reports</p><p>Writing reports is a task that someone who works in Business Management &amp; Administration might do.&#160;It involves summarizing information in an organized way so that it can be easily understood and used by other people.</p><p>Making Decisions</p><p>This task involves evaluating different options and choosing the best one for a given situation. This could be deciding which supplier to use for a company’s materials, or what changes need to be made to a business plan.</p><p>Setting Goals</p><p>An important part of improving a business is setting goals. These goals might be related to sales, customer service, or overall profitability.</p><p>Managing Finances</p><p>People in this career cluster often need to manage the finances of their companies or organizations. This includes developing budgets, tracking expenses, and making sure that the money is being spent in the right areas.</p><p>Negotiating Deals</p><p>Negotiating deals is an important task for business leadership positions. This involves reaching an agreement between two parties that is beneficial to both.</p><p>Public Relations</p><p>It’s important for a business to make sure that the public has a good impression of their company or organization. People charged with public relations (PR) tasks may organize press conferences, respond to customer inquiries, and manage the company’s website and social media accounts.</p><p>Recruiting and Hiring</p><p>Those involved in HR spend time recruiting new employees and deciding which candidates are the best fit for certain positions by reading resumes and hosting interviews.</p><p>Problem Solving</p><p>Running a business is not without its problems. Overcoming those obstacles requires people to look at a problem from different angles, think of possible solutions, and then implement the best one.</p><p>Next Tab</p><p>.</p><p>As you can see, there are many tasks required to help a business run successfully.&#160;Many of these tasks are unique to certain positions, while others are common in multiple positions.&#160;For example, an accountant might have little to do with the recruiting process that concerns the HR manager, but both will run into obstacles that will require them to spend time problem-solving.&#160;As you study careers in this cluster in more detail, you will find which tasks are typical for those careers.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c1191e0fc3e47fac1f40e1fdfadae9b0','career-exploration-m4-l5-lesson-4','5b5a08f65bfb47b9c9d85cc971872619','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Skills for Business, Manag, Admin Careers</h3><p>Skills for Business, Manag, Admin Careers</p><p>Skills, Abilities, and Talents Needed for a Career in Business, Management &amp; Administration</p><p>The jobs in the Business, Management &amp; Administration career cluster vary greatly, so the skills, abilities, and talents do as well.&#160;Let’s take a look at some of those skills, abilities, and talents:</p><p>Analytical Skills</p><p>The ability to collect, gather, visualize, and analyze information to understand complex concepts and problems.</p><p>Communication</p><p>The ability to talk and write clearly so that others can understand what you are saying.</p><p>Data Comprehension</p><p>The ability to understand data in a variety of forms and what it means for a given situation.</p><p>Decision-Making</p><p>The ability to make decisions that are in the best interest of the business.</p><p>Leadership Skills</p><p>The ability to guide and motivate others to reach a common goal.</p><p>Mathematics</p><p>The study of numbers, patterns, and shapes.</p><p>Organization</p><p>The ability to plan and organize tasks in order to achieve a goal.</p><p>Problem-Solving</p><p>The ability to identify a problem and come up with creative solutions.</p><p>Time Management</p><p>The ability to manage your own time and the time of others in order to reach a goal in a timely manner.</p><p>Understanding of financial principles</p><p>The ability to understand how to manage finances including budgeting, saving, investing, and risk management</p><p>Now that you have a foundational understanding of these skills, match the best skill to the situation:</p><p>Skill, Talent, or Ability</p><p>Really Cool Business Co.&#160;needs to figure out how to get their entire inventory online and Sam has been appointed to figure out the project from start to finish by gathering and collecting the necessary data to understand the problem.</p><p>Data comprehension</p><p>Angela is the trainer at a department store, and she has a group of new hires that she needs to teach about the company’s philosophy, explain the daily procedures, and help everyone understand their role.</p><p>Mathematics</p><p>Jaya has been tasked with deciding if it is worth the expense to invest in new machinery for the company.</p><p>Problem-Solving</p><p>Alfred has been given a group of underperforming employees to lead because he has a proven track record of helping struggling employees reach a common goal.</p><p>Organization</p><p>A previous employee left all of the company’s marketing information in random databases.&#160;Ebony must find the data and put it in a logical place where everyone can easily find and access the information.</p><p>Understanding of Financial Principles</p><p>People keep leaving their online shopping carts before checking out online and Preston must figure out a solution that encourages them to continue through the checkout process.</p><p>Communication</p><p>Alicia needs to use formulas to create sales predictions for next quarter.</p><p>Analytical skills</p><p>Aaron must make sense of the charts, graphs, and tables related to the company’s performance that his boss gave him.</p><p>Leadership</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Really Cool Business Co. needs to figure out how to get their entire inventory online and Sam has been appointed to figure out the project from start to finish by gathering and collecting the necessary data to understand the problem.</p><p>Answers for question: 1</p><p>Problem-Solving</p><p>Organization</p><p>Mathematics</p><p>Communication</p><p>Data comprehension</p><p>Leadership</p><p>Analytical skills</p><p>Understanding of Financial Principles</p><p>2.</p><p>Angela is the trainer at a department store, and she has a group of new hires that she needs to teach about the company’s philosophy, explain the daily procedures, and help everyone understand their role.</p><p>Answers for question: 2</p><p>Organization</p><p>Understanding of Financial Principles</p><p>Data comprehension</p><p>Communication</p><p>Problem-Solving</p><p>Analytical skills</p><p>Leadership</p><p>Mathematics</p><p>3.</p><p>Jaya has been tasked with deciding if it is worth the expense to invest in new machinery for the company.</p><p>Answers for question: 3</p><p>Organization</p><p>Problem-Solving</p><p>Analytical skills</p><p>Leadership</p><p>Mathematics</p><p>Data comprehension</p><p>Communication</p><p>Understanding of Financial Principles</p><p>4.</p><p>Alfred has been given a group of underperforming employees to lead because he has a proven track record of helping struggling employees reach a common goal.</p><p>Answers for question: 4</p><p>Analytical skills</p><p>Mathematics</p><p>Communication</p><p>Data comprehension</p><p>Leadership</p><p>Understanding of Financial Principles</p><p>Organization</p><p>Problem-Solving</p><p>5.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a7705bf09cc8e8d1c817fea7955a5473','career-exploration-m4-l6-lesson-5','5b5a08f65bfb47b9c9d85cc971872619','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Training &amp; Education Requirements</h3><p>Training &amp; Education Requirements</p><p>Training and Education Requirements</p><p>The jobs in the Business, Management &amp; Administration career cluster have widely differing education and training requirements.&#160;Click through the slideshow to learn about some of the jobs and the education and training they require:</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>High school diploma:&#160;Earning a diploma is typically required for jobs such as data entry clerk, human resources assistant, and administrative assistant.&#160;Some positions, such as sales associates, may even be available to those in high school.</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;4</p><p>Next</p><p>Associate degree: An associate degree is a two-year undergraduate degree from a college or university. It typically focuses on a particular field of study. Some jobs requiring an associate degree in this cluster include office manager, sales manager, and payroll specialist.</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;4</p><p>Next</p><p>Bachelor’s degree: A bachelor’s degree is an academic degree awarded by colleges and universities after completion of an undergraduate program. It is typically achieved in four years. Jobs that typically require a bachelor’s degree include project manager, financial manager, and business analyst.</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;4</p><p>Next</p><p>Master’s degree or higher: A master’s degree is an advanced academic degree awarded after two additional years of study and coursework beyond a bachelor’s degree. Jobs typically requiring an advanced degree include marketing director, management consultant, and chief financial officer.</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;4</p><p>Next</p><p>See if you can match the career to the correct education level.&#160;Drag the question into the correct educational level.</p><p>If you are using a keyboard to navigate, you must use the following alternative activity to receive credit.</p><p>High school diploma or less</p><p>Associate degree</p><p>Bachelor&#39;s degree</p><p>Master&#39;s degree or higher</p><p>Alternative Activity</p><p>Match up each choice with a category.</p><p>1. Sales associate&#160;High school diploma or less&#160;Associate degree&#160;Bachelor&#39;s degree&#160;Master&#39;s degree or higher</p><p>2. Payroll specialist&#160;High school diploma or less&#160;Associate degree&#160;Bachelor&#39;s degree&#160;Master&#39;s degree or higher</p><p>3. Financial manager&#160;High school diploma or less&#160;Associate degree&#160;Bachelor&#39;s degree&#160;Master&#39;s degree or higher</p><p>4. Marketing director&#160;High school diploma or less&#160;Associate degree&#160;Bachelor&#39;s degree&#160;Master&#39;s degree or higher</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7066f0a13f287129ddc421b078229c63','career-exploration-m4-l7-module-4-summary','5b5a08f65bfb47b9c9d85cc971872619','Module 4 Summary','text',12,'<h2>Module 4 Summary</h2><section><h3>Module 4 Summary</h3><p>Module 4 Summary</p><p>Great Work!&#160;You have successfully completed this module on Business, Management &amp; Administration.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified the pathways in the Business, Management &amp; Administration career cluster and the careers in each pathway.</p><p>Described the types of places that employ individuals who have careers in the Business Management &amp; Administration career cluster.</p><p>Described the variety of tasks performed by individuals who have careers in the Business Management &amp; Administration career cluster.</p><p>Listed the skills, abilities, and talents needed for careers in the Business Management &amp; Administration career cluster.</p><p>Identified the level of training and education required for careers in the Business Management &amp; Administration career cluster.</p><p>Researched a career in the Business Management &amp; Administration career cluster and present findings to the class.</p><p>Applied math, science, and reading skills in the completion of a project or activity related to the Business Management &amp; Administration career cluster.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('88e70bd66124d61e1d9fc409e2207f8a','career-exploration-m4-l8-module-4-project','5b5a08f65bfb47b9c9d85cc971872619','Module 4 Project','text',12,'<h2>Module 4 Project</h2><section><h3>Module 4 Project</h3><p>Module 4 Project</p><p>Career Exploration</p><p>Business, Management &amp; Administration - Project</p><p>Business, Administration &amp; Management - Project</p><p>For this project, you will choose from two options.&#160; You only need to complete one of these options.&#160; Please find both options and their rubrics below.</p><p>Option 1:&#160;For this project, you will create a slide presentation (using PowerPoint or similar software) to present a business plan for a business of your own imagination. Your presentation should include the following:</p><p>An overview of the business including the name of the business and the products or services it provides.</p><p>The positions of key employees (ex: customer service representative) and a brief overview of what those individuals do.</p><p>A customer service plan.</p><p>A marketing plan to tell people about the new business.</p><p>This presentation will have four slides total (one slide for each of the bullet points above) and should be sent directly to your teacher.</p><p>Option 1 Rubric: Business, Management &amp; Administration Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Overview</p><p>5 points The name and summary of the business are well thought out and clear.</p><p>3-4 points The name and summary of the business are mostly well thought out and clear.</p><p>0-2 points The name and summary of the business are mostly well thought out and clear.</p><p>5</p><p>Key Positions</p><p>5 points The list of key employees represents an excellent understanding of these roles and their impact on the business.</p><p>3-4 points The list of key employees represents an adequate understanding of these roles and their impact on the business.</p><p>0-2 points 5 points The list of key employees represents a poor understanding of these roles and their impact on the business.</p><p>5</p><p>Customer Service Plan</p><p>5 points The slides show a well-thought-out customer service plan that is applicable to the business.</p><p>3-4 points The slides show an adequate customer service plan that is mostly applicable to the business.</p><p>0-2 points The slides show a poor customer service plan that is not applicable to the business.</p><p>5</p><p>Marketing Plan</p><p>5 points The slides show a well-thought-out marketing plan that is applicable to the business.</p><p>3-4 points The slides show an adequate marketing plan that is mostly applicable to the business.</p><p>0-2 points The slides show a poor marketing plan that is not applicable to the business.</p><p>5</p><p>Total Points:&#160;20</p><p>Option 2</p><p>For this option, you will research a particular career that interests you in this cluster. Complete the following steps for your project:</p><p>Step 1: Research your chosen career.</p><p>Step 2: List the following</p><p>Average Salary/Salary Range</p><p>Education Requirements</p><p>Certification Requirements (if any)</p><p>Why you chose that career</p><p>Step 3: Prepare a PowerPoint presentation about your chosen career, including the information you gathered in Step 2 as well as your reason for choosing that career.</p><p>Your final submission should be your PowerPoint containing the information in Step 3.</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 2 Rubric: Business, Management &amp; Administration Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Research</p><p>12 points The student provided a career field that interested them, the average salary or range, and the education/certifications required for the career.</p><p>11-4 points The student provided two of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>3-0 points The student provided one or none of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>12</p><p>Reason for Choosing the Career Field</p><p>4 points The student thoughtfully provided the reason that they are interested in this career.</p><p>N/A</p><p>0 points The student did not provide the reason that they are interested in this career.</p><p>4</p><p>Formatting</p><p>4 points The student&#39;s presentation includes no spelling or grammatical errors.</p><p>3-1 points The student&#39;s presentation includes minimal spelling or grammatical errors.</p><p>0 points The student&#39;s presentation includes a significant amount of spelling or grammatical errors.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('696cdcccc40f4ad620838d6991c58f76','career-exploration-m4-l9-module-4-quiz','5b5a08f65bfb47b9c9d85cc971872619','Module 4 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Business, Managem, Admin. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('4c8fd4871b9d3e75ac9bebbd02ff0895','career-exploration-module-5','68d48b60cc4feb626956ed1fd8311e46','Module 5: Education & Training',5) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('605aa2ecdbfda2095eeef85fe293e765','career-exploration-m5-l1-introduction-purpose-and-objectives','4c8fd4871b9d3e75ac9bebbd02ff0895','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Mute</p><p>Welcome to this module on the Education &amp; Training career cluster.</p><p>If you’re sitting at a desk doing school work, learning about careers in the Education and Training cluster may be near the bottom of your list of jobs that sound exciting, but I want you to consider three things:</p><p>Education and training is a growing field. Jobs in this field are expected to grow by 6% in the next decade, so there&#39;s plenty of opportunity for career growth.</p><p>The opportunities out there are more than they may appear at first glance. Whether you&#39;re interested in working with kids or adults, in a classroom or a corporate setting, there&#39;s a job in education and training for you. Want to live overseas and travel the world? A job in education and training can open that door for you.</p><p>And 3. Teachers and trainers are in a unique position to help people learn and grow, and they often report feeling satisfied with their careers.</p><p>So if you are looking for more than just a paycheck, consider a fulfilling career in education and training. We have so much in store for you in this module. You’ll learn about the different pathways for professionals in this cluster and the careers in that cluster. Oh, and did I mention that teachers (while great!) are only one career of many in this cluster? You’ll also learn about what those other careers are as well.</p><p>We’ll explore where you may work and some of the tasks you may find yourself doing in this career cluster. Of course, if this cluster seems interesting to you, you’ll want to start getting your toes wet, so to speak, and knowing what skills, talents, and abilities you need to be successful in this career is important. Finally, we’ll talk about the education required for some of the different jobs in this career cluster. It&#39;s all coming up in this module, so let’s get started!</p><p>Module Description</p><p>Welcome to this module on the Education &amp; Training career cluster!&#160;In this module, you will discover the three pathways in this cluster.&#160;Whether it’s working as a corporate trainer, a guidance counselor, or a coach, we will discuss the types of places that employ individuals in this field and the variety of tasks they perform.&#160;You will also learn about the skills, abilities, and talents needed for careers in this field, as well as the level of training and education required for the different types of careers.&#160;After successfully completing the lessons in this module, you will have sufficient background knowledge to complete the end-of-module project which will give you further insight into the activities related to this career cluster.</p><p>Objectives</p><p>In this module, students will</p><p>Identify the pathways in the Education &amp; Training career cluster and the careers in each pathway.</p><p>Describe the types of places that employ individuals who have careers in the Education &amp; Training career cluster.</p><p>Describe the variety of tasks performed by individuals who have careers in the Education &amp; Training career cluster.</p><p>List the skills, abilities, and talents needed for careers in the Education &amp; Training career cluster.</p><p>Identify the level of training and education required for careers in the Education &amp; Training career cluster.</p><p>Research a career in the Education &amp; Training career cluster and present findings to the class.</p><p>Apply math, science, and reading skills in the completion of a project or activity related to the Education &amp; Training career cluster.</p><p>Polling Question</p><p>Which career in the Education &amp; Training cluster sounds most interesting to you?</p><p>Principal&#160;Coach&#160;Counselor&#160;Teacher&#160;Other</p><p>Results:</p><p>Teacher&#160;66%</p><p>Counselor&#160;33%</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Warning:&#160;json_decode() expects parameter 1 to be string, object given in&#160;/srv/app/current/blocks/interactive_definitions/controller.php&#160;on line&#160;238</p><p>Talking with someone who is trained to help you figure out your feelings and how to make decisions.</p><p>Instruction</p><p>Learning how to do something in order to be better at it.</p><p>Counseling</p><p>Telling someone how to do something so that they can do it correctly.</p><p>Training</p><p>Someone who is responsible for managing and organizing a group or organization.</p><p>Administrator</p><p>Learning different skills and information so that you can understand more about the world.</p><p>Education</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Talking with someone who is trained to help you figure out your feelings and how to make decisions.</p><p>Answers for question: 1</p><p>Administrator</p><p>Education</p><p>Instruction</p><p>Counseling</p><p>Training</p><p>2.</p><p>Learning how to do something in order to be better at it.</p><p>Answers for question: 2</p><p>Education</p><p>Administrator</p><p>Training</p><p>Counseling</p><p>Instruction</p><p>3.</p><p>Telling someone how to do something so that they can do it correctly.</p><p>Answers for question: 3</p><p>Training</p><p>Education</p><p>Counseling</p><p>Instruction</p><p>Administrator</p><p>4.</p><p>Someone who is responsible for managing and organizing a group or organization.</p><p>Answers for question: 4</p><p>Instruction</p><p>Counseling</p><p>Training</p><p>Administrator</p><p>Education</p><p>5.</p><p>Learning different skills and information so that you can understand more about the world.</p><p>Answers for question: 5</p><p>Instruction</p><p>Education</p><p>Training</p><p>Administrator</p><p>Counseling</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5c87baee9d1ff3242e039e90d74220af','career-exploration-m5-l2-lesson-1','4c8fd4871b9d3e75ac9bebbd02ff0895','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>What is Education &amp; Training Career Cluster</h3><p>What is Education &amp; Training Career Cluster</p><p>What is the Education &amp; Training Career Cluster?</p><p>The Education and Training career cluster is a group of jobs that involve helping people to learn and develop new skills.&#160;It includes jobs like teachers, guidance counselors, coaches, and trainers.&#160;These types of jobs help people to learn and understand new things, which can help them to get better jobs and be successful in life.&#160;For example, a teacher might help a student to understand math so that the student can do well in school and get a good job when he or she grows up.&#160;A coach might help a student to learn how to play a sport so that they can be more competitive and have fun.&#160;A guidance counselor might help a student to figure out what career path is best for them and how to reach their goals.</p><p>There are three primary pathways in this career cluster.&#160;Click on the hot spot image below to learn more about each one:</p><p>5</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Pathways in the Education &amp; Training Career Cluster.</p><p>The hotspot points on the image are as follows:</p><p>Administration &amp; Administrative Support Pathway</p><p>This pathway focuses on providing support to educational organizations. It includes managing, planning, and coordinating activities associated with educational organizations, such as educational policies, procedures, programs, and services. Jobs you may be familiar with in this pathway include principals, curriculum developer, and assessment specialists.</p><p>Teaching/Training Pathway</p><p>This pathway focuses on providing instruction to students and others. They may teach academic subjects, sports, or life skills. Individuals in this pathway work to help those they teach achieve goals, learn new skills, and improve their abilities. Examples of jobs in this pathway include school teacher, physical trainer, and coach.</p><p>Professional Support Services Pathway</p><p>This pathway focuses on providing services to educational organizations and students. The professionals in this pathway work to ensure that students are receiving the best possible education and that the educational system is functioning properly. They also work with administrators to implement policies to ensure the success of the school system. Jobs in this pathway include speech-language pathologist, social worker, and counselor.</p><p>Now that you’ve read about the different pathways and corresponding careers, match the career to the correct pathway.</p><p>Administration &amp; Administrative Support Pathway</p><p>Professional Support Services Pathway</p><p>Teaching/Training Pathway</p><p>Speech-language pathologist</p><p>Principal</p><p>Assessment specialist</p><p>Counselor</p><p>Physical trainer</p><p>Coach</p><p>Curriculum developer</p><p>Social worker</p><p>School teacher</p><p>Alternative Activity</p><p>Categorize each of the following</p><p>Speech-language pathologist&#160;Administration &amp; Administrative Support Pathway&#160;Professional Support Services Pathway&#160;Teaching/Training Pathway</p><p>Principal&#160;Administration &amp; Administrative Support Pathway&#160;Professional Support Services Pathway&#160;Teaching/Training Pathway</p><p>Social worker&#160;Administration &amp; Administrative Support Pathway&#160;Professional Support Services Pathway&#160;Teaching/Training Pathway</p><p>Assessment specialist&#160;Administration &amp; Administrative Support Pathway&#160;Professional Support Services Pathway&#160;Teaching/Training Pathway</p><p>Counselor&#160;Administration &amp; Administrative Support Pathway&#160;Professional Support Services Pathway&#160;Teaching/Training Pathway</p><p>School teacher&#160;Administration &amp; Administrative Support Pathway&#160;Professional Support Services Pathway&#160;Teaching/Training Pathway</p><p>Physical trainer&#160;Administration &amp; Administrative Support Pathway&#160;Professional Support Services Pathway&#160;Teaching/Training Pathway</p><p>Coach&#160;Administration &amp; Administrative Support Pathway&#160;Professional Support Services Pathway&#160;Teaching/Training Pathway</p><p>Curriculum developer&#160;Administration &amp; Administrative Support Pathway&#160;Professional Support Services Pathway&#160;Teaching/Training Pathway</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c46147cc608712e48c4b3b4cb5369de9','career-exploration-m5-l3-lesson-2','4c8fd4871b9d3e75ac9bebbd02ff0895','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Education &amp; Training Career Work</h3><p>Education &amp; Training Career Work</p><p>License:&#160;No known copyright restrictions</p><p>Where People in the Education &amp; Training Career Cluster Work</p><p>When you think of education, the first thing that likely pops into your mind is “school”.&#160;So you might be thinking that people in this career cluster are limited to working in schools and classrooms.&#160;Actually, there are many places where someone in this career cluster may find employment.&#160;Click places below to learn more:</p><p>Schools</p><p>Schools employ a range of individuals with education and training careers, including teachers, administrators, counselors, and librarians.</p><p>Non-Profit Organizations</p><p>Non-profit organizations that focus on educational programming often employ individuals with educational and training backgrounds. Examples include organizations that provide after-school programs, tutoring services, and enrichment activities.</p><p>Colleges and Universities</p><p>Colleges and universities employ a range of individuals with education and training careers, including professors, researchers, and student advisors.</p><p>Libraries</p><p>Libraries employ librarians and other professionals with education and training backgrounds.</p><p>Government Agencies</p><p>Government agencies employ individuals with education and training backgrounds to provide services such as adult literacy and workforce training.</p><p>Private Companies</p><p>Private companies often employ individuals with education and training backgrounds to develop and deliver training programs.</p><p>Professional Associations</p><p>Professional associations often employ individuals with education and training backgrounds to provide professional development and continuing education opportunities to their members.</p><p>As you can see, people in this career cluster work in a variety of places.&#160;These people appreciate the experience that comes with a background in education and training such as being able to work with a variety of people, excellent communication skills, and leadership skills.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('d8dec27812cdb1eb2dad2be3df746be9','career-exploration-m5-l4-lesson-3','4c8fd4871b9d3e75ac9bebbd02ff0895','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Activities for Education &amp; Training Career</h3><p>Activities for Education &amp; Training Career</p><p>Activities in the Education &amp; Training Career Cluster</p><p>The Education &amp; Training career cluster is focused on helping people to learn and develop new skills.&#160;This is a big undertaking and a lot of work goes into making this happen.&#160;Here are some of the common tasks people in this career cluster perform.&#160;Click on each tab to learn more:</p><p>Curriculum development</p><p>Creating curricula and educational programs tailored to specific student populations.</p><p>Lesson planning</p><p>Coming up with interesting ways to present learning material.</p><p>Advising students</p><p>Providing advice and support to students in areas such as career and academic planning.</p><p>Administrative tasks</p><p>Overseeing the operations of educational systems and institutions. This may also include budgeting, hiring, and other administrative duties.</p><p>Assessment and evaluation</p><p>Using tools such as tests, assignments, and projects to measure a student’s progress and understanding of a particular subject, skill, or course.</p><p>Coaching</p><p>Providing guidance and support to those they work with throughout the learning process.</p><p>Research</p><p>Exploring educational and learning theories and practices in order to develop effective strategies for teaching and learning as well as researching specific subjects related to what they are teaching.</p><p>Classroom management</p><p>Creating a safe and positive learning environment that encourages a sense of community within the classroom.</p><p>Teaching</p><p>Presenting a new skill or area of knowledge in a way that is appropriate for the learning population.</p><p>Resource development</p><p>Creating resources that facilitate learning and understanding.</p><p>Next Tab</p><p>Now that you know about some of the tasks in this career cluster, see if you can match the scenario to the correct task:</p><p>Task to Perform</p><p>Paul needs to create a flowchart for the newly hired employees he needs to train.</p><p>Teaching</p><p>Amy’s third-grade class is watching her as she explains fractions.</p><p>Resource development</p><p>Andrew needs to address a bullying issue between some of the members of his class.</p><p>Assessment and evaluation</p><p>Claudia is looking up facts in books and online to determine the most appropriate way to create an online course for company training.</p><p>Lesson planning</p><p>Lucy is supporting her personal training clients as they navigate the challenges of getting fit.</p><p>Research</p><p>Miles wants to make sure his class has mastered the appropriate use of commas in sentences.</p><p>Advising students</p><p>Sal has a student that is looking for guidance on what to take next semester.</p><p>Curriculum development</p><p>Amal needs to create policies about the appropriate use of cell phones in the halls.</p><p>Coaching</p><p>Lily is spending time planning how she will present her lesson on customer service tomorrow.</p><p>Classroom management</p><p>Thora started an after-school baking class and needs to prepare what she is going to teach for the next 8 weeks to a group of 10-year-olds.</p><p>Administrative tasks</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Paul needs to create a flowchart for the newly hired employees he needs to train.</p><p>Answers for question: 1</p><p>Curriculum development</p><p>Coaching</p><p>Assessment and evaluation</p><p>Resource development</p><p>Administrative tasks</p><p>Lesson planning</p><p>Teaching</p><p>Research</p><p>Advising students</p><p>Classroom management</p><p>2.</p><p>Amy’s third-grade class is watching her as she explains fractions.</p><p>Answers for question: 2</p><p>Coaching</p><p>Curriculum development</p><p>Assessment and evaluation</p><p>Advising students</p><p>Resource development</p><p>Classroom management</p><p>Administrative tasks</p><p>Lesson planning</p><p>Research</p><p>Teaching</p><p>3.</p><p>Andrew needs to address a bullying issue between some of the members of his class.</p><p>Answers for question: 3</p><p>Classroom management</p><p>Research</p><p>Lesson planning</p><p>Assessment and evaluation</p><p>Coaching</p><p>Teaching</p><p>Resource development</p><p>Curriculum development</p><p>Administrative tasks</p><p>Advising students</p><p>4.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('dc33eb4ae241eeda7c89145875584964','career-exploration-m5-l5-lesson-4','4c8fd4871b9d3e75ac9bebbd02ff0895','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Skills for Education &amp; Training Careers</h3><p>Skills for Education &amp; Training Careers</p><p>Skills, Abilities, and Talents Needed for a Career in Education &amp; Training</p><p>What makes a great teacher, counselor, trainer, or other professional in this career cluster?&#160;While some of the characteristics are going to be dependent on the exact profession, there are many skills that are applicable to a variety of jobs within the Education and Training career cluster.&#160;Click through the slideshow to learn about some of these skills, abilities, and talents:</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Communication Skills:&#160;The ability to effectively communicate with students, parents, and other staff members is essential for success in the Education &amp; Training career cluster.&#160;This includes being able to explain topics clearly, respond to questions, and give feedback.</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;6</p><p>Next</p><p>The ability to create and deliver engaging and effective lessons is essential for educators and trainers. This includes being able to create lesson plans, use appropriate technology, and assess student progress.</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;6</p><p>Next</p><p>Interpersonal skills are important for building relationships with students, parents, and other staff members. This includes being patient, understanding, and being able to work collaboratively with others.</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;6</p><p>Next</p><p>Organization and Time Management: Time management and organizational skills are necessary to manage multiple tasks and create lesson plans. This includes being able to prioritize tasks, plan ahead, and think critically.</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;6</p><p>Next</p><p>Leadership Skills: Leadership skills are essential for managing learners and inspiring them to succeed. This includes being able to motivate and provide guidance to students, as well as delegate tasks to staff members.</p><p>Previous</p><p>Slide&#160;5&#160;of&#160;6</p><p>Next</p><p>Creativity: Being able to think creatively is important for finding new and innovative ways to teach and engage students. This includes being able to come up with creative ideas for lessons and activities.</p><p>Previous</p><p>Slide&#160;6&#160;of&#160;6</p><p>Next</p><p>There are many opportunities around you right now to develop some of these skills.&#160;Click on each one to learn more:</p><p>Youth organizations</p><p>Joining a youth organization such as 4-H or Future Farmers of America to gain leadership and communication skills.</p><p>Volunteering</p><p>Volunteering at a local library or after-school program to gain experience working with children and adults.</p><p>Tutoring</p><p>Working as a tutor to help younger students with their studies and build confidence in their ability to learn and helps you develop instructional skills.</p><p>Extracurricular activities</p><p>Participating in extracurricular activities such as student government, debate team, or art to practice public speaking, interpersonal skills, and creativity.</p><p>As you can see, skill and talent development in this career cluster can start now!</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b8bc7e7ec8107e5f633f90388fefcd54','career-exploration-m5-l6-lesson-5','4c8fd4871b9d3e75ac9bebbd02ff0895','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Jobs in Training &amp; Education Requirements</h3><p>Jobs in Training &amp; Education Requirements</p><p>Training and Education Requirements</p><p>As you’ve learned, there are many jobs in the Education and Training career cluster.&#160;These jobs require particular amounts of schooling.&#160;For example, a teacher needs to go to college and get a teaching certificate, while a coach may just need a high school diploma.&#160;Administrators typically have a master’s degree or higher.</p><p>Here are some of the most common jobs in this career cluster and the required training and education for each one:</p><p>Principal</p><p>Principals must have a master’s degree in education or a related field and a valid state administrative credential. They must also have experience teaching in a school setting and a demonstrated record of successful school administration.</p><p>Coach</p><p>The education requirements to become a coach vary depending on the level of coaching. Generally, most coaches need at least a high school diploma or equivalent. For college coaching, most coaches need at least a bachelor’s degree in a related field. Many coaches also need additional certifications and licenses, depending on the sport and the level of coaching.</p><p>Teacher</p><p>Teachers must have a bachelor’s degree in education or a related field and a valid teaching credential. They must also have experience teaching in a school setting and a demonstrated record of effective instruction.</p><p>Guidance Counselor</p><p>Guidance counselors must have a master&#39;s degree in counseling or a related field and a valid state counseling credential. They must also have experience providing counseling services in a school setting and a demonstrated record of successful counseling.</p><p>School Psychologist</p><p>School psychologists must have a master’s degree in psychology or a related field and a valid state psychology credential. They must also have experience providing psychological services in a school setting and a demonstrated record of successful psychological counseling.</p><p>Teacher&#39;s Aide</p><p>Teacher&#39;s aides must have a high school diploma or equivalent and may be required to have a valid state teaching aide credential. They must also have experience working in a school setting and a demonstrated record of providing effective assistance to teachers.</p><p>Instructional Coordinator</p><p>Instructional coordinators must have a master’s degree in education or a related field and a valid state instructional credential. They must also have experience coordinating instruction in a school setting and a demonstrated record of successful program coordination.</p><p>Speech-language pathologist</p><p>In order to become a speech-language pathologist, an individual must have a Master&#39;s degree in Speech-Language Pathology from an accredited university. Additionally, a speech-language pathologist must complete a supervised clinical fellowship of at least 375 hours, as well as pass a national examination administered by the American Speech-Language-Hearing Association (ASHA). In some states, an additional state licensure exam may be required.</p><p>It&#39;s probably not surprising that formal education plays a big role in qualifying for jobs in this career cluster.&#160;By obtaining sufficient education to match the jobs you are interested in, you’ll set yourself up to be a successful candidate for the position.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1304f0e42a72bf03d71cc497572f6cd5','career-exploration-m5-l7-module-5-summary','4c8fd4871b9d3e75ac9bebbd02ff0895','Module 5 Summary','text',12,'<h2>Module 5 Summary</h2><section><h3>Module 5 Summary</h3><p>Module 5 Summary</p><p>Great Work!&#160;You have successfully completed this module&#160;on Education &amp; Training.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified the pathways in the Education &amp; Training career cluster and the careers in each pathway.</p><p>Described the types of places that employ individuals who have careers in the Education &amp; Training career cluster.</p><p>Described the variety of tasks performed by individuals who have careers in the Education &amp; Training career cluster.</p><p>Listed the skills, abilities, and talents needed for careers in the Education &amp; Training career cluster.</p><p>Identified the level of training and education required for careers in the Education &amp; Training career cluster.</p><p>Researched a career in the Education &amp; Training career cluster and present findings to the class.</p><p>Applied math, science, and reading skills in the completion of a project or activity related to the Education &amp; Training career cluster.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('18221ccf64ca9c60e9c9621818dde0f9','career-exploration-m5-l8-module-6-project','4c8fd4871b9d3e75ac9bebbd02ff0895','Module 6 Project','text',12,'<h2>Module 6 Project</h2><section><h3>Module 5 Project</h3><p>Module 5 Project</p><p>Career Exploration</p><p>Education &amp; Training - Project</p><p>For this project, you will choose from two options.&#160; You only need to complete one of these options.&#160; Please find both options and their rubrics below.</p><p>Option 1:&#160;For this project, you will create a lesson plan. It can be on any subject or skill you&#39;d like! It should include the following:</p><p>Lesson objective (the learning goal, what the students/learners should be able to do or understand by the end of the lesson)</p><p>A list of skills or knowledge the student should know before starting the new material.</p><p>Materials needed (pens, paper, technology, equipment, etc.)</p><p>A description of how you will present the lesson in an engaging way.</p><p>How you will assess students&#39; understanding of the subject.</p><p>Your final submission should include a document with the information listed above.</p><p>Option 1 Rubric: Education &amp; Training Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Objectives</p><p>4 points Objectives are clearly stated and aligned with the lesson.</p><p>3 points Objectives are adequately stated and mostly aligned with the lesson.</p><p>0-2 points Objectives are unclear and/or do not align with the lesson.</p><p>4</p><p>Background Knowledge</p><p>4 points All applicable background knowledge/skills specific to the lesson have been identified.</p><p>3 points Most applicable background knowledge/skills specific to the lesson have been identified.</p><p>0-2 points Applicable background knowledge/skills specific to the lesson have not been identified.</p><p>4</p><p>Materials List</p><p>4 points Includes a thorough list of materials needed for the teacher and students.</p><p>3-4 points Includes a list of materials needed for the teacher and students though some materials may be missing.</p><p>0-2 points Does not include a materials list and/or many materials are missing.</p><p>4</p><p>Teaching Plan</p><p>4 points Includes an engaging description of how the material would be taught in a lesson.</p><p>3 points Includes a somewhat engaging description of how the material would be taught in a lesson.</p><p>0-2 points Does not include a description of how the material would be taught or the description is inadequate.</p><p>4</p><p>Assessment</p><p>4 points Includes an applicable plan for how to assess student learning.</p><p>3 points Includes a somewhat applicable plan for how to assess student learning.</p><p>0-2 points Does not include an assessment plant and/or the plan would not reflect student learning.</p><p>4</p><p>Total Points:&#160;20</p><p>Option 2</p><p>For this option, you will research a particular career that interests you in this cluster. Complete the following steps for your project:</p><p>Step 1: Research your chosen career.</p><p>Step 2: List the following</p><p>Average Salary/Salary Range</p><p>Education Requirements</p><p>Certification Requirements (if any)</p><p>Why you chose that career</p><p>Step 3: Prepare a PowerPoint presentation about your chosen career, including the information you gathered in Step 2 as well as your reason for choosing that career.</p><p>Your final submission should be your PowerPoint containing the information in Step 3.</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 2 Rubric: Education &amp; Training Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Research</p><p>12 points The student provided a career field that interested them, the average salary or range, and the education/certifications required for the career.</p><p>11-4 points The student provided two of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>3-0 points The student provided one or none of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>12</p><p>Reason for Choosing the Career Field</p><p>4 points The student thoughtfully provided the reason that they are interested in this career.</p><p>N/A</p><p>0 points The student did not provide the reason that they are interested in this career.</p><p>4</p><p>Formatting</p><p>4 points The student&#39;s presentation includes no spelling or grammatical errors.</p><p>3-1 points The student&#39;s presentation includes minimal spelling or grammatical errors.</p><p>0 points The student&#39;s presentation includes a significant amount of spelling or grammatical errors.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('30b6a312ffb9d5035d39723874c5d6ad','career-exploration-m5-l9-module-5-quiz','4c8fd4871b9d3e75ac9bebbd02ff0895','Module 5 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Education & Training. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('3db84b7c905814af2e498fad6e931082','career-exploration-module-6','68d48b60cc4feb626956ed1fd8311e46','Module 6: Finance',6) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('61c79ac014f2bf8d4b92cff7e8f24161','career-exploration-m6-l1-introduction-purpose-and-objectives','3db84b7c905814af2e498fad6e931082','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hello and welcome to this module on the Finance Career Cluster.</p><p>In 2008, the global financial crisis began when the U.S. housing market collapsed. Banks had been lending money to borrowers with poor credit histories. So when the housing market crashed, the global economy went into a tailspin. Governments around the world had to bail out banks to prevent the crisis from getting worse. Many jobs were lost, fortunes were destroyed, and many people went through financial hardships for many years after the crisis.</p><p>Why am I sharing this story?</p><p>Because I want to share how important the Finance cluster is! Even one piece of the finance world, like banks lending money to borrowers with poor credit histories, can impact the entire world.</p><p>But don’t worry, it’s not all doom and gloom. In fact, there are a lot of great things about this career cluster!</p><p>For example, there’s a wide variety of career opportunities in the finance cluster that can help you make a difference in the world. From managing investments to helping businesses plan their financial growth, finance professionals provide a critical service for individuals, companies, and governments alike. The finance cluster encompasses a wide range of job roles, such as financial planners, accountants, insurance analysts, investors, bankers... the list is seemingly endless!</p><p>As a finance professional, you’ll have the opportunity to help people understand their financial options and make informed decisions about their money. You’ll also be able to help businesses plan and manage their financial resources effectively. Being a finance professional also offers a great deal of job security, potential for career growth, and high wages. As the global economy continues to evolve, there will be an increasing demand for financial services and professionals.</p><p>With the right qualifications and experience, you can become a highly valued and well-paid professional in the finance sector. The best part is that you don’t have to wait until you’re in college to start preparing for a career in finance. You can start exploring the finance world right now and developing the skills you need to succeed in this career! We’ll talk about those skills in this module. We’ll also talk about the pathways, education, and places of employment in this career cluster.</p><p>We’ve got a lot of great content ahead, so let’s get started!</p><p>Module Description</p><p>License:&#160;No known copyright restrictions</p><p>Welcome to this module on the Finance career cluster!&#160;In this module, you will discover the pathways and careers in this cluster.&#160;The module will also cover the different places of employment, such as banks, accounting firms, and government agencies, that employ professionals in this cluster.&#160;You will also learn about the skills, abilities, and talents needed for careers in this field, as well as the level of training and education required for the different types of careers.&#160;The module will conclude with a project designed to give you experience and application in this cluster.</p><p>Objectives</p><p>In this module, students will</p><p>Identify the pathways in the Finance career cluster and the careers in each pathway.</p><p>Describe the types of places that employ individuals who have careers in the Finance career cluster.</p><p>Describe the variety of tasks performed by individuals who have careers in the Finance career cluster.</p><p>List the skills, abilities, and talents needed for careers in the Finance career cluster.</p><p>Identify the level of training and education required for careers in the Finance career cluster.</p><p>Research a career in the Finance career cluster and present findings to the class.</p><p>Apply math, science, and reading skills in the completion of a project or activity related to the Finance career cluster.</p><p>Polling Question</p><p>Which career in the Finance cluster sounds most interesting to you?</p><p>Financial analyst&#160;Banker&#160;Accountant&#160;Insurance agent&#160;Other</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>A type of protection that helps cover costs if something bad happens, like if you get sick, have an accident, or your home is damaged.</p><p>Securities</p><p>Investments like stocks and bonds that can help you make money.</p><p>Broker</p><p>A type of security that people buy and sell to make money.</p><p>Accounting</p><p>Someone who buys and sells stocks and other investments for other people.</p><p>Stocks</p><p>Putting money into something with the hopes of making a profit</p><p>Investing</p><p>A way of keeping track of money coming in and out of a business.</p><p>Insurance</p><p>Alternative Activity</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c8d0bfd0a63ce22e07190bfd4f53ec86','career-exploration-m6-l2-lesson-1','3db84b7c905814af2e498fad6e931082','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>What is Finance Career Cluster</h3><p>What is Finance Career Cluster</p><p>What is the Finance Career Cluster?</p><p>The Finance Career cluster is a group of jobs that involve working with money.&#160;These jobs could involve helping people and businesses with their investments and savings, managing money, or helping people make smart decisions with their money.&#160;People who work in finance help people and businesses make the most of their money so they can reach their goals and have enough money for the future.</p><p>There are five primary pathways in this cluster.&#160;Click through the slideshow to learn more about these pathways:</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Securities &amp; Investments Pathway:&#160;This pathway focus on buying or selling investments like stocks and bonds.&#160;People in this pathway help people decide what investments are best for them.&#160;Examples of jobs in this pathway include personal financial advisors, financial and investment analysts, and brokerage clerks.</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;5</p><p>Next</p><p>Business Finance Pathway: This pathway deals with helping businesses manage their money. People in this pathway help businesses figure out the best way to use money to get what they need to grow and be successful by managing planning, funding, taxation and more. Some of the jobs in this pathway include budget analysts, financial managers, and treasurers.</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;5</p><p>Next</p><p>Accounting Pathway: This pathway involves keeping track of a company&#39;s money. People in this pathway help companies understand how much money they have and what they need to do to use it well. Some of the careers in this pathway include accountants and auditors.</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;5</p><p>Next</p><p>Insurance Pathway: This pathway deals with protecting people or businesses from financial losses. People in this pathway can help someone buy the right kind of insurance so they are covered if something bad happens. Careers in this pathway include insurance sales agents, insurance underwriters, and claims adjusters.</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;5</p><p>Next</p><p>Banking Services Pathway: This pathway deals with providing banking services. People in this pathway help people save their money in a bank and give them advice on how to use it wisely. Some jobs you may be familiar with in this pathway include loan officers, financial clerks, and tellers.</p><p>Previous</p><p>Slide&#160;5&#160;of&#160;5</p><p>Next</p><p>Now that you know a bit about these pathways, let’s see if you can match the person’s interest to the best pathway for them.</p><p>Pathway</p><p>Andrew enjoys talking to people and can count money back quickly.</p><p>Accounting Pathway</p><p>Lewis likes helping people feel prepared for unexpected events.</p><p>Insurance Pathway</p><p>Laketra is great at tracking the money her mom’s business brings in on weekends.</p><p>Business Finance Pathway</p><p>Trent wants to work for a large company and help them make big plans with their money.</p><p>Banking Services Pathway</p><p>Alisha likes following the stock market and wants to help people grow their wealth.</p><p>Securities &amp; Investments Pathway</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Andrew enjoys talking to people and can count money back quickly.</p><p>Answers for question: 1</p><p>Insurance Pathway</p><p>Securities &amp; Investments Pathway</p><p>Business Finance Pathway</p><p>Banking Services Pathway</p><p>Accounting Pathway</p><p>2.</p><p>Lewis likes helping people feel prepared for unexpected events.</p><p>Answers for question: 2</p><p>Business Finance Pathway</p><p>Accounting Pathway</p><p>Insurance Pathway</p><p>Banking Services Pathway</p><p>Securities &amp; Investments Pathway</p><p>3.</p><p>Laketra is great at tracking the money her mom’s business brings in on weekends.</p><p>Answers for question: 3</p><p>Securities &amp; Investments Pathway</p><p>Business Finance Pathway</p><p>Accounting Pathway</p><p>Insurance Pathway</p><p>Banking Services Pathway</p><p>4.</p><p>Trent wants to work for a large company and help them make big plans with their money.</p><p>Answers for question: 4</p><p>Insurance Pathway</p><p>Business Finance Pathway</p><p>Securities &amp; Investments Pathway</p><p>Banking Services Pathway</p><p>Accounting Pathway</p><p>5.</p><p>Alisha likes following the stock market and wants to help people grow their wealth.</p><p>Answers for question: 5</p><p>Accounting Pathway</p><p>Business Finance Pathway</p><p>Securities &amp; Investments Pathway</p><p>Banking Services Pathway</p><p>Insurance Pathway</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8510cd3a8ad0016c91fa07b816c4fd65','career-exploration-m6-l3-lesson-2','3db84b7c905814af2e498fad6e931082','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Finance Career Cluster Work</h3><p>Finance Career Cluster Work</p><p>License:&#160;No known copyright restrictions</p><p>Where People in the Finance Career Cluster Work</p><p>People in the Finance career cluster find employment in a variety of places.&#160;Click on the tabs to learn about some of those places:</p><p>Banks</p><p>Banks are places where people go to keep their money safe and get loans.&#160;They hire positions such as loan officers, tellers, and financial advisors.</p><p>Investment Companies</p><p>Investment companies are places where people go to invest their money. People who work at investment companies include stockbrokers, financial analysts, and portfolio managers.</p><p>Accounting Firms</p><p>Accounting firms are places where people and businesses can find help with taxes, payroll, and other financial management services. This is where accounts and auditors may find work if they are not employed directly by a company.</p><p>Insurance Companies</p><p>Insurance companies are places where people go to get help protecting their property and their family. Some positions they hire for include actuaries and underwriters.</p><p>Government Agencies</p><p>Government agencies are places where people go to get help from the government. Budget analysts and tax examiners are examples of professionals that may work for government agencies.</p><p>Corporations</p><p>Corporations are places where people work for a company. Depending on the size and need of the corporation, they may employ financial planners, risk managers, and treasurers.</p><p>Next Tab</p><p>As you can see, there are a variety of places that offer different financial services and employ people with many different backgrounds.&#160;Banks, investment companies, accounting firms, insurance companies, government agencies, and corporations all offer different services and hire skilled professionals to help people manage their money.&#160;Each of these places offers a unique set of financial services and provides valuable assistance to people who need help with their finances.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ecce85bef95cde06f23d86e13bb0edf7','career-exploration-m6-l4-lesson-3','3db84b7c905814af2e498fad6e931082','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Activities for Financial Career Cluster</h3><p>Activities for Financial Career Cluster</p><p>Activities in the Finance Career Cluster</p><p>All professions in the Finance career cluster focus on money.&#160;However, how a professional in this career cluster works with money varies depending on the professional’s job.&#160;Click below to learn about the various tasks in this cluster and which individuals focus on which tasks.</p><p>Developing financial plans</p><p>Creating plans and strategies to help individuals, businesses, and organizations achieve their financial goals.</p><p>Analysis</p><p>Analyzing financial data to make informed decisions about investments, expenditures, and budgeting.</p><p>Managing financial accounts</p><p>Overseeing the use of financial accounts such as investment accounts and bank accounts.</p><p>Developing financial forecast models</p><p>Studying markets and looking for trends in the markets in an effort to make wise financial decisions.</p><p>Identifying financial risk</p><p>Understanding investments and financial opportunities to determine the risk-to-reward ratio.</p><p>Negotiating and executing financial contracts</p><p>Ensuring that financial deals are properly executed.</p><p>Advising</p><p>Recommending products and services including insurance, account setup, taxes, and investments.</p><p>Preparing and filing financial documents</p><p>This includes tax documents, financial reports, profit and loss statements, and more.</p><p>Reading claims and reports</p><p>Reviewing insurance claims and determining the insurance coverage to be paid.</p><p>See if you can match the description to the task:</p><p>Task</p><p>Sita is reviewing documentation regarding an auto collision to determine whether the company owes the customer insurance money.</p><p>Developing financial forecast models</p><p>Akio is filing a tax return for a small business.</p><p>Identifying financial risks</p><p>Fatima is helping a couple find the best life insurance policies for them.</p><p>Managing financial accounts</p><p>Juan is overseeing the merger between two companies and making sure all proper documents have been signed by all parties.</p><p>Reading claims and reports</p><p>Victor is researching a new tech company to determine whether or not to recommend investing in this company to his clients.</p><p>Negotiating and executing financial contracts</p><p>Ina is creating a chart depicting her interpretation of future events based on the market research she has done.</p><p>Analysis</p><p>Jamie keeps a close eye on the investments of their clients.</p><p>Developing financial forecast models</p><p>Jiawei is reviewing the company’s financial data from the past year in order to develop budgets for the upcoming year.</p><p>Advising</p><p>Ina is creating a chart depicting her interpretation of future events based on the market research she has done.</p><p>Developing financial plans</p><p>Olga is mapping out a plan for a client to help him reach his financial retirement goals.</p><p>Preparing and filing financial documents</p><p>_</p><p>5</p><p>Alternative Activity</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0914105d34e3e957ca53ca0de98a13a3','career-exploration-m6-l5-lesson-4','3db84b7c905814af2e498fad6e931082','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Skills for Finance Career</h3><p>Skills for Finance Career</p><p>Skills, Abilities, and Talents Needed for a Career in Finance</p><p>Knowing what abilities, talents, and skills are required for success in the Finance career cluster is very important as you consider the cluster for your future career.&#160;Not only will it help you determine if this is an area that interests you, it will also give you a competitive advantage in the future.&#160;Click on the image below to learn about some of the important skills in this industry:</p><p>0</p><p>5</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Skills, abilities, and talents needed for the Finance career cluster.</p><p>The hotspot points on the image are as follows:</p><p>Leadership skills</p><p>The ability to lead teams and motivate others is important for success in the finance career cluster. This includes the ability to develop strategies, delegate tasks, and mentor junior staff.</p><p>Attention to detail</p><p>Successful finance professionals must be detail-oriented, as even the smallest mistake can have a major impact on client finances.</p><p>Analytical skills</p><p>The ability to analyze financial data and develop strategies to maximize profits and minimize losses is essential for success in the finance career cluster. This includes the ability to interpret financial statements, create and analyze budgets, and perform cost-benefit analyses.</p><p>Problem-solving skills</p><p>A successful finance professional must be able to identify and address problems quickly and effectively. This includes the ability to think on one&#39;s feet, identify patterns, and come up with creative solutions.</p><p>Interpersonal skills</p><p>Being able to develop strong relationships and collaborate with clients and colleagues is essential in the finance career cluster. This includes the ability to negotiate, build trust, and maintain a professional demeanor.</p><p>Communication skills</p><p>Being able to clearly and effectively communicate financial information is essential to the success of a finance professional. This includes the ability to explain complex financial concepts to non-financial audiences, as well as the ability to listen to and understand the needs of clients.</p><p>What skills are you currently developing?&#160;As you go through your classes and activities, reflect on some of the ways you are developing your abilities in these areas.&#160;You just might be surprised at how talented you already are in these areas!</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ef07b2c774cc0b3c667319b9d55735f0','career-exploration-m6-l6-lesson-5','3db84b7c905814af2e498fad6e931082','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Training &amp; Education Requirements</h3><p>Training &amp; Education Requirements</p><p>Training and Education Requirements</p><p>The finance career cluster includes many occupations that require different levels of training and education.&#160;Click on the tabs below to learn about some of the education requirements for common jobs in this cluster:</p><p>Accountants and auditors</p><p>Typically need at least a bachelor’s degree in accounting or a related field and prior work experience.&#160;They also need to be certified or licensed.</p><p>Banking services professionals</p><p>Depending on the requirements of the position, they may need a bachelor’s degree in finance, accounting, or a related field. Some jobs, such as bank tellers, may be able to enter the occupation with a high school diploma and on-the-job training.</p><p>Financial analysts</p><p>Typically need at least a bachelor’s degree in finance, accounting, economics, or a related field, as well as prior work experience.</p><p>Personal financial advisors</p><p>May need a bachelor’s degree in finance, economics, accounting, or a related field, as well as certification from a professional organization.</p><p>Financial managers</p><p>Typically need a bachelor’s degree in finance, accounting, economics, or a related field, as well as prior work experience.</p><p>Insurance underwriters</p><p>Typically need a bachelor’s degree in finance, economics, business, or a related field, as well as prior work experience.</p><p>Tax preparers</p><p>May need a bachelor’s degree in finance, accounting, economics, or a related field and may need to pass a certification exam.</p><p>Loan officers</p><p>Typically need a bachelor’s degree in finance, economics, business, or a related field and may need to pass a certification exam.</p><p>Budget analysts</p><p>May need a bachelor’s degree in finance, accounting, economics, or a related field, as well as prior work experience.</p><p>Credit analysts</p><p>May need a bachelor’s degree in finance, accounting, economics, or a related field, as well as prior work experience.</p><p>Next Tab</p><p>Your Education Starts Now</p><p>While many jobs require special training that can only be obtained post-high school, there are things you can do right now to steer your education in the right direction for a career in this cluster.&#160;Here are ten ideas you can implement now:</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Take courses related to finance, such as economics and accounting.</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;10</p><p>Next</p><p>Participate in math or finance clubs at school.</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;10</p><p>Next</p><p>Participate in summer internships or programs related to finance.</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;10</p><p>Next</p><p>Read books and articles related to finance and economics.</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;10</p><p>Next</p><p>Attend college and career fairs to learn more about finance-related careers.</p><p>Previous</p><p>Slide&#160;5&#160;of&#160;10</p><p>Next</p><p>Network with finance professionals.</p><p>Previous</p><p>Slide&#160;6&#160;of&#160;10</p><p>Next</p><p>Research finance-related job opportunities.</p><p>Previous</p><p>Slide&#160;7&#160;of&#160;10</p><p>Next</p><p>Take part in job shadowing or informational interviews.</p><p>Previous</p><p>Slide&#160;8&#160;of&#160;10</p><p>Next</p><p>Volunteer in a finance-related field.</p><p>Previous</p><p>Slide&#160;9&#160;of&#160;10</p><p>Next</p><p>Develop a basic understanding of financial markets and investments.</p><p>Previous</p><p>Slide&#160;10&#160;of&#160;10</p><p>Next</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ca757d94dbd6428f6e4d149357c4fdce','career-exploration-m6-l7-module-6-summary','3db84b7c905814af2e498fad6e931082','Module 6 Summary','text',12,'<h2>Module 6 Summary</h2><section><h3>Module 6 Summary</h3><p>Module 6 Summary</p><p>Great Work!&#160;You have successfully completed this module on Finance.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified the pathways in the Finance career cluster and the careers in each pathway.</p><p>Described the types of places that employ individuals who have careers in the Finance career cluster.</p><p>Described the variety of tasks performed by individuals who have careers in the Finance career cluster.</p><p>Listed the skills, abilities, and talents needed for careers in the Finance career cluster.</p><p>Identified the level of training and education required for careers in the Finance career cluster.</p><p>Researched a career in the Finance career cluster and present findings to the class.</p><p>Applied math, science, and reading skills in the completion of a project or activity related to the Finance career cluster.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('324d1282d9e4d9ae1dd982a5aa3977da','career-exploration-m6-l8-module-6-project','3db84b7c905814af2e498fad6e931082','Module 6 Project','text',12,'<h2>Module 6 Project</h2><section><h3>Module 6 Project</h3><p>Module 6 Project</p><p>Career Exploration</p><p>Finance - Project</p><p>For this project, you will choose from two options.&#160; You only need to complete one of these options.&#160; Please find both options and their rubrics below.</p><p>Option 1</p><p>For this option, you will follow the stock market. To complete the project, follow the steps below:</p><p>Step 1: Pick five publicly traded stocks (ex: Walt Disney Co, Verizon Communications, Amazon.com Inc, Apple Computers Inc, etc.) and write down the cost to buy stock in each company that day.</p><p>Step 2: Track and write down their stocks for five business days:</p><p>The open price</p><p>The close price</p><p>Step 3: After you have tracked their progress, do some analysis to answer the following questions in a write-up:</p><p>Which company(s) were worth more on the first day than on the last day?</p><p>Which company(s) are worth more on the last day than the first day?</p><p>Was the change for each company linear or did it go up some days and down others?</p><p>Based on what you learned this week, which stocks would you sell and which companies would you hang on to and why?</p><p>Your final project should include a log for the 5 companies with the daily price information and a write-up answering all of the questions in step 3. Review the rubric to see how you will be graded.</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 1 Rubric: Finance Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Daily Log</p><p>9-10 points Includes accurate information on the open and close prices for all 5 companies selected for every day of the trading week.</p><p>6-8 Includes mostly accurate information on the open and close prices for most days of the trading week.</p><p>0-5 points Information is significantly inaccurate and/or missing.</p><p>10</p><p>Write-Up</p><p>9-10 points The write-up addresses all of the points in the prompt and is well-written.</p><p>6-8 points The write-up addresses most of the points in the prompt and is adequately written.</p><p>0-5 points The write-up does not address most of the points in the prompt and/or is written poorly.</p><p>10</p><p>Total Points:&#160;20</p><p>Option 2</p><p>For this option, you will research a particular career that interests you in this cluster. Complete the following steps for your project:</p><p>Step 1: Research your chosen career.</p><p>Step 2: List the following</p><p>Average Salary/Salary Range</p><p>Education Requirements</p><p>Certification Requirements (if any)</p><p>Why you chose that career</p><p>Step 3: Prepare a PowerPoint presentation about your chosen career, including the information you gathered in Step 2 as well as your reason for choosing that career.</p><p>Your final submission should be your PowerPoint containing the information in Step 3.</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 2 Rubric: Finance Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Research</p><p>12 points The student provided a career field that interested them, the average salary or range, and the education/certifications required for the career.</p><p>11-4 points The student provided two of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>3-0 points The student provided one or none of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>12</p><p>Reason for Choosing the Career Field</p><p>4 points The student thoughtfully provided the reason that they are interested in this career.</p><p>N/A</p><p>0 points The student did not provide the reason that they are interested in this career.</p><p>4</p><p>Formatting</p><p>4 points The student&#39;s presentation includes no spelling or grammatical errors.</p><p>3-1 points The student&#39;s presentation includes minimal spelling or grammatical errors.</p><p>0 points The student&#39;s presentation includes a significant amount of spelling or grammatical errors.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('fc20d88c30d31ca88882484715db6d22','career-exploration-m6-l9-module-6-quiz','3db84b7c905814af2e498fad6e931082','Module 6 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Finance. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('c81c6d15d27f9bccbd48b3340858bfcf','career-exploration-module-7','68d48b60cc4feb626956ed1fd8311e46','Module 7: Govrment & Public Admin',7) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f24f47e92ba2f68d0674196f946e5193','career-exploration-m7-l1-introduction-purpose-and-objectives','c81c6d15d27f9bccbd48b3340858bfcf','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hello and welcome to this module on Government and Public Administration.</p><p>Are you looking for a career that will allow you to make a real difference in your community and the world? Then the Government and Public Administration career cluster may be the perfect fit for you! You can help shape policies that will improve the lives of people in your community and beyond. You&#39;ll get to work with the latest technologies and trends, and you&#39;ll have the opportunity to collaborate with a variety of people in different fields. With the Government and Public Administration career cluster, you&#39;ll have the chance to make a real impact on the world around you.</p><p>Whether you work in your hometown helping to make your community a little safer or you work for the United Nations helping to make countries a little safer, this career cluster represents opportunities to make an impact that could last for generations.</p><p>The world needs great leaders to inspire us and make changes in the environment, foreign policies and relationships, transportation, local programs and initiatives, and security. If you’re passionate about issues impacting the world around you, a career in government and public administration is the perfect way to put that passion into action.</p><p>In this course, we’ll discuss the different pathways leading to careers in this cluster. For example, you’ll learn about the pathway for elected positions like mayor or governor, and how that pathway is different from that of a city manager or housing specialist.</p><p>You’ll also learn about where you might work in this career cluster. There are so many places that need people with a background and expertise in the government and public administration career cluster. You might be shocked at how many places there are where you could work!</p><p>We’ll also discuss the different tasks people in these careers perform. It takes certain skills, abilities, and talents as well as education and training to succeed in this career cluster. We’ll make sure to explore those so you can set yourself up for success early on. Let’s dive in!</p><p>Module Description</p><p>Welcome to this module on the Government &amp; Public Administration career cluster!&#160;In this module, you will discover the seven pathways in this cluster.&#160;You’ll also learn about which jobs belong to these pathways.&#160;Next, we will discuss the types of places that employ individuals in this field and the variety of tasks they perform.&#160;Since there are so many careers in this pathway, you’ll get a wide variety of activities to learn about.&#160;You will also learn about the skills, abilities, and talents needed for careers in this field, as well as the level of training and education required for the different types of careers.&#160;After successfully completing the lessons in this module, you will have sufficient background knowledge to complete the end-of-module project which will give you further insight into the activities related to this career cluster.</p><p>Objectives</p><p>In this module, students will:</p><p>Identify the pathways in the Government &amp; Public Administration career cluster and the careers in each pathway.</p><p>Describe the types of places that employ individuals who have careers in the Government &amp; Public Administration career cluster.</p><p>Describe the variety of tasks performed by individuals who have careers in the Government &amp; Public Administration career cluster.</p><p>List the skills, abilities, and talents needed for careers in the Government &amp; Public Administration career cluster.</p><p>Identify the level of training and education required for careers in the Government &amp; Public Administration career cluster.</p><p>Research a career in the Government &amp; Public Administration career cluster and present findings to the class.</p><p>Apply math, science, and reading skills in the completion of a project or activity related to the Government &amp; Public Administration career cluster.</p><p>Polling Question</p><p>Which job in the Government &amp; Public Administration career cluster sounds most interesting to you?</p><p>Safety inspector&#160;City planner&#160;Secret service agent&#160;Lobbyist&#160;Ambassador</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Rules or laws that govern how people or businesses should behave.</p><p>Census</p><p>A survey of the population of a country or region that is taken every ten years.</p><p>Regulations</p><p>Money collected by the government to pay for services it provides, such as roads and schools.</p><p>Legislation</p><p>Rules or laws made by the government.</p><p>Internal Revenue Service (IRS)</p><p>A government agency that collects taxes.</p><p>Municipality</p><p>A city or town that is governed by its own local government.</p><p>Taxation</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Rules or laws that govern how people or businesses should behave.</p><p>Answers for question: 1</p><p>Census</p><p>Legislation</p><p>Municipality</p><p>Regulations</p><p>Taxation</p><p>Internal Revenue Service (IRS)</p><p>2.</p><p>A survey of the population of a country or region that is taken every ten years.</p><p>Answers for question: 2</p><p>Taxation</p><p>Legislation</p><p>Regulations</p><p>Internal Revenue Service (IRS)</p><p>Municipality</p><p>Census</p><p>3.</p><p>Money collected by the government to pay for services it provides, such as roads and schools.</p><p>Answers for question: 3</p><p>Internal Revenue Service (IRS)</p><p>Legislation</p><p>Census</p><p>Regulations</p><p>Municipality</p><p>Taxation</p><p>4.</p><p>Rules or laws made by the government.</p><p>Answers for question: 4</p><p>Regulations</p><p>Taxation</p><p>Internal Revenue Service (IRS)</p><p>Municipality</p><p>Legislation</p><p>Census</p><p>5.</p><p>A government agency that collects taxes.</p><p>Answers for question: 5</p><p>Taxation</p><p>Regulations</p><p>Municipality</p><p>Legislation</p><p>Census</p><p>Internal Revenue Service (IRS)</p><p>6.</p><p>A city or town that is governed by its own local government.</p><p>Answers for question: 6</p><p>Internal Revenue Service (IRS)</p><p>Legisl<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('354acba9268b6d55c64980fe2a1444ae','career-exploration-m7-l2-lesson-1','c81c6d15d27f9bccbd48b3340858bfcf','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>What is the Gov &amp; Public Admin Career Cluster</h3><p>What is the Gov &amp; Public Admin Career Cluster</p><p>What is the Government &amp; Public Administration Career Cluster?</p><p>The Finance Career cluster is a group of jobs that involve working with money.&#160;These jobs could involve helping people and businesses with their investments and savings, managing money, or helping people make smart decisions with their money.&#160;People who work in finance help people and businesses make the most of their money so they can reach their goals and have enough money for the future.</p><p>There are seven primary pathways in this career cluster.&#160;Click the tabs to learn more about each one:</p><p>Governance Pathway</p><p>This pathway involves the development and implementation of laws and policies that help to ensure the safety and well-being of citizens.&#160;Examples of jobs within this pathway include legislators, judges, mayors, and lobbyists.</p><p>National Security Pathway</p><p>This pathway focuses on protecting the country and its citizens from threats and harm. Examples of jobs within this pathway include police officers, Secret Service agents, military personnel, and border patrol agents.</p><p>Foreign Service Pathway</p><p>This pathway involves representing the United States in other countries and helping to build relationships with other nations. Examples of jobs within this pathway include diplomats, ambassadors, and foreign service officers.</p><p>Planning Pathway</p><p>This pathway involves creating plans to help improve the quality of life and increase economic prosperity. Examples of jobs within this pathway include city planners, census clerks, and economic development coordinators.</p><p>Revenue &amp; Taxation Pathway</p><p>This pathway involves collecting taxes and other payments from citizens and businesses to help fund government programs. Examples of jobs within this pathway include tax auditors, IRS agents, and revenue officers.</p><p>Regulation Pathway</p><p>This pathway involves enforcing laws and regulations to protect the public from harmful practices. Examples of jobs within this pathway include consumer protection officers, environmental inspectors, and occupational safety and health inspectors.</p><p>Public Management &amp; Admin Pathway</p><p>This pathway involves managing government programs and services, as well as overseeing the operations of government organizations. Examples of jobs within this pathway include budget directors, city managers, and public information officers.</p><p>Next Tab</p><p>Pathway</p><p>Akila is a public information officer.</p><p>Foreign Service</p><p>Jharna is an occupational safety inspector.</p><p>Planning Pathway</p><p>Mateo is an IRS agent.</p><p>Governance</p><p>Zhi is a census clerk.</p><p>Regulation</p><p>Mariam is an ambassador.</p><p>National Security</p><p>Yousuf is a police officer.</p><p>Revenue &amp; Taxation</p><p>Sari is a mayor.</p><p>Public Management &amp; Administration</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Akila is a public information officer.</p><p>Answers for question: 1</p><p>Foreign Service</p><p>Regulation</p><p>National Security</p><p>Public Management &amp; Administration</p><p>Governance</p><p>Planning Pathway</p><p>Revenue &amp; Taxation</p><p>2.</p><p>Jharna is an occupational safety inspector.</p><p>Answers for question: 2</p><p>National Security</p><p>Planning Pathway</p><p>Public Management &amp; Administration</p><p>Regulation</p><p>Revenue &amp; Taxation</p><p>Foreign Service</p><p>Governance</p><p>3.</p><p>Mateo is an IRS agent.</p><p>Answers for question: 3</p><p>Planning Pathway</p><p>Foreign Service</p><p>Revenue &amp; Taxation</p><p>Regulation</p><p>Governance</p><p>National Security</p><p>Public Management &amp; Administration</p><p>4.</p><p>Zhi is a census clerk.</p><p>Answers for question: 4</p><p>Public Management &amp; Administration</p><p>Foreign Service</p><p>Planning Pathway</p><p>Revenue &amp; Taxation</p><p>National Security</p><p>Regulation</p><p>Governance</p><p>5.</p><p>Mariam is an ambassador.</p><p>Answers for question: 5</p><p>Foreign Service</p><p>Planning Pathway</p><p>Revenue &amp; Taxation</p><p>Governance</p><p>Public Management &amp; Administration</p><p>National Security</p><p>Regulation</p><p>6.</p><p>Yousuf is a police officer.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9c78b4fb8671f2f29d0ad7c18bd29684','career-exploration-m7-l3-lesson-2','c81c6d15d27f9bccbd48b3340858bfcf','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Where Gov &amp; Public Admin ppl work</h3><p>Where Gov &amp; Public Admin ppl work</p><p>Where People in the Government and Public Administration Career Cluster Work</p><p>It takes a lot of agencies and organizations to keep our cities, states, and nation operating and progressing.&#160;From agencies concerned about protecting citizens to agencies concerned about protecting the environment, people in this career cluster have abundant opportunities to find employment.</p><p>Click below to learn about some of the places that employ people in the Government and Public Administration Career Cluster.</p><p>City Hall</p><p>City Hall is where local government officials work on matters that affect the town or city. They create laws, make sure people are abiding by them, and provide services to the community.</p><p>State House</p><p>The State House is where state government officials come together to work on laws and regulations that affect all of the people in the state.</p><p>Capitol Building</p><p>The Capitol Building is where federal government officials work on laws and regulations that affect the entire nation.</p><p>Department of Education</p><p>The Department of Education works to ensure that all children have access to quality education.</p><p>Department of Health and Human Services</p><p>The Department of Health and Human Services works to provide health care, nutrition assistance, and other services to those in need.</p><p>Department of Homeland Security</p><p>The Department of Homeland Security works to protect the United States from terrorist attacks and other threats.</p><p>Department of Defense</p><p>The Department of Defense is responsible for defending the United States from foreign threats.</p><p>Department of Justice</p><p>The Department of Justice is responsible for enforcing the laws of the United States and seeking justice for those who have been wronged.</p><p>Federal Bureau of Investigation (FBI)</p><p>The Federal Bureau of Investigation works to investigate crimes and protect the American people from crime.</p><p>Social Security Administration</p><p>The Social Security Administration works to provide economic security to retired and disabled Americans.</p><p>Postal Service</p><p>The Postal Service delivers mail to people all over the United States.</p><p>National Park Service</p><p>The National Park Service works to protect and maintain our national parks and monuments.</p><p>Environmental Protection Agency:</p><p>The Environmental Protection Agency works to protect the environment from pollution and other threats.</p><p>Internal Revenue Service</p><p>The Internal Revenue Service collects taxes from people and businesses to help pay for government services.</p><p>Police and Fire Departments</p><p>Work to ensure communities are safe and respond to calls for help due to crimes committed, fires, or medical emergencies.</p><p>As you can see, a career in Government and Public Administration presents a great opportunity to combine interests and causes to create a rewarding career.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1ff6c9b063de220db049b270f730a1a3','career-exploration-m7-l4-lesson-3','c81c6d15d27f9bccbd48b3340858bfcf','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Activities for Gov &amp; Public Admin Career</h3><p>Activities for Gov &amp; Public Admin Career</p><p>Activities in the Government &amp; Public Administration Career Cluster</p><p>A day-in-the-life of someone working in Government &amp; Public Administration is going to depend on the exact job the individual has.&#160;Some of the tasks are listed in the slideshow below:</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Working in the government to help make laws and policies</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;11</p><p>Next</p><p>As you can see, there are so many activities people in this career cluster participate in.&#160;However, they all centeraround helping to make the world a better place.&#160;Whether it’s through connecting people to services they need or introducing a new public policy, these people help make society function a little better.</p><p>Helping to keep the public safe by working in the police or fire department</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;11</p><p>Next</p><p>Keeping records of government activities and making sure they are accurate</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;11</p><p>Next</p><p>Helping people in the community access government services</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;11</p><p>Next</p><p>Managing public funds and resources</p><p>Previous</p><p>Slide&#160;5&#160;of&#160;11</p><p>Next</p><p>Working in the military to protect citizens</p><p>Previous</p><p>Slide&#160;6&#160;of&#160;11</p><p>Next</p><p>Helping to protect the environment</p><p>Previous</p><p>Slide&#160;7&#160;of&#160;11</p><p>Next</p><p>Ensuring access to healthcare services</p><p>Previous</p><p>Slide&#160;8&#160;of&#160;11</p><p>Next</p><p>Working in disaster relief teams</p><p>Previous</p><p>Slide&#160;9&#160;of&#160;11</p><p>Next</p><p>Helping to shape public policy</p><p>Previous</p><p>Slide&#160;10&#160;of&#160;11</p><p>Next</p><p>Investigating and prosecuting crimes</p><p>Previous</p><p>Slide&#160;11&#160;of&#160;11</p><p>Next</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('43e81c7964494412aa12fcbb0f53c014','career-exploration-m7-l5-lesson-4','c81c6d15d27f9bccbd48b3340858bfcf','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Skills for Gov &amp; Public Admin Careers</h3><p>Skills for Gov &amp; Public Admin Careers</p><p>Skills, Abilities, and Talents Needed for a Career in Government &amp; Public Administration</p><p>There are many skills, abilities, and talents needed for a successful career in Government &amp; Public Administration cluster.&#160;Some of those are listed below:</p><p>Communication Skills</p><p>This involves being able to speak, write, and listen effectively in order to share information, ideas, and opinions. It is important for government and public administration jobs to be able to communicate in different ways in order to get things done.</p><p>Analytical Thinking</p><p>Government and public administration jobs often involve looking at data and making decisions based on that data. Analytical thinking involves the ability to analyze information and come up with logical conclusions.</p><p>Problem-Solving Skills</p><p>Government and public administration jobs often involve finding solutions to difficult problems. Problem-solving skills involve being able to identify problems, come up with possible solutions, and then come up with the best solution.</p><p>Leadership</p><p>Leaders in government and public administration have the ability to motivate and inspire their teams. Leadership involves being able to delegate tasks, make decisions, and take responsibility.</p><p>Organization</p><p>Government and public administration jobs require the ability to keep track of multiple tasks and deadlines. Organization involves the ability to plan, prioritize, and stay organized in order to get tasks done efficiently.</p><p>Teamwork</p><p>Government and public administration jobs often involve working with others in order to get things done. Teamwork involves the ability to cooperate, collaborate, and communicate with others in order to achieve a common goal.</p><p>Decision Making</p><p>The ability to make sound decisions based on available information and research is very important when you are helping to make changes that impact communities, states, and countries.</p><p>Critical Thinking</p><p>Critical thinking is the ability to think critically and consider all options when making decisions. People in this career cluster need solid critical thinking abilities before making changes and decisions that impact lives.</p><p>Adaptability</p><p>The ability to respond quickly to changing circumstances and develop new strategies is important for success in this career cluster.</p><p>Time Management</p><p>Being able to manage time and prioritize tasks is essential for working in the government and public administration fields.</p><p>See if you can match the situation to the skill, ability, or talent needed.</p><p>Situation</p><p>Skill</p><p>Lobbyist must present information about a cause in a way that is clear, informative, and inspires action.&#160;He must be able to do this both in speech and in writing.</p><p>Time-Management</p><p>Andrea is a public administrator, and she needs to analyze the effectiveness of a new tax policy by evaluate the financial impact of the policy and also how it will affect people in the community.</p><p>Communication</p><p>A local government needs to decide how to allocate resources to best meet the needs of the community.&#160;They must figure out the available resources, determine the needs of the community, and develop a plan for giving the resources in a way that best serves the community.</p><p>Leadership</p><p>A newly elected mayor needs to set a vision, develop strategies to achieve the goals the city has in place, and motivate others to work together to improve the community.</p><p>Critical Thinking</p><p>A city manager oversees the daily operations of a city, which includes setting up budgets, organizing public services, and making sure everyone knows their role.&#160;The city manager must ensure that all tasks are completed in a timely and efficient manner.</p><p>Problem-solving skills</p><p>A detective needs to lead the investigation of a crime, a patrol officer to follow up on leads and take witness statements, and a crime scene analyst to collect and analyze evidence.&#160;Everyone must handle their responsibility efficiently and accurately.</p><p>Organization</p><p>The city council must make a decision on how much funding to allocate to the project and which aspects of the project to prioritize.</p><p>Adaptability</p><p>A policy analyst in the government must create a policy that will address literacy.&#160;To develop the policy, the analyst must consider the issue from all angles, weigh the pros and cons of different options, and develop a policy that is beneficial for the most people and meets the goals of the government.</p><p>Analytical Thinking</p><p>An IRS agent is working with a taxpayer who has multiple sources of income from different countries.&#160;The IRS employee must adjust their approach to understanding the different sources of income and tax laws from each country to accurately assess the taxpayer&#39;s taxes.</p><p>Decision-making</p><p>A governor has the following on her to-do list:&#160;Attend two public meetings, addressing the public&#39;s concerns about a new state policy, hold a press conference, and check on the progress of a state project.</p><p>Public speaking</p><p>A senator is giving a speech in support of an upcoming bill in front of a large audience.&#160;The senator must clearly explain the importance of the bill, as well as inspire support for it.&#160;They must also effectively address any questions or concerns from the audience.</p><p>Teamwork</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Lobbyist must present information about a cause in a way that is clear, informative, and inspires action. He must be able to do this both in speech and in writing.</p><p>Answers for question: 1</p><p>Organization</p><p>Analytical Thinking</p><p>Decision-making</p><p>Problem-solving skills</p><p>Communication</p><p>Teamwork</p><p>Time-Management</p><p>Public speaking</p><p>Leadership</p><p>Critical Thinking</p><p>Adaptability</p><p>2.</p><p>Andrea is a public administrator, and she needs to analyze the effectiveness of a new tax policy by evaluate the financial impact of the policy and also how it will affect people in the community.</p><p>Answers for question: 2</p><p>Adaptability</p><p>Critical Thinking</p><p>Leadership</p><p>Decision-making</p><p>Problem-solving skills</p><p>A<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('235f9c3a97076cf077022900c8ae664b','career-exploration-m7-l6-lesson-5','c81c6d15d27f9bccbd48b3340858bfcf','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Training &amp; Education Requirements</h3><p>Training &amp; Education Requirements</p><p>Training and Education Requirements</p><p>The Government &amp; Public Administration career cluster involves many jobs that help people in the community and make sure laws and rules are followed.&#160;Most of the jobs in this cluster require at least a high school diploma, and many require a college degree or specialized training.&#160;Click through the tabs below to learn about some of the careers in this cluster and the training and education required:</p><p>Governor</p><p>A governor typically must have a bachelor&#39;s degree and at least 10 years of executive experience in fields such as business, politics, or the military.&#160;The candidate must also pass a background check.</p><p>Lobbyist</p><p>Lobbyists typically need a college degree and a good understanding of the legislative process and government regulations. They must be able to communicate and negotiate effectively.</p><p>Senator</p><p>Senators must be at least 30 years old, be a U.S. citizen for at least nine years, and live in the state they are elected to represent. A college degree is not required, but most senators have advanced degrees.</p><p>Intelligence Analyst</p><p>Intelligence analysts typically need a bachelor&#39;s degree in a related field, such as computer science, engineering, mathematics, or criminal justice. They must also have experience in government or law enforcement.</p><p>County Clerk</p><p>Most county clerks have a high school diploma or an associate&#39;s degree. They must have knowledge of county laws and regulations, and they must have experience in office management.</p><p>Ambassador</p><p>Ambassadors typically need a college degree and must be able to communicate effectively in a variety of languages. They may also need extensive knowledge of foreign policy and international relations.</p><p>Census Clerk</p><p>To become a census clerk, a person must have a high school diploma or equivalent. They must also have knowledge of computer programs, such as Microsoft Office, and be able to work independently.</p><p>Tax Attorney</p><p>Tax attorneys need a law degree and must pass the bar exam in the state they practice in. They must also have knowledge of federal, state, and local tax laws.</p><p>Border Inspector</p><p>Border inspectors typically need a high school diploma or equivalent. They must pass a background check and a series of tests. They must also have knowledge of immigration and customs laws.</p><p>Immigration Officer</p><p>Immigration officers need a college degree in a related field, such as criminal justice or international relations. They must have knowledge of immigration laws and have experience in the field.</p><p>City Council Member</p><p>City council members typically need a high school diploma or equivalent. They must have knowledge of local government and have experience in public service or politics.</p><p>Program Administration Officer</p><p>Program administration officers typically need a bachelor&#39;s degree in a related field, such as public administration or business. They must also have experience in program management, budgeting, and policy analysis.</p><p>Next Tab</p><p>There are things you can do to prepare for a career in this cluster now.&#160;Click on the image below to learn more about some of these things:</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Activities that students can do now to prepare for a career in the Government &amp; Public Administration career cluster.</p><p>The hotspot points on the image are as follows:</p><p>Participate</p><p>Participate in government-related extracurricular activities, such as student government, Model United Nations, or youth civic engagement programs.</p><p>Research</p><p>Research government and public administration career pathways to gain an understanding of the types of jobs available.</p><p>Take classes</p><p>Take classes or participate in activities that will help develop important skills for a career in government and public administration, such as communication, critical thinking, problem-solving, and computer literacy.</p><p>Volunteer</p><p>Participate in internships or volunteer opportunities with local government offices or nonprofit organizations.</p><p>Attend</p><p>Attend government-related conferences or events to network and learn more about the field.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0a39f784c4a3f9325a14bcecf14e1019','career-exploration-m7-l7-module-7-summary','c81c6d15d27f9bccbd48b3340858bfcf','Module 7 Summary','text',12,'<h2>Module 7 Summary</h2><section><h3>Module 7 Summary</h3><p>Module 7 Summary</p><p>Great Work!&#160;You have successfully completed this module on&#160;the Government &amp; Public Administration career cluster.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified the pathways in the Government &amp; Public Administration career cluster and the careers in each pathway.</p><p>Described the types of places that employ individuals who have careers in the Government &amp; Public Administration career cluster.</p><p>Described the variety of tasks performed by individuals who have careers in the Government &amp; Public Administration career cluster.</p><p>Listed the skills, abilities, and talents needed for careers in the Government &amp; Public Administration career cluster.</p><p>Identified the level of training and education required for careers in the Government &amp; Public Administration career cluster.</p><p>Researched a career in the Government &amp; Public Administration career cluster and present findings to the class.</p><p>Applied math, science, and reading skills in the completion of a project or activity related to the Government &amp; Public Administration career cluster.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('04ae5d3abebc99893d3545913f36a626','career-exploration-m7-l8-module-7-project','c81c6d15d27f9bccbd48b3340858bfcf','Module 7 Project','text',12,'<h2>Module 7 Project</h2><section><h3>Module 7 Project</h3><p>Module 7 Project</p><p>Career Exploration</p><p>Government &amp; Public Administration - Project</p><p>For this project, you will choose from two options.&#160; You only need to complete one of these options.&#160; Please find both options and their rubrics below.</p><p>Option 1</p><p>For this project, think about a problem or issue in your community. Then create a PowerPoint presentation that does the following:</p><p>1. Explains the situation, why it&#39;s a problem, and who/what is negatively impacted.</p><p>2. Outlines a potential solution. The solution should include actionable items and who would be responsible for implementing these actions.</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 1 Rubric: Government &amp; Public Administration Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Problem Overview</p><p>9-10 points Provides an excellent overview of the problem and who is being impacted.</p><p>6-8 Provides a good overview of the problem and who is being impacted.</p><p>0-5 points Provides an poor overview of the problem and who is being impacted.</p><p>10</p><p>Solution</p><p>9-10 points Provides a well-thought-out solution that includes actionable items and who would be responsible for implementing those actions.</p><p>6-8 points Provides an adequate solution that includes actionable items and who would be responsible for implementing those actions.</p><p>0-5 points Does not provide an adequate solution and/or does not include actionable items and who would be responsible for implementing those actions.</p><p>10</p><p>Total Points:&#160;20</p><p>Option 2</p><p>For this option, you will research a particular career that interests you in this cluster. Complete the following steps for your project:</p><p>Step 1: Research your chosen career.</p><p>Step 2: List the following</p><p>Average Salary/Salary Range</p><p>Education Requirements</p><p>Certification Requirements (if any)</p><p>Why you chose that career</p><p>Step 3: Prepare a PowerPoint presentation about your chosen career, including the information you gathered in Step 2 as well as your reason for choosing that career.</p><p>Your final submission should be your PowerPoint containing the information in Step 3.</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 2 Rubric: Government &amp; Public Administration Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Research</p><p>12 points The student provided a career field that interested them, the average salary or range, and the education/certifications required for the career.</p><p>11-4 points The student provided two of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>3-0 points The student provided one or none of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>12</p><p>Reason for Choosing the Career Field</p><p>4 points The student thoughtfully provided the reason that they are interested in this career.</p><p>N/A</p><p>0 points The student did not provide the reason that they are interested in this career.</p><p>4</p><p>Formatting</p><p>4 points The student&#39;s presentation includes no spelling or grammatical errors.</p><p>3-1 points The student&#39;s presentation includes minimal spelling or grammatical errors.</p><p>0 points The student&#39;s presentation includes a significant amount of spelling or grammatical errors.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('613a5f9cc3d4362a155dbb7b6fb72471','career-exploration-m7-l9-module-7-quiz','c81c6d15d27f9bccbd48b3340858bfcf','Module 7 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Govrment & Public Admin. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('83d9dac8ec3bb84b2f00248cb0f2a022','career-exploration-module-8','68d48b60cc4feb626956ed1fd8311e46','Module 8: Health Science',8) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0317a921f83eb0afd6bbcfdfb5fb2c98','career-exploration-m8-l1-introduction-purpose-and-objectives','83d9dac8ec3bb84b2f00248cb0f2a022','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Welcome to this module on the Health Science career cluster.</p><p>Health Science isn’t just your average career cluster! It’s unique because you can literally save lives! And beyond that, you can also help shape the future of healthcare.</p><p>The cluster includes a wide range of occupations, from medical professionals like doctors and nurses to those who specialize in public health, health information technology, and medical research. Health Science professionals have a deep understanding of the human body and how it works, as well as the knowledge and skills needed to help people stay healthy. Health Science is a great career cluster to consider.</p><p>You can learn how to use technology to administer new treatments, create programs to improve public health, and even work in medical research to help find cures for diseases. Health Science is a field that is constantly evolving, so you will never be bored. Plus, it can be incredibly rewarding to know that your work is making a real difference in the lives of others.</p><p>In this module, we will explore various career pathways in this cluster. Each pathway contributes to the patient’s experience and growth in the medical sciences. Exploring these pathways may help you discover an area of health science that interests you most. We will also explore where people in this industry work. Yes, hospitals are one place, but there are so many places of employment that you will get to learn about.</p><p>You will also gain a foundational understanding of what some of these professionals do. From patient care, to research, to records management, it takes a lot of people performing a variety of tasks to further healthcare, and keep us all healthy!</p><p>Education and training play a crucial role in this career cluster, whether it’s a quick month or two of training to become a certified nursing assistant or a decade or more to become a surgeon! We’ll explore the different requirements and you can evaluate what might suit you best.</p><p>This is an exciting cluster, so let’s get started!</p><p>Module Description</p><p>Welcome to this module on the Health Science career cluster!&#160;In this module, you will discover the various pathways in this cluster and some of the jobs associated with each pathway.&#160;Next, we will discuss the types of places that employ individuals in this field and the variety of tasks they perform, each task contributing to health and well-being in its own way.&#160;You will also learn about the skills, abilities, and talents needed for careers in this field and how you can start developing these skills now.&#160;We will also discuss one of the most crucial aspects of this career cluster- training and education.&#160;The module will conclude with a project designed to help you explore the importance of health science.</p><p>Objectives</p><p>In this course, students will</p><p>Identify the pathways in the Health Science career cluster and the careers in each pathway.</p><p>Describe the types of places that employ individuals who have careers in the Health Science career cluster.</p><p>Describe the variety of tasks performed by individuals who have careers in the Health Science career cluster.</p><p>List the skills, abilities, and talents needed for careers in the Health Science career cluster.</p><p>Identify the level of training and education required for careers in the Health Science career cluster.</p><p>Research a career in the Health Science career cluster and present findings to the class.</p><p>Apply math, science, and reading skills in the completion of a project or activity related to the Health Science career cluster.</p><p>Polling Question</p><p>Which career in the Health Science career cluster sounds most interesting to you?</p><p>Biotechnology researcher&#160;Doctor&#160;Psychologist&#160;Medical transcriptionist&#160;Dietician&#160;Other</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>A type of care that helps people feel better physically, mentally, or emotionally.</p><p>Therapeutic</p><p>The process of figuring out what is wrong with someone&#39;s health.</p><p>Healthcare</p><p>A type of science that uses living organisms or parts of them to create products or processes for use in medicine, industry, or agriculture.</p><p>Pharmaceuticals</p><p>Any kind of care or medical action taken to improve someone&#39;s health.</p><p>Preventative healthcare</p><p>Care and services related to a person&#39;s physical and mental health.</p><p>Prescribe</p><p>Medicines or drugs made by a pharmacist to help treat a health problem.</p><p>Biotechnology</p><p>Actions taken to stop health problems from happening in the first place.</p><p>Diagnosis</p><p>When a doctor tells you what medicine you should take to treat a health problem.</p><p>Treatment</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>A type of care that helps people feel better physically, mentally, or emotionally.</p><p>Answers for question: 1</p><p>Therapeutic</p><p>Healthcare</p><p>Preventative healthcare</p><p>Prescribe</p><p>Pharmaceuticals</p><p>Diagnosis</p><p>Biotechnology</p><p>Treatment</p><p>2.</p><p>The process of figuring out what is wrong with someone&#39;s health.</p><p>Answers for question: 2</p><p>Biotechnology</p><p>Treatment</p><p>Prescribe</p><p>Healthcare</p><p>Diagnosis</p><p>Pharmaceuticals</p><p>Therapeutic</p><p>Preventative healthcare</p><p>3.</p><p>A type of science that uses living organisms or parts of them to create products or processes for use in medicine, industry, or agriculture.</p><p>Answers for question: 3</p><p>Preventative healthcare</p><p>Healthcare</p><p>Pharmaceuticals</p><p>Therapeutic</p><p>Biotechnology</p><p>Prescribe</p><p>Treatment</p><p>Diagnosis</p><p>4.</p><p>Any kind of care or medical action taken to improve someone&#39;s health.</p><p>Answers for question: 4</p><p>Treatment</p><p>Diagnosis</p><p>Pharmaceuticals</p><p>Biotechnology</p><p>Prescribe</p><p>Preventative healthcare</p><p>Therapeutic</p><p>Healthcare</p><p>5.</p><p>Care and services related to a person&#39;s physical and mental health.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('502bf6a198f097ad5146bb9f95d77eb3','career-exploration-m8-l2-lesson-1','83d9dac8ec3bb84b2f00248cb0f2a022','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>What is Health Science Career Cluster</h3><p>What is Health Science Career Cluster</p><p>What is the Health Science Career Cluster?</p><p>The Health Science career cluster is an exciting field dedicated to helping people stay healthy.&#160;People in this career cluster work in many different areas.&#160;Some help people understand how to keep their bodies healthy, like doctors, dietitians, and physical therapists.&#160;Others provide care for people who are sick or injured, like nurses, EMTs, and medical technologists.&#160;Still others work behind the scenes, like laboratory scientists, hospital administrators, and medical records specialists.&#160;No matter what the role, their contributions can save our health and our lives.</p><p>Click through the slide show to learn more about the pathways in this cluster:</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Therapeutic Services Pathway:&#160;The Therapeutic Services pathway is all about helping people to stay healthy.&#160;People in this pathway work directly with patients to give them care, treatment, advice, and teach them about how to look after themselves.&#160;They work to make sure the patient&#39;s health gets better over time.&#160;Examples of jobs in this pathway include registered nurses, athletic trainers, dentists, and psychologists.</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;5</p><p>Next</p><p>Diagnostic Services Pathway: People who work in the Diagnostic Services pathway use tests and evaluations to help find out if someone has a disease, injury, or other physical problem. They use these tests to help doctors figure out what is wrong and how to treat it. Professionals working in this pathway include clinical lab technicians, radiologists, phlebotomists, and mammographers.</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;5</p><p>Next</p><p>Health Informatics Pathway: Careers in the Health Informatics pathway involve lots of different jobs in the healthcare field. These jobs can include people who manage healthcare organizations, people who work with patient records and information, those who process and manage financial information, and people who maintain computer applications. These jobs help keep the healthcare system running smoothly and include transcriptionists, medical billers, risk managers, and healthcare administrators.</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;5</p><p>Next</p><p>Support Services Pathway: Careers in the support services pathway provide a therapeutic environment for healthcare. There are a variety of jobs in this pathway and, while patients may not always notice these positions, they play a crucial role in the healthcare system. Some of careers in this pathway include dietary technicians, hospital maintenance engineers, medical librarians, and biomedical equipment technicians.</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;5</p><p>Next</p><p>Biotechnology Research and Development Pathway: Careers in the Biotechnology Research and Development pathway involve working with science and technology to help people stay healthy. They may research diseases to try and find better treatments, or they may work on inventions designed to help patients or improve treatment and diagnosis. Examples of careers in this pathway include microbiologists, pharmaceutical scientists, research associates, and clinical trials research coordinators.</p><p>Previous</p><p>Slide&#160;5&#160;of&#160;5</p><p>Next</p><p>Now that you’ve learned about the pathways, see if you can match the job to the correct pathway.&#160; Drag the card to the correct pathway:</p><p>If you are using a keyboard to navigate, you must use the following alternative activity to receive credit.</p><p>Biotechnology Research and Development Pathway</p><p>Support Services Pathway</p><p>Health Informatics pathway</p><p>Diagnostic Services Pathway</p><p>Therapeutic Services Pathway</p><p>Alternative Activity</p><p>Match up each choice with a category.</p><p>1. Aaron is a psychologist&#160;Biotechnology Research and Development Pathway&#160;Support Services Pathway&#160;Health Informatics pathway&#160;Diagnostic Services Pathway&#160;Therapeutic Services Pathway</p><p>2. Carlos is a pharmaceutical scientist&#160;Biotechnology Research and Development Pathway&#160;Support Services Pathway&#160;Health Informatics pathway&#160;Diagnostic Services Pathway&#160;Therapeutic Services Pathway</p><p>3. Kaila is a hospital maintenance engineer&#160;Biotechnology Research and Development Pathway&#160;Support Services Pathway&#160;Health Informatics pathway&#160;Diagnostic Services Pathway&#160;Therapeutic Services Pathway</p><p>4. Zayne is a medical biller&#160;Biotechnology Research and Development Pathway&#160;Support Services Pathway&#160;Health Informatics pathway&#160;Diagnostic Services Pathway&#160;Therapeutic Services Pathway</p><p>5. Amaya is a radiologist&#160;Biotechnology Research and Development Pathway&#160;Support Services Pathway&#160;Health Informatics pathway&#160;Diagnostic Services Pathway&#160;Therapeutic Services Pathway</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('92db2377e979e17c3848c120c25415ad','career-exploration-m8-l3-lesson-2','83d9dac8ec3bb84b2f00248cb0f2a022','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Where Health Science ppl Work</h3><p>Where Health Science ppl Work</p><p>Where People in the Health Science Career Cluster Work</p><p>There are a variety of places where someone in the Health Science cluster may work.&#160;Even people with the same job title may work in very different places.&#160;For example, one psychologist may work at a hospital, while another may work at an educational institution, while another may choose to open a private practice.</p><p>5</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Where people in the health science career cluster find employment.</p><p>The hotspot points on the image are as follows:</p><p>Pharmaceutical Companies</p><p>Pharmaceutical companies are businesses that develop, manufacture, and market prescription and over-the-counter medications. They often employ health science professionals to conduct research, develop new drugs, and monitor safety and efficacy.</p><p>Private Practice</p><p>Private practice is when health science professionals open their own practice and provide services directly to patients without working for an organization.</p><p>Research Institutions</p><p>Research institutions are organizations that conduct scientific research and development. They often employ health science professionals to assist in the development and testing of new treatments and therapies.</p><p>Government Agencies</p><p>Government agencies employ health science professionals to conduct research, develop and implement public policies, and provide health care services.</p><p>Clinic</p><p>Clinics are healthcare facilities that provide primary care and specialized medical services. They are typically staffed by a team of healthcare professionals, such as nurses, doctors, and technicians.</p><p>Education Institutions</p><p>Education institutions, such as universities and colleges, employ health science professionals to teach, research, and provide clinical services.</p><p>Hospitals</p><p>Hospitals are healthcare facilities that provide comprehensive medical care for patients requiring diagnosis, treatments, and rehabilitation services. Hospitals also typically provide 24-hour emergency services, inpatient and outpatient services, diagnostic facilities, and specialized clinics.</p><p>Long-Term Care Facilities</p><p>Long-term care facilities provide care and services for those who require extended medical care. These facilities typically offer skilled nursing, physical therapy, occupational therapy, and other specialized services.</p><p>In addition to those places listed above, professionals in this career cluster may also find work in places like nonprofit organizations, corporations, and even with professional sports organizations.&#160;Many places benefit from the knowledge and expertise health science professionals bring to an organization.&#160;They help keep employees and others healthy and help improve the health of members of the organization.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('33ca316debb48072ff191cbc0a1b1496','career-exploration-m8-l4-lesson-3','83d9dac8ec3bb84b2f00248cb0f2a022','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Activities in Health Science Careers</h3><p>Activities in Health Science Careers</p><p>Activities in the Health Science Career Cluster</p><p>There are many activities required to keep the general population healthy both physically and mentally.&#160;Luckily,&#160; it isn’t up to just one group of professionals to take care of all the healthcare-related activities.&#160;The exact tasks performed by someone in the Health Science cluster depend on their chosen profession.&#160;However, here are some of the common tasks.</p><p>Click to learn more about each one:</p><p>Diagnose illnesses and treat injuries</p><p>Health science professionals help people stay healthy by finding out what is wrong and treating the problem in the best way for the patient.</p><p>Prescribe medications</p><p>Medication can help speed up the body’s healing process, alleviate pain, and treat infections. Professionals that can legally prescribe medication must know the risk and benefits of many different medications and prescribe the right one.</p><p>Educate patients on health and wellness</p><p>Health science professionals may teach patients about healthy habits and practices.</p><p>Medical testing</p><p>Health science professionals perform tests to find out what is wrong with a patient and then look at the results to figure out what needs to be done.</p><p>Research</p><p>Some professionals may research medical issues and figure out how to make treatments that help people get better.</p><p>Operate medical equipment</p><p>Some health science professionals are trained to use special machines to help diagnose illnesses and treat injuries.</p><p>Perform surgery</p><p>Surgeons, surgical assistants, anesthesiologists, and others perform surgery to fix or repair a part of the body that does not work correctly.</p><p>Monitor patient progress</p><p>Many health sciences professionals keep track of how well patients are doing by checking on them regularly.</p><p>Document patient care</p><p>Documentation is an important part of healthcare so there is a record of the patient’s health and treatment history.</p><p>Monitor public health policies and trends</p><p>Those in public health look at public health trends and determine what interventions may be needed to improve public health.</p><p>Develop healthcare plans</p><p>An important part of getting and staying healthy is having a plan. Health science professionals share their knowledge with patients on the best course of action for improving their health.</p><p>Manage healthcare teams</p><p>In order to provide the best healthcare experience possible, there must be those who ensure all members of the healthcare team are doing their part and everything is running smoothly.</p><p>Direct public health initiatives</p><p>Some professionals may lead public health initiatives to help improve the health of the community</p><p>Implement health safety regulations</p><p>This involves making sure everyone is follows the health protocols for an organization.</p><p>As you can see, there are many tasks in the Health Science career cluster.&#160;By learning more about these tasks, you can discover which ones seem most interesting to you.&#160;This can help you discover which career may be the best fit for your future.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('cb2db41903e473caa1f8550b3b0b9e98','career-exploration-m8-l5-lesson-4','83d9dac8ec3bb84b2f00248cb0f2a022','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Skills Needed in Health Science Career</h3><p>Skills Needed in Health Science Career</p><p>Skills, Abilities, and Talents Needed for a Career in Health Science</p><p>The health science industry requires people with many skills, abilities, and talents.&#160;What those skills, abilities, and talents are depends on the specific job and area of expertise.&#160;For example, a psychologist may need a different set of skills than a medical billing specialist.&#160;Let’s explore some of the most common skills, abilities, and talents in this career cluster.&#160;Click on a tab to learn more about each one:</p><p>Critical Thinking</p><p>The ability to think critically and analyze information in order to make informed decisions is very important when doing health research and treating patients.</p><p>Interpersonal Skills</p><p>The ability to effectively communicate with others and work collaboratively as part of a team is essential to many careers in this cluster because of the many people it takes to establish effective healthcare.</p><p>Technical Skills</p><p>Some individuals in this cluster need the ability to use technology and medical equipment to diagnose and treat patients.</p><p>Empathy</p><p>The ability to understand and appreciate the feelings of patients and how they respond to treatment is essential to healthcare.</p><p>Communication Skills</p><p>Many professionals in this cluster need the ability to communicate clearly and effectively with patients, families, and medical staff.</p><p>Attention to Detail</p><p>The ability to pay attention to small details in order to accurately diagnose and treat patients helps prevent misdiagnosis and other serious complications.</p><p>Physical Strength</p><p>Some professionals need the ability to lift and move patients, equipment, and supplies.</p><p>Patience</p><p>The ability to stay calm and composed in stressful situations is crucial in the emergency room, operating room, and other stressful healthcare situations.</p><p>Time Management</p><p>The ability to prioritize tasks, manage time efficiently, and meet deadlines helps keep patient healthcare running smoothly.</p><p>Adaptability</p><p>This career cluster requires the ability to quickly adjust to new situations and environments.</p><p>Research Skills</p><p>The ability to locate and evaluate information in order to make informed decisions helps the health science industry progress.</p><p>Organizational Skills</p><p>The ability to organize and maintain medical records and other documents is key to many of the roles in the Health Science cluster.</p><p>Leadership Skills</p><p>Healthcare often requires a team, and that requires someone with the ability to motivate, inspire, and lead a team of medical professionals.</p><p>Next Tab</p><p>While this may seem like an overwhelming number of skills, abilities, and talents, keep in mind that it varies from job to job.&#160;Also remember that many of these skills you can start developing now.&#160;Here are some things you can do to prepare for a successful career in this cluster:</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Take science and math classes, such as biology, chemistry, anatomy, physiology, algebra, and calculus.</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;6</p><p>Next</p><p>Participate in extracurricular activities related to the health sciences, such as volunteering at a hospital or shadowing a health professional.</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;6</p><p>Next</p><p>Research health science career paths and develop a plan for how to reach them.</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;6</p><p>Next</p><p>Join clubs and organizations related to the health sciences, such as the Health Occupations Students of America (HOSA).</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;6</p><p>Next</p><p>Take part in career exploration activities, such as visiting health science career fairs.</p><p>Previous</p><p>Slide&#160;5&#160;of&#160;6</p><p>Next</p><p>Seek out mentors who are already in the health sciences.</p><p>Previous</p><p>Slide&#160;6&#160;of&#160;6</p><p>Next</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('7cf24a39cb8122aed03114d7c60473c7','career-exploration-m8-l6-lesson-5','83d9dac8ec3bb84b2f00248cb0f2a022','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Health Science Requirements</h3><p>Health Science Requirements</p><p>Education and training play a large role in the preparation for a career in the Health Science career cluster.&#160;Many health science careers require certifications or licensing, which can only be obtained through education and training.&#160;Education and training also help to ensure that healthcare professionals are up-to-date on the latest advances in the field, which helps ensure the safety and quality of patient care.&#160;The training and education requirements vary depending on the profession, but here are some of the common professions and associated requirements:</p><p>Certified Nurse Assistant</p><p>Most states require certified nurse assistants to complete a state-approved training program and pass a competency evaluation. The program typically consists of a combination of classroom and clinical instruction and may last four to twelve weeks.</p><p>Registered Nurse</p><p>Registered nurses must earn a minimum of an Associate&#39;s degree in nursing, though many pursue a Bachelor&#39;s or Master&#39;s degree. All states also require prospective nurses to pass an exam known as the NCLEX-RN, and most states also require some form of continuing education.</p><p>Doctor</p><p>Doctors must complete a four-year undergraduate degree, followed by four years of medical school and three to eight years of residency training. Depending on their specialty, doctors may also need to complete additional training, such as fellowships.</p><p>Dentist</p><p>Dentists must complete a four-year undergraduate degree, followed by four years of dental school and a one-year residency program. In some states, dentists must also pass a written and practical exam.</p><p>Psychologist</p><p>Psychologists must complete a four-year undergraduate degree, followed by four to seven years of doctoral study, followed by an internship and/or fellowship. All states also require prospective psychologists to pass an exam.</p><p>Emergency Medical Technician (EMT)</p><p>Emergency medical technicians must complete a state-approved training program, which typically consists of classroom and clinical instruction. Most states also require prospective EMTs to pass a written and practical exam.</p><p>Phlebotomist</p><p>Phlebotomists must complete a state-approved training program, which typically consists of classroom and clinical instruction. Most states also require prospective phlebotomists to pass a written and practical exam.</p><p>Occupational therapist</p><p>Occupational therapists must complete a four-year undergraduate degree, followed by a three-year master&#39;s degree program. All states also require prospective occupational therapists to pass an exam.</p><p>Medical billing specialist</p><p>Medical billing specialists must complete a two-year associate&#39;s degree program in medical billing and coding. Some states may also require prospective medical billing specialists to pass a certification exam.</p><p>Healthcare administrator</p><p>Healthcare administrators must complete a four-year undergraduate degree, followed by a master&#39;s degree in health services administration or a similar field. Most states also require prospective healthcare administrators to pass a certification exam.</p><p>Surgeon</p><p>Surgeons must complete a four-year undergraduate degree, followed by four years of medical school and three to eight years of residency training. Depending on their specialty, surgeons may also need to complete additional training, such as fellowships.</p><p>Dental hygienist</p><p>Dental hygienists must complete an associate degree program in dental hygiene. All states also require prospective dental hygienists to pass a written and practical exam.</p><p>As you can see, some Health Science career cluster professionals have a little training post-high school while others have well over a decade before their education and training is complete.&#160;No matter how much education is required, successful mastery of the concepts and procedures is essential to quality health care and industry progression.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('01f3b542e0534f0d824156f134a2ff55','career-exploration-m8-l7-module-8-summary','83d9dac8ec3bb84b2f00248cb0f2a022','Module 8 Summary','text',12,'<h2>Module 8 Summary</h2><section><h3>Module 8 Summary</h3><p>Module 8 Summary</p><p>Great Work!&#160;You have successfully completed this module on the Health Science Career Cluster.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified the pathways in the Health Science career cluster and the careers in each pathway.</p><p>Described the types of places that employ individuals who have careers in the Health Science career cluster.</p><p>Described the variety of tasks performed by individuals who have careers in the Health Science career cluster.</p><p>Listed the skills, abilities, and talents needed for careers in the Health Science career cluster.</p><p>Identified the level of training and education required for careers in the Health Science career cluster.</p><p>Researched a career in the Health Science career cluster and present findings to the class.</p><p>Applied math, science, and reading skills in the completion of a project or activity related to the Health Science career cluster.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('9ddcd617b4dfd982c98cc338d9b0638b','career-exploration-m8-l8-module-8-project','83d9dac8ec3bb84b2f00248cb0f2a022','Module 8 Project','text',12,'<h2>Module 8 Project</h2><section><h3>Module 8 Project</h3><p>Module 8 Project</p><p>Career Exploration</p><p>Health Science - Project</p><p>For this project, you will choose from two options.&#160; You only need to complete one of these options.&#160; Please find both options and their rubrics below.</p><p>Option 1</p><p>For this project, you will create an infographic about the impact of sleep deprivation on learning. Your infographic should include the following:</p><p>An eye-catching headline</p><p>An organized layout with graphics (pictures, illustrations, etc.)</p><p>Short, concise descriptions</p><p>3+ data points (facts about sleep deprivation/learning)</p><p>Information about the sources of the data</p><p>Review the rubric below to see how you will be graded.</p><p>Option 1 Rubric: Health Science Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Headline</p><p>4 points The headline is interesting and engaging.</p><p>3 points The headline is somewhat interesting and engaging.</p><p>0-2 points The headline is not interesting or engaging and/or is missing.</p><p>4</p><p>Layout</p><p>4 points The layout is well-organized and contains appropriate graphics.</p><p>3 points The layout is mostly well-organized and contains appropriate graphics.</p><p>0-2 points The layout is not well-organized and/or does not contain appropriate graphics.</p><p>4</p><p>4 points Descriptions and information are concise and central to the topic.</p><p>3 points Descriptions and information are somewhat concise and central to the topic.</p><p>0-2 points Descriptions and information are not concise and central to the topic.</p><p>4</p><p>Data Points</p><p>4 points Contains 3 or more data points.</p><p>3 points Contains 3 or more data points.</p><p>0-2 points Does not contain 3 or more data points.</p><p>4</p><p>Sources</p><p>4 points All sources are cited and credible.</p><p>3 points Most sources are cited and credible.</p><p>0-2 points Sources are not cited and/or not credible.</p><p>4</p><p>Total Points:&#160;20</p><p>Option 2</p><p>For this option, you will research a particular career that interests you in this cluster. Complete the following steps for your project:</p><p>Step 1: Research your chosen career.</p><p>Step 2: List the following</p><p>Average Salary/Salary Range</p><p>Education Requirements</p><p>Certification Requirements (if any)</p><p>Why you chose that career</p><p>Step 3: Prepare a PowerPoint presentation about your chosen career, including the information you gathered in Step 2 as well as your reason for choosing that career.</p><p>Your final submission should be your PowerPoint containing the information in Step 3.</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 2 Rubric: Health Science Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Research</p><p>12 points The student provided a career field that interested them, the average salary or range, and the education/certifications required for the career.</p><p>11-4 points The student provided two of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>3-0 points The student provided one or none of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>12</p><p>Reason for Choosing the Career Field</p><p>4 points The student thoughtfully provided the reason that they are interested in this career.</p><p>N/A</p><p>0 points The student did not provide the reason that they are interested in this career.</p><p>4</p><p>Formatting</p><p>4 points The student&#39;s presentation includes no spelling or grammatical errors.</p><p>3-1 points The student&#39;s presentation includes minimal spelling or grammatical errors.</p><p>0 points The student&#39;s presentation includes a significant amount of spelling or grammatical errors.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e81843a09a75dd6caefb9690d51ef647','career-exploration-m8-l9-module-8-quiz','83d9dac8ec3bb84b2f00248cb0f2a022','Module 8 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Health Science. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('42c0fc1134f6a4fda8f3d9c437d58e42','career-exploration-module-9','68d48b60cc4feb626956ed1fd8311e46','Module 9: Hospitality & Tourism',9) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('dfabf1e2e3d0d88044bfe173efe6ecc4','career-exploration-m9-l1-introduction-purpose-and-objectives','42c0fc1134f6a4fda8f3d9c437d58e42','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hello and welcome to the Hospitality &amp; Tourism career cluster. This industry can take you anywhere from across the world to your own hometown. Before we jump into the content of this module, let’s explore some of the reasons why this is an excellent career cluster:</p><p>- Hospitality &amp; Tourism industry employs over 330 million people, so there are all kinds of jobs for all kinds of people.</p><p>- The industry is expected to grow by 4.3% annually over the next several years, making it one of the fastest-growing sectors of the global economy.</p><p>- Hotels, restaurants, and cruise ships are three of the major components of the hospitality &amp; tourism industry.</p><p>- The industry is a major source of job creation, accounting for 10% of all new jobs created between 2008 and 2018.</p><p>- Tourism is the world’s largest export, generating trillions of dollars annually.</p><p>- The hospitality &amp; tourism industry is becoming increasingly technology-focused, with more and more services being provided through digital platforms. So for those of you that also love technology, this may be a great way to merge interests.</p><p>- And finally, the global hospitality &amp; tourism industry is estimated to be worth over $8 trillion.</p><p>Pretty amazing facts, right? Clearly, this is one career cluster that is not to be ignored, especially if you have a passion for travel, culture, and food!</p><p>In this module, we’ll explore the pathways in this career cluster such as the restaurants and food &amp; beverage services pathway, lodging pathway, and the recreation, amusement &amp; attractions pathway. Then you’ll learn about some of the places where you could work in this industry. You’ll be amazed at all of the options out there.</p><p>We’ll also explore what activities someone in this career cluster might perform. While a day in the life of a hotel manager may be very different from the day in the life of a language interpreter on a cruise ship, you can still get an overview of what the activities in this industry may be.</p><p>Finally, we’ll talk about the skills, abilities, and talents you need to succeed in the industry as well as the education and training needed to get those skills.</p><p>If you’re ready to explore this career cluster, then let’s get into it!</p><p>Module Description</p><p>Welcome to this module on the Hospitality &amp; Tourism career cluster!&#160;In this module, you will discover the various pathways in this cluster and some of the jobs associated with each pathway.&#160;You&#39;ll learn which pathway is best for someone with an interest in the culinary arts and which one would be best for someone with an interest in building the next Disneyland, as well as everything in between.&#160;Next, we will discuss the types of places that employ individuals in this field and the variety of tasks people in this industry perform.&#160;You will also learn about the skills, abilities, and talents needed for careers in this field and how you can start developing these skills now.&#160;We will also discuss one of the most crucial aspects of this career cluster- training and education.&#160;The module will conclude with a project designed to help you explore the hospitality and tourism industry up close.</p><p>Objectives</p><p>In this module, students will</p><p>Identify the pathways in the Hospitality &amp; Tourism career cluster and the careers in each pathway.</p><p>Describe the types of places that employ individuals who have careers in the Hospitality &amp; Tourism career cluster.</p><p>Describe the variety of tasks performed by individuals who have careers in the Hospitality &amp; Tourism career cluster.</p><p>List the skills, abilities, and talents needed for careers in the Hospitality &amp; Tourism career cluster.</p><p>Identify the level of training and education required for careers in the Hospitality &amp; Tourism career cluster.</p><p>Research a career in the Hospitality &amp; Tourism career cluster and present findings to the class.</p><p>Apply math, science, and reading skills in the completion of a project or activity related to the Hospitality &amp; Tourism career cluster.</p><p>Polling Question</p><p>Which of the following careers in the Hospitality &amp; Tourism career cluster sounds most interesting to you?</p><p>Chef&#160;Tour guide&#160;Hotel owner&#160;Event planner&#160;Other</p><p>Results:</p><p>Tour guide&#160;100%</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Warning:&#160;json_decode() expects parameter 1 to be string, object given in&#160;/srv/app/current/blocks/interactive_definitions/controller.php&#160;on line&#160;238</p><p>Extras that make a place more comfortable, like TVs in hotel rooms.</p><p>Tourism</p><p>A type of travel that involves people going to different places for fun or to learn about different cultures.</p><p>Beverage</p><p>A place to stay, like a hotel or an inn.</p><p>Culinary</p><p>A drink, like water, soda, juice, or coffee.</p><p>Lodging</p><p>Cooking or the skills related to cooking food.</p><p>Amenities</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Extras that make a place more comfortable, like TVs in hotel rooms.</p><p>Answers for question: 1</p><p>Beverage</p><p>Lodging</p><p>Amenities</p><p>Culinary</p><p>Tourism</p><p>2.</p><p>A type of travel that involves people going to different places for fun or to learn about different cultures.</p><p>Answers for question: 2</p><p>Amenities</p><p>Beverage</p><p>Tourism</p><p>Lodging</p><p>Culinary</p><p>3.</p><p>A place to stay, like a hotel or an inn.</p><p>Answers for question: 3</p><p>Tourism</p><p>Culinary</p><p>Lodging</p><p>Amenities</p><p>Beverage</p><p>4.</p><p>A drink, like water, soda, juice, or coffee.</p><p>Answers for question: 4</p><p>Amenities</p><p>Beverage</p><p>Tourism</p><p>Culinary</p><p>Lodging</p><p>5.</p><p>Cooking or the skills related to cooking food.</p><p>Answers for question: 5</p><p>Tourism</p><p>Amenities</p><p>Culinary</p><p>Beverage</p><p>Lodging</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b0209153990c513c956dd9daae8292ff','career-exploration-m9-l2-lesson-1','42c0fc1134f6a4fda8f3d9c437d58e42','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>What is Hospitality &amp; Tourism Career</h3><p>What is Hospitality &amp; Tourism Career</p><p>What is the Hospitality &amp; Tourism Career Cluster?</p><p>The hospitality and tourism career cluster focuses on taking care of people and helping them have a great experience when they travel, attend an event, dine at a restaurant, and do other travel-related activities.&#160;It includes jobs like hotel managers, tour guides, restaurant workers, and even people who work at theme parks.&#160;It&#39;s about making sure people have a safe and enjoyable time when they&#39;re out exploring the world.</p><p>There are four primary pathways in this cluster.&#160;Click on the hotspots in the image below to learn more about each pathway:</p><p>5</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Pathways in the Hospitality &amp; Tourism career cluster.</p><p>The hotspot points on the image are as follows:</p><p>Recreation, Amusements, &amp; Attractions Pathway</p><p>This pathway is about providing people with fun and exciting activities. People in this pathway might work in amusement parks, movie theaters, bowling alleys, museums, and other places where people can have fun. They might help people buy tickets, provide information about the activities available, and help people have a safe and enjoyable time. Jobs in this pathway include club personnel, museums/zoos/aquariums personnel, park ranger, and ticket vendors.</p><p>Lodging Pathway</p><p>This pathway is about providing hospitality to people who stay overnight in hotels, motels, and other places. People in this pathway make sure guests have comfortable and clean rooms, help them with any problems they might have, and answer any questions they might have about the area. Jobs in this pathway include executive housekeepers, lodging managers, concierges, and hotel owners.</p><p>Restaurants &amp; Food/Beverage Services Pathway</p><p>This pathway involves preparing and serving food and drinks. People in this pathway work in restaurants, cafes, and other places where people can buy food and drinks. They might take orders, work in the kitchen to prepare food, serve food and drinks, and clean up after customers leave. Jobs in this pathway include bakers, executive chefs, caterers, restaurant servers, and bartenders.</p><p>Travel &amp; Tourism Pathway</p><p>This pathway is about helping people plan and enjoy their trips. People in this pathway might work in travel agencies, help people find good places to stay and things to do, and provide information to help people have the best time on their trip. Some of the careers in this pathway include events manager/planner, interpreter, travel agent, and tour guide.</p><p>Now that you’ve learned about the pathways, see if you can match the job to the correct pathway.&#160; Drag the card to the correct pathway:</p><p>If you are using a keyboard to navigate, you must use the following alternative activity to receive credit.</p><p>Restaurants &amp; Food/Beverage Services Pathway</p><p>Lodging Pathway</p><p>Travel &amp; Tourism Pathway</p><p>Recreation, Amusements, &amp; Attractions Pathway</p><p>Alternative Activity</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('761604ce94262098a390fb83fc15c410','career-exploration-m9-l3-lesson-2','42c0fc1134f6a4fda8f3d9c437d58e42','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Where Hospitality &amp; Tourism ppl Work</h3><p>Where Hospitality &amp; Tourism ppl Work</p><p>Where People in the Hospitality &amp; Tourism Career Cluster Work</p><p>The Hospitality and Tourism career cluster offers a variety of exciting places to work.&#160;Click through the slideshow to learn more about some of these places of employment:</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Hotels are establishments that provide lodging and other amenities to travelers.&#160;People employed in the hospitality and tourism industry in hotels typically include front desk clerks, housekeeping staff, concierges, maintenance workers, and catering staff.</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;10</p><p>Next</p><p>Resorts are usually larger than hotels and offer a variety of amenities, such as golf courses, spas, and beach access. People employed in the hospitality and tourism industry at resorts may include front desk clerks, housekeeping staff, maintenance workers, concierges, and food and beverage staff.</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;10</p><p>Next</p><p>Casinos provide a variety of gaming options, entertainment, and other amenities. People employed in the hospitality and tourism industry at casinos may include gaming managers, security personnel, gaming dealers, and food and beverage staff.</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;10</p><p>Next</p><p>Restaurants serve food and drinks and may offer other amenities such as live entertainment. People employed in the hospitality and tourism industry at restaurants may include chefs, waitstaff, bartenders, and hostesses.</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;10</p><p>Next</p><p>Cruise ships offer travelers a unique way to explore the world- by sea! People employed in the hospitality and tourism industry on cruise ships may include deckhands, stewards, food and beverage staff, and entertainment staff.</p><p>Previous</p><p>Slide&#160;5&#160;of&#160;10</p><p>Next</p><p>Airlines provide transportation for travelers. People employed in the hospitality and tourism industry at airlines may include flight attendants, pilots, ticket agents, and customer service representatives.</p><p>Previous</p><p>Slide&#160;6&#160;of&#160;10</p><p>Next</p><p>Tour operators are companies that provide guided tours and other services to travelers. People employed in the hospitality and tourism industry at tour operators may include tour guides, customer service staff, and sales representatives.</p><p>Previous</p><p>Slide&#160;7&#160;of&#160;10</p><p>Next</p><p>Travel agencies help travelers plan their trips and book travel arrangements. People employed in the hospitality and tourism industry at travel agencies may include travel agents, customer service staff, and sales representatives.</p><p>Previous</p><p>Slide&#160;8&#160;of&#160;10</p><p>Next</p><p>Theme parks offer a variety of attractions, entertainment, and food and beverage options. People employed in the hospitality and tourism industry at theme parks may include ticket takers, ride operators, food and beverage staff, and maintenance workers.</p><p>Previous</p><p>Slide&#160;9&#160;of&#160;10</p><p>Next</p><p>Convention and meeting centers provide spaces for conferences, conventions, and other events. People employed in the hospitality and tourism industry at convention and meeting centers may include event planners, customer service staff, and food and beverage staff.</p><p>Previous</p><p>Slide&#160;10&#160;of&#160;10</p><p>Next</p><p>As you can see, there are many types of businesses that employ people in the Hospitality &amp; Tourism career cluster.&#160;This allows professionals in this cluster to consider not just what they want to do, but where they want to do it.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('06616c39d3b7fb7d19ad4eab57295f50','career-exploration-m9-l4-lesson-3','42c0fc1134f6a4fda8f3d9c437d58e42','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Activities in the Hospitality &amp; Tourism Career</h3><p>Activities in the Hospitality &amp; Tourism Career</p><p>Activities in the Hospitality &amp; Tourism Career Cluster</p><p>People in the Hospitality and Tourism career cluster perform a variety of tasks.&#160;Most of these tasks center around promoting a business in the hospitality and tourism industry, or ensuring customers have a positive experience with a hospitality and tourism-related business.&#160;Some of those activities are listed below.</p><p>Click to learn more about each one:</p><p>Event planning</p><p>Planning and managing events such as conferences, conventions, and weddings.</p><p>Marketing</p><p>Developing marketing plans to promote a business in the industry.</p><p>Customer service</p><p>Providing customer service in hotels, restaurants, airlines, and other hospitality establishments to ensure customers are satisfied with the experience.</p><p>Transportation coordination</p><p>Coordinating transportation services for travelers and guests.</p><p>Running tours</p><p>Creating and managing tour packages and logistics.</p><p>Ensuring guest safety</p><p>Developing and implementing safety protocols for hospitality businesses.</p><p>Money management</p><p>Managing finances for hospitality and tourism businesses.</p><p>Training</p><p>Training staff to ensure customer satisfaction.</p><p>Research</p><p>Researching and analyzing trends in the hospitality industry.</p><p>Management</p><p>Overseeing food and beverage operations, travel operations, and accommodation operations.</p><p>Event setup</p><p>Setting up and breaking down conference rooms, lobbies, and other locations for events.</p><p>Analysis</p><p>Analyzing customer data to better optimize services for customers.</p><p>Travel coordination</p><p>Helping travelers make arrangements for accommodations, attractions, and other services.</p><p>Sales</p><p>Promoting events, attractions, and accommodations to generate revenue for a business.</p><p>Food and beverage preparation</p><p>Preparing food for restaurants, catered events, bakeries, etc.</p><p>Maintenance and cleaning</p><p>Ensuring all premises are clean, safe, and well-maintained.</p><p>As you can see, it takes the work of many people performing a variety of tasks to create a positive experience for customers when they interact with a business in the hospitality and tourism industry.&#160;While not every person in this Hospitality &amp; Tourism career cluster will perform each of the activities listed, most professionals will perform multiple tasks.&#160;For example, a head housekeeper at a hotel will not only contribute to the maintenance and cleanliness of the hotel, but may also train new housekeepers as well.&#160;An event planner may not only work out the details of an event, but may also be responsible for transportation coordination for the event.&#160;In this way, each professional has many opportunities to contribute to the success of the experience for the customer.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('74eb1d1d3c63ead27d5513c649d82482','career-exploration-m9-l5-lesson-4','42c0fc1134f6a4fda8f3d9c437d58e42','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Skills Needed in Hospitality &amp; Tourism</h3><p>Skills Needed in Hospitality &amp; Tourism</p><p>Skills, Abilities, and Talents Needed for a Career in Hospitality &amp; Tourism</p><p>A career in the Hospitality &amp; Tourism requires many skills, abilities, and talents.&#160;Some of these skills are listed below.&#160;Click through the tabs to learn more about each one.</p><p>Communication Skills</p><p>Being able to effectively communicate with customers, colleagues, and management is essential in the hospitality and tourism industry.&#160;This includes being able to listen, understand, and respond to customer needs and requests.</p><p>Interpersonal Skills</p><p>Hospitality and tourism professionals must be able to work well with others, as they often interact with customers and colleagues from diverse backgrounds. Being able to build relationships and manage conflicts is essential.</p><p>Leadership Skills</p><p>Many hospitality and tourism professionals are in management positions and must be able to lead their staff and manage operations. This includes being able to provide guidance, set goals, and motivate team members.</p><p>Problem-Solving Abilities</p><p>Hospitality and tourism professionals must be able to recognize and solve problems quickly and efficiently. This includes being able to think on their feet and address customer concerns and complaints.</p><p>Organizational Skills</p><p>Being able to stay organized is essential for hospitality and tourism professionals. This includes being able to manage multiple tasks, prioritize work, and delegate responsibilities.</p><p>Time Management</p><p>Hospitality and tourism professionals must be able to manage their time and resources effectively. This includes being able to work quickly and efficiently in order to meet deadlines and customer expectations.</p><p>Computer Skills</p><p>Many hospitality and tourism professionals must be able to use computers in order to manage customer bookings, reservations, and payments. This includes being able to use software such as Microsoft Office, point-of-sale systems, and customer relationship management systems.</p><p>Negotiation</p><p>In the hospitality and tourism industry, professionals must be able to negotiate with customers, suppliers, and other stakeholders. This includes being able to assess customer needs and offer solutions that are beneficial to all parties.</p><p>Customer Service</p><p>Hospitality and tourism professionals must be able to provide excellent customer service. This includes being able to address customer complaints and concerns, as well as anticipating customer needs and providing solutions.</p><p>Financial Management</p><p>Many hospitality and tourism professionals are responsible for managing budgets, making financial decisions, and analyzing financial data. This includes being able to understand financial statements, allocate resources, and make cost-effective decisions.</p><p>Sales and Marketing Skills</p><p>Hospitality and tourism professionals must be able to market their services and products effectively. This includes being able to identify customer needs, create promotional materials, and use digital marketing platforms.</p><p>Multilingual Skills</p><p>Being able to communicate in multiple languages is an asset in the hospitality and tourism industry. This includes being able to converse with customers in their native language, as well as being able to translate documents and materials.</p><p>Next Tab</p><p>Now that you know about some of these skills, talents, and abilities, let’s see if you can match the situation to the needed skill:</p><p>Skill Needed</p><p>A concierge must notify the rest of the hotel staff about the special accommodations required by a customer.</p><p>Negotiation</p><p>A restaurant host must make the guests feel welcome and also work well with the servers and other staff in the restaurant.</p><p>Problem-Solving</p><p>A restaurant manager must make sure that all staff members know their assignments and also make sure that a new employee remembers what to do.</p><p>Interpersonal skills</p><p>A tour guide must make last-minute adjustments to the tour due to the weather.</p><p>Time-management</p><p>An event planner needs to make sure that all of the participating vendors, supplies, and equipment are ready for the event and that everything is running on schedule.</p><p>Organization</p><p>A baker needs to make sure he has the pastries ready for the morning breakfast customers.</p><p>Communication skills</p><p>A web designer needs to update a website for a hotel.</p><p>Sales and Marketing skills</p><p>A restaurant owner needs to work out a deal with a supplier.</p><p>Financial management</p><p>A cruise ship server needs to speak with a disgruntled customer and remain calm and supportive during the interaction.</p><p>Computer skills</p><p>A tour operator owner needs to find ways to reduce costs without sacrificing the experience for the customers.</p><p>Leadership skills</p><p>A travel agent wants to convince a couple that she can help them find the best honeymoon package for them.</p><p>Multilingual skills</p><p>An interpreter must make sure his group understands the safety procedures on a cruise ship.</p><p>Customer service</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>A concierge must notify the rest of the hotel staff about the special accommodations required by a customer.</p><p>Answers for question: 1</p><p>Time-management</p><p>Customer service</p><p>Financial management</p><p>Multilingual skills</p><p>Negotiation</p><p>Organization</p><p>Communication skills</p><p>Interpersonal skills</p><p>Sales and Marketing skills</p><p>Leadership skills</p><p>Problem-Solving</p><p>Computer skills</p><p>2.</p><p>A restaurant host must make the guests feel welcome and also work well with the servers and other staff in the restaurant.</p><p>Answers for question: 2</p><p>Negotiation</p><p>Sales and Marketing skills</p><p>Interpersonal skills</p><p>Time-management</p><p>Organization</p><p>Communication skills</p><p>Leadership skills</p><p>Computer skills</p><p>Financial management</p><p>Customer service</p><p>Problem-Solving</p><p>Multilingual skills</p><p>3.</p><p>A restaurant manager must make sure that all staff members know their assignments and also make sure that a new employee remembers what to do.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('cfc3f27f67d8a8540c83eb1b9c943d29','career-exploration-m9-l6-lesson-5','42c0fc1134f6a4fda8f3d9c437d58e42','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Learning in Hospitality &amp; Tourism Career</h3><p>Learning in Hospitality &amp; Tourism Career</p><p>Education and Training in the Hospitality &amp; Tourism Career Cluster:</p><p>The Hospitality &amp; Tourism career cluster is an excellent avenue for people of many different educational backgrounds and training.&#160;For example, one individual may have very little formal education but be fluent in two or more languages as well as knowledge of different cultural norms and practices.&#160;That person may be an asset to a company that has a need for an interpreter.&#160;Another individual may put their advanced business degree into practice by running a successful hotel, for example.</p><p>Some of the various job opportunities at different educational levels are listed below.&#160;Click on the tabs to learn more:</p><p>High School Diploma</p><p>With a high school diploma, you can typically get jobs in the hospitality and tourism career cluster as a hotel receptionist, restaurant server, housekeeper, or tour guide.</p><p>Associate Degree</p><p>With an associate degree, you can typically find jobs in the hospitality and tourism career cluster as a hotel manager, restaurant manager, event coordinator, or travel agent.</p><p>Bachelor&#39;s Degree</p><p>With a bachelor&#39;s degree, you can typically find jobs in the hospitality and tourism career cluster as a hotel or resort manager, marketing manager, tourism director, or hospitality consultant.</p><p>Graduate Degree</p><p>With a graduate degree, you can typically find jobs in the hospitality and tourism career cluster as a hospitality professor, hospitality researcher, or hospitality executive.</p><p>Culinary Degree</p><p>With a culinary degree, you can typically find jobs in the Hospitality &amp; Tourism career cluster as a chef, baker/pastry chef, and beverage professional.</p><p>Next Tab</p><p>You don’t have to wait until after high school to prepare for a successful career in this career cluster.&#160;Here are some things you can do right now:</p><p>Participate in hospitality and tourism-related activities in the community, such as volunteer work at a local hotel or restaurant.</p><p>Take part in hospitality and tourism-focused extracurricular activities, such as a school club or event-planning team.</p><p>Take advantage of career exploration opportunities offered by local businesses or organizations.</p><p>Attend career fairs and informational sessions about the hospitality and tourism industry.</p><p>Pursue internship or job shadow opportunities in the hospitality and tourism industry.</p><p>Take hospitality and tourism-focused classes or electives.</p><p>Participate in job-shadowing programs and summer programs offered by universities, colleges, and vocational schools.</p><p>Develop basic skills in customer service, communication, problem-solving, and time management.</p><p>Utilize online resources such as websites, blogs, and social media accounts to learn more about the hospitality and tourism industry.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1b50b1eafd3da858af034c3d440b1e2c','career-exploration-m9-l7-module-9-summary','42c0fc1134f6a4fda8f3d9c437d58e42','Module 9 Summary','text',12,'<h2>Module 9 Summary</h2><section><h3>Module 9 Summary</h3><p>Module 9 Summary</p><p>Great Work!&#160;You have successfully completed this module on the Hospitality &amp; Tourism career cluster.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified the pathways in the Hospitality &amp; Tourism career cluster and the careers in each pathway.</p><p>Described the types of places that employ individuals who have careers in the Hospitality &amp; Tourism career cluster.</p><p>Described the variety of tasks performed by individuals who have careers in the Hospitality &amp; Tourism career cluster.</p><p>Listed the skills, abilities, and talents needed for careers in the Hospitality &amp; Tourism career cluster.</p><p>Identified the level of training and education required for careers in the Hospitality &amp; Tourism career cluster.</p><p>Researched a career in the Hospitality &amp; Tourism career cluster and present findings to the class.</p><p>Applied math, science, and reading skills in the completion of a project or activity related to the Hospitality &amp; Tourism career cluster.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f3c62ef2249e0462ff96a297ff3ca81e','career-exploration-m9-l8-module-9-project','42c0fc1134f6a4fda8f3d9c437d58e42','Module 9 Project','text',12,'<h2>Module 9 Project</h2><section><h3>Module 9 Project</h3><p>Module 9 Project</p><p>Career Exploration</p><p>Hospitality &amp; Tourism - Project</p><p>For this project, you will choose from two options.&#160; You only need to complete one of these options.&#160; Please find both options and their rubrics below.</p><p>Option 1</p><p>For this project, you will complete the following:</p><p>Step 1: Make a list of 5 businesses in the Hospitality &amp; Tourism industry in your city or town.</p><p>Step 2: From your list, choose two similar businesses (ex: two hotels, two restaurants, two amusement parks, etc.).</p><p>Step 3: Research these two companies by visiting their websites, reading reviews, etc. If possible, visit these two companies in person.</p><p>Step 4: Create a write-up as though you are a travel blogger comparing the two options. Your write-up should include the following:</p><p>An introduction to each business that highlights what would make these places interesting to someone from out of town or visiting for the first time.</p><p>Anything notable or unique about each business.</p><p>Proximity to other tourist attractions (this is where the other businesses on your list may come in handy!)</p><p>What you personally like about each business (the pros, in your opinion)</p><p>What you see as drawback for each business (the cons, in your opinion)</p><p>Your final submission should include your list of 5 businesses as well as your travel blogger write-up of the two similar businesses.</p><p>Review the rubric below to see how you will be graded.</p><p>Option 1 Rubric: Hospitality &amp; Tourism Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Write-Up</p><p>14-16 Points All points of the prompt are addressed and the writeup is fun and engaging.</p><p>11-13 points Most points of the prompt are addressed and the writeup is mostly engaging.</p><p>0-10 points Few of the points in the prompt are addressed and/or the writeup is not fun or engaging.</p><p>16</p><p>List</p><p>4 points The submission includes a list of 5 businesses within the hospitality and tourism industry in the local area.</p><p>3 points The submission includes a list of 4 businesses in the hospitality and tourism industry in the local area.</p><p>0-2 points The submission contains fewer than 4 businesses in the hospitality and tourism industry in the local area.</p><p>4</p><p>Total Points:&#160;20</p><p>Option 2</p><p>For this option, you will research a particular career that interests you in this cluster. Complete the following steps for your project:</p><p>Step 1: Research your chosen career.</p><p>Step 2: List the following</p><p>Average Salary/Salary Range</p><p>Education Requirements</p><p>Certification Requirements (if any)</p><p>Why you chose that career</p><p>Step 3: Prepare a PowerPoint presentation about your chosen career, including the information you gathered in Step 2 as well as your reason for choosing that career.</p><p>Your final submission should be your PowerPoint containing the information in Step 3.</p><p>Review the rubric below to determine how you will be graded.</p><p>s</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Research</p><p>12 points The student provided a career field that interested them, the average salary or range, and the education/certifications required for the career.</p><p>11-4 points The student provided two of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>3-0 points The student provided one or none of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>12</p><p>Reason for Choosing the Career Field</p><p>4 points The student thoughtfully provided the reason that they are interested in this career.</p><p>N/A</p><p>0 points The student did not provide the reason that they are interested in this career.</p><p>4</p><p>Formatting</p><p>4 points The student&#39;s presentation includes no spelling or grammatical errors.</p><p>3-1 points The student&#39;s presentation includes minimal spelling or grammatical errors.</p><p>0 points The student&#39;s presentation includes a significant amount of spelling or grammatical errors.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('581d0feebdc1f26362cff00d78cdc018','career-exploration-m9-l9-module-9-quiz','42c0fc1134f6a4fda8f3d9c437d58e42','Module 9 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Hospitality & Tourism. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('a80b5c9676f5c105708a156d36c573c7','career-exploration-module-10','68d48b60cc4feb626956ed1fd8311e46','Module 10: Human Services',10) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('077fd19e4e79f1dfb57a3fca32fd0f5b','career-exploration-m10-l1-introduction-purpose-and-objectives','a80b5c9676f5c105708a156d36c573c7','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hello and welcome to this module on the Human Services career cluster!</p><p>The Human Services career cluster offers a wide range of fulfilling and rewarding career opportunities. It’s a broad field that encompasses a variety of job possibilities in social work, counseling, public health, education, cosmetology, and more. Each of these industries has its own unique set of rewards.</p><p>For example, social workers are able to help individuals and families in need by connecting them with resources and providing guidance. Counselors provide invaluable support to those struggling with mental health issues, helping them find the best path to recovery. Public health professionals work to educate the public about important health topics and help communities access quality healthcare. Educators have the opportunity to shape the lives and minds of young people, helping them reach their full potential. And cosmetologists help people feel good about their appearance. Plus, there are inner benefits as well. For instance, those in the field often experience a sense of purpose and satisfaction from making a difference in the lives of others. They also gain valuable skills such as problem-solving, communication, and advocacy. Working in Human Services also provides the opportunity to learn about a variety of cultures and experiences and to make meaningful connections with people from different backgrounds. This career cluster offers a wide range of fulfilling and diverse opportunities that will allow you to make a positive impact in your communities and the world.</p><p>To help you learn more about this career cluster, first, we’ll explore the pathways within the cluster. As you may have guessed, the pathway for a cosmetologist is typically different from that of a social worker. Understanding the different pathways will help you find one that is most aligned with your interests.</p><p>We will also talk about the types of places that employ people in this career cluster. As you’ve likely figured out by now, it’s not just the work you DO that matters, but WHERE you do it can also impact how much you enjoy your career.</p><p>Later in the module, you will learn about the skills, abilities, and talents needed in this career cluster. Certain skills enable us to connect with people and figure out the best way to help them lead happier lives, so we want to make sure we are aware of what those skills are.</p><p>All of this and so much more coming up in this module! Let’s get going.</p><p>Module Description</p><p>Welcome to this module on the Human Services career cluster!&#160;In this module, you will discover the various pathways in this cluster and some of the jobs associated with each pathway.</p><p>Objectives</p><p>In this module, students will</p><p>Identify the pathways in the Human Services career cluster and the careers in each pathway.</p><p>Describe the types of places that employ individuals who have careers in the Human Services career cluster.</p><p>Describe the variety of tasks performed by individuals who have careers in the Human Services career cluster.</p><p>List the skills, abilities, and talents needed for careers in the Human Services career cluster.</p><p>Identify the level of training and education required for careers in the Human Services career cluster.</p><p>Research a career in the Human Services career cluster and present findings to the class.</p><p>Apply math, science, and reading skills in the completion of a project or activity related to the Human Services career cluster.</p><p>Polling Question</p><p>Which of the following careers in the Human Services career cluster sounds most interesting to you?</p><p>Social worker/counselor&#160;Cosmetologist&#160;Childcare worker&#160;Homecare assistant&#160;Other</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>A job that helps people with problems in their lives, like getting enough food, finding a safe place to live, and getting counseling to work through difficult times.</p><p>Social work</p><p>Talking to someone who is trained to help you figure out problems and find solutions.</p><p>Credit</p><p>A profession that involves doing hair, makeup, and other beauty treatments to make people look and feel their best.</p><p>Mental health</p><p>How your thoughts, feelings, and behaviors affect your daily life.</p><p>Cosmetology</p><p>A way of borrowing money from a bank or other lender, and then paying it back over time.</p><p>Advocacy</p><p>Speaking up for yourself or someone else to make sure their rights and needs are heard and respected.</p><p>Counseling</p><p>The ability to understand, appreciate, and respect different cultures and the people who belong to them.</p><p>Cultural competence</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>A job that helps people with problems in their lives, like getting enough food, finding a safe place to live, and getting counseling to work through difficult times.</p><p>Answers for question: 1</p><p>Social work</p><p>Counseling</p><p>Cosmetology</p><p>Credit</p><p>Mental health</p><p>Advocacy</p><p>Cultural competence</p><p>2.</p><p>Talking to someone who is trained to help you figure out problems and find solutions.</p><p>Answers for question: 2</p><p>Counseling</p><p>Mental health</p><p>Cultural competence</p><p>Credit</p><p>Social work</p><p>Advocacy</p><p>Cosmetology</p><p>3.</p><p>A profession that involves doing hair, makeup, and other beauty treatments to make people look and feel their best.</p><p>Answers for question: 3</p><p>Credit</p><p>Cultural competence</p><p>Mental health</p><p>Advocacy</p><p>Social work</p><p>Cosmetology</p><p>Counseling</p><p>4.</p><p>How your thoughts, feelings, and behaviors affect your daily life.</p><p>Answers for question: 4</p><p>Mental health</p><p>Credit</p><p>Advocacy</p><p>Cultural competence</p><p>Counseling</p><p>Cosmetology</p><p>Social work</p><p>5.</p><p>A way of borrowing money from a bank or other lender, and then paying it back over time.</p><p>Answers for question: 5</p><p>Credit</p><p>Mental health</p><p>Advocacy</p><p>Counseling</p><p>Cultural competence</p><p>Social work</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0f674475ca26f7bb305f72743d74a7ed','career-exploration-m10-l2-lesson-1','a80b5c9676f5c105708a156d36c573c7','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>What is Human Services Career</h3><p>What is Human Services Career</p><p>What is the Human Services Career Cluster?</p><p>The Human Services career cluster centers on helping people. It includes jobs like social workers, counselors, and nurses who help people manage their physical and mental health. It also includes jobs like therapists and teachers who help people learn new skills or find solutions to problems. Finally, it includes jobs like childcare workers and community organizers who help people build strong relationships and become more involved in their communities. In short, the Human Services career cluster is about helping people in a variety of ways.</p><p>Click through the slideshow to learn more about each pathway:</p><p>In the following slideshow, use your left and right arrow keys to navigate. Press spacebar to reveal the other side of the card.</p><p>Early Childhood Development &amp; Services Pathway: This pathway focuses on helping young children (ages 0-8) learn and grow. People in this pathway might help kids learn basic skills like reading and writing, or help kids cope with emotions and behavior. Jobs in this pathway include childcare worker, preschool teacher, and nanny.</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;5</p><p>Next</p><p>Counseling &amp; Mental Health Services Pathway: This pathway is about helping people who need extra support with their mental health. People in this pathway might help kids and adults with issues such as depression, anxiety, and stress. Professionals in this pathway include psychologists, sociologists, and substance abuse and behavioral disorder counselors.</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;5</p><p>Next</p><p>Family &amp; Community Services Pathway: This pathway is about helping families stay strong and build healthy relationships. People in this pathway might help families with things like parenting skills and conflict resolution. Jobs in this pathway include child life educators, social worker, and marriage/family counselor.</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;5</p><p>Next</p><p>This pathway is about helping people take good care of themselves. People in this pathway might help people with things like meal planning, managing appearances, exercise, and making sure they take their medications correctly. Professions in this pathway include esthetician, cosmetologist, and massage therapist.</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;5</p><p>Next</p><p>Consumer Services Pathway: This pathway is about helping people with their everyday needs. People in this pathway might help people with things like shopping for groceries, budgeting, and using public transportation. Examples of jobs in this pathway include certified financial planner, customer service representative, and credit counselors.</p><p>Previous</p><p>Slide&#160;5&#160;of&#160;5</p><p>Next</p><p>Now that you understand more about these pathways, see if you can match the best pathway for each person:</p><p>Warning: json_decode() expects parameter 1 to be string, object given in&#160;/srv/app/current/blocks/interactive_definitions/controller.php&#160;on line&#160;238</p><p>Pathway</p><p>Jamie loves working with young children and helping them explore the world around them.</p><p>Early Childhood Development &amp; Services Pathway</p><p>Andre enjoys learning about mental health and wants to guide people through their own mental health journey.</p><p>Personal Care Services Pathway</p><p>Suzanne has a soft spot in her heart for children who have been through divorce and wants to help them navigate the transition.</p><p>Consumer Services Pathway</p><p>Jurgen enjoys experimenting with different hairstyles.</p><p>Counseling &amp; Mental Health Services Pathway</p><p>Alex rebuilt his credit after misusing a credit card and now he would like to teach others how to do the same.</p><p>Family &amp; Community Services Pathway</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Jamie loves working with young children and helping them explore the world around them.</p><p>Answers for question: 1</p><p>Family &amp; Community Services Pathway</p><p>Personal Care Services Pathway</p><p>Early Childhood Development &amp; Services Pathway</p><p>Consumer Services Pathway</p><p>Counseling &amp; Mental Health Services Pathway</p><p>2.</p><p>Andre enjoys learning about mental health and wants to guide people through their own mental health journey.</p><p>Answers for question: 2</p><p>Consumer Services Pathway</p><p>Early Childhood Development &amp; Services Pathway</p><p>Counseling &amp; Mental Health Services Pathway</p><p>Family &amp; Community Services Pathway</p><p>Personal Care Services Pathway</p><p>3.</p><p>Suzanne has a soft spot in her heart for children who have been through divorce and wants to help them navigate the transition.</p><p>Answers for question: 3</p><p>Personal Care Services Pathway</p><p>Counseling &amp; Mental Health Services Pathway</p><p>Family &amp; Community Services Pathway</p><p>Early Childhood Development &amp; Services Pathway</p><p>Consumer Services Pathway</p><p>4.</p><p>Jurgen enjoys experimenting with different hairstyles.</p><p>Answers for question: 4</p><p>Early Childhood Development &amp; Services Pathway</p><p>Family &amp; Community Services Pathway</p><p>Consumer Services Pathway</p><p>Personal Care Services Pathway</p><p>Counseling &amp; Mental Health Services Pathway</p><p>5.</p><p>Alex rebuilt his credit after misusing a credit card and now he would like to teach others how to do the same.</p><p>Answers for question: 5</p><p>Counseling &amp; Mental Health Services Pathway</p><p>Personal Care Services Pathway</p><p>Family &amp; Community Services Pathway</p><p>Early Childhood Development &amp; Services Pathway</p><p>Consumer Services Pathway</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('77b857a6b2435a231496fe43d7324d8c','career-exploration-m10-l3-lesson-2','a80b5c9676f5c105708a156d36c573c7','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Where Human Service ppl Work</h3><p>Where Human Service ppl Work</p><p>Where People in the Human Services Career Cluster Work</p><p>People working in the Human Services career cluster can find work in places all over the country and even the world.&#160;Where these people work depends on the career and type of work they are interested in doing.&#160;You can learn about some of the places by clicking on the hotspots below:</p><p>0</p><p>5</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Places of employment in the human services career cluster.</p><p>The hotspot points on the image are as follows:</p><p>Spas/Salons</p><p>Professionals in the human services career cluster are employed in spas and salons to provide services such as haircare, massage therapy, skincare, and other personal care services.</p><p>Nonprofit Organizations</p><p>Professionals in the human services career cluster are employed in nonprofit organizations to provide services such as counseling, advocacy, education, and other community outreach.</p><p>Schools</p><p>Professionals in the human services career cluster are employed in schools to provide students with the necessary support and resources to succeed. This may include early childhood teachers, social workers, and other specialists.</p><p>Government Agencies</p><p>Government agencies employ people in the human services career cluster to assist with providing services for individuals and families. This may include social workers, counselors, educators, and other specialists.</p><p>Nursing Homes/Assisted Living Facilities</p><p>Professionals in the human services career cluster are employed in nursing homes and assisted living facilities to provide services such as physical and mental health care, social activities, and other support services.</p><p>Hospitals</p><p>Hospitals employ people in the human services career cluster to provide medical and mental health services. These professionals may include healthcare social workers, child life specialists, and rehabilitation counselors.</p><p>See if you can match the person’s job the most likely place of employment:</p><p>Place of Employment</p><p>Anna works as a child life specialist, helping children who are in the hospital navigate the challenges of illness, injury, disability, and trauma.</p><p>Nursing Homes/Assisted Living Facility</p><p>Leo is a resident care supervisor who ensures quality and timely delivery of all necessary care and services to residents at the facility.</p><p>School</p><p>Pedro teaches kindergarten.</p><p>Hospital</p><p>Amber is a social worker for The Office of Juvenile Justice.</p><p>Government Agency</p><p>Tia is a marriage and family therapist that works with an organization to provide services to families in distress.</p><p>Nonprofit Organization</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Anna works as a child life specialist, helping children who are in the hospital navigate the challenges of illness, injury, disability, and trauma.</p><p>Answers for question: 1</p><p>Government Agency</p><p>School</p><p>Hospital</p><p>Nonprofit Organization</p><p>Nursing Homes/Assisted Living Facility</p><p>2.</p><p>Leo is a resident care supervisor who ensures quality and timely delivery of all necessary care and services to residents at the facility.</p><p>Answers for question: 2</p><p>Government Agency</p><p>School</p><p>Nursing Homes/Assisted Living Facility</p><p>Nonprofit Organization</p><p>Hospital</p><p>3.</p><p>Pedro teaches kindergarten.</p><p>Answers for question: 3</p><p>Nursing Homes/Assisted Living Facility</p><p>Government Agency</p><p>Nonprofit Organization</p><p>Hospital</p><p>School</p><p>4.</p><p>Amber is a social worker for The Office of Juvenile Justice.</p><p>Answers for question: 4</p><p>Nursing Homes/Assisted Living Facility</p><p>Hospital</p><p>Nonprofit Organization</p><p>School</p><p>Government Agency</p><p>5.</p><p>Tia is a marriage and family therapist that works with an organization to provide services to families in distress.</p><p>Answers for question: 5</p><p>Nonprofit Organization</p><p>Nursing Homes/Assisted Living Facility</p><p>School</p><p>Government Agency</p><p>Hospital</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ee372bae76a5f743207ad1cbe7bbd236','career-exploration-m10-l4-lesson-3','a80b5c9676f5c105708a156d36c573c7','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Activities for Human Service Career</h3><p>Activities for Human Service Career</p><p>Activities in the Human Services Career Cluster</p><p>The Human Services career cluster is all about helping people.&#160;Of course, there are many ways that people need help and there are many ways to give that help.&#160;Click through the list to learn about some of the tasks performed by people in this career cluster:</p><p>Social Work</p><p>Support given by a professionally trained social worker to help people who have problems or need support in their lives.</p><p>Mental Health Counseling</p><p>Mental health counseling from a professional can help people work through difficult emotions or help them find ways to cope with stressful situations.</p><p>Substance Abuse Counseling</p><p>Substance abuse counseling is a type of help for people who may have a problem with drugs or alcohol.</p><p>Case Management</p><p>Case management is about making sure that people who need help get the right kind of help they need to get better. This includes finding the right doctors or services, making sure that people get the right medications, and making sure that people have a plan for their care.</p><p>Credit counseling</p><p>Credit counseling helps people learn how to manage their money better. A credit counselor can help people learn how to budget, save, and make better decisions about their finances.</p><p>Education and Advocacy: Education and advocacy help people understand their rights and get the help they need.</p><p>Family Services: Family services are about helping families stay together and be stronger. This can include finding resources to help families keep their homes, providing counseling for families who are having troubles, and helping families find the help they need.</p><p>Crisis Intervention: Crisis intervention is about helping people who are in a crisis and need immediate help. This can include providing people with food, shelter, and other services to help them get back on their feet.</p><p>Child and Family Therapy: Child and family therapy helps children and families work through their problems together. This can include talking and playing games to help kids learn how to express their feelings and help families learn how to get along better.</p><p>Community Organizing: Focuses on getting people in a community together to work on a project. This can include starting a food pantry, helping people find a place to live, or working to make changes in the community.</p><p>Homeless Services: Homeless services are about helping people who don’t have a home find a place to live. This can include finding shelters for people to stay in, helping people find jobs, and helping people get the help they need.</p><p>Victim Assistance: Help specifically for people who have been hurt or affected by a crime. This can include finding people the right services to help them heal and cope with what happened or helping them get the justice they deserve.</p><p>Health Care Coordination: Health care coordination is about making sure that people who need health care get the right kind of care they need. This can include helping people find doctors, helping them understand their health care options, or making sure that they get the right medications.</p><p>Developmental Disabilities Services: Focuses on helping people with disabilities get the help they need. This can include helping people find the right services, teaching them how to take care of themselves, or helping them find ways to live independently.</p><p>Home Health Care: Ensuring people who are sick or injured get the care they need at home. This can include helping people with their daily activities, giving them medicine, or helping them get the right treatments.</p><p>Disaster Relief and Management: Disaster relief and management is about helping people after a natural disaster like a hurricane or flood. This can include finding people places to stay, giving them food and supplies, or helping them rebuild their homes.</p><p>Refugee and Immigration Services: Refugee and immigration services help people who have been forced to leave their homes find a new place to live. This can include finding them a place to stay, helping them find a job, and helping them learn the language and culture of their new home.</p><p>Employment Assistance: Employment assistance is about helping people find and keep a job. This can include helping people find the right job for them, teaching them how to write a resume, or helping them practice for job interviews.</p><p>Spa treatments: Spa treatments focus on caring for the body while also encouraging relaxation for the mind. This can include getting a massage, getting a facial, or getting a manicure and pedicure to make you feel relaxed and refreshed.</p><p>Teaching: People who need help often need to learn new skills. This means that it is not just teachers who spend their time teaching. Professionals in the human services career cluster help people learn new skills, new ways of thinking, and better ways to engage in certain activities.</p><p>Advocacy</p><p>Advocacy is providing support for people who need it and using your voice and influence to help ensure others&#39; rights are respected.</p><p>Family Services</p><p>Family services are about helping families stay together and be stronger. This can include finding resources to help families keep their homes, providing counseling for families who are having troubles, and helping families find the help they need.</p><p>Crisis Intervention</p><p>Crisis intervention is about helping people who are in a crisis and need immediate help by doing things like making sure they have food, shelter, and necessary services.</p><p>Child and Family Therapy</p><p>Child and family therapy helps children and families work through their problems together. This can include talking and playing games to help kids learn how to express their feelings and help families learn how to get along better.</p><p>Community Organizing</p><p>Focuses on getting people in a community together to work on a project. Examples include starting a food pantry, helping people find a place to live, or working to make changes in the community.</p><p>Homeless Services:</p><p>Homeless services are about helping people who don’t have a home find a place to live. This can include finding shelters for people to stay in, helping people find jobs, and helping people get the help they need.</p><p>Victim Assistance<<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('2c8114c872b587e479473c11dc7b3100','career-exploration-m10-l5-lesson-4','a80b5c9676f5c105708a156d36c573c7','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Skills Needed for Human Service Career</h3><p>Skills Needed for Human Service Career</p><p>Skills, Abilities, and Talents Needed for a Career in Human Services</p><p>One of the key components to having a successful career in the Human Services career cluster is the desire to help people.&#160;Wanting to see people feel better and live happier lives is a crucial part of finding the motivation to make this a successful career path.&#160;However, in addition to this desire to help others, there are some critical skills, abilities, and talents that are also particularly important to this career cluster.&#160;Click on the tabs to learn more about each one:</p><p>Communication Skills</p><p>The ability to effectively and accurately communicate verbally and in writing is essential in the Human Services field.&#160;This includes being able to communicate with a wide variety of people from different backgrounds, as well as being able to express yourself clearly.</p><p>Problem-Solving Skills</p><p>Human Services professionals must be able to assess situations and determine the best solution. Problem-solving requires analytical thinking and the ability to evaluate available resources.</p><p>Interpersonal Skills</p><p>Working with people requires strong interpersonal skills. The ability to build relationships, listen actively, and demonstrate empathy are all essential for a successful career in Human Services.</p><p>Organizational Skills</p><p>Human Services professionals must be able to keep track of multiple tasks and projects at the same time. This requires strong organizational skills, such as time management, prioritization, and multitasking.</p><p>Leadership Skills</p><p>The ability to lead and motivate others is critical in the Human Services field. Leadership skills include the ability to delegate tasks, build consensus, and manage conflict.</p><p>Cultural Competency</p><p>Human Services professionals must be able to understand and respect different cultures and worldviews. This includes being aware of biases and stereotypes and being able to work with diverse populations.</p><p>Conflict Resolution Skills</p><p>Human Services professionals must be able to identify the root of conflicts and develop strategies to resolve them. This includes being able to mediate disputes and help clients develop effective problem-solving skills.</p><p>Adaptability</p><p>The Human Services field is constantly evolving, and professionals must be able to adjust to changing policies, procedures, and client needs in order to provide effective services.</p><p>Self-Care</p><p>Human Services professionals must be able to take care of themselves both physically and emotionally in order to provide the best services to clients. This includes getting enough rest, engaging in self-care activities, and maintaining healthy relationships.</p><p>Professionalism</p><p>Professionalism is essential for Human Services professionals. This includes maintaining ethical standards, following regulations and laws, and adhering to the organization’s policies and procedures.</p><p>Next Tab</p><p>You can begin to develop these skills, abilities, and talents right now!&#160;See if you can match the activity to the correct skill, ability, or talent it will develop:</p><p>Activity</p><p>Skill, Talent, or Ability</p><p>Participate in group discussions.</p><p>Conflict resolution</p><p>Play strategy board games.</p><p>Organizational skills</p><p>Participate in group activities.</p><p>Interpersonal skills</p><p>Use a planner to keep track of assignments and due dates.</p><p>Problem-Solving</p><p>Take the initiative on a project or team.</p><p>Cultural competency</p><p>Take the initiative on a project or team.</p><p>Adaptability</p><p>Listen to other perspectives.</p><p>Communication skills</p><p>Try new activities.</p><p>Leadership skills</p><p>Get enough sleep.</p><p>Self-Care</p><p>Take responsibility for your actions.</p><p>Professionalism</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Participate in group discussions.</p><p>Answers for question: 1</p><p>Communication skills</p><p>Conflict resolution</p><p>Organizational skills</p><p>Leadership skills</p><p>Adaptability</p><p>Self-Care</p><p>Cultural competency</p><p>Problem-Solving</p><p>Professionalism</p><p>Interpersonal skills</p><p>2.</p><p>Play strategy board games.</p><p>Answers for question: 2</p><p>Leadership skills</p><p>Communication skills</p><p>Adaptability</p><p>Cultural competency</p><p>Problem-Solving</p><p>Self-Care</p><p>Professionalism</p><p>Organizational skills</p><p>Interpersonal skills</p><p>Conflict resolution</p><p>3.</p><p>Participate in group activities.</p><p>Answers for question: 3</p><p>Conflict resolution</p><p>Organizational skills</p><p>Self-Care</p><p>Leadership skills</p><p>Communication skills</p><p>Problem-Solving</p><p>Professionalism</p><p>Cultural competency</p><p>Adaptability</p><p>Interpersonal skills</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('437e4d35cccdb1023339a2a04c28ffb9','career-exploration-m10-l6-lesson-5','a80b5c9676f5c105708a156d36c573c7','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Education &amp; Training for Human Service</h3><p>Education &amp; Training for Human Service</p><p>Education and Training in the Human Services Career Cluster:</p><p>Because there are so many jobs in the Human Services career cluster, there are many educational and training requirements as well.&#160;Let’s look at a few different jobs in the cluster and what training/education they require:</p><p>Social Worker</p><p>A social worker typically needs a Bachelor&#39;s degree in Social Work (BSW) and may need to be licensed, depending on the state they practice in. Many employers require a Master&#39;s of Social Work (MSW) or a Doctorate in Social Work (DSW) as well.</p><p>Counselor</p><p>A counselor typically needs a Master&#39;s degree in Counseling such as a Master&#39;s of Science in Counseling (MSC), Master&#39;s of Education in Counseling (MEd), or Master&#39;s of Science in Marriage and Family Therapy (MSMFT). Depending on the state, counselors may need to be licensed.</p><p>Child Life Specialist</p><p>A Child Life Specialist typically needs a Bachelor&#39;s degree in Child Life and must be certified by the Child Life Council.</p><p>Early Childhood Education Teacher</p><p>An Early Childhood Education Teacher typically needs a Bachelor&#39;s degree in Early Childhood Education or a related field. Some states may also require a teaching license.</p><p>Nanny</p><p>A nanny typically does not need any formal education or training but may need to be certified in CPR, first aid, and other child safety courses.</p><p>Cosmetologist</p><p>A cosmetologist typically needs to complete a cosmetology program at a state-licensed school and pass the state licensing exam.</p><p>Esthetician</p><p>An esthetician typically needs to complete an esthetician program at a state-licensed school and pass the state licensing exam.</p><p>Marriage and Family Therapist</p><p>A Marriage and Family Therapist typically needs a Master&#39;s degree in Marriage and Family Therapy or a related field. They must also be licensed in the state they practice in.</p><p>Case Manager</p><p>A Case Manager typically needs a Bachelor&#39;s degree in social work, psychology, or a related field, and may need to be licensed, depending on the state.</p><p>Human Service Assistant</p><p>A Human Service Assistant typically needs a high school diploma or GED and may need to have some form of certification in the field they are working in.</p><p>While you may not be able to apply for many of the jobs in this career cluster in the near future, you can start taking classes and participating in activities that will increase your knowledge in this field.&#160;Here are some ideas (click through the slideshow to learn more):</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Take classes in psychology, sociology, and social work.</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;4</p><p>Next</p><p>Volunteer at local nonprofits and organizations in the human services field such as schools, hospitals, and shelters.</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;4</p><p>Next</p><p>Participate in job shadowing opportunities to gain insight into the human services career cluster.</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;4</p><p>Next</p><p>Join clubs that encourage collaboration across various cultures and lifestyles such as the multicultural club or language clubs.</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;4</p><p>Next</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b276f3fb9035110bdf5b880f38f79e7e','career-exploration-m10-l7-module-10-summary','a80b5c9676f5c105708a156d36c573c7','Module 10 Summary','text',12,'<h2>Module 10 Summary</h2><section><h3>Module 10 Summary</h3><p>Module 10 Summary</p><p>Great Work!&#160;You have successfully completed this module on the Human Services career cluster.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified the pathways in the Human Services career cluster and the careers in each pathway.</p><p>Described the types of places that employ individuals who have careers in the Human Services career cluster.</p><p>Described the variety of tasks performed by individuals who have careers in the Human Services career cluster.</p><p>Listed the skills, abilities, and talents needed for careers in the Human Services career cluster.</p><p>Identified the level of training and education required for careers in the Human Services career cluster.</p><p>Researched a career in the Human Services career cluster and present findings to the class.</p><p>Applied math, science, and reading skills in the completion of a project or activity related to the Human Services career cluster.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('221bafe6251225d3612b719d9080cbc3','career-exploration-m10-l8-module-10-project','a80b5c9676f5c105708a156d36c573c7','Module 10 Project','text',12,'<h2>Module 10 Project</h2><section><h3>Module 10 Project</h3><p>Module 10 Project</p><p>Career Exploration</p><p>Human Services - Project</p><p>For this project, you will choose from two options.&#160; You only need to complete one of these options.&#160; Please find both options and their rubrics below.</p><p>Option 1</p><p>For this project, you will interview someone in the Human Services career cluster. Follow the steps below to complete the project:</p><p>Make a list of potential people to ask. Include their name, job title, and how you know them. Identify 3 or more people.</p><p>Ask the person whose career seems most interesting to you if they would be willing to do a short interview. If they are unable, ask the next person, and so on.</p><p>Make a list of 5 questions to ask. This can include questions about their background/training, what they enjoy, what they don&#39;t enjoy, when and how they decided on their career, etc.</p><p>Conduct the interview and write down/record the answers.</p><p>Your final submission should include your original list of people as well as the 5 questions and answers from the interview.</p><p>Review the rubric below to see how you will be graded.</p><p>Option 1 Rubric: Human Services Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>List</p><p>5 points The submission includes a list of 3 or more people all in the human services cluster and includes their name, profession/title, and the student&#39;s connection.</p><p>The submission includes a list of 2 people all in the human services cluster and includes their name, profession/title, and the student&#39;s connection.</p><p>0-3 points The submission includes fewer than 2 people all in the human services cluster and includes their name, profession/title, and the student&#39;s connection.</p><p>5</p><p>Interview</p><p>12-15 points The interview includes 5 or more applicable questions as well as the interviewer&#39;s response. The write-up of the interview is coherent and provides enough personal information to indicate the interview took place.</p><p>8-11 points The interview includes 5 or more applicable questions as well as the interviewer&#39;s response. The write-up of the interview is mostly coherent and provides some personal information to indicate the interview took place.</p><p>0-7 points The interview does not include 5 or more applicable questions as well as the interviewer&#39;s response. The write-up of the interview is not coherent and/or does not provide some personal information to indicate the interview took place.</p><p>15</p><p>Total Points:&#160;20</p><p>Option 2</p><p>For this option, you will research a particular career that interests you in this cluster. Complete the following steps for your project:</p><p>Step 1: Research your chosen career.</p><p>Step 2: List the following</p><p>Average Salary/Salary Range</p><p>Education Requirements</p><p>Certification Requirements (if any)</p><p>Why you chose that career</p><p>Step 3: Prepare a PowerPoint presentation about your chosen career, including the information you gathered in Step 2 as well as your reason for choosing that career.</p><p>Your final submission should be your PowerPoint containing the information in Step 3.</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 2 Rubric: Human Services Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Research</p><p>12 points The student provided a career field that interested them, the average salary or range, and the education/certifications required for the career.</p><p>11-4 points The student provided two of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>3-0 points The student provided one or none of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>12</p><p>Reason for Choosing the Career Field</p><p>4 points The student thoughtfully provided the reason that they are interested in this career.</p><p>N/A</p><p>0 points The student did not provide the reason that they are interested in this career.</p><p>4</p><p>Formatting</p><p>4 points The student&#39;s presentation includes no spelling or grammatical errors.</p><p>3-1 points The student&#39;s presentation includes minimal spelling or grammatical errors.</p><p>0 points The student&#39;s presentation includes a significant amount of spelling or grammatical errors.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('278f7d5f34fa557e60307c501f5a2c06','career-exploration-m10-l9-module-10-quiz','a80b5c9676f5c105708a156d36c573c7','Module 10 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Human Services. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('db6cf1d82fd533e2e07a4290379fb8dc','career-exploration-module-11','68d48b60cc4feb626956ed1fd8311e46','Module 11: Information Technology',11) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8b5a0e1c978bf9e20943313bd4470e0b','career-exploration-m11-l1-introduction-purpose-and-objectives','db6cf1d82fd533e2e07a4290379fb8dc','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hello and welcome to this module on the Information Technology career cluster!</p><p>Information Technology (or IT for short) is a growing field that offers a wide range of exciting career opportunities. IT professionals are responsible for developing and protecting the technology systems that run our society. These systems, like computers and phones, the Internet, blockchains, financial networks, are all super complex, so smart and driven people are needed to create and run them. As a result, IT professionals are in high demand and are often well-compensated for their services (meaning they bring home a nice paycheck!).</p><p>A career in IT gives you the opportunity to create something new and innovative. You can make a lasting impact in the technology world. What&#39;s more, IT professionals are always learning and developing their skills, which makes them even more valuable. Technology changes and evolves fast, and so do IT professionals.</p><p>In this career field, you have the opportunity to work with a variety of people and businesses. You could work for a small company, a big company, a healthcare organization, or even start your own business offering your services.</p><p>Finally, a career in IT offers a wide range of job options, from web development to software engineering to network engineering. Unlike some jobs where it can be hard to earn more money, even with experience, a career in IT also provides the opportunity for quick career advancement, which can lead to even higher salaries and more job security.</p><p>In this module, we’ll look at various pathways in IT, and also learn about the tasks performed by professionals in the career cluster. Finally, how do you get to the point where you get paid the big bucks for the tasks we’ll talk about? We will look at the education you need to be the strongest job candidate possible.</p><p>If you’re ready, let’s explore the IT career cluster!</p><p>Module Description</p><p>Welcome to this module on the Information Technology career cluster!&#160;In this module, you will discover the various pathways in this cluster and some of the jobs associated with each pathway.&#160;Next, we will discuss the types of places that employ individuals in this field.&#160;IT is a growing field, which means there are a lot of organizations that hire IT professionals!&#160;The module will explain the different tasks that someone in this career cluster may perform on a regular basis.&#160;You will also learn about the skills, abilities, and talents needed for careers.&#160;We will also discuss the different requirements in training and education for some of the common jobs in this career cluster.&#160;The module will conclude with a project designed to help you explore the Information Technology career cluster in more depth.</p><p>Objectives</p><p>In this module, students will</p><p>Identify the pathways in the Information Technology career cluster and the careers in each pathway.</p><p>Describe the types of places that employ individuals who have careers in the Information Technology career cluster.</p><p>Describe the variety of tasks performed by individuals who have careers in the Information Technology career cluster.</p><p>List the skills, abilities, and talents needed for careers in the Information Technology career cluster.</p><p>Identify the level of training and education required for careers in the Information Technology career cluster.</p><p>Research a career in the Information Technology career cluster and present findings to the class.</p><p>Apply math, science, and reading skills in the completion of a project or activity related to the Information Technology career cluster.</p><p>Polling Question</p><p>Which career in the Information Technology career cluster sounds most interesting to you?</p><p>Network administrator&#160;Game developer&#160;PC support specialist&#160;Programmer&#160;Other</p><p>Results:</p><p>Network administrator&#160;100%</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Instructions written in a programming language that a computer can understand.</p><p>Programming language</p><p>A special language used by computers to understand instructions.</p><p>Cybersecurity</p><p>A field of study that involves using computers to store, organize, and process information.</p><p>Network</p><p>A computer that is used by one person, like a laptop.</p><p>Code</p><p>A collection of computers and devices that are connected together, allowing them to share information.</p><p>Personal computer (PC)</p><p>Protecting computers and networks from hackers and other malicious attacks.</p><p>Information Technology (IT)</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Instructions written in a programming language that a computer can understand.</p><p>Answers for question: 1</p><p>Programming language</p><p>Cybersecurity</p><p>Information Technology (IT)</p><p>Code</p><p>Personal computer (PC)</p><p>Network</p><p>2.</p><p>A special language used by computers to understand instructions.</p><p>Answers for question: 2</p><p>Information Technology (IT)</p><p>Personal computer (PC)</p><p>Cybersecurity</p><p>Code</p><p>Programming language</p><p>Network</p><p>3.</p><p>A field of study that involves using computers to store, organize, and process information.</p><p>Answers for question: 3</p><p>Information Technology (IT)</p><p>Network</p><p>Cybersecurity</p><p>Code</p><p>Personal computer (PC)</p><p>Programming language</p><p>4.</p><p>A computer that is used by one person, like a laptop.</p><p>Answers for question: 4</p><p>Personal computer (PC)</p><p>Cybersecurity</p><p>Programming language</p><p>Network</p><p>Code</p><p>Information Technology (IT)</p><p>5.</p><p>A collection of computers and devices that are connected together, allowing them to share information.</p><p>Answers for question: 5</p><p>Information Technology (IT)</p><p>Cybersecurity</p><p>Personal computer (PC)</p><p>Network</p><p>Programming language</p><p>Code</p><p>6.</p><p>Protecting computers and networks from hackers and other malicious attacks.</p><p>Answers for question: 6</p><p>Cybersecurity</p><p>Information Technology (IT)</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3ea558a7438013905246b663e39bac43','career-exploration-m11-l2-lesson-1','db6cf1d82fd533e2e07a4290379fb8dc','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>What is Information Technology Career</h3><p>What is Information Technology Career</p><p>What is the Information Technology Career Cluster?</p><p>The Information Technology career cluster is a group of jobs that all involve working with computers and technology.&#160;People who are part of this cluster might work with programming (writing code), designing websites, or helping people with computer problems.&#160;These jobs are important for helping businesses and organizations use technology to do their work.&#160;Nearly every industry uses technology to help them share and complete their work, so this is an important career cluster for our digital society.</p><p>Click on the image below to learn about the four pathways in this career cluster:</p><p>5</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Pathways in the IT career field</p><p>The hotspot points on the image are as follows:</p><p>Information Support &amp; Services Pathway</p><p>This pathway is about understanding how to use and support computers, software, and other technology. This includes things like troubleshooting problems with computers, answering questions about how to use technology, and helping people find the right technology for their needs. Jobs in this pathway include PC support specialists, help desk specialists, and database analysts.</p><p>Web &amp; Digital Communications Pathway</p><p>This pathway is about understanding how to create websites and use digital media. This includes learning how to design websites, create videos, and post content on social media. Professionals working in this pathway include 3D animators, web developers, and multi-media artists.</p><p>Network Systems Pathway</p><p>This pathway is about learning how to create and maintain networks so that people can connect to the internet and share information. This might involve setting up Wi-Fi networks, connecting computers together, and helping people use the internet. Professionals working in this pathway include network engineers, systems administrators, and network technicians.</p><p>Programming &amp; Software Development Pathway</p><p>This pathway is about understanding how to create software and apps. This includes learning how to write code, create software programs, and design apps. Jobs in this pathway include applications engineer, programmer, and game developer.</p><p>Now that you’ve learned about the pathways, see if you can match the job to the correct pathway.&#160; Drag the card to the correct pathway:</p><p>If you are using a keyboard to navigate, you must use the following alternative activity to receive credit.</p><p>Network Systems Pathway</p><p>Information Support &amp; Services Pathway</p><p>Web &amp; Digital Communications Pathway</p><p>Programming &amp; Software Development Pathway</p><p>Alternative Activity</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('91f71eb1fb3e04373333a513701c9696','career-exploration-m11-l3-lesson-2','db6cf1d82fd533e2e07a4290379fb8dc','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Where Information Technology ppl Work</h3><p>Where Information Technology ppl Work</p><p>Where People in the Information Technology Career Cluster Work</p><p>As we’ve mentioned before, nearly all businesses and organizations utilize technology in some form.&#160;That means there are many places where people in the Information Technology career cluster may work.&#160;Some of those places are listed below.&#160;Click to learn more:</p><p>Software Development Companies</p><p>These companies develop software products and services, and they employ software engineers, web developers, and other IT professionals to develop, test, and maintain software.</p><p>Technology Consulting Firms</p><p>These firms provide IT advice and assistance to businesses and organizations. They employ IT consultants, systems analysts, network engineers, and other IT professionals to help clients with their IT needs.</p><p>IT Departments</p><p>Some large businesses and organizations have their own IT departments that employ IT professionals to maintain and upgrade their computer systems and networks.</p><p>Government Agencies</p><p>Many government agencies employ IT professionals to develop, maintain, and protect their computer systems and networks.</p><p>Educational Institutions</p><p>Many educational institutions employ IT professionals to develop and maintain their computer systems and networks.</p><p>Telecommunications Companies</p><p>Telecommunications companies employ IT professionals to develop, maintain, and upgrade their networks and systems.</p><p>Healthcare Organizations</p><p>Many healthcare organizations employ IT professionals to develop, maintain, and upgrade their computer systems and networks.</p><p>Banks and Financial Institutions</p><p>Banks and other financial institutions employ IT professionals to develop and maintain their computer systems and networks.</p><p>See if you can match the description to the most likely place of employment.</p><p>Place of Employment</p><p>Andrea ensures that patient information is securely stored.</p><p>Healthcare Organization</p><p>Arman helps customers access their checking and savings accounts.</p><p>Telecommunications Company</p><p>Stewart helps people who just signed up for a cell phone plan.</p><p>Government Agency</p><p>Landry is responsible for ensuring students can signup online for classes next semester.</p><p>IT Department</p><p>Cameron is working on developing new software the company can sell to healthcare systems.</p><p>Bank or Financial Institution</p><p>Carlos designs and maintains the city&#39;s websites.</p><p>Educational Institution</p><p>Theo works for a large company and helps troubleshoot tech problems experienced by employees.</p><p>Software Development Company</p><p>Maria travels to different companies to help with their technology systems and provide guidance on new systems that may help the organization.</p><p>Technology Consulting Firm</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Andrea ensures that patient information is securely stored.</p><p>Answers for question: 1</p><p>Telecommunications Company</p><p>Educational Institution</p><p>IT Department</p><p>Healthcare Organization</p><p>Software Development Company</p><p>Technology Consulting Firm</p><p>Government Agency</p><p>Bank or Financial Institution</p><p>2.</p><p>Arman helps customers access their checking and savings accounts.</p><p>Answers for question: 2</p><p>IT Department</p><p>Bank or Financial Institution</p><p>Technology Consulting Firm</p><p>Government Agency</p><p>Telecommunications Company</p><p>Educational Institution</p><p>Software Development Company</p><p>Healthcare Organization</p><p>3.</p><p>Stewart helps people who just signed up for a cell phone plan.</p><p>Answers for question: 3</p><p>Telecommunications Company</p><p>Educational Institution</p><p>Technology Consulting Firm</p><p>Healthcare Organization</p><p>IT Department</p><p>Government Agency</p><p>Bank or Financial Institution</p><p>Software Development Company</p><p>4.</p><p>Landry is responsible for ensuring students can signup online for classes next semester.</p><p>Answers for question: 4</p><p>IT Department</p><p>Technology Consulting Firm</p><p>Government Agency</p><p>Telecommunications Company</p><p>Educational Institution</p><p>Healthcare Organization</p><p>Bank or Financial Institution</p><p>Software Development Company</p><p>5.</p><p>Cameron is working on developing new software the company can sell to healthcare systems.</p><p>Answers for question: 5</p><p>Technology Consulting Firm</p><p>Educational Institution</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('61dac69e140ded40b11d4cd0f0159be2','career-exploration-m11-l4-lesson-3','db6cf1d82fd533e2e07a4290379fb8dc','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Activities for Information Technology Career</h3><p>Activities for Information Technology Career</p><p>Activities in the Information Technology Career Cluster</p><p>People in the IT career cluster spend a significant amount of time at a computer.&#160;However, what they do at the computer depends on their job.&#160;Let’s explore some of the common tasks associated with this career cluster.&#160;Click on the tabs to learn more:</p><p>Troubleshooting technical problems</p><p>Trying to figure out why something isn&#39;t working the way it should and fixing it.</p><p>Installing and maintaining technology</p><p>Setting up a computer, system, or device and making sure all the pieces are working correctly and keeping it working properly.</p><p>Cybersecurity</p><p>Making sure that the computer and its information are safe from people who might try to access it without permission.</p><p>Developing and maintaining websites</p><p>Creating and taking care of websites so that they look good and work properly.</p><p>Data backup and recovery</p><p>Saving copies of important information so it can be accessed if something bad happens to the original.</p><p>Designing and implementing databases</p><p>Setting up a way to store lots of data in an organized way.</p><p>Writing and testing code</p><p>Writing commands that tell a computer what to do and making sure they all work the way they should.</p><p>Providing technical support</p><p>Helping people figure out how to use technology and helping them fix any problems they are having.</p><p>Researching new technologies</p><p>Learning about new tools and products that can help people use technology better and more efficiently.</p><p>Developing and implementing IT policies</p><p>Creating rules for how technology should be used and making sure everyone follows them.</p><p>Next Tab</p><p>As you can see, there are many tasks that go into making sure the technology we use works smoothly.&#160;Because of IT professionals, we can quickly and easily access information, share data, and connect with other people.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('34366f2492d33a2a15da3dede0054ec0','career-exploration-m11-l5-lesson-4','db6cf1d82fd533e2e07a4290379fb8dc','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Skills Need for Information Technology</h3><p>Skills Need for Information Technology</p><p>Skills, Abilities, and Talents Needed for a Career in Information Technology</p><p>Just like any other career, the Information Technology career cluster requires certain skills, abilities, and talents in order to be successful.&#160;Click to learn about each one:</p><p>Technical Knowledge</p><p>A successful career in the information technology field requires a strong understanding of the systems, tools, and procedures used in this sector. This includes a thorough knowledge of coding languages, hardware, software, and network systems.</p><p>Problem-Solving</p><p>IT professionals must be able to identify problems and develop solutions. They should have the ability to think critically and solve technical issues quickly and efficiently.</p><p>Communication Skills</p><p>Successful IT professionals must be able to effectively communicate technical information to colleagues, clients, and management. They should also be able to explain complex concepts in simple terms.</p><p>Leadership</p><p>In order to be successful in the information technology field, IT professionals must be able to manage teams and projects. They should have the ability to motivate and lead others, as well as the ability to delegate tasks and set deadlines.</p><p>Creativity</p><p>IT professionals must be able to come up with new ideas and solutions to problems. They should also be able to think outside the box and come up with innovative solutions to challenges.</p><p>You can start developing these skills right now!&#160;Click through the slideshow to learn how to prepare for a career in this cluster.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Take classes in computer science, programming, and coding.</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;5</p><p>Next</p><p>oin an IT club or program at your school.</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;5</p><p>Next</p><p>Participate in coding competitions and hackathons.</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;5</p><p>Next</p><p>Read books, blogs, and articles related to technology and IT.</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;5</p><p>Next</p><p>Develop a portfolio of projects to showcase your skills.</p><p>Previous</p><p>Slide&#160;5&#160;of&#160;5</p><p>Next</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('67a5b1c9cf30dd06462c79c21dfb32cf','career-exploration-m11-l6-lesson-5','db6cf1d82fd533e2e07a4290379fb8dc','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Education &amp; Training for IT Career</h3><p>Education &amp; Training for IT Career</p><p>Shutter Stock</p><p>License:&#160;All Rights Reserved</p><p>Education and Training in the Information Technology Career Cluster:</p><p>The Information Technology career cluster requires a wide variety of education and training depending on the specific role.&#160;Generally, a career in this field will require a combination of higher education, such as a bachelor’s degree in computer science, as well as ongoing training and certifications.At the bachelor’s level, many Information Technology roles require a degree in computer science, information systems, software engineering, data analytics, or a related field.&#160;Additionally, some employers may prefer candidates who have taken classes in different programming languages, such as C++ and Java.In addition to higher education, many Information Technology professionals need to complete continuing education and certifications.&#160;Obtaining certifications can help keep professionals up to date with the latest certifications, and can help workers stay competitive in the job market.</p><p>Click through the tabs to learn about some of the typical requirements for some of the most common jobs in the industry:</p><p>Software Developer</p><p>Most software developers have a bachelor&#39;s degree in computer science, software engineering, or a related field.&#160;They must have strong programming and problem-solving skills, and know multiple programming languages.</p><p>Computer Systems Analyst</p><p>Computer systems analysts typically have a bachelor&#39;s degree in a field such as computer science, information systems, or management information systems. They may also have experience in the industry they are analyzing, and need to be able to solve complex problems, analyze data, and communicate effectively.</p><p>Computer Programmer</p><p>Most computer programmers have a bachelor&#39;s degree in computer science, software engineering, or a related field. They should know multiple programming languages and have strong problem-solving skills.</p><p>Network and Computer Systems Admin</p><p>Network and computer systems administrators typically have a bachelor&#39;s degree in computer science, information systems, or a related field. They need to have strong problem-solving and communication skills and be knowledgeable about network and computer systems.</p><p>Web Developer</p><p>Web developers typically have a bachelor&#39;s degree in computer science, software engineering, or a related field. They should have strong problem-solving skills, be proficient in multiple programming languages, and understand web development concepts such as HTML, CSS, and JavaScript.</p><p>Information Security Analyst</p><p>Information security analysts typically have a bachelor&#39;s degree in computer science, information systems, or a related field. They should have strong problem-solving and communication skills, and be knowledgeable about network security, computer security, and cryptography.</p><p>Computer Support Specialist</p><p>Computer support specialists typically have a bachelor&#39;s degree in computer science, information systems, or a related field. They should have strong problem-solving and communication skills, and be knowledgeable about computer hardware, software, and networks.</p><p>Computer &amp; Info Research Scientist</p><p>Computer and information research scientists typically have a doctoral degree in computer science, information systems, or a related field. They should have strong problem-solving and communication skills, and be knowledgeable about computer science, mathematics, and statistics.</p><p>Next Tab</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('214b897b33815328093b00f9c7e85ec5','career-exploration-m11-l7-module-11-summary','db6cf1d82fd533e2e07a4290379fb8dc','Module 11 Summary','text',12,'<h2>Module 11 Summary</h2><section><h3>Module 11 Summary</h3><p>Module 11 Summary</p><p>Great Work!&#160;You have successfully completed this module on the Information Technology career cluster.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified the pathways in the Information Technology career cluster and the careers in each pathway.</p><p>Described the types of places that employ individuals who have careers in the Information Technology career cluster.</p><p>Described the variety of tasks performed by individuals who have careers in the Information Technology career cluster.</p><p>Listed the skills, abilities, and talents needed for careers in the Information Technology career cluster.</p><p>Identified the level of training and education required for careers in the Information Technology career cluster.</p><p>Researched a career in the Information Technology career cluster and presented findings to the class.</p><p>Applied math, science, and reading skills in the completion of a project or activity related to the Information Technology career cluster.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e6a65c89dc8376de87ffe0c7d17fdc96','career-exploration-m11-l8-module-11-project','db6cf1d82fd533e2e07a4290379fb8dc','Module 11 Project','text',12,'<h2>Module 11 Project</h2><section><h3>Module 11 Project</h3><p>Module 11 Project</p><p>Career Exploration</p><p>Information Technology - Project</p><p>For this project, you will choose from two options.&#160; You only need to complete one of these options.&#160; Please find both options and their rubrics below.</p><p>Option 1</p><p>For this project, you will create a guide on how to create a Gmail account. Your guide can be a video tutorial, presentation, or written guide. Whatever method you choose, your guide should include the following:</p><p>A brief overview of what Gmail is, imagining the person this is for is unfamiliar with it.</p><p>Step-by-step instructions, starting from opening an internet browser and concluding with instructions on how to send their first email.</p><p>Multiple forms of instruction. For example, if you are doing a video tutorial, it should also include narration. If you are doing a written guide, it should also include images.</p><p>*Note: Be careful not to share sensitive information such as passwords!</p><p>Review the rubric to see how you will be graded.</p><p>Option 1 Rubric: Information Technology Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Gmail Overview</p><p>4 points The guide includes an excellent overview of Gmail.</p><p>3 points The guide includes an adequate overview of Gmail.</p><p>0-2 points An overview of Gmail is missing and/or inadequate/inaccurate</p><p>4</p><p>Multiple Forms of Instruction</p><p>7-8 points The instruction includes multiple forms of instruction such as video + narration or written instructions + applicable images to create a thorough guide.</p><p>5-6 points The instruction includes multiple forms of instruction such as video + narration or written instructions + applicable images but may be lacking in some parts.</p><p>0-4 points The instruction does not include multiple forms of instruction.</p><p>8</p><p>Step-by-Step Instruction</p><p>7-8 points The instruction thoroughly covers the process from opening the browser to sending the first email.</p><p>5-6 points The instruction adequately covers the process from opening the browser to sending the first email.</p><p>0-4 points The step-by-step instruction is significantly insufficient.</p><p>8</p><p>Total Points:&#160;20</p><p>Option 2</p><p>For this option, you will research a particular career that interests you in this cluster. Complete the following steps for your project:</p><p>Step 1: Research your chosen career.</p><p>Step 2: List the following</p><p>Average Salary/Salary Range</p><p>Education Requirements</p><p>Certification Requirements (if any)</p><p>Why you chose that career</p><p>Step 3: Prepare a PowerPoint presentation about your chosen career, including the information you gathered in Step 2 as well as your reason for choosing that career.</p><p>Your final submission should be your PowerPoint containing the information in Step 3.</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 2 Rubric: Information Technology Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Research</p><p>12 points The student provided a career field that interested them, the average salary or range, and the education/certifications required for the career.</p><p>11-4 points The student provided two of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>3-0 points The student provided one or none of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>12</p><p>Reason for Choosing the Career Field</p><p>4 points The student thoughtfully provided the reason that they are interested in this career.</p><p>N/A</p><p>0 points The student did not provide the reason that they are interested in this career.</p><p>4</p><p>Formatting</p><p>4 points The student&#39;s presentation includes no spelling or grammatical errors.</p><p>3-1 points The student&#39;s presentation includes minimal spelling or grammatical errors.</p><p>0 points The student&#39;s presentation includes a significant amount of spelling or grammatical errors.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5200bfddf758c96aadd4c3bb5b379bb4','career-exploration-m11-l9-module-11-quiz','db6cf1d82fd533e2e07a4290379fb8dc','Module 11 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Information Technology. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('831cb8533365c3ef13381bd1dd6d1ec7','career-exploration-module-12','68d48b60cc4feb626956ed1fd8311e46','Module 12: Law, Public Safet, Security',12) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('ceb14b22f545b52f8dd11a1f519ec116','career-exploration-m12-l1-introduction-purpose-and-objectives','831cb8533365c3ef13381bd1dd6d1ec7','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Welcome to this module on the Law, Public Safety &amp; Security career cluster.</p><p>This cluster offers many rewarding career paths that can be both fulfilling and exciting. Here are just a few reasons why you should be interested in the Law, Public Safety and Security career cluster:</p><p>First off, the Law, Public Safety and Security career cluster offers a wide variety of career options. From local law enforcement to legal services to homeland security and more, you can find a career that matches your interests and skills. This means that you will never be bored with your job, nor will you be limited in the number of job opportunities available to you.</p><p>Second, this career cluster is important and valued. People appreciate firefighters, police officers, and security personnel how help keep our communities safe. This career cluster is a great way to make a positive contribution to your local community.</p><p>Third, the Law, Public Safety and Security career cluster offers excellent job security. With the right training and credentials, you can be sure that you will have a job for many years to come. In addition, the salaries for jobs in this field are typically very competitive, so if finding a job that helps others and pays well is important to you, this may be a field to consider.</p><p>Fourth and finally, the Law, Public Safety and Security career cluster is an exciting and rewarding field to be in. You will get to work with people from all walks of life, and you will be able to help ensure the safety and security of your community. This is a great way to make a difference in the world and to make a positive impact on the lives of others.</p><p>But just what does a career in this cluster look like? We’ll explore that in this module by discussing the various pathways and corresponding jobs, the places of employment, and some of the tasks people in this cluster may perform. We’ll finish the module by learning about the training you need to find the right opportunities, as well as the skills, talents, and abilities that will help you succeed in this cluster.</p><p>If you’re ready to learn more, let’s dive in!</p><p>Module Description</p><p>Welcome to this module on the Law, Public Safety &amp; Security career cluster!&#160;In this module, you will discover the various pathways in this cluster and some of the jobs associated with each pathway.&#160;Next, we will discuss the types of places that employ individuals in this field.&#160;The module will explain the different tasks that someone in this career cluster may perform on a regular basis, such as investigating crimes, responding to emergencies, and preparing for court.&#160;You will also learn about the skills, abilities, and talents needed for careers in this cluster.&#160;We will also discuss the different requirements in training and education for some of the common jobs in this career cluster.</p><p>Objectives</p><p>In this module, students will</p><p>Identify the pathways in the Law, Public Safety &amp; Security career cluster and the careers in each pathway.</p><p>Describe the types of places that employ individuals who have careers in the Law, Public Safety &amp; Security career cluster.</p><p>Describe the variety of tasks performed by individuals who have careers in the Law, Public Safety &amp; Security career cluster.</p><p>List the skills, abilities, and talents needed for careers in the Law, Public Safety &amp; Security career cluster.</p><p>Identify the level of training and education required for careers in the Law, Public Safety &amp; Security career cluster.</p><p>Research a career in the Law, Public Safety &amp; Security career cluster and present findings to the class.</p><p>Apply math, science, and reading skills in the completion of a project or activity related to the Law, Public Safety &amp; Security career cluster.</p><p>Polling Question</p><p>Which job in the Law, Public Safety &amp; Security cluster sounds most interesting to you?</p><p>Police officer&#160;Lawyer&#160;Private investigator&#160;Emergency medical technician&#160;Other</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Looking into something to try and find out what happened.</p><p>Evidence</p><p>A decision made by a court to let someone out of prison early if they promise to behave.</p><p>Investigation</p><p>Rules that everyone in a country has to follow.</p><p>Security</p><p>Something that helps show if something happened or not.</p><p>Parole</p><p>Measures taken to keep people and things safe.</p><p>Laws</p><p>Alternative Activity</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('231ad09edcd63374b1db81eec4975871','career-exploration-m12-l2-lesson-1','831cb8533365c3ef13381bd1dd6d1ec7','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>What is Law, Public Safety, Security Careers</h3><p>What is Law, Public Safety, Security Careers</p><p>What is the Law, Public Safety &amp; Security Career Cluster?</p><p>The Law, Public Safety &amp; Security career cluster is all about protecting people and keeping them safe.&#160;People in this cluster might work as police officers, firefighters, or even in the military.&#160;They help keep us safe by enforcing laws and responding to emergencies.&#160;They might help people in danger, investigate crimes, or even provide security at places like stores and airports.</p><p>There are five primary pathways in this career cluster.&#160;Click through the slideshow to learn more about each one.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Correction Services Pathway:&#160;This pathway focuses on helping people who have broken the law learn how to be better citizens.&#160;People who work in this pathway help people in prisons and jails learn new skills and habits that will help them avoid getting into trouble again.&#160;Careers in this pathway include probation/parole officer, youth services worker, and corrections officer.</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;5</p><p>Next</p><p>Emergency &amp; Fire Management Services Pathway: This pathway focuses on helping people during emergencies or disasters. People who work in this pathway help people stay safe during natural disasters and other emergencies. They also help put out fires and rescue people who are in danger. Jobs in this pathway include firefighters, EMTs, and hazardous materials responders.</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;5</p><p>Next</p><p>Law Enforcement Services Pathway: This pathway focuses on keeping people safe by enforcing laws. People who work in this pathway help to protect people and their property by investigating crimes and arresting people who break the law. This includes professions such as highway patrol officer, police officer, and investigators.</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;5</p><p>Next</p><p>Legal Services Pathway: This pathway focuses on helping people understand the law. People who work in this pathway help people understand their legal rights and make sure they are following the law. Examples of professions in this pathway include attorneys, paralegals, and judges.</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;5</p><p>Next</p><p>Security &amp; Protective Services Pathway: This pathway focuses on keeping people, places, and things safe. People who work in this pathway help protect people, businesses, and important places from danger. They also help keep people safe by checking people&#39;s identification and doing security checks. Jobs in this pathway include security officer, information security specialist, and transportation security officer.</p><p>Previous</p><p>Slide&#160;5&#160;of&#160;5</p><p>Next</p><p>Now that you’ve learned about the pathways, see if you can match the job to the correct pathway:</p><p>Job</p><p>Pathway</p><p>Youth service worker</p><p>legal services pathway</p><p>Probation officer</p><p>legal services pathway</p><p>EMT</p><p>law enforcement and services pathway</p><p>Firefighter</p><p>emergency and fire management services pathway</p><p>Highway patrol officer</p><p>correction services pathway</p><p>Investigator</p><p>correction services pathway</p><p>attorney</p><p>emergency and fire management services pathway</p><p>Paralegal</p><p>law enforcement and services pathway</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Youth service worker</p><p>Answers for question: 1</p><p>emergency and fire management services pathway</p><p>law enforcement and services pathway</p><p>correction services pathway</p><p>legal services pathway</p><p>correction services pathway</p><p>law enforcement and services pathway</p><p>emergency and fire management services pathway</p><p>2.</p><p>Probation officer</p><p>Answers for question: 2</p><p>correction services pathway</p><p>legal services pathway</p><p>law enforcement and services pathway</p><p>emergency and fire management services pathway</p><p>law enforcement and services pathway</p><p>correction services pathway</p><p>legal services pathway</p><p>emergency and fire management services pathway</p><p>3.</p><p>EMT</p><p>Answers for question: 3</p><p>legal services pathway</p><p>law enforcement and services pathway</p><p>correction services pathway</p><p>legal services pathway</p><p>emergency and fire management services pathway</p><p>law enforcement and services pathway</p><p>correction services pathway</p><p>4.</p><p>Firefighter</p><p>Answers for question: 4</p><p>correction services pathway</p><p>law enforcement and services pathway</p><p>correction services pathway</p><p>emergency and fire management services pathway</p><p>legal services pathway</p><p>emergency and fire management services pathway</p><p>legal services pathway</p><p>law enforcement and services pathway</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('5ea672b2bc896ce83edeab04953d0da3','career-exploration-m12-l3-lesson-2','831cb8533365c3ef13381bd1dd6d1ec7','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Where Law, Public Safety, Security ppl Work</h3><p>Where Law, Public Safety, Security ppl Work</p><p>Where People in the Law, Public Safety &amp; Security Career Cluster Work</p><p>There are a variety of options available for employment in the Law, Public Safety &amp; Security career cluster.&#160;Click below to learn more:</p><p>See if you can match the description to the most likely place of employment.</p><p>Police Departments &amp; Fire Departments</p><p>Police departments and fire departments employ individuals who have careers in the Law, Public Safety &amp; Security career cluster. Police officers patrol assigned areas in order to protect people from crime and respond to emergency calls. Fire departments respond to emergencies.</p><p>Law Firms</p><p>Law firms provide legal advice and services to their clients. They can help with a variety of matters, including drafting and reviewing contracts, providing advice on regulatory compliance, representing clients in lawsuits, mediating disputes, and providing representation in criminal cases. In addition to these services, law firms may also provide advice on intellectual property, tax, and estate planning. Law firms employ individuals who have careers in the Law, Public Safety &amp; Security career cluster such as attorneys and paralegals.</p><p>Government Agencies</p><p>The government employs individuals who have careers in the Law, Public Safety &amp; Security career cluster. These individuals include judges, prosecutors, defense attorneys, and court clerks. They are responsible for ensuring that justice is served and that legal proceedings are conducted properly.</p><p>Prisons and Correctional Facilities</p><p>Prisons and correctional facilities employ individuals who have careers in the Law, Public Safety &amp; Security career cluster. Individuals employed here are responsible for monitoring and providing security for inmates and making sure that they are following the rules.</p><p>Border Patrol</p><p>The border patrol employs individuals who have careers in the Law, Public Safety &amp; Security career cluster. These individuals are responsible for patrolling and monitoring national borders in order to prevent illegal immigration and smuggling.</p><p>Security Guard Companies</p><p>Individuals who work at security guard companies are responsible for providing security services to businesses and other organizations. They may also be responsible for monitoring surveillance cameras and responding to alarms.</p><p>Private Investigation Agencies</p><p>Private investigation agencies employ individuals who have careers in the Law, Public Safety &amp; Security career cluster to conduct background checks, investigate crimes, and provide security services to businesses and other organizations.</p><p>The exact place of employment depends on the individual’s job.&#160;See if you can match the job to the most likely place of employment.</p><p>Job</p><p>Place of Employment</p><p>Private investigator</p><p>Law firm</p><p>Night guard at a business complex</p><p>Fire Department</p><p>Border patrol agent</p><p>Government agency</p><p>Correctional officer</p><p>Border Patrol</p><p>Job</p><p>Security guard company</p><p>Paralegal</p><p>Private investigation agency</p><p>EMT</p><p>Prison</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Private investigator</p><p>Answers for question: 1</p><p>Security guard company</p><p>Border Patrol</p><p>Law firm</p><p>Private investigation agency</p><p>Prison</p><p>Fire Department</p><p>Government agency</p><p>2.</p><p>Night guard at a business complex</p><p>Answers for question: 2</p><p>Government agency</p><p>Border Patrol</p><p>Prison</p><p>Fire Department</p><p>Law firm</p><p>Security guard company</p><p>Private investigation agency</p><p>3.</p><p>Border patrol agent</p><p>Answers for question: 3</p><p>Prison</p><p>Fire Department</p><p>Border Patrol</p><p>Government agency</p><p>Security guard company</p><p>Law firm</p><p>Private investigation agency</p><p>4.</p><p>Correctional officer</p><p>Answers for question: 4</p><p>Government agency</p><p>Private investigation agency</p><p>Security guard company</p><p>Border Patrol</p><p>Prison</p><p>Fire Department</p><p>Law firm</p><p>5.</p><p>Job</p><p>Answers for question: 5</p><p>Law firm</p><p>Fire Department</p><p>Government agency</p><p>Border Patrol</p><p>Security guard company</p><p>Private investigation agency</p><p>Prison</p><p>6.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e35be8c3151ea5f85c7212333e3e0461','career-exploration-m12-l4-lesson-3','831cb8533365c3ef13381bd1dd6d1ec7','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Activities for Law, Public Safety, Security</h3><p>Activities for Law, Public Safety, Security Careers</p><p>Activities in the Law, Public Safety &amp; Security Career Cluster</p><p>The Law, Public Safety &amp; Security career cluster is one of the more diverse career clusters.&#160;This means that the tasks performed by people in this cluster are going to vary greatly from professional to professional.&#160;Click through the tabs below to learn more about some of these tasks:</p><p>Draft legal documents</p><p>Writing up the rules or laws that tell people how to act in different situations.</p><p>Prepare cases for court</p><p>Getting all the evidence, witnesses, and other information together that is necessary for a court to make a decision.</p><p>Represent clients in court</p><p>Speaking and arguing on behalf of someone who is involved in a court case.</p><p>Investigate &amp; analyze criminal activity</p><p>Looking into any illegal things that happened and trying to figure out who did it.</p><p>Enforce laws and regulations</p><p>Making sure that people follow the rules and don&#39;t do anything illegal.</p><p>Prepare legal briefs</p><p>Writing up a summary of a case that explains why a certain decision should be made.</p><p>Respond to emergencies</p><p>Providing help in the event of crimes, fires, accidents, or other emergency situations.</p><p>File documents with court systems</p><p>Putting important papers and documents in the court&#39;s files so they can use them to decide a case.</p><p>Collect evidence and conduct interviews</p><p>Finding things that can help prove what happened in a case, and talking to people who have information about it.</p><p>Provide security in public places</p><p>Making sure that people are safe in public areas like parks and stores.</p><p>Perform background checks</p><p>Looking at a person&#39;s past to see if they have done anything wrong.</p><p>Create safety plans for organizations</p><p>Making sure that an organization has rules and procedures in place to keep people safe.</p><p>Educate on security regulations</p><p>Teaching people about the rules and regulations that are in place to keep them safe.</p><p>Next Tab</p><p>Each of these tasks also has many tasks within them.&#160;For example, preparing cases for court may also require researching legal precedents to see what happened in similar cases in the past.&#160;Enforcing laws and regulations may involve monitoring a particular road to enforce the speed limit and writing tickets for those who violate the laws of the road.&#160;Doing some research to learn more about each of these tasks may help you further determine if a career in Law, Public Safety &amp; Security is right for you.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c03f024292258e4c9b5faa43fa8faa36','career-exploration-m12-l5-lesson-4','831cb8533365c3ef13381bd1dd6d1ec7','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Skills Needed for Law, Public Safety, Security</h3><p>Skills Needed for Law, Public Safety, Security</p><p>Skills, Abilities, and Talents Needed for a Career in Law, Public Safety &amp; Security</p><p>Each profession within the Law, Public Safety &amp; Security career cluster requires certain skills, abilities, and talents.&#160;Click to learn about some of the more common ones:</p><p>Communication Skills</p><p>Lawyers, paralegals, and legal assistants must have excellent communication skills in order to effectively communicate with clients, colleagues, and the court. This includes both verbal and written communication skills.</p><p>Problem-Solving Abilities</p><p>Professionals in the law, public safety &amp; security career cluster must be able to quickly analyze and assess legal situations in order to come up with the best possible solutions.</p><p>Research Skills</p><p>Lawyers and investigators must be able to conduct extensive research to help their clients and victims of crimes.</p><p>Interpersonal Skills</p><p>Professionals in this field must have strong interpersonal skills in order to interact with clients, colleagues, and the court.</p><p>Analytical Skills</p><p>Professionals in the law, public safety &amp; security career cluster must have strong analytical skills in order to read and interpret legal documents and analyze legal cases.</p><p>Critical Thinking Skills</p><p>Legal professionals must be able to think critically in order to come up with sound legal arguments and strategies.</p><p>Leadership Abilities</p><p>Professionals in the law, public safety &amp; security career cluster may need to take on leadership roles in order to manage legal teams or organizations.</p><p>Negotiation Skills</p><p>Lawyers and other legal professionals must have strong negotiation skills in order to effectively negotiate with opposing parties and come to a mutually beneficial agreement.</p><p>Judgment</p><p>Professionals in the law, public safety &amp; security career cluster must be able to make sound decisions and judgments.</p><p>Empathy</p><p>Professionals in this field must be able to empathize with their clients in order to provide the best possible service.</p><p>Medical skills</p><p>Some professionals in this career cluster must have medical skills in order to respond to medical emergency situations, understand the medical evidence presented in criminal cases, and in providing aid to victims of disasters.</p><p>Click on the image below to learn more about the things you can do now to prepare for a career in this cluster:</p><p>5</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>How to prepare for a career in Law, Public Safety &amp; Security</p><p>The hotspot points on the image are as follows:</p><p>Read</p><p>Develop a strong understanding of the criminal justice system by taking classes or reading books on the topic.</p><p>Programs</p><p>Join a program in your community that provides mentorship to youth, such as a police or firefighter explorer program.</p><p>Puzzles</p><p>Build up your problem-solving skills by participating in puzzles and brainteasers.</p><p>Improve communication skills</p><p>Build up your communication skills by joining speech and debate teams and taking public speaking classes.</p><p>Classes</p><p>Take a first aid and CPR certification class to become more prepared to assist in emergency situations.</p><p>Activities</p><p>Take part in extracurricular activities such as student government, debate, or mock trial.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('fa61acae65525100ffd0133610485837','career-exploration-m12-l6-lesson-5','831cb8533365c3ef13381bd1dd6d1ec7','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Education &amp; Training for Law, PS, Security</h3><p>Education &amp; Training for Law, Public Safety, Security</p><p>Education and Training in the Law, Public Safety &amp; Security Career Cluster:</p><p>The level of training and education required for careers in the Law, Public Safety &amp; Security career cluster can vary significantly.&#160;Depending on the specific career path and job title, an individual may need a high school diploma, certification from a specialized training program, an associate&#39;s, a bachelor&#39;s, or even a master&#39;s degree.&#160;In some cases, a post-graduate law degree may be required.Let’s explore the training and education needed for some of the jobs in this career cluster.&#160;Click on each tab to learn more:</p><p>Police Officer</p><p>In the United States, police officers must have a high school diploma or GED.&#160;They must then complete a training academy program that typically lasts between 12 and 14 weeks.&#160;The academy program consists of physical conditioning, firearms training, and courses related to police laws and procedures.&#160;Some police departments may require college coursework or a degree.</p><p>Lawyer</p><p>Lawyers in the United States need to complete an undergraduate degree, preferably in a field related to law such as political science, history, English, or philosophy. They must then attend an accredited law school, pass the LSAT exam, and earn a Juris Doctor degree. After completing the J.D., lawyers must pass the state&#39;s bar exam in order to practice law.</p><p>Paralegal</p><p>Paralegals must have a postsecondary certificate or an associate&#39;s degree in paralegal studies. Courses may include legal research, legal writing, and other topics related to the legal system.</p><p>Corrections Officer</p><p>Corrections officers must have a high school diploma or GED and complete a training program. The program typically consists of physical conditioning, firearms training, and courses related to prison laws and procedures. Some departments may require college coursework or a degree.</p><p>Private Investigator</p><p>Private investigators must have a high school diploma or GED. Most states require private investigators to have a license, which requires passing a background check and completing training courses. The training courses cover topics such as surveillance, investigations, and state laws.</p><p>Security Guard</p><p>Security guards must have a high school diploma or GED and complete a training program. The program typically consists of physical conditioning, firearms training, and courses related to security procedures. Some departments may require college coursework or a degree.</p><p>Court Reporter</p><p>Court reporters must complete a postsecondary certificate or an associate&#39;s degree in court reporting. Courses may include legal terminology, legal writing, and audio transcription.</p><p>Bailiff</p><p>Bailiffs must have a high school diploma or GED and complete a training program. The program typically consists of physical conditioning, firearms training, and courses related to court laws and procedures. Some departments may require college coursework or a degree.</p><p>Firefighter</p><p>Firefighters must have a high school diploma or GED and complete a training program. The program typically consists of physical conditioning, firefighting techniques, and courses related to fire safety laws and procedures. Some departments may require college coursework or a degree.</p><p>Probation Officer</p><p>Probation officers must have a bachelor&#39;s degree in criminal justice, psychology, or a related field. They must then complete a training program that typically lasts between 12 and 14 weeks. The program consists of physical conditioning, firearms training, and courses related to probation laws and procedures.</p><p>Next Tab</p><p>As you can see, there are opportunities at every level of education and training.&#160;That is part of what makes this such an interesting and appealing career cluster.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c0fc8fd740af0e632dc7abef186c19bd','career-exploration-m12-l7-module-12-summary','831cb8533365c3ef13381bd1dd6d1ec7','Module 12 Summary','text',12,'<h2>Module 12 Summary</h2><section><h3>Module 12 Summary</h3><p>Module 12 Summary</p><p>Great Work!&#160;You have successfully completed this module on the Law, Public Safety &amp; Security career cluster.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identify the pathways in the Law, Public Safety &amp; Security career cluster and the careers in each pathway.</p><p>Describe the types of places that employ individuals who have careers in the Law, Public Safety &amp; Security career cluster.</p><p>Describe the variety of tasks performed by individuals who have careers in the Law, Public Safety &amp; Security career cluster.</p><p>List the skills, abilities, and talents needed for careers in the Law, Public Safety &amp; Security career cluster.</p><p>Identify the level of training and education required for careers in the Law, Public Safety &amp; Security career cluster.</p><p>Research a career in the Law, Public Safety &amp; Security career cluster and present findings to the class.</p><p>Apply math, science, and reading skills in the completion of a project or activity related to the Law, Public Safety &amp; Security career cluster.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e9b9585046e6e9078b72abce6065bda8','career-exploration-m12-l8-module-12-project','831cb8533365c3ef13381bd1dd6d1ec7','Module 12 Project','text',12,'<h2>Module 12 Project</h2><section><h3>Module 12 Project</h3><p>Module 12 Project</p><p>Career Exploration</p><p>Law, Public Safety &amp; Security - Project</p><p>For this project, you will choose from two options.&#160; You only need to complete one of these options.&#160; Please find both options and their rubrics below.</p><p>Option 1</p><p>For this project, you will create a presentation about a law in your state or area that you find strange, interesting, or disagree with. Complete the following for your presentation:</p><p>On one slide, provide an overview of the law.</p><p>On a second slide, explain who/what benefits from this law.</p><p>On another slide, present your opinion about the law.</p><p>On each slide, include at least one graphic/image.</p><p>Review the rubric to see how you will be graded.</p><p>Option 1 Rubric: Law, Public Safety &amp; Security Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Slide 1: Overview</p><p>5 points The slide provides an excellent overview of the law.</p><p>3-4 points The slide provides an adequate overview of the law.</p><p>0-2 points The slide provides a poor overview of the law.</p><p>5</p><p>Slide 2: Benefit</p><p>5 points The slide provides an excellent analysis of who/what benefits from this law.</p><p>3-4 points The slide provides an adequate analysis of who/what benefits from the law.</p><p>0-2 points The slide provides a poor analysis of who/what benefits from the law.</p><p>5</p><p>Graphics/Images</p><p>5 points Each slide contains at least one applicable graphic/image.</p><p>3-4 points At least 2 slides contain graphics/images and are mostly applicable.</p><p>0-2 points Fewer than 2 slides contain graphics/images and/or the images are not applicable.</p><p>5</p><p>Slide 3: Opinion</p><p>5 points The slide does an excellent job of explaining and justifying the student&#39;s opinion.</p><p>3-4 points The slide does an adequate job of explaining and justifying the student&#39;s opinion.</p><p>0-2 points The slide does a poor job of explaining and justifying the student&#39;s opinion.</p><p>5</p><p>Total Points:&#160;20</p><p>Option 2</p><p>For this option, you will research a particular career that interests you in this cluster. Complete the following steps for your project:</p><p>Step 1: Research your chosen career.</p><p>Step 2: List the following</p><p>Average Salary/Salary Range</p><p>Education Requirements</p><p>Certification Requirements (if any)</p><p>Why you chose that career</p><p>Step 3: Prepare a PowerPoint presentation about your chosen career, including the information you gathered in Step 2 as well as your reason for choosing that career.</p><p>Your final submission should be your PowerPoint containing the information in Step 3.</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 2 Rubric: Law, Public Safety &amp; Security Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Research</p><p>12 points The student provided a career field that interested them, the average salary or range, and the education/certifications required for the career.</p><p>11-4 points The student provided two of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>3-0 points The student provided one or none of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>12</p><p>Reason for Choosing the Career Field</p><p>4 points The student thoughtfully provided the reason that they are interested in this career.</p><p>N/A</p><p>0 points The student did not provide the reason that they are interested in this career.</p><p>4</p><p>Formatting</p><p>4 points The student&#39;s presentation includes no spelling or grammatical errors.</p><p>3-1 points The student&#39;s presentation includes minimal spelling or grammatical errors.</p><p>0 points The student&#39;s presentation includes a significant amount of spelling or grammatical errors.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('fe6dae217a4e4f5a54590d74f85667fd','career-exploration-m12-l9-module-12-quiz','831cb8533365c3ef13381bd1dd6d1ec7','Module 12 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Law, Public Safet, Security. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('94623a29ea536a6867da77b1e1189e14','career-exploration-module-13','68d48b60cc4feb626956ed1fd8311e46','Module 13: Manufacturing',13) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('79fc79da85fb726012c4d571d5e4fe97','career-exploration-m13-l1-introduction-purpose-and-objectives','94623a29ea536a6867da77b1e1189e14','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Descripition Objectives</h3><p>Introduction</p><p>Welcome to this module on the Manufacturing Career Cluster.</p><p>Think about how many products you use in a day. What do you think went into getting that product from an idea in someone’s mind to a physical product in your hands? We owe our thanks for the creation of so many products to those working in the manufacturing career cluster.</p><p>From the creation of new products to the development of innovative processes, the manufacturing industry is a fast-paced and ever-evolving field that offers individuals an opportunity to make a difference in the world. As the world’s population grows and technology advances, the manufacturing industry is growing rapidly. From the development of new materials to the creation of revolutionary products, the manufacturing industry is full of opportunities for those looking to make a difference. The manufacturing career cluster offers individuals the opportunity to gain a variety of skills that are essential to the industry. Through hands-on experience and educational programs, individuals can learn the fundamentals of the manufacturing trade, as well as how to troubleshoot and maintain complex machinery.</p><p>This career cluster also encompasses some of the careers that focus on product development. Would you like to be part of the team that creates the first chef robot? Or the newest must-have snowboard on the market? Or even the next-generation computer chips that will power flying cars? There are basically no limits to what can be done in the manufacturing pathway.</p><p>In addition to the technical skills, those in the manufacturing career cluster will gain important soft skills such as communication, problem-solving, and team-building. With these skills, you can make a real impact on the world by developing and managing projects that generate value for companies and customers alike.</p><p>In this module, we’ll explore the pathways leading to careers like machine operator, design engineer, mechanic, inspector, safety coordinator, and more. We’ll also discuss where you can look for employment in this career cluster and what you may be asked to do if hired as part of the manufacturing industry. You’ll also learn about the skills, abilities, and talents needed to succeed and the education needed to develop those skills.</p><p>Let’s learn more about how we get the products we use by learning about the manufacturing career cluster!</p><p>Module Description</p><p>Welcome to this module on the Manufacturing career cluster!&#160;In this module, you will discover the various pathways in this cluster and some of the jobs associated with each pathway.&#160;Next, we will discuss the types of places that employ individuals in this field.&#160;The module will explain the different tasks that someone in this career cluster may perform on a regular basis.&#160;You will also learn about the skills, abilities, and talents expected of professionals in the industry.&#160;We will also discuss the different requirements in training and education for some of the common jobs in this career cluster.</p><p>Objectives</p><p>In this module, students will</p><p>Identify the pathways in the Manufacturing career cluster and the careers in each pathway.</p><p>Describe the types of places that employ individuals who have careers in the Manufacturing career cluster.</p><p>Describe the variety of tasks performed by individuals who have careers in the Manufacturing career cluster.</p><p>List the skills, abilities, and talents needed for careers in the Manufacturing career cluster.</p><p>Identify the level of training and education required for careers in the Manufacturing career cluster.</p><p>Research a career in the Manufacturing career cluster and present findings to the class.</p><p>Apply math, science, and reading skills in the completion of a project or activity related to the Manufacturing career cluster.</p><p>Polling Question</p><p>What career in the Manufacturing career cluster sounds most interesting to you?</p><p>Quality control inspector&#160;Assembler&#160;Mechanic&#160;Product designer&#160;Other</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Creating a product is made from raw materials, like plastic, metal, or wood.</p><p>Assembly</p><p>The process of creating a product.</p><p>Production</p><p>This is a fabric or material that is made from natural or synthetic fibers.</p><p>Product</p><p>This is when a bunch of different parts are put together to make something, like a toy or a car.</p><p>Textile</p><p>When someone looks over something to make sure it meets the standards it is supposed to.</p><p>Inspection</p><p>Something that is made by a company, like a toy or a car.</p><p>Manufacturing</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Creating a product is made from raw materials, like plastic, metal, or wood.</p><p>Answers for question: 1</p><p>Manufacturing</p><p>Product</p><p>Inspection</p><p>Textile</p><p>Production</p><p>Assembly</p><p>2.</p><p>The process of creating a product.</p><p>Answers for question: 2</p><p>Manufacturing</p><p>Inspection</p><p>Assembly</p><p>Product</p><p>Production</p><p>Textile</p><p>3.</p><p>This is a fabric or material that is made from natural or synthetic fibers.</p><p>Answers for question: 3</p><p>Product</p><p>Production</p><p>Textile</p><p>Manufacturing</p><p>Inspection</p><p>Assembly</p><p>4.</p><p>This is when a bunch of different parts are put together to make something, like a toy or a car.</p><p>Answers for question: 4</p><p>Production</p><p>Textile</p><p>Manufacturing</p><p>Assembly</p><p>Inspection</p><p>Product</p><p>5.</p><p>When someone looks over something to make sure it meets the standards it is supposed to.</p><p>Answers for question: 5</p><p>Assembly</p><p>Textile</p><p>Inspection</p><p>Product</p><p>Manufacturing</p><p>Production</p><p>6.</p><p>Something that is made by a company, like a toy or a car.</p><p>Answers for question: 6</p><p>Product</p><p>Assembly</p><p>Textile</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('37620f3953bb78a2159068d0c38c82fc','career-exploration-m13-l2-lesson-1','94623a29ea536a6867da77b1e1189e14','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>What is Manufacturing Career Cluster</h3><p>What is Manufacturing Career Cluster</p><p>What is the Manufacturing Career Cluster?</p><p>The manufacturing career cluster is all about creating products or parts for products.&#160;People who work in manufacturing use machines, tools, and computers to make things like cars, clothes, electronics, and furniture.&#160;They also help figure out how to make things better, faster, and less expensive.</p><p>Click below to learn more about the pathways in this career cluster:</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Production Pathway:&#160;This pathway is about assembling products or product parts.&#160;People in this pathway use machines and tools to make electronics, construct housing components, weld, and print materials.&#160;Some of the careers in this pathway include assembler, machine operator, and welder.</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;6</p><p>Next</p><p>Manufacturing Production Process Development Pathway: This pathway is about designing and improving the way things are made. People in this pathway figure out the best way to make products for customers and oversee the manufacturing process. Jobs in this pathway include design engineer, electronics engineer, and production manager.</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;6</p><p>Next</p><p>Maintenance, Installation &amp; Repair Pathway: This pathway is about keeping things working. People in this pathway make sure machines and tools used to make products run smoothly. They also make sure products that break are fixed. Some of the jobs in this pathway include mechanic, appliance repairer, and security system installer.</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;6</p><p>Next</p><p>Quality Assurance Pathway: This pathway is about making sure products are safe and work correctly. People in this pathway make sure the products made, meet the standards for safety and quality. This may involve testing the products. Jobs in this pathway include process control technician, quality control technician, and quality engineer.</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;6</p><p>Next</p><p>Logistics &amp; Inventory Control Pathway: This pathway is about keeping track of the supplies used to make products. People in this pathway make sure the right materials, like metal and plastic, are delivered to the right place so that products can be made. They may unload trucks, move materials to the production line, and wrap pallets of products for delivery. Careers in this pathway include dispatcher, clerk, and materials mover.</p><p>Previous</p><p>Slide&#160;5&#160;of&#160;6</p><p>Next</p><p>This pathway focuses on making sure the workplace is safe. People in this pathway make sure that the machines and tools used to make products are used in a way that doesn&#39;t hurt people or the environment. Activities in this pathway include safety inspections, implementing health/safety programs and policies, and conducting investigations into the safety and health of the workplace. Professions in this pathway include safety coordinator, environmental engineer, and health and safety reps.</p><p>Previous</p><p>Slide&#160;6&#160;of&#160;6</p><p>Next</p><p>Match the person to the corresponding pathway:</p><p>If you are using a keyboard to navigate, you must use the following alternative activity to receive credit.</p><p>Production Pathway</p><p>Manufacturing Production Process Development Pathway</p><p>Maintenance, Installation &amp; Repair Pathway</p><p>Quality Assurance Pathway</p><p>Logistics &amp; Inventory Control Pathway</p><p>Health, Safety &amp; Environmental Assurance Pathway</p><p>Alternative Activity</p><p>Match up each choice with a category.</p><p>1. Ximena creates safety plans for her workplace.&#160;Production Pathway&#160;Manufacturing Production Process Development Pathway&#160;Maintenance, Installation &amp; Repair Pathway&#160;Quality Assurance Pathway&#160;Logistics &amp; Inventory Control Pathway&#160;Health, Safety &amp; Environmental Assurance Pathway</p><p>2. Jaxon processes the incoming materials to make sure all records are accurate.&#160;Production Pathway&#160;Manufacturing Production Process Development Pathway&#160;Maintenance, Installation &amp; Repair Pathway&#160;Quality Assurance Pathway&#160;Logistics &amp; Inventory Control Pathway&#160;Health, Safety &amp; Environmental Assurance Pathway</p><p>3. Fatimah is responsible for ensuring all products going out are up to standard.&#160;Production Pathway&#160;Manufacturing Production Process Development Pathway&#160;Maintenance, Installation &amp; Repair Pathway&#160;Quality Assurance Pathway&#160;Logistics &amp; Inventory Control Pathway&#160;Health, Safety &amp; Environmental Assurance Pathway</p><p>4. Charly installs security systems in businesses.&#160;Production Pathway&#160;Manufacturing Production Process Development Pathway&#160;Maintenance, Installation &amp; Repair Pathway&#160;Quality Assurance Pathway&#160;Logistics &amp; Inventory Control Pathway&#160;Health, Safety &amp; Environmental Assurance Pathway</p><p>5. Avani welds metal together during the production process.&#160;Production Pathway&#160;Manufacturing Production Process Development Pathway&#160;Maintenance, Installation &amp; Repair Pathway&#160;Quality Assurance Pathway&#160;Logistics &amp; Inventory Control Pathway&#160;Health, Safety &amp; Environmental Assurance Pathway</p><p>6. Akio uses computer-aided engineering software to create models of products and machines&#160;Production Pathway&#160;Manufacturing Production Process Development Pathway&#160;Maintenance, Installation &amp; Repair Pathway&#160;Quality Assurance Pathway&#160;Logistics &amp; Inventory Control Pathway&#160;Health, Safety &amp; Environmental Assurance Pathway</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('cb37b3b4dd18eb809ce7df75b775ebd7','career-exploration-m13-l3-lesson-2','94623a29ea536a6867da77b1e1189e14','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Where Manufacturing ppl Work</h3><p>Where Manufacturing ppl Work</p><p>Where People in the Manufacturing Career Cluster Work</p><p>People working in the Manufacturing career cluster can find employment anywhere products or materials are being created.&#160;Here are a few examples of places where professionals in this career cluster may work.&#160;Click on each tab to learn more:</p><p>Automotive Assembly Plant</p><p>This type of job involves assembling cars, trucks, and other motor vehicles on a factory assembly line.&#160;Employees may work with a variety of components such as engines, transmissions, brakes, and other parts to put together a complete vehicle.</p><p>Autobody repair shop</p><p>Automotive mechanics may find work at an autobody repair shop. Here they may do repair work for cars and trucks to ensure they are safe and efficient.</p><p>Electronics Manufacturing Plant</p><p>This type of job involves manufacturing electronic components such as circuit boards, capacitors, and resistors.</p><p>Aerospace Manufacturing Plant</p><p>This type of job involves the production of aircraft and aerospace components such as wings, fuselages, and engines.</p><p>Textile Manufacturing Plant</p><p>This type of job involves the production of textiles such as fabrics, thread, yarn, and other materials.</p><p>Chemical Plant</p><p>This type of job involves the production of materials such as plastics, polymers, and chemicals. Employees may also be involved in the assembly of products such as paint and other household products.</p><p>Steel Mill</p><p>This type of job involves the manufacture of steel and its related products such as beams, plates, and bars. Employees may also be involved in the assembly and fabrication of steel products.</p><p>Machine Shop</p><p>This type of job involves the use of machining tools and equipment to produce parts and components for a wide variety of industries.</p><p>Next Tab</p><p>Some of these may be large facilities run by big corporations.&#160;Others may be small shops run by local businesses.&#160;No matter where people in this cluster find employment, the goal is to create safe, efficient, and useable products and materials.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1567d30728613a869483ebacbdb46ac7','career-exploration-m13-l4-lesson-3','94623a29ea536a6867da77b1e1189e14','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Activities in Manufacturing Careers</h3><p>Activities in Manufacturing Careers</p><p>Activities in the Manufacturing Career Cluster</p><p>It takes a lot of people performing a variety of tasks to keep the products we use available to us.&#160;Read the tasks below to learn about some of the activities individuals in the Manufacturing career cluster may perform:</p><p>Developing production processes</p><p>Developing production processes involves creating efficient and effective ways of producing products. This includes planning layouts, selecting materials, and determining production methods.</p><p>Monitoring production</p><p>Manufacturing professionals must monitor production to ensure that all products are being made to the highest standards and specifications.</p><p>Ensuring safety</p><p>Manufacturing professionals must ensure that all safety guidelines are followed to protect workers and the products they are producing from any potential harm.</p><p>Testing products</p><p>Manufacturers must test products to make sure they meet quality standards and customer expectations.</p><p>Analyzing data</p><p>Manufacturing professionals must analyze data to identify areas for improvement and increase efficiency.</p><p>Managing inventory</p><p>Manufacturers must manage inventory to ensure that there are enough of the right materials available to meet production demands.</p><p>Negotiating contracts</p><p>Manufacturing professionals must negotiate contracts with suppliers and customers to ensure that they are getting the best deals.</p><p>Troubleshooting issues</p><p>Manufacturing professionals must troubleshoot any issues that arise with production or equipment.</p><p>Developing quality control systems</p><p>Manufacturing professionals must develop quality control systems to ensure that all products meet the required standards.</p><p>Training staff</p><p>Manufacturing professionals must train staff to ensure that they have the necessary skills and knowledge to effectively operate the equipment.</p><p>See if you can match the scenario to the correct task:</p><p>Jaya has a new idea for a product.&#160;Now that investors are interested, she needs to start figuring out how the product will actually be made.</p><p>Negotiating contracts</p><p>Kamal works at a steel mill and needs to keep production on schedule.</p><p>Analyzing data</p><p>A new machine has been ordered and Mina needs to create a plan to ensure no one is hurt by the new machine.</p><p>Testing products</p><p>Naya is responsible for ensuring the engines of the cars all work as expected.</p><p>Monitoring production</p><p>Jaden is reviewing charts and graphs to find ways to increase efficiency.</p><p>Managing inventory</p><p>Santiago is responsible for making sure there is sufficient hardware for the crew to build the aerospace parts.</p><p>Developing quality control systems</p><p>Zayna gets on the phone to speak with a supplier to find out how many products need to be ordered to receive a discount.</p><p>Troubleshooting issues:</p><p>Isabella is trying to determine what is causing her client’s appliance to malfunction.</p><p>Developing production processes</p><p>Malik is mapping out a process that will help ensure all products are up to standard.</p><p>Ensuring safety</p><p>Elena is responsible for explaining to the new crew how to work on the assembly line.</p><p>Training staff</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Jaya has a new idea for a product. Now that investors are interested, she needs to start figuring out how the product will actually be made.</p><p>Answers for question: 1</p><p>Training staff</p><p>Testing products</p><p>Managing inventory</p><p>Ensuring safety</p><p>Developing quality control systems</p><p>Negotiating contracts</p><p>Monitoring production</p><p>Troubleshooting issues:</p><p>Analyzing data</p><p>Developing production processes</p><p>2.</p><p>Kamal works at a steel mill and needs to keep production on schedule.</p><p>Answers for question: 2</p><p>Developing production processes</p><p>Testing products</p><p>Troubleshooting issues:</p><p>Managing inventory</p><p>Negotiating contracts</p><p>Monitoring production</p><p>Training staff</p><p>Analyzing data</p><p>Developing quality control systems</p><p>Ensuring safety</p><p>3.</p><p>A new machine has been ordered and Mina needs to create a plan to ensure no one is hurt by the new machine.</p><p>Answers for question: 3</p><p>Developing production processes</p><p>Developing quality control systems</p><p>Analyzing data</p><p>Testing products</p><p>Monitoring production</p><p>Negotiating contracts</p><p>Troubleshooting issues:</p><p>Training staff</p><p>Ensuring safety</p><p>Managing inventory</p><p>4.</p><p>Naya is responsible for ensuring the engines of the cars all work as expected.</p><p>Answers for question: 4</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6fc1acddcd416709ad1df9b305741e28','career-exploration-m13-l5-lesson-4','94623a29ea536a6867da77b1e1189e14','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Skills Needed for Manufacturing Careers</h3><p>Skills Needed for Manufacturing Careers</p><p>Skills, Abilities, and Talents Need for the Manufacturing Career Cluster</p><p>What does it take to be successful in the Manufacturing career cluster?&#160;Becoming successful in this career cluster takes commitment to one’s profession and a desire to create or repair products that help solve a problem for a customer.&#160;Beyond the inner commitment, there are also key skills, abilities, and talents that individuals should have in this cluster.&#160;Click below to learn more about each one:</p><p>Technical Skills</p><p>Manufacturing professionals need to have technical skills related to machines, tools, and processes. They should understand the fundamentals of engineering, have experience in working with computers and other technical equipment, and be able to troubleshoot any technical issues that arise.</p><p>Problem-Solving Skills</p><p>Manufacturing professionals need to be creative and have strong problem-solving skills. They should be able to identify problems, analyze data, and develop solutions. They should also be able to think critically and come up with better, more efficient ways to do things.</p><p>Communication Skills</p><p>Manufacturing professionals need to have excellent communication skills in order to effectively collaborate with colleagues and customers. They should be able to speak clearly and listen actively in order to build relationships and gain a better understanding of the customer’s needs.</p><p>Decision-Making Abilities</p><p>Manufacturing professionals need to be able to make decisions quickly and accurately, based on their knowledge of the product and customer requirements. They should also be able to evaluate different options and choose the best one for the situation.</p><p>Leadership Skills</p><p>Manufacturing professionals need to be strong leaders who can motivate and inspire their teams. They should be able to delegate tasks, provide guidance, and create a positive working environment.</p><p>Organizational Skills</p><p>Manufacturing professionals need to be organized and can multitask. They should be able to manage their time efficiently and juggle multiple projects at once.</p><p>Attention to Detail</p><p>Manufacturing professionals need to be detail-oriented and can pay close attention to the details of their tasks. They should be able to identify any errors or defects in the product and ensure that the product meets customer requirements.</p><p>What can you do to develop these skills and start preparing for a career in manufacturing?&#160;Click through the slideshow below to learn about what you can do now.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Take applicable classes:&#160;Take courses in math, science, and engineering, as these are essential skills for many positions in the manufacturing industry.&#160;Taking these courses can help to introduce you to the basics of manufacturing and give you an understanding of the concepts and technologies used.</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;5</p><p>Next</p><p>Participate in applicable activities: Participating in extracurricular activities related to manufacturing, such as robotics clubs or engineering competitions, can give you valuable hands-on experience with the tools and processes of the industry.</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;5</p><p>Next</p><p>Learn about the different types of manufacturing: There are many different types of manufacturing, such as plastics, metals, and electronics. Learning about the different types of manufacturing can help students understand the differences between them and give them an idea of the types of jobs they may be interested in.</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;5</p><p>Next</p><p>Develop computer and technology skills: Many positions in manufacturing require the use of computers and technology. Developing computer and technology skills early can help you be better prepared for a job in manufacturing.</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;5</p><p>Next</p><p>Develop an understanding of safety procedures: Learning about safety protocols and understanding the importance of safety in the any setting can help students to be better prepared for a job in manufacturing.</p><p>Previous</p><p>Slide&#160;5&#160;of&#160;5</p><p>Next</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('405559563f1614f4b161b12b439c5796','career-exploration-m13-l6-lesson-5','94623a29ea536a6867da77b1e1189e14','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Education &amp; Training Needed for Manufacturing</h3><p>Education &amp; Training Needed for Manufacturing</p><p>Education and Training Needed for a Career in Manufacturing</p><p>As we have seen with many career clusters, the education and training needed for a career in the Manufacturing career cluster will vary depending on the specific job within the career cluster.&#160;Generally, the education requirements for jobs in the Manufacturing career cluster range from a high school diploma or equivalent to an advanced degree.&#160;Some manufacturing positions may also require specialized certifications or training.</p><p>5</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Training and education needed for the Manufacturing career cluster.</p><p>The hotspot points on the image are as follows:</p><p>PhD</p><p>With a Ph.D., you may be able to get a job in research and development, advanced technology development, or executive management.</p><p>Certification</p><p>Some jobs require or prefer candidates to have a certification. These jobs include certified manufacturing technologist, certified quality inspector, and certified production technician.</p><p>Associate Degree</p><p>With an associate degree, you may be able to get a job in project management, production planning, quality assurance, or process improvement</p><p>High School Diploma</p><p>With a high school diploma, you may be able to get a job in manufacturing as a production worker, machine operator, assembler, or material handler.</p><p>Master&#39;s Degree</p><p>With a master&#39;s degree, you may be able to get a job in advanced manufacturing, industrial engineering, product design, research and development, or strategic planning.</p><p>Bachelor&#39;s degree</p><p>With a bachelor&#39;s degree, you may be able to get a job in design engineering, manufacturing engineering, operations management, product development, or supply chain management.</p><p>See if you can match the description to the most likely education level:</p><p>Mariam is a milling machine operator.</p><p>High school</p><p>Jaden oversees production planning.</p><p>Master&#39;s degree</p><p>Abdullah is a manufacturing technologist.</p><p>PhD</p><p>Sofia is responsible for product development.</p><p>Associate degree</p><p>Kofi was recently hired as an industrial engineer.</p><p>Bachelor&#39;s degree</p><p>Zuri does advanced technology research.</p><p>Certification</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Mariam is a milling machine operator.</p><p>Answers for question: 1</p><p>Associate degree</p><p>Certification</p><p>High school</p><p>PhD</p><p>Master&#39;s degree</p><p>Bachelor&#39;s degree</p><p>2.</p><p>Jaden oversees production planning.</p><p>Answers for question: 2</p><p>Master&#39;s degree</p><p>Certification</p><p>Associate degree</p><p>High school</p><p>PhD</p><p>Bachelor&#39;s degree</p><p>3.</p><p>Abdullah is a manufacturing technologist.</p><p>Answers for question: 3</p><p>Associate degree</p><p>Certification</p><p>High school</p><p>PhD</p><p>Master&#39;s degree</p><p>Bachelor&#39;s degree</p><p>4.</p><p>Sofia is responsible for product development.</p><p>Answers for question: 4</p><p>Master&#39;s degree</p><p>Associate degree</p><p>High school</p><p>Certification</p><p>PhD</p><p>Bachelor&#39;s degree</p><p>5.</p><p>Kofi was recently hired as an industrial engineer.</p><p>Answers for question: 5</p><p>Master&#39;s degree</p><p>PhD</p><p>Associate degree</p><p>Certification</p><p>Bachelor&#39;s degree</p><p>High school</p><p>6.</p><p>Zuri does advanced technology research.</p><p>Answers for question: 6</p><p>PhD</p><p>Bachelor&#39;s degree</p><p>High school</p><p>Certification</p><p>Master&#39;s degree</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('d9f74ca4cf6bfe8dbc0d9a3b06f2f0c3','career-exploration-m13-l7-module-13-summary','94623a29ea536a6867da77b1e1189e14','Module 13 Summary','text',12,'<h2>Module 13 Summary</h2><section><h3>Module 13 Summary</h3><p>Module 13 Summary</p><p>Great Work!&#160;You have successfully completed this module on the Manufacturing career cluster.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified the pathways in the Manufacturing career cluster and the careers in each pathway.</p><p>Described the types of places that employ individuals who have careers in the Manufacturing career cluster.</p><p>Described the variety of tasks performed by individuals who have careers in the Manufacturing career cluster.</p><p>List the skills, abilities, and talents needed for careers in the Manufacturing career cluster.</p><p>Identified the level of training and education required for careers in the Manufacturing career cluster.</p><p>Researched a career in the Manufacturing career cluster and presented findings to the class.</p><p>Applied math, science, and reading skills in the completion of a project or activity related to the Manufacturing career cluster.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('1caf1fc325b34bc0ca1f3c1d728b1a1e','career-exploration-m13-l8-module-13-project','94623a29ea536a6867da77b1e1189e14','Module 13 Project','text',12,'<h2>Module 13 Project</h2><section><h3>Module 13 Project</h3><p>Module 13 Project</p><p>Career Exploration</p><p>Manufacturing - Project</p><p>For this project, you will choose from two options.&#160; You only need to complete one of these options.&#160; Please find both options and their rubrics below.</p><p>Option 1</p><p>For this project, you will design a flowchart of the production process of a product. Follow the steps below to complete the project:</p><p>Start by researching the production process of the desired product. Gather as much information as possible about the process, including any diagrams or visuals that may be available.</p><p>Choose a drawing program to create the flowchart or draw it by hand.</p><p>Add the first step of the process to the document. This can be done by either dragging and dropping a shape from the program&#39;s shape library or manually drawing it.</p><p>Connect the first step to the next step of the process with an arrow.</p><p>Repeat steps 4 and 5 until the entire process is mapped out.</p><p>Add any labels or descriptions to the shapes or arrows to explain the process further.</p><p>Submit the flowchart document or photograph the flowchart if done by hand. If done by hand, be sure that any writing can be read in the photos.</p><p>Review the rubric to see how you will be graded.</p><p>Option 1 Rubric: Manufacturing Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Arrows</p><p>7-8 points The flowchart contains at least 4 arrows.</p><p>5-6 points The flowchart contains at least 3 arrows.</p><p>0-4 points The flowchart contains fewer than 3 arrows.</p><p>8</p><p>Processes Explained</p><p>7-8 points Each process component is identified and well explained.</p><p>5-6 points Most of the process component is identified and mostly well explained.</p><p>0-4 points The process components are not identified and/or well explained.</p><p>8</p><p>Layout</p><p>4 points The layout is neat, tidy, and well-designed.</p><p>3 points The layout is mostly neat, tidy, and well-designed.</p><p>0-2 points The layout is not neat, tidy, and/or well-designed.</p><p>4</p><p>Total Points:&#160;20</p><p>Option 2</p><p>For this option, you will research a particular career that interests you in this cluster. Complete the following steps for your project:</p><p>Step 1: Research your chosen career.</p><p>Step 2: List the following</p><p>Average Salary/Salary Range</p><p>Education Requirements</p><p>Certification Requirements (if any)</p><p>Why you chose that career</p><p>Step 3: Prepare a PowerPoint presentation about your chosen career, including the information you gathered in Step 2 as well as your reason for choosing that career.</p><p>Your final submission should be your PowerPoint containing the information in Step 3.</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 2 Rubric: Manufacturing Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Research</p><p>12 points The student provided a career field that interested them, the average salary or range, and the education/certifications required for the career.</p><p>11-4 points The student provided two of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>3-0 points The student provided one or none of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>12</p><p>Reason for Choosing the Career Field</p><p>4 points The student thoughtfully provided the reason that they are interested in this career.</p><p>N/A</p><p>0 points The student did not provide the reason that they are interested in this career.</p><p>4</p><p>Formatting</p><p>4 points The student&#39;s presentation includes no spelling or grammatical errors.</p><p>3-1 points The student&#39;s presentation includes minimal spelling or grammatical errors.</p><p>0 points The student&#39;s presentation includes a significant amount of spelling or grammatical errors.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('54984447152f233aabcd06025b7ca527','career-exploration-m13-l9-module-13-quiz','94623a29ea536a6867da77b1e1189e14','Module 13 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Manufacturing. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('c1b8d835c131d8f2a49aab6ebb1d2ae3','career-exploration-module-14','68d48b60cc4feb626956ed1fd8311e46','Module 14: Marketing',14) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('6dab17e69b14e76b1bd7fb73b8b22a39','career-exploration-m14-l1-introduction-purpose-and-objectives','c1b8d835c131d8f2a49aab6ebb1d2ae3','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Welcome to this module on the Marketing career cluster.</p><p>You are probably familiar with the term marketing, but let’s quickly define it. Marketing involves all the activities and strategies that companies use to promote and sell their products or services to customers. See a billboard while you’re in the car? That’s marketing! Watch an ad before a video? A marketing professional created that!</p><p>The Marketing career cluster is an exciting and rapidly-growing area! With the advances in technology, marketing opportunities are expanding and becoming even more creative. Professionals in this cluster are in high demand and offer a great career path with a lucrative salary.</p><p>One of the most appealing aspects of a career in marketing is the ability to be creative! Many of the pathways in this career cluster lead to jobs that require problem-solving and creative thinking. From creating content for social media platforms to developing strategies for advertising campaigns, marketing professionals are constantly challenged to think outside the box. With a wide variety of marketing roles available, there is no shortage of ways to apply your creativity. You can use your eye for style to create visually stunning merchandising displays or wow people with your sales presentation.</p><p>In addition to the creative aspects of the cluster, professionals in this field also have the opportunity to make an impact by helping people and businesses reach their goals. Whether you are creating a campaign to help a non-profit organization increase awareness or a strategy to increase sales for a food truck business, the work you do in the Marketing career cluster can help people achieve success.</p><p>The job outlook for professionals in the marketing field is very promising. According to the U.S. Bureau of Labor Statistics, employment in marketing is projected to increase at a faster rate than the average for all occupations. This growth is driven by the need for companies to reach customers through digital platforms and other means. So for those of you that love social media and the internet- you may already be developing your skills!</p><p>Speaking of skills, in this module, you’ll learn about the skills, abilities, and talents that are common for successful professionals.</p><p>The Marketing career cluster is also great if you like to stay up-to-date with the latest trends and enjoy a challenge. As technology continues to evolve, marketing professionals must keep up with the changing landscape. This means that there will always be new challenges and opportunities for those in the marketing field. Every new major communication technology, from radio and tv, to the internet and virtual reality, has created new opportunities in marketing.</p><p>In this module, we’ll talk about the education and training you’ll need to get started. From high school jobs to earning a degree in marketing, there are several paths to pursue. With the right education and experience, you can become an expert in the field and have a successful career.</p><p>From the creative opportunities to the job growth potential, the marketing career cluster is a great career option, so let’s look more closely at this exciting career cluster!</p><p>Module Description</p><p>Creative Commons&#160;is licensed under&#160;CC BY-SA 4.0(opens in a new tab).</p><p>Welcome to this module on the Marketing career cluster!&#160;In this module, you will discover the various pathways in this cluster and some of the jobs associated with each pathway.&#160;Next, we will discuss the types of places that employ individuals in this field.&#160;This is a growing career cluster, which means there are a lot of organizations looking to hire people with knowledge in this career cluster!&#160;The module will explain the different tasks that someone in this career cluster may perform on a regular basis.&#160;You will also learn about the skills, abilities, and talents needed for careers.&#160;We will also discuss the different requirements in training and education for some of the common jobs in this career cluster.&#160;The module will conclude with a project designed to help you explore the Marketing career cluster in more depth.</p><p>Objectives</p><p>In this module, students will</p><p>Identify the pathways in the Marketing career cluster and the careers in each pathway.</p><p>Describe the types of places that employ individuals who have careers in the Marketing career cluster.</p><p>Describe the variety of tasks performed by individuals who have careers in the Marketing career cluster.</p><p>List the skills, abilities, and talents needed for careers in the Marketing career cluster.</p><p>Identify the level of training and education required for careers in the Marketing career cluster.</p><p>Research a career in the Marketing career cluster and present findings to the class.</p><p>Apply math, science, and reading skills in the completion of a project or activity related to the Marketing career cluster.</p><p>Polling Question</p><p>Which of the careers in the Marketing career cluster sounds most interesting to you?</p><p>Creative director&#160;Social media manager&#160;Salesperson&#160;Merchandise buyer&#160;Other</p><p>Results:</p><p>Merchandise buyer&#160;100%</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>The activity of trying to get people to buy a product or service.</p><p>Campaign</p><p>Any item that is bought or sold, like clothes, toys, or electronics.</p><p>Merchandise</p><p>The activity of creating a good relationship between a company and the public, like through advertising and events.</p><p>Publicity</p><p>A plan of action to achieve a particular goal, like to get more people to buy a product.</p><p>Marketing</p><p>The activity of trying to get people to know about a product or service, like through media coverage or events.</p><p>Public Relations (PR)</p><p>The activity of writing text for advertisements, websites, and other promotional materials.</p><p>Copywriting</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>The activity of trying to get people to buy a product or service.</p><p>Answers for question: 1</p><p>Campaign</p><p>Public Relations (PR)</p><p>Marketing</p><p>Co<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('a6a806a5872954680cbf2886a55a9743','career-exploration-m14-l2-lesson-1','c1b8d835c131d8f2a49aab6ebb1d2ae3','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>What is Marketing Career Cluster</h3><p>What is Marketing Career Cluster</p><p>What is the Marketing Career Cluster?</p><p>The marketing career cluster includes jobs related to planning, managing, and performing marketing activities to help businesses and organizations meet their goals.&#160;This includes activities such as market research, pricing, advertising, public relations, product development, distribution, customer service, and sales.&#160;Those in this career cluster typically work within the marketing or sales departments of a business or organization.</p><p>Click on the hotspots below to learn more about the pathways in this career cluster.</p><p>0</p><p>5</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Pathways in the Marketing career cluster.</p><p>The hotspot points on the image are as follows:</p><p>Marketing Research Pathway</p><p>Having data is crucial to marketing efforts. In the marketing research pathway, people utilize surveys, polls, and market analysis to find out what people need and how to make sure companies are meeting those needs. Professionals in this pathway include forecasting managers, marketing analysts, and database analysts.</p><p>Marketing Management Pathway</p><p>This pathway focuses on planning and leading marketing activities, like setting prices, deciding what products to sell, and creating advertising campaigns. People in this pathway lead and direct much of the business operations. Jobs in this pathway include brand manager, strategic planner, and marketing services manager.</p><p>Marketing Communications Pathway</p><p>This pathway focuses on using different media, like television, radio, and the internet, to get the word out about a product or service. They plan, coordinate and follow through on marketing strategies, advertisements, promotions, and public relations activities. This includes jobs like creative director, advertising manager, and public relations manager.</p><p>Merchandising Pathway</p><p>Professionals in this pathway work to help get consumers to pay attention to products. This includes planning, buying, and displaying merchandise. Jobs in this pathway include visual merchandise manager, merchandise buyer, and receiving clerk.</p><p>Professional Sales Pathway</p><p>This pathway is primarily concerned with presenting products or services to potential customers by making persuasive presentations, negotiating contracts, and finding potential new customers. This includes business-to-business sales and business-to-individual consumer sales. Professionals in this pathway include account executives, salespersons, and telemarketers.</p><p>Career</p><p>Pathway</p><p>Brand manager</p><p>Marketing research pathway</p><p>Strategic planner</p><p>Merchandising pathway</p><p>Account executive</p><p>Professional sales pathway</p><p>Salesperson</p><p>Merchandising pathway</p><p>Merchandise buyer</p><p>Marketing communications pathway</p><p>Receiving clerk</p><p>Marketing management pathway</p><p>Creative director</p><p>Marketing management pathway</p><p>Public relations manager</p><p>Professional sales pathway</p><p>Marketing analyst</p><p>Marketing communications pathway</p><p>Database analyst</p><p>Marketing research pathway</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Brand manager</p><p>Answers for question: 1</p><p>Professional sales pathway</p><p>Marketing research pathway</p><p>Marketing communications pathway</p><p>Merchandising pathway</p><p>Marketing management pathway</p><p>Professional sales pathway</p><p>Marketing research pathway</p><p>Merchandising pathway</p><p>Marketing management pathway</p><p>2.</p><p>Strategic planner</p><p>Answers for question: 2</p><p>Professional sales pathway</p><p>Marketing communications pathway</p><p>Merchandising pathway</p><p>Marketing management pathway</p><p>Marketing research pathway</p><p>Marketing management pathway</p><p>Professional sales pathway</p><p>Marketing communications pathway</p><p>3.</p><p>Account executive</p><p>Answers for question: 3</p><p>Marketing research pathway</p><p>Merchandising pathway</p><p>Marketing communications pathway</p><p>Marketing research pathway</p><p>Professional sales pathway</p><p>Marketing management pathway</p><p>Marketing communications pathway</p><p>Professional sales pathway</p><p>Merchandising pathway</p><p>Marketing management pathway</p><p>4.</p><p>Salesperson</p><p>Answers for question: 4</p><p>Professional sales pathway</p><p>Marketing communications pathway</p><p>Marketing management pathway</p><p>Marketing communications pathway</p><p>Merchandising pathway</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('42ad2cd59fe0799c80a7c9114cfce63f','career-exploration-m14-l3-lesson-2','c1b8d835c131d8f2a49aab6ebb1d2ae3','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Where Marketing Professionals Work</h3><p>Where Marketing Professionals Work</p><p>Where Professionals in the Marketing Career Cluster Work</p><p>Organizations of all types are looking to work with professionals who can help them grow.&#160;Because of this, marketing professionals have lots of options available to them when it comes to where to work.</p><p>Click on the tabs to learn more about each potential place of employment:</p><p>Advertising Agencies</p><p>Advertising agencies are companies that specialize in creating and managing marketing campaigns for their clients.&#160;They help clients develop advertising strategies, create ads, and manage campaigns on various media platforms.</p><p>Corporations</p><p>Large corporations often employ marketing professionals to help promote products or services, develop marketing plans and strategies, and analyze how effective the marketing strategies have been.</p><p>Non-Profit Organizations</p><p>Non-profit organizations, such as charities and advocacy groups, often hire marketing professionals to help promote their mission and raise awareness of their cause.</p><p>Public Relations Firms</p><p>Public relations firms specialize in creating and managing relationships between a company and its audience such as customers, investors, and the media. They are responsible for managing public relations campaigns and creating media materials.</p><p>Media Companies</p><p>Media companies employ marketing professionals to help create and manage campaigns on various media platforms. They are responsible for developing advertising strategies, creating ads, and managing campaigns.</p><p>Government Agencies</p><p>Government agencies often hire marketing professionals to help promote policies and programs, develop public service announcements, and create and manage campaigns.</p><p>Next Tab</p><p>Marketing is a great way to combine interests.&#160;In fact, your other talents and interests may set you apart from other candidates when applying for a job.&#160;For example, if a woodworking business was looking to hire someone to help with their marketing efforts, someone who does woodworking as a hobby would already know the terminology and techniques, making it easier to create marketing content that woodworkers like.&#160;Think about how you could combine some of your interests in this career cluster.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('65cc680a76a7fac95d8aa8127dc7c5dc','career-exploration-m14-l4-lesson-3','c1b8d835c131d8f2a49aab6ebb1d2ae3','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Activities for Marketing Career ppl</h3><p>Activities for Marketing Career ppl</p><p>Tasks Performed by Individuals who have Careers in the Marketing Career Cluster</p><p>It takes a lot of work to help a company grow.&#160;Here are some of the activities that people in the Marketing career cluster may perform:</p><p>Developing and executing marketing campaigns</p><p>Making plans and carrying them out to spread the word about a product or service.</p><p>Creating content for social media</p><p>Writing and posting messages, pictures, and videos to social media sites.</p><p>Building and managing a company&#39;s online presence</p><p>Making sure that the company’s website and social media accounts are up-to-date and working properly.</p><p>Creating marketing materials</p><p>Designing materials such as brochures, catalogs, and flyers with text and images that show off a product or service to customers.</p><p>Analyzing customer data</p><p>Looking at customer information to figure out the best way to reach them.</p><p>Customer relations</p><p>Making connections with people who might be interested in the product or service and staying in touch with those who have already purchased.</p><p>Developing and presenting sales presentations</p><p>Putting together a speech or video to show how a product or service can be helpful.</p><p>Negotiating and closing sales deals</p><p>Talking with customers to agree on a price and making sure that the transaction is complete.</p><p>Tracking sales and providing reports on performance</p><p>Following up with customers and keeping records of how well the product or service is doing.</p><p>Managing inventory</p><p>Keeping track of the product or service so there is always enough to meet customer needs.</p><p>Visual merchandising</p><p>Arranging products and displays in a store so that they look inviting and attractive.</p><p>As you can see, there is a lot of variety in activity in this career cluster.&#160;Some of the tasks require creativity while others require analysis.&#160;However, all of the activities contribute to the growth and functionality of the organization.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f0d14d3d149ad0601d70ccba510c5605','career-exploration-m14-l5-lesson-4','c1b8d835c131d8f2a49aab6ebb1d2ae3','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Skills Needed for Marketing Careers</h3><p>Skills Needed for Marketing Careers</p><p>Skills, Abilities, and Talents Needed for a Career in the Marketing Career Cluster</p><p>Success in the Marketing career cluster doesn’t happen without developing certain skills, abilities, and talents.&#160;While the exact skills needed will depend on the specific job, here are some of the common ones needed for this career cluster:</p><p>Communication Skills</p><p>The ability to effectively communicate with clients, colleagues, and the public is essential for success in the marketing career cluster. This includes both verbal and written communication, as well as the ability to present ideas and products to customers.</p><p>Analytical Skills</p><p>Being able to analyze data, spot trends, and understand the needs of customers is a key skill for helping companies grow. This includes the ability to understand market research, consumer trends, and customer behaviors.</p><p>Negotiation Skill</p><p>The ability to negotiate deals with customers and suppliers is critical in the marketing career cluster, especially jobs that center on sales. Being able to secure the best prices for products and services, as well as being able to close sales deals is important for success.</p><p>Time Management</p><p>There are a lot of components to successful marketing campaigns and efforts, so being able to manage time efficiently is essential. This includes the ability to prioritize tasks, as well as be able to multitask and stay organized.</p><p>Creative Thinking</p><p>Professionals in this career cluster must have the ability to come up with innovative solutions to problems. They also need creative thinking to create effective campaigns and strategies to increase sales.</p><p>Leadership Skills</p><p>Being able to lead teams and projects is essential for the leaders in this career cluster. This includes being able to delegate tasks, as well as motivating and inspiring others.</p><p>Networking Skills</p><p>The ability to build relationships with customers, partners, and other professionals is a valuable skill in the marketing career cluster. This includes the ability to create and maintain professional relationships, as well as being able to identify new opportunities.</p><p>Problem-Solving Skills</p><p>Growing a brand is a complex issue. People in this career cluster need to quickly identify problems and develop solutions, as well as be able to think critically and strategically.</p><p>Social Media Knowledge</p><p>Understanding how to use social media platforms is a key skill in today’s marketing world. This includes the ability to create and manage campaigns, as well as understanding how to best reach target audiences.</p><p>Technical Skills</p><p>Professionals in this career cluster often utilize technology programs such as Microsoft Office and Adobe Creative Suite. They use these programs for tasks such as media design, presentation creation, and copywriting.</p><p>See if you can match the situation to the skill needed:</p><p>Skill</p><p>Quinn has been asked to give a presentation and must clearly and concisely explain the purpose of the business and how it can help the prospect.</p><p>Problem-Solving</p><p>Serena’s team is going over the sales data of the past quarter in order to formulate a new data-drive plan for the next quarter.</p><p>Networking skills</p><p>Jaxon has been sent to finalize the price of services with a new client to ensure both sides are happy.</p><p>Time management</p><p>Arya is the team leader for a new PR campaign and needs to get her team excited and organized about the project.</p><p>Negotiation skills</p><p>Phoenix’s supervisor gave him a deadline for a project that is going to be tough to meet.</p><p>Analytical skills</p><p>Elias needs to introduce himself and his new business to the other established businesses in the area to form partnerships and referrals.</p><p>Social media knowledge</p><p>Nova just found out that a team member is going to be out sick for an extended period of time and now the team must figure out how to get everything done without this teammate.</p><p>Technical skills</p><p>The CEO has asked Caleb to come up with a new design for the company’s booth at a tradeshow.&#160;The design must be eye-catching, appealing, and different from the other booths.</p><p>Leadership skills</p><p>Remi needs to come up with a strategy for how to get more followers on Instagram.</p><p>Communication skills</p><p>Quinn is designing a brochure for the hotel she works for using Adobe InDesign.</p><p>Creative thinking</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Quinn has been asked to give a presentation and must clearly and concisely explain the purpose of the business and how it can help the prospect.</p><p>Answers for question: 1</p><p>Technical skills</p><p>Communication skills</p><p>Time management</p><p>Social media knowledge</p><p>Problem-Solving</p><p>Negotiation skills</p><p>Creative thinking</p><p>Leadership skills</p><p>Analytical skills</p><p>Networking skills</p><p>2.</p><p>Serena’s team is going over the sales data of the past quarter in order to formulate a new data-drive plan for the next quarter.</p><p>Answers for question: 2</p><p>Networking skills</p><p>Analytical skills</p><p>Social media knowledge</p><p>Communication skills</p><p>Technical skills</p><p>Creative thinking</p><p>Problem-Solving</p><p>Leadership skills</p><p>Negotiation skills</p><p>Time management</p><p>3.</p><p>Jaxon has been sent to finalize the price of services with a new client to ensure both sides are happy.</p><p>Answers for question: 3</p><p>Problem-Solving</p><p>Time management</p><p>Negotiation skills</p><p>Social media knowledge</p><p>Communication skills</p><p>Networking skills</p><p>Analytical skills</p><p>Creative thinking</p><p>Leadership skills</p><p>Technical skills</p><p>4.</p><p>Arya is the team leader for a new PR campaign and needs to get her team excited and organized about the project.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('16bc8c5204e8ff57913a2ca87b160638','career-exploration-m14-l6-lesson-5','c1b8d835c131d8f2a49aab6ebb1d2ae3','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Training &amp; Education Requirements for Marketing</h3><p>Training &amp; Education Requirements for Marketing</p><p>Training and Education Requirements</p><p>Because the Marketing Career Cluster is so broad and includes a variety of jobs, the education needed depends on the specific job.&#160;Here are some professions in this career cluster and the education and training typical to that job.</p><p>Click on the tabs to learn more:</p><p>Sales Representative</p><p>A Sales Representative typically needs a high school diploma or equivalent, with some sales experience preferred.&#160;Additional training may include on-the-job training or a degree in marketing or business.</p><p>Marketing Manager</p><p>A Marketing Manager typically needs a bachelor&#39;s degree in marketing, communications, or a related field, as well as five or more years of experience in marketing management.</p><p>Merchandiser</p><p>A Merchandiser typically needs a high school diploma or GED, as well as one to two years of experience in retail sales or merchandising. Additional training may include on-the-job training or a diploma in visual merchandising.</p><p>Sales Manager</p><p>A Sales Manager typically needs a bachelor&#39;s degree in marketing, business, or a related field, as well as five or more years of experience in sales and/or sales management.</p><p>Digital Marketer</p><p>A Digital Marketer typically needs a bachelor&#39;s degree in marketing, communications, or a related field, as well as three or more years of experience in digital marketing and/or social media management.</p><p>Business Development Manager</p><p>A Business Development Manager typically needs a bachelor&#39;s degree in business, marketing, or a related field, as well as five or more years of experience in sales and/or business development.</p><p>Social Media Manager</p><p>A Social Media Manager typically needs a bachelor&#39;s degree in marketing, communications, or a related field, as well as three or more years of experience in social media management.</p><p>Account Executive</p><p>An Account Executive typically needs a bachelor&#39;s degree in marketing, communications, or a related field, as well as three or more years of experience in sales and/or account management.</p><p>Retail Sales Associate</p><p>A Retail Sales Associate typically needs a high school diploma or GED, as well as one to two years of experience in retail sales or customer service. Entry-level positions may be open to high school students. Additional training may include on-the-job training or a diploma in retail sales.</p><p>Public Relations Manager</p><p>A Public Relations Manager typically needs a bachelor&#39;s degree in public relations, communications, or a related field, as well as three or more years of experience in public relations and/or communications management.</p><p>Next Tab</p><p>As you can see, in addition to training and education, experience plays an important role in qualifying for many of these positions.&#160;You don’t have to wait until college to start gaining experience.&#160;Here are some things you can do right now:</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Participate in a business club.</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;5</p><p>Next</p><p>(opens in a new tab)</p><p>Promote activities and events at your school.</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;5</p><p>Next</p><p>Study how businesses currently use social media in their marketing efforts.</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;5</p><p>Next</p><p>Practice designing promotional materials.</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;5</p><p>Next</p><p>Talk to people in the Marketing career cluster.</p><p>Previous</p><p>Slide&#160;5&#160;of&#160;5</p><p>Next</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e57829034492749352e5f2e8afa14d6f','career-exploration-m14-l7-module-14-summary','c1b8d835c131d8f2a49aab6ebb1d2ae3','Module 14 Summary','text',12,'<h2>Module 14 Summary</h2><section><h3>Module 14 Summary</h3><p>Module 14 Summary</p><p>Great Work!&#160;You have successfully completed this module on&#160;the Marketing Career Cluster.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified the pathways in the Marketing career cluster and the careers in each pathway.</p><p>Described the types of places that employ individuals who have careers in the Marketing career cluster.</p><p>Described the variety of tasks performed by individuals who have careers in the Marketing career cluster.</p><p>Listed the skills, abilities, and talents needed for careers in the Marketing career cluster.</p><p>Identified the level of training and education required for careers in the Marketing career cluster.</p><p>Researched a career in the Marketing career cluster and presented findings to the class.</p><p>Applied math, science, and reading skills in the completion of a project or activity related to the Marketing career cluster.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('70a57f460e6603f74313cb30117d9f37','career-exploration-m14-l8-module-14-project','c1b8d835c131d8f2a49aab6ebb1d2ae3','Module 14 Project','text',12,'<h2>Module 14 Project</h2><section><h3>Module 14 Project</h3><p>Module 14 Project</p><p>Career Exploration</p><p>Marketing - Project</p><p>For this project, you will choose from two options.&#160; You only need to complete one of these options.&#160; Please find both options and their rubrics below.</p><p>Option 1</p><p>For this project, imagine you are the social media manager for a new shoe company. Complete the following:</p><p>Write up a company overview that includes the name of the company, the type(s) of shoes, and the target audience (the type of person that the company is trying to sell the shoes to).</p><p>Draft 5 social media posts and include the following:</p><p>A description of the image or video</p><p>The copy (written part) for each post</p><p>Which social media site(s) where it will be posted</p><p>Why you think this would be a good post for the company</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 1 Rubric: Marketing Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Company Write Up</p><p>5 points Write up is well crafted and thoroughly explains the company.</p><p>3-4 Write up is somewhat well crafted and mostly explains the company.</p><p>0-2 points Write up is not well crafted and/or doesn&#39;t explain the company.</p><p>5</p><p>Posts</p><p>13-15 points All five posts contain all the information requested in the bullet points.</p><p>9-12 points All five posts contain most of the information requested in the bullet points.</p><p>0-8 points Does not have all five posts and/or significant amounts of information are missing.</p><p>15</p><p>Total Points:&#160;20</p><p>Option 2</p><p>For this option, you will research a particular career that interests you in this cluster. Complete the following steps for your project:</p><p>Step 1: Research your chosen career.</p><p>Step 2: List the following</p><p>Average Salary/Salary Range</p><p>Education Requirements</p><p>Certification Requirements (if any)</p><p>Why you chose that career</p><p>Step 3: Prepare a PowerPoint presentation about your chosen career, including the information you gathered in Step 2 as well as your reason for choosing that career.</p><p>Your final submission should be your PowerPoint containing the information in Step 3.</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 2 Rubric: Marketing Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Research</p><p>12 points The student provided a career field that interested them, the average salary or range, and the education/certifications required for the career.</p><p>11-4 points The student provided two of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>3-0 points The student provided one or none of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>12</p><p>Reason for Choosing the Career Field</p><p>4 points The student thoughtfully provided the reason that they are interested in this career.</p><p>N/A</p><p>0 points The student did not provide the reason that they are interested in this career.</p><p>4</p><p>Formatting</p><p>4 points The student&#39;s presentation includes no spelling or grammatical errors.</p><p>3-1 points The student&#39;s presentation includes minimal spelling or grammatical errors.</p><p>0 points The student&#39;s presentation includes a significant amount of spelling or grammatical errors.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('bc3cb62337d6c04f8572b2b29fbd53d9','career-exploration-m14-l9-module-14-quiz','c1b8d835c131d8f2a49aab6ebb1d2ae3','Module 14 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Marketing. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('5aa9264075f0af723d8f29be7778be7c','career-exploration-module-15','68d48b60cc4feb626956ed1fd8311e46','Module 15: STEM',15) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3bf5152cb70c1ff74fa080f1da24cd5a','career-exploration-m15-l1-introduction-purpose-and-objectives','5aa9264075f0af723d8f29be7778be7c','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Welcome to this module on the Science, Technology, Engineering &amp; Mathematics career cluster.</p><p>Science, technology, engineering &amp; mathematics is a mouthful to say! Luckily, someone along the way had the clever idea to refer to it collectively as STEM.</p><p>STEM is an increasingly important field of study. STEM careers are some of the most in-demand jobs today, and they are projected to continue to be sought after for years to come. As someone who hasn’t started a career yet, you have a unique opportunity to start learning and exploring STEM fields! STEM careers offer many exciting possibilities. You could become a computer scientist, who designs and builds the world’s new innovative technology. Or, you could be an engineer, designing and constructing bridges, buildings, and other structures. You could even become a mathematician, helping to solve complex problems. STEM fields are also incredibly important for the future. STEM careers are essential to helping us solve some of the world’s most pressing problems, like climate change, poverty, and disease. With a STEM career, you could be part of a team that finds solutions to global problems and makes a positive impact on the world.</p><p>It&#39;s also worth mentioning that STEM careers can be financially rewarding. Many STEM jobs offer competitive salaries and growth opportunities. You can also use your STEM knowledge to start your own business or to invent new products and technologies. There are two main pathways in this career cluster: The Engineering and Technology Pathway and the Science and Mathematics Pathway. We’ll dig into both of these clusters in this module. We’ll also explore some of the professions included in these pathways and where someone in this cluster might find work. And of course, we’ll give you an idea of some of the activities professionals in this cluster perform.</p><p>We’ll round out the module by discussing the skills, talents, and abilities necessary for STEM careers. Education is very rigorous in STEM and a big component of STEM careers, so you’ll definitely want to pay attention to that lesson!</p><p>I hope you are excited to learn more about the STEM career cluster! Let’s get going.</p><p>Module Description</p><p>Welcome to this module on the Science, Technology, Engineering &amp; Mathematics (STEM) career cluster!&#160;In this module, you will discover the various pathways in this cluster and some of the jobs associated with each pathway.&#160;Next, we will discuss the types of places that employ individuals in this field and the variety of tasks they perform, each task contributing to new developments and advancements.&#160;You will also learn about the skills, abilities, and talents needed for careers in this field and how you can start developing these skills now.&#160;We will also discuss one of the most crucial aspects of this career cluster- training and education.&#160;The module will conclude with a project designed to help you gain hands-on experience in STEM.</p><p>Objectives</p><p>In this course, students will</p><p>Identify the pathways in Science, Technology, Engineering, &amp; Mathematics.</p><p>Describe the types of places that employ individuals who have careers in Science, Technology, Engineering, &amp; Mathematics.</p><p>Describe the variety of tasks performed by individuals who have careers in Science, Technology, Engineering, &amp; Mathematics.</p><p>List the skills, abilities, and talents needed for careers in Science, Technology, Engineering, &amp; Mathematics.</p><p>Identify the level of training and education required for careers in Science, Technology, Engineering, &amp; Mathematics.</p><p>Research a career in Science, Technology, Engineering, &amp; Mathematics and present findings to the class.</p><p>Apply math, science, and reading skills in the completion of a project or activity related to Science, Technology, Engineering, &amp; Mathematics.</p><p>Polling Question</p><p>Which career in the STEM career cluster sounds most interesting to you?</p><p>Biomedical Engineer&#160;Computer Engineer&#160;Geneticist&#160;Astronomer&#160;Archeologist&#160;Other</p><p>Results:</p><p>Computer Engineer&#160;50%</p><p>Biomedical Engineer&#160;50%</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Warning:&#160;json_decode() expects parameter 1 to be string, object given in&#160;/srv/app/current/blocks/interactive_definitions/controller.php&#160;on line&#160;238</p><p>using science and math to solve problems in the world and build things.</p><p>Engineering</p><p>a set of instructions that you can use to solve a problem or accomplish a task.</p><p>Algorithm</p><p>a rough draft or model of something that will eventually be made into a more complete product.</p><p>Robotics</p><p>the study and use of machines that can move and do things by themselves, with no help from people.</p><p>Technical</p><p>relating to the use of machines, computers, and other kinds of technology.</p><p>Prototype</p><p>related to the study of biology and medicine, and how the two fields can be used together.</p><p>Biomedical</p><p>a scientist who studies genes and how they affect people&#39;s health, traits, and development.</p><p>Geneticist</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>using science and math to solve problems in the world and build things.</p><p>Answers for question: 1</p><p>Engineering</p><p>Algorithm</p><p>Biomedical</p><p>Prototype</p><p>Technical</p><p>Geneticist</p><p>Robotics</p><p>2.</p><p>a set of instructions that you can use to solve a problem or accomplish a task.</p><p>Answers for question: 2</p><p>Prototype</p><p>Robotics</p><p>Algorithm</p><p>Biomedical</p><p>Engineering</p><p>Geneticist</p><p>Technical</p><p>3.</p><p>a rough draft or model of something that will eventually be made into a more complete product.</p><p>Answers for question: 3</p><p>Geneticist</p><p>Technical</p><p>Biomedical</p><p>Robotics</p><p>Prototype</p><p>Algorithm</p><p>Engineering</p><p>4.</p><p>the study and use of machines that can move and do things by themselves, with no help from people.</p><p>Answers for question: 4</p><p>Algorithm</p><p>Biomedical</p><p>Geneticist</p><p>Technical</p><p>Robotics</p><p>Prototype</p><p>Engineering<<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f03bae8f366c6ae633d95ffb4f5375c1','career-exploration-m15-l2-lesson-1','5aa9264075f0af723d8f29be7778be7c','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>What is STEM Career Cluster</h3><p>What is STEM Career Cluster</p><p>What is the Science, Technology, Engineering &amp; Mathematics Career Cluster?</p><p>The Science, Technology, Engineering, and Math (STEM) career cluster is a group of careers that involve using science, technology, engineering, and math in the real world.&#160;STEM careers are all around us and involve solving problems and creating things to make our lives better.&#160;In a STEM career, you might be a scientist, researching new medicines to treat illnesses, a technology specialist, helping to create new apps and websites, an engineer, designing bridges or buildings, or a mathematician, analyzing data to make predictions.</p><p>Click on the image below to learn about the two pathways in this career cluster:</p><p>5</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Pathways in the STEM career cluster</p><p>The hotspot points on the image are as follows:</p><p>Engineering &amp; Technology Pathway</p><p>This pathway involves learning about how to use technology to solve problems. It could involve building machines or computer programs or designing products like cars or buildings. Some of the jobs in this career pathway include civil engineer, computer engineer, and nuclear engineer.</p><p>Science &amp; Mathematics Pathway</p><p>This pathway involves learning about science and math to understand the world around us. It could involve learning about different animals and plants, the stars and planets, or how to use math to solve problems. Professionals in this pathway include marine biologists, astronomers, and statisticians.</p><p>Now that you’ve learned about the pathways, see if you can match the job to the correct pathway.&#160; Drag the card to the correct pathway:</p><p>If you are using a keyboard to navigate, you must use the following alternative activity to receive credit.</p><p>Engineering &amp; Technology Pathway</p><p>Science &amp; Mathematics Pathway</p><p>Alternative Activity</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('d5369109f6e2f830320fa8ae6a881d93','career-exploration-m15-l3-lesson-2','5aa9264075f0af723d8f29be7778be7c','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Were STEM Career ppl Work</h3><p>Were STEM Career ppl Work</p><p>Where People in the STEM Career Cluster Work</p><p>Professionals in the STEM career cluster have a variety of employment opportunities.&#160;Here are some of the common places that employ professionals in this career cluster.&#160;Click on each tab to learn more:</p><p>Colleges and Universities</p><p>Colleges and universities are the most common place to find professionals in the STEM career cluster.&#160;Professors and researchers in these institutions are typically engaged in research and teaching in STEM-related fields.</p><p>Government Agencies</p><p>Government agencies such as the National Aeronautics and Space Administration (NASA), National Institutes of Health (NIH), and the Department of Defense (DoD) are major employers of professionals in the STEM career cluster. These agencies often hire scientists, engineers, and other technical professionals to conduct research, develop new technologies, and solve challenging problems.</p><p>Private Companies</p><p>Private companies are another major source of employment for professionals in the STEM career cluster. Companies in a variety of industries, including biotechnology, aerospace, and computer technology, often hire professionals with STEM backgrounds to develop new products and services.</p><p>Research and Development Firms</p><p>Research and development firms are another important source of employment for professionals in the STEM career cluster. These firms specialize in scientific and technical research and often employ scientists, engineers, and other technical professionals to work on specific projects.</p><p>Nonprofit Organizations</p><p>Nonprofit organizations, such as research institutes and foundations, are also a major source of employment for professionals in the STEM career cluster. These organizations often hire scientists, engineers, and other technical professionals to conduct research and develop new technologies.</p><p>Next Tab</p><p>No matter where they work, professionals in the STEM career cluster help us understand the world around us better, create new products and inventions, and create better infrastructure.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('563a54c2b99991f9c91dad731819667a','career-exploration-m15-l4-lesson-3','5aa9264075f0af723d8f29be7778be7c','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Activities in STEM Career Cluster</h3><p>Activities in STEM Career Cluster</p><p>Activities in the STEM Career Cluster</p><p>STEM professionals are often driven by a sense of curiosity and a desire to make sense of the world around them.&#160;This is the fuel behind many of the activities these professionals perform.&#160;Although the activities performed differs according to specific jobs, here are some of the common activities.</p><p>Click to learn more about each one:</p><p>Analyzing Data</p><p>STEM professionals analyze and interpret data to identify patterns, trends, and relationships to solve problems.</p><p>Developing Algorithms</p><p>STEM professionals create algorithms and software programs to automate processes and tasks.</p><p>Designing Experiments</p><p>STEM professionals design experiments to test hypotheses and uncover new knowledge.</p><p>Troubleshooting</p><p>STEM professionals use their knowledge and experience to identify and solve problems.</p><p>Coding</p><p>STEM professionals write code to create applications, software, and websites.</p><p>Visualizing Data</p><p>STEM professionals create visualizations of data, such as charts and graphs, to better understand and analyze it.</p><p>Programming Robots</p><p>STEM professionals program robots and other machines to perform tasks and functions.</p><p>Prototyping</p><p>STEM professionals create physical prototypes of products and systems to test their functionality.</p><p>Research</p><p>STEM professionals use and conduct research to help us understand the world around us.</p><p>Match the situation to the correct activity:</p><p>Warning:&#160;json_decode() expects parameter 1 to be string, object given in&#160;/srv/app/current/blocks/interactive_definitions/controller.php&#160;on line&#160;238</p><p>Activity</p><p>Keenan is creating the first version of his new invention.</p><p>Coding</p><p>Morgan is developing an internal programming system for an automatic vacuum cleaner.</p><p>Troubleshooting</p><p>Sophie is creating a chart showing the bald eagle population over the past 5 years.</p><p>Prototyping</p><p>Tomas is developing a new app.</p><p>Programming robots</p><p>Ava is trying to determine what is causing a glitch in a new app.</p><p>Visualizing data</p><p>Cory and Lola want to test their hypothesis about adding sulfate to the soil.</p><p>Analyzing data</p><p>Tan is setting up a workflow that will correctly sort his inbox without him having to do it himself.</p><p>Designing experiments</p><p>Ando is reviewing the data from a recent study.</p><p>Research</p><p>Lea wants to figure out what material would be best for the new robot she is working on and decides to read articles and studies about different options.</p><p>Developing algorithms</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Keenan is creating the first version of his new invention.</p><p>Answers for question: 1</p><p>Research</p><p>Programming robots</p><p>Developing algorithms</p><p>Visualizing data</p><p>Coding</p><p>Designing experiments</p><p>Prototyping</p><p>Analyzing data</p><p>Troubleshooting</p><p>2.</p><p>Morgan is developing an internal programming system for an automatic vacuum cleaner.</p><p>Answers for question: 2</p><p>Programming robots</p><p>Research</p><p>Coding</p><p>Analyzing data</p><p>Developing algorithms</p><p>Troubleshooting</p><p>Designing experiments</p><p>Visualizing data</p><p>Prototyping</p><p>3.</p><p>Sophie is creating a chart showing the bald eagle population over the past 5 years.</p><p>Answers for question: 3</p><p>Analyzing data</p><p>Research</p><p>Developing algorithms</p><p>Prototyping</p><p>Troubleshooting</p><p>Visualizing data</p><p>Programming robots</p><p>Coding</p><p>Designing experiments</p><p>4.</p><p>Tomas is developing a new app.</p><p>Answers for question: 4</p><p>Coding</p><p>Designing experiments</p><p>Research</p><p>Visualizing data</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('e2048eab02395b8cfded26d27dc50278','career-exploration-m15-l5-lesson-4','5aa9264075f0af723d8f29be7778be7c','Lesson 4','text',12,'<h2>Lesson 4</h2><section><h3>Skills Needed for STEM Careers</h3><p>Skills Needed for STEM Careers</p><p>Skills, Abilities, and Talents Needed for a Career in STEM</p><p>Skills, abilities, and talents are important to careers in STEM for a variety of reasons.&#160;First, these traits are often necessary in order to properly perform the tasks associated with a STEM job, such as problem-solving, analytical thinking, and a willingness to push boundaries.&#160;Additionally, having a broad set of skills, abilities, and talents can help you stand out from other applicants and give you the edge when competing for jobs in the STEM field.&#160;Finally, having a well-rounded skillset can help you stay ahead of the curve and be productive in a rapidly changing and advancing field.</p><p>Here are some of the common skills, abilities, and&#160; talents needed in the STEM career cluster:</p><p>Problem-solving</p><p>Problem-solving is an essential skill in STEM careers. Many of the careers in this field focus on identifying and solving issues quickly and effectively.</p><p>Analytical Skills</p><p>Analytical skills are needed to interpret data and make informed decisions.</p><p>Creativity</p><p>Creativity is important for STEM careers as it allows individuals to come up with innovative solutions to problems.</p><p>Communication Skills</p><p>Individuals in STEM careers need to collaborate effectively with their teams, peers, and decision-makers in organizations.</p><p>Leadership</p><p>Many projects undertaken in this career cluster are done by a team. Because of this, leadership is important in STEM careers as it allows individuals to lead projects and teams effectively.</p><p>Technical Knowledge</p><p>Technical knowledge is essential for STEM careers as it allows individuals to understand and use the latest technologies to solve problems.</p><p>Research Skills</p><p>Research skills are important for STEM careers because this is how individuals find and analyze data to make informed decisions.</p><p>Collaboration</p><p>Collaboration is important in STEM careers as it allows individuals to work together to find innovative solutions to problems. As mentioned before, much of the work is done in teams, so working well with others is essential.</p><p>Adaptability</p><p>Adaptability is essential in STEM careers because it allows individuals to adjust to new technologies and processes quickly.</p><p>Mathematics</p><p>Mathematics is vital to understanding and analyzing complex data and processes.</p><p>Computer Programming</p><p>Computer programming is important for STEM careers as it allows individuals to create and manipulate software and hardware which are often used in STEM projects.</p><p>Project Management</p><p>STEM projects are often big and undertaken over many weeks, months, or even years. Because of this, it&#39;s important individuals know how to take on complex projects and see them through to the end.</p><p>Technical Writing</p><p>Technical writing is important for STEM careers as it allows individuals to communicate complex technical concepts in a way that is easier for those without as much experience on the topic to understand.</p><p>Because careers in the STEM industry are in such high demand, many schools and organizations are encouraging students to develop these skills and an interest in STEM early.&#160;What this means for you is that there are a variety of opportunities out there for you to take advantage of that will help prepare you for a STEM career.&#160;This includes taking advanced-level math and science classes and participating in STEM-related competitions and activities.&#160;Many schools have a robotics club, for example, which is a great way to gain experience in this field.&#160;As you try new classes and activities, you will better understand if this is the cluster for you and gain important experience along the way.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('3fda3a6341b1f0d6c4237196c9eadbc4','career-exploration-m15-l6-lesson-5','5aa9264075f0af723d8f29be7778be7c','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Education &amp; Training Requirements for STEM</h3><p>Education &amp; Training Requirements for STEM</p><p>Education and Training Requirements for a Career in the STEM Cluster:</p><p>Many STEM jobs require a high level of education and training because they involve complex problem-solving and decision-making.&#160;A career in STEM often involves specialized knowledge in areas such as mathematics, engineering, computer programming, and scientific research.&#160;This type of knowledge and the ability to apply it require a high level of education and training.&#160;Additionally, STEM jobs are often highly technical, which requires a deep understanding of the subject matter and the ability to use advanced tools and systems.</p><p>Let’s look at some of the jobs in this career cluster and the necessary education for each one.&#160;Click through the slideshow to learn more.</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Robotics engineers usually require a minimum of a bachelor&#39;s degree in engineering, although a master&#39;s degree in robotics engineering may be preferred.&#160;They must also possess strong mathematical, analytical, and problem-solving skills.</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;8</p><p>Next</p><p>Astronomers typically need a minimum of a bachelor&#39;s degree in physics, astronomy, or a related field. Some positions may require a master&#39;s or doctoral degree in a related field. Astronomers must also possess strong problem-solving and analytical skills.</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;8</p><p>Next</p><p>Biomedical engineers typically need a minimum of a bachelor&#39;s degree in biomedical engineering or a related field. Some positions may require a master&#39;s or doctoral degree in a related field. Biomedical engineers must also possess strong problem-solving and analytical skills.</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;8</p><p>Next</p><p>Computer scientists typically need a minimum of a bachelor&#39;s degree in computer science or a related field. Some positions may require a master&#39;s degree in a related field. Computer scientists must also possess strong problem-solving and analytical skills.</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;8</p><p>Next</p><p>Geologists typically need a minimum of a bachelor&#39;s degree in geology or a related field. Some positions may require a master&#39;s or doctoral degree in a related field. Geologists must also possess strong problem-solving and analytical skills.</p><p>Previous</p><p>Slide&#160;5&#160;of&#160;8</p><p>Next</p><p>Environmental scientists typically need a minimum of a bachelor&#39;s degree in environmental science or a related field. Some positions may require a master&#39;s or doctoral degree in a related field. Environmental scientists must also possess strong problem-solving and analytical skills.</p><p>Previous</p><p>Slide&#160;6&#160;of&#160;8</p><p>Next</p><p>Geneticists typically need a minimum of a bachelor&#39;s degree in genetics or a related field. Some positions may require a master&#39;s or doctoral degree in a related field. Geneticists must also possess strong problem-solving and analytical skills.</p><p>Previous</p><p>Slide&#160;7&#160;of&#160;8</p><p>Next</p><p>Mechanical engineers typically need a minimum of a bachelor&#39;s degree in mechanical engineering or a related field. Some positions may require a master&#39;s degree in a related field. Mechanical engineers must also possess strong problem-solving and analytical skills.</p><p>Previous</p><p>Slide&#160;8&#160;of&#160;8</p><p>Next</p><p>As you can see, higher education is essential to many careers in this field along with strong problem-solving and analytical.&#160;By developing strong study habits, problem-solving, and analytical skills now, you can set yourself up to receive the education and training necessary to have a successful career in STEM.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('773290dfd7ae8c83522e9cd5a3094071','career-exploration-m15-l7-module-14-summary','5aa9264075f0af723d8f29be7778be7c','Module 14 Summary','text',12,'<h2>Module 14 Summary</h2><section><h3>Module 14 Summary</h3><p>Module 14 Summary</p><p>Great Work!&#160;You have successfully completed this module on the Science, Technology, Engineering &amp; Mathematics Career Cluster.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified the pathways in Science, Technology, Engineering, &amp; Mathematics.</p><p>Described the types of places that employ individuals who have careers in Science, Technology, Engineering, &amp; Mathematics.</p><p>Described the variety of tasks performed by individuals who have careers in Science, Technology, Engineering, &amp; Mathematics.</p><p>Listed the skills, abilities, and talents needed for careers in Science, Technology, Engineering, &amp; Mathematics.</p><p>Identified the level of training and education required for careers in Science, Technology, Engineering, &amp; Mathematics.</p><p>Researched a career in Science, Technology, Engineering, &amp; Mathematics and presented findings to the class.</p><p>Applied math, science, and reading skills in the completion of a project or activity related to Science, Technology, Engineering, &amp; Mathematics.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('0685b56db30476ab7ff074ff0f404d53','career-exploration-m15-l8-module-14-project','5aa9264075f0af723d8f29be7778be7c','Module 14 Project','text',12,'<h2>Module 14 Project</h2><section><h3>Module 14 Project</h3><p>Module 14 Project</p><p>Career Exploration</p><p>Science, Technology, Engineering &amp; Mathematics - Project</p><p>For this project, you will choose from two options.&#160; You only need to complete one of these options.&#160; Please find both options and their rubrics below.</p><p>Option 1</p><p>For this project, you will construct a marble rollercoaster. Follow the steps below to complete the project:</p><p>Step 1: Gather the following materials: 3/4&quot; to 1&quot; foam pipe insulation (available at most home improvement stores), masking tape, a marble, and scissors.</p><p>Step 2: If necessary, cut your foaming into 3-foot pieces.</p><p>Step 3: Carefully cut your foam pieces in half, lengthwise.&#160;(You will need about 4 half-tubes)</p><p>Step 4: Pick a smooth, flat surface for your starting point. Keep in mind that the higher your starting point, the more energy your marble will have as it takes the first drop! Use tape to secure it in place.</p><p>Step 5: Begin constructing your rollercoaster. Use tape to connect pieces. (Hint: The smoother the connections, the better the marble will travel.)</p><p>Step 6: Incorporate twists, turns, and loops as desired. Use tape as needed to secure the rollercoaster in place.</p><p>Step 7: Test your rollercoaster and adjust as needed.</p><p>Step 8: When you are happy with the rollercoaster you have created, take a video of the marble going down your rollercoaster.</p><p>Step 9: Take a picture of the completed rollercoaster as well.</p><p>Your final submission should include a photo of the rollercoaster and a video demonstrating the marble going down it.</p><p>Review the rubric below to see how you will be graded.</p><p>Option 1 Rubric: Science, Technology, Engineer &amp; Mathematics Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Rollercoaster Video</p><p>9-10 points The video showcases the marble successfully navigating the entire constructed rollercoaster.</p><p>7-8 points The video showcases the marble successfully navigating at least one rollercoaster element (i.e. turn, loop, or uphill).</p><p>0-6 points The video does not show the marble well and/or the marble does not successfully navigate at least one rollercoaster element (i.e. turn, loop, or uphill)</p><p>10</p><p>Rollercoaster Image</p><p>9-10 points The constructed rollercoaster is well-designed and incorporates at least two turns, loops, and/or uphills.</p><p>7-8 points The constructed rollercoaster is mostly well-designed and incorporates one turn, loop, or uphill.</p><p>0-6 points The constructed rollercoaster is not well-designed and/or only runs in a straight line.</p><p>10</p><p>Total Points:&#160;20</p><p>Option 2</p><p>For this option, you will research a particular career that interests you in this cluster. Complete the following steps for your project:</p><p>Step 1: Research your chosen career.</p><p>Step 2: List the following</p><p>Average Salary/Salary Range</p><p>Education Requirements</p><p>Certification Requirements (if any)</p><p>Why you chose that career</p><p>Step 3: Prepare a PowerPoint presentation about your chosen career, including the information you gathered in Step 2 as well as your reason for choosing that career.</p><p>Your final submission should be your PowerPoint containing the information in Step 3.</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 2 Rubric: Science, Technology, Engineering &amp; Mathematics Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Research</p><p>12 points The student provided a career field that interested them, the average salary or range, and the education/certifications required for the career.</p><p>11-4 points The student provided two of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>3-0 points The student provided one or none of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>12</p><p>Reason for Choosing the Career Field</p><p>4 points The student thoughtfully provided the reason that they are interested in this career.</p><p>N/A</p><p>0 points The student did not provide the reason that they are interested in this career.</p><p>4</p><p>Formatting</p><p>4 points The student&#39;s presentation includes no spelling or grammatical errors.</p><p>3-1 points The student&#39;s presentation includes minimal spelling or grammatical errors.</p><p>0 points The student&#39;s presentation includes a significant amount of spelling or grammatical errors.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,7,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c665c2cd4208c4ed536b44248b1a757d','career-exploration-m15-l9-module-14-quiz','5aa9264075f0af723d8f29be7778be7c','Module 14 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of STEM. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,8,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('3068603f1f25503bca0c18b57f091b8c','career-exploration-module-16','68d48b60cc4feb626956ed1fd8311e46','Module 16: Transportation & Logistics',16) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('fd3b84a398834e7a26659d9c14f37e1b','career-exploration-m16-l1-introduction-purpose-and-objectives','3068603f1f25503bca0c18b57f091b8c','Introduction, Purpose and Objectives','text',12,'<h2>Introduction, Purpose and Objectives</h2><section><h3>Introduction Description Objectives</h3><p>Introduction</p><p>Hello and welcome to this module on the Transportation and Logistics career cluster.</p><p>Transportation is the lifeblood of our economy. It gets people, goods, and materials from point A to point B. But more than this, the transportation industry provides an array of challenging and rewarding career opportunities. Those interested can look forward to many possibilities: from shipping and receiving to transportation planning and safety.</p><p>And, since the industry is constantly evolving, there’s always something new to learn. Think about the impact that electric vehicles, driverless cars, and drones will have on our world. Technology is transforming the field, making logistics more efficient and creating new opportunities for those who want to stay ahead of the curve. Other examples include automation and robotics, which are being used to track and manage shipments. Artificial intelligence is being used to optimize routes and predict customer demand. The best part is that the skills you learn in this field can be applied to other areas.</p><p>Logistics and transportation knowledge can be used in any number of industries, such as retail, manufacturing, healthcare, and more. At the same time, there are plenty of opportunities to take on more of a leadership role. From managing teams to developing operations strategies to finding innovative ways to increase efficiency, those in the Transportation and Logistics career cluster can make a real difference. Whether you’re looking for a career that’s full of adventure or one that offers stability and growth, the Transportation and Logistics career cluster has something that appeals to a variety of people.</p><p>Because this career cluster encompasses so many diverse jobs, there are many pathways, and in this module, we will discuss all of them. We will also discuss places that hire people in this career cluster, activities performed on the job, the typical skills needed in this career cluster, and the training and education needed. There are several specific types of training that are unique to jobs in this career cluster, so you’ll definitely not want to miss that information!</p><p>It&#39;s all coming up in this module, so let’s get going!</p><p>Module Description</p><p>Creative Commons&#160;is licensed under&#160;CC BY-SA 4.0(opens in a new tab).</p><p>Welcome to this module on the Transportation &amp; Logistics career cluster!&#160;In this module, you will discover the several pathways in this cluster and some of the jobs associated with each pathway.&#160;There are several pathways, each with its own way of contributing to the cluster.&#160;Next, we will discuss the types of places that employ individuals in this field.&#160;The module will explain the different tasks that someone in this career cluster may perform on a regular basis.&#160;You will also learn about the skills, abilities, and talents needed for careers.&#160;We will also discuss the specific training requirements unique to the jobs in this career cluster.</p><p>Objectives</p><p>In this module, students will</p><p>Identify the pathways in the Transportation &amp; Logistics career cluster and the careers in each pathway.</p><p>Describe the types of places that employ individuals who have careers in the Transportation &amp; Logistics career cluster.</p><p>Describe the variety of tasks performed by individuals who have careers in the Transportation &amp; Logistics career cluster.</p><p>List the skills, abilities, and talents needed for careers in the Transportation &amp; Logistics career cluster.</p><p>Identify the level of training and education required for careers in the Transportation &amp; Logistics career cluster.</p><p>Research a career in the Transportation &amp; Logistics career cluster and present findings to the class.</p><p>Apply math, science, and reading skills in the completion of a project or activity related to the Transportation &amp; Logistics career cluster.</p><p>Polling Question</p><p>Which of the following careers in the Transportation &amp; Logistics career cluster sounds most interesting to you?</p><p>Logistics analyst&#160;Pilot&#160;Warehouse manager&#160;Ship mechanic&#160;Other</p><p>Make a selection to see the results so far.</p><p>Vocabulary</p><p>Match&#160;the vocabulary words below with their definition.&#160;This is an ungraded exercise that will help you familiarize with words and concepts we will learn in this module.</p><p>Terms</p><p>Moving people or things from one place to another, usually by car, bus, train, plane, or boat.</p><p>Logistics</p><p>Making sure that people or things get from one place to another in the most efficient and cost-effective way.</p><p>Maritime</p><p>Anything related to the sea, like ships, boats, and ports.</p><p>Warehouse</p><p>Goods or items that are being transported from one place to another.</p><p>Transportation</p><p>A large building used for storing goods and materials.</p><p>Cargo</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Moving people or things from one place to another, usually by car, bus, train, plane, or boat.</p><p>Answers for question: 1</p><p>Transportation</p><p>Logistics</p><p>Warehouse</p><p>Maritime</p><p>Cargo</p><p>2.</p><p>Making sure that people or things get from one place to another in the most efficient and cost-effective way.</p><p>Answers for question: 2</p><p>Maritime</p><p>Transportation</p><p>Warehouse</p><p>Cargo</p><p>Logistics</p><p>3.</p><p>Anything related to the sea, like ships, boats, and ports.</p><p>Answers for question: 3</p><p>Logistics</p><p>Cargo</p><p>Transportation</p><p>Maritime</p><p>Warehouse</p><p>4.</p><p>Goods or items that are being transported from one place to another.</p><p>Answers for question: 4</p><p>Logistics</p><p>Warehouse</p><p>Maritime</p><p>Transportation</p><p>Cargo</p><p>5.</p><p>A large building used for storing goods and materials.</p><p>Answers for question: 5</p><p>Transportation</p><p>Warehouse</p><p>Maritime</p><p>Cargo</p><p>Logistics</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f9a2c54a2f9c90fa39a88f5cfa0eb9fe','career-exploration-m16-l2-lesson-1','3068603f1f25503bca0c18b57f091b8c','Lesson 1','text',12,'<h2>Lesson 1</h2><section><h3>What is Transport &amp; Logistic Career</h3><p>What is Transport &amp; Logistic Careers</p><p>What is the Transportation and Logistics Career Cluster?</p><p>Transportation and logistics is an important career cluster that is responsible for getting goods and services from one place to another.&#160;It involves a lot of planning, organization, and problem-solving.&#160;People who work in this field might work on coordinating the delivery of goods, such as food and other products, from a warehouse to stores or customers.&#160;They might also be responsible for ensuring that the right products arrive on time and in the right condition.&#160;This could involve deciding what type of transportation is most efficient and cost-effective and making sure that all the necessary paperwork is complete.&#160;People in this cluster might also be responsible for keeping track of shipments and deliveries, as well as making sure that safety regulations are followed.&#160;In other words, the Transportation and Logistics career cluster is all about making sure that the right goods get to the right place at the right time.</p><p>There are seven pathways in this career cluster.&#160;Click through the slideshow to learn more about each one:</p><p>In the following slideshow, use your left and right arrow keys to navigate.&#160;Press spacebar to reveal the other side of the card.</p><p>Transportation Operations Pathway:&#160;This pathway is about understanding how to move people and goods safely and efficiently from one place to another.&#160;It involves learning how to operate different types of transportation vehicles and equipment, as well as understanding and following all the laws and regulations related to transportation.&#160;Jobs in this pathway include pilots, bus drivers, and heavy truck and tractor-trailer drivers.</p><p>Previous</p><p>Slide&#160;1&#160;of&#160;7</p><p>Next</p><p>Logistics Planning &amp; Management Services Pathway: This pathway is about understanding how to plan and manage the logistics of moving goods and services from one place to another. It involves learning how to organize and coordinate the different steps involved in shipping and delivery, and how to manage the costs associated with transportation. Job titles in this pathway include logistician, logistics manager, and logistics analyst.</p><p>Previous</p><p>Slide&#160;2&#160;of&#160;7</p><p>Next</p><p>Warehousing &amp; Distribution Center Operations Pathway: This pathway is about understanding how to store and move goods from a warehouse or distribution center. It involves learning how to organize and manage the inventory in a warehouse, as well as how to pick, pack, and ship items to their destination. Careers in this pathway include warehouse managers, car/truck/ship loaders, and traffic/shipping/receiving clerks.</p><p>Previous</p><p>Slide&#160;3&#160;of&#160;7</p><p>Next</p><p>Facility &amp; Mobile Equipment Maintenance Pathway: This pathway is about understanding how to maintain and repair the different types of vehicles and equipment used in transportation and logistics. It involves learning how to troubleshoot and repair equipment, as well as how to inspect and maintain it to ensure that it is in good working condition. Job titles in the pathway include automotive service technician, facility maintenance manager, and aircraft mechanic.</p><p>Previous</p><p>Slide&#160;4&#160;of&#160;7</p><p>Next</p><p>Transportation Systems/Infrastructure Planning, Management &amp; Regulation Pathway: This pathway is about understanding how to plan, manage, and regulate transportation systems and infrastructure. It involves learning how to design, build, and maintain transportation systems, as well as understanding and following all the transportation laws and regulations. Professionals in this pathway include air traffic controllers, Department of Transportation (DOT) Officer, and railroad inspectors.</p><p>Previous</p><p>Slide&#160;5&#160;of&#160;7</p><p>Next</p><p>Health, Safety &amp; Environmental Management Pathway: This pathway is about understanding how to keep people and the environment safe while transporting goods and services. It involves learning how to plan and implement safety protocols, as well as how to manage and monitor environmental risks related to transportation. Jobs in this pathway include DOT inspector, hazardous materials manager, and safety analyst.</p><p>Previous</p><p>Slide&#160;6&#160;of&#160;7</p><p>Next</p><p>Sales &amp; Service Pathway: This pathway is about understanding how to provide customer service and sales support for transportation and logistics. It involves learning how to interact with customers, as well as how to market and promote transportation services. Professional in this pathway include sales managers, sales representatives for transportation/logistics services, and cargo/freight agents.</p><p>Previous</p><p>Slide&#160;7&#160;of&#160;7</p><p>Next</p><p>Now that you understand the different pathways, see if you can match the person to the right pathway:</p><p>Pathway</p><p>Tanner drives a public bus.</p><p>Warehousing &amp; Distribution Center Operations Pathway</p><p>Carrie is in charge of managing and tracking the freight delivered to the warehouse.</p><p>Sales &amp; Service Pathway</p><p>Amanda is responsible for overseeing how shipments will get delivered to their final destinations.</p><p>Logistics Planning &amp; Management Services Pathway</p><p>Julio repairs and maintains airplanes.</p><p>Facility &amp; Mobile Equipment Maintenance Pathway</p><p>Mabelle communicates to pilots when the runway is clear for takeoff.</p><p>Health, Safety &amp; Environmental Management Pathway</p><p>Gabe ensures that hazardous materials are handled safely.</p><p>Transportation Operations Pathway</p><p>Annie networks with businesses that ship freight to tell them about the trucking company she works for.</p><p>Transportation Systems/Infrastructure Planning, Management &amp; Regulation Pathway</p><p>_</p><p>5</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Tanner drives a public bus.</p><p>Answers for question: 1</p><p>Warehousing &amp; Distribution Center Operations Pathway</p><p>Logistics Planning &amp; Management Services Pathway</p><p>Health, Safety &amp; Environmental Management Pathway</p><p>Facility &amp; Mobile Equipment Maintenance Pathway</p><p>Transportation Operations Pathway</p><p>Transportation Systems/Infrastructure Planning, Management <aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,1,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('f4160f7964ca774249933d5ef98e8ee3','career-exploration-m16-l3-lesson-2','3068603f1f25503bca0c18b57f091b8c','Lesson 2','text',12,'<h2>Lesson 2</h2><section><h3>Where Transport &amp; Logistic ppl Work</h3><p>Where Transport &amp; Logistic ppl Work</p><p>Where the People in the Transportation and Logistics Career Cluster Find Employment:</p><p>People in this career cluster find employment in a variety of places.&#160;Click below to learn more about these places of employment:</p><p>0</p><p>5</p><p>Image Hotspots Transcript</p><p>This is an image hotspot interactive. The overall image has been described as:</p><p>Places of employment for the Transportation and Logistics career cluster.</p><p>The hotspot points on the image are as follows:</p><p>Logistics Companies</p><p>Logistics companies employ people to manage the coordination of transportation and logistics services and manage customer service for clients.</p><p>Railroads</p><p>Railroads employ people to operate and maintain trains, manage the logistics of freight transportation, and manage customer service for clients.</p><p>Trucking Companies</p><p>Trucking companies employ people to operate and maintain trucks, manage the logistics of freight transportation, and manage customer service for clients.</p><p>Warehousing Companies</p><p>Warehousing companies employ people to manage the storage and distribution of goods, manage the logistics of freight transportation, and manage customer service for clients.</p><p>Airports</p><p>Airports employ people to manage the operation and maintenance of the airport, coordinate the arrival and departure of airplanes, and manage customer service for passengers.</p><p>Maritime Companies</p><p>Maritime companies employ people to operate and maintain ships, manage the logistics of freight transportation, and manage customer service for clients.</p><p>The place of employment will depend on the specialty of the individual.&#160;For example, those with a background in aviation would likely work at airports for an airline, while those with a commercial trucking license would likely find employment at a trucking company.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,2,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('02bbdee65233752e63bf47dc2a0105bb','career-exploration-m16-l4-lesson-3','3068603f1f25503bca0c18b57f091b8c','Lesson 3','text',12,'<h2>Lesson 3</h2><section><h3>Activities for Transport &amp; Logistic Careers</h3><p>Activities for Transport &amp; Logistic Careers</p><p>Activities in the Transportation &amp; Logistics Career Cluster</p><p>A lot of activities have to happen in order for goods to be moved to their final destination.&#160;It takes several people in the Transportation &amp; Logistics career cluster doing the tasks within their job in order to make that happen.&#160;Here are some of the tasks within this career cluster:</p><p>Fleet and Facility Management</p><p>Keeping track of and managing all the vehicles and buildings owned by a company.</p><p>Logistics Planning</p><p>Planning out how materials and goods will be moved from one place to another while making sure it is done efficiently.</p><p>Logistics and Supply Chain Analysis</p><p>Looking at the data from supply chain and logistics planning to make sure everything is working properly and efficiently.</p><p>Transportation Infrastructure Planning</p><p>Planning out the roads, bridges, and other things that are needed to move people and things around.</p><p>Cargo and Freight Management</p><p>Making sure the goods and products that are being moved around are safe and secure.</p><p>Shipping and Receiving</p><p>Tracking the goods or products that are sent to and received from different places.</p><p>Inventory Management</p><p>Keeping track of all the items a business has and making sure they have enough in stock.</p><p>Transportation Security</p><p>Making sure the things being moved around are secure and safe from harm.</p><p>Packaging and Delivery</p><p>Packing the goods or products so they can be safely delivered to the right place.</p><p>Route Planning and Optimization</p><p>Planning out the best routes for moving people and things around, and making sure the routes are as efficient as possible.</p><p>Emergency Logistics Coordination</p><p>Making sure that in an emergency situation, the right people and supplies get to the right place quickly and safely.</p><p>Risk Management</p><p>Looking at the potential risks that could happen when moving people and things around, and trying to lower the chances of those risks happening.</p><p>Traffic Management</p><p>Managing the flow of traffic on roads and other pathways.</p><p>Fleet Maintenance and Safety</p><p>Ensuring all the vehicles in a company’s fleet are in good condition and are being used safely.</p><p>Warehouse Management</p><p>Managing the space and resources in a warehouse to make sure everything is organized and efficient.</p><p>Asset Management</p><p>Keeping track of and managing the resources a company has.</p><p>Carrier Relationships Management</p><p>Manage the relationships between a company and the people or companies they work with to move people and things around.</p><p>The exact activities performed depend on the individual’s job.&#160;The tasks listed in this lesson are just a few examples of the tasks within this career cluster.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,3,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c9361ccf9c4c203fc8fcfcc9a456399b','career-exploration-m16-l5-lesson-5','3068603f1f25503bca0c18b57f091b8c','Lesson 5','text',12,'<h2>Lesson 5</h2><section><h3>Skills Needed for Transport &amp; Logistics</h3><p>Skills Needed for Transport &amp; Logistic</p><p>Skill, Abilities, and Talents Needed in the Transportation &amp; Logistics Career Cluster</p><p>To have a successful career in the Transportation and Logistics career cluster, there are several skills, abilities, and talents these individuals need.&#160;Click on the tabs to learn more:</p><p>Knowledge of processes and regulations</p><p>This refers to an individual’s understanding of the rules, regulations, and processes that govern the transportation and logistics industry.&#160;This includes knowledge of how to transport goods from one location to another, as well as knowledge of the laws and regulations that govern the industry.</p><p>Multitask &amp; prioritize effectively</p><p>This is an important skill for those who work in transportation and logistics, as they are often required to manage multiple tasks and deadlines in a short amount of time.</p><p>Good communication</p><p>Professionals in this career cluster need the ability to effectively communicate and interact with people in a professional manner. They also need to coordinate with many people in order to transport goods.</p><p>Ability to work under pressure</p><p>Those in the transportation and logistics industry often have to work under tight deadlines, and the ability to work under pressure is essential to success.</p><p>Problem-solving skills</p><p>People in this career cluster often have to deal with unexpected problems that require quick thinking and problem-solving.</p><p>Analytical and numerical skills</p><p>This refers to an individual’s ability to analyze data and use numerical information to make decisions. This is an important skill for those in the transportation and logistics industry, as they often have to analyze data and use numerical information to plan routes and transport goods efficiently.</p><p>Good organization &amp; time-management</p><p>Those who work in the field must be able to manage their time and organize tasks in order to meet deadlines. They need to know how to get things to the right place as efficiently as possible.</p><p>Knowledge of computer apps and software</p><p>There are several computer applications and software systems that are used in the transportation and logistics industry, and individuals in the career cluster need to be able to understand and operate them. This includes knowledge of tracking software, routing software, and other applications that are used to manage the transportation and logistics process.</p><p>Customer service</p><p>Individuals in this profession need to provide excellent customer service to those who use transportation and logistics services. This includes the ability to answer customer queries, provide advice and assistance, and ensure that customers are satisfied with the services provided.</p><p>Next Tab</p><p>Match the situation to the correct skill:</p><p>Skill</p><p>Ronaldo needs to follow the correct procedures when driving his 18-wheeler.</p><p>Good communication and interpersonal skills</p><p>Dhalia needs to manage a shipment that just arrived at the warehouse while also ensuring the correct inventory is exported.</p><p>Ability to work under pressure</p><p>Blake needs to deliver a sales presentation that effectively explains why his company would benefit the potential client.</p><p>Knowledge of processes and regulations</p><p>Gloria needs to make sure the shipment is delivered within 24 hours.</p><p>Organizational and time-management skills</p><p>Lori must research all possible routes and determine the best route based on mileage, estimated time of delivery, and efficiency.</p><p>Analytical and numerical skills</p><p>Cole just received word that a shipment to the warehouse will be delayed, and now he must figure out how to adapt to the unexpected situation.</p><p>Customer service</p><p>Connie needs to setup the warehouse so that those delivering goods can make the delivery as efficiently as possible.</p><p>Problem-solving</p><p>Hunter uses a tracking and scheduling application to coordinate with drivers who are making deliveries.</p><p>Ability to multitask and prioritize effectively</p><p>Fiona always makes sure to personally reach out to her clients after their delivery arrives to make sure everything is in order.</p><p>Knowledge of computer applications and software systems</p><p>Alternative Activity</p><p>Match description with a choice.</p><p>1.</p><p>Ronaldo needs to follow the correct procedures when driving his 18-wheeler.</p><p>Answers for question: 1</p><p>Knowledge of processes and regulations</p><p>Problem-solving</p><p>Customer service</p><p>Ability to work under pressure</p><p>Good communication and interpersonal skills</p><p>Organizational and time-management skills</p><p>Analytical and numerical skills</p><p>Ability to multitask and prioritize effectively</p><p>Knowledge of computer applications and software systems</p><p>2.</p><p>Dhalia needs to manage a shipment that just arrived at the warehouse while also ensuring the correct inventory is exported.</p><p>Answers for question: 2</p><p>Good communication and interpersonal skills</p><p>Ability to multitask and prioritize effectively</p><p>Knowledge of processes and regulations</p><p>Problem-solving</p><p>Knowledge of computer applications and software systems</p><p>Organizational and time-management skills</p><p>Analytical and numerical skills</p><p>Customer service</p><p>Ability to work under pressure</p><p>3.</p><p>Blake needs to deliver a sales presentation that effectively explains why his company would benefit the potential client.</p><p>Answers for question: 3</p><p>Good communication and interpersonal skills</p><p>Knowledge of computer applications and software systems</p><p>Organizational and time-management skills</p><p>Knowledge of processes and regulations</p><p>Ability to work under pressure</p><p>Ability to multitask and prioritize effectively</p><p>Problem-solving</p><p>Customer service</p><p>Analytical and numerical skills</p><p>4.</p><p>Gloria needs to make sure the shipment is delivered within 24 hours.</p><p>Answers for question: 4</p><p>Knowledge of processes and regulations</p><p>Analytical and numerical skills</p><p>Ability to work under pressure</p><p>Problem-solving</p><p>Knowledge of computer applications and software systems</p><p>Ability to multitask and prioritize effectively</p><p>Good communication and interpersonal skills</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('c9ed3ceb9ef7ad7df03ca91a9f715754','career-exploration-m16-l6-module-16-summary','3068603f1f25503bca0c18b57f091b8c','Module 16 Summary','text',12,'<h2>Module 16 Summary</h2><section><h3>Module 16 Summary</h3><p>Module 16 Summary</p><p>Great Work!&#160;You have successfully completed this module on the Transportation &amp; Logistics career cluster.</p><p>Don&#39;t forget to participate in the module discussions by posting at least one initial post and two replies.&#160;Also, make sure to complete the module assignment and quiz!</p><p>In this module, you:</p><p>Identified the pathways in the Transportation &amp; Logistics career cluster and the careers in each pathway.</p><p>Described the types of places that employ individuals who have careers in the Transportation &amp; Logistics career cluster.</p><p>Described the variety of tasks performeded by individuals who have careers in the Transportation &amp; Logistics career cluster.</p><p>Listed the skills, abilities, and talents needed for careers in the Transportation &amp; Logistics career cluster.</p><p>Identified the level of training and education required for careers in the Transportation &amp; Logistics career cluster.</p><p>Researched a career in the Transportation &amp; Logistics career cluster and present findings to the class.</p><p>Applied math, science, and reading skills in the completion of a project or activity related to the Transportation &amp; Logistics career cluster.</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,5,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('dbfa10c56a1fb8dd15dbcbc4dbbf487a','career-exploration-m16-l7-module-16-project','3068603f1f25503bca0c18b57f091b8c','Module 16 Project','text',12,'<h2>Module 16 Project</h2><section><h3>Module 16 Project</h3><p>Module 16 Project</p><p>Career Exploration</p><p>Transportation &amp; Logistics - Project</p><p>For this project, you will choose from two options.&#160; You only need to complete one of these options.&#160; Please find both options and their rubrics below.</p><p>Option 1</p><p>Imagine you are responsible for getting a car from your city to Paris, France. Do some research and write a report addressing the following points:</p><p>What type of vehicle(s) would you use?</p><p>What are the pros and cons of using that/those vehicle(s)?</p><p>What are the legal training/requirements required for those driving the vehicles?</p><p>Approximately how long would it take?</p><p>Describe how you would ensure the successful delivery of the car.</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 1 Rubric: Transportation &amp; Logistics Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Vehicle(s)</p><p>4 points The report identifies a specific type of vehicle /vehicles that could transport a car to the final destination.</p><p>N/A</p><p>0 points The report does not identify a specific type of vehicle that could transport a car to the final destination.</p><p>4</p><p>Pros and cons</p><p>4 points The pros and cons of the vehicle(s) chosen are well explained.</p><p>3 points The pros and cons of the vehicle(s) chosen are mostly well explained.</p><p>0-2 points The pros and cons of the vehicle(s) chosen are not well explained.</p><p>4</p><p>Legal requirements</p><p>4 points The licenses and other requirements for those operating the vehicle(s) are well explained.</p><p>3 points The licenses and other requirements for those operating the vehicle(s) are mostly well explained.</p><p>0-2 points The licenses and other requirements for those operating the vehicle(s) are not well explained.</p><p>4</p><p>Time</p><p>4 points The report gives a reasonable time estimate.</p><p>N/A</p><p>0 points The report does not give a reasonable time estimate.</p><p>4</p><p>Delivery plan</p><p>4 points The report outlines a thorough plan for communication to ensure successful delivery.</p><p>3 points The report outlines a satisfactory plan for communication to ensure successful delivery.</p><p>0-2 points The report does not outline a plan for communication to ensure successful delivery.</p><p>4</p><p>Total Points:&#160;20</p><p>Option 2</p><p>For this option, you will research a particular career that interests you in this cluster. Complete the following steps for your project:</p><p>Step 1: Research your chosen career.</p><p>Step 2: List the following</p><p>Average Salary/Salary Range</p><p>Education Requirements</p><p>Certification Requirements (if any)</p><p>Why you chose that career</p><p>Step 3: Prepare a PowerPoint presentation about your chosen career, including the information you gathered in Step 2 as well as your reason for choosing that career.</p><p>Your final submission should be your PowerPoint containing the information in Step 3.</p><p>Review the rubric below to determine how you will be graded.</p><p>Option 2 Rubric: Transportation &amp; Logistics Project</p><p>Category</p><p>Excellent</p><p>Good</p><p>Needs Improvement</p><p>Points Possible</p><p>Research</p><p>12 points The student provided a career field that interested them, the average salary or range, and the education/certifications required for the career.</p><p>11-4 points The student provided two of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>3-0 points The student provided one or none of the following: a career field that interested them the average salary or range, the education/certifications required for the career</p><p>12</p><p>Reason for Choosing the Career Field</p><p>4 points The student thoughtfully provided the reason that they are interested in this career.</p><p>N/A</p><p>0 points The student did not provide the reason that they are interested in this career.</p><p>4</p><p>Formatting</p><p>4 points The student&#39;s presentation includes no spelling or grammatical errors.</p><p>3-1 points The student&#39;s presentation includes minimal spelling or grammatical errors.</p><p>0 points The student&#39;s presentation includes a significant amount of spelling or grammatical errors.</p><p>4</p><p>Total Points:&#160;20</p></section><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,6,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('d40b7567a24cb916f54904d3040cfe88','career-exploration-m16-l8-module-16-quiz','3068603f1f25503bca0c18b57f091b8c','Module 16 Quiz','assessment',20,'<h2>Knowledge check</h2><p>Demonstrate your understanding of Transportation & Logistics. A score of 80% is required; review the lesson content and try again when needed.</p>',NULL,7,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO modules (id,slug,course_id,title,position) VALUES ('5c8b71bb76ff236908e1ae921e0f278b','career-exploration-module-17','68d48b60cc4feb626956ed1fd8311e46','Module 17: Course Wrap Up & Final Exam',17) ON DUPLICATE KEY UPDATE title=VALUES(title),position=VALUES(position);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('87373692a0a29e6f414cb97fea4962a1','career-exploration-m17-l1-course-wrap-up-and-final-exam','5c8b71bb76ff236908e1ae921e0f278b','Course Wrap Up & Final Exam','text',12,'<h2>Course Wrap Up &amp; Final Exam</h2><section><h3>Course Wrap Up</h3><p>Course Wrap Up</p><p>We&#39;re at the last leg of our exciting journey!</p><p>We hope this course has equipped you with the knowledge needed for you to master the learning objectives of this course.&#160;You should now be ready for the final exam!</p><p>This final exam has two parts.&#160; Be sure to complete and submit both parts on the next two pages to finish this activity.</p></section><section><h3>Final Exam - Part 1</h3><p>Final Exam - Part 1</p><p>Analytics:Off</p><p>Answer Key:Off</p><p>ABCABC</p><p>Directions:&#160;Read each question carefully and then choose the correct answer.</p><p>You have already taken this quiz and will not be able to retake it.</p><p>The ability to collect, gather, visualize, and analyze information to understand complex concepts and problems is called what?</p><p>Analytical skills</p><p>Deduction skills</p><p>Communication skills</p><p>Data entry skills</p><p>The agriculture, food, and natural resources career cluster only includes jobs and related to conservation.</p><p>True</p><p>False</p><p>A food safety inspector belongs to which pathway?</p><p>Agribusiness Systems</p><p>Environmental Services Systems</p><p>Food Products &amp; Processing Systems</p><p>Plant Systems</p><p>Using technology like phones or the internet to send messages or talk to someone from a distance is called what?</p><p>Digital communications</p><p>Broadcasting</p><p>High-speed processing</p><p>Telecommunications</p><p>Which pathway focuses on buying or selling investments like stocks and bonds?</p><p>Insurance pathway</p><p>Accounting pathway</p><p>Business finance pathway</p><p>Securities &amp; investments pathway</p><p>Places where people and businesses can find help with taxes, payroll, and other financial management services are called what?</p><p>Banks</p><p>Accounting firms</p><p>Corporations</p><p>Financial institutions</p><p>This pathway involves managing government programs and services, as well as overseeing the operations of government organizations.</p><p>Public Management &amp; Administration Pathway</p><p>Revenue &amp; Taxation Pathway</p><p>Foreign Service Pathway</p><p>Governance Pathway</p><p>Which of the following activities is LEAST likely to prepare you for a career in Education &amp; Training?</p><p>Volunteering</p><p>Playing video games</p><p>Joining youth organizations</p><p>Tutoring</p><p>People in the Education &amp; Training career cluster can only find jobs at schools and other institutions of learning.</p><p>True</p><p>False</p><p>Which career does NOT typically require a four-year degree?</p><p>Architect</p><p>Electrician</p><p>Engineer</p><p>Construction manager</p><p>Taking care of natural resources and the environment, like using resources wisely and not wasting them is called what?</p><p>Natural selection</p><p>Conservation</p><p>Resource awareness</p><p>Environmental science</p><p>Annie has been assigned the responsibility of overseeing the construction of a new town hall including planning, budgeting, and building.&#160;Which skill will Annie need the MOST to fulfill this responsibility?</p><p>Modeling</p><p>Drafting</p><p>Project Management</p><p>Engineering</p><p>If you wanted to be a conservationist, which pathway would you most likely take?</p><p>Natural Resources Systems</p><p>Animal Systems</p><p>Plant Systems</p><p>Power, Structural &amp; Technical Systems</p><p>Which job would benefit the most from training in Adobe Premiere Pro, Final Cut Pro, and After Effects?</p><p>Broadcast technician</p><p>Music Producer</p><p>Graphic Designer</p><p>Videographer</p><p>Someone with skills in the Business, Management &amp; Administration career cluster would not likely be hired by a healthcare organization.</p><p>True</p><p>False</p><p>Which of the following is NOT likely to be a place where someone in the Agriculture, Food &amp; Natural Resources Career Cluster would work?</p><p>Doctor&#39;s Office</p><p>National Park</p><p>Plant Nursery</p><p>Grocery Store</p><p>Which career would most likely require the ability to communicate in a foreign language?</p><p>Senator</p><p>Immigration Officer</p><p>Tax Attourney</p><p>Ambassador</p></section><section><h3>Final Exam - Part 2</h3><p>Final Exam - Part 2</p><p>Answer Key:Off</p><p>ABCABC</p><p>Directions:&#160;Read each question carefully and then choose the correct answer.</p><p>Some people in the Human Services pathway may work in a hospital setting.</p><p>True</p><p>False</p><p>Which pathway includes housekeepers, lodging managers, concierges, and hotel owners?</p><p>Restaurants &amp; Food/Beverage Services Pathway</p><p>Travel &amp; Tourism Pathway</p><p>Lodging Pathway</p><p>Recreation, Amusements, &amp; Attractions Pathway</p><p>Which of the following is NOT a likely place of employment for someone in the Hospitality &amp; Tourism career cluster?</p><p>Hotels</p><p>Cruise ship</p><p>Restaurant</p><p>University</p><p>What task is NOT likely something someone in the Marketing career cluster would perform?</p><p>Analyzing customer data</p><p>Adjusting payroll</p><p>Creating marketing materials</p><p>Visual merchandizing</p><p>Using science and math to solve problems in the world and build things is called what?</p><p>Architecture</p><p>Technology</p><p>Engineering</p><p>Robotics</p><p>Understanding how to use social media platforms is a key skill in today’s marketing world.</p><p>True</p><p>False</p><p>The most common place of employment for STEM professionals is colleges/ universities.</p><p>True</p><p>False</p><p>The process of creating something like a car is called what?</p><p>Development</p><p>Design</p><p>Production</p><p>Inspection</p><p>Which of the following is LEAST likely to be a task someone in the Hospitality &amp; Tourism career cluster may perform?</p><p>Customer service</p><p>Language lessons</p><p>Event planning</p><p>Transportation coordination</p><p>Omar needs to use a computer in the process of product design.&#160;Which skill is most important in this situation?</p><p>Organization skills</p><p>Problem-solving skills</p><p>Technical skills</p><p>Attention to details</p><p>Coding and troubleshooting are activities that are found within the STEM career cluster.</p><p>True</p><p>False</p><p>Abigail is a game developer.&#160;Which pathway best fits her job?</p><p>Network Systems Pathway</p><p>Information Support &amp; Services Pathway</p><p>Programming and Software Development Pathway</p><p>Web and Digital Communications Pathway</p><p>Which of t<aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; at any point. Thandi will pause, answer from the approved lesson material, provide an example when requested, and then continue from the last completed concept.</aside>',NULL,0,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Career Exploration lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Career Exploration interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b3e5fbb618f449aef77ac50af25c309d','career-exploration-course-mastery-assessment','5c8b71bb76ff236908e1ae921e0f278b','Course Mastery Assessment','assessment',30,'<h2>Course mastery assessment</h2><p>Bring together knowledge and application from the complete course. Achieve at least 80% to satisfy the assessment requirement for certification.</p>',NULL,1,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO assessments (id,slug,course_id,title,pass_mark,questions) VALUES ('09f7529f5324f1532ef4b8be5e8c1439','career-exploration-course-mastery-assessment','68d48b60cc4feb626956ed1fd8311e46','Career Exploration Course Mastery Assessment',80,CAST('[{"id":"career-exploration-course-mastery-assessment-q1","type":"multiple-choice","prompt":"Before starting a practical task in Agri Food NR, which action best demonstrates professional judgement?","options":["Clarify the intended outcome, constraints, and success criteria before choosing tools.","Choose the fastest tool and define the goal afterward.","Copy the first available example without checking its fit.","Begin production immediately and leave requirements for final review."],"answer":"Clarify the intended outcome, constraints, and success criteria before choosing tools.","explanation":"Strong practice begins with a clear outcome, constraints, and measurable success criteria.","clue":"Think about what must be understood before execution begins."},{"id":"career-exploration-course-mastery-assessment-q2","type":"multiple-choice","prompt":"A first attempt in Archit & Construct does not meet the requirement. What is the strongest next step?","options":["Compare the result with the criteria, identify the cause, revise, and test again.","Submit the attempt unchanged because the task is complete.","Replace the criteria with measures the attempt already meets.","Discard all evidence and restart without diagnosing the issue."],"answer":"Compare the result with the criteria, identify the cause, revise, and test again.","explanation":"An evidence-led improvement cycle diagnoses the gap before a focused revision and retest.","clue":"Use feedback and evidence to improve the next attempt."},{"id":"career-exploration-course-mastery-assessment-q3","type":"multiple-choice","prompt":"Which evidence most credibly demonstrates applied competence in Arts, Tech, Comms?","options":["A completed work sample with decisions, checks, feedback, and reflection documented.","A claim that the topic was understood without a work sample.","A list of tools with no explanation of how they were used.","An unfinished draft that has not been checked against requirements."],"answer":"A completed work sample with decisions, checks, feedback, and reflection documented.","explanation":"Competence is best demonstrated through completed, reviewed evidence and reflective reasoning.","clue":"Choose evidence that shows both the result and how quality was established."},{"id":"career-exploration-course-mastery-assessment-q4","type":"multiple-choice","prompt":"When work in Business, Managem, Admin could affect people, data, safety, or the environment, what should the learner do?","options":["Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","Proceed without checks when the intended outcome is positive.","Treat ethical and safety considerations as optional after delivery.","Hide known limitations so stakeholders remain confident."],"answer":"Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","explanation":"Responsible practice makes risk, consent, standards, and safeguards part of the work itself.","clue":"Professional quality includes the impact of the work, not only the output."},{"id":"career-exploration-course-mastery-assessment-q5","type":"multiple-choice","prompt":"How should a learner transfer skills from Education & Training to a new workplace or project context?","options":["Analyse the new context, adapt the method, test assumptions, and evaluate the result.","Repeat the original steps unchanged regardless of context.","Use only familiar methods and ignore new constraints.","Wait for a complete example to copy before making any decision."],"answer":"Analyse the new context, adapt the method, test assumptions, and evaluate the result.","explanation":"Transfer requires adapting core principles to new constraints and validating the result.","clue":"Core principles remain useful, but their application must fit the new context."}]' AS JSON)) ON DUPLICATE KEY UPDATE title=VALUES(title),pass_mark=VALUES(pass_mark),questions=VALUES(questions);
