INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('8f1a4ac8491c7a2fc7096d5d678368a6','digital-information-technology-course-mastery-assessment','3aeeccdd8d76bce783412945b196fd3f','Course Mastery Assessment','assessment',30,'<h2>Course mastery assessment</h2><p>Bring together knowledge and application from the complete course. Achieve at least 80% to satisfy the assessment requirement for certification.</p>',NULL,5,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO assessments (id,slug,course_id,title,pass_mark,questions) VALUES ('fd9e40dd3ed7c776adc942eaad76a840','digital-information-technology-course-mastery-assessment','2f765bdac8ff1224dc15ad6cef5b64ca','Digital Information Technology Course Mastery Assessment',80,CAST('[{"id":"digital-information-technology-course-mastery-assessment-q1","type":"multiple-choice","prompt":"Before starting a practical task in Digital Foundations, which action best demonstrates professional judgement?","options":["Clarify the intended outcome, constraints, and success criteria before choosing tools.","Choose the fastest tool and define the goal afterward.","Copy the first available example without checking its fit.","Begin production immediately and leave requirements for final review."],"answer":"Clarify the intended outcome, constraints, and success criteria before choosing tools.","explanation":"Strong practice begins with a clear outcome, constraints, and measurable success criteria.","clue":"Think about what must be understood before execution begins."},{"id":"digital-information-technology-course-mastery-assessment-q2","type":"multiple-choice","prompt":"A first attempt in Information and Media Literacy does not meet the requirement. What is the strongest next step?","options":["Compare the result with the criteria, identify the cause, revise, and test again.","Submit the attempt unchanged because the task is complete.","Replace the criteria with measures the attempt already meets.","Discard all evidence and restart without diagnosing the issue."],"answer":"Compare the result with the criteria, identify the cause, revise, and test again.","explanation":"An evidence-led improvement cycle diagnoses the gap before a focused revision and retest.","clue":"Use feedback and evidence to improve the next attempt."},{"id":"digital-information-technology-course-mastery-assessment-q3","type":"multiple-choice","prompt":"Which evidence most credibly demonstrates applied competence in Productivity and File Management?","options":["A completed work sample with decisions, checks, feedback, and reflection documented.","A claim that the topic was understood without a work sample.","A list of tools with no explanation of how they were used.","An unfinished draft that has not been checked against requirements."],"answer":"A completed work sample with decisions, checks, feedback, and reflection documented.","explanation":"Competence is best demonstrated through completed, reviewed evidence and reflective reasoning.","clue":"Choose evidence that shows both the result and how quality was established."},{"id":"digital-information-technology-course-mastery-assessment-q4","type":"multiple-choice","prompt":"When work in Digital Collaboration could affect people, data, safety, or the environment, what should the learner do?","options":["Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","Proceed without checks when the intended outcome is positive.","Treat ethical and safety considerations as optional after delivery.","Hide known limitations so stakeholders remain confident."],"answer":"Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","explanation":"Responsible practice makes risk, consent, standards, and safeguards part of the work itself.","clue":"Professional quality includes the impact of the work, not only the output."},{"id":"digital-information-technology-course-mastery-assessment-q5","type":"multiple-choice","prompt":"How should a learner transfer skills from Data Fundamentals to a new workplace or project context?","options":["Analyse the new context, adapt the method, test assumptions, and evaluate the result.","Repeat the original steps unchanged regardless of context.","Use only familiar methods and ignore new constraints.","Wait for a complete example to copy before making any decision."],"answer":"Analyse the new context, adapt the method, test assumptions, and evaluate the result.","explanation":"Transfer requires adapting core principles to new constraints and validating the result.","clue":"Core principles remain useful, but their application must fit the new context."}]' AS JSON)) ON DUPLICATE KEY UPDATE title=VALUES(title),pass_mark=VALUES(pass_mark),questions=VALUES(questions);
