INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('b380e6ef7b07f22eaf50eed03e1d3f4d','meta-social-media-marketing-m6-module-summary','19465ab5edec3f06401f1b2fee614be1','Module Summary','text',12,'<h2>Module Summary</h2><p>This professionally authored lesson develops practical capability in module summary within Meta Social Media Marketing. Work through Thandi''s guided explanation, test the concept in the scenario, and capture evidence of your application.</p><h3>Learning sequence</h3><ol><li>Connect the concept to a real context.</li><li>Study the core principle and worked example.</li><li>Apply the principle in a decision or practical task.</li><li>Reflect, improve, and record evidence.</li></ol><aside><strong>Interactive lecture:</strong> Say &quot;Thandi, I have a question&quot; to pause the lecture. Thandi will answer, offer an example when requested, and resume from the last completed concept.</aside>',NULL,4,1,'https://vowhumans.com/embed/c81cca0d-866f-466c-a60d-c343dcdab9c4/goalvow-academies','Thandi','Thandi presents this Meta Social Media Marketing lesson as an interactive lecture and can pause for learner questions.','before-content','presenter','Meta Social Media Marketing interactive learning guide',0,1) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO lessons (id,slug,module_id,title,type,duration_minutes,content,video_url,position,vowhuman_enabled,vowhuman_embed_url,vowhuman_presenter_name,vowhuman_intro,vowhuman_placement,vowhuman_role,vowhuman_expertise,vowhuman_camera_enabled,vowhuman_microphone_enabled) VALUES ('acc0d794108a5860fddcbf4409905718','meta-social-media-marketing-course-mastery-assessment','19465ab5edec3f06401f1b2fee614be1','Course Mastery Assessment','assessment',30,'<h2>Course mastery assessment</h2><p>Bring together knowledge and application from the complete course. Achieve at least 80% to satisfy the assessment requirement for certification.</p>',NULL,5,0,NULL,NULL,NULL,'before-content','presenter',NULL,0,0) ON DUPLICATE KEY UPDATE title=VALUES(title),type=VALUES(type),duration_minutes=VALUES(duration_minutes),content=VALUES(content),position=VALUES(position),vowhuman_enabled=VALUES(vowhuman_enabled),vowhuman_embed_url=VALUES(vowhuman_embed_url),vowhuman_presenter_name=VALUES(vowhuman_presenter_name),vowhuman_intro=VALUES(vowhuman_intro),vowhuman_placement=VALUES(vowhuman_placement),vowhuman_role=VALUES(vowhuman_role),vowhuman_expertise=VALUES(vowhuman_expertise),vowhuman_camera_enabled=VALUES(vowhuman_camera_enabled),vowhuman_microphone_enabled=VALUES(vowhuman_microphone_enabled);
INSERT INTO assessments (id,slug,course_id,title,pass_mark,questions) VALUES ('cb344727807630bd351e5607b84123b2','meta-social-media-marketing-course-mastery-assessment','623c28837060b5af982b454b1222915c','Meta Social Media Marketing Course Mastery Assessment',80,CAST('[{"id":"meta-social-media-marketing-course-mastery-assessment-q1","type":"multiple-choice","prompt":"Before starting a practical task in Meta Platform Foundations, which action best demonstrates professional judgement?","options":["Clarify the intended outcome, constraints, and success criteria before choosing tools.","Choose the fastest tool and define the goal afterward.","Copy the first available example without checking its fit.","Begin production immediately and leave requirements for final review."],"answer":"Clarify the intended outcome, constraints, and success criteria before choosing tools.","explanation":"Strong practice begins with a clear outcome, constraints, and measurable success criteria.","clue":"Think about what must be understood before execution begins."},{"id":"meta-social-media-marketing-course-mastery-assessment-q2","type":"multiple-choice","prompt":"A first attempt in Audience and Customer Insight does not meet the requirement. What is the strongest next step?","options":["Compare the result with the criteria, identify the cause, revise, and test again.","Submit the attempt unchanged because the task is complete.","Replace the criteria with measures the attempt already meets.","Discard all evidence and restart without diagnosing the issue."],"answer":"Compare the result with the criteria, identify the cause, revise, and test again.","explanation":"An evidence-led improvement cycle diagnoses the gap before a focused revision and retest.","clue":"Use feedback and evidence to improve the next attempt."},{"id":"meta-social-media-marketing-course-mastery-assessment-q3","type":"multiple-choice","prompt":"Which evidence most credibly demonstrates applied competence in Content Strategy and Creative?","options":["A completed work sample with decisions, checks, feedback, and reflection documented.","A claim that the topic was understood without a work sample.","A list of tools with no explanation of how they were used.","An unfinished draft that has not been checked against requirements."],"answer":"A completed work sample with decisions, checks, feedback, and reflection documented.","explanation":"Competence is best demonstrated through completed, reviewed evidence and reflective reasoning.","clue":"Choose evidence that shows both the result and how quality was established."},{"id":"meta-social-media-marketing-course-mastery-assessment-q4","type":"multiple-choice","prompt":"When work in Campaign Planning in Meta Ads could affect people, data, safety, or the environment, what should the learner do?","options":["Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","Proceed without checks when the intended outcome is positive.","Treat ethical and safety considerations as optional after delivery.","Hide known limitations so stakeholders remain confident."],"answer":"Identify the risks, follow relevant standards, obtain required consent, and document safeguards.","explanation":"Responsible practice makes risk, consent, standards, and safeguards part of the work itself.","clue":"Professional quality includes the impact of the work, not only the output."},{"id":"meta-social-media-marketing-course-mastery-assessment-q5","type":"multiple-choice","prompt":"How should a learner transfer skills from Community and Conversation to a new workplace or project context?","options":["Analyse the new context, adapt the method, test assumptions, and evaluate the result.","Repeat the original steps unchanged regardless of context.","Use only familiar methods and ignore new constraints.","Wait for a complete example to copy before making any decision."],"answer":"Analyse the new context, adapt the method, test assumptions, and evaluate the result.","explanation":"Transfer requires adapting core principles to new constraints and validating the result.","clue":"Core principles remain useful, but their application must fit the new context."}]' AS JSON)) ON DUPLICATE KEY UPDATE title=VALUES(title),pass_mark=VALUES(pass_mark),questions=VALUES(questions);
